INSERT INTO characters (char, data) VALUES ('砝', '{"9000": "5001.0", "Chữ Trung Quốc": "砝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 10 | nét | 石 | thạch | biểu nghĩa | đá, đồ vật cứng | 法 | pháp | biểu âm | pháp luật, phương pháp (phonetic) | 砝 là chữ hình thanh: 石 (Thạch, biểu nghĩa: đá, vật cứng nặng) + 法 (Pháp, biểu âm, rút gọn). Chỉ quả cân chuẩn dùng trong cân đo. Âm fǎ mượn từ 法.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phạ\": 石 (đá nặng) + 法 (pháp — chuẩn mực) — quả đá theo chuẩn ''pháp'' để cân đong đo lường; 砝 = quả cân chuẩn. | Gương Hán-Việt | phạ — 砝码 (phạ mã): quả cân chuẩn trong thí nghiệm | Mở khoá kiến thức | Biết 砝 giúp đọc văn bản khoa học, phòng thí nghiệm: 砝码 (quả cân), dùng trong vật lý, hóa học.", "Tự nguyên_Xie": "砝 (fǎ) chỉ quả cân chuẩn (砝码) dùng trên cân để đo trọng lượng. Wiktionary: 石 (đá, biểu nghĩa) + 法 (biểu âm, rút gọn). Chữ hình thanh tạo muộn để chỉ dụng cụ đo lường. Từ quan trọng: 砝码 (fǎmǎ) = quả cân tiêu chuẩn trong phòng thí nghiệm. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rắn, cứng", "Hạng Tần Suất (Jun Da)": "5001.0", "Tần Suất % (Jun Da)": "99.9222455422", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 去", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石去", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "去", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砝", "Unihan_Traditional (Chữ Phồn thể)": "砝", "Pinyin_Xie": "fá", "Âm Hán Việt_Xie": "kiếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ khi kết hợp thành từ ghép chỉ quả cân dùng trong đo lường. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颞', '{"9000": "5002.0", "Chữ Trung Quốc": "颞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 16 | nét | 聶 | nhiếp | biểu âm | nhiếp (phonetic, rút gọn thành 聂) | 頁 | hiệt | biểu nghĩa | đầu (bộ 页/頁 = trang, đầu người) | 颞 là chữ hình thanh: 頁 (Hiệt, biểu nghĩa: đầu, vùng đầu — bộ dùng trong các từ giải phẫu đầu) + 聶/聂 (Nhiếp, biểu âm). Chữ chỉ vùng thái dương trên đầu người. Cấu trúc hình thanh điển hình cho các chữ giải phẫu học.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"niếp\": 頁 (đầu người) + 聂 (âm niếp) — vùng ''niếp'' (thái dương) bên đầu, nơi mạch máu đập thấy rõ. | Gương Hán-Việt | niếp — 颞叶 (niếp diệp): thùy thái dương não; 颞骨 (niếp cốt): xương thái dương; 颞颥 (niếp nhũ): thái dương | Mở khoá kiến thức | Biết 颞 giúp đọc văn bản y học thần kinh: 颞叶 (thùy thái dương) liên quan trí nhớ, ngôn ngữ; 颞叶癫痫 (động kinh thùy thái dương).", "Tự nguyên_Xie": "颞 (niè) là từ giải phẫu học chỉ vùng thái dương (temporal region). Wiktionary: 聶 (biểu âm) + 頁 (đầu, biểu nghĩa). Chữ chỉ dùng trong 颞颥 (niè rú) — xương thái dương. Đây là chữ tạo muộn cho thuật ngữ y học. Từ khóa: 颞叶 (niè yè) = thùy thái dương não; 颞骨 = xương thái dương. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: nhiếp nhu 顳顬)", "Hạng Tần Suất (Jun Da)": "5002.0", "Tần Suất % (Jun Da)": "99.9223370132", "GavinGrover_Once (Chiết tự trực tiếp)": "聂 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰聂页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "聂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "颞", "Unihan_Traditional (Chữ Phồn thể)": "顳", "Pinyin_Xie": "niè", "Âm Hán Việt_Xie": "nhiếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận thái dương ở hai bên đầu của con người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('忤', '{"9000": "5003.0", "Chữ Trung Quốc": "忤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 7 | nét | 心 | tâm | biểu nghĩa | tâm, lòng | 午 | ngọ | biểu âm | giờ Ngọ (phonetic) | 忤 là chữ hình thanh: 心 (Tâm, biểu nghĩa: tâm hồn, nội tâm) + 午 (Ngọ, biểu âm). Chỉ hành động vi phạm, trái ý, không thuận. Viết với bộ 忄 (tim viết đứng). Âm wǔ mượn từ 午.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngỗ\": bộ 忄 (tim) + 午 (ngọ, âm ngỗ/wǔ) — đứa con ''ngỗ nghịch'' không nghe lời, trái tim đi ngược chiều. | Gương Hán-Việt | ngỗ — 忤逆 (ngỗ nghịch): bất hiếu, không vâng lời cha mẹ; 忤意 (ngỗ ý): trái ý | Mở khoá kiến thức | Biết 忤 giúp hiểu 忤逆 (ngỗ nghịch) — từ Hán-Việt phổ biến tiếng Việt chỉ đứa con bất hiếu; liên kết với đạo đức Nho gia.", "Tự nguyên_Xie": "忤 (wǔ) nghĩa là trái ý, vi phạm, bất tuân. Wiktionary: 心 (tâm, biểu nghĩa) + 午 (ngọ, biểu âm). Thường dùng trong từ ghép: 忤逆 (ngỗ nghịch — không vâng lời cha mẹ), 忤意 (trái ý). Chữ văn ngôn, ít gặp trong văn nói hiện đại. Cấu trúc hình thanh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngang ngược", "Hạng Tần Suất (Jun Da)": "5003.0", "Tần Suất % (Jun Da)": "99.9225194383", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 午", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄午", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "午", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "忤", "Unihan_Traditional (Chữ Phồn thể)": "忤", "Pinyin_Xie": "wǔ", "Âm Hán Việt_Xie": "ngỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ sự chống đối, không tuân theo hoặc làm tính từ mô tả tính cách ngang ngạnh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遢', '{"9000": "5004.0", "Chữ Trung Quốc": "遢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 13 | nét | 遢 | tháp | tượng hình | bẩn thỉu, luộm thuộm; chỉ dùng trong 邋遢; chưa có nguồn cấu trúc rõ ràng | 遢 thiếu dữ liệu cấu trúc rõ ràng từ nguồn học thuật. Chữ gồm bộ 辶 (đi, chuyển động) và thành phần bên trên. Chỉ dùng trong 邋遢 (lạp tháp — bẩn thỉu, luộm thuộm). Chưa có nguồn học thuật; cấu trúc chưa xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tháp\": 遢 gợi bộ 辶 (đi lại lộn xộn) — người ''tháp'' đi lại bừa bãi, nhếch nhác; 邋遢 = luộm thuộm, không gọn gàng. | Gương Hán-Việt | tháp — 邋遢 (lạp tháp): bẩn thỉu, luộm thuộm, cẩu thả | Mở khoá kiến thức | Biết 遢 giúp nhận diện từ 邋遢 — mô tả người/nơi bẩn thỉu luộm thuộm, thường dùng trong văn nói và văn học dân gian Trung Hoa.", "Tự nguyên_Xie": "遢 (tà/tā) hầu như chỉ dùng trong từ ghép 邋遢 (lātā / lā ta) — bẩn thỉu, luộm thuộm, cẩu thả. Wiktionary không cung cấp phân tích cấu tạo chi tiết. Chưa có nguồn học thuật rõ ràng về glyph cổ và cấu trúc. Chữ tạo muộn, dùng trong ngôn ngữ bình dân. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lôi thôi, bừa bãi, cẩu thả", "Hạng Tần Suất (Jun Da)": "5004.0", "Tần Suất % (Jun Da)": "99.9226103925", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 𦐇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶𦐇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𦐇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "遢", "Unihan_Traditional (Chữ Phồn thể)": "遢", "Pinyin_Xie": "tà", "Âm Hán Việt_Xie": "tháp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường kết hợp với chữ lạp để tạo thành tính từ mô tả vẻ ngoài lôi thôi, luộm thuộm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('旎', '{"9000": "5005.0", "Chữ Trung Quốc": "旎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 方 | Số nét | 11 | nét | 旎 | nỉ | tượng hình | duyên dáng, mềm mại; chỉ dùng trong 旖旎; chưa có nguồn cấu trúc học thuật rõ ràng | 旎 thiếu dữ liệu cấu trúc rõ ràng từ nguồn học thuật. Wiktionary không cung cấp phân tích hội ý/hình thanh. Chữ chỉ dùng trong 旖旎 (ỷ nỉ) — phong cảnh đẹp, duyên dáng. Chưa có nguồn học thuật; cấu trúc chưa xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nỉ\": 旎 trong 旖旎 — phong cảnh ''nỉ'' non mềm mại như dải lụa uốn lượn; dùng tả cảnh đẹp uyển chuyển. | Gương Hán-Việt | nỉ — 旖旎 (ỷ nỉ): duyên dáng, đẹp mềm mại, uyển chuyển; 旖旎风光 (ỷ nỉ phong quang): phong cảnh đẹp uyển chuyển | Mở khoá kiến thức | Biết 旎 giúp đọc thơ văn cổ điển: 旖旎 (ỷ nỉ) thường dùng tả phong cảnh núi sông đẹp, hoặc phong thái người thanh lịch.", "Tự nguyên_Xie": "旎 (nǐ) chỉ xuất hiện trong từ ghép 旖旎 (yǐ nǐ) — mô tả phong cảnh đẹp mềm mại, uốn lượn duyên dáng, hoặc phong cách uyển chuyển. Wiktionary không cung cấp phân tích glyph cổ. Chữ tạo muộn, dùng trong văn chương để tả cảnh thiên nhiên hoặc phong thái người phụ nữ. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ỷ nỉ 旖旎)", "Hạng Tần Suất (Jun Da)": "5005.0", "Tần Suất % (Jun Da)": "99.9227013467", "GavinGrover_Once (Chiết tự trực tiếp)": "方 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰方", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "旎", "Unihan_Traditional (Chữ Phồn thể)": "旎", "Pinyin_Xie": "nǐ", "Âm Hán Việt_Xie": "nỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này hầu như chỉ dùng trong từ ghép ỷ nỉ để tả cảnh sắc tươi đẹp hoặc dáng vẻ thướt tha. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘛', '{"9000": "5006.0", "Chữ Trung Quốc": "瘛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 15 | nét | 瘛 | trải | tượng hình | co giật, kinh giật; bộ 疒 (bệnh) + thành phần bên trong; chưa có nguồn học thuật | 瘛 gồm bộ 疒 (nạch — bệnh tật) và thành phần bên trong. Là chữ hình thanh thuộc nhóm bệnh lý. Wiktionary ghi ''rfdef'' (chưa có định nghĩa rõ ràng). Chỉ dùng trong 瘛瘲 (chì zòng — co giật) và 瞀瘛 (mào chì — chóng mặt co giật). Cấu trúc chưa xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trải\": bộ 疒 (bệnh) gợi người nằm bệnh — 瘛 là chứng co giật trong y học cổ truyền, tay chân ''trải'' ra co rút liên tục. | Gương Hán-Việt | trải — 瘛瘲 (trải túng): co giật tay chân; 瞀瘛 (mậu trải): chóng mặt co giật | Mở khoá kiến thức | Biết 瘛 giúp đọc sách y học cổ truyền Trung Hoa: 瘛瘲 (co giật) là triệu chứng quan trọng trong các chứng nhiệt lên não.", "Tự nguyên_Xie": "瘛 (chì) là từ y học cổ truyền chỉ co giật, kinh giật. Thường gặp trong 瘛瘲 (chì zòng) — trạng thái co giật liên tục của tay chân, triệu chứng trong bệnh thần kinh theo y học cổ. Wiktionary không có định nghĩa đầy đủ. Chưa có nguồn học thuật rõ ràng về glyph cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "co quắp, co rút", "Hạng Tần Suất (Jun Da)": "5006.0", "Tần Suất % (Jun Da)": "99.9227923009", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 恝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒恝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "恝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘛", "Unihan_Traditional (Chữ Phồn thể)": "瘛", "Pinyin_Xie": "chì", "Âm Hán Việt_Xie": "xiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng trong y học cổ truyền để chỉ chứng co giật cơ hoặc kết hợp thành từ ghép chỉ bệnh lý. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魉', '{"9000": "5007.0", "Chữ Trung Quốc": "魉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鬼 | Số nét | 16 | nét | 魉 | lưỡng | tượng hình | loài yêu quái; chỉ dùng trong 魍魎; chưa có nguồn cấu trúc học thuật rõ ràng | 魉 gồm bộ 鬼 (quỷ — ma quái) và thành phần biểu âm. Là chữ hình thanh thuộc nhóm ma quái. Chỉ dùng trong 魍魎 (wǎng liǎng) — tên loài yêu quái theo truyền thuyết Trung Hoa, ẩn trong rừng núi sông hồ. Cấu trúc chưa xác định rõ từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưỡng\": bộ 鬼 (quỷ) + âm lưỡng — loài quỷ ''lưỡng lự'' (đứng hai phía), ẩn mình trong bóng tối; 魍魎 = yêu ma quỷ quái. | Gương Hán-Việt | lưỡng — 魍魎 (võng lưỡng): yêu quái ẩn trong thiên nhiên; 魑魅魍魉 (si mỵ võng lưỡng): đủ loại yêu ma quỷ quái | Mở khoá kiến thức | Biết 魉 giúp đọc thành ngữ 魑魅魍魉 — từ quan trọng trong văn học cổ điển, chỉ mọi loại tà ma, lũ bất lương.", "Tự nguyên_Xie": "魉 (liǎng) chỉ dùng trong từ 魍魎 (wǎng liǎng) — loài yêu quái ma quái trong thần thoại Trung Hoa, ẩn mình trong rừng, núi, sông hồ. Wiktionary: chỉ có định nghĩa 魍魎, không phân tích cấu tạo chi tiết. Thành ngữ 魑魅魍魉 (si mèi wǎng liǎng) chỉ đủ loại yêu ma quỷ quái. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: võng lượng 魍魎,魍魉,蝄蜽)", "Hạng Tần Suất (Jun Da)": "5007.0", "Tần Suất % (Jun Da)": "99.9228832551", "GavinGrover_Once (Chiết tự trực tiếp)": "鬼 + 两", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鬼两", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "两", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鬼", "Unihan_Simplified (Chữ Giản thể)": "魉", "Unihan_Traditional (Chữ Phồn thể)": "魎", "Pinyin_Xie": "liǎng", "Âm Hán Việt_Xie": "lượng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường chỉ dùng trong từ ghép võng lượng để chỉ các loại ma quỷ trong truyền thuyết dân gian. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辇', '{"9000": "5008.0", "Chữ Trung Quốc": "辇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 12 | nét | 辇 | niễn | tượng hình | xe tay hoàng gia; cấu trúc cổ: người kéo xe; chưa có nguồn hội ý/hình thanh rõ ràng trong Wiktionary | 辇 gồm bộ 车 (xa — xe) và thành phần bên trên. Theo phồn thể 輦, gồm 車 (xe) + 夫 + 夫 (hai người kéo). Đây là hội ý cổ: hai người đàn ông kéo xe. Dạng giản thể 辇 đơn giản hóa cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"niễn\": bộ 车 (xe) + người kéo bên trên — xe ''niễn'' (xe ngự) do người kéo, chỉ hoàng đế được dùng. | Gương Hán-Việt | niễn — 辇毂 (niễn cốc): gần xe giá = kinh đô; 帝辇 (đế niễn): xe hoàng đế; 龙辇 (long niễn): long xa | Mở khoá kiến thức | Biết 辇 giúp đọc văn học cung đình: 辇毂之下 (dưới bánh xe ngự = kinh đô), 龙辇 (long xa hoàng đế).", "Tự nguyên_Xie": "辇 (niǎn) chỉ xe tay (handcart) hoặc xe ngự (imperial carriage — xa giá hoàng gia). Phồn thể 輦 gồm 車 (xe) + 夫夫 (hai người kéo) — hội ý: hai người đàn ông kéo xe. Wiktionary xác nhận nghĩa xe tay và xe ngự của hoàng đế. Từ ghép: 辇毂 (niếng cốc) — gần xe giá = kinh đô; 帝辇 (đế niễn) — xe của hoàng đế. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "càng xe (chỗ cầm để kéo xe); kéo xe; xe của vua", "Hạng Tần Suất (Jun Da)": "5008.0", "Tần Suất % (Jun Da)": "99.9229742092", "GavinGrover_Once (Chiết tự trực tiếp)": "㚘 + 车", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱㚘车", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㚘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "辇", "Unihan_Traditional (Chữ Phồn thể)": "輦", "Pinyin_Xie": "niǎn", "Âm Hán Việt_Xie": "liễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Làm danh từ chỉ xe kiệu của vua chúa hoặc làm động từ chỉ hành động kéo xe. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瓤', '{"9000": "5009.0", "Chữ Trung Quốc": "瓤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 瓜 | Số nét | 22 | nét | 襄 | tương | biểu âm | giúp đỡ, tương (phonetic) | 瓜 | qua | biểu nghĩa | dưa, bầu bí | 瓤 là chữ hình thanh: 瓜 (Qua, biểu nghĩa: dưa, bầu bí) + 襄 (Tương, biểu âm). Chỉ phần ruột, thịt bên trong quả dưa hoặc bầu bí. Âm ráng mượn từ 襄. Mở rộng: cũng chỉ phần bên trong của vật bất kỳ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhương\": 瓜 (dưa) + 襄 (âm nhương/ráng) — phần ''nhương'' (ruột thịt đỏ) ngọt ngào bên trong quả dưa; 瓤 = ruột dưa. | Gương Hán-Việt | nhương — 瓜瓤 (qua nhương): ruột dưa; 西瓜瓤 (tây qua nhương): ruột dưa hấu | Mở khoá kiến thức | Biết 瓤 giúp đọc văn ẩm thực, mô tả quả cây: 瓜瓤饱满 (ruột dưa đầy đặn); liên kết với bộ 瓜 trong các từ về dưa bí.", "Tự nguyên_Xie": "瓤 (ráng) chỉ phần ruột, thịt bên trong quả (đặc biệt dưa hấu, dưa chuột, bí). Wiktionary: 襄 (biểu âm) + 瓜 (dưa, biểu nghĩa). Chữ hình thanh. Từ phổ biến: 西瓜瓤 (ruột dưa hấu), 瓜瓤 (ruột dưa). Cũng dùng rộng: 书瓤 (ruột sách = nội dung), 本子瓤 (nội dung bên trong). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cùi quả", "Hạng Tần Suất (Jun Da)": "5009.0", "Tần Suất % (Jun Da)": "99.9231556008", "GavinGrover_Once (Chiết tự trực tiếp)": "襄 + 瓜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰襄瓜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "襄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "瓜", "Unihan_Simplified (Chữ Giản thể)": "瓤", "Unihan_Traditional (Chữ Phồn thể)": "瓤", "Pinyin_Xie": "ráng", "Âm Hán Việt_Xie": "nhương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau tên loại quả để chỉ phần ruột ăn được bên trong. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荥', '{"9000": "5010.0", "Chữ Trung Quốc": "荥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 荥 | huỳnh | tượng hình | địa danh Huỳnh Dương (荥阳); huyệt vị kinh lạc; chưa có nguồn cấu trúc học thuật rõ ràng | 荥 thiếu dữ liệu cấu trúc rõ ràng từ nguồn học thuật (Wiktionary chỉ ghi {{Han etym}}). Chữ liên quan đến địa danh 荥阳 (Huỳnh Dương, Hà Nam) và thuật ngữ châm cứu (荥穴 — huyệt vị loại hai). Cấu trúc chưa xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huỳnh\": 荥 gợi ''huỳnh'' (kinh lạc) — huyệt 荥 là nơi dòng khí ''lấp lánh'' chảy như suối nhỏ trong kinh lạc. | Gương Hán-Việt | huỳnh — 荥阳 (huỳnh dương): thành phố Huỳnh Dương, Hà Nam; 荥穴 (huỳnh huyệt): loại huyệt vị trong châm cứu | Mở khoá kiến thức | Biết 荥 giúp đọc sách châm cứu (荥穴 — kiểu huyệt thứ hai) và sử liệu Hà Nam (荥阳 — nơi có trận chiến lịch sử thời Sở Hán tranh hùng).", "Tự nguyên_Xie": "荥 có hai âm đọc: (1) yíng — dùng trong địa danh 荥阳 (Huỳnh Dương, tỉnh Hà Nam, Trung Hoa); (2) xíng — dùng trong y học cổ truyền: 荥穴 (huỳnh huyệt) là loại huyệt thứ hai trong ngũ du huyệt của kinh lạc. Wiktionary không cung cấp phân tích cấu tạo. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chằm Huỳnh", "Hạng Tần Suất (Jun Da)": "5010.0", "Tần Suất % (Jun Da)": "99.9232460382", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 𠕽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹𠕽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠕽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荥", "Unihan_Traditional (Chữ Phồn thể)": "滎", "Pinyin_Xie": "xíng", "Âm Hán Việt_Xie": "huỳnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng trong địa danh cổ hoặc tên huyệt vị y học cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涫', '{"9000": "5011.0", "Chữ Trung Quốc": "涫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 涫 | quán | tượng hình | nước sôi; bộ 氵 (nước) + 官 (biểu âm); chưa có nguồn học thuật rõ ràng | 涫 gồm bộ 氵 (thủy, nước) và 官 (quan, biểu âm). Là chữ hình thanh: 氵 biểu nghĩa (nước), 官 biểu âm. Wiktionary ghi ''rfdef'' (chưa có định nghĩa đầy đủ). Chỉ nước sôi sùng sục.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quán\": 氵 (nước) + 官 (quan — âm quán) — nước ''quán'' (sôi réo) như buổi họp ''quan'' lại đầy ồn ào. | Gương Hán-Việt | quán — 涫沸 (quán phí): nước sôi sùng sục; hiếm dùng trong tiếng Trung hiện đại | Mở khoá kiến thức | Biết 涫 giúp nhận diện từ hiếm trong văn bản cổ mô tả nước sôi; liên kết với bộ 氵 trong các từ về nước.", "Tự nguyên_Xie": "涫 (guàn) chỉ nước sôi sùng sục. Wiktionary không có định nghĩa đầy đủ (rfdef). Cấu trúc hình thanh: 氵 (nước) + 官 (biểu âm). Chữ hiếm, hầu như chỉ gặp trong văn bản cổ mô tả nước sôi. Chưa có nguồn học thuật rõ ràng về cấu trúc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sôi (nước)", "Hạng Tần Suất (Jun Da)": "5011.0", "Tần Suất % (Jun Da)": "99.9233364756", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 官", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵官", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "官", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "涫", "Unihan_Traditional (Chữ Phồn thể)": "涫", "Pinyin_Xie": "guàn", "Âm Hán Việt_Xie": "quan, quản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ chỉ nước sôi hoặc tính từ miêu tả trạng thái sôi sục, nóng bỏng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('娌', '{"9000": "5012.0", "Chữ Trung Quốc": "娌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 10 | nét | 女 | nữ | biểu nghĩa | phụ nữ | 里 | lý | biểu âm | trong, lý (phonetic) | 娌 là chữ hình thanh: 女 (Nữ, biểu nghĩa: phụ nữ, quan hệ gia đình nữ) + 里 (Lý, biểu âm). Chỉ vợ của em chồng trong quan hệ gia đình. Chỉ dùng trong 妯娌 (zhóu lǐ) — chị dâu và em dâu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lý\": 女 (phụ nữ) + 里 (trong nhà, âm lý) — những người phụ nữ ''trong nhà'' kết thành 妯娌 (chị dâu - em dâu). | Gương Hán-Việt | lý — chỉ dùng trong 妯娌 (trục lý): chị dâu và em dâu trong gia đình | Mở khoá kiến thức | Biết 娌 giúp hiểu từ 妯娌 — quan hệ gia đình quan trọng trong văn hóa Trung Hoa; thường xuất hiện trong tiểu thuyết gia đình.", "Tự nguyên_Xie": "娌 (lǐ) chỉ dùng trong từ 妯娌 (zhóu lǐ) — quan hệ giữa những người phụ nữ lấy anh em trong cùng gia đình (chị dâu - em dâu). Wiktionary: 女 (phụ nữ, biểu nghĩa) + 里 (biểu âm). Chữ hình thanh. Đây là quan hệ gia đình đặc thù trong văn hóa Trung Hoa. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chị em dâu; chị em bạn dâu", "Hạng Tần Suất (Jun Da)": "5012.0", "Tần Suất % (Jun Da)": "99.923426913", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 里", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女里", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "里", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "娌", "Unihan_Traditional (Chữ Phồn thể)": "娌", "Pinyin_Xie": "lǐ", "Âm Hán Việt_Xie": "lí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Hầu như chỉ dùng trong từ ghép trục lý để chỉ quan hệ chị em dâu trong gia đình. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氚', '{"9000": "5013.0", "Chữ Trung Quốc": "氚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 气 | Số nét | 7 | nét | 气 | khí | biểu nghĩa | khí, khí gas | 川 | xuyên | biểu nghĩa | ba nét = ba (số 3) | 氚 là chữ hội ý (và hình thanh): 气 (Khí, khí gas — biểu nghĩa) + 川 (Xuyên — biểu nghĩa: ba nét = số 3, biểu âm). Wiktionary: ''gas + three = hydrogen isotope with 3 nucleons (tritium)''. Cũng có thể dùng như hình thanh với 川 biểu âm. So sánh: 氕 (protium, 1), 氘 (deuterium, 2), 氚 (tritium, 3).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xuyên\": 气 (khí) + 川 (ba nét = số 3) — khí có 3 hạt nhân; 氚 = tritium (hydro-3). Hệ thống đẹp: 氕(1) → 氘(2) → 氚(3). | Gương Hán-Việt | xuyên — 氚 là ký hiệu hoá học; 氚水 (xuyên thủy): nước tritium (T₂O); 氚核 (xuyên hạch): hạt nhân tritium | Mở khoá kiến thức | Biết 氚 giúp đọc văn bản vật lý hạt nhân: 氚 (tritium) dùng trong phản ứng nhiệt hạch; liên kết với hệ thống 氕氘氚 — bộ ba đồng vị hydro.", "Tự nguyên_Xie": "氚 (chuān) là ký hiệu chữ Hán cho tritium (hydro-3, T hoặc ³H) — đồng vị phóng xạ của hydro với 2 neutron. Wiktionary: 气 (khí, biểu nghĩa) + 川 (ba, biểu nghĩa: 3 hạt nhân). Hệ thống chữ đồng vị hydro: 氕 (protium/H-1) — 氘 (deuterium/H-2) — 氚 (tritium/H-3). Số nét của thành phần thứ hai tương ứng với số khối. Chữ tạo muộn cho thuật ngữ khoa học. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồng vị trity (T) của hydro (H)", "Hạng Tần Suất (Jun Da)": "5013.0", "Tần Suất % (Jun Da)": "99.9235173504", "GavinGrover_Once (Chiết tự trực tiếp)": "气 + 川", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴气川", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "川", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "气", "Unihan_Simplified (Chữ Giản thể)": "氚", "Unihan_Traditional (Chữ Phồn thể)": "氚", "Pinyin_Xie": "chuān", "Âm Hán Việt_Xie": "xuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chuyên ngành hóa học và vật lý hạt nhân để chỉ đồng vị phóng xạ của hydro. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臁', '{"9000": "5014.0", "Chữ Trung Quốc": "臁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 17 | nét | 臁 | liêm | tượng hình | cẳng chân, xương ống chân; bộ 肉/月 (thịt, cơ thể) + thành phần bên phải; chưa có nguồn học thuật | 臁 gồm bộ 月/肉 (nhục — thịt, cơ thể) và thành phần bên phải. Là chữ hình thanh thuộc nhóm giải phẫu cơ thể. Wiktionary không có dữ liệu glyph cổ. Chỉ vùng cẳng chân, xương ống chân. Cấu trúc chưa xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêm\": bộ 月/肉 (thịt cơ thể) + âm liêm — vùng ''liêm'' (cẳng chân) mỏng manh dễ bị thương; 臁疮 là bệnh loét cẳng chân. | Gương Hán-Việt | liêm — 臁疮 (liêm sang): loét cẳng chân, bệnh da mãn tính | Mở khoá kiến thức | Biết 臁 giúp đọc sách y học cổ truyền và da liễu: 臁疮 (liêm sang) là bệnh loét cẳng chân khó lành, thường gặp ở người cao tuổi.", "Tự nguyên_Xie": "臁 (lián) chỉ vùng cẳng chân, xương ống chân (shin). Thường gặp trong từ y học: 臁疮 (liêm sang) — loét cẳng chân, bệnh da mãn tính ở vùng cẳng chân dưới. Wiktionary không có glyph cổ hay phân tích cấu tạo. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ống chân", "Hạng Tần Suất (Jun Da)": "5014.0", "Tần Suất % (Jun Da)": "99.9236077878", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 廉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月廉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "廉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "臁", "Unihan_Traditional (Chữ Phồn thể)": "臁", "Pinyin_Xie": "lián", "Âm Hán Việt_Xie": "liêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng trong y học cổ truyền để chỉ vùng ống chân hoặc các bệnh lý liên quan đến chân. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('毂', '{"9000": "5015.0", "Chữ Trung Quốc": "毂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 殳 | Số nét | 13 | nét | 毂 | cốc | tượng hình | trục bánh xe, tâm bánh xe; dạng giản thể của 轂 | 毂 là dạng giản thể của 轂. Chữ phồn thể 轂 gồm 車 (xa — xe) và thành phần phức tạp. Chỉ trục (hub) bánh xe, phần tâm nơi các căm xe tụ lại. Wiktionary: giản thể từ 轂, bỏ bộ 車 và nét ngang phía trên 车.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cốc\": 毂 = trục bánh xe — Lão Tử nói: tâm bánh xe ''cốc'' rỗng mà làm cho xe chạy được; sự vô ích lại hữu ích nhất. | Gương Hán-Việt | cốc — 辇毂 (niễn cốc): gần bánh xe vua = kinh đô; 毂下 (cốc hạ): dưới bánh xe ngự = kinh thành | Mở khoá kiến thức | Biết 毂 giúp đọc Đạo Đức Kinh ch.11 (trục bánh xe rỗng), thành ngữ 辇毂 (kinh đô), và văn học cung đình.", "Tự nguyên_Xie": "毂 (gǔ) là dạng giản thể của 轂, chỉ trục bánh xe (wheel hub) — phần trung tâm nơi các căm xe 辐 tụ vào. Wiktionary: giản thể từ 轂 (f=車→车). Từ triết học: Lão Tử dùng hình ảnh 毂 (trục bánh xe rỗng) để nói về sự hữu dụng của trống rỗng (Đạo Đức Kinh ch. 11). Từ ghép: 辇毂 (kinh đô), 毂下 (dưới trục xe = gần vua). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bầu xe (chỗ tụ hợp các nan hoa); tụ họp đông", "Hạng Tần Suất (Jun Da)": "5015.0", "Tần Suất % (Jun Da)": "99.9236982252", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 军", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴军", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "毂", "Unihan_Traditional (Chữ Phồn thể)": "轂", "Pinyin_Xie": "gǔ", "Âm Hán Việt_Xie": "cốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ bộ phận trung tâm của bánh xe hoặc ẩn dụ cho trung tâm đầu mối giao thông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碇', '{"9000": "5016.0", "Chữ Trung Quốc": "碇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 13 | nét | 石 | thạch | biểu nghĩa | đá | 定 | định | biểu âm | định, cố định (phonetic) | 碇 là chữ hình thanh: 石 (Thạch, biểu nghĩa: đá) + 定 (Định, biểu âm). Chỉ neo tàu (anchor) bằng đá hoặc vật nặng thả xuống để neo thuyền. Hình ảnh đá ''định'' (cố định) tàu thuyền tại chỗ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đính\": 石 (đá nặng) + 定 (cố định, âm đính/dìng) — tảng đá cố ''định'' con thuyền; 碇 = neo tàu. | Gương Hán-Việt | đính — 碇泊 (đính bạc): neo đậu (tàu thuyền); 下碇 (hạ đính): thả neo | Mở khoá kiến thức | Biết 碇 giúp đọc văn học hàng hải, thơ ca về thuyền bè: 碇泊 (neo đậu), 下碇 (thả neo); liên kết với bộ 石 trong dụng cụ đá.", "Tự nguyên_Xie": "碇 (dìng) chỉ neo tàu — vật nặng (thường bằng đá hoặc kim loại) thả xuống để giữ tàu thuyền tại chỗ. Wiktionary: 石 (đá, biểu nghĩa) + 定 (định, biểu âm). Chữ hình thanh. Từ ghép: 碇泊 (đính bạc) — neo đậu; 下碇 (hạ đính) — thả neo. Chữ đặc trưng trong văn học hàng hải. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hòn đá để cột thuyền vào; cái neo thuyền", "Hạng Tần Suất (Jun Da)": "5016.0", "Tần Suất % (Jun Da)": "99.9237886626", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 定", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石定", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "定", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碇", "Unihan_Traditional (Chữ Phồn thể)": "椗", "Pinyin_Xie": "dìng", "Âm Hán Việt_Xie": "đĩnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cái neo thuyền bằng đá hoặc sắt, thường dùng trong văn cổ hoặc từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('毖', '{"9000": "5017.0", "Chữ Trung Quốc": "毖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 比 | Số nét | 9 | nét | 毖 | tất | tượng hình | thận trọng, cảnh giác; bộ 比 + 毛; chưa có nguồn hội ý/hình thanh rõ ràng | 毖 gồm bộ 比 (tỷ — so sánh) và 毛 (mao — lông, thể hiện cẩn thận, nhỏ nhặt). Có thể là hội ý: cẩn thận từng chi tiết nhỏ. Wiktionary không cung cấp phân tích hình thanh/hội ý rõ ràng. Thường gặp nhất trong 惩前毖后 — lấy bài học trước làm cẩn thận về sau.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tất\": 毖 gợi sự ''tất'' (cẩn thận từng chi tiết nhỏ như sợi lông 毛) — cẩn trọng không để sai lầm; 惩前毖后 = bài học từ quá khứ. | Gương Hán-Việt | tất — 惩前毖后 (trừng tiền tất hậu): rút bài học từ lỗi trước, cẩn thận về sau | Mở khoá kiến thức | Biết 毖 giúp hiểu thành ngữ quan trọng 惩前毖后 — thành ngữ Mao Trạch Đông dùng nổi tiếng trong văn kiện chính trị.", "Tự nguyên_Xie": "毖 (bì) nghĩa là thận trọng, cảnh giác, đề phòng. Wiktionary: nghĩa gồm ''cautious, guard against, instruct, reward with food''. Thành ngữ nổi tiếng nhất: 惩前毖后 (징tiền tất hậu) — trừng phạt sai lầm trước để cẩn thận về sau; lấy bài học từ quá khứ. Chưa có nguồn học thuật rõ về cấu tạo glyph. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cẩn thận; nặng nhọc", "Hạng Tần Suất (Jun Da)": "5017.0", "Tần Suất % (Jun Da)": "99.9238785832", "GavinGrover_Once (Chiết tự trực tiếp)": "比 + 必", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱比必", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "必", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "比", "Unihan_Simplified (Chữ Giản thể)": "毖", "Unihan_Traditional (Chữ Phồn thể)": "毖", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ thể hiện sự cẩn trọng hoặc động từ với nghĩa răn đe, cảnh giác. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('壅', '{"9000": "5018.0", "Chữ Trung Quốc": "壅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 16 | nét | 雍 | ủng | biểu âm | ủng, hòa (phonetic) | 土 | thổ | biểu nghĩa | đất | 壅 là chữ hình thanh: 土 (Thổ, biểu nghĩa: đất) + 雍 (Ủng, biểu âm). Chỉ hành động đắp đất quanh gốc cây, hoặc tắc nghẽn. Âm yōng mượn từ 雍.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ủng\": 土 (đất) + 雍 (âm ủng/yōng) — đắp ''ủng'' đất quanh gốc cây, hoặc bít đất lại tắc nghẽn; 壅 = đắp đất / tắc. | Gương Hán-Việt | ủng — 壅塞 (ủng tắc): tắc nghẽn; 壅土 (ủng thổ): đắp đất quanh gốc cây | Mở khoá kiến thức | Biết 壅 giúp đọc văn nông nghiệp cổ (壅土施肥 — đắp đất bón phân) và thành ngữ 壅塞 (tắc nghẽn đường thông).", "Tự nguyên_Xie": "壅 (yōng) có hai nghĩa: (1) tắc nghẽn, bít lại; (2) đắp đất quanh gốc cây (nông nghiệp). Wiktionary: 雍 (biểu âm) + 土 (đất, biểu nghĩa). Chữ hình thanh. Từ ghép: 壅塞 (ủng tắc) — tắc nghẽn; 壅土 (ủng thổ) — đắp đất quanh gốc. Dùng trong văn học cổ và nông nghiệp. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vun xới", "Hạng Tần Suất (Jun Da)": "5018.0", "Tần Suất % (Jun Da)": "99.9239685038", "GavinGrover_Once (Chiết tự trực tiếp)": "亠 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "壅", "Unihan_Traditional (Chữ Phồn thể)": "壅", "Pinyin_Xie": "yōng", "Âm Hán Việt_Xie": "ủng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động vun xới gốc cây hoặc gây tắc nghẽn dòng chảy. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('吡', '{"9000": "5019.0", "Chữ Trung Quốc": "吡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 吡 | bỉ | tượng hình | pyridine (hóa học); tiếng cọ sát; bộ 口 + 比; chưa có nguồn học thuật | 吡 gồm bộ 口 (khẩu — miệng, âm thanh) và 比 (tỷ — so sánh, biểu âm). Wiktionary chỉ ghi {{Han etym}}. Dùng trong hóa học hữu cơ: 吡啶 (bǐ dìng) = pyridine; 吡咯 (bǐ luò) = pyrrole. Chữ tạo muộn cho thuật ngữ hóa học.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bỉ\": bộ 口 (miệng) + 比 (so sánh, âm bỉ) — trong hóa học, 吡 là ''bỉ'' tiền tố cho vòng thơm chứa nitrogen (pyridine, pyrrole). | Gương Hán-Việt | bỉ — 吡啶 (bỉ đính): pyridine; 吡咯 (bỉ lạc): pyrrole; 吡唑 (bỉ trác): pyrazole | Mở khoá kiến thức | Biết 吡 giúp đọc văn bản hóa học hữu cơ: 吡啶 (pyridine — dung môi, tổng hợp dược), 吡咯 (pyrrole — trong hemoglobin).", "Tự nguyên_Xie": "吡 (bǐ/pī) chủ yếu là tiền tố trong thuật ngữ hóa học hữu cơ: 吡啶 (pyridine), 吡咯 (pyrrole), 吡唑 (pyrazole). Cũng có nghĩa cũ: tiếng cọ sát, tiếng cót két. Wiktionary không có phân tích cấu tạo. Chữ tạo muộn cho khoa học hiện đại. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "py-ri-đin (pyridine); Ghi chú: 另见pǐ", "Hạng Tần Suất (Jun Da)": "5019.0", "Tần Suất % (Jun Da)": "99.9240584245", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 比", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口比", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "比", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "吡", "Unihan_Traditional (Chữ Phồn thể)": "吡", "Pinyin_Xie": "bǐ", "Âm Hán Việt_Xie": "phỉ, tật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ trong hóa học hoặc làm động từ chỉ sự chê bai trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缛', '{"9000": "5020.0", "Chữ Trung Quốc": "缛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 缛 | nhục | tượng hình | trang sức lộng lẫy, nghi lễ phức tạp; bộ 纟 (tơ lụa) + 辱 (biểu âm); chưa có nguồn học thuật rõ ràng | 缛 gồm bộ 纟 (mịch — tơ, lụa, chỉ đặc điểm trang trí tinh xảo) và 辱 (nhục, biểu âm). Là chữ hình thanh. Chỉ sự trang trí công phu, nghi lễ rườm rà phức tạp. Wiktionary có định nghĩa nhưng không phân tích cấu tạo glyph cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhục\": bộ 纟 (tơ lụa — đồ trang trí) + âm nhục/rù — lụa ''nhục'' (rườm rà) quá nhiều trang trí; 缛 = xa xỉ lộng lẫy / nghi lễ rườm rà. | Gương Hán-Việt | nhục — 繁文缛节 (phồn văn nhục tiết): nghi lễ rườm rà; 缛礼 (nhục lễ): nghi lễ phức tạp; 缛绣 (nhục tú): thêu thùa lộng lẫy | Mở khoá kiến thức | Biết 缛 giúp hiểu thành ngữ 繁文缛节 — mô tả quy trình, thủ tục rườm rà không cần thiết; dùng nhiều trong văn phê phán hành chính.", "Tự nguyên_Xie": "缛 (rù) nghĩa là trang sức lộng lẫy, nghi lễ phức tạp rườm rà. Wiktionary: ''decorative, adorned, elegant; beautiful''. Từ ghép quan trọng: 繁文缛节 (phồn văn nhục tiết) — nghi thức lễ nghĩa rườm rà, phức tạp không cần thiết. Cũng dùng trong 缛礼 (nghi lễ phức tạp), 缛绣 (thêu thùa tinh xảo). Chữ hình thanh với bộ 纟 (tơ lụa = đồ trang trí). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ lụa nhiều màu sặc sỡ", "Hạng Tần Suất (Jun Da)": "5020.0", "Tần Suất % (Jun Da)": "99.9241483451", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 辱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟辱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缛", "Unihan_Traditional (Chữ Phồn thể)": "縟", "Pinyin_Xie": "rù", "Âm Hán Việt_Xie": "nhục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả sự hoa mỹ, nhiều chi tiết hoặc nghi lễ rườm rà. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('玮', '{"9000": "5021.0", "Chữ Trung Quốc": "玮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 8 | nét | 玮 | vỹ | tượng hình | ngọc quý hiếm; dạng giản thể của 瑋; bộ 玉/王 (ngọc) + 韦/韋 (biểu âm) | 玮 là dạng giản thể của 瑋. Chữ gốc 瑋 gồm 玉 (ngọc, biểu nghĩa) + 韋 (vi — biểu âm). Chữ hình thanh. Dạng giản thể 玮 đơn giản hóa 韋 → 韦. Chỉ ngọc quý hiếm, thường dùng đặt tên với hàm nghĩa cao quý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vỹ\": 玉 (ngọc quý) + 韦 (âm vỹ/wěi) — ngọc ''vỹ'' (quý hiếm, to lớn như vỹ đại); 玮 = ngọc quý, thường dùng đặt tên. | Gương Hán-Việt | vỹ — 奇玮 (kỳ vỹ): kỳ diệu quý giá; ít dùng độc lập, thường trong tên người | Mở khoá kiến thức | Biết 玮 giúp nhận diện tên người Trung Hoa: 玮 là chữ phổ biến trong tên, mang nghĩa quý như ngọc.", "Tự nguyên_Xie": "玮 (wěi) là dạng giản thể của 瑋, chỉ ngọc quý, vật quý hiếm. Wiktionary: giản thể từ 瑋 (f=韋→韦). Cấu trúc gốc: 玉 (ngọc, biểu nghĩa) + 韋 (vi, biểu âm). Chữ thường dùng trong tên người, mang ý nghĩa cao quý, quý báu như ngọc. Không có nghĩa thông dụng ngoài tên riêng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc vĩ", "Hạng Tần Suất (Jun Da)": "5021.0", "Tần Suất % (Jun Da)": "99.9242382657", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 韦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王韦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "韦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "玮", "Unihan_Traditional (Chữ Phồn thể)": "瑋", "Pinyin_Xie": "wěi", "Âm Hán Việt_Xie": "vĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ sự quý báu, tốt đẹp hoặc làm danh từ chỉ một loại ngọc quý. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羟', '{"9000": "5022.0", "Chữ Trung Quốc": "羟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 11 | nét | 羊 | dương | biểu nghĩa | dê, cừu (phonetic blend: âm từ 氢) | 巠 | kinh | biểu âm | kinh (phonetic: từ 氧) | 羟 là chữ hình thanh đặc biệt: được tạo ra như blend của 氢 (hydro) và 氧 (oxy). Wiktionary giải thích: 羊 (phonetic từ 氢 — lấy âm) + 巠 (phonetic từ 氧 — lấy âm). Chữ tạo muộn để ký hiệu nhóm hydroxyl (-OH) trong hóa học hữu cơ. Cũng có nghĩa cũ: loài dê/cừu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khương\": 羟 = blend của 氢 (H) + 氧 (O) → nhóm -OH; cừu 羊 mang 巠 = nhóm hydroxyl gắn vào phân tử hữu cơ. | Gương Hán-Việt | khương — 羟基 (khương cơ): nhóm hydroxyl (-OH); 羟基酸 (khương cơ toan): acid hydroxy | Mở khoá kiến thức | Biết 羟 giúp đọc văn bản hóa học hữu cơ: 羟基 (-OH group) là nhóm chức quan trọng trong alcohol, acid carboxylic.", "Tự nguyên_Xie": "羟 (qiǎng/qīng) có nghĩa kép: (1) nghĩa cũ: một loài dê/cừu (羊 + 巠 biểu âm); (2) nghĩa hiện đại trong hóa học: nhóm hydroxyl (-OH), chữ được tạo ra như pha trộn của 氢 (hydrogen) và 氧 (oxygen) — lấy 羊 từ 氢 và 巠 từ 氧. Wiktionary xác nhận cả hai lớp nghĩa này. Chữ thú vị: kết hợp hai nguyên tử tạo thành một chữ mới. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên một loại dê", "Hạng Tần Suất (Jun Da)": "5022.0", "Tần Suất % (Jun Da)": "99.9243281863", "GavinGrover_Once (Chiết tự trực tiếp)": "羊 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰羊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "羟", "Unihan_Traditional (Chữ Phồn thể)": "羥", "Pinyin_Xie": "qiǎng", "Âm Hán Việt_Xie": "khan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài dê hoặc dùng trong hóa học để chỉ nhóm hydroxyl. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('珈', '{"9000": "5023.0", "Chữ Trung Quốc": "珈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 9 | nét | 玉 | ngọc | biểu nghĩa | ngọc bích | 加 | gia | biểu âm | thêm vào, gia (phonetic) | 珈 là chữ hình thanh: 玉 (Ngọc, biểu nghĩa: ngọc bích, đồ trang sức) + 加 (Gia, biểu âm). Chỉ đồ trang sức ngọc gắn trên trâm cài đầu phụ nữ. Âm jiā mượn từ 加.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"gia\": 玉 (ngọc) + 加 (thêm vào, âm gia) — ngọc ''thêm vào'' (gia thêm) trâm đầu; 珈 = đồ ngọc trang sức đầu tóc. | Gương Hán-Việt | gia — 珈珞 (gia lạc): đồ ngọc; 珞珈山 (lạc gia sơn): địa danh tại Vũ Hán (Đại học Vũ Hán) | Mở khoá kiến thức | Biết 珈 giúp nhận diện địa danh 珞珈山 (Vũ Hán) và các tên nữ có ý nghĩa ngọc trang sức.", "Tự nguyên_Xie": "珈 (jiā) chỉ vật trang sức bằng ngọc gắn vào trâm cài đầu (hairpin ornament) của phụ nữ quý tộc thời cổ. Wiktionary: 玉 (ngọc, biểu nghĩa) + 加 (biểu âm). Chữ hình thanh. Địa danh nổi tiếng: 珞珈山 (Lạc Gia Sơn) — đồi tại Đại học Vũ Hán. Chữ thường dùng trong tên nữ và địa danh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái già (đồ trang sức trên đầu của phụ nữ thời xưa)", "Hạng Tần Suất (Jun Da)": "5023.0", "Tần Suất % (Jun Da)": "99.9245075107", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 加", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王加", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "加", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "珈", "Unihan_Traditional (Chữ Phồn thể)": "珈", "Pinyin_Xie": "jiā", "Âm Hán Việt_Xie": "già", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ món đồ trang sức quý giá cài đầu của phụ nữ thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颀', '{"9000": "5024.0", "Chữ Trung Quốc": "颀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 斤 | Số nét | 10 | nét | 颀 | kỳ | tượng hình | cao và mảnh khảnh; bộ 頁 (đầu) + 斤 (rìu, biểu âm); chưa có nguồn học thuật rõ ràng | 颀 gồm bộ 頁 (hiệt — đầu, vùng đầu/cổ) và 斤 (cân — rìu, biểu âm). Là chữ hình thanh thuộc bộ 頁. Chỉ dáng người cao và mảnh khảnh. Wiktionary ghi nhận nhưng không phân tích chi tiết glyph cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": bộ 頁 (đầu) + 斤 (rìu — nặng, âm kỳ) — đầu ''kỳ'' (cao lên) mảnh dẻ như cán rìu; 颀 = dáng cao mảnh khảnh. | Gương Hán-Việt | kỳ — 颀长 (kỳ trường): cao và mảnh; 颀然 (kỳ nhiên): dáng cao thanh tú | Mở khoá kiến thức | Biết 颀 giúp đọc thơ văn mô tả dáng người: 颀长的身材 (thân hình cao mảnh), 颀然玉立 (đứng thẳng thanh tú như ngọc).", "Tự nguyên_Xie": "颀 (qí) chỉ dáng người cao và mảnh dẻ, thanh tú. Wiktionary: ''tall and slim''. Thường dùng trong từ ghép: 颀长 (kỳ trường) — cao và mảnh; 颀然 (kỳ nhiên) — dáng cao thượng, thanh tú. Chữ văn ngôn, dùng trong thơ ca mô tả dáng người thanh mảnh. Chưa có nguồn học thuật rõ ràng về glyph cổ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xót thương, ái ngại", "Hạng Tần Suất (Jun Da)": "5024.0", "Tần Suất % (Jun Da)": "99.9245969146", "GavinGrover_Once (Chiết tự trực tiếp)": "斤 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰斤页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "页", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "斤", "Unihan_Simplified (Chữ Giản thể)": "颀", "Unihan_Traditional (Chữ Phồn thể)": "頎", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả vóc dáng cao ráo, đẹp đẽ của con người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虼', '{"9000": "5025.0", "Chữ Trung Quốc": "虼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 9 | nét | 虼 | tượng hình | loài côn trùng nhỏ (bọ chét dê/lạc đà) | 虼 là chữ độc thể, không phân tích được bộ phận rõ ràng từ nguồn học thuật; chưa có nguồn học thuật về cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cách\" (học giả phục nguyên từ MC gè): 虼 — con bọ chét ký sinh nhỏ bé, chữ hiếm trong phương ngữ Trung Quốc. | Gương Hán-Việt | cách — chưa thấy dùng trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | 虼 rất hiếm gặp, chủ yếu xuất hiện trong từ 虼蚤 (bọ chét) ở tiếng Trung phương ngữ.", "Tự nguyên_Xie": "虼 (gè) chỉ một loài côn trùng ký sinh nhỏ (bọ chét loài dê hoặc lạc đà). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn; chưa có nguồn học thuật về tự nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con bọ chét", "Hạng Tần Suất (Jun Da)": "5025.0", "Tần Suất % (Jun Da)": "99.9246863184", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 乞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫乞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "虼", "Unihan_Traditional (Chữ Phồn thể)": "虼", "Pinyin_Xie": "gè", "Âm Hán Việt_Xie": "khất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường kết hợp tạo thành từ ghép chỉ các loại côn trùng nhỏ hút máu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佝', '{"9000": "5026.0", "Chữ Trung Quốc": "佝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 7 | nét | 亻 | nhân | biểu nghĩa | người | 句 | câu | biểu âm | câu văn, cong | 佝 = 亻(Nhân, biểu nghĩa: người) + 句 (Câu, biểu âm); chữ hình thanh. Bộ 亻 xác định nghĩa liên quan đến trạng thái thân người; 句 cung cấp âm đọc (gōu/kòu).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"câu\": 亻(người) + 句 (cong) — người còng lưng như một dấu câu uốn cong. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 佝 giúp nhận ra từ 佝偻病 (bệnh còi xương) — từ y học quan trọng.", "Tự nguyên_Xie": "Kim văn | Bạch thư | Đại triện | 佝 là chữ hình thanh: 亻(nhân) biểu nghĩa — trạng thái cơ thể người; 句 (câu) biểu âm. Chữ chủ yếu dùng trong từ 佝偻 (gōulóu) — bệnh còi xương, dáng người còng lưng. Phần 句 vốn mang nghĩa ''cong, uốn'', phù hợp với hình ảnh người cúi khom. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gù lưng, còng lưng", "Hạng Tần Suất (Jun Da)": "5026.0", "Tần Suất % (Jun Da)": "99.9248640925", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 句", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻句", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "佝", "Unihan_Traditional (Chữ Phồn thể)": "佝", "Pinyin_Xie": "gōu", "Âm Hán Việt_Xie": "câu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả tư thế lưng gù hoặc kết hợp thành từ ghép chỉ bệnh còi xương. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翕', '{"9000": "5027.0", "Chữ Trung Quốc": "翕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 12 | nét | 合 | cáp | biểu âm | hợp lại | 羽 | vũ | biểu nghĩa | lông, cánh | 翕 = 合 (Cáp, biểu âm) + 羽 (Vũ, biểu nghĩa: cánh/lông); chữ hình thanh. Bộ 羽 xác định nghĩa liên quan đến chim/cánh; 合 cung cấp âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hấp\": 羽 (cánh) + 合 (hợp) — đôi cánh khép hợp lại, chim thu mình co rúm — hình ảnh ''hấp thu'', co vào. | Gương Hán-Việt | hấp dẫn (吸引), hấp thu — tuy viết khác nhưng cùng âm Hán-Việt | Mở khoá kiến thức | Biết 翕 giúp đọc văn ngôn cổ nơi nó nghĩa là ''hòa hợp, thu lại'' (翕然, 翕合).", "Tự nguyên_Xie": "Đại triện | 翕 là chữ hình thanh: 羽 (vũ) biểu nghĩa — cánh chim; 合 (cáp) biểu âm. Nghĩa gốc là cánh chim xếp lại khép vào nhau (co lại, thu lại). Từ đó mở rộng sang nghĩa hòa thuận, nhất trí, tụ lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đóng lại; phù hợp, tương xứng", "Hạng Tần Suất (Jun Da)": "5027.0", "Tần Suất % (Jun Da)": "99.9249529795", "GavinGrover_Once (Chiết tự trực tiếp)": "合 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱合羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "合", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翕", "Unihan_Traditional (Chữ Phồn thể)": "翕", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hấp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ động tác khép mở của môi, cánh hoặc tính từ chỉ sự đồng thuận. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遴', '{"9000": "5028.0", "Chữ Trung Quốc": "遴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 15 | nét | 遴 | lận | tượng hình | chọn lựa kỹ càng, khó đi | 遴 trong ngữ liệu hiện tại không phân tích rõ bộ phận; cấu tạo gồm bộ 辶 (thước, di chuyển) và phần 粦 hoặc 廪 làm biểu âm. Chữ hình thanh, nghĩa gốc là ''đường khó đi'', sau mở rộng sang ''chọn lựa kỹ''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lận\": 遴 — đường gian nan mà vẫn phải cẩn thận lựa bước đi từng bước, như quá trình tuyển chọn kỹ lưỡng. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 遴 giúp đọc văn hành chính Trung Quốc hiện đại: 遴选 (tuyển chọn), 遴派 (cử phái).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 遴 (lín) có hai đọc: nghĩa 1 là tuyển chọn cẩn thận (遴选); nghĩa 2 (lìn, cổ) là đường xấu, khó đi. Wiktionary xác nhận có thành phần di chuyển (辶) và biểu âm. Chữ tạo muộn so với giáp cốt/kim văn; chưa có nguồn học thuật đầy đủ về tự nguyên. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khó; lựa chọn", "Hạng Tần Suất (Jun Da)": "5028.0", "Tần Suất % (Jun Da)": "99.9250418666", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 粦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶粦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "粦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "遴", "Unihan_Traditional (Chữ Phồn thể)": "遴", "Pinyin_Xie": "lín", "Âm Hán Việt_Xie": "lân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ để chỉ việc tuyển chọn nhân tài hoặc cán bộ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('珏', '{"9000": "5029.0", "Chữ Trung Quốc": "珏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 9 | nét | 珏 | tượng hình | hai viên ngọc đặt cạnh nhau | 珏 là chữ hội ý tượng hình: gồm hai chữ 玉 (ngọc) ghép lại, biểu thị hai viên ngọc đặt cạnh nhau như một bộ đôi. Wiktionary dẫn sang 玨 là chính thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 珏 — hình ảnh đôi ngọc quý sánh đôi, như hai anh hùng song kiếm hay một cặp đôi hoàn hảo. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 珏 giúp nhận ra tên người và tên riêng trong văn chương Trung Quốc (tên gợi sự quý phái đôi lứa).", "Tự nguyên_Xie": "Tiểu triện | 珏 là dị thể của 玨 — hai chữ 玉 (ngọc) xếp song song, biểu thị ''đôi ngọc, cặp ngọc quý''. Dùng để chỉ hai vật đẹp hoặc hai người tài ngang nhau. Chữ tạo muộn, chưa có giáp cốt/kim văn rõ ràng. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc (hai miếng ngọc ghép lại)", "Hạng Tần Suất (Jun Da)": "5029.0", "Tần Suất % (Jun Da)": "99.9251307536", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 玉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王玉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "玉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "珏", "Unihan_Traditional (Chữ Phồn thể)": "玨", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "giác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn cổ hoặc dùng đặt tên người để chỉ bảo vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郛', '{"9000": "5030.0", "Chữ Trung Quốc": "郛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 9 | nét | 郛 | tượng hình | tường ngoài thành, ngoại thành | 郛 không có phân tích bộ phận rõ từ nguồn anchor; chữ chỉ vành đai ngoài của thành quách cổ. Cấu tạo có thể gồm bộ 阜/邑 (ấp, thành trì) và phần biểu âm; chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 郛 (fú) — vành đai ngoài của kinh thành, như lớp tường bảo vệ phía ngoài cùng của một đô thành cổ đại. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 郛 giúp đọc văn ngôn cổ và thư tịch lịch sử khi nhắc đến cấu trúc thành trì.", "Tự nguyên_Xie": "Tiểu triện | 郛 (fú) nghĩa là tường thành ngoại vi, phần vành đai bên ngoài của thành quách cổ đại. Chữ tạo muộn, chủ yếu thấy trong kim văn và thư tịch cổ Trung Hoa; chưa có nguồn học thuật đầy đủ về tự nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khu ngoài thành, ngoại ô", "Hạng Tần Suất (Jun Da)": "5030.0", "Tần Suất % (Jun Da)": "99.9252196407", "GavinGrover_Once (Chiết tự trực tiếp)": "孚 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰孚阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郛", "Unihan_Traditional (Chữ Phồn thể)": "郛", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ vòng thành bao bọc bên ngoài thành chính thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('玖', '{"9000": "5031.0", "Chữ Trung Quốc": "玖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 7 | nét | 玉 | ngọc | biểu nghĩa | ngọc quý | 久 | cửu | biểu âm | lâu dài | 玖 = 玉 (Ngọc, biểu nghĩa: đá quý) + 久 (Cửu, biểu âm); chữ hình thanh. Bộ 玉 xác định nghĩa liên quan đến đá quý; 久 cung cấp âm đọc jiǔ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cửu\": 玉 (ngọc) + 久 (lâu dài) — viên đá tối màu bền vững theo năm tháng, dùng như số 9 chống làm giả trong hợp đồng. | Gương Hán-Việt | cửu — 九 (cửu: chín), 久 (cửu: lâu) — cùng âm Hán-Việt | Mở khoá kiến thức | Biết 玖 giúp đọc hợp đồng tài chính Trung Quốc (chữ số chống giả: 壹貳叁肆伍陸柒捌玖).", "Tự nguyên_Xie": "玖 là chữ hình thanh: 玉 (ngọc) biểu nghĩa — đá quý; 久 (cửu) biểu âm (âm jiǔ). Nghĩa gốc là loại đá quý màu đen hoặc sậm, kém hơn ngọc thạch. Ngoài ra, 玖 là chữ số 九 (chín) dùng trong văn bản tài chính/pháp lý để chống giả mạo. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đá đen giống ngọc; 9, chín (như: 九, dùng viết trong văn tự)", "Hạng Tần Suất (Jun Da)": "5031.0", "Tần Suất % (Jun Da)": "99.925485785", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 久", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王久", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "久", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "玖", "Unihan_Traditional (Chữ Phồn thể)": "玖", "Pinyin_Xie": "jiǔ", "Âm Hán Việt_Xie": "cửu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Số từ | 数词 | Danh từ | 名词 | Thường dùng làm số từ trong văn bản tài chính để viết hoa số chín nhằm tránh gian lận. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹇', '{"9000": "5032.0", "Chữ Trung Quốc": "蹇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 17 | nét | 寒 | hàn | biểu âm | lạnh | 足 | túc | biểu nghĩa | chân | 蹇 = 寒 (Hàn, biểu âm — viết tắt) + 足 (Túc, biểu nghĩa: chân); chữ hình thanh. Bộ 足 xác định nghĩa liên quan đến chân/đi lại; phần trên (từ 寒) cung cấp âm đọc jiǎn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiễng\": 足 (chân) + hàn (lạnh) — chân cóng lạnh bước đi khập khiễng, vận trình gian nan trắc trở. | Gương Hán-Việt | kiễng — chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 蹇 giúp đọc thơ văn cổ và Kinh Dịch: 蹇 là quẻ 39, tượng trưng cho gian nan cần kiên nhẫn vượt qua.", "Tự nguyên_Xie": "蹇 là chữ hình thanh: 足 (túc) biểu nghĩa — chân; phần trên viết tắt từ 寒 (hàn) biểu âm. Nghĩa gốc là chân đi khập khiễng, tàn tật. Từ đó mở rộng: khó khăn, trắc trở, số phận bất lợi. Trong Kinh Dịch, 蹇 là quẻ thứ 39, biểu tượng gian nan trên đường. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chân đi tập tễnh; láo lếu; khốn ách, gian khó", "Hạng Tần Suất (Jun Da)": "5032.0", "Tần Suất % (Jun Da)": "99.9255741553", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蹇", "Unihan_Traditional (Chữ Phồn thể)": "蹇", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "kiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả dáng đi không vững hoặc vận mệnh gặp nhiều gian truân. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逋', '{"9000": "5033.0", "Chữ Trung Quốc": "逋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 10 | nét | 逋 | bô | tượng hình | bỏ trốn, nợ dây dưa | 逋 không phân tích rõ bộ phận từ nguồn anchor; cấu tạo khả năng gồm 辶 (di chuyển, biểu nghĩa) và phần biểu âm. Chữ chủ yếu thấy trong thư tịch cổ với nghĩa trốn chạy. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bô\": 逋 (bū) — kẻ trốn nợ đi bộ (bô) trốn khỏi chủ nợ, cứ lẩn lút mãi không chịu về. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 逋 giúp đọc văn ngôn cổ: 逋逃 (bỏ trốn), 逋租 (nợ tô thuế), 逋客 (người ẩn cư xa lánh thế sự).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 逋 (bū) nghĩa là bỏ trốn, lẩn trốn; nợ dây dưa, không trả. Chữ tạo muộn với bộ 辶 (di chuyển) gợi ý sự di chuyển trốn tránh. Wiktionary không có tự nguyên chi tiết; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chạy trốn", "Hạng Tần Suất (Jun Da)": "5033.0", "Tần Suất % (Jun Da)": "99.9256625255", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 甫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶甫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逋", "Unihan_Traditional (Chữ Phồn thể)": "逋", "Pinyin_Xie": "bū", "Âm Hán Việt_Xie": "bô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn ngôn chỉ hành vi trốn tránh nghĩa vụ, nợ nần hoặc pháp luật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氅', '{"9000": "5034.0", "Chữ Trung Quốc": "氅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 毛 | Số nét | 16 | nét | 敞 | sưởng | biểu âm | rộng rãi, thông thoáng | 毛 | mao | biểu nghĩa | lông, lông vũ | 氅 = 敞 (Sưởng, biểu âm) + 毛 (Mao, biểu nghĩa: lông vũ); chữ hình thanh. Bộ 毛 xác định nghĩa liên quan đến lông chim; 敞 cung cấp âm đọc chǎng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sưởng\": 毛 (lông) + 敞 (rộng rãi) — chiếc áo choàng lông vũ rộng thênh thang, phất phới như cánh tiên. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 氅 giúp đọc văn học cổ điển: 鶴氅 (áo lông hạc của đạo sĩ), 大氅 (áo khoác lớn).", "Tự nguyên_Xie": "Tiểu triện | 氅 là chữ hình thanh: 毛 (mao) biểu nghĩa — lông vũ; 敞 (sưởng) biểu âm. Nghĩa gốc là áo choàng làm bằng lông chim, sau mở rộng sang áo khoác dài rộng. Dùng trong 大氅 (áo khoác lớn), 鶴氅 (áo choàng lông hạc của đạo sĩ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chắp lông cừu làm áo", "Hạng Tần Suất (Jun Da)": "5034.0", "Tần Suất % (Jun Da)": "99.9257508958", "GavinGrover_Once (Chiết tự trực tiếp)": "敞 + 毛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敞毛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "毛", "Unihan_Simplified (Chữ Giản thể)": "氅", "Unihan_Traditional (Chữ Phồn thể)": "氅", "Pinyin_Xie": "chǎng", "Âm Hán Việt_Xie": "sưởng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loại áo khoác ngoài không tay làm bằng lông chim của người xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粽', '{"9000": "5035.0", "Chữ Trung Quốc": "粽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 14 | nét | 米 | mễ | biểu nghĩa | gạo | 宗 | tông | biểu âm | tổ tông, dòng họ | 粽 = 米 (Mễ, biểu nghĩa: gạo) + 宗 (Tông, biểu âm); chữ hình thanh. Bộ 米 xác định nghĩa liên quan đến gạo/thực phẩm; 宗 cung cấp âm đọc zòng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tông\": 米 (gạo) + 宗 (tổ tông) — gạo gói lá dâng tổ tông trong lễ Đoan Ngọ, truyền thống ngàn năm. | Gương Hán-Việt | tông — 粽子 là bánh chưng/bánh ú trong văn hóa Trung Hoa | Mở khoá kiến thức | Biết 粽 giúp nhận ngay 粽子 (bánh chưng kiểu Trung Hoa) và hiểu văn hóa Tết Đoan Ngọ mùng 5 tháng 5.", "Tự nguyên_Xie": "粽 là chữ hình thanh: 米 (mễ) biểu nghĩa — gạo; 宗 (tông) biểu âm. Chữ chỉ bánh trưng/bánh chưng gói lá (粽子, zòngzi) — món ăn truyền thống dịp Tết Đoan Ngọ. Chữ tạo tương đối muộn; chưa thấy trong giáp cốt văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bánh bột nếp", "Hạng Tần Suất (Jun Da)": "5035.0", "Tần Suất % (Jun Da)": "99.925839266", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 宗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米宗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粽", "Unihan_Traditional (Chữ Phồn thể)": "粽", "Pinyin_Xie": "zòng", "Âm Hán Việt_Xie": "tống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau lượng từ chỉ các loại bánh làm từ gạo nếp gói lá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诂', '{"9000": "5036.0", "Chữ Trung Quốc": "诂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 7 | nét | 诂 | tượng hình | giải thích nghĩa chữ cổ | 诂 là giản thể của 詁; cấu tạo gồm 讠(ngôn, biểu nghĩa: lời nói/ngôn ngữ) + 古 (cổ, biểu âm: xưa cũ). Chữ hình thanh, nghĩa là giải thích từ ngữ cổ. Chưa thấy giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cổ\": 讠(lời) + 古 (xưa cũ) — lời giải thích nghĩa của những từ ngữ cổ xưa, môn học 訓詁 của các nhà Nho. | Gương Hán-Việt | cổ — 訓詁 (huấn cổ: giải thích kinh điển), 詁訓 — chuyên ngành ngôn ngữ học cổ Trung Hoa | Mở khoá kiến thức | Biết 诂 giúp nhận ra 訓詁學 (huấn cổ học) — môn chú giải kinh điển Hán học.", "Tự nguyên_Xie": "Đại triện | 诂 (gǔ) là giản thể của 詁: 讠(ngôn) biểu nghĩa — ngôn ngữ; 古 (cổ) biểu âm. Nghĩa chuyên môn: giải thích, chú giải từ ngữ cổ điển. Dùng trong thuật ngữ ngôn ngữ học cổ Trung Hoa: 訓詁 (huán gǔ) — môn chú giải kinh điển. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giải thích chuyện cũ", "Hạng Tần Suất (Jun Da)": "5036.0", "Tần Suất % (Jun Da)": "99.9259276363", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 古", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠古", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "古", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诂", "Unihan_Traditional (Chữ Phồn thể)": "詁", "Pinyin_Xie": "gǔ", "Âm Hán Việt_Xie": "hỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ giải nghĩa từ ngữ hoặc làm danh từ trong từ ghép chỉ việc chú giải sách cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('岢', '{"9000": "5037.0", "Chữ Trung Quốc": "岢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 8 | nét | 山 | sơn | biểu nghĩa | núi | 可 | khả | biểu âm | có thể | 岢 = 山 (Sơn, biểu nghĩa: núi) + 可 (Khả, biểu âm); chữ hình thanh. Bộ 山 xác định nghĩa liên quan đến địa hình núi; 可 cung cấp âm đọc kě.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khả\": 山 (núi) + 可 (có thể) — núi này có thể leo được không? Ngọn núi cao ngất ngưởng trả lời: khả năng khó! | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 岢 giúp nhận ra địa danh 岢嵐 (Kě Lán) ở tỉnh Sơn Tây, Trung Quốc.", "Tự nguyên_Xie": "岢 là chữ hình thanh: 山 (sơn) biểu nghĩa — núi; 可 (khả) biểu âm. Nghĩa cổ là núi cao, đồi cao. Chủ yếu thấy trong địa danh: 岢嵐 (Kě Lán — huyện ở Sơn Tây, Trung Quốc). Ít dùng ngoài ngữ cảnh địa lý. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên núi)", "Hạng Tần Suất (Jun Da)": "5037.0", "Tần Suất % (Jun Da)": "99.9260154898", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 可", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山可", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "可", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岢", "Unihan_Traditional (Chữ Phồn thể)": "岢", "Pinyin_Xie": "kě", "Âm Hán Việt_Xie": "khả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ địa danh hoặc tên núi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聒', '{"9000": "5038.0", "Chữ Trung Quốc": "聒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 12 | nét | 聒 | tượng hình | ồn ào, inh tai | 聒 không phân tích rõ bộ phận từ nguồn anchor; cấu tạo khả năng gồm 耳 (nhĩ: tai, biểu nghĩa) và phần biểu âm. Nghĩa là tiếng ồn ào làm nhức tai. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 聒 (guō) — tiếng ồn ào inh ỏi rót vào tai, như bầy chim hót loạn làm mất tập trung. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 聒 giúp đọc thành ngữ 聒噪 (ồn ào, cổ văn) và 强聒不舍 (cứ lải nhải không thôi).", "Tự nguyên_Xie": "Lục thư thông | 聒 (guō) nghĩa là ồn ào, inh tai, náo động. Cấu tạo có thể gồm 耳 (tai) và phần biểu âm. Chỉ duy nhất một lần thấy trong Kinh Thi. Từ điển Wiktionary không có tự nguyên chi tiết; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng kêu inh ỏi, om sòm", "Hạng Tần Suất (Jun Da)": "5038.0", "Tần Suất % (Jun Da)": "99.9261033432", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 舌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳舌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聒", "Unihan_Traditional (Chữ Phồn thể)": "聒", "Pinyin_Xie": "guā", "Âm Hán Việt_Xie": "quát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ miêu tả âm thanh ồn ào hoặc làm động từ gây nhiễu tai người nghe. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髁', '{"9000": "5039.0", "Chữ Trung Quốc": "髁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 17 | nét | 髁 | tượng hình | lồi cầu xương, mấu xương | 髁 không phân tích rõ bộ phận từ nguồn anchor; cấu tạo có bộ 骨 (cốt: xương, biểu nghĩa) và phần biểu âm. Chữ thuật ngữ y học. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 髁 (kē) — phần xương lồi ra như mấu đầu gối hay hông, thuật ngữ giải phẫu quan trọng trong y học. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 髁 giúp đọc văn bản y học Trung Quốc: 髁骨 (xương lồi cầu), 髖關節 (khớp háng).", "Tự nguyên_Xie": "Tiểu triện | 髁 (kē) là thuật ngữ giải phẫu chỉ lồi cầu xương (condyle) — phần lồi ở đầu xương. Cấu tạo có bộ 骨 (xương) biểu nghĩa. Chữ tạo muộn, chủ yếu dùng trong y học hiện đại; chưa có nguồn học thuật đầy đủ về tự nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xương đùi", "Hạng Tần Suất (Jun Da)": "5039.0", "Tần Suất % (Jun Da)": "99.9261911967", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 果", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨果", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "髁", "Unihan_Traditional (Chữ Phồn thể)": "髁", "Pinyin_Xie": "kē", "Âm Hán Việt_Xie": "khoả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò là danh từ chỉ bộ phận xương khớp trên cơ thể người và động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黍', '{"9000": "5040.0", "Chữ Trung Quốc": "黍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黍 | Số nét | 12 | nét | 黍 | tượng hình | cây kê, lúa mì nếp | 黍 là chữ tượng hình: mô tả cây kê (禾) với hạt hoặc nước (水) bên dưới. Theo Wiktionary, phần 水 có thể tượng trưng cho rượu nấu từ kê hoặc tính chất dính của kê; cấu tạo vẫn còn tranh luận. Là chữ độc thể cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 黍 (shǔ) — cây kê vàng óng, cây lương thực số một của nông dân Trung Hoa cổ đại, từng đo bằng từng hạt kê. | Gương Hán-Việt | thử — 黍離 (thử ly: thơ Kinh Thi nổi tiếng về nỗi nhớ quê hương đổ nát) | Mở khoá kiến thức | Biết 黍 giúp đọc thơ Kinh Thi (黍離) và hiểu văn hóa nông nghiệp cổ Trung Hoa.", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | 黍 là chữ tượng hình cổ đại: hình cây kê (禾) với nước/hạt bên dưới. Theo Wiktionary, phần 水 có thể biểu thị rượu nấu từ kê, hoặc đặc tính dính-nước của kê; cũng có thể là hạt mì. Kê (黍) là cây lương thực quan trọng nhất trong nông nghiệp cổ Trung Hoa, từng là đơn vị đo lường độ dài (chiều rộng hạt kê). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "778.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hòa (268) Nhập (038) Thủy (082)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hòa (số 268 - cây lúa) ở trên chữ Nhập (số 038 - vào) và bộ Thủy (số 082 - nước). Lúa nếp (Hòa) cần phải cấy nơi đồng trũng để luôn có nước (Thủy) chảy vào (Nhập) gốc thì mới tốt. Giải thích sự chuyển ý: Đây là chữ Hội ý. Thử là lúa nếp.", "Nghĩa Tiếng Việt_Xie": "lúa nếp", "Hạng Tần Suất (Jun Da)": "5040.0", "Tần Suất % (Jun Da)": "99.9262785334", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 氽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱禾氽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "氽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "黍", "Unihan_Traditional (Chữ Phồn thể)": "黍", "Pinyin_Xie": "shǔ", "Âm Hán Việt_Xie": "thử", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cây lương thực thuộc họ lúa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芾', '{"9000": "5041.0", "Chữ Trung Quốc": "芾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 芾 | nào | tượng hình | lá nhỏ, cây cỏ nhỏ | 芾 là chữ độc thể với bộ 艹 (thảo: cỏ) trên đầu; cấu tạo bên dưới liên quan đến nghĩa ''nhỏ bé''. Wiktionary chỉ có mục {{Han etym}} trống; chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nào\": 芾 — lá cây nhỏ non tơ xanh mướt, bộ 艹 trên đầu; tên nghệ danh của Mễ Phế (米芾) — thư pháp gia thiên tài đời Tống. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 芾 giúp nhận ra tên 米芾 (Mễ Phế/Mi Fu) — thư pháp gia và họa sĩ nổi tiếng nhất đời Tống.", "Tự nguyên_Xie": "芾 (fèi hoặc fú) là chữ ít dùng, chỉ lá nhỏ, cành lá thưa của cây. Bộ 艹 gợi liên quan đến thực vật. Wiktionary không có tự nguyên chi tiết; chưa có nguồn học thuật đầy đủ về tự nguyên. Cũng là họ tên người (nghệ danh của Mi Fu/Mi Fei — thư pháp gia đời Tống). | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "che đậy, che lấp", "Hạng Tần Suất (Jun Da)": "5041.0", "Tần Suất % (Jun Da)": "99.9263658701", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 巿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹巿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芾", "Unihan_Traditional (Chữ Phồn thể)": "芾", "Pinyin_Xie": "fèi", "Âm Hán Việt_Xie": "phất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ chỉ sự che lấp hoặc làm tính từ mô tả vẻ nhỏ bé. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淝', '{"9000": "5042.0", "Chữ Trung Quốc": "淝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 淝 | tượng hình | sông Phì Hà, địa danh lịch sử | 淝 không có anchor tự nguyên; cấu tạo có bộ 氵(thủy: nước, biểu nghĩa) và phần biểu âm. Chữ chủ yếu là địa danh tên sông. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 淝 (féi) — sông Phì nơi xảy ra trận đánh lịch sử 淝水之戰, quân Đông Tấn đại thắng trước Tiền Tần năm 383. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 淝 giúp nhận ra địa danh 淝水 (sông Phì) và trận 淝水之戰 — biến cố lịch sử quan trọng.", "Tự nguyên_Xie": "淝 (féi) chỉ sông Phì (淝水/淝河) ở tỉnh An Huy, Trung Quốc — địa điểm trận Phì Thủy (383 SCN), một trong những trận đánh lịch sử quan trọng nhất thời Ngụy Tấn Nam Bắc triều. Bộ 氵biểu nghĩa sông nước. Chưa có nguồn học thuật đầy đủ về tự nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Phì", "Hạng Tần Suất (Jun Da)": "5042.0", "Tần Suất % (Jun Da)": "99.9264532068", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 肥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵肥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "淝", "Unihan_Traditional (Chữ Phồn thể)": "淝", "Pinyin_Xie": "féi", "Âm Hán Việt_Xie": "phì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ riêng để chỉ tên sông, nổi tiếng nhất là sông Phì Thủy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲎', '{"9000": "5043.0", "Chữ Trung Quốc": "鲎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 13 | nét | 學 | học | biểu âm | học hành | 魚 | ngư | biểu nghĩa | cá, sinh vật biển | 鲎 = 學 (Học, biểu âm — rút gọn) + 魚 (Ngư, biểu nghĩa: sinh vật biển); chữ hình thanh. Chính thể là 鱟; bộ 魚 xác định nghĩa liên quan đến sinh vật biển; phần trên từ 學 cung cấp âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 鲎 (hòu) — con sam biển sống sót từ kỷ Jura, mang máu xanh quý giá — sinh vật hóa thạch sống của đại dương. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 鲎 giúp nhận ra 鲎试剂 (thuốc thử sam biển) — công cụ y tế quan trọng dùng máu sam để kiểm tra vi khuẩn.", "Tự nguyên_Xie": "鲎 là giản thể của 鱟 (hòu): 魚 (ngư) biểu nghĩa — sinh vật biển; phần trên từ 學 (học) rút gọn biểu âm. Chỉ con sam biển (horseshoe crab), một loài chân khớp cổ đại còn sống sót từ hàng triệu năm trước. Máu sam có màu xanh, dùng trong y học để kiểm tra nhiễm khuẩn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con sam biển", "Hạng Tần Suất (Jun Da)": "5043.0", "Tần Suất % (Jun Da)": "99.9265405435", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 鱼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鱼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鲎", "Unihan_Traditional (Chữ Phồn thể)": "鱟", "Pinyin_Xie": "hòu", "Âm Hán Việt_Xie": "hấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò làm danh từ chỉ loài động vật giáp xác sống ở biển. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞣', '{"9000": "5044.0", "Chữ Trung Quốc": "鞣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 18 | nét | 鞣 | tượng hình | thuộc da, chế biến da | 鞣 không phân tích rõ bộ phận từ nguồn anchor; cấu tạo có bộ 革 (cách: da thuộc, biểu nghĩa) và phần biểu âm. Chữ thuật ngữ ngành thuộc da. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 鞣 (róu) — quá trình làm mềm và bảo quản da sống thành da thuộc bền đẹp, ngành thủ công truyền thống. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 鞣 giúp đọc văn bản ngành da: 鞣制 (thuộc da), 鞣酸 (axit tanic), 鞣革 (da đã thuộc).", "Tự nguyên_Xie": "Tiểu triện | 鞣 (róu) là thuật ngữ chỉ quá trình thuộc da (tanning) — xử lý da sống thành da thuộc bằng axit tanic hoặc hóa chất. Bộ 革 (da) biểu nghĩa. 鞣酸 (tannic acid), 鞣料 (chất thuộc da). Chữ tạo muộn, dùng trong ngành da giày; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thuộc da; da mềm, da thuộc, da chín", "Hạng Tần Suất (Jun Da)": "5044.0", "Tần Suất % (Jun Da)": "99.9266278802", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 柔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革柔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "柔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞣", "Unihan_Traditional (Chữ Phồn thể)": "鞣", "Pinyin_Xie": "róu", "Âm Hán Việt_Xie": "nhu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ chỉ quá trình xử lý da hoặc làm tính từ chỉ da đã thuộc mềm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髋', '{"9000": "5045.0", "Chữ Trung Quốc": "髋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 19 | nét | 髋 | tượng hình | xương hông, khớp háng | 髋 là giản thể của 髖; cấu tạo có bộ 骨 (cốt: xương, biểu nghĩa) và phần biểu âm 寬 (khoan: rộng). Chữ thuật ngữ giải phẫu chỉ xương hông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 髋 (kuān) — xương rộng nhất cơ thể người, chính là xương hông đỡ toàn bộ trọng lượng. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 髋 giúp đọc hồ sơ y tế Trung Quốc: 髋骨 (xương chậu), 髋关节 (khớp háng), 髋骨肌 (cơ vùng hông).", "Tự nguyên_Xie": "Tiểu triện | 髋 (kuān) là giản thể của 髖: bộ 骨 (xương) biểu nghĩa; 寬 (khoan) biểu âm — âm kuān, cũng gợi nghĩa ''rộng'' (phần hông người rộng). Nghĩa: xương hông, vùng háng. Dùng trong 髋骨 (xương chậu), 髋关节 (khớp háng). Wiktionary không có tự nguyên chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xương chậu, xương hông", "Hạng Tần Suất (Jun Da)": "5045.0", "Tần Suất % (Jun Da)": "99.9267152168", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 宽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨宽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "髋", "Unihan_Traditional (Chữ Phồn thể)": "髖", "Pinyin_Xie": "kuān", "Âm Hán Việt_Xie": "khoan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận xương ở vùng hông của cơ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闳', '{"9000": "5046.0", "Chữ Trung Quốc": "闳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 7 | nét | 闳 | tượng hình | cửa ngõ rộng, to lớn | 闳 là giản thể của 閎; cấu tạo có bộ 门/門 (môn: cổng, cửa, biểu nghĩa) và phần biểu âm. Nghĩa là cổng lớn, rộng lớn. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 闳 (hóng) — cánh cổng rộng lớn của thành quách, biểu tượng sự bao la, rộng rãi và uy nghi. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 闳 giúp đọc văn ngôn cổ và nhận ra 閈閎 (cổng trong thành).", "Tự nguyên_Xie": "闳 (hóng) là giản thể của 閎: bộ 門 (môn/cổng) biểu nghĩa; phần còn lại biểu âm. Nghĩa: cổng thành, cửa lớn; mở rộng sang: rộng lớn, bao la. Dùng làm họ tên người (姓氏). Wiktionary không có tự nguyên chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cổng xóm", "Hạng Tần Suất (Jun Da)": "5046.0", "Tần Suất % (Jun Da)": "99.9268025535", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 厷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门厷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "闳", "Unihan_Traditional (Chữ Phồn thể)": "閎", "Pinyin_Xie": "hóng", "Âm Hán Việt_Xie": "hoành", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ cổng ngõ hoặc làm tính từ miêu tả sự to lớn, bao la. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('潆', '{"9000": "5047.0", "Chữ Trung Quốc": "潆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 14 | nét | 潆 | tượng hình | nước xoay vòng, dòng nước uốn lượn | 潆 không có anchor tự nguyên; cấu tạo có bộ 氵(thủy: nước, biểu nghĩa) và phần biểu âm. Nghĩa là dòng nước uốn lượn, xoay vòng. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 潆 (yíng) — dòng nước lượn vòng quanh chân núi, như dải lụa mềm mại uốn khúc trong thơ văn cổ. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 潆 giúp đọc thơ ca cổ miêu tả cảnh sông nước uốn lượn hữu tình.", "Tự nguyên_Xie": "潆 (yíng) nghĩa là dòng nước uốn lượn, xoay vòng quanh. Bộ 氵biểu nghĩa sông nước. Chữ tạo muộn, ít gặp; chưa có nguồn học thuật đầy đủ về tự nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước chảy quanh, nước xoáy", "Hạng Tần Suất (Jun Da)": "5047.0", "Tần Suất % (Jun Da)": "99.9268898902", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 萦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵萦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "萦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "潆", "Unihan_Traditional (Chữ Phồn thể)": "瀠", "Pinyin_Xie": "yíng", "Âm Hán Việt_Xie": "uynh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ miêu tả dòng nước chảy vòng quanh hoặc làm danh từ chỉ dòng nước xoáy. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('汨', '{"9000": "5048.0", "Chữ Trung Quốc": "汨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 氵 | thủy | biểu nghĩa | nước | 日 | nhật | biểu âm | mặt trời, ngày | 汨 = 氵(Thủy, biểu nghĩa: nước) + 日 (Nhật, biểu âm); chữ hình thanh. Bộ 氵xác định nghĩa liên quan đến sông nước; 日 cung cấp âm đọc mì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhặt\": 氵(nước) + 日 (nhật) — sông Mịch La phản chiếu ánh mặt trời, nơi Khuất Nguyên trầm mình — dòng sông gắn với thơ Sở Từ bất hủ. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 汨 giúp nhận ra 汨羅江 (sông Mịch La) — địa danh văn hóa gắn với Khuất Nguyên và nguồn gốc Tết Đoan Ngọ.", "Tự nguyên_Xie": "Đại triện | 汨 là chữ hình thanh: 氵(thủy) biểu nghĩa — nước, sông; 日 (nhật) biểu âm. Chủ yếu dùng trong địa danh: 汨羅 (sông Mịch La ở Hồ Nam — nơi nhà thơ Khuất Nguyên trầm mình năm 278 TCN). Âm đọc mì. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Mịch", "Hạng Tần Suất (Jun Da)": "5048.0", "Tần Suất % (Jun Da)": "99.9269767101", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 日", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "日", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "汨", "Unihan_Traditional (Chữ Phồn thể)": "汨", "Pinyin_Xie": "mì", "Âm Hán Việt_Xie": "mịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ tên sông Mịch La. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胍', '{"9000": "5049.0", "Chữ Trung Quốc": "胍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 9 | nét | ⺼ | nhục | biểu nghĩa | thịt, cơ thể | 瓜 | qua | biểu âm | dưa, bầu | 胍 = ⺼(Nhục/月, biểu nghĩa: thịt/cơ thể) + 瓜 (Qua, biểu âm); chữ hình thanh. Bộ ⺼(肉) xác định nghĩa liên quan đến hợp chất hữu cơ gốc sinh học; 瓜 cung cấp âm đọc guā.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 胍 (guā) — thuật ngữ hóa học gốc protein, 胍 là guanidin — hợp chất nền tảng của nhiều amino acid quan trọng trong cơ thể. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 胍 giúp đọc tài liệu sinh hóa Trung Quốc: 胍基 (nhóm guanidino), 二甲双胍 (metformin — thuốc tiểu đường).", "Tự nguyên_Xie": "胍 là chữ hình thanh: ⺼(nhục/肉) biểu nghĩa — liên quan đến hợp chất hữu cơ; 瓜 (qua) biểu âm. Chữ thuật ngữ hóa học-sinh hóa: guānidine (guanidine — guanidin), nền tảng của arginine và creatine. Chữ tạo hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gua-ni-đin (hoá học)", "Hạng Tần Suất (Jun Da)": "5049.0", "Tần Suất % (Jun Da)": "99.92706353", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 瓜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月瓜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "瓜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胍", "Unihan_Traditional (Chữ Phồn thể)": "胍", "Pinyin_Xie": "guā", "Âm Hán Việt_Xie": "cô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong thuật ngữ hóa học để chỉ hợp chất hữu cơ chứa nitơ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阏', '{"9000": "5050.0", "Chữ Trung Quốc": "阏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 11 | nét | 阏 | tượng hình | ngăn chặn, bịt kín | 阏 là giản thể của 閼; cấu tạo có bộ 门/門 (môn: cửa, biểu nghĩa) và phần biểu âm. Nghĩa là ngăn chặn, bịt lại, tắc nghẽn. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 阏 (yān/è) — như cánh cửa bị khóa chặt, ngăn mọi thứ không cho qua, hoặc danh hiệu 阏氏 của hoàng hậu Hung Nô. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 阏 giúp đọc sử ký về Hung Nô: 阏氏 (Yān Zhī — hoàng hậu Hung Nô, xuất hiện nhiều trong Sử Ký).", "Tự nguyên_Xie": "Tiểu triện | 阏 (yān/è) là giản thể của 閼: bộ 門 (cửa) và phần biểu âm. Nghĩa: ngăn chặn, bịt kín, tắc nghẽn. Hai đọc: yān (dùng trong 阏氏 — danh hiệu hoàng hậu Hung Nô) và è (ngăn chặn). Wiktionary ghi rfdef, chưa có tự nguyên đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên riêng)", "Hạng Tần Suất (Jun Da)": "5050.0", "Tần Suất % (Jun Da)": "99.9271498331", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 於", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门於", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "於", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阏", "Unihan_Traditional (Chữ Phồn thể)": "閼", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "át, yên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường dùng làm động từ với nghĩa ngăn chặn hoặc làm danh từ trong tên riêng cổ đại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钤', '{"9000": "5051.0", "Chữ Trung Quốc": "钤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 钤 | tượng hình | con dấu chính thức, ấn triện | 钤 là giản thể của 鈐; cấu tạo có bộ 钅/金 (kim: kim loại, biểu nghĩa) và phần biểu âm. Nghĩa là con dấu kim loại, ấn triện, chìa khóa. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 钤 (qián) — con dấu kim loại đóng lên văn thư, biểu tượng quyền lực và tính xác thực của giấy tờ chính thống. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 钤 giúp đọc văn bản thư pháp và sưu tầm đồ cổ Trung Quốc: 钤印 (đóng dấu), 钤记 (con dấu ghi chép).", "Tự nguyên_Xie": "Tiểu triện | 钤 (qián) là giản thể của 鈐: bộ 金 (kim loại) biểu nghĩa; phần còn lại biểu âm. Nghĩa: con dấu chính thức (ấn triện), dụng cụ sao chè, chìa khóa/then cài, mưu lược. Mở rộng sang nghĩa trừu tượng: chìa khóa giải vấn đề. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái khoá", "Hạng Tần Suất (Jun Da)": "5051.0", "Tần Suất % (Jun Da)": "99.9272361363", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 今", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅今", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "今", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钤", "Unihan_Traditional (Chữ Phồn thể)": "鈐", "Pinyin_Xie": "qián", "Âm Hán Việt_Xie": "kiềm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ cái khóa hoặc con dấu, và làm động từ khi chỉ việc đóng dấu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹜', '{"9000": "5052.0", "Chữ Trung Quốc": "鹜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 14 | nét | 鹜 | tượng hình | vịt trời, chim nước ham ăn | 鹜 là giản thể của 鶩; bộ 鸟 biểu nghĩa (chim), phần còn lại biểu âm. Nghĩa là vịt trời. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 鹜 (wù) — con vịt trời cô đơn bay ngang ráng chiều, bất tử trong thơ Vương Bột 落霞与孤鹜齐飞. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 鹜 giúp đọc thơ cổ: ''落霞与孤鹜齐飞'' — câu thơ nổi tiếng nhất của Vương Bột trong 滕王阁序.", "Tự nguyên_Xie": "Tiểu triện | 鹜 (wù) là giản thể của 鶩: bộ 鳥 (điểu/chim) biểu nghĩa; phần còn lại biểu âm. Nghĩa gốc: vịt trời, vịt hoang. Mở rộng: ham mê, chạy đôn chạy đáo (驰骛). Nổi tiếng trong câu thơ của Vương Bột: ''落霞与孤鹜齐飞'' (ráng chiều cùng cánh vịt lẻ cùng bay). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con vịt trời", "Hạng Tần Suất (Jun Da)": "5052.0", "Tần Suất % (Jun Da)": "99.9273224394", "GavinGrover_Once (Chiết tự trực tiếp)": "敄 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敄鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹜", "Unihan_Traditional (Chữ Phồn thể)": "鶩", "Pinyin_Xie": "wù", "Âm Hán Việt_Xie": "vụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài vịt trời, thường xuất hiện trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬈', '{"9000": "5053.0", "Chữ Trung Quốc": "鬈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 18 | nét | 鬈 | tượng hình | tóc xoăn, tóc uốn | 鬈 không phân tích rõ bộ phận từ nguồn anchor; cấu tạo có bộ 髟 (tiêu: tóc, biểu nghĩa) và phần biểu âm 卷 (quyển: cuộn). Nghĩa là tóc xoăn tự nhiên. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 鬈 (quán) — mái tóc xoăn tự nhiên uốn lượn như sóng nước, đặc điểm ngoại hình được nhắc đến trong văn chương. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 鬈 giúp đọc văn miêu tả ngoại hình: 鬈发 (tóc xoăn), 鬈曲 (xoăn lượn).", "Tự nguyên_Xie": "Tiểu triện | 鬈 (quán) nghĩa là tóc xoăn tự nhiên. Bộ 髟 (tóc) biểu nghĩa; phần biểu âm gợi ý sự cuộn xoăn. Wiktionary ghi rfdef — chưa có định nghĩa đầy đủ; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tóc tốt, tóc đẹp", "Hạng Tần Suất (Jun Da)": "5053.0", "Tần Suất % (Jun Da)": "99.9274087425", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 卷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟卷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "鬈", "Unihan_Traditional (Chữ Phồn thể)": "鬈", "Pinyin_Xie": "quán", "Âm Hán Việt_Xie": "quyền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ dùng để miêu tả mái tóc xoăn tự nhiên hoặc tóc đẹp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铵', '{"9000": "5054.0", "Chữ Trung Quốc": "铵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 铵 | tượng hình | amoni, ion NH4+ | 铵 là giản thể của 銨; cấu tạo có bộ 钅/金 (kim: kim loại, biểu nghĩa) và phần biểu âm 安 (an). Chữ thuật ngữ hóa học hiện đại chỉ ion amoni (NH4+).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 铵 (ǎn) — ion amoni NH4+ trong hóa học, bộ 金 gợi tính chất muối kim loại, phần 安 cho âm đọc. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 铵 giúp đọc tài liệu hóa học Trung Quốc: 氯化铵 (amoni clorua), 硫酸铵 (amoni sulfat), 碳酸铵 (amoni carbonat).", "Tự nguyên_Xie": "铵 (ǎn) là giản thể của 銨: bộ 金 (kim loại) biểu nghĩa — liên quan đến muối kim loại; 安 (an) biểu âm. Chữ thuật ngữ hóa học hiện đại, tạo để phiên âm ''ammonium'' (NH4+). Dùng trong 氯化铵, 硫酸铵, 碳酸铵. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "amoni (hoá học)", "Hạng Tần Suất (Jun Da)": "5054.0", "Tần Suất % (Jun Da)": "99.9274950456", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 安", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅安", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "安", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铵", "Unihan_Traditional (Chữ Phồn thể)": "銨", "Pinyin_Xie": "ǎn", "Âm Hán Việt_Xie": "an", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong hóa học để chỉ nhóm hoặc muối amoni. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戬', '{"9000": "5055.0", "Chữ Trung Quốc": "戬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戈 | Số nét | 14 | nét | 戬 | tượng hình | tiêu diệt, phúc lành | 戬 là biến thể của 戩; cấu tạo có bộ 戈 (qua: vũ khí, biểu nghĩa) và phần biểu âm. Nghĩa gốc là tiêu diệt; mở rộng sang phúc lành (nghĩa nghịch lý trong văn ngôn). Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 戬 (jiǎn) — tên của Nhị Lang Thần 楊戩 trong Phong Thần Diễn Nghĩa, vừa mang nghĩa ''tiêu diệt yêu ma'' vừa mang lại phúc lành. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 戬 giúp nhận ra tên 楊戩 (Dương Tiễn/Nhị Lang Thần) trong thần thoại và tiểu thuyết Trung Quốc.", "Tự nguyên_Xie": "Đại triện | 戬 (jiǎn) là biến thể của 戩: bộ 戈 (qua/vũ khí) biểu nghĩa — hành động chiến đấu; phần còn lại biểu âm. Nghĩa: (1) tiêu diệt, tận diệt; (2) phúc lành, điều tốt lành. Hai nghĩa tưởng mâu thuẫn nhưng trong cổ văn đều gặp. Nổi tiếng trong tên nhân vật 楊戩 (Dương Tiễn — Nhị Lang Thần). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rất, cực kỳ", "Hạng Tần Suất (Jun Da)": "5055.0", "Tần Suất % (Jun Da)": "99.9275813487", "GavinGrover_Once (Chiết tự trực tiếp)": "晋 + 戈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰晋戈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "晋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "戈", "Unihan_Simplified (Chữ Giản thể)": "戬", "Unihan_Traditional (Chữ Phồn thể)": "戩", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "tiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Phó từ | 副词 | Danh từ | 名词 | Chữ này dùng làm động từ với nghĩa tiêu diệt hoặc làm phó từ bổ nghĩa cho tính từ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('崮', '{"9000": "5056.0", "Chữ Trung Quốc": "崮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 11 | nét | 崮 | tượng hình | núi đỉnh bằng, địa hình đặc trưng Sơn Đông | 崮 không có anchor tự nguyên; cấu tạo có bộ 山 (sơn: núi, biểu nghĩa) và phần biểu âm 固 (cố: vững chắc). Chữ địa lý chỉ dạng địa hình đặc trưng. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 崮 (gù) — ngọn núi đỉnh bằng như mặt bàn, vách đứng như tường thành — địa hình độc đáo chỉ có ở Sơn Đông, Trung Quốc. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 崮 giúp nhận ra hàng chục địa danh ở Sơn Đông như 孟良崮, 抱犊崮 — nổi tiếng trong lịch sử chiến tranh và du lịch.", "Tự nguyên_Xie": "崮 (gù) không có tự nguyên từ Wiktionary. Chữ địa lý chuyên biệt: chỉ dạng núi đỉnh bằng phẳng, vách dựng đứng — đặc trưng của địa hình tỉnh Sơn Đông. Bộ 山 biểu nghĩa; 固 có thể biểu âm và biểu ý ''vững chắc''. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "núi vách đứng mà ngọn trên hơi bằng", "Hạng Tần Suất (Jun Da)": "5056.0", "Tần Suất % (Jun Da)": "99.9277534382", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 固", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山固", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "固", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "崮", "Unihan_Traditional (Chữ Phồn thể)": "崮", "Pinyin_Xie": "gù", "Âm Hán Việt_Xie": "cố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một dạng địa hình núi đặc trưng ở tỉnh Sơn Đông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('枰', '{"9000": "5057.0", "Chữ Trung Quốc": "枰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 枰 | tượng hình | bàn cờ, bàn phẳng bằng gỗ | 枰 không phân tích rõ bộ phận từ nguồn anchor; cấu tạo có bộ 木 (mộc: gỗ, biểu nghĩa) và phần biểu âm 平 (bình: bằng phẳng). Chữ chỉ bàn cờ hoặc bề mặt phẳng bằng gỗ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 枰 (píng) — mặt gỗ bằng phẳng của bàn cờ, nơi các quân cờ đấu trí — 棋枰 là đấu trường của trí tuệ. | Gương Hán-Việt | bình — 棋枰 (kỳ bình: bàn cờ), liên quan đến 平 (bình: bằng phẳng) | Mở khoá kiến thức | Biết 枰 giúp đọc văn chương cờ: 棋枰 (bàn cờ), 对枰 (đối cờ), 枰局 (thế cờ).", "Tự nguyên_Xie": "Tiểu triện | 枰 (píng) gồm 木 (mộc/gỗ) biểu nghĩa và 平 (bình) biểu âm. Nghĩa: bàn phẳng, mặt phẳng bằng gỗ. Mở rộng sang nghĩa bàn cờ (棋枰). Âm đọc píng gần với 平 (bình: bằng) — phù hợp với hình dáng bàn cờ phẳng. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đánh cờ, đánh bạc", "Hạng Tần Suất (Jun Da)": "5057.0", "Tần Suất % (Jun Da)": "99.9278392245", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 平", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木平", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "平", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "枰", "Unihan_Traditional (Chữ Phồn thể)": "枰", "Pinyin_Xie": "píng", "Âm Hán Việt_Xie": "bình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bàn cờ, thường dùng trong văn chương cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('樯', '{"9000": "5058.0", "Chữ Trung Quốc": "樯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 15 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 嗇 | sắc | biểu âm | bủn xỉn | 樯 = 木 (Mộc, biểu nghĩa: gỗ/cây) + 嗇 (Sắc, biểu âm); chữ hình thanh. Chính thể là 檣; bộ 木 xác định nghĩa liên quan đến vật bằng gỗ; 嗇 cung cấp âm đọc qiáng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 樯 (qiáng) — cột buồm thẳng đứng trên thuyền, gỗ mộc vươn lên trời xanh giữa sóng gió, biểu tượng của hành trình và phiêu lãng. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 樯 giúp đọc thơ văn cổ miêu tả thuyền bè: 帆樯 (buồm cột), 危樯 (cột buồm cao), 風樯陣馬.", "Tự nguyên_Xie": "樯 là giản thể của 檣: 木 (mộc) biểu nghĩa — gỗ; 嗇 (sắc) biểu âm. Nghĩa: cột buồm, cột chèo của thuyền. Dùng trong thơ văn cổ: 風檣陣馬 (buồm gió trận mã). Chữ thường xuất hiện trong văn tả cảnh sông nước. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái cột buồm", "Hạng Tần Suất (Jun Da)": "5058.0", "Tần Suất % (Jun Da)": "99.9279250108", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 啬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木啬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "啬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "樯", "Unihan_Traditional (Chữ Phồn thể)": "檣", "Pinyin_Xie": "qiáng", "Âm Hán Việt_Xie": "tường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cột buồm, thường đi kèm với buồm trong thơ ca. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脍', '{"9000": "5059.0", "Chữ Trung Quốc": "脍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 10 | nét | 脍 | tượng hình | gỏi cá sống, thịt thái mỏng sống | 脍 là giản thể của 膾; cấu tạo có bộ ⺼/肉 (nhục: thịt, biểu nghĩa) và phần biểu âm 會 (hội). Chữ chỉ món ăn gỏi cá/thịt sống truyền thống Trung Hoa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 脍 (kuài) — miếng cá sống thái mỏng như giấy, ngon đến mức ''膾炙人口'' — được mọi người truyền tụng khen ngợi. | Gương Hán-Việt | khoái — 膾炙人口 (khoái chích nhân khẩu: được truyền tụng rộng rãi) | Mở khoá kiến thức | Biết 脍 mở khóa thành ngữ 脍炙人口 (khoái chích nhân khẩu) — mô tả tác phẩm/câu nói được mọi người yêu thích.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 脍 (kuài) là giản thể của 膾: bộ 肉 (nhục/thịt) biểu nghĩa; 會 (hội) biểu âm. Nghĩa: gỏi — thịt hoặc cá sống thái mỏng, món ăn truyền thống của Trung Hoa và Nhật Bản cổ đại. 膾炙人口 (khoái chích nhân khẩu) là thành ngữ nổi tiếng nhất. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gỏi cá", "Hạng Tần Suất (Jun Da)": "5059.0", "Tần Suất % (Jun Da)": "99.9280107972", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 会", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月会", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "会", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脍", "Unihan_Traditional (Chữ Phồn thể)": "膾", "Pinyin_Xie": "kuài", "Âm Hán Việt_Xie": "khoái, quái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ món gỏi cá hoặc động từ thái nhỏ thịt cá trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畲', '{"9000": "5060.0", "Chữ Trung Quốc": "畲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 田 | Số nét | 12 | nét | 畲 | tượng hình | đất rẫy, đất mới khai phá | 畲 là biến thể của 畬; không có phân tích bộ phận rõ từ nguồn anchor. Cấu tạo có thể gồm 余 và bộ 田 (điền: ruộng). Chữ chỉ đất rẫy mới đốt phát, cũng là tên tộc người Xa (畲族).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 畲 (shē) — mảnh đất rẫy đốt phá rừng làm nương, cũng là tên tộc người Xa — cộng đồng dân tộc thiểu số miền Nam Trung Quốc. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt | Mở khoá kiến thức | Biết 畲 giúp nhận ra 畲族 (She Zu — tộc người Xa) và hiểu về canh tác nương rẫy trong văn hóa Trung Hoa.", "Tự nguyên_Xie": "畲 là biến thể của 畬 (shē): nghĩa gốc là đất rẫy — đất rừng đốt phát để canh tác. Wiktionary ghi là biến thể, không có tự nguyên riêng. Nổi tiếng là tên của 畲族 (She Zu/Tộc người Xa) — dân tộc thiểu số ở Phúc Kiến, Chiết Giang. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dân tộc Xa (dân tộc thiểu số ở Trung Quốc)", "Hạng Tần Suất (Jun Da)": "5060.0", "Tần Suất % (Jun Da)": "99.9280965835", "GavinGrover_Once (Chiết tự trực tiếp)": "佘 + 田", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱佘田", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "佘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "田", "Unihan_Simplified (Chữ Giản thể)": "畲", "Unihan_Traditional (Chữ Phồn thể)": "畬", "Pinyin_Xie": "shē", "Âm Hán Việt_Xie": "xa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ một dân tộc thiểu số ở Trung Quốc hoặc phương thức canh tác đốt rẫy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衾', '{"9000": "5061.0", "Chữ Trung Quốc": "衾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 衾 | khâm | tượng hình | áo chăn, tấm chăn phủ thi thể | 衾 là chữ tượng hình độc lập (bộ thủ 衣). Cấu trúc nội bộ kết hợp 今 (kim) với 衣 (y – quần áo), nhưng nguồn Wiktionary không cung cấp phân tích ls rõ ràng; coi là chữ tạo muộn hơn trong hệ thống bộ 衣.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khâm\": hình ảnh tấm 衣 (áo) được cuộn lại thành chăn phủ — khâm liệm người mất. | Gương Hán-Việt | khâm liệm (phủ xác bằng vải) | Mở khoá kiến thức | Biết 衾 (khâm) mở khoá từ 衾裯 (chăn gối), 衾枕 (khâm chẩm – chăn gối), ngữ cảnh tang lễ và thơ cổ điển.", "Tự nguyên_Xie": "Tiểu triện | 衾 thuộc bộ 衣 (y – quần áo). Ý nghĩa gốc là tấm chăn, chăn phủ, đặc biệt dùng để phủ thi thể trong tang lễ. Wiktionary chỉ ghi nhận {{Han etym}} mà không phân tích cụ thể thành phần; có hình tiểu triện cho thấy đây là chữ cổ. Trong cổ thi Trung Hoa, 衾裯 (qīndāo) chỉ chăn chiếu. Chưa có phân tích ls từ nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo ngủ; cái chăn; đồ khâm liệm", "Hạng Tần Suất (Jun Da)": "5061.0", "Tần Suất % (Jun Da)": "99.9281823698", "GavinGrover_Once (Chiết tự trực tiếp)": "今 + 衣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱今衣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "今", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衣", "Unihan_Simplified (Chữ Giản thể)": "衾", "Unihan_Traditional (Chữ Phồn thể)": "衾", "Pinyin_Xie": "qīn", "Âm Hán Việt_Xie": "khâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau động từ hoặc kết hợp trong các từ ghép chỉ chăn màn, tang lễ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹼', '{"9000": "5062.0", "Chữ Trung Quốc": "蹼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 19 | nét | 足 | tú | biểu nghĩa | chân, bàn chân | 菐 | biểu âm | thành phần biểu âm (đọc pú) | 蹼 = 足 (Tú, biểu nghĩa: chân) + 菐 (biểu âm, đọc pú); chữ hình thanh. Bộ 足 cho biết liên quan đến chân/bàn chân; 菐 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến; 蹼 (pú): tưởng tượng bàn 足 (chân) vịt có màng da nối các ngón — đó là 蹼 (màng chân). | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 蹼 mở khoá 蹼足 (bàn chân có màng), 有蹼动物 (động vật có màng chân) — từ vựng sinh học và động vật học.", "Tự nguyên_Xie": "蹼 là chữ hình thanh: 足 (chân) biểu nghĩa + 菐 biểu âm. Nghĩa gốc là màng da giữa các ngón chân/tay của động vật thủy sinh như vịt, ếch. Wiktionary xác nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1175.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Túc (236) Bộc (1174)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Túc (số 236 - bàn chân) ở bên trái chữ Bộc (số 1174 - rậm rạp/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Bộc chỉ âm, bộ Túc chỉ ý. Bộc là cái màng dính liền giữa các ngón chân của loài chim nước như con vịt, con ngan.", "Nghĩa Tiếng Việt_Xie": "màng chân (của vịt, ngỗng, ...)", "Hạng Tần Suất (Jun Da)": "5062.0", "Tần Suất % (Jun Da)": "99.9282681562", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 菐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊菐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "菐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹼", "Unihan_Traditional (Chữ Phồn thể)": "蹼", "Pinyin_Xie": "pǔ", "Âm Hán Việt_Xie": "phốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc làm định ngữ bổ nghĩa cho danh từ chỉ bộ phận cơ thể động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('劬', '{"9000": "5063.0", "Chữ Trung Quốc": "劬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 力 | Số nét | 7 | nét | 劬 | cù | tượng hình | lao nhọc, vất vả | 劬 là chữ thuộc bộ 力 (lực – sức mạnh, lao động). Không có phân tích ls từ nguồn Wiktionary. Cấu trúc kết hợp 力 với phần còn lại, nhưng nguồn không rõ ràng. Coi là chữ tạo muộn trong nhóm 力.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cù\": bộ 力 (sức lực) gợi sự nhọc nhằn — 劬 (cù) là cực nhọc, như người lao 力 (lực) đến kiệt sức. | Gương Hán-Việt | cần cù (chăm chỉ, không quản khó nhọc) | Mở khoá kiến thức | Biết 劬 (cù) mở khoá 勤劬 (cần cù, lao khổ) — từ văn học cổ và thơ chữ Hán về sự vất vả của cha mẹ.", "Tự nguyên_Xie": "Tiểu triện | 劬 thuộc bộ 力 (lực). Nghĩa gốc là lao nhọc, làm việc vất vả, thường dùng trong 勤劬 (cần cù, cực nhọc). Wiktionary không cung cấp phân tích thành phần cụ thể. Chưa có nguồn học thuật về ls. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "436.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cú (26) Lực (233)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Cú (số 112 - câu cú) và chữ Lực (số 19 - sức mạnh) . Phải gập người thành hình câu cú (Cú), dốc hết sức lực (Lực) ra làm việc gọi là nhọc nhằn, cù lao (công lao cha mẹ). Giải thích sự chuyển ý: Chữ Cú (câu cú) chỉ âm, chữ Lực (sức mạnh) chỉ ý. Bỏ nhiều công sức (Lực) làm lụng vất vả nhọc nhằn (Cù). *(Biến âm Hán Việt: Cú -> Cù)*", "Nghĩa Tiếng Việt_Xie": "nhọc nhằn", "Hạng Tần Suất (Jun Da)": "5063.0", "Tần Suất % (Jun Da)": "99.928439212", "GavinGrover_Once (Chiết tự trực tiếp)": "句 + 力", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰句力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "力", "Unihan_Simplified (Chữ Giản thể)": "劬", "Unihan_Traditional (Chữ Phồn thể)": "劬", "Pinyin_Xie": "qú", "Âm Hán Việt_Xie": "cù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc đi kèm với từ khác để chỉ sự lao động cực khổ của cha mẹ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咭', '{"9000": "5064.0", "Chữ Trung Quốc": "咭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 咭 | gắt | tượng hình | âm thanh the thé, tiếng kêu nhỏ | 咭 không có phân tích cấu trúc từ Wiktionary. Thuộc bộ 口 (khẩu – miệng), chỉ các âm thanh hoặc hành động miệng. Chữ tạo muộn, chưa có nguồn học thuật về thành phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"gắt\": bộ 口 (miệng) + âm gắt — 咭 gợi giọng nói gắt gỏng, the thé qua miệng. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 咭 mở khoá 咭片 (danh thiếp – từ Quảng Đông) và các từ mô phỏng âm thanh trong văn học hiện đại.", "Tự nguyên_Xie": "咭 thuộc bộ 口 (miệng). Không có phân tích glyphOrigin từ Wiktionary. Trong tiếng Quảng Đông, 咭片 (gāt pin) là danh thiếp (từ phonetic borrowing từ \"card\"). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng xì xào", "Hạng Tần Suất (Jun Da)": "5064.0", "Tần Suất % (Jun Da)": "99.9285244816", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 吉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口吉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咭", "Unihan_Traditional (Chữ Phồn thể)": "咭", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "kê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Danh từ | 名词 | Thường dùng làm từ tượng thanh mô tả âm thanh hoặc làm danh từ trong từ phiên âm ngoại lai. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('囫', '{"9000": "5065.0", "Chữ Trung Quốc": "囫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 囗 | Số nét | 7 | nét | 囫 | hốt | tượng hình | nguyên vẹn, trọn vẹn | 囫 thuộc bộ 囗 (vi – vòng bao). Không có phân tích ls từ Wiktionary. Cấu trúc gồm bộ 囗 bao ngoài với 勿 bên trong, nhưng nguồn không cung cấp giải thích chính thức. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hốt\": bộ 囗 (vòng bao) bao trọn — 囫 là nguyên vẹn, trọn vẹn, như thành ngữ 囫囵吞枣 nuốt cả quả táo không nhai. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 囫 mở khoá thành ngữ 囫囵吞枣 (học vẹt, không tiêu hóa kiến thức) — thành ngữ phổ biến trong giáo dục.", "Tự nguyên_Xie": "囫 thuộc bộ 囗 (vòng bao, bao quanh). Không có glyphOrigin từ Wiktionary. Chủ yếu dùng trong thành ngữ 囫囵吞枣 (hốt lôn thôn táo – nuốt trọn quả táo, tức học vẹt không hiểu). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hốt luân 囫圇,囫囵)", "Hạng Tần Suất (Jun Da)": "5065.0", "Tần Suất % (Jun Da)": "99.9286097511", "GavinGrover_Once (Chiết tự trực tiếp)": "囗 + 勿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Bao quanh toàn bộ)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴囗勿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "囗", "Unihan_Simplified (Chữ Giản thể)": "囫", "Unihan_Traditional (Chữ Phồn thể)": "囫", "Pinyin_Xie": "hú", "Âm Hán Việt_Xie": "hốt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Hầu như chỉ xuất hiện trong từ ghép liên bông để làm tính từ bổ nghĩa cho hành động nuốt chửng hoặc tiếp thu máy móc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('洱', '{"9000": "5066.0", "Chữ Trung Quốc": "洱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 水 | thủy | biểu nghĩa | nước | 耳 | nhĩ | biểu âm | thành phần biểu âm (đọc ěr) | 洱 = 氵/水 (Thủy, biểu nghĩa: nước) + 耳 (Nhĩ, biểu âm); chữ hình thanh. Bộ 氵 cho biết liên quan đến nước; 耳 chỉ âm đọc ěr.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến; 洱 (ěr): 氵 (nước) + 耳 (tai/nhĩ) — hồ Nhĩ Hải (洱海) ở Vân Nam có hình dáng như vành tai khi nhìn từ trên cao. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 洱 mở khoá 洱海 (Nhĩ Hải – hồ nổi tiếng ở Đại Lý, Vân Nam) và 大理洱海 — địa danh du lịch Trung Quốc.", "Tự nguyên_Xie": "洱 là chữ hình thanh: 水 (nước) biểu nghĩa + 耳 biểu âm. Chủ yếu dùng làm tên riêng cho sông Nhĩ (洱河) và hồ Nhĩ (洱海) ở tỉnh Vân Nam, Trung Quốc. Wiktionary xác nhận cấu trúc psc này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "415.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (306) Nhĩ (186)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thủy (số 76) và chữ Nhĩ (số 186 - cái tai) . Dòng nước (Thủy) chảy cong uốn lượn có hình dáng như cái tai (Nhĩ) (chỉ hồ Nhĩ Hải hoặc trà Phổ Nhĩ). Giải thích sự chuyển ý: Chữ Nhĩ (cái tai) chỉ âm, chữ Thủy (nước) chỉ ý. Tên một hồ nước (Thủy) lớn ở tỉnh Vân Nam, Trung Quốc (Nhĩ).", "Nghĩa Tiếng Việt_Xie": "sông Nhị", "Hạng Tần Suất (Jun Da)": "5066.0", "Tần Suất % (Jun Da)": "99.9286950207", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 耳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵耳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "洱", "Unihan_Traditional (Chữ Phồn thể)": "洱", "Pinyin_Xie": "ěr", "Âm Hán Việt_Xie": "nhĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng trong địa danh hoặc tên loại trà nổi tiếng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('刎', '{"9000": "5067.0", "Chữ Trung Quốc": "刎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 6 | nét | 勿 | vật | biểu âm | thành phần biểu âm (đọc wù/wěn) | 刀 | đao | biểu nghĩa | dao, vũ khí sắc bén | 刎 = 勿 (Vật, biểu âm) + 刀/刂 (Đao, biểu nghĩa: dao); chữ hình thanh. Wiktionary ghi: 勿 vốn chỉ chính từ này (刎), sau mới thêm 刀 để phân biệt. Bộ 刀 gợi hành động chặt đứt bằng dao.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vẫn\": 刀 (đao) + 勿 — 刎 (vẫn) là hành động dùng đao cắt cổ tự vẫn, như trong 刎颈之交 (bạn bè kết nghĩa sinh tử). | Gương Hán-Việt | tự vẫn (tự cắt cổ — từ Hán-Việt dùng trong văn học lịch sử) | Mở khoá kiến thức | Biết 刎 (vẫn) mở khoá 刎颈 (vẫn cảnh – cắt cổ), 刎颈之交 (bạn thân thiết sẵn sàng chết cùng nhau) — thành ngữ lịch sử nổi tiếng.", "Tự nguyên_Xie": "Tiểu triện | 刎 là chữ hình thanh: 刀 (dao) biểu nghĩa + 勿 biểu âm. Theo Wiktionary: ban đầu 勿 chính là dùng để viết từ này; chữ 刀 được thêm vào sau để làm rõ nghĩa \"cắt cổ\". Nghĩa chính là tự cắt cổ (刎颈), thường gặp trong văn học lịch sử Trung Hoa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "437.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Vật (25) Đao (324)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Vật (số 20 - chớ, đừng) và chữ Đao (số 18 - con dao) . Chớ đừng (Vật) dại dột dùng dao (Đao) tự cắt cổ mình, hành động đó gọi là tự vẫn. Giải thích sự chuyển ý: Chữ Vật (chớ, đừng) chỉ âm, chữ Đao (con dao) chỉ ý. Dùng dao (Đao) tự cứa cổ mình gọi là tự vẫn (Vẫn). *(Biến âm Hán Việt: Vật -> Vẫn)*", "Nghĩa Tiếng Việt_Xie": "đâm vào cổ", "Hạng Tần Suất (Jun Da)": "5067.0", "Tần Suất % (Jun Da)": "99.9287797735", "GavinGrover_Once (Chiết tự trực tiếp)": "勿 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰勿刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "刎", "Unihan_Traditional (Chữ Phồn thể)": "刎", "Pinyin_Xie": "wěn", "Âm Hán Việt_Xie": "vẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ hoặc kết hợp thành từ ghép chỉ hành động tự sát. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芏', '{"9000": "5068.0", "Chữ Trung Quốc": "芏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 6 | nét | 艸 | tháu | biểu nghĩa | cỏ, thực vật | 土 | thổ | biểu âm | đất (biểu âm dù không hoàn toàn khớp âm hiện đại) | 芏 = 艹/艸 (Tháu, biểu nghĩa: cỏ) + 土 (Thổ, biểu âm); chữ hình thanh. Bộ 艹 cho biết đây là loài thực vật; 土 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến; 芏 (dù): 艹 (cỏ) mọc trên 土 (đất) — đây là cỏ cói mặn mọc trên bùn đất vùng duyên hải. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 芏 mở khoá 芏草 (cỏ cói mặn), 茳芏 — từ vựng thực vật học và thủ công mỹ nghệ truyền thống.", "Tự nguyên_Xie": "芏 là chữ hình thanh: 艸 (cỏ) biểu nghĩa + 土 biểu âm. Wiktionary xác nhận cấu trúc psc này. Nghĩa là loài cỏ cói mặn (Cyperus malaccensis), sống ở vùng đất ngập nước ven biển, dùng để đan chiếu và làm hàng thủ công. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ mọc trên bờ biển", "Hạng Tần Suất (Jun Da)": "5068.0", "Tần Suất % (Jun Da)": "99.9288645262", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "土", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芏", "Unihan_Traditional (Chữ Phồn thể)": "芏", "Pinyin_Xie": "dù", "Âm Hán Việt_Xie": "đỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một loại cỏ cói mọc ở vùng ngập mặn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('琊', '{"9000": "5069.0", "Chữ Trung Quốc": "琊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 10 | nét | 玉 | ngọc | biểu nghĩa | ngọc, đá quý | 邪 | tà | biểu âm | thành phần biểu âm (đọc yá/yé) | 琊 = 𤣩/玉 (Ngọc, biểu nghĩa: ngọc quý) + 邪 (Tà, biểu âm); chữ hình thanh. Bộ 玉 gợi sự quý phái; 邪 chỉ âm đọc. Chữ chủ yếu dùng trong địa danh 瑯琊.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nha\": 玉 (ngọc) + 邪 (tà) — 琊 chỉ xuất hiện trong 瑯琊, địa danh cổ mang vẻ đẹp ngọc ngà huyền bí. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 琊 mở khoá 瑯琊 (Lãng Nha) — địa danh lịch sử và tên bộ phim truyền hình nổi tiếng 琅琊榜 (Langya Bang).", "Tự nguyên_Xie": "琊 là chữ hình thanh: 玉 (ngọc) biểu nghĩa + 邪 biểu âm. Wiktionary xác nhận cấu trúc psc. Chữ hầu như chỉ dùng trong địa danh 瑯琊 (Lãng Nha) — tên vùng đất lịch sử ở Sơn Đông, Trung Quốc, nổi tiếng qua phim truyền hình 琅琊榜. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vâng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 邪", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王邪", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "邪", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "琊", "Unihan_Traditional (Chữ Phồn thể)": "琊", "Pinyin_Xie": "yá", "Âm Hán Việt_Xie": "da", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng trong các địa danh cổ hoặc tên núi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碚', '{"9000": "5070.0", "Chữ Trung Quốc": "碚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 13 | nét | 碚 | bội | tượng hình | địa danh, đá | 碚 thuộc bộ 石 (thạch – đá). Không có phân tích ls từ Wiktionary. Chủ yếu dùng làm địa danh (Bắc Bội, Trùng Khánh). Chữ tạo muộn, chưa có nguồn học thuật về cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bội\": bộ 石 (đá) — 碚 gắn với địa danh 北碚 (Bắc Bội) bên sông ở Trùng Khánh, vùng đất đá núi. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 碚 mở khoá 北碚 (Bắc Bội) — quận ngoại ô Trùng Khánh, từng là trung tâm văn hóa thời kháng Nhật.", "Tự nguyên_Xie": "碚 thuộc bộ 石 (đá). Không có glyphOrigin từ Wiktionary. Chủ yếu biết đến qua địa danh 北碚 (Bắc Bội), một quận của thành phố Trùng Khánh, Trung Quốc. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên một vùng đất ở tỉnh Tứ Xuyên của Trung Quốc", "Hạng Tần Suất (Jun Da)": "5070.0", "Tần Suất % (Jun Da)": "99.9290340317", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 咅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石咅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碚", "Unihan_Traditional (Chữ Phồn thể)": "碚", "Pinyin_Xie": "bèi", "Âm Hán Việt_Xie": "bội", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng trong địa danh Bắc Bồi ở Trùng Khánh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳕', '{"9000": "5071.0", "Chữ Trung Quốc": "鳕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 19 | nét | 鳕 | tuyết | tượng hình | cá tuyết (cod) | 鳕 là dạng giản thể của 鱈. Thuộc bộ 鱼 (ngư – cá). Wiktionary ghi: 鳕 = 鱈 với 魚 giản thể thành 鱼. Không có phân tích cấu trúc riêng vì đây là chữ giản hóa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuyết\": bộ 鱼 (cá) + tuyết (雪) — 鳕 là cá tuyết, loài cá của vùng biển lạnh phủ tuyết phương Bắc. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 鳕 mở khoá 鳕鱼 (cá tuyết/cod), 鳕鱼片 (phi lê cá tuyết) — từ vựng ẩm thực và thủy sản.", "Tự nguyên_Xie": "鳕 là dạng giản thể của 鱈. Bộ 鱼 (cá) biểu nghĩa. Nghĩa là cá tuyết (cod fish), loài cá nước lạnh quan trọng trong ẩm thực. Wiktionary: {{Han simp|鱈|f=魚|t=鱼}}. Chữ tạo muộn trong hệ thống giản thể. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá tuyết, cá moruy", "Hạng Tần Suất (Jun Da)": "5071.0", "Tần Suất % (Jun Da)": "99.9291187845", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 雪", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼雪", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雪", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳕", "Unihan_Traditional (Chữ Phồn thể)": "鱈", "Pinyin_Xie": "xuě", "Âm Hán Việt_Xie": "tuyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ số lượng hoặc làm định ngữ bổ nghĩa cho danh từ khác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谪', '{"9000": "5072.0", "Chữ Trung Quốc": "谪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 13 | nét | 谪 | trích | tượng hình | giáng chức, đày xa | 谪 thuộc bộ 讠/言 (ngôn – lời nói). Không có phân tích cụ thể ls từ Wiktionary, nhưng bộ 讠 gợi hành động phán xét, lên án bằng lời; phần còn lại có thể biểu âm. Chữ có lịch sử lâu đời trong văn học cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trích\": bộ 讠 (lời/ngôn) phán xét — 谪 (trích) là bị trích trách, bị đày ải, như các thi nhân đời Đường bị 贬谪 về chốn rừng sâu. | Gương Hán-Việt | trích giáng (giáng chức và đày xa), lưu đày | Mở khoá kiến thức | Biết 谪 (trích) mở khoá 贬谪 (biếm trích – giáng chức đày đi), 谪居 (sống nơi lưu đày) — ngữ cảnh văn học lịch sử Đường Tống.", "Tự nguyên_Xie": "Tiểu triện | 谪 thuộc bộ 讠/言 (lời nói, phán xét). Nghĩa gốc là khiển trách, sau mở rộng sang giáng chức/đày ải quan lại ra vùng xa — hình phạt phổ biến trong lịch sử Trung Hoa. Wiktionary ghi: to censure, to demote, to banish. Không có phân tích thành phần chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khiển trách, phạt; lỗi lầm; biến khí", "Hạng Tần Suất (Jun Da)": "5072.0", "Tần Suất % (Jun Da)": "99.9292030205", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 啇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠啇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "啇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谪", "Unihan_Traditional (Chữ Phồn thể)": "謫", "Pinyin_Xie": "zhé", "Âm Hán Việt_Xie": "trích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ đứng trước tân ngữ chỉ người hoặc nơi bị đày đi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芎', '{"9000": "5073.0", "Chữ Trung Quốc": "芎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 6 | nét | 芎 | khung | tượng hình | cây xuyên khung (dược liệu) | 芎 thuộc bộ 艹 (tháu – cỏ, thực vật). Không có phân tích ls từ Wiktionary. Chủ yếu dùng trong tên dược liệu 川芎 (xuyên khung). Chữ tạo muộn trong hệ thống thực vật học.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khung\": bộ 艹 (cỏ) — 芎 (khung) là cây xuyên khung, vị thuốc Đông y quý, mọc ở vùng núi cao như \"khung\" trời đất. | Gương Hán-Việt | xuyên khung (vị thuốc Đông y hoạt huyết) | Mở khoá kiến thức | Biết 芎 (khung) mở khoá 川芎 (xuyên khung – Ligusticum chuanxiong), 芎藭 — từ vựng Đông y và thảo dược học.", "Tự nguyên_Xie": "Tiểu triện | 芎 thuộc bộ 艹 (thực vật). Không có glyphOrigin chi tiết từ Wiktionary. Chủ yếu dùng trong 川芎 (Ligusticum chuanxiong) — một vị thuốc Đông y quan trọng, có tác dụng hoạt huyết. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khung cùng 芎藭)", "Hạng Tần Suất (Jun Da)": "5073.0", "Tần Suất % (Jun Da)": "99.9292872565", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 弓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹弓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芎", "Unihan_Traditional (Chữ Phồn thể)": "芎", "Pinyin_Xie": "qiōng", "Âm Hán Việt_Xie": "khung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ khác tạo thành danh từ ghép chỉ vị thuốc đông y. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恂', '{"9000": "5074.0", "Chữ Trung Quốc": "恂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 9 | nét | 恂 | tuân | tượng hình | thành thật, kính sợ | 恂 thuộc bộ 忄/心 (tâm – tâm hồn, cảm xúc). Không có phân tích ls từ Wiktionary. Phần còn lại (旬/xún) có thể là biểu âm. Nghĩa liên quan đến trạng thái nội tâm: thành thật, kính sợ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuân\": bộ 忄 (tâm) — 恂 (tuân) là lòng thành thật, tuân thủ từ trong tâm, không giả tạo. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 恂 (tuân) mở khoá 恂恂 (thành thật khiêm tốn), 恂然 — từ văn học cổ điển và Luận Ngữ.", "Tự nguyên_Xie": "Tiểu triện | 恂 thuộc bộ 忄 (tâm). Không có phân tích cấu trúc chi tiết từ Wiktionary. Nghĩa bao gồm: thành thật, tin tưởng; thông suốt, không cản trở; và kính sợ. Dùng chủ yếu trong văn học cổ điển. Chưa có nguồn học thuật về ls. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tin theo", "Hạng Tần Suất (Jun Da)": "5074.0", "Tần Suất % (Jun Da)": "99.9293714924", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 旬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄旬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "恂", "Unihan_Traditional (Chữ Phồn thể)": "恂", "Pinyin_Xie": "xún", "Âm Hán Việt_Xie": "tuân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho trạng thái tâm lý hoặc hành vi của con người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('槿', '{"9000": "5075.0", "Chữ Trung Quốc": "槿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 15 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 堇 | biểu âm | thành phần biểu âm (đọc jǐn) | 槿 = 木 (Mộc, biểu nghĩa: cây) + 堇 (biểu âm, đọc jǐn); chữ hình thanh. Bộ 木 cho biết đây là loài cây; 堇 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến; 槿 (jǐn): 木 (cây) + 堇 — cây dâm bụt (木槿), hoa nở sáng tàn chiều, biểu tượng vô thường trong thơ Đường. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 槿 mở khoá 木槿 (mộc cẩn – dâm bụt/Hibiscus), 槿花 (hoa dâm bụt), 朝槿 — từ vựng thực vật và thơ cổ.", "Tự nguyên_Xie": "槿 là chữ hình thanh: 木 (cây) biểu nghĩa + 堇 biểu âm. Wiktionary xác nhận cấu trúc psc. Nghĩa là cây dâm bụt (Hibiscus syriacus) — loài hoa một ngày nở rồi tàn, biểu tượng của sự phù du trong thơ ca Đông Á. Quốc hoa Hàn Quốc (무궁화). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây dâm bụt; dâm bụt; hoa dâm bụt", "Hạng Tần Suất (Jun Da)": "5075.0", "Tần Suất % (Jun Da)": "99.9294557284", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 堇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木堇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "堇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "槿", "Unihan_Traditional (Chữ Phồn thể)": "槿", "Pinyin_Xie": "jǐn", "Âm Hán Việt_Xie": "cẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với các từ khác để chỉ cây cối hoặc làm danh từ riêng chỉ người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲢', '{"9000": "5076.0", "Chữ Trung Quốc": "鲢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 15 | nét | 魚 | ngư | biểu nghĩa | cá | 連 | liên | biểu âm | thành phần biểu âm (đọc lián) | 鲢 = 鱼/魚 (Ngư, biểu nghĩa: cá) + 連 (Liên, biểu âm); chữ hình thanh. Bộ 鱼 cho biết đây là loài cá; 連 chỉ âm đọc lián.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến; 鲢 (lián): 鱼 (cá) + 連 (liên – nối tiếp) — cá mè bơi thành đàn liên tiếp, chen chúc nhau. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 鲢 mở khoá 鲢鱼 (cá mè trắng), 白鲢 (bạch liên – cá mè trắng), 花鲢 (cá mè hoa) — từ vựng nuôi trồng thủy sản.", "Tự nguyên_Xie": "Tiểu triện | 鲢 là chữ hình thanh: 魚 (cá) biểu nghĩa + 連 biểu âm. Wiktionary xác nhận cấu trúc psc. Nghĩa là cá mè trắng (silver carp, Hypophthalmichthys molitrix) — loài cá nước ngọt phổ biến ở châu Á, được nuôi rộng rãi. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá liên, cá mè", "Hạng Tần Suất (Jun Da)": "5076.0", "Tần Suất % (Jun Da)": "99.9295399644", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 连", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼连", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "连", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲢", "Unihan_Traditional (Chữ Phồn thể)": "鰱", "Pinyin_Xie": "lián", "Âm Hán Việt_Xie": "liên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp với các từ chỉ loài cá khác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲧', '{"9000": "5077.0", "Chữ Trung Quốc": "鲧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 15 | nét | 鲧 | cổn | tượng hình | Cổn — nhân vật thần thoại, cha của Vũ | 鲧 thuộc bộ 鱼 (ngư – cá). Không có phân tích cấu trúc chi tiết từ Wiktionary ngoài {{Han etym}}. Là tên riêng của nhân vật trong thần thoại Trung Hoa — Cổn, cha của Đại Vũ trị thủy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cổn\": bộ 鱼 (cá) — 鲧 (Cổn) là nhân vật thần thoại cha của Đại Vũ, được vẽ gắn với loài cá/thủy thần, trị thủy thất bại. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 鲧 (Cổn) mở khoá câu chuyện trị thủy Trung Hoa: 鲧禹治水 (Cổn Vũ trị thủy) — thần thoại lũ lụt nổi tiếng.", "Tự nguyên_Xie": "Tiểu triện | 鲧 thuộc bộ 鱼 (cá). Wiktionary chỉ ghi {{Han etym}} không có phân tích. Đây là tên riêng: Cổn (Gǔn) — người được vua Nghiêu giao trị thủy nhưng thất bại sau chín năm, bị giết; con trai là Đại Vũ tiếp tục và thành công. Chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá lớn, cá to; (tên riêng)", "Hạng Tần Suất (Jun Da)": "5077.0", "Tần Suất % (Jun Da)": "99.9296242004", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 系", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼系", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "系", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲧", "Unihan_Traditional (Chữ Phồn thể)": "鮌", "Pinyin_Xie": "gǔn", "Âm Hán Việt_Xie": "cổn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng chỉ nhân vật lịch sử truyền thuyết Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘧', '{"9000": "5078.0", "Chữ Trung Quốc": "嘧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 14 | nét | 嘧 | mật | tượng hình | pyrimidine (thuật ngữ hóa học) | 嘧 thuộc bộ 口 (khẩu – miệng). Không có phân tích cấu trúc từ Wiktionary. Đây là chữ tạo trong hệ thống thuật ngữ hóa học hiện đại Trung Quốc để phiên dịch tên hóa hợp chất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mật\": bộ 口 (miệng) — 嘧 là chữ hóa học mới, gặp trong 嘧啶 (pyrimidine), thành phần nền tảng của DNA. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 嘧 mở khoá 嘧啶 (pyrimidine), 胸腺嘧啶 (thymine), 胞嘧啶 (cytosine) — từ vựng sinh hóa và di truyền học.", "Tự nguyên_Xie": "嘧 thuộc bộ 口. Không có glyphOrigin từ Wiktionary. Đây là chữ tạo hiện đại, dùng trong thuật ngữ hóa học: 嘧啶 (mật đình/pyrimidine) — hợp chất dị vòng cơ bản trong DNA/RNA. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mật đính 嘧啶)", "Hạng Tần Suất (Jun Da)": "5078.0", "Tần Suất % (Jun Da)": "99.9297084363", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 密", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口密", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "密", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嘧", "Unihan_Traditional (Chữ Phồn thể)": "嘧", "Pinyin_Xie": "mì", "Âm Hán Việt_Xie": "mật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường chỉ dùng làm danh từ ghép trong thuật ngữ hóa học sinh học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绀', '{"9000": "5079.0", "Chữ Trung Quốc": "绀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 8 | nét | 糸 | biểu nghĩa | tơ, sợi, vải | 甘 | cam | biểu âm | thành phần biểu âm (đọc gān/gàn) | 绀 = 糸/纟 (biểu nghĩa: tơ lụa, vải) + 甘 (Cam, biểu âm); chữ hình thanh. Bộ 糸 cho biết liên quan đến vải/màu sắc; 甘 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến; 绀 (gàn): 糸 (tơ) + 甘 (cam) — màu vải xanh tím đậm như màu áo cà sa tăng ni, huyền bí và trang nghiêm. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 绀 mở khoá 绀色 (màu xanh tím đậm), 绀青 (xanh tím) — từ vựng màu sắc và trang phục trong văn học cổ điển.", "Tự nguyên_Xie": "Tiểu triện | 绀 là chữ hình thanh: 糸 (tơ) biểu nghĩa + 甘 biểu âm. Wiktionary xác nhận cấu trúc psc. Nghĩa là màu xanh tím đậm (deep bluish-purple) — màu áo của tu sĩ Phật giáo và tăng ni trong văn học Đông Á. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xanh biếc", "Hạng Tần Suất (Jun Da)": "5079.0", "Tần Suất % (Jun Da)": "99.9297926723", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 甘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟甘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绀", "Unihan_Traditional (Chữ Phồn thể)": "紺", "Pinyin_Xie": "gàn", "Âm Hán Việt_Xie": "cám", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ đứng trước danh từ để chỉ màu sắc của sự vật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郦', '{"9000": "5080.0", "Chữ Trung Quốc": "郦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 9 | nét | 郦 | lịch | tượng hình | địa danh cổ, họ người | 郦 thuộc bộ 阝/邑 (ấp – làng, thành ấp). Không có phân tích cấu trúc chi tiết từ Wiktionary ngoài {{Han etym}}. Là tên địa danh cổ và họ người.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lịch\": bộ 阝 (ấp/thành) — 郦 (Lịch) là địa danh/họ người nổi tiếng, như Lịch Thực Kỳ mưu sĩ tài ba thời Hán. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 郦 (lịch) mở khoá 郦食其 (Lịch Thực Kỳ – mưu sĩ của Lưu Bang), 郦道元 (tác giả Thủy Kinh Chú) — nhân vật lịch sử Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 郦 thuộc bộ 阝 (ấp – làng/thành). Wiktionary chỉ ghi {{Han etym}}. Vốn là địa danh nước Lê (郦邑) thời cổ đại Trung Hoa. Nổi tiếng qua Lịch Thực (郦食其) — mưu sĩ thời Hán Sở tranh hùng. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Ly (tên cũ của nước Lỗ thời xưa, nay thuộc một phần của tỉnh Hà Nam của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "5080.0", "Tần Suất % (Jun Da)": "99.9298763915", "GavinGrover_Once (Chiết tự trực tiếp)": "丽 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰丽阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郦", "Unihan_Traditional (Chữ Phồn thể)": "酈", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng chỉ họ người hoặc địa danh cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('噱', '{"9000": "5081.0", "Chữ Trung Quốc": "噱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 16 | nét | 噱 | giác | tượng hình | cười to, hài hước | 噱 thuộc bộ 口 (khẩu – miệng). Không có phân tích cấu trúc từ Wiktionary. Bộ 口 gợi âm thanh cười. Chủ yếu dùng trong các từ như 噱头 (trò hề, chiêu trò thu hút).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giác\": bộ 口 (miệng) mở to — 噱 là tiếng cười vang, như 噱头 chiêu trò khiến ai cũng há 口 mà cười. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 噱 mở khoá 噱头 (chiêu trò hài), 发噱 (gây buồn cười), 耍噱头 (làm trò) — từ vựng hài hước và nghệ thuật biểu diễn.", "Tự nguyên_Xie": "Tiểu triện | 噱 thuộc bộ 口. Wiktionary chỉ ghi {{Han etym}} và rfdef (chưa định nghĩa chính thức). Dùng trong 噱头 (jué tóu) — chiêu trò, thủ thuật hài hước thu hút khán giả trong tiếng Thượng Hải; 发噱 — gây buồn cười. Chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cười to", "Hạng Tần Suất (Jun Da)": "5081.0", "Tần Suất % (Jun Da)": "99.9299601107", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 豦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口豦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "噱", "Unihan_Traditional (Chữ Phồn thể)": "噱", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "cược", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động cười lớn hoặc danh từ chỉ chiêu trò gây cười. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('浠', '{"9000": "5082.0", "Chữ Trung Quốc": "浠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 氵 | biểu nghĩa | nước, sông | 希 | hy | biểu âm | thành phần biểu âm (đọc xī) | 浠 = 氵/水 (biểu nghĩa: nước/sông) + 希 (Hy, biểu âm); chữ hình thanh. Bộ 氵 cho biết liên quan đến sông nước; 希 chỉ âm đọc xī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hơ\": 氵 (nước) + 希 (hy vọng) — 浠 là dòng sông mang hy vọng, như sông Tích Thủy chảy qua Hồ Bắc. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 浠 mở khoá 浠水 (huyện Tích Thủy), 浠水河 — địa danh tỉnh Hồ Bắc, Trung Quốc.", "Tự nguyên_Xie": "浠 là chữ hình thanh: 水 (nước) biểu nghĩa + 希 biểu âm. Wiktionary xác nhận cấu trúc psc. Chủ yếu dùng trong địa danh 浠水 (huyện Tích Thủy, tỉnh Hồ Bắc) và tên sông 浠水河. Không có nghĩa độc lập phổ biến ngoài tên địa lý. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hy thuỷ 浠水)", "Hạng Tần Suất (Jun Da)": "5082.0", "Tần Suất % (Jun Da)": "99.9300438299", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 希", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵希", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "希", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "浠", "Unihan_Traditional (Chữ Phồn thể)": "浠", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng chỉ tên sông hoặc tên địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('潸', '{"9000": "5083.0", "Chữ Trung Quốc": "潸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 15 | nét | 潸 | san | tượng hình | nước mắt chảy dài, khóc lặng lẽ | 潸 thuộc bộ 氵 (thủy – nước). Không có phân tích cấu trúc chi tiết từ Wiktionary. Nghĩa chỉ trạng thái chảy nước mắt, đặc biệt khóc âm thầm không thành tiếng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"san\": bộ 氵 (nước) — 潸 (san) là dòng nước mắt chảy thầm lặng, như 潸然泪下 khi lòng dâng tràn xúc động. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 潸 mở khoá 潸然泪下 (nước mắt tự nhiên tuôn rơi), 潸然 (đầm đìa lệ) — thành ngữ và từ thơ văn cổ.", "Tự nguyên_Xie": "Tiểu triện | 潸 thuộc bộ 氵 (nước). Wiktionary không cung cấp phân tích ls chi tiết. Nghĩa là chảy nước mắt, khóc âm thầm. Thường gặp trong 潸然泪下 (san nhiên lệ hạ — nước mắt tự nhiên rơi xuống) và 潸然 (san nhiên — đầm đìa nước mắt). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chảy nước mắt", "Hạng Tần Suất (Jun Da)": "5083.0", "Tần Suất % (Jun Da)": "99.9301275491", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "潸", "Unihan_Traditional (Chữ Phồn thể)": "潸", "Pinyin_Xie": "shān", "Âm Hán Việt_Xie": "san", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả trạng thái nước mắt rơi lã chã trong văn viết. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跏', '{"9000": "5084.0", "Chữ Trung Quốc": "跏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 12 | nét | 足 | tú | biểu nghĩa | chân, bàn chân | 加 | gia | biểu âm | thành phần biểu âm (đọc jiā) | 跏 = 足 (Tú, biểu nghĩa: chân) + 加 (Gia, biểu âm); chữ hình thanh. Bộ 足 cho biết liên quan đến chân/tư thế ngồi; 加 chỉ âm đọc jiā.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến; 跏 (jiā): 足 (chân) + 加 (thêm/chồng lên) — 跏趺 là tư thế ngồi xếp bàng, hai chân chồng lên nhau khi thiền định. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 跏 mở khoá 跏趺 (già phu – ngồi xếp bằng thiền định), 结跏趺坐 (ngồi kiết già) — từ vựng Phật giáo thiền định.", "Tự nguyên_Xie": "跏 là chữ hình thanh: 足 (chân) biểu nghĩa + 加 biểu âm. Wiktionary xác nhận cấu trúc psc. Nghĩa là tư thế ngồi xếp bằng (跏趺 – jiā fū), là tư thế thiền định của Phật giáo. Cũng có nghĩa cổ là đi với bàn chân quay vào trong. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngồi bắt chéo chân", "Hạng Tần Suất (Jun Da)": "5084.0", "Tần Suất % (Jun Da)": "99.9302112683", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 加", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊加", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "加", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跏", "Unihan_Traditional (Chữ Phồn thể)": "跏", "Pinyin_Xie": "jiā", "Âm Hán Việt_Xie": "già", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường kết hợp thành từ ghép già phu để chỉ tư thế ngồi thiền. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲶', '{"9000": "5085.0", "Chữ Trung Quốc": "鲶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 鲶 | niêm | tượng hình | cá trê, catfish | 鲶 thuộc bộ 鱼 (ngư – cá). Wiktionary ghi: chữ vay mượn từ tiếng Nhật 鯰 (namazu), là biến thể của 鮎. Không có cấu trúc ls độc lập; là chữ tạo muộn được dùng rộng rãi trong văn viết Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"niêm\": bộ 鱼 (cá) — 鲶 (niêm) là cá trê, loài cá trơn nhầy nhụa, dính (niêm) như từ niêm dính. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 鲶 mở khoá 鲶鱼 (cá trê), hiệu ứng cá trê (鲶鱼效应 – catfish effect, cạnh tranh kích thích phát triển) — từ vựng kinh tế và ẩm thực.", "Tự nguyên_Xie": "鲶 là chữ vay mượn từ tiếng Nhật 鯰 (namazu). Là biến thể thông dụng của 鮎 (cá trê) trong tiếng Trung hiện đại. Theo Wiktionary: {{obor|zh|ja|鯰|tr=namazu}}. Nghĩa là cá trê/catfish — loài cá da trơn nước ngọt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá măng, cá ngát, cá nheo, cá niêm", "Hạng Tần Suất (Jun Da)": "5085.0", "Tần Suất % (Jun Da)": "99.9302949875", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 念", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼念", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "念", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲶", "Unihan_Traditional (Chữ Phồn thể)": "鯰", "Pinyin_Xie": "nián", "Âm Hán Việt_Xie": "niêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ các loài cá thuộc họ cá nheo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矍', '{"9000": "5086.0", "Chữ Trung Quốc": "矍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 20 | nét | 矍 | quắc | tượng hình | nhìn xung quanh kinh ngạc, đôi mắt tinh anh | 矍 là chữ hình thanh và hội ý kết hợp (psc+ic). Wiktionary: {{liushu|psc}} và {{liushu|ic}}: 瞿 (bắt đầu, cảnh giác) + 又 (bàn tay bắt chim 隹). Cấu trúc phức tạp, gợi hình ảnh mắt sáng nhìn nhanh, tay chộp chim.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quắc\": đôi mắt 瞿 (cảnh giác) với bàn tay 又 chộp chim — 矍 (quắc) là ánh mắt quắc lên tinh anh, như cụ già 矍铄 vẫn nhanh nhẹn mắt sáng. | Gương Hán-Việt | quắc thước (già mà còn minh mẫn, khỏe mạnh) | Mở khoá kiến thức | Biết 矍 (quắc) mở khoá 矍铄 (quắc thước – tinh anh minh mẫn tuổi già) — thành ngữ khen ngợi người cao tuổi còn sức khỏe tốt.", "Tự nguyên_Xie": "Tiểu triện | 矍 là chữ vừa hình thanh vừa hội ý: 瞿 (cảnh giác, bắt đầu) biểu âm + 又 (bàn tay bắt chim 隹). Wiktionary giải thích: hình ảnh đôi mắt tinh anh (瞿) cùng bàn tay (又) chộp chim (隹). Nghĩa là nhìn xung quanh với vẻ kinh ngạc, mắt sáng tinh anh — thường dùng trong 矍铄 (quắc thước – già mà còn minh mẫn, mạnh khỏe). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1577.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cù (1576) Hựu (029)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Cù (số 1576 - mở to mắt/ 瞿) ở trên chữ Hựu (số 029 - cái tay/ 又). Con chim bị bàn tay người túm lấy thì hai mắt mở to tròn sợ hãi. Giải thích sự chuyển ý: Đây là chữ Hội ý. Quắc là liếc mắt nhìn quanh, nhìn nhớn nhác sợ hãi (quắc nhiên).", "Nghĩa Tiếng Việt_Xie": "sợ, nhớn nhác", "Hạng Tần Suất (Jun Da)": "5086.0", "Tần Suất % (Jun Da)": "99.9303781899", "GavinGrover_Once (Chiết tự trực tiếp)": "瞿 + 又", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱瞿又", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "瞿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "又", "Unihan_Simplified (Chữ Giản thể)": "矍", "Unihan_Traditional (Chữ Phồn thể)": "矍", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ trong từ ghép quắc thước để tả người già khỏe mạnh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苌', '{"9000": "5087.0", "Chữ Trung Quốc": "苌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 艹 | biểu nghĩa | cỏ, thực vật | 長 | trường | biểu âm | thành phần biểu âm (đọc cháng) | 苌 = 艹 (biểu nghĩa: cỏ) + 長 (Trường, biểu âm); chữ hình thanh. Bộ 艹 cho biết đây là thực vật; 長 chỉ âm đọc cháng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến; 苌 (cháng): 艹 (cỏ) + 長 (trường/dài) — cây 苌楚 có thân dài leo bám, như loài dây leo trong rừng xưa. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 苌 mở khoá 萇楚 (tên cây dây leo cổ điển), 萇弘化碧 (thành ngữ về oan khuất) — từ văn học và lịch sử Chu.", "Tự nguyên_Xie": "Tiểu triện | 苌 là chữ hình thanh: 艸 (cỏ) biểu nghĩa + 長 biểu âm. Wiktionary xác nhận cấu trúc psc. Chủ yếu dùng trong 萇楚 (tên cổ của cây dương đào — kiwi wild ancestor) và là họ người (苌弘 – Trường Hoằng, nhân vật thời Chu). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: trường sở 萇楚,萇楚)", "Hạng Tần Suất (Jun Da)": "5087.0", "Tần Suất % (Jun Da)": "99.9304613923", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 长", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹长", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "长", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苌", "Unihan_Traditional (Chữ Phồn thể)": "萇", "Pinyin_Xie": "cháng", "Âm Hán Việt_Xie": "trường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong tên thực vật cổ hoặc họ người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('抻', '{"9000": "5088.0", "Chữ Trung Quốc": "抻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 手 | thủ | biểu nghĩa | tay, bàn tay | 申 | thân | biểu âm | thành phần biểu âm (đọc chēn/shēn) | 抻 = 扌/手 (Thủ, biểu nghĩa: tay) + 申 (Thân, biểu âm); chữ hình thanh. Bộ 扌 cho biết liên quan đến hành động tay; 申 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến; 抻 (chēn): 扌 (tay) + 申 (giãn dài) — 抻 là hành động kéo dài mì bằng tay, như nghệ nhân làm 抻面 (mì kéo tay). | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 抻 mở khoá 抻面 (mì kéo tay/hand-pulled noodles), 抻拉 (kéo giãn) — từ vựng ẩm thực và nghề thủ công.", "Tự nguyên_Xie": "抻 là chữ hình thanh: 手 (tay) biểu nghĩa + 申 biểu âm. Wiktionary xác nhận cấu trúc psc. Nghĩa là kéo dài, kéo giãn ra bằng tay — thường dùng trong nghề làm mì sợi (抻面 – mì kéo tay/hand-pulled noodles). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kéo; lôi", "Hạng Tần Suất (Jun Da)": "5088.0", "Tần Suất % (Jun Da)": "99.9305445947", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 申", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌申", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "申", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "抻", "Unihan_Traditional (Chữ Phồn thể)": "抻", "Pinyin_Xie": "chēn", "Âm Hán Việt_Xie": "thân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động kéo giãn hoặc căng một vật gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('琰', '{"9000": "5089.0", "Chữ Trung Quốc": "琰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 12 | nét | 𤣩 | biểu nghĩa | ngọc (dạng biến thể của 玉) | 炎 | viêm | biểu âm | thành phần biểu âm (đọc yǎn/yán) | 琰 = 𤣩/玉 (biểu nghĩa: ngọc) + 炎 (Viêm, biểu âm); chữ hình thanh. Bộ 玉 cho biết liên quan đến đá quý; 炎 chỉ âm đọc yǎn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến; 琰 (yǎn): 玉 (ngọc) + 炎 (viêm/lửa) — viên ngọc 琰 sáng bừng rực như ngọn lửa 炎, dùng đặt tên người quý phái. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 琰 mở khoá tên người như 蔡琰 (Sái Diễm – Sái Văn Cơ, nữ thi nhân Đông Hán), 玉琰 — từ vựng tên riêng và văn học cổ.", "Tự nguyên_Xie": "Tiểu triện | 琰 là chữ hình thanh: 玉 (ngọc) biểu nghĩa + 炎 biểu âm. Wiktionary xác nhận cấu trúc psc. Nghĩa là tấm ngọc bài đầu nhọn (pointed jade tablet) và ngọc đẹp. Thường dùng làm tên người trong văn hóa Trung Hoa (Sái Văn Cơ tên chữ là Văn Cơ, tên thật Sái琰). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lóng lánh", "Hạng Tần Suất (Jun Da)": "5089.0", "Tần Suất % (Jun Da)": "99.9306277971", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 炎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王炎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "炎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "琰", "Unihan_Traditional (Chữ Phồn thể)": "琰", "Pinyin_Xie": "yǎn", "Âm Hán Việt_Xie": "diễm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn chương hoặc đặt tên người để chỉ vẻ đẹp tinh khiết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹚', '{"9000": "5090.0", "Chữ Trung Quốc": "鹚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 14 | nét | 鹚 | từ | tượng hình | cốc đế (cormorant) | 鹚 thuộc bộ 鸟 (điểu – chim). Wiktionary ghi: 鹚 xem 鶿 (繁thể). Đây là chữ giản thể. Không có phân tích cấu trúc riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"từ\": bộ 鸟 (chim) — 鹚 là chim cốc đế, loài chim đen tuyền lặn sâu bắt cá, biểu tượng của nghề cá truyền thống Quế Lâm. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 鹚 mở khoá 鸬鹚 (lô từ – cốc đế/cormorant), nghề cá truyền thống dùng chim 鸬鹚 — du lịch văn hóa Quế Lâm.", "Tự nguyên_Xie": "Tiểu triện | 鹚 là dạng giản thể của 鶿. Thuộc bộ 鸟 (chim). Nghĩa là chim cốc đế (cormorant) — loài chim lặn bắt cá, thường được người ngư dân huấn luyện đi câu truyền thống ở Quế Lâm và các vùng ven sông Trung Quốc. Wiktionary: {{zh-see|鶿}}. Chữ tạo muộn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lô tư 鸕鷀,鸕鷥,鸬鷀,鸬鸶)", "Hạng Tần Suất (Jun Da)": "5090.0", "Tần Suất % (Jun Da)": "99.9307109995", "GavinGrover_Once (Chiết tự trực tiếp)": "兹 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰兹鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹚", "Unihan_Traditional (Chữ Phồn thể)": "鶿", "Pinyin_Xie": "cí", "Âm Hán Việt_Xie": "từ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường đi kèm với chữ lô để tạo thành từ ghép chỉ chim cốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龆', '{"9000": "5091.0", "Chữ Trung Quốc": "龆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 13 | nét | 龆 | điều | tượng hình | tuổi thơ ấu, thay răng | 龆 là dạng giản thể của 齠. Thuộc bộ 齿/齒 (xỉ – răng). Wiktionary: {{Han simp|齠|f=齒|t=齿}}. Không có phân tích cấu trúc riêng vì là chữ giản hóa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điều\": bộ 齿 (răng) — 龆 (điều) gắn với tuổi thơ khi thay 齿 (răng) sữa, giai đoạn ngây thơ trong sáng nhất. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 龆 mở khoá 龆年 (tuổi thơ ấu), 龆龀 (điều xỉ – giai đoạn thay răng = tuổi thơ) — từ văn học cổ điển.", "Tự nguyên_Xie": "龆 là dạng giản thể của 齠. Bộ 齿 (răng). Nghĩa là tuổi thơ ấu khi trẻ em thay răng sữa (khoảng 7-8 tuổi). Dùng trong 龆年 (tuổi thay răng = tuổi thơ ấu) và 龆龀 (điều xỉ – tuổi còn thơ dại). Chữ giản hóa hiện đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gãy răng sữa; còn trẻ", "Hạng Tần Suất (Jun Da)": "5091.0", "Tần Suất % (Jun Da)": "99.9307942019", "GavinGrover_Once (Chiết tự trực tiếp)": "齿 + 召", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齿召", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "召", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齿", "Unihan_Simplified (Chữ Giản thể)": "龆", "Unihan_Traditional (Chữ Phồn thể)": "齠", "Pinyin_Xie": "tiáo", "Âm Hán Việt_Xie": "điều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ trong các từ ghép chỉ thời thơ ấu như điều niên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臬', '{"9000": "5092.0", "Chữ Trung Quốc": "臬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 自 | Số nét | 10 | nét | 自 | tự | biểu nghĩa | mũi (tượng hình) | 木 | mộc | biểu nghĩa | gỗ, cây | 臬 = 自 (Tự, mũi – biểu nghĩa) + 木 (Mộc, gỗ – biểu nghĩa); chữ hội ý. Wiktionary: Han compound hội ý của 自 (mũi) và 木 (gỗ). Nhiều cách giải thích khác nhau tồn tại; nghĩa gốc là \"bia đích\" (archery target).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến; 臬 (niè): 木 (cọc gỗ) trước 自 (mũi nhắm) — cột gỗ làm bia đích bắn cung, từ đó trở thành \"tiêu chuẩn/phép tắc\" (准臬). | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 臬 mở khoá 准臬 (chuẩn nghiết – tiêu chuẩn, khuôn mẫu), 臬司 (quan án sát đời Minh/Thanh) — từ văn học lịch sử và hành chính.", "Tự nguyên_Xie": "Tiểu triện | 臬 là chữ hội ý: 自 (mũi) + 木 (gỗ), theo Wiktionary. Nghĩa gốc là bia đích bắn cung (archery target) — cọc gỗ cắm làm mục tiêu. Sau mở rộng sang: đồng hồ mặt trời/cột đo bóng (gnomon), và rồi thành tiêu chuẩn/phép tắc (臬司 – quan coi luật pháp). Nhiều cách giải thích nguồn gốc tồn tại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái ngưỡng cửa", "Hạng Tần Suất (Jun Da)": "5092.0", "Tần Suất % (Jun Da)": "99.9308774043", "GavinGrover_Once (Chiết tự trực tiếp)": "自 + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱自木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "木", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "自", "Unihan_Simplified (Chữ Giản thể)": "臬", "Unihan_Traditional (Chữ Phồn thể)": "臬", "Pinyin_Xie": "niè", "Âm Hán Việt_Xie": "nghiệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ tiêu chuẩn, khuôn mẫu hoặc chức quan tư pháp thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芄', '{"9000": "5093.0", "Chữ Trung Quốc": "芄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 6 | nét | 芄 | hoàn | tượng hình | cây la ma (dây leo có trái) | 芄 thuộc bộ 艹 (tháu – cỏ, thực vật). Không có glyphOrigin từ Wiktionary. Là tên cây cổ điển trong Kinh Thi (芄兰 – dây leo có quả). Chữ tạo muộn, chưa có phân tích ls.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàn\": bộ 艹 (thực vật) — 芄 là cây dây leo trong Kinh Thi (芄兰), loài thực vật xuất hiện từ thời thượng cổ. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 芄 mở khoá 芄兰 (tên dây leo trong Kinh Thi — thơ ca cổ nhất Trung Hoa) — từ văn học kinh điển.", "Tự nguyên_Xie": "Tiểu triện | 芄 thuộc bộ 艹 (thực vật). Không có phân tích cấu trúc từ Wiktionary. Chủ yếu dùng trong 芄兰 (Hoàn lan) — tên dây leo có trong Kinh Thi, được nhận dạng là cây Metaplexis japonica (dây leo có quả giống ngón tay). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hoàn lan 芄蘭,芄兰)", "Hạng Tần Suất (Jun Da)": "5093.0", "Tần Suất % (Jun Da)": "99.9309600899", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 丸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹丸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芄", "Unihan_Traditional (Chữ Phồn thể)": "芄", "Pinyin_Xie": "wán", "Âm Hán Việt_Xie": "hoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong từ ghép hoàn lan để chỉ một loại cây leo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('呔', '{"9000": "5094.0", "Chữ Trung Quốc": "呔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 口 | khẩu | biểu nghĩa | miệng, lời nói | 太 | thái | biểu âm | thành phần biểu âm (đọc dāi/tài) | 呔 = 口 (Khẩu, biểu nghĩa: miệng/lời nói) + 太 (Thái, biểu âm); chữ hình thanh. Bộ 口 cho biết liên quan đến âm thanh/lời nói; 太 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến; 呔 (dāi): 口 (miệng) + 太 (thái) — 呔 là tiếng kêu từ miệng ra, hoặc cà vạt (tie) đeo trước miệng/ngực trong tiếng Quảng. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 呔 mở khoá 领呔 (cà vạt, từ Quảng Đông), 呔水 (dung dịch hóa chất đặc biệt) — từ vựng Quảng Đông và phương ngữ.", "Tự nguyên_Xie": "呔 là chữ hình thanh: 口 (miệng) biểu nghĩa + 太 biểu âm. Wiktionary xác nhận cấu trúc psc. Nghĩa là: (1) tiếng kêu gọi/ngạc nhiên (trong phương ngữ Quảng Đông và văn học cổ); (2) thắt lưng, cà vạt (từ phiên dịch âm \"tie\" trong tiếng Quảng Đông — 领呔 = cà vạt). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "này (thán từ, đằng hắng để người khác chú ý, thường thấy trong Bạch thoại thời kỳ đầu.); Ghi chú: 另见tǎi", "Hạng Tần Suất (Jun Da)": "5094.0", "Tần Suất % (Jun Da)": "99.9310427756", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 太", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口太", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "太", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呔", "Unihan_Traditional (Chữ Phồn thể)": "呔", "Pinyin_Xie": "dāi", "Âm Hán Việt_Xie": "thái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Thán từ | 叹词 | Chữ này thường dùng làm thán từ đứng đầu câu để quát hỏi hoặc gây sự chú ý trong văn bạch thoại cũ. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雒', '{"9000": "5095.0", "Chữ Trung Quốc": "雒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 隹 | Số nét | 14 | nét | 雒 | lạc | tượng hình | địa danh cổ, chim đen trắng | 雒 thuộc bộ 隹 (chuy – chim). Wiktionary chỉ ghi {{Han etym}}. Đây là địa danh cổ (洛阳 ngày xưa viết 雒阳) và tên chim trong văn học. Chữ cổ, có hình ảnh sớm trong kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạc\": bộ 隹 (chim) — 雒 (Lạc) là tên cổ của Lạc Dương (雒阳), kinh đô nhiều triều đại, như con chim thiêng đậu xuống đất lành. | Gương Hán-Việt | Lạc Dương (kinh đô lịch sử Trung Hoa) | Mở khoá kiến thức | Biết 雒 mở khoá 雒阳 (Lạc Dương cổ tự), 雒书 (Lạc Thư – một trong hai hà đồ lạc thư) — từ lịch sử và triết học cổ đại.", "Tự nguyên_Xie": "Tiểu triện | 雒 thuộc bộ 隹 (chim). Wiktionary chỉ ghi {{Han etym}} không phân tích chi tiết. Là tên cổ của địa danh Lạc Dương (雒阳 → 洛阳). Cũng là tên loài chim trong văn học cổ. Chưa có phân tích cấu trúc học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Lạc", "Hạng Tần Suất (Jun Da)": "5095.0", "Tần Suất % (Jun Da)": "99.9311254612", "GavinGrover_Once (Chiết tự trực tiếp)": "各 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰各隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "各", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "隹", "Unihan_Simplified (Chữ Giản thể)": "雒", "Unihan_Traditional (Chữ Phồn thể)": "雒", "Pinyin_Xie": "luò", "Âm Hán Việt_Xie": "lạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng chỉ tên sông, tên đất hoặc họ người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觞', '{"9000": "5096.0", "Chữ Trung Quốc": "觞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 角 | Số nét | 12 | nét | 觞 | thương | tượng hình | chén rượu, uống rượu | 觞 thuộc bộ 角 (giác – sừng, đồ đựng). Không có phân tích cấu trúc chi tiết từ Wiktionary. Bộ 角 gợi đồ đựng làm từ sừng; nghĩa là chén rượu hoặc động từ uống rượu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thương\": bộ 角 (sừng) — 觞 (thương) là chén rượu làm từ sừng, hình ảnh 曲水流觞 (thả chén rượu trôi theo dòng nước) trong thơ Vương Hi Chi. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 觞 (thương) mở khoá 觞咏 (nâng chén ngâm thơ), 流觞曲水 (thả chén rượu trên suối) — từ văn học thư pháp cổ điển.", "Tự nguyên_Xie": "Tiểu triện | 觞 thuộc bộ 角 (sừng/đồ đựng). Wiktionary chỉ ghi {{Han etym}} không phân tích chi tiết. Nghĩa là chén rượu (thường bằng sừng hoặc gỗ) và động từ \"nâng chén uống rượu\". Nổi tiếng qua thơ Vương Hi Chi 曲水流觞 (khúc thủy lưu thương) — thả chén rượu trên dòng suối cong. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chén rượu, cốc rượu", "Hạng Tần Suất (Jun Da)": "5096.0", "Tần Suất % (Jun Da)": "99.9312081468", "GavinGrover_Once (Chiết tự trực tiếp)": "角 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰角", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "觞", "Unihan_Traditional (Chữ Phồn thể)": "觴", "Pinyin_Xie": "shāng", "Âm Hán Việt_Xie": "thương, tràng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ chén rượu hoặc làm động từ với nghĩa mời rượu, chúc rượu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钒', '{"9000": "5097.0", "Chữ Trung Quốc": "钒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 8 | nét | 金 | kim | biểu nghĩa | kim loại | 凡 | phàm | biểu âm | thành phần biểu âm (đọc fán) | 钒 = 钅/金 (Kim, biểu nghĩa: kim loại) + 凡 (Phàm, biểu âm); chữ hình thanh. Bộ 金 cho biết đây là nguyên tố kim loại; 凡 chỉ âm đọc fán. Chữ tạo trong hệ thống thuật ngữ hóa học hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến; 钒 (fán): 金 (kim loại) + 凡 (phàm/bình thường) — kim loại Vanadium, nghe phàm thường nhưng là thành phần thép không thể thiếu. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 钒 mở khoá 钒钢 (thép vanadium), 钒电池 (pin vanadium), 五氧化二钒 — từ vựng hóa học và vật liệu học.", "Tự nguyên_Xie": "钒 là chữ hình thanh hiện đại: 金 (kim loại) biểu nghĩa + 凡 biểu âm. Wiktionary xác nhận cấu trúc psc. Là tên Trung văn của nguyên tố Vanadium (V, số nguyên tử 23) — kim loại chuyển tiếp cứng, màu xám bạc, dùng trong hợp kim thép. Chữ tạo cho thuật ngữ hóa học. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố vanadi, Vd", "Hạng Tần Suất (Jun Da)": "5097.0", "Tần Suất % (Jun Da)": "99.9312903156", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 凡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅凡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "凡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钒", "Unihan_Traditional (Chữ Phồn thể)": "釩", "Pinyin_Xie": "fán", "Âm Hán Việt_Xie": "phàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ trong hóa học để chỉ nguyên tố kim loại vanadi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饫', '{"9000": "5098.0", "Chữ Trung Quốc": "饫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 7 | nét | 食 | thực | biểu nghĩa | ăn, thức ăn | 夭 | yểu | biểu âm | thành phần biểu âm (đọc yù/yāo) | 饫 = 饣/食 (Thực, biểu nghĩa: ăn/thức ăn) + 夭 (Yểu, biểu âm); chữ hình thanh. Bộ 食 cho biết liên quan đến ăn uống; 夭 chỉ âm đọc. Wiktionary ghi: từ 𩜈, sau thêm 食.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ứ\": bộ 食 (ăn) + 夭 (yểu) — 饫 (ứ) là no đủ, thậm chí ứ đến mức không muốn ăn nữa — ăn uống dư thừa sung túc. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 饫 (ứ) mở khoá 饫甘餍肥 (no đủ sung sướng), 厌饫 (chán ngán vì quá no) — từ văn học cổ điển mô tả cuộc sống xa hoa.", "Tự nguyên_Xie": "Tiểu triện | 饫 là chữ hình thanh: 食 (ăn) biểu nghĩa + 夭 biểu âm. Theo Wiktionary: xuất phát từ 𩜈, sau đó được viết lại với 食. Nghĩa là no đủ, ăn ngon không thiếu thốn; cũng có nghĩa là bữa ăn tế lễ riêng tư. Thường dùng trong văn học cổ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "no nê, ăn thoả thích", "Hạng Tần Suất (Jun Da)": "5098.0", "Tần Suất % (Jun Da)": "99.9313724845", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 夭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣夭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "饫", "Unihan_Traditional (Chữ Phồn thể)": "飫", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "ứ, ốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường dùng làm động từ chỉ việc ăn uống no nê hoặc được ban tặng thức ăn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阒', '{"9000": "5099.0", "Chữ Trung Quốc": "阒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 12 | nét | 阒 | khích | tượng hình | yên tĩnh, vắng lặng | 阒 thuộc bộ 门/門 (môn – cổng, cửa). Không có phân tích cấu trúc chi tiết từ Wiktionary ngoài {{Han etym}}. Bộ 门 gợi không gian đóng kín, im ắng. Chữ cổ, dùng chủ yếu trong văn học cổ điển.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khích\": bộ 门 (cửa) — 阒 (khích) là cánh cửa 门 đóng chặt trong không gian vắng tanh, 阒寂 như ngôi nhà bỏ không không một bóng người. | Gương Hán-Việt | chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 阒 (khích) mở khoá 阒寂 (hoàn toàn tĩnh lặng), 阒然 (im ắng), 阒其无人 (không một bóng người) — từ văn học miêu tả sự cô quạnh.", "Tự nguyên_Xie": "Tiểu triện | 阒 thuộc bộ 门 (cửa). Wiktionary chỉ ghi {{Han etym}} và rfdef. Nghĩa là yên tĩnh, vắng lặng tuyệt đối — không một bóng người. Thường gặp trong 阒然 (im lặng hoàn toàn), 阒寂 (vắng lặng), 阒其无人 (hoàn toàn không có người). Chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vắng vẻ", "Hạng Tần Suất (Jun Da)": "5099.0", "Tần Suất % (Jun Da)": "99.9314546533", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 狊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门狊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "狊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阒", "Unihan_Traditional (Chữ Phồn thể)": "闃", "Pinyin_Xie": "qù", "Âm Hán Việt_Xie": "khuých", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả trạng thái vắng lặng, thường dùng trong văn viết cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('槎', '{"9000": "5100.0", "Chữ Trung Quốc": "槎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 槎 | xay | tượng hình | bè gỗ, cành cây bị chặt | 槎 không có cấu trúc IDS rõ ràng trong dữ liệu; theo hình dạng chữ, 槎 gồm bộ 木 (mộc, cây) và 差 (sai) làm âm phù. Đây có thể là chữ hình thanh, nhưng nguồn học thuật chưa xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xay\": tưởng tượng người đang xay lúa trên chiếc bè gỗ (槎) nổi giữa sông — cây gỗ kết thành bè để xay thóc. | Gương Hán-Việt | \"xay\" trong \"phiêu xay\" (bè trôi nổi) — chữ cổ ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 槎 (xay) giúp nhận ra các từ văn học cổ chỉ bè gỗ và việc chặt cây trong thi văn Hán.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 槎 là dị thể của 楂, chỉ bè gỗ (wooden raft), cành cây, log. Ngoài ra còn nghĩa là lần/dịp (time, occasion) và hành động chặt cây (to hew, to fell). Chữ tạo muộn, chưa thấy rõ trong giáp cốt/kim văn; chưa có nguồn học thuật xác nhận cấu trúc hình thanh hay hội ý. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chặt ngang cây, phát cây; cài bè", "Hạng Tần Suất (Jun Da)": "5100.0", "Tần Suất % (Jun Da)": "99.9315368221", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 差", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木差", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "差", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "槎", "Unihan_Traditional (Chữ Phồn thể)": "槎", "Pinyin_Xie": "chá", "Âm Hán Việt_Xie": "tra", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ bè gỗ hoặc làm động từ chỉ hành động chặt cây, đốn củi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸩', '{"9000": "5101.0", "Chữ Trung Quốc": "鸩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 9 | nét | 鸩 | 鸩 | tượng hình | loài chim độc | 鸩 là dạng giản thể của 鴆. Không có dữ liệu IDS; chữ liên quan đến bộ 鳥 (điểu, chim). Cấu trúc cụ thể chưa được xác nhận qua nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không rõ reading chuẩn (âm Hán-Việt thường là \"chẩm\"): 鸩 là loài chim chết chóc — lông nó ngâm vào rượu là thành thuốc độc. | Gương Hán-Việt | \"chẩm tửu\" (鸩酒) — rượu có độc, chứa lông chim chẩm; thành ngữ chỉ hành động tự hại mình. | Mở khoá kiến thức | Biết 鸩 (chẩm) giúp hiểu điển tích \"chẩm tửu\" và các ẩn dụ về thuốc độc trong văn học cổ.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi {{Han etym}} cho 鸩 mà không cung cấp chi tiết glyph. 鸩 (phồn thể 鴆) chỉ loài chim huyền thoại có lông cực độc — người xưa cho rằng nhúng lông chim vào rượu sẽ thành rượu độc (鸩酒). Chữ tạo muộn hoặc nguồn Wiktionary chưa đủ; chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "loài chim độc; rượu có độc", "Hạng Tần Suất (Jun Da)": "5101.0", "Tần Suất % (Jun Da)": "99.931618991", "GavinGrover_Once (Chiết tự trực tiếp)": "冘 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰冘鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鸩", "Unihan_Traditional (Chữ Phồn thể)": "鴆", "Pinyin_Xie": "zhèn", "Âm Hán Việt_Xie": "chậm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ loài chim độc hoặc rượu độc, và làm động từ với nghĩa đầu độc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舂', '{"9000": "5102.0", "Chữ Trung Quốc": "舂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 臼 | Số nét | 11 | nét | 廾 | trấp | biểu nghĩa | hai tay | 午 | ngọ | biểu nghĩa | chày giã | 臼 | cối | biểu nghĩa | cối giã | 舂 = 廾 (Trấp, hai tay) + 午 (Ngọ, chày) + 臼 (Cối, cối giã); chữ hội ý. Hình ảnh hai tay cầm chày giã gạo trong cối — mô tả trực quan hành động giã gạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thung\": hai tay (廾) cầm chày (午) thụng mạnh xuống cối (臼) — âm \"thung thung\" vang lên khi giã gạo. | Gương Hán-Việt | \"thung\" trong \"thung thủng\" (từ cổ chỉ việc giã gạo) — nay ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 舂 (thung) giúp nhận ra bộ 臼 (cối) trong các chữ liên quan đến giã, nghiền.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Wiktionary xác nhận 舂 là chữ hội ý (lsCodes: ic): 廾 (hai tay) + 午 (chày) + 臼 (cối) — tả động tác hai tay cầm chày giã gạo trong cối. Chữ xuất hiện từ thời giáp cốt văn, kim văn và tiểu triện, phản ánh công việc giã gạo trong đời sống nông nghiệp cổ đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giã (gạo)", "Hạng Tần Suất (Jun Da)": "5102.0", "Tần Suất % (Jun Da)": "99.9317011598", "GavinGrover_Once (Chiết tự trực tiếp)": "𡗗 + 臼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱𡗗臼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𡗗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "臼", "Unihan_Simplified (Chữ Giản thể)": "舂", "Unihan_Traditional (Chữ Phồn thể)": "舂", "Pinyin_Xie": "chōng", "Âm Hán Việt_Xie": "thung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động giã gạo hoặc đập mạnh bằng chày. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谠', '{"9000": "5103.0", "Chữ Trung Quốc": "谠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 12 | nét | 讠 | ngôn | biểu nghĩa | lời nói | 党 | đảng | biểu âm | 谠 là dạng giản thể của 讜 = 讠(Ngôn, biểu nghĩa: lời nói) + 党 (Đảng, biểu âm); chữ hình thanh. Nghĩa gốc là lời nói thẳng thắn, chân thực.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không có reading chuẩn (âm đọc là \"đảng\" theo âm Hán-Việt gần): 谠 là lời nói (讠) thẳng như đảng viên trung thực — ai cũng nghe, không né tránh. | Gương Hán-Việt | \"đảng ngôn\" (谠言) — lời nói thẳng thắn, lời trung thực, lời can gián. | Mở khoá kiến thức | Biết 谠 (đảng) giúp hiểu cụm \"谠言\" (đảng ngôn) trong văn cổ ca ngợi người dám nói thật.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 谠 là giản thể của 讜, được tạo bằng cách thay 言 thành 讠 và 黨 thành 党. 讜 chỉ lời nói thẳng thắn, lời can gián trung thực. Chữ hình thanh: bộ 言 biểu nghĩa (lời nói), 黨 biểu âm. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói thẳng", "Hạng Tần Suất (Jun Da)": "5103.0", "Tần Suất % (Jun Da)": "99.9317828119", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 党", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠党", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "党", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谠", "Unihan_Traditional (Chữ Phồn thể)": "讜", "Pinyin_Xie": "dǎng", "Âm Hán Việt_Xie": "đảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường làm tính từ bổ nghĩa cho lời nói hoặc ý kiến ngay thẳng, bộc trực. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阡', '{"9000": "5104.0", "Chữ Trung Quốc": "阡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 5 | nét | 阜 | phụ | biểu nghĩa | đất, gò đất | 千 | thiên | biểu âm | 阡 = 阜 (Phụ, biểu nghĩa: gò đất, đất) + 千 (Thiên, biểu âm); chữ hình thanh. Bộ 阜 (viết tắt là 阝bên trái) chỉ địa hình đất cao, liên quan đến bờ ruộng và con đường.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không rõ (âm gần là \"thiên\"): bờ ruộng (阡) chạy ngàn dặm (千) xuyên qua đất (阜) — cánh đồng bất tận trải dài. | Gương Hán-Việt | \"阡陌\" (thiên mạch) — hệ thống đường bờ ruộng, nghĩa rộng là cánh đồng mênh mông. | Mở khoá kiến thức | Biết 阡 (thiên) giúp hiểu cụm 阡陌 trong thơ văn cổ miêu tả cảnh đồng quê.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary xác nhận 阡 là chữ hình thanh: 阜 (gò đất) biểu nghĩa + 千 biểu âm. Nghĩa gốc là đường bờ ruộng theo chiều bắc-nam (khác với 陌 là đường đông-tây). Trong văn học cổ, 阡陌 chỉ hệ thống đường bờ ruộng của chế độ tỉnh điền. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bờ ruộng; đường đi trong bãi tha ma", "Hạng Tần Suất (Jun Da)": "5104.0", "Tần Suất % (Jun Da)": "99.9318644639", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 千", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝千", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "千", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "阡", "Unihan_Traditional (Chữ Phồn thể)": "阡", "Pinyin_Xie": "qiān", "Âm Hán Việt_Xie": "thiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ lối đi nhỏ trên bờ ruộng hoặc đường dẫn vào nghĩa trang. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莒', '{"9000": "5105.0", "Chữ Trung Quốc": "莒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 莒 | cử | tượng hình | cây khoai môn, tên nước cổ | 莒 không có cấu trúc IDS rõ ràng; theo hình dạng gồm bộ 艸 (tháu, cỏ/thực vật) ở trên và 呂 (lã) bên dưới, nhưng nguồn học thuật chưa xác nhận cụ thể. Khả năng là chữ hình thanh hoặc hội ý liên quan đến thực vật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cử\": nước Cử (莒) nổi tiếng với điển tích \"chớ quên nước Cử\" (毋忘在莒) — nhắc nhở khi hoàn cảnh khó khăn không được quên gốc rễ. | Gương Hán-Việt | \"Cử quốc\" (莒國) — nước Cử thời Chu, điển cố trong lịch sử Trung Quốc. | Mở khoá kiến thức | Biết 莒 (cử) giúp hiểu điển tích \"毋忘在莒\" — bài học về lòng kiên nhẫn và không quên nguồn cội.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Wiktionary cung cấp phát âm và định nghĩa của 莒 (khoai môn, nước Cử thời Chu, họ người) nhưng không cung cấp phân tích cấu trúc glyph rõ ràng. Xuất hiện trong kim văn và tiểu triện. Chưa có nguồn học thuật xác nhận cấu trúc hình thành chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Cử; cỏ cử", "Hạng Tần Suất (Jun Da)": "5105.0", "Tần Suất % (Jun Da)": "99.931946116", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 吕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹吕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莒", "Unihan_Traditional (Chữ Phồn thể)": "莒", "Pinyin_Xie": "jǔ", "Âm Hán Việt_Xie": "cử", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng chỉ tên nước chư hầu thời cổ hoặc tên địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萸', '{"9000": "5106.0", "Chữ Trung Quốc": "萸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 萸 | du | tượng hình | cây thù du, loại cây thuốc | 萸 không có cấu trúc IDS xác nhận; theo hình dạng gồm bộ 艸 (tháu, thực vật) và phần bên dưới. Wiktionary không phân tích cấu trúc. Chữ này hầu như chỉ dùng trong từ ghép 茱萸.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": 萸 chỉ xuất hiện trong 茱萸 — cây thù du cắm trên tóc ngày Trùng Dương để trừ tà. | Gương Hán-Việt | \"thù du\" (茱萸) — cây thù du trong câu thơ Vương Duy \"遍插茱萸少一人\" (cắm thù du khắp đầu còn thiếu một người). | Mở khoá kiến thức | Biết 萸 (du) giúp hiểu từ 茱萸 và điển tích Tết Trùng Dương trong thơ Đường.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 萸 chỉ dùng trong từ 茱萸 (thù du) — một loại cây thuốc (dogwood/Cornus) được dùng trong y học cổ truyền và nổi tiếng qua bài thơ Trùng Dương của Vương Duy. Nguồn chưa cung cấp phân tích glyph; chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây du", "Hạng Tần Suất (Jun Da)": "5106.0", "Tần Suất % (Jun Da)": "99.932027768", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 臾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹臾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "萸", "Unihan_Traditional (Chữ Phồn thể)": "萸", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong tên gọi của các loại cây thảo dược như thù du. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('妗', '{"9000": "5107.0", "Chữ Trung Quốc": "妗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 7 | nét | 女 | nữ | biểu nghĩa | phụ nữ | 今 | kim | biểu âm | 妗 = 女 (Nữ, biểu nghĩa: phụ nữ) + 今 (Kim, biểu âm); chữ hình thanh. Bộ 女 chỉ đây là chữ chỉ người phụ nữ trong quan hệ gia đình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không có reading chuẩn (âm gần \"cẩm\"): người phụ nữ (女) được gọi tên theo ngay hôm nay (今) — mợ, vợ của cậu, người phụ nữ trong gia đình bên ngoại. | Gương Hán-Việt | \"cẩm\" — trong phương ngữ miền Bắc Việt Nam, \"mợ\" tương đương với quan hệ 妗 trong tiếng Trung. | Mở khoá kiến thức | Biết 妗 (cẩm) giúp nhận ra nhóm chữ 女 chỉ quan hệ thân tộc theo họ mẹ.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận 妗 là chữ hình thanh: 女 (phụ nữ) biểu nghĩa + 今 biểu âm. Chữ chỉ vợ của anh trai mẹ (cậu), tức là mợ. Đây là chữ chuyên dùng để gọi quan hệ thân tộc bên ngoại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mợ (vợ của anh trai mẹ)", "Hạng Tần Suất (Jun Da)": "5107.0", "Tần Suất % (Jun Da)": "99.9321094201", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 今", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女今", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "今", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "妗", "Unihan_Traditional (Chữ Phồn thể)": "妗", "Pinyin_Xie": "jìn", "Âm Hán Việt_Xie": "cấm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng để xưng hô người mợ trong quan hệ gia đình. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稔', '{"9000": "5108.0", "Chữ Trung Quốc": "稔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 13 | nét | 禾 | hòa | biểu nghĩa | lúa | 念 | niệm | biểu âm | 稔 = 禾 (Hòa, biểu nghĩa: lúa) + 念 (Niệm, biểu âm); chữ hình thanh. Bộ 禾 chỉ đây là chữ liên quan đến lúa gạo, mùa màng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nậm\": lúa (禾) đã chín, cả năm nặng trĩu suy nghĩ (念) về mùa màng — 稔 là năm được mùa, quen thuộc như nhớ mãi. | Gương Hán-Việt | \"nậm\" — ít dùng trong tiếng Việt hiện đại; \"niên nậm\" (年稔) chỉ năm được mùa. | Mở khoá kiến thức | Biết 稔 (nậm) giúp hiểu cụm 稔知 (quen biết rõ), 丰稔 (mùa màng bội thu) trong văn cổ.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận 稔 là chữ hình thanh: 禾 (lúa) biểu nghĩa + 念 biểu âm. Nghĩa gốc là lúa chín, mùa màng bội thu. Mở rộng sang nghĩa năm (một năm lúa chín), quen thuộc/biết rõ (年稔 → quen thuộc theo năm tháng). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lúa chín, được mùa; năm; tội ác", "Hạng Tần Suất (Jun Da)": "5108.0", "Tần Suất % (Jun Da)": "99.9321910721", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 念", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾念", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "念", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稔", "Unihan_Traditional (Chữ Phồn thể)": "稔", "Pinyin_Xie": "rěn", "Âm Hán Việt_Xie": "nhẫm, nẫm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm tính từ thể hiện sự chín muồi hoặc trạng thái quen thuộc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穰', '{"9000": "5109.0", "Chữ Trung Quốc": "穰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 22 | nét | 穰 | nhương | tượng hình | thân cây lúa, rơm rạ | 穰 không có cấu trúc IDS rõ ràng trong dữ liệu. Theo hình dạng có bộ 禾 (hòa, lúa) ở trên. Wiktionary không cung cấp phân tích cụ thể; chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhương\": 穰 là đống rơm rạ (thân lúa) nhương nhây sau mùa gặt — dồi dào, phong phú như đống rơm chất cao. | Gương Hán-Việt | \"nhương\" — ít dùng trong tiếng Việt; trong từ \"nhương nhương\" (phong nhiêu) dùng trong văn cổ. | Mở khoá kiến thức | Biết 穰 (nhương) giúp hiểu các từ chỉ sự phong nhiêu trong mùa gặt hái như 丰穰 trong văn cổ.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 穰 nghĩa là thân cây lúa (stalks of grain), rậm rạp, phong phú (lush, abundant). Chưa có phân tích glyph chi tiết. Chữ tạo muộn, chưa thấy rõ trong giáp cốt/kim văn; chưa có nguồn học thuật xác nhận cấu trúc hình thành. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thân cây lúa", "Hạng Tần Suất (Jun Da)": "5109.0", "Tần Suất % (Jun Da)": "99.9322727242", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 襄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾襄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "襄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "穰", "Unihan_Traditional (Chữ Phồn thể)": "穰", "Pinyin_Xie": "ráng", "Âm Hán Việt_Xie": "nhưỡng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ rơm rạ hoặc tính từ chỉ sự sung túc, nhiều hoa quả. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚧', '{"9000": "5110.0", "Chữ Trung Quốc": "蚧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 10 | nét | 蚧 | nhái | tượng hình | con tắc kè, con thằn lằn | 蚧 không có cấu trúc IDS trong dữ liệu. Theo hình dạng có thể gồm bộ 虫 (trùng, côn trùng/bò sát) và phần âm phù, nhưng không có nguồn xác nhận. Chữ này hầu như chỉ dùng trong từ 蛤蚧 (cáp giới — con tắc kè).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhái\": 蚧 là con tắc kè (蛤蚧) — loài bò sát kêu \"cáp giới\" trên tường nhà, dùng làm thuốc bổ phổi. | Gương Hán-Việt | \"cáp giới\" (蛤蚧) — con tắc kè, vị thuốc quý trong đông y bổ phổi thận. | Mở khoá kiến thức | Biết 蚧 (nhái) giúp nhận ra từ 蛤蚧 trong tên thuốc đông y và tên sinh vật học.", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích glyph cho 蚧. Chữ này chủ yếu dùng trong từ 蛤蚧 (hán-việt: cáp giới) — loài tắc kè lớn, được dùng trong đông y. Chưa có nguồn học thuật xác nhận cấu trúc hình thành chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: cáp giới 蛤蚧)", "Hạng Tần Suất (Jun Da)": "5110.0", "Tần Suất % (Jun Da)": "99.9323543762", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 介", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫介", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "介", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚧", "Unihan_Traditional (Chữ Phồn thể)": "蚧", "Pinyin_Xie": "jiè", "Âm Hán Việt_Xie": "giới", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và thường xuất hiện trong từ ghép cáp giới để chỉ con tắc kè. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('餍', '{"9000": "5111.0", "Chữ Trung Quốc": "餍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 15 | nét | 厭 | ướm | biểu âm | 食 | thực | biểu nghĩa | thức ăn | 餍 = 厭 (Ướm, biểu âm) + 食 (Thực, biểu nghĩa: thức ăn); chữ hình thanh. Bộ 食 chỉ đây là chữ liên quan đến ăn uống, sự no chán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không rõ reading chuẩn (âm gần \"yếm\"): ăn (食) đến mức chán ngán (厭) — 餍 là trạng thái no nê đến bão hoà. | Gương Hán-Việt | \"yếm túc\" (饜足) — no đủ, thỏa mãn hoàn toàn; \"vô yếm\" (無饜) — tham lam không biết chán. | Mở khoá kiến thức | Biết 餍 (yếm) giúp hiểu cụm 無饜 (tham không chán) và 飫甘饜肥 (ăn ngon mặc đẹp) trong văn cổ.", "Tự nguyên_Xie": "Lục thư thông | Wiktionary xác nhận 餍 (phồn thể 饜) là chữ hình thanh: 厭 biểu âm + 食 (thức ăn) biểu nghĩa. Nghĩa là ăn no đến chán, thoả mãn hoàn toàn. Dùng trong từ 饜足 (no đủ), 無饜 (không biết chán, tham lam vô độ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "no chán, thoả mãn", "Hạng Tần Suất (Jun Da)": "5111.0", "Tần Suất % (Jun Da)": "99.9324360283", "GavinGrover_Once (Chiết tự trực tiếp)": "厌 + 食", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厌食", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "食", "Unihan_Simplified (Chữ Giản thể)": "餍", "Unihan_Traditional (Chữ Phồn thể)": "饜", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "yếm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ hoặc tính từ thể hiện trạng thái ăn no hoặc được thỏa mãn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谯', '{"9000": "5112.0", "Chữ Trung Quốc": "谯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 14 | nét | 谯 | tiều | tượng hình | tháp canh cổng thành, trách mắng | 谯 là dạng giản thể của 譙, gồm 讠(ngôn, lời nói) và 焦 (tiêu) làm âm phù. Đây là chữ hình thanh — 讠biểu nghĩa (liên quan đến lời nói/trách mắng), 焦 biểu âm. Ngoài nghĩa trách mắng, 谯 còn chỉ tháp canh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiều\": từ trên tháp canh (谯楼) quan sát xuống — 谯 vừa là tháp cao để nhìn, vừa là lời trách móc nhìn thẳng vào lỗi lầm. | Gương Hán-Việt | \"tiều lâu\" (谯楼) — tháp canh trên cổng thành trong kiến trúc cổ; \"tiều trách\" (谯责) — trách mắng. | Mở khoá kiến thức | Biết 谯 (tiều) giúp hiểu tên địa danh Tiều Quận (谯郡) và kiến trúc 谯楼 trong lịch sử Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 谯 (phồn thể 譙) có hai nghĩa chính: tháp canh trên cổng thành (watchtower) và trách mắng (to blame/reproach, dị thể của 誚). Chữ có hai âm đọc: qiáo (tháp canh) và qiào (trách mắng). Nguồn không cung cấp phân tích glyph chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trách mắng", "Hạng Tần Suất (Jun Da)": "5112.0", "Tần Suất % (Jun Da)": "99.9325171635", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 焦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠焦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "焦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谯", "Unihan_Traditional (Chữ Phồn thể)": "譙", "Pinyin_Xie": "qiáo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ mang nghĩa trách móc hoặc danh từ chỉ lầu canh xây trên cửa thành. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芗', '{"9000": "5113.0", "Chữ Trung Quốc": "芗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 6 | nét | 芗 | hương | tượng hình | mùi thơm của lúa gạo | 芗 là dạng giản thể của 薌, gồm bộ 艸 (tháu, thực vật) và phần còn lại. Không có cấu trúc IDS rõ ràng. Wiktionary không cung cấp phân tích glyph chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hương\": 芗 là mùi hương (hương) của lúa gạo (艸/禾) — khác 香 (hương) dùng cho mùi thơm chung, 芗 đặc chỉ mùi thóc gạo tươi. | Gương Hán-Việt | \"hương\" — 芗 đặc chỉ mùi lúa gạo, phân biệt với 香 dùng rộng hơn. | Mở khoá kiến thức | Biết 芗 (hương) giúp phân biệt các chữ chỉ mùi thơm trong văn học và y học cổ truyền.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 芗 (phồn thể 薌) chỉ hương thơm của lúa gạo, mùi cơm chín. Đây là chữ chuyên dùng cho mùi thơm của ngũ cốc. Chưa có phân tích cấu trúc hình thành chữ từ nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hơi cơm, mùi thóc gạo", "Hạng Tần Suất (Jun Da)": "5113.0", "Tần Suất % (Jun Da)": "99.9325982988", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 乡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹乡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芗", "Unihan_Traditional (Chữ Phồn thể)": "薌", "Pinyin_Xie": "xiāng", "Âm Hán Việt_Xie": "hương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ một loại cỏ thơm hoặc tính từ chỉ mùi hương của lương thực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菸', '{"9000": "5114.0", "Chữ Trung Quốc": "菸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艸 | tháu | biểu nghĩa | cỏ, thực vật | 於 | ư | biểu âm | 菸 = 艸 (Tháu, biểu nghĩa: cỏ/thực vật) + 於 (Ư, biểu âm); chữ hình thanh. Bộ 艸 chỉ đây là chữ liên quan đến thực vật, cụ thể là lá héo úa hoặc thuốc lá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không rõ reading chuẩn (âm gần \"vu\"): cây (艸) héo như âm \"ư\" thở dài — 菸 là lá thuốc khô héo, khói thuốc mờ mịt. | Gương Hán-Việt | \"菸草\" (vu thảo) — cây thuốc lá; dùng phổ biến ở Đài Loan thay cho 烟草. | Mở khoá kiến thức | Biết 菸 (vu) giúp đọc văn bản Đài Loan khi gặp từ 菸草 (thuốc lá) và 菸酒 (thuốc lá và rượu).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận 菸 là chữ hình thanh: 艸 (thực vật) biểu nghĩa + 於 biểu âm. Nghĩa gốc là lá héo, cây tàn úa. Sau dùng để chỉ thuốc lá (đồng nghĩa với 煙/烟) trong tiếng Trung Đài Loan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khói", "Hạng Tần Suất (Jun Da)": "5114.0", "Tần Suất % (Jun Da)": "99.9326794341", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 於", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹於", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "於", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菸", "Unihan_Traditional (Chữ Phồn thể)": "菸", "Pinyin_Xie": "yān", "Âm Hán Việt_Xie": "vu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ sự héo úa của cây cỏ hoặc danh từ chỉ cây thuốc lá. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葩', '{"9000": "5115.0", "Chữ Trung Quốc": "葩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葩 | ba | tượng hình | hoa, tinh hoa | 葩 không có cấu trúc IDS rõ ràng trong dữ liệu. Theo hình dạng gồm bộ 艸 (tháu, thực vật) ở trên, nhưng Wiktionary không cung cấp phân tích glyph chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ba\": 葩 là đóa hoa ba màu — nghe như ba (ba lần đẹp, ba lần tinh hoa) từ trong vườn cỏ (艸). | Gương Hán-Việt | \"ba\" trong \"奇葩\" (kỳ ba) — nghĩa gốc là hoa lạ kỳ; nay dùng hài hước chỉ người/vật kỳ dị. | Mở khoá kiến thức | Biết 葩 (ba) giúp hiểu từ 奇葩 (kỳ ba) trong tiếng Trung hiện đại — cả nghĩa cổ (hoa lạ) lẫn nghĩa mới (kỳ quái).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 葩 nghĩa là hoa (flowers), tinh hoa. Chữ xuất hiện trong tiểu triện và lục thư thông nhưng không có phân tích cấu trúc cụ thể. Chưa có nguồn học thuật xác nhận cấu trúc hình thành. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hoa; tinh hoa", "Hạng Tần Suất (Jun Da)": "5115.0", "Tần Suất % (Jun Da)": "99.9327605693", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 皅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹皅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葩", "Unihan_Traditional (Chữ Phồn thể)": "葩", "Pinyin_Xie": "pā", "Âm Hán Việt_Xie": "ba", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ hoa hoặc tính từ mô tả vẻ đẹp rực rỡ, lộng lẫy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踔', '{"9000": "5116.0", "Chữ Trung Quốc": "踔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 15 | nét | 足 | túc | biểu nghĩa | chân | 卓 | trác | biểu âm | 踔 = 足 (Túc, biểu nghĩa: chân) + 卓 (Trác, biểu âm); chữ hình thanh. Bộ 足 chỉ đây là chữ liên quan đến chân, bước đi, nhảy nhót.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xợt\": bước chân (足) trác việt (卓) — 踔 là bước nhảy vọt lên, vượt trội hơn người — như người nhảy xợt qua rào cản. | Gương Hán-Việt | \"踔厉\" (xợt lệ) — tinh thần hăng hái, dũng mãnh; trong 踔厉风发 (phong độ mạnh mẽ xuất chúng). | Mở khoá kiến thức | Biết 踔 (xợt) giúp hiểu thành ngữ 踔厉风发 — dùng phổ biến trong văn phong chính thức Trung Quốc hiện đại.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận 踔 là chữ hình thanh: 足 (chân) biểu nghĩa + 卓 biểu âm. Nghĩa bao gồm nhảy nhót, bước dài, vượt trội. Dùng trong thành ngữ 踔厉风发 (tinh thần hăng hái, khí thế mạnh mẽ) — phổ biến lại sau bài phát biểu của lãnh đạo Trung Quốc năm 2022. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhảy nhót", "Hạng Tần Suất (Jun Da)": "5116.0", "Tần Suất % (Jun Da)": "99.9328417046", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 卓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊卓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踔", "Unihan_Traditional (Chữ Phồn thể)": "踔", "Pinyin_Xie": "chuō", "Âm Hán Việt_Xie": "xước", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ hành động nhảy vọt hoặc tính từ chỉ sự vượt trội hơn người. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('厣', '{"9000": "5117.0", "Chữ Trung Quốc": "厣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 厂 | Số nét | 11 | nét | 厭 | ướm | biểu âm | 甲 | giáp | biểu nghĩa | vỏ cứng, mai | 厣 = 厭 (Ướm, biểu âm) + 甲 (Giáp, biểu nghĩa: vỏ cứng); chữ hình thanh. Bộ 甲 chỉ đây là chữ liên quan đến vỏ cứng của sinh vật, cụ thể là nắp vỏ ốc (operculum) hoặc yếm con cua.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không rõ reading chuẩn (âm gần \"yểm\"): cái yểm (厭) bằng mai giáp (甲) — 厣 là tấm mai che bụng con cua hay nắp đậy vỏ ốc. | Gương Hán-Việt | \"yểm\" — tấm mai, yếm con cua; trong đông y dùng làm vị thuốc. | Mở khoá kiến thức | Biết 厣 (yểm) giúp đọc tài liệu sinh học và đông y về các loài giáp xác và nhuyễn thể.", "Tự nguyên_Xie": "Wiktionary xác nhận 厣 (phồn thể 厴) là chữ hình thanh: 厭 biểu âm + 甲 (vỏ cứng) biểu nghĩa. Nghĩa là nắp vỏ ốc (operculum) và yếm con cua (phần mai bụng). Đây là chữ chuyên ngành sinh học/đông y. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái yếm của con cua", "Hạng Tần Suất (Jun Da)": "5117.0", "Tần Suất % (Jun Da)": "99.9329223231", "GavinGrover_Once (Chiết tự trực tiếp)": "厌 + 甲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厌甲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厌", "Unihan_Simplified (Chữ Giản thể)": "厣", "Unihan_Traditional (Chữ Phồn thể)": "厴", "Pinyin_Xie": "yǎn", "Âm Hán Việt_Xie": "áp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận nắp đậy vỏ của các loài ốc hoặc phần yếm của con cua. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佻', '{"9000": "5118.0", "Chữ Trung Quốc": "佻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 佻 | điêu | tượng hình | khinh bạc, tuỳ tiện | 佻 không có cấu trúc IDS rõ ràng trong dữ liệu. Theo hình dạng gồm bộ 亻(nhân, người) và phần âm phù. Wiktionary không cung cấp phân tích glyph cụ thể. Đây có thể là chữ hình thanh với 亻biểu nghĩa (người có tính cách) và phần còn lại biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điêu\": người (亻) điêu ngoa — 佻 là tính cách khinh bạc, không đứng đắn, nói năng bừa bãi. | Gương Hán-Việt | \"điêu\" trong \"khinh điêu\" (輕佻) — khinh bạc, tuỳ tiện, thiếu nghiêm túc. | Mở khoá kiến thức | Biết 佻 (điêu) giúp hiểu từ 輕佻 (khinh điêu) — tính cách hay lời nói khinh bạc không đứng đắn trong văn cổ.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 佻 có nghĩa chính là khinh bạc (frivolous), không trang trọng. Phát âm tiāo (khinh bạc), tiáo (đi một mình, duyên dáng — nghĩa cổ), tiào (nghĩa cổ). Không cung cấp phân tích glyph chi tiết. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tuỳ tiện; khinh thường; không trang trọng (lời nói và hành động)", "Hạng Tần Suất (Jun Da)": "5118.0", "Tần Suất % (Jun Da)": "99.9330029416", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 兆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻兆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "佻", "Unihan_Traditional (Chữ Phồn thể)": "佻", "Pinyin_Xie": "tiāo", "Âm Hán Việt_Xie": "điêu, điệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ để miêu tả tính cách hoặc hành vi cợt nhả, thiếu nghiêm túc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘌', '{"9000": "5119.0", "Chữ Trung Quốc": "嘌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 14 | nét | 嘌 | phiêu | tượng hình | nhanh chóng; purin (hóa học) | 嘌 không có cấu trúc IDS rõ ràng. Theo hình dạng gồm bộ 口 (khẩu, miệng) và phần âm phù. Dùng chủ yếu trong từ 嘌呤 (purin — hợp chất hóa học).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiêu\": 嘌 — miệng (口) nói phiêu nhanh; hoặc nhớ qua 嘌呤 (purin) — từ khoa học hay gặp trong y học. | Gương Hán-Việt | \"phiêu\" — ít dùng độc lập; chủ yếu qua 嘌呤 (purin) trong thuật ngữ y sinh học. | Mở khoá kiến thức | Biết 嘌 (phiêu) giúp đọc tài liệu y học Trung văn khi gặp 嘌呤 (purin) — quan trọng trong bệnh gút.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary ghi 嘌 có hai âm đọc và nghĩa: (1) piào/piāo — chạy nhanh, nói nhanh; (2) piào — dùng trong 嘌呤 (purin, base nitơ trong sinh hóa). Không cung cấp phân tích glyph. Chữ tạo muộn, chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhanh chóng", "Hạng Tần Suất (Jun Da)": "5119.0", "Tần Suất % (Jun Da)": "99.9330835601", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 票", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口票", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "票", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嘌", "Unihan_Traditional (Chữ Phồn thể)": "嘌", "Pinyin_Xie": "piào", "Âm Hán Việt_Xie": "phiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ trong văn cổ để tả dáng vẻ nhanh nhẹn hoặc kết hợp trong từ ghép hóa học. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饩', '{"9000": "5120.0", "Chữ Trung Quốc": "饩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 7 | nét | 饩 | hí | tượng hình | tặng gia súc sống, biếu thức ăn | 饩 là dạng giản thể của 餼, được tạo bằng cách thay 氣 thành 气 và 飠 thành 饣. Cấu trúc phồn thể gồm 飠(thực, thức ăn) biểu nghĩa và 氣 biểu âm — chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hí\": biếu thức ăn (饣) còn sống hơi (气) — 饩 là tặng gia súc sống, dâng lễ vật tươi sống cho người khác hoặc thần linh. | Gương Hán-Việt | \"hí\" — ít dùng; trong văn cổ \"芻饩\" (chú hí) chỉ cỏ và lương thực cung cấp cho quân đội. | Mở khoá kiến thức | Biết 饩 (hí) giúp hiểu 饩羊 (dê tế lễ) và 芻饩 (lương thảo) trong văn cổ.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 饩 là giản thể của 餼, thay thế 飠 bằng 饣 và 氣 bằng 气. 餼 chỉ gia súc sống dùng trong tế lễ, hoặc thức ăn/lương thực dùng để tặng biếu. Đây là chữ văn ngôn, liên quan đến lễ nghi cổ đại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tế sống; tặng sống; biếu sống (gia súc); biếu thức ăn; tặng thức ăn; cho thức ăn; tặng đồ ăn; cho đồ ăn", "Hạng Tần Suất (Jun Da)": "5120.0", "Tần Suất % (Jun Da)": "99.9331641785", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 气", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣气", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "气", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "饩", "Unihan_Traditional (Chữ Phồn thể)": "餼", "Pinyin_Xie": "xì", "Âm Hán Việt_Xie": "hí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ lễ vật bằng thịt sống hoặc động từ chỉ việc đem đồ ăn đi biếu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钏', '{"9000": "5121.0", "Chữ Trung Quốc": "钏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 8 | nét | 金 | kim | biểu nghĩa | kim loại, vàng | 川 | xuyên | biểu âm | 钏 = 金 (Kim, biểu nghĩa: kim loại) + 川 (Xuyên, biểu âm); chữ hình thanh. Bộ 金 chỉ đây là đồ trang sức kim loại. Âm 川 (xuyên) gợi hình ảnh dòng chảy uốn quanh cổ tay như vòng xuyến.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không rõ reading chuẩn (âm gần \"xuyến\"): kim loại (金) uốn như sông (川) quanh cổ tay — 钏 là chiếc xuyến/vòng tay bằng vàng bạc. | Gương Hán-Việt | \"xuyến\" trong \"xuyến vàng\" — vòng tay trang sức của phụ nữ, 钏 tương đương hoàn toàn. | Mở khoá kiến thức | Biết 钏 (xuyến) giúp đọc thơ từ cổ miêu tả trang sức và vẻ đẹp của phụ nữ.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận 钏 (phồn thể 釧) là chữ hình thanh: 金 (kim loại) biểu nghĩa + 川 biểu âm. Nghĩa là vòng xuyến đeo tay (bracelet, armlet). Chữ có từ thời cổ đại, dùng nhiều trong thơ từ miêu tả trang sức phụ nữ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái xuyến, cái vòng tay", "Hạng Tần Suất (Jun Da)": "5121.0", "Tần Suất % (Jun Da)": "99.933244797", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 川", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅川", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "川", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钏", "Unihan_Traditional (Chữ Phồn thể)": "釧", "Pinyin_Xie": "chuàn", "Âm Hán Việt_Xie": "xuyến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ chất liệu như vàng, ngọc để chỉ các loại vòng tay. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠓', '{"9000": "5122.0", "Chữ Trung Quốc": "蠓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 19 | nét | 虫 | trùng | biểu nghĩa | sâu, côn trùng | 蒙 | mông | biểu âm | 蠓 = 虫 (Trùng, biểu nghĩa: côn trùng) + 蒙 (Mông, biểu âm); chữ hình thanh. Bộ 虫 chỉ đây là loài côn trùng nhỏ. Âm 蒙 (mông) gợi hình ảnh những đám mỗi mù mờ bay thành đám.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mòng\": con trùng (虫) mù mờ mông lung (蒙) như sương — 蠓 là lũ mỗi nhỏ ti bay mờ mịt trước mặt. | Gương Hán-Việt | \"mòng\" — con mòng (蠛蠓) là loài côn trùng nhỏ trong văn cổ; dân gian VN dùng \"mòng\" chỉ loài ruồi lớn. | Mở khoá kiến thức | Biết 蠓 (mòng) giúp nhận ra từ 蠛蠓 (miệt mòng) và nhóm từ chỉ côn trùng nhỏ trong văn học cổ.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận 蠓 là chữ hình thanh: 虫 (côn trùng) biểu nghĩa + 蒙 biểu âm. Nghĩa là muỗi vắt/mỗi (midge, sandfly) — loài côn trùng nhỏ li ti bay thành đám. Trong phương ngữ Min còn chỉ muỗi thông thường. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: miệt mông 蠛蠓)", "Hạng Tần Suất (Jun Da)": "5122.0", "Tần Suất % (Jun Da)": "99.9333254155", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 蒙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫蒙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蒙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蠓", "Unihan_Traditional (Chữ Phồn thể)": "蠓", "Pinyin_Xie": "měng", "Âm Hán Việt_Xie": "mông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp trong từ ghép để chỉ các loài côn trùng nhỏ hút máu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黩', '{"9000": "5123.0", "Chữ Trung Quốc": "黩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黑 | Số nét | 20 | nét | 黩 | độc | tượng hình | làm ô nhục, lạm dụng | 黩 là dạng giản thể của 黷, thay 賣 bằng 卖. Cấu trúc phồn thể gồm 黑 (hắc, đen) biểu nghĩa và 賣 biểu âm — chữ hình thanh. Bộ 黑 gợi ý sự ô nhiễm, vấy bẩn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"độc\": 黩 — lấy cái đen (黑) bán (卖) ra — hành động bôi đen danh dự, ô nhục hóa điều thiêng liêng. 穷兵黩武 là hiếu chiến không biết dừng. | Gương Hán-Việt | \"độc\" trong \"穷兵黩武\" (cùng binh độc vũ) — lạm dụng vũ lực, hiếu chiến đến cùng kiệt. | Mở khoá kiến thức | Biết 黩 (độc) giúp hiểu thành ngữ 穷兵黩武 — phê phán chính sách quân sự hiếu chiến.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 黩 là giản thể của 黷. 黷 là chữ hình thanh: 黑 (đen) biểu nghĩa + 賣 biểu âm. Nghĩa là bôi nhọ, ô nhục, lạm dụng. Dùng trong 穷兵黩武 (cùng binh độc vũ — hiếu chiến, dùng binh quá mức). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhàm chán", "Hạng Tần Suất (Jun Da)": "5123.0", "Tần Suất % (Jun Da)": "99.933406034", "GavinGrover_Once (Chiết tự trực tiếp)": "黑 + 卖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰黑卖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黑", "Unihan_Simplified (Chữ Giản thể)": "黩", "Unihan_Traditional (Chữ Phồn thể)": "黷", "Pinyin_Xie": "dú", "Âm Hán Việt_Xie": "độc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ trong các từ ghép như độc vũ để chỉ việc lạm dụng binh lực hoặc làm bẩn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('倨', '{"9000": "5124.0", "Chữ Trung Quốc": "倨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 10 | nét | 倨 | cứ | tượng hình | kiêu ngạo, hống hách | 倨 theo hình dạng gồm bộ 亻(nhân, người) và 居 (cư) làm âm phù — có thể là chữ hình thanh. Wiktionary không xác nhận cấu trúc IDS cụ thể trong dữ liệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cứ\": người (亻) ngồi cứng đơ (居) không chịu cúi đầu — 倨 là thái độ kiêu ngạo, không coi ai ra gì. | Gương Hán-Việt | \"cứ ngạo\" (倨傲) — kiêu ngạo, hống hách; \"tiền cứ hậu cung\" (前倨後恭) — trước kiêu sau lễ phép. | Mở khoá kiến thức | Biết 倨 (cứ) giúp hiểu thành ngữ 前倨後恭 — điển hình cho sự thay đổi thái độ theo hoàn cảnh.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 倨 nghĩa là kiêu ngạo, hống hách (haughty, arrogant). Ngoài ra còn dùng như dị thể của 踞 (ngồi xổm) và 鋸 (cưa). Nổi tiếng qua thành ngữ 前倨後恭 (trước ngạo mạn sau khúm núm). Không cung cấp phân tích glyph chi tiết; chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngông ngáo", "Hạng Tần Suất (Jun Da)": "5124.0", "Tần Suất % (Jun Da)": "99.9334866525", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 居", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻居", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "居", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "倨", "Unihan_Traditional (Chữ Phồn thể)": "倨", "Pinyin_Xie": "jù", "Âm Hán Việt_Xie": "cứ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc kết hợp thành từ ghép để chỉ thái độ kiêu căng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缬', '{"9000": "5125.0", "Chữ Trung Quốc": "缬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 15 | nét | 缬 | hiệt | tượng hình | lụa hoa văn nhuộm, hoa mắt | 缬 là dạng giản thể của 纈, gồm 糸 (mịch, sợi tơ) biểu nghĩa và 頡 (hiệt) biểu âm — chữ hình thanh. Bộ 糸 chỉ đây liên quan đến vải lụa, sợi dệt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiệt\": sợi tơ (糸) thắt nút hiệt ra hoa văn — 缬 là kỹ thuật nhuộm thắt nút tạo hoa văn trên lụa, đẹp đến hoa mắt. | Gương Hán-Việt | \"hiệt\" — ít dùng; trong văn cổ có \"缬眼\" chỉ hiện tượng hoa mắt/chóng mặt. | Mở khoá kiến thức | Biết 缬 (hiệt) giúp đọc văn bản về nghề dệt và nhuộm truyền thống Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} cho 缬 nhưng không cung cấp chi tiết glyph. Phồn thể 纈 gồm 糸 (sợi/vải) biểu nghĩa và 頡 biểu âm. Nghĩa là vải lụa nhuộm có hoa văn (tie-dye fabric) và hiện tượng hoa mắt khi say rượu. Chưa có nguồn học thuật chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hàng dệt nhuộm có hoa văn; hoa mắt khi say rượu", "Hạng Tần Suất (Jun Da)": "5125.0", "Tần Suất % (Jun Da)": "99.9336473726", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 颉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟颉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "颉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缬", "Unihan_Traditional (Chữ Phồn thể)": "纈", "Pinyin_Xie": "xié", "Âm Hán Việt_Xie": "hiệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ loại vải nhuộm hoa văn hoặc động từ chỉ trạng thái hoa mắt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('殚', '{"9000": "5126.0", "Chữ Trung Quốc": "殚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 歹 | Số nét | 12 | nét | 殚 | đan | tượng hình | dùng hết, kiệt sức | 殚 là dạng giản thể của 殫, gồm 歹 (ngạt, xương chết) biểu nghĩa và 單 (đơn) biểu âm — có thể là chữ hình thanh. Bộ 歹 liên quan đến cái chết, sự kiệt tận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đan\": 殚 — dùng đến tận cùng (歹 gợi ý kiệt tận) từng giọt sức lực — 殚精竭虑 là dồn hết tâm sức. | Gương Hán-Việt | \"đan\" — ít dùng độc lập; \"殚精竭虑\" (đan tinh kiệt lự) — vắt kiệt tâm trí và sức lực. | Mở khoá kiến thức | Biết 殚 (đan) giúp hiểu thành ngữ 殚精竭虑 — làm việc đến mức vắt kiệt sức lực và tâm trí.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 殚 (phồn thể 殫) có nghĩa dùng hết (to exhaust, to use up) và hoàn toàn/tuyệt đối (utmost, entirely). Nổi tiếng trong cụm 殚精竭虑 (hao tâm tổn sức). Không cung cấp phân tích glyph chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hết, làm hết, cạn kiệt", "Hạng Tần Suất (Jun Da)": "5126.0", "Tần Suất % (Jun Da)": "99.9337274743", "GavinGrover_Once (Chiết tự trực tiếp)": "歹 + 单", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰歹单", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "单", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "歹", "Unihan_Simplified (Chữ Giản thể)": "殚", "Unihan_Traditional (Chữ Phồn thể)": "殫", "Pinyin_Xie": "dān", "Âm Hán Việt_Xie": "đàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Phó từ | 副词 | Thường làm động từ hoặc phó từ đứng trước động từ khác để chỉ việc dốc hết tâm lực. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钿', '{"9000": "5127.0", "Chữ Trung Quốc": "钿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 钿 | điền | tượng hình | trâm cài đầu, đồ khảm vàng | 钿 là dạng giản thể của 鈿, gồm 金 (kim, vàng/kim loại) biểu nghĩa và 田 (điền) biểu âm — chữ hình thanh. Bộ 金 chỉ đây là đồ trang sức/đồ kim loại tinh xảo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điền\": vàng (金) khảm hình ruộng (田) — 钿 là đồ trang sức tinh xảo khảm vàng hoặc trâm cài tóc của phụ nữ quý tộc. | Gương Hán-Việt | \"điền\" trong \"kim điền\" (金钿) — trâm vàng, đồ trang sức khảm vàng quý giá. | Mở khoá kiến thức | Biết 钿 (điền) giúp hiểu hình ảnh trang sức phụ nữ quý tộc trong thơ Đường như Trường Hận Ca.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi {{Han etym}} cho 钿 (phồn thể 鈿) — gồm 金 (kim loại) biểu nghĩa và 田 biểu âm. Nghĩa là trâm cài tóc, đồ trang trí khảm vàng (filigree). Nổi tiếng qua câu thơ Bạch Cư Dị: \"钗头凤\" và \"金钿委地无人收\" trong Trường Hận Ca. Nguồn không cung cấp chi tiết glyph hơn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bông bèo (một thứ đồ trang sức trên đầu của phụ nữ)", "Hạng Tần Suất (Jun Da)": "5127.0", "Tần Suất % (Jun Da)": "99.933807576", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 田", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅田", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "田", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钿", "Unihan_Traditional (Chữ Phồn thể)": "鈿", "Pinyin_Xie": "diàn", "Âm Hán Việt_Xie": "điền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ hoa tai, trâm cài tóc hoặc động từ chỉ việc khảm nạm vàng ngọc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鎏', '{"9000": "5128.0", "Chữ Trung Quốc": "鎏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 18 | nét | 流 | lưu | biểu âm | 金 | kim | biểu nghĩa | vàng | 鎏 = 流 (Lưu, biểu âm) + 金 (Kim, biểu nghĩa: vàng); chữ hình thanh. Bộ 金 chỉ đây là vàng nguyên chất, tinh khiết. 流 (chảy) gợi hình ảnh vàng chảy lỏng tinh khiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không rõ reading chuẩn (âm gần \"lưu\"): vàng (金) chảy (流) như nước tinh khiết — 鎏 là vàng nguyên chất dùng để mạ, 鎏金 là kỹ thuật mạ vàng đặc trưng đồ cổ Trung Hoa. | Gương Hán-Việt | \"lưu kim\" (鎏金) — mạ vàng; kỹ thuật phủ vàng trên bề mặt đồng/bạc thời cổ đại. | Mở khoá kiến thức | Biết 鎏 (lưu) giúp đọc tài liệu khảo cổ và bảo tàng khi gặp 鎏金 (mạ vàng nước) mô tả đồ cổ.", "Tự nguyên_Xie": "Wiktionary xác nhận 鎏 là chữ hình thanh: 金 (vàng) biểu nghĩa + 流 biểu âm. Nghĩa là vàng tinh khiết (pure gold), vàng lá mạ (gilt). Dùng chủ yếu trong 鎏金 — kỹ thuật mạ vàng nước trên đồng vật cổ đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vàng tốt, vàng nguyên chất", "Hạng Tần Suất (Jun Da)": "5128.0", "Tần Suất % (Jun Da)": "99.9338876777", "GavinGrover_Once (Chiết tự trực tiếp)": "流 + 金", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱流金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "流", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鎏", "Unihan_Traditional (Chữ Phồn thể)": "鎏", "Pinyin_Xie": "liú", "Âm Hán Việt_Xie": "lưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ trong kỹ thuật mạ vàng lên bề mặt kim loại hoặc danh từ chỉ vàng tốt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恁', '{"9000": "5129.0", "Chữ Trung Quốc": "恁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 10 | nét | 任 | nhâm | biểu âm | 心 | tâm | biểu nghĩa | tâm, lòng | 恁 = 任 (Nhâm, biểu âm) + 心 (Tâm, biểu nghĩa: lòng/tâm trí); chữ hình thanh. Bộ 心 chỉ đây là chữ liên quan đến suy nghĩ, tình cảm trong lòng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không rõ reading chuẩn (âm gần \"nhẫm\"): trong lòng (心) mang nặng trách nhiệm (任) nhớ mãi — 恁 là nhớ nhung, nghĩ đến ai trong lòng. | Gương Hán-Việt | \"nhẫm\" — ít dùng; trong từ cổ \"恁般\" (nhẫm ban) = như thế này; \"恁地\" = như vậy. | Mở khoá kiến thức | Biết 恁 (nhẫm) giúp đọc thi từ Tống Nguyên khi gặp 恁 dùng như \"như vậy\" hay \"thế đó\" trong phương ngữ.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận 恁 là chữ hình thanh: 任 biểu âm + 心 (tâm) biểu nghĩa. Nghĩa là nhớ, suy nghĩ (literary), hoặc như vậy, thế đó (dialectal — dùng ở tiếng Tống, Nguyên). Trong phương ngữ Tô-Châu và văn học cổ điển cổ trung Đại Lục dùng như đại từ/trạng từ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghĩ, nhớ", "Hạng Tần Suất (Jun Da)": "5129.0", "Tần Suất % (Jun Da)": "99.9339677794", "GavinGrover_Once (Chiết tự trực tiếp)": "任 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱任心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "任", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "恁", "Unihan_Traditional (Chữ Phồn thể)": "恁", "Pinyin_Xie": "nèn", "Âm Hán Việt_Xie": "nhẫm, nhậm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Đại từ | 代词 | Chữ này thường làm động từ biểu thị sự suy nghĩ hoặc làm đại từ chỉ thị trong văn cổ và phương ngôn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藿', '{"9000": "5130.0", "Chữ Trung Quốc": "藿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 19 | nét | 藿 | hoắc | tượng hình | lá cây đậu, cỏ thuốc | 藿 không có cấu trúc IDS rõ ràng. Theo hình dạng gồm bộ 艸 (tháu, thực vật) và phần còn lại. Wiktionary không cung cấp phân tích glyph chi tiết. Chữ tạo muộn, chỉ thấy trong lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoắc\": 藿 là lá cỏ hoắc hương — loài cây thơm đặc trưng, mùi hoắc hương quen thuộc trong thuốc đông y. | Gương Hán-Việt | \"hoắc hương\" (藿香) — cây hoắc hương, vị thuốc đông y quen thuộc; \"lê hoắc\" (藜藿) — rau cỏ đơn sơ của người nghèo. | Mở khoá kiến thức | Biết 藿 (hoắc) giúp nhận ra 藿香 (hoắc hương) trong tên thuốc đông y và mỹ phẩm.", "Tự nguyên_Xie": "Lục thư thông | Wiktionary ghi 藿 nghĩa là lá của cây đậu (leaves of pulse plants) — dùng làm rau ăn trong dân gian xưa. Mở rộng sang 藿香 (hoắc hương — Agastache/Patchouli, cây thuốc quan trọng trong đông y). Chữ tạo muộn, chưa có phân tích glyph từ nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lá dâu", "Hạng Tần Suất (Jun Da)": "5130.0", "Tần Suất % (Jun Da)": "99.9340478811", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 霍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹霍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "霍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藿", "Unihan_Traditional (Chữ Phồn thể)": "藿", "Pinyin_Xie": "huò", "Âm Hán Việt_Xie": "hoắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò là danh từ để chỉ các loại lá đậu hoặc cây thảo dược. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('囟', '{"9000": "5131.0", "Chữ Trung Quốc": "囟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 囗 | Số nét | 6 | nét | 囟 | tín | tượng hình | thóp đỉnh đầu trẻ sơ sinh | 囟 là chữ tượng hình — mô phỏng hình dạng thóp trên đỉnh đầu trẻ sơ sinh. Wiktionary xác nhận: {{liushu|p}} — fontanelle. Chữ độc lập, không liên quan đến 离.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tín\": 囟 là thóp (tín môn) trên đỉnh đầu — chữ vẽ thẳng cái thóp mềm của trẻ sơ sinh, nơi hộp sọ chưa liền. | Gương Hán-Việt | \"tín môn\" (囟門) — thóp đỉnh đầu trẻ sơ sinh; trong y học cổ truyền dùng để chuẩn đoán. | Mở khoá kiến thức | Biết 囟 (tín) giúp đọc thuật ngữ y học cổ truyền về nhi khoa và giải phẫu đầu.", "Tự nguyên_Xie": "Giáp cốt văn | Đại triện | Tiểu triện | Wiktionary xác nhận 囟 là chữ tượng hình ({{liushu|p}}): hình vẽ thóp trên đỉnh đầu trẻ sơ sinh (fontanelle). Ghi chú: không liên quan đến chữ 离. Xuất hiện từ thời giáp cốt văn và đại triện, cho thấy đây là chữ cổ xưa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái thóp trên đỉnh đầu", "Hạng Tần Suất (Jun Da)": "5131.0", "Tần Suất % (Jun Da)": "99.934127466", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 乂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Bao quanh toàn bộ)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴乂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "囟", "Unihan_Traditional (Chữ Phồn thể)": "囟", "Pinyin_Xie": "xìn", "Âm Hán Việt_Xie": "tín", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận thóp trên đỉnh đầu của trẻ sơ sinh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄣', '{"9000": "5132.0", "Chữ Trung Quốc": "鄣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 13 | nét | 鄣 | chương | tượng hình | tên nước cổ, che chắn | 鄣 gồm 章 (chương) và 邑/阝 (ấp, làng/vùng đất) — có thể là hình thanh. Wiktionary không cung cấp phân tích IDS cụ thể. Dùng làm tên địa danh cổ và dị thể của 障 (chướng ngại).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chương\": vùng đất (邑) mang tên Chương (章) — 鄣 là nước Chương cổ đại, và cũng là bức tường chướng ngại che chắn. | Gương Hán-Việt | \"chương\" trong \"Chương quốc\" (鄣國) — nước Chương thời Chu; đồng âm với 章 (chương). | Mở khoá kiến thức | Biết 鄣 (chương) giúp đọc sử ký về các nước chư hầu thời Xuân Thu Chiến Quốc.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 鄣 là tên địa danh cổ (nước Chương thời Chu, nay thuộc tỉnh Sơn Đông) và dị thể của 障 (che chắn, chướng ngại). Chữ gồm bộ 邑 (ấp) biểu nghĩa về địa danh. Xuất hiện trong tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Chương thời cổ (nay thuộc phía đông huyện Đông Bình, tỉnh Sơn Đông của Trung Quốc); (như: chướng 鄣)", "Hạng Tần Suất (Jun Da)": "5132.0", "Tần Suất % (Jun Da)": "99.9342070509", "GavinGrover_Once (Chiết tự trực tiếp)": "章 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰章阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "章", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄣", "Unihan_Traditional (Chữ Phồn thể)": "鄣", "Pinyin_Xie": "zhāng", "Âm Hán Việt_Xie": "chương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng chỉ địa danh cổ hoặc danh từ chung chỉ đồn lũy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('呋', '{"9000": "5133.0", "Chữ Trung Quốc": "呋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 呋 | phu | tượng hình | ký âm hóa học (furan) | 呋 là chữ ký âm hiện đại, dùng để phiên âm tên hóa học nước ngoài. Gồm bộ 口 (khẩu, miệng/phát âm) và phần âm phù. Không có cấu trúc ngữ nghĩa cổ điển.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phu\": 呋 là chữ dùng để phát âm (口) \"fu\" trong tên hóa học — gặp 呋 là biết ngay đây là từ phiên âm hóa học nước ngoài. | Gương Hán-Việt | \"phu\" — ký âm thuần túy, không có nghĩa Hán-Việt cổ; dùng trong 呋喃 (furan) và 呋喃西林. | Mở khoá kiến thức | Biết 呋 (phu) giúp nhận ra thuật ngữ hóa học 呋喃 (furan) trong tài liệu khoa học Trung văn.", "Tự nguyên_Xie": "呋 không có nguồn glyph cổ. Đây là chữ tạo muộn dùng để phiên âm tên hóa học: 呋喃 (furan — hợp chất vòng hữu cơ) và 呋喃西林 (furacilinum — thuốc kháng khuẩn). Chữ này thuần là ký âm, không có nghĩa Hán-Việt cổ điển. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: phu nôm 呋喃)", "Hạng Tần Suất (Jun Da)": "5133.0", "Tần Suất % (Jun Da)": "99.9342866358", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 夫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口夫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呋", "Unihan_Traditional (Chữ Phồn thể)": "呋", "Pinyin_Xie": "fū", "Âm Hán Việt_Xie": "phu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu kết hợp với chữ khác tạo thành danh từ ghép để phiên âm hợp chất hóa học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('婺', '{"9000": "5134.0", "Chữ Trung Quốc": "婺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 12 | nét | 敄 | mậu | biểu âm | 女 | nữ | biểu nghĩa | phụ nữ | 婺 = 敄 (Mậu, biểu âm) + 女 (Nữ, biểu nghĩa: phụ nữ); chữ hình thanh. Bộ 女 chỉ đây là chữ liên quan đến phụ nữ hoặc tên nữ tính. Dùng chủ yếu làm tên sao (婺女), tên đất (婺州) và tên sông (婺江).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không rõ reading chuẩn (âm gần \"vụ\"): người phụ nữ (女) đẹp như sao trời — 婺 là tên sao 婺女, tên đất Vụ Châu nơi có sông núi hữu tình. | Gương Hán-Việt | \"Vụ Châu\" (婺州) — tên tỉnh cổ nay là thành phố Kim Hoa, Chiết Giang; nổi tiếng với 婺剧 (kịch Vụ). | Mở khoá kiến thức | Biết 婺 (vụ) giúp đọc sử địa Chiết Giang và hiểu tên sao 婺女 trong thiên văn cổ đại.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận 婺 là chữ hình thanh: 敄 biểu âm + 女 (phụ nữ) biểu nghĩa. Nghĩa cổ là không tuân lệnh. Dùng chủ yếu trong tên địa danh và thiên văn: 婺女 (tên chòm sao), 婺州 (Vụ Châu — nay là Tỉnh Hoa, Chiết Giang), 婺江 (sông Vụ ở Giang Tây). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đẹp; (tên sao); (tên đất)", "Hạng Tần Suất (Jun Da)": "5134.0", "Tần Suất % (Jun Da)": "99.9343662208", "GavinGrover_Once (Chiết tự trực tiếp)": "敄 + 女", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敄女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "婺", "Unihan_Traditional (Chữ Phồn thể)": "婺", "Pinyin_Xie": "wù", "Âm Hán Việt_Xie": "vụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ chòm sao hoặc tính từ miêu tả vẻ đẹp của phụ nữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绱', '{"9000": "5135.0", "Chữ Trung Quốc": "绱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 绱 | thướng | tượng hình | khâu đế giày, miếng da đế giày | 绱 không có nguồn glyph cổ. Gồm bộ 糸/纟(mịch, sợi/dệt) biểu nghĩa và phần âm phù — có thể là hình thanh liên quan đến nghề may giày. Không có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thướng\": sợi chỉ (糸) khâu thướng lên đế giày — 绱 là công đoạn may đế giày, thường thấy ở thợ giày truyền thống. | Gương Hán-Việt | \"thướng\" — ít dùng; 绱鞋 (thướng hài) là khâu đế giày bằng tay. | Mở khoá kiến thức | Biết 绱 (thướng) giúp đọc văn bản về nghề thủ công truyền thống và thuật ngữ giày dép trong tiếng Trung.", "Tự nguyên_Xie": "绱 không có nguồn glyph. Chữ này chỉ miếng da dùng làm đế giày truyền thống Trung Hoa và động tác khâu đế vào giày. Đây là từ nghề thủ công, chủ yếu trong phương ngữ Bắc Kinh/miền Bắc Trung Quốc. Chữ tạo muộn, chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khâu giày; miếng da", "Hạng Tần Suất (Jun Da)": "5135.0", "Tần Suất % (Jun Da)": "99.9344458057", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 尚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟尚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绱", "Unihan_Traditional (Chữ Phồn thể)": "緔", "Pinyin_Xie": "shàng", "Âm Hán Việt_Xie": "thượng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động khâu đế vào mũ giày hoặc làm danh từ chỉ quai giày. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瓯', '{"9000": "5136.0", "Chữ Trung Quốc": "瓯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 瓦 | Số nét | 8 | nét | 區 | khu | biểu âm | vật đựng | 瓦 | ngoã | biểu nghĩa | đồ gốm, ngói | 瓯 = 區 (Khu, biểu âm: vật đựng) + 瓦 (Ngoã, biểu nghĩa: đồ gốm); chữ hình thanh. Wiktionary ghi cả ls=psc lẫn ls2=ic — có thể vừa là hình thanh vừa hội ý. Bộ 瓦 chỉ đây là đồ đựng bằng gốm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không rõ reading chuẩn (âm gần \"âu\"): đồ gốm (瓦) hình vùng (區) — 瓯 là cái âu gốm nhỏ; tên Ôn Châu (溫州) xưa gọi là Âu (甌). | Gương Hán-Việt | \"âu\" trong \"Đông Âu\" (東甌) — tên gọi cổ của vùng Ôn Châu, Chiết Giang; \"Âu Việt\" (甌越) — tên bộ tộc cổ đại ở vùng Chiết Giang-Phúc Kiến. | Mở khoá kiến thức | Biết 瓯 (âu) giúp hiểu địa danh Ôn Châu (Âu) và tên tộc người Âu Việt trong lịch sử Đông Nam Á.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận 瓯 (phồn thể 甌) là chữ hình thanh: 區 biểu âm + 瓦 (gốm) biểu nghĩa. Nghĩa là bát nhỏ, chén (bowl, cup). Mở rộng sang tên địa danh: 東甌 (Đông Âu cổ — nay là Ôn Châu, Chiết Giang). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái âu, cái bồn", "Hạng Tần Suất (Jun Da)": "5136.0", "Tần Suất % (Jun Da)": "99.9345253906", "GavinGrover_Once (Chiết tự trực tiếp)": "区 + 瓦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰区瓦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "区", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "瓦", "Unihan_Simplified (Chữ Giản thể)": "瓯", "Unihan_Traditional (Chữ Phồn thể)": "甌", "Pinyin_Xie": "ōu", "Âm Hán Việt_Xie": "âu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại vật dụng đựng nước hoặc cốc chén bằng đất nung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('旃', '{"9000": "5137.0", "Chữ Trung Quốc": "旃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 方 | Số nét | 10 | nét | 㫃 | yển | biểu nghĩa | lá cờ bay | 丹 | đan | biểu âm | 旃 = 㫃 (Yển, biểu nghĩa: lá cờ bay) + 丹 (Đan, biểu âm); chữ hình thanh. Bộ 㫃 (旗帜) chỉ đây là chữ liên quan đến cờ, lá cờ. 丹 gợi màu đỏ của lá cờ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không rõ reading chuẩn (âm gần \"chiên\"): lá cờ (㫃) đỏ đan (丹) bay trong gió — 旃 là lá cờ cổ xưa cán cong, dùng trong nghi lễ triều đình. | Gương Hán-Việt | \"chiên\" — ít dùng trong tiếng Việt hiện đại; trong văn cổ \"旃旌\" (chiên tinh) chỉ các loại cờ nghi lễ. | Mở khoá kiến thức | Biết 旃 (chiên) giúp đọc văn học cổ khi gặp các loại cờ và nghi lễ trong cung đình.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Lục thư thông | Wiktionary xác nhận 旃 là chữ hình thanh: 㫃 (lá cờ bay) biểu nghĩa + 丹 biểu âm. Nghĩa là lá cờ cán cong — loại cờ dùng trong nghi lễ cổ đại, cán uốn cong thay vì thẳng. Xuất hiện từ thời giáp cốt văn, kim văn và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái cờ cán cong", "Hạng Tần Suất (Jun Da)": "5137.0", "Tần Suất % (Jun Da)": "99.9346049755", "GavinGrover_Once (Chiết tự trực tiếp)": "方 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰方", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "旃", "Unihan_Traditional (Chữ Phồn thể)": "旃", "Pinyin_Xie": "zhān", "Âm Hán Việt_Xie": "chiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Đại từ | 代词 | Chữ này làm danh từ chỉ loại cờ cổ hoặc tấm thảm lông, đôi khi làm đại từ trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锶', '{"9000": "5138.0", "Chữ Trung Quốc": "锶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 锶 | tư | tượng hình | nguyên tố Stronti (Sr) | 锶 là dạng giản thể của 鍶, được tạo bằng cách thay bộ 釒 thành 钅. Cấu trúc phồn thể gồm 金 (kim) biểu nghĩa và phần âm phù — chữ hình thanh dùng để phiên âm tên nguyên tố hóa học.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": 锶 là kim loại (金) mang tên tư — Stronti (Sr) trong bảng tuần hoàn; gặp 锶 là nhớ ngay nguyên tố số 38. | Gương Hán-Việt | \"tư\" — ký âm hóa học; 锶 = Strontium (Sr); dùng trong thuật ngữ hóa học, y học hạt nhân. | Mở khoá kiến thức | Biết 锶 (tư) giúp đọc tài liệu hóa học và y học Trung văn khi gặp tên nguyên tố Stronti.", "Tự nguyên_Xie": "Wiktionary ghi 锶 là giản thể của 鍶, thay 釒 bằng 钅. 鍶 là chữ tạo ra để phiên âm tên nguyên tố Strontium (Sr, số nguyên tử 38) — một kim loại kiềm thổ. Đây là chữ hiện đại thuần ký âm khoa học, không có nghĩa Hán-Việt cổ điển. Chữ tạo muộn, chưa có nguồn học thuật về cấu trúc cổ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố stronti, Sr", "Hạng Tần Suất (Jun Da)": "5138.0", "Tần Suất % (Jun Da)": "99.9346845604", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 思", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅思", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "思", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锶", "Unihan_Traditional (Chữ Phồn thể)": "鍶", "Pinyin_Xie": "sī", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chuyên ngành hóa học để chỉ kim loại kiềm thổ stronti. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酩', '{"9000": "5139.0", "Chữ Trung Quốc": "酩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 13 | nét | 酩 | mỉnh | tượng hình | chữ chỉ trạng thái say rượu; chỉ dùng trong 酩酊 | 酩 thiếu dữ liệu cấu trúc rõ ràng từ Wiktionary. Nhìn hình thức chữ, bộ 酉 (Dậu, bình rượu) có thể là thành phần nghĩa, 冥 biểu âm — nhưng nguồn không xác nhận. Chữ tự lập trong văn cảnh 酩酊 (mính đính, say mèm).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mỉnh\": bộ 酉 (bình rượu) cộng âm minh — hình dung người cầm bình rượu, gọi tên mà lưỡi đã líu — đó là trạng thái 酩酊. | Gương Hán-Việt | mỉnh trong \"mính đính\" (酩酊) — say khướt | Mở khoá kiến thức | Biết 酩 mở khoá thành ngữ 酩酊大醉 (mính đính đại tuý — say bét nhè).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 酩 chỉ xuất hiện trong từ ghép 酩酊 (mính đính) với nghĩa say xỉn hoàn toàn. Wiktionary ghi {{Han etym}} nhưng không mô tả cấu trúc chi tiết. Có tiểu triện và lục thư thông, cho thấy chữ đã tồn tại từ thời Tần. Chưa có nguồn học thuật mô tả rõ hình thành. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mính đính 酩酊)", "Hạng Tần Suất (Jun Da)": "5139.0", "Tần Suất % (Jun Da)": "99.9347641453", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 名", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉名", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "名", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酩", "Unihan_Traditional (Chữ Phồn thể)": "酩", "Pinyin_Xie": "mǐng", "Âm Hán Việt_Xie": "mính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường kết hợp thành từ ghép đóng vai trò tính từ miêu tả trạng thái say mềm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恹', '{"9000": "5140.0", "Chữ Trung Quốc": "恹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 9 | nét | 恹 | yêm | tượng hình | chữ giản thể của 懨; chỉ trạng thái bơ phờ, ốm yếu | 恹 là dạng giản thể của 懨. Wiktionary không mô tả cấu trúc hình thành chi tiết. Bộ 心 (Tâm) có thể liên quan đến trạng thái tinh thần ốm yếu, nhưng nguồn không xác nhận cấu trúc psc hay ic.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yêm\": hình dung người nằm yêm ắp, không đứng dậy được — đó chính là 恹恹 (bơ phờ, ốm yếu). | Gương Hán-Việt | yêm — ít dùng độc lập trong tiếng Việt Hán học | Mở khoá kiến thức | Biết 恹 mở khoá từ 恹恹 (yêm yêm — xanh xao, thờ ơ) và 病恹恹 (bệnh yêm yêm — ốm nằm liệt).", "Tự nguyên_Xie": "恹 là chữ giản thể của 懨, chỉ trạng thái yếu ớt, bơ phờ, thoi thóp. Wiktionary dẫn sang 懨 để tra cứu phát âm và nguồn gốc. Thường xuất hiện trong 恹恹 (yānyān) — người trông xanh xao, mệt mỏi. Không có mô tả glyph origin chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bơ phờ, phờ phạc, thoi thóp", "Hạng Tần Suất (Jun Da)": "5140.0", "Tần Suất % (Jun Da)": "99.9348432134", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 厌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄厌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "恹", "Unihan_Traditional (Chữ Phồn thể)": "懨", "Pinyin_Xie": "yān", "Âm Hán Việt_Xie": "yêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả trạng thái mệt mỏi, ốm yếu hoặc tinh thần bơ phờ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逶', '{"9000": "5141.0", "Chữ Trung Quốc": "逶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 11 | nét | 逶 | uy | tượng hình | chỉ dạng uốn khúc, quanh co; dùng trong 逶迤 | 逶 thiếu dữ liệu cấu trúc từ Wiktionary (chỉ ghi {{Han etym}} không khai triển). Bộ 辶 (Sước, đi) có thể gợi ý chuyển động uốn lượn. Không xác nhận được cấu trúc hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uy\": nghĩ đến con đường uốn theo uy thế của núi non — 逶迤 là cảnh sắc quanh co hùng vĩ. | Gương Hán-Việt | uy — dùng trong 逶迤 (uy di, uốn lượn) | Mở khoá kiến thức | Biết 逶 mở khoá từ 逶迤 (uy di — quanh co, dài dằng dặc) dùng trong thơ văn cổ.", "Tự nguyên_Xie": "Tiểu triện | 逶 chỉ xuất hiện trong từ ghép 逶迤 (uy di) — con đường hay dãy núi uốn lượn, quanh co. Wiktionary ghi {{Han etym}} nhưng không mô tả chi tiết. Hình tiểu triện cho thấy chữ có mặt từ thời Tần. Chưa có nguồn học thuật xác nhận cấu trúc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: uy di 逶迤 )", "Hạng Tần Suất (Jun Da)": "5141.0", "Tần Suất % (Jun Da)": "99.9349222816", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 委", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶委", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "委", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逶", "Unihan_Traditional (Chữ Phồn thể)": "逶", "Pinyin_Xie": "wēi", "Âm Hán Việt_Xie": "uy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường kết hợp với chữ Di để tạo thành từ láy Uy di chỉ sự quanh co của đường sá. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缦', '{"9000": "5142.0", "Chữ Trung Quốc": "缦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 14 | nét | 糸 | mịch | biểu nghĩa | sợi tơ, lụa | 曼 | mạn | biểu âm | 缦 = 糸 (Mịch, biểu nghĩa: sợi tơ, lụa) + 曼 (Mạn, biểu âm); chữ hình thanh. Bộ 糸 chỉ chất liệu vải lụa, 曼 cho âm đọc màn/mạn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạn\": 糸 (tơ lụa) + 曼 (mạn — trải dài) — tấm lụa trơn nhẵn không hoa văn, trải mạn ra khắp nơi. | Gương Hán-Việt | mạn — ít dùng độc lập; xuất hiện trong 縵立 (mạn lập — đứng lâu không chuyển dịch) | Mở khoá kiến thức | Biết 缦 mở khoá 操縵 (thao mạn — luyện đàn), 縵縵 (mạn mạn — lan rộng).", "Tự nguyên_Xie": "Tiểu triện | 缦 là chữ hình thanh: 糸 (tơ, lụa) biểu nghĩa chỉ loại vải, 曼 biểu âm. Nghĩa gốc là vóc trơn, lụa không có hoa văn. Từ đó mở rộng sang nghĩa lan rộng, trải dài. Có tiểu triện xác nhận hình thức sớm. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vóc trơn, lụa trơn (không có vằn có hoa); lan rộng", "Hạng Tần Suất (Jun Da)": "5142.0", "Tần Suất % (Jun Da)": "99.9350013497", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 曼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟曼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缦", "Unihan_Traditional (Chữ Phồn thể)": "縵", "Pinyin_Xie": "màn", "Âm Hán Việt_Xie": "mạn, man", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ loại lụa mộc hoặc làm tính từ mô tả âm điệu chậm rãi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸹', '{"9000": "5143.0", "Chữ Trung Quốc": "鸹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 11 | nét | 鸹 | quát | tượng hình | chỉ loài chim; dùng trong 鸧鸹 (thương quát) | 鸹 thiếu dữ liệu cấu trúc chi tiết. Bộ 鸟 (Điểu, chim) có thể là thành phần nghĩa nhưng Wiktionary không ghi cấu trúc. Chữ dùng chủ yếu trong tên loài chim.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quát\": âm quát (la hét) gợi tiếng kêu của loài chim 鸹 — to và khắc nghiệt. | Gương Hán-Việt | quát — dùng trong 鸧鸹 (thương quát, tên chim) | Mở khoá kiến thức | Biết 鸹 mở khoá tên chim cổ 鸧鸹 trong thơ văn Trung Quốc.", "Tự nguyên_Xie": "鸹 dùng trong 鸧鸹 (thương quát) hay 鶬鴰 — tên một loài chim. Wiktionary không cung cấp mô tả glyph origin. Không có ảnh tiểu triện. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thương quát 鶬鴰,鸧鸹)", "Hạng Tần Suất (Jun Da)": "5143.0", "Tần Suất % (Jun Da)": "99.9350804178", "GavinGrover_Once (Chiết tự trực tiếp)": "舌 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舌鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鸟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舌", "Unihan_Simplified (Chữ Giản thể)": "鸹", "Unihan_Traditional (Chữ Phồn thể)": "鴰", "Pinyin_Xie": "guā", "Âm Hán Việt_Xie": "quát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng trong tên gọi các loài chim như thương quát hoặc quát tử. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螟', '{"9000": "5144.0", "Chữ Trung Quốc": "螟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 螟 | minh | tượng hình | sâu đục thân lúa; sâu minh | 螟 thiếu dữ liệu cấu trúc chi tiết từ Wiktionary. Bộ 虫 (Trùng, sâu bọ) có thể là thành phần nghĩa gợi ý loài côn trùng, phần còn lại có thể biểu âm, nhưng nguồn không xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"minh\": sâu 螟 ăn ngầm trong bóng tối như cái tên minh (tối tăm) — kẻ phá hoại vô hình trong ruộng lúa. | Gương Hán-Việt | minh trong 螟蛉 (minh linh — con nuôi; nghĩa gốc: loài sâu) | Mở khoá kiến thức | Biết 螟 mở khoá 螟蛉子 (minh linh tử — con nuôi) và 玉米螟 (ngọc mễ minh — sâu đục thân ngô).", "Tự nguyên_Xie": "Tiểu triện | 螟 chỉ loại sâu đục thân lúa (snout moth larva), gây hại cho nông nghiệp. Có tiểu triện. Wiktionary ghi {{Han etym}} nhưng không khai triển cấu trúc. 螟蛉 (minh linh) là từ ghép đặc biệt: nguyên chỉ ấu trùng sâu, sau chỉ con nuôi được nhận. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một thứ sâu trong thân lúa", "Hạng Tần Suất (Jun Da)": "5144.0", "Tần Suất % (Jun Da)": "99.9351589692", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 冥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫冥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螟", "Unihan_Traditional (Chữ Phồn thể)": "螟", "Pinyin_Xie": "míng", "Âm Hán Việt_Xie": "minh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trước để chỉ các loại sâu hại hoặc kết hợp thành từ ghép như minh linh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菟', '{"9000": "5145.0", "Chữ Trung Quốc": "菟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菟 | thỏ | tượng hình | chỉ cây tơ hồng (菟丝子), loại thực vật ký sinh | 菟 thiếu dữ liệu cấu trúc từ Wiktionary. Bộ 艹 (Thảo, cỏ) có thể là thành phần nghĩa chỉ thực vật, phần còn lại biểu âm, nhưng nguồn không xác nhận. Chỉ có lục thư thông — chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thỏ\": cây 菟 (tơ hồng) bám vào cây chủ như con thỏ bám dựa vào đồng cỏ — ký sinh sống nhờ. | Gương Hán-Việt | thỏ trong 菟丝 (thỏ ty — cây tơ hồng) | Mở khoá kiến thức | Biết 菟 mở khoá 菟丝子 (thỏ ty tử — hạt tơ hồng, dược liệu Đông y).", "Tự nguyên_Xie": "Lục thư thông | 菟 dùng chủ yếu trong 菟丝 (thỏ ty) / 菟丝子 — cây tơ hồng, một loại thực vật ký sinh leo trên cây chủ. Chỉ có lục thư thông, chưa thấy trong giáp cốt hay kim văn — chữ tạo muộn. Wiktionary không cung cấp mô tả glyph origin chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thố ty 菟絲,菟丝)", "Hạng Tần Suất (Jun Da)": "5145.0", "Tần Suất % (Jun Da)": "99.9352375205", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 兔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹兔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菟", "Unihan_Traditional (Chữ Phồn thể)": "菟", "Pinyin_Xie": "tú", "Âm Hán Việt_Xie": "thỏ, thố, đồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng trong danh từ ghép chỉ thảo dược như tho ty tử hoặc tên cổ của loài thỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阗', '{"9000": "5146.0", "Chữ Trung Quốc": "阗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 13 | nét | 門 | môn | biểu nghĩa | cửa | 眞 | chân | biểu âm | 阗 = 門 (Môn, biểu nghĩa: cửa) + 眞 (Chân, biểu âm); chữ hình thanh. Bộ 門 gợi ý không gian đầy ắp (chật ních như đầy qua cửa), 眞 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điền\": cửa 門 đầy ních người như đồng điền đầy lúa — 阗 là sự đông đúc đến tràn. | Gương Hán-Việt | điền trong 于阗 (Vu Điền — địa danh lịch sử Tân Cương) | Mở khoá kiến thức | Biết 阗 mở khoá địa danh 于阗 (Vu Điền) trong lịch sử Con đường tơ lụa.", "Tự nguyên_Xie": "Tiểu triện | 阗 là chữ hình thanh: 門 (cửa) biểu nghĩa, 眞 biểu âm. Nghĩa là đầy ních, đông đúc. Thường xuất hiện trong từ ghép 于阗 (tên địa danh lịch sử ở Tân Cương) và 填阗 (đầy ắp, nhộn nhịp). Có tiểu triện xác nhận hình thức sớm. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đầy ních", "Hạng Tần Suất (Jun Da)": "5146.0", "Tần Suất % (Jun Da)": "99.9353160718", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 真", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门真", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "真", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阗", "Unihan_Traditional (Chữ Phồn thể)": "闐", "Pinyin_Xie": "tián", "Âm Hán Việt_Xie": "điền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả cảnh tượng đông đúc hoặc làm động từ chỉ sự lấp đầy. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('濉', '{"9000": "5147.0", "Chữ Trung Quốc": "濉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 16 | nét | 濉 | tuy | tượng hình | Tuy Hà — tên sông ở An Huy, Giang Tô | 濉 thiếu dữ liệu cấu trúc và glyph origin hoàn toàn. Bộ 氵(Thuỷ, nước) có thể là thành phần nghĩa chỉ sông nước, nhưng nguồn không xác nhận cấu trúc cụ thể. Không có ảnh tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuy\": 濉 là tên sông — bộ 氵(nước) + âm tuy gợi dòng chảy yên tĩnh qua vùng Giang Hoài. | Gương Hán-Việt | tuy trong 濉河 (Tuy Hà — tên sông) | Mở khoá kiến thức | Biết 濉 mở khoá địa danh 濉溪 (Tuy Khê — thành phố ở An Huy) và 濉河 (sông Tuy).", "Tự nguyên_Xie": "濉 là tên riêng của sông Tuy Hà (Suī Hé), bắt nguồn từ tỉnh An Huy, chảy vào tỉnh Giang Tô, Trung Quốc. Không có glyph origin từ Wiktionary. Không có ảnh tiểu triện. Đây là chữ dùng để phiên âm địa danh. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tuy Hà (tên sông, bắt nguồn từ tỉnh An Huy, chảy vào tỉnh Giang Tô, Trung Quốc)", "Hạng Tần Suất (Jun Da)": "5147.0", "Tần Suất % (Jun Da)": "99.9353946232", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 睢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵睢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "睢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "濉", "Unihan_Traditional (Chữ Phồn thể)": "濉", "Pinyin_Xie": "suī", "Âm Hán Việt_Xie": "tuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng trong địa danh như sông Tuy Hà ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篑', '{"9000": "5148.0", "Chữ Trung Quốc": "篑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 15 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 貴 | quý | biểu âm | 篑 = 竹 (Trúc, biểu nghĩa: tre) + 貴 (Quý, biểu âm); chữ hình thanh. Bộ 竹 cho thấy vật dụng làm bằng tre — cái sọt đựng đất. 貴 cho âm đọc kuì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỹ\": cái sọt 篑 (Trúc + Quý) — dùng tre đan sọt quý giá để vận chuyển đất, thiếu một sọt là hỏng cả công trình lớn. | Gương Hán-Việt | quỹ trong 功亏一篑 (công khuy nhất quỹ — công lao thiếu chút mà hỏng) | Mở khoá kiến thức | Biết 篑 mở khoá thành ngữ quan trọng 功亏一篑 (công khuy nhất quỹ).", "Tự nguyên_Xie": "篑 là chữ hình thanh: 竹 (tre) biểu nghĩa chỉ vật liệu, 貴 biểu âm. Nghĩa là cái sọt tre dùng để đựng và chuyển đất trong xây dựng cổ đại. Nổi tiếng trong thành ngữ 功亏一篑 (công khuy nhất quỹ — công lao đổ sông đổ biển chỉ vì một sọt đất thiếu). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái sọt đựng đất", "Hạng Tần Suất (Jun Da)": "5148.0", "Tần Suất % (Jun Da)": "99.9354731745", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 贵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮贵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篑", "Unihan_Traditional (Chữ Phồn thể)": "簣", "Pinyin_Xie": "kuì", "Âm Hán Việt_Xie": "quỹ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong các thành ngữ cổ chỉ công việc đắp đất, xây dựng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醪', '{"9000": "5149.0", "Chữ Trung Quốc": "醪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 18 | nét | 醪 | lao | tượng hình | rượu đục, rượu chưa lọc | 醪 thiếu dữ liệu cấu trúc chi tiết từ Wiktionary. Bộ 酉 (Dậu, bình rượu) có thể là thành phần nghĩa gợi ý liên quan rượu. Có tiểu triện xác nhận. Không thể xác nhận cấu trúc psc hay ic từ nguồn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lao\": rượu 醪 còn đục như nước lao động — chưa lọc, chưa trong, nhưng đậm đà nhất. | Gương Hán-Việt | lao trong 醪糟 (lao tao — cơm rượu nếp đục) | Mở khoá kiến thức | Biết 醪 mở khoá 醪糟 (lao tao — cơm rượu nếp, món ngọt truyền thống) và 醪酒 (rượu đục).", "Tự nguyên_Xie": "Tiểu triện | 醪 chỉ loại rượu đục, rượu cái chưa lọc — rượu truyền thống châu Á còn nguyên cặn. Wiktionary ghi {{Han etym}} nhưng không khai triển. Có tiểu triện. Nổi tiếng trong thành ngữ 甘之如醴醪 (ngọt như rượu lao). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rượu đục", "Hạng Tần Suất (Jun Da)": "5149.0", "Tần Suất % (Jun Da)": "99.9355517259", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 翏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉翏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醪", "Unihan_Traditional (Chữ Phồn thể)": "醪", "Pinyin_Xie": "láo", "Âm Hán Việt_Xie": "lao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp để chỉ các loại rượu nếp lên men. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲛', '{"9000": "5150.0", "Chữ Trung Quốc": "鲛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 14 | nét | 鲛 | giao | tượng hình | cá giao, cá mập; loài cá sụn không vảy | 鲛 thiếu dữ liệu cấu trúc chi tiết. Bộ 鱼 (Ngư, cá) có thể là thành phần nghĩa, phần còn lại biểu âm. Wiktionary không khai triển cấu trúc. Có tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giao\": 鲛 (cá giao) — trong truyền thuyết, 鲛人 (giao nhân) là người cá huyền bí, nước mắt thành ngọc. | Gương Hán-Việt | giao trong 鲛人 (giao nhân — người cá trong thần thoại) và 鲛綃 (giao tiêu — vải dệt từ sợi người cá) | Mở khoá kiến thức | Biết 鲛 mở khoá 鲛人 (giao nhân — người cá huyền thoại) và 鲛綃 (giao tiêu — vải thần kỳ).", "Tự nguyên_Xie": "Tiểu triện | 鲛 chỉ loài cá mập (cá sụn không vảy) trong văn học cổ điển. Wiktionary ghi {{Han etym}} nhưng không mô tả chi tiết. Có tiểu triện. Trong thần thoại Trung Quốc, 鲛人 (giao nhân) là người cá sinh sống dưới biển, nước mắt khi khóc biến thành ngọc trai. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá giao", "Hạng Tần Suất (Jun Da)": "5150.0", "Tần Suất % (Jun Da)": "99.9356302772", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 交", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼交", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "交", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲛", "Unihan_Traditional (Chữ Phồn thể)": "鮫", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "giao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trước để tạo từ ghép chỉ các sinh vật hoặc sản phẩm liên quan đến cá mập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讦', '{"9000": "5151.0", "Chữ Trung Quốc": "讦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 5 | nét | 讦 | kiết | tượng hình | bới móc việc riêng tư của người khác; tố cáo, lật tẩy | 讦 thiếu dữ liệu cấu trúc chi tiết. Bộ 讠(Ngôn, lời nói) có thể là thành phần nghĩa gợi ý hành vi dùng lời nói để lật tẩy. Wiktionary không khai triển cấu trúc. Có tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiết\": 讦 (bộ 讠+ âm kiết) — dùng lời nói như mũi tên nhọn kiết (cắt đứt) để bới móc bí mật kẻ khác. | Gương Hán-Việt | kiết trong 攻讦 (công kiết — bới móc nhau, tấn công công khai) | Mở khoá kiến thức | Biết 讦 mở khoá 攻讦 (công kiết — phê phán, bới móc công khai), 告讦 (cáo kiết — tố cáo).", "Tự nguyên_Xie": "Tiểu triện | 讦 có nghĩa là bới móc, lật tẩy bí mật hay chuyện riêng tư của người khác một cách công khai. Wiktionary ghi {{Han etym}} nhưng không mô tả chi tiết. Có tiểu triện. Thường xuất hiện trong 攻讦 (công kiết — tấn công, bới móc nhau công khai). | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bới móc việc riêng của người khác", "Hạng Tần Suất (Jun Da)": "5151.0", "Tần Suất % (Jun Da)": "99.9357088285", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 干", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠干", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "干", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "讦", "Unihan_Traditional (Chữ Phồn thể)": "訐", "Pinyin_Xie": "jié", "Âm Hán Việt_Xie": "kiết, yết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ lỗi lầm hoặc đời tư của người khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('媪', '{"9000": "5152.0", "Chữ Trung Quốc": "媪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 12 | nét | 媪 | ảo | tượng hình | bà lão; nữ thần đất; phụ nữ lớn tuổi | 媪 là dạng đơn giản hóa của 媼 (thay 𥁕 bằng 昷). Bộ 女 (Nữ) là thành phần nghĩa chỉ phụ nữ. Phần còn lại biểu âm, nhưng Wiktionary không xác nhận cấu trúc rõ ràng. Không có ảnh tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ảo\": 媪 (bà lão) — bộ 女 cộng với âm ảo, hình dung một bà cụ lặng lẽ như sương khói, tựa nữ thần đất hiền hoà. | Gương Hán-Việt | ảo trong 媪神 (Ảo Thần — nữ thần đất), 田媪 (Điền Ảo — bà lão ngoài đồng) | Mở khoá kiến thức | Biết 媪 mở khoá từ cổ 田媪 (điền ảo — bà lão) và 媪媪 (ảo ảo — già cả, khoan thai).", "Tự nguyên_Xie": "媪 là biến thể của 媼 — bà lão, phụ nữ cao tuổi, hay nữ thần đất. Hình thức này xuất hiện trong từ điển 《重訂直音篇》 thời Minh và được Trung Quốc công nhận chính thức từ 1965. Không có glyph origin chi tiết từ Wiktionary. Chưa có nguồn học thuật xác nhận cấu trúc sớm. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bà lão; nữ thần đất", "Hạng Tần Suất (Jun Da)": "5152.0", "Tần Suất % (Jun Da)": "99.9357873799", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 昷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女昷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "媪", "Unihan_Traditional (Chữ Phồn thể)": "媼", "Pinyin_Xie": "ǎo", "Âm Hán Việt_Xie": "ẩu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ danh tính hoặc dùng độc lập để gọi tôn xưng người phụ nữ lớn tuổi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邬', '{"9000": "5153.0", "Chữ Trung Quốc": "邬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 6 | nét | 邬 | ổ | tượng hình | tên đất; họ người (Ổ) | 邬 là dạng giản thể của 鄔, đơn giản hoá bộ 烏 thành 乌. Bộ 邑/阝(Ấp, làng xóm, địa danh) là thành phần nghĩa chỉ địa danh. Phần 乌 (Ô) cho âm. Chữ chủ yếu dùng trong tên đất và họ người.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ổ\": 邬 (bộ 阝+ âm ổ) — địa danh cổ như cái ổ làng, nơi cộng đồng tụ hội. | Gương Hán-Việt | ổ trong 邬姓 (Ổ tính — họ Ổ) | Mở khoá kiến thức | Biết 邬 mở khoá họ 邬 (Ổ) và địa danh cổ 邬县 trong lịch sử Trung Quốc.", "Tự nguyên_Xie": "邬 là chữ giản thể của 鄔, thay 烏 (Ô) bằng 乌. Bộ 邑/阝chỉ địa danh, 乌 biểu âm. Dùng làm tên đất và họ người tại Trung Quốc. Không có glyph origin chi tiết. Không có ảnh tiểu triện. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất); họ Ổ", "Hạng Tần Suất (Jun Da)": "5153.0", "Tần Suất % (Jun Da)": "99.9358659312", "GavinGrover_Once (Chiết tự trực tiếp)": "乌 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰乌阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邬", "Unihan_Traditional (Chữ Phồn thể)": "鄔", "Pinyin_Xie": "wū", "Âm Hán Việt_Xie": "ổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng chỉ họ người hoặc địa danh cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('殇', '{"9000": "5154.0", "Chữ Trung Quốc": "殇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 歹 | Số nét | 9 | nét | 殇 | thương | tượng hình | chết non; mất khi còn trẻ hoặc trong chiến trận | 殇 thiếu dữ liệu cấu trúc chi tiết. Bộ 歹 (Đãi, xương chết) có thể là thành phần nghĩa gợi ý cái chết. Phần còn lại biểu âm. Wiktionary không khai triển cấu trúc. Có tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thương\": 殇 (bộ 歹+ âm thương) — cái chết đau thương nhất là chết khi còn trẻ, để lại nỗi thương không nguôi. | Gương Hán-Việt | thương trong 国殇 (Quốc Thương — thơ tưởng niệm tử sĩ của Khuất Nguyên) | Mở khoá kiến thức | Biết 殇 mở khoá 国殇 (Quốc Thương), 夭殇 (yểu thương — chết non), 战殇 (chiến thương — tử sĩ).", "Tự nguyên_Xie": "Tiểu triện | 殇 chỉ cái chết của người trẻ tuổi — chết non, chưa trưởng thành, hay chết trận. Wiktionary ghi {{Han etym}} nhưng không mô tả chi tiết. Có tiểu triện. Từ 国殇 (Quốc Thương) là tên bài thơ nổi tiếng của Khuất Nguyên tưởng niệm binh sĩ hi sinh. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chết non", "Hạng Tần Suất (Jun Da)": "5154.0", "Tần Suất % (Jun Da)": "99.9359444826", "GavinGrover_Once (Chiết tự trực tiếp)": "歹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰歹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "殇", "Unihan_Traditional (Chữ Phồn thể)": "殤", "Pinyin_Xie": "shāng", "Âm Hán Việt_Xie": "thương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc qua đời sớm hoặc làm danh từ chỉ người chết trẻ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄯', '{"9000": "5155.0", "Chữ Trung Quốc": "鄯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 14 | nét | 鄯 | thiện | tượng hình | tên đất (địa danh lịch sử Tân Cương) | 鄯 thiếu dữ liệu cấu trúc chi tiết. Bộ 邑/阝(Ấp) là thành phần nghĩa chỉ địa danh, phần còn lại biểu âm. Wiktionary không khai triển cấu trúc. Không có ảnh tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiện\": 鄯 (bộ 阝+ âm thiện) — vùng đất thiện lành, phồn thịnh trên con đường tơ lụa — đó là 鄯善. | Gương Hán-Việt | thiện trong 鄯善 (Thiện Thiện — vương quốc cổ Tân Cương) | Mở khoá kiến thức | Biết 鄯 mở khoá địa danh 鄯善 (Thiện Thiện), 鄯鄯 trong lịch sử Con đường tơ lụa.", "Tự nguyên_Xie": "鄯 là tên riêng địa danh, dùng chủ yếu trong 鄯善 (Thiện Thiện) — một vương quốc cổ trên Con đường tơ lụa ở Tân Cương, còn gọi là Lâu Lan (楼兰). Wiktionary chỉ ghi {{Han etym}} không khai triển. Không có ảnh. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "5155.0", "Tần Suất % (Jun Da)": "99.9360225171", "GavinGrover_Once (Chiết tự trực tiếp)": "善 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰善阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "善", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄯", "Unihan_Traditional (Chữ Phồn thể)": "鄯", "Pinyin_Xie": "shàn", "Âm Hán Việt_Xie": "thiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng trong lịch sử để chỉ nước Thiện Thiện cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芡', '{"9000": "5156.0", "Chữ Trung Quốc": "芡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 欠 | khiếm | biểu âm | 芡 = 艹 (Thảo, biểu nghĩa: cỏ, thực vật) + 欠 (Khiếm, biểu âm); chữ hình thanh. Bộ 艹 xác nhận đây là thực vật, 欠 cho âm đọc qiàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiếm\": 艹 (cỏ nước) + 欠 (khiếm — thiếu, lạnh) — cây 芡 lơ lửng trên mặt nước như thứ cỏ chưa đủ đất bám rễ. | Gương Hán-Việt | khiếm trong 芡实 (Khiếm Thực — hạt kê đầu tử, dược liệu) | Mở khoá kiến thức | Biết 芡 mở khoá 芡实 (khiếm thực — dược liệu) và 打芡 (đả khiếm — kỹ thuật làm sốt đặc).", "Tự nguyên_Xie": "Tiểu triện | 芡 là chữ hình thanh: 艹 (cỏ, thực vật) biểu nghĩa, 欠 biểu âm. Chỉ cây kê đầu tử (Euryale ferox) — loài thuỷ sinh họ hoa súng có gai. Hạt 芡实 (qiàn shí) là dược liệu và thực phẩm. Trong nấu ăn, 打芡 là kỹ thuật dùng bột đao (tinh bột) để làm sốt đặc lại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ súng, kê đầu tử", "Hạng Tần Suất (Jun Da)": "5156.0", "Tần Suất % (Jun Da)": "99.9361005517", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 欠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹欠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "欠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芡", "Unihan_Traditional (Chữ Phồn thể)": "芡", "Pinyin_Xie": "qiàn", "Âm Hán Việt_Xie": "khiếm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ cây khiếm thực hoặc bột năng làm nước sốt sệt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嫠', '{"9000": "5157.0", "Chữ Trung Quốc": "嫠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 14 | nét | 女 | nữ | biểu nghĩa | phụ nữ | 嫠 = 𠩺 (biểu âm) + 女 (Nữ, biểu nghĩa: phụ nữ); chữ hình thanh. Bộ 女 xác nhận đây là chữ liên quan đến phụ nữ. 𠩺 là thành phần ít phổ biến, cho âm đọc lí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"li\": 嫠 (Nữ + âm li — lìa) — người phụ nữ li biệt chồng do cái chết, phải tự mình gánh vác gia đình. | Gương Hán-Việt | li trong 嫠妇 (Li Phụ — quả phụ, người goá chồng) | Mở khoá kiến thức | Biết 嫠 mở khoá từ cổ 嫠妇 (li phụ — bà goá), 嫠节 (li tiết — tiết hạnh của bà goá).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 嫠 là chữ hình thanh: 女 (phụ nữ) biểu nghĩa, 𠩺 biểu âm. Chỉ người đàn bà goá, quả phụ — người phụ nữ mất chồng phải một mình nuôi con. Có tiểu triện và lục thư thông xác nhận hình thức sớm. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quả phụ; bà goá; ở goá", "Hạng Tần Suất (Jun Da)": "5157.0", "Tần Suất % (Jun Da)": "99.9361785862", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "嫠", "Unihan_Traditional (Chữ Phồn thể)": "嫠", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "li", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với các từ khác để chỉ người phụ nữ góa chồng như trong từ li phụ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肼', '{"9000": "5158.0", "Chữ Trung Quốc": "肼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 8 | nét | ⺼ | nhục | biểu nghĩa | thịt (dạng viết tắt của bộ 肉) | 井 | tỉnh | biểu âm | 肼 = ⺼ (Nhục, biểu nghĩa: thịt/cơ thể) + 井 (Tỉnh, biểu âm); chữ hình thanh. Bộ ⺼ xuất hiện vì đây là tên hoá học dùng bộ liên quan cơ thể, 井 cho âm đọc jǐng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỉnh\": ⺼ (thân thể) + 井 (tỉnh — giếng) — hydrazine 肼 như chất lỏng dưới giếng sâu, không màu nhưng có độc. | Gương Hán-Việt | tỉnh trong 肼 (tỉnh — hydrazine, chất hoá học) | Mở khoá kiến thức | Biết 肼 mở khoá 联氨/肼 (liên amine/hydrazine) trong hoá học công nghiệp và tên lửa.", "Tự nguyên_Xie": "肼 là chữ mới tạo để phiên âm tên hoá chất hydrazine (N₂H₄) trong tiếng Trung. Chữ hình thanh: ⺼ (nhục/thể) biểu nghĩa (vật chất/hoá học), 井 biểu âm. Không có hình thức tiểu triện — chữ tạo muộn trong thời hiện đại để phục vụ khoa học kỹ thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hydradin (hoá học)", "Hạng Tần Suất (Jun Da)": "5158.0", "Tần Suất % (Jun Da)": "99.9362566208", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 井", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月井", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "井", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "肼", "Unihan_Traditional (Chữ Phồn thể)": "肼", "Pinyin_Xie": "jǐng", "Âm Hán Việt_Xie": "tỉnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chuyên ngành hóa học để gọi tên hợp chất hữu cơ chứa nitơ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('峤', '{"9000": "5159.0", "Chữ Trung Quốc": "峤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 9 | nét | 峤 | kiều | tượng hình | đỉnh núi cao và nhọn; đường núi | 峤 thiếu dữ liệu cấu trúc chi tiết. Bộ 山 (Sơn, núi) có thể là thành phần nghĩa, phần còn lại biểu âm — nhưng Wiktionary không khai triển cấu trúc. Không có ảnh tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiều\": bộ 山 (núi) + âm kiều (cao vút như cầu) — đỉnh 峤 nhọn sắc, vút lên như cây kiều giữa trời. | Gương Hán-Việt | kiều trong 海峤 (Hải Kiều — vùng ven biển, Phúc Kiến, Quảng Đông) | Mở khoá kiến thức | Biết 峤 mở khoá 海峤 (hải kiều — miền duyên hải phía nam), 岭峤 (lĩnh kiều — đèo núi).", "Tự nguyên_Xie": "峤 chỉ đỉnh núi cao và nhọn, hay con đường đèo trong núi. Wiktionary ghi {{Han etym}} nhưng không mô tả chi tiết. Không có ảnh tiểu triện. Thường xuất hiện trong từ ghép địa lý và thơ văn cổ. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "núi cao mà nhọn", "Hạng Tần Suất (Jun Da)": "5159.0", "Tần Suất % (Jun Da)": "99.9363346553", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 乔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山乔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "峤", "Unihan_Traditional (Chữ Phồn thể)": "嶠", "Pinyin_Xie": "jiào", "Âm Hán Việt_Xie": "kiều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn thơ để miêu tả các đỉnh núi cao hiểm trở. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矽', '{"9000": "5160.0", "Chữ Trung Quốc": "矽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 8 | nét | 石 | thạch | biểu nghĩa | đá | 夕 | tịch | biểu âm | 矽 = 石 (Thạch, biểu nghĩa: đá) + 夕 (Tịch, biểu âm); chữ hình thanh. Bộ 石 xác nhận đây là nguyên tố khoáng chất, 夕 cho âm đọc xī (si).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thạch\": 石 (đá) + 夕 (tịch — buổi chiều, âm xī) — nguyên tố 矽 (silicon) ẩn trong đá núi, lặng lẽ như buổi chiều tịch mịch. | Gương Hán-Việt | tịch trong 矽石 (tịch thạch — đá silic, quartz) | Mở khoá kiến thức | Biết 矽 mở khoá 矽石 (tịch thạch — đá silic), 矽肺 (tịch phế — bệnh bụi phổi silic).", "Tự nguyên_Xie": "矽 là chữ hình thanh tạo ra để phiên âm tên nguyên tố silicon (Si) trong tiếng Trung Quốc. 石 (đá) biểu nghĩa vì silicon là nguyên tố khoáng trong đất đá, 夕 biểu âm (âm xī). Silicon chiếm gần 28% vỏ trái đất — nguyên tố dồi dào thứ hai. Đây là chữ hiện đại, không có hình thức tiểu triện cổ đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố silic, Si", "Hạng Tần Suất (Jun Da)": "5160.0", "Tần Suất % (Jun Da)": "99.9364121731", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 夕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石夕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "矽", "Unihan_Traditional (Chữ Phồn thể)": "矽", "Pinyin_Xie": "xì", "Âm Hán Việt_Xie": "tịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong hóa học và công nghiệp để chỉ nguyên tố silic hoặc bụi silic. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讧', '{"9000": "5161.0", "Chữ Trung Quốc": "讧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 5 | nét | 讧 | hồng | tượng hình | loạn, rối loạn; bất hoà nội bộ | 讧 thiếu dữ liệu cấu trúc chi tiết từ Wiktionary. Bộ 讠(Ngôn, lời nói) có thể là thành phần nghĩa gợi ý tranh luận, cãi vã. Có tiểu triện. Wiktionary không khai triển cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồng\": bộ 讠(lời nói) + âm hồng (to lớn, ồn ào) — 讧 là tiếng ồn ào hỗn loạn của nội bộ đang đấu đá nhau. | Gương Hán-Việt | hồng trong 内讧 (Nội Hồng — đánh nhau trong nội bộ) | Mở khoá kiến thức | Biết 讧 mở khoá 内讧 (nội hồng — tranh giành quyền lực nội bộ), quan trọng trong chính trị.", "Tự nguyên_Xie": "Tiểu triện | 讧 chỉ sự hỗn loạn, bất hoà, rối ren bên trong — đặc biệt trong 内讧 (nội hồng — đánh nhau trong nội bộ). Wiktionary ghi {{Han etym}} nhưng không khai triển. Có tiểu triện. Chữ văn học, ít dùng độc lập. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "loạn, rối loạn, lủng củng", "Hạng Tần Suất (Jun Da)": "5161.0", "Tần Suất % (Jun Da)": "99.9364896909", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 工", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠工", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "工", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "讧", "Unihan_Traditional (Chữ Phồn thể)": "訌", "Pinyin_Xie": "hòng", "Âm Hán Việt_Xie": "hồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ hoặc danh từ trong cụm từ chỉ sự tranh chấp nội bộ như nội hồng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掼', '{"9000": "5162.0", "Chữ Trung Quốc": "掼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 手 | thủ | biểu nghĩa | tay | 貫 | quán | biểu âm | 掼 = 手 (Thủ, biểu nghĩa: tay) + 貫 (Quán, biểu âm); chữ hình thanh. Bộ 手 xác nhận hành động dùng tay, 貫 cho âm đọc guàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quán\": tay (手) + quán (xuyên thấu) — ném 掼 thứ gì đó mạnh đến mức xuyên qua không khí, đánh sầm xuống đất. | Gương Hán-Việt | quán trong 掼跤 (Quán Giao — môn vật dân gian Trung Quốc) | Mở khoá kiến thức | Biết 掼 mở khoá 掼跤 (quán giao — môn vật cổ truyền), 掼蛋 (quán đản — tên trò chơi bài).", "Tự nguyên_Xie": "Tiểu triện | 掼 là chữ hình thanh: 手 (tay) biểu nghĩa, 貫 biểu âm. Nghĩa chính là quật xuống, ném mạnh xuống đất. Có tiểu triện. Dùng nhiều trong phương ngữ Giang Nam (Thượng Hải) với nghĩa ném bỏ, quăng đi. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quật xuống, đánh đổ", "Hạng Tần Suất (Jun Da)": "5162.0", "Tần Suất % (Jun Da)": "99.9365672086", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 贯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌贯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "掼", "Unihan_Traditional (Chữ Phồn thể)": "摜", "Pinyin_Xie": "guàn", "Âm Hán Việt_Xie": "quán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ biểu thị hành động ném mạnh hoặc quật một vật xuống đất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('焖', '{"9000": "5163.0", "Chữ Trung Quốc": "焖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 11 | nét | 焖 | muộn | tượng hình | đun hầm kín; nấu trong nồi đậy nắp | 焖 thiếu dữ liệu glyph origin và cấu trúc hoàn toàn. Bộ 火 (Hoả, lửa) có thể là thành phần nghĩa gợi ý nấu nướng. Không có ảnh tiểu triện. Chưa thể xác nhận cấu trúc. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"muộn\": lửa (火) âm thầm, đậy nắp muộn (kín bưng) — 焖 là cách nấu chậm rãi, giữ trọn hơi thơm. | Gương Hán-Việt | muộn trong 焖饭 (muộn phạn — cơm nấu kín), 焖鸡 (muộn kê — gà hầm kín) | Mở khoá kiến thức | Biết 焖 mở khoá 焖饭 (muộn phạn — cơm kho), 焖肉 (muộn nhục — thịt hầm kín).", "Tự nguyên_Xie": "焖 chỉ kỹ thuật nấu ăn: đun trong nồi đậy kín bằng lửa nhỏ để giữ hơi nước bên trong — như kiểu hầm, kho. Không có glyph origin từ Wiktionary. Không có ảnh tiểu triện. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đun, hầm", "Hạng Tần Suất (Jun Da)": "5163.0", "Tần Suất % (Jun Da)": "99.9366447264", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 闷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火闷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "闷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "焖", "Unihan_Traditional (Chữ Phồn thể)": "燜", "Pinyin_Xie": "mèn", "Âm Hán Việt_Xie": "muộn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ phương pháp nấu ăn đậy kín nắp và đun nhỏ lửa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('愆', '{"9000": "5164.0", "Chữ Trung Quốc": "愆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 13 | nét | 衍 | diễn | biểu âm | 心 | tâm | biểu nghĩa | tim, tâm | 愆 = 衍 (Diễn, biểu âm) + 心 (Tâm, biểu nghĩa: tim); chữ hình thanh. Bộ 心 xác nhận chữ liên quan đến nội tâm, tội lỗi xuất phát từ tâm. 衍 cho âm đọc qiān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiền\": 衍 (diễn — lan tràn) + 心 (tâm — tâm can) — tội lỗi 愆 lan tràn từ trong tâm ra, không giữ được. | Gương Hán-Việt | khiền trong 愆尤 (Khiền Vưu — tội lỗi, sai lầm), 愆期 (Khiền Kỳ — trễ hạn) | Mở khoá kiến thức | Biết 愆 mở khoá 愆尤 (khiền vưu — lỗi lầm), 愆期 (khiền kỳ — lỡ hẹn, trễ kỳ hạn).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 愆 là chữ hình thanh: 衍 biểu âm, 心 (tâm, tim) biểu nghĩa. Nghĩa gốc là tội lỗi, sai lầm xuất phát từ lòng người. Cũng có nghĩa vượt quá, trễ hạn. Có hình kim văn và tiểu triện — chứng tỏ là chữ cổ. Thường xuất hiện trong 愆期 (khiền kỳ — trễ hạn) và 愆尤 (khiền vưu — tội lỗi). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tội lỗi, sai lầm", "Hạng Tần Suất (Jun Da)": "5164.0", "Tần Suất % (Jun Da)": "99.9367222442", "GavinGrover_Once (Chiết tự trực tiếp)": "衍 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱衍心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "衍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "愆", "Unihan_Traditional (Chữ Phồn thể)": "愆", "Pinyin_Xie": "qiān", "Âm Hán Việt_Xie": "khiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ lỗi lầm hoặc làm động từ chỉ sự trễ nải, quá hạn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聩', '{"9000": "5165.0", "Chữ Trung Quốc": "聩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 15 | nét | 耳 | nhĩ | biểu nghĩa | tai | 貴 | quý | biểu âm | 聩 = 耳 (Nhĩ, biểu nghĩa: tai) + 貴 (Quý, biểu âm); chữ hình thanh. Bộ 耳 xác nhận chữ liên quan đến thính giác, 貴 cho âm đọc kuì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỹ\": tai (耳) + quý (貴) — nghe mà không hiểu như người điếc — 聩 là trạng thái mê muội quý giá nhất cần phải phá vỡ. | Gương Hán-Việt | quỹ trong 振聋发聩 (Chấn Long Phát Quỹ — làm tỉnh thức người mê muội) | Mở khoá kiến thức | Biết 聩 mở khoá 振聋发聩 (chấn long phát quỹ — tiếng sấm đánh thức kẻ điếc, nghĩa bóng: lời nói gây chấn động).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 聩 là chữ hình thanh: 耳 (tai) biểu nghĩa, 貴 biểu âm. Nghĩa gốc là điếc — tai không nghe được. Nghĩa mở rộng là mê muội, không hiểu biết. Có đại triện và tiểu triện. Nổi tiếng trong thành ngữ 振聋发聩 (chấn long phát quỹ — làm tỉnh thức kẻ điếc mù, gây chấn động tinh thần). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "điếc (tai)", "Hạng Tần Suất (Jun Da)": "5165.0", "Tần Suất % (Jun Da)": "99.936799762", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 贵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳贵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聩", "Unihan_Traditional (Chữ Phồn thể)": "聵", "Pinyin_Xie": "kuì", "Âm Hán Việt_Xie": "hội", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường làm tính từ bổ nghĩa cho danh từ hoặc kết hợp trong thành ngữ để chỉ trạng thái điếc tai. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('岘', '{"9000": "5166.0", "Chữ Trung Quốc": "岘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 7 | nét | 山 | sơn | biểu nghĩa | núi | 見 | kiến | biểu âm | 岘 = 山 (Sơn, biểu nghĩa: núi) + 見 (Kiến, biểu âm); chữ hình thanh. Bộ 山 xác nhận đây là địa danh núi, 見 cho âm đọc xiàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiện\": 山 (núi) + 見 (hiện — nhìn thấy) — ngọn núi 岘 là nơi bạn nhìn thấy cả một vùng núi đồng rộng lớn. | Gương Hán-Việt | hiện trong 峴港 (Hiện Cảng — tên Hán của Đà Nẵng) | Mở khoá kiến thức | Biết 岘 mở khoá địa danh 峴港 (Hiện Cảng = Đà Nẵng) và 岘山 (Hiện Sơn, Hồ Bắc).", "Tự nguyên_Xie": "岘 là chữ hình thanh: 山 (núi) biểu nghĩa, 見 biểu âm. Chỉ tên núi Hiện Sơn (岘山) ở phía nam Tương Dương, Hồ Bắc. Dùng chủ yếu trong địa danh 岘山 và 峴港 (Đà Nẵng — tên Hán). Không có ảnh tiểu triện. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên núi)", "Hạng Tần Suất (Jun Da)": "5166.0", "Tần Suất % (Jun Da)": "99.9368772797", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 见", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山见", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "见", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岘", "Unihan_Traditional (Chữ Phồn thể)": "峴", "Pinyin_Xie": "xiàn", "Âm Hán Việt_Xie": "hiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng trong địa danh hoặc tên núi cụ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靛', '{"9000": "5167.0", "Chữ Trung Quốc": "靛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 青 | Số nét | 16 | nét | 靛 | điến | tượng hình | thuốc nhuộm màu xanh indigo; màu xanh chàm | 靛 thiếu dữ liệu cấu trúc chi tiết từ Wiktionary. Bộ 青 (Thanh, màu xanh lam) có thể là thành phần nghĩa gợi ý màu sắc, phần còn lại biểu âm. Wiktionary không khai triển cấu trúc. Không có ảnh tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điến\": 靛 là màu chàm điến — sâu thẳm, lặng lẽ giữa xanh và tím trên cầu vồng. | Gương Hán-Việt | điến trong 靛青 (Điến Thanh — màu chàm xanh), 靛蓝 (Điến Lam — indigo) | Mở khoá kiến thức | Biết 靛 mở khoá 靛蓝 (điến lam — màu indigo), 靛青 (điến thanh — màu chàm), 靛染 (nhuộm chàm).", "Tự nguyên_Xie": "靛 chỉ màu chàm (indigo) — màu xanh tím đặc trưng từ cây chàm. Wiktionary ghi {{Han etym}} nhưng không mô tả chi tiết. Không có ảnh tiểu triện. Trong ngũ sắc cầu vồng tiếng Trung, 靛 là màu thứ sáu (红橙黄绿蓝靛紫). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thuốc nhuộm xanh", "Hạng Tần Suất (Jun Da)": "5167.0", "Tần Suất % (Jun Da)": "99.9369542807", "GavinGrover_Once (Chiết tự trực tiếp)": "青 + 定", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰青定", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "定", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "青", "Unihan_Simplified (Chữ Giản thể)": "靛", "Unihan_Traditional (Chữ Phồn thể)": "靛", "Pinyin_Xie": "diàn", "Âm Hán Việt_Xie": "điện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ chất nhuộm hoặc tính từ chỉ màu sắc xanh chàm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菖', '{"9000": "5168.0", "Chữ Trung Quốc": "菖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菖 | xương | tượng hình | xương bồ (菖蒲) — loài cây cỏ thơm | 菖 thiếu dữ liệu cấu trúc chi tiết. Bộ 艹 (Thảo, cỏ) có thể là thành phần nghĩa chỉ thực vật, phần còn lại biểu âm. Wiktionary không khai triển cấu trúc. Không có ảnh tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xương\": 菖 (bộ cỏ + âm xương) — cây xương bồ 菖蒲 như xương sống của lễ Đoan Ngọ, cắm cửa trừ tà. | Gương Hán-Việt | xương trong 菖蒲 (Xương Bồ — cây cỏ thơm, dùng dịp Đoan Ngọ) | Mở khoá kiến thức | Biết 菖 mở khoá 菖蒲 (xương bồ — cây thảo dược) và 唐菖蒲 (đường xương bồ — hoa lay ơn).", "Tự nguyên_Xie": "菖 chỉ dùng trong 菖蒲 (xương bồ, Acorus calamus) — cây cỏ thơm mọc ven sông, dùng trong y học và lễ Đoan Ngọ (cắm 菖蒲 ở cửa để tránh tà). Wiktionary ghi {{Han etym}} nhưng không khai triển. Không có ảnh tiểu triện. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: xương bồ 菖蒲)", "Hạng Tần Suất (Jun Da)": "5168.0", "Tần Suất % (Jun Da)": "99.9370312817", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 昌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹昌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菖", "Unihan_Traditional (Chữ Phồn thể)": "菖", "Pinyin_Xie": "chāng", "Âm Hán Việt_Xie": "xương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ khác để tạo thành danh từ chỉ một loại cây thân thảo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('卟', '{"9000": "5169.0", "Chữ Trung Quốc": "卟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 5 | nét | 口 | khẩu | biểu nghĩa | miệng | 卜 | bốc | biểu nghĩa | 卟 = 口 (Khẩu, biểu nghĩa: miệng) + 卜 (Bốc); chữ hội ý. Wiktionary ghi Han compound ls=ic. Hình thức dùng 口 (miệng/âm thanh) + 卜 — nhưng nghĩa hiện đại là tên phiên âm của porphyrin trong hoá học.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bốc\": 口 (miệng) + 卜 (bốc toán) — nhà bói miệng nói ra những âm tiết kỳ lạ như \"por-phin\" — đó là cách nhớ 卟 là tên hoá chất porphyrin. | Gương Hán-Việt | bốc trong 卟啉 (Bốc Lâm — porphyrin, hợp chất hoá học sinh học) | Mở khoá kiến thức | Biết 卟 mở khoá 卟啉 (bốc lâm — porphyrin, cấu trúc nền của chlorophyll và hemoglobin).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 卟 là chữ hội ý gồm 口 (khẩu) + 卜 (bốc), theo Wiktionary ghi ls=ic. Trong hình thức cổ (kim văn, tiểu triện), chữ có nghĩa là bói toán. Nghĩa hiện đại hoàn toàn khác: dùng để phiên âm \"por\" trong porphyrin (卟啉 — poóc-phin, hợp chất hữu cơ quan trọng trong sinh học, như hemoglobin). Hai nghĩa không liên quan trực tiếp. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "poóc-phin", "Hạng Tần Suất (Jun Da)": "5169.0", "Tần Suất % (Jun Da)": "99.9371082827", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 卜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口卜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "卟", "Unihan_Traditional (Chữ Phồn thể)": "卟", "Pinyin_Xie": "bǔ", "Âm Hán Việt_Xie": "kê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ ghép trong thuật ngữ hóa học để chỉ hợp chất hữu cơ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('姒', '{"9000": "5170.0", "Chữ Trung Quốc": "姒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 7 | nét | 姒 | tự | tượng hình | chị dâu (vợ của anh chồng); họ cổ | 姒 thiếu dữ liệu cấu trúc chi tiết từ Wiktionary. Bộ 女 (Nữ) có thể là thành phần nghĩa chỉ phụ nữ, phần còn lại biểu âm. Chỉ có lục thư thông — chữ tạo muộn. Wiktionary không khai triển cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tự\": 姒 (bộ 女 + âm tự) — người chị dâu tự nhiên trở thành chỗ dựa trong gia đình, như chữ tự (tự mình đứng vững). | Gương Hán-Việt | tự trong 姒姓 (Tự Tính — họ của vua Đại Vũ, nhà Hạ) | Mở khoá kiến thức | Biết 姒 mở khoá 姒姓 (họ nhà Hạ), 娣姒 (đệ tự — chị em dâu), quan trọng trong lịch sử cổ đại.", "Tự nguyên_Xie": "Lục thư thông | 姒 có nghĩa là chị dâu — vợ của anh chồng (嫂子). Cũng là họ cổ (姒姓) của vua Đại Vũ và nhà Hạ. Chỉ có lục thư thông — chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Wiktionary không khai triển cấu trúc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chị dâu", "Hạng Tần Suất (Jun Da)": "5170.0", "Tần Suất % (Jun Da)": "99.9371852837", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 以", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女以", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "以", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "姒", "Unihan_Traditional (Chữ Phồn thể)": "姒", "Pinyin_Xie": "sì", "Âm Hán Việt_Xie": "tự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ xưng hô trong gia đình thời cổ hoặc kết hợp thành từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('杷', '{"9000": "5171.0", "Chữ Trung Quốc": "杷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 8 | nét | 杷 | ba | tượng hình | cái cào cỏ, bồ cào; dùng trong 枇杷 (tỳ bà) | 杷 thiếu dữ liệu cấu trúc chi tiết. Bộ 木 (Mộc, gỗ) có thể là thành phần nghĩa chỉ công cụ làm bằng gỗ. Wiktionary không khai triển cấu trúc. Có tiểu triện và lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ba\": bộ 木 (gỗ) + âm ba — cái cào gỗ đơn giản, ba chiếu ra như ngón tay, thu góp rơm về. | Gương Hán-Việt | ba trong 枇杷 (Tỳ Ba — quả hoa lộc), 铁杷 (Thiết Ba — cào sắt) | Mở khoá kiến thức | Biết 杷 mở khoá 枇杷 (tỳ ba — quả loquat/hoa lộc) và 铁杷 (thiết ba — cào sắt nông nghiệp).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 杷 có hai nghĩa chính: (1) cái cào cỏ, bồ cào (nông cụ), (2) dùng trong 枇杷 (tỳ bà) — quả hoa lộc, loài cây ăn quả. Wiktionary không khai triển cấu trúc. Có tiểu triện và lục thư thông. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bồ cào, cái cào cỏ", "Hạng Tần Suất (Jun Da)": "5171.0", "Tần Suất % (Jun Da)": "99.9372622847", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 巴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木巴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "杷", "Unihan_Traditional (Chữ Phồn thể)": "杷", "Pinyin_Xie": "pá", "Âm Hán Việt_Xie": "ba, bà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ công cụ nông nghiệp hoặc loại cây ăn quả. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砉', '{"9000": "5172.0", "Chữ Trung Quốc": "砉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 9 | nét | 砉 | hoạch | tượng hình | tiếng răng rắc, tiếng soạt nhanh | 砉 thiếu dữ liệu cấu trúc chi tiết từ Wiktionary. Bộ 石 (Thạch, đá) có thể là thành phần nghĩa gợi ý âm thanh vật rắn. Wiktionary không khai triển cấu trúc. Không có ảnh tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoạch\": 砉 — âm thanh của lưỡi dao hoạch qua xương, soạt một cái dứt khoát — đúng cảnh Trang Tử tả nghề mổ trâu. | Gương Hán-Việt | hoạch trong 砉然 (Hoạch Nhiên — tiếng soạt, từ Trang Tử) | Mở khoá kiến thức | Biết 砉 mở khoá đoạn văn Trang Tử 砉然响然 mô tả tiếng mổ trâu — biểu tượng của kỹ năng đạt đỉnh.", "Tự nguyên_Xie": "砉 là từ tượng thanh chỉ âm thanh vật gì đó bay qua nhanh hay vỡ ra — tiếng soạt, tiếng răng rắc, tiếng toạc. Wiktionary không cung cấp glyph origin. Không có ảnh tiểu triện. Nổi tiếng trong văn bản Trang Tử: 砉然响然 (tiếng dao mổ trâu kêu soạt soạt). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "răng rắc, sột, toạc", "Hạng Tần Suất (Jun Da)": "5172.0", "Tần Suất % (Jun Da)": "99.9373392856", "GavinGrover_Once (Chiết tự trực tiếp)": "丰 + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱丰石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砉", "Unihan_Traditional (Chữ Phồn thể)": "砉", "Pinyin_Xie": "huò", "Âm Hán Việt_Xie": "hoạch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Dùng làm từ tượng thanh mô tả âm thanh sắc bén, nhanh gọn khi cắt xẻ. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袢', '{"9000": "5173.0", "Chữ Trung Quốc": "袢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 袢 | phán | tượng hình | khuyết áo, dải vải cài nút | 袢 thiếu dữ liệu cấu trúc chi tiết từ Wiktionary. Bộ 衣/衤(Y, áo) có thể là thành phần nghĩa chỉ trang phục. Wiktionary không khai triển cấu trúc. Có tiểu triện và lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phán\": bộ 衤(áo) + âm phán — dải áo phán xét chiếc áo có đẹp hay không là cái khuyết cài nút cẩn thận. | Gương Hán-Việt | phán trong 盘袢 (Bàn Phán — nút bấm kiểu Trung Quốc) | Mở khoá kiến thức | Biết 袢 mở khoá 盘袢 (bàn phán — loại nút vải truyền thống Trung Quốc trên sườn xám).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 袢 chỉ phần khuyết áo hay dải vải dùng để cài cúc áo. Wiktionary ghi {{Han etym}} nhưng không mô tả chi tiết. Có tiểu triện và lục thư thông. Chữ ít dùng, chủ yếu trong từ ghép 盘袢 (bàn phán — nút bấm kiểu Trung Quốc). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái khuyết áo, dải áo", "Hạng Tần Suất (Jun Da)": "5173.0", "Tần Suất % (Jun Da)": "99.9374162866", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 半", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤半", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "半", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袢", "Unihan_Traditional (Chữ Phồn thể)": "袢", "Pinyin_Xie": "pàn", "Âm Hán Việt_Xie": "phán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Dùng làm danh từ chỉ chi tiết trên trang phục hoặc tính từ chỉ thời tiết oi bức. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚋', '{"9000": "5174.0", "Chữ Trung Quốc": "蚋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 10 | nét | 虫 | trùng | biểu nghĩa | côn trùng | 內 | nội | biểu âm | 蚋 = 虫 (Trùng, biểu nghĩa: côn trùng) + 內 (Nội, biểu âm); chữ hình thanh. Bộ 虫 xác nhận đây là loài côn trùng, 內 cho âm đọc ruì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nội\": 虫 (côn trùng) + 內 (nội — bên trong) — con 蚋 nhỏ bé, bò vào mọi ngóc ngách bên trong để cắn. | Gương Hán-Việt | nội trong 蚊蚋 (Văn Nội — muỗi và ruồi đen) | Mở khoá kiến thức | Biết 蚋 mở khoá 蚊蚋 (văn nội — muỗi và ruồi đen, hai loại côn trùng hút máu).", "Tự nguyên_Xie": "蚋 là chữ hình thanh: 虫 (côn trùng) biểu nghĩa, 內 biểu âm. Chỉ loài ruồi đen cắn (black fly, họ Simuliidae) — côn trùng nhỏ cắn mạnh, sống ven sông. Wiktionary có mô tả cấu trúc nhưng không có ảnh tiểu triện. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ve", "Hạng Tần Suất (Jun Da)": "5174.0", "Tần Suất % (Jun Da)": "99.9374932876", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 内", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫内", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "内", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚋", "Unihan_Traditional (Chữ Phồn thể)": "蚋", "Pinyin_Xie": "ruì", "Âm Hán Việt_Xie": "nhuế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại côn trùng nhỏ hút máu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笳', '{"9000": "5175.0", "Chữ Trung Quốc": "笳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 笳 | già | tượng hình | kèn lá, nhạc cụ bằng lá cỏ; sáo hồ | 笳 thiếu dữ liệu glyph origin và cấu trúc hoàn toàn. Bộ 竹 (Trúc, tre) có thể là thành phần nghĩa gợi ý nhạc cụ, phần còn lại biểu âm — nhưng Wiktionary không cung cấp thông tin. Không có ảnh tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"già\": 笳 (kèn già) — tiếng kèn lá già dặn, ai oán, vang lên từ thảo nguyên xa xăm trong đêm chiến trận. | Gương Hán-Việt | già trong 胡笳 (Hồ Già — nhạc cụ du mục), 笳声 (già thanh — tiếng kèn lá) | Mở khoá kiến thức | Biết 笳 mở khoá 胡笳十八拍 (Hồ Già Thập Bát Phách — áng thơ nhạc bất hủ của Thái Văn Cơ).", "Tự nguyên_Xie": "笳 chỉ nhạc cụ dùng trong quân đội du mục — sáo lá, kèn làm từ lá cỏ (Hồ gia, 胡笳). Không có glyph origin từ Wiktionary. Không có ảnh tiểu triện. Nổi tiếng trong thơ Thái Văn Cơ 《胡笳十八拍》(Hồ Già Thập Bát Phách) — bản nhạc thể hiện nỗi cô đơn bị bắt làm tù nhân. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái kèn lá", "Hạng Tần Suất (Jun Da)": "5175.0", "Tần Suất % (Jun Da)": "99.9375702886", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 加", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮加", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "加", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笳", "Unihan_Traditional (Chữ Phồn thể)": "笳", "Pinyin_Xie": "jiā", "Âm Hán Việt_Xie": "gia", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ nhạc cụ thổi trong thơ ca cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('挈', '{"9000": "5176.0", "Chữ Trung Quốc": "挈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 10 | nét | 㓞 | khiết | biểu âm | 手 | thủ | biểu nghĩa | tay | 挈 = 㓞 (Khiết, biểu âm) + 手 (Thủ, biểu nghĩa: tay); chữ hình thanh. Bộ 手 xác nhận hành động dùng tay. 㓞 cho âm đọc qiè.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiết\": tay (手) + 㓞 (khiết — cắt giao ước) — người nắm tay dắt kẻ khác đi, như người đứng đầu dẫn đường. | Gương Hán-Việt | khiết trong 提挈 (Đề Khiết — dắt dẫn, chỉ đạo), 挈领 (Khiết Lĩnh — nắm yếu lĩnh) | Mở khoá kiến thức | Biết 挈 mở khoá 提挈 (đề khiết — chỉ đạo, nâng đỡ người khác) và 挈领 (khiết lĩnh — nắm bắt điểm chính yếu).", "Tự nguyên_Xie": "Tiểu triện | 挈 là chữ hình thanh: 㓞 biểu âm, 手 (tay) biểu nghĩa. Nghĩa gốc liên quan đến văn tự ký kết, hợp đồng (契约), từ đó mở rộng sang nghĩa dắt theo, mang theo, lãnh đạo. Có tiểu triện. Thường xuất hiện trong 提挈 (đề khiết — dắt dẫn, chỉ đạo) và 挈带 (khiết đới — mang theo). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "văn tự để làm tin, hợp đồng", "Hạng Tần Suất (Jun Da)": "5176.0", "Tần Suất % (Jun Da)": "99.9376472896", "GavinGrover_Once (Chiết tự trực tiếp)": "㓞 + 手", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱㓞手", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㓞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "手", "Unihan_Simplified (Chữ Giản thể)": "挈", "Unihan_Traditional (Chữ Phồn thể)": "挈", "Pinyin_Xie": "qiè", "Âm Hán Việt_Xie": "khiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ đứng trước tân ngữ để chỉ hành động mang xách hoặc dẫn dắt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踽', '{"9000": "5177.0", "Chữ Trung Quốc": "踽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 16 | nét | 足 | tú | biểu nghĩa | chân | 禹 | vũ | biểu âm | 踽 = 足 (Tú/Túc, biểu nghĩa: chân) + 禹 (Vũ, biểu âm); chữ hình thanh. Bộ 足 xác nhận chữ liên quan đến cách đi, chuyển động. 禹 cho âm đọc jǔ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vũ\": 足 (chân) + Vũ (Đại Vũ trị thuỷ, đi một mình khắp nơi) — 踽 là bước chân vũ phu lẻ loi giữa trời đất mênh mông. | Gương Hán-Việt | vũ trong 踽踽 (Vũ Vũ — bước đi thui thủi, lẻ loi) | Mở khoá kiến thức | Biết 踽 mở khoá 踽踽独行 (vũ vũ độc hành — đi một mình cô đơn) và 踽踽凉凉 (cô đơn lạnh lẽo).", "Tự nguyên_Xie": "Tiểu triện | 踽 là chữ hình thanh: 足 (chân) biểu nghĩa, 禹 biểu âm. Chỉ cách đi thui thủi, bước chân lẻ loi, đơn độc. Có tiểu triện. Nổi tiếng trong 踽踽独行 (cú cú độc hành — đi một mình lầm lũi) và 踽踽凉凉 (cú cú lương lương — cô đơn lạnh lẽo). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thui thủi; lẻ loi", "Hạng Tần Suất (Jun Da)": "5177.0", "Tần Suất % (Jun Da)": "99.9378007748", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 禹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊禹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踽", "Unihan_Traditional (Chữ Phồn thể)": "踽", "Pinyin_Xie": "jǔ", "Âm Hán Việt_Xie": "củ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường làm tính từ hoặc phó từ bổ nghĩa cho động từ di chuyển để tả dáng đi lầm lũi một mình. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黾', '{"9000": "5178.0", "Chữ Trung Quốc": "黾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黽 | Số nét | 8 | nét | 黾 | miễn | tượng hình | con ếch với cái đuôi nhỏ — tượng hình | 黾 là chữ tượng hình (象形), mô phỏng hình dáng con ếch với đuôi ngắn. Không có cấu trúc hình thanh hay hội ý. Nghĩa \"cố gắng\" là mượn âm (giả tá).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miễn\": tượng hình con ếch nhỏ với đuôi cụt — âm MIỄN được mượn để viết nghĩa \"cố gắng\" (黽勉). | Gương Hán-Việt | miễn cưỡng (勉強) — nỗ lực dù khó khăn | Mở khoá kiến thức | Biết 黾 mở khoá: 黽勉 (miễn miễn — cố gắng), 水黽 (thủy miễn — con nhện nước).", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Wiktionary xếp 黾 vào loại tượng hình (象形): hình vẽ con ếch với cái đuôi nhỏ. Nghĩa gốc là \"một loài ếch\". Nghĩa phái sinh \"cố gắng, nỗ lực\" (黽勉) là mượn âm từ chữ này — hai nghĩa không liên quan về mặt hình ảnh. Trong kim văn và đại triện còn thấy rõ hình dáng ếch. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cố gắng", "Hạng Tần Suất (Jun Da)": "5178.0", "Tần Suất % (Jun Da)": "99.937877259", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 电", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱口电", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "电", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "黾", "Unihan_Traditional (Chữ Phồn thể)": "黽", "Pinyin_Xie": "miǎn", "Âm Hán Việt_Xie": "mẫn, mãnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng trong văn viết cổ làm động từ thể hiện sự cố gắng, tự khích lệ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('侩', '{"9000": "5179.0", "Chữ Trung Quốc": "侩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 侩 | khoái | tượng hình | người môi giới — cấu trúc không rõ, tự thân | 侩 (giản thể của 儈) có bộ 亻 (nhân — người) bên trái, phần còn lại chưa có phân tích hình thanh/hội ý được Wiktionary xác nhận. Tạm coi là chữ hình thanh chưa rõ thành phần biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoái\": người (亻) chuyên làm \"khoái\" (nhanh) giao dịch — đó là kẻ môi giới buôn bán. | Gương Hán-Việt | thị khoái (市儈) — con buôn, người môi giới chợ | Mở khoá kiến thức | Biết 侩 mở khoá: 市侩 (thị khoái — con buôn), 侩子手 (khoái tử thủ — đao phủ).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi 儈 (phồn thể) là người môi giới, buôn bán trung gian, mà không phân tích cấu trúc hình thanh cụ thể. Chữ giản thể 侩 đơn giản hoá từ 儈. Nghĩa gốc và duy nhất: người làm trung gian buôn bán (市儈 — con buôn). Chưa có nguồn học thuật cho cấu trúc bên trong. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "người lái, người môi giới", "Hạng Tần Suất (Jun Da)": "5179.0", "Tần Suất % (Jun Da)": "99.9380297106", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 会", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻会", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "会", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "侩", "Unihan_Traditional (Chữ Phồn thể)": "儈", "Pinyin_Xie": "kuài", "Âm Hán Việt_Xie": "quái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng một mình hoặc kết hợp để chỉ người làm nghề trung gian, môi giới. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('凫', '{"9000": "5180.0", "Chữ Trung Quốc": "凫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 几 | Số nét | 6 | nét | 凫 | phù | tượng hình | vịt trời — chữ tượng hình | 凫 (phồn thể 鳧) là chữ tượng hình, mô phỏng hình dáng con vịt trời. Wiktionary không phân tích cấu trúc hình thanh cho chữ này. Hình giáp cốt và kim văn vẽ rõ hình dáng chim/vịt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phù\": con vịt trời (凫) PHÙ trên mặt nước — \"phù\" gợi hình ảnh nổi, bơi. | Gương Hán-Việt | phù (凫) — vịt trời, bơi lội; liên hệ phù thuỷ (người nổi trên nước) | Mở khoá kiến thức | Biết 凫 mở khoá: 凫水 (phù thuỷ — bơi lội), 野凫 (dã phù — vịt trời hoang).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Wiktionary chỉ ghi {{Han etym}} mà không phân tích chi tiết cấu trúc 鳧/凫. Dựa vào hình giáp cốt và kim văn còn thấy hình dáng con vịt trời với cánh và mỏ. Nghĩa phái sinh \"bơi lội\" (như vịt bơi) xuất hiện sau. Chưa có nguồn học thuật đầy đủ xác nhận cấu trúc. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vịt trời", "Hạng Tần Suất (Jun Da)": "5180.0", "Tần Suất % (Jun Da)": "99.938105678", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 几", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱几", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "凫", "Unihan_Traditional (Chữ Phồn thể)": "鳧", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ loài vịt trời hoặc động từ chỉ hành động bơi, nổi trên nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诔', '{"9000": "5181.0", "Chữ Trung Quốc": "诔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 8 | nét | 诔 | lỗi | tượng hình | lời điếu văn — chữ giản thể của 誄 | 诔 là chữ giản thể của 誄. Phồn thể 誄 gồm bộ 言 (ngôn — lời nói) và 耒 (lỗi — cái cày). Cấu trúc hình thanh chưa được Wiktionary phân tích rõ ràng cho chữ này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lỗi\": lời (讠) văn điếu viếng người qua đời — đọc 诔 (lỗi) là đọc bài ca ngợi linh hồn. | Gương Hán-Việt | lỗi (誄) — bài điếu văn ca ngợi người mất | Mở khoá kiến thức | Biết 诔 mở khoá: 诔文 (lỗi văn — văn điếu), 作诔 (tác lỗi — viết bài điếu).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 诔 là chữ giản thể rút gọn từ 誄 (đổi 言 thành 讠). Nghĩa gốc: viết hoặc đọc điếu văn, ca ngợi người quá cố. Phồn thể 誄 có bộ 言 (lời nói) nhấn mạnh đây là văn bản dạng ngôn từ. Cấu trúc bên trong chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lời phúng viếng; cầu cúng", "Hạng Tần Suất (Jun Da)": "5181.0", "Tần Suất % (Jun Da)": "99.9381816454", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 耒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠耒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诔", "Unihan_Traditional (Chữ Phồn thể)": "誄", "Pinyin_Xie": "lěi", "Âm Hán Việt_Xie": "lụy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ thể loại văn tế người chết hoặc động từ thực hiện việc tế viếng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郯', '{"9000": "5182.0", "Chữ Trung Quốc": "郯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 10 | nét | 郯 | đàm | tượng hình | tên nước cổ — chưa rõ cấu trúc | 郯 có bộ 邑/阝 (ấp — địa danh, làng) bên phải, là ký hiệu chỉ địa danh. Phần còn lại chưa được phân tích cấu trúc hình thanh trong Wiktionary. Đây là chữ dùng chủ yếu làm tên riêng (nước Đàm thời cổ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đàm\": ấp (阝) mang tên ĐÀM — nước Đàm nhỏ bé thời Xuân Thu, có danh nhân Đàm Tử. | Gương Hán-Việt | đàm (郯) — nước Đàm cổ; Đàm Tử (郯子) là nhân vật hiếu thuận nổi tiếng | Mở khoá kiến thức | Biết 郯 mở khoá: 郯子 (Đàm Tử — nhân vật lịch sử), 郯城 (Đàm Thành — địa danh hiện đại).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Wiktionary chỉ ghi {{Han etym}} và định nghĩa là tên nước nhỏ thời cổ đại ở vùng Sơn Đông–Giang Tô ngày nay. Không có phân tích cấu trúc cụ thể. Bộ 邑 (阝bên phải) thường chỉ địa danh, làng ấp — phù hợp với nghĩa tên đất. Chưa có nguồn học thuật xác nhận cấu trúc nội bộ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Đàm", "Hạng Tần Suất (Jun Da)": "5182.0", "Tần Suất % (Jun Da)": "99.9382576128", "GavinGrover_Once (Chiết tự trực tiếp)": "炎 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰炎阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "炎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郯", "Unihan_Traditional (Chữ Phồn thể)": "郯", "Pinyin_Xie": "tán", "Âm Hán Việt_Xie": "đàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ riêng chỉ tên nước cổ hoặc địa danh trong lịch sử Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韪', '{"9000": "5183.0", "Chữ Trung Quốc": "韪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 韋 | Số nét | 13 | nét | 韪 | vĩ | tượng hình | đúng, phải lẽ — cấu trúc chưa rõ | 韪 (phồn thể 韙) có bộ 韋 (vi — da thuộc, bao quanh) nhưng Wiktionary không phân tích cấu trúc hình thanh hay hội ý cụ thể. Chữ thường dùng trong cụm phủ định 大不韪 (đại bất vĩ — điều sai trái tày trời).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vĩ\": điều VĨ đại (韋) là điều đúng đắn, phải lẽ — 大不韪 là điều SAI trái tày trời. | Gương Hán-Việt | đại bất vĩ (大不韪) — điều sai trái nghiêm trọng, vi phạm chuẩn mực | Mở khoá kiến thức | Biết 韪 chủ yếu để đọc cụm 冒天下之大不韪 (dám làm điều sai trái tày trời).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary chỉ ghi phiên âm và định nghĩa: đúng, chính đáng, phép tắc (right, correct, proper). Thường dùng trong câu phủ định. Cấu trúc nội bộ không được phân tích. Bộ 韋 (da thuộc, quấn quanh) có thể là phần biểu nghĩa (cái bao bọc, giữ gìn → chuẩn mực). Chưa có nguồn học thuật xác nhận. Chưa thấy trong giáp cốt/kim văn, chủ yếu thấy từ tiểu triện. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phải lễ", "Hạng Tần Suất (Jun Da)": "5183.0", "Tần Suất % (Jun Da)": "99.9383335802", "GavinGrover_Once (Chiết tự trực tiếp)": "是 + 韦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴是韦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "是", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "韦", "Unihan_Simplified (Chữ Giản thể)": "韪", "Unihan_Traditional (Chữ Phồn thể)": "韙", "Pinyin_Xie": "wěi", "Âm Hán Việt_Xie": "vĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ chỉ sự đúng đắn hoặc danh từ trong các cụm từ cố định như thị vĩ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('挲', '{"9000": "5184.0", "Chữ Trung Quốc": "挲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 挲 | ta | tượng hình | vuốt ve — cấu trúc chưa rõ | 挲 có bộ 手/扌 (thủ — tay) nhấn mạnh hành động bằng tay. Phần còn lại chưa được phân tích cấu trúc hình thanh trong Wiktionary. Nghĩa: vuốt ve, mơn trớn bằng ngón tay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ta\": bàn tay (扌) nhẹ nhàng TA vuốt — động tác mơn trớn âu yếm. | Gương Hán-Việt | mạt ta (摩挲) — vuốt ve, xoa bóp nhẹ nhàng | Mở khoá kiến thức | Biết 挲 mở khoá cụm 摩挲 (mạt sa — vuốt nhẹ, xoa), hay dùng trong văn học.", "Tự nguyên_Xie": "Wiktionary ghi phiên âm và định nghĩa (stroke, caress, fondle) nhưng không phân tích cấu trúc chữ. Bộ 手 (tay) bên trái chỉ hành động liên quan đến tay. Không thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật xác nhận cấu trúc. Chữ chủ yếu dùng trong cụm 摩挲 (mạt sa — vuốt ve). | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vuốt ve, mơn trớn", "Hạng Tần Suất (Jun Da)": "5184.0", "Tần Suất % (Jun Da)": "99.9384095477", "GavinGrover_Once (Chiết tự trực tiếp)": "沙 + 手", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱沙手", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "沙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "手", "Unihan_Simplified (Chữ Giản thể)": "挲", "Unihan_Traditional (Chữ Phồn thể)": "挱", "Pinyin_Xie": "sā", "Âm Hán Việt_Xie": "sa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động xoa, vuốt nhẹ nhàng bằng tay, hay đi kèm trong từ ghép ma sa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笪', '{"9000": "5185.0", "Chữ Trung Quốc": "笪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 笪 | đác | tượng hình | chiếu tre — cấu trúc chưa rõ | 笪 có bộ 竹/⺮ (trúc — tre) ở trên, chỉ vật liệu làm từ tre. Phần dưới chưa được Wiktionary phân tích cấu trúc hình thanh cụ thể. Nghĩa gốc: chiếu thô đan bằng tre.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đác\": bộ trúc (⺮) trên đầu — chiếc chiếu ĐÁC (thô ráp) đan bằng nan tre. | Gương Hán-Việt | đác (笪) — chiếu tre thô, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 笪 mở khoá: 竹笪 (trúc đác — chiếu tre), 大笪地 (địa danh Hồng Kông nổi tiếng).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi phiên âm và định nghĩa: chiếu thô làm bằng tre hoặc cói; cũng dùng làm họ người. Không có phân tích cấu trúc hình thanh. Bộ 竹 (trúc — tre) phù hợp với nghĩa vật liệu. Chữ cũng dùng làm lượng từ trong tiếng Quảng Đông (笪地 — một mảnh đất). Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chiếu đan bằng nan tre to", "Hạng Tần Suất (Jun Da)": "5185.0", "Tần Suất % (Jun Da)": "99.9384855151", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 旦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮旦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笪", "Unihan_Traditional (Chữ Phồn thể)": "笪", "Pinyin_Xie": "dá", "Âm Hán Việt_Xie": "đát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các vật dụng làm bằng tre nứa đan thô hoặc dùng làm họ người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼋', '{"9000": "5186.0", "Chữ Trung Quốc": "鼋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 龜 | Số nét | 12 | nét | 元 | nguyên | biểu âm | đầu tiên, nguyên — cho âm yuán | 黽 | miễn | biểu nghĩa | loài ếch, bò sát dưới nước | 鼋 = 元 (Nguyên, biểu âm) + 黽 (Miễn, biểu nghĩa: loài ếch/bò sát nước); chữ hình thanh. Phần 黽 chỉ loài sinh vật sống dưới nước, phần 元 cho âm yuán gần với tên gọi con ba ba lớn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nguyên\": con NGUYÊN (元) — rùa lớn (黽) mang tên Nguyên, to đầu như người đứng đầu. | Gương Hán-Việt | nguyên (鼋) — ba ba lớn, rùa khổng lồ trong văn học cổ điển | Mở khoá kiến thức | Biết 鼋 mở khoá: 鼋头渚 (Nguyên Đầu Chử — địa danh nổi tiếng ở Vô Tích), 鼋鱼 (ba ba lớn).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary: 鼋 (phồn thể 黿) là chữ hình thanh (形聲), gồm 元 (biểu âm) và 黽 (biểu nghĩa: loài ếch, bò sát). Nghĩa: con ba ba lớn, rùa biển. Trong tiểu triện hình dạng đã rõ cấu trúc hai phần. Ba ba lớn (鼋) là loài từng xuất hiện nhiều trong sông hồ Trung Quốc cổ đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ba ba", "Hạng Tần Suất (Jun Da)": "5186.0", "Tần Suất % (Jun Da)": "99.9385614825", "GavinGrover_Once (Chiết tự trực tiếp)": "元 + 黾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱元黾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "元", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黾", "Unihan_Simplified (Chữ Giản thể)": "鼋", "Unihan_Traditional (Chữ Phồn thể)": "黿", "Pinyin_Xie": "yuán", "Âm Hán Việt_Xie": "ngoan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loài rùa lớn hoặc ba ba lớn trong tự nhiên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莜', '{"9000": "5187.0", "Chữ Trung Quốc": "莜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 莜 | du | tượng hình | cây du mạch — cấu trúc chưa rõ | 莜 có bộ 艹 (thảo — cỏ cây) ở trên, chỉ đây là loại thực vật. Phần dưới chưa được Wiktionary phân tích cấu trúc hình thanh cụ thể. Nghĩa chính: cây du mạch (莜麦 — Avena nuda), một loại yến mạch không vỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": cỏ (艹) DU mạch — loại yến mạch trần trồng ở vùng núi phía bắc Trung Quốc. | Gương Hán-Việt | du mạch (莜麦) — yến mạch trần, thực phẩm vùng cao nguyên | Mở khoá kiến thức | Biết 莜 mở khoá: 莜麦 (du mạch — yến mạch trần), 莜麦菜 (rau diếp xoăn), 莜面 (bột du mạch).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 莜 chủ yếu dùng trong 莜麥 (yến mạch trần/Avena nuda). Không có phân tích cấu trúc hình thanh. Bộ 艹 (thảo) phù hợp với nghĩa loại cây trồng. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn — chỉ thấy trong tiểu triện. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây du mạch; hạt du mạch", "Hạng Tần Suất (Jun Da)": "5187.0", "Tần Suất % (Jun Da)": "99.9386374499", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 攸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹攸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "攸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莜", "Unihan_Traditional (Chữ Phồn thể)": "莜", "Pinyin_Xie": "yóu", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ đứng trước các từ chỉ món ăn làm từ yến mạch. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菅', '{"9000": "5188.0", "Chữ Trung Quốc": "菅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 官 | quan | biểu âm | quan chức — cho âm jiān | 菅 = 艹 (Thảo, biểu nghĩa: cỏ cây) + 官 (Quan, biểu âm); chữ hình thanh. Phần 艹 chỉ đây là loại cỏ, phần 官 cho âm jiān gần với quan.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"gian\": cỏ (艹) thô như tên QUAN (官) — 草菅人命: xem mạng người như cỏ gian hoang. | Gương Hán-Việt | thảo gian (草菅) — cỏ thô dại; \"thảo gian nhân mệnh\" là xem mạng người như cỏ rác | Mở khoá kiến thức | Biết 菅 mở khoá thành ngữ 草菅人命 (thảo gian nhân mệnh — xem mạng người như cỏ rác).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary: 菅 là chữ hình thanh (形聲), gồm 艹 (biểu nghĩa: một loại cỏ) và 官 (biểu âm). Nghĩa: một loài cỏ thô (possiblement Themeda forskalii). Hay dùng trong thành ngữ 草菅人命 (thảo gian nhân mệnh — xem mạng người như cỏ rác). Trong tiểu triện và lục thư thông cấu trúc đã rõ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ gian, cỏ may", "Hạng Tần Suất (Jun Da)": "5188.0", "Tần Suất % (Jun Da)": "99.9387888679", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 官", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹官", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "官", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菅", "Unihan_Traditional (Chữ Phồn thể)": "菅", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "gian", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong các thành ngữ ví mạng người như cỏ rác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嵊', '{"9000": "5189.0", "Chữ Trung Quốc": "嵊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 13 | nét | 山 | sơn | biểu nghĩa | núi | 乘 | thừa | biểu âm | cưỡi — cho âm shèng | 嵊 = 山 (Sơn, biểu nghĩa: núi) + 乘 (Thừa, biểu âm); chữ hình thanh. Phần 山 chỉ đây liên quan đến địa hình núi, phần 乘 cho âm shèng. Dùng chủ yếu làm địa danh (huyện Nị Châu, Chiết Giang).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thừa\": núi (山) THỪA thắng — địa danh Thừa (嵊) nằm trên vùng núi Chiết Giang. | Gương Hán-Việt | thừa (嵊) — địa danh vùng núi Chiết Giang; liên hệ Thừa Châu (嵊州) | Mở khoá kiến thức | Biết 嵊 chủ yếu để nhận biết địa danh: 嵊州 (Thừa Châu — thành phố Chiết Giang), 嵊泗 (quần đảo Chiết Giang).", "Tự nguyên_Xie": "Wiktionary: 嵊 là chữ hình thanh (形聲), gồm 山 (biểu nghĩa: núi) và 乘 (biểu âm). Dùng làm địa danh — Nị Châu (嵊州), huyện Nị (嵊縣) thuộc tỉnh Chiết Giang. Không có nghĩa độc lập ngoài địa danh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "5189.0", "Tần Suất % (Jun Da)": "99.9388643186", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 乘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山乘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "嵊", "Unihan_Traditional (Chữ Phồn thể)": "嵊", "Pinyin_Xie": "shèng", "Âm Hán Việt_Xie": "thặng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng để chỉ địa danh cụ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裢', '{"9000": "5190.0", "Chữ Trung Quốc": "裢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 12 | nét | 裢 | liên | tượng hình | túi vải gấp đôi — cấu trúc chưa rõ | 裢 có bộ 衣/衤 (y — áo, vải) bên trái, chỉ vật dụng làm từ vải. Wiktionary không có mục riêng cho 裢 và không phân tích cấu trúc. Chữ chủ yếu dùng trong cụm 褡裢 (đáp liên — túi vải dài gấp đôi đeo ngang lưng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liên\": vải (衤) nối LIÊN (连) lại — chiếc túi 褡裢 có hai ngăn nối liền nhau. | Gương Hán-Việt | đáp liên (褡裢) — túi vải hai ngăn đeo ngang hông | Mở khoá kiến thức | Biết 裢 mở khoá cụm 褡裢 (đáp liên — loại túi vải cổ điển).", "Tự nguyên_Xie": "Không tìm thấy phân tích nguồn gốc trong Wiktionary cho 裢. Bộ 衤 (y — vải, áo) phù hợp với nghĩa túi vải. Chữ dùng chủ yếu trong cụm 褡裢 (đáp liên — túi vải gấp dài đeo hông). Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đáp liên 褡褳,褡裢)", "Hạng Tần Suất (Jun Da)": "5190.0", "Tần Suất % (Jun Da)": "99.9389397692", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 连", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤连", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "连", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裢", "Unihan_Traditional (Chữ Phồn thể)": "褳", "Pinyin_Xie": "lián", "Âm Hán Việt_Xie": "liên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ khác để tạo thành danh từ chỉ loại túi vải đeo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趿', '{"9000": "5191.0", "Chữ Trung Quốc": "趿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 10 | nét | 足 | tú | biểu nghĩa | chân | 及 | cập | biểu âm | đuổi kịp — cho âm tā | 趿 = 足 (Tú, biểu nghĩa: chân) + 及 (Cập, biểu âm); chữ hình thanh. Phần 足 chỉ hành động liên quan đến chân, phần 及 cho âm tā/jí gần với cập.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kịp\": chân (足) CẬP (及) đất — lê chân kéo dép, kiểu đi KỊCH không nhấc chân. | Gương Hán-Việt | kịp (趿) — lê dép, đi kéo lê chân; ít dùng độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 趿 mở khoá: 趿拉 (kịp lạp — lê dép lê), 趿着拖鞋 (đi dép lê kéo lết).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary: 趿 là chữ hình thanh (形聲), gồm 足 (biểu nghĩa: chân) và 及 (biểu âm). Nghĩa: lê chân, kéo lê khi đi; đi dép không buộc quai. Trong tiểu triện và lục thư thông cấu trúc đã rõ. Nghĩa \"giày dép\" có lẽ phái sinh từ hành động lê chân khi đi dép lê. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lê, kéo lê; giày, dép", "Hạng Tần Suất (Jun Da)": "5191.0", "Tần Suất % (Jun Da)": "99.9390152198", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 及", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊及", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "及", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "趿", "Unihan_Traditional (Chữ Phồn thể)": "趿", "Pinyin_Xie": "tā", "Âm Hán Việt_Xie": "táp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ mô tả động tác xỏ giày dép nhưng không xỏ gót. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箸', '{"9000": "5192.0", "Chữ Trung Quốc": "箸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 竹 | trúc | biểu nghĩa | tre — vật liệu làm đũa | 者 | giả | biểu âm | người/kẻ — cho âm zhù | 箸 = 竹 (Trúc, biểu nghĩa: tre) + 者 (Giả, biểu âm); chữ hình thanh. Phần 竹 chỉ đũa làm từ tre, phần 者 cho âm zhù gần với giả/giạ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giạ\": tre (竹) GIẢ/GIẠ làm đũa — bộ 竹 là vật liệu, 者 cho âm. | Gương Hán-Việt | giạ (箸) — đôi đũa; liên hệ 筷子 (kuàizi) trong tiếng Trung hiện đại | Mở khoá kiến thức | Biết 箸 mở khoá: 箸筷 (giạ khoái — đũa), 象箸 (tượng giạ — đũa ngà voi, điển tích).", "Tự nguyên_Xie": "Bạch thư | Tiểu triện | Wiktionary: 箸 là chữ hình thanh (形聲), gồm 竹 (biểu nghĩa: tre) và 者 (biểu âm). Nghĩa gốc và duy nhất: đôi đũa. Đũa truyền thống làm bằng tre nên có bộ 竹. Trong bạch thư và tiểu triện cấu trúc đã rõ. Chữ 箸 là từ cổ, hiện đại dùng 筷子 nhiều hơn — nhưng 箸 vẫn hay gặp trong văn học và ẩm thực Nhật Bản (hashi). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1235.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trúc (108) Giả (662)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trúc (số 108 - tre trúc/chỉ ý) ở trên chữ Giả (số 662 - đại từ/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Giả chỉ âm, bộ Trúc chỉ ý. Trứ là cái đũa làm từ tre trúc.", "Nghĩa Tiếng Việt_Xie": "cái đũa", "Hạng Tần Suất (Jun Da)": "5192.0", "Tần Suất % (Jun Da)": "99.9390906705", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 者", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮者", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "者", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箸", "Unihan_Traditional (Chữ Phồn thể)": "筯", "Pinyin_Xie": "zhù", "Âm Hán Việt_Xie": "trợ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ đôi đũa trong văn viết hoặc khẩu ngữ cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莴', '{"9000": "5193.0", "Chữ Trung Quốc": "莴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 莴 | oa | tượng hình | rau diếp — chữ giản thể của 萵 | 莴 là chữ giản thể của 萵. Phồn thể 萵 gồm 艹 (thảo — cỏ cây) và 咼 (biểu âm), giản thể đổi 咼 thành 呙. Cấu trúc hình thanh rõ: 艹 biểu nghĩa cây rau, phần còn lại biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oa\": cỏ (艹) OA tròn, mập — cây rau diếp có lá xanh tròn mọng. | Gương Hán-Việt | oa cự (萵苣) — rau diếp xanh; oa súc (莴笋) — ngồng diếp | Mở khoá kiến thức | Biết 莴 mở khoá: 莴苣 (oa cự — rau diếp), 莴笋 (oa súc — ngồng diếp giòn).", "Tự nguyên_Xie": "Wiktionary: 莴 là chữ giản thể của 萵, đổi 咼 thành 呙. Nghĩa: rau diếp (萵苣/莴苣 — lettuce). Cấu trúc 艹 (thảo — cây rau) + biểu âm. Chữ dùng chủ yếu trong tổ hợp 莴苣 (oa cự — rau diếp xanh) và 莴笋 (oa súc — ngồng diếp). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: oa cự 萵苣,莴苣)", "Hạng Tần Suất (Jun Da)": "5193.0", "Tần Suất % (Jun Da)": "99.9391656043", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 呙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹呙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "呙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莴", "Unihan_Traditional (Chữ Phồn thể)": "萵", "Pinyin_Xie": "wō", "Âm Hán Việt_Xie": "oa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ ghép để chỉ các loại rau diếp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莠', '{"9000": "5194.0", "Chữ Trung Quốc": "莠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 莠 | dữu | tượng hình | cỏ vực dại — cấu trúc chưa rõ | 莠 có bộ 艹 (thảo — cỏ) ở trên, chỉ đây là loại cỏ dại. Phần dưới chưa được Wiktionary phân tích cấu trúc hình thanh. Nghĩa: cỏ vực (Setaria viridis — green foxtail), loại cỏ dại giống lúa thường mọc trong ruộng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dữu\": cỏ (艹) DỮU (xấu xa) — cỏ vực mọc lẫn lúa gợi hình ảnh \"良莠不齐\" (tốt xấu lẫn lộn). | Gương Hán-Việt | dữu (莠) — cỏ vực dại; \"lương dữu bất tề\" là tốt xấu lẫn lộn | Mở khoá kiến thức | Biết 莠 mở khoá thành ngữ 良莠不齐 (lương dữu bất tề — tốt xấu lẫn lộn, không đồng đều).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi phiên âm và định nghĩa: cỏ vực (Setaria viridis), hay dùng nghĩa bóng là người xấu (良莠不齐 — tốt xấu lẫn lộn). Không có phân tích cấu trúc. Bộ 艹 (thảo) phù hợp nghĩa cỏ dại. Chưa có nguồn học thuật xác nhận cấu trúc nội bộ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ vực (hay mọc trong ruộng làm hại lúa)", "Hạng Tần Suất (Jun Da)": "5194.0", "Tần Suất % (Jun Da)": "99.9392405381", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 秀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹秀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莠", "Unihan_Traditional (Chữ Phồn thể)": "莠", "Pinyin_Xie": "yǒu", "Âm Hán Việt_Xie": "dửu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ cỏ dại hoặc tính từ chỉ sự xấu xa, lẫn lộn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阌', '{"9000": "5195.0", "Chữ Trung Quốc": "阌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 11 | nét | 阌 | văn | tượng hình | tên đất Văn Hương — cấu trúc chưa rõ | 阌 (phồn thể 閿) có bộ 门/門 (môn — cửa) bên ngoài, phần còn lại chưa được Wiktionary phân tích cấu trúc cụ thể. Dùng chủ yếu làm địa danh: 閿鄉 (Văn Hương — huyện cổ ở Hà Nam).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"văn\": cửa (门) VĂN — tên đất Văn Hương (閿鄉) ở Hà Nam, cổng vào vùng Quan Trung. | Gương Hán-Việt | văn hương (閿鄉) — tên huyện cổ ở tỉnh Hà Nam, Trung Quốc | Mở khoá kiến thức | Biết 阌 chủ yếu để nhận biết địa danh 阌乡/閿鄉 (Văn Hương, Hà Nam).", "Tự nguyên_Xie": "Wiktionary chỉ ghi phiên âm và định nghĩa là địa danh (閿鄉 — Văn Hương, Hà Nam). Không có phân tích cấu trúc hình thanh. Bộ 門 (cổng, cửa) gợi hình ảnh cửa ngõ. Chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "5195.0", "Tần Suất % (Jun Da)": "99.939315472", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 受", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门受", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "受", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阌", "Unihan_Traditional (Chữ Phồn thể)": "閿", "Pinyin_Xie": "wén", "Âm Hán Việt_Xie": "văn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chỉ dùng làm danh từ riêng trong các địa danh lịch sử. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('旯', '{"9000": "5196.0", "Chữ Trung Quốc": "旯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 6 | nét | 旯 | lạp | tượng hình | góc tối, xó xỉnh — chữ tạo muộn | 旯 là chữ tạo muộn, không có nguồn trong Wiktionary. Chữ chủ yếu dùng trong cụm 旮旯 (ca lạp — góc tối, xó xỉnh, nơi khuất lấp). Cấu trúc hình dạng giống 日 (nhật — mặt trời) phía trên và cái gì đó bên dưới, nhưng không có phân tích hội ý/hình thanh được xác nhận. Chưa thấy trong giáp cốt, kim văn, hay tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạp\": 旯 trong 旮旯 — góc LẠP (khuất lấp) tối tăm, nơi mặt trời (日) không chiếu tới. | Gương Hán-Việt | ca lạp (旮旯) — góc tối, xó xỉnh, nơi khuất lấp | Mở khoá kiến thức | Biết 旯 mở khoá cụm 旮旯 (ca lạp — góc tối, xó xỉnh) hay dùng trong khẩu ngữ phương bắc.", "Tự nguyên_Xie": "Không tìm thấy phân tích nguồn gốc trong Wiktionary cho 旯. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chủ yếu dùng trong cụm 旮旯 (ca lạp — góc tối, xó xỉnh). Cấu trúc chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ca lạp 旮旯)", "Hạng Tần Suất (Jun Da)": "5196.0", "Tần Suất % (Jun Da)": "99.9393904058", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 九", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱日九", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "九", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "旯", "Unihan_Traditional (Chữ Phồn thể)": "旯", "Pinyin_Xie": "lá", "Âm Hán Việt_Xie": "lạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp thành từ ghép để làm danh từ chỉ nơi góc khuất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('圜', '{"9000": "5197.0", "Chữ Trung Quốc": "圜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 囗 | Số nét | 16 | nét | 囗 | vi | biểu nghĩa | vòng tròn, bao quanh | 睘 | biểu âm | cho âm huán | 圜 = 囗 (Vi, biểu nghĩa: vòng tròn, bao quanh) + 睘 (biểu âm); chữ hình thanh. Phần 囗 là vòng bao ngoài gợi hình dáng tròn, phần 睘 cho âm huán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"viên\": bao quanh (囗) VIÊN tròn — 圜 là vòng tròn hoàn hảo, mọi phía đều đóng lại. | Gương Hán-Việt | viên (圜) — tròn, vòng tròn; đồng nghĩa với 圆 trong nhiều văn bản cổ | Mở khoá kiến thức | Biết 圜 mở khoá: 圜土 (viên thổ — nhà giam tròn thời cổ), 圜丘 (viên khâu — đàn tế trời hình tròn).", "Tự nguyên_Xie": "Wiktionary: 圜 là chữ hình thanh (形聲), gồm 囗 (biểu nghĩa: vòng tròn) và 睘 (biểu âm). Nghĩa: tròn, vòng tròn, bao quanh. Đồng nghĩa với 圓 (viên — tròn) trong nhiều ngữ cảnh. Chữ cũng dùng trong từ cổ 圜土 (viên thổ — nhà tù). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vòng tròn", "Hạng Tần Suất (Jun Da)": "5197.0", "Tần Suất % (Jun Da)": "99.9394653397", "GavinGrover_Once (Chiết tự trực tiếp)": "囗 + 睘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Bao quanh toàn bộ)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴囗睘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "睘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "囗", "Unihan_Simplified (Chữ Giản thể)": "圜", "Unihan_Traditional (Chữ Phồn thể)": "圜", "Pinyin_Xie": "huán", "Âm Hán Việt_Xie": "hoàn, viên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Tính từ | 形容词 | Có thể làm danh từ chỉ vòng tròn hoặc động từ chỉ sự bao quanh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涪', '{"9000": "5198.0", "Chữ Trung Quốc": "涪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 氵 | thuỷ | biểu nghĩa | nước | 咅 | biểu âm | cho âm fú | 涪 = 氵 (Thuỷ, biểu nghĩa: nước) + 咅 (biểu âm); chữ hình thanh. Phần 氵 chỉ đây là tên sông, phần 咅 cho âm fú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phù\": nước (氵) PHÙ chảy — sông Phù (涪江) ở Tứ Xuyên, nơi sinh ra củ cải muối 涪陵榨菜. | Gương Hán-Việt | phù lăng (涪陵) — địa danh Trùng Khánh nổi tiếng với dưa cải muối | Mở khoá kiến thức | Biết 涪 mở khoá địa danh: 涪江 (Phù Giang — sông ở Tứ Xuyên), 涪陵 (Phù Lăng — thành phố Trùng Khánh).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary: 涪 là chữ hình thanh (形聲), gồm 氵 (biểu nghĩa: nước) và 咅 (biểu âm). Nghĩa: sông Phù (涪江) ở Tứ Xuyên và Trùng Khánh. Địa danh nổi tiếng: 涪陵 (Phù Lăng — nơi trồng củ cải muối Trùng Khánh). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Phù (ở tỉnh Tứ Xuyên của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "5198.0", "Tần Suất % (Jun Da)": "99.9395402735", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 咅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵咅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "涪", "Unihan_Traditional (Chữ Phồn thể)": "涪", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ tên sông hoặc địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赍', '{"9000": "5199.0", "Chữ Trung Quốc": "赍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 12 | nét | 齊 | tề | biểu âm | đồng đều — cho âm jī | 貝 | bối | biểu nghĩa | vỏ sò, tiền tệ, của cải | 赍 = 齊 (Tề, biểu âm) + 貝 (Bối, biểu nghĩa: vỏ sò, tiền tệ, của cải); chữ hình thanh. Phần 貝 chỉ đây liên quan đến của cải/tiền bạc (vỏ sò là tiền cổ), phần 齊 cho âm jī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": tiền vỏ sò (貝) TỀ trang — mang lễ vật (赍) đến biếu tặng. | Gương Hán-Việt | tư (赍) — mang lễ vật biếu tặng; tư phát (赍发) là cho tiền lên đường | Mở khoá kiến thức | Biết 赍 mở khoá: 赍发 (tư phát — cho tiền tiễn đường), 赍志而没 (tư chí nhi một — chết với hoài bão chưa thực hiện).", "Tự nguyên_Xie": "Wiktionary: 赍 (phồn thể 齎) là chữ hình thanh (形聲), gồm 齊 (biểu âm) và 貝 (biểu nghĩa: vỏ sò/tiền). Nghĩa: đem cho, mang biếu; tiễn đưa kèm quà. Trong văn cổ cũng mang nghĩa \"mang theo\" nói chung. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đem cho, mang cho; tiễn đưa", "Hạng Tần Suất (Jun Da)": "5199.0", "Tần Suất % (Jun Da)": "99.9396152074", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 贝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱贝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "赍", "Unihan_Traditional (Chữ Phồn thể)": "賫", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "tê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ hành động mang theo hoặc ban tặng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('柞', '{"9000": "5200.0", "Chữ Trung Quốc": "柞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 柞 | tạc | tượng hình | cây sồi — cấu trúc chưa rõ | 柞 có bộ 木 (mộc — cây, gỗ) bên trái, chỉ đây là loại cây. Phần bên phải chưa được Wiktionary phân tích cấu trúc hình thanh cụ thể. Nghĩa: cây sồi, cây thường xanh có gai (dùng nuôi tằm gai — 柞蚕).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tạc\": cây (木) TẠC — cây sồi gai dùng để nuôi con tằm sồi (柞蚕), dệt lụa thô. | Gương Hán-Việt | tạc (柞) — cây sồi gai; tạc tàm (柞蚕) là tằm sồi, dệt vải thô | Mở khoá kiến thức | Biết 柞 mở khoá: 柞蚕 (tạc tàm — tằm sồi), 柞丝绸 (tạc ty trù — lụa tằm sồi thô).", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Wiktionary ghi phiên âm và định nghĩa (oak, spinous evergreen tree) nhưng không phân tích cấu trúc hình thanh. Bộ 木 (mộc — gỗ, cây) phù hợp nghĩa loại cây. Chữ có kim văn và bigseal, gợi ý chữ khá cổ. Tên sông 柞水 là nghĩa phái sinh. Chưa có nguồn học thuật xác nhận cấu trúc nội bộ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây tạc (lá có răng cưa, dùng để chải đầu); phạt cây, phát cây; chật hẹp; tiếng vang ra ngoài", "Hạng Tần Suất (Jun Da)": "5200.0", "Tần Suất % (Jun Da)": "99.9396896244", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 乍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木乍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "柞", "Unihan_Traditional (Chữ Phồn thể)": "柞", "Pinyin_Xie": "zhà", "Âm Hán Việt_Xie": "tạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ một loại cây gỗ hoặc làm động từ chỉ hành động chặt cây. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗍', '{"9000": "5201.0", "Chữ Trung Quốc": "嗍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 嗍 | sác | tượng hình | mút bằng miệng — chữ tạo muộn | 嗍 có bộ 口 (khẩu — miệng) bên trái, chỉ hành động dùng miệng. Wiktionary không có mục cho 嗍. Không thấy trong giáp cốt, kim văn hay tiểu triện. Chữ tạo muộn, chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sác\": miệng (口) SÁC sáp — động tác MÚT bằng miệng, âm thanh \"sác sác\". | Gương Hán-Việt | sác (嗍) — mút, hút bằng miệng; ít thấy trong từ điển chuẩn | Mở khoá kiến thức | Biết 嗍 để hiểu phương ngữ: 嗍螺蛳 (sác loa tư — mút ốc), 嗍手指 (mút ngón tay).", "Tự nguyên_Xie": "Không tìm thấy phân tích nguồn gốc trong Wiktionary cho 嗍. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Bộ 口 (miệng) phù hợp với nghĩa mút bằng miệng. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mút bằng miệng", "Hạng Tần Suất (Jun Da)": "5201.0", "Tần Suất % (Jun Da)": "99.9397640415", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 朔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口朔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗍", "Unihan_Traditional (Chữ Phồn thể)": "嗍", "Pinyin_Xie": "suō", "Âm Hán Việt_Xie": "thoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ vị ngữ biểu thị động tác mút hoặc bú sữa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('囵', '{"9000": "5202.0", "Chữ Trung Quốc": "囵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 囗 | Số nét | 7 | nét | 囵 | luân | tượng hình | toàn vẹn, nguyên cả — chữ tạo muộn | 囵 có bộ 囗 (vi — bao quanh) ở ngoài, chỉ sự bao bọc toàn vẹn. Wiktionary không có mục cho 囵. Chữ tạo muộn, chủ yếu dùng trong cụm 囫囵 (hốt luân — nguyên cả, không chia nhỏ). Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"luân\": vòng (囗) LUÂN tròn — 囫囵吞枣 nuốt cả quả táo không nhai, nghĩa hồ đồ qua loa. | Gương Hán-Việt | hốt luân (囫囵) — nguyên cả, không chia nhỏ; 囫囵吞枣 là học hồ đồ qua loa | Mở khoá kiến thức | Biết 囵 mở khoá thành ngữ 囫囵吞枣 (hốt luân thôn táo — nuốt táo nguyên cả, học vẹt không hiểu).", "Tự nguyên_Xie": "Không tìm thấy phân tích nguồn gốc trong Wiktionary cho 囵. Chữ tạo muộn. Bộ 囗 (bao quanh) gợi nghĩa toàn vẹn, nguyên khối. Dùng chủ yếu trong 囫囵 (hốt luân — nguyên cả, nuốt cả). Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hốt luân 囫圇,囫囵)", "Hạng Tần Suất (Jun Da)": "5202.0", "Tần Suất % (Jun Da)": "99.9398384585", "GavinGrover_Once (Chiết tự trực tiếp)": "囗 + 仑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Bao quanh toàn bộ)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴囗仑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "仑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "囗", "Unihan_Simplified (Chữ Giản thể)": "囵", "Unihan_Traditional (Chữ Phồn thể)": "圇", "Pinyin_Xie": "lún", "Âm Hán Việt_Xie": "luân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường không đứng độc lập mà kết hợp thành từ ghép để làm tính từ bổ nghĩa. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('榧', '{"9000": "5203.0", "Chữ Trung Quốc": "榧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 14 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 匪 | phỉ | biểu âm | không phải, tên cướp — cho âm fěi | 榧 = 木 (Mộc, biểu nghĩa: gỗ, cây) + 匪 (Phỉ, biểu âm); chữ hình thanh. Phần 木 chỉ đây là loại cây, phần 匪 cho âm fěi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phỉ\": cây (木) PHỈ — cây phỉ đặc sản Chiết Giang, hạt béo thơm ngon. | Gương Hán-Việt | phỉ (榧) — cây phỉ/thông phỉ; phỉ tử (榧子) là hạt ăn được | Mở khoá kiến thức | Biết 榧 mở khoá: 香榧 (hương phỉ — phỉ thơm), 榧子 (phỉ tử — hạt cây phỉ ăn được).", "Tự nguyên_Xie": "Wiktionary: 榧 là chữ hình thanh (形聲), gồm 木 (biểu nghĩa: gỗ, cây) và 匪 (biểu âm). Nghĩa: cây phỉ (Torreya grandis — Chinese nutmeg yew), một loại cây lá kim quý ở vùng Giang Nam. Hạt 榧子 (phỉ tử) ăn được và dùng làm thuốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây phỉ", "Hạng Tần Suất (Jun Da)": "5203.0", "Tần Suất % (Jun Da)": "99.9399128756", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 匪", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木匪", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匪", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "榧", "Unihan_Traditional (Chữ Phồn thể)": "榧", "Pinyin_Xie": "fěi", "Âm Hán Việt_Xie": "phỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ một loại cây hạt trần hoặc quả của loại cây này. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裰', '{"9000": "5204.0", "Chữ Trung Quốc": "裰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 13 | nét | 裰 | đoát | tượng hình | vá áo — cấu trúc chưa rõ | 裰 có bộ 衣/衤 (y — áo, vải) bên trái, chỉ hành động liên quan đến may vá. Wiktionary ghi phiên âm và định nghĩa nhưng không phân tích cấu trúc hình thanh. Nghĩa: vá áo; áo thầy tu (直裰).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đoát\": vải áo (衤) ĐOÁT vá — chiếc áo tu sĩ 直裰 là áo liền thân vá víu lại, đơn giản. | Gương Hán-Việt | trực đoát (直裰) — áo dài tu sĩ đơn giản của nhà sư và đạo sĩ | Mở khoá kiến thức | Biết 裰 mở khoá: 直裰 (trực đoát — áo tu sĩ), hay gặp trong tiểu thuyết cổ điển.", "Tự nguyên_Xie": "Wiktionary: 裰 nghĩa vá áo (hist-dict), cũng dùng trong 直裰 (trực đoát — áo dài của thầy tu Đạo giáo và Phật giáo). Không có phân tích cấu trúc. Bộ 衤 (y — áo) phù hợp với nghĩa may vá. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vá (áo)", "Hạng Tần Suất (Jun Da)": "5204.0", "Tần Suất % (Jun Da)": "99.9399872927", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 叕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤叕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裰", "Unihan_Traditional (Chữ Phồn thể)": "裰", "Pinyin_Xie": "duō", "Âm Hán Việt_Xie": "chuyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc khâu vá hoặc làm danh từ chỉ áo dài của tăng lữ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笾', '{"9000": "5205.0", "Chữ Trung Quốc": "笾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 𥫗 | trúc | biểu nghĩa | tre — vật liệu làm đồ tế | 邊 | biên | biểu âm | biên giới — cho âm biān | 笾 = 𥫗 (Trúc, biểu nghĩa: tre) + 邊 (Biên, biểu âm); chữ hình thanh. Phần trúc chỉ đồ dùng làm bằng tre, phần 邊 cho âm biān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biên\": tre (竹) BIÊN kết — cái biên (笾) đan bằng tre để bày đồ cúng bên cạnh (邊) bàn thờ. | Gương Hán-Việt | biên đậu (笾豆) — đồ tế lễ cổ điển: 笾 đựng đồ khô, 豆 đựng đồ ướt | Mở khoá kiến thức | Biết 笾 mở khoá: 笾豆 (biên đậu — đồ tế lễ), 加笾 (gia biên — thêm đồ lễ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary: 笾 (phồn thể 籩) là chữ hình thanh (形聲), gồm 𥫗/竹 (biểu nghĩa: tre) và 邊 (biểu âm). Nghĩa: khay/giỏ tre dùng để bày đồ khô trong lễ tế cổ (trái cây khô, thịt khô). Dùng trong lễ nghi tế tự thời cổ, thường xuất hiện cùng 豆 (đậu — bát gỗ đựng thức ăn ướt). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái biên (để bày đồ cúng tế)", "Hạng Tần Suất (Jun Da)": "5205.0", "Tần Suất % (Jun Da)": "99.9400617097", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 边", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴⺮边", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "边", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笾", "Unihan_Traditional (Chữ Phồn thể)": "籩", "Pinyin_Xie": "biān", "Âm Hán Việt_Xie": "biên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ một loại lễ khí bằng tre dùng trong tế lễ thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簟', '{"9000": "5206.0", "Chữ Trung Quốc": "簟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 18 | nét | 簟 | điếm | tượng hình | chiếu tre đan — cấu trúc chưa rõ | 簟 có bộ 竹/⺮ (trúc — tre) ở trên, chỉ đây là vật dụng làm bằng tre. Wiktionary ghi phiên âm và định nghĩa nhưng không phân tích cấu trúc hình thanh. Nghĩa: chiếu tre đan (bamboo mat), dùng trong văn học cổ điển.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điếm\": tre (⺮) ĐIẾM mát — chiếc chiếu điếm (簟) đan bằng nan tre, trải nằm ngày hè. | Gương Hán-Việt | điếm (簟) — chiếu tre; 冰簟 (băng điếm) là chiếu tre mát lạnh thời hè trong thơ cổ | Mở khoá kiến thức | Biết 簟 giúp đọc thơ Đường: 簟凉 (điếm lương — chiếu mát), 冰簟 (băng điếm — chiếu mát như băng).", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Wiktionary ghi 簟 nghĩa chiếu tre (bamboo mat), dùng trong văn học cổ và phương ngữ. Không có phân tích cấu trúc hình thanh. Bộ 竹 (tre) phù hợp với vật liệu chiếu. Kim văn và bigseal cho thấy chữ khá cổ. Chưa có nguồn học thuật xác nhận cấu trúc nội bộ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chiếu đan", "Hạng Tần Suất (Jun Da)": "5206.0", "Tần Suất % (Jun Da)": "99.9401361268", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "簟", "Unihan_Traditional (Chữ Phồn thể)": "簟", "Pinyin_Xie": "diàn", "Âm Hán Việt_Xie": "điệm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ các loại chiếu làm từ tre trúc dùng để trải nằm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跎', '{"9000": "5207.0", "Chữ Trung Quốc": "跎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 12 | nét | 跎 | đà | tượng hình | vấp chân, trượt — cấu trúc chưa rõ | 跎 có bộ 足 (tú — chân) bên trái, chỉ hành động liên quan đến chân. Wiktionary ghi phiên âm và định nghĩa nhưng không phân tích cấu trúc hình thanh. Nghĩa: trượt chân, vấp ngã; dùng chủ yếu trong 蹉跎 (ta đà — phí hoài thời gian).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đà\": chân (足) ĐÀ vấp — 蹉跎 là bước chân trật nhịp, thời gian trôi ĐÀ (phí hoài). | Gương Hán-Việt | ta đà (蹉跎) — phí hoài tuổi trẻ, bỏ lỡ thời cơ | Mở khoá kiến thức | Biết 跎 mở khoá cụm 蹉跎岁月 (ta đà tuế nguyệt — tháng năm phí hoài).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary: 跎 định nghĩa qua 蹉跎 (to slip away, to idle away time). Không có phân tích cấu trúc hình thanh. Bộ 足 (chân) phù hợp nghĩa trượt chân. Chữ chủ yếu dùng trong cụm 蹉跎 — phí hoài tuổi trẻ. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vấp chân, sẩy chân, trượt chân", "Hạng Tần Suất (Jun Da)": "5207.0", "Tần Suất % (Jun Da)": "99.9402105438", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 它", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊它", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "它", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跎", "Unihan_Traditional (Chữ Phồn thể)": "跎", "Pinyin_Xie": "tuó", "Âm Hán Việt_Xie": "đà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường kết hợp thành từ ghép để làm động từ chỉ sự lãng phí thời gian. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('巽', '{"9000": "5208.0", "Chữ Trung Quốc": "巽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 己 | Số nét | 12 | nét | 丌 | cơ | biểu nghĩa | người quỳ gối bên bàn thờ | 巽 (gốc là 巺) là chữ hội ý (會意): 𠨎 (người quỳ gối) + 丌 (bàn thờ/bàn) — hình ảnh chuẩn bị/bày biện thức ăn. Ý nghĩa gốc: dọn thức ăn, phục tùng. Về sau mượn nghĩa cho quẻ Tốn trong Kinh Dịch.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tốn\": người quỳ (𠨎) bên bàn (丌) — TỐN thuận, nhún nhường; quẻ Tốn trong Kinh Dịch tượng gió nhẹ thuận chiều. | Gương Hán-Việt | tốn (巽) — quẻ Tốn trong bát quái, tượng gió; tốn thuận (謙遜) là nhún nhường | Mở khoá kiến thức | Biết 巽 mở khoá: 巽卦 (tốn quái — quẻ Tốn), 巽言 (tốn ngôn — lời nhún nhường), Sundanese (巽他 — người Sunda).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary: 巽 gốc là 巺, hội ý từ 𠨎 (người quỳ gối) và 丌 (bàn — table): hình ảnh người phục tùng bày biện thức ăn. Nghĩa gốc: dọn dẹp thức ăn → phục tùng, nhún nhường. Sau dùng làm phiên thiết cho 饌 (soạn — bày biện thức ăn). Hiện đại dùng làm quẻ thứ 5 trong bát quái (☴ — Tốn, tượng gió, hướng đông nam). lsCodes: ic (hội ý). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quẻ Tốn (hạ đoạn) trong Kinh Dịch (chỉ có vạch dưới đứt, tượng Phong (gió), tượng trưng cho con gái trưởng, hành Mộc, tuổi Thìn và Tỵ, hướng Đông Nam)", "Hạng Tần Suất (Jun Da)": "5208.0", "Tần Suất % (Jun Da)": "99.9402849609", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 共", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱共", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "巽", "Unihan_Traditional (Chữ Phồn thể)": "巽", "Pinyin_Xie": "xùn", "Âm Hán Việt_Xie": "tốn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Làm danh từ chỉ một quẻ trong Kinh Dịch hoặc làm tính từ chỉ sự cung kính. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('曷', '{"9000": "5209.0", "Chữ Trung Quốc": "曷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 曰 | Số nét | 9 | nét | 匃 | cái | biểu âm | xin, cầu — cho âm hé | 曰 | viết | biểu nghĩa | nói, rằng | 曷 = 匃 (Cái, biểu âm) + 曰 (Viết, biểu nghĩa: nói, rằng); chữ hình thanh. Phần 曰 (nói) gợi nghĩa từ nghi vấn dùng trong lời nói, phần 匃 cho âm hé theo Shuowen.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạt\": nói (曰) HẠT — câu hỏi HẠT? (tại sao, cái gì?) trong văn ngôn, như tiếng \"hạt\" vang lên trong lời hỏi. | Gương Hán-Việt | hạt (曷) — từ nghi vấn văn cổ \"tại sao, cái gì\"; ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 曷 mở khoá: 曷不 (hạt bất — sao không?), 曷若 (hạt nhược — như thế nào), hay gặp trong thơ Kinh Thi.", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Wiktionary (Shuowen Jiezi): 曷 là chữ hình thanh (形聲), gồm 匃 (biểu âm) và 曰 (biểu nghĩa: nói). Nghĩa: tại sao? cái gì? ở đâu? — từ nghi vấn văn cổ. Kim văn và bigseal cho thấy chữ khá cổ. Trong văn ngôn hay dùng 曷不 (hạt bất — sao không?) biểu thị lời kêu gọi hoặc nghi vấn tu từ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "677.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Viết (043) Cái (676)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Viết (số 043 - nói) ở trên chữ Cái (số 676 - cầu xin). Miệng nói (Viết) lời cầu xin (Cái) mong người khác giải đáp. Giải thích sự chuyển ý: Đây là chữ Hội ý. Câu giải đáp ấy chính là lời hỏi ''Tại sao?''. Hạt là từ dùng để hỏi tại sao, cớ sao, khi nào.", "Nghĩa Tiếng Việt_Xie": "gì, sao chẳng", "Hạng Tần Suất (Jun Da)": "5209.0", "Tần Suất % (Jun Da)": "99.940359378", "GavinGrover_Once (Chiết tự trực tiếp)": "曰 + 匃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱曰匃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "曰", "Unihan_Simplified (Chữ Giản thể)": "曷", "Unihan_Traditional (Chữ Phồn thể)": "曷", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Đại từ | 代词 | Phó từ | 副词 | Thường dùng làm đại từ nghi vấn hoặc phó từ đứng đầu câu hỏi trong văn ngôn. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逖', '{"9000": "5210.0", "Chữ Trung Quốc": "逖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 10 | nét | 逖 | địch | tượng hình | xa xôi — cấu trúc chưa rõ | 逖 có bộ 辵/辶 (sước — bước đi, đường) chỉ hành động di chuyển hoặc khoảng cách. Wiktionary ghi phiên âm và định nghĩa nhưng không phân tích cấu trúc hình thanh. Nghĩa: xa, xa xôi; giữ khoảng cách.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"địch\": đường xa (辶) ĐỊCH — 逖聽 là lắng nghe tin tức từ xa; khoảng ĐỊCH (cách trở) không qua được. | Gương Hán-Việt | địch (逖) — xa xôi, cách trở; 逖聽 là thu thập tin tức từ xa | Mở khoá kiến thức | Biết 逖 mở khoá: 逖聽 (địch thính — lắng nghe từ xa), 離逖 (ly địch — xa cách biệt ly).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary: 逖 nghĩa xa, xa xôi (far, distant); giữ khoảng cách. Không có phân tích cấu trúc hình thanh. Bộ 辶 (đường đi) phù hợp nghĩa xa cách. Chỉ thấy tiểu triện và lục thư thông. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xa; xa xôi", "Hạng Tần Suất (Jun Da)": "5210.0", "Tần Suất % (Jun Da)": "99.9404332782", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 狄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶狄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "狄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逖", "Unihan_Traditional (Chữ Phồn thể)": "逖", "Pinyin_Xie": "tì", "Âm Hán Việt_Xie": "thích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này dùng làm tính từ để chỉ khoảng cách địa lý xa xôi hoặc sự xa cách trong văn ngôn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骓', '{"9000": "5211.0", "Chữ Trung Quốc": "骓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 11 | nét | 骓 | truy | tượng hình | ngựa loang xám trắng — cấu trúc chưa rõ | 骓 (phồn thể 騅) có bộ 馬/马 (mã — ngựa) chỉ đây là loại ngựa. Wiktionary ghi phiên âm và định nghĩa nhưng không phân tích cấu trúc hình thanh. Nghĩa: ngựa loang xám trắng đen; đặc biệt là tên con ngựa của Hạng Vũ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"truy\": ngựa (馬) TRUY — Ô Truy (烏騅) là con ngựa huyền thoại của Hạng Vũ, lông đen loang trắng. | Gương Hán-Việt | ô truy (烏騅) — ngựa của Hạng Vũ; tượng trưng cho thời thế không thuận | Mở khoá kiến thức | Biết 骓 mở khoá điển tích Ô Truy (烏骓) và bài ca nổi tiếng của Hạng Vũ trong Sử Ký.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary: 骓 (phồn thể 騅) nghĩa ngựa piebald (lông pha xám và trắng). Nổi tiếng là tên ngựa của Tây Sở Bá Vương Hạng Vũ — được nhắc trong \"Hồng Cai\" (Shiji): \"Lực bạt sơn hề khí cái thế, thời bất lợi hề Truy bất thệ...\" Không có phân tích cấu trúc. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa có lông xanh trắng đen lẫn lộn", "Hạng Tần Suất (Jun Da)": "5211.0", "Tần Suất % (Jun Da)": "99.9405071785", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骓", "Unihan_Traditional (Chữ Phồn thể)": "騅", "Pinyin_Xie": "zhuī", "Âm Hán Việt_Xie": "chuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một giống ngựa chiến có sắc lông pha trộn thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绔', '{"9000": "5212.0", "Chữ Trung Quốc": "绔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 9 | nét | 糹 | mịch | biểu nghĩa | tơ lụa, vải | 夸 | khoa | biểu âm | khoác lác — cho âm kù | 绔 = 糹 (Mịch, biểu nghĩa: tơ lụa) + 夸 (Khoa, biểu âm); chữ hình thanh. Phần 糹 chỉ quần làm từ lụa mịn, phần 夸 cho âm kù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khố\": lụa (糹) KHOA trương — 紈绔子弟 là tên KHOA (夸) trương mặc quần lụa đắt tiền, chỉ công tử bột. | Gương Hán-Việt | hoàn khố (紈绔) — quần lụa mịn; khố tử đệ (紈绔子弟) là công tử bột con nhà giàu | Mở khoá kiến thức | Biết 绔 mở khoá thành ngữ 纨绔子弟 (hoàn khố tử đệ — công tử bột, con cái nhà giàu hư hỏng).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary: 绔 (phồn thể 絝) là chữ hình thanh (形聲), gồm 糹 (biểu nghĩa: lụa) và 夸 (biểu âm). Nghĩa: quần (dạng cổ của 裤/褲). Nổi tiếng qua cụm 紈絝 (hoàn khố — quần lụa mịn) → nghĩa bóng: công tử bột, con nhà giàu ăn chơi. 紈絝子弟 là thành ngữ chỉ con cái nhà quyền quý hư hỏng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái khố; cái quần đùi", "Hạng Tần Suất (Jun Da)": "5212.0", "Tần Suất % (Jun Da)": "99.9405810788", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 夸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟夸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绔", "Unihan_Traditional (Chữ Phồn thể)": "絝", "Pinyin_Xie": "kù", "Âm Hán Việt_Xie": "khố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ các loại quần mặc ở thân dưới của người xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('枋', '{"9000": "5213.0", "Chữ Trung Quốc": "枋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 8 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 方 | phương | biểu âm | phương, vuông — cho âm fāng | 枋 = 木 (Mộc, biểu nghĩa: gỗ, cây) + 方 (Phương, biểu âm); chữ hình thanh. Phần 木 chỉ đây là loại cây gỗ, phần 方 cho âm fāng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phương\": gỗ (木) PHƯƠNG hướng — cây 枋 (phương) cho gỗ tốt làm đà vuông (方) trong xây dựng. | Gương Hán-Việt | phương (枋) — cây phương, gỗ dùng trong xây dựng và nhuộm | Mở khoá kiến thức | Biết 枋 mở khoá: 枋木 (phương mộc — gỗ cây phương), thường gặp trong văn liệu kiến trúc cổ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary: 枋 là chữ hình thanh (形聲), gồm 木 (biểu nghĩa: gỗ) và 方 (biểu âm). Nghĩa: gỗ đàn hương, cây dùng làm gỗ xây dựng hoặc nhuộm màu. Trong tiểu triện và lục thư thông cấu trúc đã rõ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây phương (dùng làm thuốc nhuộm)", "Hạng Tần Suất (Jun Da)": "5213.0", "Tần Suất % (Jun Da)": "99.9406549791", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 方", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木方", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "方", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "枋", "Unihan_Traditional (Chữ Phồn thể)": "枋", "Pinyin_Xie": "fāng", "Âm Hán Việt_Xie": "phương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cây gỗ hoặc thanh gỗ dùng làm xà nhà. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镒', '{"9000": "5214.0", "Chữ Trung Quốc": "镒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 镒 | dật | tượng hình | đơn vị đo vàng — cấu trúc chưa rõ | 镒 (phồn thể 鎰) có bộ 金/钅 (kim — vàng, kim loại) chỉ đây là đơn vị đo khối lượng kim loại quý. Wiktionary ghi phiên âm và định nghĩa nhưng không phân tích cấu trúc hình thanh. Nghĩa: đơn vị đo khối lượng vàng thời cổ (bằng 20 hoặc 24 lạng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dật\": vàng (钅) DẬT — 万镒黄金 là vạn dật vàng, đơn vị đo vàng của người xưa. | Gương Hán-Việt | dật (镒) — đơn vị đo vàng cổ; 百镒 là trăm dật vàng | Mở khoá kiến thức | Biết 镒 giúp đọc văn ngôn: 百镒之金 (bách dật chi kim — trăm dật vàng, trị giá rất cao).", "Tự nguyên_Xie": "Wiktionary: 镒 (phồn thể 鎰) là đơn vị đo khối lượng tương đương 20 hoặc 24 兩 (lạng). Trích Mạnh Tử: \"璞玉值萬鎰\" — ngọc thô trị giá vạn dật. Không có phân tích cấu trúc hình thanh. Bộ 金 (vàng) phù hợp với đơn vị đo kim loại. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dật (đơn vị đo khối lượng, bằng 20 lạng)", "Hạng Tần Suất (Jun Da)": "5214.0", "Tần Suất % (Jun Da)": "99.9407288793", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 益", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅益", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "益", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镒", "Unihan_Traditional (Chữ Phồn thể)": "鎰", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Chữ này làm lượng từ đặt sau số từ để đo lường khối lượng vàng bạc thời xưa. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魃', '{"9000": "5215.0", "Chữ Trung Quốc": "魃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鬼 | Số nét | 14 | nét | 魃 | bạt | tượng hình | thần nắng hạn — cấu trúc chưa rõ | 魃 có bộ 鬼 (quỷ) bên trái, chỉ đây là loại thần linh/yêu quái. Wiktionary ghi phiên âm và định nghĩa nhưng không phân tích cấu trúc hình thanh. Nghĩa: thần hạn hán (drought demon), gây ra khô hạn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạt\": quỷ (鬼) BẠT trừ nước — thần BẠT (旱魃) hút sạch nước mưa, gây đại hạn. | Gương Hán-Việt | hạn bạt (旱魃) — thần hạn hán trong thần thoại Trung Hoa; bạt trừ (跋除) là tiêu diệt | Mở khoá kiến thức | Biết 魃 mở khoá: 旱魃 (hạn bạt — thần hạn hán), 旱魃为虐 (thành ngữ — hạn hán hoành hành).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary: 魃 là thần hạn hán (drought demon). Trích Kinh Thi (Shijing): \"旱魃為虐，如惔如焚\" — thần hạn nổi giận, như lửa bốc thiêu. Trích Sơn Hải Kinh: nơi thần 魃 ở không có mưa. Không có phân tích cấu trúc hình thanh. Bộ 鬼 (quỷ, thần linh siêu nhiên) phù hợp nghĩa thần hạn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thần nắng", "Hạng Tần Suất (Jun Da)": "5215.0", "Tần Suất % (Jun Da)": "99.9408027796", "GavinGrover_Once (Chiết tự trực tiếp)": "鬼 + 犮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鬼犮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鬼", "Unihan_Simplified (Chữ Giản thể)": "魃", "Unihan_Traditional (Chữ Phồn thể)": "魃", "Pinyin_Xie": "bá", "Âm Hán Việt_Xie": "bạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ vị thần hoặc loài quỷ gây ra nạn hạn hán trong thần thoại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('餮', '{"9000": "5216.0", "Chữ Trung Quốc": "餮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 18 | nét | 殄 | điên | biểu âm | tuyệt diệt | 食 | thực | biểu nghĩa | thức ăn, ăn | 餮 = 殄 (Điên, biểu âm) + 食 (Thực, biểu nghĩa: thức ăn); chữ hình thanh. Phần 食 gợi nghĩa ăn uống tham lam, phần 殄 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiết\": bộ 食 (thực) bên cạnh 殄 (điên) — con quái thú 饕餮 chỉ biết ăn, ăn không ngừng, tham lam đến tuyệt diệt. | Gương Hán-Việt | thiết trong 饕餮 (thao thiết) — tên quái thú tham ăn | Mở khoá kiến thức | Biết 餮 mở khoá từ 饕餮 (thao thiết) — hình tượng quen thuộc trên đồ đồng Trung Hoa cổ.", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 餮 là chữ hình thanh: 殄 (điên, âm tit3) cho âm, 食 (thực) cho nghĩa ăn uống. Chữ này chủ yếu dùng trong từ ghép 饕餮 (thao thiết) — tên một con quái thú huyền thoại trong văn hóa Trung Hoa cổ, tượng trưng cho lòng tham ăn vô độ. Hình tượng 饕餮 thường xuất hiện trên đồ đồng thời nhà Thương. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thao thiết 饕餮)", "Hạng Tần Suất (Jun Da)": "5216.0", "Tần Suất % (Jun Da)": "99.9408766799", "GavinGrover_Once (Chiết tự trực tiếp)": "殄 + 食", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱殄食", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "殄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "食", "Unihan_Simplified (Chữ Giản thể)": "餮", "Unihan_Traditional (Chữ Phồn thể)": "餮", "Pinyin_Xie": "tiè", "Âm Hán Việt_Xie": "thiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường làm tính từ chỉ tính tham ăn và thường đi liền với chữ thao thành từ ghép. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讵', '{"9000": "5217.0", "Chữ Trung Quốc": "讵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 6 | nét | 讵 | cự | tượng hình | chữ giản thể của 詎 | 讵 là dạng giản thể của 詎, thay bộ 訁 (ngôn) bằng 讠. Cấu trúc gốc gồm bộ 言 (ngôn, lời nói) và phần biểu âm — chữ dùng làm phụ từ biểu thị sự ngạc nhiên hoặc phủ định tu từ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cự\": chữ 讠(ngôn) + phần âm — ''há lẽ nào lời nói lại không đến được?'' Phụ từ văn ngôn biểu thị sự phủ nhận đầy ngạc nhiên. | Gương Hán-Việt | cự — dùng trong văn ngôn cổ, ít gặp trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 讵 mở khoá lối hành văn văn ngôn: 讵料 (há ngờ đâu), 讵知 (há biết được).", "Tự nguyên_Xie": "Tiểu triện | 讵 là dạng giản thể của 詎. Theo Wiktionary, 詎 gồm bộ 言 (ngôn, lời nói) và thành phần biểu âm. Chữ này dùng làm phụ từ văn ngôn mang nghĩa ''há'' (biểu thị câu hỏi tu từ phủ định) hoặc ''nếu''. Dạng giản thể 讵 thay 訁 bằng 讠 theo quy tắc giản hóa. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chẳng nhẽ, há (phụ từ); nếu", "Hạng Tần Suất (Jun Da)": "5217.0", "Tần Suất % (Jun Da)": "99.9409505802", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 巨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠巨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "讵", "Unihan_Traditional (Chữ Phồn thể)": "詎", "Pinyin_Xie": "jù", "Âm Hán Việt_Xie": "cự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Chữ này làm phó từ đứng trước động từ để biểu thị ý nghi vấn hoặc phản vấn. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('乜', '{"9000": "5218.0", "Chữ Trung Quốc": "乜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 乙 | Số nét | 2 | nét | 乜 | khiết | tượng hình | chữ tượng hình mô tả mắt lim dim | 乜 là chữ độc thể, bộ 乙 (ất). Không có nguồn cấu trúc học thuật rõ ràng — chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Hình dạng đơn giản, chỉ 2 nét.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiết\": chữ nhỏ xíu chỉ 2 nét như đôi mắt đang nheo lại — nhìn một mắt lim dim là 乜 rồi. | Gương Hán-Việt | khiết — ít dùng trong tiếng Việt, chủ yếu dùng trong họ tên | Mở khoá kiến thức | Biết 乜 giúp nhận ra họ Khiết (乜) trong tên người, và hiểu tiếng Quảng Đông 乜嘢 (cái gì).", "Tự nguyên_Xie": "Không có nguồn Wiktionary cụ thể cho 乜. Chữ thuộc bộ 乙 (ất), chỉ 2 nét. Dùng trong tiếng Quảng Đông với nghĩa ''cái gì'' (what?), và trong tiếng phổ thông có nghĩa ''nheo mắt, lim dim''. Đây là chữ tạo muộn, chưa có nguồn học thuật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "506.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ất (505)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Từ chữ Ất (乙) thêm một nét cong kéo dài nữa, tạo thành dáng vẻ hai con mắt đang liếc xéo hoặc nheo lại lác mắt. Giải thích sự chuyển ý: Đây là chữ Tượng hình (hoặc Hội ý). Từ hình dạng con mắt nheo lại hoặc lác mắt, biểu thị cái nhìn không thẳng (nhìn xéo/lác). (Âm Miết hoặc Dã).", "Nghĩa Tiếng Việt_Xie": "nheo mắt, lim dim mắt; họ Khiết", "Hạng Tần Suất (Jun Da)": "5218.0", "Tần Suất % (Jun Da)": "99.9410239636", "GavinGrover_Once (Chiết tự trực tiếp)": "乚 + ㇆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴乚㇆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "乚", "Unihan_Simplified (Chữ Giản thể)": "乜", "Unihan_Traditional (Chữ Phồn thể)": "乜", "Pinyin_Xie": "miē", "Âm Hán Việt_Xie": "khiết, mị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động nheo mắt hoặc làm danh từ chỉ một họ người. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄢', '{"9000": "5219.0", "Chữ Trung Quốc": "鄢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 13 | nét | 焉 | yên | biểu âm | 阝 | ấp | biểu nghĩa | địa danh, thành ấp | 鄢 = 焉 (Yên, biểu âm) + 阝 (Ấp, biểu nghĩa: địa danh); chữ hình thanh. Bộ 阝 bên phải chỉ địa danh, tên đất; phần 焉 cho âm đọc yān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yên\": bộ 阝(ấp) kết hợp 焉 (yên) — địa danh cổ tên Yên, kinh đô nước Trịnh nay thuộc Hà Nam. | Gương Hán-Việt | yên — trong họ tên và địa danh cổ Trung Hoa | Mở khoá kiến thức | Biết 鄢 giúp nhận ra địa danh cổ Trung Hoa và họ người hiếm gặp.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 鄢 là chữ hình thanh: 焉 (yên) cho âm, 邑/阝 (ấp) cho nghĩa địa danh. Chữ này là tên của một địa danh cổ xưa — thành Yên, từng là kinh đô nước Trịnh thời Xuân Thu, nay thuộc tỉnh Hà Nam, Trung Quốc. Cũng dùng làm họ người. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thành Yên (kinh đô nước Trịnh); nước Yên (tức nước Trịnh cũ, nay thuộc tỉnh Hà Nam của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "5219.0", "Tần Suất % (Jun Da)": "99.9410973471", "GavinGrover_Once (Chiết tự trực tiếp)": "焉 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰焉阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "焉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄢", "Unihan_Traditional (Chữ Phồn thể)": "鄢", "Pinyin_Xie": "yān", "Âm Hán Việt_Xie": "yển, yên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng chỉ địa danh hoặc tên một nước chư hầu thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瑭', '{"9000": "5220.0", "Chữ Trung Quốc": "瑭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 14 | nét | 瑭 | đường | tượng hình | một loại ngọc | 瑭 thuộc bộ 玉 (ngọc). Theo cấu trúc chữ Hán, nhiều khả năng gồm bộ 玉/王 (ngọc, biểu nghĩa) và phần biểu âm là 唐 (đường). Chữ chỉ một loại ngọc quý, ít dùng trong văn bản hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đường\": bộ 玉 (ngọc) — một loại ngọc quý thời xưa mang tên Đường, quý như triều đại nhà Đường. | Gương Hán-Việt | đường — ít dùng trong tiếng Việt, chủ yếu trong tên cổ và văn học | Mở khoá kiến thức | Biết 瑭 giúp nhận ra tên người và triều đại Hậu Đường trong lịch sử Trung Hoa (五代十国).", "Tự nguyên_Xie": "Theo Wiktionary, 瑭 là tên một loại ngọc. Chữ thuộc bộ 玉 (ngọc), âm đọc táng/táng theo trung cổ âm. Cấu trúc học thuật chưa rõ ràng trong nguồn tra cứu, có khả năng là hình thanh với 唐 (đường) làm phần biểu âm. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc đường (một loại ngọc)", "Hạng Tần Suất (Jun Da)": "5220.0", "Tần Suất % (Jun Da)": "99.9411707306", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 唐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王唐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "唐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "瑭", "Unihan_Traditional (Chữ Phồn thể)": "瑭", "Pinyin_Xie": "táng", "Âm Hán Việt_Xie": "đường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một thứ ngọc quý thường dùng trong văn chương cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踅', '{"9000": "5221.0", "Chữ Trung Quốc": "踅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 14 | nét | 折 | chiết | biểu âm | gãy, bẻ | 足 | túc | biểu nghĩa | chân, bước đi | 踅 = 折 (Chiết, biểu âm) + 足 (Túc, biểu nghĩa: chân); chữ hình thanh. Bộ 足 gợi nghĩa bước đi, chân; phần 折 cho âm xué.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiết\": bộ 足 (túc, chân) + 折 (chiết, gãy/bẻ) — đôi chân bẻ ngoặt lại, đi qua đi lại không ngừng. | Gương Hán-Việt | tiết — ít dùng trong tiếng Việt thông thường | Mở khoá kiến thức | Biết 踅 giúp nhận ra từ miêu tả dáng đi lượn vòng, do dự, không thẳng hướng trong văn học.", "Tự nguyên_Xie": "Theo Wiktionary, 踅 là chữ hình thanh: 折 (chiết) cho âm, 足 (túc, chân) cho nghĩa. Chữ mang nghĩa đi đi lại lại, quay lại giữa đường, hoặc lượn vòng. Cấu trúc gợi hình ảnh đôi chân bẻ hướng, quay ngược trở lại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đi đi lại lại", "Hạng Tần Suất (Jun Da)": "5221.0", "Tần Suất % (Jun Da)": "99.9412441141", "GavinGrover_Once (Chiết tự trực tiếp)": "折 + 足", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱折足", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "折", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "足", "Unihan_Simplified (Chữ Giản thể)": "踅", "Unihan_Traditional (Chữ Phồn thể)": "踅", "Pinyin_Xie": "xué", "Âm Hán Việt_Xie": "tuyệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động đi quanh quẩn hoặc quay người trở lại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馓', '{"9000": "5222.0", "Chữ Trung Quốc": "馓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 15 | nét | 馓 | tán | tượng hình | loại bánh rán | 馓 thuộc bộ 食 (thực). Chữ chỉ một loại bánh chiên giòn từ bột mì, không có dữ liệu cấu trúc chi tiết trong nguồn tra cứu. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tán\": bộ 食 (thực, ăn) — loại bánh chiên giòn tan, ăn là tán ra thành từng miếng nhỏ. | Gương Hán-Việt | tán — ít dùng trong tiếng Việt, chủ yếu trong ngữ cảnh ẩm thực | Mở khoá kiến thức | Biết 馓 giúp nhận ra món 馓子 (tán tử) — bánh chiên giòn truyền thống của người Hồi và nhiều vùng Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Không có nguồn Wiktionary glyph-origin chi tiết cho 馓. Chữ thuộc bộ 食 (thực, thức ăn), chỉ loại bánh chiên giòn làm từ bột mì — gọi là 馓子 (tán tử) trong tiếng Hán. Đây là món ăn truyền thống phổ biến ở nhiều vùng Trung Quốc và cộng đồng Hồi giáo. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bánh rán", "Hạng Tần Suất (Jun Da)": "5222.0", "Tần Suất % (Jun Da)": "99.9413169808", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 散", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣散", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "散", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "馓", "Unihan_Traditional (Chữ Phồn thể)": "饊", "Pinyin_Xie": "sǎn", "Âm Hán Việt_Xie": "tản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ loại bánh bột mì chiên giòn trong ẩm thực truyền thống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟛', '{"9000": "5223.0", "Chữ Trung Quốc": "蟛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 18 | nét | 蟛 | bành | tượng hình | loài cua đất | 蟛 thuộc bộ 虫 (trùng). Chữ chỉ con cua đất nhỏ (蟛蜞), không có dữ liệu cấu trúc chi tiết trong nguồn tra cứu. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bành\": bộ 虫 (trùng, sinh vật) — con cua bành kỳ nhỏ xíu sống dưới bùn. | Gương Hán-Việt | bành — trong 蟛蜞 (bành kỳ), cua nhỏ vùng bùn lầy | Mở khoá kiến thức | Biết 蟛 mở khoá từ 蟛蜞 (bành kỳ) — loài cua nhỏ quen thuộc trong ẩm thực và văn học miền sông nước.", "Tự nguyên_Xie": "Không có nguồn Wiktionary glyph-origin chi tiết cho 蟛. Chữ thuộc bộ 虫 (trùng, sâu bọ/sinh vật nhỏ), chỉ dùng trong từ 蟛蜞 (bành kỳ) — loài cua nhỏ sống ở vùng bùn lầy ven biển và sông. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bành kỳ 蟛蜞)", "Hạng Tần Suất (Jun Da)": "5223.0", "Tần Suất % (Jun Da)": "99.9413898475", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 彭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫彭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟛", "Unihan_Traditional (Chữ Phồn thể)": "蟛", "Pinyin_Xie": "péng", "Âm Hán Việt_Xie": "bành", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong từ ghép để chỉ một loài cua nhỏ sống ở vùng nước lợ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳟', '{"9000": "5224.0", "Chữ Trung Quốc": "鳟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 20 | nét | 鳟 | tôn | tượng hình | cá chày, cá trout | 鳟 là dạng giản thể của 鱒, thay bộ 魚 bằng 鱼. Chữ thuộc bộ 鱼 (ngư, cá), chỉ loài cá chày hay cá trout. Cấu trúc gốc gồm bộ 魚/鱼 (ngư, biểu nghĩa) và phần biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tôn\": bộ 鱼 (ngư, cá) — loài cá mà người ta tôn trọng vì ngon thịt, chính là cá trout hay cá chày. | Gương Hán-Việt | tôn — ít dùng trong tiếng Việt, chủ yếu trong ngữ cảnh sinh học/ẩm thực | Mở khoá kiến thức | Biết 鳟 giúp nhận ra 鳟鱼 (tôn ngư) — cá hồi/cá trout trong thực đơn nhà hàng Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 鳟 là dạng giản thể của 鱒. Theo Wiktionary, 鱒 gồm bộ 魚 (ngư, cá) cho nghĩa và phần biểu âm. Chữ chỉ loài cá chày (barbel) hoặc cá trout. Dạng giản thể 鳟 thay 魚 bằng 鱼 theo quy tắc giản hóa chữ Hán hiện đại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá chày", "Hạng Tần Suất (Jun Da)": "5224.0", "Tần Suất % (Jun Da)": "99.9414627142", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 尊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼尊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳟", "Unihan_Traditional (Chữ Phồn thể)": "鱒", "Pinyin_Xie": "zūn", "Âm Hán Việt_Xie": "tôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các loài cá thuộc họ cá hồi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荛', '{"9000": "5225.0", "Chữ Trung Quốc": "荛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 荛 | nhiêu | tượng hình | củi, cây làm giấy | 荛 là dạng giản thể của 蕘, thay 堯 bằng 尧. Chữ thuộc bộ 艹 (thảo, cây cỏ), chỉ loại cây làm củi hoặc làm giấy, hay người đi kiếm củi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhiêu\": bộ 艹 (thảo, cây) — cây nhiêu mọc dại, dùng làm củi hay làm giấy, người nghèo đi nhặt. | Gương Hán-Việt | nhiêu — ít dùng trong tiếng Việt hiện đại, chủ yếu trong văn cổ | Mở khoá kiến thức | Biết 荛 giúp hiểu hình ảnh người tiều phu (刍荛之言) trong thành ngữ Hán — ý kiến của người bình dân.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 荛 là dạng giản thể của 蕘. Chữ thuộc bộ 艹 (thảo, cây cỏ). Nghĩa gốc là củi rạc, cành khô; người đi kiếm củi. Cũng chỉ cây Wikstroemia japonica (nhiêu mộc) — loài cây vỏ dùng làm giấy truyền thống. Dạng giản thể thay 堯 bằng 尧. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "củi rạc, củi khô; người kiếm củi; cây nhiêu (vỏ dùng làm giấy)", "Hạng Tần Suất (Jun Da)": "5225.0", "Tần Suất % (Jun Da)": "99.9415355809", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 尧", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹尧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荛", "Unihan_Traditional (Chữ Phồn thể)": "蕘", "Pinyin_Xie": "ráo", "Âm Hán Việt_Xie": "nhiêu, nghiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn viết cổ để chỉ củi khô hoặc người đốn củi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菬', '{"9000": "5226.0", "Chữ Trung Quốc": "菬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菬 | trảo | tượng hình | một loại cây (định nghĩa chưa rõ) | 菬 thuộc bộ 艹 (thảo, cây cỏ). Chữ này cực kỳ hiếm gặp, Wiktionary chưa có định nghĩa rõ ràng (rfdef). Âm đọc có nhiều biến thể: huā, huà, zhǎo, ziu2. Cấu tạo và nghĩa chính xác chưa được xác định trong học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trảo\": bộ 艹 (thảo, cây) — một loài cỏ/cây chưa được định danh rõ, hiếm gặp đến mức từ điển cũng chưa có định nghĩa. | Gương Hán-Việt | trảo — cực hiếm trong tiếng Việt, chủ yếu gặp trong danh sách chữ Hán hiếm | Mở khoá kiến thức | Biết 菬 giúp nhận ra chữ Hán hiếm thuộc bộ 艹, thường xuất hiện trong danh sách chữ cổ.", "Tự nguyên_Xie": "Theo Wiktionary, 菬 thuộc bộ 艹 (thảo). Chữ này chưa có định nghĩa rõ ràng (rfdef — request for definition). Âm đọc ghi nhận: m=huā/huà/zhǎo, Quảng Đông: ziu2/ciu4. Đây là chữ cực hiếm, chưa có nguồn học thuật đầy đủ. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "茬", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 沼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹沼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "沼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菬", "Unihan_Traditional (Chữ Phồn thể)": "菬", "Pinyin_Xie": "qiáo", "Âm Hán Việt_Xie": "trảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn cổ để chỉ phần gốc rạ còn lại trên ruộng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('忪', '{"9000": "5227.0", "Chữ Trung Quốc": "忪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 7 | nét | 忪 | tụng | tượng hình | hoảng sợ, xúc động | 忪 thuộc bộ 忄(tâm). Chữ chỉ trạng thái hoảng sợ, xúc động, hay yên tĩnh (tùy âm đọc). Không có dữ liệu cấu trúc chi tiết từ nguồn tra cứu — chữ tạo muộn, chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tụng\": bộ 忄(tâm, lòng) — lòng đang xúc động, hoảng sợ hay bỗng nhiên yên tĩnh như sau một cơn choáng. | Gương Hán-Việt | tụng — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 忪 giúp đọc hiểu văn học cổ miêu tả trạng thái tâm lý: hoảng loạn (惊忪) hay vừa tỉnh giấc.", "Tự nguyên_Xie": "Theo Wiktionary, 忪 thuộc bộ 忄(tâm, lòng). Chữ có hai âm đọc: sōng (yên tĩnh, bình thản) và zhōng (hoảng sợ, kinh hãi). Cấu trúc chi tiết chưa được ghi lại trong nguồn tra cứu. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xúc động; hoảng sợ, khiếp sợ", "Hạng Tần Suất (Jun Da)": "5227.0", "Tần Suất % (Jun Da)": "99.9416807976", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 公", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄公", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "公", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "忪", "Unihan_Traditional (Chữ Phồn thể)": "忪", "Pinyin_Xie": "sōng", "Âm Hán Việt_Xie": "chung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường kết hợp với từ khác làm tính từ miêu tả trạng thái tâm lý lo lắng, sợ hãi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阍', '{"9000": "5228.0", "Chữ Trung Quốc": "阍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 11 | nét | 阍 | hôn | tượng hình | cửa cung điện, lính canh cửa | 阍 thuộc bộ 门 (môn, cửa). Chữ chỉ cửa cung điện hoặc người lính canh cổng. Không có dữ liệu glyph-origin chi tiết, nhưng bộ 门 rõ ràng gợi nghĩa cổng, cửa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hôn\": bộ 门 (môn, cửa) — người canh cổng đứng trong bóng tối lúc chập choạng tối (hôn, tối tăm), gác cửa cung vua. | Gương Hán-Việt | hôn — trong hôn nhân (阍, hôn) và văn học cổ về người canh cổng | Mở khoá kiến thức | Biết 阍 giúp đọc hiểu thơ văn cổ nói về 阍者 (hôn giả) — người gác cổng cung điện.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Không có nguồn Wiktionary glyph-origin chi tiết cho 阍. Chữ thuộc bộ 门 (môn, cửa). Nghĩa: cửa cung điện; người canh gác cổng (阍者, 阍人). Dùng nhiều trong văn học cổ điển và thơ văn. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên lính canh cửa; cửa cung điện", "Hạng Tần Suất (Jun Da)": "5228.0", "Tần Suất % (Jun Da)": "99.9417531475", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 昏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门昏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阍", "Unihan_Traditional (Chữ Phồn thể)": "閽", "Pinyin_Xie": "hūn", "Âm Hán Việt_Xie": "hôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ người gác cổng hoặc cổng cung điện trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('姹', '{"9000": "5229.0", "Chữ Trung Quốc": "姹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 9 | nét | 姹 | sá | tượng hình | xinh đẹp, rực rỡ | 姹 thuộc bộ 女 (nữ). Chữ chỉ vẻ đẹp rực rỡ, mỹ lệ. Không có dữ liệu glyph-origin chi tiết — chữ tạo muộn, chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sá\": bộ 女 (nữ) — người con gái rực rỡ như hoa, là 姹 trong thành ngữ 姹紫嫣红 (muôn màu hoa đẹp). | Gương Hán-Việt | sá — trong 姹紫嫣红 (sá tử yên hồng), thành ngữ tả hoa đẹp | Mở khoá kiến thức | Biết 姹 mở khoá thành ngữ nổi tiếng 姹紫嫣红 — tả cảnh trăm hoa đua nở rực rỡ.", "Tự nguyên_Xie": "Không có nguồn Wiktionary glyph-origin chi tiết cho 姹. Chữ thuộc bộ 女 (nữ, phụ nữ). Nghĩa: xinh đẹp, rực rỡ, mỹ lệ. Thường dùng trong 姹紫嫣红 (sá tử yên hồng) — thành ngữ chỉ trăm hoa đua nở rực rỡ. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xinh đẹp; mỹ lệ", "Hạng Tần Suất (Jun Da)": "5229.0", "Tần Suất % (Jun Da)": "99.9418254974", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 宅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女宅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "姹", "Unihan_Traditional (Chữ Phồn thể)": "奼", "Pinyin_Xie": "chà", "Âm Hán Việt_Xie": "xá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ trong các cụm từ miêu tả vẻ đẹp rực rỡ của hoa lá. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纰', '{"9000": "5230.0", "Chữ Trung Quốc": "纰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 7 | nét | 纰 | ti | tượng hình | lụa dệt lỗi, lỗi lầm | 纰 thuộc bộ 纟(mịch, sợi tơ). Chữ chỉ lụa dệt lỗi, hoặc lỗi lầm, bất cẩn. Không có dữ liệu glyph-origin chi tiết — chữ tạo muộn, chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ti\": bộ 纟(mịch, sợi tơ) — tấm lụa dệt bị lỗi sợi, tượng trưng cho sơ suất, cẩu thả. | Gương Hán-Việt | ti — ít dùng trong tiếng Việt, chủ yếu trong từ chuyên dụng | Mở khoá kiến thức | Biết 纰 mở khoá từ 纰漏 (ti lậu) — sơ suất, lỗi lầm không đáng có.", "Tự nguyên_Xie": "Tiểu triện | Không có nguồn Wiktionary glyph-origin chi tiết cho 纰. Chữ thuộc bộ 纟(mịch, sợi tơ). Nghĩa gốc: lụa dệt kém chất lượng, bị lỗi; mép vải. Nghĩa mở rộng: sai lầm, bất cẩn. Thường dùng trong từ 纰漏 (ti lậu — sơ suất, lỗi lầm). chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lỗi, bất cẩn; lụa dệt lỗi", "Hạng Tần Suất (Jun Da)": "5230.0", "Tần Suất % (Jun Da)": "99.9418978473", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 比", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟比", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "比", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "纰", "Unihan_Traditional (Chữ Phồn thể)": "紕", "Pinyin_Xie": "pī", "Âm Hán Việt_Xie": "phi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ hoặc kết hợp tạo từ ghép để chỉ những sai sót trong công việc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桉', '{"9000": "5231.0", "Chữ Trung Quốc": "桉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 安 | an | biểu âm | yên bình | 桉 = 木 (Mộc, biểu nghĩa: cây) + 安 (An, biểu âm); chữ hình thanh. Bộ 木 chỉ đây là loài cây; phần 安 cho âm ān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"an\": bộ 木 (mộc, cây) + 安 (an) — cây bạch đàn mang tên An, mọc thẳng tắp như sự yên bình. | Gương Hán-Việt | an — trong 桉树 (an thụ) là cây bạch đàn | Mở khoá kiến thức | Biết 桉 mở khoá 桉树 (an thụ) — cây bạch đàn, loài cây trồng phổ biến ở miền Nam Trung Quốc và Việt Nam.", "Tự nguyên_Xie": "Theo Wiktionary, 桉 là chữ hình thanh: 木 (mộc, cây) cho nghĩa, 安 (an, ān) cho âm. Chữ chỉ cây bạch đàn (eucalyptus) — loài cây được nhập khẩu vào Trung Quốc và đặt tên Hán theo âm ''an''. Cũng là tên cổ của một loại bàn dài. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bàn dài; bản án", "Hạng Tần Suất (Jun Da)": "5231.0", "Tần Suất % (Jun Da)": "99.9419701972", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 安", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木安", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "安", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桉", "Unihan_Traditional (Chữ Phồn thể)": "桉", "Pinyin_Xie": "ān", "Âm Hán Việt_Xie": "an", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ cây bạch đàn hoặc các bộ phận liên quan. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氪', '{"9000": "5232.0", "Chữ Trung Quốc": "氪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 气 | Số nét | 11 | nét | 气 | khí | biểu nghĩa | khí, hơi | 克 | khắc | biểu âm | 氪 = 气 (Khí, biểu nghĩa: khí, hơi) + 克 (Khắc, biểu âm); chữ hình thanh. Bộ 气 chỉ đây là nguyên tố khí; phần 克 cho âm kè.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khắc\": bộ 气 (khí) + 克 (khắc) — khí krypton, loại khí khắc phục được bóng tối khi dùng trong đèn điện. | Gương Hán-Việt | khắc — trong 氪气 (khắc khí) là khí krypton | Mở khoá kiến thức | Biết 氪 giúp đọc hiểu bảng tuần hoàn tiếng Hán: 氪 (krypton, Kr) cùng nhóm khí hiếm với 氖 (neon), 氩 (argon).", "Tự nguyên_Xie": "Theo Wiktionary, 氪 là chữ hình thanh hiện đại: 气 (khí) cho nghĩa nguyên tố khí, 克 (khắc, kè) cho âm. Chữ tạo ra để phiên âm tên nguyên tố krypton (Kr) — nguyên tố khí hiếm số 36 trong bảng tuần hoàn. Đây là chữ tạo muộn, thuộc nhóm chữ Hán ký hiệu hóa học. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố krypton, Kr", "Hạng Tần Suất (Jun Da)": "5232.0", "Tần Suất % (Jun Da)": "99.9420425471", "GavinGrover_Once (Chiết tự trực tiếp)": "气 + 克", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴气克", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "克", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "气", "Unihan_Simplified (Chữ Giản thể)": "氪", "Unihan_Traditional (Chữ Phồn thể)": "氪", "Pinyin_Xie": "kè", "Âm Hán Việt_Xie": "khắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chuyên ngành hóa học để chỉ nguyên tố khí hiếm Krypton. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氘', '{"9000": "5233.0", "Chữ Trung Quốc": "氘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 气 | Số nét | 6 | nét | 气 | khí | biểu nghĩa | khí, hơi | ⿰丿丨 | biểu âm / biểu nghĩa | hai (biến thể của 刀) | 氘 = 气 (Khí, biểu nghĩa) + ⿰丿丨 (biến thể của 刀 — âm dāo, hoặc biểu số hai); chữ hội ý kiêm hình thanh. Bộ 气 chỉ nguyên tố khí; phần ⿰丿丨 (hai nét) gợi đồng vị thứ hai của hydro. Wiktionary ghi nhận cả ls=ic (hội ý) và psc (hình thanh).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đao\": bộ 气 (khí) + hai nét (số 2) — đồng vị thứ hai của hydro, nặng gấp đôi. | Gương Hán-Việt | đao — trong 氘气 (đao khí) là khí deuterium | Mở khoá kiến thức | Biết 氘 giúp đọc bảng đồng vị trong tài liệu hóa học/vật lý hạt nhân tiếng Hán: 氕氘氚 (ba đồng vị của hydro).", "Tự nguyên_Xie": "Theo Wiktionary, 氘 là chữ hội ý: 气 (khí, hơi) kết hợp ⿰丿丨 (biểu số hai, hoặc biến thể của 刀 dāo làm phần biểu âm). Chữ chỉ đồng vị deuterium (D) của hydro — nguyên tử nặng với 1 proton và 1 neutron. So sánh: 氕 (protium, đồng vị 1) và 氚 (tritium, đồng vị 3). Đây là chữ tạo muộn cho khoa học hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồng vị đơtri (D) của hydro (H)", "Hạng Tần Suất (Jun Da)": "5233.0", "Tần Suất % (Jun Da)": "99.9421148971", "GavinGrover_Once (Chiết tự trực tiếp)": "气 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴气", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "氘", "Unihan_Traditional (Chữ Phồn thể)": "氘", "Pinyin_Xie": "dāo", "Âm Hán Việt_Xie": "đao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong khoa học để chỉ đồng vị hydro nặng có ký hiệu là D. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垅', '{"9000": "5234.0", "Chữ Trung Quốc": "垅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 8 | nét | 土 | thổ | biểu nghĩa | đất | 龍 | long | biểu âm | 垅 = 土 (Thổ, biểu nghĩa: đất) + 龍 (Long, biểu âm); chữ hình thanh. Bộ 土 chỉ đây liên quan đến đất; phần 龍 cho âm lǒng. Là biến thể giản thể của 壟.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lũng\": bộ 土 (thổ, đất) + 龍 (long) — luống đất nổi cao như lưng rồng trên cánh đồng. | Gương Hán-Việt | lũng — trong địa danh như Long 垅 (Lũng) | Mở khoá kiến thức | Biết 垅 giúp nhận ra từ 田垅 (điền lũng) — luống ruộng, hình ảnh phổ biến trong thơ ca nông thôn.", "Tự nguyên_Xie": "Theo Wiktionary, 垅 là dạng biến thể của 壟, hình thanh: 土 (thổ, đất) cho nghĩa, 龍 (long) cho âm lǒng. Chữ chỉ luống cày trong ruộng, hoặc gò mả. Thường dùng trong một số tên riêng theo ghi chú Wiktionary. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "luống cày", "Hạng Tần Suất (Jun Da)": "5234.0", "Tần Suất % (Jun Da)": "99.9421867302", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 龙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土龙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "垅", "Unihan_Traditional (Chữ Phồn thể)": "壠", "Pinyin_Xie": "lǒng", "Âm Hán Việt_Xie": "lũng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ chỉ bờ ruộng hoặc luống đất trồng trọt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郃', '{"9000": "5235.0", "Chữ Trung Quốc": "郃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 8 | nét | 郃 | hợp | tượng hình | tên huyện cổ | 郃 thuộc bộ 阝 (ấp, địa danh). Chữ là tên địa danh cổ — huyện Hợp thuộc tỉnh Thiểm Tây. Cấu trúc chi tiết không rõ trong nguồn tra cứu — chữ tạo muộn, chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hợp\": bộ 阝 (ấp, đất đai) — vùng đất Hợp, huyện cổ ở Thiểm Tây, nơi hội tụ (hợp) nhiều con đường. | Gương Hán-Việt | hợp — trong địa danh cổ Trung Hoa, tên huyện | Mở khoá kiến thức | Biết 郃 giúp nhận ra tên địa danh cổ và họ người trong lịch sử Trung Hoa.", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary, 郃 là tên huyện thuộc tỉnh Thiểm Tây (Shanxi/Shaanxi). Chữ thuộc bộ 阝 (ấp, đơn vị hành chính). Âm đọc: hé (phổ thông), gap3/hap6 (Quảng Đông). Cấu trúc chi tiết chưa rõ trong học thuật. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "5235.0", "Tần Suất % (Jun Da)": "99.9422585633", "GavinGrover_Once (Chiết tự trực tiếp)": "合 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰合阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "合", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郃", "Unihan_Traditional (Chữ Phồn thể)": "郃", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "cáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ địa danh hoặc họ người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('汊', '{"9000": "5236.0", "Chữ Trung Quốc": "汊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 6 | nét | 水 | thủy | biểu nghĩa | nước | 叉 | xoa | biểu âm | giao nhau, chĩa | 汊 = 水/氵 (Thủy, biểu nghĩa: nước) + 叉 (Xoa, biểu âm kiêm biểu nghĩa: giao nhau); chữ hình thanh kiêm hội ý. Bộ 水 chỉ đây là dòng nước; phần 叉 vừa cho âm chà vừa gợi hình dòng nước rẽ nhánh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xoà\": bộ 水 (thủy, nước) + 叉 (xoa, rẽ nhánh) — sông xòa ra như bàn tay, phân nhánh chằng chịt. | Gương Hán-Việt | xoà — trong 汊港 (xoà cảng), 汊河 (sông nhánh) | Mở khoá kiến thức | Biết 汊 mở khoá từ địa lý 汊道 (nhánh sông), 汊港 — thường gặp trong tên địa danh vùng sông nước miền Nam Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 汊 là chữ hình thanh kiêm hội ý: 水 (thủy, nước) cho nghĩa, 叉 (xoa, chà) vừa cho âm vừa gợi hình ảnh giao nhau/rẽ nhánh. Chữ chỉ dòng nhánh, chỗ dòng nước phân ra hai hay nhiều nhánh. Hình ảnh rất trực quan: sông rẽ chĩa như chữ 叉. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dòng nhánh, dòng nước chảy rẽ", "Hạng Tần Suất (Jun Da)": "5236.0", "Tần Suất % (Jun Da)": "99.9423303965", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 叉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵叉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "汊", "Unihan_Traditional (Chữ Phồn thể)": "汊", "Pinyin_Xie": "chà", "Âm Hán Việt_Xie": "xá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các nhánh sông nhỏ rẽ ra từ dòng chính. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('娉', '{"9000": "5237.0", "Chữ Trung Quốc": "娉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 10 | nét | 娉 | sính | tượng hình | xinh đẹp, duyên dáng | 娉 thuộc bộ 女 (nữ). Chữ chỉ vẻ đẹp duyên dáng, yểu điệu của phụ nữ. Cũng dùng trong từ 娉婷 (sính đình) — dáng đi thướt tha. Không có dữ liệu glyph-origin chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sính\": bộ 女 (nữ) — người con gái duyên dáng như trong từ 聘礼 (sính lễ), nhà trai phải hỏi mới cưới được. | Gương Hán-Việt | sính — trong 娉婷 (sính đình) dáng đi yểu điệu, thướt tha | Mở khoá kiến thức | Biết 娉 mở khoá từ thơ 娉婷 (sính đình) — dáng đứng thướt tha của người đẹp, quen thuộc trong thơ cổ Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 娉 có âm pīng (duyên dáng, đẹp) và âm pìng (hỏi cưới, sính lễ). Chữ thuộc bộ 女 (nữ). Cấu trúc chi tiết không rõ trong học thuật. Nghĩa chính: xinh đẹp, duyên dáng; cũng có nghĩa đi hỏi cưới. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con gái đẹp", "Hạng Tần Suất (Jun Da)": "5237.0", "Tần Suất % (Jun Da)": "99.9424022296", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 甹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女甹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "娉", "Unihan_Traditional (Chữ Phồn thể)": "娉", "Pinyin_Xie": "pīng", "Âm Hán Việt_Xie": "phinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ miêu tả vẻ đẹp thanh tú của người phụ nữ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纡', '{"9000": "5238.0", "Chữ Trung Quốc": "纡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 6 | nét | 纡 | vu | tượng hình | quanh co, uốn khúc | 纡 là dạng giản thể của 紆, thay bộ 糹 bằng 纟. Chữ thuộc bộ 纟(mịch, sợi tơ). Nghĩa: quanh co, uốn khúc — như sợi tơ bị vặn xoắn. Cấu trúc gốc của 紆 gồm bộ 糹 (mịch) và phần biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vu\": bộ 纟(mịch, sợi) — sợi chỉ xoắn vu vơ, quanh co không thẳng hướng. | Gương Hán-Việt | vu — trong 纡曲 (vu khúc) quanh co, văn học cổ | Mở khoá kiến thức | Biết 纡 mở khoá từ 纡尊降贵 (vu tôn giáng quý) — hạ mình chịu khó, thành ngữ văn học cổ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 纡 là dạng giản thể của 紆. Theo Wiktionary, 紆 gồm bộ 糹 (mịch, sợi tơ) cho nghĩa và phần biểu âm. Nghĩa: uốn cong, quanh co, xoắn lại. Cũng dùng trong văn cổ với nghĩa ''hạ thấp mình'' (纡尊降贵). Dạng giản thể thay 糹 bằng 纟. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quanh co", "Hạng Tần Suất (Jun Da)": "5238.0", "Tần Suất % (Jun Da)": "99.9424740627", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 于", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟于", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "于", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "纡", "Unihan_Traditional (Chữ Phồn thể)": "紆", "Pinyin_Xie": "yū", "Âm Hán Việt_Xie": "u", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ chỉ sự quanh co hoặc làm động từ chỉ hành động uốn cong. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缟', '{"9000": "5239.0", "Chữ Trung Quốc": "缟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 糸 | mịch | biểu nghĩa | sợi tơ, lụa | 高 | cao | biểu âm | cao | 缟 = 糸/纟(Mịch, biểu nghĩa: sợi tơ, lụa) + 高 (Cao, biểu âm); chữ hình thanh. Bộ 纟chỉ đây liên quan đến tơ lụa; phần 高 cho âm gǎo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cảo\": bộ 纟(mịch, lụa) + 高 (cao) — tấm lụa trắng tinh khiết, cao quý như tuyết trắng. | Gương Hán-Việt | cảo — trong 缟素 (cảo tố) màu trắng tang, văn học cổ | Mở khoá kiến thức | Biết 缟 giúp đọc hiểu văn thơ cổ: 缟素 (cảo tố) chỉ màu trắng tang lễ, hoặc lụa trắng thuần khiết.", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary, 缟 là chữ hình thanh: 糸 (mịch, sợi tơ) cho nghĩa, 高 (cao, gǎo) cho âm. Chữ chỉ lụa trắng mỏng, lụa thô chưa nhuộm màu. Trong văn cổ, màu trắng của 缟 tượng trưng cho sự thanh khiết và tang lễ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tre thuộc mỏng", "Hạng Tần Suất (Jun Da)": "5239.0", "Tần Suất % (Jun Da)": "99.9425458959", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 高", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟高", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "高", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缟", "Unihan_Traditional (Chữ Phồn thể)": "縞", "Pinyin_Xie": "gǎo", "Âm Hán Việt_Xie": "cảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ loại lụa trắng hoặc làm tính từ chỉ màu trắng tinh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('旮', '{"9000": "5240.0", "Chữ Trung Quốc": "旮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 6 | nét | 旮 | ca | tượng hình | góc khuất, xó xỉnh | 旮 thuộc bộ 日 (nhật). Chữ chỉ dùng trong từ 旮旯 (ca lạp) — nghĩa góc khuất, xó tối. Không có nguồn glyph-origin, chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ca\": bộ 日 (nhật, mặt trời) — nơi mà ánh mặt trời không chiếu tới, là góc khuất 旮旯. | Gương Hán-Việt | ca — ít dùng trong tiếng Việt, chủ yếu trong từ 旮旯 | Mở khoá kiến thức | Biết 旮 mở khoá từ phương ngữ Bắc Kinh 旮旯 (gā lá) — góc khuất, xó xỉnh, thường dùng trong văn học dân gian.", "Tự nguyên_Xie": "Không có nguồn Wiktionary glyph-origin chi tiết cho 旮. Chữ thuộc bộ 日 (nhật). Chỉ dùng trong từ 旮旯 (gā lá) — góc khuất, xó xỉnh, nơi tối tăm hẻo lánh. Đây là chữ tạo muộn, phương ngữ Bắc Kinh, chưa thấy trong giáp cốt/kim văn. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ca lạp 旮旯)", "Hạng Tần Suất (Jun Da)": "5240.0", "Tần Suất % (Jun Da)": "99.942617729", "GavinGrover_Once (Chiết tự trực tiếp)": "九 + 日", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱九日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "九", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "旮", "Unihan_Traditional (Chữ Phồn thể)": "旮", "Pinyin_Xie": "gā", "Âm Hán Việt_Xie": "ca", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và thường kết hợp thành từ ghép để chỉ góc khuất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镢', '{"9000": "5241.0", "Chữ Trung Quốc": "镢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 镢 | quắc | tượng hình | cuốc chim, cuốc lớn | 镢 thuộc bộ 金/钅(kim, kim loại). Chữ chỉ cái cuốc lớn dùng trong nông nghiệp. Wiktionary có ghi nghĩa nhưng không có phân tích glyph-origin chi tiết — chữ tạo muộn, chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quắc\": bộ 钅(kim, sắt) — cái cuốc bằng sắt quắc xuống đất, làm nông cụ khai phá. | Gương Hán-Việt | quắc — ít dùng trong tiếng Việt, chủ yếu trong từ nông cụ | Mở khoá kiến thức | Biết 镢 giúp nhận ra nông cụ 镢头 (quắc đầu) — cuốc chim lớn, phổ biến ở nông thôn miền Bắc Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 镢 là tên nông cụ: cuốc chim, cuốc lớn (hoe/mattock). Chữ thuộc bộ 金/钅(kim, kim loại) gợi đây là dụng cụ bằng kim loại. Phần biểu âm không rõ trong học thuật. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cuốc chim; quắc; như \"quắc (cái búa chim)\" \n (Danh) Cái cuốc lớn (nông cụ).", "Hạng Tần Suất (Jun Da)": "5241.0", "Tần Suất % (Jun Da)": "99.9426895621", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 厥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅厥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镢", "Unihan_Traditional (Chữ Phồn thể)": "鐝", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại nông cụ dùng để đào đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('傈', '{"9000": "5242.0", "Chữ Trung Quốc": "傈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 12 | nét | 傈 | lật | tượng hình | tộc Lật Túc (Lisu) | 傈 thuộc bộ 亻(nhân, người). Chữ chỉ dùng trong tên tộc người 傈僳 (lật túc) — dân tộc Lisu sinh sống ở Vân Nam và Tứ Xuyên. Không có dữ liệu glyph-origin, chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lật\": bộ 亻(nhân, người) — người dân tộc Lật Túc (傈僳) sống trên núi cao Vân Nam. | Gương Hán-Việt | lật — trong 傈僳族 (lật túc tộc) — dân tộc Lisu | Mở khoá kiến thức | Biết 傈 mở khoá tên dân tộc 傈僳族 — người Lisu, dân tộc thiểu số ở Vân Nam Trung Quốc và Thái Lan.", "Tự nguyên_Xie": "Không có nguồn Wiktionary glyph-origin chi tiết cho 傈. Chữ thuộc bộ 亻(nhân, người). Chỉ dùng trong từ 傈僳 (lì sù) — tên dân tộc Lisu (Lật Túc), một trong 56 dân tộc Trung Quốc, sống chủ yếu ở tỉnh Vân Nam. Đây là chữ tạo muộn dùng để phiên âm tên dân tộc. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lật túc 傈僳)", "Hạng Tần Suất (Jun Da)": "5242.0", "Tần Suất % (Jun Da)": "99.9427613953", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "傈", "Unihan_Traditional (Chữ Phồn thể)": "傈", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng dùng trong tên gọi của dân tộc Lật Túc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('堋', '{"9000": "5243.0", "Chữ Trung Quốc": "堋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 11 | nét | 堋 | bằng | tượng hình | đê phân lũ, chôn cất | 堋 thuộc bộ 土 (thổ, đất). Chữ có nghĩa đê phân lũ thời xưa, hoặc liên quan đến chôn cất. Wiktionary có ghi âm và một số nghĩa nhưng không có phân tích cấu trúc chi tiết. Chữ tạo muộn, chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bằng\": bộ 土 (thổ, đất) — đắp đất thành bờ bằng để phân nước lũ, hay đắp đất chôn người. | Gương Hán-Việt | bằng — ít dùng trong tiếng Việt, chủ yếu trong văn cổ | Mở khoá kiến thức | Biết 堋 giúp đọc hiểu văn bản lịch sử về hệ thống thủy lợi cổ đại Trung Hoa.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 堋 thuộc bộ 土 (thổ, đất). Âm đọc: bèng (phổ thông), bang1/bing3 (Quảng Đông). Nghĩa: đê phân lũ; chôn cất (động từ văn ngôn). Cấu trúc chi tiết không rõ. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đê phân lũ (thời xưa)", "Hạng Tần Suất (Jun Da)": "5243.0", "Tần Suất % (Jun Da)": "99.9428327116", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 朋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土朋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "堋", "Unihan_Traditional (Chữ Phồn thể)": "堋", "Pinyin_Xie": "péng", "Âm Hán Việt_Xie": "bằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ công trình đê đập hoặc bia ngắm bắn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔺', '{"9000": "5244.0", "Chữ Trung Quốc": "蔺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 蔺 | lận | tượng hình | cỏ cói dệt chiếu; họ Lận | 蔺 thuộc bộ 艹 (thảo, cây cỏ). Chữ chỉ loài cỏ lận (soft rush) dùng dệt chiếu; cũng là họ người nổi tiếng trong lịch sử Trung Hoa (Lận Tương Như). Không có phân tích cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lận\": bộ 艹 (thảo, cỏ) — cây cói lận để dệt chiếu; họ Lận nổi tiếng với Lận Tương Như, người không sợ uy quyền. | Gương Hán-Việt | lận — trong họ Lận (蔺) và tên cây cói | Mở khoá kiến thức | Biết 蔺 mở khoá tên danh nhân lịch sử 蔺相如 (Lận Tương Như) — chính khách kiêm ngoại giao tài ba nước Triệu.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 蔺 thuộc bộ 艹 (thảo). Nghĩa: cỏ lận mềm (common rush, soft rush) — loài cây lá dài dùng dệt chiếu cói; cũng là họ người (họ Lận). Nổi tiếng nhất là Lận Tương Như (蔺相如) — tể tướng nước Triệu thời Chiến Quốc. chưa có nguồn học thuật đầy đủ về glyph-origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ lận, có cói (để dệt chiếu); họ Lận", "Hạng Tần Suất (Jun Da)": "5244.0", "Tần Suất % (Jun Da)": "99.942904028", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 𫕶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹𫕶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𫕶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔺", "Unihan_Traditional (Chữ Phồn thể)": "藺", "Pinyin_Xie": "lìn", "Âm Hán Việt_Xie": "lận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cỏ bấc hoặc dùng làm họ người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('庥', '{"9000": "5245.0", "Chữ Trung Quốc": "庥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 9 | nét | 庥 | hưu | tượng hình | bóng mát, che chở; nghỉ ngơi | 庥 thuộc bộ 广 (nghiễm, mái che). Chữ gợi hình ảnh được che chở dưới mái, nghỉ ngơi trong bóng mát. Không có dữ liệu glyph-origin chi tiết — chữ tạo muộn, chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hưu\": bộ 广 (nghiễm, mái che) — bóng mát mát lành dưới mái che, được nghỉ ngơi bình yên (hưu). | Gương Hán-Việt | hưu — ít dùng trong tiếng Việt, liên quan đến bóng mát, che chở | Mở khoá kiến thức | Biết 庥 giúp đọc hiểu văn thơ cổ tả sự che chở, bảo hộ từ bề trên hay từ thiên nhiên.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 庥 thuộc bộ 广 (nghiễm, mái hiên). Nghĩa: bóng mát, che chở, bảo hộ; nghỉ ngơi, thôi dừng; điều tốt lành. Chữ này ít dùng trong tiếng Hán hiện đại, chủ yếu trong văn thơ cổ. chưa có nguồn học thuật đầy đủ về glyph-origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghỉ ngơi; thôi, dừng; tốt lành", "Hạng Tần Suất (Jun Da)": "5245.0", "Tần Suất % (Jun Da)": "99.9429753443", "GavinGrover_Once (Chiết tự trực tiếp)": "广 + 休", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴广休", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "休", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "广", "Unihan_Simplified (Chữ Giản thể)": "庥", "Unihan_Traditional (Chữ Phồn thể)": "庥", "Pinyin_Xie": "xiū", "Âm Hán Việt_Xie": "hưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ bóng râm che chở hoặc ân huệ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('枥', '{"9000": "5246.0", "Chữ Trung Quốc": "枥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 8 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 歷 | lịch | biểu âm | 枥 = 木 (Mộc, biểu nghĩa: cây) + 歷 (Lịch, biểu âm); chữ hình thanh. Bộ 木 chỉ đây là loài cây; phần 歷 cho âm lì. Chữ chỉ loại cây sồi, hoặc chuồng ngựa (máng ngựa).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lịch\": bộ 木 (mộc, gỗ) + 歷 (lịch) — cái máng gỗ trong chuồng ngựa, nơi 老骥伏枥 (ngựa già nằm chuồng). | Gương Hán-Việt | lịch — trong thành ngữ 老骥伏枥 (ngựa già nằm chuồng) | Mở khoá kiến thức | Biết 枥 mở khoá thành ngữ bất hủ của Tào Tháo: 老骥伏枥，志在千里 — người già vẫn có chí lớn.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 枥 là chữ hình thanh: 木 (mộc, cây) cho nghĩa, 歷 (lịch, lì) cho âm. Chữ có hai nghĩa chính: (1) loại cây sồi; (2) chuồng ngựa, máng ngựa (tương đương 历). Câu thơ nổi tiếng của Tào Tháo: ''老骥伏枥，志在千里'' (ngựa già nằm chuồng, chí còn nghìn dặm). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ổn định", "Hạng Tần Suất (Jun Da)": "5246.0", "Tần Suất % (Jun Da)": "99.9430466607", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 历", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木历", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "历", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "枥", "Unihan_Traditional (Chữ Phồn thể)": "櫪", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ đứng sau các từ chỉ ngựa để chỉ nơi nuôi dưỡng hoặc máng ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腭', '{"9000": "5247.0", "Chữ Trung Quốc": "腭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 13 | nét | 腭 | ngạc | tượng hình | vòm miệng, ngạc | 腭 thuộc bộ 肉/月 (nhục, thịt). Chữ là dạng biến thể của 顎 (ngạc), chỉ vòm miệng (palate). Cấu trúc chi tiết không có trong nguồn tra cứu — chữ tạo muộn dùng trong giải phẫu học.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạc\": bộ 月/肉 (nhục, thịt cơ thể) — phần mô thịt ở ngạc miệng (vòm miệng), quan trọng khi nuốt và phát âm. | Gương Hán-Việt | ngạc — trong 腭骨 (ngạc cốt) xương vòm miệng; 软腭 (nhuyễn ngạc) | Mở khoá kiến thức | Biết 腭 mở khoá từ y học 软腭 (vòm mềm), 硬腭 (vòm cứng) — thuật ngữ giải phẫu răng miệng và tai mũi họng.", "Tự nguyên_Xie": "Theo Wiktionary, 腭 là dạng biến thể của 顎. Chữ thuộc bộ 肉/月 (nhục, mô cơ thể). Nghĩa: vòm miệng, ngạc (palate) — phần trên của khoang miệng. Trong y học có: 软腭 (vòm mềm), 硬腭 (vòm cứng). Chữ này là thuật ngữ giải phẫu tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vòm miệng", "Hạng Tần Suất (Jun Da)": "5247.0", "Tần Suất % (Jun Da)": "99.943117977", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 咢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月咢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腭", "Unihan_Traditional (Chữ Phồn thể)": "齶", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ngạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng trước hoặc sau các từ chỉ bộ phận cơ thể để cấu tạo thuật ngữ giải phẫu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹕', '{"9000": "5248.0", "Chữ Trung Quốc": "鹕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 14 | nét | 胡 | hồ | biểu âm | 鳥 | điểu | biểu nghĩa | chim | 鹕 = 胡 (Hồ, biểu âm) + 鳥/鸟 (Điểu, biểu nghĩa: chim); chữ hình thanh. Bộ 鸟 chỉ đây là loài chim; phần 胡 cho âm hú. Chữ chỉ dùng trong 鹈鹕 (đề hồ) — con bồ nông (pelican).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồ\": bộ 鸟 (điểu, chim) + 胡 (hồ) — con chim hồ nông đánh cá bằng cái túi lớn dưới cổ. | Gương Hán-Việt | hồ — trong 鹈鹕 (đề hồ, bồ nông) | Mở khoá kiến thức | Biết 鹕 mở khoá từ 鹈鹕 (tí hú) — con bồ nông, loài chim biểu tượng của vùng sông nước nhiệt đới.", "Tự nguyên_Xie": "Theo Wiktionary, 鹕 là chữ hình thanh: 胡 (hồ) cho âm hú, 鳥 (điểu, chim) cho nghĩa. Chỉ dùng trong từ 鹈鹕 (tí hú) — con bồ nông (pelican), loài chim nước lớn có túi dưới mỏ. Đây là từ phiên âm, tên con chim đặt theo cách vay mượn ngôn ngữ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đề hồ 鵜鶘,鹈鹕)", "Hạng Tần Suất (Jun Da)": "5248.0", "Tần Suất % (Jun Da)": "99.9431892934", "GavinGrover_Once (Chiết tự trực tiếp)": "胡 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰胡鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "胡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹕", "Unihan_Traditional (Chữ Phồn thể)": "鶘", "Pinyin_Xie": "hú", "Âm Hán Việt_Xie": "hồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và hầu như chỉ xuất hiện trong từ ghép để chỉ loài chim bồ nông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笮', '{"9000": "5249.0", "Chữ Trung Quốc": "笮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 笮 | trách | tượng hình | vỉ tre, tấm đan bằng tre | 笮 thuộc bộ 竹 (trúc, tre). Chữ có hai nghĩa: (1) tấm vỉ tre đặt dưới ngói trên mái nhà; (2) túi đựng tên; (3) thúc bách, gấp rút. Cấu trúc chi tiết không có trong nguồn tra cứu — chữ tạo muộn, chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trách\": bộ 竹 (trúc, tre) — tấm đan tre trách trên mái nhà, chặt cứng giữ ngói không bị gió thổi bay. | Gương Hán-Việt | trách — ít dùng trong tiếng Việt, chủ yếu trong kiến trúc cổ | Mở khoá kiến thức | Biết 笮 giúp đọc hiểu văn bản kiến trúc và kỹ thuật xây dựng cổ đại Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 笮 thuộc bộ 竹 (trúc, tre). Nghĩa: (1) tấm vỉ tre đặt giữa hàng rui và lớp ngói trên mái nhà (dùng trong kiến trúc cổ); (2) túi đựng tên; (3) thúc bách, gấp rút (âm zǎ). Cấu trúc chi tiết không rõ. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thúc bách, gấp rút; tấm vỉ tre đặt giữa lớp ngói và hàng rui trên mái nhà; túi đựng tên", "Hạng Tần Suất (Jun Da)": "5249.0", "Tần Suất % (Jun Da)": "99.9432606097", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 乍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮乍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笮", "Unihan_Traditional (Chữ Phồn thể)": "笮", "Pinyin_Xie": "zé", "Âm Hán Việt_Xie": "trách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Tính từ | 形容词 | Chữ này có thể làm danh từ chỉ vật dụng bằng tre hoặc làm động từ chỉ hành động ép nén. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髂', '{"9000": "5250.0", "Chữ Trung Quốc": "髂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 18 | nét | 髂 | khả | tượng hình | xương chậu, xương hông | 髂 thuộc bộ 骨 (cốt, xương). Chữ chỉ xương hông/chậu (ilium) trong giải phẫu học. Không có dữ liệu glyph-origin chi tiết — chữ tạo muộn dùng trong thuật ngữ y học.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khả\": bộ 骨 (cốt, xương) — xương hông khả năng chịu lực cả người, là xương chậu quan trọng nhất. | Gương Hán-Việt | khả — trong 髂骨 (khả cốt) xương hông | Mở khoá kiến thức | Biết 髂 mở khoá thuật ngữ y học 髂骨 (ilium), 髂嵴 (iliac crest) — cần thiết khi đọc tài liệu phẫu thuật chỉnh hình.", "Tự nguyên_Xie": "Theo Wiktionary, 髂 thuộc bộ 骨 (cốt, xương). Nghĩa: xương hông (ilium) — xương lớn nhất trong xương chậu. Âm đọc: qià (phổ thông), kaa3 (Quảng Đông). Chữ là thuật ngữ giải phẫu tạo muộn. chưa có nguồn học thuật đầy đủ về glyph-origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xương chậu", "Hạng Tần Suất (Jun Da)": "5250.0", "Tần Suất % (Jun Da)": "99.9433319261", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 客", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨客", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "客", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "髂", "Unihan_Traditional (Chữ Phồn thể)": "髂", "Pinyin_Xie": "qià", "Âm Hán Việt_Xie": "khách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường kết hợp với từ chỉ xương để tạo thành thuật ngữ y học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魍', '{"9000": "5251.0", "Chữ Trung Quốc": "魍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鬼 | Số nét | 17 | nét | 鬼 | quỷ | biểu nghĩa | ma quỷ | 罔 | vóng | biểu âm | 魍 = 鬼 (Quỷ, biểu nghĩa: ma quỷ) + 罔 (Vóng, biểu âm); chữ hình thanh. Bộ 鬼 chỉ đây là loài yêu quái, ma; phần 罔 cho âm wǎng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"võng\": bộ 鬼 (quỷ, ma) + 罔 (võng, lưới bẫy) — con yêu quái 魍魎 giăng lưới bóng đêm bẫy người lạc đường. | Gương Hán-Việt | võng — trong 魍魎 (võng lượng) ma quái, yêu nghiệt | Mở khoá kiến thức | Biết 魍 mở khoá từ 魑魅魍魉 (ly mị võng lượng) — thành ngữ chỉ đủ loại ma quái yêu nghiệt.", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary, 魍 là chữ hình thanh: 鬼 (quỷ, ma) cho nghĩa, 罔 (vóng, wǎng) cho âm. Chỉ dùng trong từ 魍魎 (wǎng liǎng) — tên loài yêu quái, ma núi rừng trong thần thoại Trung Hoa. 魍魎 tượng trưng cho âm tà, điều xấu xa ẩn nấp trong bóng tối. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: võng lượng 魍魎,魍魉,蝄蜽)", "Hạng Tần Suất (Jun Da)": "5251.0", "Tần Suất % (Jun Da)": "99.9434032424", "GavinGrover_Once (Chiết tự trực tiếp)": "鬼 + 罔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鬼罔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "罔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鬼", "Unihan_Simplified (Chữ Giản thể)": "魍", "Unihan_Traditional (Chữ Phồn thể)": "魍", "Pinyin_Xie": "wǎng", "Âm Hán Việt_Xie": "võng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và thường đi đôi với các từ chỉ ma quỷ khác để chỉ chung các loài yêu quái. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缁', '{"9000": "5252.0", "Chữ Trung Quốc": "缁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 缁 | tri | tượng hình | lụa đen, màu đen | 缁 thuộc bộ 纟(mịch, sợi tơ). Chữ chỉ màu đen tối của lụa, hoặc lụa đen. Trong văn Phật giáo, 缁衣 (y đen) là áo tăng sĩ. Cấu trúc chi tiết không có trong nguồn tra cứu — chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tri\": bộ 纟(mịch, lụa) — tấm lụa đen tri thức (缁衣) mà tăng sĩ mặc khi tu học. | Gương Hán-Việt | tri — trong 缁衣 (tri y) áo tăng sĩ màu đen, Phật giáo | Mở khoá kiến thức | Biết 缁 mở khoá từ 缁衣 (áo tăng), 缁流 (giới tu sĩ Phật giáo) — thường gặp trong văn học thiền.", "Tự nguyên_Xie": "Theo Wiktionary, 缁 thuộc bộ 纟(mịch, sợi tơ). Nghĩa: lụa màu đen, màu đen tối. Cũng dùng để chỉ tăng sĩ Phật giáo (mặc áo đen). Cấu trúc chi tiết không rõ trong học thuật. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lụa thâm; màu đen", "Hạng Tần Suất (Jun Da)": "5252.0", "Tần Suất % (Jun Da)": "99.9434745588", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 甾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟甾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缁", "Unihan_Traditional (Chữ Phồn thể)": "緇", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "tri", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ bổ nghĩa cho danh từ để chỉ màu đen hoặc trang phục của người tu hành. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('槊', '{"9000": "5253.0", "Chữ Trung Quốc": "槊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 14 | nét | 槊 | giáo | tượng hình | giáo dài, mác dài | 槊 thuộc bộ 木 (mộc). Chữ chỉ loại giáo dài, vũ khí dùng trên lưng ngựa chiến. Wiktionary có ghi nghĩa nhưng không có phân tích glyph-origin chi tiết. Chữ tạo muộn, chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giáo\": bộ 木 (mộc, gỗ) — cây giáo dài làm bằng gỗ cứng, biểu trưng quyền uy chiến trận; gắn với hình ảnh Tào Tháo 横槊赋诗. | Gương Hán-Việt | giáo — trong 横槊 (hoành giáo) cầm ngang giáo | Mở khoá kiến thức | Biết 槊 mở khoá điển tích 横槊赋诗 (hoành giáo phú thi) — hình tượng Tào Tháo cầm giáo đọc thơ, biểu tượng anh hùng văn võ song toàn.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 槊 là tên loại vũ khí cổ đại — giáo dài (long lance), dùng từ lưng ngựa chiến. Chữ thuộc bộ 木 (mộc). Nổi tiếng trong thơ Tô Đông Pha: ''横槊赋诗'' (ngang giáo làm thơ) — miêu tả Tào Tháo. chưa có nguồn học thuật đầy đủ về glyph-origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái giáo dài; một trò đánh cờ", "Hạng Tần Suất (Jun Da)": "5253.0", "Tần Suất % (Jun Da)": "99.9435458751", "GavinGrover_Once (Chiết tự trực tiếp)": "朔 + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱朔木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "槊", "Unihan_Traditional (Chữ Phồn thể)": "槊", "Pinyin_Xie": "shuò", "Âm Hán Việt_Xie": "sáo, sóc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đóng vai trò tân ngữ hoặc chủ ngữ trong câu khi nói về binh khí cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跞', '{"9000": "5254.0", "Chữ Trung Quốc": "跞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 12 | nét | 𧾷 | túc | biểu nghĩa | chân, bộ túc | 樂 | lạc | biểu âm | 跞 = 足/𧾷 (Túc, biểu nghĩa: chân) + 樂 (Lạc, biểu âm); chữ hình thanh. Bộ 足 chỉ đây liên quan đến chân, bước đi; phần 樂 cho âm lì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạc\": bộ 足 (túc, chân) + 樂 (lạc) — chân bước đi theo điệu vui lạc, nhảy múa cử động. | Gương Hán-Việt | lạc — ít dùng trong tiếng Việt, chủ yếu trong văn cổ | Mở khoá kiến thức | Biết 跞 giúp nhận ra chữ ít gặp thuộc bộ 足 trong văn bản cổ điển Trung Hoa.", "Tự nguyên_Xie": "Theo Wiktionary, 跞 là chữ hình thanh: 足/𧾷 (túc, chân) cho nghĩa, 樂 (lạc, lì) cho âm. Nghĩa: đi lại, cử động chân; cũng dùng trong nghĩa dùng nước hoa (theo một số nguồn). Chữ ít phổ biến trong tiếng Hán hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cựa, cử động", "Hạng Tần Suất (Jun Da)": "5254.0", "Tần Suất % (Jun Da)": "99.9436171915", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 乐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊乐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跞", "Unihan_Traditional (Chữ Phồn thể)": "躒", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị động tác của chân hoặc sự di chuyển nhanh nhẹn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醚', '{"9000": "5255.0", "Chữ Trung Quốc": "醚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 16 | nét | 酉 | dấu | biểu nghĩa | nhóm chức chứa oxy, hóa học | 迷 | mê | biểu nghĩa kiêm biểu âm | mê muội, mê mờ | 醚 = 酉 (Dấu, biểu nghĩa: nhóm chức oxy hóa học) + 迷 (Mê, biểu nghĩa kiêm biểu âm: mê mờ, gây mê); chữ hội ý kiêm hình thanh. Bộ 酉 gợi chất hóa học; phần 迷 vừa cho âm mí vừa gợi tính chất gây mê của ete.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mê\": bộ 酉 (dấu, hóa học) + 迷 (mê) — chất ete (ether) làm người mê, gây ngất — đúng như tính chất gây mê của diethyl ether trong y học. | Gương Hán-Việt | mê — trong 醚类 (mê loại) nhóm hợp chất ether | Mở khoá kiến thức | Biết 醚 mở khoá thuật ngữ hóa học: 乙醚 (diethyl ether), 甲醚 (dimethyl ether), 醚键 (liên kết ether C-O-C).", "Tự nguyên_Xie": "Theo Wiktionary, 醚 là chữ hội ý: 酉 (dấu, nhóm chức oxy hóa học) + 迷 (mê, gây mê, nhầm lẫn), chỉ tính chất gây mê của diethyl ether. Phần 迷 cũng đóng vai biểu âm (mí). Chữ được tạo ra để đặt tên hợp chất ether trong hóa học hiện đại — một nhóm hữu cơ có liên kết C-O-C. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ête", "Hạng Tần Suất (Jun Da)": "5255.0", "Tần Suất % (Jun Da)": "99.943687991", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 迷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉迷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "迷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醚", "Unihan_Traditional (Chữ Phồn thể)": "醚", "Pinyin_Xie": "mí", "Âm Hán Việt_Xie": "mê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng độc lập hoặc kết hợp với các từ hóa học khác để chỉ tên chất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('吒', '{"9000": "5256.0", "Chữ Trung Quốc": "吒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 6 | nét | 口 | khẩu | biểu nghĩa | miệng | 乇 | trác | biểu âm | (biểu âm) | 吒 = 口 (Khẩu, biểu nghĩa: miệng) + 乇 (biểu âm); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cha\": miệng (口) mở to thét lên — như tiếng \"cha\" trong Na-tra (哪吒), vị thần tướng tiếng tăm. | Gương Hán-Việt | 哪吒 (Na-cha) — tên nhân vật thần thoại Trung Hoa | Mở khoá kiến thức | Biết 吒 giúp nhận ra tên 哪吒 (Na-cha/Na-tra) trong văn học cổ và phim hoạt hình Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 口 (khẩu) biểu nghĩa liên quan đến miệng/tiếng la hét; 乇 cho âm đọc. Tiểu triện ghi nhận dạng chữ hiện tại. Nghĩa gốc: thét lên, quát mắng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên riêng)", "Hạng Tần Suất (Jun Da)": "5256.0", "Tần Suất % (Jun Da)": "99.9437587906", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 乇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口乇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "吒", "Unihan_Traditional (Chữ Phồn thể)": "吒", "Pinyin_Xie": "zhā", "Âm Hán Việt_Xie": "tra, trá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này chủ yếu làm danh từ trong tên riêng của nhân vật thần thoại hoặc làm động từ biểu thị sự giận dữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('枳', '{"9000": "5257.0", "Chữ Trung Quốc": "枳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 枳 | chỉ | tượng hình | cây chỉ xác (trifoliate orange), cây có gai dùng làm hàng rào | 枳 là chữ độc thể, chưa xác định được cấu trúc hình thanh hay hội ý rõ ràng từ nguồn học thuật. Dạng tiểu triện liên quan đến bộ 木 (cây), nhưng phân tích chi tiết chưa có nguồn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chỉ\": cây 枳 (chỉ xác) — cây gai dùng làm hàng rào, trái vàng nhỏ đắng như quýt dại. | Gương Hán-Việt | 枳實 (chỉ thực), 枳殼 (chỉ xác) — vị thuốc đông y từ quả cây chỉ | Mở khoá kiến thức | Biết 枳 giúp đọc tên vị thuốc đông y 枳實 (chỉ thực) và 枳殼 (chỉ xác) trong toa thuốc cổ.", "Tự nguyên_Xie": "Tiểu triện | Chưa có phân tích nguồn gốc chi tiết từ Wiktionary. 枳 chỉ loại cây trifoliate orange (Poncirus trifoliata) — cây có gai, trái giống cam nhưng rất đắng, dùng làm hàng rào và vị thuốc đông y. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây chỉ", "Hạng Tần Suất (Jun Da)": "5257.0", "Tần Suất % (Jun Da)": "99.9438295901", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 只", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木只", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "只", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "枳", "Unihan_Traditional (Chữ Phồn thể)": "枳", "Pinyin_Xie": "zhǐ", "Âm Hán Việt_Xie": "chỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng đầu cụm từ để chỉ tên loài cây hoặc vị thuốc đông y. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('搿', '{"9000": "5258.0", "Chữ Trung Quốc": "搿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 14 | nét | 搿 | cách | tượng hình | ôm choàng, vùng hai tay ngoắc vào nhau | 搿 là chữ độc thể, không có nguồn học thuật phân tích cấu trúc. Dạng chữ thấy có liên quan đến bộ 手 (tay), gợi ý hành động tay, nhưng chưa xác định chính thức. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cách\": hai bàn tay (手) cách nhau rồi vùng lại ôm chặt — hình ảnh của 搿 (ôm choàng). | Gương Hán-Việt | Chữ ít gặp trong văn bản Hán-Việt cổ điển | Mở khoá kiến thức | Biết 搿 giúp hiểu từ phương ngữ Bắc Kinh chỉ động tác ôm chặt, vùng tay vào nhau.", "Tự nguyên_Xie": "Không có phân tích nguồn gốc từ Wiktionary hay CHISE. 搿 là chữ mô tả hành động ôm, vùng hai tay vào nhau. Dạng chữ liên quan đến bộ 手 (tay). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vùng tay lại, ngoắc hai tay vào nhau", "Hạng Tần Suất (Jun Da)": "5258.0", "Tần Suất % (Jun Da)": "99.9439003897", "GavinGrover_Once (Chiết tự trực tiếp)": "龵 + 拿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰龵拿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "拿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "龵", "Unihan_Simplified (Chữ Giản thể)": "搿", "Unihan_Traditional (Chữ Phồn thể)": "搿", "Pinyin_Xie": "gé", "Âm Hán Việt_Xie": "cách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước tân ngữ hoặc kết hợp với bổ ngữ xu hướng trong khẩu ngữ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹧', '{"9000": "5259.0", "Chữ Trung Quốc": "鹧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 16 | nét | 鹧 | giá | tượng hình | chim đa đa (partridge), dùng trong 鹧鸪 | 鹧 là dạng giản thể của 鷓. Chữ gốc 鷓 gồm bộ 鳥 (điểu, chim) và phần biểu âm, nhưng cấu trúc chi tiết chưa được phân tích trong nguồn tham khảo. Chỉ dùng trong từ 鹧鸪 (chim đa đa).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giá\": chim 鹧 (giá) chỉ xuất hiện trong tên 鹧鸪 — tiếng chim đa đa kêu buồn trong thơ Đường như tiếng \"giá cô\" vọng núi. | Gương Hán-Việt | 鷓鴣 (giá cô) — chim đa đa, biểu tượng nỗi sầu xa xứ trong thơ Đường | Mở khoá kiến thức | Biết 鹧 giúp đọc tên chim 鹧鸪 (giá cô) trong thơ Đường và tên bài 鹧鸪天 (điệu từ cổ điển).", "Tự nguyên_Xie": "Tiểu triện | 鹧 là dạng giản thể của 鷓, chỉ dùng trong từ 鹧鸪 (zhègū) — chim đa đa (partridge). Wiktionary ghi nhận không có phân tích nguồn gốc chi tiết. Chữ thuộc bộ 鳥 (chim). Chưa có nguồn học thuật phân tích sâu hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: chá cô 鷓鴣,鹧鸪)", "Hạng Tần Suất (Jun Da)": "5259.0", "Tần Suất % (Jun Da)": "99.9439711893", "GavinGrover_Once (Chiết tự trực tiếp)": "庶 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰庶鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "庶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹧", "Unihan_Traditional (Chữ Phồn thể)": "鷓", "Pinyin_Xie": "zhè", "Âm Hán Việt_Xie": "chá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ liên kết để cấu tạo tên các loài chim trong từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜍', '{"9000": "5260.0", "Chữ Trung Quốc": "蜍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 虫 | trùng | biểu nghĩa | côn trùng, sinh vật nhỏ | 余 | dư | biểu âm | (biểu âm) | 蜍 = 虫 (Trùng, biểu nghĩa: sinh vật nhỏ) + 余 (Dư, biểu âm); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thờ\": con trùng (虫) kêu \"thờ thờ\" trong đêm — đó là con cóc 蟾蜍 ngồi bên giếng dưới ánh trăng. | Gương Hán-Việt | 蟾蜍 (thiềm thừ) — con cóc, biểu tượng mặt trăng trong văn hóa Trung Hoa | Mở khoá kiến thức | Biết 蜍 giúp đọc 蟾蜍 (thiềm thừ/chán chú) — từ cổ điển chỉ con cóc, xuất hiện trong thơ về trăng và huyền thoại Hằng Nga.", "Tự nguyên_Xie": "Chữ hình thanh: 虫 (trùng) biểu nghĩa chỉ loài sinh vật nhỏ; 余 (dư) cho âm đọc. 蜍 chỉ dùng trong từ 蟾蜍 (thiềm thừ) — con cóc. Wiktionary xác nhận cấu trúc hình thanh này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thiềm thừ 蟾蜍)", "Hạng Tần Suất (Jun Da)": "5260.0", "Tần Suất % (Jun Da)": "99.9440419888", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 余", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫余", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "余", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜍", "Unihan_Traditional (Chữ Phồn thể)": "蜍", "Pinyin_Xie": "chú", "Âm Hán Việt_Xie": "thừ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này hầu như chỉ làm danh từ liên kết trong từ ghép để chỉ loài cóc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舻', '{"9000": "5261.0", "Chữ Trung Quốc": "舻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 11 | nét | 舻 | lô | tượng hình | mũi thuyền, đầu thuyền | 舻 là dạng giản thể của 艫. Chữ gốc 艫 thuộc bộ 舟 (thuyền), nhưng cấu trúc hình thanh chi tiết chưa có nguồn học thuật rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lô\": mũi thuyền (舟) lướt sóng — 舳艫千里 (trục lô thiên lý) mô tả đoàn thuyền dài vô tận. | Gương Hán-Việt | 舳艫 (trục lô) — hai đầu mũi và đuôi thuyền, hình ảnh trong phú cổ | Mở khoá kiến thức | Biết 舻 giúp đọc thành ngữ 舳艫千里 (trục lô thiên lý) — đoàn chiến thuyền dài ngàn dặm trong văn học cổ.", "Tự nguyên_Xie": "Tiểu triện | 舻 là dạng giản thể của 艫, chỉ mũi thuyền hoặc đuôi thuyền. Theo Wiktionary, 艫 thuộc bộ 舟 (thuyền). Chữ thường dùng trong cặp 舳艫 (trục lô) chỉ hai đầu thuyền. Không có phân tích hình thanh chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mũi thuyền", "Hạng Tần Suất (Jun Da)": "5261.0", "Tần Suất % (Jun Da)": "99.9441127884", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 卢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟卢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "舻", "Unihan_Traditional (Chữ Phồn thể)": "艫", "Pinyin_Xie": "lú", "Âm Hán Việt_Xie": "lô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận của thuyền, thường xuất hiện trong văn học cổ hoặc từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鏊', '{"9000": "5262.0", "Chữ Trung Quốc": "鏊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 18 | nét | 鏊 | ngạo | tượng hình | vỉ nướng bằng gang, chảo dẹt không viền | 鏊 là chữ độc thể thuộc bộ 金 (kim loại). Cấu trúc chi tiết chưa được phân tích trong nguồn học thuật. Dạng chữ gợi ý vật dụng bằng kim loại để nướng bánh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạo\": chiếc vỉ gang 鏊 (ngạo) đặt trên lửa \"ngạo\" — mặt phẳng nóng bỏng để nướng bánh tráng và bánh dày. | Gương Hán-Việt | 鏊子 (ngạo tử) — vỉ nướng bằng gang, dụng cụ làm bánh truyền thống | Mở khoá kiến thức | Biết 鏊 giúp nhận ra dụng cụ nấu ăn truyền thống 鏊子 (ngạo tử) trong văn hóa ẩm thực Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi nhận 鏊 là vỉ nướng bằng gang phẳng (griddle). Chữ thuộc bộ 金 (kim loại). Không có phân tích nguồn gốc chi tiết về cấu trúc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vỉ nướng, lò sấy", "Hạng Tần Suất (Jun Da)": "5262.0", "Tần Suất % (Jun Da)": "99.944183588", "GavinGrover_Once (Chiết tự trực tiếp)": "敖 + 金", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敖金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鏊", "Unihan_Traditional (Chữ Phồn thể)": "鏊", "Pinyin_Xie": "ào", "Âm Hán Việt_Xie": "ngao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ dụng cụ nấu ăn bằng sắt, có thể đứng độc lập làm tân ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禳', '{"9000": "5263.0", "Chữ Trung Quốc": "禳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 21 | nét | 禳 | nhương | tượng hình | lễ cầu an, tế trừ tai họa | 禳 thuộc bộ 示 (thần linh/nghi lễ). Cấu trúc chi tiết chưa được phân tích trong nguồn học thuật. Dạng chữ gợi ý nghi lễ tôn giáo để xua đuổi tà ma.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhương\": bộ 示 (thần linh) làm lễ \"nhương\" — nghi thức cúng bái xua đuổi tai ương, trừ tà khử bệnh. | Gương Hán-Việt | 禳解 (nhương giải), 祈禳 (kỳ nhương) — lễ cầu an, xua đuổi tà ma trong truyền thống tín ngưỡng | Mở khoá kiến thức | Biết 禳 giúp đọc các từ nghi lễ cổ 禳災 (nhương tai), 祈禳 (kỳ nhương) trong văn bản đạo giáo và phong tục dân gian.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi nhận 禳 là nghi lễ cầu nguyện hoặc hiến tế để xua đuổi tai họa. Chữ thuộc bộ 示 (nghi lễ thần linh). Tiểu triện và Lục thư thông đã ghi nhận dạng chữ này. Không có phân tích hình thanh chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lễ cầu mát", "Hạng Tần Suất (Jun Da)": "5263.0", "Tần Suất % (Jun Da)": "99.9442543875", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 襄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻襄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "襄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禳", "Unihan_Traditional (Chữ Phồn thể)": "禳", "Pinyin_Xie": "ráng", "Âm Hán Việt_Xie": "nhương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị hành động cúng tế giải hạn, thường đi kèm tân ngữ chỉ tai ương. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒺', '{"9000": "5264.0", "Chữ Trung Quốc": "蒺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蒺 | tật | tượng hình | cây tật lê (furze/gorse), cây cỏ nhiều gai | 蒺 thuộc bộ 艸 (cỏ). Chỉ dùng trong từ 蒺藜 (tật lê). Cấu trúc hình thanh chi tiết chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tật\": cỏ (艸) mọc đầy gai như cái \"tật\" — 蒺藜 (tật lê) là loại cỏ gai nguy hiểm dùng làm bẫy ngựa thời cổ. | Gương Hán-Việt | 蒺藜 (tật lê) — cây cỏ gai, dùng làm chướng ngại vật trong chiến tranh cổ đại | Mở khoá kiến thức | Biết 蒺 giúp đọc tên cây 蒺藜 (tật lê) trong thơ và sách thuốc cổ, cũng như thuật ngữ chiến tranh cổ đại.", "Tự nguyên_Xie": "Wiktionary ghi nhận 蒺 chỉ dùng trong 蒺藜 (jílí) — cây tật lê, một loại cỏ có gai nhọn. Chữ thuộc bộ 艸 (cỏ). Không có phân tích nguồn gốc chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tật lê 蒺藜)", "Hạng Tần Suất (Jun Da)": "5264.0", "Tần Suất % (Jun Da)": "99.9443246703", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 疾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹疾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "疾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒺", "Unihan_Traditional (Chữ Phồn thể)": "蒺", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "tật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ liên kết trong từ ghép để chỉ một loại cây có gai. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钹', '{"9000": "5265.0", "Chữ Trung Quốc": "钹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 钹 | bạt | tượng hình | cái chũm chọe, nhạc cụ gõ bằng đồng | 钹 là dạng giản thể của 鈸, thuộc bộ 金 (kim loại). Cấu trúc hình thanh chi tiết của chữ gốc 鈸 chưa được phân tích trong nguồn. Dạng chữ gợi ý nhạc cụ bằng kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạt\": kim loại (金) \"bạt\" vào nhau tạo âm thanh vang — 钹 (bạt) là đôi chũm chọe trong ban nhạc lễ hội. | Gương Hán-Việt | 铙钹 (nạo bạt) — cặp nhạc cụ gõ đồng trong âm nhạc truyền thống và lễ nghi Phật giáo | Mở khoá kiến thức | Biết 钹 giúp nhận ra từ 铙钹 (nạo bạt) — bộ nhạc cụ gõ đồng trong nghi lễ Phật giáo và đám rước truyền thống.", "Tự nguyên_Xie": "钹 là dạng giản thể của 鈸 — cymbals (chũm chọe). Chữ thuộc bộ 金 (kim loại). Wiktionary chỉ ghi nhận nguồn gốc cơ bản, không có phân tích chi tiết. Chưa có nguồn học thuật sâu hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái nạo bạt (nhạc)", "Hạng Tần Suất (Jun Da)": "5265.0", "Tần Suất % (Jun Da)": "99.9443949531", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 犮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅犮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钹", "Unihan_Traditional (Chữ Phồn thể)": "鈸", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "bạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nhạc cụ gõ bằng đồng, có thể đi sau lượng từ chỉ chiếc hoặc đôi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜢', '{"9000": "5266.0", "Chữ Trung Quốc": "蜢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 蜢 | mãnh | tượng hình | con châu chấu (grasshopper) | 蜢 thuộc bộ 虫 (côn trùng). Chỉ dùng trong 蚱蜢 (châu chấu). Cấu trúc hình thanh chi tiết chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mãnh\": con trùng (虫) nhảy \"mãnh\" mẽ — 蚱蜢 (trách mãnh) là con châu chấu phóng mình xa trên đồng lúa. | Gương Hán-Việt | 蚱蜢 (trách mãnh) — con châu chấu, hình ảnh quen thuộc ở ruộng lúa | Mở khoá kiến thức | Biết 蜢 giúp đọc 蚱蜢 (trách mãnh/zhàměng) — con châu chấu trong văn xuôi và thơ nông thôn Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận 蜢 chỉ dùng trong 蚱蜢 (zhàměng) — con châu chấu. Chữ thuộc bộ 虫 (côn trùng). Tiểu triện ghi nhận dạng chữ này. Không có phân tích nguồn gốc chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: trách mãnh 蚱蜢)", "Hạng Tần Suất (Jun Da)": "5266.0", "Tần Suất % (Jun Da)": "99.9444652359", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 孟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫孟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜢", "Unihan_Traditional (Chữ Phồn thể)": "蜢", "Pinyin_Xie": "měng", "Âm Hán Việt_Xie": "mãnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ liên kết, thường xuất hiện trong từ ghép để chỉ các loài côn trùng nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬻', '{"9000": "5267.0", "Chữ Trung Quốc": "鬻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鬲 | Số nét | 22 | nét | 䰜 | biểu nghĩa | vạc/nồi ba chân (cauldron) | 米 | mễ | biểu nghĩa | gạo | 鬻 = 䰜 (vạc ba chân, biểu nghĩa) + 米 (Mễ, gạo, biểu nghĩa); chữ hội ý: gạo nấu trong vạc → cháo. Hai nét 弓 hai bên tượng hình hơi bốc lên từ nồi cháo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dục\": vạc (䰜) nấu gạo (米) bốc hơi — 鬻 (dục) là nồi cháo sôi sùng sục, sau mượn nghĩa \"bán\" như bán cháo mưu sinh. | Gương Hán-Việt | 賣鬻 (mại dục) — bán, mưu sinh; 鬻文 (dục văn) — bán văn chương kiếm sống | Mở khoá kiến thức | Biết 鬻 giúp hiểu chữ 粥 (cháo) là dạng rút gọn của 鬻, và đọc các từ Hán cổ liên quan đến mưu sinh, bán buôn.", "Tự nguyên_Xie": "Tiểu triện | Chữ hội ý: 䰜 (biến thể của 鬲, vạc ba chân rỗng) + 米 (gạo). Hai nét 弓 ở hai bên tượng hình hơi bốc từ nồi cháo đang sôi. Nghĩa gốc là cháo loãng — dạng rút gọn thành 粥 (zhōu). Sau đó 鬻 được mượn âm để chỉ nghĩa \"bán\" (𧶠). Wiktionary xác nhận rõ quá trình này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cháo loãng", "Hạng Tần Suất (Jun Da)": "5267.0", "Tần Suất % (Jun Da)": "99.9445355186", "GavinGrover_Once (Chiết tự trực tiếp)": "粥 + 鬲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱粥鬲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "粥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鬲", "Unihan_Simplified (Chữ Giản thể)": "鬻", "Unihan_Traditional (Chữ Phồn thể)": "鬻", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "dục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ mang nghĩa là bán trong các văn bản cổ hoặc thành ngữ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('珩', '{"9000": "5268.0", "Chữ Trung Quốc": "珩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 10 | nét | 玉 | ngọc | biểu nghĩa | ngọc | 行 | hàng | biểu âm | (biểu âm) | 珩 = 玉 (Ngọc, biểu nghĩa: ngọc) + 行 (Hàng, biểu âm); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hành\": ngọc (玉) nằm hàng ngang (行) — 珩 là thanh ngọc hành ngang ở đỉnh bộ trang sức treo, biểu trưng phẩm giá quý tộc. | Gương Hán-Việt | 珩璜 (hành hoàng) — bộ trang sức ngọc hoàn chỉnh của quý tộc cổ đại | Mở khoá kiến thức | Biết 珩 giúp đọc thuật ngữ trang sức ngọc cổ 珩璜 (hành hoàng) trong văn bản lịch sử và khảo cổ học Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 玉 (ngọc) biểu nghĩa; 行 (hàng) cho âm đọc. 珩 chỉ thanh ngọc nằm ngang ở trên cùng của bộ trang sức ngọc treo (jade pendant). Là vật trang sức quý tộc thời Xuân Thu. Wiktionary xác nhận cấu trúc hình thanh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "viên ngọc đeo", "Hạng Tần Suất (Jun Da)": "5268.0", "Tần Suất % (Jun Da)": "99.9446058014", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 行", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王行", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "行", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "珩", "Unihan_Traditional (Chữ Phồn thể)": "珩", "Pinyin_Xie": "háng", "Âm Hán Việt_Xie": "hành", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại ngọc quý thời xưa, thường dùng trong tên người hoặc văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('卮', '{"9000": "5269.0", "Chữ Trung Quốc": "卮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 卩 | Số nét | 5 | nét | 卮 | chi | tượng hình | chén rượu hình trụ, chén uống rượu cổ đại | 卮 là tượng hình, mô tả chiếc chén rượu hình trụ có nắp, tay cầm và ba chân — dụng cụ uống rượu thời cổ đại. Dạng đại triện còn lưu giữ hình dáng này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chi\": chiếc chén (卮) \"chi\" đầy rượu — 卮酒 (chi tửu) là chén rượu dâng mời khách quý trong nghi lễ cổ đại. | Gương Hán-Việt | 卮酒 (chi tửu) — chén rượu, 卮言 (chi ngôn) — lời nói tự nhiên như chén rượu đầy rồi vơi | Mở khoá kiến thức | Biết 卮 giúp đọc 卮酒 (chi tửu) và 卮言 (chi ngôn — khái niệm triết học của Trang Tử về lời nói biến hóa).", "Tự nguyên_Xie": "Đại triện | 卮 là tượng hình chỉ chén rượu hình trụ (cylindrical wine vessel) có nắp, tay cầm và ba chân. Wiktionary mô tả đây là dụng cụ uống rượu thời cổ đại. Chữ cũng dùng để đo lường thể tích chất lỏng. Đại triện ghi nhận hình dáng chiếc chén. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chén", "Hạng Tần Suất (Jun Da)": "5269.0", "Tần Suất % (Jun Da)": "99.9446755674", "GavinGrover_Once (Chiết tự trực tiếp)": "𠂋 + 㔾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𠂋㔾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㔾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "𠂋", "Unihan_Simplified (Chữ Giản thể)": "卮", "Unihan_Traditional (Chữ Phồn thể)": "卮", "Pinyin_Xie": "zhī", "Âm Hán Việt_Xie": "chi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ đồ đựng rượu cổ, thường đi sau lượng từ hoặc làm tân ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垭', '{"9000": "5270.0", "Chữ Trung Quốc": "垭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 9 | nét | 土 | thổ | biểu nghĩa | đất | 亞 | á | biểu âm | (biểu âm) | 垭 = 土 (Thổ, biểu nghĩa: đất) + 亞 (Á, biểu âm); chữ hình thanh. Nghĩa liên quan đến địa hình đất — khe núi hẹp giữa hai ngọn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"á\": đất (土) kẽ hở \"á\" hẹp giữa hai ngọn núi — 垭口 (á khẩu) là đèo núi, cửa ải thiên nhiên. | Gương Hán-Việt | 垭口 (á khẩu) — đèo núi, cửa ải; thường xuất hiện trong địa danh vùng núi Tứ Xuyên, Hồ Bắc | Mở khoá kiến thức | Biết 垭 giúp đọc địa danh núi non miền Tây Trung Quốc — 垭口 (á khẩu) xuất hiện rất nhiều trong bản đồ và văn học du ký.", "Tự nguyên_Xie": "Chữ hình thanh: 土 (thổ) biểu nghĩa liên quan đến địa hình đất; 亞 (á) cho âm đọc. 垭 chỉ khe núi hẹp giữa hai ngọn núi — địa hình phổ biến ở vùng núi Trung Quốc, thường dùng đặt tên địa danh. Wiktionary xác nhận cấu trúc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khe núi; khe hẹp (giữa hai quả núi, có thể đi được, thường dùng làm tên đất như Mã Đầu Ô, Tân Gia Ô đều thuộc tỉnh Hồ Bắc); ái; như \"ái (đất mùn)\" (gdhn)", "Hạng Tần Suất (Jun Da)": "5270.0", "Tần Suất % (Jun Da)": "99.9447453334", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 亚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土亚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "垭", "Unihan_Traditional (Chữ Phồn thể)": "埡", "Pinyin_Xie": "yā", "Âm Hán Việt_Xie": "ô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ xuất hiện trong các địa danh để chỉ vùng đất trũng giữa hai ngọn núi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苄', '{"9000": "5271.0", "Chữ Trung Quốc": "苄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 卞 | biện | biểu âm | (biểu âm) | 苄 = 艹 (Thảo, biểu nghĩa: thực vật) + 卞 (Biện, biểu âm); chữ hình thanh. Đây là chữ tạo mới để phiên âm thuật ngữ hóa học benzyl.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biện\": cỏ (艹) + 卞 (biện âm) → 苄 (biện) là ký hiệu hóa học cho nhóm benzyl — thuật ngữ khoa học mượn chữ Hán tạo mới. | Gương Hán-Việt | 苄基 (biện cơ) — nhóm benzyl trong hóa học hữu cơ | Mở khoá kiến thức | Biết 苄 giúp đọc thuật ngữ hóa học Trung Quốc 苄基 (biện cơ = benzyl group), 苄醇 (biện thuần = benzyl alcohol).", "Tự nguyên_Xie": "Tiểu triện | 苄 là chữ tạo mới (không có giáp cốt hay kim văn) dùng để phiên âm thuật ngữ hóa học \"benzyl\" (苄基 — nhóm benzyl C₆H₅CH₂-). Cấu trúc hình thanh: 艹 (thảo) biểu nghĩa liên quan đến hợp chất hữu cơ; 卞 (biện) cho âm đọc. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ben-zyn", "Hạng Tần Suất (Jun Da)": "5271.0", "Tần Suất % (Jun Da)": "99.9448150994", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 卞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹卞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苄", "Unihan_Traditional (Chữ Phồn thể)": "苄", "Pinyin_Xie": "biàn", "Âm Hán Việt_Xie": "biện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ ghép trong các thuật ngữ hóa học để chỉ nhóm chức benzyl. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苕', '{"9000": "5272.0", "Chữ Trung Quốc": "苕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 苕 | thiều | tượng hình | hoa lau, hoa lăng tiêu (trumpet creeper) | 苕 thuộc bộ 艸 (cỏ). Cấu trúc hình thanh chi tiết chưa có nguồn học thuật. Chỉ ghi nhận Han etym cơ bản. Chữ chỉ cây lau, hoa lăng tiêu, xuất hiện nhiều trong thơ kinh Thi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiều\": bụi cỏ (艸) \"thiều\" nhẹ trong gió — 苕 là hoa lau mềm uốn cong, hình ảnh nỗi nhớ trong Kinh Thi. | Gương Hán-Việt | 苕之华 (thiều chi hoa) — tên bài thơ trong Kinh Thi, hình ảnh hoa lau khô héo tượng trưng nỗi buồn | Mở khoá kiến thức | Biết 苕 giúp đọc tên bài 苕之华 trong Kinh Thi và nhận ra chữ trong các địa danh như苕溪 (Thiều Khê) ở Chiết Giang.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary chỉ ghi nhận nguồn gốc cơ bản (Han etym). 苕 chỉ hoa lau sậy hoặc hoa lăng tiêu (trumpet creeper). Xuất hiện trong Kinh Thi với hình ảnh cành lau uốn cong, gợi sự mềm mại và nỗi nhớ. Chữ tạo muộn, chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hoa lau, hoa lăng tiêu", "Hạng Tần Suất (Jun Da)": "5272.0", "Tần Suất % (Jun Da)": "99.9448848654", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 召", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹召", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "召", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苕", "Unihan_Traditional (Chữ Phồn thể)": "苕", "Pinyin_Xie": "sháo", "Âm Hán Việt_Xie": "điều, thiều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ để chỉ một số loại cây cỏ hoặc củ khoai lang trong phương ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菀', '{"9000": "5273.0", "Chữ Trung Quốc": "菀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菀 | uyển | tượng hình | cây cúc tím (Aster tataricus), vườn cây | 菀 thuộc bộ 艸 (cỏ). Cấu trúc hình thanh chi tiết chưa có nguồn học thuật. Chữ có nhiều âm đọc (wǎn, yù, yuàn, yùn), mỗi âm có nghĩa khác nhau.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uyển\": bụi cỏ (艸) \"uyển\" mềm — 菀 là cây cúc tím (紫菀), vị thuốc đông y nổi tiếng trị ho. | Gương Hán-Việt | 紫菀 (tử uyển) — cây cúc tím, vị thuốc đông y; 菀枯 (uyển khô) — tươi tốt và khô héo | Mở khoá kiến thức | Biết 菀 giúp đọc tên vị thuốc 紫菀 (tử uyển/zǐwǎn) — cây cúc tím trị ho trong đông y.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi nhận 菀 có nhiều nghĩa theo âm đọc: wǎn = cây cúc tím (Aster tataricus, 紫菀); yù = tươi tốt (luxuriant); yuàn = vườn cây (biến thể của 苑); yùn = tích lũy (biến thể của 蘊). Chữ thuộc bộ 艸. Không có phân tích nguồn gốc chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vườn hoa", "Hạng Tần Suất (Jun Da)": "5273.0", "Tần Suất % (Jun Da)": "99.9449546314", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 宛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹宛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菀", "Unihan_Traditional (Chữ Phồn thể)": "菀", "Pinyin_Xie": "wǎn", "Âm Hán Việt_Xie": "uyển, uất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường làm tính từ mô tả trạng thái cây cối xanh tươi hoặc làm danh từ chỉ vườn tược. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骠', '{"9000": "5274.0", "Chữ Trung Quốc": "骠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 14 | nét | 骠 | phiêu | tượng hình | ngựa vàng lang trắng, chiến mã dũng mãnh | 骠 là dạng giản thể của 驃, thuộc bộ 馬 (ngựa). Cấu trúc hình thanh chi tiết của chữ gốc 驃 chưa được phân tích trong nguồn. Tiểu triện và Lục thư thông ghi nhận dạng chữ này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiêu\": ngựa (馬) \"phiêu\" nhanh như gió — 骠骑 (phiêu kỵ) là kỵ binh tinh nhuệ, tước vị võ tướng cao quý trong lịch sử Hán. | Gương Hán-Việt | 驃騎 (phiêu kỵ) — tước vị tướng quân cao cấp; 驃騎將軍 (phiêu kỵ tướng quân) — danh hiệu Hoắc Khứ Bệnh | Mở khoá kiến thức | Biết 骠 giúp đọc chức tước 骠骑将军 (phiêu kỵ tướng quân) — danh hiệu lừng lẫy của danh tướng Hoắc Khứ Bệnh thời Hán Vũ Đế.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 骠 là dạng giản thể của 驃 — chỉ ngựa chiến vàng lang trắng, dũng mãnh. Wiktionary chỉ ghi nhận Han etym cơ bản. Chữ thuộc bộ 馬 (ngựa). Không có phân tích nguồn gốc chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa vàng lang trắng; khoẻ mạnh", "Hạng Tần Suất (Jun Da)": "5274.0", "Tần Suất % (Jun Da)": "99.9450243974", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 票", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马票", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "票", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骠", "Unihan_Traditional (Chữ Phồn thể)": "驃", "Pinyin_Xie": "biāo", "Âm Hán Việt_Xie": "phiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ loại ngựa chiến khỏe hoặc làm tính từ mô tả sự dũng mãnh, nhanh nhẹn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袷', '{"9000": "5275.0", "Chữ Trung Quốc": "袷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 11 | nét | 衤 | y | biểu nghĩa | quần áo | 合 | cáp | biểu âm | (biểu âm) | 袷 = 衤 (Y, biểu nghĩa: quần áo) + 合 (Cáp, biểu âm); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giáp\": áo (衤) ghép (合) hai lớp — 袷衣 (giáp y) là áo kép có lót, mặc vào mùa thu đông khi trời se lạnh. | Gương Hán-Việt | 袷衣 (giáp y) — áo kép có lót, 夹袷 (giáp giáp) — mô tả kiểu áo hai lớp truyền thống | Mở khoá kiến thức | Biết 袷 giúp đọc thuật ngữ trang phục cổ điển 袷衣 (giáp y) — áo kép trong văn học và lịch sử trang phục Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 衤 (y) biểu nghĩa liên quan đến quần áo; 合 (cáp) cho âm đọc. 袷 chỉ áo kép — áo có lớp lót bên trong, khác với áo đơn (单). Wiktionary xác nhận cấu trúc hình thanh này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo kép", "Hạng Tần Suất (Jun Da)": "5275.0", "Tần Suất % (Jun Da)": "99.9450941634", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 合", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤合", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "合", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袷", "Unihan_Traditional (Chữ Phồn thể)": "袷", "Pinyin_Xie": "jiá", "Âm Hán Việt_Xie": "khiếp, kiếp, giáp, cáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ loại áo khoác hai lớp thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跹', '{"9000": "5276.0", "Chữ Trung Quốc": "跹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 13 | nét | 跹 | tiên | tượng hình | múa xoay, bước nhảy uyển chuyển | 跹 là dạng giản thể của 躚, thuộc bộ 足 (chân). Cấu trúc hình thanh chi tiết chưa có nguồn học thuật. Chữ chỉ điệu múa xoay tròn, bước chân uyển chuyển.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiên\": chân (足) bước \"tiên\" thoát — 翩跹 (phiên tiên) là dáng múa xoay nhẹ nhàng như cánh bướm trong thơ cổ. | Gương Hán-Việt | 翩跹 (phiên tiên) — dáng bay múa uyển chuyển, nhẹ nhàng; 蹁跹 (biên tiên) — bước đi lắc lư, múa xoay | Mở khoá kiến thức | Biết 跹 giúp đọc từ thơ cổ 翩跹 (phiên tiên) — hình ảnh múa bay uyển chuyển trong Sở Từ và thơ Đường.", "Tự nguyên_Xie": "跹 là dạng giản thể của 躚 — chỉ điệu múa xoay tròn, bước chân nhẹ nhàng. Wiktionary ghi nhận nghĩa múa (dancing, swirling) và phương ngữ Mân Nam chỉ đi lại lảng vảng. Không có phân tích nguồn gốc chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chùn bước, do dự", "Hạng Tần Suất (Jun Da)": "5276.0", "Tần Suất % (Jun Da)": "99.9451639294", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 迁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊迁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "迁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跹", "Unihan_Traditional (Chữ Phồn thể)": "躚", "Pinyin_Xie": "xiān", "Âm Hán Việt_Xie": "tiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường kết hợp với chữ khác tạo thành động từ liên hợp mô tả dáng điệu nhảy múa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘘', '{"9000": "5277.0", "Chữ Trung Quốc": "瘘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 14 | nét | 瘘 | lậu | tượng hình | lỗ rò, vết thương mãn tính (fistula) | 瘘 là dạng giản thể của 瘻, thuộc bộ 疒 (bệnh tật). Cấu trúc hình thanh chi tiết chưa có nguồn học thuật. Chỉ bệnh lỗ rò (fistula) hoặc lưu hạch.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lậu\": bệnh (疒) \"lậu\" — vết thương không lành, tạo lỗ rò mãn tính. 瘘管 (lậu quản) là ống rò trong y học. | Gương Hán-Việt | 瘻管 (lậu quản) — ống rò (fistula); 鼠瘻 (thử lậu) — lưu hạch cổ (scrofula, bệnh lao hạch) | Mở khoá kiến thức | Biết 瘘 giúp đọc thuật ngữ y học cổ 瘘管 (lậu quản = fistula), 肛瘘 (giang lậu = rò hậu môn) trong văn bản đông y.", "Tự nguyên_Xie": "Tiểu triện | 瘘 là dạng giản thể của 瘻 — chỉ bệnh lỗ rò (fistula) hoặc lưu hạch (scrofula). Wiktionary ghi nhận hai âm đọc: lòu = fistula; lú = gù lưng. Chữ thuộc bộ 疒 (bệnh tật). Tiểu triện ghi nhận dạng chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: câu lu 痀瘻)", "Hạng Tần Suất (Jun Da)": "5277.0", "Tần Suất % (Jun Da)": "99.9452336954", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 娄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒娄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "娄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘘", "Unihan_Traditional (Chữ Phồn thể)": "瘻", "Pinyin_Xie": "lòu", "Âm Hán Việt_Xie": "lu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại bệnh lý rò rỉ dịch hoặc mủ trong y học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('騔', '{"9000": "5278.0", "Chữ Trung Quốc": "騔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 19 | nét | 騔 | cách | tượng hình | (nghĩa chưa rõ, thuộc bộ mã) | 騔 thuộc bộ 馬 (ngựa). Không có dữ liệu phân tích cấu trúc từ nguồn học thuật. Chữ cực hiếm, nghĩa không xác định rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cách\": chữ ngựa (馬) hiếm gặp — 騔 là chữ cổ thuộc bộ mã, nghĩa chưa được ghi chép đầy đủ trong từ điển hiện đại. | Gương Hán-Việt | Chữ quá hiếm, chưa ghi nhận trong từ Hán-Việt thông dụng | Mở khoá kiến thức | 騔 là chữ cực hiếm thuộc bộ 馬, chủ yếu xuất hiện trong văn bản cổ đại chưa được chú giải đầy đủ.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc từ Wiktionary hay CHISE cho 騔. Chữ thuộc bộ 馬 (ngựa), nghĩa không rõ ràng trong các từ điển hiện đại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "锔", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 曷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬曷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "騔", "Unihan_Traditional (Chữ Phồn thể)": "騔", "Pinyin_Xie": "gé", "Âm Hán Việt_Xie": "cách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này là từ cổ, dùng làm danh từ chỉ loại ngựa hoặc động từ liên quan đến việc kẹp giữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磬', '{"9000": "5279.0", "Chữ Trung Quốc": "磬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 16 | nét | 殸 | khánh | biểu nghĩa | cái khánh (nhạc cụ đá) | 石 | thạch | biểu nghĩa | đá | 磬 = 殸 (Khánh, biểu nghĩa: hình tượng cái khánh) + 石 (Thạch, biểu nghĩa: đá); chữ hội ý. Kết hợp hình tượng nhạc cụ đá với bộ thạch để chỉ cụ thể loại nhạc cụ làm từ đá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khánh\": đá (石) gõ vào nhạc cụ (殸) — 磬 (khánh) là tấm đá hình chữ L treo lên gõ, âm thanh trong vắt trong nghi lễ cung đình. | Gương Hán-Việt | 磬 (khánh) — nhạc cụ đá gõ trong nghi lễ Nho giáo; 鐘磬 (chung khánh) — chuông và khánh đá, biểu tượng âm nhạc cung đình | Mở khoá kiến thức | Biết 磬 giúp đọc 鐘磬 (chung khánh), 編磬 (biên khánh — bộ khánh đá) trong văn bản lịch sử âm nhạc và nghi lễ Nho giáo.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | Chữ hội ý: 殸 (hình tượng nhạc cụ gõ) + 石 (thạch = đá). Giáp cốt văn đã có dạng chữ này, cho thấy khánh đá là nhạc cụ quan trọng từ thời Thương. Tiểu triện và Lục thư thông đều ghi nhận cấu trúc này. Wiktionary xác nhận là hội ý (ic). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái khánh", "Hạng Tần Suất (Jun Da)": "5279.0", "Tần Suất % (Jun Da)": "99.9454424765", "GavinGrover_Once (Chiết tự trực tiếp)": "殸 + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱殸石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "殸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磬", "Unihan_Traditional (Chữ Phồn thể)": "磬", "Pinyin_Xie": "qìng", "Âm Hán Việt_Xie": "khánh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại nhạc cụ gõ hình chữ L ngược làm bằng đá hoặc ngọc thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缶', '{"9000": "5280.0", "Chữ Trung Quốc": "缶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 缶 | Số nét | 6 | nét | 缶 | phẫu | tượng hình | bình/chum đất nung có nắp, dùng đựng rượu | 缶 là chữ tượng hình độc thể, mô tả chiếc bình đất nung có nắp. Đây cũng là một bộ thủ (radical 121). Kim văn còn ghi nhận hình dạng bình đất rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phẫu\": bình đất (缶) \"phẫu\" — chiếc chum đất nung có nắp, vừa đựng rượu vừa là nhạc cụ gõ trong lễ hội cổ đại. | Gương Hán-Việt | 擊缶 (kích phẫu) — gõ vào bình đất làm nhạc; 缶鼓 (phẫu cổ) — trống bình đất | Mở khoá kiến thức | Biết 缶 giúp đọc 擊缶 (kích phẫu) — điển tích nổi tiếng về vua Tần gõ bình đất hát, và nhận ra bộ thủ 缶 trong các chữ 罐, 缸, 罄.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 缶 là chữ tượng hình mô tả bình đất nung có nắp (earthenware jar with a lid). Kim văn và tiểu triện đều thể hiện hình dáng bình đất. Wiktionary xác nhận là tượng hình (liushu: pictograph). Dùng để đựng rượu và làm nhạc cụ trong nghi lễ. Không liên quan đến phần trên của chữ 鬱. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "781.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Là hình vẽ cái vò làm bằng sành sứ (nét trên giống cái nắp, ở dưới là thân vò phình ra). Giải thích sự chuyển ý: Đây là chữ Tượng hình. Phẫu là cái chum, cái vò làm bằng đất nung.", "Nghĩa Tiếng Việt_Xie": "bộ phũ", "Hạng Tần Suất (Jun Da)": "5280.0", "Tần Suất % (Jun Da)": "99.9455117258", "GavinGrover_Once (Chiết tự trực tiếp)": "午 + 山", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱午山", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "午", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "缶", "Unihan_Traditional (Chữ Phồn thể)": "缶", "Pinyin_Xie": "fǒu", "Âm Hán Việt_Xie": "phữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại bình, vò bằng đất nung dùng để đựng rượu hoặc làm nhạc cụ gõ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笸', '{"9000": "5281.0", "Chữ Trung Quốc": "笸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 笸 | phả | tượng hình | cái rổ tre dẹt đựng thóc gạo | 笸 thuộc bộ 竹 (tre). Không có dữ liệu phân tích cấu trúc từ nguồn học thuật. Chỉ dùng trong từ 笸箩/笸籮 (rổ tre dẹt).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phả\": tre (竹) làm cái rổ \"phả\" dẹt — 笸箩 (phả la) là dụng cụ nông nghiệp truyền thống để sàng thóc. | Gương Hán-Việt | 笸箩 (phả la) — rổ tre dẹt dùng sàng thóc, dụng cụ nông thôn truyền thống | Mở khoá kiến thức | Biết 笸 giúp đọc tên dụng cụ nông nghiệp 笸箩 (phả la/pǒluó) trong văn xuôi và hồi ký nông thôn Trung Quốc.", "Tự nguyên_Xie": "Không có phân tích nguồn gốc từ Wiktionary hay CHISE cho 笸. Chữ thuộc bộ 竹 (tre), chỉ dùng trong 笸箩 (pǒluó) — rổ tre dẹt dùng đựng và sàng thóc gạo. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: phả la 笸籮,笸箩)", "Hạng Tần Suất (Jun Da)": "5281.0", "Tần Suất % (Jun Da)": "99.945580975", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 叵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮叵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笸", "Unihan_Traditional (Chữ Phồn thể)": "笸", "Pinyin_Xie": "pǒ", "Âm Hán Việt_Xie": "phả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ trong từ ghép chỉ đồ đan bằng tre để đựng đồ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸷', '{"9000": "5282.0", "Chữ Trung Quốc": "鸷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 11 | nét | 鸷 | chí | tượng hình | chim dữ, chim săn mồi (hawk, vulture) | 鸷 là dạng giản thể của 鷙 (執+鳥). Chữ gốc 鷙 gồm 執 (cầm nắm/bắt) + 鳥 (chim) — chim bắt mồi. Dạng giản thể rút gọn bộ 執→执 và 鳥→鸟.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chí\": chim (鸟) \"chí\" — loài chim săn mồi hung dữ, bắt (執) con mồi bằng móng vuốt. 鸷鸟 (chí điểu) là biểu tượng anh hùng trong Sở Từ. | Gương Hán-Việt | 鷙鳥 (chí điểu) — chim dữ, biểu tượng người tài khác thường trong Ly Tao (Khuất Nguyên) | Mở khoá kiến thức | Biết 鸷 giúp đọc hình ảnh 鷙鳥 (chí điểu) trong Ly Tao của Khuất Nguyên — ẩn dụ cho người có chí khí không chịu cúi đầu.", "Tự nguyên_Xie": "Tiểu triện | 鸷 là dạng giản thể của 鷙 — chim dữ, chim săn mồi (raptor). Chữ gốc 鷙 = 執 (bắt giữ) + 鳥 (chim), gợi ý loài chim chuyên bắt con mồi. Wiktionary xác nhận đây là dạng giản thể. Tiểu triện ghi nhận dạng chữ gốc. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loài chim dữ)", "Hạng Tần Suất (Jun Da)": "5282.0", "Tần Suất % (Jun Da)": "99.9456502242", "GavinGrover_Once (Chiết tự trực tiếp)": "执 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱执鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "执", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鸷", "Unihan_Traditional (Chữ Phồn thể)": "鷙", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "chí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ loài chim săn mồi hoặc làm tính từ mô tả sự hung dữ, dũng mãnh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芰', '{"9000": "5283.0", "Chữ Trung Quốc": "芰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 芰 | kỵ | tượng hình | củ ấu (water chestnut/water caltrop), cây thủy sinh có gai | 芰 thuộc bộ 艸 (cỏ). Cấu trúc hình thanh chi tiết chưa có nguồn học thuật. Chỉ loại cây ấu (water caltrop, Trapa) mọc dưới nước, quả có gai nhọn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỵ\": cỏ (艸) dưới nước — 芰 (kỵ) là cây ấu bốn cạnh, quả như ngôi sao gai nhọn nổi trên mặt ao trong thơ Khuất Nguyên. | Gương Hán-Việt | 芰荷 (kỵ hà) — cây ấu và hoa sen, hình ảnh trong Ly Tao của Khuất Nguyên | Mở khoá kiến thức | Biết 芰 giúp đọc 芰荷 (kỵ hà) — hình ảnh cây ấu và hoa sen trong Ly Tao, biểu tượng sự thanh cao của Khuất Nguyên.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary ghi nhận 芰 chủ yếu dùng trong văn bản cổ (chiefly archaic) chỉ cây ấu (water chestnut, Trapa spp.), đồng nghĩa với 菱 (líng). Xuất hiện trong Quốc Ngữ với điển tích Khuất Đáo thích ăn củ ấu. Đại triện và tiểu triện đã ghi nhận. Không có phân tích nguồn gốc chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loại củ ấu có 4 cạnh", "Hạng Tần Suất (Jun Da)": "5283.0", "Tần Suất % (Jun Da)": "99.9457882058", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 支", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹支", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "支", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芰", "Unihan_Traditional (Chữ Phồn thể)": "芰", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "kị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn học cổ để chỉ cây củ ấu hoặc lá củ ấu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕲', '{"9000": "5284.0", "Chữ Trung Quốc": "蕲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蕲 | kỳ | tượng hình | cây kỳ (loại cỏ thơm), địa danh Kỳ Châu | 蕲 là dạng giản thể của 蘄, thuộc bộ 艸 (cỏ). Cấu trúc chi tiết chưa có nguồn học thuật. Dùng trong 蕲茝 (kỳ chỉ) — cây cỏ thơm, và địa danh 蕲春 (Kỳ Xuân) ở Hồ Bắc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": cỏ (艸) \"kỳ\" lạ thơm — 蕲春 (Kỳ Xuân) là quê hương của danh y Lý Thời Trân, nơi có nhiều thảo dược quý. | Gương Hán-Việt | 蘄州 (Kỳ Châu), 蕲春 (Kỳ Xuân) — địa danh lịch sử ở Hồ Bắc, quê Lý Thời Trân | Mở khoá kiến thức | Biết 蕲 giúp đọc địa danh 蕲春 (Kỳ Xuân) — quê hương danh y Lý Thời Trân tác giả Bản Thảo Cương Mục.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 蕲 là dạng giản thể của 蘄 — chỉ loại cây cỏ thơm và địa danh vùng Hồ Bắc (蘄州, 蘄春). Wiktionary xác nhận là dạng giản thể. Tiểu triện và Lục thư thông ghi nhận dạng chữ gốc. Không có phân tích nguồn gốc chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: kỳ chỉ 蘄茝,蕲茝)", "Hạng Tần Suất (Jun Da)": "5284.0", "Tần Suất % (Jun Da)": "99.9458569382", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蕲", "Unihan_Traditional (Chữ Phồn thể)": "蘄", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ mang nghĩa cầu xin, mong mỏi trong văn ngôn hoặc làm danh từ riêng chỉ địa danh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阆', '{"9000": "5285.0", "Chữ Trung Quốc": "阆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 10 | nét | 阆 | lang | tượng hình | cửa cao, không gian rộng lớn, tiên cảnh | 阆 là dạng giản thể của 閬, thuộc bộ 門 (cửa). Cấu trúc hình thanh chi tiết chưa có nguồn học thuật. Chủ yếu dùng trong 阆苑 (lang uyển) — vườn tiên, tiên cảnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lang\": cửa (門) mở ra \"lang\" rộng — 阆苑 (lang uyển) là vườn tiên trên thiên đình, nơi Tây Vương Mẫu ngự. | Gương Hán-Việt | 閬苑 (lang uyển) — vườn tiên; 閬風 (lang phong) — núi tiên trong thần thoại; 阆中 (Lang Trung) — địa danh Tứ Xuyên | Mở khoá kiến thức | Biết 阆 giúp đọc 阆苑 (lang uyển) trong thơ Đường (Đỗ Phủ, Lý Bạch) và địa danh 阆中 (Lang Trung) ở Tứ Xuyên.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 阆 là dạng giản thể của 閬 — chỉ cửa cao, không gian rộng lớn, lạnh lẽo; thường dùng trong văn học để chỉ tiên cảnh. Wiktionary ghi nhận hai nghĩa: cao vời vợi và rộng trống. Đại triện và tiểu triện ghi nhận dạng chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bát ngát", "Hạng Tần Suất (Jun Da)": "5285.0", "Tần Suất % (Jun Da)": "99.9459256706", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 良", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门良", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "良", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阆", "Unihan_Traditional (Chữ Phồn thể)": "閬", "Pinyin_Xie": "láng", "Âm Hán Việt_Xie": "lãng, lang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ mô tả sự rộng lớn hoặc danh từ trong tên địa danh cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纨', '{"9000": "5286.0", "Chữ Trung Quốc": "纨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 6 | nét | 纨 | hoàn | tượng hình | lụa trắng mịn, lụa nõn cao cấp | 纨 là dạng giản thể của 紈, thuộc bộ 糸 (tơ lụa). Cấu trúc hình thanh chi tiết chưa có nguồn học thuật. Chỉ loại lụa trắng mịn cao cấp, biểu tượng xa hoa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàn\": tơ (糸) mịn \"hoàn\" — 纨绔子弟 (hoàn quát tử đệ) là con nhà giàu mặc lụa là, lười biếng không làm gì. | Gương Hán-Việt | 紈褲 (hoàn quát) — quần lụa, ẩn dụ cho kẻ ăn bám; 紈扇 (hoàn phiến) — quạt lụa trắng | Mở khoá kiến thức | Biết 纨 giúp đọc thành ngữ 纨绔子弟 (hoàn quát tử đệ) — con nhà giàu ăn chơi lêu lổng, và hiểu nền văn hóa lụa cổ đại.", "Tự nguyên_Xie": "Tiểu triện | 纨 là dạng giản thể của 紈 — lụa trắng mịn, tơ lụa cao cấp. Wiktionary xác nhận là dạng giản thể. Tiểu triện ghi nhận dạng chữ. Chữ thường xuất hiện trong 纨绔 (hoàn quát) — quần lụa, ẩn dụ cho kẻ con nhà giàu ăn không ngồi rồi. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lụa nõn", "Hạng Tần Suất (Jun Da)": "5286.0", "Tần Suất % (Jun Da)": "99.9459944031", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 丸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟丸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "纨", "Unihan_Traditional (Chữ Phồn thể)": "紈", "Pinyin_Xie": "wán", "Âm Hán Việt_Xie": "hoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong các từ ghép chỉ trang phục sang trọng của giới nhà giàu ngày xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('琮', '{"9000": "5287.0", "Chữ Trung Quốc": "琮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 12 | nét | 琮 | tông | tượng hình | ngọc tông — khối ngọc bát giác rỗng giữa, tế khí đại diện cho đất | 琮 thuộc bộ 玉 (ngọc). Cấu trúc hình thanh chi tiết chưa có nguồn học thuật. Chữ chỉ loại tế khí ngọc đặc biệt — hình hộp bát giác bên ngoài, trụ tròn rỗng bên trong, đại diện cho đất trong nghi lễ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tông\": ngọc (玉) hình vuông rỗng giữa — 琮 (tông) là tế khí đại diện cho đất, vuông ngoài tròn trong, triết lý âm dương của người Hoa Hạ. | Gương Hán-Việt | 黃琮 (hoàng tông) — ngọc tông màu vàng tế đất; 琮璧 (tông bích) — cặp tế khí ngọc trời-đất | Mở khoá kiến thức | Biết 琮 giúp đọc thuật ngữ khảo cổ và nghi lễ 黃琮 (hoàng tông), hiểu triết lý \"trời tròn đất vuông\" trong văn hóa ngọc cổ đại.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận 琮 là khối ngọc hình hộp chữ nhật có lỗ tròn ở giữa (hollow jade cylinder with rectangular sides). Đây là tế khí quan trọng trong nghi lễ — cùng với 璧 (tế trời), 琮 đại diện cho đất. Không có phân tích nguồn gốc chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc chạm hình bát giác, ở giữa tròn", "Hạng Tần Suất (Jun Da)": "5287.0", "Tần Suất % (Jun Da)": "99.9460631355", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 宗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王宗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "琮", "Unihan_Traditional (Chữ Phồn thể)": "琮", "Pinyin_Xie": "cóng", "Âm Hán Việt_Xie": "tông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại ngọc khí tế lễ thời cổ đại của Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('牦', '{"9000": "5288.0", "Chữ Trung Quốc": "牦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 牛 | Số nét | 8 | nét | 牦 | mao | tượng hình | con bò yak, bò lông dài vùng cao nguyên Tây Tạng | 牦 thuộc bộ 牛 (bò). Cấu trúc hình thanh chi tiết chưa có nguồn học thuật. Tiểu triện và Lục thư thông ghi nhận dạng chữ. Chỉ con bò yak hoặc lông đuôi ngựa dài.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mao\": bò (牛) lông \"mao\" dài phủ xuống — 牦牛 (mao ngưu) là con bò yak Tây Tạng, lông dài phủ kín thân chịu được lạnh giá. | Gương Hán-Việt | 犛牛/牦牛 (mao ngưu) — bò yak Tây Tạng, biểu tượng vùng cao nguyên | Mở khoá kiến thức | Biết 牦 giúp đọc 牦牛 (mao ngưu/máoniú) — con bò yak trong văn bản địa lý và du ký về Tây Tạng.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary chỉ ghi nhận Han etym cơ bản cho 牦. Chữ thuộc bộ 牛 (bò), chỉ con bò yak (犛牛/牦牛) ở cao nguyên Tây Tạng, nổi tiếng với bộ lông dài. Tiểu triện và Lục thư thông ghi nhận nhiều biến thể. Không có phân tích chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mao ngưu 犛牛,牦牛); đuôi ngựa; lông dài", "Hạng Tần Suất (Jun Da)": "5288.0", "Tần Suất % (Jun Da)": "99.9461318679", "GavinGrover_Once (Chiết tự trực tiếp)": "牛 + 毛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰牛毛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "牛", "Unihan_Simplified (Chữ Giản thể)": "牦", "Unihan_Traditional (Chữ Phồn thể)": "氂", "Pinyin_Xie": "máo", "Âm Hán Việt_Xie": "mao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong từ ghép để chỉ loài bò Tây Tạng có lông dài. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砩', '{"9000": "5289.0", "Chữ Trung Quốc": "砩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 10 | nét | 砩 | phất | tượng hình | đá huỳnh thạch (fluorite), đá dùng đắp đập ngăn nước | 砩 thuộc bộ 石 (đá). Cấu trúc hình thanh chi tiết chưa có nguồn học thuật. Wiktionary chỉ ghi nhận Han etym cơ bản. Chữ hiếm gặp trong văn bản hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phất\": đá (石) \"phất\" nước — 砩 là loại đá dùng đắp đập hoặc chỉ khoáng vật huỳnh thạch trong văn bản địa lý cổ. | Gương Hán-Việt | Chữ hiếm, ít gặp trong văn bản Hán-Việt thông dụng | Mở khoá kiến thức | 砩 là chữ hiếm thuộc bộ 石, xuất hiện trong văn bản khoáng vật học cổ hoặc địa lý chí.", "Tự nguyên_Xie": "Wiktionary chỉ ghi nhận Han etym cơ bản cho 砩. Chữ thuộc bộ 石 (đá), chỉ loại đá dùng đắp đập ngăn nước hoặc huỳnh thạch (fluorite). Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "huỳnh thạch", "Hạng Tần Suất (Jun Da)": "5289.0", "Tần Suất % (Jun Da)": "99.9462006003", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 弗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石弗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砩", "Unihan_Traditional (Chữ Phồn thể)": "砩", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phất, phế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong thuật ngữ khoáng sản hoặc xây dựng thủy lợi cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠲', '{"9000": "5290.0", "Chữ Trung Quốc": "蠲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 23 | nét | 蜀 | thục | biểu nghĩa | loài sâu (biểu nghĩa côn trùng) | 益 | ích | biểu âm | (biểu âm) | 蠲 = 蜀 (Thục, biểu nghĩa: loài sâu/côn trùng) + 益 (Ích, biểu âm); chữ hình thanh. Đây là chữ phức tạp nhất trong bộ 虫 với 23 nét.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyên\": sâu (蜀) lợi ích (益) — 蠲 (quyên) là \"miễn trừ gánh nặng\" như con cuốn chiếu đào đất, 蠲免 (quyên miễn) là miễn thuế cho dân. | Gương Hán-Việt | 蠲免 (quyên miễn) — miễn thuế, miễn dịch; 蠲除 (quyên trừ) — bãi bỏ, trừ khử | Mở khoá kiến thức | Biết 蠲 giúp đọc thuật ngữ hành chính cổ 蠲免 (quyên miễn — miễn thuế), 蠲租 (quyên tô — miễn tô ruộng) trong sử sách Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 蜀 (thục) biểu nghĩa liên quan đến loài sâu/côn trùng; 益 (ích) cho âm đọc. Wiktionary xác nhận cấu trúc psc này. Nghĩa văn học: trừ miễn (remit), làm sạch (cleanse), biểu hiện (manifest); nghĩa tự nhiên: con cuốn chiếu (julid/millipede). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sạch sẽ; trừ đi, loại được; sáng sủa; một loài sâu nhỏ nhiều chân", "Hạng Tần Suất (Jun Da)": "5290.0", "Tần Suất % (Jun Da)": "99.9462693328", "GavinGrover_Once (Chiết tự trực tiếp)": "益 + 蜀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰益蜀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蜀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "益", "Unihan_Simplified (Chữ Giản thể)": "蠲", "Unihan_Traditional (Chữ Phồn thể)": "蠲", "Pinyin_Xie": "juān", "Âm Hán Việt_Xie": "quyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ với nghĩa miễn giảm thuế khóa hoặc loại bỏ bệnh tật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锒', '{"9000": "5291.0", "Chữ Trung Quốc": "锒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 锒 | lang | tượng hình | xích sắt, xiềng xích (lock, chain) | 锒 là dạng giản thể của 鋃, thuộc bộ 金 (kim loại). Cấu trúc hình thanh chi tiết chưa có nguồn học thuật. Chỉ dùng trong 锒铛 (lang đang) — tiếng keng keng của xiềng xích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lang\": kim loại (金) khua \"lang\" đang — 锒铛入狱 (lang đang nhập ngục) là tiếng xiềng xích khua khi bị tống ngục. | Gương Hán-Việt | 鋃鐺 (lang đang) — xiềng xích, tiếng kim loại va chạm; 锒铛入狱 (lang đang nhập ngục) — bị bắt giam | Mở khoá kiến thức | Biết 锒 giúp đọc thành ngữ 锒铛入狱 (lang đang nhập ngục) — bị bắt xiềng xích tống vào ngục, xuất hiện thường xuyên trong văn học và báo chí.", "Tự nguyên_Xie": "Tiểu triện | 锒 là dạng giản thể của 鋃, chỉ dùng trong 锒铛 (lángdāng) — xiềng xích, tiếng keng keng của kim loại. Wiktionary xác nhận là dạng giản thể. Tiểu triện ghi nhận dạng chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lang đang 鋃鐺)", "Hạng Tần Suất (Jun Da)": "5291.0", "Tần Suất % (Jun Da)": "99.9463380652", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 良", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅良", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "良", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锒", "Unihan_Traditional (Chữ Phồn thể)": "鋃", "Pinyin_Xie": "láng", "Âm Hán Việt_Xie": "lang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong từ ghép để chỉ xiềng xích hoặc tiếng kêu của kim loại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锕', '{"9000": "5292.0", "Chữ Trung Quốc": "锕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 锕 | a | tượng hình | nguyên tố actini (Ac, số hiệu 89) | 锕 thuộc bộ 金 (kim loại). Là chữ tạo mới để ký hiệu nguyên tố hóa học actinium (Ac). Cấu trúc chi tiết chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"a\": kim loại (金) phóng xạ \"a\" — 锕 (a) là ký hiệu Hán cho nguyên tố actinium, kim loại phóng xạ hiếm gặp trong thiên nhiên. | Gương Hán-Việt | Chữ thuần khoa học, ít xuất hiện trong Hán-Việt cổ điển | Mở khoá kiến thức | Biết 锕 giúp đọc bảng tuần hoàn tiếng Trung — 锕系元素 (a hệ nguyên tố) là dãy actinide trong hóa học hạt nhân.", "Tự nguyên_Xie": "锕 là chữ tạo mới dùng để phiên âm nguyên tố hóa học actinium (Ac, số nguyên tử 89). Chữ thuộc bộ 金 (kim loại), thể hiện đây là kim loại phóng xạ. Không có phân tích nguồn gốc chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố actini, Ac", "Hạng Tần Suất (Jun Da)": "5292.0", "Tần Suất % (Jun Da)": "99.9464067976", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 阿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅阿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锕", "Unihan_Traditional (Chữ Phồn thể)": "錒", "Pinyin_Xie": "ā", "Âm Hán Việt_Xie": "a", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nguyên tố hóa học actini, thường dùng trong thuật ngữ khoa học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郓', '{"9000": "5293.0", "Chữ Trung Quốc": "郓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 8 | nét | 軍 | quân | biểu âm | (biểu âm) | 邑 | ấp | biểu nghĩa | ấp/làng, địa danh | 郓 = 軍 (Quân, biểu âm) + 邑 (Ấp, biểu nghĩa: địa danh); chữ hình thanh. Chỉ địa danh — ấp Vận thuộc nước Lỗ thời Xuân Thu (nay thuộc Sơn Đông).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vận\": ấp (邑) + quân (軍 biểu âm) — 郓 (vận) là địa danh lịch sử ở Sơn Đông, từ thời Xuân Thu đến nay gắn với huyện Vận Thành trong Thủy Hử. | Gương Hán-Việt | 郓城 (Vận Thành) — địa danh Sơn Đông, quê hương nhân vật Tống Giang trong Thủy Hử | Mở khoá kiến thức | Biết 郓 giúp đọc địa danh 郓城 (Vận Thành) — quê của Tống Giang trong tiểu thuyết Thủy Hử, và 郓州 (Vận Châu) trong sử sách.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Chữ hình thanh: 邑 (ấp) biểu nghĩa chỉ địa danh; 軍 (quân) cho âm đọc. 郓 chỉ ấp Vận (郓邑) thuộc nước Lỗ thời Xuân Thu — nay là huyện Vận Thành (郓城) tỉnh Sơn Đông. Kim văn và tiểu triện ghi nhận dạng chữ. Wiktionary xác nhận cấu trúc hình thanh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ấp Vận thuộc nước Lỗ thời xưa (nay thuộc tỉnh Sơn Đông của Trung Quốc); họ Vận", "Hạng Tần Suất (Jun Da)": "5293.0", "Tần Suất % (Jun Da)": "99.94647553", "GavinGrover_Once (Chiết tự trực tiếp)": "军 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰军阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "军", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郓", "Unihan_Traditional (Chữ Phồn thể)": "鄆", "Pinyin_Xie": "yùn", "Âm Hán Việt_Xie": "vận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng chỉ địa danh thời cổ hoặc họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('妯', '{"9000": "5294.0", "Chữ Trung Quốc": "妯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 8 | nét | 女 | nữ | biểu nghĩa | người phụ nữ | 由 | do | biểu âm | 妯 = 女 (Nữ, biểu nghĩa: phụ nữ) + 由 (Do, biểu âm); chữ hình thanh. Bộ Nữ cho biết liên quan đến phụ nữ, 由 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dâu\": người phụ nữ (女) đến nhà chồng, mang theo duyên do (由) — ấy là mối dâu chị em trong một nhà. | Gương Hán-Việt | dâu trong tổ hợp chỉ quan hệ hôn nhân gia đình | Mở khoá kiến thức | Biết 妯 mở khoá cụm 妯娌 (chị em dâu) — từ chỉ quan hệ trong gia đình truyền thống.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 女 (nữ) là phần biểu nghĩa chỉ phụ nữ, 由 là phần biểu âm cho âm đọc zhóu. Nghĩa gốc chỉ chị em dâu trong gia đình (妯娌 zhóulǐ). Dạng tiểu triện đã ghi nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chị em dâu", "Hạng Tần Suất (Jun Da)": "5294.0", "Tần Suất % (Jun Da)": "99.9465437457", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 由", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女由", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "由", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "妯", "Unihan_Traditional (Chữ Phồn thể)": "妯", "Pinyin_Xie": "zhóu", "Âm Hán Việt_Xie": "trục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp thành từ ghép cỗ dâu để chỉ quan hệ chị em dâu trong gia đình. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驷', '{"9000": "5295.0", "Chữ Trung Quốc": "驷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 8 | nét | 驷 | tứ | tượng hình | xe bốn ngựa kéo | 驷 là chữ tượng hình/hội ý cổ, viết tắt từ 馬 (ngựa) kết hợp với ý tứ (bốn). Dạng kim văn và đại triện ghi rõ hình ảnh bốn con ngựa kéo xe. Đây là chữ tạo muộn hơn so với các chữ kim văn cơ bản.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tứ\": bốn con ngựa (tứ = bốn) cùng kéo một cỗ xe — uy thế vua chúa thời xưa. | Gương Hán-Việt | tứ trong 驷马 (tứ mã — xe bốn ngựa) | Mở khoá kiến thức | Biết 驷 mở khoá thành ngữ 驷马难追 — lời nói ra như tứ mã khó đuổi kịp.", "Tự nguyên_Xie": "Kim văn | Bạch thư | Đại triện | Tiểu triện | 驷 vốn chỉ cỗ xe bốn ngựa kéo, dùng trong thời cổ đại khi xe tứ mã là biểu tượng quyền lực và địa vị. Dạng kim văn, bạch thư và tiểu triện đều ghi nhận chữ này với hình ảnh bốn ngựa. Thành ngữ 驷马难追 (tứ mã nan truy) — lời nói ra không lấy lại được dù tứ mã đuổi theo. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỗ xe 4 ngựa", "Hạng Tần Suất (Jun Da)": "5295.0", "Tần Suất % (Jun Da)": "99.9466119613", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 四", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马四", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "四", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "驷", "Unihan_Traditional (Chữ Phồn thể)": "駟", "Pinyin_Xie": "sì", "Âm Hán Việt_Xie": "tứ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Làm danh từ chỉ cỗ xe bốn ngựa hoặc làm lượng từ để đếm số lượng xe ngựa thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹩', '{"9000": "5296.0", "Chữ Trung Quốc": "鹩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 17 | nét | 鹩 | liêu | tượng hình | chim nhỏ (tiêu liêu/chim sẻ nhỏ) | 鹩 là chữ chỉ loài chim nhỏ (wren), dùng hầu như chỉ trong tổ hợp 鹪鹩 (tiêu liêu). Chữ giản thể của 鷯. Cấu trúc phức tạp, chưa tra được thành phần hình thanh rõ ràng từ dữ liệu hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêu\": con chim liêu (鹩) bé tí, chỉ cần một cành cây để đậu — biểu tượng của sự an phận, giản dị. | Gương Hán-Việt | liêu trong 鹪鹩 (tiêu liêu — chim sẻ nhỏ) | Mở khoá kiến thức | Biết 鹩 mở khoá tổ hợp 鹪鹩 và thành ngữ 鹪鹩一枝 — ý nói an phận với chút ít.", "Tự nguyên_Xie": "Tiểu triện | 鹩 là dạng giản thể của 鷯, chỉ loài chim nhỏ bé như chim sẻ. Thường dùng trong tổ hợp 鹪鹩 (tiêu liêu) — loài chim wren. Thành ngữ 鹪鹩一枝 (tiêu liêu nhất chi) — chỉ cần một cành cây nhỏ, ý nói người biết đủ an phận. Chưa có nguồn học thuật đầy đủ về cấu tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tiêu liêu 鷦鷯,鹪鹩)", "Hạng Tần Suất (Jun Da)": "5296.0", "Tần Suất % (Jun Da)": "99.9466801769", "GavinGrover_Once (Chiết tự trực tiếp)": "尞 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰尞鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹩", "Unihan_Traditional (Chữ Phồn thể)": "鷯", "Pinyin_Xie": "liáo", "Âm Hán Việt_Xie": "liêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ khác để tạo thành tên loài chim nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舢', '{"9000": "5297.0", "Chữ Trung Quốc": "舢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 9 | nét | 舢 | san | tượng hình | thuyền nhỏ (san bản) | 舢 là chữ dùng chủ yếu trong tổ hợp 舢舨 (san bản) chỉ loại thuyền nhỏ chèo tay. Không có dữ liệu cấu trúc thành phần rõ ràng. Chưa có nguồn học thuật về nguồn gốc chữ viết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"san\": chiếc thuyền san bản (舢舨) — nhỏ bé, chèo tay, len lỏi giữa các tàu lớn trong cảng. | Gương Hán-Việt | san trong 舢舨 (san bản — thuyền nhỏ) | Mở khoá kiến thức | Biết 舢 mở khoá từ 舢舨 — loại thuyền nhỏ quen thuộc ở vùng cảng biển Trung Quốc.", "Tự nguyên_Xie": "舢 dùng chủ yếu trong tổ hợp 舢舨 (san bản) hoặc 舢板, chỉ loại thuyền nhỏ dùng để chèo tay, thường dùng ở cảng hoặc sông. Đây là chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật đầy đủ về cấu tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: san bản 舢舨,舢板)", "Hạng Tần Suất (Jun Da)": "5297.0", "Tần Suất % (Jun Da)": "99.9467483926", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 山", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟山", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "山", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "舢", "Unihan_Traditional (Chữ Phồn thể)": "舢", "Pinyin_Xie": "shān", "Âm Hán Việt_Xie": "san", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ bản để chỉ loại thuyền gỗ nhỏ đi sông biển. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趸', '{"9000": "5298.0", "Chữ Trung Quốc": "趸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 10 | nét | 趸 | đốn | tượng hình | hàng nguyên kiện, số chỉnh | 趸 là dạng giản thể của 躉. Theo Wiktionary, 趸 được giản hoá từ 躉 bằng cách thay 萬 thành 万. Chữ tạo muộn, chủ yếu dùng trong từ 趸售 (bán buôn nguyên kiện) hoặc 趸船 (thuyền cầu tàu nổi). Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đốn\": mua bán theo đốn (趸) — mua nguyên kiện, bán buôn sỉ, hàng chỉnh tề số lượng lớn. | Gương Hán-Việt | đốn trong 趸售 (đốn thụ — bán buôn sỉ) | Mở khoá kiến thức | Biết 趸 mở khoá từ 趸售 (bán sỉ) và 趸船 (thuyền cầu tàu nổi).", "Tự nguyên_Xie": "趸 là dạng giản thể của 躉. Wiktionary ghi: giản hoá từ 躉 (f=萬, t=万). Dùng trong 趸售 nghĩa là bán theo lô/buôn sỉ, và 趸船 chỉ loại thuyền bè nổi làm cầu tàu. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hàng số chỉnh tề", "Hạng Tần Suất (Jun Da)": "5298.0", "Tần Suất % (Jun Da)": "99.9468166082", "GavinGrover_Once (Chiết tự trực tiếp)": "万 + 足", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱万足", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "万", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "足", "Unihan_Simplified (Chữ Giản thể)": "趸", "Unihan_Traditional (Chữ Phồn thể)": "躉", "Pinyin_Xie": "dǔn", "Âm Hán Việt_Xie": "độn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Phó từ | 副词 | Thường làm phó từ đứng trước động từ để chỉ hành vi mua hoặc bán với số lượng lớn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芫', '{"9000": "5299.0", "Chữ Trung Quốc": "芫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 艸 | tháu | biểu nghĩa | cỏ, thực vật | 元 | nguyên | biểu âm | 芫 = 艸/艹 (Tháu, biểu nghĩa: cỏ/thực vật) + 元 (Nguyên, biểu âm); chữ hình thanh. Bộ 艹 cho biết đây là loài thực vật, 元 cho âm yuán/yán. Tên một loài cây độc dùng làm thuốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nguyên\": cây cỏ (艹) mang tên nguyên (元) — cây nguyên hoa độc tính, nhưng là vị thuốc quý trong đông y. | Gương Hán-Việt | nguyên trong 芫花 (nguyên hoa), 芫荽 (nguyên tuy — rau mùi) | Mở khoá kiến thức | Biết 芫 mở khoá tên cây thuốc 芫花 và rau gia vị 芫荽 (rau mùi).", "Tự nguyên_Xie": "Tiểu triện | 芫 là chữ hình thanh: 艹 (tháu) là phần biểu nghĩa chỉ thực vật, 元 là phần biểu âm. Chỉ hai loài: 芫花 (nguyên hoa, Daphne genkwa) — cây thuốc có hoa tím độc tính cao; và 芫荽 (nguyên tuy, rau mùi). Dạng tiểu triện ghi nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: nguyên hoa 芫花); cây thuốc cá (một loại cây độc còn gọi là ngư độc 魚毒,鱼毒, tên khoa học: daphne genkwa)", "Hạng Tần Suất (Jun Da)": "5299.0", "Tần Suất % (Jun Da)": "99.9470207383", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 元", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹元", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "元", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芫", "Unihan_Traditional (Chữ Phồn thể)": "芫", "Pinyin_Xie": "yán", "Âm Hán Việt_Xie": "nguyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng trong tên gọi các loại thực vật như rau mùi hoặc cây thuốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗉', '{"9000": "5300.0", "Chữ Trung Quốc": "嗉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 嗉 | nhố | tượng hình | cái diều chim | 嗉 không có dữ liệu cấu trúc thành phần rõ ràng. Chữ chỉ cái diều (túc thực) của chim — phần phình ra ở cổ chim để chứa thức ăn tạm thời trước khi tiêu hóa. Chưa có nguồn học thuật về cấu tạo chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhố\": cái diều nhố (嗉) của con chim — phình phồng ở cổ, chứa đầy hạt giống trước khi tiêu hóa. | Gương Hán-Việt | nhố trong 嗉囊 (nhố nang — diều chim) | Mở khoá kiến thức | Biết 嗉 mở khoá từ chuyên ngành sinh học 嗉囊 (diều chim, crop) — bộ phận tiêu hóa đặc trưng của chim.", "Tự nguyên_Xie": "嗉 chỉ cái diều (crop) của chim — túi chứa thức ăn nằm ở phần cổ trước khi vào dạ dày. Dùng trong tổ hợp 嗉囊 (nhố nang), 嗉袋, 嗉子. Chưa có nguồn học thuật về nguồn gốc chữ viết. Chưa có nguồn học thuật đầy đủ về cấu tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái diều (gà, chim)", "Hạng Tần Suất (Jun Da)": "5300.0", "Tần Suất % (Jun Da)": "99.9470884372", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 素", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口素", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "素", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗉", "Unihan_Traditional (Chữ Phồn thể)": "嗉", "Pinyin_Xie": "sù", "Âm Hán Việt_Xie": "tố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ bộ phận chứa thức ăn ở cổ của các loài chim và gia cầm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠊', '{"9000": "5301.0", "Chữ Trung Quốc": "蠊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 19 | nét | 蠊 | liêm | tượng hình | con gián (trong tổ hợp 蜚蠊) | 蠊 không có dữ liệu cấu trúc thành phần rõ ràng. Chữ chỉ dùng trong tổ hợp 蜚蠊 (phỉ liêm — con gián). Đây là chữ chuyên dụng trong từ điển cổ và sinh học. Chưa có nguồn học thuật về cấu tạo chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêm\": con liêm (蠊) trong tổ hợp phỉ liêm (蜚蠊) — tên cổ điển của con gián, loài côn trùng sống sót từ thời tiền sử. | Gương Hán-Việt | liêm trong 蜚蠊 (phỉ liêm — con gián) | Mở khoá kiến thức | Biết 蠊 mở khoá tên khoa học dân gian 蜚蠊 — tên cổ điển của con gián trong y học và sinh học truyền thống.", "Tự nguyên_Xie": "蠊 dùng trong 蜚蠊 (phỉ liêm) chỉ con gián (cockroach). Wiktionary cũng ghi nhận nghĩa cổ là một loài nhuyễn thể biển dài một thốn, màu trắng, ăn được. Đây là chữ tạo muộn, chưa có nguồn học thuật đầy đủ về cấu tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: phỉ liêm 蜚蠊)", "Hạng Tần Suất (Jun Da)": "5301.0", "Tần Suất % (Jun Da)": "99.9471561361", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 廉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫廉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "廉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蠊", "Unihan_Traditional (Chữ Phồn thể)": "蠊", "Pinyin_Xie": "lián", "Âm Hán Việt_Xie": "liêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp thành từ ghép phỉ liêm để chỉ con gián trong sinh học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笊', '{"9000": "5302.0", "Chữ Trung Quốc": "笊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 10 | nét | 笊 | chảo | tượng hình | cái rổ tre, cái muôi lưới | 笊 không có dữ liệu cấu trúc thành phần và không có dữ liệu nguồn gốc chữ viết. Chữ dùng chủ yếu trong tổ hợp 笊篱 (chảo ly) chỉ cái rổ lọc bằng tre/kim loại. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chảo\": cái chảo ly (笊篱) — dụng cụ nhà bếp đan bằng tre, vớt mì hay rau ra khỏi nồi nước sôi. | Gương Hán-Việt | chảo trong 笊篱 (chảo ly — rổ lọc, muôi lưới) | Mở khoá kiến thức | Biết 笊 mở khoá từ 笊篱 — dụng cụ nhà bếp truyền thống của người Trung Quốc.", "Tự nguyên_Xie": "笊 dùng chủ yếu trong tổ hợp 笊篱 (chảo ly — cái rổ/muôi lưới) chỉ dụng cụ nhà bếp có lỗ để lọc vớt thức ăn ra khỏi nước sôi. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật đầy đủ về cấu tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tráo ly 笊篱,笊籬)", "Hạng Tần Suất (Jun Da)": "5302.0", "Tần Suất % (Jun Da)": "99.9472238349", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 爪", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮爪", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爪", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笊", "Unihan_Traditional (Chữ Phồn thể)": "笊", "Pinyin_Xie": "zhào", "Âm Hán Việt_Xie": "tráo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ loại vợt tre dùng trong nhà bếp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莸', '{"9000": "5303.0", "Chữ Trung Quốc": "莸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 莸 | du | tượng hình | cây du (cỏ hôi) | 莸 không có dữ liệu cấu trúc thành phần rõ ràng. Chữ chỉ loài cây bụi nhỏ Caryopteris divaricata — cây có lá răng cưa và mùi hôi. Thường đối lập với 薰 (hương thơm) trong thành ngữ cổ. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": cây du (莸) có mùi hôi — đối lập với cỏ thơm 薰, ví cho điều xấu xa không thể chung với điều tốt đẹp. | Gương Hán-Việt | du trong 薰莸 (huân du — thơm và hôi) | Mở khoá kiến thức | Biết 莸 mở khoá thành ngữ 薰莸不同器 — tốt xấu không thể chung chạ.", "Tự nguyên_Xie": "Tiểu triện | 莸 chỉ cây Caryopteris divaricata — một loài cây bụi nhỏ có mùi hôi, lá hình trứng, hoa màu xanh lam. Trong văn học cổ, 莸 (hôi) đối lập với 薰 (thơm) để nói về sự không thể hòa hợp giữa tốt và xấu. Thành ngữ 薰莸不同器 — hương và臭 không thể chứa chung. Dạng tiểu triện ghi nhận chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ du (lá có răng cưa, mùi rất hôi); một loại cây bụi nhỏ (rụng lá, lá hình trứng, hoa màu lam, kết quả nang, toàn cây hoặc phần rễ dùng làm thuốc)", "Hạng Tần Suất (Jun Da)": "5303.0", "Tần Suất % (Jun Da)": "99.947291017", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 犹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹犹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莸", "Unihan_Traditional (Chữ Phồn thể)": "蕕", "Pinyin_Xie": "yóu", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn học cổ để chỉ một loại cỏ hôi đối lập với cỏ thơm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饴', '{"9000": "5304.0", "Chữ Trung Quốc": "饴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 8 | nét | 饴 | di | tượng hình | kẹo mạch nha, mật ngọt | 饴 không có dữ liệu cấu trúc thành phần rõ ràng trong nguồn hiện có. Chữ chỉ kẹo mạch nha — loại đường dẻo làm từ ngũ cốc lên men. Hình thức kim văn và tiểu triện được ghi nhận. Chưa có nguồn học thuật về cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"di\": kẹo di (饴) — mạch nha ngọt dẻo, hình ảnh bà nội ngậm kẹo ngọt chơi với cháu nhỏ trong thành ngữ 含饴弄孙. | Gương Hán-Việt | di trong 饴糖 (di đường — mạch nha), 含饴弄孙 | Mở khoá kiến thức | Biết 饴 mở khoá thành ngữ 含饴弄孙 — hình ảnh tuổi già hạnh phúc bên cháu con.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 饴 chỉ kẹo mạch nha (maltose syrup) — loại đường dẻo, ngọt, vàng óng, làm từ gạo hoặc ngũ cốc lên men. Dạng kim văn và tiểu triện được ghi nhận. Thành ngữ 含饴弄孙 (hàm di lộng tôn) — ngậm kẹo mạch nha chơi với cháu, ý nói tuổi già nhàn hạ hưởng phúc. Chưa có nguồn học thuật đầy đủ về cấu tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọt lắm, ngọt khé; kẹo mạch nha", "Hạng Tần Suất (Jun Da)": "5304.0", "Tần Suất % (Jun Da)": "99.947358199", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 台", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣台", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "台", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "饴", "Unihan_Traditional (Chữ Phồn thể)": "飴", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ kẹo mạch nha hoặc làm tính từ chỉ vị ngọt ngào. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阃', '{"9000": "5305.0", "Chữ Trung Quốc": "阃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 10 | nét | 阃 | khổn | tượng hình | ngưỡng cửa; khu phụ nữ | 阃 không có dữ liệu cấu trúc thành phần rõ ràng. Chữ chỉ ngưỡng cửa của tường thành ngoài, mở rộng sang nghĩa khu vực phụ nữ (khuê phòng), vợ. Chưa có nguồn học thuật về cấu tạo chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khổn\": ngưỡng cửa khổn (阃) của tường thành — ranh giới giữa trong và ngoài, ví như khuê phòng sâu kín của phụ nữ thời xưa. | Gương Hán-Việt | khổn trong 阃外 (khổn ngoại — bên ngoài biên ải, quân sự) | Mở khoá kiến thức | Biết 阃 mở khoá từ văn học cổ và lịch sử: 阃外 (vùng ngoài biên giới), khuê phòng trong thơ cổ.", "Tự nguyên_Xie": "阃 (khổn) nghĩa gốc là ngưỡng cửa (threshold/doorsill), đặc biệt là ngưỡng cửa tường thành ngoài của đô thị. Từ đó mở rộng sang nghĩa khu phụ nữ (khuê phòng) và kính ngữ chỉ vợ. Cũng dùng trong quân sự với nghĩa biên cương bên ngoài. Chưa có nguồn học thuật đầy đủ về cấu tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái then cửa; cồng ngoài thành", "Hạng Tần Suất (Jun Da)": "5305.0", "Tần Suất % (Jun Da)": "99.9474253811", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 困", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门困", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "困", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阃", "Unihan_Traditional (Chữ Phồn thể)": "閫", "Pinyin_Xie": "kǔn", "Âm Hán Việt_Xie": "khổn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ ngưỡng cửa hoặc khu vực sinh hoạt của phụ nữ thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('浯', '{"9000": "5306.0", "Chữ Trung Quốc": "浯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 浯 | ngô | tượng hình | tên sông ở Sơn Đông | 浯 không có dữ liệu cấu trúc thành phần và không có dữ liệu nguồn gốc chữ viết. Chữ chỉ tên riêng của sông Ngô (浯水/浯河) ở tỉnh Sơn Đông, Trung Quốc. Đây là chữ địa danh chuyên dụng. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngô\": sông Ngô (浯) — con sông chảy qua đất Sơn Đông, ghi dấu tên gọi cổ xưa trong địa lý Trung Hoa. | Gương Hán-Việt | ngô trong 浯水 (sông Ngô) | Mở khoá kiến thức | Biết 浯 giúp đọc hiểu địa danh lịch sử 浯水 trong văn bản địa lý và sử Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | 浯 là tên riêng của sông Ngô (浯水 hoặc 浯河) ở Sơn Đông, Trung Quốc. Dạng tiểu triện được ghi nhận. Đây là chữ địa danh chuyên dụng. Chưa có nguồn học thuật đầy đủ về cấu tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Ngô (ở tỉnh Sơn Đông của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "5306.0", "Tần Suất % (Jun Da)": "99.9474925632", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 吾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵吾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "浯", "Unihan_Traditional (Chữ Phồn thể)": "浯", "Pinyin_Xie": "wú", "Âm Hán Việt_Xie": "ngô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng để chỉ tên sông hoặc địa danh ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('枇', '{"9000": "5307.0", "Chữ Trung Quốc": "枇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 8 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 比 | tỷ | biểu âm | 枇 = 木 (Mộc, biểu nghĩa: cây) + 比 (Tỷ, biểu âm); chữ hình thanh. Bộ Mộc cho biết đây là loài cây, 比 cho âm pí. Chủ yếu dùng trong tổ hợp 枇杷 (tỳ bà — quả nhót).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỳ\": cây mộc (木) mang âm tỷ (比) — cây tỳ bà (枇杷) cho quả nhỏ vàng óng như nhạc khí tỳ bà nổi tiếng. | Gương Hán-Việt | tỳ trong 枇杷 (tỳ bà — quả loquat) | Mở khoá kiến thức | Biết 枇 mở khoá từ 枇杷 — cây quả nhót nổi tiếng trong đông y và ẩm thực Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 枇 là chữ hình thanh: 木 (mộc) là phần biểu nghĩa chỉ cây, 比 là phần biểu âm cho âm pí. Chủ yếu dùng trong tổ hợp 枇杷 (tỳ bà — loquat, quả nhót hay táo nhật). Dạng tiểu triện và lục thư thông được ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây sơn trà", "Hạng Tần Suất (Jun Da)": "5307.0", "Tần Suất % (Jun Da)": "99.9475597452", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 比", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木比", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "比", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "枇", "Unihan_Traditional (Chữ Phồn thể)": "枇", "Pinyin_Xie": "pí", "Âm Hán Việt_Xie": "tì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ bà để tạo thành danh từ chỉ cây tỳ bà. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('焱', '{"9000": "5308.0", "Chữ Trung Quốc": "焱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 12 | nét | 火 | hỏa | biểu nghĩa | lửa | 火 | hỏa | biểu nghĩa | lửa | 火 | hỏa | biểu nghĩa | lửa | 焱 = 火 + 火 + 火 (ba chữ Hỏa chồng lên nhau); chữ hội ý. Wiktionary ghi zh-etym-triple: 火. Ba ngọn lửa gộp lại tạo thành tia lửa bùng lên mạnh mẽ. Tương tự như 森 (ba cây = rừng rậm), 品 (ba miệng = nhiều).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diễm\": ba ngọn lửa (火×3) gộp lại thành 焱 — tia lửa diễm lệ bùng cháy, sáng rực như tên người trong thơ văn Trung Hoa. | Gương Hán-Việt | diễm trong 焱焱 (diễm diễm — lửa cháy rực); cũng dùng làm tên người | Mở khoá kiến thức | Biết 焱 giúp nhận ra mô hình ba bộ thủ ghép lại: 淼 (nước mênh mông), 森 (rừng), 晶 (sáng trong).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 焱 là chữ hội ý gồm ba chữ 火 (hỏa — lửa) xếp chồng. Wiktionary xác nhận: zh-etym-triple 火. Ba ngọn lửa biểu trưng cho tia lửa bùng phát mạnh mẽ hoặc ngọn lửa sáng rực. Dạng đại triện và tiểu triện được ghi nhận. Cùng kiểu cấu tạo với 淼 (ba Thủy = nước mênh mông) hay 磊 (ba Thạch = đống đá). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tia lửa toé ra", "Hạng Tần Suất (Jun Da)": "5308.0", "Tần Suất % (Jun Da)": "99.9476269273", "GavinGrover_Once (Chiết tự trực tiếp)": "火", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "品 (Kiến trúc tam giác)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴火", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "焱", "Unihan_Traditional (Chữ Phồn thể)": "焱", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "diễm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ tia lửa hoặc dùng đặt tên người với nghĩa sáng lạng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铆', '{"9000": "5309.0", "Chữ Trung Quốc": "铆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 铆 | mão | tượng hình | đinh tán, rivê | 铆 không có dữ liệu cấu trúc thành phần và không có dữ liệu nguồn gốc chữ viết. Chữ chỉ đinh tán (rivet) trong cơ khí — loại đinh kim loại dùng để nối ghép các tấm kim loại. Chữ tạo muộn, liên quan đến kỹ thuật cơ khí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mão\": đinh tán mão (铆) — ghim chặt các tấm thép lại với nhau, dồn hết lực vào từng nhát búa. | Gương Hán-Việt | mão trong 铆钉 (mão đinh — đinh tán, rivet) | Mở khoá kiến thức | Biết 铆 mở khoá từ kỹ thuật 铆钉 (đinh tán) và thành ngữ 铆劲儿 (dồn hết sức).", "Tự nguyên_Xie": "铆 là thuật ngữ cơ khí chỉ đinh tán (rivet) và thao tác tán đinh. 铆钉 (mão đinh) là đinh tán dùng trong xây dựng tàu thuyền, cầu cống, máy bay. 铆劲儿 (mão kình nhi) nghĩa bóng là dồn hết sức lực vào. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rivê (cơ khí); tán rivê", "Hạng Tần Suất (Jun Da)": "5309.0", "Tần Suất % (Jun Da)": "99.9476935926", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 卯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅卯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铆", "Unihan_Traditional (Chữ Phồn thể)": "鉚", "Pinyin_Xie": "mǎo", "Âm Hán Việt_Xie": "mão", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ hành động tán đinh hoặc làm danh từ chỉ đinh tán trong cơ khí. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('擤', '{"9000": "5310.0", "Chữ Trung Quốc": "擤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 17 | nét | 扌 | biểu nghĩa | tay | 鼻 | tỵ | biểu nghĩa | mũi | 擤 = 扌 (biểu nghĩa: tay) + 鼻 (Tỵ, biểu nghĩa: mũi); chữ hội ý. Hai phần kết hợp theo nghĩa: tay (扌) + mũi (鼻) = động tác dùng tay hỉ mũi. Cấu trúc hội ý rất trực quan, ít thấy trong chữ Hán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hảnh\": tay (扌) áp vào mũi (鼻) — động tác hỉ mũi hảnh rất đời thường, chữ vẽ lại đúng cử chỉ đó. | Gương Hán-Việt | hảnh trong 擤鼻涕 (hảnh tỵ thế — hỉ mũi) | Mở khoá kiến thức | Biết 擤 giúp đọc hiểu từ y học và sinh hoạt 擤鼻涕 — hành động hỉ mũi.", "Tự nguyên_Xie": "擤 là chữ hội ý: 手/扌 (tay) và 鼻 (mũi) kết hợp diễn tả hành động dùng tay hỉ mũi (blow one''s nose). Wiktionary xác nhận ls=ic. Cấu trúc hội ý trực quan hiếm gặp trong tiếng Trung hiện đại. Chưa có ghi nhận dạng cổ văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hỉ mũi, xỉ mũi, xì mũi", "Hạng Tần Suất (Jun Da)": "5310.0", "Tần Suất % (Jun Da)": "99.9477602579", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 鼻", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌鼻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鼻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "擤", "Unihan_Traditional (Chữ Phồn thể)": "擤", "Pinyin_Xie": "xǐng", "Âm Hán Việt_Xie": "tỉnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ nước mũi để diễn tả hành động xì mũi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('柢', '{"9000": "5311.0", "Chữ Trung Quốc": "柢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 柢 | đê | tượng hình | rễ cây, gốc rễ | 柢 không có dữ liệu cấu trúc thành phần rõ ràng. Chữ chỉ rễ cây — phần ăn sâu vào đất, nền tảng của cây. Dùng trong thành ngữ 根深柢固 (căn sâu đê cố — gốc rễ vững chắc). Dạng tiểu triện được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đê\": rễ đê (柢) cắm sâu xuống lòng đất — trong thành ngữ 根深柢固, nền móng vững như rễ cây trăm tuổi. | Gương Hán-Việt | đê trong 根深柢固 (căn sâu đê cố — gốc rễ vững chắc) | Mở khoá kiến thức | Biết 柢 mở khoá thành ngữ 根深柢固 — dùng để ca ngợi điều gì có nền tảng bền vững, sâu xa.", "Tự nguyên_Xie": "Tiểu triện | 柢 chỉ rễ cây (root), đặc biệt là rễ chính ăn sâu vào lòng đất. Dùng trong thành ngữ 根深柢固 — nền móng vững chắc, ý nói điều gì đó bền vững lâu dài. Dạng tiểu triện được ghi nhận. Chưa có nguồn học thuật đầy đủ về cấu tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rễ cây", "Hạng Tần Suất (Jun Da)": "5311.0", "Tần Suất % (Jun Da)": "99.9478269232", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 氐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木氐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "氐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "柢", "Unihan_Traditional (Chữ Phồn thể)": "柢", "Pinyin_Xie": "dǐ", "Âm Hán Việt_Xie": "để", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ phần gốc rễ của cây hoặc nguồn gốc của một vấn đề. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醢', '{"9000": "5312.0", "Chữ Trung Quốc": "醢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 17 | nét | 醢 | hải | tượng hình | thịt ướp, thịt băm; hình phạt băm thịt | 醢 không có dữ liệu cấu trúc thành phần rõ ràng. Chữ chỉ thịt muối ướp hoặc thịt băm nhỏ (minced pickled meat) — một loại ẩm thực cổ đại. Cũng là tên hình phạt cực hình thời cổ: băm xác phạm nhân. Dạng tiểu triện và lục thư thông được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hải\": hải (醢) — thịt băm muối ướp thời cổ đại; cũng là cực hình man rợ nhất trong lịch sử Trung Hoa cổ đại. | Gương Hán-Việt | hải trong 醢刑 (hải hình — hình phạt băm xác); 肉醢 (nhục hải — thịt muối ướp) | Mở khoá kiến thức | Biết 醢 giúp đọc hiểu sử liệu và văn học cổ Trung Hoa về hình phạt và ẩm thực cổ đại.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 醢 (hải) nghĩa gốc là thịt muối ướp hoặc thịt băm nhỏ — một dạng chế biến thực phẩm cổ đại của Trung Hoa. Sau mở rộng sang nghĩa là hình phạt man rợ: băm nát xác người (như trường hợp Bá Di trong Sử ký). Wiktionary dẫn câu trong tác phẩm của Hàn Dũ. Dạng tiểu triện và lục thư thông được ghi nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thịt ướp, thịt băm; hình phạt băm thịt phạm nhân", "Hạng Tần Suất (Jun Da)": "5312.0", "Tần Suất % (Jun Da)": "99.9478935884", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 𥁓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉𥁓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𥁓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醢", "Unihan_Traditional (Chữ Phồn thể)": "醢", "Pinyin_Xie": "hǎi", "Âm Hán Việt_Xie": "hải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ món mắm thịt hoặc làm động từ chỉ hình phạt băm xác thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('呲', '{"9000": "5313.0", "Chữ Trung Quốc": "呲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 口 | khẩu | biểu nghĩa | miệng, lời nói | 此 | thử | biểu âm | 呲 = 口 (Khẩu, biểu nghĩa: miệng) + 此 (Thử, biểu âm); chữ hình thanh. Bộ Khẩu cho biết liên quan đến miệng/âm thanh, 此 cho âm cī. Nghĩa: nhe răng, mắng chửi, vật rách toạc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thư\": cái miệng (口) hé ra chỗ này (此) — nhe răng cười hoặc mắng chửi thẳng mặt. | Gương Hán-Việt | thư trong 呲牙 (thư nha — nhe răng) | Mở khoá kiến thức | Biết 呲 giúp đọc hiểu từ khẩu ngữ 呲牙咧嘴 (nhe răng giả cười) và 呲了一顿 (bị mắng một trận).", "Tự nguyên_Xie": "呲 là chữ hình thanh: 口 (khẩu) là phần biểu nghĩa liên quan đến miệng, 此 là phần biểu âm cho âm cī. Nghĩa đa dạng: mắng mỏ, nhe răng cười, vật rách/đứt, bắn phun ra. Wiktionary xác nhận cấu trúc hình thanh này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mắng mỏ; nhe răng cười; rách, vỡ, đứt; phun ra, bắn ra", "Hạng Tần Suất (Jun Da)": "5313.0", "Tần Suất % (Jun Da)": "99.9479597369", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 此", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口此", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "此", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呲", "Unihan_Traditional (Chữ Phồn thể)": "呲", "Pinyin_Xie": "cī", "Âm Hán Việt_Xie": "thử", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ để miêu tả động tác nhe răng hoặc hành động quở trách ai đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('崾', '{"9000": "5314.0", "Chữ Trung Quốc": "崾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 12 | nét | 崾 | yểu | tượng hình | địa danh (eo núi, yên ngựa) | 崾 không có dữ liệu cấu trúc thành phần và không có dữ liệu nguồn gốc chữ viết. Chữ dùng trong địa danh 崾崄 (yểu hiểm) chỉ đèo núi hiểm trở. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yểu\": đèo yểu (崾) — eo núi hẹp hiểm trở ở vùng Thiểm Tây, nơi gió lùa và đường quanh co. | Gương Hán-Việt | yểu trong địa danh 崾崄 (yểu hiểm — đèo núi hiểm) | Mở khoá kiến thức | Biết 崾 giúp đọc hiểu địa danh tỉnh Thiểm Tây và văn bản địa lý Trung Hoa.", "Tự nguyên_Xie": "崾 là chữ dùng trong địa danh 崾崄 (yểu hiểm) hoặc tên xã ở tỉnh Thiểm Tây, Trung Quốc — chỉ đèo/eo núi hiểm trở. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật đầy đủ về cấu tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "徾", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "崾", "Unihan_Traditional (Chữ Phồn thể)": "崾", "Pinyin_Xie": "yǎo", "Âm Hán Việt_Xie": "yểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ địa hình yên ngựa hoặc lối đi nhỏ giữa hai quả đồi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('溆', '{"9000": "5315.0", "Chữ Trung Quốc": "溆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 溆 | tự | tượng hình | sông Tự; bến sông | 溆 không có dữ liệu cấu trúc thành phần rõ ràng. Chữ chỉ tên sông Tự (溆水) ở Hồ Nam, Trung Quốc, và bến sông. Địa danh liên quan đến huyện Tự Phủ (溆浦). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tự\": sông Tự (溆) chảy qua đất Hồ Nam — bến nước bình yên ghi dấu địa danh 溆浦 trong thơ văn Trung Hoa. | Gương Hán-Việt | tự trong 溆浦 (Tự Phủ — huyện ở Hồ Nam) | Mở khoá kiến thức | Biết 溆 giúp đọc hiểu địa danh 溆浦 và sử liệu vùng Hồ Nam.", "Tự nguyên_Xie": "溆 là tên sông Tự (溆水) ở tỉnh Hồ Nam, Trung Quốc. Cũng mang nghĩa bến sông. Địa danh quan trọng nhất là huyện Tự Phủ (溆浦县) — vùng đất văn hóa nổi tiếng. Wiktionary ghi nhận chữ này là địa danh. Chưa có nguồn học thuật đầy đủ về cấu tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Tự; bến sông", "Hạng Tần Suất (Jun Da)": "5315.0", "Tần Suất % (Jun Da)": "99.9480920339", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 叙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵叙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "溆", "Unihan_Traditional (Chữ Phồn thể)": "漵", "Pinyin_Xie": "xù", "Âm Hán Việt_Xie": "tự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong địa danh hoặc chỉ bến nước, bờ sông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('潴', '{"9000": "5316.0", "Chữ Trung Quốc": "潴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 14 | nét | 水 | thủy | biểu nghĩa | nước | 豬 | trư | biểu âm | 潴 = 水/氵 (Thủy, biểu nghĩa: nước) + 豬 (Trư, biểu âm); chữ hình thanh. Bộ Thủy cho biết liên quan đến nước, 豬 cho âm zhū. Nghĩa: nơi nước đọng lại, vũng nước.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trư\": nước (水) đọng lại như âm trư (豬) — vũng nước tù đọng, chứa nước mưa không thoát đi được. | Gương Hán-Việt | trư trong 潴留 (trư lưu — ứ đọng), 潴水 (trư thủy — nơi nước đọng) | Mở khoá kiến thức | Biết 潴 giúp đọc hiểu thuật ngữ y học 尿潴留 (niệu trư lưu — bí tiểu) và địa lý 水潴.", "Tự nguyên_Xie": "Tiểu triện | 潴 là chữ hình thanh: 水/氵 (thủy) là phần biểu nghĩa chỉ nước, 豬 là phần biểu âm cho âm zhū. Nghĩa gốc: chỗ nước đọng lại, tụ lại — ao hồ tự nhiên hoặc vùng trũng chứa nước. Wiktionary xác nhận cấu trúc hình thanh này. Dạng tiểu triện được ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chứa; đọng lại (nước)", "Hạng Tần Suất (Jun Da)": "5316.0", "Tần Suất % (Jun Da)": "99.9481581824", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 猪", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵猪", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "猪", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "潴", "Unihan_Traditional (Chữ Phồn thể)": "瀦", "Pinyin_Xie": "zhū", "Âm Hán Việt_Xie": "trư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Làm động từ chỉ việc nước tích tụ lại hoặc làm danh từ chỉ vũng nước đọng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('牖', '{"9000": "5317.0", "Chữ Trung Quốc": "牖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 片 | Số nét | 15 | nét | 牖 | dũ | tượng hình | cửa sổ | 牖 không có dữ liệu cấu trúc thành phần và không có dữ liệu nguồn gốc chữ viết từ Wiktionary. Chữ chỉ cửa sổ — đặc biệt là cửa sổ trên tường (khác với 窗 là cửa sổ mái). Dạng tiểu triện và lục thư thông được ghi nhận. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dũ\": cửa sổ dũ (牖) — ô vuông trên tường phòng, ánh sáng lọt qua dạy người ta thêm hiểu biết như 牖民 (khai sáng dân chúng). | Gương Hán-Việt | dũ trong 牖民 (dũ dân — khai sáng dân chúng); 户牖 (hộ dũ — cửa và cửa sổ) | Mở khoá kiến thức | Biết 牖 giúp đọc hiểu văn học và kiến trúc cổ: 户牖 (cửa và cửa sổ), 牖民 (khai sáng).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 牖 (dũ) chỉ cửa sổ trong kiến trúc cổ — cửa sổ khoét trên tường, đặc biệt là cửa sổ phía nam của phòng. Dùng trong thành ngữ 朽木不可雕，粪土之墙不可圬 — không thể khắc gỗ mục. Thành ngữ 启牖 (khai mở cánh cửa sổ) ví việc mở mang trí tuệ. Dạng tiểu triện và lục thư thông được ghi nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1486.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phiến (114) Hộ (063) Phủ (204)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm bộ Phiến (số 114 - tấm ván/ 爿), bộ Hộ (số 063 - cánh cửa/ 戶) và chữ Phủ (số 204 - rộng lớn/ 甫 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Chữ Phủ chỉ âm, bộ Phiến và Hộ chỉ ý. Dũ là cái cửa sổ để trổ ra đón ánh sáng vào nhà.", "Nghĩa Tiếng Việt_Xie": "cửa sổ", "Hạng Tần Suất (Jun Da)": "5317.0", "Tần Suất % (Jun Da)": "99.9482243309", "GavinGrover_Once (Chiết tự trực tiếp)": "片 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰片", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "牖", "Unihan_Traditional (Chữ Phồn thể)": "牖", "Pinyin_Xie": "yǒu", "Âm Hán Việt_Xie": "dũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ cửa sổ trong văn ngôn hoặc động từ với nghĩa khai sáng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硪', '{"9000": "5318.0", "Chữ Trung Quốc": "硪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 12 | nét | 硪 | ngoa | tượng hình | cái đầm nện đất, cối đá | 硪 không có dữ liệu cấu trúc thành phần rõ ràng. Chữ chỉ dụng cụ đầm nện đất — loại đầm đá tròn nặng dùng trong xây dựng. Chủ yếu dùng trong 砐硪 (ngoa ngoa — địa hình cao hiểm). Dạng giáp cốt văn và tiểu triện được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngoa\": cái đầm ngoa (硪) — đá nặng buộc dây, nện xuống đất thình thịch để làm chặt nền móng. | Gương Hán-Việt | ngoa trong 石硪 (thạch ngoa — đầm đá), 砐硪 (ngoa ngoa — cao ngất) | Mở khoá kiến thức | Biết 硪 giúp đọc hiểu từ xây dựng cổ truyền 石硪 (đầm đá) và từ mô tả địa hình 砐硪.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | 硪 chỉ cái đầm đất (stone rammer) dùng trong xây dựng — một loại đá nặng buộc dây, nâng lên thả xuống để nện chặt nền đất. Cũng dùng trong 砐硪 chỉ địa hình cao ngất hiểm trở. Dạng giáp cốt văn và tiểu triện được ghi nhận. Chưa có nguồn học thuật đầy đủ về cấu tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái đầm, cái nện", "Hạng Tần Suất (Jun Da)": "5318.0", "Tần Suất % (Jun Da)": "99.9482904794", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 我", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石我", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "我", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硪", "Unihan_Traditional (Chữ Phồn thể)": "硪", "Pinyin_Xie": "wò", "Âm Hán Việt_Xie": "ngã, ngạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ dụng cụ nặng bằng đá hoặc sắt dùng để nện đất cho chặt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碓', '{"9000": "5319.0", "Chữ Trung Quốc": "碓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 13 | nét | 碓 | đối | tượng hình | cối chày giã gạo | 碓 không có dữ liệu cấu trúc thành phần và không có dữ liệu nguồn gốc chữ viết. Chữ chỉ cái cối giã gạo — dụng cụ nông nghiệp truyền thống gồm một chày đá buộc trên đòn bẩy, đạp xuống giã gạo. Dạng tiểu triện được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đối\": cái cối đối (碓) giã gạo — âm thình thịch của nhịp chày cối đá trong làng quê Á Đông từ ngàn xưa. | Gương Hán-Việt | đối trong 碓房 (đối phòng — nhà cối xay), 水碓 (thủy đối — cối nước) | Mở khoá kiến thức | Biết 碓 giúp đọc hiểu từ nông nghiệp cổ truyền: 水碓 (cối dùng sức nước), 碓房 (nhà cối).", "Tự nguyên_Xie": "Tiểu triện | 碓 (đối) chỉ cối giã gạo — dụng cụ nông nghiệp cổ truyền: một tảng đá nặng gắn trên đòn bẩy, người đạp một đầu, đầu kia nâng lên rồi giã xuống cối đựng thóc. Dạng tiểu triện được ghi nhận. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái cối giã gạo", "Hạng Tần Suất (Jun Da)": "5319.0", "Tần Suất % (Jun Da)": "99.9483566279", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碓", "Unihan_Traditional (Chữ Phồn thể)": "碓", "Pinyin_Xie": "duì", "Âm Hán Việt_Xie": "đối", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ dụng cụ giã gạo hoặc giã thuốc bằng sức chân hoặc sức nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹆', '{"9000": "5320.0", "Chữ Trung Quốc": "鹆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 12 | nét | 鹆 | dục | tượng hình | chim cù dục (nhồng) | 鹆 không có dữ liệu cấu trúc thành phần rõ ràng. Chữ dùng trong 鸲鹆 (cù dục) chỉ chim nhồng (myna) — loài chim biết bắt chước giọng người. Dạng tiểu triện được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dục\": chim dục (鹆) trong cù dục (鸲鹆) — chim nhồng đen bóng biết học nói, tiếng kêu lanh lảnh như lời mời gọi. | Gương Hán-Việt | dục trong 鸲鹆 (cù dục — chim nhồng, myna) | Mở khoá kiến thức | Biết 鹆 mở khoá tên chim 鸲鹆 — chim nhồng biết nói, quen thuộc trong thư phòng học giả Trung Hoa xưa.", "Tự nguyên_Xie": "Tiểu triện | 鹆 dùng trong tổ hợp 鸲鹆 (cù dục) hoặc 鴝鵒 chỉ chim nhồng (myna) — loài chim lông đen bóng, có đốm trắng trên cánh, nổi tiếng biết bắt chước giọng nói. Dạng tiểu triện được ghi nhận. Chưa có nguồn học thuật đầy đủ về cấu tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: cù dục 鴝鵒,鸜鵒,鸲鹆)", "Hạng Tần Suất (Jun Da)": "5320.0", "Tần Suất % (Jun Da)": "99.9484227764", "GavinGrover_Once (Chiết tự trực tiếp)": "谷 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰谷鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鸟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "谷", "Unihan_Simplified (Chữ Giản thể)": "鹆", "Unihan_Traditional (Chữ Phồn thể)": "鵒", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "dục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Hầu như chỉ dùng làm danh từ trong từ ghép cù dục để chỉ loài chim sáo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬣', '{"9000": "5321.0", "Chữ Trung Quốc": "鬣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 25 | nét | 鬣 | liệp | tượng hình | bờm, râu, lông cứng | 鬣 không có dữ liệu cấu trúc thành phần rõ ràng. Chữ chỉ bờm cổ thú (mane), râu hoặc lông cứng, gai của cá. Dùng trong 鬣狗 (鬣 cẩu — linh cẩu/hyena) và 鬣蜥 (thằn lằn có mào). Dạng tiểu triện được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liệp\": bờm liệp (鬣) — dải lông cứng trên cổ sư tử hay ngựa, gai nhọn vươn lên đầy uy lực và hoang dã. | Gương Hán-Việt | liệp trong 鬣狗 (liệp cẩu — linh cẩu), 马鬣 (mã liệp — bờm ngựa) | Mở khoá kiến thức | Biết 鬣 mở khoá từ động vật học 鬣狗 (hyena) và 鬣蜥 (iguana có mào).", "Tự nguyên_Xie": "Tiểu triện | 鬣 (liệp) chỉ bờm của thú (mane), râu cứng, gai cá hoặc lá thông. Wiktionary liệt kê: beard, mane, whiskers, bristles, tuft, fins, needles. Dùng trong 鬣狗 (linh cẩu/hyena) và 鬣蜥 (thằn lằn có mào gai). Dạng tiểu triện được ghi nhận. Chưa có nguồn học thuật đầy đủ về cấu tạo chữ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "râu; bờm cổ thú", "Hạng Tần Suất (Jun Da)": "5321.0", "Tần Suất % (Jun Da)": "99.9484889249", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 巤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟巤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "鬣", "Unihan_Traditional (Chữ Phồn thể)": "鬣", "Pinyin_Xie": "liè", "Âm Hán Việt_Xie": "liệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ phần lông dài trên cổ ngựa, sư tử hoặc râu tóc dài. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('堀', '{"9000": "5322.0", "Chữ Trung Quốc": "堀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 11 | nét | 土 | thổ | biểu nghĩa | đất | 屈 | khuất | biểu âm | 堀 = 土 (Thổ, biểu nghĩa: đất) + 屈 (Khuất, biểu âm); chữ hình thanh. Bộ Thổ cho biết liên quan đến đất, 屈 cho âm kū. Nghĩa: đào hố trong đất, hố/hang. Wiktionary ghi: truyền đạt nghĩa đào hố trong đất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quật\": đất (土) bị khuất xuống (屈) — đào quật (堀) thành hố sâu, cái hang trong lòng đất. | Gương Hán-Việt | quật trong 堀割 (quật cát — kênh đào), 地堀 (địa quật — hào đất) | Mở khoá kiến thức | Biết 堀 giúp đọc hiểu địa danh và thuật ngữ Nhật-Hán về đào hố và kênh mương.", "Tự nguyên_Xie": "Tiểu triện | 堀 là chữ hình thanh: 土 (thổ) là phần biểu nghĩa chỉ đất, 屈 là phần biểu âm cho âm kū. Wiktionary xác nhận: ''conveys the meaning of digging a hole in the ground'' (Digital Shinjigen 2017). Nghĩa: đào hố, hố đất. Dạng tiểu triện được ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cao ngất", "Hạng Tần Suất (Jun Da)": "5322.0", "Tần Suất % (Jun Da)": "99.9485550734", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 屈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土屈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "堀", "Unihan_Traditional (Chữ Phồn thể)": "堀", "Pinyin_Xie": "kū", "Âm Hán Việt_Xie": "quật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ hang động, nơi trú ẩn hoặc tính từ chỉ trạng thái nổi bật lên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('帙', '{"9000": "5323.0", "Chữ Trung Quốc": "帙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 8 | nét | 巾 | can | biểu nghĩa | vải, khăn | 失 | thất | biểu âm | 帙 = 巾 (Can, biểu nghĩa: vải/khăn) + 失 (Thất, biểu âm); chữ hình thanh. Bộ Cân (巾) cho biết làm từ vải, 失 cho âm zhì. Nghĩa: bao vải bọc sách, tập sách.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trật\": vải can (巾) bọc mất đi (失) sự rách nát — cái bao trật bọc sách, giữ trang sách lâu bền. | Gương Hán-Việt | trật trong 书帙 (thư trật — bao sách), 帙数 (trật số — số tập sách) | Mở khoá kiến thức | Biết 帙 giúp đọc hiểu từ thư tịch học 书帙 (bao sách) và đơn vị đo sách trong thư mục cổ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 帙 là chữ hình thanh: 巾 (can) là phần biểu nghĩa chỉ vải/khăn, 失 là phần biểu âm cho âm zhì. Nghĩa gốc: bao vải để bọc sách (book wrapper) — dụng cụ bảo quản sách thời cổ đại. Mở rộng sang nghĩa đơn vị đo: một 帙 = mười quyển sách. Dạng tiểu triện và lục thư thông được ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bao sách", "Hạng Tần Suất (Jun Da)": "5323.0", "Tần Suất % (Jun Da)": "99.9486212219", "GavinGrover_Once (Chiết tự trực tiếp)": "巾 + 失", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巾失", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "失", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "帙", "Unihan_Traditional (Chữ Phồn thể)": "帙", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "trật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Dùng làm danh từ chỉ túi vải bọc sách hoặc làm lượng từ cho sách vở, tranh cuộn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雱', '{"9000": "5324.0", "Chữ Trung Quốc": "雱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 12 | nét | 雱 | phanh | tượng hình | mưa rơi dày hạt | 雱 không có dữ liệu cấu trúc thành phần rõ ràng. Chữ mô tả cảnh mưa rơi nặng hạt, dày đặc. Dùng trong thơ văn cổ, đặc biệt trong Kinh Thi. Dạng tiểu triện được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phanh\": tuyết phanh phanh (雱雱) — cảnh mưa tuyết đổ xuống trắng xóa trời đất trong thơ Kinh Thi cổ. | Gương Hán-Việt | phanh trong 雨雪雱雱 (câu thơ Kinh Thi — tuyết rơi dày) | Mở khoá kiến thức | Biết 雱 giúp đọc hiểu thơ Kinh Thi và văn học cổ mô tả thiên nhiên tuyết rơi.", "Tự nguyên_Xie": "Tiểu triện | 雱 (phanh) chỉ mưa rơi dày hạt, nặng — cảnh mưa tuyết đổ xuống trắng xóa. Xuất hiện trong Kinh Thi (雨雪雱雱 — tuyết rơi dày đặc). Dạng tiểu triện được ghi nhận. Chưa có nguồn học thuật đầy đủ về cấu tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mưa rơi nặng hạt", "Hạng Tần Suất (Jun Da)": "5324.0", "Tần Suất % (Jun Da)": "99.9486873704", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 方", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨方", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "方", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "雱", "Unihan_Traditional (Chữ Phồn thể)": "雱", "Pinyin_Xie": "pāng", "Âm Hán Việt_Xie": "bàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Dùng làm tính từ miêu tả trạng thái mưa tuyết rơi dày đặc, nặng hạt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诎', '{"9000": "5325.0", "Chữ Trung Quốc": "诎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 7 | nét | 诎 | khuất | tượng hình | uốn lượn, ngắt nghỉ (lời nói) | 诎 là dạng giản thể của 詘. Wiktionary ghi: giản hoá từ 詘 (f=言, t=讠). Bộ 讠là dạng giản thể của 言, kết hợp với phần còn lại tạo thành chữ chỉ lời nói ngắt quãng, uốn lượn. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuất\": lời nói (讠) bị khuất khúc, uốn lượn — người bị khuất (诎) không nói thẳng được, phải ngắt ngứ. | Gương Hán-Việt | khuất trong 诎伸 (khuất thân — khuất phục và vươn lên) | Mở khoá kiến thức | Biết 诎 giúp đọc hiểu văn bản cổ về lời nói ngắt quãng và trạng thái khuất phục.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 诎 là dạng giản thể của 詘 — giản hoá bộ 言 thành 讠. Chữ 詘 nguyên nghĩa là lời nói ngắt quãng, uốn lượn; sau mở rộng sang nghĩa cúi mình, khuất phục. Cũng dùng mọi lúc/mọi thời (trong một số từ điển). Dạng tiểu triện và lục thư thông được ghi nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mọi lúc", "Hạng Tần Suất (Jun Da)": "5325.0", "Tần Suất % (Jun Da)": "99.9488852991", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 出", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠出", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "出", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诎", "Unihan_Traditional (Chữ Phồn thể)": "詘", "Pinyin_Xie": "qū", "Âm Hán Việt_Xie": "truất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ biểu thị sự nhượng bộ, chịu thua hoặc làm tính từ miêu tả trạng thái bị khuất phục, hạn chế. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('獐', '{"9000": "5326.0", "Chữ Trung Quốc": "獐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 14 | nét | 獐 | chương | tượng hình | con hươu nước (water deer) | 獐 không có dữ liệu cấu trúc thành phần rõ ràng. Chữ chỉ loài hươu nước (water deer, Hydropotes inermis) — loài nai nhỏ không có sừng nhưng con đực có hai nanh dài. Dùng trong thành ngữ 獐头鼠目 (đầu hươu mắt chuột). Dạng tiểu triện được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chương\": con chương (獐) — hươu nước có nanh dài, trong thành ngữ 獐头鼠目 ví kẻ có tướng mạo gian xảo, nhỏ nhen. | Gương Hán-Việt | chương trong 獐子 (chương tử — con hươu nước), 獐头鼠目 | Mở khoá kiến thức | Biết 獐 mở khoá thành ngữ 獐头鼠目 — chỉ người có diện mạo gian xảo.", "Tự nguyên_Xie": "Tiểu triện | 獐 chỉ hươu nước (water deer) — loài thú nhỏ đặc hữu của Trung Quốc và Hàn Quốc, không có sừng nhưng con đực có hai nanh nhô ra. Nổi tiếng qua thành ngữ 獐头鼠目 — đầu hươu mắt chuột, chỉ người xấu xí tướng mạo gian trá. Dạng tiểu triện được ghi nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trứng cá", "Hạng Tần Suất (Jun Da)": "5326.0", "Tần Suất % (Jun Da)": "99.9489509308", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 章", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭章", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "章", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "獐", "Unihan_Traditional (Chữ Phồn thể)": "獐", "Pinyin_Xie": "zhāng", "Âm Hán Việt_Xie": "chương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ con vật, đóng vai trò làm chủ ngữ hoặc tân ngữ trong câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桁', '{"9000": "5327.0", "Chữ Trung Quốc": "桁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 行 | hàng | biểu âm | 桁 = 木 (Mộc, biểu nghĩa: gỗ/cây) + 行 (Hàng, biểu âm); chữ hình thanh. Bộ Mộc cho biết làm từ gỗ, 行 cho âm háng/héng. Nghĩa: dầm gỗ ngang hoặc cùm to bằng gỗ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hành\": gỗ mộc (木) xếp hàng (行) ngang — dầm hành nằm ngang đỡ mái nhà, hoặc cái cùm to gông cổ tội nhân. | Gương Hán-Việt | hành trong 桁架 (hành giá — khung giàn), 桁条 (hành điều — xà ngang) | Mở khoá kiến thức | Biết 桁 giúp đọc hiểu thuật ngữ kiến trúc 桁架 (truss/giàn đỡ) và 桁条 (xà ngang).", "Tự nguyên_Xie": "桁 là chữ hình thanh: 木 (mộc) là phần biểu nghĩa chỉ gỗ, 行 là phần biểu âm cho âm háng/héng. Nghĩa gốc: dầm gỗ ngang (purlin) trong kiến trúc nhà cổ. Cũng chỉ cái cùm to bằng gỗ dùng làm hình cụ. Wiktionary xác nhận cấu trúc hình thanh này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái dầm gỗ; cái cùm to", "Hạng Tần Suất (Jun Da)": "5327.0", "Tần Suất % (Jun Da)": "99.9490165625", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 行", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木行", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "行", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桁", "Unihan_Traditional (Chữ Phồn thể)": "桁", "Pinyin_Xie": "héng", "Âm Hán Việt_Xie": "hằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ cấu kiện kiến trúc hoặc công cụ hình phạt thời xưa, đứng sau định ngữ hoặc làm tân ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛱', '{"9000": "5328.0", "Chữ Trung Quốc": "蛱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 蛱 | giáp | tượng hình | bướm đốm (trong 蛱蝶) | 蛱 không có dữ liệu cấu trúc thành phần rõ ràng. Chữ dùng trong 蛱蝶 (giáp điệp) chỉ loài bướm đốm họ Nymphalidae — bướm có cánh rực rỡ sặc sỡ. Dạng tiểu triện được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giáp\": bướm giáp (蛱蝶) — cánh lốm đốm như giáp trụ chiến binh, bay nhẹ nhàng giữa hoa như trong thơ Đỗ Phủ. | Gương Hán-Việt | giáp trong 蛱蝶 (giáp điệp — bướm họ Nymphalidae) | Mở khoá kiến thức | Biết 蛱 mở khoá từ thơ Đường 穿花蛱蝶 — hình ảnh bướm bay qua hoa trong thơ Đỗ Phủ.", "Tự nguyên_Xie": "Tiểu triện | 蛱 dùng trong tổ hợp 蛱蝶 (giáp điệp) chỉ bướm họ Nymphalidae — nhóm bướm lớn nhất, cánh đẹp nhiều màu sắc. Nổi tiếng qua câu thơ của Đỗ Phủ: 穿花蛱蝶深深见 (bướm giáp xuyên hoa sâu thẳm hiện). Dạng tiểu triện được ghi nhận. Chưa có nguồn học thuật đầy đủ về cấu tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bướm đốm", "Hạng Tần Suất (Jun Da)": "5328.0", "Tần Suất % (Jun Da)": "99.9490821943", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 夹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫夹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛱", "Unihan_Traditional (Chữ Phồn thể)": "蛺", "Pinyin_Xie": "jiá", "Âm Hán Việt_Xie": "hiệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ khác để tạo thành danh từ chỉ loài bướm, đóng vai trò làm chủ ngữ hoặc tân ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳏', '{"9000": "5329.0", "Chữ Trung Quốc": "鳏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 18 | nét | 鳏 | quan | tượng hình | cá lớn; người goá vợ | 鳏 không có dữ liệu cấu trúc thành phần rõ ràng. Chữ có hai nghĩa: cá lớn (cổ ngữ) và người goá vợ (nghĩa phổ biến hơn). Trong văn học cổ, 鳏夫 chỉ người đàn ông không vợ (widower). Dạng kim văn, tiểu triện và lục thư thông được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quan\": người quan (鳏) — goá vợ sống một mình như con cá lớn cô đơn giữa dòng sông, trong tứ cùng dân 鳏寡孤独. | Gương Hán-Việt | quan trong 鳏夫 (quan phu — người goá vợ), 鳏寡孤独 | Mở khoá kiến thức | Biết 鳏 mở khoá tứ cùng dân 鳏寡孤独 — bốn loại người cần được xã hội quan tâm.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 鳏 (quan) có hai nhánh nghĩa: 1) Cá lớn — nghĩa gốc trong giáp cốt và kim văn; 2) Người goá vợ/không có vợ — mượn âm hoặc mở rộng nghĩa. Trong tứ cùng dân (鳏寡孤独 — quan quả cô độc) chỉ bốn loại người khổ nhất xã hội: goá chồng/vợ, mồ côi, đơn độc. Dạng kim văn, tiểu triện và lục thư thông được ghi nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá lớn; người goá vợ", "Hạng Tần Suất (Jun Da)": "5329.0", "Tần Suất % (Jun Da)": "99.949147826", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 眔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼眔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "眔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳏", "Unihan_Traditional (Chữ Phồn thể)": "鰥", "Pinyin_Xie": "guān", "Âm Hán Việt_Xie": "quan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ người đàn ông góa vợ hoặc làm tính từ trong các cụm từ miêu tả sự cô đơn, đơn độc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郴', '{"9000": "5330.0", "Chữ Trung Quốc": "郴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 10 | nét | 郴 | trần | tượng hình | tên địa danh, huyện Trần ở Hồ Nam | 郴 là chữ địa danh, bộ 邑 (ấp, địa danh) nằm bên phải. Cấu trúc cụ thể chưa có phân tích ls rõ ràng; chữ tạo theo lối hình thanh với bộ 邑 biểu nghĩa (địa danh/vùng đất).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Trần\": chữ gồm rừng cây (林) bên cạnh ấp làng (邑) — một vùng đất có rừng bao quanh làng xóm, gợi hình ảnh huyện Trần ở Hồ Nam xưa. | Gương Hán-Việt | Trần trong tên địa danh 郴州 (Trần Châu, thành phố ở Hồ Nam) | Mở khoá kiến thức | Biết 郴 mở khoá địa danh lịch sử 郴州 — vùng đất từng là trọng trấn miền Nam Trung Quốc thời cổ.", "Tự nguyên_Xie": "Tiểu triện | 郴 là tên một huyện cổ ở tỉnh Hồ Nam, Trung Quốc. Chữ gồm bộ 邑 (ấp, chỉ địa danh hành chính). Wiktionary chỉ ghi là địa danh (Chenzhou), không có phân tích cấu trúc học chi tiết. Chưa có nguồn học thuật về nghĩa gốc của thành phần 林 bên trái. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên một huyện Trung Quốc thời xưa)", "Hạng Tần Suất (Jun Da)": "5330.0", "Tần Suất % (Jun Da)": "99.9492134577", "GavinGrover_Once (Chiết tự trực tiếp)": "林 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰林阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "林", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郴", "Unihan_Traditional (Chữ Phồn thể)": "郴", "Pinyin_Xie": "chēn", "Âm Hán Việt_Xie": "sâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng chỉ địa danh, xuất hiện trong các tên gọi hành chính như Sâm Châu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('幂', '{"9000": "5331.0", "Chữ Trung Quốc": "幂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 冖 | Số nét | 12 | nét | 幂 | mịch | tượng hình | tấm vải phủ, màn che | 幂 là dạng giản thể / biến thể của 冪. Wiktionary ghi \"xem 冪\". Bộ 冖 (mịch, tấm vải phủ) ở trên gợi ý nghĩa che phủ. Cấu trúc ls chưa được phân tích đầy đủ trong nguồn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Mịch\": bộ 冖 (tấm vải phủ) trên đầu — hình ảnh tấm khăn che phủ mọi thứ bên dưới, như màn trải ngang không gian. | Gương Hán-Việt | Mịch trong thuật ngữ toán học 幂次 (mịch thứ) — số mũ, lũy thừa | Mở khoá kiến thức | Biết 幂 mở khoá thuật ngữ toán 幂次 (lũy thừa), 幂级数 (chuỗi lũy thừa) trong toán học Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | 幂 là biến thể giản của 冪 (mịch). Chữ 冪 gồm bộ 冖 (tấm vải phủ đồ) kết hợp với các thành phần phía dưới, chỉ tấm vải che phủ hay khăn trùm. Wiktionary chỉ ghi \"xem 冪\", không có phân tích cấu trúc riêng cho 幂. Chưa có nguồn học thuật độc lập cho dạng này. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái màn căng ở trên, cái bạt; cái khăn phủ đồ; cái mạng che mặt", "Hạng Tần Suất (Jun Da)": "5331.0", "Tần Suất % (Jun Da)": "99.9492790894", "GavinGrover_Once (Chiết tự trực tiếp)": "冖 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱冖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "幂", "Unihan_Traditional (Chữ Phồn thể)": "冪", "Pinyin_Xie": "mì", "Âm Hán Việt_Xie": "mịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ phép tính lũy thừa hoặc làm động từ với nghĩa che phủ, đậy lên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箝', '{"9000": "5332.0", "Chữ Trung Quốc": "箝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 拑 | kiềm | biểu âm | kẹp, giữ chặt | 箝 = 竹 (Trúc, biểu nghĩa: vật bằng tre) + 拑 (Kiềm, biểu âm). Chữ hình thanh: bộ 竹 cho biết dụng cụ làm từ tre hoặc hành động liên quan đến vật cứng; 拑 cho âm đọc. Gốc chỉ cái kìm tre, sau mở rộng sang nghĩa kìm kẹp, kiểm soát.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Kiềm\": tre (竹) dùng làm kìm kẹp — hình dụng cụ tre kẹp chặt, không thể thoát ra, giống kìm kiểm soát (箝制). | Gương Hán-Việt | Kiềm trong 箝制 (kiềm chế) — kìm hãm, kiểm soát | Mở khoá kiến thức | Biết 箝 mở khoá từ 箝制 (kiềm chế/kìm hãm), 箝口 (bịt miệng, cấm nói).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 箝 là chữ hình thanh: 竹 (trúc) biểu nghĩa chỉ loại dụng cụ tre hay vật cứng; 拑 biểu âm. Nghĩa gốc là cái kìm, cái cặp làm bằng tre hoặc kim loại. Sau phát triển sang nghĩa ẩn: kìm hãm, kiểm soát (箝制 — kềm chế). Chưa có nguồn giáp cốt hay kim văn riêng. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái kìm; giữ, kìm; cùm chân", "Hạng Tần Suất (Jun Da)": "5332.0", "Tần Suất % (Jun Da)": "99.9493447211", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 拑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮拑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "拑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箝", "Unihan_Traditional (Chữ Phồn thể)": "箝", "Pinyin_Xie": "qián", "Âm Hán Việt_Xie": "kiềm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ mang tân ngữ với nghĩa khống chế, khóa chặt hoặc làm danh từ chỉ dụng cụ kẹp giữ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('僳', '{"9000": "5333.0", "Chữ Trung Quốc": "僳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 14 | nét | 僳 | túc | tượng hình | tên dân tộc thiểu số 傈僳族 | 僳 là chữ dùng phiên âm tên dân tộc 傈僳 (Lật Túc). Bộ 亻 (nhân) gợi ý liên quan đến người/dân tộc. Cấu trúc chi tiết không có trong nguồn Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Túc\": bộ người (亻) kết hợp liên tưởng đến dân tộc người — 傈僳族 là tộc người Lisu sống trên núi cao vùng Vân Nam. | Gương Hán-Việt | Túc trong 傈僳族 (Lật Túc tộc) — tên dân tộc Lisu ở Vân Nam | Mở khoá kiến thức | Biết 僳 mở khoá tên dân tộc 傈僳族 — dân tộc Lisu, một trong 55 dân tộc thiểu số chính thức của Trung Quốc.", "Tự nguyên_Xie": "僳 chủ yếu xuất hiện trong tên dân tộc 傈僳族 (Lật Túc tộc — dân tộc Lisu), một dân tộc thiểu số sống ở vùng Vân Nam, Trung Quốc và Đông Nam Á. Chữ được tạo để phiên âm, không có phân tích cấu trúc học trong Wiktionary. Chưa có nguồn học thuật về etymology. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lật túc 傈僳)", "Hạng Tần Suất (Jun Da)": "5333.0", "Tần Suất % (Jun Da)": "99.9494103528", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "僳", "Unihan_Traditional (Chữ Phồn thể)": "僳", "Pinyin_Xie": "sù", "Âm Hán Việt_Xie": "túc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ khác để tạo thành danh từ riêng chỉ tộc người Lisu ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疝', '{"9000": "5334.0", "Chữ Trung Quốc": "疝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 8 | nét | 疒 | nạch | biểu nghĩa | bệnh, ốm đau | 山 | sơn | biểu âm | núi | 疝 = 疒 (Nạch, biểu nghĩa: bệnh tật) + 山 (Sơn, biểu âm). Chữ hình thanh điển hình: bộ 疒 đặt bên trái/trên chỉ loại bệnh; 山 cho âm (shàn ≈ sơn). Nghĩa chuyên biệt về bệnh thoát vị.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Sán\": bộ bệnh (疒) + núi (山) — như núi nhô ra khỏi bụng, hình ảnh khối thoát vị phồng lên như ngọn núi nhỏ. | Gương Hán-Việt | Sán trong 疝气 (sán khí) — bệnh thoát vị (hernia) | Mở khoá kiến thức | Biết 疝 mở khoá thuật ngữ y khoa 疝气 (thoát vị), dùng phổ biến trong văn bản y tế Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 疝 là chữ hình thanh: 疒 (nạch) biểu nghĩa chỉ bệnh tật; 山 (sơn) biểu âm — âm shàn gần với sơn. Nghĩa gốc và duy nhất là bệnh thoát vị (hernia), khi ruột hoặc mô bên trong bụng đẩy qua thành cơ thể. Từ thường gặp là 疝气 (疝氣). Chữ xuất hiện trong tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh sán, sa đì", "Hạng Tần Suất (Jun Da)": "5334.0", "Tần Suất % (Jun Da)": "99.9494759845", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 山", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒山", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "山", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "疝", "Unihan_Traditional (Chữ Phồn thể)": "疝", "Pinyin_Xie": "shàn", "Âm Hán Việt_Xie": "sán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một loại bệnh lý trong y học, đóng vai trò làm chủ ngữ hoặc tân ngữ trong câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茴', '{"9000": "5335.0", "Chữ Trung Quốc": "茴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 回 | hồi | biểu âm | quay lại | 茴 = 艹 (Thảo, biểu nghĩa: cỏ/thực vật) + 回 (Hồi, biểu âm). Chữ hình thanh: bộ 艹 chỉ đây là loài thực vật; 回 cho âm (huí ≈ hồi). Âm đọc tiếng Việt \"hồi\" của 回 chính là tên cây hồi trong tiếng Việt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Hồi\": cỏ (艹) + hồi (回) — cây hồi hương, loài thảo mộc thơm mang đúng tên Hán-Việt \"hồi\" quen thuộc trong ẩm thực Việt. | Gương Hán-Việt | Hồi trong 茴香 (hồi hương) — cây hồi, đại hồi; gia vị phổ biến | Mở khoá kiến thức | Biết 茴 mở khoá từ 茴香 (hồi hương/tiểu hồi), 八角茴香 (bát giác đại hồi) — các loại gia vị quen thuộc trong ẩm thực Á Đông.", "Tự nguyên_Xie": "Theo Wiktionary, 茴 là chữ hình thanh: 艸/艹 (cỏ, thảo) biểu nghĩa chỉ loài thực vật; 回 (hồi) biểu âm. Chữ chỉ cây hồi, tiểu hồi (茴香 — fennel, aniseed). Âm Hán-Việt \"hồi\" khớp trực tiếp với 回 biểu âm, tạo sự trùng hợp thú vị: tên cây hồi trong tiếng Việt chính là cách đọc Hán-Việt của thành phần biểu âm. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hồi hương 茴香)", "Hạng Tần Suất (Jun Da)": "5335.0", "Tần Suất % (Jun Da)": "99.9495410995", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 回", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹回", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "回", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茴", "Unihan_Traditional (Chữ Phồn thể)": "茴", "Pinyin_Xie": "huí", "Âm Hán Việt_Xie": "hồi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với các từ khác để tạo thành danh từ chỉ cây gia vị hoặc hương liệu nấu ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('揶', '{"9000": "5336.0", "Chữ Trung Quốc": "揶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 扌 | thủ | biểu nghĩa | tay | 耶 | gia | biểu âm | 揶 = 扌 (Thủ, biểu nghĩa: tay) + 耶 (Gia, biểu âm). Chữ hình thanh: bộ 扌 chỉ hành động của tay; 耶 cho âm (yé ≈ gia). Nghĩa chuyên dùng trong từ 揶揄 — cười nhạo, chế giễu bằng cử chỉ tay hay điệu bộ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Gia\": tay (扌) + gia (耶) — dùng tay chỉ trỏ, cười nhạo người khác (揶揄); hành động chế giễu bằng cử chỉ. | Gương Hán-Việt | Gia trong 揶揄 (gia du) — chế giễu, chọc ghẹo, nhạo báng | Mở khoá kiến thức | Biết 揶 mở khoá thành ngữ 揶揄 (gia du) — chế giễu, mỉa mai; từ văn chương dùng để chỉ thái độ nhạo báng.", "Tự nguyên_Xie": "Theo Wiktionary, 揶 là chữ hình thanh (hình thanh gốc là 耶): 手/扌 (tay) biểu nghĩa; 耶 biểu âm. Chữ chỉ xuất hiện trong từ ghép 揶揄 (gia du) — chế giễu, nhạo báng bằng cử chỉ hoặc lời nói. Không có ghi chép giáp cốt hay kim văn riêng cho chữ này. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cười nhạo", "Hạng Tần Suất (Jun Da)": "5336.0", "Tần Suất % (Jun Da)": "99.9496062144", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 耶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌耶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "揶", "Unihan_Traditional (Chữ Phồn thể)": "揶", "Pinyin_Xie": "yé", "Âm Hán Việt_Xie": "da", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường kết hợp với chữ du thành từ ghép gia du để làm động từ mang nghĩa chế giễu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('呦', '{"9000": "5337.0", "Chữ Trung Quốc": "呦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 呦 | ạo | tượng hình | tiếng kêu bất ngờ, tiếng hươu kêu | 呦 là chữ tượng thanh: bộ 口 (khẩu, miệng) biểu nghĩa chỉ âm thanh; phần còn lại cho âm. Chữ dùng ghi tiếng thán từ (ôi, ồ) hoặc tiếng hươu kêu (呦呦). Cấu trúc ls chưa được ghi nhận rõ trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Ạo\": miệng (口) thốt ra tiếng ngạc nhiên — 呦！ giống \"ồ!\" hay \"ôi!\" khi gặp điều bất ngờ; cũng là tiếng hươu gọi đàn (呦呦). | Gương Hán-Việt | Ạo trong 呦呦 (ạo ạo) — tiếng hươu kêu, âm thanh gọi đàn trong Kinh Thi | Mở khoá kiến thức | Biết 呦 mở khoá câu thơ nổi tiếng trong Kinh Thi: 呦呦鹿鸣 (hươu kêu tiếng hươu) — được Tào Tháo trích dẫn trong 短歌行.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 呦 là thán từ biểu đạt sự ngạc nhiên hay nhận ra đột ngột (giống \"ôi\", \"ồ\" trong tiếng Việt). Ví dụ: 呦！你怎么也来了？ (Ồ! Bạn cũng đến đây sao?). Chữ cũng ghi tiếng hươu kêu trong thơ cổ (呦呦 — tiếng hươu gọi nhau). Xuất hiện trong tiểu triện. Chưa có nguồn học thuật chuyên sâu về cấu trúc. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng hươu kêu", "Hạng Tần Suất (Jun Da)": "5337.0", "Tần Suất % (Jun Da)": "99.9496713293", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 幼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口幼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "幼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呦", "Unihan_Traditional (Chữ Phồn thể)": "呦", "Pinyin_Xie": "yōu", "Âm Hán Việt_Xie": "u", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Thán từ | 叹词 | Chữ này thường dùng làm từ mô phỏng tiếng hươu kêu hoặc thán từ biểu thị sự ngạc nhiên trong văn cổ. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗌', '{"9000": "5338.0", "Chữ Trung Quốc": "嗌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 口 | khẩu | biểu nghĩa | miệng | 益 | ích | biểu âm | lợi ích | 嗌 = 口 (Khẩu, biểu nghĩa: miệng/cổ họng) + 益 (Ích, biểu âm). Chữ hình thanh: bộ 口 chỉ liên quan đến miệng/cổ họng; 益 cho âm (ài ~ ích, có biến âm). Nghĩa gốc là cổ họng; nghĩa Quảng Đông hiện đại mở rộng sang la hét, gọi to.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Ách\": miệng (口) + ích (益) — cổ họng là cửa ngõ của miệng; 嗌 gợi hình ảnh cái cổ họng chặt như ách cản đường. | Gương Hán-Việt | Ách trong 嗌塞 (ách tắc) — nghẹn cổ, bít tắc cổ họng | Mở khoá kiến thức | Biết 嗌 mở khoá nghĩa cổ điển về cổ họng trong văn ngôn; đồng thời hiểu từ la hét (嗌) trong tiếng Quảng Đông.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 嗌 là chữ hình thanh: 口 biểu nghĩa (miệng, cổ họng); 益 biểu âm. Nghĩa cổ (văn ngôn): cổ họng; đường thông tin huyết mạch. Nghĩa tiếng Tần–Tấn xưa: nghẹn cổ. Tiếng Quảng Đông hiện đại: la hét, gọi to, gọi đồ ăn mang về (嗌外賣). Chữ có tiểu triện và Lục thư thông, chứng tỏ chữ khá xưa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cổ họng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 益", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口益", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "益", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗌", "Unihan_Traditional (Chữ Phồn thể)": "嗌", "Pinyin_Xie": "ài", "Âm Hán Việt_Xie": "ách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này chủ yếu làm danh từ chỉ cổ họng hoặc động từ chỉ sự nghẹn ngào trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('囹', '{"9000": "5339.0", "Chữ Trung Quốc": "囹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 囗 | Số nét | 8 | nét | 囗 | vi | biểu nghĩa | vây quanh, vòng bao | 令 | lệnh | biểu âm | lệnh | 囹 = 囗 (Vi, biểu nghĩa: vòng vây, bao quanh) + 令 (Lệnh, biểu âm). Chữ hình thanh: bộ 囗 chỉ không gian khép kín (nhà tù, cũi); 令 cho âm (líng ≈ lệnh). Chữ hầu như chỉ dùng trong 囹圄 (linh ngữ — nhà tù).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Linh\": vòng vây (囗) + lệnh (令) — nhà tù là nơi lệnh nhốt người vào vòng bao kín; 囹圄 = ngục tù, nơi giam giữ theo lệnh. | Gương Hán-Việt | Linh trong 囹圄 (linh ngữ) — nhà tù, lao ngục | Mở khoá kiến thức | Biết 囹 mở khoá thành ngữ 身陷囹圄 (thân hãm linh ngữ) — bị sa vào vòng lao ngục; thường gặp trong văn học và báo chí.", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary, 囹 là chữ hình thanh: 囗 biểu nghĩa chỉ không gian bao bọc, vây kín (nhà tù, chuồng cũi); 令 biểu âm. Chữ là dạng rút gọn của 囹圄, chỉ nhà lao. Có hình đại triện (bigseal), chứng tỏ chữ tương đối xưa. Trong tiếng Hán hiện đại, 囹 gần như chỉ xuất hiện trong thành ngữ 身陷囹圄 (bị tù giam). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: linh ngữ 囹圄)", "Hạng Tần Suất (Jun Da)": "5339.0", "Tần Suất % (Jun Da)": "99.9498015592", "GavinGrover_Once (Chiết tự trực tiếp)": "囗 + 令", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Bao quanh toàn bộ)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴囗令", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "囗", "Unihan_Simplified (Chữ Giản thể)": "囹", "Unihan_Traditional (Chữ Phồn thể)": "囹", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này hầu như chỉ xuất hiện trong từ ghép linh ngữ để làm danh từ chỉ chốn lao tù. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螈', '{"9000": "5340.0", "Chữ Trung Quốc": "螈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 螈 | nguyên | tượng hình | con kỳ nhông (sa giông) | 螈 chủ yếu xuất hiện trong 蠑螈/蝾螈 (vinh nguyên — con sa giông, kỳ nhông). Bộ 虫 (trùng) gợi ý đây là loài động vật/côn trùng nhỏ. Không có dữ liệu etymology trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Nguyên\": bộ trùng (虫) + nguyên — con sinh vật dáng dài như con sa giông (蝾螈); tên gọi Hán-Việt \"nguyên\" gợi hình ảnh sinh vật nguyên thủy, trơn láng. | Gương Hán-Việt | Nguyên trong 蝾螈 (vinh nguyên) — con sa giông, kỳ nhông (salamander) | Mở khoá kiến thức | Biết 螈 mở khoá từ 蝾螈/蠑螈 (sa giông, salamander) — loài lưỡng cư quen trong sách sinh học và văn học Trung Quốc.", "Tự nguyên_Xie": "螈 không có dữ liệu cấu trúc học trong Wiktionary. Chữ xuất hiện chủ yếu trong 蠑螈 (vinh nguyên) hoặc 蝾螈 — chỉ con sa giông (salamander), loài lưỡng cư có đuôi. Bộ 虫 chỉ loại động vật nhỏ/lưỡng cư. Chưa có nguồn học thuật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: vinh nguyên 蠑螈,蝾螈)", "Hạng Tần Suất (Jun Da)": "5340.0", "Tần Suất % (Jun Da)": "99.9498666741", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 原", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫原", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "原", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螈", "Unihan_Traditional (Chữ Phồn thể)": "螈", "Pinyin_Xie": "yuán", "Âm Hán Việt_Xie": "nguyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường đứng sau chữ vinh để tạo thành danh từ chỉ loài kỳ giông hoặc sa giông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脲', '{"9000": "5341.0", "Chữ Trung Quốc": "脲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | 脲 | niệu | tượng hình | urê (hợp chất chứa ni-tơ trong nước tiểu) | 脲 là chữ tạo muộn, dùng trong hóa học hiện đại để ghi từ ngoại lai \"urea\" (urê). Bộ ⺼/肉 (nhục, thịt/thể xác) gợi ý chất hữu cơ từ cơ thể; 尿 (niệu, nước tiểu) gợi âm và nguồn gốc. Chưa có nguồn học thuật về etymology.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Niệu\": bộ thịt/hữu cơ (⺼) + liên tưởng nước tiểu — urê (脲) là hợp chất ni-tơ thải ra trong nước tiểu, sản phẩm phân hủy protein của cơ thể. | Gương Hán-Việt | Niệu trong 脲酶 (niệu môi) — enzyme urease; 尿素 (niệu tố) — urê | Mở khoá kiến thức | Biết 脲 mở khoá thuật ngữ hóa-sinh: 脲酶 (urease), 脲基 (nhóm ureido) — thường gặp trong giáo trình hóa học Trung Quốc.", "Tự nguyên_Xie": "脲 là chữ Hán hiện đại tạo để phiên dịch thuật ngữ hóa học \"urea\" (urê). Không có dữ liệu Wiktionary hay giáp cốt/kim văn. Bộ 肉/⺼ chỉ chất hữu cơ từ cơ thể; âm niào liên quan đến 尿 (nước tiểu) vì urê là sản phẩm thải của trao đổi đạm trong nước tiểu. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "urê (hoá học)", "Hạng Tần Suất (Jun Da)": "5341.0", "Tần Suất % (Jun Da)": "99.949931789", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 尿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月尿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脲", "Unihan_Traditional (Chữ Phồn thể)": "脲", "Pinyin_Xie": "niào", "Âm Hán Việt_Xie": "niệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này được dùng làm danh từ trong thuật ngữ hóa học để chỉ hợp chất urê. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镊', '{"9000": "5342.0", "Chữ Trung Quốc": "镊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 金 | kim | biểu nghĩa | kim loại, vàng | 聶 | nhiếp | biểu âm | 镊 = 金 (Kim, biểu nghĩa: kim loại) + 聶 (Nhiếp, biểu âm). Chữ hình thanh: bộ 金 chỉ đây là dụng cụ kim loại; 聶 cho âm (niè ≈ nhiếp). Chữ phồn thể là 鑷, dùng chữ 金 đầy đủ hơn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Nhiếp\": kim loại (金) + nhiếp (聶) — cái nhíp là dụng cụ kim loại kẹp chặt (nhiếp = cầm/kẹp); dùng nhổ lông mày hay lấy dằm. | Gương Hán-Việt | Nhiếp trong 镊子 (nhiếp tử) — cái nhíp | Mở khoá kiến thức | Biết 镊 mở khoá từ 镊子 (cái nhíp), dụng cụ y tế và làm đẹp quen thuộc; cũng gặp trong văn bản y khoa.", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 镊 (phồn thể 鑷) là chữ hình thanh: 金 biểu nghĩa chỉ vật bằng kim loại; 聶 biểu âm. Nghĩa là cái nhíp, cái cặp kim loại dùng để kẹp nhổ lông, lấy vật nhỏ. Chỉ có dạng Lục thư thông, chứng tỏ chữ tạo tương đối muộn (Ming trở lại). Dụng cụ nhíp bằng kim loại đã được sử dụng từ thời Trung Hoa cổ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái nhíp; cái cặp tóc", "Hạng Tần Suất (Jun Da)": "5342.0", "Tần Suất % (Jun Da)": "99.9499963872", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 聂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅聂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "聂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镊", "Unihan_Traditional (Chữ Phồn thể)": "鑷", "Pinyin_Xie": "niè", "Âm Hán Việt_Xie": "nhiếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ cái nhíp hoặc làm động từ với nghĩa dùng nhíp để kẹp, nhổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锑', '{"9000": "5343.0", "Chữ Trung Quốc": "锑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 金 | kim | biểu nghĩa | kim loại, vàng | 弟 | đệ | biểu âm | em trai | 锑 = 金 (Kim, biểu nghĩa: kim loại) + 弟 (Đệ, biểu âm). Chữ hình thanh: bộ 金 chỉ nguyên tố kim loại; 弟 cho âm (tī ≈ đệ). Chữ tạo hiện đại để phiên dịch tên nguyên tố antimony (Sb).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Đề\": kim loại (金) + đệ (弟) — antimon là \"người em\" của kim loại nặng, giòn và ánh bạc; chữ 锑 tạo ra riêng để đặt tên nguyên tố này. | Gương Hán-Việt | Đề trong 锑矿 (đề khoáng) — quặng antimon; 三氧化二锑 — antimon trioxide | Mở khoá kiến thức | Biết 锑 mở khoá hóa học nguyên tố: 锑矿 (quặng Sb), 三氧化二锑 (Sb₂O₃ — chất chống cháy) — gặp trong giáo trình hóa vô cơ Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 锑 (phồn thể 銻) là chữ hình thanh: 金 biểu nghĩa (kim loại); 弟 biểu âm. Chữ tạo để ghi tên nguyên tố antimon (antimony, ký hiệu Sb, số nguyên tử 51). Antimon là kim loại màu trắng bạc, giòn. Có dạng tiểu triện nhưng thực chất là chữ tạo muộn để phiên âm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "antimon, nguyên tố stibi, Sb", "Hạng Tần Suất (Jun Da)": "5343.0", "Tần Suất % (Jun Da)": "99.9500609853", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 弟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅弟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锑", "Unihan_Traditional (Chữ Phồn thể)": "銻", "Pinyin_Xie": "tī", "Âm Hán Việt_Xie": "đễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nguyên tố hóa học antimon trong bảng tuần hoàn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胨', '{"9000": "5344.0", "Chữ Trung Quốc": "胨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 9 | nét | 胨 | đống | tượng hình | peptone — sản phẩm thủy phân protein | 胨 là chữ tạo hiện đại dùng trong sinh hóa để ghi từ ngoại lai \"peptone\". Bộ ⺼/肉 (nhục) gợi ý chất hữu cơ từ thịt/protein. Không có dữ liệu etymology trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Đống\": bộ thịt/protein (⺼) — peptone (胨) là protein bị phân giải một nửa, \"khúc giữa\" của quá trình tiêu hóa đạm, gợi hình ảnh khối đống thịt chưa phân hủy hoàn toàn. | Gương Hán-Việt | Đống trong 蛋白胨 (đản bạch đống) — peptone từ lòng trắng trứng | Mở khoá kiến thức | Biết 胨 mở khoá thuật ngữ vi sinh học: 蛋白胨 (peptone), thành phần chính của môi trường nuôi cấy vi khuẩn LB trong phòng thí nghiệm.", "Tự nguyên_Xie": "胨 là chữ tạo muộn dùng trong sinh hóa hiện đại để phiên dịch \"peptone\" (peptôn) — sản phẩm thủy phân một phần của protein, dùng làm môi trường nuôi cấy vi khuẩn. Bộ 肉/⺼ chỉ chất hữu cơ từ protein/thịt. Không có dữ liệu Wiktionary hay giáp cốt/kim văn. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "pepton (hoá học)", "Hạng Tần Suất (Jun Da)": "5344.0", "Tần Suất % (Jun Da)": "99.9501255834", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 东", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月东", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "东", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胨", "Unihan_Traditional (Chữ Phồn thể)": "腖", "Pinyin_Xie": "dòng", "Âm Hán Việt_Xie": "đống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ trong sinh hóa học để chỉ chất peptone. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膈', '{"9000": "5345.0", "Chữ Trung Quốc": "膈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 14 | nét | ⺼ | nhục | biểu nghĩa | thịt, cơ thể | 鬲 | cách | biểu âm | nồi ba chân | 膈 = ⺼ (Nhục, biểu nghĩa: cơ thể, mô mềm) + 鬲 (Cách, biểu âm). Chữ hình thanh: bộ ⺼ chỉ bộ phận cơ thể; 鬲 cho âm (gé ≈ cách). Cơ hoành là lớp cơ ngăn giữa khoang ngực và bụng, như tấm ngăn giữa hai khoang.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Cách\": thịt/cơ (⺼) + cách (鬲) — cơ hoành là lớp cơ \"ngăn cách\" (cách) ngực và bụng; 鬲 xưa là nồi có vách ngăn, nay âm đó chỉ cơ ngăn trong người. | Gương Hán-Việt | Cách trong 膈膜 (cách mạc) — cơ hoành; 横膈 (hoành cách) — cơ hoành ngang | Mở khoá kiến thức | Biết 膈 mở khoá thuật ngữ giải phẫu: 膈膜/横膈膜 (cơ hoành), 膈神经 (thần kinh hoành) — thường gặp trong giáo trình y khoa.", "Tự nguyên_Xie": "Theo Wiktionary, 膈 là chữ hình thanh: 肉/⺼ (nhục) biểu nghĩa chỉ cơ quan cơ thể; 鬲 biểu âm. Nghĩa là cơ hoành (diaphragm) — lớp cơ ngăn giữa ngực và bụng. Cũng có nghĩa thứ hai là một loại chuông. 膈膜 là thuật ngữ y học chỉ cơ hoành. Phát âm thứ hai gè trong 膈應 (khó chịu, ghét). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cơ hoành", "Hạng Tần Suất (Jun Da)": "5345.0", "Tần Suất % (Jun Da)": "99.9501901816", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 鬲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月鬲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鬲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膈", "Unihan_Traditional (Chữ Phồn thể)": "膈", "Pinyin_Xie": "gé", "Âm Hán Việt_Xie": "cách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cơ hoành ngăn cách giữa khoang ngực và khoang bụng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痼', '{"9000": "5346.0", "Chữ Trung Quốc": "痼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 13 | nét | 疒 | nạch | biểu nghĩa | bệnh tật | 固 | cố | biểu âm | chắc chắn, cứng | 痼 = 疒 (Nạch, biểu nghĩa: bệnh tật) + 固 (Cố, biểu âm). Chữ hình thanh: bộ 疒 chỉ đây là bệnh; 固 cho âm (gù ≈ cố) và gợi nghĩa — bệnh cứng đầu, không chữa được. Sự trùng lặp âm và nghĩa làm cho chữ rất dễ nhớ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Cố\": bệnh (疒) + cố (固) — bệnh cứng đầu (固 = cứng), không chữa khỏi; 痼疾 là \"bệnh cố hữu\" — căn bệnh bám rễ vào người như đinh đóng cột. | Gương Hán-Việt | Cố trong 痼疾 (cố tật) — bệnh kinh niên; 痼癖 (cố tích) — tật xấu bám rễ | Mở khoá kiến thức | Biết 痼 mở khoá thành ngữ 痼疾难医 (bệnh kinh niên khó chữa), hay từ 沉痼 (bệnh nặng lâu năm) — gặp trong văn học và báo chí.", "Tự nguyên_Xie": "Theo Wiktionary, 痼 là chữ hình thanh: 疒 biểu nghĩa (bệnh); 固 biểu âm (gù ≈ cố). Nghĩa là bệnh mãn tính, lâu năm, khó chữa — như 痼疾 (cố tật). Cũng chỉ thói quen ăn sâu lâu năm (痼習, 痼癖). Thành ngữ 沉痼 chỉ bệnh nặng kinh niên. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cố tật (bệnh chữa không khỏi)", "Hạng Tần Suất (Jun Da)": "5346.0", "Tần Suất % (Jun Da)": "99.9502547797", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 固", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒固", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "固", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痼", "Unihan_Traditional (Chữ Phồn thể)": "痼", "Pinyin_Xie": "gù", "Âm Hán Việt_Xie": "cố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm định ngữ bổ nghĩa cho danh từ để chỉ căn bệnh lâu năm khó chữa trị. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳊', '{"9000": "5347.0", "Chữ Trung Quốc": "鳊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 鳊 | biên | tượng hình | cá biên, cá mè (bream) | 鳊 là chữ ghi tên loài cá. Bộ 鱼 (ngư) biểu nghĩa chỉ loài cá. Dạng phồn thể là 鯿. Cấu trúc ls không ghi trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Biên\": bộ cá (鱼) + biên — cá biên (鳊鱼) là loài cá dẹp hình bầu dục, thân \"phẳng như tấm bia\", gợi hình ảnh dẹt bên sườn. | Gương Hán-Việt | Biên trong 鳊鱼 (biên ngư) — cá biên, cá mè trắng | Mở khoá kiến thức | Biết 鳊 mở khoá tên loài cá 鳊鱼 — cá biên/mè, loài cá nước ngọt phổ biến trong ẩm thực Trung Quốc.", "Tự nguyên_Xie": "鳊 (phồn thể 鯿) là tên loài cá mè/cá biên (bream), họ cá chép. Wiktionary không có phân tích cấu trúc học chi tiết; chỉ ghi phát âm và nghĩa. Có hình thái cổ (MC/OC), chứng tỏ chữ khá xưa. Chưa có nguồn học thuật về cấu trúc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá biên, cá mè", "Hạng Tần Suất (Jun Da)": "5347.0", "Tần Suất % (Jun Da)": "99.9503193779", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 扁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼扁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "扁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳊", "Unihan_Traditional (Chữ Phồn thể)": "鯿", "Pinyin_Xie": "biān", "Âm Hán Việt_Xie": "biên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài cá mè hoặc cá biên trong tiếng Trung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赅', '{"9000": "5348.0", "Chữ Trung Quốc": "赅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 10 | nét | 赅 | cai | tượng hình | đầy đủ, toàn vẹn, bao gồm | 赅 (phồn thể 賅) là chữ bộ 貝 (bối, của cải). Cấu trúc chi tiết không có trong Wiktionary ngoài ghi chú {{Han etym}}. Chữ hầu như chỉ dùng trong 言简意赅 (lời ít ý đủ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Cai\": bộ của cải (貝) — \"cai\" gợi đầy đủ, bao quát; 言简意赅 là văn phong lý tưởng: lời ít mà ý nghĩa đầy đủ, không thiếu sót. | Gương Hán-Việt | Cai trong 言简意赅 (ngôn giản ý cai) — nói ngắn gọn nhưng đủ ý | Mở khoá kiến thức | Biết 赅 mở khoá thành ngữ văn phong 言简意赅 — tiêu chuẩn vàng của văn viết: ngắn gọn mà bao quát đủ ý.", "Tự nguyên_Xie": "赅 (phồn thể 賅) là chữ có bộ 貝 (của cải) gợi nghĩa đầy đủ, sung túc. Wiktionary chỉ ghi {{Han etym}} không có phân tích cấu trúc chi tiết. Nghĩa hiện đại chủ yếu là \"đầy đủ, bao gồm tất cả\". Chữ gặp nhiều nhất trong thành ngữ 言简意赅 (ngôn giản ý cai — lời ngắn ý đủ). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đầy đủ, phong phú", "Hạng Tần Suất (Jun Da)": "5348.0", "Tần Suất % (Jun Da)": "99.950383976", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 亥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝亥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赅", "Unihan_Traditional (Chữ Phồn thể)": "賅", "Pinyin_Xie": "gāi", "Âm Hán Việt_Xie": "cai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ bổ nghĩa cho danh từ hoặc xuất hiện trong thành ngữ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贽', '{"9000": "5349.0", "Chữ Trung Quốc": "贽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 10 | nét | 執 | chấp | biểu âm | nắm giữ, chấp hành | 貝 | bối | biểu nghĩa | của cải, vật quý | 贽 = 執 (Chấp, biểu âm) + 貝 (Bối, biểu nghĩa: của cải quý giá). Chữ hình thanh: 貝 chỉ đây là vật có giá trị; 執 cho âm (zhì ~ chấp, có biến âm). Nghĩa là lễ vật mang đến khi lần đầu ra mắt người trên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Chất\": của cải (貝) + chấp (執) — lễ vật (贽) là vật quý \"nắm trong tay\" (執) mang đến dâng khi gặp mặt lần đầu; tương tự \"quà ra mắt\" trong văn hóa Việt. | Gương Hán-Việt | Chất trong 执贽 (chấp chất) — cầm lễ vật đến ra mắt; 贽见 (chất kiến) — dâng lễ gặp mặt | Mở khoá kiến thức | Biết 贽 mở khoá nghi lễ Nho giáo: 执贽 (cầm lễ vật), 贽见礼 (lễ ra mắt) — gặp trong sử sách và văn chương cổ điển.", "Tự nguyên_Xie": "Theo Wiktionary, 贽 (phồn thể 贄) là chữ hình thanh: 執 biểu âm; 貝 biểu nghĩa (của cải quý). Nghĩa là lễ vật dâng lên người trên trong lần đầu gặp mặt chính thức — tục lệ lễ nghi Trung Hoa xưa. Từ điển cổ như 贽见 (dâng lễ ra mắt), 执贽 (cầm lễ vật). Phong tục này phản ánh văn hóa lễ nghi Nho giáo. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ lễ khi gặp mặt, của làm tin", "Hạng Tần Suất (Jun Da)": "5349.0", "Tần Suất % (Jun Da)": "99.9504485741", "GavinGrover_Once (Chiết tự trực tiếp)": "执 + 贝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱执贝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "执", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "贽", "Unihan_Traditional (Chữ Phồn thể)": "贄", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "chí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trước động từ hoặc làm tân ngữ trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苤', '{"9000": "5350.0", "Chữ Trung Quốc": "苤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 丕 | phi | biểu âm | lớn, vĩ đại | 苤 = 艹 (Thảo, biểu nghĩa: cỏ/thực vật) + 丕 (Phi, biểu âm). Chữ hình thanh: bộ 艹 chỉ loài thực vật; 丕 cho âm (piě ≈ phi, có biến âm). Chữ hầu như chỉ dùng trong 苤蓝 — su hào (kohlrabi).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Phi\": cỏ (艹) + phi (丕) — su hào (苤蓝) là loại rau \"phi thường\" to phình như quả bóng, thân phình lên khỏi mặt đất như cái bình. | Gương Hán-Việt | Phi trong 苤蓝 (phi lam) — cây su hào, củ su hào | Mở khoá kiến thức | Biết 苤 mở khoá từ 苤蓝 (su hào) — loại rau củ phổ biến trong ẩm thực Trung Quốc và Việt Nam.", "Tự nguyên_Xie": "Theo Wiktionary, 苤 là chữ hình thanh: 艸/艹 biểu nghĩa (thực vật); 丕 biểu âm. Chữ gần như chỉ xuất hiện trong 苤蓝 (苤藍) — cây su hào (kohlrabi), loài rau họ cải thân phình to. Không có ghi chép giáp cốt hay kim văn riêng. Đây là chữ tạo tương đối muộn để ghi tên loài rau. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: phiết lam 苤藍,苤蓝)", "Hạng Tần Suất (Jun Da)": "5350.0", "Tần Suất % (Jun Da)": "99.9505772536", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 丕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹丕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苤", "Unihan_Traditional (Chữ Phồn thể)": "苤", "Pinyin_Xie": "piě", "Âm Hán Việt_Xie": "phiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong từ ghép để chỉ cây su hào. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('峄', '{"9000": "5351.0", "Chữ Trung Quốc": "峄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 8 | nét | 峄 | dịch | tượng hình | núi Dịch, địa danh ở Sơn Đông | 峄 là dạng giản thể của 嶧. Bộ 山 (sơn) biểu nghĩa chỉ ngọn núi. Cấu trúc chi tiết: {{Han simp|嶧|f=睪|t=𠬤}} — giản lược thành phần 睪 thành 𠬤. Chữ chỉ dùng làm địa danh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Dịch\": bộ núi (山) — núi Dịch (峄山) là nơi Tần Thủy Hoàng dựng bia đá ghi công, được Lý Tư viết chữ triện nổi tiếng. | Gương Hán-Việt | Dịch trong 峄山 (Dịch Sơn) — núi Dịch ở Sơn Đông; 峄山碑 — bia đá Dịch Sơn | Mở khoá kiến thức | Biết 峄 mở khoá 峄山碑 (Bia Dịch Sơn) — một trong những tác phẩm thư pháp triện thư nổi tiếng nhất, mẫu học chữ triện.", "Tự nguyên_Xie": "Tiểu triện | 峄 là dạng giản của 嶧, tên núi Dịch (峄山/嶧山) ở tỉnh Sơn Đông, Trung Quốc. Núi này nổi tiếng với Bia Dịch Sơn do Tần Thủy Hoàng dựng, được Lý Tư khắc chữ. Wiktionary ghi {{Han simp}} không có phân tích cấu trúc học sâu. Bộ 山 biểu nghĩa chỉ núi. Chưa có nguồn học thuật về cấu trúc nội tại. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "núi Dịch (ở tỉnh Sơn Đông của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "5351.0", "Tần Suất % (Jun Da)": "99.950641335", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "峄", "Unihan_Traditional (Chữ Phồn thể)": "嶧", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng chỉ địa danh cụ thể trong địa lý cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桡', '{"9000": "5352.0", "Chữ Trung Quốc": "桡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 桡 | nhiêu | tượng hình | mái chèo, gỗ cong; xương quay | 桡 là dạng giản thể của 橈. Bộ 木 (mộc) biểu nghĩa chỉ đồ vật bằng gỗ. {{Han simp|橈|f=堯|t=尧}} — giản lược 堯 thành 尧. Nghĩa: mái chèo, vật gỗ cong; trong y học là xương quay (radius).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Nhiêu\": bộ gỗ (木) + uốn cong — mái chèo là cây gỗ uốn cong trong nước; trong y học, 桡骨 (xương quay) là xương cong nơi cổ tay. | Gương Hán-Việt | Nhiêu trong 桡骨 (nhiêu cốt) — xương quay (radius); 桡动脉 — động mạch quay | Mở khoá kiến thức | Biết 桡 mở khoá thuật ngữ giải phẫu 桡骨 (xương quay), 桡动脉 (động mạch quay) — hay dùng khi bắt mạch cổ tay.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 桡 là dạng giản của 橈 (nhiêu). Wiktionary ghi {{Han simp}}, không có phân tích cấu trúc học độc lập. Phồn thể 橈 gồm 木 (mộc) + 堯 (nghiêu, biểu âm). Nghĩa: gỗ cong, mái chèo ngắn; trong giải phẫu học là xương quay (桡骨 — xương cẳng tay phía ngón cái). Có hình tiểu triện và Lục thư thông. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mái chèo; dầm", "Hạng Tần Suất (Jun Da)": "5352.0", "Tần Suất % (Jun Da)": "99.9507054164", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 尧", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木尧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桡", "Unihan_Traditional (Chữ Phồn thể)": "橈", "Pinyin_Xie": "ráo", "Âm Hán Việt_Xie": "nhiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ công cụ chèo thuyền hoặc bộ phận xương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雎', '{"9000": "5353.0", "Chữ Trung Quốc": "雎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 隹 | Số nét | 13 | nét | 且 | thả | biểu âm | hơn nữa, lại | 隹 | chuy | biểu nghĩa | loài chim đuôi ngắn | 雎 = 且 (Thả, biểu âm) + 隹 (Chuy, biểu nghĩa: loài chim). Chữ hình thanh: 隹 chỉ đây là loài chim; 且 cho âm (jū ≈ thả, biến âm). Nghĩa chuyên biệt: con chim thư cưu (chim osprey/diều hâu cá), xuất hiện trong câu mở đầu Kinh Thi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Thư\": chim (隹) + thả (且) — 雎鳩 (thư cưu) là đôi chim trong câu mở đầu Kinh Thi; tiếng chim gọi đôi gợi tình yêu lứa đôi hài hòa. | Gương Hán-Việt | Thư trong 雎鳩 (thư cưu) — chim osprey; 关关雎鸠 — câu mở đầu Kinh Thi | Mở khoá kiến thức | Biết 雎 mở khoá câu thơ kinh điển: 關關雎鳩，在河之洲 — câu mở đầu thiên Quan Thư trong Kinh Thi, biểu tượng tình yêu hài hòa trong văn học Trung Quốc.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 雎 là chữ hình thanh: 隹 biểu nghĩa (loài chim đuôi ngắn); 且 biểu âm. Nghĩa: con chim 雎鳩 (thư cưu) — chim osprey/diều hâu cá. Chữ nổi tiếng nhờ câu mở đầu Kinh Thi: 關關雎鳩，在河之洲 (Quan quan tiếng thư cưu, trên bãi giữa sông). Cũng dùng trong tên người (Phạm Thư — 范雎, thừa tướng nước Tần) và tên sông (雎水). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thư cưu 雎鳩,雎鸠)", "Hạng Tần Suất (Jun Da)": "5353.0", "Tần Suất % (Jun Da)": "99.9507694977", "GavinGrover_Once (Chiết tự trực tiếp)": "且 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰且隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "且", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "隹", "Unihan_Simplified (Chữ Giản thể)": "雎", "Unihan_Traditional (Chữ Phồn thể)": "雎", "Pinyin_Xie": "jū", "Âm Hán Việt_Xie": "sư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ xuất hiện trong Kinh Thi để chỉ loài chim chung thủy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲋', '{"9000": "5354.0", "Chữ Trung Quốc": "鲋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 13 | nét | 鲋 | phụ | tượng hình | cá diếc (cá chép vàng) | 鲋 (phồn thể 鮒) là chữ ghi tên loài cá. Bộ 鱼 (ngư) biểu nghĩa chỉ loài cá. Cấu trúc chi tiết không ghi trong Wiktionary ngoài phát âm cổ (MC/OC), cho thấy chữ tương đối xưa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Phụ\": bộ cá (鱼) — cá diếc (鲋) là loài cá nhỏ; thành ngữ 涸辙之鲋 (cá trong vũng cạn) ám chỉ người lâm nguy cần giúp gấp, như con cá \"phụ\" (nương nhờ) vào giọt nước còn lại. | Gương Hán-Việt | Phụ trong 涸辙之鲋 (hạc triệt chi phụ) — cá trong vũng cạn, người lâm nguy | Mở khoá kiến thức | Biết 鲋 mở khoá thành ngữ 涸辙之鲋 — cá trong vết bánh xe cạn, dùng để nói người cần giúp đỡ khẩn cấp; gặp nhiều trong văn học cổ.", "Tự nguyên_Xie": "Tiểu triện | 鲋 (phồn thể 鮒) là tên cá diếc/cá chép vàng (Carassius auratus). Wiktionary có ghi âm Trung Cổ và Thượng Cổ nhưng không phân tích cấu trúc học. Chữ xuất hiện trong thành ngữ nổi tiếng 涸辙之鲋 (con cá trong vũng nước cạn kiệt) — dùng chỉ người trong hoàn cảnh nguy cấp cần cứu gấp. Chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con cá diếc", "Hạng Tần Suất (Jun Da)": "5354.0", "Tần Suất % (Jun Da)": "99.9508335791", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 付", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼付", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "付", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲋", "Unihan_Traditional (Chữ Phồn thể)": "鮒", "Pinyin_Xie": "fù", "Âm Hán Việt_Xie": "phụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loài cá diếc trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞫', '{"9000": "5355.0", "Chữ Trung Quốc": "鞫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 18 | nét | 鞫 | cúc | tượng hình | tra tấn, thẩm vấn; khánh kiệt | 鞫 có bộ 革 (cách — da thuộc) gợi ý liên quan đến vật dụng da hay trói buộc. Cấu trúc chi tiết không ghi trong Wiktionary. Nghĩa chính: thẩm vấn (văn ngôn); nghèo khốn, cùng cực.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Cúc\": bộ da (革) — dây da trói kẻ bị thẩm vấn; 鞫 gợi hình ảnh tra tấn bằng dây da, thẩm tra đến cùng — nghĩa mở rộng là kiệt cùng, không còn gì. | Gương Hán-Việt | Cúc trong 鞫治 (cúc trị) — tra tấn, thẩm xét; 鞫审 (cúc thẩm) — xét xử | Mở khoá kiến thức | Biết 鞫 mở khoá loạt từ pháp lý cổ: 鞫治 (tra tấn xét xử), 鞫审 (thẩm tra), 鞫讯 (tra hỏi) — gặp trong sử sách và pháp luật thời cổ đại.", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} nhưng không phân tích cấu trúc học chi tiết cho 鞫. Có âm Trung Cổ và Thượng Cổ (MC/OC), cho thấy chữ khá xưa. Nghĩa văn ngôn: tra hỏi, thẩm vấn tội nhân; vụ án hình sự; kiệt sức; nghèo khốn; đáy của hồ. Tiếng Mân Nam Chương Châu có nghĩa dẻo dai, cứng bền. Chưa có nguồn học thuật về cấu trúc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xét hỏi kỹ càng; khốn cùng", "Hạng Tần Suất (Jun Da)": "5355.0", "Tần Suất % (Jun Da)": "99.9508976604", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 訇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革訇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "訇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞫", "Unihan_Traditional (Chữ Phồn thể)": "鞫", "Pinyin_Xie": "jū", "Âm Hán Việt_Xie": "cúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ người bị thẩm vấn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼬', '{"9000": "5356.0", "Chữ Trung Quốc": "鼬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼠 | Số nét | 18 | nét | 鼠 | thử | biểu nghĩa | chuột | 由 | do | biểu âm | từ, bởi vì | 鼬 = 鼠 (Thử, biểu nghĩa: chuột — chỉ loài gặm nhấm/thú nhỏ) + 由 (Do, biểu âm). Chữ hình thanh: 鼠 chỉ đây là loài thú gần với chuột; 由 cho âm (yòu ≈ do). Con chồn (weasel) được xếp gần chuột trong phân loại dân gian Trung Hoa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Dữu\": chuột (鼠) + do (由) — chồn là \"do từ loài chuột mà ra\" theo phân loại xưa; 黄鼬 (hoàng dữu) là chồn vàng quen thuộc, hay rình gà. | Gương Hán-Việt | Dữu trong 鼬鼠 (dữu thử) — con chồn; 黄鼬 (hoàng dữu) — chồn vàng | Mở khoá kiến thức | Biết 鼬 mở khoá tên các loài mustelid: 黄鼬 (chồn vàng), 臭鼬 (skunk), 白鼬 (chồn ecmine), 鼬鲨 (cá mập hổ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 鼬 là chữ hình thanh: 鼠 biểu nghĩa (chuột, thú nhỏ); 由 biểu âm. Nghĩa là con chồn (weasel), tên khoa học Mustela. Mở rộng sang toàn bộ họ Mustelidae (bao gồm chồn, rái cá, badger). Chữ có hình tiểu triện. Từ ghép bao gồm 黄鼬 (chồn vàng — chồn hương thông thường), 臭鼬 (con skunk), 白鼬 (chồn ecmine/chồn trắng). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "855.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thử (854) Do (372)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thử (số 854 - con chuột) ở bên trái chữ Do (số 372 - nguyên do/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Do chỉ âm, bộ Thử chỉ ý. Dữu là từ chỉ chung loài chồn, sóc (bởi vì chúng giống con chuột).", "Nghĩa Tiếng Việt_Xie": "con chồn, con sóc", "Hạng Tần Suất (Jun Da)": "5356.0", "Tần Suất % (Jun Da)": "99.9509617418", "GavinGrover_Once (Chiết tự trực tiếp)": "鼠 + 由", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鼠由", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "由", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼠", "Unihan_Simplified (Chữ Giản thể)": "鼬", "Unihan_Traditional (Chữ Phồn thể)": "鼬", "Pinyin_Xie": "yòu", "Âm Hán Việt_Xie": "dứu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loài chồn hoặc kết hợp thành tên các loài thú. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('獯', '{"9000": "5357.0", "Chữ Trung Quốc": "獯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 17 | nét | 獯 | huân | tượng hình | tên tộc man di phương Bắc | 獯 có bộ 犬/犭 (khuyển — chó) gợi hình dung man di phương Bắc theo cách gọi miệt thị của người Hán xưa (dùng bộ thú). Cấu trúc chi tiết không ghi trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Huân\": bộ chó (犭) — theo cách đặt tên cổ đại, 獯鬻 là tên Hán gọi tộc du mục phương Bắc; \"huân\" gợi tiếng gió lạnh thảo nguyên phía bắc. | Gương Hán-Việt | Huân trong 獯鬻 (Huân Húc) — tên bộ tộc du mục phương Bắc thời cổ Trung Quốc | Mở khoá kiến thức | Biết 獯 mở khoá tên bộ tộc lịch sử 獯鬻 — được cho là tổ tiên của Hung Nô (匈奴), đề tài thường xuất hiện trong sách lịch sử cổ đại Trung Quốc.", "Tự nguyên_Xie": "獯 là chữ viết tắt của 獯鬻 (Huân Húc) — tên gọi của người Hán thời Hạ, Thương để chỉ một bộ tộc du mục phương Bắc (được cho là tổ tiên của Hung Nô). Bộ 犭 gợi cách nhìn miệt thị của người Hán xưa đối với các bộ tộc du mục. Wiktionary không có phân tích cấu trúc sâu. Chữ có âm MC/OC nhưng không ghi rõ cấu trúc học. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một giống rợ phía bắc)", "Hạng Tần Suất (Jun Da)": "5357.0", "Tần Suất % (Jun Da)": "99.9510253064", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 熏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭熏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "熏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "獯", "Unihan_Traditional (Chữ Phồn thể)": "獯", "Pinyin_Xie": "xūn", "Âm Hán Việt_Xie": "huân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng chỉ tộc người du mục cổ đại ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('昀', '{"9000": "5358.0", "Chữ Trung Quốc": "昀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 8 | nét | 昀 | quân | tượng hình | ánh sáng mặt trời, rạng đông | 昀 có bộ 日 (nhật — mặt trời) biểu nghĩa chỉ ánh sáng/mặt trời. Không có dữ liệu Wiktionary. Chữ hầu như chỉ dùng trong tên người. Cấu trúc chi tiết chưa được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Quân\": bộ mặt trời (日) — 昀 gợi ánh sáng chan hòa của buổi sáng, ấm áp và rực rỡ; tên đẹp cho người mang ý nghĩa rạng đông, tươi sáng. | Gương Hán-Việt | Quân trong tên người 昀 — ánh bình minh, dùng đặt tên con trai/gái với ý nghĩa tươi sáng | Mở khoá kiến thức | Biết 昀 giúp đọc tên người Trung Quốc: một chữ phổ biến trong tên đặt vì nghĩa tốt (ánh sáng, bình minh, ôn hòa).", "Tự nguyên_Xie": "昀 không có dữ liệu Wiktionary hay giáp cốt/kim văn. Bộ 日 (nhật) chỉ ánh sáng mặt trời, bình minh. Nghĩa: ánh sáng mặt trời, rạng đông. Chữ dùng chủ yếu trong tên người Trung Quốc vì có nghĩa đẹp (rạng sáng, ôn hòa). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rạng đông, bình minh", "Hạng Tần Suất (Jun Da)": "5358.0", "Tần Suất % (Jun Da)": "99.9510888709", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 匀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日匀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "昀", "Unihan_Traditional (Chữ Phồn thể)": "昀", "Pinyin_Xie": "yún", "Âm Hán Việt_Xie": "quân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ ánh sáng ấm áp hoặc dùng đặt tên riêng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痍', '{"9000": "5359.0", "Chữ Trung Quốc": "痍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 11 | nét | 夷 | di | biểu âm | man di, bằng phẳng | 疒 | nạch | biểu nghĩa | bệnh tật, thương tích | 痍 = 夷 (Di, biểu âm) + 疒 (Nạch, biểu nghĩa: bệnh/thương tích). Chữ hình thanh: 疒 chỉ đây là vết thương hay bệnh; 夷 cho âm (yí ≈ di). Nghĩa: vết thương, vết xây xát. Thường gặp trong 疮痍 (thương di — vết thương) và thành ngữ 满目疮痍.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Di\": bệnh (疒) + di (夷) — 疮痍 (thương di) là vết thương loang đầy; 满目疮痍 là cảnh tàn phá sau chiến tranh, \"đầy mắt vết thương\". | Gương Hán-Việt | Di trong 疮痍 (thương di) — vết thương; 满目疮痍 (mãn mục thương di) — cảnh điêu tàn | Mở khoá kiến thức | Biết 痍 mở khoá thành ngữ 满目疮痍 — vết thương đầy mắt, thường dùng mô tả đất nước, xã hội bị tàn phá sau chiến loạn; gặp nhiều trong văn học và báo chí.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 痍 là chữ hình thanh: 疒 biểu nghĩa (bệnh, thương tích); 夷 biểu âm. Nghĩa là vết thương, vết thâm tím. Chữ xuất hiện chủ yếu trong từ 疮痍 (thương di) và thành ngữ 满目疮痍 (mãn mục thương di — vết thương đầy mắt, ám chỉ cảnh điêu tàn sau chiến tranh). Có hình tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bị đau", "Hạng Tần Suất (Jun Da)": "5359.0", "Tần Suất % (Jun Da)": "99.9511524355", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 夷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒夷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痍", "Unihan_Traditional (Chữ Phồn thể)": "痍", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các từ ghép để chỉ vết thương trên cơ thể hoặc nỗi đau thương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟊', '{"9000": "5360.0", "Chữ Trung Quốc": "蟊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 17 | nét | 蟊 | mao | tượng hình | sâu đục rễ lúa, sâu hại | 蟊 có bộ 虫 (trùng) gợi ý đây là loài côn trùng. Cấu trúc chi tiết không ghi trong Wiktionary ngoài ghi chú {{Han etym}}. Chữ có hình tiểu triện, tương đối xưa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Mao\": bộ trùng (虫) — sâu mao đục rễ lúa; 蟊贼 (mao tặc) là \"sâu mọt và kẻ trộm\" — ẩn dụ cho kẻ phá hoại đất nước từ bên trong. | Gương Hán-Việt | Mao trong 蟊贼 (mao tặc) — sâu hại và kẻ phá hoại; 斑蟊 (ban mao) — con ban mao (blister beetle) | Mở khoá kiến thức | Biết 蟊 mở khoá ẩn dụ 蟊贼 (mao tặc) — kẻ phá hoại từ bên trong; và từ y học 斑蟊 — con ban mao có độc dùng trong đông y.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi {{Han etym}} nhưng không phân tích cấu trúc học chi tiết. Có âm MC/OC, cho thấy chữ khá xưa. Nghĩa: loài sâu ăn rễ mạ/cây non (loài gây hại nông nghiệp). Thường gặp trong 蟊贼 (mao tặc) — sâu bọ và kẻ trộm, ẩn dụ chỉ kẻ phá hoại, hại nước. Cũng trong 斑蟊 (ban mao — con blister beetle, dùng trong y học truyền thống). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sâu cắn gốc lúa", "Hạng Tần Suất (Jun Da)": "5360.0", "Tần Suất % (Jun Da)": "99.9512160001", "GavinGrover_Once (Chiết tự trực tiếp)": "矛 + 䖵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱矛䖵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䖵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "矛", "Unihan_Simplified (Chữ Giản thể)": "蟊", "Unihan_Traditional (Chữ Phồn thể)": "蟊", "Pinyin_Xie": "máo", "Âm Hán Việt_Xie": "mâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ để chỉ loài sâu ăn lá lúa hoặc ẩn dụ cho kẻ phá hoại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞴', '{"9000": "5361.0", "Chữ Trung Quốc": "鞴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 19 | nét | 鞴 | bị | tượng hình | thắng yên ngựa; bễ thổi lò rèn | 鞴 có bộ 革 (cách — da thuộc) biểu nghĩa chỉ vật dụng bằng da. Cấu trúc chi tiết không ghi trong Wiktionary. Nghĩa chính: thắng yên cương lên ngựa; nghĩa mở rộng là bễ (ống thổi gió lò rèn). Có hình tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Bị\": bộ da (革) — da thắng yên ngựa (bị — mang/đeo); 鞲鞴 là bễ rèn, vật dụng da-kim dùng để thổi gió. Câu tục ngữ: ngựa tốt không thắng hai yên. | Gương Hán-Việt | Bị trong 鞲鞴 (câu bị) — bễ thổi gió (pittông); 鞴马 (bị mã) — thắng yên ngựa | Mở khoá kiến thức | Biết 鞴 mở khoá từ 鞲鞴 (bễ/pittông cơ khí) và câu ngạn ngữ 好馬不鞴雙鞍 — người trung thành không thờ hai chủ.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi {{Han etym}} nhưng không phân tích cấu trúc học. 鞴 có ba âm đọc: bèi (thắng yên ngựa), fú, bù (ý nghĩa khác trong từ điển cổ). Nghĩa chính là dùng da thắng yên ngựa; nghĩa thứ hai là bễ thổi (trong 鞲鞴 — ống pittông của bễ rèn). Từ cổ 好馬不鞴雙鞍 (ngựa tốt không thắng hai yên) — ý chỉ người trung thành không hai lòng. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: câu bị 鞲鞴)", "Hạng Tần Suất (Jun Da)": "5361.0", "Tần Suất % (Jun Da)": "99.9512795646", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鞴", "Unihan_Traditional (Chữ Phồn thể)": "鞴", "Pinyin_Xie": "bèi", "Âm Hán Việt_Xie": "bị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc đóng yên cương cho ngựa hoặc làm danh từ trong thuật ngữ cơ khí. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疖', '{"9000": "5362.0", "Chữ Trung Quốc": "疖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 7 | nét | 疒 | nạch | biểu nghĩa | bệnh, thương | 節 | tiết | biểu âm | đốt, tiết | 疖 = 疒 (Nạch, biểu nghĩa: bệnh tật) + 節/节 (Tiết, biểu âm, viết tắt). Chữ hình thanh: 疒 chỉ đây là loại bệnh da; 節 cho âm (jiē ≈ tiết). Nghĩa: mụn nhọt, đinh nhọt — chỗ da bị viêm mủ cục bộ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tiết\": bệnh (疒) + tiết (節) — mụn nhọt như \"nốt\" (tiết/đốt) bệnh nổi lên trên da; âm jiē khớp với tiết. | Gương Hán-Việt | Tiết trong 疖子 (tiết tử) — mụn nhọt, đinh nhọt | Mở khoá kiến thức | Biết 疖 mở khoá từ y khoa 疖子 (mụn nhọt), 疖肿 (nhọt sưng) — thường gặp trong hồ sơ bệnh án và sách y khoa Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 疖 (phồn thể 癤) là chữ hình thanh: 疒 biểu nghĩa (bệnh); 節 biểu âm. Nghĩa: mụn nhọt, đinh nhọt, boil. Chữ phồn thể 癤 có hình giáp cốt/tiểu triện. Đây là từ y khoa chỉ vết viêm da cấp tính có mủ, phổ biến trong văn bản y tế Trung Quốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rôm sảy", "Hạng Tần Suất (Jun Da)": "5362.0", "Tần Suất % (Jun Da)": "99.9513431292", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "疖", "Unihan_Traditional (Chữ Phồn thể)": "癤", "Pinyin_Xie": "jiē", "Âm Hán Việt_Xie": "tiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các động từ chỉ sự xuất hiện của mụn nhọt như mọc hoặc phát. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('熘', '{"9000": "5363.0", "Chữ Trung Quốc": "熘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 14 | nét | 熘 | lưu | tượng hình | kỹ thuật nấu ăn: xào nhanh với bột nước | 熘 có bộ 火/灬 (hỏa — lửa) biểu nghĩa chỉ phương pháp dùng lửa/nhiệt. Không có dữ liệu Wiktionary. Chữ tạo muộn dùng chỉ kỹ thuật nấu ăn đặc trưng của ẩm thực Trung Hoa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Lưu\": lửa (灬) + lưu — 熘 là kỹ thuật \"lướt\" nhanh qua lửa (liū), thức ăn được xào chớp nhoáng trong nước sốt nóng; gợi hình ảnh lửa và nước hòa quyện nhanh. | Gương Hán-Việt | Lưu trong 熘肉 (lưu nhục) — thịt xào kiểu liū; 熘鱼片 — cá xào nước sốt | Mở khoá kiến thức | Biết 熘 mở khoá kỹ thuật nấu ăn Trung Hoa: 熘 (liū) — xào nhanh với nước bột sệt, tạo lớp sốt bao ngoài thực phẩm; gặp trong thực đơn nhà hàng Trung Quốc.", "Tự nguyên_Xie": "熘 không có dữ liệu Wiktionary hay giáp cốt/kim văn. Bộ 火/灬 biểu nghĩa chỉ phương pháp dùng lửa. Nghĩa: một kỹ thuật nấu ăn Trung Hoa (liū) — xào nhanh với nước thịt/bột pha loãng, hoặc hấp rồi tưới nước sốt nóng lên. Phổ biến trong món 溜肉段, 熘鱼片. Chữ tạo muộn dùng trong ngữ cảnh ẩm thực, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xào thức ăn", "Hạng Tần Suất (Jun Da)": "5363.0", "Tần Suất % (Jun Da)": "99.9514066938", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 留", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火留", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "留", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "熘", "Unihan_Traditional (Chữ Phồn thể)": "熘", "Pinyin_Xie": "liū", "Âm Hán Việt_Xie": "lựu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ nguyên liệu để biểu thị phương pháp chế biến món ăn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('乇', '{"9000": "5364.0", "Chữ Trung Quốc": "乇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 丿 | Số nét | 3 | nét | 乇 | trác | tượng hình | ủy thác; hình tượng cỏ mọc hoặc dụng cụ cắt | 乇 là chữ độc lập (tượng hình/chỉ sự). Hai thuyết: (1) Từ Trung Thư: dụng cụ cắt đôi như 力; (2) Lâm Nghĩa Quang: hình cỏ mọc có rễ lộ. Nghĩa hiện dùng: ủy thác. Chữ có hình từ giáp cốt đến tiểu triện — rất xưa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Trác\": hình cỏ nhỏ (乇) mọc nương tựa vào đất — ủy thác (乇) là nương nhờ vào người khác như cọng cỏ tựa vào nền đất. | Gương Hán-Việt | Trác trong 乇民 (trác dân) — dân ly tán, dân không nơi nương tựa | Mở khoá kiến thức | Biết 乇 mở khoá lịch sử văn tự: đây là một trong những chữ Hán cổ nhất có hình giáp cốt, xuất hiện trong nghiên cứu về nguồn gốc chữ Hán.", "Tự nguyên_Xie": "Giáp cốt văn | Bạch thư | Đại triện | Tiểu triện | Theo Wiktionary, 乇 là chữ tượng hình với hai thuyết: (1) Từ Trung Thư (徐中舒): dụng cụ cắt tương tự 力 (dao cắt); (2) Lâm Nghĩa Quang (林義光): hình cỏ mọc — thân cỏ với rễ lộ ở dưới. Chữ xuất hiện từ giáp cốt văn, bạch thư (lụa), đại triện, tiểu triện — là chữ rất cổ. Nghĩa hiện đại: ủy thác, nương nhờ. Ngày nay thường thấy trong 乇民 (dân du cư) ở văn ngôn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1339.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thất (006)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Có một nét phẩy (丿) ở trên chữ Thất (số 006 - số 7/ 七). Giải thích sự chuyển ý: Đây là chữ Tượng hình. Hình ảnh mầm lá cỏ nhú lên mọc trên mặt đất.", "Nghĩa Tiếng Việt_Xie": "uỷ thác", "Hạng Tần Suất (Jun Da)": "5364.0", "Tần Suất % (Jun Da)": "99.9514697416", "GavinGrover_Once (Chiết tự trực tiếp)": "㇒ + 七", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱㇒七", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "七", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "㇒", "Unihan_Simplified (Chữ Giản thể)": "乇", "Unihan_Traditional (Chữ Phồn thể)": "乇", "Pinyin_Xie": "tuō", "Âm Hán Việt_Xie": "thác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm động từ với nghĩa ủy thác hoặc làm danh từ chỉ hình dáng cỏ mới mọc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羸', '{"9000": "5365.0", "Chữ Trung Quốc": "羸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 19 | nét | 羸 | luy | tượng hình | gầy yếu, kiệt sức | 羸 là chữ phức hợp, bộ 羊 (dương — con dê/dương) ở trong. Wiktionary không có phân tích cấu trúc học chi tiết. Nghĩa: yếu đuối, gầy mòn, kiệt sức. Có hình đại triện và tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Luy\": bộ dê (羊) — con dê gầy bệnh, không còn sức lực; 羸弱 (luy nhược) là thành ngữ tả người/thú vật suy kiệt, yếu ớt. | Gương Hán-Việt | Luy trong 羸弱 (luy nhược) — gầy yếu; 羸兵 (luy binh) — quân giả ốm yếu để nghi binh | Mở khoá kiến thức | Biết 羸 mở khoá từ văn ngôn 羸弱 (gầy yếu), 羸瘦 (gầy ốm), và mưu kế 以羸师诱之 (dùng quân giả ốm để nhử địch) — mưu kế nổi tiếng trong Sử Ký.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary có âm Trung Cổ/Thượng Cổ (MC léi, OC) nhưng không phân tích cấu trúc học. Bộ 羊 (dê) trong 羸 gợi hình ảnh con dê ốm yếu, gầy mòn. Nghĩa: yếu, kiệt sức, gầy trơ xương (văn ngôn). Từ ghép: 羸弱 (luy nhược — yếu đuối), 羸瘦 (luy sấu — gầy ốm), 羸兵 (luy binh — quân lính ốm yếu, thường dùng trong kế nghi binh). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gầy, yếu đuối", "Hạng Tần Suất (Jun Da)": "5365.0", "Tần Suất % (Jun Da)": "99.9515327894", "GavinGrover_Once (Chiết tự trực tiếp)": "𣎆 + 羊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𣎆羊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𣎆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羊", "Unihan_Simplified (Chữ Giản thể)": "羸", "Unihan_Traditional (Chữ Phồn thể)": "羸", "Pinyin_Xie": "léi", "Âm Hán Việt_Xie": "luy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc sau phó từ chỉ mức độ để miêu tả trạng thái gầy yếu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嵴', '{"9000": "5366.0", "Chữ Trung Quốc": "嵴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 13 | nét | 嵴 | tích | tượng hình | sống núi, đỉnh lăn; mào xương | 嵴 là chữ tạo từ 山脊 (sơn tích — sống núi). Wiktionary ghi \"From 山脊\". Bộ 山 (sơn) biểu nghĩa chỉ địa hình núi. Nghĩa: sống núi (mountain ridge); trong sinh học: mào xương (crista); trong chiếu tướng: đỉnh gò.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tích\": bộ núi (山) — sống núi, đường lưỡi dao nhô lên của dãy núi; trong giải phẫu, 嵴 là mào xương nhô lên như sống núi nhỏ. | Gương Hán-Việt | Tích trong 嵴椎 (tích chuy) — xương sống; 肋嵴 (lặc tích) — gờ xương sườn | Mở khoá kiến thức | Biết 嵴 mở khoá thuật ngữ giải phẫu: 嵴椎 (xương sống), 线粒体嵴 (mào ty thể — mitochondrial crista) — gặp trong giáo trình sinh học tế bào.", "Tự nguyên_Xie": "Theo Wiktionary, 嵴 là chữ tạo từ 山脊 (sơn tích — sống núi), rút gọn thành một chữ. Bộ 山 biểu nghĩa chỉ địa hình núi. Nghĩa: sống núi, đường gờ nhô lên. Trong y học/sinh học: crista (mào — đường nhô lên của xương). Trong chiếu tướng học (palmistry): apex của gò tay. Không có ghi chép giáp cốt/kim văn — chữ tạo muộn. Chưa có nguồn học thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "triền núi", "Hạng Tần Suất (Jun Da)": "5366.0", "Tần Suất % (Jun Da)": "99.9515958371", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 脊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山脊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "脊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "嵴", "Unihan_Traditional (Chữ Phồn thể)": "嵴", "Pinyin_Xie": "jǐ", "Âm Hán Việt_Xie": "tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ địa hình sống núi hoặc các cấu trúc đường gờ trong giải phẫu học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('栀', '{"9000": "5367.0", "Chữ Trung Quốc": "栀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 栀 | chi | tượng hình | cây dành dành (gardenia) | 栀 (phồn thể 梔) có bộ 木 (mộc) biểu nghĩa chỉ loài cây. Cấu trúc chi tiết không ghi trong Wiktionary ngoài ghi chú {{Han etym}}. Nghĩa: cây dành dành, hoa trắng thơm (Gardenia jasminoides).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Chi\": bộ cây (木) — cây dành dành (栀子花) nở hoa trắng thơm ngào ngạt; hoa \"chi\" trắng trong trẻo như tên gọi Hán-Việt 栀子. | Gương Hán-Việt | Chi trong 栀子 (chi tử) — quả dành dành; 栀子花 (chi tử hoa) — hoa dành dành | Mở khoá kiến thức | Biết 栀 mở khoá từ 栀子花 (hoa dành dành — gardenia), loài hoa trắng thơm biểu tượng cho vẻ đẹp tinh khiết trong thi ca Trung Quốc; cũng dùng nhuộm màu thực phẩm.", "Tự nguyên_Xie": "栀 (phồn thể 梔) là tên cây dành dành (gardenia, Cape jasmine — Gardenia jasminoides). Wiktionary có âm cổ (MC/OC) nhưng không phân tích cấu trúc học chi tiết. Bộ 木 biểu nghĩa chỉ loài cây. Nghĩa mở rộng: nhuộm màu vàng (từ quả dành dành). Chữ có hai cách đọc: văn ngôn và bạch thoại ở các phương ngữ. Chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây dành dành", "Hạng Tần Suất (Jun Da)": "5367.0", "Tần Suất % (Jun Da)": "99.9516588849", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 卮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木卮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "栀", "Unihan_Traditional (Chữ Phồn thể)": "梔", "Pinyin_Xie": "zhī", "Âm Hán Việt_Xie": "chi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trước các từ chỉ bộ phận của cây như tử hoặc tử hoa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('槲', '{"9000": "5368.0", "Chữ Trung Quốc": "槲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 15 | nét | 槲 | hộc | tượng hình | cây hộc, cây sồi Nhật Bản (daimyo oak) | 槲 có bộ 木 (mộc) biểu nghĩa chỉ loài cây gỗ. Cấu trúc chi tiết không ghi trong Wiktionary. Nghĩa: cây hộc/sồi Nhật Bản (Quercus dentata — daimyo oak, Japanese emperor oak).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Hộc\": bộ cây (木) — cây hộc là cây sồi to lá ở vùng ôn đới; 槲寄生 (tầm gửi hộc) là loại cây ký sinh trên cành sồi, dùng làm thuốc dân gian. | Gương Hán-Việt | Hộc trong 槲寄生 (hộc ký sinh) — tầm gửi cây sồi; 槲树 (hộc thụ) — cây hộc | Mở khoá kiến thức | Biết 槲 mở khoá từ 槲寄生 (tầm gửi sồi — Viscum), vị thuốc đông y; và 槲蕨 (dương xỉ sồi) trong y học thảo mộc Trung Quốc.", "Tự nguyên_Xie": "Wiktionary có âm MC/OC cho 槲 nhưng không phân tích cấu trúc học. Bộ 木 biểu nghĩa chỉ loài cây. Nghĩa: cây hộc (槲树) — cây sồi lá to (Quercus dentata), loài cây rụng lá ở Đông Á. Từ ghép: 槲寄生 (tầm gửi cây sồi — mistletoe, Viscum coloratum), một vị thuốc dân gian. 槲蕨 (dương xỉ sồi), 槲栎 (sồi hỗn hợp). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây hộc", "Hạng Tần Suất (Jun Da)": "5368.0", "Tần Suất % (Jun Da)": "99.9517219327", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 斛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木斛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "槲", "Unihan_Traditional (Chữ Phồn thể)": "槲", "Pinyin_Xie": "hú", "Âm Hán Việt_Xie": "hộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trước các từ chỉ bộ phận của cây như diệp hoặc ký sinh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('炝', '{"9000": "5369.0", "Chữ Trung Quốc": "炝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 8 | nét | 炝 | tượng hình | chữ tạo muộn, không rõ cấu trúc | 炝 không có dữ liệu cấu trúc CHISE. Bộ 火 (hỏa) gợi ý liên quan đến lửa/nhiệt, nhưng chưa xác định được loại chữ (hình thanh hay hội ý) từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: chữ 炝 có bộ 火 (lửa) — hình ảnh ngọn lửa bùng lên khi xào tái thịt cá, khói bay mùi sặc sụa. | Gương Hán-Việt | 炝 chưa có từ Hán-Việt phổ biến trong tiếng Việt | Mở khoá kiến thức | Biết 炝 giúp nhận diện thuật ngữ ẩm thực Trung Hoa như 炝炒 (xào tái).", "Tự nguyên_Xie": "Chưa có nguồn học thuật. 炝 mang bộ 火 (lửa), gợi ý nghĩa liên quan đến nhiệt — nấu tái bằng nước sôi hoặc chiên sơ qua dầu. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nấu chín tái; sặc, hắc", "Hạng Tần Suất (Jun Da)": "5369.0", "Tần Suất % (Jun Da)": "99.9517849805", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 仓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火仓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "仓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "炝", "Unihan_Traditional (Chữ Phồn thể)": "熗", "Pinyin_Xie": "qiàng", "Âm Hán Việt_Xie": "sang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ cách nấu ăn nhanh bằng dầu nóng hoặc làm tính từ miêu tả mùi hắc gây sặc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('炷', '{"9000": "5370.0", "Chữ Trung Quốc": "炷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 9 | nét | 炷 | tượng hình | bấc đèn, nén hương | 炷 không có dữ liệu cấu trúc CHISE rõ ràng. Wiktionary ghi nhận là danh từ/động từ chỉ hành động đốt hương hoặc bấc đèn. Khả năng là chữ hình thanh với bộ 火 (hỏa, biểu nghĩa: lửa) và 主 (chủ, biểu âm: zhù→zhù), nhưng lsCodes trống nên chỉ suy luận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 炷 có bộ 火 (lửa) — hình ảnh ngọn lửa nhỏ trên bấc đèn dầu leo lắt, hay làn khói từ nén hương 一炷香 (một nén hương). | Gương Hán-Việt | 炷 chưa có từ Hán-Việt quen thuộc trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 炷 giúp hiểu 一炷香 (một nén hương — đơn vị thời gian dân gian), 灯炷 (bấc đèn).", "Tự nguyên_Xie": "Wiktionary ghi 炷 mang nghĩa: đốt (hương), bấc đèn dầu, và lượng từ đếm nén hương đang cháy. Chữ có bộ 火 (lửa) gợi ý liên quan đến ngọn lửa nhỏ — bấc đèn hay nén hương. Không có hình ảnh từ giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bấc đèn", "Hạng Tần Suất (Jun Da)": "5370.0", "Tần Suất % (Jun Da)": "99.9518480283", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 主", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火主", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "主", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "炷", "Unihan_Traditional (Chữ Phồn thể)": "炷", "Pinyin_Xie": "zhù", "Âm Hán Việt_Xie": "chú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Động từ | 动词 | Thường làm lượng từ cho hương hoặc làm động từ chỉ hành động thắp, đốt hương. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硐', '{"9000": "5371.0", "Chữ Trung Quốc": "硐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 11 | nét | 硐 | tượng hình | hang động, hầm mỏ | 硐 không có dữ liệu cấu trúc CHISE. Wiktionary ghi 硐 là dị thể của 洞 (động: hang), mang bộ 石 (thạch: đá) thay vì bộ 水. Khả năng là chữ hình thanh với bộ 石 (biểu nghĩa: đá/hầm) và một thành phần biểu âm, nhưng không xác nhận được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 硐 có bộ 石 (đá) — tưởng tượng một hầm mỏ khoét sâu trong đá, tối tăm và vang âm — giống 洞 nhưng nhấn mạnh chất đá. | Gương Hán-Việt | 動 (động: chuyển động) — cùng âm, dễ nhầm; 硐 chuyên dùng trong khai mỏ | Mở khoá kiến thức | Biết 硐 giúp đọc văn bản khai khoáng TQ như 矿硐 (hầm mỏ), 硐室 (buồng hầm).", "Tự nguyên_Xie": "Wiktionary ghi 硐 là dị thể của 洞, mang nghĩa hang động, hầm mỏ (âm dòng/tóng). Bộ 石 (đá) phản ánh ngữ cảnh địa chất — hầm mỏ khai thác trong đá. Nghĩa cổ thứ hai là ''đá mài'' (grindstone). Chữ tương đối muộn, không có giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hang động; hầm mỏ", "Hạng Tần Suất (Jun Da)": "5371.0", "Tần Suất % (Jun Da)": "99.9519110761", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 同", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石同", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "同", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硐", "Unihan_Traditional (Chữ Phồn thể)": "硐", "Pinyin_Xie": "dòng", "Âm Hán Việt_Xie": "động", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các hang động tự nhiên hoặc đường hầm khai thác mỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锸', '{"9000": "5372.0", "Chữ Trung Quốc": "锸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 锸 | tượng hình | xẻng, mai đào đất | 锸 không có dữ liệu cấu trúc CHISE. Wiktionary dùng dạng truyền thống 鍤, ghi là công cụ xẻng/thuổng dùng trong văn ngôn. Bộ 金 (kim: kim loại) gợi ý đây là vật dụng bằng kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 锸 có bộ 金 (kim loại) — hình ảnh lưỡi xẻng sắt bổ xuống đất, âm chā gợi tiếng kim loại cắm vào đất. | Gương Hán-Việt | 锸 chưa có từ Hán-Việt quen dùng trong tiếng Việt | Mở khoá kiến thức | Biết 锸 giúp đọc văn cổ/kỹ thuật nông nghiệp TQ về dụng cụ đào đất.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 锸 (dạng truyền thống 鍤, âm chā) là từ văn ngôn chỉ cái xẻng, cái thuổng. Tương đương với 铲子 trong tiếng Hoa hiện đại. Bộ 金 (kim loại) xác nhận đây là dụng cụ kim loại. Có hình tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mai, xẻng, thuổng; cái kim", "Hạng Tần Suất (Jun Da)": "5372.0", "Tần Suất % (Jun Da)": "99.9519741239", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 臿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅臿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锸", "Unihan_Traditional (Chữ Phồn thể)": "鍤", "Pinyin_Xie": "chā", "Âm Hán Việt_Xie": "tráp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau động từ hành động để chỉ công cụ đào đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹂', '{"9000": "5373.0", "Chữ Trung Quốc": "鹂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 12 | nét | 鹂 | tượng hình | chim vàng anh | 鹂 không có dữ liệu cấu trúc CHISE. Bộ 鳥 (điểu: chim) xác nhận đây là tên loài chim. Dạng truyền thống 鸝 xuất hiện khá muộn trong văn học (thế kỷ 3 TCN).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 鹂 có bộ 鳥 (chim) — hình ảnh chim vàng anh lông vàng rực hót trên cành liễu, âm lí vang trong trẻo như tiếng nhạc. | Gương Hán-Việt | 鹂 thường gặp trong thành ngữ 黄鹂 (hoàng li: chim vàng anh) | Mở khoá kiến thức | Biết 鹂 giúp đọc thơ cổ điển TQ — 黄鹂 (hoàng li) là hình ảnh xuân tươi phổ biến.", "Tự nguyên_Xie": "Wiktionary ghi 鹂 (dạng truyền thống 鸝) là chim vàng anh (oriole), xuất hiện sớm nhất trong ''Phú Cao Đường'' của Tống Ngọc, thế kỷ 3 TCN. Tên chim mô tả âm thanh hoặc màu sắc — vàng óng như ánh sáng. Bộ 鳥 (chim) là thành phần biểu nghĩa rõ ràng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim vàng anh", "Hạng Tần Suất (Jun Da)": "5373.0", "Tần Suất % (Jun Da)": "99.9520371717", "GavinGrover_Once (Chiết tự trực tiếp)": "丽 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰丽鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹂", "Unihan_Traditional (Chữ Phồn thể)": "鸝", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "li", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng trong các danh từ ghép để chỉ loài chim vàng anh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裾', '{"9000": "5374.0", "Chữ Trung Quốc": "裾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 13 | nét | 衣 | y | biểu nghĩa | quần áo | 居 | cư | biểu âm | 裾 = 衣 (Y, biểu nghĩa: quần áo) + 居 (Cư, biểu âm); chữ hình thanh. Thành phần 衣 cho biết nghĩa liên quan đến y phục, thành phần 居 cung cấp âm đọc gần với jū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 裾 = 衣 (y: áo) + 居 (cư: ở); chữ hình thanh — vạt áo ''cư trú'' xung quanh thân mình, bao bọc như nơi ở. | Gương Hán-Việt | 裾 chưa có từ Hán-Việt quen dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 裾 giúp đọc văn học cổ điển TQ — 曳裾 (kéo vạt áo), 衣裾 (vạt áo).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 裾 là chữ hình thanh: 衣 (y, biểu nghĩa: quần áo) + 居 (cư, biểu âm). Chữ chỉ vạt áo, viền áo, hoặc tà áo. Thường gặp trong thành ngữ văn học như 曳裾王門 (kéo vạt áo nơi cổng vua — ý chỉ người xu nịnh quyền thế) hay 絕裾而去 (dứt áo mà đi). Có hình tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vạt áo", "Hạng Tần Suất (Jun Da)": "5374.0", "Tần Suất % (Jun Da)": "99.9521002194", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 居", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤居", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "居", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裾", "Unihan_Traditional (Chữ Phồn thể)": "裾", "Pinyin_Xie": "jū", "Âm Hán Việt_Xie": "cư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ trang phục để chỉ phần vạt áo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('侪', '{"9000": "5375.0", "Chữ Trung Quốc": "侪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 侪 | tượng hình | lũ, chúng, bọn (nhóm người) | 侪 là chữ giản thể của 儕, đơn giản hóa từ 齊→齐. Không có dữ liệu cấu trúc CHISE rõ ràng. Bộ 人 (nhân: người) gợi ý nghĩa tập hợp người.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 侪 có bộ 人 (người) — hình ảnh một đám người đứng ngang hàng nhau (齐: ngang bằng), cùng nhóm, cùng giới. | Gương Hán-Việt | 侪 liên quan đến 儕輩 (tề bối: bọn, lũ, hàng ngũ) | Mở khoá kiến thức | Biết 侪 giúp đọc văn ngôn TQ — 吾侪 (ngô tề: bọn tôi/chúng tôi), 侪辈 (tề bối: đồng bọn).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Wiktionary ghi 侪 là chữ giản thể của 儕, đơn giản hóa thành phần 齊 thành 齐. Chữ 儕 mang nghĩa: bạn bè, đồng bọn, lũ người cùng nhóm. Có hình kim văn và tiểu triện. Bộ 人 (người) xác nhận nghĩa liên quan đến nhóm người. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lũ, chúng, bọn", "Hạng Tần Suất (Jun Da)": "5375.0", "Tần Suất % (Jun Da)": "99.9521632672", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 齐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻齐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "齐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "侪", "Unihan_Traditional (Chữ Phồn thể)": "儕", "Pinyin_Xie": "chái", "Âm Hán Việt_Xie": "sài", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Đại từ | 代词 | Thường dùng trong văn viết cổ để chỉ nhóm người cùng hàng ngũ hoặc thế hệ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('珐', '{"9000": "5376.0", "Chữ Trung Quốc": "珐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 9 | nét | 珐 | tượng hình | men pháp lang, đồ tráng men | 珐 không có dữ liệu cấu trúc CHISE và không có nguồn Wiktionary. Bộ 玉 (ngọc) gợi ý liên quan đến đồ trang trí quý giá. Chữ tạo muộn, chủ yếu dùng trong từ ghép 珐琅 (pháp lang: đồ tráng men cloisonné).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 珐 có bộ 玉 (ngọc) — liên tưởng đến đồ 珐琅 (pháp lang) lấp lánh màu sắc như ngọc, kỹ thuật men màu tinh xảo trên đồ đồng cung đình. | Gương Hán-Việt | 珐 chỉ dùng trong 珐琅 (pháp lang) — không có từ Hán-Việt độc lập | Mở khoá kiến thức | Biết 珐 giúp nhận diện 珐琅 (pháp lang: cloisonné/đồ tráng men) — đặc trưng nghệ thuật cung đình TQ.", "Tự nguyên_Xie": "Chưa có nguồn học thuật. 珐 có bộ 玉 (ngọc: đá quý), gợi ý chất liệu quý giá. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chủ yếu dùng trong từ 珐琅 (pháp lang) — kỹ thuật tráng men màu trên kim loại, du nhập vào TQ từ phương Tây qua Con đường Tơ lụa. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: pháp lang 珐琅)", "Hạng Tần Suất (Jun Da)": "5376.0", "Tần Suất % (Jun Da)": "99.9523518938", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 去", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王去", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "去", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "珐", "Unihan_Traditional (Chữ Phồn thể)": "琺", "Pinyin_Xie": "fà", "Âm Hán Việt_Xie": "pháp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu kết hợp với chữ khác tạo thành danh từ ghép chỉ chất liệu tráng men. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('縯', '{"9000": "5377.0", "Chữ Trung Quốc": "縯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 17 | nét | 縯 | tượng hình | kéo dài, dài | 縯 không có dữ liệu cấu trúc CHISE. Bộ 糸 (mịch: sợi chỉ) gợi ý nghĩa liên quan đến sợi chỉ dài hoặc sự kéo dài. Wiktionary ghi hai cách đọc: yǎn (dài, kéo dài) và yǐn (không rõ nghĩa).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chưa phổ biến\": 縯 có bộ 糸 (mịch: sợi chỉ) — hình ảnh sợi chỉ kéo dài mãi không đứt, tương tự 演 (diễn) cùng âm yǎn. | Gương Hán-Việt | 縯 liên hệ âm với 演 (diễn), nhưng ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 縯 giúp phân biệt với 演 (diễn) — 縯 chuyên chỉ sự kéo dài vật lý, 演 chỉ trình diễn.", "Tự nguyên_Xie": "Wiktionary ghi 縯 có hai cách đọc: yǎn (dài, kéo dài) và yǐn (không rõ nghĩa). Bộ 糸 (sợi chỉ) gợi liên tưởng đến cuộn chỉ dài. Chữ tương đối hiếm, không có hình ảnh glyph cổ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kéo dài", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 寅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹寅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "𬙂", "Unihan_Traditional (Chữ Phồn thể)": "縯", "Pinyin_Xie": "yǎn", "Âm Hán Việt_Xie": "diễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn cổ để chỉ sự kéo dài hoặc phát triển của sự vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哔', '{"9000": "5378.0", "Chữ Trung Quốc": "哔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 口 | khẩu | biểu nghĩa | miệng | 畢 | tất | biểu âm | 哔 = 口 (Khẩu, biểu nghĩa: miệng) + 畢 (Tất, biểu âm); chữ hình thanh. Thành phần 口 gợi ý âm thanh phát ra từ miệng hoặc thiết bị, 畢 cung cấp âm đọc gần với bì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 哔 = 口 (khẩu: miệng) + 畢 (tất: xong/hết); chữ hình thanh — miệng phát ra tiếng ''bíp!'' liên hồi khi pin sắp hết. | Gương Hán-Việt | 哔 chưa có từ Hán-Việt quen dùng | Mở khoá kiến thức | Biết 哔 giúp nhận diện 哔哔 (tiếng bíp), 哔叽 (vải len kiểu biber) trong văn bản hiện đại.", "Tự nguyên_Xie": "Wiktionary ghi 哔 (dạng truyền thống 嗶) là chữ hình thanh: 口 (khẩu, biểu nghĩa: miệng) + 畢 (tất, biểu âm). Có hai nghĩa: (1) âm thanh bíp (onomatopoeia); (2) dùng trong phiên âm nước ngoài. Thường gặp trong 哔哔 (tiếng bíp liên tiếp) và 哔叽 (vải len bib). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vải len, đồ dệt bằng lông", "Hạng Tần Suất (Jun Da)": "5378.0", "Tần Suất % (Jun Da)": "99.9524769558", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 毕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口毕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哔", "Unihan_Traditional (Chữ Phồn thể)": "嗶", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ tượng thanh | 象声词 | Thường dùng trong từ ghép chỉ loại vải len hoặc làm từ mô phỏng âm thanh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('屙', '{"9000": "5379.0", "Chữ Trung Quốc": "屙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 尸 | Số nét | 10 | nét | 尸 | thi | biểu nghĩa | thân xác, thân thể | 阿 | a | biểu âm | 屙 = 尸 (Thi, biểu nghĩa: thân xác/cơ thể) + 阿 (A, biểu âm); chữ hình thanh. Bộ 尸 ở đây đại diện cho cơ thể người, 阿 cung cấp âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 屙 = 尸 (thi: thân xác) + 阿 (a: âm); chữ hình thanh — thân xác (尸) kêu ''a!'' khi đau bụng phải bài tiết. | Gương Hán-Việt | 屙 chưa có từ Hán-Việt phổ biến, dùng trong phương ngữ TQ | Mở khoá kiến thức | Biết 屙 giúp hiểu từ phương ngữ 屙屎 (đi đại tiện), 屙尿 (đi tiểu) trong tiếng Quảng Đông và miền Nam TQ.", "Tự nguyên_Xie": "Wiktionary ghi 屙 là chữ hình thanh: 尸 (thi, biểu nghĩa: thân thể) + 阿 (a, biểu âm, không đọc OCM). Chữ mang nghĩa tiêu chảy, bài tiết — liên quan đến chức năng sinh lý của cơ thể. Không có hình ảnh glyph cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ốm nặng", "Hạng Tần Suất (Jun Da)": "5379.0", "Tần Suất % (Jun Da)": "99.9525394868", "GavinGrover_Once (Chiết tự trực tiếp)": "尸 + 阿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴尸阿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "尸", "Unihan_Simplified (Chữ Giản thể)": "屙", "Unihan_Traditional (Chữ Phồn thể)": "屙", "Pinyin_Xie": "ē", "Âm Hán Việt_Xie": "a", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong khẩu ngữ để chỉ hoạt động bài tiết của cơ thể. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('旆', '{"9000": "5380.0", "Chữ Trung Quốc": "旆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 方 | Số nét | 10 | nét | 㫃 | biểu nghĩa | cờ hiệu, dải cờ | 旆 có lsCodes là psc, gồm 㫃 (biểu nghĩa: cờ hiệu) và một thành phần biểu âm 𣎵 (theo Wiktionary). Chữ hình thanh chỉ loại cờ có tua đuôi én ở dưới — cờ lễ nghi thời cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 旆 có bộ 㫃 (cờ hiệu) — hình ảnh lá cờ đuôi én phần phật trong gió khi đoàn quân xuất chinh, âm pèi gợi tiếng vải phần phật. | Gương Hán-Việt | 旆 chưa có từ Hán-Việt quen dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 旆 giúp đọc thơ văn cổ điển về chiến trận — 前旆 (tiền bái: cờ đầu đoàn quân), 酒旆 (tửu bái: cờ hiệu quán rượu).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 旆 là chữ hình thanh: 㫃 (biểu nghĩa: cờ hiệu) + 𣎵 (biểu âm). Chữ chỉ loại ''banner'' có tua đuôi én (swallowtail ornament) treo phía dưới — cờ lễ nghi trong quân đội và triều đình cổ đại. Cũng dùng chỉ cờ hiệu nói chung. Có hình tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cờ bái (cắm trên xe hoặc thuyền khi đi xa)", "Hạng Tần Suất (Jun Da)": "5380.0", "Tần Suất % (Jun Da)": "99.9526020178", "GavinGrover_Once (Chiết tự trực tiếp)": "方 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰方", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "旆", "Unihan_Traditional (Chữ Phồn thể)": "旆", "Pinyin_Xie": "pèi", "Âm Hán Việt_Xie": "bái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn thơ cổ để chỉ các loại cờ hiệu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佰', '{"9000": "5381.0", "Chữ Trung Quốc": "佰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 亻 | biểu nghĩa | người | 百 | bách | biểu âm | 佰 = 亻 (nhân, biểu nghĩa: người) + 百 (Bách, biểu âm); chữ hình thanh. Thành phần 亻 gợi ý người đứng đầu một đơn vị 100 quân, 百 vừa cung cấp âm vừa gợi nghĩa ''trăm''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 佰 = 亻 (người) + 百 (bách: trăm); chữ hình thanh — người đứng đầu một trăm quân lính; chữ ''trăm'' dùng trong tài chính để khó giả mạo. | Gương Hán-Việt | 佰 thay thế cho 百 trong văn bản tài chính/pháp lý TQ | Mở khoá kiến thức | Biết 佰 giúp đọc séc ngân hàng và văn bản pháp lý TQ — 仟佰 (nghìn trăm) dùng thay 千百.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 佰 là chữ hình thanh: 亻 (nhân, biểu nghĩa: người) + 百 (bách, biểu âm). Chữ có hai nghĩa chính: (1) dạng tài chính của 百 (trăm) — dùng trong văn bản kế toán để chống làm giả; (2) chỉ huy/chỉ huy 100 lính (centurion) thời cổ. Có hình tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trăm, 100; rất nhiều", "Hạng Tần Suất (Jun Da)": "5381.0", "Tần Suất % (Jun Da)": "99.9526645488", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 百", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻百", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "百", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "佰", "Unihan_Traditional (Chữ Phồn thể)": "佰", "Pinyin_Xie": "bǎi", "Âm Hán Việt_Xie": "bách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Số từ | 数词 | Chữ này dùng làm số từ trong các văn bản tài chính để tránh việc tẩy xóa sửa đổi số liệu. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('僦', '{"9000": "5382.0", "Chữ Trung Quốc": "僦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 14 | nét | 僦 | tượng hình | thuê, mướn | 僦 không có dữ liệu cấu trúc CHISE. Bộ 人 (nhân: người) gợi ý quan hệ giao dịch giữa người với người. Wiktionary ghi là từ văn ngôn chỉ việc thuê mướn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 僦 có bộ 人 (người) — hình ảnh người đứng trước căn nhà trả tiền cho chủ nhà để thuê ở — 僦屋 (thuê nhà) trong văn ngôn. | Gương Hán-Việt | 僦 chưa có từ Hán-Việt quen dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 僦 giúp đọc văn bản lịch sử về kinh tế TQ — 僦屋 (thuê nhà), 僦舍 (thuê phòng), 僦费 (tiền thuê).", "Tự nguyên_Xie": "Wiktionary ghi 僦 là từ văn ngôn: (1) thuê/mướn (nhà, xe, dịch vụ); (2) tiền thuê (rental payment). Dùng trong các từ như 僦屋 (thuê nhà), 僦居 (thuê chỗ ở). Bộ 人 (người) phản ánh quan hệ giao dịch. Không có hình ảnh glyph cổ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thuê, mướn", "Hạng Tần Suất (Jun Da)": "5382.0", "Tần Suất % (Jun Da)": "99.9527270798", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 就", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻就", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "就", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "僦", "Unihan_Traditional (Chữ Phồn thể)": "僦", "Pinyin_Xie": "jiù", "Âm Hán Việt_Xie": "tựu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị hành động thuê hoặc mướn nhà cửa, xe cộ trong văn ngôn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('牯', '{"9000": "5383.0", "Chữ Trung Quốc": "牯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 牛 | Số nét | 9 | nét | 牛 | ngưu | biểu nghĩa | bò | 古 | cổ | biểu âm | 牯 = 牛 (Ngưu, biểu nghĩa: bò) + 古 (Cổ, biểu âm); chữ hình thanh. Thành phần 牛 cho biết đây là con bò, 古 cung cấp âm đọc gần với gǔ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 牯 = 牛 (ngưu: bò) + 古 (cổ: xưa); chữ hình thanh — con bò đực cổ xưa trên ruộng đồng, vững chắc như chữ 古 (cổ). | Gương Hán-Việt | 牯 chưa có từ Hán-Việt quen dùng, thường gặp trong địa danh TQ | Mở khoá kiến thức | Biết 牯 giúp nhận diện địa danh 牯岭 (Cô Lĩnh) — khu nghỉ dưỡng nổi tiếng ở Lư Sơn.", "Tự nguyên_Xie": "Wiktionary ghi 牯 là chữ hình thanh: 牛 (ngưu, biểu nghĩa: bò) + 古 (cổ, biểu âm). Chữ chỉ con bò đực hoặc bò nói chung (có nơi dùng chỉ bò cái). Phổ biến trong địa danh như 牯岭 (Cô Lĩnh — địa danh nổi tiếng ở Lư Sơn, Giang Tây). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con bò đực", "Hạng Tần Suất (Jun Da)": "5383.0", "Tần Suất % (Jun Da)": "99.9527896108", "GavinGrover_Once (Chiết tự trực tiếp)": "牛 + 古", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰牛古", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "古", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "牛", "Unihan_Simplified (Chữ Giản thể)": "牯", "Unihan_Traditional (Chữ Phồn thể)": "牯", "Pinyin_Xie": "gǔ", "Âm Hán Việt_Xie": "cổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường kết hợp với các từ khác để chỉ gia súc giống đực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钪', '{"9000": "5384.0", "Chữ Trung Quốc": "钪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 钪 | tượng hình | nguyên tố scandi | 钪 không có dữ liệu cấu trúc CHISE và không có nguồn Wiktionary. Bộ 金 (kim: kim loại) xác nhận đây là tên nguyên tố kim loại. Chữ tạo muộn để phiên âm tên khoa học.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 钪 có bộ 金 (kim loại) — nguyên tố scandi, kim loại hiếm dùng trong đèn metal-halide và hợp kim nhôm công nghệ cao. | Gương Hán-Việt | 钪 chưa có từ Hán-Việt quen dùng, chỉ dùng trong hóa học | Mở khoá kiến thức | Biết 钪 giúp đọc bảng tuần hoàn tiếng Trung — 钪 (Sc, scandi) kim loại đất hiếm nhẹ.", "Tự nguyên_Xie": "Chưa có nguồn học thuật. 钪 là chữ tạo muộn để phiên âm tên nguyên tố Scandium (Sc, số nguyên tử 21). Bộ 金 (kim loại) xác nhận là kim loại. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố scandi, Sc", "Hạng Tần Suất (Jun Da)": "5384.0", "Tần Suất % (Jun Da)": "99.9528521418", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 亢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅亢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钪", "Unihan_Traditional (Chữ Phồn thể)": "鈧", "Pinyin_Xie": "kàng", "Âm Hán Việt_Xie": "kháng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chuyên ngành hóa học để chỉ nguyên tố kim loại scandi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掾', '{"9000": "5385.0", "Chữ Trung Quốc": "掾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 掾 | tượng hình | chức quan phó, thuộc lại | 掾 không có dữ liệu cấu trúc CHISE. Bộ 手 (thủ: tay) gợi ý người thực thi công việc bằng tay — viên chức xử lý giấy tờ hành chính. Wiktionary chỉ ghi định nghĩa chung.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 掾 có bộ 手 (tay) — viên chức dùng đôi tay xử lý giấy tờ, thuộc lại giúp việc cho quan trên — 掾吏 (thuộc lại). | Gương Hán-Việt | 掾 liên quan đến 掾吏 (duyện lại: thuộc lại hành chính cổ đại) | Mở khoá kiến thức | Biết 掾 giúp đọc văn bản lịch sử hành chính TQ — 掾吏 (thuộc lại), 掾属 (nhân viên phụ tá).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 掾 là danh xưng chung cho các quan chức cấp dưới, thư ký hành chính trong hệ thống quan liêu Trung Hoa cổ đại. Bộ 手 (tay) gợi ý người làm việc tay chân hành chính. Có hình tiểu triện và lục thư thông. Không rõ cấu trúc chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chức quan phó", "Hạng Tần Suất (Jun Da)": "5385.0", "Tần Suất % (Jun Da)": "99.9529146728", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 彖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌彖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "掾", "Unihan_Traditional (Chữ Phồn thể)": "掾", "Pinyin_Xie": "yuàn", "Âm Hán Việt_Xie": "duyện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ chức vụ trợ lý hoặc cấp dưới của quan lại thời phong kiến. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('仟', '{"9000": "5386.0", "Chữ Trung Quốc": "仟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 5 | nét | 仟 | tượng hình | nghìn, 1000 | 仟 không có dữ liệu cấu trúc CHISE. Wiktionary ghi là dạng tài chính của 千 (nghìn), cấu trúc tương tự 佰 (trăm). Bộ 人 (nhân) kết hợp với âm 千 — người đứng đầu nghìn quân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 仟 có bộ 人 (người) — người đứng đầu một nghìn quân lính; cũng là chữ ''nghìn'' dùng trên séc ngân hàng để không bị sửa thành 干 hay 千. | Gương Hán-Việt | 仟 thay thế cho 千 trong văn bản tài chính/pháp lý TQ | Mở khoá kiến thức | Biết 仟 giúp đọc séc ngân hàng TQ — 仟佰拾 (nghìn trăm mười) thay cho 千百十.", "Tự nguyên_Xie": "Wiktionary ghi 仟 là: (1) chỉ huy 1000 lính thời cổ; (2) dạng tài chính của 千 (nghìn) dùng trong văn bản kế toán; (3) dạng cổ của 阡 (đường bờ ruộng). Bộ 人 (người) kết hợp với âm nghìn. Không có hình ảnh glyph cổ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghìn, 1000", "Hạng Tần Suất (Jun Da)": "5386.0", "Tần Suất % (Jun Da)": "99.953039218", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 千", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻千", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "千", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "仟", "Unihan_Traditional (Chữ Phồn thể)": "仟", "Pinyin_Xie": "qiān", "Âm Hán Việt_Xie": "thiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Số từ | 数词 | Chữ này làm số từ dùng trong ngân hàng và hóa đơn để biểu thị số một nghìn nhằm chống gian lận. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('圮', '{"9000": "5387.0", "Chữ Trung Quốc": "圮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 6 | nét | 圮 | dãy | tượng hình | đổ nát, sụp đổ | 圮 không có dữ liệu cấu trúc CHISE. Wiktionary ghi là từ văn ngôn chỉ sự sụp đổ, hủy hoại. Bộ 土 (thổ: đất) gợi ý công trình đất/đá bị sụp đổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dãy\": 圮 có bộ 土 (đất) — hình ảnh tường đất bị ''dãy'' ra, đổ sụp, hoang phế — 頹圮 (tui dãy: hoang tàn đổ nát). | Gương Hán-Việt | dãy trong ''đổ dãy'' — dạng cổ, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 圮 giúp đọc văn học cổ TQ — 頹圮 (đổ nát), 圮地 (địa thế hiểm nghèo trong Tôn Tử Binh Pháp).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 圮 (âm pǐ) mang nghĩa phá hủy, sụp đổ. Dùng trong thành ngữ 頹圮 (đổ nát), 圮地 (vùng đất xấu — trong Binh pháp Tôn Tử). Có hình tiểu triện. Bộ 土 (đất) xác nhận liên quan đến công trình/địa vật. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đổ nát", "Hạng Tần Suất (Jun Da)": "5387.0", "Tần Suất % (Jun Da)": "99.9531012322", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 己", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土己", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "己", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "圮", "Unihan_Traditional (Chữ Phồn thể)": "圮", "Pinyin_Xie": "pǐ", "Âm Hán Việt_Xie": "bĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ hoặc tính từ để miêu tả trạng thái sụp đổ, hoang tàn của công trình xây dựng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芟', '{"9000": "5388.0", "Chữ Trung Quốc": "芟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 芟 | sam | tượng hình | cắt cỏ, cái liềm | 芟 không có dữ liệu cấu trúc CHISE rõ ràng. Bộ 艸 (thảo: cỏ) xác nhận liên quan đến thực vật. Có hình giáp cốt văn và tiểu triện, gợi ý là chữ cổ. Wiktionary không rõ cấu trúc hình thành.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sam\": 芟 có bộ 艸 (cỏ) — hình ảnh người cầm liềm (芟) gặt cỏ hoang, dọn dẹp cánh đồng. Nhớ: SAM = cắt, SAM cỏ đi. | Gương Hán-Việt | sam trong ''phát sam'' — nghĩa là phát quang, phát cỏ (ít dùng trong tiếng Việt hiện đại) | Mở khoá kiến thức | Biết 芟 giúp đọc văn ngôn — 芟除 (diệt trừ), 芟夷 (tiêu diệt), 芟繁就簡 (rút gọn, giản lược).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Wiktionary ghi 芟 (âm shān) mang nghĩa cắt cỏ, phát quang, loại bỏ. Có hình giáp cốt văn và tiểu triện. Bộ 艸 (cỏ) xác nhận liên quan đến thực vật. Từ ghép quan trọng: 芟除 (diệt trừ), 芟繁就簡 (bỏ phức tạp giữ đơn giản). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cắt cỏ; cái liềm", "Hạng Tần Suất (Jun Da)": "5388.0", "Tần Suất % (Jun Da)": "99.9531632465", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 殳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹殳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "殳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芟", "Unihan_Traditional (Chữ Phồn thể)": "芟", "Pinyin_Xie": "shān", "Âm Hán Việt_Xie": "sam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị hành động phát quang cỏ dại hoặc tiêu diệt, loại bỏ tận gốc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('崃', '{"9000": "5389.0", "Chữ Trung Quốc": "崃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 10 | nét | 崃 | tượng hình | núi Lai (Tứ Xuyên) | 崃 không có dữ liệu cấu trúc CHISE. Bộ 山 (sơn: núi) xác nhận đây là tên địa danh núi. Wiktionary không cung cấp cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 崃 có bộ 山 (sơn: núi) — tên dãy núi 邛崃 (Cùng Lai) ở Tứ Xuyên, ranh giới giữa bình nguyên Thành Đô và cao nguyên Tây Tạng. | Gương Hán-Việt | 崃 chỉ dùng trong địa danh 邛崃 — không có từ Hán-Việt độc lập | Mở khoá kiến thức | Biết 崃 giúp đọc địa lý TQ — 邛崃山 là dãy núi quan trọng nối Tứ Xuyên với Tây Tạng.", "Tự nguyên_Xie": "Wiktionary ghi 崃 (dạng truyền thống 崍, âm lái) chủ yếu dùng trong địa danh 邛崃山 và 邛崃縣 ở tỉnh Tứ Xuyên. Bộ 山 (núi) xác nhận là tên núi. Chữ khá chuyên biệt, dùng trong địa danh hành chính. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "núi Lai (ở tỉnh Tứ Xuyên của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "5389.0", "Tần Suất % (Jun Da)": "99.9532252607", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 来", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山来", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "来", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "崃", "Unihan_Traditional (Chữ Phồn thể)": "崍", "Pinyin_Xie": "lái", "Âm Hán Việt_Xie": "lai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng dùng trong địa danh để chỉ dãy núi Quỳnh Lai ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('廪', '{"9000": "5390.0", "Chữ Trung Quốc": "廪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 16 | nét | 广 | nghiễm | biểu nghĩa | nhà, mái che | 㐭 | biểu âm | kho thóc | 禾 | biểu nghĩa | lúa | 廪 = 广 (Nghiễm, biểu nghĩa: mái nhà/công trình) + 禾 (biểu nghĩa: lúa) + 㐭 (biểu âm: kho thóc); chữ hội ý. Ba thành phần kết hợp: mái nhà (广) chứa lúa (禾) trong kho (㐭) — tạo thành hình tượng vựa thóc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 廪 = 广 (nhà) + 禾 (lúa) + 㐭 (kho); chữ hội ý — ngôi nhà (广) chứa đầy lúa (禾) — đó chính là vựa thóc của triều đình cấp lương cho quan lại. | Gương Hán-Việt | lẫm trong ''thương lẫm'' — kho thóc, vựa lương thực (ít dùng tiếng Việt hiện đại) | Mở khoá kiến thức | Biết 廪 giúp đọc sử TQ — 倉廩 (thương lẫm: kho thóc nhà nước), 廩生 (lẫm sinh: học sinh được cấp lương thực).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary ghi 廪 (dạng truyền thống 廩) ban đầu viết là 㐭, sau phát triển thành chữ hội ý: 广 (mái nhà) + 㐭 (kho thóc, biểu âm lẫn biểu nghĩa) + 禾 (lúa). Nghĩa: vựa thóc, đặc biệt là kho gạo; lương thực triều đình cấp phát. Có hình đại triện và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vựa thóc; kho đụn; cấp cho, phát cho", "Hạng Tần Suất (Jun Da)": "5390.0", "Tần Suất % (Jun Da)": "99.9532872749", "GavinGrover_Once (Chiết tự trực tiếp)": "广 + 禀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴广禀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "广", "Unihan_Simplified (Chữ Giản thể)": "廪", "Unihan_Traditional (Chữ Phồn thể)": "廩", "Pinyin_Xie": "lǐn", "Âm Hán Việt_Xie": "lẫm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ kho chứa lương thực của nhà nước hoặc làm động từ chỉ việc cấp phát lương bổng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('擘', '{"9000": "5391.0", "Chữ Trung Quốc": "擘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 17 | nét | 辟 | tích | biểu âm | 手 | thủ | biểu nghĩa | tay | 擘 = 辟 (Tích, biểu âm) + 手 (Thủ, biểu nghĩa: tay); chữ hình thanh. Thành phần 手 cho biết liên quan đến hành động của tay, 辟 cung cấp âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 擘 = 辟 (âm) + 手 (thủ: tay); chữ hình thanh — ngón tay cái (擘) dùng để bẻ (bāi) tách hai vật ra — mạnh nhất trong năm ngón tay. | Gương Hán-Việt | 擘 chưa có từ Hán-Việt quen dùng trong tiếng Việt | Mở khoá kiến thức | Biết 擘 giúp đọc y học TQ — 擘指 (ngón cái), 巨擘 (cự bách: người xuất sắc nhất trong lĩnh vực).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 擘 là chữ hình thanh: 辟 (tích, biểu âm) + 手 (thủ, biểu nghĩa: tay). Chữ có nghĩa ngón tay cái; và động từ bẻ, xé, tách ra. Có hình tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bẻ, tẽ, tách ra, bửa ra", "Hạng Tần Suất (Jun Da)": "5391.0", "Tần Suất % (Jun Da)": "99.9533492891", "GavinGrover_Once (Chiết tự trực tiếp)": "辟 + 手", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱辟手", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "手", "Unihan_Simplified (Chữ Giản thể)": "擘", "Unihan_Traditional (Chữ Phồn thể)": "擘", "Pinyin_Xie": "bāi", "Âm Hán Việt_Xie": "phách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động dùng tay bẻ, tẽ hoặc phân chia sự vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笱', '{"9000": "5392.0", "Chữ Trung Quốc": "笱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 竹 | trúc | biểu nghĩa | tre | 句 | câu | biểu âm | 笱 = 竹 (Trúc, biểu nghĩa: tre) + 句 (Câu, biểu âm); chữ hình thanh. Thành phần 竹 xác nhận đây là vật dụng làm bằng tre, 句 cung cấp âm đọc gần với gǒu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"càu\": 笱 = 竹 (trúc: tre) + 句 (câu: móc); chữ hình thanh — cái đó tre hình móc câu (句), đặt ở đập nước để bẫy cá — cá vào không ra được. | Gương Hán-Việt | càu trong ''đó càu'' — loại dụng cụ bắt cá bằng tre ít còn dùng trong tiếng Việt | Mở khoá kiến thức | Biết 笱 giúp đọc thơ kinh điển TQ — 鱼笱 (ngư càu: cái đó cá) xuất hiện trong Kinh Thi.", "Tự nguyên_Xie": "Bạch thư | Đại triện | Tiểu triện | Wiktionary ghi 笱 là chữ hình thanh: 竹 (trúc, biểu nghĩa: tre) + 句 (câu, biểu âm). Chữ chỉ cái đó — bẫy cá hình rọ bằng tre, đặt ở miệng đập nước để cá bơi vào nhưng không ra được. Có hình bạch thư (lụa), đại triện và tiểu triện — chữ cổ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái đó (để bắt cá)", "Hạng Tần Suất (Jun Da)": "5392.0", "Tần Suất % (Jun Da)": "99.9534113033", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 句", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮句", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笱", "Unihan_Traditional (Chữ Phồn thể)": "笱", "Pinyin_Xie": "gǒu", "Âm Hán Việt_Xie": "cẩu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại dụng cụ đánh bắt cá bằng tre của người xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跗', '{"9000": "5393.0", "Chữ Trung Quốc": "跗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 12 | nét | 跗 | tượng hình | mu bàn chân, cổ chân | 跗 không có dữ liệu cấu trúc CHISE. Bộ 足 (túc: chân) xác nhận liên quan đến chân. Wiktionary chỉ ghi định nghĩa không có cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 跗 có bộ 足 (túc: chân) — phần mu bàn chân (跗) nằm trên mặt trên của bàn chân, nơi gắn với cổ chân. | Gương Hán-Việt | 跗 chưa có từ Hán-Việt quen dùng, chủ yếu trong giải phẫu học | Mở khoá kiến thức | Biết 跗 giúp đọc văn bản y học TQ — 跗骨 (xương cổ chân), 跗关节 (khớp cổ chân), 跗面 (mu bàn chân).", "Tự nguyên_Xie": "Wiktionary ghi 跗 (âm fū) chỉ mu bàn chân (instep), cổ bàn chân. Dùng trong y học/giải phẫu: 跗骨 (xương cổ chân), 跗关节 (khớp cổ chân). Bộ 足 (chân) xác nhận liên quan đến giải phẫu bàn chân. Khả năng là chữ hình thanh với 足 (biểu nghĩa) và phần còn lại (biểu âm). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mu bàn chân", "Hạng Tần Suất (Jun Da)": "5393.0", "Tần Suất % (Jun Da)": "99.9534733175", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 付", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊付", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "付", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跗", "Unihan_Traditional (Chữ Phồn thể)": "跗", "Pinyin_Xie": "fū", "Âm Hán Việt_Xie": "phụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận mu bàn chân hoặc đài hoa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲅', '{"9000": "5394.0", "Chữ Trung Quốc": "鲅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 13 | nét | 鲅 | tượng hình | cá thu tây ban nha | 鲅 không có dữ liệu cấu trúc CHISE. Bộ 魚 (ngư: cá) xác nhận đây là tên loài cá. Wiktionary dùng dạng truyền thống 鮁.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 鲅 có bộ 魚 (cá) — cá thu 鲅鱼 (bá ngư) là loài cá biển to, thịt chắc, phổ biến ở vùng biển Bắc Trung Quốc. | Gương Hán-Việt | 鲅 chưa có từ Hán-Việt quen dùng, chủ yếu trong ngữ cảnh ẩm thực TQ | Mở khoá kiến thức | Biết 鲅 giúp đọc thực đơn và văn bản thủy sản TQ — 鲅鱼 (bá ngư: cá thu) là nguyên liệu quan trọng ở Thanh Đảo, Đại Liên.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 鲅 (dạng truyền thống 鮁, âm bà) chỉ cá thu Tây Ban Nha (Spanish mackerel). Có nghĩa thứ hai là 鮁鮁 — miêu tả cá vẫy đuôi bơi. Có hình tiểu triện. Bộ 魚 (cá) xác nhận là tên loài cá biển. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem 鮁魚", "Hạng Tần Suất (Jun Da)": "5394.0", "Tần Suất % (Jun Da)": "99.9535353318", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 犮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼犮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲅", "Unihan_Traditional (Chữ Phồn thể)": "鮁", "Pinyin_Xie": "bà", "Âm Hán Việt_Xie": "bát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ trong tên gọi cá thu hoặc động từ chỉ dáng cá nhảy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硷', '{"9000": "5395.0", "Chữ Trung Quốc": "硷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 12 | nét | 硷 | tượng hình | chất kiềm, bazơ | 硷 là chữ giản thể của 礆, đơn giản hóa thành phần 僉→佥. Không có dữ liệu cấu trúc CHISE. Bộ 石 (thạch: đá/khoáng chất) gợi ý liên quan đến chất khoáng/hóa học.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 硷 có bộ 石 (thạch: đá/khoáng) — chất kiềm khai thác từ khoáng chất, dùng giặt giũ và làm xà phòng — đối lập với 酸 (toan: axit). | Gương Hán-Việt | 硷 liên quan đến 碱性 (kiềm tính) trong hóa học — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 硷 giúp đọc văn bản hóa học TQ — 碱性 (kiềm tính), 碱土 (đất kiềm), 纯碱 (soda).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 硷 là chữ giản thể của 礆 (đơn giản hóa 僉→佥). Chữ chỉ chất kiềm, bazơ — muối hoặc oxit kim loại có tính kiềm. Bộ 石 (khoáng chất) phản ánh nguồn gốc khai thác từ đất/khoáng. Có hình tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chất kiềm, chất dảm (trong đất, như xà phòng, dùng để giặt), bazơ", "Hạng Tần Suất (Jun Da)": "5395.0", "Tần Suất % (Jun Da)": "99.9535968292", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 佥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石佥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "佥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硷", "Unihan_Traditional (Chữ Phồn thể)": "礆", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "dảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ hợp chất hóa học có tính kiềm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苎', '{"9000": "5396.0", "Chữ Trung Quốc": "苎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 苎 | tượng hình | cây gai, sợi gai | 苎 là chữ giản thể của 苧, đơn giản hóa thành phần 丁→一. Bộ 艸 (thảo: cỏ/thực vật) xác nhận đây là tên cây. Wiktionary ghi là dị thể của 苧 (ramie — cây gai dầu).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 苎 có bộ 艸 (cỏ) — cây gai trắng (苎麻) cho sợi dai như dây, dùng dệt vải mùa hè mát mẻ. Nhớ: cây gai mà sợi đẹp. | Gương Hán-Việt | 苎 liên quan đến vải gai (cây ramie) — tiếng Việt gọi là ''gai trắng'' hay ''lanh Trung Quốc'' | Mở khoá kiến thức | Biết 苎 giúp đọc văn bản dệt may TQ — 苎麻 (trữ ma: cây gai trắng/ramie), sợi tự nhiên bền và mát.", "Tự nguyên_Xie": "Wiktionary ghi 苎 là giản thể của 苧, chỉ cây ramie (Boehmeria nivea) — cây gai trắng cho sợi bền, dùng dệt vải từ thời cổ đại TQ. Bộ 艸 (thực vật) xác nhận là tên cây. Chữ tạo muộn, không có hình ảnh cổ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Còn viết là: 苎麻; cây gai; sợi gai", "Hạng Tần Suất (Jun Da)": "5396.0", "Tần Suất % (Jun Da)": "99.9536583266", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 㝉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹㝉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㝉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苎", "Unihan_Traditional (Chữ Phồn thể)": "苧", "Pinyin_Xie": "zhù", "Âm Hán Việt_Xie": "trữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cây gai hoặc sợi gai dùng để dệt vải thô. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('匏', '{"9000": "5397.0", "Chữ Trung Quốc": "匏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 勹 | Số nét | 11 | nét | 匏 | bầu | tượng hình | quả bầu | 匏 không có dữ liệu cấu trúc CHISE. Wiktionary chỉ ghi {{Han etym}} không rõ chi tiết. Bộ 勹 (bão) và hình dáng tổng thể gợi ý hình ảnh quả bầu tròn. Có hình tiểu triện và lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bầu\": 匏 — quả bầu tròn trĩnh, trống rỗng khi khô — âm bầu trong tiếng Việt trùng Hán-Việt, dễ nhớ. Bầu khô làm nhạc cụ sênh trong bát âm cổ đại. | Gương Hán-Việt | bầu trong 匏音 — âm nhạc từ bầu khô trong bát âm cổ đại | Mở khoá kiến thức | Biết 匏 giúp đọc văn học cổ TQ — 匏爵 (chén uống rượu bằng bầu), 匏瓜 (quả bầu), 匏音 (nhạc bầu).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary chỉ ghi {{Han etym}} không chi tiết. Chữ 匏 chỉ quả bầu (bottle gourd) và nhạc cụ làm từ bầu khô (trong bát âm: sênh làm từ bầu). Có hình tiểu triện và lục thư thông. Bộ 勹 gợi hình dạng cong của quả bầu. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quả bầu", "Hạng Tần Suất (Jun Da)": "5397.0", "Tần Suất % (Jun Da)": "99.9537198241", "GavinGrover_Once (Chiết tự trực tiếp)": "夸 + 包", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰夸包", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "包", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "夸", "Unihan_Simplified (Chữ Giản thể)": "匏", "Unihan_Traditional (Chữ Phồn thể)": "匏", "Pinyin_Xie": "páo", "Âm Hán Việt_Xie": "bào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ quả bầu khô hoặc loại nhạc cụ cổ làm từ quả bầu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗾', '{"9000": "5398.0", "Chữ Trung Quốc": "嗾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 14 | nét | 嗾 | tượng hình | xuýt chó, kích động | 嗾 không có dữ liệu cấu trúc CHISE. Bộ 口 (khẩu: miệng) gợi ý liên quan đến âm thanh hoặc lời nói. Wiktionary ghi là từ chỉ hành động dùng lời xúi giục, kích động.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 嗾 có bộ 口 (miệng) — tiếng xuýt của người kích động chó xông vào kẻ thù; từ đó mở rộng thành ''xúi bẩy'' người khác làm điều xấu. | Gương Hán-Việt | 嗾 chưa có từ Hán-Việt quen dùng trong tiếng Việt | Mở khoá kiến thức | Biết 嗾 giúp đọc văn ngôn — 指嗾 (chỉ tẩu: xúi giục), 嗾使 (tẩu sử: sai khiến người khác làm điều xấu).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 嗾 (âm sǒu) mang nghĩa xuýt (dùng tiếng để xúi chó tấn công), kích động, xúi bẩy. Dùng trong thành ngữ 指嗾 (xúi giục), 嗾使 (sai khiến). Bộ 口 (miệng) phản ánh việc dùng lời để điều khiển người/vật khác. Có hình tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xuýt, huýt, xuỵt; khuyến khích, thúc giục", "Hạng Tần Suất (Jun Da)": "5398.0", "Tần Suất % (Jun Da)": "99.9537813215", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 族", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口族", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "族", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗾", "Unihan_Traditional (Chữ Phồn thể)": "嗾", "Pinyin_Xie": "sǒu", "Âm Hán Việt_Xie": "thốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị hành động xúi giục hoặc ra lệnh cho chó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('圄', '{"9000": "5399.0", "Chữ Trung Quốc": "圄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 囗 | Số nét | 10 | nét | 囗 | biểu nghĩa | vây quanh, bao bọc | 吾 | ngô | biểu âm | 圄 = 囗 (vi: vây bọc, biểu nghĩa: hàng rào/vây quanh) + 吾 (Ngô, biểu âm); chữ hình thanh. Thành phần 囗 (hàng rào bao quanh) chỉ nơi giam cầm, 吾 cung cấp âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 圄 = 囗 (vây bọc) + 吾 (ngô: ta/tôi); chữ hình thanh — ''ta'' bị vây bọc bốn phía — đó là nhà tù, không thoát ra được. | Gương Hán-Việt | ngự trong 囹圄 (linh ngự: nhà giam) — từ văn ngôn chỉ tù ngục | Mở khoá kiến thức | Biết 圄 giúp đọc văn ngôn — 囹圄 (linh ngự: ngục tù), 草滿囹圄 (cỏ mọc đầy nhà giam — ý chỉ xã hội thái bình không ai phạm tội).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 圄 là chữ hình thanh: 囗 (vi, biểu nghĩa: bao vây/hàng rào) + 吾 (ngô, biểu âm). Chữ chỉ nhà tù, nơi giam cầm. Thường dùng trong thành ngữ 囹圄 (linh ngữ: nhà giam, ngục tù). Cũng có nghĩa: nhốt vào tù, người chăn ngựa/giữ ngựa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: linh ngữ 囹圄)", "Hạng Tần Suất (Jun Da)": "5399.0", "Tần Suất % (Jun Da)": "99.9538428189", "GavinGrover_Once (Chiết tự trực tiếp)": "囗 + 吾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Bao quanh toàn bộ)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴囗吾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "囗", "Unihan_Simplified (Chữ Giản thể)": "圄", "Unihan_Traditional (Chữ Phồn thể)": "圄", "Pinyin_Xie": "yǔ", "Âm Hán Việt_Xie": "ngữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ nhà giam hoặc động từ với nghĩa giam giữ, hạn chế tự do. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('彀', '{"9000": "5400.0", "Chữ Trung Quốc": "彀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 弓 | Số nét | 13 | nét | 彀 | tượng hình | kéo cung đủ độ, đích cung | 彀 không có dữ liệu cấu trúc CHISE. Bộ 弓 (cung: cây cung) gợi ý liên quan đến cung tên. Wiktionary ghi là từ văn ngôn chỉ hành động kéo cung đến mức đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 彀 có bộ 弓 (cung tên) — kéo căng cây cung đến mức tối đa trước khi nhả — từ đó sinh nghĩa ''đủ/đạt đến mức cần thiết''; 英雄入彀 = anh hùng sa vào bẫy. | Gương Hán-Việt | 彀 chưa có từ Hán-Việt quen dùng trong tiếng Việt | Mở khoá kiến thức | Biết 彀 giúp đọc văn ngôn — 彀中 (bẫy, trong tầm tay), 入彀 (sa bẫy), 英雄入彀 (anh hùng lọt vào bẫy).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 彀 (âm gòu) mang nghĩa: kéo cung đến mức tối đa; đích bắn; trường bắn; người bắn giỏi. Sau đó mở rộng thành ''đủ/đầy'' (alt form của 夠). Bộ 弓 (cung) xác nhận nguồn gốc liên quan đến cung tên. Có hình tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái đích cung (chỗ có khấc trên cung để dương dây)", "Hạng Tần Suất (Jun Da)": "5400.0", "Tần Suất % (Jun Da)": "99.9539043163", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 弓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴弓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "彀", "Unihan_Traditional (Chữ Phồn thể)": "彀", "Pinyin_Xie": "gòu", "Âm Hán Việt_Xie": "cấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm động từ chỉ việc giương cung hoặc tính từ chỉ sự đầy đủ, đạt yêu cầu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粳', '{"9000": "5401.0", "Chữ Trung Quốc": "粳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 13 | nét | 粳 | tượng hình | gạo tẻ, lúa tám | 粳 không có dữ liệu cấu trúc CHISE. Bộ 米 (mễ: gạo) xác nhận là loại thóc/gạo. Wiktionary ghi có cấu trúc nhưng không chi tiết. Khả năng là chữ hình thanh với 米 (biểu nghĩa) và phần biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 粳 có bộ 米 (gạo) — gạo tẻ (粳米: jīng mǐ), đối lập với gạo nếp (糯米: nuò mǐ). Nhớ: 粳 (cứng/tẻ) còn 糯 (mềm/dẻo/nếp). | Gương Hán-Việt | 粳 chưa có từ Hán-Việt quen dùng; tiếng Việt gọi là ''gạo tẻ'' | Mở khoá kiến thức | Biết 粳 giúp đọc nhãn thực phẩm TQ — 粳米 (gạo tẻ), 粳稻 (lúa tẻ), đối lập với 糯米 (gạo nếp).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 粳 (âm jīng/gēng) chỉ lúa gạo không nếp (non-glutinous rice). Bộ 米 (gạo) xác nhận là loại gạo. Phân biệt với 糯 (nuo: nếp/gạo nếp). Có hình tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lúa tám cánh ta", "Hạng Tần Suất (Jun Da)": "5401.0", "Tần Suất % (Jun Da)": "99.953965297", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 更", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米更", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "更", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粳", "Unihan_Traditional (Chữ Phồn thể)": "秔", "Pinyin_Xie": "jīng", "Âm Hán Việt_Xie": "canh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại lúa hoặc gạo tẻ hạt ngắn và dẻo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('卣', '{"9000": "5402.0", "Chữ Trung Quốc": "卣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 卜 | Số nét | 7 | nét | 卣 | tượng hình | đồ đựng rượu thời cổ | 卣 là chữ tượng hình (liushutong: p). Hình vẽ quả bầu hoặc bình có nắp đậy, dùng đựng rượu trong lễ tế. Thành phần bên trong từng được viết là 土 trong kim văn, sau bị sai lạc thành 仌 trong tiểu triện. Không liên quan đến 鹵.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 卣 là chữ tượng hình — hình chiếc bình rượu cổ có nắp, dùng trong lễ tế thần. Nhớ: 卣 trông như chiếc bình bầu tròn giữa hai nét dọc. | Gương Hán-Việt | 卣 chưa có từ Hán-Việt quen dùng, chủ yếu trong khảo cổ học | Mở khoá kiến thức | Biết 卣 giúp đọc tài liệu khảo cổ và bảo tàng TQ — 卣 là tên gọi loại đồ đồng quý trong bộ sưu tập thời Thương-Chu.", "Tự nguyên_Xie": "Giáp cốt văn | Lục thư thông | Wiktionary ghi 卣 là chữ tượng hình — hình vẽ chiếc bình đựng rượu có nắp. Thành phần trong biết trong kim văn là 土, sau bị biến dạng thành 仌 trong tiểu triện. Đây là loại đồ đựng rượu lễ tế thời Thương-Chu. Có hình giáp cốt văn phong phú. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ đựng rượu ngày xưa", "Hạng Tần Suất (Jun Da)": "5402.0", "Tần Suất % (Jun Da)": "99.9540262776", "GavinGrover_Once (Chiết tự trực tiếp)": "⺊ + 囙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺊囙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "囙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺊", "Unihan_Simplified (Chữ Giản thể)": "卣", "Unihan_Traditional (Chữ Phồn thể)": "卣", "Pinyin_Xie": "yǒu", "Âm Hán Việt_Xie": "dữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại bình đựng rượu tế lễ bằng đồng thời Thương Chu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('勐', '{"9000": "5403.0", "Chữ Trung Quốc": "勐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 力 | Số nét | 10 | nét | 孟 | mạnh | biểu âm | 力 | lực | biểu nghĩa | sức lực | 勐 = 孟 (Mạnh, biểu âm) + 力 (Lực, biểu nghĩa: sức mạnh); chữ hình thanh. Thành phần 力 cho biết liên quan đến quyền lực, 孟 cung cấp âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 勐 = 孟 (mạnh: âm) + 力 (lực: sức mạnh); chữ hình thanh — sức mạnh (力) của thủ lĩnh; 勐 trong địa danh Xishuangbanna nghĩa là vùng đất của lãnh chúa. | Gương Hán-Việt | 勐 chưa có từ Hán-Việt quen dùng, chủ yếu trong địa danh Vân Nam | Mở khoá kiến thức | Biết 勐 giúp đọc địa danh vùng Tây Song Bản Nạp — 勐腊 (Mạnh Lạp), 勐海 (Mạnh Hải: nổi tiếng với trà Phổ Nhĩ).", "Tự nguyên_Xie": "Wiktionary ghi 勐 là chữ hình thanh: 孟 (mạnh, biểu âm) + 力 (lực, biểu nghĩa). Chữ chỉ uy quyền lớn, có thẩm quyền. Chủ yếu dùng trong địa danh của Xishuangbanna — 勐 (měng) là từ tiếng Thái/Dai chỉ vùng đất cai trị của một lãnh chúa. Ví dụ: 勐腊 (Mạnh Lạp), 勐海 (Mạnh Hải). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "có uy quyền, uy lực lớn", "Hạng Tần Suất (Jun Da)": "5403.0", "Tần Suất % (Jun Da)": "99.9540872583", "GavinGrover_Once (Chiết tự trực tiếp)": "孟 + 力", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰孟力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "力", "Unihan_Simplified (Chữ Giản thể)": "勐", "Unihan_Traditional (Chữ Phồn thể)": "勐", "Pinyin_Xie": "měng", "Âm Hán Việt_Xie": "mãnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ sự dũng mãnh hoặc danh từ chỉ đơn vị hành chính mường bản ở vùng dân tộc thiểu số. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掴', '{"9000": "5404.0", "Chữ Trung Quốc": "掴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 手 | thủ | biểu nghĩa | tay | 國 | quốc | biểu âm | 掴 = 手 (Thủ, biểu nghĩa: tay) + 國 (Quốc, biểu âm); chữ hình thanh. Thành phần 手 cho biết là hành động của tay, 國 cung cấp âm đọc gần với guāi/guó.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 掴 = 手 (thủ: tay) + 國 (quốc: âm); chữ hình thanh — bàn tay (手) vung ra tát ''bốp'' vào mặt — âm guāi gợi tiếng tát. | Gương Hán-Việt | 掴 chưa có từ Hán-Việt quen dùng trong tiếng Việt | Mở khoá kiến thức | Biết 掴 giúp đọc văn bản mô tả hành động thể xác — 掴脸 (tát mặt), 掴耳光 (tát tai).", "Tự nguyên_Xie": "Wiktionary ghi 掴 (dạng truyền thống 摑) là chữ hình thanh: 手 (thủ, biểu nghĩa: tay) + 國 (quốc, biểu âm). Chữ chỉ hành động tát, bạt tai bằng lòng bàn tay. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đánh, bạt tai", "Hạng Tần Suất (Jun Da)": "5404.0", "Tần Suất % (Jun Da)": "99.9541482389", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 国", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌国", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "国", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "掴", "Unihan_Traditional (Chữ Phồn thể)": "摑", "Pinyin_Xie": "guāi", "Âm Hán Việt_Xie": "quặc, quách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ vị ngữ biểu thị hành động vỗ hoặc tát bằng lòng bàn tay. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涑', '{"9000": "5405.0", "Chữ Trung Quốc": "涑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 水 | thủy | biểu nghĩa | nước | 束 | thúc | biểu âm | 涑 = 水 (Thủy, biểu nghĩa: nước) + 束 (Thúc, biểu âm); chữ hình thanh. Thành phần 水 xác nhận đây là tên sông, 束 cung cấp âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa phổ biến: 涑 = 水 (thủy: nước) + 束 (thúc: bó/cuộn); chữ hình thanh — con sông (水) chảy mạnh cuộn cuộn như bó (束). 涑水 là quê hương của sử gia Tư Mã Quang. | Gương Hán-Việt | 涑 chưa có từ Hán-Việt quen dùng, chủ yếu trong địa danh lịch sử | Mở khoá kiến thức | Biết 涑 giúp đọc tài liệu sử TQ — 涑水 là sông ở Sơn Tây, 涑水紀聞 là tác phẩm của Tư Mã Quang.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary ghi 涑 là chữ hình thanh: 水 (thủy, biểu nghĩa) + 束 (thúc, biểu âm). Chữ chỉ sông Tốc ở tỉnh Sơn Tây. Dùng trong địa danh 涑水 và 涑水紀聞 (tác phẩm sử học của Tư Mã Quang). Có hình đại triện và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Tốc", "Hạng Tần Suất (Jun Da)": "5405.0", "Tần Suất % (Jun Da)": "99.9542092196", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 束", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵束", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "束", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "涑", "Unihan_Traditional (Chữ Phồn thể)": "涑", "Pinyin_Xie": "sù", "Âm Hán Việt_Xie": "tốc, tâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ riêng chỉ tên sông hoặc động từ chỉ việc tẩy rửa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('浞', '{"9000": "5406.0", "Chữ Trung Quốc": "浞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 浞 | trọc | tượng hình | ngâm trong nước; tên riêng | 浞 là chữ độc thể, bộ 水 (thuỷ) gợi nghĩa liên quan đến nước. Không có dữ liệu cấu trúc hình thanh hay hội ý từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 浞 mang bộ 水 (nước) — hình dung một vật bị ngâm ngập hoàn toàn trong nước, ướt sũng. | Gương Hán-Việt | 浞 chưa xuất hiện phổ biến trong từ Hán-Việt tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 浞 giúp nhận diện tên địa danh và nhân vật lịch sử cổ Trung Hoa có liên quan đến nước.", "Tự nguyên_Xie": "Tiểu triện | 浞 có bộ 水 (nước), gợi nghĩa ngâm, thấm ướt. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên riêng)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 足", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵足", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "足", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "浞", "Unihan_Traditional (Chữ Phồn thể)": "浞", "Pinyin_Xie": "zhuó", "Âm Hán Việt_Xie": "trác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Tính từ | 形容词 | Chủ yếu dùng làm danh từ riêng trong tên người cổ hoặc động từ chỉ sự thấm ướt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('玳', '{"9000": "5407.0", "Chữ Trung Quốc": "玳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 9 | nét | 𤣩 | biểu nghĩa | ngọc bích, đá quý | 代 | đại | biểu âm | thay thế | 玳 = 𤣩 (bộ Ngọc, biểu nghĩa: chất liệu quý) + 代 (Đại, biểu âm). Chữ hình thanh: 𤣩 chỉ loại đồ vật quý giá làm từ chất liệu cứng như ngọc/mai rùa, 代 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đại\": 玳 = ngọc (𤣩) + âm Đại (代) — mai rùa quý như ngọc, đẹp như đồ trang sức triều đại. | Gương Hán-Việt | 玳 xuất hiện trong từ Hán-Việt \"đại mội\" (玳瑁) — loài rùa biển quý. | Mở khoá kiến thức | Biết 玳 mở khoá từ 玳瑁 (đại mội) — tên loài rùa biển có mai được dùng làm đồ mỹ nghệ truyền thống.", "Tự nguyên_Xie": "Theo Wiktionary, 玳 là chữ hình thanh: 𤣩 (biến thể của 玉, ngọc) làm phần biểu nghĩa chỉ chất liệu cứng quý; 代 (đại) làm phần biểu âm. Chữ chỉ dùng trong từ ghép 玳瑁 — loài rùa biển có mai đẹp được dùng làm đồ trang sức từ thời cổ đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đại mội 玳瑁)", "Hạng Tần Suất (Jun Da)": "5407.0", "Tần Suất % (Jun Da)": "99.9543311809", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 代", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王代", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "代", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "玳", "Unihan_Traditional (Chữ Phồn thể)": "玳", "Pinyin_Xie": "dài", "Âm Hán Việt_Xie": "đại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong từ ghép chỉ loài đồi mồi hoặc chất liệu từ mai của nó. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('愍', '{"9000": "5408.0", "Chữ Trung Quốc": "愍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 13 | nét | 愍 | mẫn | tượng hình | xót thương, lo lắng | 愍 là chữ có bộ 心 (tâm) ở dưới, gợi nghĩa cảm xúc trong lòng. Không có dữ liệu cấu trúc hình thanh hay hội ý từ nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mẫn\": 愍 có bộ 心 (tâm) — tấm lòng mẫn cảm, xót xa trước nỗi đau của người khác. | Gương Hán-Việt | 愍 xuất hiện trong \"mẫn\" mang nghĩa thương xót, tương tự 悯 (mẫn) trong từ Hán-Việt. | Mở khoá kiến thức | Biết 愍 giúp đọc văn ngôn cổ điển diễn tả lòng trắc ẩn, xót thương của vua chúa hay bề trên.", "Tự nguyên_Xie": "Tiểu triện | 愍 mang bộ 心 (tâm, trái tim), chỉ cảm xúc xót thương, lo lắng. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết từ Wiktionary. Chữ tồn tại từ thời cổ, thấy trong tiểu triện (hanziyuan). | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xót thương; lo lắng", "Hạng Tần Suất (Jun Da)": "5408.0", "Tần Suất % (Jun Da)": "99.9543921615", "GavinGrover_Once (Chiết tự trực tiếp)": "敃 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敃心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "愍", "Unihan_Traditional (Chữ Phồn thể)": "愍", "Pinyin_Xie": "mǐn", "Âm Hán Việt_Xie": "mẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ biểu thị sự thương xót hoặc tính từ chỉ trạng thái lo âu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畛', '{"9000": "5409.0", "Chữ Trung Quốc": "畛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 田 | Số nét | 10 | nét | 畛 | chẩn | tượng hình | bờ ranh giữa các thửa ruộng | 畛 có bộ 田 (điền, ruộng) làm phần nghĩa, gợi liên tưởng đến ranh giới giữa các mảnh ruộng. Không có dữ liệu cấu trúc chi tiết từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chẩn\": 畛 có bộ 田 (ruộng) — hình dung đường bờ thẳng tắp chia cắt các thửa ruộng, ranh giới rõ ràng không vượt qua được. | Gương Hán-Việt | 畛 ít dùng độc lập; xuất hiện trong từ Hán-Việt cổ như \"chẩn vực\" (畛域) nghĩa ranh giới, phạm vi. | Mở khoá kiến thức | Biết 畛 giúp đọc hiểu văn cổ diễn đạt khái niệm ranh giới, phân vùng ruộng đất.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 畛 từ Wiktionary chỉ đường bờ giữa các ruộng, ranh giới, phạm vi. Bộ 田 (điền) gợi nghĩa liên quan đến đất ruộng. Thấy trong tiểu triện và lục thư thông (hanziyuan). Chưa có dữ liệu hình thanh hay hội ý rõ ràng từ nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bờ ruộng; giới hạn", "Hạng Tần Suất (Jun Da)": "5409.0", "Tần Suất % (Jun Da)": "99.9544531422", "GavinGrover_Once (Chiết tự trực tiếp)": "田 + 㐱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰田㐱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "田", "Unihan_Simplified (Chữ Giản thể)": "畛", "Unihan_Traditional (Chữ Phồn thể)": "畛", "Pinyin_Xie": "zhěn", "Âm Hán Việt_Xie": "chẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ ranh giới hoặc động từ chỉ sự phân chia giới hạn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赧', '{"9000": "5410.0", "Chữ Trung Quốc": "赧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 赤 | Số nét | 11 | nét | 赤 | xích | biểu nghĩa | đỏ | 𡰫 | biểu âm | 赧 = 赤 (Xích, biểu nghĩa: màu đỏ) + 𡰫 (biểu âm). Chữ hình thanh: 赤 chỉ màu đỏ — mặt đỏ bừng vì thẹn; 𡰫 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nấn\": 赧 = đỏ (赤) + âm — mặt đỏ như 赤 vì quá thẹn, nấn ná chưa dám nhìn ai. | Gương Hán-Việt | 赧 xuất hiện trong \"nấn\" mang nghĩa xấu hổ, thẹn đỏ mặt trong văn ngôn cổ. | Mở khoá kiến thức | Biết 赧 giúp đọc hiểu những đoạn văn cổ miêu tả sự xấu hổ, ngượng ngùng của nhân vật.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 赧 là chữ hình thanh gồm 赤 (xích, đỏ) làm phần biểu nghĩa và 𡰫 làm phần biểu âm. Nghĩa gốc là mặt đỏ bừng vì xấu hổ, thẹn thùng. Thấy trong tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thẹn đỏ mặt", "Hạng Tần Suất (Jun Da)": "5410.0", "Tần Suất % (Jun Da)": "99.9545141228", "GavinGrover_Once (Chiết tự trực tiếp)": "赤 + 𠬝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰赤𠬝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠬝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "赤", "Unihan_Simplified (Chữ Giản thể)": "赧", "Unihan_Traditional (Chữ Phồn thể)": "赧", "Pinyin_Xie": "nǎn", "Âm Hán Việt_Xie": "noãn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả trạng thái đỏ mặt vì ngượng ngùng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貉', '{"9000": "5411.0", "Chữ Trung Quốc": "貉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豸 | Số nét | 13 | nét | 貉 | hạc | tượng hình | loài thú giống cầy, chồn rút | 貉 có bộ 豸 (trĩ) — bộ chỉ các loài thú không có chân trước. Không có dữ liệu cấu trúc hình thanh hay hội ý rõ ràng từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạc\": 貉 có bộ 豸 (thú nằm phủ) — loài thú lông dày nằm rình, cùng hội cùng thuyền với đồng bọn. | Gương Hán-Việt | 貉 ít xuất hiện trong tiếng Việt hiện đại; trong văn ngôn có \"hạc\" chỉ loài thú này. | Mở khoá kiến thức | Biết 貉 giúp đọc thành ngữ 一丘之貉 (nhất khâu chi hạc) — một lũ cùng giuộc, cùng hội cùng thuyền.", "Tự nguyên_Xie": "Kim văn | Bạch thư | 貉 không có dữ liệu Wiktionary chi tiết về cấu trúc. Bộ 豸 chỉ các loài thú dữ, nằm phủ phục. Thấy trong kim văn và bạch thư. Chữ chỉ một loài thú giống cầy hoặc gấu trúc con (tanuki), dùng trong cụm \"một đàn 貉\" ý chỉ bọn xấu xa. Chưa có nguồn học thuật xác nhận. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loài thú giống con cầy", "Hạng Tần Suất (Jun Da)": "5411.0", "Tần Suất % (Jun Da)": "99.9545745867", "GavinGrover_Once (Chiết tự trực tiếp)": "豸 + 各", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豸各", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "各", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豸", "Unihan_Simplified (Chữ Giản thể)": "貉", "Unihan_Traditional (Chữ Phồn thể)": "貉", "Pinyin_Xie": "háo", "Âm Hán Việt_Xie": "hạc, lạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loài động vật thuộc họ chó giống con cầy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('擀', '{"9000": "5412.0", "Chữ Trung Quốc": "擀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 16 | nét | 手 | thủ | biểu nghĩa | tay | 幹 | cán | biểu âm | 擀 = 手 (Thủ, biểu nghĩa: tay) + 幹 (Cán, biểu âm). Chữ hình thanh: tay (手) thực hiện hành động cán, ép phẳng; 幹 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 擀 = tay (手) + cán (幹) — bàn tay cầm cây cán, lăn mạnh để cán dẹp miếng bột. | Gương Hán-Việt | 擀 ít xuất hiện trong từ Hán-Việt; động tác cán bột trong ẩm thực. | Mở khoá kiến thức | Biết 擀 giúp đọc công thức nấu ăn tiếng Trung, đặc biệt các món mì tươi tự cán.", "Tự nguyên_Xie": "Theo Wiktionary, 擀 là chữ hình thanh gồm 手 (tay) làm phần biểu nghĩa và 幹 làm phần biểu âm. Nghĩa là dùng tay cán mỏng, ép phẳng — đặc biệt dùng để cán bột mì làm mì sợi. Không có dạng cổ trong giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cán, nghiền, ép", "Hạng Tần Suất (Jun Da)": "5412.0", "Tần Suất % (Jun Da)": "99.9546350505", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 幹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌幹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "幹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "擀", "Unihan_Traditional (Chữ Phồn thể)": "擀", "Pinyin_Xie": "gǎn", "Âm Hán Việt_Xie": "cán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ bột hoặc bánh để biểu thị hành động cán phẳng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('湫', '{"9000": "5413.0", "Chữ Trung Quốc": "湫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 湫 | tiêu | tượng hình | ao nhỏ, vũng nước; ẩm thấp chật hẹp | 湫 có bộ 水 (thuỷ) gợi nghĩa liên quan đến nước, ao vũng. Không có dữ liệu cấu trúc hình thanh hay hội ý từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": 湫 có bộ 水 (nước) — ao nước nhỏ lạnh lẽo tiêu điều nằm ở nơi u tối, chật hẹp. | Gương Hán-Việt | 湫 ít dùng trong tiếng Việt hiện đại; trong văn ngôn có \"tiêu\" chỉ ao hồ nhỏ. | Mở khoá kiến thức | Biết 湫 giúp đọc thơ văn cổ miêu tả cảnh ao hồ nhỏ, nơi ẩm thấp u tối.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 湫 không có dữ liệu Wiktionary cấu trúc chi tiết. Bộ 水 (nước) gợi nghĩa ao nước nhỏ, nơi ẩm thấp. Chưa có nguồn học thuật xác nhận. Chữ tạo muộn, chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái ao; mát rượi", "Hạng Tần Suất (Jun Da)": "5413.0", "Tần Suất % (Jun Da)": "99.9546955144", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 秋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵秋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "湫", "Unihan_Traditional (Chữ Phồn thể)": "湫", "Pinyin_Xie": "jiǎo", "Âm Hán Việt_Xie": "tưu, tiểu, tiều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ ao đầm hoặc tính từ miêu tả nơi ẩm thấp, mát lạnh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逦', '{"9000": "5414.0", "Chữ Trung Quốc": "逦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 10 | nét | 逦 | lệ | tượng hình | quanh co, uốn lượn liên tiếp | 逦 có bộ 辵 (sước) — bộ chỉ chuyển động, đi lại. Không có dữ liệu cấu trúc chi tiết từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lệ\": 逦 có bộ 辵 (đi) — con đường uốn lượn lệ lạc qua núi đồi, không bao giờ thẳng. | Gương Hán-Việt | 逦 xuất hiện trong \"dĩ lệ\" (迤邐/迤逦) — chỉ chuỗi sự vật kéo dài quanh co. | Mở khoá kiến thức | Biết 逦 giúp đọc thơ văn cổ miêu tả cảnh vật hoặc đoàn người kéo dài uốn lượn.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 逦 theo Wiktionary (dạng truyền thống 邐) chỉ dùng trong từ ghép 迤邐/迤逦 nghĩa là uốn lượn, quanh co liên tiếp. Bộ 辵 (đi) gợi ý đến chuyển động ngoằn ngoèo. Thấy trong kim văn và tiểu triện (hanziyuan). Chưa có phân tích cấu trúc rõ ràng từ Wiktionary. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: dĩ lệ 迤邐,迤逦)", "Hạng Tần Suất (Jun Da)": "5414.0", "Tần Suất % (Jun Da)": "99.9547559782", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 丽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶丽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逦", "Unihan_Traditional (Chữ Phồn thể)": "邐", "Pinyin_Xie": "lǐ", "Âm Hán Việt_Xie": "lệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ trong từ ghép để miêu tả sự uốn lượn kéo dài của đường sá, núi non. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('椴', '{"9000": "5415.0", "Chữ Trung Quốc": "椴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 椴 | đoạn | tượng hình | cây đoạn, cây bồ đề châu Âu (linden) | 椴 có bộ 木 (mộc, cây) làm phần nghĩa, chỉ một loại cây. Không có dữ liệu cấu trúc hình thanh hay hội ý từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đoạn\": 椴 có bộ 木 (cây) — cây đoạn thẳng cao vút, gỗ dùng làm đồ nội thất đẹp. | Gương Hán-Việt | 椴 ít xuất hiện trong tiếng Việt; \"đoạn\" trong văn cảnh thực vật học chỉ cây linden. | Mở khoá kiến thức | Biết 椴 giúp đọc tài liệu thực vật học và tên gỗ tiếng Trung trong ngành lâm nghiệp.", "Tự nguyên_Xie": "椴 từ Wiktionary chỉ cây linden (bồ đề châu Âu) hoặc cây dương châu Á. Bộ 木 (cây) gợi nghĩa loại thực vật. Chưa có dữ liệu phân tích cấu trúc chi tiết từ nguồn học thuật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây đoạn", "Hạng Tần Suất (Jun Da)": "5415.0", "Tần Suất % (Jun Da)": "99.9548164421", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 段", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木段", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "段", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "椴", "Unihan_Traditional (Chữ Phồn thể)": "椴", "Pinyin_Xie": "duàn", "Âm Hán Việt_Xie": "đoạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một loài cây thân gỗ rụng lá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铄', '{"9000": "5416.0", "Chữ Trung Quốc": "铄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 金 | kim | biểu nghĩa | kim loại, vàng | 樂 | lạc | biểu âm | 铄 = 金 (Kim, biểu nghĩa: kim loại) + 樂 (Lạc, biểu âm). Chữ hình thanh: kim (金) chỉ kim loại bị nung chảy; 樂 cho âm đọc. Dạng phồn thể là 鑠.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thước\": 铄 = kim (金) + âm Lạc (樂) — kim loại bị lửa thước nung chảy thành dòng sáng rực. | Gương Hán-Việt | 铄 xuất hiện trong thành ngữ \"众口铄金\" (chúng khẩu thước kim) — miệng lưỡi thiên hạ có thể làm tan chảy cả vàng. | Mở khoá kiến thức | Biết 铄 giúp đọc thành ngữ 众口铄金 và văn ngôn miêu tả sức mạnh dư luận hoặc sự nung chảy.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 铄 (phồn thể 鑠) là chữ hình thanh gồm 金 (kim loại) làm phần biểu nghĩa và 樂 làm phần biểu âm. Nghĩa gốc là nung chảy kim loại bằng nhiệt. Mở rộng nghĩa: làm yếu dần, xói mòn; hoặc sáng láng, rực rỡ. Thấy trong tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nóng chảy", "Hạng Tần Suất (Jun Da)": "5416.0", "Tần Suất % (Jun Da)": "99.954876906", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 乐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅乐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铄", "Unihan_Traditional (Chữ Phồn thể)": "鑠", "Pinyin_Xie": "shuò", "Âm Hán Việt_Xie": "thước", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ chỉ sự nung chảy kim loại hoặc làm tính từ mô tả ánh sáng rực rỡ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箧', '{"9000": "5417.0", "Chữ Trung Quốc": "箧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 箧 | khiếp | tượng hình | cái tráp, hộp nhỏ đựng đồ | 箧 là dạng giản thể của 篋, có bộ 竹 (trúc) gợi nghĩa vật dụng đan bằng tre. Đây là chữ giản hóa, thay 夾 bằng 夹. Không có cấu trúc hình thanh hay hội ý độc lập rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiếp\": 箧 có bộ 竹 (tre) — chiếc khiếp đan bằng tre đựng sách quý, gọn nhẹ mang theo đường. | Gương Hán-Việt | 箧 xuất hiện trong \"khiếp\" chỉ tráp, hộp nhỏ; trong thành ngữ 行箧 (hành khiếp) — hành lý. | Mở khoá kiến thức | Biết 箧 giúp đọc văn ngôn miêu tả vật dụng cá nhân, hành lý hoặc nơi cất giữ sách vở.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 箧 là dạng giản thể của 篋 (khiếp). Wiktionary ghi đây là chữ giản hóa từ 篋, thay phần 夾 thành 夹. Chữ gốc 篋 gồm bộ 竹 (trúc) chỉ vật đan từ tre, 夾 cho âm. Nghĩa là cái tráp hoặc hộp nhỏ đựng đồ. Thấy trong tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái tráp, cái hòm nhỏ", "Hạng Tần Suất (Jun Da)": "5417.0", "Tần Suất % (Jun Da)": "99.9549373698", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "箧", "Unihan_Traditional (Chữ Phồn thể)": "篋", "Pinyin_Xie": "qiè", "Âm Hán Việt_Xie": "khiếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại hộp, tráp nhỏ đựng sách vở hoặc đồ đạc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('刖', '{"9000": "5418.0", "Chữ Trung Quốc": "刖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 6 | nét | 月 | nguyệt | biểu âm | 刂 | biểu nghĩa | dao, hình phạt bằng dao | 刖 = 月 (Nguyệt, biểu âm) + 刂 (bộ Đao, biểu nghĩa: dao, hình phạt). Chữ hình thanh: 刂 chỉ hành động chặt bằng dao; 月 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nguyệt\" (âm): 刖 = dao (刂) + nguyệt (月 cho âm) — hình phạt chặt chân bằng dao sắc như ánh trăng, không có đường chuộc. | Gương Hán-Việt | 刖 ít dùng trong tiếng Việt hiện đại; trong văn ngôn cổ \"nguyệt hình\" chỉ hình phạt chặt chân. | Mở khoá kiến thức | Biết 刖 giúp đọc văn sử học về hình luật Trung Hoa cổ và câu chuyện Biện Hòa bị xử 刖 vì dâng ngọc quý.", "Tự nguyên_Xie": "Giáp cốt văn | Theo Wiktionary, 刖 là chữ hình thanh gồm 月 làm phần biểu âm và 刀/刂 làm phần biểu nghĩa chỉ dao, hình phạt. Nghĩa gốc là hình phạt chặt chân, một trong ngũ hình của Trung Hoa cổ đại. Thấy trong giáp cốt văn — một trong những chữ cổ nhất liên quan đến hình phạt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hình phạt chặt chân", "Hạng Tần Suất (Jun Da)": "5418.0", "Tần Suất % (Jun Da)": "99.9549978337", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "刖", "Unihan_Traditional (Chữ Phồn thể)": "刖", "Pinyin_Xie": "yuè", "Âm Hán Việt_Xie": "ngoạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành vi chặt chân hoặc làm danh từ chỉ hình phạt này thời cổ đại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲮', '{"9000": "5419.0", "Chữ Trung Quốc": "鲮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 鲮 | lăng | tượng hình | cá lăng, cá đác (mud carp) | 鲮 có bộ 魚 (ngư, cá) làm phần nghĩa, chỉ một loại cá. Không có dữ liệu cấu trúc hình thanh hay hội ý từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lăng\": 鲮 có bộ 魚 (cá) — con cá lăng trong truyền thuyết có mặt người, nghe tên lăng liền nhớ loài cá kỳ lạ. | Gương Hán-Việt | 鲮 xuất hiện trong \"lăng lý\" (鯪鯉) — tên cổ của con tê tê (pangolin). | Mở khoá kiến thức | Biết 鲮 giúp đọc tài liệu ẩm thực và sinh học về cá nước ngọt miền nam Trung Hoa.", "Tự nguyên_Xie": "鲮 (phồn thể 鯪) theo Wiktionary chỉ cá lăng (mud carp, Cirrhinus molitorella), một loài cá nước ngọt phổ biến ở miền nam Trung Hoa. Ngoài ra còn có nghĩa thần thoại: loài cá có mặt người và tay người. Bộ 魚 (cá) làm phần nghĩa. Chưa có phân tích cấu trúc chi tiết từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá lăng, cá đác", "Hạng Tần Suất (Jun Da)": "5419.0", "Tần Suất % (Jun Da)": "99.9550582975", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 夌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼夌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲮", "Unihan_Traditional (Chữ Phồn thể)": "鯪", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "lăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong tên gọi các loài động vật như cá lăng hoặc tê tê. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訇', '{"9000": "5420.0", "Chữ Trung Quốc": "訇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 9 | nét | 勻 | biểu âm | 言 | ngôn | biểu nghĩa | lời nói, âm thanh | 訇 = 勻 (biểu âm, rút gọn) + 言 (Ngôn, biểu nghĩa: âm thanh, lời nói). Chữ hình thanh: 言 chỉ âm thanh lớn; 勻 (viết tắt) cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 訇 = âm (言) + âm lớn — tiếng HOẰNG một phát vang như sấm nổ, không nhầm được. | Gương Hán-Việt | 訇 xuất hiện trong \"A Hoằng\" (阿訇) — tước danh giáo sĩ Hồi giáo trong tiếng Việt. | Mở khoá kiến thức | Biết 訇 giúp đọc văn bản về Hồi giáo Trung Hoa và thơ miêu tả âm thanh dữ dội.", "Tự nguyên_Xie": "Bạch thư | Đại triện | Tiểu triện | Theo Wiktionary, 訇 là chữ hình thanh gồm 勻 (rút gọn, biểu âm) và 言 (ngôn, biểu nghĩa). Là từ tượng thanh chỉ tiếng động lớn như sấm hay vật nặng rơi. Cũng dùng trong \"阿訇\" (A Hoằng) — chức danh giáo sĩ Hồi giáo. Thấy trong bạch thư, đại triện, tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng động lớn", "Hạng Tần Suất (Jun Da)": "5420.0", "Tần Suất % (Jun Da)": "99.9551182446", "GavinGrover_Once (Chiết tự trực tiếp)": "勹 + 言", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴勹言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "言", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "勹", "Unihan_Simplified (Chữ Giản thể)": "訇", "Unihan_Traditional (Chữ Phồn thể)": "訇", "Pinyin_Xie": "hōng", "Âm Hán Việt_Xie": "hoanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Danh từ | 名词 | Chữ này thường dùng làm từ tượng thanh mô tả âm thanh lớn như tiếng sấm hay tiếng sóng vỗ. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茱', '{"9000": "5421.0", "Chữ Trung Quốc": "茱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艸 | tháu | biểu nghĩa | cỏ, cây | 朱 | chu | biểu âm | 茱 = 艸 (Tháu, biểu nghĩa: thực vật) + 朱 (Chu, biểu âm). Chữ hình thanh: 艸 chỉ loại cây; 朱 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thù\": 茱 = cây (艸) + âm Chu (朱) — cây thù du đỏ thơm, người xưa cài trên tóc ngày Trùng Dương để trừ tà. | Gương Hán-Việt | 茱 xuất hiện trong \"thù du\" (茱萸) — tên loại cây thơm dùng trong lễ tết Trùng Dương. | Mở khoá kiến thức | Biết 茱 giúp đọc thơ Đường miêu tả lễ Trùng Dương, đặc biệt bài thơ nổi tiếng của Vương Duy.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 茱 là chữ hình thanh gồm 艸 (cỏ cây) làm phần biểu nghĩa và 朱 làm phần biểu âm. Chữ chỉ dùng trong từ ghép 茱萸 — loài cây thơm dùng trong nghi lễ truyền thống Trung Hoa, nhất là ngày Tết Trùng Dương (9/9 âm lịch). Thấy trong tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thù du 茱萸)", "Hạng Tần Suất (Jun Da)": "5421.0", "Tần Suất % (Jun Da)": "99.9551781917", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 朱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹朱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茱", "Unihan_Traditional (Chữ Phồn thể)": "茱", "Pinyin_Xie": "zhū", "Âm Hán Việt_Xie": "thù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và hầu như chỉ xuất hiện trong từ ghép chỉ cây thù du. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啖', '{"9000": "5422.0", "Chữ Trung Quốc": "啖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 啖 | đạm | tượng hình | ăn, nhai; cám dỗ bằng thức ăn hoặc lợi lộc | 啖 có bộ 口 (khẩu, miệng) gợi nghĩa hành động ăn uống bằng miệng. Không có dữ liệu cấu trúc chi tiết từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đạm\": 啖 có bộ 口 (miệng) — miệng đạm ăn ngon, hoặc dụ dỗ người khác bằng miếng mồi béo bở. | Gương Hán-Việt | 啖 xuất hiện trong \"đạm thực\" (啖食) — ăn uống; hoặc văn ngôn \"dụ đạm\" chỉ dụ dỗ bằng lợi lộc. | Mở khoá kiến thức | Biết 啖 giúp đọc văn ngôn cổ và tiếng Quảng Đông liên quan đến ăn uống và cám dỗ.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 啖 theo Wiktionary mang nghĩa ăn, ăn ngon lành; dụ dỗ bằng lợi ích. Bộ 口 (miệng) gợi hành động ăn. Thấy trong kim văn và tiểu triện. Tiếng Quảng Đông dùng làm lượng từ đếm ngụm nước hoặc nụ hôn. Chưa có phân tích cấu trúc chi tiết từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ăn, nếm; cám dỗ", "Hạng Tần Suất (Jun Da)": "5422.0", "Tần Suất % (Jun Da)": "99.9552381388", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 炎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口炎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "炎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啖", "Unihan_Traditional (Chữ Phồn thể)": "啖", "Pinyin_Xie": "dàn", "Âm Hán Việt_Xie": "đạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động ăn uống hoặc dụ dỗ người khác bằng lợi ích. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('悭', '{"9000": "5423.0", "Chữ Trung Quốc": "悭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 10 | nét | 悭 | khan | tượng hình | keo kiệt, bủn xỉn | 悭 là dạng giản thể của 慳, có bộ 心 (tâm) gợi nghĩa tính tình, thái độ trong lòng. Đây là chữ giản hóa thay 堅 bằng 坚.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khan\": 悭 có bộ 心 (tâm) — tấm lòng khan hiếm, chặt chẽ đến mức không dám tiêu một xu. | Gương Hán-Việt | 悭 xuất hiện trong \"khan tham\" (悭贪) — keo kiệt tham lam; \"khan sắc\" nghĩa tính bủn xỉn. | Mở khoá kiến thức | Biết 悭 giúp đọc văn ngôn cổ mô tả tính keo kiệt, đặc biệt trong văn học Phật giáo.", "Tự nguyên_Xie": "悭 là dạng giản thể của 慳 (khan). Wiktionary ghi đây là chữ giản hóa từ 慳, thay phần 堅 thành 坚. Nghĩa là keo kiệt, bủn xỉn, không chịu cho đi. Bộ 心 (tâm) chỉ tính cách. Không có ảnh cổ tự. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "keo kiệt", "Hạng Tần Suất (Jun Da)": "5423.0", "Tần Suất % (Jun Da)": "99.9552980859", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 坚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄坚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "坚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "悭", "Unihan_Traditional (Chữ Phồn thể)": "慳", "Pinyin_Xie": "qiān", "Âm Hán Việt_Xie": "khan, san", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ để miêu tả tính cách keo kiệt hoặc trạng thái thiếu thốn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('愀', '{"9000": "5424.0", "Chữ Trung Quốc": "愀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 12 | nét | 愀 | xỉu | tượng hình | vẻ mặt ưu tư, buồn bã, lo lắng | 愀 có bộ 心 (tâm) gợi nghĩa cảm xúc trong lòng. Không có dữ liệu cấu trúc chi tiết từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xỉu\": 愀 có bộ 心 (tâm) — tâm trạng xỉu xuống, mặt trở nên u ám như trời trước cơn bão. | Gương Hán-Việt | 愀 xuất hiện trong \"xỉu nhiên\" (愀然) — vẻ mặt đột nhiên trở nên nghiêm trọng, buồn bã. | Mở khoá kiến thức | Biết 愀 giúp đọc văn ngôn cổ mô tả sắc mặt thay đổi, tâm trạng chợt u buồn.", "Tự nguyên_Xie": "愀 theo Wiktionary có nghĩa nhìn nghiêm nghị hoặc buồn bã. Bộ 心 (tâm) gợi cảm xúc nội tâm. Dùng chủ yếu trong từ ghép 愀然 — vẻ mặt trở nên nghiêm trọng hoặc ưu buồn. Chưa có phân tích cấu trúc chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lo lắng", "Hạng Tần Suất (Jun Da)": "5424.0", "Tần Suất % (Jun Da)": "99.9553580329", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 秋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄秋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "愀", "Unihan_Traditional (Chữ Phồn thể)": "愀", "Pinyin_Xie": "qiǎo", "Âm Hán Việt_Xie": "thiểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ sự thay đổi sắc mặt hoặc làm tính từ chỉ vẻ mặt nghiêm túc, lo âu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('朐', '{"9000": "5425.0", "Chữ Trung Quốc": "朐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 月 | Số nét | 9 | nét | 朐 | cù | tượng hình | thịt khô cong queo; bộ phận đầu xe kẹp cổ ngựa | 朐 có bộ 月 (nguyệt, thịt/xương) gợi nghĩa liên quan đến thịt hoặc cơ thể. Không có dữ liệu cấu trúc chi tiết từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cù\": 朐 có bộ 月 (thịt) — miếng thịt khô cong cù queo, hoặc bộ phận cong của xe ngựa cổ. | Gương Hán-Việt | 朐 ít xuất hiện trong tiếng Việt hiện đại; trong văn ngôn chỉ thịt khô hoặc tên địa danh Trung Hoa cổ. | Mở khoá kiến thức | Biết 朐 giúp đọc văn cổ về tên địa danh Trung Hoa (朐县) hoặc miêu tả thức ăn dự trữ thời xưa.", "Tự nguyên_Xie": "Tiểu triện | 朐 có bộ 月 (vốn là 肉, thịt) gợi nghĩa vật phẩm từ thịt hoặc liên quan đến cơ thể. Nghĩa: thịt khô cong queo; bộ phận đầu trục xe kẹp vào cổ ngựa. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thịt khô cong queo; vật ở đầu trước càng xe kẹp ở giữa cổ ngựa để thắng xe; xa", "Hạng Tần Suất (Jun Da)": "5425.0", "Tần Suất % (Jun Da)": "99.95541798", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 句", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月句", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "朐", "Unihan_Traditional (Chữ Phồn thể)": "朐", "Pinyin_Xie": "qú", "Âm Hán Việt_Xie": "cù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại thịt khô uốn cong hoặc dùng trong địa danh cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畈', '{"9000": "5426.0", "Chữ Trung Quốc": "畈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 田 | Số nét | 9 | nét | 田 | điền | biểu nghĩa | ruộng, đất canh tác | 反 | phản | biểu âm | 畈 = 田 (Điền, biểu nghĩa: ruộng) + 反 (Phản, biểu âm). Chữ hình thanh: 田 chỉ đất canh tác; 反 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phán\": 畈 = ruộng (田) + âm Phản (反) — phán đoán nhìn qua là ruộng đồng bằng phẳng trải rộng một vùng. | Gương Hán-Việt | 畈 ít xuất hiện trong tiếng Việt; trong Hán-Việt \"phán\" chỉ khoảnh ruộng lớn. | Mở khoá kiến thức | Biết 畈 giúp đọc địa danh tiếng Trung, đặc biệt các tên làng xã tỉnh Hồ Bắc.", "Tự nguyên_Xie": "Theo Wiktionary, 畈 là chữ hình thanh gồm 田 (điền, ruộng) làm phần biểu nghĩa và 反 làm phần biểu âm. Nghĩa là khoảnh ruộng rộng, lớn; lượng từ đếm mảnh đất ruộng; dùng nhiều trong địa danh miền trung Trung Hoa (đặc biệt Hồ Bắc, Giang Tây). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ruộng đất; mảnh, khoảnh", "Hạng Tần Suất (Jun Da)": "5426.0", "Tần Suất % (Jun Da)": "99.9554779271", "GavinGrover_Once (Chiết tự trực tiếp)": "田 + 反", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰田反", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "反", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "田", "Unihan_Simplified (Chữ Giản thể)": "畈", "Unihan_Traditional (Chữ Phồn thể)": "畈", "Pinyin_Xie": "fàn", "Âm Hán Việt_Xie": "phán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ cánh đồng ở vùng đồi núi hoặc làm lượng từ cho khoảnh ruộng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹨', '{"9000": "5427.0", "Chữ Trung Quốc": "鹨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 16 | nét | 鹨 | liêu | tượng hình | chim chiền chiện (pipit) | 鹨 có bộ 鳥 (điểu, chim) gợi nghĩa loài chim. Không có dữ liệu cấu trúc chi tiết từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêu\": 鹨 có bộ 鳥 (chim) — chim chiền chiện bay liêu xiêu trên đồng lúa, hót vang trời xanh. | Gương Hán-Việt | 鹨 ít xuất hiện trong tiếng Việt; trong sinh học \"liêu\" chỉ các loài chim chiền chiện (pipit). | Mở khoá kiến thức | Biết 鹨 giúp đọc tài liệu điểu học và văn học miêu tả cảnh đồng quê có tiếng chim hót.", "Tự nguyên_Xie": "Tiểu triện | 鹨 (phồn thể 鷚) theo Wiktionary là chim chiền chiện thuộc chi Anthus, sống ở đồng ruộng và núi thấp. Bộ 鳥 (chim) gợi ý loài chim. Thấy trong tiểu triện (hanziyuan). Chưa có phân tích cấu trúc chi tiết từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim chiền chiện", "Hạng Tần Suất (Jun Da)": "5427.0", "Tần Suất % (Jun Da)": "99.9555378742", "GavinGrover_Once (Chiết tự trực tiếp)": "翏 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰翏鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹨", "Unihan_Traditional (Chữ Phồn thể)": "鷚", "Pinyin_Xie": "liù", "Âm Hán Việt_Xie": "lưu, liêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim chiền chiện trong các tài liệu sinh học hoặc văn học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛘', '{"9000": "5428.0", "Chữ Trung Quốc": "蛘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 虫 | trùng | biểu âm | sâu, côn trùng | 羊 | dương | biểu nghĩa | 蛘 = 虫 (Trùng, biểu âm) + 羊 (Dương, biểu nghĩa). Chữ hình thanh: theo Wiktionary, 虫 là phần biểu âm (c1=p) và 羊 là phần biểu nghĩa (c2=s). Chỉ loài sâu hại lúa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dương\": 蛘 = sâu (虫) + dương (羊) — con sâu mọt cứng đầu như con dê, gặm nát hạt thóc trong kho. | Gương Hán-Việt | 蛘 ít xuất hiện trong tiếng Việt; trong nông nghiệp \"dương\" chỉ sâu hại ngũ cốc. | Mở khoá kiến thức | Biết 蛘 giúp đọc tài liệu nông nghiệp, phòng trừ sâu bệnh trong kho lúa gạo.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 蛘 là chữ hình thanh gồm 虫 làm phần biểu âm và 羊 làm phần biểu nghĩa. Chỉ loài sâu mọt (weevil) phá hại lúa gạo và ngũ cốc. Thấy trong tiểu triện (hanziyuan). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "loài sâu hại lúa", "Hạng Tần Suất (Jun Da)": "5428.0", "Tần Suất % (Jun Da)": "99.9555978212", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 羊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫羊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛘", "Unihan_Traditional (Chữ Phồn thể)": "蛘", "Pinyin_Xie": "yáng", "Âm Hán Việt_Xie": "dạng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài côn trùng nhỏ phá hoại mùa màng hoặc đồ dùng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佶', '{"9000": "5429.0", "Chữ Trung Quốc": "佶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 佶 | cật | tượng hình | mạnh mẽ, vững chắc; khúc khuỷu khó hiểu | 佶 có bộ 亻(nhân, người) gợi nghĩa liên quan đến con người. Không có dữ liệu cấu trúc chi tiết từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cật\": 佶 có bộ 亻(người) — người cật lực mạnh mẽ, hoặc câu văn cật vật khó hiểu như đường quanh co. | Gương Hán-Việt | 佶 xuất hiện trong \"cật khuất\" (佶屈) — khúc khuỷu, khó đọc; hoặc tên riêng người Trung Hoa. | Mở khoá kiến thức | Biết 佶 giúp đọc phê bình văn học cổ điển, đặc biệt mô tả văn phong khó hiểu.", "Tự nguyên_Xie": "Tiểu triện | 佶 theo Wiktionary mang nghĩa mạnh mẽ, vững chắc; dùng trong từ ghép 佶屈 — khúc khuỷu, gồ ghề khó hiểu (nói về văn phong). Bộ 亻(người) gợi đặc tính của người. Thấy trong tiểu triện (hanziyuan). Chưa có phân tích cấu trúc chi tiết từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên riêng)", "Hạng Tần Suất (Jun Da)": "5429.0", "Tần Suất % (Jun Da)": "99.9556572515", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 吉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻吉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "佶", "Unihan_Traditional (Chữ Phồn thể)": "佶", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "cát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ miêu tả sự cường tráng hoặc dùng trong tên riêng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缃', '{"9000": "5430.0", "Chữ Trung Quốc": "缃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 缃 | tương | tượng hình | lụa vàng phớt, màu vàng nhạt | 缃 có bộ 糸 (mịch, tơ lụa) gợi nghĩa loại vải lụa màu sắc. Không có dữ liệu cấu trúc chi tiết từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tương\": 缃 có bộ 糸 (lụa) — tấm lụa tương màu vàng nhạt như trà xanh, mỏng manh và sang trọng. | Gương Hán-Việt | 缃 xuất hiện trong \"tương thiếp\" (緗帙) — hộp bọc sách bằng lụa vàng nhạt. | Mở khoá kiến thức | Biết 缃 giúp đọc văn học cổ điển mô tả màu sắc vải vóc và đồ vật quý.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 缃 (phồn thể 緗) theo Wiktionary chỉ màu vàng nhạt hoặc lụa màu vàng nhạt. Bộ 糸 (tơ lụa) gợi nghĩa chất liệu vải. Thấy trong tiểu triện và lục thư thông. Chưa có phân tích cấu trúc chi tiết từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lụa vàng phơn phớt", "Hạng Tần Suất (Jun Da)": "5430.0", "Tần Suất % (Jun Da)": "99.9557166818", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 相", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟相", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "相", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缃", "Unihan_Traditional (Chữ Phồn thể)": "緗", "Pinyin_Xie": "xiāng", "Âm Hán Việt_Xie": "tương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Dùng làm danh từ chỉ loại lụa màu vàng nhạt hoặc làm tính từ chỉ sắc vàng này. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('晟', '{"9000": "5431.0", "Chữ Trung Quốc": "晟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 10 | nét | 晟 | thịnh | tượng hình | sáng rực, chói lọi; rực rỡ | 晟 có bộ 日 (nhật, mặt trời) gợi nghĩa ánh sáng, sự rực rỡ. Không có dữ liệu cấu trúc chi tiết từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thịnh\": 晟 có bộ 日 (mặt trời) — mặt trời thịnh vượng chói sáng, rực rỡ không gì che khuất. | Gương Hán-Việt | 晟 xuất hiện trong tên người Trung Hoa; trong Hán-Việt \"thịnh\" gợi sự hưng thịnh, sáng láng. | Mở khoá kiến thức | Biết 晟 giúp đọc tên người Trung Hoa và văn ngôn cổ miêu tả sự huy hoàng rực rỡ.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 晟 theo Wiktionary mang nghĩa sáng, rực rỡ. Bộ 日 (mặt trời) gợi nghĩa ánh sáng. Thấy trong đại triện và tiểu triện. Cũng là dạng đọc thay thế của 盛 (thịnh) và 晶 (tinh). Chưa có phân tích cấu trúc chi tiết từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sự rực rỡ của mặt trời, sự chói lọi; sáng; lửa cháy rần rật", "Hạng Tần Suất (Jun Da)": "5431.0", "Tần Suất % (Jun Da)": "99.9557761121", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 成", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱日成", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "成", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "晟", "Unihan_Traditional (Chữ Phồn thể)": "晟", "Pinyin_Xie": "chéng", "Âm Hán Việt_Xie": "thạnh, thịnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ chỉ sự sáng sủa, thịnh vượng hoặc dùng làm danh từ trong tên người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲱', '{"9000": "5432.0", "Chữ Trung Quốc": "鲱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 鲱 | phi | tượng hình | cá trích (herring) | 鲱 có bộ 魚 (ngư, cá) gợi nghĩa loài cá. Không có dữ liệu cấu trúc chi tiết từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phi\": 鲱 có bộ 魚 (cá) — cá trích phi nhanh trong đàn khổng lồ giữa đại dương lạnh. | Gương Hán-Việt | 鲱 ít xuất hiện trong tiếng Việt; trong sinh học \"phi\" chỉ cá trích. | Mở khoá kiến thức | Biết 鲱 giúp đọc tài liệu ẩm thực Nhật Bản, Bắc Âu và ngư nghiệp tiếng Trung.", "Tự nguyên_Xie": "鲱 (phồn thể 鯡) theo Wiktionary chỉ cá trích (herring). Bộ 魚 (cá) gợi nghĩa loại cá. Chưa có phân tích cấu trúc chi tiết từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá lầm", "Hạng Tần Suất (Jun Da)": "5432.0", "Tần Suất % (Jun Da)": "99.9558355424", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 非", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼非", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "非", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲱", "Unihan_Traditional (Chữ Phồn thể)": "鯡", "Pinyin_Xie": "fēi", "Âm Hán Việt_Xie": "phi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ loài cá trích trong các danh từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('凼', '{"9000": "5433.0", "Chữ Trung Quốc": "凼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 6 | nét | 凼 | đãng | tượng hình | hố nước, vũng bùn, rãnh nước nhỏ | 凼 có bộ 水 (thuỷ) gợi nghĩa liên quan đến nước. Không có dữ liệu cấu trúc chi tiết từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đãng\": 凼 có bộ 水 (nước) — cái đãng nước nhỏ ở góc ruộng, nơi nước đọng sau mưa. | Gương Hán-Việt | 凼 ít xuất hiện trong tiếng Việt; trong phương ngữ Tứ Xuyên chỉ vũng nước, hố bùn. | Mở khoá kiến thức | Biết 凼 giúp đọc tên địa danh và văn học phương ngữ Tứ Xuyên.", "Tự nguyên_Xie": "凼 không có dữ liệu Wiktionary. Chữ có bộ 水 (nước), chỉ hố nước nhỏ, vũng hoặc rãnh. Đây là chữ phương ngữ dùng chủ yếu trong tiếng Trung miền nam (đặc biệt Tứ Xuyên, Hồ Nam). Chưa có nguồn học thuật xác nhận. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hố", "Hạng Tần Suất (Jun Da)": "5433.0", "Tần Suất % (Jun Da)": "99.9558949727", "GavinGrover_Once (Chiết tự trực tiếp)": "凵 + 水", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿶ (Bao quanh phía dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴凵水", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "水", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "凵", "Unihan_Simplified (Chữ Giản thể)": "凼", "Unihan_Traditional (Chữ Phồn thể)": "凼", "Pinyin_Xie": "dàng", "Âm Hán Việt_Xie": "đãng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong khẩu ngữ phương nam để chỉ các hố nước hoặc vũng bùn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苴', '{"9000": "5434.0", "Chữ Trung Quốc": "苴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 艹 | biểu nghĩa | cỏ, cây | 且 | thả | biểu âm | 苴 = 艹 (bộ Thảo, biểu nghĩa: thực vật) + 且 (Thả, biểu âm). Chữ hình thanh: 艹 chỉ loại cây/cỏ; 且 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trở\": 苴 = cỏ (艹) + âm Thả (且) — bó cỏ gai dầu thô trở nên bao tải chắc chắn, dùng bọc hàng hóa. | Gương Hán-Việt | 苴 ít xuất hiện trong tiếng Việt hiện đại; trong văn ngôn Hán-Việt \"trở\" chỉ cây gai hoặc vải thô. | Mở khoá kiến thức | Biết 苴 giúp đọc văn ngôn cổ về lễ tang, nông nghiệp và nghi lễ dùng bao tải.", "Tự nguyên_Xie": "Giáp cốt văn | Đại triện | Tiểu triện | Theo Wiktionary, 苴 là chữ hình thanh gồm 艹 (cỏ cây) làm phần biểu nghĩa và 且 làm phần biểu âm. Nghĩa gốc: cây gai dầu cái (có hạt); vải bao tải; đệm lót. Thấy trong giáp cốt văn, đại triện, tiểu triện — chữ có lịch sử rất lâu đời. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gai có hạt; bọc, gói; mê cỏ lót giày dép", "Hạng Tần Suất (Jun Da)": "5434.0", "Tần Suất % (Jun Da)": "99.955954403", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 且", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹且", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "且", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苴", "Unihan_Traditional (Chữ Phồn thể)": "苴", "Pinyin_Xie": "jū", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ cây gai hoặc cỏ khô, hoặc làm động từ với nghĩa bao bọc, lót đế. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颛', '{"9000": "5435.0", "Chữ Trung Quốc": "颛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 15 | nét | 颛 | chuyên | tượng hình | hiền lành, đơn thuần; thận trọng | 颛 có bộ 頁 (hiệt, đầu người) gợi nghĩa liên quan đến con người hoặc tính cách. Không có dữ liệu cấu trúc chi tiết từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chuyên\": 颛 có bộ 頁 (đầu người) — người đầu óc chuyên nhất, thành thật thận trọng như Chuyên Húc — vị vua huyền thoại. | Gương Hán-Việt | 颛 xuất hiện trong \"Chuyên Húc\" (颛顼) — tên một trong Ngũ Đế thần thoại Trung Hoa. | Mở khoá kiến thức | Biết 颛 giúp đọc thần thoại Trung Hoa và văn ngôn cổ mô tả đức tính chân thành, thận trọng.", "Tự nguyên_Xie": "Tiểu triện | 颛 (phồn thể 顓) theo Wiktionary mang nghĩa hiền lành, thành thật, đơn giản. Bộ 頁 (đầu người) gợi tính cách. Thấy trong tiểu triện. Nổi tiếng nhất là tên nhân vật thần thoại Trung Hoa: Chuyên Húc (颛顼) — một trong Ngũ Đế huyền thoại. Chưa có phân tích cấu trúc chi tiết từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên riêng)", "Hạng Tần Suất (Jun Da)": "5435.0", "Tần Suất % (Jun Da)": "99.9560138333", "GavinGrover_Once (Chiết tự trực tiếp)": "耑 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耑页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "颛", "Unihan_Traditional (Chữ Phồn thể)": "顓", "Pinyin_Xie": "zhuān", "Âm Hán Việt_Xie": "chuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ chỉ sự ngu muội hoặc chuyên nhất, và làm danh từ trong tên riêng cổ đại. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('厍', '{"9000": "5436.0", "Chữ Trung Quốc": "厍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 厂 | Số nét | 6 | nét | 厍 | xá | tượng hình | họ Xá; làng, thôn xóm nhỏ | 厍 có bộ 厂 (hán) gợi ý không gian, nơi chốn. Không có dữ liệu cấu trúc chi tiết từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xá\": 厍 có bộ 厂 (nhà, không gian) — ngôi nhà/làng Xá nhỏ dưới vách núi, nơi ở của một dòng họ. | Gương Hán-Việt | 厍 xuất hiện trong họ tên Xá (厍) — một họ hiếm gặp trong tiếng Trung. | Mở khoá kiến thức | Biết 厍 giúp nhận diện họ tên và địa danh hiếm gặp trong tiếng Trung.", "Tự nguyên_Xie": "厍 (phồn thể 厙) theo Wiktionary là họ Xá trong tiếng Trung, hoặc chỉ làng nhỏ trong địa danh. Bộ 厂 (hán) gợi nghĩa không gian, nơi ở. Thấy trong văn bản cổ. Chưa có phân tích cấu trúc chi tiết từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Xá", "Hạng Tần Suất (Jun Da)": "5436.0", "Tần Suất % (Jun Da)": "99.9560727468", "GavinGrover_Once (Chiết tự trực tiếp)": "厂 + 车", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厂车", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "车", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厂", "Unihan_Simplified (Chữ Giản thể)": "厍", "Unihan_Traditional (Chữ Phồn thể)": "厙", "Pinyin_Xie": "shè", "Âm Hán Việt_Xie": "xá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng chỉ họ người hoặc địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('匚', '{"9000": "5437.0", "Chữ Trung Quốc": "匚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 匚 | Số nét | 2 | nét | 匚 | phương | tượng hình | vật đựng đồ hình hộp; bộ thủ thứ 22 trong Khang Hy tự điển | 匚 là chữ tượng hình vẽ hình một cái hộp/thùng đựng đồ nhìn nghiêng. Đây là chữ độc thể, chính là bộ thủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phương\": 匚 tượng hình cái hộp mở miệng — nhìn là thấy ngay vật đựng đồ vuông vức phương chính. | Gương Hán-Việt | 匚 xuất hiện trong bộ thủ Hán tự; \"phương\" gợi vật hình hộp, đồ đựng vuông. | Mở khoá kiến thức | Biết 匚 giúp nhận diện các chữ cùng bộ như 匠 (thợ thủ công), 匪 (kẻ cướp), 匣 (hộp đựng đồ).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Theo Wiktionary, 匚 là chữ tượng hình (liushu=pictograph) mô tả hình dạng một cái thùng hoặc hộp đựng đồ. Thấy trong giáp cốt văn, kim văn và tiểu triện — lịch sử rất lâu đời. Đây chính là bộ thủ số 22 trong Khang Hy tự điển. Cũng là dạng cổ của 放 và 方. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "519.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình dáng một cái hộp gỗ hoặc cái rương hòm có mở một mặt cạnh (để bỏ đồ vật vào trong) gọi là cái rương (phương). Giải thích sự chuyển ý: Đây là chữ Tượng hình. Vẽ lại hình dạng cái hộp đựng đồ dùng, rương hòm vuông vức có nắp đậy mặt hông (Phương).", "Nghĩa Tiếng Việt_Xie": "vật đựng đồ", "Hạng Tần Suất (Jun Da)": "5437.0", "Tần Suất % (Jun Da)": "99.9561316603", "GavinGrover_Once (Chiết tự trực tiếp)": "一 + ㇗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱一㇗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "一", "Unihan_Simplified (Chữ Giản thể)": "匚", "Unihan_Traditional (Chữ Phồn thể)": "匚", "Pinyin_Xie": "fāng", "Âm Hán Việt_Xie": "phương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ vật dụng đựng đồ thời cổ hoặc làm tên gọi của bộ thủ chữ Hán. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('徉', '{"9000": "5438.0", "Chữ Trung Quốc": "徉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彳 | Số nét | 9 | nét | 徉 | dương | tượng hình | đi lang thang, thẩn thơ; do dự | 徉 có bộ 彳(sước) gợi nghĩa đi lại, chuyển động thong thả. Không có dữ liệu cấu trúc chi tiết từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dương\": 徉 có bộ 彳(đi) — đi dạo dương dương tự đắc, thong thả như không có việc gì quan trọng. | Gương Hán-Việt | 徉 xuất hiện trong \"tường dương\" (徜徉) — đi thong dong không mục đích, ngao du. | Mở khoá kiến thức | Biết 徉 giúp đọc thơ văn cổ miêu tả cảnh đi dạo nhàn nhã, tâm hồn thư thái.", "Tự nguyên_Xie": "徉 theo Wiktionary dùng trong từ ghép 徜徉 — đi dạo thong thả không mục đích. Bộ 彳(sước) gợi chuyển động từng bước. Cũng là dạng thay thế của 佯 (dương, giả vờ). Chưa có phân tích cấu trúc chi tiết từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quanh co, vòng vèo", "Hạng Tần Suất (Jun Da)": "5438.0", "Tần Suất % (Jun Da)": "99.9561905738", "GavinGrover_Once (Chiết tự trực tiếp)": "彳 + 羊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰彳羊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "彳", "Unihan_Simplified (Chữ Giản thể)": "徉", "Unihan_Traditional (Chữ Phồn thể)": "徉", "Pinyin_Xie": "yáng", "Âm Hán Việt_Xie": "dương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường kết hợp với chữ Thường để tạo thành động từ liên miên chỉ dáng đi thong dong, lang thang. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('洙', '{"9000": "5439.0", "Chữ Trung Quốc": "洙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 水 | thủy | biểu nghĩa | nước | 朱 | chu | biểu âm | 洙 = 水 (Thủy, biểu nghĩa: nước) + 朱 (Chu, biểu âm). Chữ hình thanh: 水 chỉ con sông, nguồn nước; 朱 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chua\": 洙 = nước (水) + âm Chu (朱) — sông Chua (Thù) chảy quanh đất Khổng Tử, dòng nước chua ngọt trên đất học vấn. | Gương Hán-Việt | 洙 xuất hiện trong \"Thù Tứ\" (洙泗) — tên hai con sông gắn với quê hương Khổng Tử, biểu trưng cho văn hóa Nho giáo. | Mở khoá kiến thức | Biết 洙 giúp đọc văn chương Nho học và địa danh lịch sử tỉnh Sơn Đông.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 洙 là chữ hình thanh gồm 水 (nước) làm phần biểu nghĩa và 朱 làm phần biểu âm. Chỉ tên các con sông ở tỉnh Sơn Đông. Thấy trong tiểu triện (hanziyuan). Sông Thù (洙水) nổi tiếng vì chảy gần quê hương Khổng Tử. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Thù", "Hạng Tần Suất (Jun Da)": "5439.0", "Tần Suất % (Jun Da)": "99.9562494873", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 朱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵朱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "洙", "Unihan_Traditional (Chữ Phồn thể)": "洙", "Pinyin_Xie": "zhū", "Âm Hán Việt_Xie": "thù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng chỉ tên một con sông ở tỉnh Sơn Đông Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氡', '{"9000": "5440.0", "Chữ Trung Quốc": "氡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 气 | Số nét | 9 | nét | 气 | khí | biểu nghĩa | khí, hơi | 冬 | đông | biểu âm | 氡 = 气 (Khí, biểu nghĩa: chất khí) + 冬 (Đông, biểu âm). Chữ hình thanh: 气 chỉ nguyên tố dạng khí; 冬 cho âm đọc. Đây là chữ đặt tên cho nguyên tố radon (Rn).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đông\": 氡 = khí (气) + đông (冬) — khí radon lạnh lẽo vô hình như mùa đông, không màu không mùi nhưng có hại. | Gương Hán-Việt | 氡 xuất hiện trong khoa học: \"đông\" (氡) là tên tiếng Hán của nguyên tố radon. | Mở khoá kiến thức | Biết 氡 giúp đọc tài liệu khoa học, y tế và vật lý hạt nhân bằng tiếng Trung.", "Tự nguyên_Xie": "Theo Wiktionary, 氡 là chữ hình thanh gồm 气 (khí) làm phần biểu nghĩa và 冬 làm phần biểu âm. Đây là chữ hiện đại đặt tên cho nguyên tố radon (Rn, số hiệu nguyên tử 86). Cách đặt tên nhất quán với các nguyên tố khí hiếm khác trong tiếng Trung. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố radon, Rn", "Hạng Tần Suất (Jun Da)": "5440.0", "Tần Suất % (Jun Da)": "99.9563084008", "GavinGrover_Once (Chiết tự trực tiếp)": "气 + 冬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴气冬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "气", "Unihan_Simplified (Chữ Giản thể)": "氡", "Unihan_Traditional (Chữ Phồn thể)": "氡", "Pinyin_Xie": "dōng", "Âm Hán Việt_Xie": "đông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nguyên tố hóa học radon, thường dùng trong thuật ngữ khoa học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胗', '{"9000": "5441.0", "Chữ Trung Quốc": "胗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 9 | nét | 胗 | chẩn | tượng hình | mề chim; loét môi; phát ban | 胗 có bộ 月 (vốn là 肉, thịt) gợi nghĩa liên quan đến cơ thể, nội tạng. Không có dữ liệu cấu trúc chi tiết từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chẩn\": 胗 có bộ 月 (thịt) — mề chim chẩn chắc và dày, hoặc chỗ chẩn nổi trên da. | Gương Hán-Việt | 胗 xuất hiện trong \"chẩn\" liên quan đến y học cổ; trong ẩm thực có \"鸡胗\" (mề gà). | Mở khoá kiến thức | Biết 胗 giúp đọc thực đơn và tài liệu y học tiếng Trung về nội tạng gia cầm.", "Tự nguyên_Xie": "Tiểu triện | 胗 theo Wiktionary có hai âm đọc: zhěn (loét môi, thay thế cho 疹) và zhēn (mề chim, dạ dày chim). Bộ 月 (肉, thịt) gợi liên quan đến nội tạng. Thấy trong tiểu triện (hanziyuan). Chưa có phân tích cấu trúc chi tiết từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mề chim; mề", "Hạng Tần Suất (Jun Da)": "5441.0", "Tần Suất % (Jun Da)": "99.9563673143", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 㐱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月㐱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胗", "Unihan_Traditional (Chữ Phồn thể)": "胗", "Pinyin_Xie": "zhēn", "Âm Hán Việt_Xie": "chẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận mề của các loài gia cầm, thường dùng trong ẩm thực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('癯', '{"9000": "5442.0", "Chữ Trung Quốc": "癯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 23 | nét | 疒 | biểu nghĩa | bệnh, tật | 瞿 | biểu âm | 癯 = 疒 (bộ Nạch, biểu nghĩa: bệnh tật, thể trạng yếu) + 瞿 (biểu âm). Chữ hình thanh: 疒 chỉ tình trạng gày yếu do bệnh; 瞿 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cù\": 癯 = bệnh (疒) + âm Cù (瞿) — người ốm cù gầy gò, tiều tụy như ngọn nến gần tàn. | Gương Hán-Việt | 癯 xuất hiện trong từ Hán-Việt \"thanh cù\" (清癯) — gầy gò mà thanh tú, thường dùng để tả người học rộng. | Mở khoá kiến thức | Biết 癯 giúp đọc thơ văn cổ điển miêu tả ngoại hình người học sĩ gầy gò mà có khí chất.", "Tự nguyên_Xie": "Theo Wiktionary, 癯 là chữ hình thanh gồm 疒 (bệnh tật) làm phần biểu nghĩa và 瞿 làm phần biểu âm. Là dạng thay thế của 臞 — mang nghĩa gày còm, tiều tụy, mệt mỏi. Không có ảnh cổ tự. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gầy còm", "Hạng Tần Suất (Jun Da)": "5442.0", "Tần Suất % (Jun Da)": "99.9564262278", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 瞿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒瞿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "瞿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "癯", "Unihan_Traditional (Chữ Phồn thể)": "癯", "Pinyin_Xie": "qú", "Âm Hán Việt_Xie": "cù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả dáng vẻ gầy gò của con người, thường dùng trong văn viết cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞒', '{"9000": "5443.0", "Chữ Trung Quốc": "鞒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 15 | nét | 鞒 | kiều | tượng hình | mấu yên ngựa; giày tuyết bằng gỗ | 鞒 có bộ 革 (cách, da thuộc) gợi nghĩa vật dụng làm từ da hoặc liên quan đến ngựa. Không có dữ liệu cấu trúc chi tiết từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiều\": 鞒 có bộ 革 (da) — phần da kiều nhô lên của yên ngựa, người cưỡi ngựa tựa vào. | Gương Hán-Việt | 鞒 ít xuất hiện trong tiếng Việt; trong văn ngôn chỉ bộ phận của yên ngựa. | Mở khoá kiến thức | Biết 鞒 giúp đọc văn học lịch sử về kỵ binh và dụng cụ cưỡi ngựa cổ đại.", "Tự nguyên_Xie": "鞒 (phồn thể 鞽) theo Wiktionary không có dữ liệu cấu trúc chi tiết. Bộ 革 (da thuộc) gợi nghĩa vật dụng liên quan đến ngựa, yên cương. Chữ chỉ mấu nhô lên của yên ngựa, hoặc giày gỗ dùng đi tuyết. Chưa có nguồn học thuật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mấu trên yên ngựa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 乔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革乔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞒", "Unihan_Traditional (Chữ Phồn thể)": "鞒", "Pinyin_Xie": "qiáo", "Âm Hán Việt_Xie": "khiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận mấu nhô lên trên yên ngựa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锆', '{"9000": "5444.0", "Chữ Trung Quốc": "锆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 锆 | cáo | tượng hình | nguyên tố zirconium, Zr | 锆 có bộ 金 (kim, kim loại) gợi nghĩa nguyên tố kim loại. Không có dữ liệu cấu trúc chi tiết từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cáo\": 锆 có bộ 金 (kim loại) — kim loại cáo bền chắc, dùng trong lò phản ứng hạt nhân vì chịu nhiệt tốt. | Gương Hán-Việt | 锆 xuất hiện trong thuật ngữ khoa học; \"cáo\" là tên Hán-Việt của nguyên tố zirconium. | Mở khoá kiến thức | Biết 锆 giúp đọc tài liệu khoa học vật liệu, hạt nhân và hóa học bằng tiếng Trung.", "Tự nguyên_Xie": "锆 không có dữ liệu Wiktionary cấu trúc chi tiết. Đây là chữ hiện đại đặt tên cho nguyên tố zirconium (Zr, số hiệu nguyên tử 40). Bộ 金 (kim loại) gợi tính chất kim loại của nguyên tố. Không có ảnh cổ tự. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố ziriconi, Zr", "Hạng Tần Suất (Jun Da)": "5444.0", "Tần Suất % (Jun Da)": "99.9565440548", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 告", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅告", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "告", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锆", "Unihan_Traditional (Chữ Phồn thể)": "鋯", "Pinyin_Xie": "gào", "Âm Hán Việt_Xie": "cáo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nguyên tố hóa học ziriconi, dùng nhiều trong lĩnh vực hóa học và địa chất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佤', '{"9000": "5445.0", "Chữ Trung Quốc": "佤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 6 | nét | 佤 | ngoã | tượng hình | người Va (Wa) — dân tộc thiểu số tây nam Trung Hoa | 佤 có bộ 亻(nhân, người) gợi nghĩa liên quan đến con người, tộc người. Đây là chữ thay thế cho dạng cũ có bộ 犭(khuyển) — bộ mang hàm ý miệt thị đã bị loại bỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngoã\": 佤 có bộ 亻(người) — người (亻) tộc Ngoã (佤) Vân Nam, chữ được cải cách để xóa bỏ sự kỳ thị. | Gương Hán-Việt | 佤 xuất hiện trong \"kha ngoã\" (佧佤) hoặc \"Ngoã tộc\" (佤族) — tên tộc người Wa trong tiếng Việt. | Mở khoá kiến thức | Biết 佤 giúp đọc tài liệu dân tộc học, lịch sử vùng biên giới Vân Nam và vấn đề tộc danh trong tiếng Trung.", "Tự nguyên_Xie": "Theo Wiktionary, 佤 là chữ thay thế (replacement) cho một dạng chữ cũ có bộ 犭(khuyển — chỉ thú vật) vốn mang hàm ý miệt thị tộc người Wa. Bộ 亻(người) trung tính, tôn trọng hơn. Chỉ tộc người Va (Wa) ở tỉnh Vân Nam, Trung Hoa và vùng Đông Nam Á giáp biên giới. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(như: kha ngoã 佧佤)", "Hạng Tần Suất (Jun Da)": "5445.0", "Tần Suất % (Jun Da)": "99.9566029683", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 瓦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻瓦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "瓦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "佤", "Unihan_Traditional (Chữ Phồn thể)": "佤", "Pinyin_Xie": "wǎ", "Âm Hán Việt_Xie": "ngõa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng chỉ tộc người Ngoã hoặc vùng đất nơi họ sinh sống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('勰', '{"9000": "5446.0", "Chữ Trung Quốc": "勰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 力 | Số nét | 15 | nét | 劦 | hiệp | biểu âm | hợp lực (ba chữ Lực 力 ghép) | 思 | tư | biểu nghĩa | suy nghĩ, tâm trí | 勰 = 劦 (Hiệp, biểu âm: ba Lực hợp lại) + 思 (Tư, biểu nghĩa: suy nghĩ); chữ hình thanh. Hình ảnh tư duy hài hoà, tâm trí cân bằng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiệp\" (theo âm 劦): ba sức mạnh (劦) cùng một tâm trí (思) — hài hoà, đồng thuận. | Gương Hán-Việt | Chữ này ít xuất hiện trong từ Hán-Việt thông dụng hiện đại; chủ yếu dùng làm tên người (Lưu Hiệp — tác giả Văn Tâm Điêu Long) | Mở khoá kiến thức | Biết 勰 giúp nhận ra tên Lưu Hiệp (劉勰), nhà lý luận văn học nổi tiếng đời Lương.", "Tự nguyên_Xie": "Lục thư thông | Chữ hình thanh: 劦 là thành phần biểu âm (ba chữ Lực 力 ghép lại, biểu thị hợp lực), 思 là thành phần biểu nghĩa (tâm trí, suy nghĩ). Chỉ có dạng Lục thư thông (thời Minh), chưa thấy trong giáp cốt/kim văn — có thể là chữ tạo muộn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hoà, đều", "Hạng Tần Suất (Jun Da)": "5446.0", "Tần Suất % (Jun Da)": "99.9568381056", "GavinGrover_Once (Chiết tự trực tiếp)": "劦 + 思", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰劦思", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "思", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "劦", "Unihan_Simplified (Chữ Giản thể)": "勰", "Unihan_Traditional (Chữ Phồn thể)": "勰", "Pinyin_Xie": "xié", "Âm Hán Việt_Xie": "hiệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ chỉ sự hòa hợp, thường dùng trong tên người hoặc văn cảnh cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钺', '{"9000": "5447.0", "Chữ Trung Quốc": "钺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 金 | kim | biểu nghĩa | kim loại | 戉 | việt | biểu âm | cái búa chiến | 钺 = 金 (Kim, biểu nghĩa: kim loại) + 戉 (Việt, biểu âm: búa chiến); chữ hình thanh (và một phần hội ý). Nguyên gốc viết là 戉 — chiếc búa lớn bằng đồng dùng trong nghi lễ. Thêm bộ Kim để nhấn mạnh chất liệu kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"việt\": bộ Kim (đồng) + 戉 (búa) — 钺 là chiếc búa đồng nghi lễ, biểu tượng quyền uy của vua chúa. | Gương Hán-Việt | \"việt\" ít xuất hiện độc lập; gặp trong 斧鉞 (phủ việt — búa và rìu, biểu tượng hình phạt/quyền lực) | Mở khoá kiến thức | Biết 钺 giúp hiểu 斧鉞 (búa rìu — biểu tượng hình phạt trong văn cổ), 假黃鉞 (ban búa vàng — phong tướng quyền cao).", "Tự nguyên_Xie": "Tiểu triện | Nguyên thủy viết là 戉 — xem thêm ở chữ đó. Sau thêm bộ 金 (kim loại) để tạo thành 鉞/钺: hình thanh kiêm hội ý — 金 chỉ chất liệu đồng/bronze, 戉 vừa biểu âm vừa biểu hình cây búa. 钺 là loại búa chiến lớn bằng đồng hoặc ngọc bích, dùng trong nghi lễ hoặc hành quyết, biểu tượng quyền lực tối cao. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái búa lớn, cái kích (vũ khí); sao Việt", "Hạng Tần Suất (Jun Da)": "5447.0", "Tần Suất % (Jun Da)": "99.9568965023", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 戉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅戉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钺", "Unihan_Traditional (Chữ Phồn thể)": "鉞", "Pinyin_Xie": "yuè", "Âm Hán Việt_Xie": "việt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại vũ khí cổ hình chiếc búa lớn hoặc chòm sao trên trời. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繇', '{"9000": "5448.0", "Chữ Trung Quốc": "繇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 17 | nét | 䍃 | diêu | biểu âm | 系 | hệ | biểu nghĩa | sợi dây, kết nối | 繇 = 䍃 (Diêu, biểu âm) + 系 (Hệ, biểu nghĩa: sợi/kết nối); chữ hình thanh. Dạng gốc viết là 䌛. Chữ đa âm: đọc yáo (lời bói), yóu (từ), zhòu (lời giải quẻ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diêu\" (theo âm 䍃): sợi Hệ (系) xuyên qua âm Diêu — 繇 là lời bói nối kết quá khứ với tương lai như sợi chỉ. | Gương Hán-Việt | Ít dùng trong tiếng Việt hiện đại; gặp trong tên cổ như 皋繇 (Cao Dao — nhân vật thần thoại phán xét) | Mở khoá kiến thức | Biết 繇 giúp đọc văn cổ: 繇辭 (lời bói quẻ), 徭役 (lao dịch — dù thường viết bằng 徭).", "Tự nguyên_Xie": "Tiểu triện | Nguyên gốc viết là 䌛. Sau trở thành hình thanh: 系 (sợi dây, kết nối) là thành phần biểu nghĩa, 䍃 là thành phần biểu âm. Chữ đa âm đa nghĩa: đọc yáo có nghĩa lao dịch (tương tự 徭), dân ca (tương tự 謠); đọc yóu có nghĩa từ/bởi (tương tự 由); đọc zhòu có nghĩa lời bói quẻ (liên quan đến 籀). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lời xem quẻ bói", "Hạng Tần Suất (Jun Da)": "5448.0", "Tần Suất % (Jun Da)": "99.956954899", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 系", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰系", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "繇", "Unihan_Traditional (Chữ Phồn thể)": "繇", "Pinyin_Xie": "yáo", "Âm Hán Việt_Xie": "diêu, lựu, chựu, do", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ lời giải thích của các quẻ bói hoặc bài hát dân gian thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螭', '{"9000": "5449.0", "Chữ Trung Quốc": "螭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 虫 | trùng | biểu nghĩa | sinh vật, côn trùng/bò sát | 离 | ly | biểu âm | 螭 = 虫 (Trùng, biểu nghĩa: sinh vật huyền thoại/loài bò sát) + 离 (Ly, biểu âm); chữ hình thanh. 虫 trong văn cổ chỉ mọi loài sinh vật nhỏ, đặc biệt bò sát và côn trùng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"li\" (theo âm 离): bộ Trùng (sinh vật) + âm Ly — 螭 là rồng con chưa mọc sừng, như li không thể rời (离) bầy. | Gương Hán-Việt | \"li\" trong li long (螭龍 — rồng không sừng), ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 螭 giúp đọc văn học cổ và nhận ra các họa tiết trang trí 螭紋 (hoa văn rồng li) trên cổ vật.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 虫 (sinh vật) là thành phần biểu nghĩa, chỉ 螭 là một loài sinh vật huyền thoại. 离 là thành phần biểu âm. Dạng tiểu triện đã thể hiện cấu trúc này. 螭 là con rồng không có sừng trong truyền thuyết Trung Hoa, thường dùng trang trí kiến trúc và đồ vật. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con Li (con rồng không sừng trong truyền thuyết để trang trí các công trình kiến trúc hoặc công nghệ phẩm); con li; yêu quái", "Hạng Tần Suất (Jun Da)": "5449.0", "Tần Suất % (Jun Da)": "99.9570132957", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 离", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫离", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "离", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螭", "Unihan_Traditional (Chữ Phồn thể)": "螭", "Pinyin_Xie": "chī", "Âm Hán Việt_Xie": "li", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài rồng không sừng trong truyền thuyết hoặc họa tiết trang trí hình rồng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嵬', '{"9000": "5450.0", "Chữ Trung Quốc": "嵬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 12 | nét | 嵬 | ngôi | tượng hình | núi đá cheo leo, cao ngất | 嵬 là chữ độc lập, không phân tích được thêm qua cấu trúc hình thanh/hội ý rõ ràng từ nguồn. Dạng tiểu triện và Lục thư thông cho thấy hình núi đá cao ngất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngôi\": hình núi đá cao và gập ghềnh — 嵬 gợi hình ảnh ngọn núi ngôi nghiêng, cheo leo khó trèo. | Gương Hán-Việt | \"ngôi\" ít dùng trong từ Hán-Việt thông dụng; gặp trong 崔嵬 (tuy ngôi — núi cao cheo leo) trong thơ cổ | Mở khoá kiến thức | Biết 嵬 giúp đọc thơ cổ: 崔嵬 (núi cao cheo leo), 馬嵬 (Mã Ngôi — địa danh lịch sử, nơi Dương Quý Phi bị xử tử).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary không cung cấp phân tích thành tố cho 嵬. Dựa vào cấu trúc thị giác: chữ chứa bộ 山 (núi) và có dáng biểu thị sự cheo leo, bất quy tắc. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "núi đá", "Hạng Tần Suất (Jun Da)": "5450.0", "Tần Suất % (Jun Da)": "99.9570711756", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 鬼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山鬼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鬼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "嵬", "Unihan_Traditional (Chữ Phồn thể)": "嵬", "Pinyin_Xie": "wéi", "Âm Hán Việt_Xie": "ngôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ miêu tả địa hình núi non cao lớn, hiểm trở hoặc gập ghềnh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轸', '{"9000": "5451.0", "Chữ Trung Quốc": "轸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 9 | nét | 轸 | chẩn | tượng hình | thanh gỗ ngang sau xe, khung xe | 轸 là chữ không có phân tích thành tố rõ ràng từ nguồn Wiktionary. Cấu trúc thị giác có bộ 車 (xa — xe). Chữ tạo muộn, chưa thấy phân tích hội ý hay hình thanh cụ thể ngoài dạng kim văn và tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chẩn\": bộ Xa (車 — xe) + phần ngang phía sau — 轸 là thanh gỗ chẩn đỡ đáy xe, cũng là điểm tựa của trái tim đau (chẩn ưu — nỗi sầu). | Gương Hán-Việt | \"chẩn\" trong 軫憂 (chẩn ưu — sầu muộn, trong văn cổ), Chẩn tú (sao Chẩn — một trong Nhị thập bát tú) | Mở khoá kiến thức | Biết 轸 giúp nhận chòm sao Chẩn (軫宿) trong thiên văn cổ và cụm 軫懷 (chẩn hoài — mang lòng thương xót).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Wiktionary không cung cấp phân tích thành tố tường minh cho 軫/轸. Chữ liên quan đến xe cộ — có bộ 車. Dạng kim văn và tiểu triện đã tồn tại. Nghĩa gốc: thanh gỗ ngang phía sau xe, khung xe; mở rộng sang nghĩa đau lòng/sầu muộn và tên chòm sao Chẩn. Chưa có nguồn học thuật rõ ràng về cấu trúc nội tại. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thanh gỗ bắc ngang sau xe, khung xe; sao Chẩn (một trong Nhị thập bát tú)", "Hạng Tần Suất (Jun Da)": "5451.0", "Tần Suất % (Jun Da)": "99.9571290556", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 㐱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车㐱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "轸", "Unihan_Traditional (Chữ Phồn thể)": "軫", "Pinyin_Xie": "zhěn", "Âm Hán Việt_Xie": "chẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ bộ phận xe hoặc tính từ chỉ sự đau thương, lo lắng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肟', '{"9000": "5452.0", "Chữ Trung Quốc": "肟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 7 | nét | 肟 | ốc | tượng hình | oxim (hợp chất hữu cơ) | 肟 là chữ hiện đại dùng trong hóa học để phiên âm thuật ngữ oxime từ tiếng Anh/Đức. Không có phân tích thành tố hình-thanh cổ điển. Bộ 肉/月 có thể chỉ chất hữu cơ, phần còn lại biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ốc\" (phỏng đoán): bộ Nhục (月 — chất hữu cơ) ghép biểu âm — 肟 là ký hiệu hóa học mới, dùng trong oxim. | Gương Hán-Việt | Ít dùng trong tiếng Việt; xuất hiện trong văn bản hóa học chuyên ngành | Mở khoá kiến thức | Biết 肟 giúp đọc tài liệu hóa học Trung Văn: 肟化 (tạo oxim), 酮肟 (ketoxime).", "Tự nguyên_Xie": "肟 là chữ tạo mới trong thời hiện đại để phiên âm thuật ngữ hóa học oxime (C=N-OH). Không có nguồn giáp cốt hay kim văn. Chưa có nguồn học thuật về nguồn gốc chữ viết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "oxim (hợp chất hữu cơ) (Anh: oxime)", "Hạng Tần Suất (Jun Da)": "5452.0", "Tần Suất % (Jun Da)": "99.9571869355", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 亏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月亏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "肟", "Unihan_Traditional (Chữ Phồn thể)": "肟", "Pinyin_Xie": "wò", "Âm Hán Việt_Xie": "ốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong hóa học để chỉ nhóm hợp chất hữu cơ oxim. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肫', '{"9000": "5453.0", "Chữ Trung Quốc": "肫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 8 | nét | 肫 | chun | tượng hình | mề gà/vịt; chân thành | 肫 không có phân tích thành tố rõ ràng từ Wiktionary. Bộ 肉 (nhục) gợi liên quan đến cơ thể/nội tạng. Nghĩa gốc liên quan đến má (mặt) và mề chim.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chun\" (theo âm zhūn): bộ Nhục (nội tạng) — 肫 là mề gà, túi chứa thức ăn chăm chỉ, chân thành như chiếc mề không từ chối gì. | Gương Hán-Việt | \"chun\" ít dùng trong tiếng Việt; gặp trong 雞肫 (kê chun — mề gà) | Mở khoá kiến thức | Biết 肫 giúp đọc thực đơn và văn cổ: 雞肫 (mề gà), 鴨肫 (mề vịt), 肫肫 (thành thật, thiết tha trong văn cổ).", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích thành tố tường minh cho 肫. Chữ có bộ 肉 (thịt, nội tạng). Nghĩa gốc: má; mở rộng sang mề chim và ý nghĩa văn học ''chân thành''. Đọc zhūn có nghĩa mề; đọc chún là dị thể của 純; đọc tún là dị thể của 豚. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thành khẩn; thành thật; thật thà; mề; bao tử", "Hạng Tần Suất (Jun Da)": "5453.0", "Tần Suất % (Jun Da)": "99.9572448155", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 屯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月屯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "肫", "Unihan_Traditional (Chữ Phồn thể)": "肫", "Pinyin_Xie": "zhūn", "Âm Hán Việt_Xie": "truân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Làm danh từ chỉ dạ dày cơ của gia cầm hoặc tính từ thể hiện sự thành thật, khẩn thiết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邨', '{"9000": "5454.0", "Chữ Trung Quốc": "邨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 6 | nét | 屯 | đồn | biểu âm | 邑 | ấp | biểu nghĩa | thành ấp, khu dân cư | 邨 = 屯 (Đồn, biểu âm) + 邑 (Ấp, biểu nghĩa: khu dân cư, thành ấp); chữ hình thanh. 邑 ở vị trí bên phải thường viết thành bộ 阝phải (phụ). Dị thể của 村.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thôn\" (theo nghĩa 村): bộ Ấp (邑 — khu dân cư) + âm Đồn — 邨 là nơi dân đồn trú thành làng xóm. | Gương Hán-Việt | \"thôn\" trong thôn làng, thôn xóm (thường viết 村 hơn là 邨 trong tiếng Việt hiện đại) | Mở khoá kiến thức | Biết 邨 giúp đọc địa danh Hồng Kông và văn cổ: 邨屋 (nhà thôn xóm), 渔邨 (làng chài).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 邑 (ấp, khu dân cư) là thành phần biểu nghĩa, 屯 là thành phần biểu âm. 邨 là dị thể cổ của 村 — cùng nghĩa thôn xóm, làng quê. Dạng tiểu triện đã thể hiện cấu trúc này. Trong chữ Hán hiện đại, 村 phổ biến hơn, 邨 còn dùng trong tên địa danh (đặc biệt ở Hồng Kông, Đài Loan). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thôn xóm, nhà quê", "Hạng Tần Suất (Jun Da)": "5454.0", "Tần Suất % (Jun Da)": "99.9573026954", "GavinGrover_Once (Chiết tự trực tiếp)": "屯 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰屯阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邨", "Unihan_Traditional (Chữ Phồn thể)": "邨", "Pinyin_Xie": "cūn", "Âm Hán Việt_Xie": "thôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ làng quê, thôn xóm, là dạng viết khác của chữ thôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘿', '{"9000": "5455.0", "Chữ Trung Quốc": "瘿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 16 | nét | 疒 | nạch | biểu nghĩa | bệnh tật | 嬰 | anh | biểu âm | 瘿 = 疒 (Nạch, biểu nghĩa: bệnh tật) + 嬰 (Anh, biểu âm); chữ hình thanh. Nguyên thủy là tượng hình: hình người phụ nữ có khối u ở cổ. Sau phát triển thành hình thanh với 疒 biểu nghĩa bệnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"anh\" (theo âm 嬰): bộ Nạch (bệnh) + âm Anh — 瘿 là cái bướu bệnh (anh) mọc ở cổ, như vật thừa thãi bám vào. | Gương Hán-Việt | Ít dùng trong tiếng Việt; xuất hiện trong từ y học cổ 癭瘤 (bướu cổ/khối u) | Mở khoá kiến thức | Biết 瘿 giúp đọc văn y học cổ: 癭瘤 (bướu u), 蟲癭 (nốt sùi do côn trùng trên cây).", "Tự nguyên_Xie": "Giáp cốt văn | Ban đầu là tượng hình (liushutong): hình người phụ nữ có bướu cổ. Về sau trở thành hình thanh: 疒 (bệnh tật) là thành phần biểu nghĩa, 嬰 là thành phần biểu âm. Thú vị là 嬰 lại dùng 瘿 làm thành phần biểu âm trong tiền sử, như thấy trong đồng thư. Nghĩa: bướu cổ (goitre), u cục; mở rộng sang nghĩa ''gánh nặng, thứ thừa''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bướu ở cổ", "Hạng Tần Suất (Jun Da)": "5455.0", "Tần Suất % (Jun Da)": "99.9573605753", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 婴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒婴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "婴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘿", "Unihan_Traditional (Chữ Phồn thể)": "癭", "Pinyin_Xie": "yǐng", "Âm Hán Việt_Xie": "anh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ khối u, bướu trên cổ người hoặc vết lồi lõm trên thân cây. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('仞', '{"9000": "5456.0", "Chữ Trung Quốc": "仞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 5 | nét | 仞 | nhận | tượng hình | đơn vị đo chiều cao/sâu (khoảng 2-3 mét) | 仞 không có phân tích thành tố rõ ràng từ Wiktionary. Chữ có bộ 人 (亻 — người). Có thể là hình thanh với 亻 biểu nghĩa người/đo bằng người, phần còn lại biểu âm — nhưng chưa được xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhận\": bộ Nhân (亻 — người) + đo chiều cao — 仞 là đơn vị đo bằng chiều cao người, dùng tả núi cao vạn nhận. | Gương Hán-Việt | \"nhận\" trong 千仞 (thiên nhận — ngàn nhận), 萬仞 (vạn nhận — cao muôn trượng, trong thơ cổ) | Mở khoá kiến thức | Biết 仞 giúp đọc thơ tả núi cao: 千仞 (ngàn nhận cao), 壁立千仞 (vách đá đứng nghìn nhận).", "Tự nguyên_Xie": "Wiktionary không phân tích cấu trúc nội tại của 仞. Chữ liên quan đến đơn vị đo lường của người (亻 bộ Nhân). Đơn vị 仞 được định nghĩa khác nhau: 8 thước, 7 thước, hay 4-5 thước tùy thời đại. Cũng dùng như dị thể của 刃 (lưỡi dao), 牣 (đầy), 認 (nhận ra), v.v. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhận (đơn vị đo thời nhà Chu, bằng 1/8 trượng)", "Hạng Tần Suất (Jun Da)": "5456.0", "Tần Suất % (Jun Da)": "99.9574179385", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 刃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻刃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "仞", "Unihan_Traditional (Chữ Phồn thể)": "仞", "Pinyin_Xie": "rèn", "Âm Hán Việt_Xie": "nhận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Động từ | 动词 | Thường dùng làm lượng từ đo lường thời cổ hoặc động từ mang nghĩa đo đạc chiều cao, độ sâu. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('奁', '{"9000": "5457.0", "Chữ Trung Quốc": "奁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 大 | Số nét | 7 | nét | 奁 | liêm | tượng hình | hộp gương, hộp đựng đồ trang sức của phụ nữ | 奁 là dạng giản thể của 奩. 奩 có cấu trúc phức tạp với 匸 (hộp) và 區 (khu vực). 奁 đơn giản hóa phần 區 thành 区. Chữ tạo muộn, thấy trong tiểu triện và Lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêm\": hộp (匸) chứa vật quý của người con gái — 奁 là chiếc tráp hồi môn, đựng đồ trang sức và gương soi. | Gương Hán-Việt | \"liêm\" trong 妝奩 (trang liêm — hộp trang điểm), 奩具 (liêm cụ — đồ trong hộp trang sức) | Mở khoá kiến thức | Biết 奁 giúp đọc thơ từ tả phụ nữ: 妝奁 (tráp trang điểm), 奩田 (ruộng hồi môn), 奩贈 (đồ tặng theo cô dâu).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 奁 là dạng giản thể của 奩 (hộp gương, tráp trang sức của phụ nữ). 奩 có cấu trúc hộp (匸) chứa đồ vật (區). Dạng tiểu triện và Lục thư thông cho thấy hình chiếc hộp với nắp. Chữ tạo muộn, không thấy trong giáp cốt/kim văn. Nghĩa chính: hộp gương, tráp đựng đồ trang điểm; mở rộng sang của hồi môn, đồ sính lễ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái hộp gương", "Hạng Tần Suất (Jun Da)": "5457.0", "Tần Suất % (Jun Da)": "99.9574753016", "GavinGrover_Once (Chiết tự trực tiếp)": "大 + 区", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱大区", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "区", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "大", "Unihan_Simplified (Chữ Giản thể)": "奁", "Unihan_Traditional (Chữ Phồn thể)": "匲", "Pinyin_Xie": "lián", "Âm Hán Việt_Xie": "liêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ chiếc hộp đựng đồ trang điểm hoặc của hồi môn của cô dâu ngày xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('宄', '{"9000": "5458.0", "Chữ Trung Quốc": "宄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 5 | nét | 宀 | miên | biểu nghĩa | mái nhà | 九 | cửu | biểu âm | 宄 = 宀 (Miên, biểu nghĩa: mái nhà) + 九 (Cửu, biểu âm); chữ hình thanh. Mái nhà (宀) ám chỉ kẻ trộm ẩn nấp bên trong/bên ngoài nhà — kẻ gian trong tường nhà.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỷ\" (theo âm guǐ): mái nhà (宀) che giấu kẻ gian (九 — uốn éo lẩn tránh) — 宄 là tên bọn gian tặc ẩn mình dưới mái nhà. | Gương Hán-Việt | \"quỷ\" trong 奸宄 (gian quỷ — kẻ phản loạn, phần tử nguy hiểm); ít dùng độc lập | Mở khoá kiến thức | Biết 宄 giúp đọc văn cổ về trật tự xã hội: 奸宄 (kẻ gian phản loạn), 庇匿奸宄 (che giấu phần tử nguy hiểm).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Chữ hình thanh: 宀 (mái nhà) là thành phần biểu nghĩa — gợi ý kẻ gian ẩn nấp trong/quanh nhà; 九 là thành phần biểu âm. Dạng giáp cốt văn và tiểu triện đã thể hiện cấu trúc này. Nghĩa: kẻ xấu, kẻ phản loạn, phần tử nguy hiểm ẩn náu trong cộng đồng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gian, trộm cướp", "Hạng Tần Suất (Jun Da)": "5458.0", "Tần Suất % (Jun Da)": "99.9575326648", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + 九", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀九", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "九", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "宀", "Unihan_Simplified (Chữ Giản thể)": "宄", "Unihan_Traditional (Chữ Phồn thể)": "宄", "Pinyin_Xie": "guǐ", "Âm Hán Việt_Xie": "quỹ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ kẻ gian ác, phản nghịch hoặc kẻ trộm cắp nội bộ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轳', '{"9000": "5459.0", "Chữ Trung Quốc": "轳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 9 | nét | 轳 | lô | tượng hình | ròng rọc, máy tời (thường dùng trong 轆轤) | 轳 không có phân tích thành tố rõ ràng từ Wiktionary. Bộ 車 (xe) gợi liên quan đến cơ chế chuyển động. Chủ yếu dùng trong từ ghép 轆轤 (máy tời/ròng rọc).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lô\": bộ Xa (車 — bánh xe) quay tròn — 轳 là phần ròng rọc quay trong máy tời 轆轤, bánh xe lăn kéo nước lên. | Gương Hán-Việt | \"lô\" trong 轆轤 (lộc lô — máy tời, ròng rọc giếng) | Mở khoá kiến thức | Biết 轳 giúp đọc văn cổ và kỹ thuật cổ: 轆轤 (máy tời giếng), 辘轳格 (kiểu thơ vần xoắn).", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích thành tố cho 轤/轳. Chữ tạo muộn, không thấy dạng giáp cốt/kim văn. Chủ yếu xuất hiện trong 轆轤 — máy tời dùng để kéo nước từ giếng hoặc kéo thuyền. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lộc lô 轆轤,辘轳)", "Hạng Tần Suất (Jun Da)": "5459.0", "Tần Suất % (Jun Da)": "99.9575900279", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 卢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车卢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "轳", "Unihan_Traditional (Chữ Phồn thể)": "轤", "Pinyin_Xie": "lú", "Âm Hán Việt_Xie": "lô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong từ ghép để chỉ hệ thống ròng rọc hoặc trục quay giếng nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('熳', '{"9000": "5460.0", "Chữ Trung Quốc": "熳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 15 | nét | 熳 | mạn | tượng hình | rực rỡ, lan tràn (thường dùng trong 爛熳/烂漫) | 熳 không có phân tích thành tố rõ ràng từ Wiktionary. Bộ 火 (hỏa — lửa) gợi ý nghĩa lan tràn rực rỡ. Chủ yếu dùng trong 爛熳 (rực rỡ, hồn nhiên).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạn\": bộ Hỏa (lửa) lan tràn (mạn) — 熳 là ngọn lửa bùng cháy rực rỡ, lan ra khắp nơi tự nhiên hồn nhiên. | Gương Hán-Việt | \"mạn\" trong 爛熳 (lan mạn — rực rỡ, hồn nhiên); ít dùng độc lập | Mở khoá kiến thức | Biết 熳 giúp đọc thơ văn: 爛熳 (rực rỡ), 熳熳 (hồn nhiên lan tràn).", "Tự nguyên_Xie": "熳 không có nguồn gốc được phân tích trong Wiktionary. Bộ 火 (lửa) là thành phần gợi ý nghĩa. Chủ yếu xuất hiện trong từ ghép 爛熳/烂漫 — rực rỡ, hồn nhiên tự nhiên. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rực rỡ; hồn nhiên; chân chất", "Hạng Tần Suất (Jun Da)": "5460.0", "Tần Suất % (Jun Da)": "99.9576473911", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 曼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火曼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "熳", "Unihan_Traditional (Chữ Phồn thể)": "熳", "Pinyin_Xie": "màn", "Âm Hán Việt_Xie": "mạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Dùng làm tính từ miêu tả hoa nở rực rỡ hoặc ánh lửa lan tỏa rộng khắp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睇', '{"9000": "5461.0", "Chữ Trung Quốc": "睇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 12 | nét | 睇 | đệ | tượng hình | liếc nhìn, hé mắt nhìn | 睇 không có phân tích thành tố rõ ràng từ Wiktionary. Bộ 目 (mục — mắt) là thành phần biểu nghĩa, chỉ hành động nhìn. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đệ\": bộ Mục (mắt) liếc nhìn — 睇 là ánh mắt hé liếc, nhẹ nhàng nhưng sắc sảo như con mắt đệ tử quan sát sư phụ. | Gương Hán-Việt | \"đệ\" ít dùng trong tiếng Việt; 睇 phổ biến trong tiếng Quảng Đông (dì — nhìn, xem) | Mở khoá kiến thức | Biết 睇 giúp đọc thơ cổ tả ánh mắt: 睇眄 (đệ miến — liếc nhìn), cũng gặp trong văn học Quảng Đông.", "Tự nguyên_Xie": "Tiểu triện | 睇 không có nguồn gốc phân tích từ Wiktionary. Bộ 目 (mắt) gợi ý hành động nhìn. Dạng tiểu triện đã tồn tại. Nghĩa: liếc mắt nhìn, hé mắt nhìn — thường mang hàm ý nhìn liếc hoặc nhìn chăm chú. Chưa có nguồn học thuật rõ ràng về cấu trúc nội tại. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hé mắt nhìn", "Hạng Tần Suất (Jun Da)": "5461.0", "Tần Suất % (Jun Da)": "99.9577047542", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 弟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目弟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睇", "Unihan_Traditional (Chữ Phồn thể)": "睇", "Pinyin_Xie": "dì", "Âm Hán Việt_Xie": "đệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước tân ngữ để chỉ hành động liếc nhìn hoặc nhìn trộm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钼', '{"9000": "5462.0", "Chữ Trung Quốc": "钼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 金 | kim | biểu nghĩa | kim loại | 目 | mục | biểu âm | 钼 = 金 (Kim, biểu nghĩa: kim loại) + 目 (Mục, biểu âm); chữ hình thanh. Đây là chữ tạo mới trong hóa học hiện đại để ký hiệu nguyên tố Molybden (Mo).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mục\": Kim (kim loại) + Mục (mắt) — 钼 là kim loại \"mục\" — molybden, nguyên tố cứng như ánh mắt sắc bén. | Gương Hán-Việt | Ít dùng trong tiếng Việt thông thường; xuất hiện trong văn bản hóa học/luyện kim | Mở khoá kiến thức | Biết 钼 giúp đọc tài liệu hóa học và luyện kim Trung Văn: 钼钢 (thép molybden), 钼酸 (molybdic acid).", "Tự nguyên_Xie": "钼 là chữ tạo mới để phiên âm nguyên tố hóa học Molybdenum (Mo, số nguyên tử 42). Cấu trúc hình thanh: 金 (kim loại) biểu nghĩa — vì Mo là kim loại; 目 (mục, âm mù) biểu âm gần với âm mù/mu của molybdenum. Dạng phồn thể 鉬 có cùng cấu trúc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố molipden, Mo", "Hạng Tần Suất (Jun Da)": "5462.0", "Tần Suất % (Jun Da)": "99.9577621174", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 目", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅目", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "目", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钼", "Unihan_Traditional (Chữ Phồn thể)": "鉬", "Pinyin_Xie": "mù", "Âm Hán Việt_Xie": "mục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nguyên tố kim loại, thường đứng độc lập hoặc làm định ngữ trong thuật ngữ hóa học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝼', '{"9000": "5463.0", "Chữ Trung Quốc": "蝼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 虫 | trùng | biểu nghĩa | côn trùng | 娄 | lâu | biểu âm | 蝼 = 虫 (Trùng, biểu nghĩa: côn trùng) + 娄 (Lâu, biểu âm); chữ hình thanh. Chỉ con dế dũi (mole cricket), loài côn trùng đào hang dưới đất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lâu\" (theo âm 娄): bộ Trùng (côn trùng) + âm Lâu — 蝼 là con sâu lâu năm ẩn dưới đất, đục phá rễ cây. | Gương Hán-Việt | \"lâu\" trong 螻蛄 (lâu cô — con dế dũi), 螻蟈 (lâu quắc — ếch đồng/dế mèn) | Mở khoá kiến thức | Biết 蝼 giúp đọc văn cổ về côn trùng và ẩn dụ khiêm tốn: 螻蛄之志 (chí con dế dũi — tự khiêm).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 虫 (côn trùng) là thành phần biểu nghĩa, 娄 là thành phần biểu âm (âm lâu). Dạng tiểu triện đã thể hiện cấu trúc này. Trong chữ Nôm tiếng Việt, 蝼 được dùng cho các từ ''sâu'', ''châu'' (châu chấu). 蝼 = con dế dũi (Gryllotalpa africana), loài sâu hại mùa màng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lâu cô 螻蛄,蝼蛄); (xem: lâu quắc 螻蟈,蝼蝈)", "Hạng Tần Suất (Jun Da)": "5463.0", "Tần Suất % (Jun Da)": "99.9578194805", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 娄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫娄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "娄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝼", "Unihan_Traditional (Chữ Phồn thể)": "螻", "Pinyin_Xie": "lóu", "Âm Hán Việt_Xie": "lâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ liên kết với các chữ khác để tạo thành tên gọi các loài côn trùng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跆', '{"9000": "5464.0", "Chữ Trung Quốc": "跆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 12 | nét | 跆 | đài | tượng hình | giẫm đạp, đá (chân) | 跆 không có phân tích thành tố rõ ràng từ Wiktionary. Bộ 足 (túc — chân) là thành phần biểu nghĩa, gợi hành động dùng chân. Phần còn lại có thể biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đài\": bộ Túc (chân) đạp mạnh — 跆 là cú đạp trong 跆拳道 (Taekwondo), chân nâng lên cao rồi đạp xuống. | Gương Hán-Việt | \"đài\" ít dùng độc lập; nổi tiếng trong 跆拳道 (đài quyền đạo — Taekwondo) | Mở khoá kiến thức | Biết 跆 giúp đọc về môn võ Taekwondo: 跆拳道 (Taekwondo), 跆籍 (giẫm đạp trong văn cổ).", "Tự nguyên_Xie": "Wiktionary không phân tích cấu trúc nội tại của 跆. Bộ 足 (chân) gợi ý nghĩa hành động bằng chân — giẫm đạp. Không có dạng giáp cốt hay kim văn. Nổi tiếng nhất qua 跆拳道 (Taekwondo — môn võ Hàn Quốc). Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giẫm đạp, đá", "Hạng Tần Suất (Jun Da)": "5464.0", "Tần Suất % (Jun Da)": "99.9578768437", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 台", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊台", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "台", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跆", "Unihan_Traditional (Chữ Phồn thể)": "跆", "Pinyin_Xie": "tái", "Âm Hán Việt_Xie": "đài", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động của chân, thường xuất hiện trong các từ ghép liên quan đến võ thuật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('樗', '{"9000": "5465.0", "Chữ Trung Quốc": "樗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 15 | nét | 木 | mộc | biểu nghĩa | cây | 雩 | vu | biểu âm | 樗 = 木 (Mộc, biểu nghĩa: cây) + 雩 (Vu, biểu âm); chữ hình thanh. Chỉ loài cây Ailanthus altissima (cây thiên đường/thầu dầu) — loại cây cao lớn nhưng gỗ vô dụng, trong văn học Trung Hoa tượng trưng cho người tài năng bị coi thường.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vụ\": bộ Mộc (cây) + âm Vu — 樗 là cây vụ vô dụng, nhưng Trang Tử nói: chính vì vô dụng mà sống thọ. | Gương Hán-Việt | \"vụ\" trong 樗散 (vụ tán — vô dụng phân tán); ẩn dụ tự khiêm trong văn học | Mở khoá kiến thức | Biết 樗 giúp đọc Trang Tử và văn học cổ: 樗散 (vô dụng), 樗材 (tài năng vô dụng — tự khiêm), 樗蒲 (trò đánh xúc xắc cổ đại).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 木 (cây) là thành phần biểu nghĩa, 雩 là thành phần biểu âm. Dạng tiểu triện và Lục thư thông đã thể hiện cấu trúc này. 樗 là cây Ailanthus glandulosa/altissima — cây to nhưng gỗ mềm vô dụng làm đồ mộc, do đó trong Trang Tử dùng ẩn dụ ''cây vô dụng'' để nói về sự tự do không bị lợi dụng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây thầu dầu; cây thanh thất; cây thiên đường (tree of heaven)", "Hạng Tần Suất (Jun Da)": "5465.0", "Tần Suất % (Jun Da)": "99.9579342068", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 雩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木雩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "樗", "Unihan_Traditional (Chữ Phồn thể)": "樗", "Pinyin_Xie": "chū", "Âm Hán Việt_Xie": "sư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cây thân gỗ, thường dùng trong văn học cổ hoặc tên gọi thực vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲰', '{"9000": "5466.0", "Chữ Trung Quốc": "鲰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 鲰 | tâu | tượng hình | cá nhỏ, người thấp hèn nhỏ bé | 鲰 không có phân tích thành tố rõ ràng từ Wiktionary. Bộ 魚 (ngư — cá) là thành phần biểu nghĩa. Dạng tiểu triện đã tồn tại. Thường dùng trong 鯫生 (tâu sinh — kẻ hèn mọn, trong văn cổ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tâu\": bộ Ngư (cá) nhỏ — 鲰 là con cá tép nhỏ nhoi, ẩn dụ người tầm thường yếu ớt. | Gương Hán-Việt | \"tâu\" ít dùng trong tiếng Việt; gặp trong 鯫生 (tâu sinh — kẻ hèn mọn, Sử Ký) | Mở khoá kiến thức | Biết 鲰 giúp đọc Sử Ký: 鯫生說我 (kẻ hèn tầm thường khuyên ta — Hạng Vũ nói).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không phân tích cấu trúc nội tại của 鯫/鲰. Bộ 魚 (cá) gợi ý nghĩa cá nhỏ. Nghĩa mở rộng: người nhỏ bé hèn kém. Dạng tiểu triện đã tồn tại. 鯫生 xuất hiện trong Sử Ký — Hạng Vũ dùng để tự chê mình là ''kẻ tầm thường''. Chưa có nguồn học thuật rõ ràng về cấu trúc nội tại. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con cá tép", "Hạng Tần Suất (Jun Da)": "5466.0", "Tần Suất % (Jun Da)": "99.95799157", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 取", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼取", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "取", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲰", "Unihan_Traditional (Chữ Phồn thể)": "鯫", "Pinyin_Xie": "zōu", "Âm Hán Việt_Xie": "tưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ loài cá nhỏ hoặc tính từ ví von người có địa vị thấp kém. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诶', '{"9000": "5467.0", "Chữ Trung Quốc": "诶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 9 | nét | 诶 | ai | tượng hình | tiếng thán từ: ơi, chao ôi, ừ | 诶 là dạng giản thể của 誒. Bộ 讠(言 — lời nói) là thành phần biểu nghĩa — đây là âm thanh thốt ra bằng miệng. Chữ chủ yếu dùng như thán từ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ai\": bộ Ngôn (lời nói) — 诶 là tiếng thốt ra khi nghe ai gọi hoặc khi ngạc nhiên, như \"ơi\" hay \"ừ\" trong tiếng Việt. | Gương Hán-Việt | \"ai\" ít dùng trong tiếng Việt; 诶 là thán từ khẩu ngữ Trung Quốc hiện đại | Mở khoá kiến thức | Biết 诶 giúp hiểu hội thoại hàng ngày: 诶！(éi — ừ, được rồi), 诶？(ēi — ủa?), dùng nhiều trong phim/truyện hiện đại.", "Tự nguyên_Xie": "Tiểu triện | 诶 là dạng giản thể của 誒, xem thêm ở đó. Bộ 言 (lời nói) biểu nghĩa — đây là thán từ. Dạng tiểu triện đã tồn tại. Chữ dùng để biểu thị nhiều thán từ khác nhau: éi (xác nhận/gọi đáp), ēi (bày tỏ ngạc nhiên), ěi (không đồng ý), èi (gọi đáp). Chưa có phân tích thành tố học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ôi, chao ôi", "Hạng Tần Suất (Jun Da)": "5467.0", "Tần Suất % (Jun Da)": "99.9581057795", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 矣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠矣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诶", "Unihan_Traditional (Chữ Phồn thể)": "誒", "Pinyin_Xie": "éi", "Âm Hán Việt_Xie": "hi, hy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Thán từ | 叹词 | Chữ này làm thán từ thường đứng đầu câu để biểu thị sự ngạc nhiên, đồng ý hoặc gọi hỏi. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薜', '{"9000": "5468.0", "Chữ Trung Quốc": "薜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 艸 | tháu | biểu nghĩa | cây cỏ, thực vật | 辟 | tích | biểu âm | 薜 = 艹 (Tháu, biểu nghĩa: cây cỏ) + 辟 (Tích, biểu âm); chữ hình thanh. Chỉ nhiều loài cây: 薜荔 (dây leo thường xanh), đương quy (Angelica sinensis), v.v.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": bộ Tháo (cây cỏ) + âm Tích — 薜 là loài dây leo tích tụ trên vách đá, xuất hiện nhiều trong thơ Khuất Nguyên. | Gương Hán-Việt | \"tích\" ít dùng độc lập; gặp trong 薜荔 (tích lệ — dây leo) trong Ly Tao của Khuất Nguyên | Mở khoá kiến thức | Biết 薜 giúp đọc Khuất Nguyên và thơ cổ: 薜荔 (dây leo quân tử), 薜衣 (áo dệt từ lá 薜).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 艸 (cây cỏ) là thành phần biểu nghĩa, 辟 là thành phần biểu âm. Dạng tiểu triện đã thể hiện cấu trúc này. 薜 là tên gọi nhiều loài thực vật: 薜荔 (dây leo Ficus pumila hoặc cây điều lăng Kadsura), đương quy (vị thuốc), và một số loài cỏ nước. Trong thơ Khuất Nguyên, 薜荔 và 蕙草 là biểu tượng người quân tử. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một giống cây bụi; cây đương quy", "Hạng Tần Suất (Jun Da)": "5468.0", "Tần Suất % (Jun Da)": "99.9581626259", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 辟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹辟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薜", "Unihan_Traditional (Chữ Phồn thể)": "薜", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại cây leo hoặc thảo dược, thường dùng trong tên gọi thực vật cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铧', '{"9000": "5469.0", "Chữ Trung Quốc": "铧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 金 | kim | biểu nghĩa | kim loại | 華 | hoa | biểu âm | 铧 = 金 (Kim, biểu nghĩa: kim loại) + 華 (Hoa, biểu âm); chữ hình thanh. Dạng phồn thể 鏵. Chỉ lưỡi cày bằng sắt — công cụ nông nghiệp quan trọng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoa\" (theo âm 華): Kim (sắt) + Hoa (âm) — 铧 là lưỡi cày sắt xẻ đất như dao bén, tạo ra những luống đất đẹp như hoa văn. | Gương Hán-Việt | \"hoa\" ít dùng độc lập trong tiếng Việt; 铧 xuất hiện trong từ nông nghiệp cổ 铧犁 (lưỡi cày) | Mở khoá kiến thức | Biết 铧 giúp đọc văn bản nông nghiệp: 铧犁 (lưỡi cày), 铧铁 (sắt làm lưỡi cày).", "Tự nguyên_Xie": "Giáp cốt văn | Chữ hình thanh: 金 (kim loại) là thành phần biểu nghĩa — lưỡi cày làm bằng sắt/đồng; 華 là thành phần biểu âm. Dạng phồn thể 鏵. Nguyên gốc viết là 㭉. Dạng giáp cốt văn đã tồn tại. 铧 là lưỡi cày (plowshare) — phần kim loại ở đầu cày cắt và lật đất. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lưỡi cày", "Hạng Tần Suất (Jun Da)": "5469.0", "Tần Suất % (Jun Da)": "99.9582194722", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 华", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅华", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "华", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铧", "Unihan_Traditional (Chữ Phồn thể)": "鏵", "Pinyin_Xie": "huá", "Âm Hán Việt_Xie": "hoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận của nông cụ, thường đứng sau các danh từ chỉ công cụ cày cấy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裥', '{"9000": "5470.0", "Chữ Trung Quốc": "裥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 12 | nét | 裥 | giản | tượng hình | nếp gấp trên quần áo, ly quần | 裥 không có phân tích thành tố rõ ràng từ Wiktionary. Bộ 衣 (y — quần áo) là thành phần biểu nghĩa. Dạng phồn thể 襉. Chỉ nếp gấp/ly trên quần áo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giản\": bộ Y (quần áo) có những nếp (giản) đều đặn — 裥 là những ly may trên váy, giống như các đoạn (giản) được gấp lại ngăn nắp. | Gương Hán-Việt | \"giản\" ít dùng độc lập trong tiếng Việt; 裥 xuất hiện trong từ may mặc 打裥 (tạo nếp gấp), 百裥裙 (váy trăm ly) | Mở khoá kiến thức | Biết 裥 giúp đọc tài liệu thời trang: 百裥裙 (váy trăm ly), 打裥 (may nếp gấp).", "Tự nguyên_Xie": "裥 là dạng giản thể của 襉. Wiktionary không cung cấp phân tích thành tố nội tại. Bộ 衣 (quần áo) biểu nghĩa. Nghĩa: nếp gấp, ly trên trang phục — kỹ thuật may mặc tạo ra các nếp đều đặn trên váy hoặc quần. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nếp trên quần", "Hạng Tần Suất (Jun Da)": "5470.0", "Tần Suất % (Jun Da)": "99.9582763186", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 间", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤间", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "间", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裥", "Unihan_Traditional (Chữ Phồn thể)": "襇", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "giản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nếp gấp ly trên trang phục, thường kết hợp với các từ liên quan đến may mặc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('榇', '{"9000": "5471.0", "Chữ Trung Quốc": "榇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 榇 | sấn | tượng hình | quan tài, áo quan | 榇 không có phân tích thành tố rõ ràng từ Wiktionary. Bộ 木 (mộc — gỗ) là thành phần biểu nghĩa — quan tài làm bằng gỗ. Dạng phồn thể 櫬. Chữ tạo muộn, thấy trong tiểu triện và Lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sấn\": bộ Mộc (gỗ) đóng hòm sấn — 榇 là chiếc quan tài gỗ, đồ gỗ cuối cùng người ta cần đến. | Gương Hán-Việt | \"sấn\" ít dùng trong tiếng Việt hiện đại; 榇 xuất hiện trong văn cổ và điếu văn 靈榇 (linh cữu) | Mở khoá kiến thức | Biết 榇 giúp đọc văn tế và điếu văn: 靈榇 (linh cữu — quan tài người quá cố), 屍榇 (quan tài).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 榇 là dạng giản thể của 櫬. Wiktionary không phân tích cấu trúc nội tại. Bộ 木 (gỗ) biểu nghĩa — quan tài là đồ vật bằng gỗ. Dạng tiểu triện và Lục thư thông đã tồn tại. Nghĩa chính: quan tài, linh cữu. Từ điển Quảng Đông và Mân Nam ghi nhận từ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái áo quan", "Hạng Tần Suất (Jun Da)": "5471.0", "Tần Suất % (Jun Da)": "99.9583331649", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 亲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木亲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "榇", "Unihan_Traditional (Chữ Phồn thể)": "櫬", "Pinyin_Xie": "chèn", "Âm Hán Việt_Xie": "sấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ quan tài, thường dùng trong văn viết trang trọng hoặc văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馃', '{"9000": "5472.0", "Chữ Trung Quốc": "馃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 11 | nét | 馃 | quả | tượng hình | bánh chiên dầu, đồ ăn vặt | 馃 không có phân tích thành tố rõ ràng từ Wiktionary. Bộ 食 (thực — ăn uống) là thành phần biểu nghĩa. Chữ tạo muộn, chủ yếu dùng trong phương ngữ Bắc Kinh chỉ đồ ăn vặt chiên dầu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quả\": bộ Thực (ăn) + âm Quả — 馃 là loại ''quả'' ăn được chiên trong dầu, như quẩy hoặc bánh rán. | Gương Hán-Việt | \"quả\" ít dùng trong tiếng Việt; 馃 là từ khẩu ngữ Bắc Kinh chỉ đồ ăn chiên | Mở khoá kiến thức | Biết 馃 giúp hiểu khẩu ngữ ẩm thực Bắc Kinh: 馃子 (quẩy chiên), 馃儿 (bánh nhỏ chiên dầu).", "Tự nguyên_Xie": "馃 không có nguồn gốc phân tích từ Wiktionary. Bộ 食 (ăn uống) biểu nghĩa. Không có dạng giáp cốt/kim văn. Chữ tạo muộn, dùng trong khẩu ngữ Bắc Kinh chỉ: bánh và đồ ăn chiên dầu (như 馃子 — quẩy chiên), hoặc đồ ăn vặt kiểu cũ. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loại thức ăn chiên dầu; ăn lót dạ theo lối cũ", "Hạng Tần Suất (Jun Da)": "5472.0", "Tần Suất % (Jun Da)": "99.9583900113", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 果", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣果", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "馃", "Unihan_Traditional (Chữ Phồn thể)": "餜", "Pinyin_Xie": "guǒ", "Âm Hán Việt_Xie": "quả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại bánh rán hoặc đồ ăn nhẹ làm từ bột mì. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹚', '{"9000": "5473.0", "Chữ Trung Quốc": "蹚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 18 | nét | 蹚 | thang | tượng hình | lội qua, giẫm lên bùn nước | 蹚 không có phân tích thành tố rõ ràng từ Wiktionary. Bộ 足 (túc — chân) là thành phần biểu nghĩa, gợi hành động bước qua nước/bùn. Chữ tạo muộn, không có dạng giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thang\": bộ Túc (chân) lội qua nước thang — 蹚 là bước chân lội qua bùn nước, như lội qua vũng nước đục. | Gương Hán-Việt | \"thang\" ít dùng trong tiếng Việt; 蹚 là từ khẩu ngữ/phương ngữ Trung Quốc | Mở khoá kiến thức | Biết 蹚 giúp đọc văn xuôi và nông nghiệp: 蹚水 (lội qua nước), 蹚地 (bừa đất giữa hàng cây).", "Tự nguyên_Xie": "蹚 không có nguồn gốc phân tích từ Wiktionary. Bộ 足 (chân) biểu nghĩa — lội bùn nước bằng chân. Không có dạng giáp cốt/kim văn. Nghĩa: lội qua bùn/nước nông; giẫm lên; trong nông nghiệp: cào/bừa đất giữa các hàng cây. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lội qua; giẫm lên; cào, bừa", "Hạng Tần Suất (Jun Da)": "5473.0", "Tần Suất % (Jun Da)": "99.9585031873", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 堂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊堂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "堂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹚", "Unihan_Traditional (Chữ Phồn thể)": "蹚", "Pinyin_Xie": "tāng", "Âm Hán Việt_Xie": "thang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường mang tân ngữ chỉ nguồn nước hoặc mặt đất phía sau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('怄', '{"9000": "5474.0", "Chữ Trung Quốc": "怄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 7 | nét | 怄 | âu | tượng hình | tức giận, bực bội, ấm ức | 怄 không có phân tích thành tố rõ ràng từ Wiktionary. Bộ 忄(心 — tâm) là thành phần biểu nghĩa, gợi trạng thái cảm xúc. Phần còn lại có thể biểu âm. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"âu\": bộ Tâm (lòng) âu lo bực bội — 怄 là cảm giác âu sầu tức giận nung nấu trong lòng không nói được. | Gương Hán-Việt | \"âu\" ít dùng trong tiếng Việt; 怄 là từ khẩu ngữ tiếng Trung hiện đại | Mở khoá kiến thức | Biết 怄 giúp hiểu khẩu ngữ: 怄气 (ấm ức, bực bội), 怄死人 (bực đến chết).", "Tự nguyên_Xie": "怄 không có nguồn gốc phân tích từ Wiktionary. Bộ 心 (tâm/lòng) biểu nghĩa — trạng thái tâm lý bực bội. Không có dạng giáp cốt/kim văn. Nghĩa: tức giận, bực bội, ấm ức — trạng thái cảm xúc tiêu cực dồn nén. Từ khẩu ngữ tiếng Trung hiện đại. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giận, bực tức", "Hạng Tần Suất (Jun Da)": "5474.0", "Tần Suất % (Jun Da)": "99.9585595168", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 区", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄区", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "区", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "怄", "Unihan_Traditional (Chữ Phồn thể)": "慪", "Pinyin_Xie": "òu", "Âm Hán Việt_Xie": "âu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị trạng thái tâm lý bực dọc, thường kết hợp với khí thành 怄气. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('寤', '{"9000": "5475.0", "Chữ Trung Quốc": "寤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 14 | nét | 㝱 | mộng | biểu nghĩa | giấc mộng | 吾 | ngô | biểu âm | 寤 = 㝱 (Mộng, biểu nghĩa: giấc mộng — dạng rút gọn của 夢) + 吾 (Ngô, biểu âm); chữ hình thanh. 寤 chỉ trạng thái thức giấc sau giấc ngủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngộ\" (theo âm 吾/wù): Mộng (㝱) bị phá tan bởi âm Ngô — 寤 là khoảnh khắc bừng tỉnh khỏi giấc mộng. | Gương Hán-Việt | \"ngộ\" trong 寤寐 (ngộ mị — thức và ngủ), ít dùng độc lập trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 寤 giúp đọc văn cổ: 寤寐思服 (thức ngủ đều nghĩ — Kinh Thi), 寤寐 (ngộ mị — lúc thức lúc ngủ).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 㝱 (dạng rút gọn của 夢 — giấc mộng) là thành phần biểu nghĩa, 吾 là thành phần biểu âm. Nghĩa: thức dậy (từ giấc ngủ/mộng). Dạng tiểu triện đã thể hiện cấu trúc này. Chữ liên quan đến giấc ngủ và tỉnh dậy trong văn học cổ điển. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thức dậy.", "Hạng Tần Suất (Jun Da)": "5475.0", "Tần Suất % (Jun Da)": "99.9586158464", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + 𤕻", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀𤕻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𤕻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "宀", "Unihan_Simplified (Chữ Giản thể)": "寤", "Unihan_Traditional (Chữ Phồn thể)": "寤", "Pinyin_Xie": "wù", "Âm Hán Việt_Xie": "ngụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động tỉnh giấc, thường dùng trong văn viết cổ hoặc kết hợp thành từ ghép. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缗', '{"9000": "5476.0", "Chữ Trung Quốc": "缗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 缗 | mẫn | tượng hình | dây câu, dây xâu tiền | 缗 không có phân tích thành tố rõ ràng từ Wiktionary. Bộ 糸 (mịch — sợi, dây) là thành phần biểu nghĩa. Dạng phồn thể 緡. Nghĩa: dây câu cá, dây xâu đồng tiền; đơn vị tiền tệ 1000 đồng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mẫn\": bộ Mịch (sợi) xâu tiền — 缗 là sợi dây mẫn xâu một nghìn đồng thành xâu, hoặc sợi câu cá kiên nhẫn. | Gương Hán-Việt | \"mẫn\" ít dùng trong tiếng Việt; 缗 xuất hiện trong văn kinh tế cổ (算緡錢 — thuế tiền thời Hán) | Mở khoá kiến thức | Biết 缗 giúp đọc văn kinh tế cổ: 緡錢 (xâu tiền — đơn vị 1000 đồng), 算緡 (thu thuế tiền — thời Hán Vũ Đế).", "Tự nguyên_Xie": "Lục thư thông | 缗 là dạng giản thể của 緡. Wiktionary không phân tích cấu trúc nội tại. Bộ 糸 (sợi/dây) biểu nghĩa — dây câu và dây xâu tiền đều là sợi dây. Chỉ có dạng Lục thư thông. Nghĩa chính: dây câu cá; dây xâu đồng tiền; đơn vị tiền 1000 đồng; tên địa danh cổ (nước Mẫn xưa, Sơn Đông). Cũng dùng nghĩa bôi lên, phủ lên (phương ngữ). | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây câu; quan tiền", "Hạng Tần Suất (Jun Da)": "5476.0", "Tần Suất % (Jun Da)": "99.958672176", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 昬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟昬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缗", "Unihan_Traditional (Chữ Phồn thể)": "緡", "Pinyin_Xie": "mín", "Âm Hán Việt_Xie": "mân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ dây xâu tiền hoặc làm lượng từ để đếm số lượng quan tiền thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硗', '{"9000": "5477.0", "Chữ Trung Quốc": "硗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 11 | nét | 硗 | kiêu | tượng hình | đất xấu, đất sỏi đá cằn cỗi | 硗 là dạng giản thể của 磽. Bộ 石 (thạch — đá) là thành phần biểu nghĩa — đất sỏi đá không canh tác được. Dạng tiểu triện đã tồn tại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiêu\": bộ Thạch (đá) kiêu ngạo không chịu màu mỡ — 硗 là đất sỏi kiêu, trơ, cứng đầu không cho cây cỏ mọc. | Gương Hán-Việt | \"kiêu\" ít dùng trong tiếng Việt; 硗 xuất hiện trong văn nông nghiệp cổ | Mở khoá kiến thức | Biết 硗 giúp đọc văn mô tả địa hình: 硗薄 (đất cằn mỏng), 硗确 (đất sỏi đá cứng).", "Tự nguyên_Xie": "Tiểu triện | 硗 là dạng giản thể của 磽, xem thêm ở đó. Bộ 石 (đá) biểu nghĩa — đất cằn cỗi nhiều sỏi đá. Dạng tiểu triện đã tồn tại. Nghĩa: đất xấu, đất sỏi đá không màu mỡ, không trồng trọt được. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đất xấu, đất sỏi", "Hạng Tần Suất (Jun Da)": "5477.0", "Tần Suất % (Jun Da)": "99.9587285056", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 尧", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石尧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硗", "Unihan_Traditional (Chữ Phồn thể)": "磽", "Pinyin_Xie": "qiāo", "Âm Hán Việt_Xie": "nghiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường đứng trước danh từ chỉ đất đai để miêu tả sự cằn cỗi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碡', '{"9000": "5478.0", "Chữ Trung Quốc": "碡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 14 | nét | 碡 | độc | tượng hình | đá lăn, con lăn đá dùng để phẳng đất hoặc đập lúa | 碡 không có phân tích thành tố rõ ràng từ Wiktionary. Bộ 石 (thạch — đá) là thành phần biểu nghĩa. Chỉ dùng trong từ ghép 碌碡/磟碡 — con lăn đá nông nghiệp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"độc\": bộ Thạch (đá) lăn độc đường — 碡 là viên đá lăn nặng nề qua đồng lúa, nghiền phẳng mọi thứ. | Gương Hán-Việt | \"độc\" ít dùng độc lập trong tiếng Việt; 碡 chỉ dùng trong 碌碡/磟碡 (lăn đá nông nghiệp) | Mở khoá kiến thức | Biết 碡 giúp đọc văn nông nghiệp cổ: 碌碡 (con lăn đá), 石碡 (đá lăn).", "Tự nguyên_Xie": "Wiktionary không phân tích cấu trúc nội tại của 碡. Bộ 石 (đá) biểu nghĩa. Chỉ dùng trong từ ghép 碌碡 hoặc 磟碡 — con lăn đá hình trụ dùng trong nông nghiệp cổ đại để san phẳng đất hoặc đập lúa. Nghĩa độc lập của chữ không rõ ràng ngoài từ ghép này. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đá lăn, hòn lăn, quả lăn", "Hạng Tần Suất (Jun Da)": "5478.0", "Tần Suất % (Jun Da)": "99.9587848352", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 毒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石毒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碡", "Unihan_Traditional (Chữ Phồn thể)": "碡", "Pinyin_Xie": "dú", "Âm Hán Việt_Xie": "độc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại nông cụ bằng đá dùng để lu lèn đất hoặc trục lúa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矬', '{"9000": "5479.0", "Chữ Trung Quốc": "矬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 矢 | Số nét | 12 | nét | 矢 | thỉ | biểu nghĩa | mũi tên | 坐 | toạ | biểu âm | 矬 = 矢 (Thỉ, biểu nghĩa: mũi tên) + 坐 (Toạ, biểu âm); chữ hình thanh. Mũi tên ngắn gợi ý nghĩa ''thấp, ngắn''. Chỉ người thấp bé, lùn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thỉ-toạ\": mũi Thỉ (矢) ngắn ngồi Toạ (坐) thấp — 矬 là người lùn thấp, như mũi tên ngắn ngồi bệt xuống. | Gương Hán-Việt | \"thỉ\" ít dùng trong tiếng Việt; 矬 là từ khẩu ngữ chỉ người lùn | Mở khoá kiến thức | Biết 矬 giúp hiểu khẩu ngữ: 矬子 (người lùn), 矬矮 (thấp lùn), 矮矬矬 (lùn tịt).", "Tự nguyên_Xie": "Chữ hình thanh: 矢 (mũi tên) là thành phần biểu nghĩa — gợi ý nghĩa ngắn (mũi tên ngắn); 坐 là thành phần biểu âm. Nghĩa: thấp bé về chiều cao (chủ yếu nói về người). Đồng nghĩa với 矮. Dùng trong khẩu ngữ và phương ngữ Trung Quốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thấp; thấp lùn; lùn tịt; nhỏ xíu; còi cọc (người)", "Hạng Tần Suất (Jun Da)": "5479.0", "Tần Suất % (Jun Da)": "99.9588411647", "GavinGrover_Once (Chiết tự trực tiếp)": "矢 + 坐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰矢坐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "坐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "矢", "Unihan_Simplified (Chữ Giản thể)": "矬", "Unihan_Traditional (Chữ Phồn thể)": "矬", "Pinyin_Xie": "cuó", "Âm Hán Việt_Xie": "toạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả vóc dáng thấp lùn của người hoặc vật, thường dùng trong khẩu ngữ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸱', '{"9000": "5480.0", "Chữ Trung Quốc": "鸱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 10 | nét | 氐 | đê | biểu âm | 鳥 | điểu | biểu nghĩa | chim | 鸱 = 氐 (Đê, biểu âm) + 鳥 (Điểu, biểu nghĩa: chim); chữ hình thanh. Dạng phồn thể 鴟. Chỉ con cú mèo/diều hâu trong thần thoại và thơ cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xi\" (theo âm 氐): bộ Điểu (chim) + âm Đê — 鸱 là con chim xi cú mèo, nhìn thấy trong bóng tối những gì người khác không thấy. | Gương Hán-Việt | \"xi\" trong 鴟鴞 (xi tiêu — cú mèo, trong Kinh Thi), 鴟夷 (xi di — bình da hoặc bút danh Phạm Lãi) | Mở khoá kiến thức | Biết 鸱 giúp đọc Kinh Thi (鴟鴞), Sử Ký (鴟夷子皮 — tên hiệu Phạm Lãi), và thơ cổ tả cảnh đêm.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 鳥 (chim) là thành phần biểu nghĩa, 氐 là thành phần biểu âm. Dạng phồn thể 鴟. Dạng tiểu triện và Lục thư thông đã thể hiện cấu trúc này. Nghĩa: cú mèo (owl), hoặc diều hâu. Trong Kinh Thi có bài 鴟鴞 (Chỉ Tiêu) — cú mèo cướp con chim non, là ẩn dụ cho hoạn nạn. 鴟夷 là tên bình da thuộc đựng rượu, cũng là bút danh của Phạm Lãi. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(như: giốc si 角鴟,角鸱)", "Hạng Tần Suất (Jun Da)": "5480.0", "Tần Suất % (Jun Da)": "99.9588974943", "GavinGrover_Once (Chiết tự trực tiếp)": "氐 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氐鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "氐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鸱", "Unihan_Traditional (Chữ Phồn thể)": "鴟", "Pinyin_Xie": "chī", "Âm Hán Việt_Xie": "si", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loài chim thuộc họ cú hoặc diều hâu, thường xuất hiện trong từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虺', '{"9000": "5481.0", "Chữ Trung Quốc": "虺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 9 | nét | 兀 | ngột | biểu âm | đứng vững, trơ trọi | 虫 | trùng | biểu nghĩa | sâu bọ, côn trùng | 虺 = 兀 (Ngột, biểu âm) + 虫 (Trùng, biểu nghĩa: sâu bọ); chữ hình thanh. Phần 虫 chỉ loài bò sát/côn trùng, phần 兀 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hủy\": con rắn hổ mang (虫) đứng thẳng trơ trọi (兀) như cột độc — nhìn thấy là sợ. | Gương Hán-Việt | 虺 xuất hiện trong thành ngữ 虺蜴 (hủy dịch) chỉ loài bò sát độc hại. | Mở khoá kiến thức | Biết 虺 (hủy) mở khoá các từ cổ văn chỉ rắn độc và thú vật nguy hiểm trong thơ Kinh Thi.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 虫 (trùng) biểu nghĩa chỉ loài bò sát, 兀 (ngột) biểu âm. Tiểu triện đã có dạng này. 虺 chỉ loài rắn độc lớn trong thư tịch cổ Trung Hoa, thường xuất hiện cùng 蜴 (thằn lằn). Chưa có nguồn glyph-origin chi tiết hơn ngoài cấu trúc hình thanh. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rắn hổ mang", "Hạng Tần Suất (Jun Da)": "5481.0", "Tần Suất % (Jun Da)": "99.9589538239", "GavinGrover_Once (Chiết tự trực tiếp)": "兀 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴兀虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "虺", "Unihan_Traditional (Chữ Phồn thể)": "虺", "Pinyin_Xie": "huī", "Âm Hán Việt_Xie": "hủy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài rắn độc thời cổ, thường dùng trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糅', '{"9000": "5482.0", "Chữ Trung Quốc": "糅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 15 | nét | 糅 | nhu | tượng hình | hỗn hợp, lẫn lộn | 糅 là chữ độc lập trong Wiktionary không có cấu trúc hội ý/hình thanh rõ ràng được ghi nhận. Về hình thức, 糅 gồm 米 (mễ, gạo) và 柔 (nhu, mềm mại) — có thể suy luận là hình thanh với 米 biểu nghĩa (lúa gạo, thức ăn) và 柔 biểu âm, song chưa có xác nhận học thuật. Cần lưu ý đây chỉ là suy luận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhu\": lấy hạt 米 (gạo) nhào 柔 (nhừ, mềm) cùng nhau — trộn lẫn, nhào nhuyễn mọi thứ với nhau. | Gương Hán-Việt | 糅 dùng trong 糅合 (nhu hợp: pha trộn), 糅雜 (nhu tạp: lộn xộn). | Mở khoá kiến thức | Biết 糅 (nhu) mở khoá các từ chỉ sự pha trộn, hỗn tạp trong văn học cổ: 糅雜, 糅合, 雜糅.", "Tự nguyên_Xie": "Wiktionary ghi nhận 糅 nghĩa là trộn lẫn, pha tạp. Không có glyph-origin hình thanh/hội ý được xác nhận. Nhìn hình thức chữ, có thể gồm 米 (gạo, thức ăn) và 柔 (mềm), gợi ý pha trộn thức ăn — song chưa có nguồn học thuật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lẫn lộn", "Hạng Tần Suất (Jun Da)": "5482.0", "Tần Suất % (Jun Da)": "99.9590101535", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 柔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米柔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "柔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "糅", "Unihan_Traditional (Chữ Phồn thể)": "糅", "Pinyin_Xie": "róu", "Âm Hán Việt_Xie": "nhữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động trộn lẫn nhiều thứ vào nhau, thường đi kèm với các động từ khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雠', '{"9000": "5483.0", "Chữ Trung Quốc": "雠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 隹 | Số nét | 18 | nét | 雠 | thù | tượng hình | thù địch, đối lập | 雠 là dạng giản thể của 讎. Dạng truyền thống 讎 gồm hai chim 隹 (chuy) đối mặt nhau với 言 (ngôn, lời nói) ở giữa — hội ý: hai bên cãi nhau, đối đáp thành thù. Dạng 雠 đơn giản hoá bỏ 言. Chữ hội ý gốc, nay thường dùng dạng giản.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thù\": hai con chim (隹隹) mặt đối mặt tranh cãi — thù địch nhau từ lời qua tiếng lại. | Gương Hán-Việt | 雠 trong 仇雠 (cừu thù: kẻ thù), 校雠 (hiệu thù: đối chiếu văn bản). | Mở khoá kiến thức | Biết 雠 (thù) mở khoá từ cổ văn: 仇雠, 校雠 (hiệu đính sách), 雠校.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 雠 là dạng giản của 讎. Dạng cổ 讎 gồm hai 隹 (chim) kẹp 言 (lời) ở giữa: hai bên đối đáp cãi vã thành thù. Kim văn và tiểu triện đều có dạng 讎. Dạng hiện đại 雠 bỏ bộ 言, chỉ còn hai 隹 đối nhau. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thù địch", "Hạng Tần Suất (Jun Da)": "5483.0", "Tần Suất % (Jun Da)": "99.9590664831", "GavinGrover_Once (Chiết tự trực tiếp)": "雔 + 讠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴雔讠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "雠", "Unihan_Traditional (Chữ Phồn thể)": "讎", "Pinyin_Xie": "chóu", "Âm Hán Việt_Xie": "thù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường làm danh từ chỉ kẻ thù hoặc động từ thể hiện sự thù hằn, đối đầu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('帑', '{"9000": "5484.0", "Chữ Trung Quốc": "帑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 8 | nét | 奴 | nô | biểu âm | nô lệ | 巾 | can | biểu nghĩa | vải, khăn, túi | 帑 = 奴 (Nô, biểu âm) + 巾 (Can, biểu nghĩa: vải, túi đựng); chữ hình thanh. Phần 巾 gợi ý vật đựng chứa (túi, bọc), phần 奴 cho âm đọc cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nô\": chiếc túi vải (巾) giao cho nô bộc (奴) giữ gìn — đó là kho báu hoàng gia. | Gương Hán-Việt | 帑 trong 帑藏 (nô tàng: kho tàng nhà nước), 国帑 (quốc nô: ngân khố quốc gia). | Mở khoá kiến thức | Biết 帑 (nô) mở khoá từ cổ văn chỉ kho báu: 帑藏, 国帑, 帑室 (vợ con).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 巾 (can, vải/túi) biểu nghĩa chỉ nơi cất giữ, 奴 (nô) biểu âm. Tiểu triện có dạng này. 帑 gốc nghĩa là kho tiền của nhà nước hoặc kho tàng hoàng gia; cũng dùng chỉ vợ con (帑室). Wiktionary xác nhận cấu trúc hình thanh này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kho để của, kho báu", "Hạng Tần Suất (Jun Da)": "5484.0", "Tần Suất % (Jun Da)": "99.9591228126", "GavinGrover_Once (Chiết tự trực tiếp)": "奴 + 巾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰奴巾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "帑", "Unihan_Traditional (Chữ Phồn thể)": "帑", "Pinyin_Xie": "tǎng", "Âm Hán Việt_Xie": "thảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ triều đình hoặc quốc gia để chỉ kho tàng, ngân khố. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镧', '{"9000": "5485.0", "Chữ Trung Quốc": "镧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 镧 | lam | tượng hình | nguyên tố kim loại lanthan | 镧 là dạng giản thể của 鑭. Về hình thức, gồm 钅 (kim loại, biểu nghĩa) và một phần biểu âm, nhưng Wiktionary chỉ ghi {{Han etym}} mà không nêu cấu trúc chi tiết. Chữ dùng để phiên âm tên nguyên tố hoá học lanthanum (La), tạo ra trong thời hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lam\": bộ 钅 (kim loại) + âm \"lam\" — lanthanum là nguyên tố kim loại đất hiếm màu bạc, số 57. | Gương Hán-Việt | 镧 dùng trong 镧系元素 (lam hệ nguyên tố: nguyên tố họ lanthan). | Mở khoá kiến thức | Biết 镧 (lam) mở khoá thuật ngữ hoá học: 镧系 (họ lanthan), 稀土元素 (đất hiếm).", "Tự nguyên_Xie": "镧 (dạng giản của 鑭) là chữ dùng để phiên âm tên nguyên tố hoá học lanthanum (tiếng Latin: lanthanum, ký hiệu La). Chữ tạo muộn để ký âm tên khoa học phương Tây, không có glyph-origin giáp cốt hay kim văn. Wiktionary không cung cấp cấu trúc hình thanh/hội ý cụ thể. Chưa có nguồn học thuật về nguồn gốc chữ viết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố lantan, La", "Hạng Tần Suất (Jun Da)": "5485.0", "Tần Suất % (Jun Da)": "99.9591791422", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 阑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅阑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镧", "Unihan_Traditional (Chữ Phồn thể)": "鑭", "Pinyin_Xie": "lán", "Âm Hán Việt_Xie": "lan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong thuật ngữ hóa học để chỉ nguyên tố kim loại Lanthanum. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('埙', '{"9000": "5486.0", "Chữ Trung Quốc": "埙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 10 | nét | 埙 | huân | tượng hình | nhạc cụ bằng đất nung | 埙 là dạng giản thể của 塤. Wiktionary dẫn về 塤 nhưng không có cấu trúc hình thanh/hội ý được xác nhận. Về hình thức, có thể thấy thành phần 土 (thổ, đất) — gợi ý nhạc cụ làm từ đất nung — song cấu trúc đầy đủ chưa được học thuật ghi nhận rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huân\": cục đất (土) nung thành nhạc cụ cổ xưa — tiếng 埙 vang lên u trầm như tiếng của đất. | Gương Hán-Việt | 埙 trong 埙篪 (huân trì: cặp nhạc cụ gió tấu cùng nhau), biểu tượng hòa hợp anh em. | Mở khoá kiến thức | Biết 埙 (huân) mở khoá từ cổ: 埙篪相和 (huân trì tương hòa: anh em hòa thuận), nhạc cụ cổ Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 埙 (dạng giản của 塤) chỉ loại nhạc cụ hơi làm từ đất nung, có nhiều lỗ, âm thanh trầm ấm. Wiktionary ghi {{rfe|zh}} (cần thêm nguồn gốc), tức chưa có glyph-origin đầy đủ. Tiểu triện và Lục thư thông đã có dạng chữ này. Nhạc cụ 埙 xuất hiện từ thời Tiên Tần. Chưa có nguồn học thuật về cấu trúc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái huân (một nhạc cụ để thổi làm bằng đất nung đỏ, có nhiều lỗ)", "Hạng Tần Suất (Jun Da)": "5486.0", "Tần Suất % (Jun Da)": "99.959234955", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 员", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土员", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "员", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "埙", "Unihan_Traditional (Chữ Phồn thể)": "塤", "Pinyin_Xie": "xūn", "Âm Hán Việt_Xie": "huân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một loại nhạc cụ cổ của Trung Quốc, đóng vai trò tân ngữ sau động từ thổi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啁', '{"9000": "5487.0", "Chữ Trung Quốc": "啁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 啁 | trào | tượng hình | tiếng chim ríu rít | 啁 có bộ 口 (khẩu, miệng/tiếng) — gợi ý âm thanh, tiếng kêu. Wiktionary không ghi cấu trúc hình thanh/hội ý cụ thể. Về hình thức, có thể gồm 口 (biểu nghĩa: âm thanh) và một thành phần biểu âm, nhưng chưa xác nhận học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trào\": miệng (口) phát ra tiếng ríu rít líu lo — như chim chóc trào lên tiếng ca. | Gương Hán-Việt | 啁 trong 啁啾 (trào thu: tiếng chim hót ríu rít). | Mở khoá kiến thức | Biết 啁 (trào) mở khoá từ thi ca cổ chỉ âm thanh chim chóc: 啁啾, 啁哳.", "Tự nguyên_Xie": "Tiểu triện | 啁 là từ tượng thanh chỉ tiếng chim ríu rít, líu lo. Wiktionary ghi nhận nhiều cách đọc (zhāo, zhōu, tiáo, cháo) — đây là đặc điểm của từ tượng thanh phổ phương ngữ. Tiểu triện có dạng chữ này. Dùng chủ yếu trong 啁啾 (zhōu jiū: tiếng chim hót), 啁哳 (tiếng ríu rít). Chưa có nguồn học thuật về nguồn gốc cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "líu lo; ríu rít (âm thanh)", "Hạng Tần Suất (Jun Da)": "5487.0", "Tần Suất % (Jun Da)": "99.9592907678", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 周", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口周", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "周", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啁", "Unihan_Traditional (Chữ Phồn thể)": "啁", "Pinyin_Xie": "zhāo", "Âm Hán Việt_Xie": "trù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Động từ | 动词 | Thường dùng làm từ tượng thanh mô tả tiếng chim hót hoặc kết hợp thành từ láy để tả âm thanh. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('悒', '{"9000": "5488.0", "Chữ Trung Quốc": "悒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 10 | nét | 悒 | ấp | tượng hình | lo âu, ưu sầu | 悒 có bộ 忄(心, tâm/lòng) — biểu nghĩa cảm xúc. Wiktionary không ghi cấu trúc hình thanh/hội ý rõ ràng. Hình thức có thể gồm 忄(biểu nghĩa: tâm trạng) và một thành phần bên phải biểu âm, nhưng chưa xác nhận học thuật cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ấp\": trái tim (忄) bị ấp ủ lo âu — nỗi sầu u uất không thoát ra được. | Gương Hán-Việt | 悒 trong 悒郁 (ấp uất: ưu uất, u sầu), 忧悒 (ưu ấp: lo âu, sầu muộn). | Mở khoá kiến thức | Biết 悒 (ấp) mở khoá từ cổ văn chỉ tâm trạng sầu muộn: 悒郁, 悒悒不乐, 忧悒.", "Tự nguyên_Xie": "Tiểu triện | 悒 nghĩa là lo âu, sầu não, không vui. Wiktionary ghi nhận âm đọc và nghĩa nhưng không có glyph-origin cụ thể. Tiểu triện có dạng chữ này. Dùng chủ yếu trong văn học cổ điển qua các từ như 悒悒 (lo lắng kéo dài), 悒郁 (âu sầu, ưu uất), 忧悒 (lo buồn). Chưa có nguồn học thuật về cấu trúc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áy náy, lo lắng", "Hạng Tần Suất (Jun Da)": "5488.0", "Tần Suất % (Jun Da)": "99.9593465806", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 邑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄邑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "邑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "悒", "Unihan_Traditional (Chữ Phồn thể)": "悒", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ấp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ miêu tả trạng thái tâm lý buồn bã, u sầu, có thể đứng trước danh từ hoặc sau phó từ chỉ mức độ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('犍', '{"9000": "5489.0", "Chữ Trung Quốc": "犍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 牛 | Số nét | 12 | nét | 犍 | kiền | tượng hình | trâu đực khoẻ mạnh | 犍 có bộ 牛 (ngưu, trâu/bò) — biểu nghĩa gia súc. Wiktionary chỉ ghi {{Han etym}} mà không nêu cấu trúc. Hình thức có thể gồm 牛 (biểu nghĩa) và phần biểu âm bên phải, nhưng cấu trúc học thuật chưa được ghi nhận đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiền\": con bò/trâu (牛) vạm vỡ kiền cường — bước đi mạnh mẽ, không gì ngăn cản. | Gương Hán-Việt | 犍 trong 犍陀羅 (Kiền-đà-la: Gandhara, vùng đất cổ), 犍为 (Kiền Vi: địa danh Tứ Xuyên). | Mở khoá kiến thức | Biết 犍 (kiền) mở khoá địa danh cổ: 犍为 (Tứ Xuyên), 犍陀罗 (Gandhara trong Phật giáo).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 犍 có bộ 牛 (ngưu, trâu/bò), chỉ trâu đực hoặc bò đực khoẻ mạnh; cũng là tên đất cổ (Kiền Vi). Wiktionary chỉ ghi {{Han etym}}, không có glyph-origin cụ thể. Tiểu triện và Lục thư thông đã có dạng chữ này. Trong văn học Phật giáo, 犍陀羅 (Kiền-đà-la, Gandhara) cũng dùng chữ này. Chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dáng trâu đi khoẻ mạnh; (tên đất)", "Hạng Tần Suất (Jun Da)": "5489.0", "Tần Suất % (Jun Da)": "99.9594023934", "GavinGrover_Once (Chiết tự trực tiếp)": "牛 + 建", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰牛建", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "建", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "牛", "Unihan_Simplified (Chữ Giản thể)": "犍", "Unihan_Traditional (Chữ Phồn thể)": "犍", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "kiền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ con trâu đực đã thiến hoặc dùng trong địa danh cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硌', '{"9000": "5490.0", "Chữ Trung Quốc": "硌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 11 | nét | 石 | thạch | biểu nghĩa | đá, cứng | 各 | cac | biểu âm | mỗi, từng | 硌 = 石 (Thạch, biểu nghĩa: đá, cứng) + 各 (Cac, biểu âm); chữ hình thanh. Phần 石 gợi ý sự cứng, gồ ghề; phần 各 cho âm đọc. Wiktionary xác nhận cấu trúc hình thanh này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngắc\": viên đá (石) nằm ngắc dưới lưng — cảm giác bị cấn, khó chịu không ngủ được. | Gương Hán-Việt | 硌 dùng trong 硌脚 (ngắc chân: sỏi đá cấn chân), 石硌硌 (sỏi lổm chổm). | Mở khoá kiến thức | Biết 硌 (ngắc) mở khoá từ thông tục: 硌脚 (cấn chân), 硌背 (cấn lưng) — cảm giác đá sỏi cạnh sắc.", "Tự nguyên_Xie": "Chữ hình thanh: 石 (thạch, đá) biểu nghĩa, 各 (cac) biểu âm. Nghĩa gốc: cảm giác bị vật cứng như đá cấn vào người, gây khó chịu. Wiktionary xác nhận cấu trúc {{Han compound|石|各|ls=psc|c1=s|c2=p|t1=rock}}. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bị cấn (chỗ nằm không phẳng, nằm khó chịu)", "Hạng Tần Suất (Jun Da)": "5490.0", "Tần Suất % (Jun Da)": "99.9594582062", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 各", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石各", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "各", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硌", "Unihan_Traditional (Chữ Phồn thể)": "硌", "Pinyin_Xie": "gè", "Âm Hán Việt_Xie": "các, lạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ biểu thị cảm giác bị cấn, đau do chạm phải vật cứng, gồ ghề khi nằm hoặc ngồi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锩', '{"9000": "5491.0", "Chữ Trung Quốc": "锩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 锩 | quyển | tượng hình | cong, quằn lưỡi kim loại | 锩 có bộ 钅 (kim, kim loại — biểu nghĩa) và phần bên phải có thể là biểu âm, nhưng Wiktionary không ghi nhận cấu trúc. Hình thức gợi ý hình thanh (kim loại + biểu âm), song chưa xác nhận học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyển\": lưỡi kim loại (钅) bị quằn cong — dao kiếm sau khi đánh mạnh bị biến dạng. | Gương Hán-Việt | 锩 trong 锩刃 (quyển nhận: lưỡi dao bị quằn). | Mở khoá kiến thức | Biết 锩 (quyển) mở khoá từ kỹ thuật rèn: lưỡi dao quằn, kim loại bị biến dạng khi va chạm.", "Tự nguyên_Xie": "锩 nghĩa là lưỡi dao/kiếm bị quằn, cong do va chạm. Bộ 钅 (kim loại) gợi ý liên quan đến kim khí. Wiktionary không có glyph-origin. Chữ này không xuất hiện trong giáp cốt hay kim văn; tạo muộn hơn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quằn (lưỡi dao, lưỡi kiếm)", "Hạng Tần Suất (Jun Da)": "5491.0", "Tần Suất % (Jun Da)": "99.959514019", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 卷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅卷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锩", "Unihan_Traditional (Chữ Phồn thể)": "錈", "Pinyin_Xie": "juǎn", "Âm Hán Việt_Xie": "quyển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ miêu tả trạng thái lưỡi dao, kiếm bị cong quằn hoặc sứt mẻ sau khi chém. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虿', '{"9000": "5492.0", "Chữ Trung Quốc": "虿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 9 | nét | 萬 | vạn | biểu âm | vạn, mười nghìn | 虫 | trùng | biểu nghĩa | sâu bọ, sinh vật | 虿 = 萬 (Vạn, biểu âm) + 虫 (Trùng, biểu nghĩa: sinh vật); chữ hình thanh. Điều thú vị là 虿 thể hiện nghĩa gốc của 萬 — ban đầu 萬 vẽ con bọ cạp, sau mới chuyển sang nghĩa số đếm vạn. Wiktionary xác nhận điều này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sái\": bọ cạp (虫) mang đuôi như con số vạn (萬) — chính 萬 nguyên gốc vẽ con bọ cạp này. | Gương Hán-Việt | 虿 trong 虺虿 (hủy sái: rắn độc và bọ cạp), biểu tượng độc hại, nguy hiểm. | Mở khoá kiến thức | Biết 虿 (sái) mở khoá lịch sử chữ 萬: 萬 gốc là hình bọ cạp trước khi thành số đếm vạn.", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Chữ hình thanh: 虫 (trùng) biểu nghĩa chỉ sinh vật, 萬 (vạn) biểu âm. Đáng chú ý, Wiktionary ghi: chữ 虿 thể hiện nghĩa gốc của 萬 — tức 萬 ban đầu vẽ hình con bọ cạp, sau này mượn sang nghĩa mười nghìn (vạn). Kim văn, đại triện và tiểu triện đều có dạng 蠆 (dạng truyền thống). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con bọ cạp", "Hạng Tần Suất (Jun Da)": "5492.0", "Tần Suất % (Jun Da)": "99.9595698318", "GavinGrover_Once (Chiết tự trực tiếp)": "万 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱万虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "万", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "虿", "Unihan_Traditional (Chữ Phồn thể)": "蠆", "Pinyin_Xie": "chài", "Âm Hán Việt_Xie": "sái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loài bọ cạp hoặc các loài côn trùng có độc trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛑', '{"9000": "5493.0", "Chữ Trung Quốc": "蛑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 蛑 | mâu | tượng hình | cua biển, côn trùng hại mầm | 蛑 có bộ 虫 (trùng, côn trùng/động vật nhỏ — biểu nghĩa). Wiktionary không ghi cấu trúc hình thanh/hội ý cụ thể. Phần bên phải có thể là biểu âm nhưng chưa xác nhận học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mâu\": con côn trùng (虫) gây mâu thuẫn hại mầm cây — hoặc con cua biển bơi ngang. | Gương Hán-Việt | 蛑 trong 蝤蛑 (tưu mâu: cua biển bơi), 蛑贼 (mâu tặc: sâu hại cây). | Mở khoá kiến thức | Biết 蛑 (mâu) mở khoá từ cổ: 蝤蛑 (cua bơi), 鳅蛑 (tên ghép chỉ động vật nước).", "Tự nguyên_Xie": "Tiểu triện | 蛑 là dạng rút gọn của 蝤蛑 (cua bơi biển). Wiktionary cũng ghi thêm nghĩa dị thể của 蟊 (sâu ăn rễ mầm). Tiểu triện có dạng chữ này. Bộ 虫 biểu nghĩa sinh vật nhỏ/côn trùng. Chưa có glyph-origin cụ thể hay cấu trúc học thuật được ghi nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tưu mâu 蝤蛑)", "Hạng Tần Suất (Jun Da)": "5493.0", "Tần Suất % (Jun Da)": "99.9596256446", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 牟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫牟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "牟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛑", "Unihan_Traditional (Chữ Phồn thể)": "蛑", "Pinyin_Xie": "móu", "Âm Hán Việt_Xie": "mâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ ghép để chỉ một loại cua biển hoặc côn trùng gây hại cho lúa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艉', '{"9000": "5494.0", "Chữ Trung Quốc": "艉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 13 | nét | 艉 | vĩ | tượng hình | phần đuôi tàu thuyền | 艉 có bộ 舟 (chu, thuyền — biểu nghĩa). Wiktionary không có glyph-origin; Wiktionary cũng không tìm thấy cấu trúc hình thanh/hội ý. Hình thức chữ gồm 舟 (thuyền) + phần biểu âm, có thể là chữ tạo muộn cho thuật ngữ hàng hải.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vĩ\": đuôi (vĩ) của con tàu (舟) — phần sau cùng nơi bánh lái điều khiển hướng đi. | Gương Hán-Việt | 艉 đối với 艏 (thủ): đầu tàu và đuôi tàu — cặp từ hàng hải. | Mở khoá kiến thức | Biết 艉 (vĩ) mở khoá từ hàng hải: 艏 (đầu tàu), 船艉 (phần đuôi tàu), 艉楼 (cabin đuôi).", "Tự nguyên_Xie": "艉 nghĩa là phần đuôi (sau) của tàu thuyền. Bộ 舟 (chu, thuyền) biểu nghĩa. Wiktionary không có glyph-origin — đây có thể là chữ tạo muộn hoặc chuyên dùng trong hàng hải. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phần đuôi thuyền, tàu", "Hạng Tần Suất (Jun Da)": "5494.0", "Tần Suất % (Jun Da)": "99.9596814574", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 尾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟尾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艉", "Unihan_Traditional (Chữ Phồn thể)": "艉", "Pinyin_Xie": "wěi", "Âm Hán Việt_Xie": "vĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ bộ phận phía sau của tàu thuyền, kết hợp với các từ chỉ phương hướng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钅', '{"9000": "5495.0", "Chữ Trung Quốc": "钅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 5 | nét | 钅 | kim | tượng hình | bộ kim loại (dạng giản thể của 釒) | 钅 là dạng giản thể của 釒 — bộ thủ Kim trong chữ Hán. Dùng làm thành phần biểu nghĩa trong các chữ liên quan đến kim loại. Bản thân 钅 không phải chữ độc lập dùng trong câu, mà là bộ thủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kim\": bộ 钅 là dạng giản của vàng (金) — nhìn thấy 钅 bên trái là biết chữ đó liên quan đến kim loại. | Gương Hán-Việt | 钅 xuất hiện trong hàng trăm chữ: 钱 (tiền), 银 (ngân/bạc), 铁 (thiết/sắt), 铜 (đồng). | Mở khoá kiến thức | Biết 钅 (kim) mở khoá toàn bộ nhóm chữ kim loại: 钱 tiền, 银 bạc, 铁 sắt, 铜 đồng, 金 vàng.", "Tự nguyên_Xie": "钅 là dạng giản của 釒 (kim bàng: bộ kim khi đứng bên trái). Dạng đầy đủ 金 (kim) là chữ tượng hình vẽ mỏ vàng/kim loại trong lòng đất với các hạt quặng. Wiktionary ghi {{Han simp|釒}} — tức đây chỉ là dạng rút gọn hiện đại. Chữ tạo muộn từ cải cách chữ giản thể Trung Quốc. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bộ kim; liên quan tới kim loại", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "𠂉 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱𠂉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "钅", "Unihan_Traditional (Chữ Phồn thể)": "钅", "Pinyin_Xie": "jīn", "Âm Hán Việt_Xie": "kim", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm bộ thủ bên trái trong các chữ Hán liên quan đến kim loại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咴', '{"9000": "5496.0", "Chữ Trung Quốc": "咴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 咴 | hồi | tượng hình | tiếng ngựa hí | 咴 có bộ 口 (khẩu, miệng — biểu nghĩa âm thanh). Wiktionary không có glyph-origin; đây là chữ tượng thanh tạo muộn. Không có cấu trúc hình thanh/hội ý học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồi\": miệng (口) ngựa phát ra tiếng hí \"hồi hồi\" — âm thanh vang rền đặc trưng của ngựa. | Gương Hán-Việt | 咴 trong 咴咴 (hồi hồi: tiếng ngựa hí liên tiếp). | Mở khoá kiến thức | Biết 咴 (hồi) mở khoá từ tả tiếng ngựa trong văn học: 咴咴声 (tiếng hí).", "Tự nguyên_Xie": "咴 là chữ tượng thanh chỉ tiếng ngựa hí (咴咴). Bộ 口 biểu nghĩa âm thanh phát ra từ miệng. Wiktionary không có glyph-origin — chữ tạo muộn, chủ yếu dùng trong văn xuôi hiện đại để tả tiếng ngựa. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hí (từ tượng thanh, tiếng ngựa hí.)", "Hạng Tần Suất (Jun Da)": "5496.0", "Tần Suất % (Jun Da)": "99.9597925662", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 灰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口灰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "灰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咴", "Unihan_Traditional (Chữ Phồn thể)": "咴", "Pinyin_Xie": "huī", "Âm Hán Việt_Xie": "hôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Thường dùng làm từ tượng thanh để mô tả tiếng ngựa kêu. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筮', '{"9000": "5497.0", "Chữ Trung Quốc": "筮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 13 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 巫 | vu | biểu nghĩa | thầy cúng, phù thuỷ | 筮 = 竹 (Trúc, biểu nghĩa: tre) + 巫 (Vu, biểu nghĩa: thầy cúng) + 𠬞 (hai bàn tay); chữ hội ý. Ba thành phần hợp lại: thầy cúng (巫) dùng hai tay (𠬞) cầm que tre (竹) để bói. Wiktionary xác nhận cấu trúc hội ý này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vầu\": thầy vu (巫) hai tay (𠬞) cầm que trúc (竹) gieo quẻ — đó là phép bói cỏ thi 筮. | Gương Hán-Việt | 筮 trong 卜筮 (bốc vầu: bói bằng mai rùa và cỏ thi), 占筮 (chiêm vầu: xem quẻ). | Mở khoá kiến thức | Biết 筮 (vầu) mở khoá từ bói toán cổ: 卜筮 (bói toán), 筮仕 (xin quẻ trước khi ra làm quan).", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Chữ hội ý (hội ý): 竹 (tre) + 巫 (thầy phù thuỷ) + 𠬞 (hai bàn tay) — hình ảnh thầy cúng dùng hai tay cầm que cỏ thi/tre để gieo quẻ bói. Wiktionary xác nhận: {{Han compound|竹|巫|𠬞|t1=bamboo|t2=shaman|t3=two hands|ls=ic}}. Kim văn, đại triện và tiểu triện đều có dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bói cỏ thi", "Hạng Tần Suất (Jun Da)": "5497.0", "Tần Suất % (Jun Da)": "99.9598478622", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 巫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮巫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筮", "Unihan_Traditional (Chữ Phồn thể)": "筮", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thệ, phệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành vi bói toán thời cổ đại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艏', '{"9000": "5498.0", "Chữ Trung Quốc": "艏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 15 | nét | 艏 | thủ | tượng hình | phần trước/mũi tàu thuyền | 艏 có bộ 舟 (chu, thuyền — biểu nghĩa). Wiktionary không có glyph-origin. Hình thức gồm 舟 + phần biểu âm. Chữ tạo muộn cho thuật ngữ hàng hải hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thủ\": đầu (thủ) của con tàu (舟) — mũi tàu xé sóng tiến lên phía trước. | Gương Hán-Việt | 艏 đối với 艉 (vĩ, đuôi tàu) — cặp từ hàng hải chỉ hai đầu tàu. | Mở khoá kiến thức | Biết 艏 (thủ) mở khoá từ hàng hải: 艉 (đuôi tàu), 船艏 (mũi tàu), 艏楼 (cabin mũi).", "Tự nguyên_Xie": "艏 nghĩa là mũi (phần trước) của tàu thuyền. Bộ 舟 (chu) biểu nghĩa tàu thuyền. Wiktionary không có glyph-origin — chữ tạo muộn, dùng trong hàng hải. Đối với 艉 (đuôi tàu). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phần trước thuyền", "Hạng Tần Suất (Jun Da)": "5498.0", "Tần Suất % (Jun Da)": "99.9599031582", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 首", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟首", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "首", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艏", "Unihan_Traditional (Chữ Phồn thể)": "艏", "Pinyin_Xie": "shǒu", "Âm Hán Việt_Xie": "thủ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau để chỉ phần mũi của tàu thuyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糁', '{"9000": "5499.0", "Chữ Trung Quốc": "糁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 14 | nét | 糁 | sâm | tượng hình | hạt gạo, cơm trộn canh | 糁 có bộ 米 (mễ, gạo — biểu nghĩa). Wiktionary không có glyph-origin. Hình thức gồm 米 + phần biểu âm bên phải. Có thể là chữ hình thanh nhưng chưa xác nhận học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sâm\": hạt gạo (米) lẻ sâm sấp — cơm trộn lẫn canh, no mà thanh đạm. | Gương Hán-Việt | 糁 trong 糁羹 (sâm canh: canh có hạt gạo), 糁饭 (cơm trộn canh). | Mở khoá kiến thức | Biết 糁 (sâm) mở khoá từ ẩm thực cổ: 糁羹, 豆糁 (đậu nghiền trộn), văn hóa cơm canh trộn.", "Tự nguyên_Xie": "Tiểu triện | 糁 nghĩa là hạt gạo lẻ hoặc cơm hòa trộn với canh/nước súp. Bộ 米 (gạo) biểu nghĩa. Wiktionary không có glyph-origin. Tiểu triện có dạng chữ này. Dùng trong ẩm thực cổ Trung Hoa, đặc biệt trong văn học và thi ca. Chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hạt gạo; cơm hoà với canh", "Hạng Tần Suất (Jun Da)": "5499.0", "Tần Suất % (Jun Da)": "99.9599584542", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 参", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米参", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "参", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "糁", "Unihan_Traditional (Chữ Phồn thể)": "糝", "Pinyin_Xie": "sǎn", "Âm Hán Việt_Xie": "tảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ các hạt nhỏ hoặc bột mịn của ngũ cốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼍', '{"9000": "5500.0", "Chữ Trung Quốc": "鼍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黽 | Số nét | 20 | nét | 單 | đơn | biểu âm | đơn lẻ, đơn độc | 黽 | biểu nghĩa | cóc, ếch — loài bò sát/lưỡng cư | 鼍 = 單 (Đơn, biểu âm) + 黽 (biểu nghĩa: cóc/loài bò sát); chữ hình thanh. Phần 黽 gợi ý loài bò sát sống dưới nước, phần 單 cho âm đọc. Wiktionary xác nhận cấu trúc này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đà\": con bò sát (黽) đơn độc (單) ngâm mình dưới sông — đó là cá sấu Dương Tử nổi tiếng. | Gương Hán-Việt | 鼍 trong 鼍鼓 (đà cổ: trống bịt da cá sấu), 鼍龙 (đà long: cá sấu Trung Hoa). | Mở khoá kiến thức | Biết 鼍 (đà) mở khoá từ cổ: 鼍鼓 (trống da cá sấu trong lễ nhạc cung đình), 鼍龙.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Chữ hình thanh: 黽 (loài cóc/bò sát nước) biểu nghĩa, 單 (đơn) biểu âm. Giáp cốt văn, kim văn, đại triện và tiểu triện đều có dạng 鼉 (dạng truyền thống). 鼍 chỉ con cá sấu Dương Tử (Alligator sinensis) — loài bò sát nước đặc hữu Trung Quốc. Tiếng trống da cá sấu (鼍鼓) là nhạc cụ lễ nghi cổ Trung Hoa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con kỳ đà", "Hạng Tần Suất (Jun Da)": "5500.0", "Tần Suất % (Jun Da)": "99.9600137502", "GavinGrover_Once (Chiết tự trực tiếp)": "吅 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱吅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鼍", "Unihan_Traditional (Chữ Phồn thể)": "鼉", "Pinyin_Xie": "tuó", "Âm Hán Việt_Xie": "đà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập để chỉ loài cá sấu Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肄', '{"9000": "5501.0", "Chữ Trung Quốc": "肄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 聿 | Số nét | 13 | nét | 肄 | lị | tượng hình | học tập, luyện tập | 肄 có bộ 聿 (duật, bút/gậy — biểu nghĩa hành động viết/luyện tập). Wiktionary không có glyph-origin. Kim văn đã có dạng chữ này. Cấu trúc học thuật chưa được ghi nhận rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lị\": cầm bút (聿) miệt mài học tập mãi không xong — đang học, chưa tốt nghiệp (肄业). | Gương Hán-Việt | 肄 trong 肄业 (lị nghiệp: còn đang theo học, chưa tốt nghiệp). | Mở khoá kiến thức | Biết 肄 (lị) mở khoá thuật ngữ giáo dục: 肄业 (đang theo học), 肄习 (tập luyện).", "Tự nguyên_Xie": "Kim văn | 肄 nghĩa là học tập, luyện tập; cũng có nghĩa dư thừa, mệt nhọc, cành non. Kim văn đã có dạng chữ này. Wiktionary không có glyph-origin cụ thể. Bộ 聿 gợi ý hành động viết/luyện tập. Dùng trong 肄业 (lị nghiệp: đang học, chưa tốt nghiệp). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tập, học; dư, thừa; nhọc; cành non", "Hạng Tần Suất (Jun Da)": "5501.0", "Tần Suất % (Jun Da)": "99.9600690462", "GavinGrover_Once (Chiết tự trực tiếp)": "𠤕 + 聿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰𠤕聿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠤕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "聿", "Unihan_Simplified (Chữ Giản thể)": "肄", "Unihan_Traditional (Chữ Phồn thể)": "肄", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong các từ ghép liên quan đến học tập hoặc thực hành. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籴', '{"9000": "5502.0", "Chữ Trung Quốc": "籴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 8 | nét | 入 | nhập | biểu nghĩa | vào, nhập vào | 䊮 | biểu âm | lúa gạo | 籴 = 入 (Nhập, biểu nghĩa: đưa vào) + 䊮 (biểu âm + biểu nghĩa: lúa thóc); chữ hội ý kiêm hình thanh. Wiktionary ghi ls=ic (hội ý) và ls2=psc (hình thanh) — nghĩa gốc: đưa thóc vào kho = mua thóc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"địch\": thóc gạo (䊮) đưa vào (入) kho — mua thóc nhập kho, đối với 糶 bán ra. | Gương Hán-Việt | 籴 trong 籴粮 (địch lương: mua lương thực), đối với 糶 (tiêu: bán thóc ra). | Mở khoá kiến thức | Biết 籴 (địch) mở khoá cặp từ lương thực cổ: 籴 (mua vào) vs 糶 (bán ra).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ vừa hội ý vừa hình thanh: 入 (nhập, đưa vào) + 䊮 (thóc gạo). Nghĩa: nhập thóc vào, mua thóc. Wiktionary xác nhận {{Han compound|入|䊮|t1=in|t2=grain|c1=s|c2=p|ls=ic|ls2=psc}}. Đại triện và tiểu triện đều có dạng 糴 (truyền thống). Đối với 糶 (tiêu/bán thóc ra). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mua thóc, nhập thóc", "Hạng Tần Suất (Jun Da)": "5502.0", "Tần Suất % (Jun Da)": "99.9601238254", "GavinGrover_Once (Chiết tự trực tiếp)": "入 + 米", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱入米", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "米", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "入", "Unihan_Simplified (Chữ Giản thể)": "籴", "Unihan_Traditional (Chữ Phồn thể)": "糴", "Pinyin_Xie": "dí", "Âm Hán Việt_Xie": "địch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ lương thực để biểu thị việc mua vào. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骜', '{"9000": "5503.0", "Chữ Trung Quốc": "骜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 13 | nét | 敖 | ngào | biểu âm | ngạo nghễ, du ngoạn | 馬 | mã | biểu nghĩa | ngựa | 骜 = 敖 (Ngào, biểu âm) + 馬 (Mã, biểu nghĩa: ngựa); chữ hình thanh. Phần 馬 gợi ý loài ngựa, phần 敖 cho âm đọc. Wiktionary xác nhận cấu trúc này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạo\": con ngựa (馬) ngạo nghễ (敖) không chịu thuần — đó là ngựa bất kham, phóng túng. | Gương Hán-Việt | 骜 trong 桀骜不驯 (kiệt ngạo bất tuần: kiêu ngạo khó thuần phục), 骜放 (ngạo phóng: kiêu hãnh phóng túng). | Mở khoá kiến thức | Biết 骜 (ngạo) mở khoá thành ngữ: 桀骜不驯 (kiêu ngạo không chịu thuần phục).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 馬 (mã, ngựa) biểu nghĩa, 敖 (ngào) biểu âm. Nghĩa gốc: ngựa bất kham, không chịu thuần; mở rộng sang người kiêu ngạo, không chịu khuất phục. Wiktionary xác nhận {{Han compound|敖|馬|ls=psc|t2=horse|c1=p|c2=s}}. Tiểu triện có dạng 驁 (truyền thống). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ngựa bất kham", "Hạng Tần Suất (Jun Da)": "5503.0", "Tần Suất % (Jun Da)": "99.9601786047", "GavinGrover_Once (Chiết tự trực tiếp)": "敖 + 马", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敖马", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骜", "Unihan_Traditional (Chữ Phồn thể)": "驁", "Pinyin_Xie": "ào", "Âm Hán Việt_Xie": "ngạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ bổ nghĩa cho danh từ để chỉ sự ngang tàng, bất kham. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砻', '{"9000": "5504.0", "Chữ Trung Quốc": "砻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 龍 | Số nét | 10 | nét | 砻 | lung | tượng hình | cối xay lúa, mài giũa | 砻 là dạng giản thể của 礱. Wiktionary không ghi cấu trúc hình thanh/hội ý cụ thể. Về hình thức, 砻 có thể gồm 龙 (long, rồng — biểu âm) và một bộ biểu nghĩa, nhưng chưa xác nhận học thuật. Tiểu triện và Lục thư thông có dạng 礱.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lung\": cái cối xay lúa (砻) cứ vòng vòng — lung linh tiếng gạo lúa đổ xuống như rồng (龙) quay. | Gương Hán-Việt | 砻 trong 砻磨 (lung ma: xay mài), 砻糠 (lung khang: trấu lúa). | Mở khoá kiến thức | Biết 砻 (lung) mở khoá từ nông nghiệp: 砻糠 (trấu), 砻磨 (xay mài lúa gạo).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 砻 (dạng giản của 礱) nghĩa là xay lúa, mài giũa. Wiktionary không có glyph-origin cụ thể cho 礱. Tiểu triện và Lục thư thông đã có dạng này. Dùng trong 礱磨 (xay mài), 砻糠 (vỏ trấu sau xay). Chữ liên quan đến nông nghiệp — xay lúa. Chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái cối xay", "Hạng Tần Suất (Jun Da)": "5504.0", "Tần Suất % (Jun Da)": "99.9602333839", "GavinGrover_Once (Chiết tự trực tiếp)": "龙 + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱龙石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "石", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "龙", "Unihan_Simplified (Chữ Giản thể)": "砻", "Unihan_Traditional (Chữ Phồn thể)": "礱", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "lung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Có thể làm danh từ chỉ cối xay hoặc động từ chỉ hành động xay xát. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜮', '{"9000": "5505.0", "Chữ Trung Quốc": "蜮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 蜮 | vức | tượng hình | con vực — sinh vật huyền thoại bắn cát | 蜮 có bộ 虫 (trùng, sinh vật nhỏ — biểu nghĩa). Wiktionary không ghi cấu trúc hình thanh/hội ý rõ. Về hình thức gồm 虫 + phần biểu âm bên phải, song chưa xác nhận học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vức\": con vật (虫) bí ẩn dưới nước phun cát giết người — 鬼蜮 là ví dụ cho thủ đoạn âm mưu. | Gương Hán-Việt | 蜮 trong 鬼蜮伎俩 (quỷ vực kỹ lưỡng: trò ma quỷ, thủ đoạn xảo quyệt). | Mở khoá kiến thức | Biết 蜮 (vức) mở khoá thành ngữ: 鬼蜮伎俩 (âm mưu thủ đoạn), 为鬼为蜮 (làm điều ma quỷ).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 蜮 là sinh vật huyền thoại trong văn hóa Trung Hoa: hình như rùa nhỏ ba chân sống dưới nước, có thể phun cát vào người gây chết. Cũng chỉ sâu ăn lá non. Đại triện và tiểu triện đã có dạng chữ. Dùng trong 鬼蜮伎俩 (quỷ vực kỹ lưỡng: trò ma quỷ thủ đoạn). Wiktionary không ghi glyph-origin học thuật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con vực (một loài bọ)", "Hạng Tần Suất (Jun Da)": "5505.0", "Tần Suất % (Jun Da)": "99.9602881631", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 或", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫或", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "或", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜮", "Unihan_Traditional (Chữ Phồn thể)": "蜮", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "vực", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn cảnh cổ hoặc dùng trong thành ngữ chỉ sự ngầm hại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龀', '{"9000": "5506.0", "Chữ Trung Quốc": "龀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 10 | nét | 龀 | sấn | tượng hình | thay răng sữa | 龀 là dạng giản thể của 齔. Dạng truyền thống 齔 gồm 齒 (xỉ, răng — biểu nghĩa) và một thành phần biểu âm. Wiktionary xác nhận {{Han simp|齔|f=齒|t=齿}} — dạng giản bỏ bớt nét trong bộ 齒.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sấn\": răng (齒→龀) sấn sổ thay đổi — răng sữa rụng đi, răng vĩnh viễn mọc lên. | Gương Hán-Việt | 龀 trong 童龀 (đồng sấn: trẻ em tuổi thay răng), 龀龄 (tuổi thay răng ~7-8). | Mở khoá kiến thức | Biết 龀 (sấn) mở khoá từ cổ: 童龀 (trẻ thơ đang thay răng), 黄口孺子 — độ tuổi thơ ấu.", "Tự nguyên_Xie": "Tiểu triện | 龀 (dạng giản của 齔) nghĩa là rụng răng sữa và mọc răng vĩnh viễn. Bộ 齒 (răng) biểu nghĩa. Tiểu triện có dạng 齔. Dùng trong 龀龄 (độ tuổi thay răng sữa, khoảng 7-8 tuổi), 童龀 (trẻ em đang thay răng). Wiktionary ghi dẫn về 齔. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thay răng sữa thành răng khôn", "Hạng Tần Suất (Jun Da)": "5506.0", "Tần Suất % (Jun Da)": "99.9603429423", "GavinGrover_Once (Chiết tự trực tiếp)": "齿 + 匕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齿匕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齿", "Unihan_Simplified (Chữ Giản thể)": "龀", "Unihan_Traditional (Chữ Phồn thể)": "齔", "Pinyin_Xie": "chèn", "Âm Hán Việt_Xie": "sấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ việc thay răng sữa hoặc kết hợp chỉ tuổi thơ ấu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黢', '{"9000": "5507.0", "Chữ Trung Quốc": "黢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黑 | Số nét | 19 | nét | 黑 | hắc | biểu nghĩa | đen | 夋 | biểu âm | 黢 = 黑 (Hắc, biểu nghĩa: đen) + 夋 (biểu âm); chữ hình thanh. Phần 黑 cho nghĩa đen tối, phần 夋 cho âm đọc. Wiktionary xác nhận cấu trúc này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thúy\": đen hắc (黑) đến mức tối đen như mực — 黑黢黢 là màu đen đậm đặc không thấy gì. | Gương Hán-Việt | 黢 trong 黢黑 (thúy hắc: đen thẫm), 黑黢黢 (đen kịt), 乌黢黢 (tối đen). | Mở khoá kiến thức | Biết 黢 (thúy) mở khoá từ tả màu: 黑黢黢 (đen kịt), 乌黢黢 (tối tăm mù mịt).", "Tự nguyên_Xie": "Chữ hình thanh: 黑 (hắc, đen) biểu nghĩa, 夋 biểu âm. Nghĩa: đen, tối đen. Wiktionary xác nhận {{Han compound|黑|夋|c1=s|c2=p|t1=black|ls=psc}}. Dùng trong 黑黢黢 (đen kịt, tối tăm), 黢黑 (đen thẫm). Chữ tạo muộn hơn so với 黑. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đen", "Hạng Tần Suất (Jun Da)": "5507.0", "Tần Suất % (Jun Da)": "99.9603977216", "GavinGrover_Once (Chiết tự trực tiếp)": "黑 + 夋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰黑夋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黑", "Unihan_Simplified (Chữ Giản thể)": "黢", "Unihan_Traditional (Chữ Phồn thể)": "黢", "Pinyin_Xie": "qū", "Âm Hán Việt_Xie": "xuất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ bổ nghĩa cho danh từ hoặc kết hợp tạo từ ghép chỉ màu sắc đen tối. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('劢', '{"9000": "5508.0", "Chữ Trung Quốc": "劢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 力 | Số nét | 5 | nét | 劢 | mại | tượng hình | cố gắng, gắng sức | 劢 là dạng giản thể của 勱. Wiktionary không ghi cấu trúc hình thanh/hội ý. Hình thức có bộ 力 (lực, sức — biểu nghĩa gắng sức). Cấu trúc học thuật chưa được xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mại\": gắng hết sức (力) mà tiến mại lên — ra sức nỗ lực, không lùi bước. | Gương Hán-Việt | 劢 trong 劢力 (mại lực: ra sức), 奋劢 (phấn mại: phấn đấu nỗ lực). | Mở khoá kiến thức | Biết 劢 (mại) mở khoá từ văn ngôn chỉ nỗ lực: 劢力, 奋劢 — cố gắng hết mình.", "Tự nguyên_Xie": "劢 (dạng giản của 勱) nghĩa là gắng sức, ra sức nỗ lực. Bộ 力 (sức mạnh) có thể là biểu nghĩa. Wiktionary ghi {{Han etyl}} (lỗi chính tả — thường là {{Han etym}}) và không có glyph-origin. Chữ tạo muộn, không thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cố gắng, gắng sức", "Hạng Tần Suất (Jun Da)": "5508.0", "Tần Suất % (Jun Da)": "99.9604525008", "GavinGrover_Once (Chiết tự trực tiếp)": "万 + 力", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰万力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "万", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "力", "Unihan_Simplified (Chữ Giản thể)": "劢", "Unihan_Traditional (Chữ Phồn thể)": "勱", "Pinyin_Xie": "mài", "Âm Hán Việt_Xie": "mại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường dùng làm động từ trong văn viết cổ để thể hiện sự nỗ lực, cố gắng hết mình. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耪', '{"9000": "5509.0", "Chữ Trung Quốc": "耪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耒 | Số nét | 16 | nét | 耪 | bảng | tượng hình | xới đất, cày xới | 耪 có bộ 耒 (lỗi, cái cày — biểu nghĩa nông cụ). Wiktionary không có glyph-origin. Hình thức gồm 耒 + phần biểu âm bên phải. Chữ tạo muộn, không thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bảng\": cầm cày (耒) xới tơi đất — động tác làm đất nông nghiệp vùng phương Bắc. | Gương Hán-Việt | 耪 trong 耪地 (bảng địa: xới đất), 耪草 (bảng thảo: xới cỏ dại). | Mở khoá kiến thức | Biết 耪 (bảng) mở khoá từ nông nghiệp phương Bắc: 耪地 (xới đất), 耪草 (xới cỏ).", "Tự nguyên_Xie": "耪 nghĩa là xới tơi đất bằng nông cụ. Bộ 耒 (lỗi, cái cày) biểu nghĩa nông nghiệp. Wiktionary không có glyph-origin. Chữ tạo muộn, dùng chủ yếu trong phương ngữ phương Bắc Trung Quốc để chỉ động tác xới đất sau khi gieo hạt. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xới tơi đất", "Hạng Tần Suất (Jun Da)": "5509.0", "Tần Suất % (Jun Da)": "99.9605610257", "GavinGrover_Once (Chiết tự trực tiếp)": "耒 + 旁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耒旁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耒", "Unihan_Simplified (Chữ Giản thể)": "耪", "Unihan_Traditional (Chữ Phồn thể)": "耪", "Pinyin_Xie": "pǎng", "Âm Hán Việt_Xie": "bảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động làm đất trong nông nghiệp, thường mang tân ngữ phía sau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬯', '{"9000": "5510.0", "Chữ Trung Quốc": "鬯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鬯 | Số nét | 10 | nét | 鬯 | sướng | tượng hình | bình đựng rượu tế lễ | 鬯 là chữ tượng hình thuần tuý: vẽ hình chiếc bình đựng rượu nếp dùng trong tế lễ, với các điểm nhỏ tượng trưng hạt millet (mạch nha lên men). Wiktionary ghi: {{liushu|p}} — tức tượng hình. Chiếc thìa nhỏ ở đáy được thêm vào sau.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sướng\": chiếc bình (鬯) rượu nếp thơm ngào ngạt — dâng lên thần linh, lòng thấy thư sướng. | Gương Hán-Việt | 鬯 trong 秬鬯 (cự sướng: rượu mạch đen tế lễ), 匕鬯不惊 (bỉ sướng bất kinh: trật tự yên bình). | Mở khoá kiến thức | Biết 鬯 (sướng) mở khoá thành ngữ cổ: 匕鬯不惊 (bình yên vô sự), 秬鬯 (rượu tế đặc biệt).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Chữ tượng hình (tượng hình): vẽ chiếc bình đầy rượu nếp tế thần làm từ mạch đen lên men và vỏ thơm. Các điểm nhỏ tượng trưng hạt millet. Wiktionary xác nhận {{liushu|p}} of a vessel full of sacrificial wine. Giáp cốt văn, kim văn, đại triện và tiểu triện đều có dạng này. 鬯 cũng là bộ thủ riêng (bộ 鬯). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rượu nếp", "Hạng Tần Suất (Jun Da)": "5510.0", "Tần Suất % (Jun Da)": "99.9606152881", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 匕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱匕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鬯", "Unihan_Traditional (Chữ Phồn thể)": "鬯", "Pinyin_Xie": "chàng", "Âm Hán Việt_Xie": "sưởng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này chủ yếu làm danh từ chỉ một loại rượu cúng tế thời cổ hoặc làm tính từ chỉ sự thông suốt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畚', '{"9000": "5511.0", "Chữ Trung Quốc": "畚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 田 | Số nét | 10 | nét | 畚 | bổn | tượng hình | cái ky hốt đất, rổ tre | 畚 không có cấu trúc hình thanh/hội ý rõ ràng trong Wiktionary. Về hình thức có bộ 田 (điền, ruộng) — song mối liên hệ không rõ ràng. Wiktionary chỉ ghi âm đọc và định nghĩa mà không nêu glyph-origin.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bổn\": cái ky đựng đất (畚) — gốc gác từ ruộng đất (田), dụng cụ lao động thô sơ của người nông dân. | Gương Hán-Việt | 畚 trong 畚箕 (bổn cơ: sọt hốt đất), 畚斗 (ky xúc đất). | Mở khoá kiến thức | Biết 畚 (bổn) mở khoá từ công cụ thủ công: 畚箕, 畚斗, 箕畚 — đồ đựng, hốt đất.", "Tự nguyên_Xie": "畚 nghĩa là cái ky hốt đất hoặc rổ tre đan để xúc đất, vật liệu xây dựng. Wiktionary không có glyph-origin. Tiểu triện có dạng chữ này. Dùng trong 畚斗 (bổn đẩu: cái ky/sọt), 畚箕 (bổn cơ: cái sọt đan), 箕畚 (đồ dùng xúc đất). Chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái son, cái ky hốt đất", "Hạng Tần Suất (Jun Da)": "5511.0", "Tần Suất % (Jun Da)": "99.9606695505", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 田", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱田", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "畚", "Unihan_Traditional (Chữ Phồn thể)": "畚", "Pinyin_Xie": "běn", "Âm Hán Việt_Xie": "bản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường làm danh từ chỉ dụng cụ hốt rác, đất cát hoặc làm động từ chỉ việc xúc bằng ky. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觳', '{"9000": "5512.0", "Chữ Trung Quốc": "觳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 角 | Số nét | 17 | nét | 觳 | hộc | tượng hình | cái hộc đong thóc; khiếp sợ | 觳 có bộ 角 (giác, sừng/góc — biểu nghĩa). Wiktionary không ghi cấu trúc hình thanh/hội ý. Hình thức gồm 角 + phần biểu âm bên phải, nhưng chưa xác nhận học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hộc\": cái hộc (觳) đo lúa gạo — và con bò run rẩy (觳觫) trước miếng dao như đo được số phận mình. | Gương Hán-Việt | 觳 trong 觳觫 (hộc tốc: run sợ run rẩy — điển cố bò run trước khi bị giết tế). | Mở khoá kiến thức | Biết 觳 (hộc) mở khoá điển cố Mạnh Tử: 觳觫 (bò run rẩy), được Tề Tuyên Vương tha tội.", "Tự nguyên_Xie": "Tiểu triện | 觳 nghĩa là đơn vị đo lường cổ (10 đấu = 1 hộc) hoặc chén/cốc nhỏ. Bộ 角 (sừng/cốc) có thể biểu nghĩa đồ đựng. Wiktionary không có glyph-origin. Tiểu triện có dạng chữ này. Dùng trong 觳觫 (hộc tốc: run sợ, vì con bò run rẩy trước khi bị mổ). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái hộc đựng thóc; hộc (đơn vị đo, bằng 10 đấu)", "Hạng Tần Suất (Jun Da)": "5512.0", "Tần Suất % (Jun Da)": "99.960723813", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "觳", "Unihan_Traditional (Chữ Phồn thể)": "觳", "Pinyin_Xie": "hú", "Âm Hán Việt_Xie": "hộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này thường làm danh từ chỉ đồ đong lường cổ hoặc làm lượng từ đo lường dung tích. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稞', '{"9000": "5513.0", "Chữ Trung Quốc": "稞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 13 | nét | 禾 | biểu nghĩa | cây lúa, ngũ cốc | 果 | quả | biểu âm | quả, kết quả | 稞 = 禾 (biểu nghĩa: cây lúa/ngũ cốc) + 果 (Quả, biểu âm); chữ hình thanh. Phần 禾 gợi ý loại ngũ cốc, phần 果 cho âm đọc. Wiktionary xác nhận cấu trúc này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoa\": cây lúa (禾) mang hạt như quả (果) tròn — đó là lúa mạch Tây Tạng, lương thực miền cao. | Gương Hán-Việt | 稞 trong 青稞 (thanh khoa: lúa mạch Tây Tạng), 稞麦 (khoa mạch: đại mạch không vỏ). | Mở khoá kiến thức | Biết 稞 (khoa) mở khoá từ văn hóa Tây Tạng: 青稞 (lúa mạch cao nguyên), 青稞酒 (rượu lúa mạch Tạng).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 禾 (lúa/ngũ cốc) biểu nghĩa, 果 (quả) biểu âm. Nghĩa: lúa mạch Tây Tạng (青稞, qīng kē) — loại đại mạch không vỏ trồng ở vùng cao nguyên. Wiktionary xác nhận {{Han compound|禾|果|ls=psc|c1=s|c2=p|t1=rice}}. Tiểu triện có dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây lúa", "Hạng Tần Suất (Jun Da)": "5513.0", "Tần Suất % (Jun Da)": "99.9607780754", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 果", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾果", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稞", "Unihan_Traditional (Chữ Phồn thể)": "稞", "Pinyin_Xie": "kē", "Âm Hán Việt_Xie": "khoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại ngũ cốc hạt trần, tiêu biểu là lúa mạch cao nguyên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹁', '{"9000": "5514.0", "Chữ Trung Quốc": "鹁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 12 | nét | 鹁 | bột | tượng hình | chim bồ câu rừng | 鹁 là dạng giản thể của 鵓. Wiktionary không ghi cấu trúc hình thanh/hội ý. Hình thức có bộ 鸟 (điểu, chim — biểu nghĩa). Có thể là hình thanh với phần biểu âm, nhưng chưa xác nhận học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bột\": con chim (鸟) kêu \"bột bột\" trong rừng — đó là chim bồ câu rừng 鹁鸽. | Gương Hán-Việt | 鹁 trong 鹁鸽 (bột cáp: bồ câu rừng), 鵓鴣 (chim cun cút bồ câu). | Mở khoá kiến thức | Biết 鹁 (bột) mở khoá từ chỉ chim bồ câu: 鹁鸽 (bồ câu rừng), 鹁鸪 (cun cút).", "Tự nguyên_Xie": "鹁 (dạng giản của 鵓) chỉ loài chim bồ câu rừng (鹁鸽, bồ câu). Bộ 鸟 biểu nghĩa chim. Wiktionary dẫn về 鵓 nhưng không có glyph-origin. Tiếng kêu của chim 鹁 là \"bột bột\" — có thể là từ tượng thanh. Chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bột cáp 鵓鴿,鹁鸽)", "Hạng Tần Suất (Jun Da)": "5514.0", "Tần Suất % (Jun Da)": "99.9608323379", "GavinGrover_Once (Chiết tự trực tiếp)": "孛 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰孛鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹁", "Unihan_Traditional (Chữ Phồn thể)": "鵓", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "bột", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, hầu như chỉ dùng trong từ ghép để chỉ loài chim bồ câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲲', '{"9000": "5515.0", "Chữ Trung Quốc": "鲲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 魚 | ngư | biểu nghĩa | cá | 昆 | côn | biểu âm | côn trùng; anh (cả) | 鲲 = 魚 (Ngư, biểu nghĩa: cá) + 昆 (Côn, biểu âm); chữ hình thanh. Phần 魚 gợi ý sinh vật biển, phần 昆 cho âm đọc. Wiktionary xác nhận cấu trúc này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"côn\": con cá (魚) khổng lồ mang tên Côn (昆) — Trang Tử viết: \"Ở biển Bắc có con cá Côn, to không biết bao nhiêu nghìn dặm\". | Gương Hán-Việt | 鲲 trong 鲲鹏 (côn bằng: cá Côn hoá thành chim Bằng), điển cố Trang Tử về chí lớn. | Mở khoá kiến thức | Biết 鲲 (côn) mở khoá điển cố Trang Tử: 鲲鹏展翅 (cá Côn hoá chim Bằng, chí lớn cao bay xa).", "Tự nguyên_Xie": "Chữ hình thanh: 魚 (ngư, cá) biểu nghĩa, 昆 (côn) biểu âm. Gốc nghĩa là trứng cá hoặc cá con nhỏ; sau mở rộng thành cá Côn khổng lồ huyền thoại trong Trang Tử. Wiktionary xác nhận {{Han compound|魚|昆|ls=psc|c1=s|t1=fish|c2=p}}. Dạng truyền thống 鯤. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con cá côn", "Hạng Tần Suất (Jun Da)": "5515.0", "Tần Suất % (Jun Da)": "99.9608866003", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 昆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼昆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲲", "Unihan_Traditional (Chữ Phồn thể)": "鯤", "Pinyin_Xie": "kūn", "Âm Hán Việt_Xie": "côn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài cá khổng lồ trong truyền thuyết, thường đi liền với chim bằng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('捌', '{"9000": "5516.0", "Chữ Trung Quốc": "捌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 10 | nét | 扌 | biểu nghĩa | tay — động tác tay | 別 | biết | biểu âm | chia rẽ, khác biệt | 捌 = 扌 (biểu nghĩa: tay, hành động tay) + 別 (Biết, biểu âm); chữ hình thanh. Nghĩa gốc: dùng tay phá ra, chia tách. Wiktionary xác nhận cấu trúc này. Cũng dùng là chữ số 8 trong văn kiện tài chính (chống sửa chữa).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bịt\": tay (扌) bịt lại chia (別) ra — dùng làm chữ 8 (八) trong văn kiện để bịt đường gian lận. | Gương Hán-Việt | 捌 dùng thay 八 trong văn kiện tài chính: 壹貳叁肆伍陸柒捌玖拾. | Mở khoá kiến thức | Biết 捌 (bịt) mở khoá bộ chữ số kế toán: 壹貳叁肆伍陸柒捌玖拾 — dùng trong hợp đồng, séc ngân hàng.", "Tự nguyên_Xie": "Đại triện | Chữ hình thanh: 扌 (手, tay) biểu nghĩa, 別 (biết) biểu âm. Nghĩa gốc: tay phá ra, chia tách. Sau đó dùng làm chữ số 8 (八) trong văn kiện ngân hàng/tài chính để tránh gian lận sửa chữa. Wiktionary xác nhận {{Han compound|手|alt1=扌|別|t1=hand|ls=psc|c1=s|c2=p}}. Đại triện có dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phá, chia; tám, 8", "Hạng Tần Suất (Jun Da)": "5516.0", "Tần Suất % (Jun Da)": "99.9609946084", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 别", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌别", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "别", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "捌", "Unihan_Traditional (Chữ Phồn thể)": "捌", "Pinyin_Xie": "bā", "Âm Hán Việt_Xie": "bát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Số từ | 数词 | Động từ | 动词 | Chữ này thường dùng làm số từ trong các văn bản tài chính để biểu thị số tám nhằm tránh tẩy xóa. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菔', '{"9000": "5517.0", "Chữ Trung Quốc": "菔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菔 | phục | tượng hình | củ cải trắng, rau cải | 菔 có bộ 艸/⺾ (thảo, cỏ/cây — biểu nghĩa thực vật). Wiktionary không ghi cấu trúc hình thanh/hội ý. Hình thức gồm ⺾ + phần biểu âm bên dưới/phải, song chưa xác nhận học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phục\": cây cỏ (⺾) mang củ ngầm dưới đất phục sẵn — đó là củ cải trắng 莱菔 ẩn mình dưới lòng đất. | Gương Hán-Việt | 菔 trong 萊菔 (lai phục: củ cải trắng), 蘿菔 (la phục: củ cải). | Mở khoá kiến thức | Biết 菔 (phục) mở khoá tên thảo dược: 萊菔子 (hạt củ cải, thuốc tiêu thực), 蘿菔 (củ cải).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 菔 chỉ loại củ cải trắng; chủ yếu dùng trong tên ghép 蘆菔 và 萊菔 (tức củ cải — Raphanus sativus). Bộ ⺾ (thảo) biểu nghĩa thực vật. Wiktionary ghi {{Han etym}} nhưng không có glyph-origin. Tiểu triện và Lục thư thông có dạng này. Chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rau cải", "Hạng Tần Suất (Jun Da)": "5517.0", "Tần Suất % (Jun Da)": "99.961048354", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 服", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹服", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "服", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菔", "Unihan_Traditional (Chữ Phồn thể)": "菔", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "bặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong từ ghép lai phục để chỉ củ cải trắng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('獬', '{"9000": "5518.0", "Chữ Trung Quốc": "獬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 16 | nét | 獬 | giải | tượng hình | con giải trĩ — kỳ thú trừ gian | 獬 có bộ 犬/犭 (khuyển, chó — biểu nghĩa thú vật). Wiktionary không ghi cấu trúc hình thanh/hội ý. Hình thức gồm 犭 + phần biểu âm bên phải, song chưa xác nhận học thuật cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giải\": con thú (犭) giải trĩ (獬豸) — một sừng phân biệt thiện ác, húc kẻ gian, biểu tượng công lý. | Gương Hán-Việt | 獬 trong 獬豸 (giải trĩ: kỳ thú công lý), 獬豸冠 (mũ giải trĩ — mũ quan tòa cổ Trung Hoa). | Mở khoá kiến thức | Biết 獬 (giải) mở khoá văn hóa pháp luật cổ: 獬豸 (biểu tượng công lý), 獬豸冠 (mũ quan).", "Tự nguyên_Xie": "獬 chỉ dùng trong 獬豸 (giải trĩ): kỳ thú huyền thoại Trung Hoa hình như dê/lân, có một sừng, thông minh phân biệt thiện ác — húc vào kẻ gian dối. Biểu tượng của công lý và pháp luật cổ Trung Hoa. Bộ 犭 (thú) biểu nghĩa. Wiktionary không có glyph-origin. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: giải trĩ 獬豸)", "Hạng Tần Suất (Jun Da)": "5518.0", "Tần Suất % (Jun Da)": "99.9611020997", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 解", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭解", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "解", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "獬", "Unihan_Traditional (Chữ Phồn thể)": "獬", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "giải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong từ ghép giải trĩ để chỉ loài thần thú phân biệt chính tà. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('柘', '{"9000": "5519.0", "Chữ Trung Quốc": "柘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 木 | mộc | biểu nghĩa | cây | 石 | thạch | biểu âm | đá | 柘 = 木 (Mộc, biểu nghĩa: cây) + 石 (Thạch, biểu âm: đá). Chữ hình thanh — bộ Mộc xác định đây là loài cây, phần Thạch cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giá\" (柘): hình ảnh cây gỗ (木) cứng như đá (石) — đó là cây giá, loài cây gỗ cứng họ dâu. | Gương Hán-Việt | giá — dùng trong \"giá mộc\" (cây giá) | Mở khoá kiến thức | Biết 柘 mở khoá tên loài cây trong văn chương cổ Trung Hoa, liên quan đến nghề dệt lụa và làm cung tên.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. Bộ 木 (Mộc) biểu thị loại thực vật, phần 石 (Thạch) biểu âm. Cây 柘 (zhè) là một loài thân gỗ họ dâu tằm, lá dùng nuôi tằm, gỗ cứng dùng làm cung. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây gai, cây chá (một loài giống cây dâu tằm)", "Hạng Tần Suất (Jun Da)": "5519.0", "Tần Suất % (Jun Da)": "99.9611558454", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "石", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "柘", "Unihan_Traditional (Chữ Phồn thể)": "柘", "Pinyin_Xie": "zhè", "Âm Hán Việt_Xie": "chá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loài cây gỗ có lá nuôi tằm và vỏ dùng làm thuốc nhuộm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('娆', '{"9000": "5520.0", "Chữ Trung Quốc": "娆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 9 | nét | 娆 | nhiêu | tượng hình | duyên dáng, quyến rũ | 娆 là dạng giản thể của 嬈, vốn gồm 女 (Nữ) và 堯 (Nghiêu, biểu âm). Chữ hình thanh — bộ Nữ biểu thị liên quan đến phụ nữ, dáng điệu; phần Nghiêu biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhiêu\" (娆): người phụ nữ (女) duyên dáng như vua Nghiêu (尧) — yêu nhiêu, mê hoặc lòng người. | Gương Hán-Việt | nhiêu — dùng trong \"yêu nhiêu\" (妖娆, vẻ duyên dáng quyến rũ) | Mở khoá kiến thức | Biết 娆 mở khoá từ 妖娆 (yêu nhiêu) — từ thơ văn tả vẻ đẹp mê hoặc, yêu kiều.", "Tự nguyên_Xie": "Tiểu triện | 娆 là dạng giản thể của 嬈, với 堯 (Nghiêu) giản lược thành 尧. Chữ hình thanh: bộ 女 (Nữ) biểu ý vẻ duyên dáng của người phụ nữ; phần 堯/尧 biểu âm (ráo). Thường dùng trong từ 妖娆 (yāo ráo) — yêu nhiêu, duyên dáng quyến rũ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: yêu nhiêu 妖嬈,妖娆)", "Hạng Tần Suất (Jun Da)": "5520.0", "Tần Suất % (Jun Da)": "99.961209591", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 尧", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女尧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "娆", "Unihan_Traditional (Chữ Phồn thể)": "嬈", "Pinyin_Xie": "ráo", "Âm Hán Việt_Xie": "nhiễu, nhiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ trong từ ghép yêu nhiêu để miêu tả vẻ đẹp uốn lượn, quyến rũ của phụ nữ hoặc phong cảnh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篪', '{"9000": "5521.0", "Chữ Trung Quốc": "篪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 16 | nét | 篪 | trì | tượng hình | sáo trúc bịt đầu dùng trong nhã nhạc cung đình | 篪 có bộ 竹 (Trúc) ở trên, phần dưới là 虒 hoặc biến thể. Chữ hình thanh — bộ Trúc xác định vật liệu làm nhạc cụ; phần dưới biểu âm. Chưa có phân tích Wiktionary rõ ràng về cấu trúc phần dưới.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trì\" (篪): sáo trúc (竹) cổ của cung đình — âm trì vang như tiếng sáo trúc réo rắt. | Gương Hán-Việt | trì — dùng trong \"huân trì\" (埙篪, ví tình huynh đệ hòa hợp) | Mở khoá kiến thức | Biết 篪 mở khoá thành ngữ \"huân trì tương hòa\" (兄弟感情好) — ví tình anh em hòa thuận.", "Tự nguyên_Xie": "Tiểu triện | 篪 là loại sáo trúc bịt đầu (close-ended) dùng trong nhã nhạc cung đình Trung Hoa cổ, có từ 7 đến 8 lỗ tùy theo tài liệu cổ. Bộ 竹 (Trúc) xác định chất liệu. Thường được nhắc cùng với 埙 (huân — nhạc cụ đất nung): \"如壎如篪\" (như huân như trì) ví tình huynh đệ hòa hợp. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái sáo 8 lỗ", "Hạng Tần Suất (Jun Da)": "5521.0", "Tần Suất % (Jun Da)": "99.9612633367", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 虒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮虒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篪", "Unihan_Traditional (Chữ Phồn thể)": "篪", "Pinyin_Xie": "chí", "Âm Hán Việt_Xie": "trì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại nhạc cụ thổi bằng tre thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲀', '{"9000": "5522.0", "Chữ Trung Quốc": "鲀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 12 | nét | 鲀 | đồn | tượng hình | cá nóc, cá lợn biển | 鲀 là dạng giản thể của 魨, vốn gồm 魚 (Ngư, biểu nghĩa: cá) và 屯 (Đồn, biểu âm). Chữ hình thanh — bộ Ngư xác định loài cá, phần 屯 biểu âm tún.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồn\" (鲀): con cá (鱼) phình tròn như đồn binh (屯) khi gặp nguy hiểm — đó là cá nóc, cá đồn. | Gương Hán-Việt | đồn — dùng trong \"hà đồn\" (河豚/河鲀, cá nóc nước ngọt) | Mở khoá kiến thức | Biết 鲀 mở khoá từ 河鲀 (hà đồn — cá nóc) và nhóm từ về hải sản có độc trong tiếng Trung.", "Tự nguyên_Xie": "鲀 là dạng giản thể của 魨, trong đó 魚 (Ngư) được giản lược thành 鱼. Cấu trúc hình thanh: 魚 biểu nghĩa (loài cá), 屯 biểu âm. Cá nóc (河豚, hé tún) là loài cá biển có độc tố tetrodotoxin nguy hiểm, song thịt được coi là món ngon ở Nhật Bản và Trung Quốc. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá lợn biển, cá nóc", "Hạng Tần Suất (Jun Da)": "5522.0", "Tần Suất % (Jun Da)": "99.9613170823", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 屯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼屯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲀", "Unihan_Traditional (Chữ Phồn thể)": "魨", "Pinyin_Xie": "tún", "Âm Hán Việt_Xie": "đồn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong sinh học để chỉ các loài cá thuộc họ cá nóc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谰', '{"9000": "5523.0", "Chữ Trung Quốc": "谰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 14 | nét | 谰 | lam | tượng hình | vu khống, nói xấu bịa đặt | 谰 là dạng giản thể của 讕, vốn gồm 訁(讠, Ngôn, biểu nghĩa: lời nói) và 闌/门 (Lan, biểu âm). Chữ hình thanh — bộ Ngôn xác định liên quan đến ngôn ngữ, lời nói; phần còn lại biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lam\" (谰): lời nói (讠) phóng túng không bờ không bến — vu khống, bịa đặt. | Gương Hán-Việt | lam — dùng trong \"lam ngôn\" (谰言, lời bịa đặt) | Mở khoá kiến thức | Biết 谰 mở khoá từ 谰言 (lam ngôn — lời vu khống) và 无耻谰言 (lời vô sỉ bịa đặt).", "Tự nguyên_Xie": "Tiểu triện | 谰 là dạng giản thể của 讕, trong đó 訁 giản thành 讠 và 門 giản thành 门. Cấu trúc hình thanh: 讠(Ngôn) biểu ý lời nói/ngôn từ; phần biểu âm lan. Nghĩa gốc: vu khống, bịa đặt lời nói. Thường dùng trong từ 谰言 (lam ngôn — lời bịa đặt). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vu khống", "Hạng Tần Suất (Jun Da)": "5523.0", "Tần Suất % (Jun Da)": "99.9613703112", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 阑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠阑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谰", "Unihan_Traditional (Chữ Phồn thể)": "讕", "Pinyin_Xie": "lán", "Âm Hán Việt_Xie": "lan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong các từ ghép như vu lam hoặc lam ngôn để chỉ hành vi vu oan cho người khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('孬', '{"9000": "5524.0", "Chữ Trung Quốc": "孬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 子 | Số nét | 10 | nét | 不 | bất | biểu nghĩa | không, phủ định | 好 | hảo | biểu nghĩa | tốt, giỏi | 孬 = 不 (Bất, biểu nghĩa: không) + 好 (Hảo, biểu nghĩa: tốt). Chữ hội ý — ghép \"không\" và \"tốt\" lại thành \"không tốt\", tức xấu, hèn nhát. Cấu tạo minh bạch, dễ nhớ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nao\" (孬): không (不) tốt (好) — đó là nao, xấu, hèn. Cấu trúc chữ hiển thị thẳng nghĩa. | Gương Hán-Việt | nao — dùng trong tiếng Hán phương ngữ, chưa thông dụng trong từ Hán-Việt tiếng Việt | Mở khoá kiến thức | Biết 孬 giúp hiểu cách người Trung Quốc tạo chữ mới theo hội ý — đọc hình là biết nghĩa ngay.", "Tự nguyên_Xie": "孬 là chữ hội ý hiện đại, ghép 不 (bất — không) và 好 (hảo — tốt). Nghĩa đen là \"không tốt\", từ đó mang nghĩa: xấu, tồi, nhát gan. Đây là chữ tạo muộn trong lịch sử chữ Hán, không thấy trong giáp cốt hoặc kim văn cổ. Phổ biến trong phương ngữ miền Bắc Trung Quốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xấu, tồi; nhát gan, nhút nhát, hèn nhát", "Hạng Tần Suất (Jun Da)": "5524.0", "Tần Suất % (Jun Da)": "99.9614235401", "GavinGrover_Once (Chiết tự trực tiếp)": "不 + 好", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱不好", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "好", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "不", "Unihan_Simplified (Chữ Giản thể)": "孬", "Unihan_Traditional (Chữ Phồn thể)": "孬", "Pinyin_Xie": "nāo", "Âm Hán Việt_Xie": "nạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Dùng làm tính từ trong khẩu ngữ để chê bai tính chất xấu hoặc tính cách nhút nhát của ai đó. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('伥', '{"9000": "5525.0", "Chữ Trung Quốc": "伥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 6 | nét | 人 | nhân | biểu nghĩa | người | 長 | trường | biểu âm | dài, lớn | 伥 = 亻(Nhân, biểu nghĩa: người) + 長 (Trường, biểu âm). Chữ hình thanh — bộ Nhân xác định liên quan đến con người; phần Trường cho âm đọc chāng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trường\" (伥): người (亻) lang thang dài lâu (長) không siêu thoát — hồn ma kẻ bị hổ ăn làm tay sai. | Gương Hán-Việt | trường — dùng trong \"vị hổ tác trường\" (为虎作伥, làm tay sai cho kẻ ác) | Mở khoá kiến thức | Biết 伥 mở khoá thành ngữ 为虎作伥 — cảnh báo về kẻ tiếp tay cho cái ác.", "Tự nguyên_Xie": "Tiểu triện | 伥 (cũng viết 倀) là chữ hình thanh: bộ 人 (Nhân) biểu ý liên quan đến người, 長 (Trường) biểu âm. Nghĩa gốc: hồn ma của người bị hổ ăn thịt, trở thành tôi tớ của hổ và dẫn đường tìm nạn nhân tiếp theo. Thành ngữ 为虎作伥 (vị hổ tác trường) — làm tay sai cho kẻ ác. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lông bông", "Hạng Tần Suất (Jun Da)": "5525.0", "Tần Suất % (Jun Da)": "99.9614767689", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 长", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻长", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "长", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "伥", "Unihan_Traditional (Chữ Phồn thể)": "倀", "Pinyin_Xie": "chāng", "Âm Hán Việt_Xie": "trành", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong từ ghép trường quỷ hoặc vi hổ tác trường để chỉ kẻ tay sai giúp người ác làm bậy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谇', '{"9000": "5526.0", "Chữ Trung Quốc": "谇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 10 | nét | 谇 | tuế | tượng hình | mắng nhiếc, nói xấu | 谇 là dạng giản thể của 誶. Chữ có bộ 讠(Ngôn, biểu nghĩa: lời nói) và phần biểu âm. Chữ hình thanh — bộ Ngôn xác định liên quan đến ngôn ngữ, lời nói mắng nhiếc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuế\" (谇): lời nói (讠) cay độc như dao — mắng nhiếc, xỉ vả. | Gương Hán-Việt | tuế — dùng trong văn ngôn Trung Quốc cổ, chưa thông dụng trong từ Hán-Việt tiếng Việt | Mở khoá kiến thức | Biết 谇 mở khoá vốn từ văn ngôn về hành động ngôn ngữ tiêu cực như mắng nhiếc, xỉ vả.", "Tự nguyên_Xie": "Bạch thư | Tiểu triện | 谇 (誶) là chữ hình thanh với bộ 言/讠(Ngôn) biểu ý lời nói, phần còn lại biểu âm suì. Nghĩa: mắng nhiếc, xỉ vả, dùng lời lẽ sỉ nhục ai. Wiktionary ghi nhận dạng cổ 誶 có hình ảnh trong bạch thư (silk manuscript) và tiểu triện. Đây là chữ văn ngôn, ít dùng trong văn hiện đại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mắng nhiếc", "Hạng Tần Suất (Jun Da)": "5526.0", "Tần Suất % (Jun Da)": "99.9615299978", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 卒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠卒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谇", "Unihan_Traditional (Chữ Phồn thể)": "誶", "Pinyin_Xie": "suì", "Âm Hán Việt_Xie": "tối", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ trong văn ngôn để chỉ hành vi la mắng hoặc trách phạt bằng lời nói. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄄', '{"9000": "5527.0", "Chữ Trung Quốc": "鄄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 11 | nét | 鄄 | quyện | tượng hình | địa danh: tên huyện ở Sơn Đông | 鄄 có bộ 阝(Ấp, bên phải, biểu nghĩa: địa danh, vùng đất) và phần bên trái biểu âm. Chữ hình thanh dùng để ký âm địa danh — bộ Ấp xác định là tên đất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyện\" (鄄): đất (阝) cuộn lại một góc — tên huyện cổ ở Sơn Đông. Chưa có nguồn học thuật rõ ràng về glyph-origin. | Gương Hán-Việt | quyện — địa danh lịch sử trong văn bản Trung Hoa | Mở khoá kiến thức | Biết 鄄 giúp đọc địa danh cổ trong sử sách Trung Quốc (Tam Quốc, Hán thư).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 鄄 là tên huyện cổ ở tỉnh Sơn Đông, Trung Quốc (huyện Quyện, nay là Quyện Thành). Cấu trúc hình thanh: bộ 邑/阝(Ấp) biểu ý địa danh, phần còn lại biểu âm juàn. Wiktionary không có phân tích glyph-origin rõ ràng; chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Có hình trong tiểu triện. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên một huyện ở tỉnh Sơn Đông của Trung Quốc", "Hạng Tần Suất (Jun Da)": "5527.0", "Tần Suất % (Jun Da)": "99.9615832267", "GavinGrover_Once (Chiết tự trực tiếp)": "垔 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰垔阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "垔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄄", "Unihan_Traditional (Chữ Phồn thể)": "鄄", "Pinyin_Xie": "juàn", "Âm Hán Việt_Xie": "quyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng để chỉ địa danh cổ hoặc huyện Quyện Thành thuộc tỉnh Sơn Đông, Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狎', '{"9000": "5528.0", "Chữ Trung Quốc": "狎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 8 | nét | 犬 | khuyển | biểu nghĩa | chó | 甲 | giáp | biểu âm | giáp, đứng đầu | 狎 = 犭(Khuyển, biểu nghĩa: chó) + 甲 (Giáp, biểu âm). Chữ hình thanh — bộ Khuyển liên quan đến hành vi gần gũi, thân mật như thú vật; phần Giáp cho âm xiá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiệp\" (狎): chó (犭) cứ quấn quýt mãi (甲 — đứng đầu, áp sát) — cợt nhả, thân mật quá trớn. | Gương Hán-Việt | hiệp — dùng trong \"hiệp nịnh\" (狎昵, thân mật quá mức), \"hiệp khách\" (狎客, khách làng chơi) | Mở khoá kiến thức | Biết 狎 mở khoá từ 狎昵 (thân mật quá trớn), 狎客 (khách phong lưu), 狎侮 (coi thường) trong văn ngôn.", "Tự nguyên_Xie": "Tiểu triện | 狎 là chữ hình thanh: bộ 犬/犭(Khuyển — chó) biểu ý sự gần gũi thân mật theo kiểu tự nhiên của loài vật; 甲 (Giáp) biểu âm xiá. Nghĩa gốc: quen thuộc, thân mật quá mức đến mức mất kính trọng. Sách Lễ Ký ghi: \"賢者狎而敬之\" — kẻ hiền nhân thân thiết mà vẫn giữ kính trọng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhờn, cợt nhả, đùa bỡn", "Hạng Tần Suất (Jun Da)": "5528.0", "Tần Suất % (Jun Da)": "99.9616364555", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 甲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭甲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狎", "Unihan_Traditional (Chữ Phồn thể)": "狎", "Pinyin_Xie": "xiá", "Âm Hán Việt_Xie": "hiệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ hành vi suồng sã, thiếu tôn trọng do quá thân quen. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闫', '{"9000": "5529.0", "Chữ Trung Quốc": "闫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 6 | nét | 闫 | diêm | tượng hình | họ Diêm; dạng giản của 閻 | 闫 là dạng chữ thảo rồi được chuẩn hóa giản thể từ 閻, vốn gồm 門 (Môn, cổng) và 臽/臾 biểu âm. Dạng giản thể 闫 chỉ có bộ 門 và chữ 丫 bên trong.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diêm\" (闫): cổng làng (門) dẫn vào xóm — họ Diêm, một trong những họ phổ biến ở Trung Quốc. | Gương Hán-Việt | diêm — dùng làm họ tên 闫 (Diêm), liên quan đến 阎王 (Diêm Vương, vua cõi âm phủ) | Mở khoá kiến thức | Biết 闫 mở khoá họ tên tiếng Trung (họ Yan/Diêm) và từ 阎王 (Diêm Vương) trong thần thoại.", "Tự nguyên_Xie": "闫 bắt nguồn từ chữ thảo (cursive script) của 閻, sau đó được chính thức hóa trong đợt giản hóa chữ Hán thứ hai. 閻 gốc có bộ 門 (Môn — cổng làng, khu xóm) và phần biểu âm. Nghĩa ban đầu: cổng vào làng, ngõ xóm. Ngày nay chủ yếu dùng làm họ tên (họ Diêm/Yan). Chữ tạo muộn dưới dạng giản thể hiện tại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "âm phủ, địa ngục", "Hạng Tần Suất (Jun Da)": "5529.0", "Tần Suất % (Jun Da)": "99.9616896844", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 三", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门三", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "三", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "闫", "Unihan_Traditional (Chữ Phồn thể)": "閆", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "diêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ họ người trong tiếng Trung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('滟', '{"9000": "5530.0", "Chữ Trung Quốc": "滟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 氵 | thủy | biểu nghĩa | nước | 豔 | diễm | biểu âm | rực rỡ, lộng lẫy | 滟 = 氵(Thủy, biểu nghĩa: nước) + 豔 (Diễm, biểu âm). Chữ hình thanh — bộ Thủy xác định liên quan đến nước; phần Diễm cho âm yàn. Dạng đầy đủ là 灩.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diễm\" (滟): nước (氵) rực rỡ diễm lệ (豔) — sóng lấp lánh tràn đầy. | Gương Hán-Việt | diễm — dùng trong \"liễm diễm\" (瀲滟/潋滟, sóng nước lấp lánh) | Mở khoá kiến thức | Biết 滟 mở khoá từ thơ văn 潋滟 (liễm diễm — sóng lấp lánh) trong thơ Tô Đông Pha và văn học cổ.", "Tự nguyên_Xie": "滟 (đầy đủ: 灩) là chữ hình thanh: bộ 氵(Thủy) biểu ý nước, 豔 (Diễm) biểu âm yàn. Nghĩa: nước tràn đầy, sóng sánh lấp lánh. Thường dùng trong 瀲灩 (liễm diễm) — sóng nước lấp lánh. Thơ Tô Đông Pha \"水光潋滟晴方好\" là câu thơ nổi tiếng dùng chữ này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước động, sóng sánh, chan chứa, tràn đầy", "Hạng Tần Suất (Jun Da)": "5530.0", "Tần Suất % (Jun Da)": "99.9617429133", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 艳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵艳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "艳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "滟", "Unihan_Traditional (Chữ Phồn thể)": "灩", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "diễm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả vẻ lấp lánh và dập dềnh của sóng nước. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('齑', '{"9000": "5531.0", "Chữ Trung Quốc": "齑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齊 | Số nét | 15 | nét | 齊 | tày | biểu âm | đều, ngay ngắn | 韭 | cửu | biểu nghĩa | hẹ, cây hành | 齑 = 齊 (Tày, biểu âm) + 韭 (Cửu, biểu nghĩa: hẹ). Chữ hình thanh — bộ Cửu (cây hẹ, thực vật ăn được) xác định đây là loại gia vị từ thực vật; phần Tày biểu âm jī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tê\" (齑): rau hẹ (韭) băm tề (齊) ra — đó là tê, gia vị rau băm nhỏ dùng trong ẩm thực cổ Trung Hoa. | Gương Hán-Việt | tê — dùng trong \"tê diêm\" (齑盐, muối rau dưa dân dã) | Mở khoá kiến thức | Biết 齑 mở khoá từ 齑盐 (tê diêm — cuộc sống đạm bạc) và các từ ẩm thực cổ về gia vị.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 齑 (dạng cổ 齏) gốc từ 𠬘, về sau trở thành chữ hình thanh với 齊 (Tày) biểu âm và 韭 (Cửu — hẹ) biểu nghĩa. Nghĩa: rau hẹ hay rau thơm băm nhỏ dùng làm gia vị; sau mở rộng sang gia vị nói chung. Cũng có nghĩa \"nghiền nát thành từng mảnh\". Dạng hình ảnh tìm thấy từ đại triện và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ gia vị", "Hạng Tần Suất (Jun Da)": "5531.0", "Tần Suất % (Jun Da)": "99.9617961421", "GavinGrover_Once (Chiết tự trực tiếp)": "文 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱文", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "齑", "Unihan_Traditional (Chữ Phồn thể)": "齏", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "tê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ các loại rau gia vị giã nhỏ hoặc tính từ chỉ sự tan nát. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遒', '{"9000": "5532.0", "Chữ Trung Quốc": "遒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 12 | nét | 遒 | tựu | tượng hình | cứng mạnh, khỏe khoắn; sắp hết | 遒 có bộ 辶(辵, Xước, biểu nghĩa: đi, di chuyển) và phần 酋 (Tù, biểu âm: thủ lĩnh, rượu lâu năm). Chữ hình thanh — bộ Xước gợi sự chuyển động, tiến tới; phần Tù biểu âm qiú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tựu\" (遒): bước tiến (辶) mạnh mẽ như thủ lĩnh (酋) — bút pháp tựu kiếm, cứng rắn, khỏe khoắn. | Gương Hán-Việt | tựu — dùng trong \"tựu kiếm\" (遒劲, bút pháp mạnh mẽ rắn chắc) | Mở khoá kiến thức | Biết 遒 mở khoá từ 遒劲 (tựu kiếm — bút pháp/văn phong mạnh khỏe) trong phê bình văn học nghệ thuật.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 遒 gồm bộ 辶(辵 — đi đường, vận động) và 酋 biểu âm qiú. Nghĩa gốc liên quan đến sự gần hết, gấp rút; phát triển sang nghĩa cứng mạnh, khỏe khoắn (đặc biệt khi nói về văn phong, bút pháp). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn; có hình trong tiểu triện (hanziyuan). Wiktionary không có phân tích cấu trúc rõ ràng. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cấp bách; sắp hết; họp lại; cứng, bền chắc", "Hạng Tần Suất (Jun Da)": "5532.0", "Tần Suất % (Jun Da)": "99.961849371", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 酋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶酋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "酋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "遒", "Unihan_Traditional (Chữ Phồn thể)": "遒", "Pinyin_Xie": "qiú", "Âm Hán Việt_Xie": "tù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho nét chữ, văn phong hoặc sức lực mạnh mẽ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磔', '{"9000": "5533.0", "Chữ Trung Quốc": "磔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 15 | nét | 磔 | kẹt | tượng hình | hình phanh thây; nét phảy trong thư pháp | 磔 có bộ 石 (Thạch, đá) và phần 桀 hoặc 庶 biểu âm. Bộ Thạch gợi tính chất cứng rắn, bất động; kết hợp với nghĩa hình phạt xe xé xác. Cấu trúc đầy đủ chưa được Wiktionary phân tích rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kẹt\" (磔): hình phạt kẹt cứng như đá (石) — phanh thây, xé xác; trong thư pháp là nét phảy mạnh xuống. | Gương Hán-Việt | kẹt — dùng trong \"kẹt hình\" (磔刑, hình phanh thây) | Mở khoá kiến thức | Biết 磔 mở khoá từ 磔刑 (kẹt hình — hình phạt phanh thây) trong sử học và thuật ngữ thư pháp.", "Tự nguyên_Xie": "Tiểu triện | 磔 (zhé, Hán-Việt: kẹt) là hình phạt phanh thây bằng xe ngựa kéo về nhiều hướng, một trong những hình phạt dã man nhất trong hình luật cổ đại Trung Hoa. Ngoài ra còn dùng trong thư pháp để chỉ nét phảy (捺) nghiêng xuống phải. Wiktionary có hình tiểu triện. Cấu trúc chi tiết chưa rõ; chưa có nguồn học thuật phân tích glyph-origin. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hình phanh thây; nét phảy", "Hạng Tần Suất (Jun Da)": "5533.0", "Tần Suất % (Jun Da)": "99.9619025999", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 桀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石桀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "桀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磔", "Unihan_Traditional (Chữ Phồn thể)": "磔", "Pinyin_Xie": "zhé", "Âm Hán Việt_Xie": "trách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ hình phạt phanh thây thời cổ đại hoặc động từ thực hiện hình phạt đó. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聃', '{"9000": "5534.0", "Chữ Trung Quốc": "聃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 11 | nét | 聃 | đam | tượng hình | tai to và dài; tên tự của Lão Tử | 聃 gồm bộ 耳 (Nhĩ, tai) và phần 冉 (Nhiễm, biểu âm: mềm mại, rủ xuống). Chữ hình thanh — bộ Nhĩ xác định liên quan đến tai; phần Nhiễm biểu âm dān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đam\" (聃): tai (耳) rủ xuống mềm mại (冉) — đó là đam, tên tự của Lão Tử vì đôi tai dài đặc biệt. | Gương Hán-Việt | đam — dùng trong \"Lão Đam\" (老聃, tên tự của Lão Tử) | Mở khoá kiến thức | Biết 聃 mở khoá tên tự 老聃 (Lão Đam) của Lão Tử và vốn từ về tướng mạo trong văn hóa cổ Trung Hoa.", "Tự nguyên_Xie": "Lục thư thông | 聃 vốn viết là 耼, gồm 耳 (Nhĩ — tai) và 冉 (Nhiễm — rủ xuống, buông thõng). Nghĩa: tai to và dài, rủ xuống. Đây là tên tự (字) của Lão Tử — Lão Đam (老聃), vì tương truyền Lão Tử có đôi tai rất dài. Chữ chủ yếu dùng trong danh hiệu 老聃. Hình ảnh lưu thư thông (hanziyuan) cho thấy dạng tiến hóa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mê mải, đắm đuối", "Hạng Tần Suất (Jun Da)": "5534.0", "Tần Suất % (Jun Da)": "99.9619558287", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 冉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳冉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聃", "Unihan_Traditional (Chữ Phồn thể)": "聃", "Pinyin_Xie": "dān", "Âm Hán Việt_Xie": "đam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ riêng chỉ Lão Tử hoặc tính từ tả tai to xệ xuống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('綦', '{"9000": "5535.0", "Chữ Trung Quốc": "綦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 14 | nét | 綦 | kỳ | tượng hình | màu xám đậm; rất, cực kỳ; họ Kỳ | 綦 có bộ 糸 (Mịch, sợi tơ, biểu nghĩa: vải vóc, màu sắc) và phần 其 (Kỳ) ở trên biểu âm. Chữ hình thanh — bộ Mịch liên quan đến vải/sợi và màu sắc; phần biểu âm qí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\" (綦): sợi tơ (糸) màu xám kỳ lạ — 綦 còn có nghĩa \"rất, cực kỳ\" trong văn ngôn. | Gương Hán-Việt | kỳ — dùng trong \"kỳ trọng\" (綦重, cực kỳ nặng) và họ tên người | Mở khoá kiến thức | Biết 綦 mở khoá cách dùng trạng từ văn ngôn \"kỳ\" (rất, cực kỳ) và hiểu về màu sắc vải cổ đại.", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | 綦 chứa bộ 糸 (Mịch — sợi tơ, vải) ở dưới và 其 (Kỳ) biểu âm. Nghĩa gốc: màu xám đen của vải; phát triển sang nghĩa trạng từ \"rất, cực kỳ\" (như 綦重 — hết sức nặng nề). Wiktionary chỉ ghi nhận phát âm mà không phân tích cấu trúc rõ. Có hình ảnh từ kim văn, đại triện và tiểu triện. Chưa có nguồn học thuật rõ ràng về glyph-origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rất; cực; họ Kỳ", "Hạng Tần Suất (Jun Da)": "5535.0", "Tần Suất % (Jun Da)": "99.9620090576", "GavinGrover_Once (Chiết tự trực tiếp)": "其 + 糸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱其糸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "其", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糸", "Unihan_Simplified (Chữ Giản thể)": "綦", "Unihan_Traditional (Chữ Phồn thể)": "綦", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Tính từ | 形容词 | Danh từ | 名词 | Trong văn ngôn thường dùng làm phó từ đứng trước tính từ để biểu thị mức độ cực kỳ. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲡', '{"9000": "5536.0", "Chữ Trung Quốc": "鲡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 15 | nét | 鲡 | ly | tượng hình | cá chình (lươn biển) | 鲡 là dạng giản thể của 鱺, gồm 魚/鱼 (Ngư, biểu nghĩa: cá) và 麗/丽 (Lệ, biểu âm). Chữ hình thanh — bộ Ngư xác định loài cá; phần Lệ biểu âm lí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ly\" (鲡): cá (鱼) ly kỳ trơn như lươn — đó là ly, trong tên cá chình 鳗鲡. | Gương Hán-Việt | ly — dùng trong \"mạn ly\" (鳗鲡, cá chình biển/lươn biển) | Mở khoá kiến thức | Biết 鲡 mở khoá từ 鳗鲡 (mạn ly — cá chình) và tên các loài cá đặc biệt trong tiếng Trung.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 鲡 (dạng đầy đủ 鱺) là chữ hình thanh: 魚 (Ngư) biểu ý loài cá, 麗 (Lệ) biểu âm lí. Chủ yếu dùng trong từ 鳗鲡/鰻鱺 (mạn ly — cá chình biển, lươn biển). Loài cá này nổi tiếng trong ẩm thực Nhật Bản (unagi). Wiktionary chỉ ghi {{Han etym}} mà không có glyph-origin chi tiết; có hình ảnh từ tiểu triện và lưu thư thông (hanziyuan). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: man ly 鰻鱺,鳗鲡)", "Hạng Tần Suất (Jun Da)": "5536.0", "Tần Suất % (Jun Da)": "99.9620622865", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 丽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼丽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲡", "Unihan_Traditional (Chữ Phồn thể)": "鱺", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "li", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ man tạo thành danh từ ghép chỉ loài cá chình. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔻', '{"9000": "5537.0", "Chữ Trung Quốc": "蔻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 艹 | thảo | biểu nghĩa | cỏ cây | 寇 | khấu | biểu âm | giặc, kẻ thù | 蔻 = 艹 (Thảo, biểu nghĩa: cỏ cây) + 寇 (Khấu, biểu âm). Chữ hình thanh — bộ Thảo xác định đây là loài thực vật; phần Khấu cho âm kòu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khấu\" (蔻): cây cỏ (艹) tên là khấu (寇) — đậu khấu, loài gia vị quý và biểu tượng tuổi thiếu nữ. | Gương Hán-Việt | khấu — dùng trong \"đậu khấu\" (豆蔻, cardamom) và \"nhục đậu khấu\" (肉豆蔻, nutmeg) | Mở khoá kiến thức | Biết 蔻 mở khoá từ 豆蔻年华 (tuổi đậu khấu — tuổi thiếu nữ 13-14) và các gia vị quý trong ẩm thực Trung Hoa.", "Tự nguyên_Xie": "蔻 là chữ hình thanh: bộ 艹(Thảo — cỏ cây) biểu ý thực vật, 寇 (Khấu) biểu âm kòu. Chủ yếu dùng trong từ 豆蔻 (đậu khấu — cardamom) và 肉豆蔻 (nhục đậu khấu — nutmeg). 豆蔻年华 (tuổi đậu khấu) là thành ngữ chỉ tuổi thiếu nữ 13-14 tuổi, lấy từ thơ Đỗ Mục. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đậu khấu 荳蔻,豆蔻)", "Hạng Tần Suất (Jun Da)": "5537.0", "Tần Suất % (Jun Da)": "99.9621149986", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 寇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹寇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔻", "Unihan_Traditional (Chữ Phồn thể)": "蔻", "Pinyin_Xie": "kòu", "Âm Hán Việt_Xie": "khấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ đậu tạo thành danh từ chỉ cây thảo dược đậu khấu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泠', '{"9000": "5538.0", "Chữ Trung Quốc": "泠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 泠 | lênh | tượng hình | mát lạnh, trong trẻo; tiếng nước chảy | 泠 gồm bộ 氵(Thủy, biểu nghĩa: nước) và 令 (Lệnh, biểu âm). Chữ hình thanh — bộ Thủy xác định liên quan đến nước; phần Lệnh biểu âm líng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lênh\" (泠): nước (氵) mát theo lệnh (令) tự nhiên — 泠泠, tiếng nước lênh lênh trong trẻo. | Gương Hán-Việt | lênh — dùng trong \"lênh lênh\" (泠泠, tiếng nước réo trong) và \"Tây Lênh\" (西泠, địa danh ở Hàng Châu) | Mở khoá kiến thức | Biết 泠 mở khoá từ 泠泠 (tiếng nước trong trẻo), 西泠印社 (Tây Lênh Ấn Xã — hội thư pháp nổi tiếng Trung Quốc).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 泠 gồm 氵(Thủy — nước) và 令 (Lệnh) biểu âm líng. Nghĩa: mát lạnh, dễ chịu (như gió mát, nước trong); tiếng nước chảy réo rắt. Dùng trong 泠泠 (lênh lênh — tiếng nước réo) và 泠然 (lênh nhiên — nhẹ nhàng, thoải mái). Wiktionary không phân tích glyph-origin chi tiết nhưng có hình ảnh đại triện và tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tiếng nước chảy)", "Hạng Tần Suất (Jun Da)": "5538.0", "Tần Suất % (Jun Da)": "99.9621677106", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 令", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵令", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泠", "Unihan_Traditional (Chữ Phồn thể)": "泠", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Từ tượng thanh | 象声词 | Thường dùng làm tính từ miêu tả gió mát, nước trong hoặc âm thanh thanh tao. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砗', '{"9000": "5539.0", "Chữ Trung Quốc": "砗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 9 | nét | 砗 | xa | tượng hình | trai khổng lồ (砗磲) | 砗 gồm bộ 石 (Thạch, biểu nghĩa: đá, vật cứng) và 车 (Xa, biểu âm: xe). Chữ hình thanh — bộ Thạch gợi tính chất cứng rắn như đá; phần Xa biểu âm chē.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xa\" (砗): vật cứng như đá (石) to như xe (车) — đó là xa cừ, loài trai khổng lồ. | Gương Hán-Việt | xa — dùng trong \"xa cừ\" (砗磲, trai khổng lồ) là một trong Thất bảo Phật giáo | Mở khoá kiến thức | Biết 砗 mở khoá từ 砗磲 (xa cừ — Tridacna gigas, trai khổng lồ Phật giáo) và vốn từ về đồ quý trong Phật giáo.", "Tự nguyên_Xie": "砗 (dạng đầy đủ 硨) là chữ hình thanh: bộ 石 (Thạch) gợi chất liệu cứng; 车/車 biểu âm chē. Chỉ dùng trong từ 砗磲 (xa cừ — giant clam, loài trai khổng lồ quý hiếm). Vỏ trai 砗磲 trong Phật giáo là một trong Thất bảo. Wiktionary ghi nhận chỉ dùng trong 硨磲 (dạng đầy đủ). Chưa có nguồn học thuật về glyph-origin chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: xa cừ 硨磲,砗磲)", "Hạng Tần Suất (Jun Da)": "5539.0", "Tần Suất % (Jun Da)": "99.9622204227", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 车", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石车", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "车", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砗", "Unihan_Traditional (Chữ Phồn thể)": "硨", "Pinyin_Xie": "chē", "Âm Hán Việt_Xie": "xa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường đi kèm với chữ cừ tạo thành danh từ chỉ loài sò tai tượng hoặc chất liệu ngọc xa cừ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钕', '{"9000": "5540.0", "Chữ Trung Quốc": "钕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 8 | nét | 金 | kim | biểu nghĩa | kim loại | 女 | nữ | biểu âm | phụ nữ | 钕 = 钅(Kim, biểu nghĩa: kim loại) + 女 (Nữ, biểu âm). Chữ hình thanh — bộ Kim xác định đây là kim loại; phần Nữ biểu âm nǚ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nữ\" (钕): kim loại (钅) mang tên nữ (女) — nguyên tố neodi, không phải nặng mà quý như ngọc nữ trong công nghệ cao. | Gương Hán-Việt | nữ — dùng trong \"nữ kim\" (钕, ký hiệu Nd) — nguyên tố neodymium | Mở khoá kiến thức | Biết 钕 mở khoá hệ thống đặt tên nguyên tố hóa học trong tiếng Trung: bộ 钅+ ký tự biểu âm.", "Tự nguyên_Xie": "钕 (dạng đầy đủ 釹) là chữ hình thanh tạo ra để phiên âm tên nguyên tố neodymium (Nd): bộ 金 (Kim — kim loại) biểu ý nguyên tố hóa học thuộc nhóm kim loại; 女 (Nữ) biểu âm nǚ — âm gần với \"neo\" trong neodymium. Neodymium (neodi, Nd) là nguyên tố đất hiếm, quan trọng trong sản xuất nam châm mạnh (NdFeB) dùng trong thiết bị điện tử. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố neodi, Nd", "Hạng Tần Suất (Jun Da)": "5540.0", "Tần Suất % (Jun Da)": "99.9622731348", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 女", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "女", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钕", "Unihan_Traditional (Chữ Phồn thể)": "釹", "Pinyin_Xie": "nǚ", "Âm Hán Việt_Xie": "nục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong hóa học để chỉ nguyên tố kim loại đất hiếm Neodymi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镫', '{"9000": "5541.0", "Chữ Trung Quốc": "镫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 镫 | đăng | tượng hình | bàn đạp ngựa; đồ thắp đèn | 镫 (dạng đầy đủ 鐙) gồm bộ 钅(Kim, biểu nghĩa: kim loại) và 登 (Đăng, biểu âm: lên, trèo lên). Chữ hình thanh — bộ Kim xác định vật bằng kim loại; phần Đăng biểu âm dèng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đăng\" (镫): vật kim loại (钅) dùng để leo lên (登) — bàn đạp ngựa, phát minh giúp kỵ binh chiến đấu hiệu quả. | Gương Hán-Việt | đăng — dùng trong \"mã đăng\" (马镫, bàn đạp ngựa) và \"đăng long\" (镫笼, hộp đèn) | Mở khoá kiến thức | Biết 镫 mở khoá từ 马镫 (mã đăng — bàn đạp ngựa, phát minh thay đổi lịch sử chiến tranh).", "Tự nguyên_Xie": "Tiểu triện | 镫 (鐙) là chữ hình thanh: bộ 金/钅(Kim — kim loại) biểu ý đồ vật bằng kim loại; 登 (Đăng) biểu âm dèng. Nghĩa gốc: đồ dùng để cúng tế (đồ đựng, giá đỡ bằng kim loại). Nghĩa hiện đại: bàn đạp ngựa (馬鐙/马镫 — mã đăng), phát minh quan trọng trong lịch sử quân sự. Wiktionary có hình tiểu triện (hanziyuan). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ đựng các đồ cúng", "Hạng Tần Suất (Jun Da)": "5541.0", "Tần Suất % (Jun Da)": "99.9623258469", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 登", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅登", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "登", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镫", "Unihan_Traditional (Chữ Phồn thể)": "鐙", "Pinyin_Xie": "dèng", "Âm Hán Việt_Xie": "đăng, đặng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ chỉ bàn đạp của yên ngựa hoặc chân để đèn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菹', '{"9000": "5542.0", "Chữ Trung Quốc": "菹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菹 | thư | tượng hình | dưa muối, rau muối; đầm lầy | 菹 gồm bộ 艹 (Thảo, biểu nghĩa: cỏ cây, rau) và 俎 (Trở, biểu âm: bàn thờ). Chữ hình thanh — bộ Thảo xác định liên quan đến thực vật; phần biểu âm jū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thư\" (菹): rau cỏ (艹) ngâm muối — dưa muối nguyên cây; cũng là hình phạt dã man băm xương thịt. | Gương Hán-Việt | thư — dùng trong \"thư hải\" (菹醢, hình phạt băm xương thịt thời cổ) | Mở khoá kiến thức | Biết 菹 mở khoá từ 菹醢 (thư hải — hình phạt cổ đại) và hiểu cách bảo quản thực phẩm trong văn hóa cổ Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 菹 gồm 艹(Thảo — cỏ/rau) và phần còn lại biểu âm jū. Nghĩa: rau cải muối nguyên cây; đầm lầy, bãi lầy. Ngoài ra còn có nghĩa hình phạt cổ đại: băm xương thịt (菹醢 — thư hải: hình phạt băm nhỏ). Wiktionary ghi nhận trong 菹醢 (jūhǎi). Hình ảnh từ tiểu triện và lưu thư thông (hanziyuan). Chưa có glyph-origin chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dưa muối cả cây; hình phạt bằm xương thịt", "Hạng Tần Suất (Jun Da)": "5542.0", "Tần Suất % (Jun Da)": "99.9623780422", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 沮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹沮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "沮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菹", "Unihan_Traditional (Chữ Phồn thể)": "菹", "Pinyin_Xie": "jū", "Âm Hán Việt_Xie": "trư, thư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này chủ yếu làm danh từ chỉ các loại rau muối hoặc vùng đất đầm lầy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胂', '{"9000": "5543.0", "Chữ Trung Quốc": "胂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 9 | nét | 胂 | thăn | tượng hình | hợp chất arsine (AsH₃) | 胂 gồm bộ 月/肉 (Nhục, biểu nghĩa: thịt, cơ thể) và 申 (Thân, biểu âm). Chữ hình thanh dùng để phiên âm tên hóa chất — bộ Nhục/Nguyệt gợi liên quan đến sinh học; phần Thân biểu âm shèn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thăn\" (胂): bộ Nhục (月) + Thân (申) — chữ kỹ thuật chỉ hợp chất arsine (AsH₃), khí độc trong hóa học. | Gương Hán-Việt | thăn — thuật ngữ hóa học, chưa dùng trong từ Hán-Việt thông thường | Mở khoá kiến thức | Biết 胂 giúp đọc tên hóa chất gốc asen trong tài liệu hóa học tiếng Trung.", "Tự nguyên_Xie": "Tiểu triện | 胂 là chữ hình thanh dùng để phiên âm tên hóa học arsine (AsH₃ — khí arsine, hợp chất của asen và hydro). Bộ 月/肉 (Nhục) gợi tính độc hại đến cơ thể; 申 (Thân) biểu âm shèn. Đây là chữ tạo ra trong thời hiện đại để biểu diễn tên nguyên tố/hợp chất hóa học. Wiktionary không có glyph-origin; có hình tiểu triện (hanziyuan). Chưa có nguồn học thuật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hợp chất a-sin", "Hạng Tần Suất (Jun Da)": "5543.0", "Tần Suất % (Jun Da)": "99.9624302375", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 申", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月申", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "申", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胂", "Unihan_Traditional (Chữ Phồn thể)": "胂", "Pinyin_Xie": "shèn", "Âm Hán Việt_Xie": "thân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chuyên ngành hóa học để gọi tên hợp chất hữu cơ arsine. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('煅', '{"9000": "5544.0", "Chữ Trung Quốc": "煅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 13 | nét | 煅 | đoán | tượng hình | nung luyện kim loại | 煅 gồm bộ 火 (Hỏa, biểu nghĩa: lửa) và 段 (Đoạn, biểu âm). Chữ hình thanh — bộ Hỏa xác định liên quan đến nhiệt; phần Đoạn biểu âm duàn. Biến thể/liên quan với 锻 (rèn đúc).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đoán\" (煅): lửa (火) rèn đúc mạnh mẽ (段) — nung, đốt luyện kim loại hay dược liệu. | Gương Hán-Việt | đoán — dùng trong \"đoán thiêu\" (煅烧, nung luyện) và thuật ngữ y học cổ truyền | Mở khoá kiến thức | Biết 煅 mở khoá thuật ngữ y học cổ truyền Trung Hoa về cách chế biến dược liệu bằng lửa.", "Tự nguyên_Xie": "煅 gồm 火 (Hỏa — lửa) và 段 (Đoạn) biểu âm duàn. Nghĩa: nung luyện kim loại bằng lửa, đốt nóng để thay đổi tính chất. Dùng trong thuật ngữ y học cổ truyền Trung Hoa: 煅烧 (đoán thiêu — nung cháy), 煅石灰 (đoán thạch khôi — nung vôi). Wiktionary không có glyph-origin; chữ tạo muộn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nung, nướng", "Hạng Tần Suất (Jun Da)": "5544.0", "Tần Suất % (Jun Da)": "99.9624824328", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 段", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火段", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "段", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "煅", "Unihan_Traditional (Chữ Phồn thể)": "煅", "Pinyin_Xie": "duàn", "Âm Hán Việt_Xie": "đoán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ việc nung nóng khoáng vật hoặc kim loại ở nhiệt độ cao. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('煸', '{"9000": "5545.0", "Chữ Trung Quốc": "煸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 13 | nét | 煸 | biên | tượng hình | xào sơ, đảo nhanh trên lửa lớn | 煸 gồm bộ 火 (Hỏa, biểu nghĩa: lửa) và 扁 (Biển, biểu âm). Chữ hình thanh — bộ Hỏa xác định liên quan đến nấu bằng lửa; phần Biển biểu âm biān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biên\" (煸): lửa (火) nhanh dẹt (扁) — xào biên, đảo nhanh trên lửa lớn trước khi nấu. | Gương Hán-Việt | biên — dùng trong \"can biên\" (干煸, xào khô) — kỹ thuật nấu ăn Tứ Xuyên | Mở khoá kiến thức | Biết 煸 mở khoá thuật ngữ ẩm thực Trung Hoa: 干煸 (xào khô), kỹ thuật làm bay hơi nước trước khi nêm nếm.", "Tự nguyên_Xie": "煸 gồm 火 (Hỏa — lửa) và 扁 (Biển) biểu âm biān. Nghĩa: xào sơ nguyên liệu trên chảo lửa lớn trước khi nấu tiếp. Đây là kỹ thuật nấu ăn (干煸 — can biên, xào khô) rất phổ biến trong ẩm thực Tứ Xuyên. Wiktionary không có glyph-origin; chữ tạo muộn trong ngữ cảnh ẩm thực. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xào qua trước khi nấu", "Hạng Tần Suất (Jun Da)": "5545.0", "Tần Suất % (Jun Da)": "99.9625346281", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 扁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火扁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "扁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "煸", "Unihan_Traditional (Chữ Phồn thể)": "煸", "Pinyin_Xie": "biān", "Âm Hán Việt_Xie": "biên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ phương pháp nấu ăn xào sơ thức ăn trong chảo nóng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螯', '{"9000": "5546.0", "Chữ Trung Quốc": "螯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 敖 | ngào | biểu âm | ngạo nghễ, đi chơi | 虫 | trùng | biểu nghĩa | sâu bọ, côn trùng | 螯 = 敖 (Ngào, biểu âm) + 虫 (Trùng, biểu nghĩa: sâu bọ). Chữ hình thanh — bộ Trùng xác định liên quan đến côn trùng/giáp xác; phần Ngào cho âm áo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngao\" (螯): trùng (虫) ngào nghễ (敖) kẹp chặt — đó là ngao, càng cua kẹp mạnh. | Gương Hán-Việt | ngao — dùng trong \"trì ngao\" (持螯, cầm càng cua) và thành ngữ về thú vui uống rượu | Mở khoá kiến thức | Biết 螯 mở khoá từ 蟹螯 (cua ngao — càng cua), 持螯把酒 (thú ẩm thực thanh nhàn).", "Tự nguyên_Xie": "螯 là chữ hình thanh: bộ 虫 (Trùng — sâu bọ, giáp xác) biểu ý bộ phận của sinh vật; 敖 (Ngào) biểu âm áo. Nghĩa: càng cua, kẹp của tôm cua. Sách Tuân Tử: \"蟹六跪而二螯\" (cua sáu chân hai càng). Thành ngữ 持螯把酒 (trì ngào bả tửu — cầm càng cua uống rượu) ví thú vui thanh nhàn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con rùa biển", "Hạng Tần Suất (Jun Da)": "5546.0", "Tần Suất % (Jun Da)": "99.9625868234", "GavinGrover_Once (Chiết tự trực tiếp)": "敖 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敖虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螯", "Unihan_Traditional (Chữ Phồn thể)": "螯", "Pinyin_Xie": "áo", "Âm Hán Việt_Xie": "ngao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận càng của các loài giáp xác như cua hay tôm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躅', '{"9000": "5547.0", "Chữ Trung Quốc": "躅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 20 | nét | 足 | túc | biểu nghĩa | chân | 蜀 | thục | biểu âm | nước Thục, tằm | 躅 = 足 (Túc, biểu nghĩa: chân) + 蜀 (Thục, biểu âm). Chữ hình thanh — bộ Túc xác định liên quan đến bước chân, đi lại; phần Thục biểu âm zhú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sộc\" (躅): chân (足) do dự như vua Thục (蜀) chưa quyết — đó là sộc, dẫm chân nao núng. | Gương Hán-Việt | sộc — dùng trong \"trực trọc\" (踯躅, do dự nao núng) | Mở khoá kiến thức | Biết 躅 mở khoá từ 踯躅 (do dự, dẫm chân tại chỗ) trong thơ văn cổ điển Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 躅 là chữ hình thanh: bộ 足 (Túc — chân) biểu ý liên quan đến bước chân; 蜀 (Thục) biểu âm zhú. Nghĩa: bước chân do dự, dẫm chân tại chỗ; vết chân để lại. Từ 踯躅 (trực trọc — do dự, nao núng) là cụm dùng phổ biến nhất. Hình ảnh tiểu triện từ Wikimedia. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nao núng, do dự; vết chân", "Hạng Tần Suất (Jun Da)": "5547.0", "Tần Suất % (Jun Da)": "99.9626390187", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 蜀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊蜀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蜀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "躅", "Unihan_Traditional (Chữ Phồn thể)": "躅", "Pinyin_Xie": "zhú", "Âm Hán Việt_Xie": "trục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ hành động đi lại ngập ngừng hoặc dậm chân tại chỗ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲠', '{"9000": "5548.0", "Chữ Trung Quốc": "鲠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 15 | nét | 鲠 | ngạnh | tượng hình | xương cá; hóc xương; người ngay thẳng | 鲠 (dạng đầy đủ 鯁) gồm bộ 鱼 (Ngư, biểu nghĩa: cá) và 更 (Canh, biểu âm). Chữ hình thanh — bộ Ngư xác định liên quan đến cá; phần Canh biểu âm gěng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạnh\" (鲠): cá (鱼) cứng (更) ngạnh — xương cá mắc họng; ví người cứng cỏi thẳng thắn. | Gương Hán-Việt | ngạnh — dùng trong \"như ngạnh tại hầu\" (如鲠在喉, như xương mắc họng — điều muốn nói không thể nín) | Mở khoá kiến thức | Biết 鲠 mở khoá thành ngữ 如鲠在喉 và 骨鲠之臣 (vị thần thẳng thắn dám can gián).", "Tự nguyên_Xie": "Tiểu triện | 鲠 (鯁) là chữ hình thanh: 魚/鱼 (Ngư) biểu ý liên quan đến cá, 更 (Canh) biểu âm gěng. Nghĩa gốc: xương cá; nghĩa mở rộng: bị hóc xương cá; hình ảnh ẩn dụ: người thẳng thắn, cứng cỏi không nịnh hót (骨鲠之臣 — thần bốc trực). Thành ngữ 如鲠在喉 (như xương mắc họng — điều nói không ra không được) rất phổ biến. Tiếng Lào ກ້າງ và tiếng Thái ก้าง vay mượn từ chữ này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xương cá; hóc xương; người ngay thẳng không nịnh nọt", "Hạng Tần Suất (Jun Da)": "5548.0", "Tần Suất % (Jun Da)": "99.962691214", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 更", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼更", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "更", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲠", "Unihan_Traditional (Chữ Phồn thể)": "骾", "Pinyin_Xie": "gěng", "Âm Hán Việt_Xie": "ngạnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ việc bị hóc xương hoặc tính từ chỉ tính cách cương trực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佥', '{"9000": "5549.0", "Chữ Trung Quốc": "佥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 7 | nét | 亼 | tập | biểu nghĩa | tụ tập, hội tụ | 兄 | huynh | biểu nghĩa | anh, người trên | 佥 (dạng cổ 僉) = 亼 (Tập, hội tụ) + 兄 (Huynh, anh) viết đôi. Chữ hội ý — người ta hội tụ lại cùng trả lời, cùng nói một lời. Từ tiểu triện, cả chữ được viết lại thành 亼 + 吅 + 从.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiêm\" (佥): mọi người (兄×2) cùng tụ hội (亼) đồng lòng nói — đó là thiêm, tất cả đều nhất trí. | Gương Hán-Việt | thiêm — dùng trong \"thiêm sự\" (佥事, chức quan thời phong kiến), \"thiêm đồng\" (佥同, đồng thuận) | Mở khoá kiến thức | Biết 佥 mở khoá chức quan 佥事 (thiêm sự) trong sử Minh-Thanh và từ văn ngôn chỉ sự đồng thuận.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 佥 (僉) vốn là 亼 (Tập — tụ hội) và 兄 (Huynh — người trên) viết đôi, biểu thị nhiều người cùng đáp lại tiếng gọi, cùng nói một điều — nghĩa là \"tất cả, đồng lòng\". Từ tiểu triện được viết lại thành 亼 + 吅 (hai miệng nói) + 从 (hai người). Nghĩa: tất cả, cùng nhau, đồng lòng. Chữ văn ngôn cổ, ít dùng trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đều, cùng", "Hạng Tần Suất (Jun Da)": "5549.0", "Tần Suất % (Jun Da)": "99.9627434093", "GavinGrover_Once (Chiết tự trực tiếp)": "亼 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "佥", "Unihan_Traditional (Chữ Phồn thể)": "僉", "Pinyin_Xie": "qiān", "Âm Hán Việt_Xie": "thiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Đại từ | 代词 | Chữ này làm phó từ đứng trước động từ để biểu thị hành động chung của tập thể. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罘', '{"9000": "5550.0", "Chữ Trung Quốc": "罘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 9 | nét | 罘 | phù | tượng hình | lưới bẫy thỏ; bình phong che chắn | 罘 gồm bộ 网/罓 (Võng, biểu nghĩa: lưới) và 不 (Bất, biểu âm). Chữ hình thanh — bộ Võng xác định liên quan đến vật dùng lưới; phần Bất biểu âm fú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phù\" (罘): lưới (网) không (不) cho thoát — đó là phù, lưới bẫy thỏ. | Gương Hán-Việt | phù — dùng trong \"Chỉ Phù\" (芝罘, tên địa danh ở Sơn Đông) và \"phù ti\" (罘罳, bình phong lưới) | Mở khoá kiến thức | Biết 罘 mở khoá địa danh 芝罘 (Chỉ Phù — mũi đất ở Yên Đài, Sơn Đông) và từ liên quan đến săn bắn cổ đại.", "Tự nguyên_Xie": "罘 gồm 网 (Võng — lưới) và 不 (Bất) biểu âm fú. Nghĩa: lưới bẫy thỏ và động vật nhỏ. Ngoài ra còn có nghĩa 罘罳 (phù ti — loại bình phong lưới ở cổng cung đình). Wiktionary ghi nhận nghĩa và phát âm nhưng không có glyph-origin chi tiết. Chưa có nguồn học thuật về cấu trúc chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái lưới săn thỏ", "Hạng Tần Suất (Jun Da)": "5550.0", "Tần Suất % (Jun Da)": "99.9627956046", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + 不", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒不", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "不", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "罘", "Unihan_Traditional (Chữ Phồn thể)": "罘", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại lưới dùng để bẫy thỏ hoặc thú nhỏ thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嶝', '{"9000": "5551.0", "Chữ Trung Quốc": "嶝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 15 | nét | 山 | sơn | biểu nghĩa | núi | 登 | đăng | biểu âm | leo lên, bước lên | 嶝 = 山 (Sơn, biểu nghĩa: núi) + 登 (Đăng, biểu âm). Chữ hình thanh — bộ Sơn xác định liên quan đến địa hình núi; phần Đăng biểu âm dèng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đằng\" (嶝): núi (山) leo lên (登) — đường nhỏ dốc leo sườn núi. | Gương Hán-Việt | đằng — dùng trong \"đại đằng\" (大嶝, tên đảo gần Hạ Môn) | Mở khoá kiến thức | Biết 嶝 mở khoá địa danh 大嶝岛 (đảo Đại Đăng/Đại Đằng) và từ liên quan đến đường núi trong văn học cổ.", "Tự nguyên_Xie": "嶝 là chữ hình thanh: bộ 山 (Sơn — núi) biểu ý địa hình; 登 (Đăng — leo lên) biểu âm dèng. Nghĩa: đường nhỏ men theo sườn núi để đi lên. Cũng là thành phần trong địa danh như 大嶝 (Đại Đăng) và 小嶝 (Tiểu Đăng) — hai đảo nhỏ gần Hạ Môn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đường nhỏ đi trên núi", "Hạng Tần Suất (Jun Da)": "5551.0", "Tần Suất % (Jun Da)": "99.9628477999", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 登", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山登", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "登", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "嶝", "Unihan_Traditional (Chữ Phồn thể)": "嶝", "Pinyin_Xie": "dèng", "Âm Hán Việt_Xie": "đặng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ lối đi nhỏ và dốc trên sườn núi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坨', '{"9000": "5552.0", "Chữ Trung Quốc": "坨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 8 | nét | 坨 | đà | tượng hình | đống, tảng, cục (đất hoặc vật gì đó kết thành khối) | 坨 gồm bộ 土 (Thổ, biểu nghĩa: đất) và 它 (Tha, biểu âm: nó, kia). Chữ hình thanh — bộ Thổ xác định liên quan đến đất, địa hình; phần Tha biểu âm tuó.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đà\" (坨): đất (土) vón lại thành khối tha lôi — một cục, một đống bùn đất. | Gương Hán-Việt | đà — từ khẩu ngữ, chưa thông dụng trong từ Hán-Việt tiếng Việt | Mở khoá kiến thức | Biết 坨 giúp đọc hiểu khẩu ngữ tiếng Trung: 一坨 (một đống/cục) — từ đo lường không chính thức.", "Tự nguyên_Xie": "坨 gồm 土 (Thổ — đất) và 它 (Tha) biểu âm tuó. Nghĩa: cục đất, đống, tảng (vật gì đó vón lại thành khối). Wiktionary không có glyph-origin; chữ tạo muộn. Dùng phổ biến trong khẩu ngữ miền Bắc Trung Quốc: 一坨泥 (một đống bùn), 一坨肉 (một tảng thịt). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đống, tảng, gò; đóng thành tảng", "Hạng Tần Suất (Jun Da)": "5552.0", "Tần Suất % (Jun Da)": "99.9629516737", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 它", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土它", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "它", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坨", "Unihan_Traditional (Chữ Phồn thể)": "坨", "Pinyin_Xie": "tuó", "Âm Hán Việt_Xie": "đà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này thường dùng làm danh từ chỉ đống đất hoặc làm lượng từ cho các vật có hình khối, tảng, cục. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菽', '{"9000": "5553.0", "Chữ Trung Quốc": "菽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艹 | thảo | biểu nghĩa | cỏ cây | 叔 | thúc | biểu âm | chú, nhặt hạt | 菽 = 艹 (Thảo, biểu nghĩa: cỏ cây) + 叔 (Thúc, biểu âm). Chữ hình thanh — bộ Thảo xác định đây là loài thực vật; phần Thúc biểu âm shū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thúc\" (菽): cây cỏ (艹) chú thúc (叔) hái về — đó là thúc, đậu đỗ nói chung. | Gương Hán-Việt | thúc — dùng trong \"thúc túc\" (菽粟, đậu và gạo — nhu yếu phẩm) | Mở khoá kiến thức | Biết 菽 mở khoá từ 菽粟 (thúc túc — đậu lúa, nhu yếu phẩm) và hiểu vai trò của đậu trong nông nghiệp cổ đại Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 菽 là chữ hình thanh: bộ 艹(Thảo — cỏ, thực vật) biểu ý loài cây; 叔 (Thúc) biểu âm shū. Nghĩa: đậu, tổng gọi các loại đỗ/đậu. Trong văn học cổ, \"菽\" là tên gọi chung cho đậu nành và các loại đậu. Thành ngữ \"不知稼穑艰难，不知菽粟\" (không biết nhọc nhằn trồng cấy, không biết đậu lúa) nói về người thiếu thực tế. Hình tiểu triện từ Wikimedia. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây đỗ, cây đậu", "Hạng Tần Suất (Jun Da)": "5553.0", "Tần Suất % (Jun Da)": "99.9630033522", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 叔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹叔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菽", "Unihan_Traditional (Chữ Phồn thể)": "菽", "Pinyin_Xie": "shū", "Âm Hán Việt_Xie": "thục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ trong văn ngôn để chỉ chung các loại cây họ đậu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哞', '{"9000": "5554.0", "Chữ Trung Quốc": "哞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 哞 | mâu | tượng hình | tiếng bò rống (moo) | 哞 gồm bộ 口 (Khẩu, biểu nghĩa: miệng, âm thanh) và 牟 (Mâu, biểu âm). Chữ hình thanh — bộ Khẩu xác định đây là âm thanh; phần Mâu biểu âm mōu. Chữ phỏng âm (onomatopoeia) chỉ tiếng bò.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mâu\" (哞): miệng (口) phát âm mâu mâu — tiếng bò rống, gần với \"moo\" trong tiếng Anh. | Gương Hán-Việt | mâu — chủ yếu dùng trong văn học thiếu nhi và truyện tranh khi mô tả tiếng bò | Mở khoá kiến thức | Biết 哞 giúp đọc văn miêu tả âm thanh (phỏng âm) trong tiếng Trung — tương tự 汪汪 (tiếng chó), 喵喵 (tiếng mèo).", "Tự nguyên_Xie": "哞 gồm 口 (Khẩu — miệng, âm thanh) và 牟 (Mâu) biểu âm mōu. Chữ phỏng âm: \"哞\" mô phỏng tiếng bò kêu \"moo\" trong tiếng Anh. Đây là chữ tạo muộn dùng trong văn học thiếu nhi và miêu tả âm thanh. Wiktionary không có glyph-origin. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng bò rống", "Hạng Tần Suất (Jun Da)": "5554.0", "Tần Suất % (Jun Da)": "99.9630550307", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 牟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口牟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "牟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哞", "Unihan_Traditional (Chữ Phồn thể)": "哞", "Pinyin_Xie": "mōu", "Âm Hán Việt_Xie": "mâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Động từ | 动词 | Chữ này thường dùng làm từ tượng thanh mô phỏng tiếng bò kêu hoặc làm động từ chỉ hành động bò rống. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('徜', '{"9000": "5555.0", "Chữ Trung Quốc": "徜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彳 | Số nét | 11 | nét | 徜 | thường | tượng hình | thơ thẩn, đi lại thong dong | 徜 gồm bộ 彳(Xích, biểu nghĩa: bước chân nhỏ, đi từng bước) và 尚 (Thượng, biểu âm). Chữ hình thanh — bộ Xích xác định liên quan đến đi lại; phần Thượng biểu âm cháng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thường\" (徜): bước (彳) thong dong thường ngày — 徜徉, dạo bước tự do thảnh thơi. | Gương Hán-Việt | thường — dùng trong \"thường dương\" (徜徉, thơ thẩn dạo bước) | Mở khoá kiến thức | Biết 徜 mở khoá từ 徜徉 (thường dương — đi lại thong dong, thơ thẩn) trong thơ văn.", "Tự nguyên_Xie": "徜 gồm 彳(Xích — đi bước nhỏ) và 尚 (Thượng) biểu âm cháng. Chỉ dùng trong từ 徜徉 (thường dương — thơ thẩn dạo bước, đi lại tự do). Wiktionary ghi nhận chỉ dùng trong 徜徉. Chưa có glyph-origin chi tiết. Chưa có nguồn học thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thảng dương 徜佯)", "Hạng Tần Suất (Jun Da)": "5555.0", "Tần Suất % (Jun Da)": "99.9631067092", "GavinGrover_Once (Chiết tự trực tiếp)": "彳 + 尚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰彳尚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "彳", "Unihan_Simplified (Chữ Giản thể)": "徜", "Unihan_Traditional (Chữ Phồn thể)": "徜", "Pinyin_Xie": "cháng", "Âm Hán Việt_Xie": "thảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường không đứng một mình mà kết hợp thành từ láy để làm động từ chỉ trạng thái đi dạo, đi quanh quẩn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('慊', '{"9000": "5556.0", "Chữ Trung Quốc": "慊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 13 | nét | 慊 | khiêm | tượng hình | không hài lòng; thỏa mãn (nghĩa hai chiều) | 慊 gồm bộ 忄(Tâm, biểu nghĩa: tâm trạng, cảm xúc) và 兼 (Kiêm, biểu âm). Chữ hình thanh — bộ Tâm xác định liên quan đến nội tâm; phần Kiêm biểu âm qiàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiêm\" (慊): tâm (忄) kiêm nhường (兼) — lòng chưa thỏa hay đã thỏa, tùy ngữ cảnh. | Gương Hán-Việt | khiêm — dùng trong văn ngôn cổ chỉ trạng thái tâm lý không/đã hài lòng | Mở khoá kiến thức | Biết 慊 mở khoá cách đọc văn ngôn Mạnh Tử về trạng thái nội tâm và khí hạo nhiên.", "Tự nguyên_Xie": "Tiểu triện | 慊 gồm 忄(Tâm — tâm trạng) và 兼 (Kiêm) biểu âm qiàn. Chữ độc đáo vì có hai nghĩa đối lập: (1) không hài lòng, bất mãn; (2) hài lòng, thỏa mãn — tùy ngữ cảnh. Sách Mạnh Tử: \"行有不慊於心，則餒矣\" (hành động mà lòng không thỏa thì sức kém). Wiktionary có hình tiểu triện. Cấu trúc chi tiết chưa rõ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "không hài lòng, không thích", "Hạng Tần Suất (Jun Da)": "5556.0", "Tần Suất % (Jun Da)": "99.9631583877", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 兼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄兼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "慊", "Unihan_Traditional (Chữ Phồn thể)": "慊", "Pinyin_Xie": "qiàn", "Âm Hán Việt_Xie": "khiết, khiểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này dùng làm tính từ hoặc động từ thể hiện tâm trạng không hài lòng, oán giận hoặc tiếc nuối. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('洳', '{"9000": "5557.0", "Chữ Trung Quốc": "洳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 洳 | nhơ | tượng hình | đất trũng lầy, đất ngập nước | 洳 gồm bộ 氵(Thủy, biểu nghĩa: nước) và 如 (Như, biểu âm). Chữ hình thanh — bộ Thủy xác định liên quan đến nước, vùng ẩm ướt; phần Như biểu âm rù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhơ\" (洳): nước (氵) ngập như (如) vậy — đất nhơ lầy ướt, trũng ngập. | Gương Hán-Việt | nhơ — dùng trong \"thư nhơ\" (沮洳, đầm lầy) và \"Nhơ Hà\" (洳河, tên sông) | Mở khoá kiến thức | Biết 洳 mở khoá từ 沮洳 (đầm lầy) trong Kinh Thi và địa danh 洳河 (sông Nhơ ở Bắc Kinh).", "Tự nguyên_Xie": "洳 gồm 氵(Thủy — nước) và 如 (Như) biểu âm rù. Nghĩa: ẩm ướt, lầy lội; vùng đất trũng ngập nước. Dùng trong 沮洳 (thư nhơ — đầm lầy), 洳河 (Nhơ Hà — tên sông ở Bắc Kinh). Sách cổ Kinh Thi đã dùng: \"汾沮洳\" (Phần thư nhơ — bên sông Phần lầy ướt). Wiktionary có phát âm nhưng không có glyph-origin chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đất trũng lầy", "Hạng Tần Suất (Jun Da)": "5557.0", "Tần Suất % (Jun Da)": "99.9632100663", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 如", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵如", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "如", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "洳", "Unihan_Traditional (Chữ Phồn thể)": "洳", "Pinyin_Xie": "rù", "Âm Hán Việt_Xie": "như", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này dùng làm tính từ chỉ sự ẩm ướt hoặc danh từ chỉ vùng đất trũng lầy lội. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('渑', '{"9000": "5558.0", "Chữ Trung Quốc": "渑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 渑 | tượng hình | tên sông Thằng ở Sơn Đông | 渑 là chữ chỉ tên riêng (tên sông), không phân tích được thành phần theo từ điển CHISE. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thằng\": 渑 có bộ 水 (thủy) bên trái — đây là chữ chỉ dòng sông Thằng ở Sơn Đông. | Gương Hán-Việt | \"thằng\" ít gặp trong từ điển Hán-Việt; chủ yếu dùng trong địa danh. | Mở khoá kiến thức | Biết 渑 giúp nhận ra tên địa danh sông Thằng trong văn bản lịch sử Trung Quốc.", "Tự nguyên_Xie": "渑 là tên sông Thằng (Miǎn Hé) ở tỉnh Sơn Đông, Trung Quốc. Không có nguồn Wiktionary ghi nhận glyph origin; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Thằng", "Hạng Tần Suất (Jun Da)": "5558.0", "Tần Suất % (Jun Da)": "99.9632617448", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 黾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵黾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "黾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "渑", "Unihan_Traditional (Chữ Phồn thể)": "澠", "Pinyin_Xie": "miǎn", "Âm Hán Việt_Xie": "thằng, miễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ tên sông hoặc địa danh cổ ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('灞', '{"9000": "5559.0", "Chữ Trung Quốc": "灞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 24 | nét | 水 | thủy | biểu nghĩa | nước | 霸 | bá | biểu âm | chúa tể, bá chủ | 灞 = 水 (Thủy, biểu nghĩa: nước) + 霸 (Bá, biểu âm); chữ hình thanh. 水 cho biết đây là tên sông, 霸 cho biết âm đọc bà.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bá\": 灞 có bộ 水 (thủy) kèm 霸 (Bá — bá chủ) — dòng sông bá chủ ở kinh đô Trường An xưa. | Gương Hán-Việt | \"bá\" ít gặp trong từ điển Hán-Việt thông dụng; chủ yếu trong địa danh. | Mở khoá kiến thức | Biết 灞 giúp đọc tên địa danh 灞河, 灞源 trong thơ văn cổ Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 灞 là chữ hình thanh (psc): bộ 水 biểu nghĩa ''nước'', 霸 biểu âm. Chữ chuyên dùng trong địa danh 灞河 — con sông ở tỉnh Thiểm Tây (Shaanxi), Trung Quốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Bá (ở tỉnh Thiểm Tây của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "5559.0", "Tần Suất % (Jun Da)": "99.9633134233", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 霸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵霸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "霸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "灞", "Unihan_Traditional (Chữ Phồn thể)": "灞", "Pinyin_Xie": "bà", "Âm Hán Việt_Xie": "bá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ riêng để chỉ con sông Bá Thủy ở tỉnh Thiểm Tây, Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盍', '{"9000": "5560.0", "Chữ Trung Quốc": "盍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 10 | nét | 盍 | tượng hình | đồ đựng và nắp đậy — hỏi ''sao chẳng?'' | 盍 là tượng hình nguyên thủy: một chiếc nắp đậy lên đồ đựng (皿). Theo Wiktionary, 盍 là dạng gốc của chữ 蓋 (cái nắp), sau dùng làm hư từ hỏi ''sao chẳng''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạp\": 盍 hình một cái nắp đậy lên bát 皿 — câu hỏi văn ngôn ''sao chẳng đậy nắp lại?'' | Gương Hán-Việt | \"hạp\" ít gặp trong từ điển Hán-Việt; 盍 chủ yếu dùng trong văn ngôn cổ. | Mở khoá kiến thức | Biết 盍 giúp đọc văn ngôn cổ Trung Quốc — hư từ vấn ngữ ''sao chẳng'' xuất hiện nhiều trong Luận Ngữ, Tả Truyện.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Đại triện | Theo Wiktionary, 盍 vốn là chữ tượng hình (liushu 1): hình ảnh một đồ đựng và cái nắp đậy lên trên. Đây là dạng nguyên thủy của 蓋. Về sau 盍 chuyên dùng làm hư từ vấn ngữ văn ngôn, nghĩa là ''sao'', ''sao chẳng''. Chữ có di tích từ giáp cốt văn, kim văn, bạch thư và đại triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1063.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khứ (489) Mãnh (151)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Khứ (số 489 - rời đi) ở trên bộ Mãnh (số 151 - bát đĩa). Giải thích sự chuyển ý: Đây là chữ Hội ý. Hạp mang ý nghĩa hợp lại, đậy lại. Sau thường dùng làm trợ từ biểu thị sự hỏi ngược lại: sao chẳng (Hạp các ngôn nhĩ chí - Sao các ngươi không nói chí hướng của mình ra).", "Nghĩa Tiếng Việt_Xie": "sao, sao chẳng (câu hỏi); cánh cửa", "Hạng Tần Suất (Jun Da)": "5560.0", "Tần Suất % (Jun Da)": "99.9633651018", "GavinGrover_Once (Chiết tự trực tiếp)": "去 + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱去皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "去", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "盍", "Unihan_Traditional (Chữ Phồn thể)": "盇", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Động từ | 动词 | Chữ này thường dùng làm phó từ nghi vấn trong văn ngôn với nghĩa là sao không. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钋', '{"9000": "5561.0", "Chữ Trung Quốc": "钋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 7 | nét | 钋 | tượng hình | nguyên tố hóa học polonium (Po) | 钋 là chữ tạo muộn dùng để phiên âm tên nguyên tố hóa học polonium (Po). Bộ 钅 (kim — kim loại) biểu nghĩa, phần còn lại biểu âm. Chưa thấy trong giáp cốt hay kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phác\": 钋 có bộ 钅 (kim — kim loại) — nguyên tố kim loại phóng xạ polonium do Marie Curie phát hiện. | Gương Hán-Việt | \"phác\" ít gặp trong từ điển Hán-Việt; 钋 chủ yếu dùng trong hóa học. | Mở khoá kiến thức | Biết 钋 giúp đọc tên nguyên tố polonium trong văn bản hóa học tiếng Trung.", "Tự nguyên_Xie": "钋 là chữ tạo muộn, không có nguồn Wiktionary ghi nhận glyph origin. Chữ dùng để biểu thị nguyên tố hóa học polonium (Po, số hiệu nguyên tử 84) — được đặt theo tên Ba Lan (Poland), quê hương của Marie Curie. chưa có nguồn học thuật về nguồn gốc chữ viết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố poloni, Po", "Hạng Tần Suất (Jun Da)": "5561.0", "Tần Suất % (Jun Da)": "99.9634167803", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 卜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅卜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钋", "Unihan_Traditional (Chữ Phồn thể)": "釙", "Pinyin_Xie": "pō", "Âm Hán Việt_Xie": "bộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ trong hóa học để chỉ nguyên tố kim loại phóng xạ Polonium. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸫', '{"9000": "5562.0", "Chữ Trung Quốc": "鸫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 10 | nét | 鸫 | tượng hình | con sáo đất (họ Turdidae) | 鸫 là chữ chỉ loài chim Turdus (sáo đất, họ Turdidae). Bộ 鸟 (điểu — chim) biểu nghĩa, phần còn lại có thể biểu âm. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đông\": 鸫 có bộ 鸟 (điểu — chim) — loài chim Turdidae có tiếng hót hay. | Gương Hán-Việt | \"đông\" ít gặp trong từ điển Hán-Việt; 鸫 chủ yếu dùng trong sinh học. | Mở khoá kiến thức | Biết 鸫 giúp nhận ra tên loài chim sáo đất trong sách vở sinh học tiếng Trung.", "Tự nguyên_Xie": "鸫 không có nguồn Wiktionary ghi nhận glyph origin. Chữ chỉ loài chim thuộc họ Turdidae (sáo đất, quạ), bộ 鸟 cho biết đây là chữ chỉ loài chim. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con quạ", "Hạng Tần Suất (Jun Da)": "5562.0", "Tần Suất % (Jun Da)": "99.9634684588", "GavinGrover_Once (Chiết tự trực tiếp)": "东 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰东鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "东", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鸫", "Unihan_Traditional (Chữ Phồn thể)": "鶇", "Pinyin_Xie": "dōng", "Âm Hán Việt_Xie": "đông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ các loài chim thuộc họ chim hoét. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踯', '{"9000": "5563.0", "Chữ Trung Quốc": "踯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 15 | nét | 踯 | tượng hình | chùn bước, do dự | 踯 là chữ giản thể của 躑. Theo Wiktionary, 踯 đơn giản hóa từ 躑 (bộ 鄭 rút thành 郑). Chưa thấy cấu trúc hình thanh hay hội ý được ghi chú rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trích\": 踯 có bộ 足 (túc — chân) — đôi chân do dự không chịu bước đi. | Gương Hán-Việt | \"trích\" ít gặp trong từ điển Hán-Việt; 踯 chủ yếu dùng trong 踯躅. | Mở khoá kiến thức | Biết 踯 giúp đọc từ 踯躅 (zhízhú — chần chừ, do dự) xuất hiện trong thơ văn cổ điển.", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 踯 là chữ giản thể của 躑, được rút gọn bộ 鄭 thành 郑. Chữ 躑 có nghĩa ''chùn bước, do dự'' (躑躅, chần chừ không đi). Chỉ thấy trong Lục thư thông (chữ tạo muộn), chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chùn bước, trù trừ, do dự", "Hạng Tần Suất (Jun Da)": "5563.0", "Tần Suất % (Jun Da)": "99.9635201373", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 郑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊郑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "郑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踯", "Unihan_Traditional (Chữ Phồn thể)": "躑", "Pinyin_Xie": "zhí", "Âm Hán Việt_Xie": "trịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường kết hợp với chữ khác tạo thành động từ liên kết chỉ trạng thái đi quanh quẩn, do dự không tiến lên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('縻', '{"9000": "5564.0", "Chữ Trung Quốc": "縻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 17 | nét | 縻 | tượng hình | dây buộc, kiềm chế | 縻 có bộ 糸 (mịch — tơ sợi) biểu nghĩa dây buộc. Không có nguồn Wiktionary ghi nhận cấu trúc chi tiết; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mi\": 縻 có bộ 糸 (mịch — tơ sợi) — sợi dây buộc chặt con trâu không cho đi. | Gương Hán-Việt | \"mi\" trong \"羁縻\" (kiềm chế) — từ lịch sử/chính trị. | Mở khoá kiến thức | Biết 縻 giúp đọc từ 羁縻 (羁縻政策 — chính sách kiềm chế) trong lịch sử Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | 縻 không có nguồn Wiktionary ghi nhận glyph origin. Bộ 糸 gợi ý chữ liên quan đến dây thừng, buộc trói. Nghĩa là dây cương trâu bò, hoặc ràng buộc, kiềm chế. Chỉ thấy tiểu triện, chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "buộc lại", "Hạng Tần Suất (Jun Da)": "5564.0", "Tần Suất % (Jun Da)": "99.9635718159", "GavinGrover_Once (Chiết tự trực tiếp)": "麻 + 糸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴麻糸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "糸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "麻", "Unihan_Simplified (Chữ Giản thể)": "縻", "Unihan_Traditional (Chữ Phồn thể)": "縻", "Pinyin_Xie": "mí", "Âm Hán Việt_Xie": "mi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ với nghĩa trói buộc hoặc làm danh từ chỉ dây thừng buộc trâu bò. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萘', '{"9000": "5565.0", "Chữ Trung Quốc": "萘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 萘 | tượng hình | chất naphthalene (C₁₀H₈) | 萘 là chữ tạo muộn dùng để phiên âm tên hợp chất hóa học naphthalene. Bộ 艸 (thảo — cỏ/thực vật) biểu nghĩa chất hữu cơ, phần còn lại biểu âm. Không có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nại\": 萘 có bộ 艸 (thảo) — naphthalene chiết xuất từ nhựa thực vật hữu cơ. | Gương Hán-Việt | \"nại\" ít gặp trong từ điển Hán-Việt; 萘 chủ yếu dùng trong hóa học. | Mở khoá kiến thức | Biết 萘 giúp đọc tên hóa chất naphthalene trong văn bản hóa học tiếng Trung.", "Tự nguyên_Xie": "萘 là chữ tạo muộn, không có nguồn Wiktionary ghi nhận glyph origin. Chữ dùng để biểu thị hợp chất hóa học naphthalene (C₁₀H₈) — một hydrocarbon thơm có trong nhựa than đá, thường dùng làm thuốc chống sâu bọ (băng phiến). Chưa có nguồn học thuật về nguồn gốc chữ viết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chất naptalin (công thức hoá học: C10H8)", "Hạng Tần Suất (Jun Da)": "5565.0", "Tần Suất % (Jun Da)": "99.9636234944", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 奈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹奈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "萘", "Unihan_Traditional (Chữ Phồn thể)": "萘", "Pinyin_Xie": "nài", "Âm Hán Việt_Xie": "nại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong hóa học để chỉ hợp chất hữu cơ naphtalen. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褫', '{"9000": "5566.0", "Chữ Trung Quốc": "褫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 15 | nét | 衣 | y | biểu nghĩa | áo, quần áo | 虒 | biểu âm | 褫 = 衣 (Y, biểu nghĩa: quần áo) + 虒 (biểu âm); chữ hình thanh. Bộ 衣 cho biết chữ liên quan đến quần áo, 虒 cho biết âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trì\": 褫 có bộ 衣 (y — áo) — cởi/lột áo kẻ phạm tội, tước bỏ phẩm hàm. | Gương Hán-Việt | \"trì\" ít gặp trong từ điển Hán-Việt; 褫 chủ yếu dùng trong 褫職, 褫奪. | Mở khoá kiến thức | Biết 褫 giúp đọc từ 褫職 (tước chức), 褫奪 (tước đoạt) trong văn bản pháp lý hay lịch sử.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 褫 là chữ hình thanh (psc): 衣 biểu nghĩa ''quần áo'', 虒 biểu âm. Nghĩa gốc là cởi/lột áo, tước bỏ. Trong văn ngôn còn nghĩa là tước đoạt phẩm hàm, chức vụ (''褫職''). Chỉ thấy tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cởi áo", "Hạng Tần Suất (Jun Da)": "5566.0", "Tần Suất % (Jun Da)": "99.9636751729", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 虒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤虒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褫", "Unihan_Traditional (Chữ Phồn thể)": "褫", "Pinyin_Xie": "chǐ", "Âm Hán Việt_Xie": "sỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường dùng trong các từ ghép chỉ việc tước đoạt chức vị hoặc quyền lợi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羰', '{"9000": "5567.0", "Chữ Trung Quốc": "羰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 15 | nét | 羰 | tượng hình | nhóm carbonyl (C=O) trong hóa học | 羰 là chữ tạo muộn dùng trong hóa học. Bộ 羊 (dương — con dê) biểu âm hoặc là thành phần cấu tạo. Không có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thang\": 羰 chứa bộ 羊 (dương) — nhớ carbonyl bằng hình ảnh dê (羊) và nhóm C=O. | Gương Hán-Việt | \"thang\" ít gặp trong từ điển Hán-Việt; 羰 chủ yếu dùng trong hóa học. | Mở khoá kiến thức | Biết 羰 giúp đọc thuật ngữ hóa học 羰基 (nhóm carbonyl) trong văn bản hóa học tiếng Trung.", "Tự nguyên_Xie": "羰 là chữ tạo muộn, không có nguồn Wiktionary ghi nhận glyph origin. Chữ dùng để biểu thị nhóm chức carbonyl (C=O) trong hóa học hữu cơ. Chưa có nguồn học thuật về nguồn gốc chữ viết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gốc cacbonyl (công thức hoá học: CO-)", "Hạng Tần Suất (Jun Da)": "5567.0", "Tần Suất % (Jun Da)": "99.9637268514", "GavinGrover_Once (Chiết tự trực tiếp)": "羊 + 炭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰羊炭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "炭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羊", "Unihan_Simplified (Chữ Giản thể)": "羰", "Unihan_Traditional (Chữ Phồn thể)": "羰", "Pinyin_Xie": "tāng", "Âm Hán Việt_Xie": "thang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong hóa học hữu cơ để chỉ nhóm chức cacbonyl. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('俅', '{"9000": "5568.0", "Chữ Trung Quốc": "俅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 9 | nét | 人 | nhân | biểu nghĩa | người | 求 | cầu | biểu âm | xin cầu | 俅 = 亻(Nhân, biểu nghĩa: người) + 求 (Cầu, biểu âm); chữ hình thanh. 亻 cho biết chữ liên quan đến người, 求 cho biết âm đọc qiú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cầu\": 俅 = 亻 (nhân — người) + 求 (cầu) — người cầu kỳ trong trang phục. | Gương Hán-Việt | \"cầu\" ít gặp trong từ điển Hán-Việt; 俅 chủ yếu là chữ cổ. | Mở khoá kiến thức | Biết 俅 giúp đọc từ cổ 俅俅 (cung kính, chỉnh tề trong ăn mặc) trong văn ngôn.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 俅 là chữ hình thanh (psc): bộ 人 biểu nghĩa ''người'', 求 biểu âm. Nghĩa cổ là vẻ ngoài của mũ/khăn đội đầu và trang phục trang trí. Thấy trong tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dân tộc Cầu của Trung Quốc (còn gọi là dân tộc Độc Long); kính cẩn tuân theo, cung thuận", "Hạng Tần Suất (Jun Da)": "5568.0", "Tần Suất % (Jun Da)": "99.9638296916", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 求", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻求", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "求", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "俅", "Unihan_Traditional (Chữ Phồn thể)": "俅", "Pinyin_Xie": "qiú", "Âm Hán Việt_Xie": "cầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ thể hiện dáng vẻ cung kính hoặc làm danh từ chỉ tên một dân tộc thiểu số. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芤', '{"9000": "5569.0", "Chữ Trung Quốc": "芤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 芤 | tượng hình | cây hành; mạch rỗng (y học cổ truyền) | 芤 có bộ 艸 (thảo — cỏ) biểu nghĩa thực vật. Không có nguồn Wiktionary ghi nhận cấu trúc chi tiết; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"câu\": 芤 có bộ 艸 (thảo — cỏ) — hình ảnh cây hành rỗng ruột, thân trống như ống sậy. | Gương Hán-Việt | \"câu\" ít gặp trong từ điển Hán-Việt; 芤 chủ yếu là thuật ngữ Đông y. | Mở khoá kiến thức | Biết 芤 giúp đọc thuật ngữ y học cổ truyền 芤脉 (mạch rỗng) trong sách Đông y.", "Tự nguyên_Xie": "芤 không có nguồn Wiktionary ghi nhận glyph origin. Bộ 艸 gợi ý chữ liên quan đến thực vật. Nghĩa là cây hành, thân rỗng; trong y học cổ truyền Trung Quốc, 芤脉 chỉ loại mạch rỗng (như nhấn vào ống hành). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây hành; hành", "Hạng Tần Suất (Jun Da)": "5569.0", "Tần Suất % (Jun Da)": "99.9638808534", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 孔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹孔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芤", "Unihan_Traditional (Chữ Phồn thể)": "芤", "Pinyin_Xie": "kōu", "Âm Hán Việt_Xie": "khưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ cây hành hoặc làm tính từ mô tả trạng thái mạch đập rỗng trong đông y. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隳', '{"9000": "5570.0", "Chữ Trung Quốc": "隳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 17 | nét | 隳 | tượng hình | huỷ hoại, phá đổ | 隳 có bộ 阜 (phụ — gò đất, tường lũy) biểu nghĩa. Wiktionary ghi nhận các dạng dùng nhưng không phân tích cấu trúc hình thanh hay hội ý. Chưa có nguồn học thuật xác nhận cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hủy\": 隳 có bộ 阜 (phụ — tường lũy) — tường lũy sụp đổ, hủy hoại tan hoang. | Gương Hán-Việt | \"hủy\" trong \"hủy hoại\" — ít gặp trong từ điển Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 隳 giúp đọc thành ngữ cổ 身敗名隳 (thân bại danh hủy) và 隳壞 (hủy hoại) trong văn ngôn.", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary, 隳 nghĩa là phá hủy, làm sụp đổ. Chữ cổ xuất hiện trong văn ngôn với nghĩa tiêu diệt, hủy hoại (身敗名隳 — thân bại danh tan). Có thể đọc là 惰 (lười biếng) trong một số văn bản. Thấy trong đại triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "huỷ nát", "Hạng Tần Suất (Jun Da)": "5570.0", "Tần Suất % (Jun Da)": "99.9639320151", "GavinGrover_Once (Chiết tự trực tiếp)": "隋 + 𠇍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱隋𠇍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠇍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "隋", "Unihan_Simplified (Chữ Giản thể)": "隳", "Unihan_Traditional (Chữ Phồn thể)": "隳", "Pinyin_Xie": "huī", "Âm Hán Việt_Xie": "huy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện hành động tàn phá hoặc làm sụp đổ công trình, chí khí. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('洮', '{"9000": "5571.0", "Chữ Trung Quốc": "洮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 洮 | rệu | tượng hình | sông Thao ở Cam Túc | 洮 có bộ 水 (thủy — nước) biểu nghĩa, gợi ý đây là chữ chỉ sông. Wiktionary chỉ ghi {{Han etym}} mà không phân tích chi tiết cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"rệu\": 洮 có bộ 水 (thủy — nước) — sông Thao (洮河) cuộn chảy qua Cam Túc đổ vào Hoàng Hà. | Gương Hán-Việt | \"rệu\" ít gặp trong từ điển Hán-Việt thông dụng; chủ yếu dùng trong địa danh. | Mở khoá kiến thức | Biết 洮 giúp đọc địa danh 洮河 (sông Thao), 洮州 trong lịch sử và địa lý Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận 洮 nhưng không có phân tích glyph origin chi tiết. Bộ 水 biểu nghĩa sông nước. Chữ chủ yếu dùng làm tên riêng cho sông Thao (洮河) ở tỉnh Cam Túc, Trung Quốc — phụ lưu của sông Hoàng Hà. Thấy trong tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Thao", "Hạng Tần Suất (Jun Da)": "5571.0", "Tần Suất % (Jun Da)": "99.9639831768", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 兆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵兆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "洮", "Unihan_Traditional (Chữ Phồn thể)": "洮", "Pinyin_Xie": "táo", "Âm Hán Việt_Xie": "đào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ với nghĩa gột rửa hoặc làm danh từ riêng chỉ tên sông. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胼', '{"9000": "5572.0", "Chữ Trung Quốc": "胼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 10 | nét | 胼 | bẹn | tượng hình | chai tay (vết chai ở tay chân do lao động) | 胼 có bộ 肉/月 (nhục — thịt) biểu nghĩa, gợi ý chữ liên quan đến mô da thịt. Wiktionary ghi nhận chữ nhưng không phân tích cấu trúc glyph origin chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bẹn\": 胼 có bộ 肉 (nhục — thịt) — vết chai da thịt trên bàn tay người lao động. | Gương Hán-Việt | \"bẹn\" ít gặp trong từ điển Hán-Việt; 胼 chủ yếu xuất hiện trong từ chuyên môn y học cổ truyền. | Mở khoá kiến thức | Biết 胼 giúp đọc từ 胼胝 (vết chai) và thành ngữ 胼手胝足 (tay chai chân cứng — cần cù lao động).", "Tự nguyên_Xie": "Theo Wiktionary, 胼 chỉ dùng trong từ 胼胝 (pián zhī) — vết chai tay chân do lao động vất vả. Bộ 肉 (月) biểu nghĩa mô thịt. Thành ngữ 胼手胝足 (tay chai chân cứng) chỉ sự lao động vất vả. Chưa thấy trong giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: biền chi 胼胝)", "Hạng Tần Suất (Jun Da)": "5572.0", "Tần Suất % (Jun Da)": "99.9640343386", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 并", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月并", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "并", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胼", "Unihan_Traditional (Chữ Phồn thể)": "胼", "Pinyin_Xie": "pián", "Âm Hán Việt_Xie": "biền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ vết chai trên da hoặc làm tính từ mô tả phần da bị chai cứng do lao động. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罴', '{"9000": "5573.0", "Chữ Trung Quốc": "罴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 14 | nét | 罷 | bãi | biểu âm | thôi, bỏ | 熊 | hùng | biểu nghĩa | gấu | 罴 = 罷 (Bãi, biểu âm) + 熊 (Hùng, biểu nghĩa: gấu); chữ hình thanh. Gốc từ 羆, bộ 熊 cho biết đây là loài gấu, bộ 罷 cho biết âm đọc pí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bi\": 罴 = 熊 (hùng — gấu) + 罷 (bãi, biểu âm) — gấu nâu khổng lồ không chịu bãi bước. | Gương Hán-Việt | \"bi\" ít gặp trong từ điển Hán-Việt; 罴 chủ yếu dùng trong thơ ca cổ điển. | Mở khoá kiến thức | Biết 罴 giúp đọc từ 熊罴 (gấu lớn) và thành ngữ cổ 如虎如罴 (như hổ như gấu — dũng mãnh) trong thơ văn.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 罴 (phồn thể: 羆) là chữ hình thanh (psc): 熊 biểu nghĩa ''gấu'', 罷 biểu âm. Hai chữ có phần chung 能. Nghĩa là gấu nâu (Ursus arctos). Trong từ điển cổ, 罴 chỉ gấu lớn hơn gấu 熊 thông thường. Thấy trong tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con bi (như gấu)", "Hạng Tần Suất (Jun Da)": "5573.0", "Tần Suất % (Jun Da)": "99.9640855003", "GavinGrover_Once (Chiết tự trực tiếp)": "罢 + 灬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罢灬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "罢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "灬", "Unihan_Simplified (Chữ Giản thể)": "罴", "Unihan_Traditional (Chữ Phồn thể)": "羆", "Pinyin_Xie": "pí", "Âm Hán Việt_Xie": "bi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài gấu lớn lông màu xám vàng ở vùng núi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镛', '{"9000": "5574.0", "Chữ Trung Quốc": "镛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 镛 | tượng hình | chuông lớn (nhạc cụ thời cổ) | 镛 là chữ giản thể của 鏞. Bộ 钅 (kim — kim loại) biểu nghĩa nhạc cụ kim khí, phần còn lại biểu âm. Chưa thấy cấu trúc được phân tích trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dung\": 镛 có bộ 钅 (kim — kim loại) — chiếc chuông lớn vang dội trong cung đình. | Gương Hán-Việt | \"dung\" ít gặp trong từ điển Hán-Việt; 镛 là nhạc cụ cổ. | Mở khoá kiến thức | Biết 镛 giúp đọc tên nhạc cụ cổ trong sách âm nhạc lịch sử Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 镛 là chữ giản thể của 鏞, rút gọn bộ 金 thành 钅. Chữ chỉ loại chuông lớn dùng trong nhạc lễ cung đình thời cổ Trung Quốc. Chỉ thấy tiểu triện, chưa thấy giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chuông lớn (một loại nhạc cụ thời cổ.)", "Hạng Tần Suất (Jun Da)": "5574.0", "Tần Suất % (Jun Da)": "99.964136662", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 庸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅庸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "庸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镛", "Unihan_Traditional (Chữ Phồn thể)": "鏞", "Pinyin_Xie": "yōng", "Âm Hán Việt_Xie": "dong", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại nhạc cụ gõ bằng đồng thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('怛', '{"9000": "5575.0", "Chữ Trung Quốc": "怛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 8 | nét | 怛 | đắn | tượng hình | xót xa, lo lắng, kinh ngạc | 怛 có bộ 忄 (tâm — lòng) biểu nghĩa cảm xúc, gợi ý chữ liên quan đến tâm trạng đau buồn. Wiktionary không phân tích cấu trúc glyph origin chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đắn\": 怛 có bộ 忄 (tâm — lòng) — lòng đắng cay, xót xa khi chứng kiến điều đau lòng. | Gương Hán-Việt | \"đắn\" ít gặp trong từ điển Hán-Việt; 怛 chủ yếu xuất hiện trong văn ngôn và thành ngữ. | Mở khoá kiến thức | Biết 怛 giúp đọc thành ngữ 怛然失色 (tái mặt), 惻怛之心 (lòng trắc ẩn) trong văn học cổ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 怛 là chữ văn ngôn nghĩa ''xót xa, lo lắng, kinh sợ''. Bộ 忄 (tâm) biểu nghĩa trạng thái tâm lý. Hay gặp trong thành ngữ 怛然失色 (tái mặt kinh hoàng), 惻怛 (trắc ẩn, xót xa). Thấy trong tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "386.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tâm (148) Đán (81)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tâm (số 148 - tâm đứng) và chữ Đán (số 122 - buổi sáng) . Đát là cảm giác buồn rầu, sợ hãi, xót xa. Giải thích sự chuyển ý: Chữ Đán (buổi sáng) chỉ âm, chữ Tâm (lòng) chỉ ý. Cảm giác trong lòng (Tâm) xót xa, hoang mang sợ hãi (Đát). *(Biến âm Hán Việt: Đán -> Đát)*", "Nghĩa Tiếng Việt_Xie": "xót xa; kinh ngạc; nhọc nhằn", "Hạng Tần Suất (Jun Da)": "5575.0", "Tần Suất % (Jun Da)": "99.9641878237", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 旦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄旦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "怛", "Unihan_Traditional (Chữ Phồn thể)": "怛", "Pinyin_Xie": "dá", "Âm Hán Việt_Xie": "đát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ miêu tả tâm trạng lo âu hoặc làm động từ biểu thị sự kinh sợ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芊', '{"9000": "5576.0", "Chữ Trung Quốc": "芊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 6 | nét | 艸 | tháu | biểu nghĩa | cỏ, thực vật | 千 | thiên | biểu âm | nghìn | 芊 = 艸 (Tháu, biểu nghĩa: cỏ/thực vật) + 千 (Thiên, biểu âm); chữ hình thanh. Bộ 艸 cho biết chữ liên quan đến thực vật, 千 cho biết âm đọc qiān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiên\": 芊 = 艸 (tháu — cỏ) + 千 (thiên — nghìn) — nghìn ngọn cỏ xanh mướt trải dài. | Gương Hán-Việt | \"thiên\" ít gặp trong từ điển Hán-Việt; 芊 chủ yếu dùng trong thơ ca. | Mở khoá kiến thức | Biết 芊 giúp đọc từ 芊芊 (xanh mướt), 芊绵 (tươi tốt trải dài) trong thơ ca miêu tả thiên nhiên.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 芊 là chữ hình thanh (psc): 艸 biểu nghĩa cỏ/thực vật, 千 biểu âm. Nghĩa là cây cối xanh tươi, um tùm, tốt tươi. Hay gặp trong từ láy 芊芊, 芊綿 (xanh mướt, tươi tốt). Thấy trong tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xanh um, tốt tươi", "Hạng Tần Suất (Jun Da)": "5576.0", "Tần Suất % (Jun Da)": "99.9642384687", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 千", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹千", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "千", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芊", "Unihan_Traditional (Chữ Phồn thể)": "芊", "Pinyin_Xie": "qiān", "Âm Hán Việt_Xie": "thiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ đứng trước danh từ hoặc làm vị ngữ để tả vẻ xanh tươi của cây cỏ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啉', '{"9000": "5577.0", "Chữ Trung Quốc": "啉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 口 | khẩu | biểu nghĩa | miệng | 林 | lam | biểu âm | rừng | 啉 = 口 (Khẩu, biểu nghĩa: miệng) + 林 (biểu âm); chữ hình thanh. Bộ 口 thường dùng làm thành phần hình thanh trong các từ mượn âm, 林 cho biết âm đọc lín.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lăm\": 啉 = 口 (khẩu — miệng) + 林 (lam — rừng) — phát âm lín như 林, bộ 口 cho biết đây là từ phiên âm ngoại lai. | Gương Hán-Việt | \"lăm\" ít gặp trong từ điển Hán-Việt thông dụng; 啉 chủ yếu dùng trong thuật ngữ hóa học. | Mở khoá kiến thức | Biết 啉 giúp đọc thuật ngữ hóa học 喹啉 (quinoline), 氯啉 trong văn bản tiếng Trung.", "Tự nguyên_Xie": "Theo Wiktionary, 啉 là chữ hình thanh (psc): 口 biểu nghĩa ''miệng'', 林 biểu âm. Chữ chủ yếu dùng để phiên âm thuật ngữ hóa học — như 喹啉 (quinoline), 吗啡 (morphine). Bộ 口 xuất hiện nhiều trong chữ phiên âm từ ngoại lai. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Ki-nô-lin (Anh: quinoline)", "Hạng Tần Suất (Jun Da)": "5577.0", "Tần Suất % (Jun Da)": "99.9642891136", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 林", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口林", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "林", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啉", "Unihan_Traditional (Chữ Phồn thể)": "啉", "Pinyin_Xie": "lín", "Âm Hán Việt_Xie": "lâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ trong các thuật ngữ hóa học hoặc làm động từ chỉ hành động uống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('噌', '{"9000": "5578.0", "Chữ Trung Quốc": "噌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 15 | nét | 口 | khẩu | biểu nghĩa | miệng | 曾 | tằng | biểu âm | từng, đã từng | 噌 = 口 (Khẩu, biểu nghĩa: miệng) + 曾 (Tằng, biểu âm); chữ hình thanh. Bộ 口 cho biết chữ liên quan đến miệng/âm thanh, 曾 cho biết âm đọc cēng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tằng\": 噌 = 口 (khẩu — miệng) + 曾 (tằng) — cái miệng từng la hét, quát mắng. | Gương Hán-Việt | \"tằng\" ít gặp trong từ điển Hán-Việt; 噌 chủ yếu dùng trong khẩu ngữ. | Mở khoá kiến thức | Biết 噌 giúp đọc tiếng lóng miêu tả âm thanh sắc bén hoặc nhận ra chữ trong từ 味噌 (miso) tiếng Nhật.", "Tự nguyên_Xie": "Theo Wiktionary, 噌 là chữ hình thanh (psc): 口 biểu nghĩa ''miệng'', 曾 biểu âm. Nghĩa là quát mắng, hét lớn, hoặc tiếng động soạt phắt. Trong tiếng Nhật, 噌 còn dùng trong 味噌 (miso — tương miso). Chưa thấy giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xoẹt, soạt, phắt (tiếng động); mắng mỏ", "Hạng Tần Suất (Jun Da)": "5578.0", "Tần Suất % (Jun Da)": "99.9643397586", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 曾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口曾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "噌", "Unihan_Traditional (Chữ Phồn thể)": "噌", "Pinyin_Xie": "cēng", "Âm Hán Việt_Xie": "tăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Động từ | 动词 | Thường dùng làm từ tượng thanh mô tả tiếng động nhanh hoặc làm động từ mang nghĩa quở trách. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嫱', '{"9000": "5579.0", "Chữ Trung Quốc": "嫱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 14 | nét | 女 | nữ | biểu nghĩa | người phụ nữ | 牆 | tường | biểu âm | bức tường | 嫱 = 女 (Nữ, biểu nghĩa: người phụ nữ) + 牆 (Tường, biểu âm); chữ hình thanh. Bộ 女 cho biết chữ liên quan đến phụ nữ, 牆 cho biết âm đọc qiáng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tường\": 嫱 = 女 (nữ — phụ nữ) + 牆 (tường) — mỹ nhân sau bức tường cung cấm. | Gương Hán-Việt | \"tường\" ít gặp trong từ điển Hán-Việt; 嫱 chủ yếu là danh hiệu cung đình. | Mở khoá kiến thức | Biết 嫱 giúp nhận ra tên Vương Chiêu Quân (王嫱) — một trong Tứ đại mỹ nhân Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 嫱 (phồn thể: 嬙) là chữ hình thanh (psc): 女 biểu nghĩa ''phụ nữ'', 牆 hoặc 嗇 biểu âm. Nghĩa là mỹ nhân trong cung, chức quan nữ trong cung đình. Nổi tiếng nhất là Vương Chiêu Quân (王昭君) còn gọi là 王嫱. Thấy trong tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một chức quan bà)", "Hạng Tần Suất (Jun Da)": "5579.0", "Tần Suất % (Jun Da)": "99.9643904035", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 啬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女啬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "啬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "嫱", "Unihan_Traditional (Chữ Phồn thể)": "嬙", "Pinyin_Xie": "qiáng", "Âm Hán Việt_Xie": "tường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ đứng sau tên riêng để chỉ chức danh của phi tần thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绲', '{"9000": "5580.0", "Chữ Trung Quốc": "绲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 绲 | tượng hình | dải đai, viền vải (trang trí quần áo) | 绲 có bộ 糸/纟 (mịch — tơ sợi) biểu nghĩa vải sợi, gợi ý chữ liên quan đến dây dải. Wiktionary ghi nhận chữ nhưng không phân tích cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"côn\": 绲 có bộ 纟 (mịch — tơ sợi) — đường viền tơ lụa trang trí trên áo quần. | Gương Hán-Việt | \"côn\" ít gặp trong từ điển Hán-Việt; 绲 là thuật ngữ may mặc cổ. | Mở khoá kiến thức | Biết 绲 giúp đọc từ 绲带 (dây đai), 绲边 (đường viền may) trong sách may mặc hay lịch sử trang phục.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary (phồn thể: 緄), 绲 nghĩa là dải đai, dây thừng, hoặc may viền trang trí quần áo. Bộ 糸 biểu nghĩa tơ sợi/vải. Hay gặp trong từ 緄帶 (dây đai), 緄邊 (viền may). Thấy trong tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dải; đai; nịch; dây; may viền; nẹp; viền; côn \n (Danh) Dây; dải. (Động) May viền (trang sức quần áo). (Danh) Lượng từ: bó; mớ. Một âm là hỗn. (Danh) Hỗn Nhung 緄戎 một nhánh của tộc Tây Nhung 西戎.", "Hạng Tần Suất (Jun Da)": "5580.0", "Tần Suất % (Jun Da)": "99.9644410485", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 昆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟昆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绲", "Unihan_Traditional (Chữ Phồn thể)": "緄", "Pinyin_Xie": "gǔn", "Âm Hán Việt_Xie": "cổn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Lượng từ | 量词 | Thường dùng làm động từ chỉ việc may viền áo hoặc làm danh từ chỉ sợi dây đai. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膻', '{"9000": "5581.0", "Chữ Trung Quốc": "膻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 17 | nét | ⺼ | biểu nghĩa | thịt (dạng biến thể của 肉) | 亶 | biểu âm | 膻 = ⺼ (dạng biến của 肉 Nhục, biểu nghĩa: thịt) + 亶 (biểu âm); chữ hình thanh. Bộ 肉 cho biết chữ liên quan đến mô thịt/mùi thịt, 亶 cho biết âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiện\": 膻 có bộ 肉 (nhục — thịt) — mùi tanh hôi đặc trưng của thịt dê cừu. | Gương Hán-Việt | \"thiện\" ít gặp trong từ điển Hán-Việt; 膻 chủ yếu dùng trong ẩm thực và Đông y. | Mở khoá kiến thức | Biết 膻 giúp đọc 膻气 (mùi tanh dê), 膻中 (huyệt vị giữa ngực trong Đông y) trong văn bản ẩm thực và y học.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 膻 là chữ hình thanh (psc): bộ 肉 (⺼) biểu nghĩa ''thịt'', 亶 biểu âm. Có hai âm: shān (mùi hôi tanh của dê/cừu, đồng nghĩa 羶) và dàn (trung tâm ngực trong y học cổ truyền 膻中). Thấy trong tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mùi tanh hôi của dê hay cừu", "Hạng Tần Suất (Jun Da)": "5581.0", "Tần Suất % (Jun Da)": "99.9644916934", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 亶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月亶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膻", "Unihan_Traditional (Chữ Phồn thể)": "羴", "Pinyin_Xie": "shān", "Âm Hán Việt_Xie": "chiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ đứng trước danh từ để bổ nghĩa cho mùi vị đặc trưng của thịt dê. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('焐', '{"9000": "5582.0", "Chữ Trung Quốc": "焐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 11 | nét | 焐 | tượng hình | ấp, chườm ấm bằng hơi nóng | 焐 có bộ 火 (hỏa — lửa) biểu nghĩa nhiệt. Không có nguồn Wiktionary ghi nhận cấu trúc; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ô\": 焐 có bộ 火 (hỏa — lửa) — dùng hơi nóng để chườm ấm, ấp ấm. | Gương Hán-Việt | \"ô\" ít gặp trong từ điển Hán-Việt; 焐 là từ phương ngữ miền Bắc. | Mở khoá kiến thức | Biết 焐 giúp đọc hiểu tiếng lóng phương ngữ miền Bắc Trung Quốc trong văn học hiện đại.", "Tự nguyên_Xie": "焐 là chữ tạo muộn, không có nguồn Wiktionary ghi nhận glyph origin. Bộ 火 biểu nghĩa lửa/nhiệt. Nghĩa là ấp, chườm ấm — dùng hơi nóng để làm ấm vật. Phổ biến trong tiếng Trung phương ngữ phía bắc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ấp, chườm", "Hạng Tần Suất (Jun Da)": "5582.0", "Tần Suất % (Jun Da)": "99.9645423383", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 吾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火吾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "焐", "Unihan_Traditional (Chữ Phồn thể)": "焐", "Pinyin_Xie": "wù", "Âm Hán Việt_Xie": "ngộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ đứng trước danh từ chỉ bộ phận cơ thể cần được sưởi ấm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葎', '{"9000": "5583.0", "Chữ Trung Quốc": "葎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葎 | tượng hình | cây gai cần (Humulus japonicus), thân gai làm thuốc | 葎 có bộ 艸 (thảo — cỏ) biểu nghĩa thực vật. Wiktionary ghi nhận chữ nhưng chỉ dùng trong tên loài 葎草 mà không phân tích cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"luật\": 葎 có bộ 艸 (thảo — cỏ) — cây cỏ gai leo dày đặc như luật nghiêm ngặt. | Gương Hán-Việt | \"luật\" ít gặp trong từ điển Hán-Việt; 葎 chủ yếu dùng trong tên cây. | Mở khoá kiến thức | Biết 葎 giúp đọc tên cây 葎草 (cây gai cần) trong sách Đông y và thực vật học tiếng Trung.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 葎 chỉ dùng trong từ 葎草 — loài cây gai cần (Humulus japonicus), thân có nhiều gai nhỏ, thường mọc ven đường, có công dụng làm thuốc trong Đông y. Bộ 艸 biểu nghĩa thực vật. Thấy trong tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại cỏ, thân nhiều gai, có thể làm thuốc)", "Hạng Tần Suất (Jun Da)": "5583.0", "Tần Suất % (Jun Da)": "99.9646431114", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 律", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹律", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "律", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葎", "Unihan_Traditional (Chữ Phồn thể)": "葎", "Pinyin_Xie": "lǜ", "Âm Hán Việt_Xie": "lựu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong y học cổ truyền để gọi tên một loại cây thân leo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('亓', '{"9000": "5584.0", "Chữ Trung Quốc": "亓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 二 | Số nét | 4 | nét | 亓 | tượng hình | dạng cổ của 其; họ Kỳ | 亓 là dạng cổ của chữ 其 (kỳ — đại từ ''nó, chúng''). Chữ hiện dùng chủ yếu làm họ tên (họ Kỳ). Không có nguồn học thuật phân tích cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": 亓 là dạng cổ của 其 (kỳ), nay chủ yếu dùng làm họ người. | Gương Hán-Việt | \"kỳ\" ít gặp trong từ điển Hán-Việt; 亓 chủ yếu dùng làm họ người. | Mở khoá kiến thức | Biết 亓 giúp nhận ra họ tên 亓氏 (họ Kỳ) trong danh sách trăm họ Trung Quốc.", "Tự nguyên_Xie": "亓 là dạng cổ của 其. Không có nguồn Wiktionary ghi nhận glyph origin chi tiết. Chữ xuất hiện trong kim văn và văn bản cổ đại như dạng thay thế của 其 (đại từ chỉ ngôi thứ ba). Ngày nay chủ yếu dùng làm họ (亓氏 — họ Kỳ). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Kỳ", "Hạng Tần Suất (Jun Da)": "5584.0", "Tần Suất % (Jun Da)": "99.9646932396", "GavinGrover_Once (Chiết tự trực tiếp)": "二 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱二", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "亓", "Unihan_Traditional (Chữ Phồn thể)": "亓", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Đại từ | 代词 | Chủ yếu dùng làm danh từ riêng chỉ họ người hoặc làm đại từ chỉ định trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('倮', '{"9000": "5585.0", "Chữ Trung Quốc": "倮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 10 | nét | 倮 | tượng hình | trần truồng, lộ ra | 倮 có bộ 亻 (nhân — người) biểu nghĩa, gợi ý chữ liên quan đến trạng thái của người. Không có nguồn Wiktionary ghi nhận cấu trúc; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lõa\": 倮 có bộ 亻 (nhân — người) — người không mặc quần áo, trần trụi. | Gương Hán-Việt | \"lõa\" trong \"trần lõa\" — đồng nghĩa với 裸. | Mở khoá kiến thức | Biết 倮 giúp đọc văn bản cổ và tên dân tộc thiểu số trong lịch sử Trung Quốc.", "Tự nguyên_Xie": "倮 không có nguồn Wiktionary ghi nhận glyph origin. Bộ 亻 (nhân) biểu nghĩa người. Nghĩa là trần truồng, lộ ra, không có gì che phủ. Đồng nghĩa với 裸 (lõa). Trong ''Nhị thập tứ sử'' và văn cổ, 倮 chỉ người hay dân tộc không mặc quần áo. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lộ ra, hiện ra; trần truồng", "Hạng Tần Suất (Jun Da)": "5585.0", "Tần Suất % (Jun Da)": "99.9647433678", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 果", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻果", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "倮", "Unihan_Traditional (Chữ Phồn thể)": "倮", "Pinyin_Xie": "luǒ", "Âm Hán Việt_Xie": "khỏa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả trạng thái khỏa thân hoặc làm động từ chỉ sự để lộ ra. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莼', '{"9000": "5586.0", "Chữ Trung Quốc": "莼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 莼 | tượng hình | rau nhút (Brasenia schreberi), cây thủy sinh ăn được | 莼 là chữ giản thể của 蒓. Bộ 艸 (thảo — cỏ) biểu nghĩa thực vật. Chữ chỉ loài cây thủy sinh 莼菜 ăn được, lá mọng nước.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuần\": 莼 có bộ 艸 (thảo — cỏ) — cây rau nhút mọc dưới nước, lá mềm nhớt. | Gương Hán-Việt | \"thuần\" ít gặp trong từ điển Hán-Việt; 莼 chủ yếu dùng trong tên thực vật. | Mở khoá kiến thức | Biết 莼 giúp đọc thành ngữ 莼鲈之思 (nhớ quê) và tên món ăn 莼菜汤 trong văn học và ẩm thực Giang Nam.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 莼 là chữ giản thể của 蒓, rút gọn bộ 糸 thành 纟. Chữ chỉ cây rau nhút (Brasenia schreberi) — loài thủy sinh ăn được, nổi tiếng ở vùng Giang Nam. Thành ngữ 莼鲈之思 (思念家乡美食) chỉ nỗi nhớ quê hương. Thấy trong tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rau nhút, rau rút", "Hạng Tần Suất (Jun Da)": "5586.0", "Tần Suất % (Jun Da)": "99.9647934959", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 纯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹纯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "纯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莼", "Unihan_Traditional (Chữ Phồn thể)": "蒓", "Pinyin_Xie": "chún", "Âm Hán Việt_Xie": "thuần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại rau thủy sinh, thường dùng trong ẩm thực cổ hoặc tên món ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蘅', '{"9000": "5587.0", "Chữ Trung Quốc": "蘅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 19 | nét | 蘅 | tượng hình | cây cỏ thơm (杜蘅, Asarum forbesii) | 蘅 có bộ 艸 (thảo — cỏ) biểu nghĩa thực vật thơm. Wiktionary ghi nhận chữ nhưng không phân tích cấu trúc glyph origin chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hành\": 蘅 có bộ 艸 (thảo — cỏ) — cây cỏ thơm ngát trong thơ ca cổ điển. | Gương Hán-Việt | \"hành\" ít gặp trong từ điển Hán-Việt; 蘅 chủ yếu dùng trong thơ ca và thực vật học. | Mở khoá kiến thức | Biết 蘅 giúp đọc thơ cổ điển Trung Quốc — 蘅芷 (cỏ thơm), 蘅皋 (bờ cỏ thơm) hay gặp trong Tao Ca, Ly Tao.", "Tự nguyên_Xie": "Theo Wiktionary, 蘅 là viết tắt của 杜蘅 (Asarum forbesii) và 微蘅 — các loài cỏ thơm có dược tính. Bộ 艸 biểu nghĩa thực vật. Chữ xuất hiện nhiều trong thi ca cổ điển miêu tả thảo mộc thơm. Chưa có nguồn học thuật về glyph origin. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại cỏ thơm)", "Hạng Tần Suất (Jun Da)": "5587.0", "Tần Suất % (Jun Da)": "99.9648436241", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 衡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹衡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "衡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蘅", "Unihan_Traditional (Chữ Phồn thể)": "蘅", "Pinyin_Xie": "héng", "Âm Hán Việt_Xie": "hành", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài cỏ thơm cổ đại, thường xuất hiện trong văn học và tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘞', '{"9000": "5588.0", "Chữ Trung Quốc": "嘞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 14 | nét | 嘞 | tượng hình | trợ từ ngữ khí (tiếng Quảng Đông/phương ngữ) | 嘞 có bộ 口 (khẩu — miệng) biểu nghĩa ngữ khí, âm thanh. Không có nguồn Wiktionary ghi nhận cấu trúc; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lặc\": 嘞 có bộ 口 (khẩu — miệng) — tiếng kêu cuối câu ''lei'' nhẹ nhàng đồng ý hoặc hoàn tất. | Gương Hán-Việt | \"lặc\" ít gặp trong từ điển Hán-Việt; 嘞 chủ yếu là trợ từ phương ngữ. | Mở khoá kiến thức | Biết 嘞 giúp đọc hội thoại tiếng Quảng Đông và văn học hiện đại, đặc biệt trong tiểu thuyết phương ngữ.", "Tự nguyên_Xie": "嘞 là chữ tạo muộn, không có nguồn Wiktionary ghi nhận glyph origin. Bộ 口 biểu nghĩa âm thanh/ngữ khí. Chữ dùng làm trợ từ ngữ khí trong tiếng Quảng Đông và phương ngữ Bắc Kinh, biểu thị sự hoàn tất, từ chối lịch sự, hoặc nhấn mạnh nhẹ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(trợ từ chỉ sự hoàn tất)", "Hạng Tần Suất (Jun Da)": "5588.0", "Tần Suất % (Jun Da)": "99.9648937522", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 勒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口勒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嘞", "Unihan_Traditional (Chữ Phồn thể)": "嘞", "Pinyin_Xie": "lei", "Âm Hán Việt_Xie": "lặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Trợ từ | 助词 | Chữ này làm trợ từ ngữ khí đặt ở cuối câu để biểu thị sự khẳng định, đồng ý hoặc hoàn thành. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí).", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缒', '{"9000": "5589.0", "Chữ Trung Quốc": "缒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 糸 | biểu nghĩa | sợi tơ, dây | 追 | đôi | biểu âm | đuổi theo | 缒 = 糸 (biểu nghĩa: dây tơ) + 追 (Đôi, biểu âm); chữ hình thanh. Bộ 糸 cho biết chữ liên quan đến dây thừng, 追 cho biết âm đọc zhuì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trụy\": 缒 = 糸 (dây tơ) + 追 (đôi — đuổi) — buông dây thòng xuống, hạ thấp như vật rơi trụy. | Gương Hán-Việt | \"trụy\" ít gặp trong từ điển Hán-Việt; 缒 chủ yếu là từ văn ngôn. | Mở khoá kiến thức | Biết 缒 giúp đọc văn ngôn cổ — ''夜缒而出'' (đêm dùng dây thoát ra) trong Tả Truyện.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary (phồn thể: 縋), 缒 là chữ hình thanh (psc): 糸 biểu nghĩa ''dây tơ/thừng'', 追 biểu âm. Nghĩa là thòng dây từ trên xuống, dùng dây hạ người hoặc vật từ cao xuống. Xuất hiện trong Tả Truyện: ''夜縋而出'' (đêm dùng dây thoát ra). Thấy trong tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "buông dây, thòng dây từ trên xuống", "Hạng Tần Suất (Jun Da)": "5589.0", "Tần Suất % (Jun Da)": "99.9649438804", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 追", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟追", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "追", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缒", "Unihan_Traditional (Chữ Phồn thể)": "縋", "Pinyin_Xie": "zhuì", "Âm Hán Việt_Xie": "truý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động dùng dây để thả người hoặc vật từ trên cao xuống. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镆', '{"9000": "5590.0", "Chữ Trung Quốc": "镆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 镆 | tượng hình | thanh kiếm (镆铘 — kiếm quý) | 镆 có bộ 钅 (kim — kim loại) biểu nghĩa vũ khí kim loại. Wiktionary ghi nhận 镆 là phồn thể 鏌 nhưng không phân tích cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạc\": 镆 có bộ 钅 (kim — kim loại) — thanh kiếm huyền thoại 镆铘 sắc bén như thần. | Gương Hán-Việt | \"mạc\" ít gặp trong từ điển Hán-Việt; 镆 chủ yếu là tên kiếm cổ. | Mở khoá kiến thức | Biết 镆 giúp nhận ra tên kiếm cổ 镆铘 (Mạc Da) trong văn học và lịch sử kiếm thuật Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary (phồn thể: 鏌), 镆 là tên kiếm quý 镆铘 (Mò Yé) — một trong những thanh kiếm huyền thoại của Trung Quốc cổ đại. Bộ 钅 biểu nghĩa kim loại/vũ khí. Thấy trong tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mạc da 鏌鋣,镆铘)", "Hạng Tần Suất (Jun Da)": "5590.0", "Tần Suất % (Jun Da)": "99.9649940085", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 莫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅莫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "莫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镆", "Unihan_Traditional (Chữ Phồn thể)": "鏌", "Pinyin_Xie": "mò", "Âm Hán Việt_Xie": "mạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, hầu như chỉ dùng trong từ ghép Mạc Da để chỉ thanh kiếm báu thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('伧', '{"9000": "5591.0", "Chữ Trung Quốc": "伧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 6 | nét | 伧 | tượng hình | người quê mùa, thô lỗ | 伧 có bộ 亻 (nhân — người) biểu nghĩa, gợi ý chữ chỉ người. Wiktionary ghi nhận 伧 (phồn thể: 傖) nhưng không phân tích cấu trúc glyph origin.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thương\": 伧 có bộ 亻 (nhân — người) — người quê kiểng thiếu lịch sự. | Gương Hán-Việt | \"thương\" ít gặp trong từ điển Hán-Việt; 伧 chủ yếu dùng trong 寒伧. | Mở khoá kiến thức | Biết 伧 giúp đọc từ 寒伧 (thô kệch, quê mùa) trong văn học và văn ngôn Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary (phồn thể: 傖), 伧 nghĩa là người quê mùa, tầm thường, thô lỗ. Bộ 亻 biểu nghĩa người. Hay gặp trong 寒伧 (hèn mọn, thô kệch), 伧父 (người quê mùa). Chưa có nguồn học thuật về glyph origin. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khiếm nhã; gã, thằng cha (khinh bỉ)", "Hạng Tần Suất (Jun Da)": "5591.0", "Tần Suất % (Jun Da)": "99.9650937481", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 仓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻仓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "仓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "伧", "Unihan_Traditional (Chữ Phồn thể)": "傖", "Pinyin_Xie": "cāng", "Âm Hán Việt_Xie": "sanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ sự thô kệch, quê mùa hoặc làm danh từ chỉ hạng người thô bỉ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荏', '{"9000": "5592.0", "Chữ Trung Quốc": "荏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艹 | biểu nghĩa | cỏ, thực vật | 任 | nhâm | biểu âm | nhận việc, phó thác | 荏 = 艹 (biểu nghĩa: cỏ/thực vật) + 任 (Nhâm, biểu âm); chữ hình thanh. Bộ 艹 cho biết chữ liên quan đến thực vật, 任 cho biết âm đọc rěn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhiệm\": 荏 = 艹 (cỏ) + 任 (nhâm) — cây cỏ nhu mì, thời gian 荏苒 trôi đi như cỏ mềm. | Gương Hán-Việt | \"nhiệm\" ít gặp trong từ điển Hán-Việt; 荏 chủ yếu dùng trong 荏苒. | Mở khoá kiến thức | Biết 荏 giúp đọc từ 荏苒 (thời gian trôi dần) và 荏弱 (nhu nhược, yếu đuối) trong văn ngôn cổ.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 荏 là chữ hình thanh (psc): 艸 (艹) biểu nghĩa cỏ/thực vật, 任 biểu âm. Nghĩa là cây tía tô (荏苒 — thời gian trôi qua nhẹ nhàng) hoặc nhu mì, yếu đuối. Trong văn ngôn, 荏苒 chỉ thời gian dần trôi. Thấy trong tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thứ đậu to; nhu mì, nhu nhược", "Hạng Tần Suất (Jun Da)": "5592.0", "Tần Suất % (Jun Da)": "99.9651433595", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 任", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹任", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "任", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荏", "Unihan_Traditional (Chữ Phồn thể)": "荏", "Pinyin_Xie": "rěn", "Âm Hán Việt_Xie": "nhẫm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ cây tía tô hoặc làm tính từ chỉ sự mềm yếu, nhu nhược. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('唳', '{"9000": "5593.0", "Chữ Trung Quốc": "唳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 唳 | tượng hình | tiếng kêu của chim hạc | 唳 có bộ 口 (khẩu — miệng) biểu nghĩa âm thanh. Wiktionary ghi nhận chữ nhưng không phân tích cấu trúc glyph origin chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lệ\": 唳 có bộ 口 (khẩu — miệng) — tiếng kêu lệ lạc của chim hạc trong gió. | Gương Hán-Việt | \"lệ\" ít gặp trong từ điển Hán-Việt; 唳 chủ yếu dùng trong 鹤唳, 风声鹤唳. | Mở khoá kiến thức | Biết 唳 giúp đọc thành ngữ 风声鹤唳 (hoảng loạn) và tên điển tích 华亭鹤唳 trong văn học cổ.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 唳 chỉ tiếng kêu của chim, đặc biệt là tiếng hạc. Bộ 口 biểu nghĩa âm thanh. Hay gặp trong thành ngữ 风声鹤唳 (nghe gió thổi cũng tưởng hạc kêu — chỉ trạng thái kinh hãi, hoảng loạn). Thấy trong tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng kêu", "Hạng Tần Suất (Jun Da)": "5593.0", "Tần Suất % (Jun Da)": "99.9651929708", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 戾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口戾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "唳", "Unihan_Traditional (Chữ Phồn thể)": "唳", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ tiếng chim hạc kêu hoặc làm danh từ chỉ âm thanh đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('檩', '{"9000": "5594.0", "Chữ Trung Quốc": "檩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 17 | nét | 檩 | tượng hình | đòn tay (xà ngang gác trên đầu cột trong kiến trúc) | 檩 có bộ 木 (mộc — gỗ) biểu nghĩa vật liệu gỗ trong kiến trúc. Wiktionary ghi nhận 檩 (phồn thể: 檁) là thuật ngữ kiến trúc nhưng không phân tích cấu trúc glyph origin.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lẫm\": 檩 có bộ 木 (mộc — gỗ) — thanh gỗ nằm ngang bắc trên cột đỡ mái nhà. | Gương Hán-Việt | \"lẫm\" ít gặp trong từ điển Hán-Việt; 檩 là thuật ngữ kiến trúc. | Mở khoá kiến thức | Biết 檩 giúp đọc tên bộ phận 檩条 (đòn tay), 脊檩 (đòn nóc) trong sách kiến trúc và xây dựng tiếng Trung.", "Tự nguyên_Xie": "Theo Wiktionary (phồn thể: 檁), 檩 là thuật ngữ kiến trúc chỉ đòn tay — xà ngang bắc trên đầu cột để gác rui mè (purlin). Bộ 木 biểu nghĩa gỗ. Thường thấy trong kiến trúc gỗ truyền thống Trung Quốc. Thấy ở âm cổ Trung Đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đòn tay, xà ngang bắc trên đầu cột để gác rui", "Hạng Tần Suất (Jun Da)": "5594.0", "Tần Suất % (Jun Da)": "99.9652425822", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 禀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木禀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "檩", "Unihan_Traditional (Chữ Phồn thể)": "檁", "Pinyin_Xie": "lǐn", "Âm Hán Việt_Xie": "lẫm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ thanh gỗ ngang dùng để đỡ rui mè trong kiến trúc nhà cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸶', '{"9000": "5595.0", "Chữ Trung Quốc": "鸶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 10 | nét | 絲 | tơ | biểu âm | sợi tơ (cho âm đọc) | 鳥 | điểu | biểu nghĩa | chim | 鸶 = 絲 (Tơ, biểu âm) + 鳥 (Điểu, biểu nghĩa: chim); chữ hình thanh. Phần 鳥 chỉ loại (chim), phần 絲 cho âm gần với sī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\" (âm): Con chim (鳥) mà tiếng kêu nghe như sợi tơ (絲) căng — đó là tiếng cò lướt trên mặt nước yên tĩnh. | Gương Hán-Việt | lô tư (鸕鷥 — tên con cò) | Mở khoá kiến thức | Biết 鸶 mở khoá các tên loài chim có 鳥 bộ như 鹭鸶 (lộ tư — cò trắng).", "Tự nguyên_Xie": "Chữ hình thanh: 鳥 (điểu) biểu nghĩa chỉ loài chim, 絲 (tơ) biểu âm cho âm sī. Đây là dạng giản thể của 鷥, chỉ loài cò trắng (egret) hay diệc. Chưa có glyph giáp cốt/kim văn ghi nhận. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lô tư 鸕鷀,鸕鷥,鸬鷀,鸬鸶)", "Hạng Tần Suất (Jun Da)": "5595.0", "Tần Suất % (Jun Da)": "99.9652921936", "GavinGrover_Once (Chiết tự trực tiếp)": "丝 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱丝鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鸶", "Unihan_Traditional (Chữ Phồn thể)": "鷥", "Pinyin_Xie": "sī", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường kết hợp thành từ ghép để chỉ loài chim cò trắng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚬', '{"9000": "5596.0", "Chữ Trung Quốc": "蚬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 10 | nét | 蚬 | hiển | tượng hình | con hến — chữ độc thể, chưa tách được thành phần rõ ràng | 蚬 là chữ thuộc bộ 虫 (trùng) nhưng không có cấu trúc hình thanh/hội ý rõ trong dạng giản thể hiện tại. Dạng phồn thể 蜆 có thể tích hợp thêm yếu tố âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiển\": Con trùng (虫) bé tí mà hiển hiện khắp bãi bùn — đó là con hến 蚬. | Gương Hán-Việt | hiển (蚬 — con hến) | Mở khoá kiến thức | Biết 蚬 mở khoá các từ chỉ hải sản nước ngọt trong tiếng Trung, đặc biệt trong ẩm thực vùng Hoa Nam.", "Tự nguyên_Xie": "Tiểu triện | Dạng phồn thể là 蜆. Chữ chỉ loài nhuyễn thể hai mảnh vỏ sống trong nước ngọt hoặc nước lợ (basket clam, Corbiculidae). Có hình tiểu triện ghi nhận. Chưa có phân tích hình thanh/hội ý rõ từ Wiktionary cho dạng giản thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con hến; con sâu kèn", "Hạng Tần Suất (Jun Da)": "5596.0", "Tần Suất % (Jun Da)": "99.9653418049", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 见", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫见", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "见", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚬", "Unihan_Traditional (Chữ Phồn thể)": "蜆", "Pinyin_Xie": "xiǎn", "Âm Hán Việt_Xie": "hiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con hến hoặc các loài động vật thân mềm hai mảnh vỏ nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骱', '{"9000": "5597.0", "Chữ Trung Quốc": "骱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 13 | nét | 骱 | giải | tượng hình | khớp xương — chữ bộ 骨, chưa phân tích được thành phần rõ trong dạng hiện tại | 骱 thuộc bộ 骨 (cốt — xương), nhưng không có cấu trúc hình thanh hay hội ý rõ ràng trong Wiktionary. Chữ chỉ mối nối/khớp giữa các xương.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giải\": Xương (骨) được \"giải\" ra từng khớp — đó là 骱, chỉ mối khớp nối giữa các đốt xương. | Gương Hán-Việt | giải (骱 — khớp xương) | Mở khoá kiến thức | Biết 骱 mở khoá từ 脱骱 (thoát cốt khớp — trật khớp) trong y học cổ truyền Trung Quốc.", "Tự nguyên_Xie": "骱 chỉ khớp xương, phương ngữ Hoa Nam và Quảng Đông. Không có phân tích hình thể từ Wiktionary. Âm đọc đa dạng: gà, jiá, jiè, xiè tuỳ phương ngữ. Chưa có nguồn học thuật về glyph cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khớp xương", "Hạng Tần Suất (Jun Da)": "5597.0", "Tần Suất % (Jun Da)": "99.9653914163", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 介", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨介", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "介", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "骱", "Unihan_Traditional (Chữ Phồn thể)": "骱", "Pinyin_Xie": "jiè", "Âm Hán Việt_Xie": "giới", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ khớp xương hoặc chỗ tiếp giáp giữa các xương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蘖', '{"9000": "5598.0", "Chữ Trung Quốc": "蘖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 20 | nét | 蘖 | nghiệt | tượng hình | chồi cây tái sinh sau khi bị chặt — chữ phức tạp, không tách rõ thành phần hình thanh/hội ý | 蘖 là dạng giản thể được dùng ở Trung Quốc đại lục, tương đương 櫱. Chữ chỉ chồi non mọc lại từ gốc cây đã bị chặt. Cấu trúc chi tiết chưa được phân tích rõ trong Wiktionary cho dạng này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghiệt\": Dù bị chặt đứt, cây vẫn sinh \"nghiệt\" — chồi 蘖 mọc lên như một sức sống bất diệt từ gốc rễ. | Gương Hán-Việt | nghiệt (蘖/櫱 — chồi tái sinh) | Mở khoá kiến thức | Biết 蘖 mở khoá thành ngữ 余孽 (dư nghiệt — tàn dư xấu xa) và ý niệm tái sinh trong thơ văn Hán.", "Tự nguyên_Xie": "Lục thư thông | 蘖 là dạng giản thể của 櫱, chỉ chồi/chồi non tái sinh từ gốc cây sau khi bị chặt. Chỉ có hình lục thư thông (Liushutong, thời Minh muộn) được ghi nhận — chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật phân tích chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chồi cây đâm lên sau khi đã chặt cây mẹ", "Hạng Tần Suất (Jun Da)": "5598.0", "Tần Suất % (Jun Da)": "99.9654410277", "GavinGrover_Once (Chiết tự trực tiếp)": "薛 + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱薛木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "薛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "蘖", "Unihan_Traditional (Chữ Phồn thể)": "櫱", "Pinyin_Xie": "niè", "Âm Hán Việt_Xie": "nghiệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ chồi non mọc ra từ gốc cây đã bị chặt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('澍', '{"9000": "5599.0", "Chữ Trung Quốc": "澍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 15 | nét | 水 | thủy | biểu nghĩa | nước | 尌 | biểu âm | cho âm shù | 澍 = 氵(Thủy, biểu nghĩa: nước) + 尌 (biểu âm); chữ hình thanh. Phần 氵 chỉ mưa/nước, phần 尌 cho âm shù. Chữ chỉ mưa đúng thời đúng lúc, mưa thuận gió hoà.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thụ\": Nước (氵) đổ xuống đúng thời — cơn mưa 澍 như vị thần \"thụ\" ân cho đất đai khô cằn. | Gương Hán-Việt | thụ (澍 — mưa thuận thời) | Mở khoá kiến thức | Biết 澍 mở khoá các từ chỉ mưa lành trong thơ văn cổ, như 甘澍 (cam thụ — mưa ngọt lành).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 氵(thủy) biểu nghĩa chỉ nước/mưa, 尌 biểu âm cho âm shù. Hình tiểu triện đã ghi nhận. 澍 chỉ cơn mưa đúng thời tiết, nuôi dưỡng vạn vật — từ đó mang nghĩa tươi tốt, thấm nhuần. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mưa phải thời; tươi mát, thấm nhuần", "Hạng Tần Suất (Jun Da)": "5599.0", "Tần Suất % (Jun Da)": "99.9654906391", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 尌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵尌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "澍", "Unihan_Traditional (Chữ Phồn thể)": "澍", "Pinyin_Xie": "shù", "Âm Hán Việt_Xie": "chú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ cơn mưa đúng lúc hoặc làm động từ với nghĩa thấm nhuần. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韫', '{"9000": "5600.0", "Chữ Trung Quốc": "韫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 韋 | Số nét | 13 | nét | 韫 | uẩn | tượng hình | cất giấu — bộ 韋 (vi), nhưng không có cấu trúc hình thanh rõ ràng trong dạng giản thể | 韫 thuộc bộ 韋 (vi — da thuộc), dạng giản thể của 韞. Wiktionary chỉ ghi {{Han etym}} mà không phân tích cụ thể. Chữ chỉ hành động cất giấu, ẩn chứa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uẩn\": Bọc trong da (韋) mà không lộ ra ngoài — đó là 韫 uẩn, giấu kín điều quý giá bên trong. | Gương Hán-Việt | uẩn (韫 — cất giấu, ẩn chứa); uẩn khúc (chuyện giấu kín) | Mở khoá kiến thức | Biết 韫 mở khoá từ 韫藏 (uẩn tàng — cất giấu) và phong cách viết hàm súc trong văn học cổ điển.", "Tự nguyên_Xie": "韫 là dạng giản thể của 韞. Wiktionary không cung cấp phân tích hình thể chi tiết cho chữ này. Chữ thuộc bộ 韋 (da thuộc, vật dùng để bọc/giấu), mang nghĩa cất giấu, ẩn chứa trong lòng. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cất giấu", "Hạng Tần Suất (Jun Da)": "5600.0", "Tần Suất % (Jun Da)": "99.9655402504", "GavinGrover_Once (Chiết tự trực tiếp)": "韦 + 昷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰韦昷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "韦", "Unihan_Simplified (Chữ Giản thể)": "韫", "Unihan_Traditional (Chữ Phồn thể)": "韞", "Pinyin_Xie": "yùn", "Âm Hán Việt_Xie": "uẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ để chỉ hành động che giấu, tích trữ hoặc ẩn chứa tài năng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颎', '{"9000": "5601.0", "Chữ Trung Quốc": "颎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 12 | nét | 颎 | quýnh | tượng hình | sáng chói — dạng giản thể của 熲, thay 頁 bằng 页 | 颎 là dạng giản thể của 熲 (quýnh — sáng chói). Wiktionary ghi là 汉字简化 (giản hoá) từ 熲, thay bộ 頁 bằng 页. Không có phân tích hình thể riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quýnh\": Ngọn lửa (火) bùng lên quýnh quáng, chói rực — 颎 là ánh sáng bừng sáng bất ngờ. | Gương Hán-Việt | quýnh (颎 — sáng chói, chói lọi) | Mở khoá kiến thức | Biết 颎 mở khoá các từ cổ miêu tả ánh sáng rực rỡ trong thơ văn Hán.", "Tự nguyên_Xie": "Tiểu triện | 颎 là dạng giản thể của 熲. Hình tiểu triện được ghi nhận. 熲 ghép từ các thành phần chỉ lửa/ánh sáng. Chữ mang nghĩa sáng rực, chói lọi. Chưa có phân tích hình thể Wiktionary riêng cho 颎. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sáng chói, soi tỏ", "Hạng Tần Suất (Jun Da)": "5601.0", "Tần Suất % (Jun Da)": "99.9655898618", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "颎", "Unihan_Traditional (Chữ Phồn thể)": "熲", "Pinyin_Xie": "jiǒng", "Âm Hán Việt_Xie": "quýnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả ánh sáng rực rỡ hoặc làm động từ chỉ sự soi tỏ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘏', '{"9000": "5602.0", "Chữ Trung Quốc": "嘏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 14 | nét | 古 | cổ | biểu nghĩa | xưa cũ, trường tồn | 叚 | biểu âm | cho âm gǔ | 嘏 = 古 (Cổ, biểu nghĩa: xưa cũ, trường tồn) + 叚 (biểu âm); chữ hình thanh. Phần 古 chỉ tính trường thọ bền lâu, phần 叚 cho âm gần với gǔ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hỗ\": Xưa cũ (古) mà vẫn trường tồn — phúc 嘏 là thứ phúc lớn, lâu bền như trời đất. | Gương Hán-Việt | hỗ (嘏 — phúc lớn, trường thọ) | Mở khoá kiến thức | Biết 嘏 mở khoá ngôn ngữ tế lễ cổ đại Trung Hoa, đặc biệt trong các bài chúc tụng.", "Tự nguyên_Xie": "Chữ hình thanh: 古 (cổ) biểu nghĩa gợi ý trường thọ, lâu dài; 叚 biểu âm. Wiktionary xác nhận cấu trúc psc. 嘏 mang nghĩa phúc lành lớn, trường thọ, hạnh phúc dài lâu — thường dùng trong văn tế lễ cổ đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phúc lớn, trường thọ", "Hạng Tần Suất (Jun Da)": "5602.0", "Tần Suất % (Jun Da)": "99.9656389564", "GavinGrover_Once (Chiết tự trực tiếp)": "古 + 叚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰古叚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "古", "Unihan_Simplified (Chữ Giản thể)": "嘏", "Unihan_Traditional (Chữ Phồn thể)": "嘏", "Pinyin_Xie": "gǔ", "Âm Hán Việt_Xie": "hỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ phúc lành lớn hoặc làm tính từ chúc tụng sự trường thọ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垡', '{"9000": "5603.0", "Chữ Trung Quốc": "垡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 9 | nét | 垡 | phạt | tượng hình | cày vỡ đất — chữ bộ 土, chưa tách rõ thành phần | 垡 thuộc bộ 土 (thổ — đất), chỉ hành động cày vỡ đất hay lật đất. Wiktionary không cung cấp phân tích hình thể cụ thể. Chữ thường dùng trong địa danh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phạt\": Đất (土) bị \"phạt\" bởi lưỡi cày — 垡 là miếng đất vừa được cày lật lên. | Gương Hán-Việt | phạt (垡 — cày vỡ đất) | Mở khoá kiến thức | Biết 垡 mở khoá một số địa danh Bắc Trung Quốc có chứa chữ này.", "Tự nguyên_Xie": "垡 thuộc bộ 土 (thổ). Wiktionary chỉ ghi âm đọc và nghĩa cơ bản mà không có phân tích hình thể. Chữ chỉ hành động cày vỡ đất hoặc dùng trong địa danh. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cày vỡ", "Hạng Tần Suất (Jun Da)": "5603.0", "Tần Suất % (Jun Da)": "99.965688051", "GavinGrover_Once (Chiết tự trực tiếp)": "伐 + 土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱伐土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "伐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "垡", "Unihan_Traditional (Chữ Phồn thể)": "垡", "Pinyin_Xie": "fá", "Âm Hán Việt_Xie": "phiệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ việc cày vỡ đất hoang hoặc làm danh từ chỉ thớ đất được lật lên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腚', '{"9000": "5604.0", "Chữ Trung Quốc": "腚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 肉 | nhục | biểu nghĩa | thịt, thân thể | 定 | định | biểu âm | cho âm dìng | 腚 = 月/肉 (Nhục, biểu nghĩa: thịt/thân thể) + 定 (Định, biểu âm); chữ hình thanh. Phần 肉 chỉ bộ phận cơ thể, phần 定 cho âm dìng. Chữ dùng trong phương ngữ Bắc Kinh chỉ mông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đính\": Thịt (月/肉) ngồi \"đính\" một chỗ — 腚 là cái mông, bộ phận để ngồi cố định. | Gương Hán-Việt | đính (腚 — mông, đít) | Mở khoá kiến thức | Biết 腚 mở khoá vốn từ tiếng Bắc Kinh khẩu ngữ về bộ phận cơ thể, phân biệt với 屁股 chính thức hơn.", "Tự nguyên_Xie": "Chữ hình thanh: 肉 (nhục) biểu nghĩa chỉ thịt/bộ phận thân thể, 定 biểu âm cho âm dìng. Wiktionary xác nhận cấu trúc psc (no_och2=1, tức không tái lập âm Thượng Cổ cho 定). 腚 là từ phương ngữ Bắc Kinh chỉ mông (buttocks), tương đương 屁股. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đít", "Hạng Tần Suất (Jun Da)": "5604.0", "Tần Suất % (Jun Da)": "99.9657371456", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 定", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月定", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "定", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腚", "Unihan_Traditional (Chữ Phồn thể)": "腚", "Pinyin_Xie": "dìng", "Âm Hán Việt_Xie": "đĩnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong khẩu ngữ để chỉ phần mông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('焯', '{"9000": "5605.0", "Chữ Trung Quốc": "焯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 12 | nét | 焯 | chước | tượng hình | chần, luộc sơ — bộ 火, chưa tách rõ thành phần hình thanh trong dạng hiện tại | 焯 thuộc bộ 火 (hoả — lửa). Wiktionary không cung cấp phân tích hình thể rõ ràng. Chữ có hai âm: chāo (chần, chần qua nước sôi) và zhuō/zhuó (sáng rõ). Hình tiểu triện và lục thư thông đã ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chước\": Lửa (火) làm chín \"chước\" — 焯 là động tác chần qua nước sôi nhanh, vừa đủ nhiệt. | Gương Hán-Việt | chước (焯 — chần, luộc sơ) | Mở khoá kiến thức | Biết 焯 mở khoá kỹ thuật nấu ăn Trung Hoa: 焯水 (chần qua nước) — bước cơ bản trong nhiều công thức.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 焯 thuộc bộ 火, chưa có phân tích hình thể từ Wiktionary. Âm chāo dùng trong nấu ăn: chần rau hoặc thực phẩm qua nước sôi trong thời gian rất ngắn. Âm zhuō/zhuó dùng trong văn học nghĩa là sáng rõ, rõ ràng. Chữ tạo muộn, có hình tiểu triện và lục thư thông. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chần, luộc; rõ rệt, hiểu rõ", "Hạng Tần Suất (Jun Da)": "5605.0", "Tần Suất % (Jun Da)": "99.9657862402", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 卓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火卓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "焯", "Unihan_Traditional (Chữ Phồn thể)": "焯", "Pinyin_Xie": "chāo", "Âm Hán Việt_Xie": "trác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ trong nấu ăn để chỉ việc nhúng nhanh thực phẩm vào nước sôi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繻', '{"9000": "5606.0", "Chữ Trung Quốc": "繻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 20 | nét | 繻 | nhu | tượng hình | lụa mịn, tấm lụa xé — bộ 糸 (mịch), chưa tách rõ thành phần hình thanh | 繻 thuộc bộ 糸 (mịch — sợi, tơ lụa). Wiktionary không cung cấp phân tích cấu trúc. Chữ chỉ loại lụa mịn hoặc tấm lụa bị xé, đôi khi dùng làm vé/thẻ giấy. Hình tiểu triện và lục thư thông đã ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhu\": Sợi tơ (糸) mềm mại \"nhu\" nhất — 繻 là loại lụa cao cấp nhất, mịn như nước. | Gương Hán-Việt | nhu (繻 — lụa mịn cao cấp); từ 棄繻 (khí nhu — bỏ thẻ lụa, chí lớn) | Mở khoá kiến thức | Biết 繻 mở khoá thành ngữ 終軍棄繻 (Chung Quân bỏ thẻ lụa — chí khí tuổi trẻ lên đường lập nghiệp).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 繻 thuộc bộ 糸 (sợi lụa). Không có phân tích hình thể Wiktionary. Chữ chỉ loại lụa mịn cao cấp (fine silk gauze) hoặc mảnh lụa dùng làm thẻ thông hành (hàm ý câu chuyện Chung Quân bỏ thẻ). Chữ tạo muộn, chỉ thấy từ tiểu triện. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "绻", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 需", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹需", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "需", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "𦈡", "Unihan_Traditional (Chữ Phồn thể)": "繻", "Pinyin_Xie": "xū", "Âm Hán Việt_Xie": "nhu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ loại lụa mỏng hoặc tấm thẻ thông hành bằng lụa thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('怙', '{"9000": "5607.0", "Chữ Trung Quốc": "怙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 8 | nét | 怙 | hỗ | tượng hình | trông cậy, dựa vào — bộ 忄(tâm), chưa có phân tích Wiktionary | 怙 thuộc bộ 忄(tâm — lòng, tình cảm), chỉ sự trông cậy, tin tưởng vào ai đó. Wiktionary không có anchor cho chữ này. Có hình tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hỗ\": Lòng (忄) luôn hướng về người mình \"hỗ\" trợ và cậy nhờ — 怙 là sự nương tựa tin cậy tuyệt đối. | Gương Hán-Việt | hỗ (怙 — trông cậy); 怙恃 (hỗ thị — cha mẹ, người nương tựa) | Mở khoá kiến thức | Biết 怙 mở khoá từ 怙恃 (cha mẹ — theo nghĩa bóng: người để nương tựa) và 怙恶不悛 (ngoan cố không chịu sửa).", "Tự nguyên_Xie": "Tiểu triện | 怙 thuộc bộ 忄(tâm). Không có phân tích hình thể từ Wiktionary (usedForm = null). Chữ mang nghĩa trông cậy, dựa dẫm vào. Có hình tiểu triện. Phân tích dựa trên thành phần: tâm (忄) gợi ý cảm xúc trông chờ, nương tựa. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trông cậy", "Hạng Tần Suất (Jun Da)": "5607.0", "Tần Suất % (Jun Da)": "99.9658844293", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 古", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄古", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "古", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "怙", "Unihan_Traditional (Chữ Phồn thể)": "怙", "Pinyin_Xie": "hù", "Âm Hán Việt_Xie": "hỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ sự ỷ thế, nương tựa hoặc làm danh từ chỉ cha mẹ trong văn cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羧', '{"9000": "5608.0", "Chữ Trung Quốc": "羧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 13 | nét | 羊 | dương | biểu nghĩa | oxy, từ 氧 (dưỡng) | 夋 | biểu nghĩa | axit, từ 酸 (toan) | 羧 = 羊 (phần rút gọn của 氧 — dưỡng khí/oxy) + 夋 (phần rút gọn của 酸 — toan/axit); chữ hội ý. Đây là chữ hiện đại tạo ra cho hoá học hữu cơ: ghép ý oxy + axit để chỉ nhóm carboxyl (-COOH).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toa\": Nhóm 羧 (toa) = oxy (羊≈氧) + axit (夋≈酸) kết hợp — đúng như công thức -COOH của nhóm carboxyl. | Gương Hán-Việt | toa (羧 — nhóm carboxyl -COOH) | Mở khoá kiến thức | Biết 羧 mở khoá hệ thống thuật ngữ hoá hữu cơ Trung Quốc: 羧酸 (toa toan — carboxylic acid), 羧基 (toa cơ — nhóm carboxyl).", "Tự nguyên_Xie": "Chữ hội ý hiện đại (không có glyph cổ): 羊 rút gọn từ 氧 (dưỡng — oxy) + 夋 rút gọn từ 酸 (toan — axit). Wiktionary xác nhận ls=ic (hội ý). 羧 chỉ nhóm carboxyl (-COOH) trong hoá học hữu cơ. Chữ tạo muộn phục vụ thuật ngữ khoa học hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gốc các-bô-xin (-COOH)", "Hạng Tần Suất (Jun Da)": "5608.0", "Tần Suất % (Jun Da)": "99.9659335239", "GavinGrover_Once (Chiết tự trực tiếp)": "羊 + 夋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰羊夋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羊", "Unihan_Simplified (Chữ Giản thể)": "羧", "Unihan_Traditional (Chữ Phồn thể)": "羧", "Pinyin_Xie": "suō", "Âm Hán Việt_Xie": "thoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các thuật ngữ hóa học để chỉ nhóm chức axit hữu cơ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼙', '{"9000": "5609.0", "Chữ Trung Quốc": "鼙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼓 | Số nét | 21 | nét | 鼙 | bề | tượng hình | trống trận — chữ bộ 鼓, không tách rõ thành phần hình thanh | 鼙 thuộc bộ 鼓 (cổ — trống). Wiktionary không cung cấp phân tích hình thể cụ thể. Chữ chỉ loại trống nhỏ dùng trong quân đội hoặc nghi lễ. Có hình tiểu triện và lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bề\": Tiếng trống 鼓 \"bề bề\" vang lên — 鼙 là trống chiến nhỏ, thúc quân xông trận. | Gương Hán-Việt | bề (鼙 — trống trận nhỏ); 鼙鼓 (bề cổ — trống chiến) | Mở khoá kiến thức | Biết 鼙 mở khoá hình ảnh chiến trường cổ đại Trung Hoa, đặc biệt trong thơ Đường: 漁陽鼙鼓動地來 (trống chiến ngư dương vang trời đất).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 鼙 thuộc bộ 鼓 (trống), chỉ loại trống nhỏ đeo trên lưng ngựa dùng trong chiến trận hoặc lễ nhạc cung đình. Wiktionary chỉ ghi âm đọc và nghĩa mà không phân tích hình thể. Có hình tiểu triện và lục thư thông. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trống trận", "Hạng Tần Suất (Jun Da)": "5609.0", "Tần Suất % (Jun Da)": "99.9659826185", "GavinGrover_Once (Chiết tự trực tiếp)": "鼓 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱鼓卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼓", "Unihan_Simplified (Chữ Giản thể)": "鼙", "Unihan_Traditional (Chữ Phồn thể)": "鼙", "Pinyin_Xie": "pí", "Âm Hán Việt_Xie": "bề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại trống trận nhỏ thời xưa, thường dùng trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('倥', '{"9000": "5610.0", "Chữ Trung Quốc": "倥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 10 | nét | 亻 | nhân | biểu nghĩa | người | 空 | không | biểu âm | cho âm kōng | 倥 = 亻(Nhân, biểu nghĩa: người) + 空 (Không, biểu âm); chữ hình thanh. Phần 亻 chỉ liên quan đến người, phần 空 cho âm kōng. Chữ chỉ người ngu dốt, không biết gì, hoặc trạng thái bức bách.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"không\": Người (亻) mà lòng rỗng \"không\" — 倥 là người ngu dốt, trống rỗng không có tri thức. | Gương Hán-Việt | không (倥 — ngu dốt); 倥偬 (không tổng — bận bức, vội vàng) | Mở khoá kiến thức | Biết 倥 mở khoá từ 倥偬 (bận bức, vội vã) và 倥侗 (ngây ngô, ngu dốt) trong văn học cổ.", "Tự nguyên_Xie": "Chữ hình thanh: 亻(nhân) biểu nghĩa chỉ người, 空 (không) biểu âm cho âm kōng. Wiktionary xác nhận cấu trúc psc. 倥 mang nghĩa ngu dốt, bất lực (倥侗) hoặc bận bức (倥偬 — vội vàng bận rộn). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngu dốt; không biết", "Hạng Tần Suất (Jun Da)": "5610.0", "Tần Suất % (Jun Da)": "99.9660311963", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 空", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻空", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "空", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "倥", "Unihan_Traditional (Chữ Phồn thể)": "倥", "Pinyin_Xie": "kōng", "Âm Hán Việt_Xie": "không", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ để mô tả trạng thái ngu muội hoặc khờ khạo của con người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('亳', '{"9000": "5611.0", "Chữ Trung Quốc": "亳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 亠 | Số nét | 10 | nét | 亳 | bạc | tượng hình | đất Bạc — địa danh lịch sử, chữ độc thể bộ 亠 | 亳 thuộc bộ 亠 (đầu mái nhà), là địa danh chỉ kinh đô của vua Thang (nhà Thương). Wiktionary không cung cấp phân tích cấu trúc. Đây là chữ dùng trong địa danh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạc\": Đất 亳 là nơi vua Thang lập đô — \"bạc\" địa lịch sử ngàn năm, nay là Bạc Châu. | Gương Hán-Việt | bạc (亳 — đất Bạc, Bạc Châu 亳州) | Mở khoá kiến thức | Biết 亳 mở khoá lịch sử nhà Thương và địa danh 亳州 (Bạc Châu, An Huy — quê hương Tào Tháo).", "Tự nguyên_Xie": "Kim văn | Bạch thư | Tiểu triện | 亳 là tên địa danh cổ — kinh đô của vua Thành Thang nhà Thương (khoảng 1600 TCN). Có hình kim văn (Thương), bạch thư và tiểu triện ghi nhận. Ngày nay là Bạc Châu (亳州), tỉnh An Huy, Trung Quốc. Wiktionary không phân tích hình thể chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đất Bạc (kinh đô vua Thang, nay thuộc tỉnh Hà Nam Trung Quốc)", "Hạng Tần Suất (Jun Da)": "5611.0", "Tần Suất % (Jun Da)": "99.9660797741", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 乇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱乇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "亳", "Unihan_Traditional (Chữ Phồn thể)": "亳", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "bạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng chỉ địa danh cổ hoặc dùng trong tên gọi hành chính hiện đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艽', '{"9000": "5612.0", "Chữ Trung Quốc": "艽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 5 | nét | 艽 | giao | tượng hình | cỏ giao, tần giao — bộ 艸, chưa có phân tích cấu trúc từ Wiktionary | 艽 thuộc bộ 艸 (tháu — cỏ). Wiktionary chỉ ghi {{Han etym}} mà không phân tích cụ thể. Có hình tiểu triện. Chữ chỉ cây tần giao (Gentiana macrophylla) dùng trong Đông y.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giao\": Cỏ (艸) mọc hoang giao nhau rối rắm — 艽 là cỏ giao, vị thuốc Đông y quý. | Gương Hán-Việt | giao (艽 — cỏ giao, tần giao); 秦艽 (tần giao — dược liệu) | Mở khoá kiến thức | Biết 艽 mở khoá tên dược liệu 秦艽 (tần giao) trong Đông y — dùng trị phong thấp, đau xương.", "Tự nguyên_Xie": "Tiểu triện | 艽 thuộc bộ 艸 (cỏ). Wiktionary không cung cấp phân tích hình thể. Có hình tiểu triện. 艽 chủ yếu xuất hiện trong tên dược liệu 秦艽 (tần giao) — một loại cỏ Gentiana dùng trong Đông y để trị phong thấp. Chưa có nguồn học thuật rõ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ổ của các con thú; cỏ giao (dùng để làm thuốc)", "Hạng Tần Suất (Jun Da)": "5612.0", "Tần Suất % (Jun Da)": "99.9661283519", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 九", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹九", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "九", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "艽", "Unihan_Traditional (Chữ Phồn thể)": "艽", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "giao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cỏ thuốc hoặc hang ổ hoang dã của thú rừng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荠', '{"9000": "5613.0", "Chữ Trung Quốc": "荠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艸 | tháu | biểu nghĩa | cỏ, thực vật | 齊 | tày | biểu âm | cho âm jì | 荠 = 艸 (Tháu, biểu nghĩa: cỏ/thực vật) + 齊 (Tày, biểu âm); chữ hình thanh. Dạng phồn thể 薺. Phần 艸 chỉ loại thực vật, phần 齊 cho âm jì/qí tuỳ nghĩa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tề\": Cỏ (艸) mọc \"tề\" đồng đều trên cánh đồng — 荠 là loại rau dại mọc tràn lan, hái ăn được. | Gương Hán-Việt | tề (荠 — cây tề thái, rau dại ăn được) | Mở khoá kiến thức | Biết 荠 mở khoá thơ cổ về cây tề thái và hình ảnh người dân hái rau dại trong gian khó.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 艸 (tháu) biểu nghĩa chỉ thực vật, 齊 biểu âm. Dạng phồn thể là 薺. Wiktionary xác nhận cấu trúc psc. Có hình tiểu triện và lục thư thông. 荠 chỉ cây tề thái (Capsella bursa-pastoris — shepherd''s purse) — rau ăn được và cũng có trong 菱角 (củ ấu). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại rau)", "Hạng Tần Suất (Jun Da)": "5613.0", "Tần Suất % (Jun Da)": "99.9661769297", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 齐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹齐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "齐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荠", "Unihan_Traditional (Chữ Phồn thể)": "薺", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "tề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường kết hợp thành từ ghép chỉ loại rau tề thái dùng làm thực phẩm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('昴', '{"9000": "5614.0", "Chữ Trung Quốc": "昴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 9 | nét | 昴 | mão | tượng hình | sao Mão — bộ 日 (nhật), chưa có phân tích cấu trúc từ Wiktionary | 昴 thuộc bộ 日 (nhật — mặt trời/sao). Wiktionary không cung cấp phân tích hình thể chi tiết. Chữ chỉ sao Mão (Pleiades) — một trong Nhị thập bát tú (28 chòm sao). Có hình tiểu triện và lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mão\": Mặt trời (日) của tuổi Mão — 昴 là chòm sao Mão, tụ sáng như một bầy gà con. | Gương Hán-Việt | mão (昴 — sao Mão, chòm Pleiades); Mão Tú (昴宿) | Mở khoá kiến thức | Biết 昴 mở khoá thiên văn học Trung Hoa cổ đại và hệ thống Nhị thập bát tú (二十八宿).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 昴 thuộc bộ 日 (nhật/thiên thể). Wiktionary không phân tích hình thể. Có hình tiểu triện và lục thư thông. 昴 là tên chòm sao Pleiades (Mão Tú — Đầu Lông Xù), một trong 28 chòm sao thiên văn Trung Hoa cổ. Được gọi là 昴宿星团 (Pleiades cluster). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sao Mão (một trong Nhị thập bát tú)", "Hạng Tần Suất (Jun Da)": "5614.0", "Tần Suất % (Jun Da)": "99.9662255075", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 卯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱日卯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "昴", "Unihan_Traditional (Chữ Phồn thể)": "昴", "Pinyin_Xie": "mǎo", "Âm Hán Việt_Xie": "mão", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng chỉ một chòm sao trong thiên văn học cổ đại phương Đông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舨', '{"9000": "5615.0", "Chữ Trung Quốc": "舨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 10 | nét | 舨 | bản | tượng hình | thuyền nhỏ — bộ 舟, không có anchor Wiktionary | 舨 thuộc bộ 舟 (chu — thuyền). Wiktionary không có anchor cho chữ này (usedForm = null). Chữ chỉ loại thuyền nhỏ, thường xuất hiện trong 舢舨 (xan bản — thuyền chèo nhỏ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bản\": Thuyền (舟) làm bằng ván \"bản\" — 舨 là chiếc thuyền gỗ nhỏ, đơn sơ. | Gương Hán-Việt | bản (舨 — thuyền nhỏ); 舢舨 (xan bản — sampan) | Mở khoá kiến thức | Biết 舨 mở khoá từ 舢舨 (sampan) — loại thuyền nhỏ truyền thống vùng Hoa Nam và Đông Nam Á.", "Tự nguyên_Xie": "舨 thuộc bộ 舟 (thuyền). Không có anchor Wiktionary, không có hình glyph cổ. Chữ thường dùng trong tổ hợp 舢舨 (sampan — thuyền gỗ nhỏ của người dân vùng biển Nam Á, Hoa Nam). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: xan bản 舢舨)", "Hạng Tần Suất (Jun Da)": "5615.0", "Tần Suất % (Jun Da)": "99.9662740853", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 反", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟反", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "反", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "舨", "Unihan_Traditional (Chữ Phồn thể)": "舨", "Pinyin_Xie": "bǎn", "Âm Hán Việt_Xie": "bản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và hầu như chỉ xuất hiện trong từ ghép để chỉ loại thuyền nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魈', '{"9000": "5616.0", "Chữ Trung Quốc": "魈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鬼 | Số nét | 16 | nét | 魈 | tiêu | tượng hình | yêu quái núi rừng — bộ 鬼, chưa tách rõ thành phần | 魈 thuộc bộ 鬼 (quỷ — ma quỷ). Wiktionary không cung cấp phân tích hình thể chi tiết. Chữ chỉ loài tinh quái một chân sống trong núi (mountain spirit), hoặc con khỉ đầu chó mandrill.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": Ma quỷ (鬼) réo \"tiêu tiêu\" trong núi — 魈 là con yêu tinh một chân ẩn nấp trong rừng sâu. | Gương Hán-Việt | tiêu (魈 — yêu quái núi); 山魈 (sơn tiêu — mandrill, khỉ đầu chó) | Mở khoá kiến thức | Biết 魈 mở khoá thần thoại yêu quái Trung Hoa và tên loài linh trưởng 山魈 trong sinh vật học.", "Tự nguyên_Xie": "魈 thuộc bộ 鬼 (quỷ). Wiktionary không phân tích hình thể. Chữ chỉ yêu quái núi rừng trong thần thoại Trung Hoa — loài tinh một chân gây hại người. Hiện đại dùng trong 山魈 (sơn tiêu) chỉ con mandrill (khỉ đầu chó). Không có hình glyph cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "yêu quái", "Hạng Tần Suất (Jun Da)": "5616.0", "Tần Suất % (Jun Da)": "99.9663226631", "GavinGrover_Once (Chiết tự trực tiếp)": "鬼 + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鬼肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鬼", "Unihan_Simplified (Chữ Giản thể)": "魈", "Unihan_Traditional (Chữ Phồn thể)": "魈", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài quỷ núi trong truyền thuyết hoặc loài khỉ mặt chó lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醣', '{"9000": "5617.0", "Chữ Trung Quốc": "醣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 17 | nét | 酉 | dấu | biểu nghĩa | nhóm chức có oxy (oxygenated functional group) | 唐 | đường | biểu âm | cho âm táng | 醣 = 酉 (Dấu, biểu nghĩa: nhóm chức có oxy trong hoá hữu cơ) + 唐 (Đường, biểu âm); chữ hình thanh. Bộ 酉 xuất hiện trong nhiều thuật ngữ hoá học như 醇 (alcohol), 醛 (aldehyde), 酮 (ketone). Chữ đồng nghĩa với 糖 (carbohydrate).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đường\": Nhóm oxy (酉) mà nghe âm \"đường\" (唐) — 醣 là đường carbohydrate, ngọt trong hoá học. | Gương Hán-Việt | đường (醣 — đường, carbohydrate); đường huyết, đường phèn | Mở khoá kiến thức | Biết 醣 mở khoá thuật ngữ hoá học Đài Loan: 醣類 (loại đường/carbohydrate), 單醣 (monosaccharide), 多醣 (polysaccharide).", "Tự nguyên_Xie": "Chữ hình thanh: 酉 biểu nghĩa chỉ nhóm chức có oxy trong hoá học hữu cơ, 唐 biểu âm. Wiktionary xác nhận cấu trúc psc. 醣 là từ cổ hơn/phồn thể của 糖, dùng chuyên ngành cho saccharide/carbohydrate. Phổ biến ở Đài Loan và Hồng Kông. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đường", "Hạng Tần Suất (Jun Da)": "5617.0", "Tần Suất % (Jun Da)": "99.9663712409", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 唐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉唐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "唐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醣", "Unihan_Traditional (Chữ Phồn thể)": "醣", "Pinyin_Xie": "táng", "Âm Hán Việt_Xie": "đường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng nhiều trong hóa học để chỉ các hợp chất hữu cơ nhóm đường. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('枵', '{"9000": "5618.0", "Chữ Trung Quốc": "枵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 号 | gào | biểu âm | cho âm xiāo | 枵 = 木 (Mộc, biểu nghĩa: cây/gỗ) + 号 (Gào, biểu âm); chữ hình thanh. Phần 木 chỉ liên quan đến cây/gỗ, phần 号 cho âm xiāo. Chữ chỉ thân cây rỗng hoặc trạng thái trống rỗng, đói bụng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hèo\": Cây (木) mà ruột rỗng, kêu \"hèo hèo\" — 枵 là thân cây rỗng, cũng ví bụng đói rỗng. | Gương Hán-Việt | hèo (枵 — rỗng không, đói bụng); 枵腹 (hèo phúc — bụng đói) | Mở khoá kiến thức | Biết 枵 mở khoá từ 枵腹从公 (bụng đói lo việc công — hình ảnh quan liêm khiết tận tụy).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 木 (mộc) biểu nghĩa chỉ cây/gỗ, 号 biểu âm. Wiktionary xác nhận cấu trúc psc. Có hình tiểu triện. 枵 chỉ thân cây rỗng không (hollow stump), nghĩa mở rộng: trống rỗng, đói bụng (枵腹 — bụng đói rỗng rang). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây rỗng; rỗng không", "Hạng Tần Suất (Jun Da)": "5618.0", "Tần Suất % (Jun Da)": "99.9664198187", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 号", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木号", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "号", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "枵", "Unihan_Traditional (Chữ Phồn thể)": "枵", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "hiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ để mô tả trạng thái trống rỗng hoặc đói bụng trong văn viết. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粜', '{"9000": "5619.0", "Chữ Trung Quốc": "粜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 11 | nét | 粜 | thiếu | tượng hình | bán thóc — dạng giản thể của 糶, chưa tách rõ thành phần | 粜 là dạng giản thể của 糶 (bán thóc ra). Wiktionary ghi là dạng xem lại 糶. Bộ 米 (mễ — gạo). Chỉ có hình tiểu triện. Chữ chỉ hành động bán gạo/thóc từ kho dự trữ ra ngoài.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiếu\": Bán thóc gạo (米) ra — 粜 là đem gạo từ kho ra bán, trái với 籴 (mua gạo vào). | Gương Hán-Việt | thiếu (粜 — bán thóc); thiếu cốc (粜谷 — bán thóc) | Mở khoá kiến thức | Biết 粜 mở khoá cặp đối nghĩa 粜/糴 (bán/mua thóc) trong kinh tế nông nghiệp cổ đại Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 粜 là dạng giản thể của 糶 (thiếu — bán thóc). Có hình tiểu triện. Chữ đối nghịch với 糴 (địch — mua thóc vào). Ghép 出 (xuất — ra) + 米 (mễ — gạo): ý nghĩa là đem gạo ra ngoài bán. Wiktionary không phân tích hình thể riêng cho dạng giản thể. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bán thóc ra", "Hạng Tần Suất (Jun Da)": "5619.0", "Tần Suất % (Jun Da)": "99.9664683965", "GavinGrover_Once (Chiết tự trực tiếp)": "出 + 米", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱出米", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "出", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粜", "Unihan_Traditional (Chữ Phồn thể)": "糶", "Pinyin_Xie": "tiào", "Âm Hán Việt_Xie": "thiếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành vi bán ngũ cốc ra, trái nghĩa với hành vi mua vào. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('甙', '{"9000": "5620.0", "Chữ Trung Quốc": "甙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 弋 | Số nét | 8 | nét | 代 | đại | biểu nghĩa | thay thế | 甘 | cam | biểu nghĩa | ngọt | 甙 = 代 (Đại, biểu nghĩa: thay thế) + 甘 (Cam, biểu nghĩa: ngọt); chữ hội ý. Ý tứ: chất ngọt (甘) được thay thế/biến đổi (代) — chỉ glycoside (đường liên kết với phân tử không đường).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đại\": Ngọt (甘) được \"đại\" thay đổi cấu trúc — 甙 là glycoside, phân tử đường liên kết với nhóm khác. | Gương Hán-Việt | đại (甙 — glycoside) | Mở khoá kiến thức | Biết 甙 mở khoá thuật ngữ hoá dược cổ: từ đồng nghĩa với 苷 (glycoside) và 醣苷.", "Tự nguyên_Xie": "Chữ hội ý: 代 (đại — thay thế) kết hợp với 甘 (cam — ngọt). Wiktionary xác nhận ls=ic (hội ý). 甙 là từ cũ chỉ glycoside trong hoá học hữu cơ — đường liên kết với aglycon. Nay ít dùng, thay bằng 苷. Chữ hiện đại không có glyph cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chất glucô", "Hạng Tần Suất (Jun Da)": "5620.0", "Tần Suất % (Jun Da)": "99.9665164576", "GavinGrover_Once (Chiết tự trực tiếp)": "弋 + 甘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴弋甘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "弋", "Unihan_Simplified (Chữ Giản thể)": "甙", "Unihan_Traditional (Chữ Phồn thể)": "甙", "Pinyin_Xie": "dài", "Âm Hán Việt_Xie": "đại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chuyên ngành hóa học để chỉ hợp chất hữu cơ chứa đường. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('珲', '{"9000": "5621.0", "Chữ Trung Quốc": "珲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 10 | nét | 珲 | huy | tượng hình | ngọc quý sáng rực — dạng giản thể của 琿, bộ 玉 | 珲 là dạng giản thể của 琿 (huy — ngọc sáng đẹp). Wiktionary ghi là giản hoá từ 琿 (thay 車 bằng 车). Bộ 玉 (ngọc). Chủ yếu dùng trong địa danh 珲春 (Huy Xuân, Cát Lâm).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huy\": Ngọc (玉) sáng \"huy\" rực rỡ — 珲 là viên ngọc quý lấp lánh. | Gương Hán-Việt | huy (珲 — ngọc sáng); 珲春 (Huy Xuân — địa danh) | Mở khoá kiến thức | Biết 珲 mở khoá địa danh 珲春 (Huy Xuân) — thành phố cực đông Trung Quốc, giáp 3 nước.", "Tự nguyên_Xie": "珲 là dạng giản thể của 琿, bộ 玉 (ngọc). Wiktionary ghi là 汉字简化 từ 琿. Không có phân tích hình thể riêng. Chữ mang nghĩa ngọc quý sáng rực. Hiện phổ biến nhất trong địa danh 珲春市 (Thành phố Huy Xuân, tỉnh Cát Lâm, giáp Triều Tiên và Nga). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loại ngọc đẹp và quý", "Hạng Tần Suất (Jun Da)": "5621.0", "Tần Suất % (Jun Da)": "99.9665645186", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 军", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王军", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "军", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "珲", "Unihan_Traditional (Chữ Phồn thể)": "琿", "Pinyin_Xie": "huī", "Âm Hán Việt_Xie": "hồn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong tên người hoặc tên địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('杓', '{"9000": "5622.0", "Chữ Trung Quốc": "杓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 7 | nét | 杓 | biêu | tượng hình | cán gáo, cán sao Bắc Đẩu — bộ 木, chưa có phân tích Wiktionary chi tiết | 杓 thuộc bộ 木 (mộc — gỗ). Wiktionary chỉ ghi {{Han etym}} không phân tích chi tiết. Có hình đại triện. Chữ chỉ cái cán của gáo múc nước hoặc ba sao đuôi của chòm Đại Hùng Tinh (chuôi sao Bắc Đẩu).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biêu\": Gỗ (木) làm cán gáo \"biêu\" cong — 杓 là cái cán, từ gáo múc nước đến chuôi sao Bắc Đẩu trên trời. | Gương Hán-Việt | biêu (杓 — cán gáo, chuôi Bắc Đẩu) | Mở khoá kiến thức | Biết 杓 mở khoá hình tượng thiên văn: 杓 chỉ ba sao đuôi Đại Hùng Tinh, dùng để định phương hướng bắc.", "Tự nguyên_Xie": "Đại triện | 杓 thuộc bộ 木. Wiktionary không cung cấp phân tích hình thể. Có hình đại triện (Đại triện — Chou script). Chữ mang hai nghĩa: cán của gáo/muỗng (ladle handle) và ba ngôi sao đuôi của chòm Đại Hùng (chuôi Bắc Đẩu). Chưa có nguồn học thuật rõ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chuôi sao Bắc Đẩu; gạt ra, lôi ra", "Hạng Tần Suất (Jun Da)": "5622.0", "Tần Suất % (Jun Da)": "99.9666125796", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 勺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木勺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "杓", "Unihan_Traditional (Chữ Phồn thể)": "杓", "Pinyin_Xie": "biāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ chuôi sao hoặc động từ chỉ hành động gạt bỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('楸', '{"9000": "5623.0", "Chữ Trung Quốc": "楸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 楸 | thu | tượng hình | cây gỗ thu (Catalpa) — bộ 木, chưa có phân tích hình thanh từ Wiktionary | 楸 thuộc bộ 木 (mộc — cây/gỗ). Wiktionary không cung cấp phân tích hình thể. Có hình tiểu triện. Chữ chỉ cây Catalpa bungei (Manchurian catalpa) hoặc Mallotus japonicus — gỗ cứng dùng làm bàn cờ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thu\": Cây (木) của mùa \"thu\" — 楸 là cây thu, gỗ dùng làm bàn cờ vây quý giá. | Gương Hán-Việt | thu (楸 — cây thu Catalpa); 楸枰 (thu bình — bàn cờ vây) | Mở khoá kiến thức | Biết 楸 mở khoá từ 楸枰 (bàn cờ) và hình ảnh tao nhân mặc khách ngồi đánh cờ dưới cây thu trong thơ cổ.", "Tự nguyên_Xie": "Tiểu triện | 楸 thuộc bộ 木. Wiktionary không phân tích hình thể. Có hình tiểu triện. Chữ chỉ cây thu (Catalpa bungei) — loại cây rụng lá thân gỗ, gỗ cứng đẹp truyền thống dùng làm bàn cờ vây (楸枰). Cũng chỉ Mallotus japonicus. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây gỗ thu (thường dùng để đóng bàn cờ)", "Hạng Tần Suất (Jun Da)": "5623.0", "Tần Suất % (Jun Da)": "99.9666606406", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 秋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木秋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "楸", "Unihan_Traditional (Chữ Phồn thể)": "楸", "Pinyin_Xie": "qiū", "Âm Hán Việt_Xie": "thu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp để chỉ các vật dụng làm từ gỗ thu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('楦', '{"9000": "5624.0", "Chữ Trung Quốc": "楦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 楦 | huyễn | tượng hình | khuôn giày — bộ 木, chưa có phân tích hình thanh từ Wiktionary | 楦 thuộc bộ 木 (mộc — gỗ). Wiktionary không cung cấp phân tích hình thể cụ thể. Có hình tiểu triện và lục thư thông. Chữ chỉ cái khuôn gỗ dùng để làm giày/mũ, hoặc động tác nhét đầy/phồng to.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyễn\": Gỗ (木) đẽo thành khuôn \"huyễn\" — 楦 là cái khuôn giày, dùng để định hình đế và mũ giày. | Gương Hán-Việt | huyễn (楦 — khuôn giày); 鞋楦 (hài huyễn — khuôn giày) | Mở khoá kiến thức | Biết 楦 mở khoá từ 鞋楦 (khuôn giày), 楦头 (đầu khuôn), thành ngữ 麒麟楦 (hình ngoài đẹp nhưng ruột rỗng).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 楦 thuộc bộ 木. Wiktionary không phân tích hình thể. Có hình tiểu triện và lục thư thông. 楦 chỉ cái khuôn gỗ (last/block) dùng để tạo hình giày hoặc mũ. Nghĩa mở rộng: nhét đầy, nhồi phồng. Phương ngữ: ăn no nê (nhồi đầy bụng). | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái khuôn; cốt khuôn; ướm; thử", "Hạng Tần Suất (Jun Da)": "5624.0", "Tần Suất % (Jun Da)": "99.9667087016", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 宣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木宣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "楦", "Unihan_Traditional (Chữ Phồn thể)": "楥", "Pinyin_Xie": "xuàn", "Âm Hán Việt_Xie": "tuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Làm danh từ chỉ cái khuôn đóng giày hoặc làm động từ chỉ việc nong khuôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疃', '{"9000": "5625.0", "Chữ Trung Quốc": "疃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 田 | Số nét | 17 | nét | 田 | điền | biểu nghĩa | ruộng, đồng | 童 | đồng | biểu âm | cho âm tuǎn | 疃 = 田 (Điền, biểu nghĩa: ruộng/đồng) + 童 (Đồng, biểu âm); chữ hình thanh. Phần 田 chỉ đất canh tác/nông thôn, phần 童 cho âm gần tuǎn. Chữ chỉ làng nhỏ/thôn, thường dùng trong địa danh Bắc Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thoản\": Đồng ruộng (田) có trẻ \"đồng\" chơi — 疃 là thôn nhỏ yên bình nơi trẻ con chạy đùa trên đồng. | Gương Hán-Việt | thoản (疃 — thôn ấp, làng nhỏ) | Mở khoá kiến thức | Biết 疃 mở khoá địa danh làng xã vùng Hoa Bắc, đặc biệt Hà Bắc — nhiều làng có tên kết thúc bằng 疃.", "Tự nguyên_Xie": "Chữ hình thanh: 田 (điền) biểu nghĩa chỉ ruộng đồng/nông thôn, 童 biểu âm. Wiktionary xác nhận cấu trúc psc. 疃 chỉ làng/xóm nhỏ, thôn ấp, khu dân cư ngoài thành — thường dùng trong địa danh như X疃 (Thôn X). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đinh thoản 町疃); thôn trang, đồn điền", "Hạng Tần Suất (Jun Da)": "5625.0", "Tần Suất % (Jun Da)": "99.9667567626", "GavinGrover_Once (Chiết tự trực tiếp)": "田 + 童", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰田童", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "童", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "田", "Unihan_Simplified (Chữ Giản thể)": "疃", "Unihan_Traditional (Chữ Phồn thể)": "疃", "Pinyin_Xie": "tuǎn", "Âm Hán Việt_Xie": "thoản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong địa danh hoặc đi kèm từ khác để chỉ làng xóm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛏', '{"9000": "5626.0", "Chữ Trung Quốc": "蛏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 11 | nét | 蛏 | tranh | tượng hình | con trùng trục, hàu nhỏ — dạng giản thể của 蟶, bộ 虫 | 蛏 là dạng giản thể của 蟶 (tranh — razor clam). Wiktionary ghi là 汉字简化 từ 蟶, thay 聖 bằng 圣. Bộ 虫 (trùng). Chỉ loài hàu lông dài (razor clam) — hải sản biển thông dụng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tranh\": Con sâu (虫) dài như ống \"tranh\" — 蛏 là con trùng trục, hình như ống tre nằm trong cát. | Gương Hán-Việt | tranh (蛏 — con trùng trục, razor clam) | Mở khoá kiến thức | Biết 蛏 mở khoá tên hải sản 蛏子 (razor clam) và cách nấu các món hải sản vùng duyên hải Trung Quốc.", "Tự nguyên_Xie": "蛏 là dạng giản thể của 蟶. Wiktionary ghi là giản hoá từ 蟶. Bộ 虫 (trùng — sâu bọ, côn trùng, động vật nhỏ). Razor clam là loài nhuyễn thể hai mảnh vỏ dài, sống chui trong bùn cát. Phổ biến trong ẩm thực Hoa Nam và Đông Nam Á. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con trùng trục, con hàu nhỏ", "Hạng Tần Suất (Jun Da)": "5626.0", "Tần Suất % (Jun Da)": "99.9668048237", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 圣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫圣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛏", "Unihan_Traditional (Chữ Phồn thể)": "蟶", "Pinyin_Xie": "chēng", "Âm Hán Việt_Xie": "sanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loài động vật thân mềm sống ở biển. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠛', '{"9000": "5627.0", "Chữ Trung Quốc": "蠛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 20 | nét | 蠛 | mọt | tượng hình | ruồi nhỏ, côn trùng sinh ra nơi ẩm ướt — bộ 虫, chưa tách rõ thành phần | 蠛 thuộc bộ 虫 (trùng — sâu bọ). Wiktionary không cung cấp phân tích hình thể. Chữ chỉ loài côn trùng nhỏ sinh sản ở nơi ẩm ướt, thường gặp trong tổ hợp 蠛蠓.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mọt\": Sâu (虫) \"mọt\" nhỏ li ti ở chỗ ẩm — 蠛 là côn trùng bé tí sinh ra từ ẩm mốc. | Gương Hán-Việt | mọt (蠛 — ruồi nhỏ, côn trùng ẩm ướt); 蠛蠓 (mọt mồng — ruồi nhỏ) | Mở khoá kiến thức | Biết 蠛 mở khoá từ 蠛蠓 (mọt mồng — loài ruồi nhỏ li ti) thường dùng trong văn học miêu tả vật nhỏ bé tầm thường.", "Tự nguyên_Xie": "蠛 thuộc bộ 虫. Wiktionary chỉ ghi âm đọc và nghĩa cơ bản (rfdef — cần định nghĩa thêm) mà không phân tích hình thể. Chữ chỉ ruồi nhỏ hoặc côn trùng sinh ra ở chỗ ẩm mốc. Chưa có nguồn học thuật rõ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: miệt mông 蠛蠓)", "Hạng Tần Suất (Jun Da)": "5627.0", "Tần Suất % (Jun Da)": "99.9668528847", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 蔑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫蔑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蔑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蠛", "Unihan_Traditional (Chữ Phồn thể)": "蠛", "Pinyin_Xie": "miè", "Âm Hán Việt_Xie": "miệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong từ ghép để chỉ loài côn trùng nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髌', '{"9000": "5628.0", "Chữ Trung Quốc": "髌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 19 | nét | 髌 | bẫn | tượng hình | xương bánh chè — bộ 骨, chưa tách rõ thành phần hình thanh từ Wiktionary | 髌 thuộc bộ 骨 (cốt — xương). Dạng phồn thể là 髕. Wiktionary không phân tích hình thể chi tiết. Chữ chỉ xương bánh chè (patella/kneecap), cũng chỉ hình phạt cổ đại cắt bỏ xương bánh chè.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bẫn\": Xương (骨) ở chỗ \"bẫn\" nhất khi quỳ — 髌 là xương bánh chè, chắn trước đầu gối. | Gương Hán-Việt | bẫn (髌 — xương bánh chè); 髌骨 (bẫn cốt — xương patella) | Mở khoá kiến thức | Biết 髌 mở khoá từ y học 髌骨 (xương bánh chè), 髌骨骨折 (gãy xương bánh chè) — thường gặp trong y tế chấn thương.", "Tự nguyên_Xie": "髌 là dạng giản thể của 髕, bộ 骨 (xương). Wiktionary không phân tích hình thể. Chữ có hai nghĩa: 1) xương bánh chè (patella — xương đầu gối), 2) hình phạt cổ đại cắt xương bánh chè (刖刑 biến thể). Đây là từ y học giải phẫu. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xương bánh chè, xương đầu gối; hình phạt chặt xương bánh chè", "Hạng Tần Suất (Jun Da)": "5628.0", "Tần Suất % (Jun Da)": "99.9669009457", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 宾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨宾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "髌", "Unihan_Traditional (Chữ Phồn thể)": "髕", "Pinyin_Xie": "bìn", "Âm Hán Việt_Xie": "bận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ bộ phận cơ thể hoặc hình phạt thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茔', '{"9000": "5629.0", "Chữ Trung Quốc": "茔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 茔 | doanh | tượng hình | mồ mả, nghĩa trang — dạng giản thể của 塋, bộ 艸 | 茔 là dạng giản thể của 塋 (doanh — mồ mả). Wiktionary ghi dạng gốc là 塋 (bộ 土). Dạng giản 茔 dùng bộ 艸 (tháu). Chữ chỉ nơi chôn cất, mồ mả, nghĩa trang gia tộc. Có hình tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"doanh\": Đất (土) vây \"doanh\" xung quanh mộ phần — 茔 là khu đất mồ mả, nơi an nghỉ của người đã khuất. | Gương Hán-Việt | doanh (茔 — mồ mả); 墳茔 (phần doanh — khu mộ) | Mở khoá kiến thức | Biết 茔 mở khoá từ 先茔 (tiên doanh — mộ tổ tiên), 祖茔 (tổ doanh — nghĩa địa gia tộc) trong văn học cổ và lễ nghi.", "Tự nguyên_Xie": "Tiểu triện | 茔 là dạng giản thể của 塋 (doanh — mồ mả). Dạng gốc 塋 thuộc bộ 土 (thổ — đất). Có hình tiểu triện. Chữ chỉ phần đất mồ mả của gia tộc, nghĩa địa, chỗ chôn cất. 墳塋 (phần doanh — mồ mả), 先塋 (tiên doanh — mộ tổ tiên). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mồ mả", "Hạng Tần Suất (Jun Da)": "5629.0", "Tần Suất % (Jun Da)": "99.9669490067", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "茔", "Unihan_Traditional (Chữ Phồn thể)": "塋", "Pinyin_Xie": "yíng", "Âm Hán Việt_Xie": "doanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ khu đất chôn cất hoặc lăng mộ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诼', '{"9000": "5630.0", "Chữ Trung Quốc": "诼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 10 | nét | 诼 | trác | tượng hình | rèm pha, vu khống — bộ 言 (ngôn), chưa tách rõ thành phần hình thanh từ Wiktionary | 诼 thuộc bộ 言 (ngôn — lời nói). Dạng phồn thể là 諑. Wiktionary không phân tích hình thể chi tiết. Chữ chỉ hành động vu khống, nói xấu, rèm pha.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trác\": Lời (言) nói \"trác\" thẳng vào danh dự người khác — 诼 là lời vu khống, rèm pha ác ý. | Gương Hán-Việt | trác (诼 — rèm pha, vu khống); 謠諑 (dao trác — tin đồn vu khống) | Mở khoá kiến thức | Biết 诼 mở khoá từ 謠諑 (dao trác — tin đồn xấu, lời vu khống) và ngôn ngữ chính trị cổ đại Trung Hoa.", "Tự nguyên_Xie": "诼 là dạng giản thể của 諑, bộ 言 (lời nói). Wiktionary không cung cấp phân tích hình thể chi tiết. Chữ mang nghĩa vu khống, phỉ báng — lời nói ác ý để hại người. Thường gặp trong tổ hợp 謠諑 (dao trác — tin đồn và vu khống). | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lời rèm pha", "Hạng Tần Suất (Jun Da)": "5630.0", "Tần Suất % (Jun Da)": "99.967044612", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 豖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠豖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诼", "Unihan_Traditional (Chữ Phồn thể)": "諑", "Pinyin_Xie": "zhuó", "Âm Hán Việt_Xie": "trác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ việc gièm pha hoặc danh từ chỉ lời nói xấu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嬖', '{"9000": "5631.0", "Chữ Trung Quốc": "嬖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 16 | nét | 辟 | tích | biểu âm | cho âm bì | 女 | nữ | biểu nghĩa | phụ nữ | 嬖 = 辟 (Tích, biểu âm) + 女 (Nữ, biểu nghĩa: phụ nữ); chữ hình thanh. Phần 女 chỉ người phụ nữ được sủng ái, phần 辟 cho âm bì. Chữ chỉ kẻ được vua/chủ sủng ái dù thân phận thấp hèn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bế\": Phụ nữ (女) mà \"bế\" chặt trong lòng vua — 嬖 là kẻ được sủng ái tuyệt đối, dù hèn mọn. | Gương Hán-Việt | bế (嬖 — được sủng ái); 嬖人 (bế nhân — kẻ được vua sủng ái) | Mở khoá kiến thức | Biết 嬖 mở khoá ngôn ngữ cung đình cổ: 嬖人 (bế nhân — kẻ sủng thần), 嬖臣 (bế thần — nịnh thần được sủng).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Chữ hình thanh: 辟 biểu âm cho âm bì, 女 biểu nghĩa chỉ phụ nữ. Wiktionary xác nhận cấu trúc psc. Có hình giáp cốt văn và tiểu triện — rất cổ. 嬖 chỉ kẻ được bề trên sủng ái đặc biệt dù địa vị thấp hèn — thường mang hàm ý tiêu cực (nịnh thần được vua sủng ái). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hèn mà được vua quý", "Hạng Tần Suất (Jun Da)": "5631.0", "Tần Suất % (Jun Da)": "99.9670921562", "GavinGrover_Once (Chiết tự trực tiếp)": "辟 + 女", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱辟女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "嬖", "Unihan_Traditional (Chữ Phồn thể)": "嬖", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Danh từ | 名词 | Thường làm động từ chỉ sự sủng ái thiên vị hoặc tính từ chỉ người được yêu chiều. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耒', '{"9000": "5632.0", "Chữ Trung Quốc": "耒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耒 | Số nét | 6 | nét | 耒 | lồi | tượng hình | cái cày — chữ tượng hình, là chính nó (bộ thủ 127) | 耒 là chữ tượng hình độc thể — hình dáng của cái cày tay thời cổ đại. Là bộ thủ 127, là gốc của nhiều chữ liên quan đến nông cụ như 耕 (cày), 耘 (làm cỏ), 耗 (hao tổn). Không có Wiktionary anchor.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lồi\": Cái cày \"lồi\" ra khỏi đất — 耒 là hình dáng cây cày tay, nguồn gốc của nền nông nghiệp Trung Hoa. | Gương Hán-Việt | lồi (耒 — cái cày); bộ 耒 làm gốc cho 耕 (canh), 耘 (vân) | Mở khoá kiến thức | Biết 耒 mở khoá cả họ chữ nông cụ: 耕 (canh cày), 耘 (làm cỏ), 耙 (bừa), 耜 (lưỡi cày) — tất cả đều có bộ 耒.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 耒 là chữ tượng hình (pictograph) — mô phỏng hình dáng cái cày tay (spade/plow handle). Có hình đại triện và tiểu triện. Bộ thủ 127, là gốc chữ cho nhiều từ nông nghiệp. Không có anchor Wiktionary (usedForm = null). | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1082.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Mộc (075)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình ảnh bàn tay (chữ Thủ số 064 - biến thể) cầm một cái cày làm bằng gỗ (bộ Mộc số 075). Giải thích sự chuyển ý: Đây là chữ Tượng hình. Lỗi là cái cày gỗ của người nông dân.", "Nghĩa Tiếng Việt_Xie": "cái cày", "Hạng Tần Suất (Jun Da)": "5632.0", "Tần Suất % (Jun Da)": "99.9671397004", "GavinGrover_Once (Chiết tự trực tiếp)": "丰 + 八", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴丰八", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "八", "Unihan_Simplified (Chữ Giản thể)": "耒", "Unihan_Traditional (Chữ Phồn thể)": "耒", "Pinyin_Xie": "lěi", "Âm Hán Việt_Xie": "lỗi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ chỉ công cụ làm ruộng thời cổ hoặc làm bộ thủ trong cấu tạo chữ Hán. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜣', '{"9000": "5633.0", "Chữ Trung Quốc": "蜣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 蜣 | khương | tượng hình | bọ hung — bộ 虫, không có anchor Wiktionary | 蜣 thuộc bộ 虫 (trùng — sâu bọ). Không có anchor Wiktionary. Chữ chỉ con bọ hung (dung beetle — bọ lăn phân), thường xuất hiện trong 蜣蜋 (khương lang — dung beetle).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khương\": Sâu (虫) \"khương\" cứng lăn phân — 蜣 là con bọ hung, loài côn trùng tái chế phân bón tuyệt vời của tự nhiên. | Gương Hán-Việt | khương (蜣 — bọ hung); 蜣蜋/蜣螂 (khương lang — dung beetle) | Mở khoá kiến thức | Biết 蜣 mở khoá từ 蜣螂 (khương lang — bọ hung/dung beetle) trong sinh vật học và thơ văn miêu tả thiên nhiên.", "Tự nguyên_Xie": "蜣 thuộc bộ 虫. Không có anchor Wiktionary (usedForm = null). Chữ chỉ con bọ hung (蜣螂/蜣蜋 — dung beetle), loài côn trùng nổi tiếng vì lăn phân thành viên tròn. Biểu tượng linh thiêng của người Ai Cập cổ đại. Chưa có nguồn học thuật về nguồn gốc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khương lang 蜣蜋)", "Hạng Tần Suất (Jun Da)": "5633.0", "Tần Suất % (Jun Da)": "99.9671872447", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 羌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫羌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜣", "Unihan_Traditional (Chữ Phồn thể)": "蜣", "Pinyin_Xie": "qiāng", "Âm Hán Việt_Xie": "khương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ khi kết hợp với chữ khác để chỉ loài bọ hung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笄', '{"9000": "5634.0", "Chữ Trung Quốc": "笄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 10 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 幵 | biểu âm | (biểu âm, đọc gần jī) | 笄 = 竹 (Trúc, biểu nghĩa: tre/trúc) + 幵 (biểu âm). Chữ hình thanh: bộ 竹 cho nghĩa (chiếc trâm làm bằng tre), phần 幵 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kê\": bộ Trúc (竹) gợi chiếc trâm tre cài lên mái tóc người thiếu nữ vừa đến tuổi cập kê. | Gương Hán-Việt | kê trong \"及笄\" (cập kê — tuổi thiếu nữ 15) | Mở khoá kiến thức | Biết 笄 mở khoá \"cập kê\" (及笄之年 — tuổi con gái 15 trưởng thành đội trâm).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: 笄 là chữ hình thanh, gồm 竹 (tre) biểu nghĩa và 幵 biểu âm. Chiếc trâm cài đầu trong lịch sử thường được làm bằng tre hoặc xương. Lễ 及笄 (及笄之年) đánh dấu thiếu nữ 15 tuổi trưởng thành và bắt đầu đội trâm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trâm cài đầu", "Hạng Tần Suất (Jun Da)": "5634.0", "Tần Suất % (Jun Da)": "99.9672347889", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 开", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮开", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "开", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笄", "Unihan_Traditional (Chữ Phồn thể)": "笄", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "kê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ trâm cài tóc hoặc động từ chỉ nghi lễ búi tóc cài trâm khi con gái đến tuổi trưởng thành. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跣', '{"9000": "5635.0", "Chữ Trung Quốc": "跣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 13 | nét | 𧾷 | túc | biểu nghĩa | bàn chân | 先 | tiên | biểu âm | (biểu âm, đọc gần xiǎn) | 跣 = 𧾷 (Túc, biểu nghĩa: bàn chân, dạng biến thể của 足) + 先 (Tiên, biểu âm). Chữ hình thanh: bộ chân cho nghĩa đi chân trần, phần 先 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiển\": bộ Túc (足) là bàn chân, kết hợp 先 (Tiên) — đôi chân đi trước tiên không cần giày, đó là đi chân 跣. | Gương Hán-Việt | tiển trong \"tiển túc\" (跣足 — đi chân trần) | Mở khoá kiến thức | Biết 跣 mở khoá \"tiển túc\" (跣足) và các từ miêu tả đi chân không trong văn ngôn.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: 跣 là chữ hình thanh, gồm 足 (biến thể 𧾷, biểu nghĩa: bàn chân) và 先 (biểu âm). Nghĩa gốc là đi chân trần, không mang giày dép. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đi chân không, đi chân trần", "Hạng Tần Suất (Jun Da)": "5635.0", "Tần Suất % (Jun Da)": "99.9672823331", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 先", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊先", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "先", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跣", "Unihan_Traditional (Chữ Phồn thể)": "跣", "Pinyin_Xie": "xiǎn", "Âm Hán Việt_Xie": "tiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ hoặc tính từ bổ nghĩa cho hành động đi chân đất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钣', '{"9000": "5636.0", "Chữ Trung Quốc": "钣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 钣 | bản | tượng hình | tấm kim loại — chữ không phân tích được qua IDS rõ ràng, là dạng giản thể của 鈑 | 钣 là dạng giản thể của 鈑. Dạng phồn thể 鈑 gồm 金 (Kim, biểu nghĩa: kim loại) + 反 (biểu âm). Chữ hình thanh: kim loại phẳng như tấm bản.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bản\": bộ Kim (钅) là kim loại, cộng ý \"bản\" — tấm kim loại phẳng như một tờ bản mỏng. | Gương Hán-Việt | bản trong \"bản kim\" (钣金 — tấm kim loại, kim loại tấm) | Mở khoá kiến thức | Biết 钣 mở khoá thuật ngữ kỹ thuật 钣金 (sheet metal) thường dùng trong ngành cơ khí, ô tô.", "Tự nguyên_Xie": "Theo Wiktionary: 钣 (phồn thể 鈑) chỉ tấm kim loại phẳng. Cấu tạo 金 (kim loại) + âm 反 (bǎn). Dùng trong kỹ thuật như 钣金 (tấm kim loại, bản kim). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tấm kim loại", "Hạng Tần Suất (Jun Da)": "5636.0", "Tần Suất % (Jun Da)": "99.9673298774", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 反", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅反", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "反", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钣", "Unihan_Traditional (Chữ Phồn thể)": "鈑", "Pinyin_Xie": "bǎn", "Âm Hán Việt_Xie": "bản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các thuật ngữ kỹ thuật cơ khí liên quan đến tấm kim loại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戆', '{"9000": "5637.0", "Chữ Trung Quốc": "戆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 25 | nét | 贛 | biểu âm | (biểu âm, đọc gần gàng) | 心 | tâm | biểu nghĩa | tâm trí, lòng dạ | 戆 = 贛 (biểu âm) + 心 (Tâm, biểu nghĩa: tâm trí). Chữ hình thanh: bộ Tâm cho nghĩa sự ngu đần về mặt tâm trí, phần 贛 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đáng\": bộ Tâm (心) là tâm trí, cộng phần 贛 lớn cồng kềnh — cái tâm trí cồng kềnh mà lại trống rỗng, đó là sự \"đáng\" (ngu đần). | Gương Hán-Việt | đáng trong \"đáng đầu\" (戆头 — kẻ ngốc nghếch, trong tiếng Thượng Hải) | Mở khoá kiến thức | Biết 戆 mở khoá từ phương ngữ 戆头 (ngốc) thường gặp trong văn học miền Giang Nam và tiếng Thượng Hải.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: 戆 (phồn thể 戇) là chữ hình thanh, gồm 贛 (biểu âm) và 心 (biểu nghĩa: tâm trí). Nghĩa là ngu đần, ngốc nghếch, dùng trong phương ngữ miền Đông (Thượng Hải, Giang Nam) để chỉ người kém trí. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngu đần", "Hạng Tần Suất (Jun Da)": "5637.0", "Tần Suất % (Jun Da)": "99.9673769048", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "戆", "Unihan_Traditional (Chữ Phồn thể)": "戇", "Pinyin_Xie": "gàng", "Âm Hán Việt_Xie": "tráng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ đứng trước danh từ hoặc làm vị ngữ để miêu tả tính cách khờ khạo, bướng bỉnh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜉', '{"9000": "5638.0", "Chữ Trung Quốc": "蜉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 蜉 | phù | tượng hình | con phù du — chữ không có nguồn phân tích compound rõ ràng từ Wiktionary | 蜉 có bộ 虫 (côn trùng) và phần 孚 (phù, biểu âm). Dù Wiktionary không ghi rõ công thức, cấu trúc hình thanh với bộ Trùng biểu nghĩa loài côn trùng sống ngắn, phần 孚 cho âm là suy luận hợp lý. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phù\": bộ Trùng (虫) là côn trùng, âm 孚 — con trùng \"phù\" phất, chỉ sống một ngày như bọt nước \"phù\" du. | Gương Hán-Việt | phù trong \"phù du\" (蜉蝣 — phù du, sống ngắn ngủi) | Mở khoá kiến thức | Biết 蜉 mở khoá thành ngữ 蜉蝣撼树 (phù du muốn lay cây lớn — tự lượng sức) và biểu tượng vô thường trong thơ Tô Đông Pha.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi {{Han etym}} mà không cung cấp phân tích cụ thể cho 蜉. Dựa vào cấu trúc: bộ 虫 (côn trùng) và phần âm 孚 (fú). Tên gọi 蜉蝣 (phù du) chỉ loài phù du Ephemeroptera, sống chỉ vài giờ đến vài ngày, là biểu tượng của sự ngắn ngủi trong văn chương cổ điển. chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: phù du 蜉蝣)", "Hạng Tần Suất (Jun Da)": "5638.0", "Tần Suất % (Jun Da)": "99.9674239323", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 孚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫孚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜉", "Unihan_Traditional (Chữ Phồn thể)": "蜉", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong từ ghép để chỉ các loài côn trùng nhỏ như phù du. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喾', '{"9000": "5639.0", "Chữ Trung Quốc": "喾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 學 | học | biểu âm | (biểu âm, gần âm kù) | 告 | cáo | biểu nghĩa | cáo báo, truyền tin | 喾 (phồn thể 嚳) = 學 (Học, biểu âm) + 告 (Cáo, biểu nghĩa: cáo báo). Chữ hình thanh: bộ 告 cho nghĩa báo tin gấp, phần 學 cho âm. Wiktionary lưu ý 告 cũng có thể là thành phần biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khốc\": bộ Cáo (告) là cáo báo, kết hợp 學 — Đế Khốc là vị đế vương \"cáo\" truyền lệnh thiên hạ. | Gương Hán-Việt | khốc trong \"Đế Khốc\" (帝嚳 — Đế Khốc, một trong Ngũ Đế) | Mở khoá kiến thức | Biết 喾 mở khoá Ngũ Đế (五帝) thần thoại Trung Hoa: Hoàng Đế, Chuyên Húc, Đế Khốc, Đế Nghiêu, Đế Thuấn.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: 喾 (phồn thể 嚳) là chữ hình thanh, gồm 學 (biểu âm) và 告 (biểu nghĩa: cáo báo). Là tên của Đế Khốc (帝嚳) — một trong Ngũ Đế thần thoại Trung Quốc. Cũng có nghĩa cổ là báo tin gấp, thông báo nhanh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vội bảo, cấp báo; (tên riêng)", "Hạng Tần Suất (Jun Da)": "5639.0", "Tần Suất % (Jun Da)": "99.9674709597", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 告", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱告", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "喾", "Unihan_Traditional (Chữ Phồn thể)": "嚳", "Pinyin_Xie": "kù", "Âm Hán Việt_Xie": "khốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ riêng chỉ Đế Khốc hoặc làm động từ mang nghĩa thông báo khẩn cấp trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铍', '{"9000": "5640.0", "Chữ Trung Quốc": "铍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 金 | kim | biểu nghĩa | kim loại | 皮 | bì | biểu âm | (biểu âm, đọc gần pī) | 铍 (phồn thể 鈹) = 金 (Kim, biểu nghĩa: kim loại) + 皮 (Bì, biểu âm). Chữ hình thanh: bộ 金 cho nghĩa kim loại/vũ khí, phần 皮 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phi\": bộ Kim (钅) là kim loại, âm 皮 (Bì) — kim loại nhẹ như tờ da (皮), đó là beryllium, nguyên tố \"phi\" thường nhẹ. | Gương Hán-Việt | phi trong \"phi kim\" (铍 — beryllium trong thuật ngữ hóa học Hán-Việt) | Mở khoá kiến thức | Biết 铍 mở khoá tên gọi Hán của các nguyên tố hoá học: bộ 金 + âm phiên âm = tên nguyên tố kim loại.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: 铍 (phồn thể 鈹) là chữ hình thanh, gồm 金 (biểu nghĩa: kim loại) và 皮 (biểu âm, không có âm Old Chinese tương ứng). Nghĩa cổ là thanh kiếm lưỡi ngắn hình dao. Nghĩa hiện đại dùng để phiên âm nguyên tố beryllium (Be), nguyên tố số 4 trong bảng tuần hoàn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái gươm vỏ hình như con dao; cái kim to; nguyên tố berili, Be", "Hạng Tần Suất (Jun Da)": "5640.0", "Tần Suất % (Jun Da)": "99.9675179871", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 皮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅皮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铍", "Unihan_Traditional (Chữ Phồn thể)": "鈹", "Pinyin_Xie": "pī", "Âm Hán Việt_Xie": "phi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ các loại vũ khí cổ, kim châm cứu lớn hoặc nguyên tố hóa học beryli. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陉', '{"9000": "5641.0", "Chữ Trung Quốc": "陉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 7 | nét | 陉 | hình | tượng hình | chỗ đứt quãng của núi — dạng giản thể của 陘, thay 巠 bằng 𢀖 | 陉 là dạng giản thể của 陘. Dạng phồn thể 陘 gồm 阜 (Phụ, gò đất/núi) + 巠 (biểu âm). Chữ hình thanh: bộ Phụ cho nghĩa địa hình núi non, phần 巠 cho âm. Dạng giản thể thay 巠 bằng 𢀖.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hình\": bộ Phụ (阝) là núi gò, hẻm núi bị ngắt \"hình\" ra giữa — 陉 là chỗ đứt quãng trong dãy núi. | Gương Hán-Việt | hình trong \"Tỉnh Hình\" (井陉 — địa danh hẻm núi lịch sử ở Hà Bắc) | Mở khoá kiến thức | Biết 陉 mở khoá địa danh lịch sử 井陉 — nơi Hàn Tín thắng trận lừng lẫy bằng trận \"bối thuỷ\" (배수진).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 陉 là giản thể của 陘. Wiktionary ghi: {{Han simp|陘|f=巠|t=𢀖}} — tức đơn giản hoá thành phần 巠 thành 𢀖. Nghĩa là chỗ đứt quãng, hẻm núi. Dùng trong địa danh như 井陉 (Tỉnh Hình — hẻm núi nổi tiếng ở Hà Bắc, nơi diễn ra nhiều trận đánh lịch sử). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỗ đứt quãng của núi; phần nổi cao lên trên của bếp lò (chỗ để đồ vật)", "Hạng Tần Suất (Jun Da)": "5641.0", "Tần Suất % (Jun Da)": "99.9675644978", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "陉", "Unihan_Traditional (Chữ Phồn thể)": "陘", "Pinyin_Xie": "xíng", "Âm Hán Việt_Xie": "hình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ địa hình hiểm trở giữa các thung lũng hoặc dùng trong địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薹', '{"9000": "5642.0", "Chữ Trung Quốc": "薹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 17 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 臺 | đài | biểu âm | (biểu âm, đọc tái) | 薹 = 艹 (Thảo, biểu nghĩa: cỏ/thực vật) + 臺 (Đài, biểu âm). Chữ hình thanh: bộ cỏ cho nghĩa thực vật, phần 臺 cho âm tái.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đài\": bộ Thảo (艹) là cây cỏ, âm 臺 (Đài) — cái \"đài\" mầm non vươn lên từ cây cỏ, đó là 薹 (cọng hoa, ngọn non). | Gương Hán-Việt | đài trong \"tỏi đài\" (蒜薹 — cọng tỏi, ngọn tỏi) | Mở khoá kiến thức | Biết 薹 mở khoá tên rau quả: 蒜薹 (cọng tỏi), 菜薹 (ngọn cải), 蕓薹 (cải dầu/rapeseed).", "Tự nguyên_Xie": "Theo Wiktionary: 薹 là chữ hình thanh, gồm 艸 (biến thể 艹, biểu nghĩa: cỏ/thực vật) và 臺 (biểu âm). Nghĩa là cọng hoa hoặc chồi non của cây thảo mộc khi còn mềm và ăn được. Dùng trong 蒜薹 (cọng tỏi), 菜薹 (ngọn cải xanh). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nảy mầm", "Hạng Tần Suất (Jun Da)": "5642.0", "Tần Suất % (Jun Da)": "99.9676110085", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 臺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹臺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薹", "Unihan_Traditional (Chữ Phồn thể)": "薹", "Pinyin_Xie": "tái", "Âm Hán Việt_Xie": "đài", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ phần thân non mọc cao lên của một số loại rau để làm thức ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肷', '{"9000": "5643.0", "Chữ Trung Quốc": "肷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 8 | nét | 肷 | khiếm | tượng hình | vùng mạng mỡ giữa bụng và hông — không có nguồn phân tích Wiktionary | 肷 có bộ 月/肉 (Nhục, thịt/thân thể) và phần 欠 (biểu âm, đọc gần qiǎn). Cấu trúc hình thanh suy từ cấu tạo chữ, nhưng Wiktionary không cung cấp phân tích. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiếm\": bộ Nhục (月) là thịt/cơ thể, kết hợp 欠 (thiếu) — vùng \"khiếm\" hụt nhất của thân thể, nơi mỡ ít nhất giữa sườn và hông. | Gương Hán-Việt | khiếm trong \"khiếm nhục\" (肷肉 — thịt vùng sườn non, mạng mỡ) | Mở khoá kiến thức | Biết 肷 mở khoá thuật ngữ giải phẫu và ẩm thực mô tả vùng sườn non, bụng dưới của động vật.", "Tự nguyên_Xie": "Wiktionary không có phân tích cụ thể cho 肷. Bộ 月/肉 (thịt/cơ thể) cho thấy liên quan đến bộ phận cơ thể. Nghĩa là vùng mạng mỡ giữa bụng và hông, thường dùng cho động vật (vùng sườn non). Phần 欠 có thể là biểu âm. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mạng mỡ (giữa bụng và hông, thường dùng đối với các loài thú)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 欠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月欠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "欠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "肷", "Unihan_Traditional (Chữ Phồn thể)": "肷", "Pinyin_Xie": "qiǎn", "Âm Hán Việt_Xie": "hiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ phần da lông mềm ở vùng bụng và hông của các loài thú. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('岵', '{"9000": "5644.0", "Chữ Trung Quốc": "岵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 8 | nét | 岵 | hô | tượng hình | núi có cây cỏ — Wiktionary không cung cấp phân tích compound | 岵 gồm 山 (Sơn, núi) và 古 (Cổ, biểu âm, đọc gần hù). Dù Wiktionary không ghi công thức, cấu trúc hình thanh bộ Sơn + 古 biểu âm là suy luận hợp lý. Chưa có nguồn xác nhận chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hô\": bộ Sơn (山) là núi, âm 古 (Cổ) — ngọn núi \"hô\" xưa cũ phủ cây xanh, nơi người con leo lên ngóng trông về cha. | Gương Hán-Việt | hô trong \"陟岵\" (trèo núi có cây — nhớ cha, trong Kinh Thi) | Mở khoá kiến thức | Biết 岵 mở khoá bài thơ 陟岵 trong Kinh Thi — nỗi nhớ cha mẹ của con trai đi lính xa nhà.", "Tự nguyên_Xie": "Wiktionary chỉ cung cấp phát âm và từ ghép cho 岵, không phân tích cấu tạo. Nghĩa là ngọn núi có cây cỏ tươi tốt (đối lập với 屺 — núi trơ không cây). Cặp 陟岵陟屺 trong Kinh Thi diễn tả nỗi nhớ cha mẹ của con trai đi xa. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "núi có cây cỏ", "Hạng Tần Suất (Jun Da)": "5644.0", "Tần Suất % (Jun Da)": "99.9677040298", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 古", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山古", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "古", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岵", "Unihan_Traditional (Chữ Phồn thể)": "岵", "Pinyin_Xie": "hù", "Âm Hán Việt_Xie": "hỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ này làm danh từ chỉ ngọn núi có cây cối tốt tươi, thường dùng trong văn thơ cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瓴', '{"9000": "5645.0", "Chữ Trung Quốc": "瓴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 瓦 | Số nét | 9 | nét | 瓴 | linh | tượng hình | lọ đất đựng nước; ngói máng — Wiktionary không phân tích compound | 瓴 gồm 令 (Lệnh, biểu âm, đọc gần líng) và 瓦 (Ngõa, ngói/đồ gốm). Dù Wiktionary không ghi công thức, cấu trúc hình thanh bộ Ngõa + 令 biểu âm là suy luận hợp lý từ cấu tạo chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"linh\": bộ Ngõa (瓦) là đồ gốm/ngói, âm Lệnh (令) — cái bình đất \"linh\" đựng nước hoặc viên ngói máng trên mái. | Gương Hán-Việt | linh trong \"cao ốc kiến linh\" (高屋建瓴 — từ trên cao dốc nước xuống, có lợi thế áp đảo) | Mở khoá kiến thức | Biết 瓴 mở khoá thành ngữ 高屋建瓴 — chiếm thế cao, uy hiếp từ trên xuống, thường dùng trong phân tích chiến lược.", "Tự nguyên_Xie": "Wiktionary cung cấp phát âm và nghĩa cho 瓴 nhưng không phân tích cấu tạo. Nghĩa: (1) bình đất đựng nước cổ tay cầm dài, (2) ngói máng hình lõm dẫn nước trên mái. Nổi tiếng trong thành ngữ 高屋建瓴 — từ trên cao đổ nước xuống như xối, ví tư thế chiếm ưu thế hoàn toàn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "viên ngói bò; lọ đựng nước có quai thời xưa", "Hạng Tần Suất (Jun Da)": "5645.0", "Tần Suất % (Jun Da)": "99.9677505405", "GavinGrover_Once (Chiết tự trực tiếp)": "令 + 瓦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰令瓦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "瓦", "Unihan_Simplified (Chữ Giản thể)": "瓴", "Unihan_Traditional (Chữ Phồn thể)": "瓴", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ này làm danh từ chỉ loại ngói ống hoặc bình chứa nước thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荽', '{"9000": "5646.0", "Chữ Trung Quốc": "荽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 妥 | thoả | biểu âm | (biểu âm, đọc gần suī) | 荽 = 艹 (Thảo, biểu nghĩa: thực vật) + 妥 (Thoả, biểu âm). Chữ hình thanh: bộ Thảo cho nghĩa loài cỏ/thực vật, phần 妥 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuy\": bộ Thảo (艹) là cỏ cây, âm 妥 (Thoả) — loài cỏ \"tuy\" nhỏ mà mùi thơm mạnh, đó là rau mùi/ngò rí. | Gương Hán-Việt | tuy trong \"hồ tuy\" (胡荽 — rau mùi, ngò rí) | Mở khoá kiến thức | Biết 荽 mở khoá tên cổ điển của rau mùi/ngò rí: 胡荽 (hồ tuy) — \"hồ\" chỉ nguồn gốc từ vùng Tây Vực.", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary: 荽 là chữ hình thanh, gồm 艸 (biến thể 艹, biểu nghĩa: thực vật) và 妥 (biểu âm). Dùng trong 胡荽 (hồ tuy) — tên cổ của rau mùi/ngò rí (coriander, Coriandrum sativum). Cây này có nguồn gốc từ vùng Trung Đông, nhập vào Trung Quốc qua con đường Tơ lụa, nên có tiền tố \"hồ\" (胡 — ngoại lai). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hồ tuy 胡荽)", "Hạng Tần Suất (Jun Da)": "5646.0", "Tần Suất % (Jun Da)": "99.9677965343", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 妥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹妥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "妥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荽", "Unihan_Traditional (Chữ Phồn thể)": "荽", "Pinyin_Xie": "suī", "Âm Hán Việt_Xie": "tuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ này làm danh từ chỉ rau mùi, thường dùng trong từ ghép hồ tuy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('怫', '{"9000": "5647.0", "Chữ Trung Quốc": "怫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 8 | nét | 怫 | phật | tượng hình | uất ức, tức giận — Wiktionary không phân tích compound | 怫 gồm 忄 (Tâm biên, biểu nghĩa: cảm xúc/tâm trạng) và 弗 (Phất, biểu âm, đọc gần fú). Cấu trúc hình thanh bộ Tâm + 弗 biểu âm là suy luận từ tự dạng, Wiktionary không ghi rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phật\": bộ Tâm biên (忄) là cảm xúc, âm 弗 (Phất) — \"phật\" lòng, cảm giác uất ức không thoát được, như bị chặn lại (弗 = không được). | Gương Hán-Việt | phật trong \"phật nhiên\" (怫然 — nổi giận đột ngột) | Mở khoá kiến thức | Biết 怫 mở khoá từ \"怫然\" (phật nhiên) thường gặp trong văn ngôn cổ điển miêu tả cơn giận bùng phát.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi {{Han etym}} không phân tích cụ thể cho 怫. Bộ 忄 (Tâm biên) cho thấy liên quan đến cảm xúc; phần 弗 (Phất) là biểu âm. Nghĩa là uất ức, tức giận, buồn bực không thoát ra được. Dùng trong 怫然 (phật nhiên — nổi giận đột ngột). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "uất, tức", "Hạng Tần Suất (Jun Da)": "5647.0", "Tần Suất % (Jun Da)": "99.9678425282", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 弗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄弗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "怫", "Unihan_Traditional (Chữ Phồn thể)": "怫", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Từ này làm tính từ biểu thị trạng thái tức giận hoặc uất ức trong lòng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钭', '{"9000": "5648.0", "Chữ Trung Quốc": "钭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 钭 | đẩu | tượng hình | bình đựng rượu thời xưa — không có nguồn Wiktionary | 钭 gồm 钅 (Kim biên, biểu nghĩa: kim loại) và 斗 (Đẩu, biểu âm, đọc gần tǒu). Cấu trúc hình thanh bộ Kim + 斗 biểu âm là suy luận từ tự dạng. Wiktionary không cung cấp phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đẩu\": bộ Kim (钅) là kim loại, âm 斗 (Đẩu) — cái \"đẩu\" kim loại đựng rượu thời xưa. | Gương Hán-Việt | đẩu trong \"đẩu thị\" (钭氏 — họ Đẩu) | Mở khoá kiến thức | Biết 钭 nhận diện họ hiếm gặp Đẩu (钭) trong gia phả và văn bản lịch sử Trung Hoa.", "Tự nguyên_Xie": "Wiktionary không có mục cho 钭 (không có phân tích cấu tạo). Bộ 钅 (kim loại) cho thấy là đồ vật bằng kim loại. Nghĩa là bình đựng rượu thời cổ đại. Cũng dùng làm họ (姓氏): họ Đẩu. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một đồ đựng rượu thời xưa; họ Đẩu", "Hạng Tần Suất (Jun Da)": "5648.0", "Tần Suất % (Jun Da)": "99.9678885221", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 斗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅斗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钭", "Unihan_Traditional (Chữ Phồn thể)": "鈄", "Pinyin_Xie": "tǒu", "Âm Hán Việt_Xie": "đẩu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ này làm danh từ chỉ dụng cụ đong rượu thời xưa hoặc dùng làm họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窀', '{"9000": "5649.0", "Chữ Trung Quốc": "窀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 9 | nét | 窀 | truân | tượng hình | huyệt mộ — Wiktionary không phân tích compound | 窀 gồm 穴 (Huyệt, bộ: hang/hốc) và 屯 (Truân, biểu âm, đọc gần zhūn). Cấu trúc hình thanh bộ Huyệt + 屯 biểu âm là suy luận từ tự dạng. Wiktionary không ghi rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"truân\": bộ Huyệt (穴) là hầm hốc, âm 屯 (Truân) — cái huyệt \"truân\" sâu trong đất, nơi an nghỉ cuối cùng. | Gương Hán-Việt | truân trong \"truân tịch\" (窀穸 — huyệt mộ, chỗ chôn cất) | Mở khoá kiến thức | Biết 窀 mở khoá từ văn ngôn 窀穸 (truân tịch) thường gặp trong bi văn, điếu văn cổ điển.", "Tự nguyên_Xie": "Đại triện | Wiktionary cho thấy 窀 hầu như chỉ dùng trong từ 窀穸 (truân tịch). Bộ 穴 (hầm, hang) gợi ý liên quan đến huyệt mộ. Nghĩa của 窀穸 là huyệt mộ, chỗ chôn cất. Từ này xuất hiện trong 左传 và văn ngôn cổ điển. Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: truân tịch 窀穸)", "Hạng Tần Suất (Jun Da)": "5649.0", "Tần Suất % (Jun Da)": "99.967934516", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 屯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴屯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窀", "Unihan_Traditional (Chữ Phồn thể)": "窀", "Pinyin_Xie": "zhūn", "Âm Hán Việt_Xie": "truân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Từ này thường kết hợp thành từ ghép truân tịch để chỉ việc chôn cất người chết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缯', '{"9000": "5650.0", "Chữ Trung Quốc": "缯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 15 | nét | 缯 | tăng | tượng hình | vải lụa — dạng giản thể của 繒 | 缯 là dạng giản thể của 繒. Dạng phồn thể 繒 gồm 糸 (Mịch, biểu nghĩa: sợi tơ/lụa) và 曾 (Tằng, biểu âm). Chữ hình thanh: bộ tơ lụa cho nghĩa vải lụa, phần 曾 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tăng\": bộ Mịch (糸) là sợi tơ lụa, âm Tằng (曾) — vải lụa \"tăng\" từ thời xa xưa (曾 = đã từng), loại lụa thô dày của người xưa. | Gương Hán-Việt | tăng trong \"tăng bạch\" (繒帛 — lụa vải, hàng tơ lụa tổng hợp) | Mở khoá kiến thức | Biết 缯 mở khoá từ cổ điển 布帛 (bố bạch) và 缯帛 (tăng bạch) — các loại vải thô và lụa trong văn ngôn.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary: 缯 (phồn thể 繒) chỉ các loại vải lụa. Cấu tạo 糸 (tơ lụa) + 曾 (biểu âm). Nghĩa là lụa, vải tơ tằm. Trong lịch sử, các tộc phương Bắc (Bạch Man) mặc áo vải lụa trắng. Cũng là họ tên địa danh 鄫 (nước Tằng cổ đại). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trói, buộc; lụa dày", "Hạng Tần Suất (Jun Da)": "5650.0", "Tần Suất % (Jun Da)": "99.9679805098", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 曾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟曾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缯", "Unihan_Traditional (Chữ Phồn thể)": "繒", "Pinyin_Xie": "zēng", "Âm Hán Việt_Xie": "tăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Từ này làm danh từ chỉ các loại tơ lụa nói chung thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('倬', '{"9000": "5651.0", "Chữ Trung Quốc": "倬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 10 | nét | 倬 | xác | tượng hình | rõ rệt, lớn lao — Wiktionary không phân tích compound | 倬 gồm 亻 (Nhân biên, biểu nghĩa: người) và 卓 (Trác, biểu âm, đọc gần zhuō). Cấu trúc hình thanh bộ Nhân + 卓 biểu âm là suy luận từ tự dạng. Wiktionary không ghi rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xác\": bộ Nhân (亻) là người, âm 卓 (Trác) — người \"xác\" thực nổi bật, cao vời trác tuyệt. | Gương Hán-Việt | xác trong \"倬彼\" (xác bỉ — rực rỡ kia, trong Kinh Thi) | Mở khoá kiến thức | Biết 倬 nhận ra câu thơ Kinh Thi 倬彼雲漢 — Ngân Hà rực rỡ, biểu tượng của sự huy hoàng trong thơ cổ.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary cung cấp nghĩa và ví dụ cho 倬 nhưng không phân tích cấu tạo. Nghĩa: (1) rõ ràng, lớn lao, vĩ đại (văn học); (2) xinh đẹp, duyên dáng (nghĩa cổ). Dùng trong Kinh Thi: 倬彼雲漢，昭回于天 (Rực rỡ thay dải Ngân Hà, sáng ngời xoay chuyển trên trời). | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rõ rệt, lớn lao", "Hạng Tần Suất (Jun Da)": "5651.0", "Tần Suất % (Jun Da)": "99.9680259869", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 卓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻卓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "倬", "Unihan_Traditional (Chữ Phồn thể)": "倬", "Pinyin_Xie": "zhuō", "Âm Hán Việt_Xie": "trác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Từ này làm tính từ miêu tả vẻ ngoài to lớn, rõ ràng hoặc rực rỡ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('摭', '{"9000": "5652.0", "Chữ Trung Quốc": "摭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 14 | nét | 摭 | trích | tượng hình | nhặt lên, thu thập — Wiktionary không phân tích compound | 摭 gồm 扌 (Thủ biên, biểu nghĩa: tay/hành động tay) và 庶/石 (biểu âm). Dù Wiktionary không ghi công thức, bộ Thủ cho nghĩa hành động nhặt, lượm bằng tay là rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trích\": bộ Thủ biên (扌) là tay, âm 庶 (Thứ/trích) — dùng tay \"trích\" nhặt từng thứ một, thu lượm cẩn thận. | Gương Hán-Việt | trích trong \"trích thập\" (摭拾 — lượm nhặt, thu thập) | Mở khoá kiến thức | Biết 摭 mở khoá từ văn ngôn 摭拾 (trích thập) và tên sách cổ 摭言 (Trích Ngôn — tuyển lời hay đời Đường).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary cung cấp nghĩa và ví dụ cho 摭 nhưng không phân tích cấu tạo. Nghĩa là nhặt lên, thu thập, lượm lặt. Dùng trong 摭拾 (lượm nhặt), 摭言 (nhặt lời hay, thu thập lời nói). Sách 摭言 của Vương Định Bảo đời Đường là tuyển tập giai thoại văn học. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lượm; nhặt; lấy", "Hạng Tần Suất (Jun Da)": "5652.0", "Tần Suất % (Jun Da)": "99.968071464", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 庶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌庶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "庶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "摭", "Unihan_Traditional (Chữ Phồn thể)": "摭", "Pinyin_Xie": "zhí", "Âm Hán Việt_Xie": "chích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Từ này làm động từ chỉ hành động nhặt lấy hoặc thu thập tài liệu, thông tin. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('帔', '{"9000": "5653.0", "Chữ Trung Quốc": "帔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 8 | nét | 巾 | can | biểu nghĩa | vải, khăn | 皮 | bì | biểu âm | (biểu âm, đọc gần pèi) | 帔 = 巾 (Can, biểu nghĩa: vải/khăn) + 皮 (Bì, biểu âm). Chữ hình thanh: bộ Cân cho nghĩa đồ vải/trang phục, phần 皮 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phi\": bộ Cân (巾) là vải, âm 皮 (Bì) — tấm vải \"phi\" phơi trên vai người phụ nữ quý tộc, đó là 帔 choàng vai. | Gương Hán-Việt | phi trong \"hà phi\" (霞帔 — áo choàng ráng mây của mệnh phụ) | Mở khoá kiến thức | Biết 帔 mở khoá trang phục cung đình 霞帔 và 凤冠霞帔 (mũ phụng áo ráng) — trang phục hôn lễ cổ điển cao quý nhất.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: 帔 là chữ hình thanh, gồm 巾 (biểu nghĩa: vải) và 皮 (biểu âm). Là loại áo choàng dài không tay của phụ nữ thời xưa, cài phía trước. Nổi tiếng nhất trong 霞帔 (hà phi) — áo choàng ráng mây của mệnh phụ phu nhân, biểu tượng địa vị cao quý. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vải choàng vai (thời xưa)", "Hạng Tần Suất (Jun Da)": "5653.0", "Tần Suất % (Jun Da)": "99.9681169411", "GavinGrover_Once (Chiết tự trực tiếp)": "巾 + 皮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巾皮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "帔", "Unihan_Traditional (Chữ Phồn thể)": "帔", "Pinyin_Xie": "pèi", "Âm Hán Việt_Xie": "bí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ này làm danh từ chỉ loại khăn hoặc áo choàng vai của phụ nữ thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('楝', '{"9000": "5654.0", "Chữ Trung Quốc": "楝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 柬 | giản | biểu âm | (biểu âm, đọc gần liàn) | 楝 = 木 (Mộc, biểu nghĩa: cây/gỗ) + 柬 (Giản, biểu âm). Chữ hình thanh: bộ Mộc cho nghĩa loài cây, phần 柬 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"luyện\": bộ Mộc (木) là cây, âm 柬 (Giản) — cây \"luyện\" (xoan) gỗ dùng rèn luyện nhiều đồ dùng, hoa tím nhỏ đặc trưng. | Gương Hán-Việt | luyện trong \"khổ luyện\" (苦楝 — cây xoan đắng, Melia azedarach) | Mở khoá kiến thức | Biết 楝 mở khoá tên thực vật 苦楝 (cây xoan đắng) và 楝树 (cây xoan) — loài cây dân gian quen thuộc.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: 楝 là chữ hình thanh, gồm 木 (biểu nghĩa: cây) và 柬 (biểu âm). Chỉ cây xoan (Melia azedarach) thuộc họ Xoan (Meliaceae). Cây xoan là loài cây ăn sâu vào văn hoá Việt Nam và Trung Hoa — hoa tím nhỏ, mùi thơm nhẹ, báo hiệu mùa hè. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây xoan", "Hạng Tần Suất (Jun Da)": "5654.0", "Tần Suất % (Jun Da)": "99.9681624182", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 柬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木柬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "柬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "楝", "Unihan_Traditional (Chữ Phồn thể)": "楝", "Pinyin_Xie": "liàn", "Âm Hán Việt_Xie": "luyện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ này làm danh từ chỉ cây xoan, thường dùng trong tên gọi các bộ phận của cây. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痱', '{"9000": "5655.0", "Chữ Trung Quốc": "痱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 13 | nét | 痱 | phí | tượng hình | rôm sảy; trúng gió — Wiktionary không phân tích compound | 痱 gồm 疒 (bộ bệnh tật) và 費/非 (biểu âm, đọc gần fèi). Dù Wiktionary không ghi công thức, bộ 疒 cho nghĩa bệnh/tình trạng cơ thể là rõ ràng. Chưa có nguồn xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phí\": bộ bệnh (疒) là bệnh tật, âm 非/費 (Phi/Phí) — bệnh ngoài da \"phí\" phải chịu đựng mùa hè nóng bức, đó là rôm sảy. | Gương Hán-Việt | phí trong \"phí tử\" (痱子 — rôm sảy) | Mở khoá kiến thức | Biết 痱 nhận ra tên bệnh 痱子 (rôm sảy) và 风痱 (trúng gió) trong y học cổ truyền và dân gian.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary cung cấp nghĩa và từ đồng nghĩa cho 痱 nhưng không phân tích cấu tạo. Bộ 疒 (bệnh tật). Nghĩa: (1) rôm sảy (prickly heat) — phát ban da mùa hè; (2) trúng gió (风痱). Từ thông dụng là 痱子 (rôm sảy). Bệnh phổ biến ở trẻ em trong thời tiết nóng ẩm. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bị trúng gió", "Hạng Tần Suất (Jun Da)": "5655.0", "Tần Suất % (Jun Da)": "99.9682078953", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 非", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒非", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "非", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痱", "Unihan_Traditional (Chữ Phồn thể)": "疿", "Pinyin_Xie": "fèi", "Âm Hán Việt_Xie": "phỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ này làm danh từ chỉ chứng bệnh rôm sảy ngoài da hoặc chứng tê liệt do trúng gió. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚶', '{"9000": "5656.0", "Chữ Trung Quốc": "蚶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 11 | nét | 虫 | trùng | biểu nghĩa | côn trùng, sinh vật nhỏ | 甘 | cam | biểu âm | (biểu âm, đọc gần hān) | 蚶 = 虫 (Trùng, biểu nghĩa: sinh vật nhỏ/động vật biển) + 甘 (Cam, biểu âm). Chữ hình thanh: bộ Trùng cho nghĩa loài động vật (sò), phần 甘 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàm\": bộ Trùng (虫) là sinh vật biển, âm 甘 (Cam) — con sò \"hàm\" vị ngọt (甘) của biển, đó là sò huyết 蚶. | Gương Hán-Việt | hàm trong \"mao hàm\" (毛蚶 — sò lông/sò huyết) | Mở khoá kiến thức | Biết 蚶 mở khoá tên hải sản 毛蚶 (sò lông), 蚶子 (sò huyết) thường gặp trong thực đơn hải sản Trung Hoa.", "Tự nguyên_Xie": "Theo Wiktionary: 蚶 là chữ hình thanh, gồm 虫 (biểu nghĩa: côn trùng/sinh vật) và 甘 (biểu âm). Chỉ con sò huyết (ark clam, Tegillarca granosa), loài nhuyễn thể hai vỏ. Tên 甘 biểu âm cũng gợi ý vị ngọt (甘 = ngọt) của sò huyết. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con sò", "Hạng Tần Suất (Jun Da)": "5656.0", "Tần Suất % (Jun Da)": "99.9682533724", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 甘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫甘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚶", "Unihan_Traditional (Chữ Phồn thể)": "蚶", "Pinyin_Xie": "hān", "Âm Hán Việt_Xie": "ham", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các loài sò hoặc làm thành phần trong tên món ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螬', '{"9000": "5657.0", "Chữ Trung Quốc": "螬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 17 | nét | 螬 | tào | tượng hình | ấu trùng bọ xít, sâu đất — Wiktionary không phân tích compound | 螬 gồm 虫 (Trùng, biểu nghĩa: côn trùng) và 曹 (Tào, biểu âm, đọc gần cáo). Cấu trúc hình thanh bộ Trùng + 曹 biểu âm là suy luận từ tự dạng. Wiktionary không ghi rõ công thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tào\": bộ Trùng (虫) là côn trùng, âm 曹 (Tào) — con \"tào\" (ấu trùng bọ hung) nằm trong đất như đám lính (曹 = bầy đoàn). | Gương Hán-Việt | tào trong \"tề tào\" (蠐螬 — ấu trùng bọ hung) | Mở khoá kiến thức | Biết 螬 mở khoá từ y học cổ truyền 蠐螬 — ấu trùng bọ hung, được dùng trong dược liệu truyền thống.", "Tự nguyên_Xie": "Wiktionary cho thấy 螬 hầu như chỉ dùng trong từ 蠐螬 (tề tào). Bộ 虫 (côn trùng). Nghĩa: ấu trùng của bọ hung (scarab beetle grub, Holotrichia), sống trong đất ăn rễ cây. Trong y học cổ truyền, 蠐螬 có thể dùng làm thuốc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tề tào 蠐螬,蛴螬)", "Hạng Tần Suất (Jun Da)": "5657.0", "Tần Suất % (Jun Da)": "99.9682988495", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 曹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫曹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螬", "Unihan_Traditional (Chữ Phồn thể)": "螬", "Pinyin_Xie": "cáo", "Âm Hán Việt_Xie": "tào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường xuất hiện trong từ ghép để chỉ các loại ấu trùng côn trùng sống dưới đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髑', '{"9000": "5658.0", "Chữ Trung Quốc": "髑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 22 | nét | 骨 | cốt | biểu nghĩa | xương | 蜀 | thục | biểu âm | (biểu âm, đọc gần dú) | 髑 = 骨 (Cốt, biểu nghĩa: xương) + 蜀 (Thục, biểu âm). Chữ hình thanh: bộ Cốt cho nghĩa xương/hộp sọ, phần 蜀 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"độc\": bộ Cốt (骨) là xương, âm 蜀 (Thục) — cái xương \"độc\" đầu, hộp sọ trơ trọi trong 髑髏. | Gương Hán-Việt | độc trong \"độc lâu\" (髑髏 — hộp sọ người) | Mở khoá kiến thức | Biết 髑 mở khoá từ 髑髏 (độc lâu) thường gặp trong văn học Phật giáo, truyện kiếm hiệp và từ vựng giải phẫu học cổ.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary: 髑 là chữ hình thanh, gồm 骨 (biểu nghĩa: xương) và 蜀 (biểu âm). Hầu như chỉ dùng trong từ 髑髏 (độc lâu) — hộp sọ người. Từ này gắn với hình ảnh cái chết, tử thi, được dùng nhiều trong văn học võ hiệp, Phật giáo và Đạo giáo. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: độc lâu 髑髏,髑髅)", "Hạng Tần Suất (Jun Da)": "5658.0", "Tần Suất % (Jun Da)": "99.9683443266", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 蜀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨蜀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蜀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "髑", "Unihan_Traditional (Chữ Phồn thể)": "髑", "Pinyin_Xie": "dú", "Âm Hán Việt_Xie": "độc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu kết hợp với chữ lâu để tạo thành từ ghép chỉ đầu lâu người chết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼗', '{"9000": "5659.0", "Chữ Trung Quốc": "鼗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼓 | Số nét | 19 | nét | 鼗 | đào | tượng hình | trống cơm — Wiktionary không phân tích compound | 鼗 có bộ 鼓 (Cổ, trống) và phần 兆 (biểu âm, đọc gần táo). Cấu trúc hình thanh bộ Cổ cho nghĩa nhạc cụ gõ, phần 兆 cho âm là suy luận từ tự dạng. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đào\": bộ Cổ (鼓) là trống, âm 兆 (Triệu/đào) — cái trống \"đào\" lắc qua lắc lại, âm thanh rung động như điềm triệu (兆). | Gương Hán-Việt | đào trong \"đào cổ\" (鼗鼓 — trống lắc cơm) | Mở khoá kiến thức | Biết 鼗 nhận ra tên nhạc cụ cổ Trung Hoa: trống lắc 鼗鼓, một trong những nhạc cụ có tuổi đời lâu nhất trong âm nhạc cung đình.", "Tự nguyên_Xie": "Wiktionary cung cấp nghĩa và từ ghép cho 鼗 nhưng không phân tích cấu tạo. Nghĩa là trống lắc (pellet drum) — loại trống có hai viên bi buộc vào hai bên, khi lắc quay thì gõ vào mặt trống. Còn gọi là trống cơm hoặc lăng-đăng. Dùng trong âm nhạc cung đình và dân gian Trung Quốc từ thời thượng cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái trống cơm", "Hạng Tần Suất (Jun Da)": "5659.0", "Tần Suất % (Jun Da)": "99.968434764", "GavinGrover_Once (Chiết tự trực tiếp)": "兆 + 鼓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱兆鼓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼓", "Unihan_Simplified (Chữ Giản thể)": "鼗", "Unihan_Traditional (Chữ Phồn thể)": "鞀", "Pinyin_Xie": "táo", "Âm Hán Việt_Xie": "đào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại nhạc cụ gõ cổ truyền của Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狷', '{"9000": "5660.0", "Chữ Trung Quốc": "狷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 10 | nét | 狷 | quyên | tượng hình | ngay thẳng, bồng bột — Wiktionary không phân tích compound | 狷 gồm 犭 (Khuyển biên, biểu nghĩa: chó/tính khí) và 囧/卷 (biểu âm, đọc gần juàn). Cấu trúc hình thanh bộ Khuyển + biểu âm là suy luận từ tự dạng. Wiktionary không ghi rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyên\": bộ Khuyển (犭) là tính khí, âm 卷 (Quyển/quyên) — tính khí \"quyên\" cao ngạo, không chịu sai, như người không chịu ô nhiễm. | Gương Hán-Việt | quyên trong \"cuồng quyên\" (狂狷 — bồng bột và quá cẩn thận, hai cực trong Luận Ngữ) | Mở khoá kiến thức | Biết 狷 mở khoá khái niệm triết học Nho gia 狂狷 trong Luận Ngữ — Khổng Tử bàn về hai loại cá tính khác cực.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary cung cấp nghĩa cho 狷 nhưng không phân tích cấu tạo. Bộ 犭 (chó/tính khí động vật). Nghĩa: (1) bồng bột, bốc đồng; (2) thu mình, quá thận trọng; (3) ngay thẳng về nhân cách. Dùng trong 狂狷 (Khổng Tử bàn về hai cực trong Luận Ngữ: người bồng bột và người quá cẩn thận). | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngay thẳng, không làm việc xấu", "Hạng Tần Suất (Jun Da)": "5660.0", "Tần Suất % (Jun Da)": "99.9684797243", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 肙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭肙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狷", "Unihan_Traditional (Chữ Phồn thể)": "狷", "Pinyin_Xie": "juàn", "Âm Hán Việt_Xie": "quyến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ chỉ tính cách con người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('殛', '{"9000": "5661.0", "Chữ Trung Quốc": "殛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 歹 | Số nét | 12 | nét | 殛 | cực | tượng hình | xử tử, giết — Wiktionary không phân tích compound | 殛 gồm 歹 (Đãi, biểu nghĩa: xương khô/cái chết) và 亟 (Cực, biểu âm, đọc gần jí). Cấu trúc hình thanh bộ Đãi cho nghĩa liên quan đến cái chết, phần 亟 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cực\": bộ Đãi (歹) là cái chết, âm 亟 (Cực) — hình phạt \"cực\" độ, xử tử người. | Gương Hán-Việt | cực trong \"cực hình\" (殛刑 — hình phạt cực nặng, xử tử) | Mở khoá kiến thức | Biết 殛 nhận ra điển cố lịch sử 鯀殛禹興 (Cổn bị giết, Vũ lên thay) — câu chuyện về Đại Vũ trị thủy thời thượng cổ.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary cung cấp nghĩa và ví dụ cổ điển cho 殛. Bộ 歹 (cái chết/xương khô). Nghĩa: (1) xử tử, giết; (2) giam cầm suốt đời. Dùng trong văn ngôn cổ điển: 鯀殛而禹興 (Cổn bị xử tử, Vũ lên thay) trong Tả Truyện. Đây là điển cố lịch sử Trung Hoa về Đại Vũ trị thủy. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giết tróc; án tử hình, xử tử", "Hạng Tần Suất (Jun Da)": "5661.0", "Tần Suất % (Jun Da)": "99.9685246846", "GavinGrover_Once (Chiết tự trực tiếp)": "歹 + 亟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰歹亟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "歹", "Unihan_Simplified (Chữ Giản thể)": "殛", "Unihan_Traditional (Chữ Phồn thể)": "殛", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "cức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết cổ để chỉ việc thiên lôi hoặc vua chúa trừng phạt kẻ có tội. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裉', '{"9000": "5662.0", "Chữ Trung Quốc": "裉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 11 | nét | 裉 | cấn | tượng hình | nách áo, đường may nách — không có nguồn Wiktionary | 裉 gồm 衤 (Y biên, biểu nghĩa: quần áo) và 艮 (Cấn, biểu âm, đọc gần kèn). Cấu trúc hình thanh bộ Y biên cho nghĩa phần áo, phần 艮 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cấn\": bộ Y biên (衤) là áo, âm 艮 (Cấn) — chỗ \"cấn\" (vướng, khó chịu) nhất khi mặc áo là nách áo 裉. | Gương Hán-Việt | cấn trong \"nách áo\" — đường may nối tay và thân áo | Mở khoá kiến thức | Biết 裉 nhận ra thuật ngữ may vá dân gian chỉ phần nách áo — kiến thức cần thiết khi đọc hướng dẫn may mặc truyền thống.", "Tự nguyên_Xie": "Wiktionary không có mục cho 裉. Bộ 衤 (Y biên, quần áo) cho thấy liên quan đến trang phục. Nghĩa là đường khâu/nách áo — phần may nối tay áo và thân áo. Dùng trong may vá dân gian. Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nách áo", "Hạng Tần Suất (Jun Da)": "5662.0", "Tần Suất % (Jun Da)": "99.9685696449", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 艮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤艮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "艮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裉", "Unihan_Traditional (Chữ Phồn thể)": "裉", "Pinyin_Xie": "kèn", "Âm Hán Việt_Xie": "khẳng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong ngành may mặc để chỉ phần nách của trang phục. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粝', '{"9000": "5663.0", "Chữ Trung Quốc": "粝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 11 | nét | 粝 | lệ | tượng hình | gạo thô chưa giã kỹ — Wiktionary chỉ ghi Han etym | 粝 là dạng giản thể của 糲. Dạng phồn thể 糲 gồm 米 (Mễ, biểu nghĩa: gạo) và 厲 (biểu âm). Chữ hình thanh: bộ Mễ cho nghĩa gạo thô, phần 厲 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lệ\": bộ Mễ (米) là gạo, âm 厲 (Lệ) — hạt gạo \"lệ\" thô ráp (厲 = sắc bén, thô), chưa giã trắng tinh. | Gương Hán-Việt | lệ trong \"lệ thực\" (粝食 — bữa ăn thô đạm, sống giản dị) | Mở khoá kiến thức | Biết 粝 mở khoá thành ngữ 粝食粗衣 (lệ thực thô y — ăn thô mặc vải, cuộc sống đạm bạc) thường gặp trong văn ngôn.", "Tự nguyên_Xie": "Lục thư thông | Wiktionary chỉ ghi {{Han etym}} cho 粝 (phồn thể 糲) mà không phân tích. Bộ 米 (gạo). Nghĩa là gạo thô, gạo giã chưa kỹ, gạo lứt — đối lập với gạo trắng tinh. Trong văn ngôn, 粝食 (lệ thực) chỉ bữa ăn đạm bạc, nghèo khó. Biểu tượng của cuộc sống giản dị, khổ hạnh. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gạo giã chưa kỹ", "Hạng Tần Suất (Jun Da)": "5663.0", "Tần Suất % (Jun Da)": "99.9686146052", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 厉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米厉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粝", "Unihan_Traditional (Chữ Phồn thể)": "糲", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm tính từ bổ nghĩa cho danh từ chỉ lương thực thô sơ, đạm bạc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萋', '{"9000": "5664.0", "Chữ Trung Quốc": "萋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 萋 | thê | tượng hình | cỏ xanh tươi tốt — Wiktionary không phân tích compound | 萋 gồm 艹 (Thảo, biểu nghĩa: cỏ/thực vật) và 妻 (Thê, biểu âm, đọc gần qī). Cấu trúc hình thanh bộ Thảo cho nghĩa cỏ cây tươi tốt, phần 妻 cho âm. Wiktionary không ghi rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thê\": bộ Thảo (艹) là cỏ cây, âm 妻 (Thê) — cỏ \"thê\" xanh mướt như người vợ trẻ (妻) xinh tươi. | Gương Hán-Việt | thê trong \"thê thê\" (萋萋 — cỏ xanh mướt, rậm rạp) | Mở khoá kiến thức | Biết 萋 mở khoá thơ cổ: 萋萋滿別情 (thê thê tràn đầy tình ly biệt) — câu thơ nổi tiếng của Lý Bạch về chia tay.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary cung cấp nghĩa cho 萋 nhưng không phân tích cấu tạo. Bộ 艹 (cỏ). Nghĩa: cỏ cây tươi tốt, um tùm. Dùng trong 萋萋 (thê thê — cỏ xanh mướt) — từ láy miêu tả vẻ xanh tươi. Nổi tiếng trong thơ Lý Bạch: 又送王孫去，萋萋滿別情 (lại tiễn người đi, cỏ xanh mướt đầy tình chia ly). | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ xanh xanh", "Hạng Tần Suất (Jun Da)": "5664.0", "Tần Suất % (Jun Da)": "99.9686595655", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 妻", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹妻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "妻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "萋", "Unihan_Traditional (Chữ Phồn thể)": "萋", "Pinyin_Xie": "qī", "Âm Hán Việt_Xie": "thê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ miêu tả cảnh sắc thiên nhiên cây cỏ xanh tươi trong văn thơ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葭', '{"9000": "5665.0", "Chữ Trung Quốc": "葭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葭 | già | tượng hình | cỏ lau — Wiktionary chỉ ghi Han etym | 葭 gồm 艹 (Thảo, biểu nghĩa: cỏ/thực vật) và 叚 (Hà, biểu âm, đọc gần jiā). Cấu trúc hình thanh bộ Thảo + 叚 biểu âm là suy luận từ tự dạng. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"già\": bộ Thảo (艹) là cỏ, âm 叚 (Hà/già) — cỏ \"già\" lau xanh bên bờ sông, nơi người thơ tìm người yêu không gặp. | Gương Hán-Việt | già trong \"kiêm già\" (蒹葭 — sậy và lau, trong Kinh Thi) | Mở khoá kiến thức | Biết 葭 mở khoá bài thơ Kinh Thi 蒹葭 — một trong những bài thơ tình đẹp nhất cổ đại: cỏ lau xanh, sương trắng, tìm người thương không gặp.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi {{Han etym}} không phân tích cụ thể cho 葭. Bộ 艹 (cỏ). Nghĩa là cỏ lau non (cây lau mới mọc, Phragmites communis). Nổi tiếng trong Kinh Thi, bài 蒹葭 (Kiêm Già) — cỏ lau xanh xanh, hình ảnh tìm người thương không gặp. Cũng dùng để chỉ sáo trúc trong văn học. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ lau, cỏ gai", "Hạng Tần Suất (Jun Da)": "5665.0", "Tần Suất % (Jun Da)": "99.9687045258", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 叚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹叚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葭", "Unihan_Traditional (Chữ Phồn thể)": "葭", "Pinyin_Xie": "jiā", "Âm Hán Việt_Xie": "gia", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn học cổ để chỉ cây lau hoặc tượng trưng cho tình thân quyến. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衽', '{"9000": "5666.0", "Chữ Trung Quốc": "衽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 9 | nét | 衽 | nhẫm | tượng hình | vạt áo — Wiktionary không phân tích compound | 衽 gồm 衤 (Y biên, biểu nghĩa: quần áo) và 壬 (Nhâm, biểu âm, đọc gần rèn). Cấu trúc hình thanh bộ Y biên cho nghĩa phần áo, phần 壬 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhẫm\": bộ Y biên (衤) là áo, âm 壬 (Nhâm) — vạt \"nhẫm\" bên trái hay phải áo, phân biệt văn hoá Hoa và Di. | Gương Hán-Việt | nhẫm trong \"tả nhẫm\" (左衽 — vạt trái, cách mặc của người Di) | Mở khoá kiến thức | Biết 衽 mở khoá khái niệm lịch sử 左衽右衽 — vạt áo trái (người Di) vs vạt áo phải (người Hán), phân biệt văn hoá quan trọng trong cổ văn.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary cung cấp phát âm và từ ghép cho 衽 nhưng không phân tích cấu tạo. Bộ 衤 (quần áo). Nghĩa: (1) vạt áo — phần trước và sau của áo; (2) chiếu ngủ. Nổi tiếng trong 左衽 (tả nhẫm — vạt áo bên trái) — cách mặc của các tộc di (người ngoại tộc), đối lập với 右衽 (hữu nhẫm — vạt phải) của người Hán. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vạt áo; cái chiếu", "Hạng Tần Suất (Jun Da)": "5666.0", "Tần Suất % (Jun Da)": "99.9687494861", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 壬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤壬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "壬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "衽", "Unihan_Traditional (Chữ Phồn thể)": "衽", "Pinyin_Xie": "rèn", "Âm Hán Việt_Xie": "nhẫm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ vạt áo truyền thống hoặc làm động từ với nghĩa là cài vạt áo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳢', '{"9000": "5667.0", "Chữ Trung Quốc": "鳢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 21 | nét | 鳢 | lễ | tượng hình | cá lóc — Wiktionary không phân tích compound | 鳢 là dạng giản thể của 鱧. Dạng phồn thể 鱧 gồm 魚 (Ngư, biểu nghĩa: cá) và 豊 (Lễ, biểu âm, đọc gần lǐ). Chữ hình thanh: bộ Ngư cho nghĩa loài cá, phần 豊 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lễ\": bộ Ngư (鱼) là cá, âm 豊 (Lễ) — con cá \"lễ\" to lớn đen bóng, hung hãn như ông lớn (豊 = phong phú, lớn). | Gương Hán-Việt | lễ trong \"ô lễ\" (乌鱧 — cá lóc đen, cá chuối) | Mở khoá kiến thức | Biết 鳢 nhận ra tên khoa học/cổ điển của cá lóc trong văn bản Trung Hoa: 鱧魚, 烏鱧, 黑鱧.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary cung cấp nghĩa cho 鳢 (phồn thể 鱧) nhưng không phân tích cấu tạo. Bộ 魚 (cá). Nghĩa là cá lóc đầu rắn (northern snakehead, Channa argus). Cá lóc là loài cá nước ngọt hung dữ, săn mồi mạnh, thường nuôi ở ao hồ. Quen thuộc trong văn hoá ẩm thực Việt Nam (cá lóc, cá chuối) và Trung Quốc (乌鱧 — cá đen). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá chuối, cá quả, cá lóc", "Hạng Tần Suất (Jun Da)": "5667.0", "Tần Suất % (Jun Da)": "99.9687944464", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 豊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼豊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳢", "Unihan_Traditional (Chữ Phồn thể)": "鱧", "Pinyin_Xie": "lǐ", "Âm Hán Việt_Xie": "lễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài cá lóc, thường kết hợp trong các từ ghép chỉ tên cá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('傧', '{"9000": "5668.0", "Chữ Trung Quốc": "傧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 12 | nét | 傧 | tân | tượng hình | tiếp đón khách — dạng giản thể của 儐 | 傧 là dạng giản thể của 儐. Dạng phồn thể 儐 gồm 亻 (Nhân biên, biểu nghĩa: người) và 賓 (Tân, biểu âm). Chữ hình thanh: bộ Nhân cho nghĩa vai trò của người, phần 賓 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tân\": bộ Nhân (亻) là người, âm 賓 (Tân) — người chuyên lo việc \"tân\" tiếp đón, dẫn khách trong hôn lễ. | Gương Hán-Việt | tân trong \"tân tướng\" (傧相 — phù dâu phù rể trong đám cưới) | Mở khoá kiến thức | Biết 傧 mở khoá từ hôn lễ 傧相 (tân tướng) — phù dâu phù rể trong đám cưới truyền thống Trung Hoa.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Wiktionary chỉ ghi {{Han etym}} không phân tích cụ thể cho 傧 (phồn thể 儐). Bộ 亻 (người). Nghĩa là người tiếp đón khách; phù dâu/phù rể (người đưa đón trong hôn lễ). Dùng trong 傧相 (tân tướng — phù dâu phù rể trong đám cưới truyền thống). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "người tiếp tân", "Hạng Tần Suất (Jun Da)": "5668.0", "Tần Suất % (Jun Da)": "99.96883889", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 宾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻宾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "傧", "Unihan_Traditional (Chữ Phồn thể)": "儐", "Pinyin_Xie": "bīn", "Âm Hán Việt_Xie": "tân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ người tiếp tân hoặc động từ chỉ việc đón tiếp khách khứa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喁', '{"9000": "5669.0", "Chữ Trung Quốc": "喁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 喁 | ngụm | tượng hình | cá ngó miệng; tiếng đáp — Wiktionary không phân tích compound | 喁 gồm 口 (Khẩu, biểu nghĩa: miệng/tiếng nói) và 禺 (Ngung, biểu âm, đọc gần yóng). Cấu trúc hình thanh bộ Khẩu cho nghĩa miệng/tiếng, phần 禺 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngụm\": bộ Khẩu (口) là miệng, âm 禺 (Ngung) — cái miệng \"ngụm\" mở ra hớp không khí như cá ngóc miệng lên mặt nước. | Gương Hán-Việt | ngụm trong \"喁喁細語\" (ngụm ngụm tế ngữ — thì thầm nhỏ) | Mở khoá kiến thức | Biết 喁 mở khoá từ thơ văn 喁喁 — tiếng thì thầm nhỏ nhẹ, hình ảnh cặp đôi tâm sự riêng tư.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary cung cấp nghĩa cho 喁 nhưng không phân tích cấu tạo. Bộ 口 (miệng). Nghĩa: (1) cá ngóc miệng lên mặt nước thở; (2) tiếng đáp lại nhỏ. Dùng trong 喁喁 (ngụm ngụm — tiếng thì thầm, nói nhỏ) và 喁喁細語 (thì thầm riêng tư). Cũng thấy trong 噞喁 — cá ngóc miệng. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "môi cá dẩu lên; tiếng nhịp", "Hạng Tần Suất (Jun Da)": "5669.0", "Tần Suất % (Jun Da)": "99.9688833335", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 禺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口禺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "喁", "Unihan_Traditional (Chữ Phồn thể)": "喁", "Pinyin_Xie": "yóng", "Âm Hán Việt_Xie": "vu, ngung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ miêu tả động tác há miệng thở của cá hoặc làm danh từ chỉ âm thanh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嫘', '{"9000": "5670.0", "Chữ Trung Quốc": "嫘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 14 | nét | 嫘 | luy | tượng hình | họ Luy; Luy Tổ — Wiktionary không phân tích compound | 嫘 gồm 女 (Nữ, biểu nghĩa: phụ nữ) và 累 (Luy, biểu âm). Cấu trúc hình thanh bộ Nữ cho nghĩa liên quan đến người phụ nữ, phần 累 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"luy\": bộ Nữ (女) là phụ nữ, âm 累 (Luy) — người phụ nữ \"luy\" (cần mẫn tích lũy) Luy Tổ, người dạy nhân loại dệt lụa từ tơ tằm. | Gương Hán-Việt | luy trong \"Luy Tổ\" (嫘祖 — vợ Hoàng Đế, tổ mẫu nghề tơ lụa) | Mở khoá kiến thức | Biết 嫘 mở khoá truyền thuyết Luy Tổ (嫘祖) — nhân vật thần thoại sáng tạo nghề tơ lụa Trung Hoa, được thờ trong ngành dệt.", "Tự nguyên_Xie": "Wiktionary cung cấp thông tin về 嫘 nhưng không phân tích cấu tạo. Bộ 女 (phụ nữ). Chủ yếu là tên riêng: 嫘祖 (Luy Tổ) — vợ của Hoàng Đế, được truyền thuyết cho là người đầu tiên dạy dân trồng dâu nuôi tằm, se tơ dệt lụa. Được tôn thờ là tổ mẫu nghề dệt lụa Trung Hoa. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Luy", "Hạng Tần Suất (Jun Da)": "5670.0", "Tần Suất % (Jun Da)": "99.968927777", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 累", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女累", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "累", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "嫘", "Unihan_Traditional (Chữ Phồn thể)": "嫘", "Pinyin_Xie": "léi", "Âm Hán Việt_Xie": "luy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng trong tên người thời cổ đại như Luy Tổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罟', '{"9000": "5671.0", "Chữ Trung Quốc": "罟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 10 | nét | 罟 | cổ | tượng hình | lưới bắt cá/chim — Wiktionary không phân tích compound | 罟 gồm 网/罒 (Võng, biểu nghĩa: lưới) và 古 (Cổ, biểu âm, đọc gần gǔ). Cấu trúc hình thanh bộ Võng cho nghĩa dụng cụ lưới bắt, phần 古 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cổ\": bộ Võng (罒) là lưới, âm 古 (Cổ) — cái lưới \"cổ\" xưa dùng bắt cá, biểu tượng nghề đánh bắt truyền thống. | Gương Hán-Việt | cổ trong \"cổ sư\" (罟師 — người đánh lưới, ngư dân) | Mở khoá kiến thức | Biết 罟 mở khoá câu Mạnh Tử 數罟不入洿池 — tư tưởng bảo vệ thiên nhiên sớm nhất trong triết học Nho gia.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary cung cấp nghĩa và ví dụ cổ điển cho 罟. Bộ 罒/网 (lưới). Nghĩa: (1) lưới bắt cá hoặc chim; (2) dùng lưới bắt. Trích Mạnh Tử: 數罟不入洿池 (lưới mắt nhỏ không vào ao sâu — bảo vệ nguồn lợi thủy sản). Từ này gắn với tư tưởng bảo vệ thiên nhiên trong Nho gia. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái lưới; hình phạt", "Hạng Tần Suất (Jun Da)": "5671.0", "Tần Suất % (Jun Da)": "99.9689722205", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + 古", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒古", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "古", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "罟", "Unihan_Traditional (Chữ Phồn thể)": "罟", "Pinyin_Xie": "gǔ", "Âm Hán Việt_Xie": "cổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ lưới cá hoặc động từ chỉ việc dùng lưới đánh bắt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钌', '{"9000": "5672.0", "Chữ Trung Quốc": "钌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 7 | nét | 钌 | liễu | tượng hình | nguyên tố ruthenium — dạng giản thể của 釕 | 钌 là dạng giản thể của 釕. Dạng phồn thể 釕 gồm 金 (Kim, biểu nghĩa: kim loại) và 了 (Liễu, biểu âm). Chữ hình thanh: bộ Kim cho nghĩa nguyên tố kim loại, phần 了 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liễu\": bộ Kim (钅) là kim loại, âm 了 (Liễu) — nguyên tố kim loại \"liễu\" nhẹ, đó là ruthenium, kim loại quý hiếm trong nhóm platin. | Gương Hán-Việt | liễu trong \"liễu nguyên tố\" (钌 — ruthenium, Ru, nguyên tử số 44) | Mở khoá kiến thức | Biết 钌 mở khoá mẫu đặt tên nguyên tố trong Hán ngữ: bộ 金 + âm phiên âm ngắn = tên nguyên tố kim loại quý.", "Tự nguyên_Xie": "Wiktionary chỉ ghi {{Han etym}} không phân tích cụ thể cho 钌 (phồn thể 釕). Bộ 金/钅 (kim loại). Nghĩa là nguyên tố ruthenium (Ru), nguyên tử số 44. Tên chữ Hán 釕 phiên âm âm \"liễu\" để dịch âm \"ruthenium\". Cũng dùng trong 钌铞 (liễu điếu nhi) — móc kim loại nhỏ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố ruteni, Ru; (xem: liễu điếu nhi 釕銱,钌铞)", "Hạng Tần Suất (Jun Da)": "5672.0", "Tần Suất % (Jun Da)": "99.969016664", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 了", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅了", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "了", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钌", "Unihan_Traditional (Chữ Phồn thể)": "釕", "Pinyin_Xie": "liǎo", "Âm Hán Việt_Xie": "liễu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ nguyên tố hóa học hoặc cái móc cửa trong khẩu ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裼', '{"9000": "5673.0", "Chữ Trung Quốc": "裼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 13 | nét | 裼 | tích | tượng hình | áo mặc sát thân, vạt mở để lộ da | 裼 là chữ độc thể — bộ 衣 (y, áo) là gốc cấu tạo, chỉ loại áo mặc sát thân bên trong có thể mở vạt. Chưa có phân tích hình thanh / hội ý rõ ràng từ Wiktionary; xếp vào chữ tạo muộn, chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": bộ 衣 (áo) kết hợp với phần bên trong — gợi hình ảnh lớp áo lót mỏng sát da, mở vạt theo nghi lễ. | Gương Hán-Việt | tích — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 裼 mở khoá từ vựng lễ nghi cổ Trung Hoa về y phục truyền thống.", "Tự nguyên_Xie": "Tiểu triện | 裼 (âm Hán-Việt: tích) là chữ biểu thị loại áo trong, mặc sát da, có thể mở vạt để lộ ngực — thường thấy trong văn cổ lễ nghi. Wiktionary chỉ ghi nhận phát âm và thiếu thông tin tạo tự. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "裼", "Hạng Tần Suất (Jun Da)": "5673.0", "Tần Suất % (Jun Da)": "99.9690611076", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 易", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤易", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "易", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裼", "Unihan_Traditional (Chữ Phồn thể)": "裼", "Pinyin_Xie": "tì", "Âm Hán Việt_Xie": "thế, tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ miêu tả hành động cởi trần hoặc phanh áo ngoài. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('愦', '{"9000": "5674.0", "Chữ Trung Quốc": "愦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 12 | nét | 愦 | quẫn | tượng hình | tâm trạng rối loạn, mê muội | 愦 là dạng giản thể của 憒. Chữ gốc 憒 gồm bộ 忄(tâm, biểu nghĩa: tâm trí) + 潰 lược bỏ thành phần (biểu âm). Cấu trúc hình thanh — bộ 心/忄 chỉ trạng thái tâm lý, phần còn lại cho âm đọc. Wiktionary không phân tích chi tiết; cấu trúc suy luận từ dạng phồn thể 憒.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quẫn\": bộ 忄(tâm) báo hiệu trạng thái tâm trí — như người quẫn bách, đầu óc rối mù không lối thoát. | Gương Hán-Việt | quẫn — như \"quẫn trí\" (tâm trí tối tăm, không minh mẫn) | Mở khoá kiến thức | Biết 愦 mở khoá từ vựng miêu tả trạng thái tâm lý tiêu cực trong văn cổ Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 愦 (âm Hán-Việt suy luận: quẫn) là dạng giản lược của 憒, mang nghĩa tâm trí rối loạn, mê muội, lẫn lộn. Wiktionary ghi nhận dạng phồn thể 憒 với nghĩa ''confused; befuddled; muddle-headed'' trong văn học cổ. Chưa có nguồn học thuật xác nhận tạo tự chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rối ruột, nhầm lẫn", "Hạng Tần Suất (Jun Da)": "5674.0", "Tần Suất % (Jun Da)": "99.9691055511", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 贵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄贵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "愦", "Unihan_Traditional (Chữ Phồn thể)": "憒", "Pinyin_Xie": "kuì", "Âm Hán Việt_Xie": "hội", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho tâm trạng hoặc trạng thái tinh thần hỗn loạn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝽', '{"9000": "5675.0", "Chữ Trung Quốc": "蝽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 蝽 | xuân | tượng hình | loài bọ xít (côn trùng hút nhựa cây) | 蝽 là chữ tạo muộn, không có glyph cổ trong giáp cốt hay kim văn. Bộ 虫 (trùng, biểu nghĩa: côn trùng) là cấu phần chính. Wiktionary không có phân tích tạo tự. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xuân\": bộ 虫 (trùng, côn trùng) — loài bọ xít xuất hiện vào mùa xuân khi cây đâm chồi, hút nhựa non. | Gương Hán-Việt | xuân — ít dùng độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 蝽 mở khoá từ vựng côn trùng học và thuật ngữ nông nghiệp Trung Hoa.", "Tự nguyên_Xie": "蝽 (âm Hán-Việt: xuân, đọc chūn) chỉ loài bọ xít — côn trùng thuộc họ Pentatomidae hoặc các họ liên quan, hút nhựa cây hoặc thực vật. Bộ 虫 xác nhận đây là chữ chỉ côn trùng. Không có glyph cổ; chữ tạo muộn, chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "loài bọ xít", "Hạng Tần Suất (Jun Da)": "5675.0", "Tần Suất % (Jun Da)": "99.9691499946", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 春", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫春", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "春", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝽", "Unihan_Traditional (Chữ Phồn thể)": "蝽", "Pinyin_Xie": "chūn", "Âm Hán Việt_Xie": "xuẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các loài côn trùng thuộc họ bọ xít. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锗', '{"9000": "5676.0", "Chữ Trung Quốc": "锗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 锗 | chá | tượng hình | nguyên tố germani (Ge), kim loại bán dẫn | 锗 là dạng giản thể của 鍺. Chữ gồm bộ 钅(kim, biểu nghĩa: kim loại) + 者 (biểu âm, cho âm zhě). Cấu trúc hình thanh — tạo ra để phiên âm tên nguyên tố Germanium. Wiktionary chỉ ghi {{Han etym}} không có phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giả\": bộ 钅(kim loại) + 者 (âm giả/zhě) — kim loại \"giả\" này là Germani, chất bán dẫn dùng trong vi mạch điện tử. | Gương Hán-Việt | giả — không dùng trong nghĩa này tiếng Việt; chỉ gặp trong hóa học | Mở khoá kiến thức | Biết 锗 mở khoá từ vựng hóa học và bảng tuần hoàn nguyên tố tiếng Trung.", "Tự nguyên_Xie": "锗 (âm Hán-Việt: chá, đọc zhě) là chữ tạo mới để phiên âm tên nguyên tố Germanium (Ge, số hiệu 32). Bộ 钅(kim) xác định đây là kim loại; 者 cho âm. Là chữ khoa học hiện đại, không có glyph cổ. Chưa có nguồn học thuật xác nhận tạo tự. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố germani, Ge", "Hạng Tần Suất (Jun Da)": "5676.0", "Tần Suất % (Jun Da)": "99.9692383649", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 者", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅者", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "者", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锗", "Unihan_Traditional (Chữ Phồn thể)": "鍺", "Pinyin_Xie": "zhě", "Âm Hán Việt_Xie": "giả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong lĩnh vực hóa học và vật lý bán dẫn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衿', '{"9000": "5677.0", "Chữ Trung Quốc": "衿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 9 | nét | 衿 | câm | tượng hình | vạt áo, tà áo; dây buộc cổ áo | 衿 gồm bộ 衤(y, biểu nghĩa: áo) + 今 (kim, biểu âm). Cấu trúc hình thanh — bộ 衤 chỉ y phục, 今 cho âm. Wiktionary chỉ ghi {{Han etym}} không phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"câm\": bộ 衤(áo) + 今 (bây giờ, âm câm) — cái vạt áo buộc chặt như \"câm\" miệng áo lại, giữ kín người mặc. | Gương Hán-Việt | câm — ít dùng độc lập; gặp trong thơ văn cổ \"thanh câm\" (vạt áo xanh, chỉ học trò) | Mở khoá kiến thức | Biết 衿 mở khoá từ vựng y phục và thơ văn cổ điển Trung Hoa, đặc biệt hình ảnh \"thanh câm\" (học trò).", "Tự nguyên_Xie": "衿 (Hán-Việt: câm, đọc jīn) chỉ vạt áo, tà áo, hoặc dây buộc cổ áo. Bộ 衤 xác nhận liên quan đến y phục; 今 cho âm đọc. Không có glyph cổ chi tiết từ Wiktionary. Chưa có nguồn học thuật xác nhận cấu trúc đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vạt áo; tà áo; dây lưng; thắt lưng", "Hạng Tần Suất (Jun Da)": "5677.0", "Tần Suất % (Jun Da)": "99.9692822916", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 今", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤今", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "今", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "衿", "Unihan_Traditional (Chữ Phồn thể)": "衿", "Pinyin_Xie": "jīn", "Âm Hán Việt_Xie": "khâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các bộ phận của trang phục truyền thống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粢', '{"9000": "5678.0", "Chữ Trung Quốc": "粢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 12 | nét | 粢 | tư | tượng hình | lúa nếp, thóc nếp dùng trong tế lễ | 粢 gồm bộ 米 (mễ, biểu nghĩa: gạo, ngũ cốc) ở dưới và phần trên là 次 hoặc biến thể. Wiktionary chỉ ghi {{Han etym}}; Tiểu triện có ảnh. Chưa có phân tích chi tiết, xếp cấu trúc suy luận từ bộ thủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": bộ 米 (gạo) ở nền — thóc nếp \"tư\" dâng lên bàn thờ tổ tiên, hạt gạo thiêng liêng nhất trong lễ tế. | Gương Hán-Việt | tư — không dùng độc lập trong tiếng Việt; gặp trong từ \"thứ tư\" không liên quan | Mở khoá kiến thức | Biết 粢 mở khoá từ vựng tế tự và nghi lễ cổ Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 粢 (Hán-Việt: tư, đọc zī) chỉ loại ngũ cốc dâng cúng tế lễ — thường là kê hoặc lúa nếp. Bộ 米 xác nhận liên quan đến ngũ cốc. Chữ này thuộc từ vựng tế tự cổ, không phổ biến trong bạch thoại. Không có phân tích Wiktionary chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thóc nếp, lúa nếp", "Hạng Tần Suất (Jun Da)": "5678.0", "Tần Suất % (Jun Da)": "99.9693262183", "GavinGrover_Once (Chiết tự trực tiếp)": "次 + 米", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱次米", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "次", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粢", "Unihan_Traditional (Chữ Phồn thể)": "粢", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ đứng trước các danh từ khác để chỉ loại ngũ cốc dùng trong cúng tế thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醵', '{"9000": "5679.0", "Chữ Trung Quốc": "醵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 20 | nét | 醵 | cự | tượng hình | góp tiền mua rượu đãi tiệc; quyên góp cùng uống | 醵 gồm bộ 酉 (dậu, biểu nghĩa: rượu, bình rượu) + 豦 hoặc 劇 lược (biểu âm). Cấu trúc hình thanh — bộ 酉 chỉ rượu, phần âm cho âm jù/cự. Không có glyph cổ từ Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cự\": bộ 酉 (rượu) kết hợp âm cự — mọi người cùng \"cự\" (đóng góp) tiền mua rượu tiệc tùng. | Gương Hán-Việt | cự — không dùng độc lập trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 醵 mở khoá từ vựng về tiệc tùng và phong tục góp quỹ ăn uống trong văn hoá cổ Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 醵 (Hán-Việt: cự, đọc jù) mang nghĩa góp tiền cùng mua rượu đãi tiệc, hoặc quyên góp chung để tổ chức yến tiệc. Bộ 酉 xác nhận liên quan đến rượu. Tiểu triện có ảnh ghi nhận. Không có phân tích tạo tự chi tiết từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quyên góp làm tiệc tiễn", "Hạng Tần Suất (Jun Da)": "5679.0", "Tần Suất % (Jun Da)": "99.9693701451", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 豦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉豦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醵", "Unihan_Traditional (Chữ Phồn thể)": "醵", "Pinyin_Xie": "jù", "Âm Hán Việt_Xie": "cự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ tiền bạc hoặc tiệc tùng để biểu thị việc cùng nhau góp vốn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跫', '{"9000": "5680.0", "Chữ Trung Quốc": "跫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 13 | nét | 跫 | cung | tượng hình | tiếng bước chân giẫm trên đất | 跫 gồm bộ 足 (túc, biểu nghĩa: chân) ở dưới và phần trên cho âm (cung/qióng). Cấu trúc hình thanh suy luận — bộ 足 chỉ chân/bước đi, phần âm cho âm qióng. Wiktionary chỉ ghi nhận định nghĩa không phân tích tạo tự chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cung\": bộ 足 (chân) — tiếng \"cung\" vang xa là bước chân hiếm hoi trong nơi tĩnh lặng, quý như ngọc. | Gương Hán-Việt | cung — không dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 跫 mở khoá từ vựng thơ văn cổ điển về sự tĩnh lặng và tiếng bước chân xa.", "Tự nguyên_Xie": "跫 (Hán-Việt: cung, đọc qióng) mô tả tiếng bước chân người giẫm trên mặt đất — âm thanh cô đơn, hiếm nghe. Bộ 足 (chân) xác nhận liên quan đến việc đi lại. Wiktionary ghi nhận nghĩa văn học ''sound of footsteps''. Không có glyph cổ rõ ràng. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng chân giẫm xuống đất", "Hạng Tần Suất (Jun Da)": "5680.0", "Tần Suất % (Jun Da)": "99.9694140718", "GavinGrover_Once (Chiết tự trực tiếp)": "巩 + 足", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱巩足", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "足", "Unihan_Simplified (Chữ Giản thể)": "跫", "Unihan_Traditional (Chữ Phồn thể)": "跫", "Pinyin_Xie": "qióng", "Âm Hán Việt_Xie": "cung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ làm tân ngữ cho các động từ nghe thấy hoặc làm định ngữ trong thơ ca. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鐾', '{"9000": "5681.0", "Chữ Trung Quốc": "鐾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 21 | nét | 鐾 | bí | tượng hình | mài dao nhiều lần cho sắc bén | 鐾 gồm bộ 金 (kim, biểu nghĩa: kim loại) ở dưới và phần trên cho âm bèi/bí. Cấu trúc hình thanh suy luận — bộ 金 chỉ dao, kim loại; phần trên cho âm. Wiktionary ghi nhận nghĩa ''sharpen by repeated grinding'' nhưng không phân tích tạo tự chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\": bộ 金 (kim loại) — liếc dao \"bí\" mãi trên đá mài, âm thanh lạo xạo từng nhát một cho đến khi lưỡi dao sáng bóng. | Gương Hán-Việt | bí — không dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 鐾 mở khoá từ vựng kỹ thuật về rèn, mài dao trong thủ công nghiệp cổ Trung Hoa.", "Tự nguyên_Xie": "鐾 (Hán-Việt: bí, đọc bèi) mang nghĩa liếc dao, mài dao nhiều lần trên đá hoặc da để làm sắc bén. Bộ 金 xác nhận liên quan đến kim loại/dao. Wiktionary định nghĩa ''to sharpen a knife by repeated grinding''. Chưa có nguồn học thuật xác nhận tạo tự. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "liếc dao cho sắc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "辟 + 金", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱辟金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鐾", "Unihan_Traditional (Chữ Phồn thể)": "鐾", "Pinyin_Xie": "bèi", "Âm Hán Việt_Xie": "tí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ đứng trước các danh từ chỉ công cụ cắt thái như dao, kéo để chỉ hành động mài sắc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('廛', '{"9000": "5682.0", "Chữ Trung Quốc": "廛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 15 | nét | 廛 | chờn | tượng hình | chỗ ở của dân thường; quán hàng ở chợ | 廛 gồm bộ 广 (nghiễm, biểu nghĩa: nhà, mái che) + các thành phần bên trong. Wiktionary chỉ ghi {{Han etym}} không có phân tích chi tiết. Đại triện và Tiểu triện đều có ảnh ghi nhận. Cấu trúc suy luận: bộ 广 chỉ kiến trúc, phần còn lại cho âm hoặc nghĩa bổ sung.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chờn\": bộ 广 (mái nhà) — khu \"chờn\" là dãy nhà chợ, nơi thương nhân chờn chờn chờ khách đến mua. | Gương Hán-Việt | chờn — ít dùng trong tiếng Việt; gặp trong \"thị廛\" (khu chợ) trong văn ngôn | Mở khoá kiến thức | Biết 廛 mở khoá từ vựng về kiến trúc đô thị và thương mại trong văn hoá cổ Trung Hoa.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 廛 (Hán-Việt: chờn, đọc chán) chỉ khu nhà ở của dân thường hoặc quán hàng trong chợ. Bộ 广 xác nhận liên quan đến không gian có mái che — chỗ ở, nơi buôn bán. Đại triện và Tiểu triện đều ghi nhận. Wiktionary định nghĩa ''a store, shop; ground allotted to a retainer''. Chưa có nguồn học thuật xác nhận tạo tự. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỗ ở của dân; quán chợ", "Hạng Tần Suất (Jun Da)": "5682.0", "Tần Suất % (Jun Da)": "99.9695019253", "GavinGrover_Once (Chiết tự trực tiếp)": "㢆 + 𡉀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴㢆𡉀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𡉀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "㢆", "Unihan_Simplified (Chữ Giản thể)": "廛", "Unihan_Traditional (Chữ Phồn thể)": "廛", "Pinyin_Xie": "chán", "Âm Hán Việt_Xie": "triền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ kết hợp với các từ chỉ nơi chốn để chỉ khu vực sinh sống hoặc buôn bán thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('墉', '{"9000": "5683.0", "Chữ Trung Quốc": "墉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 14 | nét | 墉 | dung | tượng hình | tường thành cao, tường phòng thủ | 墉 gồm bộ 土 (thổ, biểu nghĩa: đất, tường xây từ đất) + 庸 (dung, biểu âm). Cấu trúc hình thanh suy luận — bộ 土 chỉ vật liệu xây dựng, 庸 cho âm yōng/dung. Wiktionary định nghĩa ''fortified wall; city wall''. Giáp cốt văn có ảnh ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dung\": bộ 土 (đất) + dung (庸, âm) — tường thành \"dung dung\" vững chắc như vị tướng dung mạo hiên ngang, không gì phá được. | Gương Hán-Việt | dung — gặp trong \"thành dung\" (tường thành) trong văn ngôn cổ | Mở khoá kiến thức | Biết 墉 mở khoá từ vựng kiến trúc quân sự và thành trì trong văn hoá cổ Trung Hoa.", "Tự nguyên_Xie": "Giáp cốt văn | 墉 (Hán-Việt: dung, đọc yōng) chỉ tường thành cao, tường phòng thủ của thành trì. Bộ 土 xác nhận liên quan đến đất và kiến trúc. Giáp cốt văn cho thấy chữ này đã tồn tại từ rất sớm. Wiktionary định nghĩa ''fortified wall; city wall''. Chưa có nguồn học thuật xác nhận cấu trúc đầy đủ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tường thành; tường cao", "Hạng Tần Suất (Jun Da)": "5683.0", "Tần Suất % (Jun Da)": "99.969545852", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 庸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土庸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "庸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "墉", "Unihan_Traditional (Chữ Phồn thể)": "墉", "Pinyin_Xie": "yōng", "Âm Hán Việt_Xie": "dong", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các động từ như xây dựng, trèo qua hoặc làm chủ ngữ trong câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哌', '{"9000": "5684.0", "Chữ Trung Quốc": "哌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 哌 | phái | tượng hình | dùng phiên âm tên thuốc (piperazine) | 哌 gồm bộ 口 (khẩu, biểu nghĩa: âm thanh/phiên âm) + 派 (phái, biểu âm hoặc gợi nghĩa). Cấu trúc hình thanh — bộ 口 dùng để tạo chữ phiên âm từ nước ngoài, 派 cho âm pài/phái. Chữ tạo mới cho mục đích khoa học, không có glyph cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phái\": bộ 口 (miệng, âm) — chữ \"phái\" này là âm miệng mượn để viết tên thuốc piperazin trong tiếng Trung y. | Gương Hán-Việt | phái — không dùng độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 哌 mở khoá từ vựng y dược học và hóa học hữu cơ trong tiếng Trung.", "Tự nguyên_Xie": "哌 (Hán-Việt: phái, đọc pài) là chữ tạo mới dùng phiên âm tên hợp chất hóa học piperazine (piperazin) trong y dược. Bộ 口 là dấu hiệu phiên âm ngoại ngữ trong tiếng Trung. Không có glyph cổ, không có nguồn học thuật về tạo tự. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "piperazin (tên thuốc) (Anh : piperazine)", "Hạng Tần Suất (Jun Da)": "5684.0", "Tần Suất % (Jun Da)": "99.9695897788", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "哌", "Unihan_Traditional (Chữ Phồn thể)": "哌", "Pinyin_Xie": "pài", "Âm Hán Việt_Xie": "phái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ tượng thanh | 象声词 | Thường dùng làm từ tượng thanh khi lặp lại hoặc làm danh từ trong các từ ghép phiên âm tên thuốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('扦', '{"9000": "5685.0", "Chữ Trung Quốc": "扦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 6 | nét | 扌 | biểu nghĩa | tay, động tác tay | 千 | thiên | biểu âm | 扦 = 扌(Thủ, biểu nghĩa: tay) + 千 (Thiên, biểu âm, cho âm qiān/xiên); chữ hình thanh. Nghĩa gốc là que nhọn, xiên đâm xuyên — hành động dùng tay xỏ que vào. Tiếng Việt mượn âm thành ''xiên''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xiên\": tay (扌) cầm que nghìn (千) cái — xiên thức ăn mỗi bữa như que xiên thịt nướng, tay thao tác liên tục. | Gương Hán-Việt | xiên — tiếng Việt dùng ''xiên'' (xiên que, nướng xiên) chính là mượn từ chữ này | Mở khoá kiến thức | Biết 扦 mở khoá từ vựng về dụng cụ nướng, lấy mẫu hạt trong nông nghiệp và đời sống hàng ngày.", "Tự nguyên_Xie": "扦 (Hán-Việt: xiên, đọc qiān) là chữ hình thanh: 扌(thủ, tay) biểu nghĩa, 千 (thiên) cho âm. Nghĩa gốc là xiên/skewer — que nhọn xuyên qua thức ăn hoặc dụng cụ lấy mẫu (hạt thóc, bột). Wiktionary xác nhận cấu trúc Han compound. Tiếng Việt đã mượn trực tiếp thành từ ''xiên'' ({{vi-l|xiên|扦}}). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái đế; cái giá; cái tiêm (bằng kim loại hay bằng tre vót nhọn); cái xỉa; ống lấy mẫu (lấy mẫu gạo, hạt, bột); cắm vào", "Hạng Tần Suất (Jun Da)": "5685.0", "Tần Suất % (Jun Da)": "99.9696771154", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 千", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌千", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "千", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "扦", "Unihan_Traditional (Chữ Phồn thể)": "扦", "Pinyin_Xie": "qiān", "Âm Hán Việt_Xie": "thiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Dùng làm động từ đi kèm tân ngữ chỉ vật bị cắm hoặc làm danh từ chỉ dụng cụ nhọn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('堇', '{"9000": "5686.0", "Chữ Trung Quốc": "堇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 11 | nét | 堇 | cẩn | tượng hình | người bị thiêu trong nghi lễ cầu mưa; đất vàng; mùa; ít | 堇 là chữ hội ý — Wiktionary phân tích: 大 (người lớn) bị thiêu trong nghi lễ (lửa 火 dưới), miệng mở kêu la (廿 ở trên, gợi miệng). Ý nghĩa gốc: người bị thiêu trong buổi tế cầu mưa. So sánh với 黃. Không phải hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cẩn\": người (大) bị thiêu (lửa + miệng kêu) — cẩn thận từng chút vì xưa người ta \"cẩn\" sự trong lễ tế thiêng liêng nhất. | Gương Hán-Việt | cẩn — gặp trong \"cẩn thận\" (thực ra là chữ khác, 謹); 堇 ít dùng độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 堇 mở khoá chữ gốc của 謹 (cẩn), 勤 (cần), 瑾 (cẩn — ngọc đẹp) vì 堇 là âm phù của nhiều chữ.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 堇 (Hán-Việt: cẩn, đọc jǐn) là chữ hội ý: mô tả người lớn (大) bị thiêu trong nghi lễ tế trời cầu mưa, có lửa (火) phía dưới và miệng mở rộng kêu la (廿) phía trên — theo Li Xueqin 2012. Nghĩa gốc chỉ nghi lễ thiêu người, sau chuyển sang nghĩa ''đất sét vàng'', ''mùa'', ''ít''. Có kim văn và tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1317.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cách (1316) Thổ (032)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Cách (số 1316 - da thú/viết giảm nét) ở trên bộ Thổ (số 032 - đất). Thứ đất có chất keo kết dính chặt như da thú là đất sét bùn. Giải thích sự chuyển ý: Đây là chữ Hội ý. Cẩn vốn nghĩa là thứ đất bùn dẻo dính (đất sét). Nó cũng là tên một loài cỏ (cỏ cẩn).", "Nghĩa Tiếng Việt_Xie": "bôi, trát", "Hạng Tần Suất (Jun Da)": "5686.0", "Tần Suất % (Jun Da)": "99.9697205254", "GavinGrover_Once (Chiết tự trực tiếp)": "廿 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱廿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "堇", "Unihan_Traditional (Chữ Phồn thể)": "堇", "Pinyin_Xie": "jǐn", "Âm Hán Việt_Xie": "cận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ các loại thực vật cổ hoặc làm động từ trong văn viết cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('婧', '{"9000": "5687.0", "Chữ Trung Quốc": "婧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 11 | nét | 婧 | tĩnh | tượng hình | người phụ nữ mảnh khảnh, tài năng | 婧 gồm bộ 女 (nữ, biểu nghĩa: phụ nữ) + 靖 lược hoặc 青 (biểu âm, cho âm jìng/tĩnh). Cấu trúc hình thanh suy luận — bộ 女 chỉ đặc điểm nữ giới, phần âm cho âm jìng. Wiktionary ghi nhận nghĩa ''slender, delicate; talented, gifted'' của phụ nữ trong văn học.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tĩnh\": bộ 女 (nữ) + âm tĩnh — người phụ nữ tĩnh lặng mà xuất chúng, như nước lặng sâu, tài năng giấu bên trong. | Gương Hán-Việt | tĩnh — thường dùng làm tên người nữ; gần với 靜 (yên lặng) | Mở khoá kiến thức | Biết 婧 mở khoá từ vựng tính cách và nét đẹp phụ nữ trong văn học cổ điển.", "Tự nguyên_Xie": "Tiểu triện | 婧 (Hán-Việt: tĩnh, đọc jìng) miêu tả người phụ nữ có thân hình mảnh khảnh, duyên dáng, hoặc người phụ nữ tài năng xuất chúng. Bộ 女 xác nhận chỉ về nữ giới. Wiktionary ghi nhận hai nghĩa văn học: mảnh mai/duyên dáng và tài năng/có năng khiếu. Tiểu triện có ảnh. Chưa có nguồn học thuật xác nhận cấu trúc đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nữ sĩ; người phụ nữ có tài", "Hạng Tần Suất (Jun Da)": "5687.0", "Tần Suất % (Jun Da)": "99.9697639353", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 青", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女青", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "青", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "婧", "Unihan_Traditional (Chữ Phồn thể)": "婧", "Pinyin_Xie": "jìng", "Âm Hán Việt_Xie": "tinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ bổ nghĩa cho danh từ chỉ phụ nữ hoặc dùng trực tiếp làm tên riêng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('暌', '{"9000": "5688.0", "Chữ Trung Quốc": "暌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 13 | nét | 暌 | khuê | tượng hình | tách biệt, đối lập, xa cách | 暌 gồm bộ 日 (nhật, biểu nghĩa: mặt trời, ánh sáng) và phần còn lại cho âm (khuê/kuí). Cấu trúc hình thanh suy luận. Không có glyph cổ từ Wiktionary. Nghĩa ''tách biệt, xa cách'' có thể liên quan đến mặt trời khuất sau mây — ánh sáng bị ngăn cách.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuê\": bộ 日 (mặt trời) bị che khuất — \"khuê\" gợi cảm giác xa cách như vầng dương và mặt đất bị chia cắt bởi mây dày. | Gương Hán-Việt | khuê — gặp trong \"khuê li\" (xa cách, chia lìa) trong văn ngôn | Mở khoá kiến thức | Biết 暌 mở khoá từ vựng Kinh Dịch (quẻ 睽) và thơ văn cổ về sự ly biệt.", "Tự nguyên_Xie": "暌 (Hán-Việt: khuê, đọc kuí) mang nghĩa xa cách, đối lập, tách biệt — thường gặp trong Kinh Dịch (quẻ 睽, khuê). Bộ 日 (mặt trời) suy luận biểu nghĩa về sự phân cắt ánh sáng/tầm nhìn. Không có glyph cổ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trái, đối lập", "Hạng Tần Suất (Jun Da)": "5688.0", "Tần Suất % (Jun Da)": "99.9698073453", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 癸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日癸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "癸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "暌", "Unihan_Traditional (Chữ Phồn thể)": "暌", "Pinyin_Xie": "kuí", "Âm Hán Việt_Xie": "khuê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ kết hợp với các từ chỉ thời gian để diễn tả sự xa cách lâu ngày. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罱', '{"9000": "5689.0", "Chữ Trung Quốc": "罱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 14 | nét | 罱 | lảm | tượng hình | dụng cụ bắt cá dạng lưới hoặc vợt | 罱 gồm bộ 网/罒 (võng, biểu nghĩa: lưới) ở trên và phần dưới gợi tay cầm hoặc âm. Cấu trúc hình thanh suy luận — bộ 罒 xác nhận là dụng cụ đánh bắt cá dùng lưới. Wiktionary ghi nhận ''an implement for taking fish; to pick up with this implement''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lảm\": bộ 罒 (lưới) — cái vợt \"lảm\" kẹp hai đầu, lảm lảm đưa qua đưa lại vớt cá dưới lòng ao. | Gương Hán-Việt | lảm — không dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 罱 mở khoá từ vựng nghề cá và dụng cụ đánh bắt truyền thống vùng Giang Nam.", "Tự nguyên_Xie": "罱 (Hán-Việt: lảm, đọc lǎn) chỉ loại dụng cụ vớt cá — dạng lưới hai cán, kẹp lại để bắt cá hoặc vớt bùn dưới ao. Bộ 罒 (lưới) xác nhận liên quan đến nghề cá. Wiktionary ghi nhận nghĩa ''an implement for taking fish''. Không có glyph cổ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái đăng bắt cá", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + 南", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒南", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "南", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "罱", "Unihan_Traditional (Chữ Phồn thể)": "罱", "Pinyin_Xie": "lǎn", "Âm Hán Việt_Xie": "lãm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ dụng cụ đánh cá hoặc động từ chỉ hành động xúc cá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镞', '{"9000": "5690.0", "Chữ Trung Quốc": "镞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 金 | kim | biểu nghĩa | kim loại | 族 | tộc | biểu âm | 镞 = 金 (Kim, biểu nghĩa: kim loại) + 族 (Tộc, biểu âm, cho âm zú/tộc); chữ hình thanh. Nghĩa gốc là đầu mũi tên bằng kim loại. Dạng phồn thể 鏃.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tộc\" (âm phù 族): kim loại (金) + tộc (族) — đầu mũi tên kim loại nhọn bén, cả \"tộc\" chiến binh dùng để săn bắn. | Gương Hán-Việt | tộc — không dùng trong nghĩa mũi tên tiếng Việt; 族 dùng làm \"tộc người\" | Mở khoá kiến thức | Biết 镞 mở khoá từ vựng vũ khí cổ đại và thuật ngữ săn bắt trong văn học cổ Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 镞 (Hán-Việt: tộc suy luận từ âm phù 族, đọc zú) là chữ hình thanh: 金 (kim, kim loại) biểu nghĩa, 族 (tộc) cho âm. Nghĩa gốc là đầu mũi tên bằng kim loại — phần nhọn cắm vào đầu mũi tên. Dạng phồn thể 鏃. Tiểu triện có ảnh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đầu mũi tên; sắc nhọn", "Hạng Tần Suất (Jun Da)": "5690.0", "Tần Suất % (Jun Da)": "99.9698941652", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 族", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅族", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "族", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镞", "Unihan_Traditional (Chữ Phồn thể)": "鏃", "Pinyin_Xie": "zú", "Âm Hán Việt_Xie": "thốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ đầu mũi tên hoặc tính từ chỉ sự sắc bén. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹰', '{"9000": "5691.0", "Chữ Trung Quốc": "蹰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 19 | nét | 足 | tú | biểu nghĩa | chân, bước đi | 廚 | chù | biểu âm | 蹰 = 足 (Tú, biểu nghĩa: chân) + 廚 (Chù, biểu âm, cho âm chú); chữ hình thanh. Dạng phồn thể 躕. Chữ này thường dùng trong từ ghép 踟躕 (trì trù) — đứng phân vân không dứt bước.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trù\": chân (足) + âm chù (廚, bếp) — chân đứng ở bếp mà không bước được, \"trù trừ\" do dự như không muốn rời bữa ăn. | Gương Hán-Việt | trù — dùng trong \"trù trừ\" (do dự, phân vân); \"trì trù\" là từ ghép quen thuộc | Mở khoá kiến thức | Biết 蹰 mở khoá thành ngữ \"踟躕\" (trì trù — do dự, đứng không dứt bước) dùng nhiều trong thơ cổ.", "Tự nguyên_Xie": "蹰 (Hán-Việt: trù suy luận từ âm phù, đọc chú) là chữ hình thanh: 足 (tú, chân) biểu nghĩa, 廚 (chù) cho âm. Thường dùng trong 踟躕 (trì trù) — đứng lần khần, do dự không bước được. Dạng phồn thể 躕. Wiktionary xác nhận cấu trúc Han compound. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: trì trù 踟躊)", "Hạng Tần Suất (Jun Da)": "5691.0", "Tần Suất % (Jun Da)": "99.9699375751", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 厨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊厨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹰", "Unihan_Traditional (Chữ Phồn thể)": "躕", "Pinyin_Xie": "chú", "Âm Hán Việt_Xie": "trù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường kết hợp với chữ trì tạo thành từ ghép chỉ sự do dự. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陟', '{"9000": "5692.0", "Chữ Trung Quốc": "陟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 9 | nét | 阝 | biểu nghĩa | gò đất, sườn núi | 步 | bộ | biểu nghĩa | bước, hai chân chỉ lên | 陟 = 阝(Phụ, biểu nghĩa: gò đất/sườn núi) + 步 (Bộ, biểu nghĩa: bước đi, hai bàn chân hướng lên); chữ hội ý. Hai chân hướng lên (步) trên gò đất (阝) = leo lên. So sánh với 降 (hai chân hướng xuống = xuống).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trắc\": gò đất (阝) + bộ (步, bước chân) — \"trắc\" lên như bước chân leo dốc, đối ngược với 降 (xuống dốc). | Gương Hán-Việt | trắc — gặp trong \"trắc giáng\" (thăng giáng, thưởng phạt quan chức) trong văn ngôn cổ | Mở khoá kiến thức | Biết 陟 mở khoá cặp đối ngữ kinh điển 陟/降 (lên/xuống) trong Kinh Thư và thành ngữ về thăng quan tiến chức.", "Tự nguyên_Xie": "Kim văn | 陟 (Hán-Việt: trắc, đọc zhì) là chữ hội ý: 阝(phụ, gò đất) + 步 (bộ, bước đi với hai chân hướng lên). Ý nghĩa: leo lên dốc/gò — hai chân bước lên cao. Wiktionary xác nhận cấu trúc và so sánh với 降 (hai chân hướng xuống = xuống). Kim văn ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trèo lên; cất nhắc, thăng chức", "Hạng Tần Suất (Jun Da)": "5692.0", "Tần Suất % (Jun Da)": "99.9699809851", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 步", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝步", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "步", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陟", "Unihan_Traditional (Chữ Phồn thể)": "陟", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "trắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ đứng trước tân ngữ hoặc kết hợp trong từ ghép như truất trắc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳔', '{"9000": "5693.0", "Chữ Trung Quốc": "鳔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 19 | nét | 鳔 | phiêu | tượng hình | bong bóng cá — túi khí giúp cá nổi | 鳔 là dạng giản thể của 鰾. Chữ gốc 鰾 gồm bộ 魚 (ngư, biểu nghĩa: cá) + 票 (biểu âm, cho âm biào/phiêu). Cấu trúc hình thanh — bộ 魚 chỉ cá, 票 cho âm. Wiktionary ghi ''see 鰾''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiêu\": bộ 魚 (cá) + âm phiêu (票) — bong bóng \"phiêu\" làm con cá \"phiêu\" (lơ lửng) trong nước, không chìm không nổi. | Gương Hán-Việt | phiêu — gặp trong \"bong bóng cá\" (dịch nôm); phiêu dạt, lênh phiêu trong tiếng Việt | Mở khoá kiến thức | Biết 鳔 mở khoá từ vựng giải phẫu cá và ẩm thực (keo cá bong bóng) trong tiếng Trung.", "Tự nguyên_Xie": "鳔 (Hán-Việt: phiêu, đọc biào) là dạng giản thể của 鰾, chỉ bong bóng cá (swim bladder) — túi khí bên trong cơ thể cá giúp cá điều chỉnh độ nổi. Bộ 魚 xác nhận liên quan đến cá. Wiktionary dẫn về 鰾. Chữ tạo muộn, chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bong bóng cá", "Hạng Tần Suất (Jun Da)": "5693.0", "Tần Suất % (Jun Da)": "99.970024395", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 票", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼票", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "票", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳔", "Unihan_Traditional (Chữ Phồn thể)": "鰾", "Pinyin_Xie": "biào", "Âm Hán Việt_Xie": "phiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ bong bóng của loài cá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脘', '{"9000": "5694.0", "Chữ Trung Quốc": "脘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | 脘 | quản | tượng hình | khoang trong dạ dày | 脘 gồm bộ 月/肉 (nhục, biểu nghĩa: thịt, cơ quan nội tạng) + 完 (hoàn, biểu âm, cho âm wǎn/quản). Cấu trúc hình thanh suy luận — bộ 月 (nhục) xác nhận là bộ phận nội tạng. Tiểu triện có ảnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quản\": bộ 月 (thịt/nội tạng) + âm quản (完 lược) — khoang \"quản\" lý thức ăn trong dạ dày, như người quản kho giữ lương thực bên trong. | Gương Hán-Việt | quản — gặp trong \"trung quản\" (vùng bụng giữa) trong y học cổ truyền | Mở khoá kiến thức | Biết 脘 mở khoá từ vựng y học cổ truyền về dạ dày và hệ tiêu hóa.", "Tự nguyên_Xie": "Tiểu triện | 脘 (Hán-Việt: quản, đọc wǎn) chỉ khoang trong của dạ dày — vùng bụng trên (thượng quản), vùng bụng giữa (trung quản), vùng bụng dưới (hạ quản). Bộ 月 (nhục, thịt) xác nhận là thuật ngữ y học về cơ quan nội tạng. Tiểu triện ghi nhận. Chưa có nguồn học thuật xác nhận cấu trúc đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lần trong của dạ dày", "Hạng Tần Suất (Jun Da)": "5694.0", "Tần Suất % (Jun Da)": "99.970067805", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 完", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月完", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "完", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脘", "Unihan_Traditional (Chữ Phồn thể)": "脘", "Pinyin_Xie": "wǎn", "Âm Hán Việt_Xie": "quản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong y học cổ truyền để chỉ vùng dạ dày. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('岿', '{"9000": "5695.0", "Chữ Trung Quốc": "岿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 8 | nét | 岿 | khôi | tượng hình | núi cao sừng sững, trơ trọi đứng một mình | 岿 là dạng giản thể của 巋. Chữ gốc 巋 gồm bộ 山 (sơn, biểu nghĩa: núi) + phần còn lại cho âm (kuī/khôi). Cấu trúc hình thanh suy luận. Wiktionary ghi nhận nghĩa ''towering; lofty'', đặc biệt trong 巋然不動 (trơ vững không chuyển).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khôi\": bộ 山 (núi) — ngọn núi \"khôi ngô\" sừng sững giữa trời, không thứ gì lay chuyển được. | Gương Hán-Việt | khôi — gặp trong \"khôi nhiên bất động\" (巋然不動, trơ trọi vững chắc) trong văn ngôn | Mở khoá kiến thức | Biết 岿 mở khoá thành ngữ 巋然不動 (khôi nhiên bất động) dùng trong văn học và báo chí hiện đại.", "Tự nguyên_Xie": "岿 (Hán-Việt: khôi, đọc kuī) là dạng giản thể của 巋, mang nghĩa núi cao sừng sững, đứng một mình vững chắc. Bộ 山 xác nhận liên quan đến núi. Wiktionary ghi nhận nghĩa ''towering; lofty'' trong văn học. Thành ngữ nổi tiếng ''巋然不動'' (khôi nhiên bất động — trơ trọi không lay chuyển). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đứng một mình, trơ trọi", "Hạng Tần Suất (Jun Da)": "5695.0", "Tần Suất % (Jun Da)": "99.9701541081", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 归", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山归", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "归", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岿", "Unihan_Traditional (Chữ Phồn thể)": "巋", "Pinyin_Xie": "kuī", "Âm Hán Việt_Xie": "khuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ miêu tả dáng núi cao lớn đứng sừng sững. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('侔', '{"9000": "5696.0", "Chữ Trung Quốc": "侔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 侔 | mầu | tượng hình | bằng nhau, ngang hàng, sánh bằng | 侔 gồm bộ 亻(nhân, biểu nghĩa: người) + 牟 (mưu/mầu, biểu âm, cho âm móu). Cấu trúc hình thanh suy luận — bộ 亻 chỉ người/hành vi giữa người với người, phần âm gợi ý so sánh ngang bằng. Tiểu triện có ảnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mầu\": bộ 亻(người) + âm mầu — người \"mầu\" nghĩa là sánh ngang, ngang tầm với nhau — như tài năng \"mầu\" bậc thần minh. | Gương Hán-Việt | mầu — ít dùng độc lập; gặp trong văn học cổ điển | Mở khoá kiến thức | Biết 侔 mở khoá từ vựng so sánh và ngợi ca trong văn ngôn cổ điển Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 侔 (Hán-Việt: mầu, đọc móu) mang nghĩa ngang hàng, sánh bằng, tương đương. Bộ 亻(nhân) xác nhận liên quan đến người. Wiktionary ghi nhận ''to match; to equal''. Tiểu triện ghi nhận. Chưa có nguồn học thuật xác nhận tạo tự đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đều, ngang hàng", "Hạng Tần Suất (Jun Da)": "5696.0", "Tần Suất % (Jun Da)": "99.9701970013", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 牟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻牟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "牟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "侔", "Unihan_Traditional (Chữ Phồn thể)": "侔", "Pinyin_Xie": "móu", "Âm Hán Việt_Xie": "mâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ sự so sánh ngang bằng hoặc tương đương giữa hai bên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郾', '{"9000": "5697.0", "Chữ Trung Quốc": "郾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 11 | nét | 匽 | biểu âm | 邑 | ấp | biểu nghĩa | thị trấn, vùng đất | 郾 = 匽 (biểu âm, cho âm yǎn) + 邑 (Ấp, biểu nghĩa: thị trấn/vùng đất); chữ hình thanh. Wiktionary xác nhận cấu trúc Han compound. Nghĩa: tên địa danh huyện ở Hà Nam (nay là Yancheng). Đại triện và Tiểu triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yển\": bộ 邑 (ấp, vùng đất) — 郾 là tên đất cổ xứ Trung Nguyên, như chim én (燕) làm tổ ở vùng bình nguyên màu mỡ. | Gương Hán-Việt | yến — ít dùng độc lập; liên quan đến địa danh Yancheng và nước Yên cổ | Mở khoá kiến thức | Biết 郾 mở khoá từ vựng địa danh lịch sử Trung Nguyên và hiểu được cấu tạo chữ địa danh bộ 邑.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 郾 (Hán-Việt: yến suy luận từ âm phù, đọc yǎn) là chữ hình thanh: 匽 cho âm, 邑 (ấp, vùng đất) biểu nghĩa. Chỉ địa danh huyện Yancheng thuộc Dĩnh Xuyên (nay tỉnh Hà Nam). Trong kim văn tìm thấy dạng này. Wiktionary ghi nhận cũng dùng thay cho 燕 (nước Yên cổ đại) trong văn khắc đồng. Đại triện và Tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên một huyện ở tỉnh Hà Nam của Trung Quốc", "Hạng Tần Suất (Jun Da)": "5697.0", "Tần Suất % (Jun Da)": "99.9702398945", "GavinGrover_Once (Chiết tự trực tiếp)": "匽 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰匽阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郾", "Unihan_Traditional (Chữ Phồn thể)": "郾", "Pinyin_Xie": "yǎn", "Âm Hán Việt_Xie": "yển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng chỉ địa danh, thường xuất hiện trong tên huyện Yển Thành. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('唿', '{"9000": "5698.0", "Chữ Trung Quốc": "唿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 口 | khẩu | biểu nghĩa | miệng | 忽 | hốt | biểu âm | 唿 = 口 (Khẩu, biểu nghĩa: miệng) + 忽 (Hốt, biểu âm, cho âm hū/hốt); chữ hình thanh. Tiếng Việt mượn âm thành ''hót'' (chim hót). Wiktionary xác nhận là chữ Nôm: hót (chim hót), hút (hút thuốc).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hốt\": miệng (口) + hốt (忽) — miệng phát ra âm \"hốt\" như tiếng chim \"hót\", hoặc hút mạnh một cái ''hốt''. | Gương Hán-Việt | hốt — tiếng Việt dùng ''hót'' (chim hót) và ''hút'' (hút thuốc) đều viết bằng 唿 trong chữ Nôm | Mở khoá kiến thức | Biết 唿 mở khoá chữ Nôm ''hót'' và ''hút'' — hiểu cầu nối giữa chữ Hán và ngữ âm tiếng Việt.", "Tự nguyên_Xie": "唿 (Hán-Việt: hốt, đọc hū) là chữ hình thanh dùng trong tiếng Việt (chữ Nôm): 口 (khẩu, miệng) biểu nghĩa, 忽 (hốt) cho âm. Tiếng Việt mượn làm ''hót'' (chim hót), ''hút'' (hút thuốc), ''ngút'' (khói ngút). Wiktionary xác nhận cấu trúc Han compound và ghi rõ các đọc Nôm. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "huýt; huýt sáo; huýt gió (bằng tay)", "Hạng Tần Suất (Jun Da)": "5698.0", "Tần Suất % (Jun Da)": "99.9702827876", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 忽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口忽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "忽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "唿", "Unihan_Traditional (Chữ Phồn thể)": "唿", "Pinyin_Xie": "hū", "Âm Hán Việt_Xie": "hốt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Động từ | 动词 | Thường dùng làm từ tượng thanh mô tả tiếng gió thổi hoặc tiếng thở dài. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砹', '{"9000": "5699.0", "Chữ Trung Quốc": "砹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 10 | nét | 砹 | ái | tượng hình | nguyên tố Astatine (At, số 85) | 砹 gồm bộ 石 (thạch, biểu nghĩa: đá, khoáng chất) + phần còn lại cho âm (ài/ái). Cấu trúc hình thanh — bộ 石 dùng để tạo tên nguyên tố phi kim. Chữ tạo mới cho mục đích khoa học. Không có glyph cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ái\": bộ 石 (đá) + âm ái — nguyên tố \"ái\" là Astatine, thứ kim loại phóng xạ \"ái\" (ngắn ngủi) nhất vì chu kỳ bán rã chỉ vài giờ. | Gương Hán-Việt | ái — không dùng trong tiếng Việt thông thường, chỉ gặp trong hóa học | Mở khoá kiến thức | Biết 砹 mở khoá tên nguyên tố phóng xạ nặng trong bảng tuần hoàn tiếng Trung.", "Tự nguyên_Xie": "砹 (Hán-Việt: ái, đọc ài) là chữ tạo mới để phiên âm tên nguyên tố Astatine (At, số hiệu 85) — phi kim phóng xạ nặng nhất. Bộ 石 (đá/khoáng chất) chỉ đây là nguyên tố vô cơ. Không có glyph cổ. Chưa có nguồn học thuật về tạo tự. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố An-xta-ti, kí hiệu At", "Hạng Tần Suất (Jun Da)": "5699.0", "Tần Suất % (Jun Da)": "99.9703256808", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 艾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石艾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "艾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砹", "Unihan_Traditional (Chữ Phồn thể)": "砹", "Pinyin_Xie": "ài", "Âm Hán Việt_Xie": "ngải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chuyên ngành hóa học để chỉ nguyên tố ái. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疴', '{"9000": "5700.0", "Chữ Trung Quốc": "疴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 10 | nét | 疴 | kha | tượng hình | ốm nặng, bệnh tật | 疴 gồm bộ 疒 (nạch, biểu nghĩa: bệnh tật) + 可 (khả, biểu âm, cho âm kē/kha). Cấu trúc hình thanh suy luận — bộ 疒 xác nhận là chữ chỉ bệnh. Wiktionary ghi ''见 痾'' (xem thêm 痾). Tiểu triện có ảnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kha\": bộ 疒 (bệnh) + âm kha (可) — bệnh \"kha\" là thứ bệnh nan y, khó \"kha\" (khắc phục) nổi. | Gương Hán-Việt | kha — ít dùng độc lập; gặp trong \"trầm疴\" (bệnh nặng kinh niên) | Mở khoá kiến thức | Biết 疴 mở khoá từ vựng y học cổ điển về bệnh tật lâu dài.", "Tự nguyên_Xie": "Tiểu triện | 疴 (Hán-Việt: kha, đọc kē) là dạng biến thể của 痾, chỉ bệnh tật nặng, ốm đau. Bộ 疒 xác nhận liên quan đến bệnh. Wiktionary dẫn về 痾. Tiểu triện ghi nhận. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ốm nặng", "Hạng Tần Suất (Jun Da)": "5700.0", "Tần Suất % (Jun Da)": "99.9703685739", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 可", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒可", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "可", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "疴", "Unihan_Traditional (Chữ Phồn thể)": "痾", "Pinyin_Xie": "kē", "Âm Hán Việt_Xie": "kha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong văn viết cổ để chỉ các loại bệnh tật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麸', '{"9000": "5701.0", "Chữ Trung Quốc": "麸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 麥 | Số nét | 11 | nét | 麸 | phu | tượng hình | cám, trấu — vỏ ngoài của hạt ngũ cốc sau khi xay | 麸 là dạng giản thể của 麩. Chữ gốc 麩 gồm bộ 麥 (mạch, biểu nghĩa: lúa mì) + 夫 (phu, biểu âm, cho âm fū/phu). Cấu trúc hình thanh. Wiktionary ghi là chữ shinjitai (JIS Nhật Bản) của 麩. Tiểu triện và liushutong có ảnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phu\": bộ 麦 (lúa mì) + phu (夫, người đàn ông) — cám mì \"phu\" như người lao động thô ráp bên ngoài, sau khi xay thì bị tách ra khỏi hạt gạo trắng mịn. | Gương Hán-Việt | phu — ít dùng trong tiếng Việt; cám mì = \"bran\" trong y học | Mở khoá kiến thức | Biết 麸 mở khoá từ vựng thực phẩm và dinh dưỡng: cám mì, gluten, thực phẩm ngũ cốc.", "Tự nguyên_Xie": "Tiểu triện | Lưu thư thông | 麸 (Hán-Việt: phu, đọc fū) là dạng giản thể/shinjitai của 麩, chỉ cám mì — vỏ ngoài của lúa mì sau khi xay. Bộ 麥 (mạch, lúa mì) xác nhận liên quan đến lúa mì. 夫 (phu) cho âm. Tiểu triện ghi nhận. Wiktionary xác nhận gốc Nhật 麩 là chữ chuẩn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trấu (vỏ hạt thóc)", "Hạng Tần Suất (Jun Da)": "5701.0", "Tần Suất % (Jun Da)": "99.9704114671", "GavinGrover_Once (Chiết tự trực tiếp)": "麦 + 夫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰麦夫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "麦", "Unihan_Simplified (Chữ Giản thể)": "麸", "Unihan_Traditional (Chữ Phồn thể)": "䴸", "Pinyin_Xie": "fū", "Âm Hán Việt_Xie": "phu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ lớp vỏ cám bên ngoài của các loại ngũ cốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薨', '{"9000": "5702.0", "Chữ Trung Quốc": "薨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 死 | tu | biểu nghĩa | chết | 瞢 | biểu âm | 薨 = 死 (Tu, biểu nghĩa: chết) + 瞢 (biểu âm rút gọn, cho âm hōng); chữ hình thanh. Nghĩa: từ chuyên dùng cho cái chết của chư hầu, vương công hoặc đại thần cấp cao — không dùng cho thường dân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoăng\": chết (死) + âm hoăng — \"hoăng\" là từ kính ngữ khi vua/chư hầu băng hà, như tiếng chuông \"hoăng hoăng\" báo tang lớn trong triều đình. | Gương Hán-Việt | hoăng — dùng trong \"băng hoăng\" (vua chư hầu mất) trong văn ngôn; tiếng Việt \"băng hà\" cũng là tương đương | Mở khoá kiến thức | Biết 薨 mở khoá hệ thống từ kính ngữ cái chết trong văn hoá cổ Trung Hoa: 崩 (vua), 薨 (chư hầu), 卒 (quan lại), 死 (dân thường).", "Tự nguyên_Xie": "Tiểu triện | 薨 (Hán-Việt: hoăng, đọc hōng) là chữ hình thanh: 死 (tu, chết) biểu nghĩa, 瞢 (rút gọn) cho âm. Nghĩa chuyên biệt: chỉ dùng khi vua chư hầu hoặc quan đại thần qua đời — cách nói trang trọng, tránh dùng chữ 死 trực tiếp. Wiktionary xác nhận nghĩa ''of feudal lords or high officials — to pass away''. Tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vua hay đại thần chết; nhanh vù vù", "Hạng Tần Suất (Jun Da)": "5702.0", "Tần Suất % (Jun Da)": "99.9704543603", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "薨", "Unihan_Traditional (Chữ Phồn thể)": "薨", "Pinyin_Xie": "hōng", "Âm Hán Việt_Xie": "hoăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Từ tượng thanh | 象声词 | Chữ này làm động từ đặc trị trong văn cổ để chỉ việc qua đời của vua chư hầu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('綝', '{"9000": "5703.0", "Chữ Trung Quốc": "綝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 14 | nét | 綝 | sâm | tượng hình | dừng lại; ngay ngắn, có trật tự | 綝 gồm bộ 糸/糹(mịch, biểu nghĩa: sợi chỉ, vải) + 林 (lâm, biểu âm, cho âm chēn/sâm). Cấu trúc hình thanh suy luận — bộ 糸 gợi ý về sợi chỉ bị thắt nút (dừng lại). Tiểu triện có ảnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sâm\": bộ 糸 (sợi chỉ) + âm sâm — sợi chỉ \"sâm\" lại, dừng đột ngột, không thể kéo thêm. | Gương Hán-Việt | sâm — ít dùng trong tiếng Việt; \"sâm\" gợi nhân sâm (khác chữ) | Mở khoá kiến thức | Biết 綝 mở khoá từ vựng dệt may và từ cổ về trật tự ngay ngắn trong văn ngôn.", "Tự nguyên_Xie": "Tiểu triện | 綝 (Hán-Việt: sâm, đọc chēn) mang nghĩa dừng lại, hoặc trạng thái ngay ngắn có trật tự. Bộ 糸 (sợi chỉ) gợi ý hình ảnh sợi chỉ được sắp xếp ngay ngắn. Wiktionary ghi nhận ''to stop; 綝纚'' (trạng thái ngay ngắn). Tiểu triện ghi nhận. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngừng; dừng; lương thiện", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 林", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹林", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "林", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "𬘭", "Unihan_Traditional (Chữ Phồn thể)": "綝", "Pinyin_Xie": "chēn", "Âm Hán Việt_Xie": "lâm, sâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này dùng làm động từ chỉ sự dừng lại hoặc tính từ thể hiện sự tốt lành. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('滁', '{"9000": "5704.0", "Chữ Trung Quốc": "滁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 滁 | trừ | tượng hình | tên sông, tên địa danh ở tỉnh An Huy | 滁 gồm bộ 氵(thủy, biểu nghĩa: nước, sông) + 余 (dư, biểu âm, cho âm chú/trừ). Cấu trúc hình thanh suy luận — bộ 氵xác nhận liên quan đến sông. Tiểu triện có ảnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trừ\": bộ 氵(nước, sông) + âm trừ — sông Trừ nước chảy trong vắt, nơi Âu Dương Tu viết bài ký nổi tiếng về Túy Ông Đình. | Gương Hán-Việt | trừ — gặp trong \"Trừ Châu\" (Chuzhou, An Huy); \"trừ\" trong tiếng Việt còn có nghĩa loại bỏ (chữ khác) | Mở khoá kiến thức | Biết 滁 mở khoá từ vựng địa danh An Huy và hiểu tên địa danh bộ 氵trong tiếng Trung.", "Tự nguyên_Xie": "Tiểu triện | 滁 (Hán-Việt: trừ, đọc chú) là tên riêng địa danh — chỉ sông Trừ (Chu River) và thành phố Chuzhou (Trừ Châu) ở tỉnh An Huy. Bộ 氵 xác nhận gốc là tên sông. Nổi tiếng qua bài Túy Ông Đình Ký (醉翁亭记) của Âu Dương Tu. Tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Trừ", "Hạng Tần Suất (Jun Da)": "5704.0", "Tần Suất % (Jun Da)": "99.9705396298", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 除", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵除", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "除", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "滁", "Unihan_Traditional (Chữ Phồn thể)": "滁", "Pinyin_Xie": "chú", "Âm Hán Việt_Xie": "trừ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ tên sông hoặc địa danh ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('偾', '{"9000": "5705.0", "Chữ Trung Quốc": "偾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 11 | nét | 偾 | phẫn | tượng hình | phá hỏng, làm thất bại; ngã xuống, chết | 偾 là dạng giản thể của 僨. Chữ gốc 僨 gồm bộ 亻(nhân, biểu nghĩa: người) + 賁 (biểu âm, cho âm fèn/phẫn). Cấu trúc hình thanh suy luận. Wiktionary ghi nhận ba nghĩa: phá hủy, ngã chết, và kích động.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phẫn\": bộ 亻(người) + âm phẫn — người \"phẫn\" nộ quá mức thì \"phẫn\" (đổ ngã) việc lớn, hỏng hết mọi thứ. | Gương Hán-Việt | phẫn — gặp trong \"phẫn nộ\" (tức giận dữ dội, nhưng là chữ khác 憤); 偾 ít dùng | Mở khoá kiến thức | Biết 偾 mở khoá từ vựng thành ngữ về thất bại do hành động sai lầm trong văn ngôn.", "Tự nguyên_Xie": "Tiểu triện | 偾 (Hán-Việt: phẫn, đọc fèn) là dạng giản thể của 僨. Bộ 亻(nhân) xác nhận liên quan đến hành vi của người. Nghĩa: phá hỏng, làm sụp đổ; ngã chết; hoặc kích động căng thẳng. Wiktionary ghi nhận ''to ruin; to fall down; excited; tense''. Tiểu triện ghi nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đổ ngã", "Hạng Tần Suất (Jun Da)": "5705.0", "Tần Suất % (Jun Da)": "99.9705820062", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 贲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻贲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "偾", "Unihan_Traditional (Chữ Phồn thể)": "僨", "Pinyin_Xie": "fèn", "Âm Hán Việt_Xie": "phẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ sự đổ ngã hoặc tính từ chỉ trạng thái thất bại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拊', '{"9000": "5706.0", "Chữ Trung Quốc": "拊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 拊 | phủ | tượng hình | vỗ tay, gõ nhẹ; nhạc cụ gõ cổ đại | 拊 gồm bộ 扌(thủ, biểu nghĩa: tay) + 付 (phó, biểu âm, cho âm fǔ/phủ). Cấu trúc hình thanh suy luận — bộ 扌xác nhận là động tác tay. Tiểu triện có ảnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phủ\": bộ 扌(tay) + âm phủ — \"phủ\" lòng bàn tay xuống đùi mà cười thành tiếng, như người xưa vỗ đùi tán thưởng. | Gương Hán-Việt | phủ — ít dùng độc lập; gặp trong \"phủ thủ\" (vỗ tay) và từ ngữ nhạc cụ cổ trong văn ngôn | Mở khoá kiến thức | Biết 拊 mở khoá từ vựng nhạc cụ cổ đại và cử chỉ biểu đạt cảm xúc trong văn học cổ Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 拊 (Hán-Việt: phủ, đọc fǔ) mang nghĩa vỗ tay, đập nhẹ, hoặc gõ nhạc cụ. Nghĩa phụ: loại nhạc cụ gõ cổ đại (搏拊). Bộ 扌xác nhận động tác tay. Wiktionary ghi nhận ''to clap hands; to strike; an ancient percussion instrument''. Tiểu triện ghi nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vỗ", "Hạng Tần Suất (Jun Da)": "5706.0", "Tần Suất % (Jun Da)": "99.9706243826", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 付", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌付", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "付", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拊", "Unihan_Traditional (Chữ Phồn thể)": "拊", "Pinyin_Xie": "fǔ", "Âm Hán Việt_Xie": "phủ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động vỗ nhẹ bằng tay hoặc vỗ về an ủi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('撺', '{"9000": "5707.0", "Chữ Trung Quốc": "撺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 15 | nét | 撺 | toản | tượng hình | ném, liệng; xúi giục; làm ẩu, vội vã | 撺 là dạng giản thể của 攛. Chữ gốc 攛 gồm bộ 扌(thủ, biểu nghĩa: tay) + phần còn lại cho âm (cuān/toản). Cấu trúc hình thanh suy luận. Wiktionary không phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toản\": bộ 扌(tay) — tay \"toản\" ném vật đi, hoặc \"toản\" (xúi giục) người khác hành động liều lĩnh. | Gương Hán-Việt | toản — không dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 撺 mở khoá từ vựng khẩu ngữ Trung Hoa về hành động ném và xúi giục.", "Tự nguyên_Xie": "撺 (Hán-Việt: toản, đọc cuān) là dạng giản thể của 攛. Bộ 扌xác nhận động tác tay — ném, liệng, hoặc xúi giục người khác làm điều gì đó. Wiktionary ghi nhận ''hurry; to throw; to urge''. Chưa có nguồn học thuật xác nhận tạo tự. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ném, liệng, vứt; làm dối, làm ẩu; phát cáu, nổi giận; dẫn dụ vào bẫy", "Hạng Tần Suất (Jun Da)": "5707.0", "Tần Suất % (Jun Da)": "99.970666759", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 窜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌窜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "窜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "撺", "Unihan_Traditional (Chữ Phồn thể)": "攛", "Pinyin_Xie": "cuān", "Âm Hán Việt_Xie": "thoán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị hành động ném mạnh hoặc xúi giục người khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('呒', '{"9000": "5708.0", "Chữ Trung Quốc": "呒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 呒 | vô | tượng hình | không có; trợ từ phủ định (ngôn ngữ Thượng Hải) | 呒 là dạng giản thể của 嘸. Wiktionary ghi {{Han etym|無}} — tức là gốc tạo chữ liên quan đến 無 (vô, không có). Bộ 口 (khẩu) kết hợp với 无/無 biến thể. Cấu trúc hình thanh suy luận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vô\": bộ 口 (miệng) + gốc 無 (không có) — miệng nói \"vô\" là không có, chẳng có gì — phủ định hoàn toàn. | Gương Hán-Việt | vô — tiếng Việt dùng \"vô\" (không) trong khẩu ngữ miền Nam | Mở khoá kiến thức | Biết 呒 mở khoá từ vựng phương ngữ Ngô (Thượng Hải) và hiểu các cách biểu đạt phủ định trong tiếng Trung.", "Tự nguyên_Xie": "呒 (Hán-Việt: vô, đọc fǔ/m) là dạng giản thể của 嘸, có gốc từ 無 (vô, không có). Bộ 口 xác nhận là phát âm/trợ từ. Nghĩa chính: không có, chẳng có — dùng trong phương ngữ Thượng Hải và Ngô ngữ để phủ định. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "không có, chẳng có, chả có; (trợ từ)", "Hạng Tần Suất (Jun Da)": "5708.0", "Tần Suất % (Jun Da)": "99.9707091354", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 无", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口无", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "无", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呒", "Unihan_Traditional (Chữ Phồn thể)": "嘸", "Pinyin_Xie": "fǔ", "Âm Hán Việt_Xie": "mô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Phó từ | 副词 | Chữ này làm động từ phủ định tương đương với chữ vô trong một số phương ngôn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狯', '{"9000": "5709.0", "Chữ Trung Quốc": "狯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 9 | nét | 狯 | khoái | tượng hình | xảo trá, ranh mãnh, quỷ quyệt | 狯 là dạng giản thể của 獪. Chữ gốc 獪 gồm bộ 犭(khuyển, biểu nghĩa: chó, loài thú) + 會 (hội, biểu âm, cho âm kuài/khoái). Cấu trúc hình thanh — bộ 犭gợi hình ảnh loài vật xảo quyệt như cáo. Tiểu triện và liushutong có ảnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoái\": bộ 犭(thú) + âm khoái (會) — con thú \"khoái\" như con cáo, lanh lẹ xảo quyệt, luôn nhanh một bước hơn người. | Gương Hán-Việt | khoái — ít dùng; \"khoái\" trong tiếng Việt thường nghĩa thích thú (chữ khác) | Mở khoá kiến thức | Biết 狯 mở khoá từ vựng tính cách tiêu cực và thành ngữ về sự gian xảo trong văn học cổ.", "Tự nguyên_Xie": "Tiểu triện | Lưu thư thông | 狯 (Hán-Việt: khoái, đọc kuài) là dạng giản thể của 獪, mang nghĩa xảo trá, ranh mãnh, quỷ quyệt. Bộ 犭(chó/loài thú) gợi hình ảnh loài vật tinh ranh. Wiktionary ghi nhận ''sly; cunning; crafty''. Tiểu triện ghi nhận. Dùng trong thành ngữ ''狡獪'' (gian xảo). | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xảo trá, quỷ quyệt", "Hạng Tần Suất (Jun Da)": "5709.0", "Tần Suất % (Jun Da)": "99.9707515117", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 会", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭会", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "会", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狯", "Unihan_Traditional (Chữ Phồn thể)": "獪", "Pinyin_Xie": "kuài", "Âm Hán Việt_Xie": "quái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ để miêu tả tính cách gian xảo hoặc tinh ranh của con người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('猢', '{"9000": "5710.0", "Chữ Trung Quốc": "猢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 12 | nét | 猢 | hồ | tượng hình | loài khỉ nhỏ ở Trung Quốc | 猢 là chữ độc thể — bộ 犬 (khuyển, chó/thú) là gốc ý, phần còn lại biểu âm; không có phân tích hội ý hay hình thanh rõ ràng trong nguồn học thuật. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồ\": bộ 犬 (thú) mang âm \"hồ\" — hình dung con khỉ nhảy trên cây hồ lô, dùng trong từ 猢猻 chỉ loài khỉ tinh nghịch. | Gương Hán-Việt | 猢 trong 猢猻 (hú sūn) — khỉ con lanh lợi | Mở khoá kiến thức | Biết 猢 mở khoá từ 猢猻 (hú sūn) — tên gọi văn học cho loài khỉ, thường gặp trong thơ cổ và văn chương Trung Hoa.", "Tự nguyên_Xie": "猢 chỉ xuất hiện trong tổ hợp 猢猻 (hú sūn) — tên loài khỉ nhỏ sống ở miền tây Trung Quốc. Wiktionary không cung cấp phân tích cấu trúc chi tiết; bộ 犬 gợi đây là loài thú. Chưa có nguồn học thuật đầy đủ về glyph cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loài khỉ ở Trung Quốc", "Hạng Tần Suất (Jun Da)": "5710.0", "Tần Suất % (Jun Da)": "99.9707938881", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 胡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭胡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "胡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "猢", "Unihan_Traditional (Chữ Phồn thể)": "猢", "Pinyin_Xie": "hú", "Âm Hán Việt_Xie": "hồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường đi kèm với chữ tôn để chỉ loài khỉ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('椁', '{"9000": "5711.0", "Chữ Trung Quốc": "椁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 椁 | quách | tượng hình | hòm ngoài bọc quan tài | 椁 là dạng giản thể của 槨. Bộ 木 (mộc, gỗ) gợi nghĩa đồ vật bằng gỗ; phần còn lại biểu âm. Cấu trúc hình thanh nhưng chưa có phân tích IDS đầy đủ trong nguồn học thuật. Chữ tạo muộn, chỉ thấy trong Lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quách\": bộ 木 (gỗ) + âm guǒ — chiếc hòm gỗ \"quách\" bọc bên ngoài quan tài, giữ linh cửu khỏi đất ẩm. | Gương Hán-Việt | quách trong \"quan quách\" — quan tài và hòm ngoài | Mở khoá kiến thức | Biết 椁 mở khoá khái niệm \"quan quách\" trong tang lễ Trung Hoa cổ đại — thường gặp trong văn bản khảo cổ và lịch sử.", "Tự nguyên_Xie": "Lục thư thông | 椁 là dạng rút gọn của 槨 — hòm gỗ bọc bên ngoài quan tài chính (棺). Trong tang lễ Trung Hoa cổ đại, người có địa vị cao được chôn với cả 棺 (quan) bên trong và 槨/椁 (quách) bên ngoài. Wiktionary chỉ ghi \"{{zh-see|槨|sv}}\" — tức dạng giản thể. Chưa có phân tích glyph cổ rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái quách (để bọc ngoài áo quan)", "Hạng Tần Suất (Jun Da)": "5711.0", "Tần Suất % (Jun Da)": "99.9708362645", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 享", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木享", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "享", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "椁", "Unihan_Traditional (Chữ Phồn thể)": "槨", "Pinyin_Xie": "guǒ", "Âm Hán Việt_Xie": "quách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cái quách gỗ bọc bên ngoài quan tài chính. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('榱', '{"9000": "5712.0", "Chữ Trung Quốc": "榱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 14 | nét | 榱 | suôi | tượng hình | đòn tay, xà gỗ đỡ mái ngói | 榱 là chữ bộ 木 (mộc, gỗ) — gợi nghĩa vật liệu gỗ dùng trong kiến trúc. Không có phân tích hội ý hay hình thanh rõ ràng từ Wiktionary. Chữ chỉ thấy trong Tiểu triện. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"suôi\": bộ 木 (gỗ) — hình dung những thanh gỗ \"suôi\" (xuôi) từ đỉnh mái chạy dài xuống, nâng đỡ mái ngói. | Gương Hán-Việt | suôi trong \"đòn suôi\" — xà gỗ mái nhà | Mở khoá kiến thức | Biết 榱 mở khoá vốn từ kiến trúc cổ đại Trung Hoa — thường gặp trong thơ phú tả cung điện.", "Tự nguyên_Xie": "Tiểu triện | 榱 chỉ đòn tay (rafter) — thanh gỗ nằm nghiêng trên mái nhà để đỡ ngói hoặc tranh. Bộ 木 (gỗ) xác nhận chất liệu. Wiktionary chỉ có mục {{Han etym}} mà không phân tích thêm. Dạng Tiểu triện đã xuất hiện nhưng không rõ nguồn gốc glyph cổ hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gái rui (đóng trên mái ngói để móc ngói giắt lá vào)", "Hạng Tần Suất (Jun Da)": "5712.0", "Tần Suất % (Jun Da)": "99.9708786409", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 衰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木衰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "衰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "榱", "Unihan_Traditional (Chữ Phồn thể)": "榱", "Pinyin_Xie": "cuī", "Âm Hán Việt_Xie": "suy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ để chỉ các thanh rui trên mái nhà cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罾', '{"9000": "5713.0", "Chữ Trung Quốc": "罾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 17 | nét | 网 | võng | biểu nghĩa | lưới | 曾 | tằng | biểu âm | 罾 = 网 (Võng, biểu nghĩa: lưới) + 曾 (Tằng, biểu âm); chữ hình thanh. Bộ 网 xác định nghĩa loại dụng cụ đánh cá hình lưới; 曾 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tăng\": bộ 网 (lưới) + 曾 cho âm — hình dung chiếc lưới vuông to \"tăng\" dần khi đầy cá kéo lên bờ. | Gương Hán-Việt | tăng trong ngư cụ cổ — lưới đánh cá hình vuông | Mở khoá kiến thức | Biết 罾 mở khoá vốn từ ngư nghiệp cổ đại; thường gặp trong thơ ca dân gian miền sông nước Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 罾 là loại lưới đánh cá hình vuông lớn, được buộc vào bốn góc cần trúc và thả xuống sông rồi kéo lên — kiểu ngư cụ phổ biến ở miền nam Trung Quốc. Wiktionary phân tích: 网 (lưới, biểu nghĩa) + 曾 (biểu âm) theo cấu trúc hình thanh. Tiểu triện đã có dạng gần với chữ hiện đại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái lưới đánh cá", "Hạng Tần Suất (Jun Da)": "5713.0", "Tần Suất % (Jun Da)": "99.9709210173", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + 曾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒曾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "罾", "Unihan_Traditional (Chữ Phồn thể)": "罾", "Pinyin_Xie": "zēng", "Âm Hán Việt_Xie": "tăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ dụng cụ đánh cá hoặc làm động từ với nghĩa cất vó. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铳', '{"9000": "5714.0", "Chữ Trung Quốc": "铳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 金 | kim | biểu nghĩa | kim loại | 充 | sung | biểu âm | 铳 = 金 (Kim, biểu nghĩa: kim loại) + 充 (Sung, biểu âm); chữ hình thanh. Bộ 金 chỉ đây là vũ khí kim loại; 充 cho âm gần chòng/sung.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sung\": bộ 金 (kim loại) + 充 cho âm — chiếc súng kim loại được \"sung\" (nạp) đạn, dùng trong chiến trận xưa. | Gương Hán-Việt | sung trong \"hỏa sung\" (火銃) — súng hỏa mai thời cổ | Mở khoá kiến thức | Biết 铳 mở khoá lịch sử vũ khí Đông Á — từ này là gốc của 銃 (tiếng Nhật: súng) và liên quan đến chữ \"súng\" tiếng Việt.", "Tự nguyên_Xie": "铳 (dạng phồn thể 銃) chỉ loại vũ khí cầm tay bằng kim loại thời cổ — ban đầu là lỗ rìu để cắm cán, về sau chỉ súng hỏa mai. Wiktionary phân tích hình thanh: 金 (kim loại, biểu nghĩa) + 充 (biểu âm). Chữ này là tổ tiên của từ 銃 trong tiếng Nhật (じゅう, súng) và chữ súng trong tiếng Việt vay mượn qua tiếng Hán. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái lỗ rìu búa để cho cán vào; cái súng (vũ khí đời xưa)", "Hạng Tần Suất (Jun Da)": "5714.0", "Tần Suất % (Jun Da)": "99.9709633936", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 充", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅充", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "充", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铳", "Unihan_Traditional (Chữ Phồn thể)": "銃", "Pinyin_Xie": "chòng", "Âm Hán Việt_Xie": "súng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ loại súng hoặc đứng độc lập để chỉ hỏa khí. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裎', '{"9000": "5715.0", "Chữ Trung Quốc": "裎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 12 | nét | 裎 | trình | tượng hình | cởi trần, áo đơn | 裎 có bộ 衣 (y, quần áo) gợi nghĩa liên quan đến y phục; phần còn lại (呈 Trình) gợi âm. Cấu trúc hình thanh khả năng cao nhưng Wiktionary không xác nhận rõ. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trình\": bộ 衣 (áo) + âm trình — hình dung người \"trình\" diện mà không mặc áo ngoài, cởi trần phơi lưng. | Gương Hán-Việt | trình trong ngữ cảnh cổ văn — cởi trần, không y phục | Mở khoá kiến thức | Biết 裎 mở khoá vốn từ cổ văn về y phục — thường gặp trong kinh điển Nho gia khi tả nghi lễ.", "Tự nguyên_Xie": "Tiểu triện | 裎 chỉ trạng thái cởi trần hoặc chiếc áo đơn. Bộ 衣 (y phục) xác nhận nghĩa liên quan đến quần áo. Wiktionary chỉ ghi \"{{rfdef|zh}}\" — chưa có định nghĩa hoàn chỉnh. Dạng Tiểu triện còn lưu lại. Chưa có nguồn học thuật đầy đủ về glyph cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cởi trần, cởi truồng; áo đơn", "Hạng Tần Suất (Jun Da)": "5715.0", "Tần Suất % (Jun Da)": "99.97100577", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 呈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤呈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "呈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裎", "Unihan_Traditional (Chữ Phồn thể)": "裎", "Pinyin_Xie": "chéng", "Âm Hán Việt_Xie": "trình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ trong văn viết cổ để chỉ hành động cởi trần. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳚', '{"9000": "5716.0", "Chữ Trung Quốc": "鳚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 19 | nét | 鳚 | vị | tượng hình | cá lon mây, cá dạng rắn | 鳚 có bộ 魚 (ngư, cá) là gốc ý, gợi đây là loài cá; phần còn lại biểu âm. Không có dữ liệu Wiktionary hay anchor glyph. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vị\": bộ 魚 (cá) + âm vị — loài cá \"vị\" (vẫy) mình dài như rắn, bơi lượn dưới đáy đá. | Gương Hán-Việt | vị trong tên sinh học cá — cá lon mây | Mở khoá kiến thức | Biết 鳚 mở khoá vốn từ sinh học thủy sản — tên loài cá blenny trong ngư học Trung Hoa.", "Tự nguyên_Xie": "鳚 chỉ loài cá dạng rắn (blenny), thân dài mảnh, thường sống ở vùng nước cạn hoặc rạn đá. Bộ 魚 (cá) xác nhận đây là tên loài cá. Không có dữ liệu glyph cổ hay phân tích cấu trúc từ Wiktionary. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá lon mây", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 尉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼尉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳚", "Unihan_Traditional (Chữ Phồn thể)": "鳚", "Pinyin_Xie": "wèi", "Âm Hán Việt_Xie": "ngư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong danh pháp sinh học để chỉ các loài cá thuộc họ cá lon mây. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眦', '{"9000": "5717.0", "Chữ Trung Quốc": "眦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 11 | nét | 眦 | tì | tượng hình | khoé mắt, đuôi mắt | 眦 là dạng giản hoặc dị thể của 眥. Bộ 目 (mục, mắt) gợi nghĩa liên quan đến mắt; phần còn lại biểu âm. Cấu trúc hình thanh nhưng Wiktionary chỉ dẫn sang 眥. Chưa có nguồn học thuật đầy đủ riêng cho 眦.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tì\": bộ 目 (mắt) — khoé mắt là điểm \"tì\" vào khóe, nơi lệ chảy ra khi xúc động. | Gương Hán-Việt | tì trong y học cổ — khoé mắt, đuôi mắt | Mở khoá kiến thức | Biết 眦 mở khoá vốn từ y học và văn học cổ — thường gặp trong miêu tả tướng mạo, cảm xúc dữ dội (\"mắt trợn ngược\").", "Tự nguyên_Xie": "Tiểu triện | 眦 là dạng khác của 眥 — chỉ khoé mắt (góc trong hoặc ngoài của mắt). Bộ 目 (mắt) xác nhận nghĩa giải phẫu mắt. Dạng Tiểu triện còn lưu lại. Wiktionary ghi \"{{zh-see|眥}}\" — tức dị thể. Chưa có nguồn học thuật riêng. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khoé mắt; đuôi mắt", "Hạng Tần Suất (Jun Da)": "5717.0", "Tần Suất % (Jun Da)": "99.9710905228", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 此", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目此", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "此", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眦", "Unihan_Traditional (Chữ Phồn thể)": "眥", "Pinyin_Xie": "zì", "Âm Hán Việt_Xie": "tí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong các cụm từ miêu tả biểu cảm mắt như trợn mắt tức giận. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('璎', '{"9000": "5718.0", "Chữ Trung Quốc": "璎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 15 | nét | 璎 | anh | tượng hình | chuỗi ngọc đeo | 璎 là dạng giản thể của 瓔. Bộ 玉/王 (ngọc) gợi nghĩa đồ trang sức bằng ngọc quý; phần còn lại biểu âm. Cấu trúc hình thanh nhưng Wiktionary không phân tích chi tiết. Chữ chủ yếu gặp trong từ 璎珞 (anh lạc — vòng hạt ngọc).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"anh\": bộ 玉 (ngọc) + âm anh — chuỗi \"anh\" ngọc lấp lánh quanh cổ các vị thần Phật giáo và quý tộc cung đình. | Gương Hán-Việt | anh trong \"anh lạc\" (璎珞) — vòng ngọc trang sức | Mở khoá kiến thức | Biết 璎 mở khoá từ 璎珞 — chuỗi ngọc Phật giáo, thường gặp trong mỹ thuật tôn giáo và văn học cung đình.", "Tự nguyên_Xie": "Lục thư thông | 璎 là dạng giản thể của 瓔 — chỉ chuỗi ngọc trang sức đeo quanh cổ hoặc thân. Bộ 玉 (ngọc) xác nhận chất liệu quý. Chủ yếu dùng trong 瓔珞/璎珞 (anh lạc) — loại chuỗi ngọc Phật giáo và quý tộc cổ đại. Wiktionary ghi \"{{rfdef|zh}}\" và liệt kê hợp từ 瓔珞/瓔珞木. Dạng Lục thư thông còn lưu ba ảnh. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chuỗi ngọc đeo", "Hạng Tần Suất (Jun Da)": "5718.0", "Tần Suất % (Jun Da)": "99.9711328992", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 婴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王婴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "婴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "璎", "Unihan_Traditional (Chữ Phồn thể)": "瓔", "Pinyin_Xie": "yīng", "Âm Hán Việt_Xie": "anh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn chương để chỉ đồ trang sức bằng ngọc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('崞', '{"9000": "5719.0", "Chữ Trung Quốc": "崞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 11 | nét | 崞 | quách | tượng hình | tên núi ở Sơn Tây | 崞 có bộ 山 (sơn, núi) gợi nghĩa địa danh núi non; phần còn lại biểu âm. Cấu trúc hình thanh khả năng cao nhưng Wiktionary không phân tích chi tiết. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quách\": bộ 山 (núi) + âm quách — ngọn núi mang tên \"Quách\" nằm ở Sơn Tây, gần thành cổ được bao bọc như tường \"quách\". | Gương Hán-Việt | quách trong địa danh cổ — núi Quách, huyện Quách Sơn Tây | Mở khoá kiến thức | Biết 崞 mở khoá các địa danh lịch sử tỉnh Sơn Tây — thường gặp trong sử liệu và địa chí Trung Hoa.", "Tự nguyên_Xie": "崞 là tên địa danh — chỉ ngọn núi và huyện Quách ở tỉnh Sơn Tây, Trung Quốc (nay là huyện Nguyên Bình). Bộ 山 (núi) xác nhận nghĩa địa lý. Wiktionary ghi dùng trong tên đất ({{zh-used2|p}}). Chưa có nguồn học thuật đầy đủ về cấu trúc glyph. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "5719.0", "Tần Suất % (Jun Da)": "99.9712171351", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 享", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山享", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "享", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "崞", "Unihan_Traditional (Chữ Phồn thể)": "崞", "Pinyin_Xie": "guō", "Âm Hán Việt_Xie": "quách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng để chỉ địa danh hoặc tên núi thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缇', '{"9000": "5720.0", "Chữ Trung Quốc": "缇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 缇 | đề | tượng hình | lụa màu đỏ phớt | 缇 là dạng giản thể của 緹. Bộ 糸 (mịch, tơ lụa) gợi nghĩa chất liệu dệt may; phần còn lại biểu âm. Cấu trúc hình thanh nhưng Wiktionary không phân tích chi tiết. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đề\": bộ 糸 (tơ) + âm đề — tấm lụa \"đề\" (đỏ phớt) mà các nữ quan triều Hán mặc trong nghi lễ trang trọng. | Gương Hán-Việt | đề trong \"đề kỵ\" (緹騎) — kỵ binh triều Hán áo đỏ | Mở khoá kiến thức | Biết 缇 mở khoá vốn từ lịch sử triều Hán — 緹騎 (kỵ binh hoàng cung mặc lụa đỏ), 緹縈 (tên nhân vật hiếu nữ nổi tiếng).", "Tự nguyên_Xie": "Tiểu triện | 缇 (phồn thể 緹) chỉ loại lụa màu đỏ cam hoặc đỏ phớt — màu của trang phục quan lại và nghi lễ triều đình. Bộ 糸 (tơ lụa) xác nhận đây là loại vải. Dạng Tiểu triện còn lưu lại. Wiktionary ghi \"{{rfdef|zh}}\" và liệt kê hợp từ 緹縈救父 (câu chuyện nổi tiếng về lòng hiếu thảo), 緹騎 (kỵ binh mặc đồng phục đỏ). | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lụa đỏ phớt", "Hạng Tần Suất (Jun Da)": "5720.0", "Tần Suất % (Jun Da)": "99.9712589947", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 是", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟是", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "是", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缇", "Unihan_Traditional (Chữ Phồn thể)": "緹", "Pinyin_Xie": "tí", "Âm Hán Việt_Xie": "đề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm tính từ bổ nghĩa cho trang phục hoặc danh từ chỉ loại lụa màu đỏ cam. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝣', '{"9000": "5721.0", "Chữ Trung Quốc": "蝣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 蝣 | du | tượng hình | con phù du, chuồn chuồn may | 蝣 có bộ 虫 (trùng, sâu bọ) gợi nghĩa loài côn trùng; phần còn lại biểu âm. Cấu trúc hình thanh nhưng Wiktionary không phân tích chi tiết cấu trúc glyph. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": bộ 虫 (sâu bọ) — con 蜉蝣 (phù du) \"du\" lượn chỉ một ngày rồi biến mất, như đời người thoáng qua. | Gương Hán-Việt | du trong \"phù du\" (蜉蝣) — biểu tượng sự phù du, ngắn ngủi | Mở khoá kiến thức | Biết 蝣 mở khoá từ 蜉蝣 — biểu tượng phù du trong thơ cổ Tô Thức và Kinh Thi, tả sự ngắn ngủi của kiếp người.", "Tự nguyên_Xie": "蝣 là thành phần trong tổ hợp 蜉蝣 (phù du) — loài côn trùng có tuổi thọ cực ngắn (chỉ một ngày), sống ở gần ao hồ. 蜉蝣 trở thành biểu tượng văn học cho sự phù du ngắn ngủi của cuộc đời. Bộ 虫 (sâu bọ) xác nhận đây là côn trùng. Wiktionary ghi \"{{zh-short|蜉蝣}}\". Chưa có nguồn học thuật đầy đủ về glyph cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: phù du 蜉蝣)", "Hạng Tần Suất (Jun Da)": "5721.0", "Tần Suất % (Jun Da)": "99.9713008543", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 斿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫斿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝣", "Unihan_Traditional (Chữ Phồn thể)": "蝣", "Pinyin_Xie": "yóu", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ phù tạo thành từ ghép phù du để chỉ loài côn trùng sống ngắn ngủi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萑', '{"9000": "5722.0", "Chữ Trung Quốc": "萑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艸 | thảo | biểu nghĩa | cỏ cây | 隹 | chuy | biểu âm | 萑 = 艸 (Thảo, biểu nghĩa: cỏ cây) + 隹 (Chuy, biểu âm); chữ hình thanh. Bộ 艸 xác định đây là loài thực vật; 隹 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàn\": bộ 艸 (cỏ) + 隹 (chim) — bụi cỏ lau \"hoàn\" mọc um tùm, chim 隹 ẩn náu bên trong, tạo nơi trú ẩn bí ẩn. | Gương Hán-Việt | hoàn trong 萑苻 (Hoàn Phù) — nơi kẻ trộm ẩn náu (thành ngữ cổ) | Mở khoá kiến thức | Biết 萑 mở khoá địa danh và thành ngữ cổ 萑苻之盗 — chỉ trộm cướp lẩn trốn trong bụi lau rậm rạp.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 萑 chỉ loài cỏ lau dùng để đan chiếu hoặc làm thuốc (益母草 — ngải mẫu). Wiktionary phân tích hình thanh: 艸 (cỏ, biểu nghĩa) + 隹 (biểu âm). Địa danh Hoàn Phố (萑苻) nổi tiếng trong lịch sử là nơi tụ họp của kẻ trộm cướp. Tiểu triện và Lục thư thông còn lưu ảnh. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1132.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (028) Truy (202)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thảo (số 028 - cỏ) ở trên chữ Truy (số 202 - chim đuôi ngắn/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Truy chỉ âm, bộ Thảo chỉ ý. Chuy vốn là tên một loài rau cỏ mọc ven nước, có thể dùng đan lát mành tã.", "Nghĩa Tiếng Việt_Xie": "cỏ hoàn, cỏ lau", "Hạng Tần Suất (Jun Da)": "5722.0", "Tần Suất % (Jun Da)": "99.9713421971", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "萑", "Unihan_Traditional (Chữ Phồn thể)": "萑", "Pinyin_Xie": "huán", "Âm Hán Việt_Xie": "hoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn học cổ để chỉ các loại cỏ lau sậy hoang dại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狲', '{"9000": "5723.0", "Chữ Trung Quốc": "狲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 9 | nét | 狲 | tôn | tượng hình | con khỉ | 狲 là dạng giản thể của 猻. Bộ 犬 (khuyển, thú/chó) gợi nghĩa loài thú linh trưởng; phần còn lại biểu âm. Cấu trúc hình thanh nhưng không có phân tích chi tiết từ nguồn học thuật. Chủ yếu dùng trong tổ hợp 猢猻/猢狲.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tôn\": bộ 犬 (thú) + âm tôn — con khỉ \"tôn\" (Tôn Ngộ Không!) lanh lợi, nhảy nhót không ngừng. | Gương Hán-Việt | tôn trong 猢狲 (hú sūn) — khỉ con, gắn với hình ảnh Tôn Ngộ Không | Mở khoá kiến thức | Biết 狲 mở khoá từ 猢狲 — tên văn học chỉ khỉ, thường gặp trong Tây Du Ký và thành ngữ \"猢狲散\" (lũ khỉ tan đàn — tả thế sự tan vỡ).", "Tự nguyên_Xie": "狲 (phồn thể 猻) chủ yếu xuất hiện trong tổ hợp 猢猻/猢狲 (hú sūn) — tên văn học cho loài khỉ nhỏ. Bộ 犬 (thú) xác nhận đây là loài động vật. Wiktionary liệt kê 猢猻、猴猻、兔猻 (hú sūn, hóu sūn, tù sūn). Chưa có nguồn học thuật đầy đủ về glyph cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con khỉ", "Hạng Tần Suất (Jun Da)": "5723.0", "Tần Suất % (Jun Da)": "99.97138354", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 孙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭孙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狲", "Unihan_Traditional (Chữ Phồn thể)": "猻", "Pinyin_Xie": "sūn", "Âm Hán Việt_Xie": "tôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong từ ghép để chỉ loài khỉ như hồ tôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缱', '{"9000": "5724.0", "Chữ Trung Quốc": "缱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 16 | nét | 缱 | khiển | tượng hình | gắn bó, quyến luyến nhau | 缱 là dạng giản thể của 繾. Bộ 糸 (mịch, tơ lụa/sợi chỉ) gợi sự gắn kết, ràng buộc; phần còn lại biểu âm. Cấu trúc hình thanh nhưng Wiktionary không phân tích chi tiết. Dạng Tiểu triện còn lưu lại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiển\": bộ 糸 (tơ) — những sợi tơ \"khiển\" (không rời được) quấn lấy nhau, như tình cảm 繾綣 khó mà dứt ra. | Gương Hán-Việt | khiển trong 缱绻 (khiển quyển) — quyến luyến, tha thiết | Mở khoá kiến thức | Biết 缱 mở khoá từ 缱绻 — từ thi ca cổ điển tả tình yêu sâu đậm không nỡ rời xa, thường gặp trong từ và thơ Đường Tống.", "Tự nguyên_Xie": "Tiểu triện | 缱 (phồn thể 繾) chủ yếu dùng trong tổ hợp 繾綣 (khiển quyển) — trạng thái quyến luyến, gắn bó không muốn rời xa nhau, đặc biệt trong tình yêu. Bộ 糸 (sợi chỉ) gợi hình ảnh những sợi tình cảm quấn quýt khó gỡ. Wiktionary ghi \"{{zh-used|繾綣}}\". Dạng Tiểu triện còn lưu. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gắn bó; quyến luyến nhau", "Hạng Tần Suất (Jun Da)": "5724.0", "Tần Suất % (Jun Da)": "99.9714248828", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 遣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟遣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "遣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缱", "Unihan_Traditional (Chữ Phồn thể)": "繾", "Pinyin_Xie": "qiǎn", "Âm Hán Việt_Xie": "khiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ trong từ ghép khiển quyến để tả tình cảm gắn bó không rời. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('晷', '{"9000": "5725.0", "Chữ Trung Quốc": "晷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 12 | nét | 晷 | quỹ | tượng hình | bóng mặt trời, đồng hồ mặt trời | 晷 có bộ 日 (nhật, mặt trời) ở dưới, gợi nghĩa liên quan đến ánh sáng mặt trời và bóng. Phần trên (鬼 biến thể) biểu âm. Cấu trúc hình thanh khả năng cao nhưng Wiktionary không phân tích chi tiết IDS. Dạng Tiểu triện còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỹ\": bộ 日 (mặt trời) — chiếc \"quỹ\" (đồng hồ mặt trời) đọc bóng của nhật để đo giờ; ai học khuya là \"kế quỹ\" (tiếp nối ánh sáng). | Gương Hán-Việt | quỹ trong 日晷 (nhật quỹ) — đồng hồ mặt trời | Mở khoá kiến thức | Biết 晷 mở khoá từ 日晷 (đồng hồ mặt trời) và thành ngữ 焚膏繼晷 — đốt nến tiếp tục sau khi bóng mặt trời tắt, tả sự chăm chỉ miệt mài.", "Tự nguyên_Xie": "Tiểu triện | 晷 chỉ bóng của mặt trời trên mặt đất, qua đó chỉ thời gian và đồng hồ mặt trời (日晷 — nhật quỹ). Bộ 日 (mặt trời) xác nhận nghĩa thiên văn. Dùng phổ biến trong thành ngữ 焚膏繼晷 (đốt đèn tiếp nối bóng mặt trời — tả sự cần mẫn học hành). Wiktionary liệt kê nhiều hợp từ nhưng không phân tích glyph. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bóng mặt trời", "Hạng Tần Suất (Jun Da)": "5725.0", "Tần Suất % (Jun Da)": "99.9714662256", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 咎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱日咎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "晷", "Unihan_Traditional (Chữ Phồn thể)": "晷", "Pinyin_Xie": "guǐ", "Âm Hán Việt_Xie": "quỹ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bóng nắng hoặc đồng hồ mặt trời thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('冼', '{"9000": "5726.0", "Chữ Trung Quốc": "冼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 冫 | Số nét | 8 | nét | 冼 | tiển | tượng hình | họ Tiển | 冼 có bộ 冫 (băng/nước) ở bên trái, phần 先 (tiên) biểu âm. Cấu trúc hình thanh khả năng cao nhưng không có dữ liệu Wiktionary hay anchor glyph. Chữ chủ yếu dùng như họ người (họ Tiển). Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiển\": bộ 冫 (nước) + 先 (tiên, trước) — dòng nước \"tiển\" (tiên phong) chảy trước, gắn với họ Tiển nổi danh trong sử Trung Hoa. | Gương Hán-Việt | tiển trong họ Tiển — Tiển Phu Nhân, nữ anh hùng dân tộc Lạc Việt | Mở khoá kiến thức | Biết 冼 mở khoá lịch sử họ Tiển — đặc biệt Tiển Phu Nhân (冼夫人), biểu tượng đoàn kết dân tộc thời Tùy Đường.", "Tự nguyên_Xie": "冼 chủ yếu là họ người — họ Tiển/Tẩy, nổi tiếng với Tiển Phu Nhân (冼夫人 — nữ tù trưởng, anh hùng dân tộc thiểu số thời Nam Triều và Tùy Đường). Bộ 冫 (nước/băng) kết hợp với 先 (âm xǐan/tiên). Không có dữ liệu glyph cổ từ nguồn học thuật. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Tiển", "Hạng Tần Suất (Jun Da)": "5726.0", "Tần Suất % (Jun Da)": "99.9715075684", "GavinGrover_Once (Chiết tự trực tiếp)": "冫 + 先", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰冫先", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "先", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冫", "Unihan_Simplified (Chữ Giản thể)": "冼", "Unihan_Traditional (Chữ Phồn thể)": "冼", "Pinyin_Xie": "xiǎn", "Âm Hán Việt_Xie": "tiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痧', '{"9000": "5727.0", "Chữ Trung Quốc": "痧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 12 | nét | 疒 | nạch | biểu nghĩa | bệnh tật | 沙 | sa | biểu âm | 痧 = 疒 (Nạch, biểu nghĩa: bệnh tật) + 沙 (Sa, biểu âm); chữ hình thanh. Bộ 疒 xác định đây là tên bệnh; 沙 cho âm shā gần với shā của 痧.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sa\": bộ 疒 (bệnh) + 沙 (sa, cát) — bệnh \"sa\" như hạt cát nóng bỏng trong người, dân gian hay \"cạo gió\" để trị. | Gương Hán-Việt | sa trong \"cạo gió\" (刮痧) — phép chữa bệnh dân gian | Mở khoá kiến thức | Biết 痧 mở khoá từ 刮痧 (cạo gió) — phương pháp y học cổ truyền phổ biến ở cả Trung Quốc và Việt Nam.", "Tự nguyên_Xie": "痧 chỉ chứng bệnh \"sa\" — trong y học dân gian Trung Hoa và Việt Nam, chỉ các triệu chứng như đau bụng cấp, tả lỵ, hoặc bệnh do nắng nóng (trúng nắng). Wiktionary phân tích hình thanh: 疒 (bệnh tật, biểu nghĩa) + 沙 (biểu âm). Gần với phong tục \"cạo gió\" (刮痧 guā shā) của người Hoa và người Việt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh thổ tả", "Hạng Tần Suất (Jun Da)": "5727.0", "Tần Suất % (Jun Da)": "99.9715489112", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 沙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒沙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "沙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痧", "Unihan_Traditional (Chữ Phồn thể)": "痧", "Pinyin_Xie": "shā", "Âm Hán Việt_Xie": "sa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các chứng bệnh nhiệt, trúng gió hoặc phát ban trong đông y. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕖', '{"9000": "5728.0", "Chữ Trung Quốc": "蕖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 蕖 | cừ | tượng hình | cây sen, hoa sen | 蕖 có bộ 艸 (thảo, cỏ cây) gợi nghĩa thực vật; phần còn lại biểu âm. Cấu trúc hình thanh nhưng Wiktionary không phân tích chi tiết. Chủ yếu dùng trong tổ hợp 芙蕖 (phù cừ) — tên cổ của hoa sen. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cừ\": bộ 艸 (cỏ) — bông 芙蕖 (phù cừ) là tên thơ của hoa sen, \"cừ\" mang âm thanh thanh thoát như cánh sen trắng vươn lên khỏi bùn. | Gương Hán-Việt | cừ trong 芙蕖 (phù cừ) — tên thơ của hoa sen | Mở khoá kiến thức | Biết 蕖 mở khoá từ 芙蕖 — tên thơ của hoa sen trong Kinh Thi và thơ cổ, thường đi cùng 芙蓉 (phù dung).", "Tự nguyên_Xie": "蕖 chủ yếu xuất hiện trong từ 芙蕖 (fú qú) — tên cổ điển và thi vị của hoa sen trong thơ ca Trung Hoa. Bộ 艸 (thực vật) xác nhận đây là loài cây. Wiktionary ghi \"{{zh-used|芙蕖|lotus}}\". Cũng gặp trong 木蕖 (mộc cừ — một loài cây). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: phù cừ 芙蕖)", "Hạng Tần Suất (Jun Da)": "5728.0", "Tần Suất % (Jun Da)": "99.97163108", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 渠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹渠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "渠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕖", "Unihan_Traditional (Chữ Phồn thể)": "蕖", "Pinyin_Xie": "qú", "Âm Hán Việt_Xie": "cừ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và thường xuất hiện trong từ ghép phù cừ để chỉ hoa sen. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狍', '{"9000": "5729.0", "Chữ Trung Quốc": "狍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 8 | nét | 狍 | bào | tượng hình | hươu nai ở bắc Trung Quốc | 狍 có bộ 犬 (khuyển, thú) gợi nghĩa loài thú; phần còn lại biểu âm. Cấu trúc hình thanh nhưng Wiktionary không phân tích chi tiết. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bào\": bộ 犬 (thú) + âm bào — con hươu \"bào\" (chạy bào) nhanh nhẹn trong rừng bạch dương phía bắc. | Gương Hán-Việt | bào trong động vật học — hươu bào Siberia | Mở khoá kiến thức | Biết 狍 mở khoá vốn từ động vật rừng phương bắc — loài hươu nai phổ biến trong câu chuyện dân gian và ẩm thực vùng Đông Bắc Trung Quốc.", "Tự nguyên_Xie": "狍 chỉ con hươu Siberia (Capreolus pygargus) — loài nai nhỏ sống ở rừng phía bắc và đông bắc Trung Quốc, Siberia và bán đảo Triều Tiên. Bộ 犬 (thú) xác nhận đây là động vật có vú. Wiktionary ghi tên khoa học và từ 狍子 (páo zi). Chưa có nguồn học thuật đầy đủ về glyph cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hươu bào", "Hạng Tần Suất (Jun Da)": "5729.0", "Tần Suất % (Jun Da)": "99.9716719061", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 包", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭包", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "包", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狍", "Unihan_Traditional (Chữ Phồn thể)": "狍", "Pinyin_Xie": "páo", "Âm Hán Việt_Xie": "bào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài động vật thuộc họ hươu nai ở vùng Đông Bắc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('憷', '{"9000": "5730.0", "Chữ Trung Quốc": "憷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 16 | nét | 憷 | xúc | tượng hình | sợ hãi, đau đớn | 憷 có bộ 心 (tâm, tâm lý/cảm xúc) gợi nghĩa trạng thái cảm xúc; phần còn lại (楚 biến thể) biểu âm và nghĩa. Cấu trúc hình thanh nhưng Wiktionary chỉ ghi dị thể của 楚 và 怵. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xúc\": bộ 心 (tim) + âm xúc — trái tim bị \"xúc\" (chạm) mạnh, sinh ra cảm giác sợ hãi hoặc đau nhói. | Gương Hán-Việt | xúc trong \"xúc cảm\" — trạng thái tâm lý sợ hãi, đau đớn | Mở khoá kiến thức | Biết 憷 mở khoá cặp từ khẩu ngữ Bắc Kinh: 憷场 (xúc tràng — sợ khi lên sân khấu/trước đám đông), 憷头 (ngại ngùng).", "Tự nguyên_Xie": "憷 là dạng thay thế của 楚 (đau đớn) và 怵 (sợ hãi). Bộ 心 (tâm) xác nhận đây là trạng thái tâm lý. Wiktionary ghi hai cách đọc: chǔ (thay thế 楚 — đau) và chù (thay thế 怵 — sợ). Thường dùng trong văn nói (khẩu ngữ) tiếng Phổ thông; trong văn viết chính thức dùng 怵. Chưa có nguồn học thuật đầy đủ về glyph. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sợ hãi; đau đớn", "Hạng Tần Suất (Jun Da)": "5730.0", "Tần Suất % (Jun Da)": "99.9717127321", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 楚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄楚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "楚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "憷", "Unihan_Traditional (Chữ Phồn thể)": "憷", "Pinyin_Xie": "chù", "Âm Hán Việt_Xie": "sở", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ biểu thị tâm lý e ngại hoặc sợ hãi trước một việc gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锛', '{"9000": "5731.0", "Chữ Trung Quốc": "锛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 锛 | bôn | tượng hình | cái rìu đẽo; đẽo bằng rìu | 锛 là dạng giản thể của 錛. Bộ 金 (kim, kim loại) gợi nghĩa công cụ bằng kim loại; phần còn lại biểu âm. Cấu trúc hình thanh nhưng Wiktionary chỉ có {{Han etyl}} (lỗi đánh máy) mà không phân tích. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bôn\": bộ 金 (kim loại) + âm bôn — chiếc rìu \"bôn\" kim loại nặng của thợ mộc, đẽo gỗ tạo ra tiếng \"bôn bốp\" vang vọng. | Gương Hán-Việt | bôn trong thợ mộc cổ — rìu đẽo gỗ | Mở khoá kiến thức | Biết 锛 mở khoá vốn từ thủ công nghiệp — công cụ thợ mộc truyền thống, thường gặp trong văn bản kỹ thuật và mô tả nghề nghiệp.", "Tự nguyên_Xie": "锛 (phồn thể 錛) chỉ cái rìu đẽo (adze) — dụng cụ thợ mộc dùng để đẽo và làm phẳng gỗ. Bộ 金 (kim loại) xác nhận đây là công cụ bằng kim loại. Wiktionary có mục {{Han etyl}} (có lẽ là lỗi đánh máy của {{Han etym}}) — không có phân tích cấu trúc đầy đủ. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái rìu; đẽo bằng rìu", "Hạng Tần Suất (Jun Da)": "5731.0", "Tần Suất % (Jun Da)": "99.9717535581", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 奔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅奔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锛", "Unihan_Traditional (Chữ Phồn thể)": "錛", "Pinyin_Xie": "bēn", "Âm Hán Việt_Xie": "bôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này vừa làm danh từ chỉ dụng cụ đẽo gỗ vừa làm động từ chỉ hành động đẽo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窨', '{"9000": "5732.0", "Chữ Trung Quốc": "窨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 14 | nét | 窨 | ấm | tượng hình | hầm ngầm; ủ hương trà | 窨 có bộ 穴 (huyệt, hố/hang) gợi nghĩa không gian ngầm hoặc kín; phần dưới (音 âm) biểu âm. Cấu trúc hình thanh nhưng Wiktionary chỉ có {{Han etym}} mà không phân tích chi tiết. Dạng Tiểu triện còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ấm\": bộ 穴 (hầm) + 音 (âm) — căn hầm \"ấm\" áp kín mít, dùng để ủ trà hoa hay cất giữ thứ quý giá trong bóng tối. | Gương Hán-Việt | ấm trong 窨茶 (ấm trà) — ủ hương hoa vào trà | Mở khoá kiến thức | Biết 窨 mở khoá quy trình sản xuất trà hoa nổi tiếng — 窨茶 là kỹ thuật ủ trà với hoa tươi để tạo trà lài, trà nhài và các loại trà hương.", "Tự nguyên_Xie": "Tiểu triện | 窨 có hai cách đọc: xūn/yìn. Đọc xūn chỉ hầm ngầm hoặc kho chứa; đọc yìn dùng trong 窨茶 (ấm trà) — ủ trà với hoa để hấp thụ hương thơm (như trà lài 茉莉花茶). Bộ 穴 (hang hốc) kết hợp với 音 (âm thanh/tiếng) gợi không gian kín. Dạng Tiểu triện còn lưu. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái nhà hầm; chôn lâu", "Hạng Tần Suất (Jun Da)": "5732.0", "Tần Suất % (Jun Da)": "99.9717943841", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 音", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴音", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "音", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窨", "Unihan_Traditional (Chữ Phồn thể)": "窨", "Pinyin_Xie": "xūn", "Âm Hán Việt_Xie": "huân, ấm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ căn hầm dưới đất hoặc làm động từ chỉ việc ướp hương trà. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袼', '{"9000": "5733.0", "Chữ Trung Quốc": "袼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 11 | nét | 袼 | cách | tượng hình | miếng vải khâu đế giày; vải gấu áo | 袼 có bộ 衣 (y, quần áo/vải) gợi nghĩa liên quan đến may mặc; phần còn lại (各 cách) biểu âm. Cấu trúc hình thanh nhưng Wiktionary không phân tích chi tiết. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cách\": bộ 衣 (vải) + 各 (cách) — miếng vải \"cách\" (lót mỗi lớp) khâu chặt vào đế giày thủ công, bền chắc qua tháng năm. | Gương Hán-Việt | cách trong thủ công may mặc — 袼褙 (cách bối) làm đế giày | Mở khoá kiến thức | Biết 袼 mở khoá kỹ thuật thủ công may mặc cổ truyền — 袼褙 là phương pháp dán vải lên giấy nhiều lớp để làm đế giày thủ công của Trung Hoa.", "Tự nguyên_Xie": "袼 chỉ miếng vải dùng khâu lót đế giày hoặc phần vải ở gấu tay áo (nách áo). Bộ 衣 (vải/may mặc) xác nhận đây là thuật ngữ may mặc. Wiktionary định nghĩa \"sleeve\". Chữ gặp trong 袼褙 (cách bối) — phương pháp dán nhiều lớp vải cứng để làm đế giày thủ công. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khâu đế giày", "Hạng Tần Suất (Jun Da)": "5733.0", "Tần Suất % (Jun Da)": "99.9718352102", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 各", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤各", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "各", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袼", "Unihan_Traditional (Chữ Phồn thể)": "袼", "Pinyin_Xie": "gē", "Âm Hán Việt_Xie": "các", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và thường kết hợp thành từ ghép để chỉ miếng vải lót hoặc bồi giấy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('帏', '{"9000": "5734.0", "Chữ Trung Quốc": "帏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 7 | nét | 巾 | can | biểu nghĩa | vải, khăn | 韋 | vi | biểu âm | 帏 = 巾 (Can, biểu nghĩa: vải/khăn) + 韋 (Vi, biểu âm); chữ hình thanh. Bộ 巾 xác định đây là vật dụng bằng vải dệt; 韋 cho âm wéi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vi\": bộ 巾 (vải) + 韋 (vi) — tấm màn \"vi\" trướng bằng vải quây quanh giường ngủ, tạo không gian riêng tư trong cung điện. | Gương Hán-Việt | vi trong 帏幕 (vi mộ) — màn trướng cung điện | Mở khoá kiến thức | Biết 帏 mở khoá vốn từ nội thất cổ đại — 帏幄 (vi ác) chỉ màn trướng nơi nghị sự, 帏幕 chỉ màn trướng trang trí.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 帏 (phồn thể 幃) chỉ loại màn vải làm thành tường ngăn hoặc bao quanh giường — dùng trong nội thất cung đình và phòng ngủ quý tộc. Wiktionary phân tích hình thanh: 巾 (vải, biểu nghĩa) + 韋 (biểu âm). Kim văn đã có dạng chữ này — nghĩa là chữ xuất hiện từ thời đồ đồng. Dạng Kim văn, Tiểu triện và Lục thư thông đều còn lưu ảnh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màn; màn trướng; túi thơm", "Hạng Tần Suất (Jun Da)": "5734.0", "Tần Suất % (Jun Da)": "99.9718760362", "GavinGrover_Once (Chiết tự trực tiếp)": "巾 + 韦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巾韦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "韦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "帏", "Unihan_Traditional (Chữ Phồn thể)": "幃", "Pinyin_Xie": "wéi", "Âm Hán Việt_Xie": "vi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các loại màn che hoặc túi thơm trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('儋', '{"9000": "5735.0", "Chữ Trung Quốc": "儋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 15 | nét | 儋 | đam | tượng hình | gánh nặng hai bên; cái vò nhỏ; địa danh Đam Châu | 儋 có bộ 亻 (nhân, người) gợi nghĩa hành động hoặc vai trò của người; phần còn lại (詹 chiêm) biểu âm. Cấu trúc hình thanh nhưng Wiktionary chỉ có {{Han etym}} mà không phân tích chi tiết. Dạng Bạch thư, Đại triện và Tiểu triện còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đam\": bộ 亻 (người) + âm đam — người gánh \"đam\" (đôi quang gánh) cân bằng hai bên, cũng là tên đất Đam Châu nơi Tô Đông Pha bị lưu đày. | Gương Hán-Việt | đam trong địa danh Đam Châu (儋州) — Hải Nam | Mở khoá kiến thức | Biết 儋 mở khoá lịch sử văn học Tống — Tô Thức bị đày đến Đam Châu (儋州) ở Hải Nam, nơi ông sáng tác nhiều tác phẩm bất hủ.", "Tự nguyên_Xie": "Bạch thư | Đại triện | Tiểu triện | 儋 có nghĩa là gánh hai bên cân bằng (a load of two) hoặc chiếc vò nhỏ. Là tên huyện Đam Châu (儋州) ở đảo Hải Nam, nơi nhà thơ Tô Thức bị đày cuối đời. Bộ 亻 (người) gợi hành động gánh vác. Dạng cổ từ Bạch thư đến Tiểu triện đều còn lưu ảnh — là dấu hiệu chữ có nguồn gốc lâu đời. Chưa có phân tích IDS chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "huyện Đam (ở Hải Nam, Trung Quốc)", "Hạng Tần Suất (Jun Da)": "5735.0", "Tần Suất % (Jun Da)": "99.9719168622", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 詹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻詹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "詹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "儋", "Unihan_Traditional (Chữ Phồn thể)": "儋", "Pinyin_Xie": "dān", "Âm Hán Việt_Xie": "đam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ riêng chỉ địa danh hoặc động từ mang nghĩa gánh vác trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绨', '{"9000": "5736.0", "Chữ Trung Quốc": "绨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 10 | nét | 绨 | đề | tượng hình | lụa thô, tơ dệt thô | 绨 là dạng giản thể của 綈. Bộ 糸 (mịch, tơ lụa) gợi nghĩa chất liệu dệt; phần còn lại biểu âm. Cấu trúc hình thanh nhưng Wiktionary không phân tích chi tiết. Dạng Tiểu triện còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đề\": bộ 糸 (tơ) + âm đề — tấm lụa \"đề\" (thô) tuy không sang nhưng ấm lòng, nhắc điển cố 綈袍之贈 về tình nghĩa bạn bè vượt qua giàu nghèo. | Gương Hán-Việt | đề trong 绨袍之赠 (đề bào chi tặng) — tặng áo lụa thô, tình nghĩa chân thật | Mở khoá kiến thức | Biết 绨 mở khoá điển cố 綈袍之贈 — câu chuyện tình bạn giữa Phạm Thư và Tu Giả trong Chiến Quốc Sách, biểu tượng ân nghĩa trọng hơn phú quý.", "Tự nguyên_Xie": "Tiểu triện | 绨 (phồn thể 綈) chỉ loại tơ thô dệt chéo — một dạng lụa hạng trung, không mịn bằng lụa thượng hạng. Nổi tiếng trong điển cố 綈袍之贈 (đề bào chi tặng) — tặng chiếc áo lụa thô, biểu hiện tình nghĩa chân thật dù địa vị đã thay đổi. Bộ 糸 (tơ) xác nhận đây là loại vải. Dạng Tiểu triện còn lưu. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vải dày", "Hạng Tần Suất (Jun Da)": "5736.0", "Tần Suất % (Jun Da)": "99.9719576882", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 弟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟弟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绨", "Unihan_Traditional (Chữ Phồn thể)": "綈", "Pinyin_Xie": "tí", "Âm Hán Việt_Xie": "đề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ chất liệu vải lụa thô dày thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疠', '{"9000": "5737.0", "Chữ Trung Quốc": "疠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 8 | nét | 疠 | lệ | tượng hình | bệnh hủi; dịch bệnh | 疠 là dạng giản thể của 癘. Bộ 疒 (nạch, bệnh tật) gợi nghĩa bệnh dịch nguy hiểm; phần còn lại biểu âm. Cấu trúc hình thanh nhưng Wiktionary không phân tích chi tiết IDS. Dạng Tiểu triện còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lệ\": bộ 疒 (bệnh) + âm lệ — bệnh \"lệ\" (lây lây) kinh khủng như dịch hạch; thành ngữ 瘴癘 tả vùng rừng thiêng nước độc. | Gương Hán-Việt | lệ trong 瘴癘 (chướng lệ) — khí độc và dịch bệnh rừng rậm | Mở khoá kiến thức | Biết 疠 mở khoá cụm 瘴癘 — thường dùng trong sử liệu tả vùng Lĩnh Nam, Vân Nam; nơi quan lại bị lưu đày thường chết vì \"chướng lệ\".", "Tự nguyên_Xie": "Tiểu triện | 疠 (phồn thể 癘) chỉ bệnh dịch nguy hiểm hoặc bệnh hủi (phong cùi). Bộ 疒 (bệnh tật) xác nhận đây là tên bệnh. Wiktionary liệt kê: bệnh dịch (epidemic), vết loét và dị thể của 癩 (phong cùi). Thường gặp trong cụm 瘴癘 (chướng lệ) — khí độc và dịch bệnh ở vùng rừng nhiệt đới. Dạng Tiểu triện còn lưu. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh hủi", "Hạng Tần Suất (Jun Da)": "5737.0", "Tần Suất % (Jun Da)": "99.9719985143", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 万", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒万", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "万", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "疠", "Unihan_Traditional (Chữ Phồn thể)": "癘", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các loại dịch bệnh nguy hiểm hoặc bệnh phong hủi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蘩', '{"9000": "5738.0", "Chữ Trung Quốc": "蘩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 20 | nét | 蘩 | phồn | tượng hình | cỏ bạch hao, ngải hương trắng | 蘩 có bộ 艸 (thảo, cỏ cây) gợi nghĩa thực vật; phần còn lại (繁 phồn) biểu âm và gợi hình ảnh um tùm. Cấu trúc hình thanh nhưng Wiktionary không phân tích chi tiết. Dạng Lục thư thông còn lưu hai ảnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phồn\": bộ 艸 (cỏ) + 繁 (phồn, phong phú) — cỏ 蘩 mọc \"phồn\" thịnh ở ven sông, người xưa hái dâng lễ tế trong Kinh Thi. | Gương Hán-Việt | phồn trong Kinh Thi — cỏ bạch hao dùng trong lễ tế | Mở khoá kiến thức | Biết 蘩 mở khoá vốn từ thực vật học Kinh Thi — cỏ 蘩 xuất hiện trong bài 采蘩 (Thái Phồn), tả người phụ nữ hái cỏ sáng sớm.", "Tự nguyên_Xie": "Lục thư thông | 蘩 chỉ loài Artemisia stelleriana (ngải dusty miller / bạch hao) — loài cỏ lá bạc trắng như phủ bụi, mọc ở bãi sông và bờ biển. Là một trong những loài cỏ được nhắc đến trong Kinh Thi — người xưa hái 蘩 cho lễ tế. Bộ 艸 (cỏ) xác nhận thực vật. Dạng Lục thư thông còn lưu. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ phiền, cỏ bạch hao (lá như lá ngải cứu nhỏ)", "Hạng Tần Suất (Jun Da)": "5738.0", "Tần Suất % (Jun Da)": "99.9720388235", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 繁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹繁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "繁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蘩", "Unihan_Traditional (Chữ Phồn thể)": "蘩", "Pinyin_Xie": "fán", "Âm Hán Việt_Xie": "phiền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loài cỏ tế tự trong thơ ca cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嵝', '{"9000": "5739.0", "Chữ Trung Quốc": "嵝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 12 | nét | 山 | sơn | biểu nghĩa | núi | 婁 | lâu | biểu âm | 嵝 = 山 (Sơn, biểu nghĩa: núi) + 婁 (Lâu, biểu âm); chữ hình thanh. Bộ 山 xác định đây là địa danh núi; 婁 cho âm lǒu/lāu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lũ\": bộ 山 (núi) + 婁 (lâu/lũ) — đỉnh Cẩu Lũ (岣嶁) nơi có tấm bia bí ẩn từ thời vua Hạ Vũ trị thủy, ẩn giấu trong mây mù Hành Sơn. | Gương Hán-Việt | lũ trong 岣嵝 (Cẩu Lũ) — đỉnh núi Hành Sơn Hồ Nam | Mở khoá kiến thức | Biết 嵝 mở khoá địa danh lịch sử 岣嶁 — đỉnh Hành Sơn và tấm bia 岣嶁碑 bí ẩn được Hàn Dũ và nhiều văn nhân đời Đường đến khám phá.", "Tự nguyên_Xie": "嵝 (phồn thể 嶁) chỉ đỉnh núi — đặc biệt dùng trong 岣嶁 (Cẩu Lũ) — tên đỉnh núi Hành Sơn ở Hồ Nam (một trong Ngũ Nhạc). Nổi tiếng vì 岣嶁碑 (Cẩu Lũ Bi) — tấm bia khắc chữ bí ẩn mà tương truyền do vua Hạ Vũ khắc khi trị thủy. Wiktionary phân tích hình thanh: 山 (núi, biểu nghĩa) + 婁 (biểu âm). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên núi)", "Hạng Tần Suất (Jun Da)": "5739.0", "Tần Suất % (Jun Da)": "99.9720791327", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 娄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山娄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "娄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "嵝", "Unihan_Traditional (Chữ Phồn thể)": "嶁", "Pinyin_Xie": "lǒu", "Âm Hán Việt_Xie": "lũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng trong địa danh như đỉnh núi Lũ Sơn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('庀', '{"9000": "5740.0", "Chữ Trung Quốc": "庀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 5 | nét | 庀 | tỉ | tượng hình | chuẩn bị, sắm sửa; quy định | 庀 có bộ 广 (nghiễm, mái nhà/công trình) gợi nghĩa quản lý, tổ chức; bên trong có thể là 匕 (tì, thìa) biểu âm. Không có dữ liệu Wiktionary hay anchor glyph. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỉ\": bộ 广 (nhà rộng) — người quản gia \"tỉ\" mỉ (tỉ mỉ) sắp xếp và chuẩn bị đầy đủ mọi thứ trong ngôi nhà lớn. | Gương Hán-Việt | tỉ trong cổ văn — chuẩn bị, sắm sửa đầy đủ | Mở khoá kiến thức | Biết 庀 mở khoá vốn từ hành chính cổ đại — chỉ việc chuẩn bị, trang bị đầy đủ trước khi thực hiện công việc lớn.", "Tự nguyên_Xie": "庀 có nghĩa chuẩn bị, sắm đủ, quy định. Bộ 广 (nhà rộng, quản lý) gợi hành động tổ chức và chuẩn bị trong không gian lớn. Không có dữ liệu glyph cổ hay phân tích cấu trúc từ Wiktionary. Chữ hiếm gặp trong văn bản hiện đại. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đủ, sắm", "Hạng Tần Suất (Jun Da)": "5740.0", "Tần Suất % (Jun Da)": "99.972119442", "GavinGrover_Once (Chiết tự trực tiếp)": "广 + 匕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴广匕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "广", "Unihan_Simplified (Chữ Giản thể)": "庀", "Unihan_Traditional (Chữ Phồn thể)": "庀", "Pinyin_Xie": "pǐ", "Âm Hán Việt_Xie": "phỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ trong văn ngôn với nghĩa chuẩn bị hoặc phân bổ công việc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('汜', '{"9000": "5741.0", "Chữ Trung Quốc": "汜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 6 | nét | 汜 | dẫy | tượng hình | nhánh nước rẽ rồi chảy về; sông Tỷ | 汜 có bộ 氵(thủy, nước) gợi nghĩa dòng chảy; phần còn lại (巳 tị) biểu âm. Cấu trúc hình thanh nhưng Wiktionary không phân tích chi tiết IDS. Dạng Giáp cốt văn và Tiểu triện còn lưu — là dấu hiệu chữ có nguồn gốc rất cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dẫy\": bộ 氵(nước) + 巳 (tị) — dòng nước \"dẫy\" (dẫn) đi xa rồi \"dẫy\" lại về, như người xa quê cuối cùng cũng trở về cội nguồn. | Gương Hán-Việt | dẫy trong địa mạo học cổ — nhánh sông tách ra rồi hợp lại | Mở khoá kiến thức | Biết 汜 mở khoá thơ Kinh Thi — bài 江有汜 (Giang hữu tỷ) dùng hình ảnh dòng nước lạc rồi về để tả mối tình duyên xa cách.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | 汜 chỉ dòng nước nhánh tách ra từ con sông chính rồi sau đó chảy trở lại — như dòng nước lạc lối rồi tìm về nguồn. Cũng là tên sông Tỷ ở Hà Nam. Bộ 氵 (nước) xác nhận địa mạo học. Dạng Giáp cốt văn đã có — chứng tỏ khái niệm này quan trọng trong văn hóa nông nghiệp ven sông từ thời Thương. Wiktionary liệt kê nhiều hợp từ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dòng nước đã rẽ ngang lại chảy về chỗ cũ; sông Tỷ", "Hạng Tần Suất (Jun Da)": "5741.0", "Tần Suất % (Jun Da)": "99.9721597512", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 巳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵巳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "汜", "Unihan_Traditional (Chữ Phồn thể)": "汜", "Pinyin_Xie": "sì", "Âm Hán Việt_Xie": "dĩ, tỉ, tỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ dòng nước rẽ ra rồi tụ lại hoặc dùng trong địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('炅', '{"9000": "5742.0", "Chữ Trung Quốc": "炅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 8 | nét | 火 | hoả | biểu ý | lửa | 日 | nhật | biểu ý | mặt trời | 炅 = 火 (Hoả, lửa) + 日 (Nhật, mặt trời); chữ hội ý. Lửa và mặt trời cùng tỏa sáng — hội tụ hai nguồn ánh sáng/nhiệt mạnh nhất để tạo nghĩa \"rực sáng, chói lọi\".", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không rõ (slug 炅); âm jiǒng: Hoả (lửa) + Nhật (mặt trời) hội ý — hình ảnh lửa và mặt trời cùng bừng sáng, tạo nên vẻ \"jiǒng\" — rực rỡ không thể nhìn thẳng. | Gương Hán-Việt | quýnh trong ý nghĩa \"rực sáng\" — Hán-Việt không phổ biến | Mở khoá kiến thức | Biết 炅 mở khoá hiểu cấu trúc hội ý — 火+日 là ví dụ điển hình của chữ hội ý kết hợp hai yếu tố thị giác để tạo nghĩa trừu tượng.", "Tự nguyên_Xie": "Tiểu triện | 炅 là chữ hội ý: 火 (lửa) + 日 (mặt trời). Kết hợp hai nguồn sáng và nhiệt mạnh nhất — ánh lửa và mặt trời — để diễn đạt sự rực rỡ, chói sáng. Wiktionary xác nhận \"{{Han compound|火|日|t1=fire|t2=sun|ls=ic}}\". Đọc jiǒng (sáng rực) hoặc guì (họ người). Dạng Tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ánh mặt trời", "Hạng Tần Suất (Jun Da)": "5742.0", "Tần Suất % (Jun Da)": "99.9722000605", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 火", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱日火", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "火", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "炅", "Unihan_Traditional (Chữ Phồn thể)": "炅", "Pinyin_Xie": "jiǒng", "Âm Hán Việt_Xie": "quý, quýnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ chỉ sự sáng sủa hoặc làm danh từ riêng trong tên người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('煳', '{"9000": "5743.0", "Chữ Trung Quốc": "煳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 13 | nét | 煳 | hồ | tượng hình | cháy khét, cháy sém | 煳 có bộ 火 (hoả, lửa) gợi nghĩa liên quan đến nhiệt/lửa; phần còn lại (胡 hồ) biểu âm. Cấu trúc hình thanh nhưng không có dữ liệu Wiktionary hay anchor glyph. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồ\": bộ 火 (lửa) + 胡 (hồ, âm) — nồi cơm bị \"hồ\" (cháy khét), mùi khói lan tỏa khắp bếp, nhắc nhở không được để quên lửa. | Gương Hán-Việt | hồ trong nấu ăn — cháy khét, cơm khê | Mở khoá kiến thức | Biết 煳 mở khoá vốn từ nấu ăn và khẩu ngữ — chỉ tình trạng thức ăn bị cháy sém, thường gặp trong mô tả ẩm thực và đời sống hằng ngày.", "Tự nguyên_Xie": "煳 chỉ trạng thái cháy khét hoặc cháy sém trong nấu ăn — thức ăn bị để quá lửa tạo mùi khét. Bộ 火 (lửa) xác nhận liên quan đến nhiệt. Phần biểu âm 胡 (hú/hồ) cho âm. Không có dữ liệu glyph cổ hay phân tích từ Wiktionary. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cháy, khét; cháy sém", "Hạng Tần Suất (Jun Da)": "5743.0", "Tần Suất % (Jun Da)": "99.9722403697", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 胡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火胡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "胡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "煳", "Unihan_Traditional (Chữ Phồn thể)": "煳", "Pinyin_Xie": "hú", "Âm Hán Việt_Xie": "hồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho thức ăn bị nấu quá lửa hoặc làm động từ chỉ việc bị cháy khét. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泶', '{"9000": "5744.0", "Chữ Trung Quốc": "泶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 泶 | học | tượng hình | vùng nước theo mùa — có nước mùa hạ, cạn mùa đông | 泶 là dạng giản thể của 澩. Bộ 氵(thủy, nước) gợi nghĩa liên quan đến nước; phần còn lại biểu âm. Cấu trúc hình thanh nhưng Wiktionary chỉ có {{Han etym}} mà không phân tích. Dạng Tiểu triện còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"học\": bộ 氵(nước) + âm học — vùng đầm \"học\" (học hỏi theo mùa): mùa hạ đầy nước, mùa đông cạn khô — thiên nhiên biến đổi theo chu kỳ. | Gương Hán-Việt | học trong địa mạo học cổ — đầm nước theo mùa | Mở khoá kiến thức | Biết 泶 mở khoá vốn từ địa lý cổ đại Trung Hoa — chỉ loại địa hình nước đặc biệt theo mùa, thường gặp trong sách địa lý và thủy văn cổ.", "Tự nguyên_Xie": "Tiểu triện | 泶 (phồn thể 澩) chỉ vùng nước đặc biệt — có nước vào mùa hạ nhưng cạn vào mùa đông, như đầm hoặc vùng trũng theo mùa. Bộ 氵(nước) xác nhận đây là địa hình nước. Dạng Tiểu triện còn lưu. Wiktionary chỉ có {{Han etym}}. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vùng núi có nước vào mùa hạ, không có nước trong mùa đông", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 水", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴水", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "泶", "Unihan_Traditional (Chữ Phồn thể)": "泶", "Pinyin_Xie": "xué", "Âm Hán Việt_Xie": "hạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ hiện tượng nước chảy ở khe núi vào mùa hè hoặc khô cạn vào mùa đông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瓠', '{"9000": "5745.0", "Chữ Trung Quốc": "瓠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 瓜 | Số nét | 11 | nét | 瓠 | hộ | tượng hình | quả bầu; bình đựng nước từ bầu khô | 瓠 có bộ 瓜 (qua, bầu bí) gợi nghĩa loài thực vật leo; phần còn lại biểu âm. Cấu trúc hình thanh nhưng Wiktionary chỉ có {{Han etym}} mà không phân tích chi tiết. Dạng Tiểu triện và Lục thư thông còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hộ\": bộ 瓜 (bầu) — quả 瓠 (bầu hộ) treo lủng lẳng trên giàn như chiếc bình thiên nhiên, người xưa phơi khô dùng đựng nước. | Gương Hán-Việt | hộ trong Kinh Thi — bầu 瓠/匏 biểu tượng sự cống hiến | Mở khoá kiến thức | Biết 瓠 mở khoá từ 匏瓜 (bào qua) và vốn từ Kinh Thi — hình ảnh quả bầu trong thơ cổ biểu tượng cho sự hữu dụng hoặc lãng phí tùy ngữ cảnh.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 瓠 chỉ quả bầu dài (bottle gourd) — loài bầu dùng để đựng nước hoặc chứa rượu sau khi phơi khô ruột. Là loại cây được nhắc đến trong Kinh Thi (từ 匏 và 瓠). Bộ 瓜 (bầu bí) xác nhận đây là loài thực vật thuộc họ bầu bí. Dạng Tiểu triện và ba ảnh Lục thư thông còn lưu. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bầu đựng nước làm từ quả bầu khô", "Hạng Tần Suất (Jun Da)": "5745.0", "Tần Suất % (Jun Da)": "99.9723209882", "GavinGrover_Once (Chiết tự trực tiếp)": "夸 + 瓜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰夸瓜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "瓜", "Unihan_Simplified (Chữ Giản thể)": "瓠", "Unihan_Traditional (Chữ Phồn thể)": "瓠", "Pinyin_Xie": "hù", "Âm Hán Việt_Xie": "hồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ quả bầu hoặc vỏ bầu khô dùng làm bình đựng nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窳', '{"9000": "5746.0", "Chữ Trung Quốc": "窳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 15 | nét | 窳 | dũ | tượng hình | xấu, vô dụng, yếu kém; bị nứt vỡ | 窳 có bộ 穴 (huyệt, hang hốc) gợi nghĩa chỗ trống rỗng hoặc lỗ hổng; phần còn lại biểu âm. Cấu trúc hình thanh nhưng không có dữ liệu Wiktionary. Dạng Tiểu triện và Lục thư thông còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dũ\": bộ 穴 (hang rỗng) — vật \"dũ\" (yếu ớt) như bình gốm rỗng có vết nứt bên trong, dễ vỡ và vô dụng. | Gương Hán-Việt | dũ trong cổ văn phê bình — xấu kém, vô dụng | Mở khoá kiến thức | Biết 窳 mở khoá vốn từ phê phán trong cổ văn — chỉ sản phẩm kém chất lượng hoặc đạo đức suy đồi, thường gặp trong sử liệu và văn bản kinh tế cổ đại.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 窳 chỉ những thứ xấu, vô dụng, yếu kém hoặc bị nứt vỡ. Bộ 穴 (hang hốc) gợi hình ảnh vật bị rỗng ruột, thiếu sức mạnh bên trong. Không có dữ liệu Wiktionary hay phân tích glyph chi tiết. Dạng Tiểu triện và Lục thư thông còn lưu ảnh. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xấu, vô dụng", "Hạng Tần Suất (Jun Da)": "5746.0", "Tần Suất % (Jun Da)": "99.9723612974", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 㼌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴㼌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㼌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窳", "Unihan_Traditional (Chữ Phồn thể)": "窳", "Pinyin_Xie": "yǔ", "Âm Hán Việt_Xie": "dũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ để mô tả sự lười biếng, suy đồi hoặc chất lượng kém của đồ vật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虮', '{"9000": "5747.0", "Chữ Trung Quốc": "虮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 8 | nét | 虮 | ký | tượng hình | trứng rận, chấy | 虮 có bộ 虫 (trùng, sâu bọ) gợi nghĩa loài ký sinh trùng; phần còn lại (几 ki) biểu âm. Cấu trúc hình thanh nhưng Wiktionary chỉ có {{Han etym}} mà không phân tích chi tiết. Dạng Tiểu triện còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ký\": bộ 虫 (sâu bọ) + 几 (ki, âm) — con 虮 (ký) nhỏ như hạt cám bám vào tóc, khó phát hiện nhưng gây ngứa ngáy. | Gương Hán-Việt | ký trong 虮虱 (ký thật) — chấy rận, kẻ ti tiện nhỏ nhoi | Mở khoá kiến thức | Biết 虮 mở khoá từ 虮虱 — tổ hợp chỉ chấy rận, dùng trong cả nghĩa đen và nghĩa bóng (kẻ ti tiện, vật nhỏ không đáng kể).", "Tự nguyên_Xie": "Tiểu triện | 虮 chỉ trứng rận (nits) — trứng của chấy rận bám vào tóc hoặc lông. Bộ 虫 (sâu bọ/ký sinh) xác nhận đây là loài côn trùng ký sinh. Dạng Tiểu triện còn lưu. Wiktionary chỉ có {{Han etym}}. Thường gặp trong thành ngữ 虮虱 (ký thật) — chấy rận, dùng tả kẻ nhỏ bé ti tiện. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trứng rận", "Hạng Tần Suất (Jun Da)": "5747.0", "Tần Suất % (Jun Da)": "99.9724016067", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 几", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫几", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "几", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "虮", "Unihan_Traditional (Chữ Phồn thể)": "蟣", "Pinyin_Xie": "jǐ", "Âm Hán Việt_Xie": "kỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ trứng của con rận hoặc các loại ký sinh trùng nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚰', '{"9000": "5748.0", "Chữ Trung Quốc": "蚰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 11 | nét | 蚰 | du diên | tượng hình | con rết nhỏ (蚰蜒) | 蚰 là chữ dùng riêng trong từ 蚰蜒 (du diên — rết nhỏ/cuốn chiếu). Không có phân tích hình thanh/hội ý rõ ràng từ nguồn học thuật; coi như tượng hình hoặc chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du diên\" (蚰蜒): bộ 虫 (trùng) gợi loài sâu bọ — con du diên bò lên tường khiến người run rẩy. | Gương Hán-Việt | 蚰蜒 (du diên) — rết nhỏ, cuốn chiếu | Mở khoá kiến thức | Biết 蚰 giúp nhận ra từ 蚰蜒 chỉ loài rết nhỏ trong văn bản y học hoặc thơ cổ.", "Tự nguyên_Xie": "Chữ 蚰 chỉ xuất hiện trong từ ghép 蚰蜒 (du diên), chỉ loài rết nhỏ hay cuốn chiếu. Wiktionary không có thông tin nguồn gốc cụ thể; chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: du diên 蚰蜒)", "Hạng Tần Suất (Jun Da)": "5748.0", "Tần Suất % (Jun Da)": "99.9724419159", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 由", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫由", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "由", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚰", "Unihan_Traditional (Chữ Phồn thể)": "蚰", "Pinyin_Xie": "yóu", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong từ ghép để chỉ một loài động vật chân khớp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邰', '{"9000": "5749.0", "Chữ Trung Quốc": "邰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 7 | nét | 邰 | thai | tượng hình | tên nước cổ thời Hạ, họ người | 邰 là địa danh và họ người. Không có phân tích hình thanh/hội ý rõ ràng từ nguồn học thuật; dạng tiểu triện có sẵn. Chữ có bộ 邑 (ấp) nhưng cấu trúc không được Wiktionary phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thai\" (邰): bộ 邑 (ấp, làng) gợi vùng đất — nước Thai là vùng đất của tổ tiên nhà Chu trong truyền thuyết. | Gương Hán-Việt | 邰 — họ người và tên nước cổ, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 邰 giúp nhận ra họ邰 trong văn bản lịch sử Trung Hoa và địa danh cổ.", "Tự nguyên_Xie": "Tiểu triện | 邰 là tên một nước cổ thời Hạ, nay thuộc huyện Vũ Công, tỉnh Thiểm Tây. Cũng dùng làm họ người. Wiktionary chỉ ghi nhận phát âm và nghĩa địa danh, không có phân tích cấu trúc chi tiết. Chưa có nguồn học thuật rõ ràng về nguồn gốc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Thai", "Hạng Tần Suất (Jun Da)": "5749.0", "Tần Suất % (Jun Da)": "99.9724822251", "GavinGrover_Once (Chiết tự trực tiếp)": "台 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰台阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "台", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邰", "Unihan_Traditional (Chữ Phồn thể)": "邰", "Pinyin_Xie": "tái", "Âm Hán Việt_Xie": "thai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng chỉ địa danh cổ hoặc họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苊', '{"9000": "5750.0", "Chữ Trung Quốc": "苊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 厄 | ách | biểu âm | biểu âm | 苊 = 艹 (Thảo, biểu nghĩa: cỏ/thực vật) + 厄 (Ách, biểu âm); chữ hình thanh. Phần 艹 cho biết đây là hợp chất liên quan đến thực vật; phần 厄 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ách\" (苊): bộ 艹 (thảo) + 厄 (ách) — hình dung chất hữu cơ acenaphthylene như một \"ách\" (gánh nặng) trên thế giới thực vật hóa học. | Gương Hán-Việt | 苊 — ít xuất hiện trong từ Hán-Việt thông dụng; chủ yếu dùng trong thuật ngữ hóa học | Mở khoá kiến thức | Biết 苊 giúp đọc được tên hợp chất hữu cơ acenaphthylene trong tài liệu hóa học Trung-Việt.", "Tự nguyên_Xie": "Theo Wiktionary, 苊 là chữ hình thanh: 艹 (cỏ/thực vật) là phần biểu nghĩa, 厄 là phần biểu âm. Chữ được dùng để phiên âm tên hợp chất hữu cơ acenaphthylene (苊, C₁₂H₁₀) trong hóa học hiện đại — đây là chữ tạo muộn phục vụ dịch thuật khoa học. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "A-xê-nap-ten (công thức : C12H10); Ghi chú: (英acenaphthene)", "Hạng Tần Suất (Jun Da)": "5750.0", "Tần Suất % (Jun Da)": "99.9725220176", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 厄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹厄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苊", "Unihan_Traditional (Chữ Phồn thể)": "苊", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong thuật ngữ hóa học để chỉ một loại hợp chất hữu cơ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砀', '{"9000": "5751.0", "Chữ Trung Quốc": "砀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 8 | nét | 砀 | đãng | tượng hình | đá hoa văn, đá nhiều màu | 砀 (giản thể của 碭) là chữ chỉ loại đá có hoa văn đẹp. Wiktionary chỉ ghi {{Han etym}} mà không phân tích cấu trúc chi tiết; dạng tiểu triện và lục thư thông có sẵn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đãng\" (砀): bộ 石 (thạch, đá) gợi chất liệu — đá 砀 là loại đá hoa văn rực rỡ như sóng 荡 (đãng) cuộn trên bề mặt. | Gương Hán-Việt | 砀 — ít dùng trong từ Hán-Việt thông dụng; chủ yếu trong địa danh (Đãng Sơn) | Mở khoá kiến thức | Biết 砀 giúp nhận ra địa danh 砀山 (Đãng Sơn) ở An Huy, Trung Quốc trong văn bản lịch sử.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 砀 là giản thể của 碭, chỉ loại đá có hoa văn sặc sỡ. Wiktionary không cung cấp phân tích cấu trúc chi tiết (chỉ ghi Han etym). Dạng tiểu triện và lục thư thông còn lưu lại. Chưa có nguồn học thuật rõ ràng về nguồn gốc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đá hoa", "Hạng Tần Suất (Jun Da)": "5751.0", "Tần Suất % (Jun Da)": "99.9725618101", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 𠃓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石𠃓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠃓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砀", "Unihan_Traditional (Chữ Phồn thể)": "碭", "Pinyin_Xie": "dàng", "Âm Hán Việt_Xie": "đãng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ loại đá hoa hoặc tính từ chỉ sự rực rỡ, rộng lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('捩', '{"9000": "5752.0", "Chữ Trung Quốc": "捩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 捩 | lệ | tượng hình | vặn, xoay bằng tay | 捩 có bộ 手 (thủ, tay) nhưng Wiktionary không phân tích cấu trúc chi tiết. Không có lsCodes; coi như chữ không rõ cấu trúc hình thanh/hội ý theo nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lệ\" (捩): bộ 扌 (thủ, tay) + hình dạng gợi xoắn — tay 捩 vặn mạnh như vặn khăn ướt cho ráo nước. | Gương Hán-Việt | 捩 — ít xuất hiện trong từ Hán-Việt thông dụng; dùng trong văn bản cổ | Mở khoá kiến thức | Biết 捩 giúp đọc từ 转捩点 (zhuǎnlìdiǎn — điểm ngoặt, bước ngoặt) trong văn bản chính luận.", "Tự nguyên_Xie": "Chữ 捩 chỉ hành động vặn xoắn hoặc bẻ gãy bằng tay. Wiktionary chỉ ghi {{Han etym}} mà không có phân tích cấu trúc. Từ hình thức, bộ 手 (扌, tay) gợi hành động thủ công, nhưng nguồn gốc chính xác chưa được xác nhận học thuật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xoay; vặn", "Hạng Tần Suất (Jun Da)": "5752.0", "Tần Suất % (Jun Da)": "99.9726016025", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 戾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌戾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "捩", "Unihan_Traditional (Chữ Phồn thể)": "捩", "Pinyin_Xie": "liè", "Âm Hán Việt_Xie": "liệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ chỉ hành động xoay chuyển, vặn hoặc bẻ cong một vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹉', '{"9000": "5753.0", "Chữ Trung Quốc": "蹉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 16 | nét | 足 | tú | biểu nghĩa | chân | 差 | sai | biểu âm | biểu âm | 蹉 = 足 (Tú, biểu nghĩa: chân) + 差 (Sai, biểu âm); chữ hình thanh. Phần 足 cho biết nghĩa liên quan đến chân/bước đi; phần 差 cung cấp âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tha\" (蹉): bộ 足 (tú, chân) + 差 (sai) — chân bước sai một bước là 蹉 — trượt ngã, lỡ mất cơ hội. | Gương Hán-Việt | 蹉跎 (tha đà) — lãng phí thời gian, để tháng ngày trôi qua vô ích | Mở khoá kiến thức | Biết 蹉 giúp đọc thành ngữ 蹉跎岁月 (tha đà tuế nguyệt — lãng phí năm tháng) trong thơ văn cổ.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 蹉 là chữ hình thanh: 足 (chân) là phần biểu nghĩa, 差 là phần biểu âm. Nghĩa gốc là trượt chân, vấp ngã; mở rộng sang nghĩa phạm sai lầm, bỏ lỡ. Dạng tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sa chân; sẩy chân trượt ngã", "Hạng Tần Suất (Jun Da)": "5753.0", "Tần Suất % (Jun Da)": "99.972641395", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 差", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊差", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "差", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹉", "Unihan_Traditional (Chữ Phồn thể)": "蹉", "Pinyin_Xie": "cuō", "Âm Hán Việt_Xie": "tha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ chỉ hành động sẩy chân hoặc lãng phí thời gian trong từ ghép. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莪', '{"9000": "5754.0", "Chữ Trung Quốc": "莪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 艸 | tháo | biểu nghĩa | cỏ, thực vật | 我 | ngã | biểu âm | biểu âm | 莪 = 艸 (Tháo, biểu nghĩa: cỏ/thực vật) + 我 (Ngã, biểu âm); chữ hình thanh. Bộ 艸 xác định đây là loài thực vật; 我 cung cấp âm đọc gần với é.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngò\" (莪): bộ 艸 (tháo, cỏ) + 我 (ngã — tôi) — \"tôi\" là cỏ nga, loài thảo mộc xuất hiện trong thơ Kinh Thi như lời tự xưng của thiên nhiên. | Gương Hán-Việt | 莪蒿 (ngò hao) — tên loài cỏ; 蓼莪 (liễu ngò) — bài thơ trong Kinh Thi | Mở khoá kiến thức | Biết 莪 giúp đọc tên thực vật cổ và tên bài thơ 蓼莪 trong Kinh Thi (thơ về nỗi nhớ cha mẹ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 莪 là chữ hình thanh: 艸 (cỏ/thực vật) là phần biểu nghĩa, 我 là phần biểu âm. Chữ chỉ loài cỏ nga (một loại Artemisia hay Incarvillea sinensis), xuất hiện trong Kinh Thi. Dạng tiểu triện và lục thư thông còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ nga", "Hạng Tần Suất (Jun Da)": "5754.0", "Tần Suất % (Jun Da)": "99.9726811874", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 我", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹我", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "我", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莪", "Unihan_Traditional (Chữ Phồn thể)": "莪", "Pinyin_Xie": "é", "Âm Hán Việt_Xie": "nga", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại cỏ tế hoặc rau ngải cứu hoang. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螽', '{"9000": "5755.0", "Chữ Trung Quốc": "螽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 17 | nét | 螽 | chung | tượng hình | châu chấu, cào cào (loài côn trùng) | 螽 là chữ chỉ loài cào cào/châu chấu. Wiktionary không phân tích cấu trúc chi tiết; chỉ có ảnh lục thư thông. Coi như chữ tạo muộn hoặc tượng hình không rõ nguồn gốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chung\" (螽): bộ 虫 (trùng, sâu bọ) ẩn trong chữ — tiếng cào cào kêu \"chung chung\" vào mùa thu như âm thanh cuối mùa. | Gương Hán-Việt | 螽斯 (chung ti) — cào cào; biểu tượng con cháu đông đúc trong thơ Kinh Thi | Mở khoá kiến thức | Biết 螽 giúp đọc từ 螽斯 (chung ti) trong Kinh Thi, biểu tượng phồn thực và con cháu đông đúc.", "Tự nguyên_Xie": "Lục thư thông | Chữ 螽 chỉ loài côn trùng thuộc họ cào cào (katydid). Wiktionary chỉ ghi {{Han etym}} mà không có phân tích cấu trúc. Chỉ có dạng lục thư thông (Minh mạt), không có giáp cốt hay kim văn — chữ tạo muộn. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loài sâu)", "Hạng Tần Suất (Jun Da)": "5755.0", "Tần Suất % (Jun Da)": "99.9727209799", "GavinGrover_Once (Chiết tự trực tiếp)": "冬 + 䖵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱冬䖵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䖵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冬", "Unihan_Simplified (Chữ Giản thể)": "螽", "Unihan_Traditional (Chữ Phồn thể)": "螽", "Pinyin_Xie": "zhōng", "Âm Hán Việt_Xie": "chung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các loài côn trùng thuộc bộ Cánh thẳng như cào cào, muồm muỗm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蘼', '{"9000": "5756.0", "Chữ Trung Quốc": "蘼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 22 | nét | 蘼 | mi | tượng hình | loài cỏ dùng trong tên thực vật | 蘼 là chữ phức tạp chỉ dùng trong tên thực vật như 蘼蕪, 荼蘼. Wiktionary không phân tích cấu trúc chi tiết; không có ảnh glyph cổ. Coi như chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mi\" (蘼): chữ lớn, phức tạp như chính loài cây 蘼蕪 um tùm — bộ 艸 (thảo) ẩn bên trên gợi thực vật rậm rạp. | Gương Hán-Việt | 蘼蕪 (mi vô) — cỏ thơm; 荼蘼 (đồ mi) — hoa cuối mùa, biểu tượng tàn phai | Mở khoá kiến thức | Biết 蘼 giúp nhận ra 荼蘼 (đồ mi) trong thơ văn — hình ảnh hoa tàn cuối xuân, biểu tượng kết thúc và chia ly.", "Tự nguyên_Xie": "Chữ 蘼 chỉ dùng trong tên cây như 蘼蕪 (mi vô — một loài cỏ thơm) và 荼蘼 (đồ mi — loài hoa leo). Wiktionary không có phân tích nguồn gốc cụ thể. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loại tảo", "Hạng Tần Suất (Jun Da)": "5756.0", "Tần Suất % (Jun Da)": "99.972800048", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 靡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹靡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "靡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蘼", "Unihan_Traditional (Chữ Phồn thể)": "蘼", "Pinyin_Xie": "mí", "Âm Hán Việt_Xie": "mi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại cỏ thơm dùng trong y học cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('槔', '{"9000": "5757.0", "Chữ Trung Quốc": "槔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 14 | nét | 槔 | cau | tượng hình | gầu nước, cần vọt múc nước giếng | 槔 chỉ dùng trong từ 桔槔 (kết cau — cần vọt múc nước). Wiktionary tham chiếu dạng cổ 橰 nhưng không phân tích cấu trúc. Bộ 木 (mộc, gỗ) gợi dụng cụ làm bằng gỗ; tổng thể là chữ tạo muộn không rõ hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cau\" (槔): bộ 木 (mộc, gỗ) gợi cần vọt bằng gỗ — 桔槔 là cái gầu cau cau lên xuống múc nước giếng như người cúi đầu cần cù. | Gương Hán-Việt | 桔槔 (kết cau) — cần vọt múc nước giếng | Mở khoá kiến thức | Biết 槔 giúp đọc từ 桔槔 trong văn bản kỹ thuật nông nghiệp cổ đại Trung Hoa.", "Tự nguyên_Xie": "Chữ 槔 chỉ dùng trong từ 桔槔 (kết cau), chỉ loại cần vọt gỗ dùng để múc nước giếng — một công cụ thủy lợi cổ truyền. Wiktionary tham chiếu dạng cổ 橰 nhưng không có phân tích nguồn gốc chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: kết cao 桔槔)", "Hạng Tần Suất (Jun Da)": "5757.0", "Tần Suất % (Jun Da)": "99.9728393237", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 皋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木皋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "槔", "Unihan_Traditional (Chữ Phồn thể)": "槔", "Pinyin_Xie": "gāo", "Âm Hán Việt_Xie": "cao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong từ ghép chỉ dụng cụ múc nước cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('曛', '{"9000": "5758.0", "Chữ Trung Quốc": "曛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 18 | nét | 曛 | huân | tượng hình | ánh nắng chiều tà, hoàng hôn | 曛 có bộ 日 (nhật, mặt trời) nhưng Wiktionary không phân tích cấu trúc chi tiết. Từ hình thức, có thể là hình thanh với 日 biểu nghĩa, nhưng nguồn học thuật không xác nhận. Coi như chữ không rõ cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huân\" (曛): bộ 日 (nhật, mặt trời) gợi cảnh — mặt trời tắt dần như lửa 薰 (huân), để lại màu vàng huyền 曛 trên nền trời. | Gương Hán-Việt | 曛 — ít dùng trong từ Hán-Việt thông dụng; chủ yếu trong thơ văn cổ tả hoàng hôn | Mở khoá kiến thức | Biết 曛 giúp đọc thơ Đường tả cảnh chiều tà như 夕曛 (tịch huân — ánh chiều tàn).", "Tự nguyên_Xie": "Chữ 曛 chỉ ánh sáng vàng đỏ của mặt trời lúc hoàng hôn, cảnh chiều tà. Wiktionary chỉ ghi {{Han etym}} mà không có phân tích cấu trúc. Không có ảnh glyph cổ. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nắng quái, ánh sáng thừa của mặt trời lúc lặn", "Hạng Tần Suất (Jun Da)": "5758.0", "Tần Suất % (Jun Da)": "99.9728785993", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 熏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日熏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "熏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "曛", "Unihan_Traditional (Chữ Phồn thể)": "曛", "Pinyin_Xie": "xūn", "Âm Hán Việt_Xie": "huân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ ánh sáng lúc hoàng hôn hoặc tính từ chỉ sự u tối. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛲', '{"9000": "5759.0", "Chữ Trung Quốc": "蛲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 蛲 | nhiêu | tượng hình | giun kim (ký sinh trùng) | 蛲 là giản thể của 蟯, rút gọn phần 堯 thành 尧. Bộ 虫 (trùng, sâu bọ) xác định đây là loài ký sinh trùng; phần còn lại biểu âm. Đây là chữ giản hóa hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhiêu\" (蛲): bộ 虫 (trùng, sâu bọ) + 尧 (nhiêu, biểu âm) — giun kim 蛲虫 là loài sâu bọ gây ngứa ngáy \"nhiêu nhương\" trong ruột trẻ em. | Gương Hán-Việt | 蛲虫 (nhiêu trùng) — giun kim | Mở khoá kiến thức | Biết 蛲 giúp đọc thuật ngữ y học 蛲虫病 (bệnh giun kim) trong tài liệu nhi khoa.", "Tự nguyên_Xie": "Tiểu triện | 蛲 là dạng giản thể của 蟯 (giun kim, loài ký sinh trùng ruột), rút gọn phần 堯 thành 尧. Bộ 虫 (sâu bọ) biểu nghĩa; phần biểu âm 尧/堯 gợi âm náo/nhiêu. Dạng tiểu triện của 蟯 còn lưu lại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giun kim, lãi kim", "Hạng Tần Suất (Jun Da)": "5759.0", "Tần Suất % (Jun Da)": "99.972917875", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 尧", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫尧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛲", "Unihan_Traditional (Chữ Phồn thể)": "蟯", "Pinyin_Xie": "náo", "Âm Hán Việt_Xie": "nhiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ trong y học để chỉ loài giun kim. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹾', '{"9000": "5760.0", "Chữ Trung Quốc": "鹾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹵 | Số nét | 16 | nét | 鹵 | lỗ | biểu nghĩa | muối | 差 | sai | biểu âm | biểu âm | 鹾 = 鹵 (Lỗ, biểu nghĩa: muối) + 差 (Sai, biểu âm); chữ hình thanh. Bộ 鹵 xác định nghĩa liên quan đến muối; phần 差 cung cấp âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tán\" (鹾): 鹵 (lỗ, muối) + 差 (sai, biểu âm) — muối 鹾 có vị mặn \"sai\" khác hẳn mọi vị khác, không thể lẫn lộn. | Gương Hán-Việt | 鹾 — ít dùng trong từ Hán-Việt thông dụng; chủ yếu trong văn bản ẩm thực và y học cổ | Mở khoá kiến thức | Biết 鹾 giúp đọc từ 鹾务 (tán vụ — công vụ muối, thuế muối) trong văn bản lịch sử kinh tế Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 鹾 (phồn thể 鹺) là chữ hình thanh: 鹵 (muối) là phần biểu nghĩa, 差 là phần biểu âm. Nghĩa là vị mặn, muối. Dạng tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mặn, vị mặn", "Hạng Tần Suất (Jun Da)": "5760.0", "Tần Suất % (Jun Da)": "99.9729571507", "GavinGrover_Once (Chiết tự trực tiếp)": "卤 + 差", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰卤差", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "差", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "卤", "Unihan_Simplified (Chữ Giản thể)": "鹾", "Unihan_Traditional (Chữ Phồn thể)": "鹺", "Pinyin_Xie": "cuó", "Âm Hán Việt_Xie": "ta", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng trong văn viết cổ làm danh từ chỉ muối hoặc tính từ chỉ vị mặn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隹', '{"9000": "5761.0", "Chữ Trung Quốc": "隹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 隹 | Số nét | 8 | nét | 隹 | chuy | tượng hình | chim đuôi ngắn (chim sẻ) | 隹 là chữ tượng hình độc lập, mô tả hình dáng con chim đuôi ngắn (như chim sẻ). Đây là bộ thủ 172 trong Khang Hi tự điển, xuất hiện trong giáp cốt văn và kim văn. Tự thân là tượng hình, không phân tích thêm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chuy\" (隹): chữ tượng hình vẽ con chim đuôi ngắn đứng thẳng — khác 鳥 (điểu) có đuôi dài rũ xuống; 隹 là chim sẻ chuy chuy đứng thẳng đuôi. | Gương Hán-Việt | 隹 là bộ thủ trong: 集 (tập — chim tụ), 雄 (hùng), 雌 (thư), 雀 (tước — chim sẻ), 雁 (nhạn) | Mở khoá kiến thức | Biết 隹 mở khóa hàng chục chữ bộ chim: 集 (tập), 雄 (hùng), 雌 (thư), 雀 (tước), 雁 (nhạn), 難 (nan), 雙 (song).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 隹 là chữ tượng hình (象形): hình vẽ con chim đuôi ngắn, ví dụ chim sẻ. Ngoài nghĩa chim đuôi ngắn, 隹 còn là dạng gốc của 鷕 (tiếng chim kêu). So sánh với 鳥 (điểu, chim đuôi dài). Các dạng giáp cốt, kim văn, đại triện và tiểu triện đều còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "175.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Vẽ hình một loài chim đuôi ngắn.", "Nghĩa Tiếng Việt_Xie": "chim đuôi ngắn", "Hạng Tần Suất (Jun Da)": "5761.0", "Tần Suất % (Jun Da)": "99.9729964264", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "隹", "Unihan_Traditional (Chữ Phồn thể)": "隹", "Pinyin_Xie": "zhuī", "Âm Hán Việt_Xie": "chuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong văn ngôn hoặc làm bộ thủ cấu tạo chữ Hán. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('犸', '{"9000": "5762.0", "Chữ Trung Quốc": "犸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 6 | nét | 犭 | khuyển | biểu nghĩa | thú, động vật | 馬 | mã | biểu âm | biểu âm | 犸 = 犭 (Khuyển, biểu nghĩa: thú/động vật) + 馬 (Mã, biểu âm); chữ hình thanh. Bộ 犭 xác định đây là loài thú; phần 馬 cung cấp âm đọc mà/mà.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mã\" (犸): bộ 犭 (khuyển, thú) + 馬 (mã, ngựa) — con voi ma mút 猛犸 to như ngựa khổng lồ, vừa mạnh vừa thú. | Gương Hán-Việt | 猛犸 (mãnh mã) — voi ma mút (mammoth) | Mở khoá kiến thức | Biết 犸 giúp nhận ra 猛犸象 (mãnh mã tượng — voi ma mút) trong văn bản khoa học và lịch sử tự nhiên.", "Tự nguyên_Xie": "Theo Wiktionary, 犸 (phồn thể 獁) là chữ hình thanh: 犭 (thú) là phần biểu nghĩa, 馬 là phần biểu âm. Chữ dùng để phiên âm từ \"mammoth\" (voi ma mút) trong từ 猛犸 (mãnh mã). Đây là chữ tạo muộn phục vụ dịch thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mãnh mã 猛獁,猛犸)", "Hạng Tần Suất (Jun Da)": "5762.0", "Tần Suất % (Jun Da)": "99.973035702", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 马", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭马", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "马", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "犸", "Unihan_Traditional (Chữ Phồn thể)": "獁", "Pinyin_Xie": "mà", "Âm Hán Việt_Xie": "mã", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này hầu như chỉ dùng trong từ ghép để chỉ loài voi ma mút. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衄', '{"9000": "5763.0", "Chữ Trung Quốc": "衄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 血 | Số nét | 10 | nét | 血 | huyết | biểu nghĩa | máu | 丑 | sửu | biểu âm | biểu âm | 衄 = 血 (Huyết, biểu nghĩa: máu) + 丑 (Sửu, biểu âm); chữ hình thanh. Bộ 血 xác định nghĩa liên quan đến máu; phần 丑 cung cấp âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nục\" (衄): 血 (huyết, máu) + 丑 (sửu, biểu âm) — máu 血 chảy cam lộng ra mũi là 衄 — \"nục\" máu, hình ảnh không thể nhầm. | Gương Hán-Việt | 衄血 (nục huyết) — chảy máu cam; 鼻衄 (tỵ nục) — máu mũi | Mở khoá kiến thức | Biết 衄 giúp đọc thuật ngữ y học 鼻衄 (tỵ nục — chảy máu cam) và 衄血 (nục huyết) trong tài liệu y học cổ truyền.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 衄 là chữ hình thanh: 血 (máu) là phần biểu nghĩa, 丑 là phần biểu âm. Nghĩa gốc là chảy máu cam (máu mũi); nghĩa mở rộng là thất bại trong trận chiến. Dạng tiểu triện và lục thư thông còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đổ máu cam", "Hạng Tần Suất (Jun Da)": "5763.0", "Tần Suất % (Jun Da)": "99.9730749777", "GavinGrover_Once (Chiết tự trực tiếp)": "血 + 丑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰血丑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "血", "Unihan_Simplified (Chữ Giản thể)": "衄", "Unihan_Traditional (Chữ Phồn thể)": "䶊", "Pinyin_Xie": "nǜ", "Âm Hán Việt_Xie": "nục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ việc chảy máu mũi hoặc thất bại trong chiến đấu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('銎', '{"9000": "5764.0", "Chữ Trung Quốc": "銎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 銎 | khung | tượng hình | lỗ tra cán rìu/búa | 銎 có bộ 金 (kim, kim loại) ẩn trong cấu trúc nhưng Wiktionary không phân tích thêm. Từ hình thức, có thể hội ý giữa 金 (kim loại) và phần còn lại, nhưng nguồn học thuật không xác nhận. Coi như chữ không rõ cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khung\" (銎): bộ 金 (kim, kim loại) — 銎 là lỗ \"khung\" rỗng trên lưỡi rìu kim loại, nơi tra cán gỗ vào — không có lỗ này thì không dùng được búa. | Gương Hán-Việt | 銎 — ít xuất hiện trong từ Hán-Việt thông dụng; chủ yếu trong từ điển chuyên ngành và văn bản cổ | Mở khoá kiến thức | Biết 銎 giúp đọc các mô tả vũ khí và dụng cụ cổ đại trong văn bản lịch sử Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Chữ 銎 chỉ lỗ hổng ở phần lưỡi rìu/búa dùng để tra cán vào. Wiktionary chỉ ghi {{Han etym}} mà không có phân tích cấu trúc. Có bộ 金 (kim loại) gợi vật liệu làm bằng kim khí. Dạng tiểu triện còn lưu lại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cán rìu, cán búa", "Hạng Tần Suất (Jun Da)": "5764.0", "Tần Suất % (Jun Da)": "99.9731922879", "GavinGrover_Once (Chiết tự trực tiếp)": "巩 + 金", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱巩金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "銎", "Unihan_Traditional (Chữ Phồn thể)": "銎", "Pinyin_Xie": "qióng", "Âm Hán Việt_Xie": "khung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ phần lỗ trên đầu rìu búa dùng để tra cán vào. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泫', '{"9000": "5765.0", "Chữ Trung Quốc": "泫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 泫 | huyễn | tượng hình | nước nhỏ giọt, lệ chảy, long lanh | 泫 có bộ 氵(thủy, nước) nhưng anchor không có glyphOrigin. Từ cấu trúc bộ 氵+ 玄 (huyền, tối/sâu), có thể là hình thanh với 玄 biểu âm, nhưng nguồn học thuật không xác nhận. Coi như chữ không rõ cấu trúc theo nguồn hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyễn\" (泫): bộ 氵 (thủy, nước) + 玄 (huyền, sâu thẳm) — giọt nước 泫 lấp lánh huyễn hoặc như giọt lệ chảy dài trong bóng tối. | Gương Hán-Việt | 泫然 (huyễn nhiên) — rơi lệ, lệ chảy dài | Mở khoá kiến thức | Biết 泫 giúp đọc thơ văn cổ tả cảnh khóc hoặc sương móc long lanh như 泫然泪下 (huyễn nhiên lệ hạ).", "Tự nguyên_Xie": "Tiểu triện | Chữ 泫 chỉ nước nhỏ giọt, ánh nước long lanh, hoặc nước mắt chảy. Anchor không cung cấp glyphOrigin. Từ hình thức có bộ 氵 (nước) + 玄 (huyền), có thể là hình thanh nhưng chưa được xác nhận học thuật. Dạng tiểu triện còn lưu lại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước mênh mông", "Hạng Tần Suất (Jun Da)": "5765.0", "Tần Suất % (Jun Da)": "99.9732310468", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 玄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵玄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "玄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泫", "Unihan_Traditional (Chữ Phồn thể)": "泫", "Pinyin_Xie": "xuàn", "Âm Hán Việt_Xie": "huyễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ nước mắt rơi hoặc tính từ mô tả sương đọng long lanh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('玢', '{"9000": "5766.0", "Chữ Trung Quốc": "玢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 8 | nét | 玢 | phân | tượng hình | một loại ngọc; đá porphyrite | 玢 có bộ 玉 (ngọc) nhưng Wiktionary không phân tích cấu trúc chi tiết. Từ hình thức có thể là hình thanh với 分 (phân) biểu âm, nhưng nguồn học thuật không xác nhận. Coi như chữ không rõ cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phân\" (玢): bộ 玉 (ngọc, đá quý) — 玢 là loại ngọc \"phân\" — mịn và bóng như bề mặt đá porphyrite đánh bóng. | Gương Hán-Việt | 玢 — ít dùng trong từ Hán-Việt thông dụng; chủ yếu trong địa chất học và văn bản cổ | Mở khoá kiến thức | Biết 玢 giúp đọc thuật ngữ địa chất 玢岩 (phân nham — đá porphyrite) trong tài liệu khoa học.", "Tự nguyên_Xie": "Chữ 玢 chỉ một loại ngọc quý và cũng dùng trong tên đá porphyrite (玢岩). Wiktionary ghi hai cách đọc: fēn và bīn, dùng trong hai nghĩa khác nhau. Không có phân tích cấu trúc chi tiết. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc Phân; Ghi chú: 另见fēn", "Hạng Tần Suất (Jun Da)": "5766.0", "Tần Suất % (Jun Da)": "99.9732698057", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 分", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王分", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "玢", "Unihan_Traditional (Chữ Phồn thể)": "玢", "Pinyin_Xie": "bīn", "Âm Hán Việt_Xie": "tân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong tên gọi các loại đá hoặc ngọc có vân. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辊', '{"9000": "5767.0", "Chữ Trung Quốc": "辊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 12 | nét | 辊 | cổn | tượng hình | trục lăn, con lăn quay | 辊 (phồn thể 輥) có bộ 車 (xa, xe/bánh xe) nhưng Wiktionary không phân tích cấu trúc chi tiết. Từ cấu trúc có thể là hình thanh với 昆 (côn) biểu âm, nhưng nguồn học thuật không xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cổn\" (辊): bộ 車 (xa, bánh xe) — 辊 là trục lăn \"cổn\" quay tròn trong máy móc, như bánh xe không có vành. | Gương Hán-Việt | 辊 — ít dùng trong từ Hán-Việt; chủ yếu trong thuật ngữ công nghiệp | Mở khoá kiến thức | Biết 辊 giúp đọc thuật ngữ cơ khí 辊子 (cổn tử — con lăn) và 轧辊 (áp cổn — trục cán) trong tài liệu kỹ thuật.", "Tự nguyên_Xie": "Tiểu triện | Chữ 辊 (phồn thể 輥) chỉ trục lăn hoặc con lăn, dùng trong công nghiệp như máy cán thép. Wiktionary không có phân tích cấu trúc chi tiết. Bộ 車 (xe) gợi cơ chế quay. Dạng tiểu triện còn lưu lại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trục quay", "Hạng Tần Suất (Jun Da)": "5767.0", "Tần Suất % (Jun Da)": "99.9733085646", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 昆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车昆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "辊", "Unihan_Traditional (Chữ Phồn thể)": "輥", "Pinyin_Xie": "gǔn", "Âm Hán Việt_Xie": "cổn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các loại trục lăn hoặc con lăn trong máy móc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞋', '{"9000": "5768.0", "Chữ Trung Quốc": "瞋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 15 | nét | 瞋 | trân | tượng hình | trừng mắt giận dữ | 瞋 có bộ 目 (mục, mắt) nhưng anchor không có glyphOrigin. Từ cấu trúc bộ 目 + 真 (chân), có thể là hình thanh với 真 biểu âm, nhưng nguồn học thuật không xác nhận. Coi như chữ không rõ cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trân\" (瞋): bộ 目 (mục, mắt) — đôi mắt 目 trừng \"trân trân\" trong cơn giận — 瞋 là ánh mắt giận dữ không che giấu được. | Gương Hán-Việt | 瞋目 (trân mục) — trừng mắt; 瞋恚 (trân khuể) — tức giận (Phật giáo) | Mở khoá kiến thức | Biết 瞋 giúp đọc thuật ngữ Phật giáo 瞋恚 (trân khuể — sân hận), một trong ba độc (tham sân si).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 瞋 chỉ trừng mắt nhìn trong cơn tức giận. Anchor không cung cấp glyphOrigin. Từ hình thức có bộ 目 (mắt) + 真 (chân), có thể hình thanh nhưng chưa xác nhận. Dạng tiểu triện và lục thư thông còn lưu lại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trừng mắt nhìn, lườm", "Hạng Tần Suất (Jun Da)": "5768.0", "Tần Suất % (Jun Da)": "99.9733473235", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 真", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目真", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "真", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞋", "Unihan_Traditional (Chữ Phồn thể)": "瞋", "Pinyin_Xie": "chēn", "Âm Hán Việt_Xie": "sân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ bộ phận cơ thể hoặc đối tượng bị lườm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('墀', '{"9000": "5769.0", "Chữ Trung Quốc": "墀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 15 | nét | 墀 | trì | tượng hình | sân trong, thềm bậc | 墀 có bộ 土 (thổ, đất) nhưng Wiktionary không phân tích cấu trúc chi tiết (chỉ ghi rfdef). Từ hình thức có thể là hình thanh với phần còn lại biểu âm, nhưng nguồn học thuật không xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trì\" (墀): bộ 土 (thổ, đất) — sân 墀 là khoảng đất \"trì\" trước cung điện, nơi quan lại quỳ chờ — không gian uy nghi và im lặng. | Gương Hán-Việt | 丹墀 (đan trì) — thềm son đỏ của cung điện; 墀头 (trì đầu) — đầu tường trang trí | Mở khoá kiến thức | Biết 墀 giúp đọc từ 丹墀 (đan trì — thềm son đỏ cung điện) trong thơ văn cung đình và kiến trúc cổ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 墀 chỉ sân trong hoặc bậc thềm của cung điện/nhà quan lại. Wiktionary chỉ ghi {{Han etym}} và rfdef (thiếu định nghĩa). Bộ 土 (đất) gợi mặt sân lát đất. Dạng tiểu triện và lục thư thông còn lưu lại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sân nhỏ, sân trong", "Hạng Tần Suất (Jun Da)": "5769.0", "Tần Suất % (Jun Da)": "99.9733860823", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 犀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土犀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "墀", "Unihan_Traditional (Chữ Phồn thể)": "墀", "Pinyin_Xie": "chí", "Âm Hán Việt_Xie": "trì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn cổ để chỉ phần thềm hoặc sân nhỏ trước cung điện. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酐', '{"9000": "5770.0", "Chữ Trung Quốc": "酐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 10 | nét | 酐 | can | tượng hình | anhydride (hợp chất hóa học) | 酐 có bộ 酉 (dậu, rượu/dịch) nhưng Wiktionary chỉ ghi {{Han etym}} mà không phân tích cấu trúc. Từ hình thức có thể là hình thanh với 干 (can) biểu âm, nhưng nguồn học thuật không xác nhận. Đây là chữ tạo muộn cho thuật ngữ hóa học.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"can\" (酐): bộ 酉 (dậu, dung dịch) + 干 (can, khô) — anhydride là hợp chất \"khô\" 干, tạo ra khi rút nước khỏi acid như rượu 酉 cô đặc lại. | Gương Hán-Việt | 酐 — ít dùng trong từ Hán-Việt thông dụng; chủ yếu trong thuật ngữ hóa học | Mở khoá kiến thức | Biết 酐 giúp đọc tên hóa chất như 乙酸酐 (axetic anhydride) và 顺丁烯二酸酐 (maleic anhydride) trong tài liệu hóa học.", "Tự nguyên_Xie": "Chữ 酐 là chữ tạo muộn dùng để dịch thuật ngữ hóa học \"anhydride\" (hợp chất tạo ra khi loại nước từ acid). Wiktionary chỉ ghi {{Han etym}}. Bộ 酉 (dậu) gợi liên quan đến dung dịch hóa học. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chất anhydride (hoá học)", "Hạng Tần Suất (Jun Da)": "5770.0", "Tần Suất % (Jun Da)": "99.9734248412", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 干", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉干", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "干", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酐", "Unihan_Traditional (Chữ Phồn thể)": "酐", "Pinyin_Xie": "gān", "Âm Hán Việt_Xie": "can", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong thuật ngữ hóa học để chỉ hợp chất tách nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('堞', '{"9000": "5771.0", "Chữ Trung Quốc": "堞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 12 | nét | 堞 | điệp | tượng hình | tường nhô trên đỉnh thành (bắn lỗ châu mai) | 堞 có bộ 土 (thổ, đất/tường) nhưng Wiktionary không phân tích cấu trúc chi tiết. Từ hình thức có thể là hình thanh với 枼 (điệp) biểu âm, nhưng nguồn học thuật không xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệp\" (堞): bộ 土 (thổ, tường đất) — tường thành \"điệp\" từng lớp nhô lên như răng cưa, che chắn cho lính bên trong. | Gương Hán-Việt | 城堞 (thành điệp) — lỗ châu mai trên tường thành; 雉堞 (trĩ điệp) — tường thành có lỗ châu mai | Mở khoá kiến thức | Biết 堞 giúp đọc thuật ngữ kiến trúc quân sự cổ 雉堞 và 城堞 trong văn bản lịch sử.", "Tự nguyên_Xie": "Tiểu triện | Chữ 堞 chỉ phần tường nhỏ nhô lên trên đỉnh thành lũy, có lỗ châu mai để bắn. Wiktionary cho nghĩa \"plate\" nhưng nghĩa chính là tường thành có lỗ châu mai (雉堞). Bộ 土 (đất/tường) biểu nghĩa. Dạng tiểu triện còn lưu lại. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tường ngắn trên mặt thành", "Hạng Tần Suất (Jun Da)": "5771.0", "Tần Suất % (Jun Da)": "99.9735018422", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 枼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土枼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "枼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "堞", "Unihan_Traditional (Chữ Phồn thể)": "堞", "Pinyin_Xie": "dié", "Âm Hán Việt_Xie": "điệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn cổ để chỉ các công sự phòng thủ trên thành lũy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('尥', '{"9000": "5772.0", "Chữ Trung Quốc": "尥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 尢 | Số nét | 6 | nét | 尥 | liệu | tượng hình | đá hậu (động tác đá chân sau của ngựa) | 尥 có bộ 尢 (vương, chân tật) nhưng Wiktionary chỉ ghi rfdef (thiếu định nghĩa chi tiết). Từ hình thức, bộ 尢 gợi chân/bước đi bất thường. Nguồn học thuật không xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liệu\" (尥): bộ 尢 (vương, chân cong) — 尥蹶子 là cú đá hậu của ngựa \"liệu\" mạnh bất ngờ — không cẩn thận là ăn đòn. | Gương Hán-Việt | 尥蹶子 (liệu quyết tử) — đá hậu (ngựa đá sau lưng) | Mở khoá kiến thức | Biết 尥 giúp đọc từ 尥蹶子 trong văn học thông tục và thành ngữ chỉ hành động đột ngột phản kháng.", "Tự nguyên_Xie": "Tiểu triện | Chữ 尥 chỉ động tác ngựa đá chân sau, hay chân bước vướng víu. Dùng chủ yếu trong từ 尥蹶子 (liệu quyết tử — đá hậu). Wiktionary chỉ ghi rfdef. Bộ 尢 gợi chân tật/chân yếu. Dạng tiểu triện còn lưu lại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: liệu quệ tử 尥蹶子)", "Hạng Tần Suất (Jun Da)": "5772.0", "Tần Suất % (Jun Da)": "99.9735400843", "GavinGrover_Once (Chiết tự trực tiếp)": "尢 + 勺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴尢勺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "尢", "Unihan_Simplified (Chữ Giản thể)": "尥", "Unihan_Traditional (Chữ Phồn thể)": "尥", "Pinyin_Xie": "liào", "Âm Hán Việt_Xie": "liệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ kết hợp trong cụm từ để chỉ hành động đá chân sau của lừa, ngựa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嚯', '{"9000": "5773.0", "Chữ Trung Quốc": "嚯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 19 | nét | 嚯 | oác | tượng hình | thán từ ngạc nhiên/khen ngợi; tiếng cười ha hả | 嚯 có bộ 口 (khẩu, miệng) nhưng anchor không có glyphOrigin. Đây là chữ tượng thanh dùng miệng phát ra âm thanh; không phân tích hình thanh/hội ý theo nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oác\" (嚯): bộ 口 (khẩu, miệng) — tiếng \"oác oác\" bật ra từ miệng khi bất ngờ thấy điều kỳ lạ — thán từ của ngạc nhiên. | Gương Hán-Việt | 嚯 — ít xuất hiện trong từ Hán-Việt; chủ yếu trong văn nói và truyện tranh hiện đại | Mở khoá kiến thức | Biết 嚯 giúp đọc văn nói thông tục và lời thoại truyện tranh Trung Quốc hiện đại.", "Tự nguyên_Xie": "Chữ 嚯 là thán từ hoặc từ tượng thanh: thể hiện ngạc nhiên, khen ngợi, hoặc tiếng cười ha hả. Anchor không có glyphOrigin. Bộ 口 (miệng) xác nhận đây là âm thanh phát ra. Chưa có nguồn học thuật. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ồ (tỏ ý kinh ngạc hoặc khen ngợi); ha hả; hô hố (từ tượng thanh, tiếng cười)", "Hạng Tần Suất (Jun Da)": "5773.0", "Tần Suất % (Jun Da)": "99.9735783264", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 霍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口霍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "霍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嚯", "Unihan_Traditional (Chữ Phồn thể)": "嚯", "Pinyin_Xie": "huò", "Âm Hán Việt_Xie": "hước", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Thán từ | 叹词 | Từ tượng thanh | 象声词 | Thường đứng đầu câu làm thán từ biểu thị sự ngạc nhiên hoặc làm từ mô phỏng tiếng cười lớn. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('猗', '{"9000": "5774.0", "Chữ Trung Quốc": "猗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 11 | nét | 猗 | y | tượng hình | thán từ khen ngợi; xanh tốt; dài | 猗 có bộ 犭(khuyển, thú) nhưng Wiktionary chỉ ghi {{Han etym}} mà không phân tích cấu trúc. Từ hình thức có thể là hình thanh với 奇 (kỳ) biểu âm, nhưng nguồn học thuật không xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"y\" (猗): bộ 犭 (thú) + âm y/yī gợi thán từ — như tiếng \"ý\" bật ra khi nhìn thấy cảnh đẹp rực rỡ trong vườn Kinh Thi. | Gương Hán-Việt | 猗那 (y na) — vẻ uyển chuyển, mềm mại; 猗猗 (y y) — tươi tốt rậm rạp | Mở khoá kiến thức | Biết 猗 giúp đọc thơ Kinh Thi như \"猗与那与\" (y dư na dư — ôi thật uyển chuyển thay).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 猗 có nhiều nghĩa: thán từ khen ngợi, tính từ chỉ vật xanh tươi dài tốt, hoặc động từ nương dựa vào. Wiktionary chỉ ghi {{Han etym}}. Bộ 犭 (thú) bất thường với nghĩa thán từ — có thể là dấu hiệu chữ tạo muộn. Dạng tiểu triện và lục thư thông còn lưu lại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khen ngợi, ca ngợi; xanh tốt; dài; vậy, thế; nương, dựa vào", "Hạng Tần Suất (Jun Da)": "5774.0", "Tần Suất % (Jun Da)": "99.9736165685", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 奇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭奇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "猗", "Unihan_Traditional (Chữ Phồn thể)": "猗", "Pinyin_Xie": "yī", "Âm Hán Việt_Xie": "y", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Trợ từ | 助词 | Thán từ | 叹词 | Thường dùng trong cổ văn làm tính từ miêu tả cây cối hoặc trợ từ, thán từ ở cuối hoặc đầu câu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí). | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逑', '{"9000": "5775.0", "Chữ Trung Quốc": "逑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 10 | nét | 辵 | sước | biểu nghĩa | bước đi, di chuyển | 求 | cầu | biểu âm | biểu âm | 逑 = 辵 (Sước, biểu nghĩa: bước đi) + 求 (Cầu, biểu âm); chữ hình thanh. Bộ 辵 xác định nghĩa liên quan đến di chuyển/tìm kiếm; phần 求 cung cấp âm đọc và gợi ý nghĩa tìm đôi lứa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cầu\" (逑): 辵 (sước, bước đi) + 求 (cầu, tìm kiếm) — đi tìm kiếm 求 người bạn đời — đó là 逑, người lứa đôi xứng đôi vừa lứa. | Gương Hán-Việt | 好逑 (hảo cầu) — người bạn đời tốt đẹp; \"窈窕淑女，君子好逑\" (thành ngữ từ Kinh Thi) | Mở khoá kiến thức | Biết 逑 giúp đọc câu Kinh Thi nổi tiếng \"窈窕淑女，君子好逑\" (người thục nữ yểu điệu, là người bạn đời tốt của quân tử).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 逑 là chữ hình thanh: 辵 (bước đi) là phần biểu nghĩa, 求 là phần biểu âm. Nghĩa gốc là người bạn đời, đôi lứa; mở rộng sang thu thập, gom góp. Dạng tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lứa đôi; tích góp, vơ vét", "Hạng Tần Suất (Jun Da)": "5775.0", "Tần Suất % (Jun Da)": "99.9736548106", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 求", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶求", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "求", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逑", "Unihan_Traditional (Chữ Phồn thể)": "逑", "Pinyin_Xie": "qiú", "Âm Hán Việt_Xie": "cầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ bạn đời hoặc động từ chỉ sự kết hợp, tìm kiếm trong văn thơ cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逯', '{"9000": "5776.0", "Chữ Trung Quốc": "逯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 11 | nét | 逯 | lộc | tượng hình | bước đi cẩn thận; họ người | 逯 có bộ 辵 (sước, bước đi) nhưng Wiktionary không phân tích cấu trúc chi tiết. Từ hình thức có thể là hình thanh với 录 (lục) biểu âm, nhưng nguồn học thuật không xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lộc\" (逯): bộ 辵 (sước, bước đi) — bước đi \"lộc cộc\" cẩn thận từng bước, không vội vàng — đó là 逯, họ người ít gặp. | Gương Hán-Việt | 逯 — chủ yếu dùng làm họ người; ít từ ghép thông dụng | Mở khoá kiến thức | Biết 逯 giúp nhận ra họ 逯 (Lộc) trong danh sách họ người hiếm ở Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 逯 có nghĩa bước đi cẩn thận và là họ người. Wiktionary không có phân tích cấu trúc chi tiết. Bộ 辵 (bước đi) biểu nghĩa. Dạng tiểu triện và lục thư thông còn lưu lại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Lộc", "Hạng Tần Suất (Jun Da)": "5776.0", "Tần Suất % (Jun Da)": "99.9736930527", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 录", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶录", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "录", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逯", "Unihan_Traditional (Chữ Phồn thể)": "逯", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chủ yếu dùng làm danh từ riêng chỉ họ người hoặc làm động từ cổ chỉ việc đi lại không có định hướng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硖', '{"9000": "5777.0", "Chữ Trung Quốc": "硖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 11 | nét | 硖 | giáp | tượng hình | địa danh ở Hà Bắc; mõm núi nhô ra | 硖 (phồn thể 硤) có bộ 石 (thạch, đá) nhưng Wiktionary chỉ ghi rfdef. Từ hình thức có thể là hình thanh với 夹 (giáp) biểu âm, nhưng nguồn học thuật không xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giáp\" (硖): bộ 石 (thạch, đá núi) — núi đá \"giáp\" nhô ra mặt nước như hai cánh kẹp lại — địa hình hiểm trở. | Gương Hán-Việt | 硖石镇 (Giáp Thạch trấn) — địa danh ở Chiết Giang; 石硤尾 (Thạch Giáp Vĩ) — địa danh ở Hồng Kông | Mở khoá kiến thức | Biết 硖 giúp nhận ra địa danh 硖石 (Giáp Thạch) trong địa lý Trung Quốc.", "Tự nguyên_Xie": "Chữ 硖 (phồn thể 硤) là tên địa danh ở Hà Bắc và chỉ mõm núi nhô ra mặt nước. Wiktionary chỉ ghi rfdef. Bộ 石 (đá) biểu nghĩa gợi địa hình đá núi. Nguồn học thuật không phân tích chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mõm núi (gie ra trong nước)", "Hạng Tần Suất (Jun Da)": "5777.0", "Tần Suất % (Jun Da)": "99.9737312948", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 夹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石夹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硖", "Unihan_Traditional (Chữ Phồn thể)": "硤", "Pinyin_Xie": "xiá", "Âm Hán Việt_Xie": "giáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong địa danh để chỉ địa hình hẻm núi hoặc vách đá ven sông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('噻', '{"9000": "5778.0", "Chữ Trung Quốc": "噻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 16 | nét | 噻 | tắc | tượng hình | thiophene (hợp chất hữu cơ) | 噻 có bộ 口 (khẩu, miệng) nhưng anchor không có glyphOrigin. Đây là chữ tạo muộn dùng để phiên âm thuật ngữ hóa học \"thiophene\". Không phân tích hình thanh/hội ý theo nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tắc\" (噻): bộ 口 (khẩu) — 噻吩 là thiophene, hợp chất vòng lưu huỳnh — âm \"tắc\" như tiếng \"tắc\" nghẹt khi gặp mùi lưu huỳnh. | Gương Hán-Việt | 噻 — ít dùng trong từ Hán-Việt thông dụng; chủ yếu trong hóa học hữu cơ | Mở khoá kiến thức | Biết 噻 giúp đọc tên hóa chất như 噻吩 (thiophene) và 噻唑 (thiazole) trong tài liệu hóa học.", "Tự nguyên_Xie": "Chữ 噻 là chữ tạo muộn dùng để phiên âm thuật ngữ hóa học \"thiophene\" (噻吩, C₄H₄S — vòng thơm chứa lưu huỳnh). Anchor không có glyphOrigin. Bộ 口 (miệng) thường gặp trong các chữ phiên âm. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thi- ô-phen (hợp chất hữu cơ)", "Hạng Tần Suất (Jun Da)": "5778.0", "Tần Suất % (Jun Da)": "99.9737695369", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 塞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口塞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "塞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "噻", "Unihan_Traditional (Chữ Phồn thể)": "噻", "Pinyin_Xie": "sāi", "Âm Hán Việt_Xie": "tắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Trong tiếng Trung hiện đại chữ này chủ yếu dùng để phiên âm các hợp chất hóa học chứa lưu huỳnh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嵛', '{"9000": "5779.0", "Chữ Trung Quốc": "嵛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 12 | nét | 嵛 | du | tượng hình | tên núi ở Sơn Đông (Côn Du sơn) | 嵛 có bộ 山 (sơn, núi) nhưng anchor không có glyphOrigin. Đây là địa danh chỉ núi Côn Du ở Sơn Đông. Không phân tích hình thanh/hội ý theo nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\" (嵛): bộ 山 (sơn, núi) — núi Du (昆嵛) là ngọn núi nổi tiếng ở Sơn Đông, nơi đạo Toàn Chân khai tổ. | Gương Hán-Việt | 昆嵛山 (Côn Du sơn) — tên núi thiêng ở Sơn Đông | Mở khoá kiến thức | Biết 嵛 giúp nhận ra địa danh 昆嵛山 (Côn Du sơn) — núi thiêng liên quan đến đạo giáo Toàn Chân trong lịch sử Trung Hoa.", "Tự nguyên_Xie": "Chữ 嵛 là tên riêng chỉ núi Côn Du (昆嵛山) ở tỉnh Sơn Đông, Trung Quốc. Anchor không có glyphOrigin. Bộ 山 (núi) biểu nghĩa xác nhận đây là địa danh núi. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Côn Du (tên núi ở tỉnh Sơn Đông, Trung Quốc.)", "Hạng Tần Suất (Jun Da)": "5779.0", "Tần Suất % (Jun Da)": "99.973807779", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 俞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山俞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "俞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "嵛", "Unihan_Traditional (Chữ Phồn thể)": "嵛", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ địa danh núi Côn Du. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畀', '{"9000": "5780.0", "Chữ Trung Quốc": "畀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 田 | Số nét | 8 | nét | 甶 | biểu âm | biểu âm (dạng cổ) | 丌 | cơ | biểu nghĩa | bệ, đế — gợi ý nghĩa dâng/đưa | 畀 trong dạng cổ là chữ tượng hình vẽ mũi tên đầu bằng. Sau này dạng chữ biến đổi thành 甶+丌, và Thuyết Văn hiểu nhầm là hình thanh với 甶 biểu âm, 丌 (bệ đỡ) biểu nghĩa. Thực chất nguồn gốc là tượng hình, không phải hình thanh theo Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỵ\" (畀): chữ gốc là mũi tên đầu bằng — trao tặng mũi tên 畀 cho người khác là hành động dâng cho, cho đi, đó là nghĩa của 畀. | Gương Hán-Việt | 畀 — ít dùng trong từ Hán-Việt thông dụng; chủ yếu trong văn bản Kinh Thi và cổ văn | Mở khoá kiến thức | Biết 畀 giúp đọc cổ văn và Kinh Thi nơi 畀 mang nghĩa \"cho/trao\" trang trọng.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Theo Wiktionary, trong giáp cốt văn 畀 là chữ tượng hình vẽ mũi tên có đầu bằng (cf. 矢 — mũi tên nhọn) — đây là dạng gốc của 錍 (mũi tên đầu bằng). Trong kim văn thêm một chấm, dần biến thành nét ngắn; phần dưới biến đổi thành 廾 hoặc 丌. Thuyết Văn Giải Tự hiểu nhầm là hình thanh 甶(biểu âm)+丌(bệ đỡ). Ảnh giáp cốt, kim văn và đại triện còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cho", "Hạng Tần Suất (Jun Da)": "5780.0", "Tần Suất % (Jun Da)": "99.9738460211", "GavinGrover_Once (Chiết tự trực tiếp)": "田 + 丌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱田丌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "田", "Unihan_Simplified (Chữ Giản thể)": "畀", "Unihan_Traditional (Chữ Phồn thể)": "畀", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ hành động ban cho hoặc trao cho ai đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲃', '{"9000": "5781.0", "Chữ Trung Quốc": "鲃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 12 | nét | 鲃 | bát | tượng hình | loài cá nước ngọt (barb/bonito) | 鲃 là giản thể của 䰾, rút gọn 魚 thành 鱼. Bộ 鱼 (ngư, cá) xác định đây là loài cá; phần còn lại có thể biểu âm. Đây là chữ giản hóa hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bát\" (鲃): bộ 鱼 (ngư, cá) — cá 鲃 là loài cá \"bát\" ngát dưới nước, cùng họ cá chép, bơi thành đàn đông đúc. | Gương Hán-Việt | 鲃 — ít dùng trong từ Hán-Việt thông dụng; chủ yếu trong thuật ngữ sinh học cá | Mở khoá kiến thức | Biết 鲃 giúp đọc tên loài cá trong tài liệu sinh học và thủy sản như 鲃鱼 (cá barb).", "Tự nguyên_Xie": "鲃 là dạng giản thể của 䰾, rút gọn bộ 魚 thành 鱼. Chỉ một loài cá nước ngọt thuộc họ cá chép (barb), phổ biến ở châu Âu, châu Phi và châu Á. Không có phân tích cấu trúc chi tiết từ nguồn học thuật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại cá nước ngọt, sống chủ yếu ở Châu Âu, Châu Phi và Châu Á)", "Hạng Tần Suất (Jun Da)": "5781.0", "Tần Suất % (Jun Da)": "99.9739225053", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 巴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼巴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲃", "Unihan_Traditional (Chữ Phồn thể)": "䰾", "Pinyin_Xie": "bā", "Âm Hán Việt_Xie": "bát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò là danh từ chỉ tên một loài cá trong ngành động vật học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('偬', '{"9000": "5782.0", "Chữ Trung Quốc": "偬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 11 | nét | 偬 | tổng | tượng hình | khẩn cấp, bận rộn (dùng trong 倥偬) | 偬 có bộ 人/亻(nhân, người) nhưng Wiktionary chỉ ghi 偬 là dị thể của 傯. Từ hình thức có thể là hình thanh với 总 (tổng) biểu âm, nhưng nguồn học thuật không xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tổng\" (偬): bộ 亻(nhân, người) — người 亻bận 偬 tổng tổng, bận rộn tất tả như không có lúc dừng — đó là 倥偬. | Gương Hán-Việt | 倥偬 (không tổng) — bận rộn tất tả, không có thời gian | Mở khoá kiến thức | Biết 偬 giúp đọc thành ngữ 倥偬岁月 (những năm tháng bận rộn) trong thơ văn cổ.", "Tự nguyên_Xie": "Chữ 偬 là dị thể của 傯, chỉ tình trạng khẩn cấp, bận rộn; dùng chủ yếu trong từ 倥偬 (không tổng — bận rộn tất tả). Wiktionary chỉ ghi {{Han etym}} và zh-see 傯. Không có ảnh glyph cổ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: không tổng 倥傯,倥偬)", "Hạng Tần Suất (Jun Da)": "5782.0", "Tần Suất % (Jun Da)": "99.9739602306", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 怱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻怱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "怱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "偬", "Unihan_Traditional (Chữ Phồn thể)": "傯", "Pinyin_Xie": "zǒng", "Âm Hán Việt_Xie": "tổng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này hầu như chỉ xuất hiện trong từ ghép khống tổng để miêu tả sự bận rộn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄞', '{"9000": "5783.0", "Chữ Trung Quốc": "鄞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 13 | nét | 鄞 | ngân | tượng hình | địa danh, tên huyện cổ ở Ninh Ba, Chiết Giang | 鄞 là chữ địa danh chuyên dùng, gốc bộ 邑 (ấp, chỉ nơi chốn/làng ấp). Nguồn gốc cấu tạo nội bộ chưa được Wiktionary phân giải cụ thể; chưa có nguồn học thuật xác định rõ ls.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngân\": bộ 邑 (làng ấp) ghép với phần âm — giúp nhớ đây là tên vùng đất cổ Ninh Ba, nơi con sông bạc (ngân) chảy qua. | Gương Hán-Việt | Chữ 鄞 chủ yếu dùng trong địa danh cổ (huyện Ngân, Ninh Ba); ít xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 鄞 giúp nhận ra các địa danh lịch sử Trung Hoa liên quan đến vùng Chiết Giang.", "Tự nguyên_Xie": "Tiểu triện | Chữ 鄞 xuất hiện trong thư tịch cổ như một địa danh: chỉ huyện Ân (Yin) thuộc Ninh Ba, Chiết Giang. Bộ 邑 (ấp) ở vị trí biểu nghĩa chỉ đây là tên đất. Phần còn lại mang âm. Chưa có nguồn học thuật xác minh cấu trúc nội bộ; tiểu triện đã tồn tại dạng chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "5783.0", "Tần Suất % (Jun Da)": "99.9739979559", "GavinGrover_Once (Chiết tự trực tiếp)": "堇 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰堇阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "堇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄞", "Unihan_Traditional (Chữ Phồn thể)": "鄞", "Pinyin_Xie": "yín", "Âm Hán Việt_Xie": "ngân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò danh từ riêng dùng trong địa danh học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('呖', '{"9000": "5784.0", "Chữ Trung Quốc": "呖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 呖 | lịch | tượng hình | âm thanh vỡ, tiếng gãy; bộ khẩu 口 gợi liên quan đến miệng/âm | 呖 là chữ dùng trong từ tượng thanh (onomatopoeia). Wiktionary không có mục riêng; cấu trúc nội bộ chưa được phân tích học thuật. Bộ 口 gợi âm thanh. Chưa có nguồn học thuật xác định rõ ls.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lịch\": bộ 口 (miệng) gợi âm thanh — 呖呖 là tiếng chim hoặc âm vỡ giòn tan, như tiếng \"lịch cắc\" kêu lên. | Gương Hán-Việt | 呖 ít xuất hiện trong từ Hán-Việt thông dụng; dùng chủ yếu trong từ tượng thanh như 呖呖. | Mở khoá kiến thức | Biết 呖 giúp đọc các từ tượng thanh mô tả âm thanh giòn, vỡ trong văn học cổ.", "Tự nguyên_Xie": "呖 (lì) là chữ tượng thanh chỉ âm thanh vỡ, gãy hay tiếng chim kêu. Không có mục Wiktionary; cấu trúc không rõ ràng. Chưa có nguồn học thuật xác minh. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng gãy, tiếng vỡ", "Hạng Tần Suất (Jun Da)": "5784.0", "Tần Suất % (Jun Da)": "99.9740356813", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 历", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口历", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "历", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呖", "Unihan_Traditional (Chữ Phồn thể)": "嚦", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Tính từ | 形容词 | Thường đi kèm lặp lại hoặc kết hợp với các từ chỉ âm thanh để mô tả tiếng chim hót. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('溧', '{"9000": "5785.0", "Chữ Trung Quốc": "溧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 溧 | rớt | tượng hình | tên sông ở An Huy và Giang Tô; bộ 水 gợi liên quan đến nước | 溧 là địa danh chỉ sông Lật (tên sông ở An Huy, Giang Tô). Wiktionary không có mục phân tích cấu trúc; bộ 水 (thủy) cho thấy liên quan đến sông nước. Chưa có nguồn học thuật xác định ls cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"rớt\": bộ 水 (nước) chảy xuống — dòng sông Lật \"rớt\" qua vùng đất An Huy, Giang Tô. | Gương Hán-Việt | 溧 chủ yếu dùng trong địa danh (sông Lật, Lật Dương); ít xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 溧 giúp nhận diện địa danh vùng Giang Nam liên quan đến sông nước.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 溧 dùng làm tên địa lý, chỉ dòng sông ở vùng An Huy và Giang Tô. Hình ảnh tiểu triện và lục thư thông còn lưu lại. Bộ 水 biểu nghĩa chỉ nước/sông; phần còn lại biểu âm. Chưa có phân tích Wiktionary cụ thể. Chưa có nguồn học thuật xác minh cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Lật", "Hạng Tần Suất (Jun Da)": "5785.0", "Tần Suất % (Jun Da)": "99.9740734066", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "溧", "Unihan_Traditional (Chữ Phồn thể)": "溧", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng trong các địa danh như Lật Dương, Lật Thủy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嬲', '{"9000": "5786.0", "Chữ Trung Quốc": "嬲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 17 | nét | 男 | nam | biểu nghĩa | đàn ông | 女 | nữ | biểu nghĩa | đàn bà | 男 | nam | biểu nghĩa | đàn ông | 嬲 là chữ hội ý: hai chữ 男 (nam, đàn ông) kẹp một chữ 女 (nữ, đàn bà) ở giữa. Hình ảnh hai người đàn ông vây quanh một người đàn bà gợi nghĩa quấy rối, trêu ghẹo, đeo bám. So sánh 嫐 (女 kẹp giữa hai 男 theo bố cục khác).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"náo\": 男女男 — hai người đàn ông (男) kẹp một người đàn bà (女) ở giữa, tạo cảnh náo loạn, quấy rối không thôi. | Gương Hán-Việt | 嬲 ít dùng trong từ Hán-Việt; xuất hiện trong văn ngữ cổ với nghĩa trêu ghẹo, đeo bám. | Mở khoá kiến thức | Biết 嬲 giúp đọc các văn bản cổ tả cảnh trêu ghẹo, quấy nhiễu; cũng xuất hiện trong tiếng Quảng Đông hiện đại.", "Tự nguyên_Xie": "Wiktionary ghi: 嬲 = 男 + 女 + 男, hai chữ 男 (người đàn ông) kẹp chữ 女 (người đàn bà) ở giữa. Cấu trúc hội ý mô tả cảnh hai đàn ông vây quanh một đàn bà — biểu thị nghĩa trêu ghẹo, đeo bám, quấy rầy. Tiếng Quảng Đông còn dùng với nghĩa tức giận. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ghẹo; trêu ghẹo; đeo bám; bám theo; lằng nhằng", "Hạng Tần Suất (Jun Da)": "5786.0", "Tần Suất % (Jun Da)": "99.9741111319", "GavinGrover_Once (Chiết tự trực tiếp)": "𤲶 + 女", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𤲶女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𤲶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "嬲", "Unihan_Traditional (Chữ Phồn thể)": "嬲", "Pinyin_Xie": "niǎo", "Âm Hán Việt_Xie": "điểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ biểu thị hành động trêu chọc hoặc tức giận trong khẩu ngữ và phương ngôn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肭', '{"9000": "5787.0", "Chữ Trung Quốc": "肭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 8 | nét | 肭 | nọi | tượng hình | con hải cẩu; béo; bộ 肉 gợi liên quan đến thịt/thân xác | 肭 có bộ 肉 (nhục, thịt/thân xác). Wiktionary chỉ ghi {{Han etym}} không phân giải cấu trúc. Chưa xác định được ls; chưa có nguồn học thuật cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nọi\": bộ 肉 (thịt) gợi con vật béo mập — hải cẩu (肭脐) với thân hình tròn trịa, mỡ dày, sống ở biển. | Gương Hán-Việt | 肭 xuất hiện trong từ 肭脐 (nọi tề) — chỉ dương vật hải cẩu dùng trong đông y; ít dùng độc lập. | Mở khoá kiến thức | Biết 肭 giúp đọc tên dược liệu đông y cổ liên quan đến hải cẩu (肭脐).", "Tự nguyên_Xie": "Tiểu triện | 肭 mang bộ 肉 (thịt), gợi liên quan đến cơ thể hoặc mỡ. Nghĩa chính là con hải cẩu (海狗) hoặc béo mập. Tiểu triện còn lưu lại hình dạng chữ. Chưa có phân tích Wiktionary cụ thể về ls hay cấu trúc; chưa có nguồn học thuật xác minh. Chưa có nguồn học thuật xác minh. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con hải cẩu", "Hạng Tần Suất (Jun Da)": "5787.0", "Tần Suất % (Jun Da)": "99.9741488572", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 内", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月内", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "内", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "肭", "Unihan_Traditional (Chữ Phồn thể)": "肭", "Pinyin_Xie": "nà", "Âm Hán Việt_Xie": "nạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này hầu như chỉ dùng trong từ ghép uất nột để chỉ loài hải cẩu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹈', '{"9000": "5788.0", "Chữ Trung Quốc": "鹈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 12 | nét | 弟 | đệ | biểu âm | em trai (cho âm) | 鳥 | điểu | biểu nghĩa | chim | 鹈 là chữ hình thanh: 鳥 (điểu, chim) biểu nghĩa chỉ đây là loài chim; 弟 (đệ) biểu âm cho âm tí/đệ. Chữ giản thể của 鵜.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đề\": bộ 鳥 (chim) + 弟 (đệ, em) — con chim bồ nông đứng thẳng như người em cõng túi thức ăn to tướng trên ngực. | Gương Hán-Việt | 鹈 xuất hiện trong 鹈鹕 (đề hồ — bồ nông); ít dùng độc lập trong từ Hán-Việt. | Mở khoá kiến thức | Biết 鹈 giúp đọc tên loài chim bồ nông (鹈鹕) trong văn học, sinh học tiếng Trung.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 鵜 = 弟 (biểu âm) + 鳥 (biểu nghĩa: chim), chữ hình thanh. 鵜 chỉ chim bồ nông (pelican). Chỉ dùng trong từ 鵜鶘 (tí hú — bồ nông) hoặc 鷿鵜. Tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đề hồ 鵜鶘,鹈鹕)", "Hạng Tần Suất (Jun Da)": "5788.0", "Tần Suất % (Jun Da)": "99.9741865825", "GavinGrover_Once (Chiết tự trực tiếp)": "弟 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰弟鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹈", "Unihan_Traditional (Chữ Phồn thể)": "鵜", "Pinyin_Xie": "tí", "Âm Hán Việt_Xie": "đề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường đi liền với chữ hồ để tạo thành danh từ chỉ loài chim bồ nông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹱', '{"9000": "5789.0", "Chữ Trung Quốc": "鹱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 18 | nét | 鹱 | hoắc | tượng hình | chim biển bộ Procellariiformes (hải âu, hải yến, shearwater); bộ 鳥 gợi loài chim | 鹱 là tên loài chim biển. Wiktionary không phân giải cấu trúc nội bộ cụ thể; chưa có nguồn học thuật xác định ls. Bộ 鳥 (điểu) cho biết đây là chim.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoắc\": chữ chứa bộ 鳥 (chim) — loài chim biển 鹱 lướt nhanh hoắc hoắc trên sóng, không biết mệt. | Gương Hán-Việt | 鹱 là thuật ngữ chuyên ngành điểu học; ít xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 鹱 giúp đọc tên khoa học các loài chim biển trong văn bản điểu học tiếng Trung.", "Tự nguyên_Xie": "鹱 (huò) chỉ các loài chim biển thuộc bộ Procellariiformes — bao gồm hải âu (albatross), chim hải yến (petrel) và shearwater. Wiktionary liệt kê chữ cổ 鸌 nhưng không phân giải cấu trúc hội ý hay hình thanh. Chưa có nguồn học thuật xác minh. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loại chim biển; vạc; như \"chim vạc\"", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鸟 + 蒦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鸟蒦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蒦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹱", "Unihan_Traditional (Chữ Phồn thể)": "鹱", "Pinyin_Xie": "hù", "Âm Hán Việt_Xie": "oách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ một loài chim biển thuộc họ hải âu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窭', '{"9000": "5790.0", "Chữ Trung Quốc": "窭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 14 | nét | 穴 | huyệt | biểu nghĩa | hang, lỗ hổng | 婁 | lâu | biểu âm | (cho âm) | 窭 là chữ hình thanh: 穴 (huyệt, hang/lỗ hổng) biểu nghĩa gợi cảnh sống trong hang — ẩn dụ cho sự nghèo khó; 婁 (lâu) biểu âm. Chữ phồn thể là 窶.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lũ\": bộ 穴 (hang) + 婁 (lâu) — người nghèo phải sống trong hang hốc (穴), thiếu thốn đủ bề. | Gương Hán-Việt | 窭 xuất hiện trong 窭人 (lũ nhân — người nghèo) trong văn học cổ; ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 窭 giúp đọc văn cổ tả cảnh nghèo khó, kham khổ trong văn học Hán.", "Tự nguyên_Xie": "Wiktionary ghi 窶 = 穴 (biểu nghĩa: hang, lỗ hổng) + 婁 (biểu âm), chữ hình thanh. Hình ảnh người sống trong hang gợi cảnh nghèo túng, thiếu thốn. Chữ giản thể viết 窭. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghèo túng", "Hạng Tần Suất (Jun Da)": "5790.0", "Tần Suất % (Jun Da)": "99.9742620332", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 娄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴娄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "娄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窭", "Unihan_Traditional (Chữ Phồn thể)": "窶", "Pinyin_Xie": "jù", "Âm Hán Việt_Xie": "cũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường dùng trong văn viết để tả cảnh nghèo khổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黧', '{"9000": "5791.0", "Chữ Trung Quốc": "黧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黑 | Số nét | 20 | nét | 𥝢 | lợi | biểu âm | biến thể của 利 (cho âm) | 黑 | hắc | biểu nghĩa | đen | 黧 là chữ hình thanh: 黑 (hắc, đen) biểu nghĩa; 𥝢 (biến thể của 利) biểu âm. Màu đen vàng xạm, không thuần đen như 黑.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lê\": bộ 黑 (hắc/đen) + 利 (lợi) — da mặt đen xạm (黧黑) như người lao động nhiều năm dưới nắng, rám nắng đến mức lê lết. | Gương Hán-Việt | 黧 xuất hiện trong 黧黑 (lê hắc — đen xạm); ít dùng độc lập trong tiếng Việt. | Mở khoá kiến thức | Biết 黧 giúp đọc miêu tả màu da hoặc màu sắc đen vàng trong văn học cổ.", "Tự nguyên_Xie": "Wiktionary ghi: 黧 = 𥝢 (biến thể 利, biểu âm) + 黑 (biểu nghĩa: đen), chữ hình thanh. Nghĩa: màu vàng đen, đen xạm — không thuần đen mà ngả vàng. Xuất hiện trong thành ngữ 黧黑 (đen xạm). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màu đen xạm", "Hạng Tần Suất (Jun Da)": "5791.0", "Tần Suất % (Jun Da)": "99.9742997585", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 黑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱黑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "黧", "Unihan_Traditional (Chữ Phồn thể)": "黧", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "lê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ để miêu tả màu sắc da mặt hoặc lông thú. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谵', '{"9000": "5792.0", "Chữ Trung Quốc": "谵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 15 | nét | 言 | ngôn | biểu nghĩa | lời nói | 詹 | chiêm | biểu âm | (cho âm) | 谵 là chữ hình thanh: 言 (ngôn, lời nói) biểu nghĩa chỉ liên quan đến lời nói; 詹 (chiêm) biểu âm. Chữ phồn thể là 譫. Nghĩa: nói sảng, nói mê, lảm nhảm mất kiểm soát.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiêm\": bộ 言 (lời nói) + 詹 (chiêm) — người bệnh nặng nói chiêm bao, miệng lảm nhảm không ngừng trong cơn mê sảng. | Gương Hán-Việt | 谵 xuất hiện trong 谵语 (chiêm ngữ — nói mê sảng) trong y học cổ truyền; ít dùng độc lập. | Mở khoá kiến thức | Biết 谵 giúp đọc thuật ngữ y học cổ truyền liên quan đến triệu chứng mê sảng (谵语, 谵妄).", "Tự nguyên_Xie": "Wiktionary ghi 譫 = 言 (biểu nghĩa: lời nói) + 詹 (biểu âm), chữ hình thanh. Nghĩa: nói nhiều lảm nhảm; nói mê sảng trong bệnh tật. Xuất hiện trong từ 譫語/谵语 (mê sảng) — triệu chứng y học. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói mê, nói sảng", "Hạng Tần Suất (Jun Da)": "5792.0", "Tần Suất % (Jun Da)": "99.9743374838", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 詹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠詹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "詹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谵", "Unihan_Traditional (Chữ Phồn thể)": "譫", "Pinyin_Xie": "zhān", "Âm Hán Việt_Xie": "chiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường kết hợp thành từ ghép để chỉ trạng thái nói nhảm khi bệnh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沆', '{"9000": "5793.0", "Chữ Trung Quốc": "沆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 沆 | hàng | tượng hình | mặt nước mênh mông; sương mù buổi tối; bộ 水 gợi liên quan đến nước | 沆 có bộ 水 (thủy, nước). Wiktionary không phân giải cấu trúc nội bộ thành hình thanh hay hội ý; ghi {{Han etym}} chung. Chưa xác định được ls cụ thể. Chữ có hai âm đọc: hàng (sương mù, mặt nước) và háng (nước chảy).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàng\": bộ 水 (nước) — sương mù (沆瀣) mênh mông trên mặt nước, dày đặc như hàng hàng lớp lớp. | Gương Hán-Việt | 沆 xuất hiện trong 沆瀣一气 (hàng giải nhất khí — đồng lõa, cùng hội cùng thuyền); ít dùng độc lập. | Mở khoá kiến thức | Biết 沆 giúp đọc thành ngữ 沆瀣一气 — dùng chỉ những kẻ xấu câu kết với nhau.", "Tự nguyên_Xie": "Tiểu triện | 沆 dùng trong các từ như 沆漭 (mặt nước mênh mông), 沆瀣 (sương mù đêm). Bộ 水 gợi liên quan đến nước/sông. Tiểu triện còn lưu lại. Chưa có phân tích Wiktionary cụ thể về ls hay cấu trúc; chưa có nguồn học thuật xác minh. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước lũ; chở qua", "Hạng Tần Suất (Jun Da)": "5793.0", "Tần Suất % (Jun Da)": "99.9743752091", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 亢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵亢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沆", "Unihan_Traditional (Chữ Phồn thể)": "沆", "Pinyin_Xie": "hàng", "Âm Hán Việt_Xie": "hãng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ sương móc hoặc làm tính từ trong từ ghép chỉ sự thông đồng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嫒', '{"9000": "5794.0", "Chữ Trung Quốc": "嫒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 13 | nét | 嫒 | ái | tượng hình | tiếng gọi con gái người khác; bộ 女 gợi giới tính nữ | 嫒 có bộ 女 (nữ). Wiktionary không có mục riêng; cấu trúc nội bộ chưa được phân tích học thuật. Chưa xác định ls. Chữ dùng trong xưng hô lịch sự khi gọi con gái người khác.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ái\": bộ 女 (nữ) + âm ái (yêu thương) — 令嫒 là cách gọi trân trọng, yêu quý con gái nhà người. | Gương Hán-Việt | 嫒 xuất hiện trong 令嫒 (lệnh ái — lệnh ái, tiếng gọi lịch sự con gái người khác) trong giao tiếp trang trọng. | Mở khoá kiến thức | Biết 嫒 giúp dùng đúng xưng hô lịch sự 令嫒 khi nói về con gái của người đối thoại.", "Tự nguyên_Xie": "嫒 (ài) là chữ dùng trong xưng hô tôn kính: 令嫒 (lệnh ái) — tiếng gọi trân trọng con gái của người khác. Bộ 女 biểu nghĩa chỉ giới nữ. Không có mục Wiktionary; chưa có phân tích ls. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng gọi con gái người khác", "Hạng Tần Suất (Jun Da)": "5794.0", "Tần Suất % (Jun Da)": "99.9744129344", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 爱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女爱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "嫒", "Unihan_Traditional (Chữ Phồn thể)": "嬡", "Pinyin_Xie": "ài", "Âm Hán Việt_Xie": "ái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường dùng trong từ tôn xưng lệnh ái để chỉ con gái nhà người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('塬', '{"9000": "5795.0", "Chữ Trung Quốc": "塬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 13 | nét | 塬 | nguyên | tượng hình | cao nguyên dạng bàn tại tây bắc Trung Quốc; bộ 土 gợi địa hình/đất | 塬 có bộ 土 (thổ, đất). Wiktionary không có mục riêng; cấu trúc nội bộ chưa được phân tích học thuật. Chưa xác định ls. Đây là địa hình đặc trưng vùng Hoàng Thổ cao nguyên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nguyên\": bộ 土 (đất) + 原 (nguyên, đồng bằng) — cao nguyên đất hoàng thổ mênh mông, bề mặt bằng phẳng như tờ giấy, vách dốc đứng hai bên. | Gương Hán-Việt | 塬 ít xuất hiện trong từ Hán-Việt thông dụng; dùng trong địa lý học vùng tây bắc Trung Quốc. | Mở khoá kiến thức | Biết 塬 giúp đọc tài liệu địa lý, văn học miêu tả vùng cao nguyên hoàng thổ Thiểm Tây, Cam Túc.", "Tự nguyên_Xie": "塬 (yuán) là chữ chỉ dạng địa hình đặc trưng ở tây bắc Trung Quốc: cao nguyên đất vàng (hoàng thổ) có đỉnh bằng phẳng, vách dốc đứng. Bộ 土 biểu nghĩa. Phần còn lại liên quan đến âm. Không có mục Wiktionary; chưa có nguồn học thuật xác minh cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đụn", "Hạng Tần Suất (Jun Da)": "5795.0", "Tần Suất % (Jun Da)": "99.9744506597", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 原", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土原", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "原", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "塬", "Unihan_Traditional (Chữ Phồn thể)": "塬", "Pinyin_Xie": "yuán", "Âm Hán Việt_Xie": "nguyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một dạng địa hình cao nguyên đất đỏ ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缣', '{"9000": "5796.0", "Chữ Trung Quốc": "缣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 缣 | kiêm | tượng hình | lụa mỏng mịn dùng để viết; bộ 糸 gợi liên quan đến tơ lụa | 缣 có bộ 糸 (mịch, tơ/sợi). Wiktionary ghi 縑 với mục {{Han etym}} nhưng không phân giải cấu trúc cụ thể. Chưa xác định ls. Chữ phồn thể là 縑.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiêm\": bộ 糸 (tơ) — tấm lụa 缣 kiêm cả vai trò giấy viết lẫn hàng dệt quý; học giả thời xưa viết sách trên 缣帛. | Gương Hán-Việt | 缣 xuất hiện trong 缣帛 (kiêm bạch — vải lụa), 缣素 (kiêm tố — lụa trắng để viết); ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 缣 giúp đọc văn bản lịch sử về vật liệu viết chữ thời cổ đại Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | 缣 (jiān) là loại lụa mịn màng, dùng trong thời cổ để viết thay giấy (trước khi giấy phổ biến). Bộ 糸 biểu nghĩa chỉ tơ lụa. Chữ phồn thể 縑 xuất hiện trong từ 縑素 (lụa trắng để viết), 縑帛 (vải lụa). Tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lụa nhũn (xưa dùng để viết)", "Hạng Tần Suất (Jun Da)": "5796.0", "Tần Suất % (Jun Da)": "99.974488385", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 兼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟兼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缣", "Unihan_Traditional (Chữ Phồn thể)": "縑", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "kiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại lụa dệt bằng tơ kép thời xưa dùng để viết vẽ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篯', '{"9000": "5797.0", "Chữ Trung Quốc": "篯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 16 | nét | 篯 | tiên | tượng hình | họ Tiên (tên người); bộ 竹 gợi liên quan đến tre/trúc | 篯 có bộ 竹 (trúc, tre). Wiktionary ghi 籛 với {{Han etym}} nhưng không phân giải cấu trúc. Chưa xác định ls. Chữ chủ yếu dùng trong tên người (Tiên Thiết — người sống lâu trong truyền thuyết).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiên\": bộ 竹 (trúc) — Tiên Khanh (篯铿) là tên của Bành Tổ, người sống lâu như trúc xanh không tàn. | Gương Hán-Việt | 篯 xuất hiện trong tên 篯铿 (Bành Tổ); ít dùng trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 篯 giúp đọc tài liệu về nhân vật thần thoại Bành Tổ (篯铿) trong văn hóa Trung Hoa.", "Tự nguyên_Xie": "篯 (jiān) chủ yếu xuất hiện trong tên 篯铿 (Tiên Khanh) — tên cổ của Bành Tổ (Péng Zǔ), nhân vật trường thọ trong truyền thuyết Trung Hoa. Bộ 竹 biểu nghĩa. Chữ phồn thể 籛. Chưa có phân tích Wiktionary cụ thể; chưa có nguồn học thuật xác minh cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Jian", "Hạng Tần Suất (Jun Da)": "5797.0", "Tần Suất % (Jun Da)": "99.9745261104", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 钱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮钱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "钱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篯", "Unihan_Traditional (Chữ Phồn thể)": "籛", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "tiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ riêng dùng làm họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酃', '{"9000": "5798.0", "Chữ Trung Quốc": "酃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 19 | nét | 霝 | linh | biểu âm | (cho âm) | 邑 | ấp | biểu nghĩa | làng ấp, địa danh | 酃 là chữ hình thanh: 邑 (ấp, làng ấp/địa danh) biểu nghĩa chỉ đây là tên đất; 霝 biểu âm. Chữ chỉ hồ Linh và huyện Linh ở Hồ Nam.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"linh\": bộ 邑 (ấp, đất) + 霝 (linh) — huyện Linh (酃縣) ở Hồ Nam, nơi có hồ nước trong vắt dùng ủ rượu linh thiêng. | Gương Hán-Việt | 酃 xuất hiện trong 酃湖 (linh hồ), 酃縣 (huyện Linh); ít dùng trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 酃 giúp đọc địa danh lịch sử tỉnh Hồ Nam Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi: 酃 = 霝 (biểu âm) + 邑 (biểu nghĩa: làng ấp), chữ hình thanh. Chỉ hồ Linh (酃湖) và huyện Linh (酃縣, nay là Viêm Lăng) ở tỉnh Hồ Nam. Tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên một cái hồ ở tỉnh Hồ Nam của Trung Quốc, nước dùng để ủ rượu nho; huyện Linh (ở tỉnh Hồ Nam của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "5798.0", "Tần Suất % (Jun Da)": "99.9745633189", "GavinGrover_Once (Chiết tự trực tiếp)": "霝 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰霝阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "霝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "酃", "Unihan_Traditional (Chữ Phồn thể)": "酃", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng chỉ địa danh cổ hoặc tên huyện ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喱', '{"9000": "5799.0", "Chữ Trung Quốc": "喱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 喱 | li | tượng hình | đơn vị đo lường (grain); dùng phiên âm curry (cà ri); bộ 口 gợi âm thanh/phiên âm | 喱 có bộ 口 (khẩu). Wiktionary ghi {{Han etym|厘}} — liên quan đến chữ 厘 (li, đơn vị đo). Chủ yếu dùng để phiên âm từ nước ngoài (curry → 咖喱). Chưa xác định ls cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"li\": bộ 口 (miệng) nếm thử — 咖喱 (cà ri) vào miệng tỏa mùi thơm nồng, li bì không quên. | Gương Hán-Việt | 喱 xuất hiện trong 咖喱 (li — cà ri), 啫喱 (thạch jelly); ít dùng độc lập trong từ Hán-Việt. | Mở khoá kiến thức | Biết 喱 giúp đọc tên các món ăn và thực phẩm nhập khẩu trong tiếng Trung hiện đại.", "Tự nguyên_Xie": "喱 (lí) liên quan đến 厘 — đơn vị đo cổ. Hiện chủ yếu dùng trong từ phiên âm: 咖喱 (cà ri, từ curry tiếng Anh/Tamil), 啫喱 (thạch, từ jelly). Bộ 口 gợi vai trò phiên âm. Chữ tạo muộn, không thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: già ly 咖喱); gam (đơn vị khối lượng)", "Hạng Tần Suất (Jun Da)": "5799.0", "Tần Suất % (Jun Da)": "99.9746005274", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 厘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口厘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "喱", "Unihan_Traditional (Chữ Phồn thể)": "喱", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "ly", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Chữ này làm lượng từ chỉ đơn vị trọng lượng cổ hoặc dùng trong từ dịch âm cà ri. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泔', '{"9000": "5800.0", "Chữ Trung Quốc": "泔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 水 | thủy | biểu nghĩa | nước | 甘 | cam | biểu âm | (cho âm) | 泔 là chữ hình thanh: 水 (thủy, nước) biểu nghĩa chỉ liên quan đến nước; 甘 (cam) biểu âm. Nghĩa: nước vo gạo, nước bẩn sau khi rửa gạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cam\": bộ 水 (nước) + 甘 (cam/ngọt) — nước vo gạo ban đầu hơi ngọt (甘), nhưng dùng xong thành nước bẩn. | Gương Hán-Việt | 泔 xuất hiện trong 泔水 (cam thủy — nước vo gạo, nước thải bếp); ít dùng độc lập. | Mở khoá kiến thức | Biết 泔 giúp đọc văn bản về sinh hoạt bếp núc, nông nghiệp truyền thống trong văn học cổ.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary ghi: 泔 = 水 (biểu nghĩa: nước) + 甘 (biểu âm), chữ hình thanh. Nghĩa gốc: nước vo gạo (泔水 — nước bẩn sau khi vo gạo). Hình ảnh đại triện và tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước vo gạo", "Hạng Tần Suất (Jun Da)": "5800.0", "Tần Suất % (Jun Da)": "99.9746377359", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 甘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵甘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泔", "Unihan_Traditional (Chữ Phồn thể)": "泔", "Pinyin_Xie": "gān", "Âm Hán Việt_Xie": "cam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường kết hợp thành từ ghép chỉ nước vo gạo hoặc nước thải nhà bếp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('溘', '{"9000": "5801.0", "Chữ Trung Quốc": "溘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 溘 | hụp | tượng hình | bỗng chốc, đột ngột; bộ 水 gợi hình ảnh nước cuốn trôi bất ngờ | 溘 có bộ 水 (thủy, nước). Wiktionary không có mục phân tích cấu trúc nội bộ cụ thể; chưa xác định ls. Chữ dùng chủ yếu trong thơ cổ với nghĩa đột ngột, bỗng chốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hụp\": bộ 水 (nước) — như bị nước hụp xuống bất ngờ, hình ảnh gợi sự đột ngột, ra đi bất thần không kịp trở tay. | Gương Hán-Việt | 溘 ít dùng trong từ Hán-Việt thông dụng; xuất hiện trong thơ cổ với nghĩa đột ngột qua đời (溘然长逝). | Mở khoá kiến thức | Biết 溘 giúp đọc thơ cổ điển Hán, đặc biệt tác phẩm Khuất Nguyên và thơ tả cái chết đột ngột.", "Tự nguyên_Xie": "Tiểu triện | 溘 (kè) dùng trong văn học cổ để chỉ sự đột ngột, bất ngờ — như nước ập tới (bộ 水). Xuất hiện nhiều trong thơ Khuất Nguyên (Ly Tao: 溘死以流亡兮 — bỗng chết mà trôi dạt). Tiểu triện còn lưu lại. Chưa có phân tích Wiktionary cụ thể; chưa có nguồn học thuật xác minh cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bỗng chốc", "Hạng Tần Suất (Jun Da)": "5801.0", "Tần Suất % (Jun Da)": "99.9746749445", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 盍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵盍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "盍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "溘", "Unihan_Traditional (Chữ Phồn thể)": "溘", "Pinyin_Xie": "kè", "Âm Hán Việt_Xie": "khạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Chữ này thường làm phó từ đứng trước động từ để chỉ hành động xảy ra đột ngột. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迕', '{"9000": "5802.0", "Chữ Trung Quốc": "迕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 7 | nét | 迕 | ngỗ | tượng hình | gặp gỡ, đối nghịch, trái ngược; bộ 辶 gợi di chuyển/gặp gỡ | 迕 có bộ 辶 (sước, đi lại). Wiktionary ghi {{Han etym}} nhưng không phân giải cụ thể. Chưa xác định ls. Nghĩa: gặp gỡ, đối nghịch, bất tuân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngỗ\": bộ 辶 (đi) — kẻ ngỗ ngược đi thẳng vào lề ngược, đối đầu trực tiếp với mọi người. | Gương Hán-Việt | 迕 ít xuất hiện trong từ Hán-Việt thông dụng; dùng trong văn ngữ cổ với nghĩa ngỗ ngược, trái lệnh. | Mở khoá kiến thức | Biết 迕 giúp đọc văn bản cổ tả tính cách bất tuân, ngỗ ngược hay hành động đi ngược lại quy tắc.", "Tự nguyên_Xie": "迕 (wù) mang bộ 辶 (đi lại), gợi hành động đi ngược lại, gặp mặt đối diện. Nghĩa: trái ngược, bất tuân, vi phạm. Chưa có phân tích Wiktionary cụ thể về cấu trúc; chưa có nguồn học thuật xác minh. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gặp gỡ", "Hạng Tần Suất (Jun Da)": "5802.0", "Tần Suất % (Jun Da)": "99.974712153", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 午", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶午", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "午", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "迕", "Unihan_Traditional (Chữ Phồn thể)": "迕", "Pinyin_Xie": "wù", "Âm Hán Việt_Xie": "ngỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ chỉ sự gặp gỡ hoặc tính từ chỉ sự trái ngược, ngang bướng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肀', '{"9000": "5803.0", "Chữ Trung Quốc": "肀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 聿 | Số nét | 4 | nét | 肀 | duật | tượng hình | cây bút lông (hình tượng cổ của bút viết); tự thân là bộ thủ | 肀 là bộ thủ độc lập — hình vẽ cổ của cây bút lông cầm tay. Đây là dạng cổ của chữ 聿 (duật — bút viết). Không có thành phần con; chính 肀 là hình tượng tự thân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"duật\": tự thân 肀 là hình tượng bàn tay cầm bút — duật bút viết lên, mỗi nét là một sáng tạo. | Gương Hán-Việt | 肀 tồn tại như bộ thủ trong các chữ như 肃 (túc), 肄 (dị); ít dùng độc lập. | Mở khoá kiến thức | Biết 肀 giúp nhận ra bộ thủ trong các chữ liên quan đến viết lách, nghi lễ như 肃, 肄, 聿.", "Tự nguyên_Xie": "肀 là hình vẽ tượng hình cổ của cây bút lông (tức 聿). Không có mục Wiktionary riêng; cấu trúc là tượng hình thuần túy — hình bàn tay cầm bút. Chữ chủ yếu tồn tại như bộ thủ trong chữ hợp thể, không dùng độc lập. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "duật (tdhv) duật1", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: me", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⺺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "肀", "Unihan_Traditional (Chữ Phồn thể)": "肀", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "duật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ chỉ cây bút hoặc làm bộ thủ trong cấu tạo chữ Hán. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秫', '{"9000": "5804.0", "Chữ Trung Quốc": "秫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 10 | nét | 禾 | hòa | biểu nghĩa | lúa, ngũ cốc | 朮 | truật | biểu âm | (cho âm; gốc là lúa nếp nhỏ) | 秫 là chữ hình thanh (có thể kiêm hội ý): 禾 (hòa, lúa/ngũ cốc) biểu nghĩa; 朮 (truật) biểu âm — nhưng 朮 nguyên nghĩa cũng là lúa nếp nhỏ nên đây còn có yếu tố hội ý. Chữ chỉ lúa nếp dùng nấu rượu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"truật\": bộ 禾 (lúa) + 朮 (truật, nếp nhỏ) — hạt nếp truật truật dùng nấu rượu ngon, thơm tho. | Gương Hán-Việt | 秫 xuất hiện trong 秫酒 (truật tửu — rượu nếp), 秫米 (truật mễ — gạo nếp); ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 秫 giúp đọc văn bản về nấu rượu truyền thống, nông nghiệp và ẩm thực cổ Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi: 秫 = 禾 (biểu nghĩa: ngũ cốc) + 朮 (biểu âm, nguyên nghĩa là lúa nếp nhỏ), chữ hình thanh kiêm hội ý. Chú ý: 朮 ở đây không phải 术 (thuật) — hai chữ khác nhau. Nghĩa: lúa nếp dùng cất rượu (秫酒 — rượu nếp). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lúa nếp để cất rượu", "Hạng Tần Suất (Jun Da)": "5804.0", "Tần Suất % (Jun Da)": "99.9747865701", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 术", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾术", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "术", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秫", "Unihan_Traditional (Chữ Phồn thể)": "秫", "Pinyin_Xie": "shú", "Âm Hán Việt_Xie": "thuật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại lương thực hoặc nguyên liệu dùng để nấu rượu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裣', '{"9000": "5805.0", "Chữ Trung Quốc": "裣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 12 | nét | 裣 | liễm | tượng hình | vạt áo; cử chỉ chắp tay cúi đầu chào; bộ 衣 gợi liên quan đến quần áo | 裣 có bộ 衣 (y, quần áo). Wiktionary không có mục riêng; cấu trúc nội bộ chưa được phân tích học thuật. Chưa xác định ls. Chữ dùng trong nghi lễ chào hỏi cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liễm\": bộ 衣 (áo) — 裣衽 là cử chỉ liễm lại vạt áo, cúi mình chào kiểu cổ đại, nét văn hóa lễ nghi Trung Hoa. | Gương Hán-Việt | 裣 xuất hiện trong 裣衽 (liễm nhẫm — cử chỉ kéo vạt áo cúi chào); ít dùng trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 裣 giúp đọc văn bản về lễ nghi, trang phục và nghi thức chào hỏi trong xã hội phong kiến.", "Tự nguyên_Xie": "裣 (liǎn) mang bộ 衣 (quần áo), liên quan đến vạt áo và cử chỉ nghi lễ. Từ 裣衽 (liễm nhẫm) chỉ cử chỉ cúi mình kéo vạt áo chào hỏi trong lễ nghi cổ. Không có mục Wiktionary; chưa có phân tích cấu trúc; chưa có nguồn học thuật xác minh. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: liễm nhẫm 襝衽,裣衽)", "Hạng Tần Suất (Jun Da)": "5805.0", "Tần Suất % (Jun Da)": "99.9748237786", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 佥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤佥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "佥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裣", "Unihan_Traditional (Chữ Phồn thể)": "襝", "Pinyin_Xie": "liǎn", "Âm Hán Việt_Xie": "liễm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong văn viết cổ để tả cử chỉ sửa sang trang phục thể hiện sự kính cẩn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铋', '{"9000": "5806.0", "Chữ Trung Quốc": "铋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 金 | kim | biểu nghĩa | kim loại | 必 | tất | biểu âm | (cho âm) | 铋 là chữ hình thanh: 金 (kim, kim loại) biểu nghĩa chỉ đây là nguyên tố kim loại; 必 (tất) biểu âm. Đây là chữ tạo ra để phiên dịch tên nguyên tố bismuth (Bi) trong hóa học hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tất\": bộ 金 (kim loại) + 必 (tất, nhất thiết) — bismuth tất nhiên là kim loại, ánh bạc nhưng giòn. | Gương Hán-Việt | 铋 xuất hiện trong thuật ngữ hóa học 铋 (bismuth, Bi); ít dùng trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 铋 giúp đọc tài liệu hóa học, bảng tuần hoàn và tên nguyên tố trong tiếng Trung.", "Tự nguyên_Xie": "Wiktionary ghi: 铋 = 金 (biểu nghĩa: kim loại) + 必 (biểu âm), chữ hình thanh. Đây là chữ tạo mới để biểu thị nguyên tố bismuth (Bi, số nguyên tử 83) — kim loại màu trắng bạc, giòn, nặng. Chữ tạo muộn, không thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố bitmut, Bi", "Hạng Tần Suất (Jun Da)": "5806.0", "Tần Suất % (Jun Da)": "99.9748609871", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 必", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅必", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "必", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铋", "Unihan_Traditional (Chữ Phồn thể)": "鉍", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong lĩnh vực hóa học để chỉ nguyên tố kim loại bitmut. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒌', '{"9000": "5807.0", "Chữ Trung Quốc": "蒌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 蒌 | lâu | tượng hình | cỏ lâu (Artemisia selengensis); bộ 艹 gợi liên quan đến cây cỏ | 蒌 có bộ 艹 (thảo, cây cỏ). Wiktionary ghi 蔞 nhưng không phân giải cấu trúc nội bộ cụ thể. Chưa xác định ls. Chữ chỉ loài cỏ lâu (蒌蒿) ăn được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lâu\": bộ 艹 (cỏ) — cỏ lâu (蒌蒿) mọc ven bờ sông, non mềm ăn được, hái về xào lâu lâu mới chín. | Gương Hán-Việt | 蒌 xuất hiện trong 蒌蒿 (lâu hao — cỏ lâu, thực vật ăn được); ít dùng trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 蒌 giúp đọc tên thực vật, ẩm thực dã ngoại và thực phẩm vùng Giang Nam trong văn học.", "Tự nguyên_Xie": "Tiểu triện | 蒌 (lóu) chỉ loài cây 蒌蒿 (lâu hao — Artemisia selengensis), một loại cỏ ăn được ở vùng đầm lầy. Bộ 艹 biểu nghĩa chỉ thực vật. Tiểu triện còn lưu lại. Chưa có phân tích Wiktionary cụ thể về cấu trúc; chưa có nguồn học thuật xác minh. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ lâu (có mầm ăn được)", "Hạng Tần Suất (Jun Da)": "5807.0", "Tần Suất % (Jun Da)": "99.9748981957", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 娄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹娄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "娄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒌", "Unihan_Traditional (Chữ Phồn thể)": "蔞", "Pinyin_Xie": "lóu", "Âm Hán Việt_Xie": "lâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại thực vật thân thảo có thể ăn được. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('曩', '{"9000": "5808.0", "Chữ Trung Quốc": "曩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 21 | nét | 曩 | nán | tượng hình | trước kia, xưa kia; bộ 日 gợi liên quan đến thời gian/ngày tháng | 曩 có bộ 日 (nhật, mặt trời/ngày). Wiktionary ghi {{Han etym}} nhưng không phân giải cụ thể. Chưa xác định ls. Chữ dùng trong văn ngữ cổ với nghĩa thời gian đã qua.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nán\": bộ 日 (mặt trời) — những ngày xưa (曩日) như ánh nắng xưa đã tắt, chỉ còn trong ký ức. | Gương Hán-Việt | 曩 xuất hiện trong 曩者 (nán giả — trước kia), 曩日 (nán nhật — ngày xưa) trong văn học cổ. | Mở khoá kiến thức | Biết 曩 giúp đọc văn ngữ cổ điển Hán khi gặp các cụm chỉ thời gian quá khứ xa.", "Tự nguyên_Xie": "Tiểu triện | 曩 (nǎng) mang bộ 日 (mặt trời/thời gian), gợi thời điểm đã qua. Nghĩa: xưa kia, trước đây, hồi trước. Dùng nhiều trong văn ngữ cổ: 曩者 (nán giả — trước kia), 曩日 (nán nhật — ngày xưa). Tiểu triện còn lưu lại. Chưa có phân tích Wiktionary cụ thể; chưa có nguồn học thuật xác minh cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trước kia, xưa kia", "Hạng Tần Suất (Jun Da)": "5808.0", "Tần Suất % (Jun Da)": "99.9749354042", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 襄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱日襄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "襄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "曩", "Unihan_Traditional (Chữ Phồn thể)": "曩", "Pinyin_Xie": "nǎng", "Âm Hán Việt_Xie": "nãng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Phó từ | 副词 | Thường làm trạng ngữ chỉ thời gian đứng đầu câu hoặc trước động từ để chỉ việc trong quá khứ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赀', '{"9000": "5809.0", "Chữ Trung Quốc": "赀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 10 | nét | 赀 | tư | tượng hình | phạt tiền; lường tính; bộ 贝 gợi liên quan đến tiền tài | 赀 có bộ 贝 (bối, vỏ sò/tiền). Wiktionary ghi {{Han etym}} nhưng không phân giải cấu trúc. Chưa xác định ls. Nghĩa: phạt tiền, tài sản, ước tính.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": bộ 贝 (tiền) — tư lự, tính toán tài sản; phạt tiền (赀罚) là hình phạt cụ thể bằng tiền tài. | Gương Hán-Việt | 赀 xuất hiện trong 赀财 (tư tài — tài sản nhỏ), 赀罚 (tư phạt — phạt tiền) trong văn cổ; ít dùng trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 赀 giúp đọc văn bản pháp luật, hành chính thời cổ đại Trung Quốc liên quan đến tiền phạt.", "Tự nguyên_Xie": "Bạch thư | Tiểu triện | 赀 (zī) mang bộ 贝 (tiền tài), liên quan đến tiền phạt và tài sản. Nghĩa: phạt tiền, ước lượng, tài sản nhỏ. Hình ảnh bạch thư (lụa viết) và tiểu triện còn lưu lại. Chưa có phân tích Wiktionary cụ thể về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phạt tiền; lường tính", "Hạng Tần Suất (Jun Da)": "5809.0", "Tần Suất % (Jun Da)": "99.9749726127", "GavinGrover_Once (Chiết tự trực tiếp)": "此 + 贝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱此贝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "此", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赀", "Unihan_Traditional (Chữ Phồn thể)": "貲", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "ti", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Có thể làm danh từ chỉ của cải hoặc động từ chỉ việc phạt tiền, đánh giá trị. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箪', '{"9000": "5810.0", "Chữ Trung Quốc": "箪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 箪 | đan | tượng hình | cái giỏ tre đựng cơm (dạng giản thể của 簞); bộ 竹 gợi chất liệu tre | 箪 là chữ giản thể của 簞, có bộ 竹 (trúc, tre). Wiktionary ghi {{Han simp|簞|f=單|t=单}} — đây là chữ giản thể. Cấu trúc phồn thể 簞 = 竹 + 單. Chữ chỉ giỏ tre đựng cơm trong bữa ăn đơn giản.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đan\": bộ 竹 (tre) — giỏ tre 箪 đan bằng tay, đựng một giỏ cơm đạm bạc như Nhan Hồi mà vẫn vui. | Gương Hán-Việt | 箪 xuất hiện trong 箪食瓢饮 (đan thực biều ẩm — sống đạm bạc) — điển cố Luận Ngữ; ít dùng độc lập. | Mở khoá kiến thức | Biết 箪 giúp hiểu điển cố 箪食瓢饮 trong Luận Ngữ và văn học Nho gia.", "Tự nguyên_Xie": "Tiểu triện | 箪 là giản thể của 簞 (= 竹 biểu nghĩa: tre + 單 biểu âm). Chữ chỉ cái giỏ tre nhỏ dùng đựng cơm. Xuất hiện trong câu Luận Ngữ nổi tiếng: 一箪食，一瓢饮 (một giỏ cơm, một gáo nước — cảnh sống đạm bạc của Nhan Hồi). Tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái giỏ; cái làn; ống lam; ống trúc (đựng cơm thời xưa)", "Hạng Tần Suất (Jun Da)": "5810.0", "Tần Suất % (Jun Da)": "99.9750098212", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 单", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮单", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "单", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箪", "Unihan_Traditional (Chữ Phồn thể)": "簞", "Pinyin_Xie": "dān", "Âm Hán Việt_Xie": "đan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ đồ dùng bằng tre để đựng thức ăn của người xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('朊', '{"9000": "5811.0", "Chữ Trung Quốc": "朊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 8 | nét | 朊 | nhuyễn | tượng hình | dị thể của 脘 (vùng bụng trên); bộ 月/肉 gợi liên quan đến cơ thể | 朊 có bộ 月 (nguyệt — dạng viết tắt của 肉/nhục, thịt/cơ thể). Wiktionary không có mục riêng; đây là dị thể của 脘. Chưa xác định ls. Cũng dùng trong thuật ngữ 朊病毒 (prion — nhuyễn bệnh độc).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhuyễn\": bộ 月/肉 (thịt) — 朊病毒 (prion) là nhuyễn thể protein gây bệnh não xốp bò BSE; mềm nhũn như tên gọi. | Gương Hán-Việt | 朊 xuất hiện trong 朊病毒 (nhuyễn bệnh độc — prion) trong y học; ít dùng trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 朊 giúp đọc thuật ngữ y học hiện đại về prion và bệnh não xốp.", "Tự nguyên_Xie": "朊 (ruǎn) là dị thể của 脘 (phần bụng trên, dạ dày). Bộ 月 ở đây là dạng viết tắt của 肉 (thịt), chỉ bộ phận cơ thể. Hiện đại dùng trong 朊病毒 (prion — loại tác nhân gây bệnh protein bất thường). Không có mục Wiktionary riêng; chưa có nguồn học thuật xác minh cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dị thể của chữ 脘", "Hạng Tần Suất (Jun Da)": "5811.0", "Tần Suất % (Jun Da)": "99.9750470298", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 元", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月元", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "元", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "朊", "Unihan_Traditional (Chữ Phồn thể)": "朊", "Pinyin_Xie": "ruǎn", "Âm Hán Việt_Xie": "nguyễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong thuật ngữ sinh hóa hiện đại để chỉ prôtêin hoặc thể dị của chữ quản. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳙', '{"9000": "5812.0", "Chữ Trung Quốc": "鳙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 19 | nét | 魚 | ngư | biểu nghĩa | cá | 庸 | dung | biểu âm | (cho âm) | 鳙 là chữ hình thanh: 魚 (ngư, cá) biểu nghĩa chỉ đây là loài cá; 庸 (dung) biểu âm. Chữ chỉ cá mè hoa (bighead carp) — loài cá đầu to, thân đen.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dung\": bộ 魚 (cá) + 庸 (dung, tầm thường) — cá mè hoa 鳙 có bề ngoài tầm thường nhưng đầu to vô đối, thịt ngọt thơm. | Gương Hán-Việt | 鳙 xuất hiện trong 鳙鱼 (dung ngư — cá mè hoa), 胖头鱼 (cá đầu mập); ít dùng trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 鳙 giúp đọc tên các loài cá trong văn bản thủy sản, ẩm thực và sinh học tiếng Trung.", "Tự nguyên_Xie": "Wiktionary ghi: 鳙 = 魚 (biểu nghĩa: cá) + 庸 (biểu âm), chữ hình thanh. Chỉ loài cá mè hoa (Hypophthalmichthys nobilis) — cá nước ngọt đầu rất to, dân gian gọi là 胖头鱼 (cá đầu mập). Chữ tạo muộn, không thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá mè hoa; dung; như \"dung (loại cá chép)\" \n (Danh) Cá mè hoa; mình đen; đầu rất to; sinh sản ở nước ngọt. \n§ Tục gọi là bàn đầu ngư 胖頭魚.", "Hạng Tần Suất (Jun Da)": "5812.0", "Tần Suất % (Jun Da)": "99.9750842383", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 庸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼庸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "庸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳙", "Unihan_Traditional (Chữ Phồn thể)": "鱅", "Pinyin_Xie": "yōng", "Âm Hán Việt_Xie": "dung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loài cá nước ngọt có đầu rất to. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('仫', '{"9000": "5813.0", "Chữ Trung Quốc": "仫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 5 | nét | 仫 | mộc | tượng hình | tên tộc người Mulao ở Trung Quốc; bộ 人 gợi con người/dân tộc | 仫 có bộ 亻(nhân, người). Wiktionary không có mục riêng; cấu trúc nội bộ chưa được phân tích học thuật. Chưa xác định ls. Chữ dùng trong tên dân tộc 仫佬族 (tộc Mulao ở Quảng Tây).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mộc\": bộ 亻(người) — người dân tộc Mulao (仫佬) sống gần rừng, gần gũi thiên nhiên mộc mạc. | Gương Hán-Việt | 仫 ít xuất hiện trong từ Hán-Việt; dùng chủ yếu trong tên dân tộc 仫佬族. | Mở khoá kiến thức | Biết 仫 giúp nhận biết tên dân tộc thiểu số Mulao trong văn bản dân tộc học Trung Quốc.", "Tự nguyên_Xie": "仫 (mù) dùng trong tên dân tộc thiểu số 仫佬族 (Mulao/Mùlǎo zú) ở tỉnh Quảng Tây. Bộ 亻biểu nghĩa chỉ con người/dân tộc. Không có mục Wiktionary; chưa có nguồn học thuật xác minh cấu trúc. Chữ tạo muộn, không thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mu lao 仫佬)", "Hạng Tần Suất (Jun Da)": "5813.0", "Tần Suất % (Jun Da)": "99.9751214468", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 么", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻么", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "么", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "仫", "Unihan_Traditional (Chữ Phồn thể)": "仫", "Pinyin_Xie": "mù", "Âm Hán Việt_Xie": "mu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng trong tên gọi của dân tộc Mulao ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钎', '{"9000": "5814.0", "Chữ Trung Quốc": "钎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 8 | nét | 金 | kim | biểu nghĩa | kim loại | 千 | thiên | biểu nghĩa | nghìn (hội ý: kim loại cứng như nghìn lần rèn) | 钎 là chữ hội ý theo nguồn gốc Nhật (kokuji): 金 (kim, kim loại) + 千 (thiên, nghìn). Đây là chữ tạo ra trong tiếng Nhật (và tiếp nhận vào Hán ngữ) để chỉ cây choòng, xà beng — công cụ kim loại dùng đục đá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiên\": 金 (kim) + 千 (thiên, nghìn) — cây choòng 钎 là thép rèn nghìn lần, cứng như thiên lần búa giáng xuống đá. | Gương Hán-Việt | 钎 ít xuất hiện trong từ Hán-Việt thông dụng; dùng trong ngành khai khoáng (钎子 — cây choòng). | Mở khoá kiến thức | Biết 钎 giúp đọc tài liệu kỹ thuật khai mỏ, xây dựng tiếng Trung.", "Tự nguyên_Xie": "Wiktionary ghi: 钎 theo {{ja-etym-kokuji}} — chữ Nhật tạo ra (kokuji): 金 (kim loại) + 千 (nghìn), hội ý. Gợi ý: dụng cụ kim loại cứng như nghìn lần rèn. Chữ chỉ cây choòng/xà beng (drill rod) dùng trong khai thác mỏ. Chữ tạo muộn, không thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái choòng, cái xà beng", "Hạng Tần Suất (Jun Da)": "5814.0", "Tần Suất % (Jun Da)": "99.9751581386", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 千", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅千", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "千", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钎", "Unihan_Traditional (Chữ Phồn thể)": "釺", "Pinyin_Xie": "qiān", "Âm Hán Việt_Xie": "thiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ chất liệu hoặc công dụng để chỉ các loại dụng cụ kim loại nhọn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芑', '{"9000": "5815.0", "Chữ Trung Quốc": "芑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 6 | nét | 芑 | khởi | tượng hình | kê trắng (lúa khỉ); rau diếp; bộ 艹 gợi liên quan đến thực vật | 芑 có bộ 艹 (thảo, cây cỏ). Wiktionary ghi {{Han etym}} nhưng không phân giải cụ thể. Chưa xác định ls. Chữ chỉ loại kê trắng hoặc rau diếp trong thực vật học cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khởi\": bộ 艹 (cỏ) + âm khởi — hạt kê trắng 芑 là thực vật khởi đầu cho bữa ăn đơn giản thời cổ đại. | Gương Hán-Việt | 芑 xuất hiện trong 采芑 (thái khởi — hái kê, tên bài thơ Kinh Thi); ít dùng trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 芑 giúp đọc Kinh Thi và văn bản thực vật học cổ Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | 芑 (qǐ) mang bộ 艹 (cây cỏ), chỉ loài thực vật: kê trắng (hay rau diếp). Xuất hiện trong Kinh Thi 詩經 (Thái Khỉ — 采芑). Tiểu triện còn lưu lại. Chưa có phân tích Wiktionary cụ thể về cấu trúc; chưa có nguồn học thuật xác minh. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lúa khỉ (kê trắng); rau diếp", "Hạng Tần Suất (Jun Da)": "5815.0", "Tần Suất % (Jun Da)": "99.9751948303", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 己", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹己", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "己", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芑", "Unihan_Traditional (Chữ Phồn thể)": "芑", "Pinyin_Xie": "qǐ", "Âm Hán Việt_Xie": "khỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại lúa kê cổ hoặc rau diếp trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胙', '{"9000": "5816.0", "Chữ Trung Quốc": "胙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 9 | nét | 胙 | tộ | tượng hình | thịt tế lễ đem chia; ban thưởng; bộ 月/肉 gợi liên quan đến thịt | 胙 có bộ 月 (dạng viết tắt của 肉/nhục, thịt). Wiktionary ghi {{Han etym}} nhưng không phân giải cụ thể. Chưa xác định ls. Chữ liên quan đến nghi lễ tế tự: thịt sau khi tế rồi phân phát.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tộ\": bộ 肉 (thịt) — thịt tế lễ (胙肉) sau khi dâng cúng được chia phát, mang ý nghĩa ban phúc, tộ phần từ tổ tiên. | Gương Hán-Việt | 胙 xuất hiện trong 胙肉 (tộ nhục — thịt tế lễ), 福胙 (phúc tộ — phần thịt phúc lộc); ít dùng trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 胙 giúp đọc văn bản về nghi lễ tế tự, phong kiến và văn hóa tế lễ cổ Trung Hoa.", "Tự nguyên_Xie": "Bạch thư | 胙 (zuò) mang bộ 肉 (thịt), nghĩa gốc: thịt tế lễ sau khi dâng cúng, đem phân phát cho người tham dự. Cũng có nghĩa ban thưởng, phúc lành. Hình ảnh bạch thư (帛書) còn lưu lại. Chưa có phân tích Wiktionary cụ thể về cấu trúc; chưa có nguồn học thuật xác minh. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phần thịt tế rồi đem chia ra; báo đáp", "Hạng Tần Suất (Jun Da)": "5816.0", "Tần Suất % (Jun Da)": "99.9752315221", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 乍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月乍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胙", "Unihan_Traditional (Chữ Phồn thể)": "胙", "Pinyin_Xie": "zuò", "Âm Hán Việt_Xie": "tạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ thịt tế thần hoặc động từ với nghĩa ban thưởng, phong tước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盱', '{"9000": "5817.0", "Chữ Trung Quốc": "盱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 8 | nét | 盱 | hu | tượng hình | trợn mắt, mắt mở to; bộ 目 gợi liên quan đến mắt | 盱 có bộ 目 (mục, mắt). Wiktionary ghi {{Han etym}} nhưng không phân giải cụ thể. Chưa xác định ls. Nghĩa: trợn mắt, mắt mở to ngạc nhiên hoặc đe dọa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hu\": bộ 目 (mắt) — 盱 là cái nhìn hu hú mở to, trợn trừng, đôi mắt như muốn nói không bằng lời. | Gương Hán-Việt | 盱 xuất hiện trong 盱眙 (Hu Di — tên địa danh ở Giang Tô) và 盱衡 (hu hành — trợn mắt); ít dùng độc lập. | Mở khoá kiến thức | Biết 盱 giúp đọc địa danh lịch sử 盱眙 (Hu Di) và văn bản cổ tả biểu cảm khuôn mặt.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 盱 (xū) mang bộ 目 (mắt), nghĩa: trợn mắt, nhìn trừng trừng. Xuất hiện trong 盱衡 (hu hành — trợn mắt nhìn ngang) và địa danh 盱眙 (Hu Di — Hsu Yi, tên huyện ở Giang Tô). Hình ảnh kim văn, tiểu triện và lục thư thông còn lưu lại. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trợn mắt", "Hạng Tần Suất (Jun Da)": "5817.0", "Tần Suất % (Jun Da)": "99.9752682138", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 于", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目于", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "于", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "盱", "Unihan_Traditional (Chữ Phồn thể)": "盱", "Pinyin_Xie": "xū", "Âm Hán Việt_Xie": "hu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết cổ hoặc dùng trong tên địa danh như huyện Hu Dị. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糇', '{"9000": "5818.0", "Chữ Trung Quốc": "糇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 15 | nét | 糇 | hầu | tượng hình | lương khô, bánh lương; bộ 米 gợi liên quan đến gạo/lương thực | 糇 có bộ 米 (mễ, gạo/lương thực). Wiktionary ghi {{Han etym}} nhưng không phân giải cụ thể. Chưa xác định ls. Nghĩa: lương khô, bánh lương — thức ăn khô mang theo khi đi xa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hầu\": bộ 米 (gạo) — lương khô 糇 là gạo rang hay bánh cứng, binh lính hầu hầu nhai trên đường chinh chiến dài ngày. | Gương Hán-Việt | 糇 xuất hiện trong 糇粮 (hầu lương — lương khô mang đường), 糇食 (hầu thực — lương khô); ít dùng trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 糇 giúp đọc văn học chiến trận cổ đại và thơ ca tả cảnh hành quân xa xôi.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 糇 (hóu) mang bộ 米 (gạo/lương thực), nghĩa: lương khô mang theo đường trường. Xuất hiện trong văn học cổ tả cảnh chinh chiến, đi xa. Hình ảnh tiểu triện và lục thư thông còn lưu lại. Chưa có phân tích Wiktionary cụ thể về cấu trúc; chưa có nguồn học thuật xác minh. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lương khô", "Hạng Tần Suất (Jun Da)": "5818.0", "Tần Suất % (Jun Da)": "99.9753049056", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 侯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米侯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "侯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "糇", "Unihan_Traditional (Chữ Phồn thể)": "餱", "Pinyin_Xie": "hóu", "Âm Hán Việt_Xie": "hầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp thành từ ghép để chỉ lương khô mang theo khi đi xa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('挹', '{"9000": "5819.0", "Chữ Trung Quốc": "挹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 10 | nét | 手 | thủ | biểu nghĩa | tay | 邑 | ấp | biểu âm | (cho âm) | 挹 là chữ hình thanh: 手 (thủ, tay) biểu nghĩa chỉ hành động dùng tay; 邑 (ấp) biểu âm. Nghĩa: rót, múc, chắt — hành động dùng tay múc hoặc kéo xuống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"úp\": bộ 手 (tay) + 邑 (ấp) — tay úp gáo múc nước (挹注), rót từ bình này sang bình khác. | Gương Hán-Việt | 挹 xuất hiện trong 挹注 (úp chú — múc đổ, bổ sung); ít dùng độc lập trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 挹 giúp đọc văn học cổ tả hành động múc nước, rót rượu và hình ảnh khiêm nhường.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi: 挹 = 手 (biểu nghĩa: tay) + 邑 (biểu âm), chữ hình thanh. Nghĩa: múc nước, rót, chắt; cũng nghĩa thu lại, kéo lui. Hình ảnh tiểu triện và lục thư thông còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rót, chắt, chút; lui, nén đi", "Hạng Tần Suất (Jun Da)": "5819.0", "Tần Suất % (Jun Da)": "99.9753415973", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 邑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌邑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "邑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "挹", "Unihan_Traditional (Chữ Phồn thể)": "挹", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ấp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ thể hiện hành động múc chất lỏng hoặc ẩn dụ cho việc tiếp thu, khiêm tốn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('捭', '{"9000": "5820.0", "Chữ Trung Quốc": "捭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 捭 | bái | tượng hình | đánh bằng hai tay; mở ra; bộ 手 gợi hành động bàn tay | 捭 có bộ 手 (thủ, tay). Wiktionary ghi {{Han etym}} nhưng không phân giải cụ thể. Chưa xác định ls. Nghĩa: dùng hai tay đánh hoặc mở ra — xuất hiện trong từ 捭阖 (bái hạp — mở đóng, thuật ngoại giao).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bái\": bộ 手 (tay) — 捭阖 là thuật ngoại giao bái hạp mở đóng, tay phải biết khi nào mở, khi nào đóng. | Gương Hán-Việt | 捭 xuất hiện trong 捭阖 (bái hạp — thuật ngoại giao, tên sách Quỷ Cốc Tử); ít dùng độc lập. | Mở khoá kiến thức | Biết 捭 giúp đọc tài liệu về thuật ngoại giao cổ đại, đặc biệt sách Quỷ Cốc Tử (鬼谷子·捭阖).", "Tự nguyên_Xie": "Tiểu triện | 捭 (bǎi) mang bộ 手 (tay), nghĩa: đánh bằng hai tay, mở ra. Xuất hiện trong từ 捭阖 (bái hạp — thuật mở đóng trong ngoại giao, tên sách của Quỷ Cốc Tử). Tiểu triện còn lưu lại. Chưa có phân tích Wiktionary cụ thể về cấu trúc; chưa có nguồn học thuật xác minh. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mở ra; hai tay đánh", "Hạng Tần Suất (Jun Da)": "5820.0", "Tần Suất % (Jun Da)": "99.975378289", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "捭", "Unihan_Traditional (Chữ Phồn thể)": "捭", "Pinyin_Xie": "bǎi", "Âm Hán Việt_Xie": "bãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong thuật ngữ chính trị cổ đại như bái hạp để chỉ việc mở đóng, liên kết chia rẽ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('悱', '{"9000": "5821.0", "Chữ Trung Quốc": "悱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 11 | nét | 悱 | phỉ | tượng hình | tấm tức muốn nói mà không thành lời; bộ 心 gợi cảm xúc nội tâm | 悱 có bộ 忄(tâm, lòng/cảm xúc). Wiktionary ghi {{Han etym}} nhưng không phân giải cụ thể. Chưa xác định ls. Nghĩa: tức lòng muốn nói mà chưa diễn đạt được — xuất hiện trong Luận Ngữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phỉ\": bộ 心 (lòng) — cảm giác phỉ phui, tức lòng muốn nói điều gì mà mãi không tìm được lời thích hợp. | Gương Hán-Việt | 悱 xuất hiện trong 悱恻 (phỉ trắc — não lòng, xúc động sâu xa) và câu Luận Ngữ nổi tiếng; ít dùng độc lập. | Mở khoá kiến thức | Biết 悱 giúp đọc Luận Ngữ và văn học tả trạng thái nội tâm dồn nén, xúc cảm chưa bộc lộ được.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 悱 (fěi) mang bộ 忄(lòng), nghĩa: tức tưởi, nung nấu muốn nói mà chưa nói được. Xuất hiện trong Luận Ngữ: 不愤不启，不悱不发 — không bực thì không gợi mở, không tức tưởi thì không khai phá. Tiểu triện và lục thư thông còn lưu lại. Chưa có phân tích Wiktionary cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tấm tức, muốn nói mà không được", "Hạng Tần Suất (Jun Da)": "5821.0", "Tần Suất % (Jun Da)": "99.9754149808", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 非", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄非", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "非", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "悱", "Unihan_Traditional (Chữ Phồn thể)": "悱", "Pinyin_Xie": "fěi", "Âm Hán Việt_Xie": "phỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả trạng thái tâm lý ngập ngừng, u uất muốn bày tỏ trong văn cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬟', '{"9000": "5822.0", "Chữ Trung Quốc": "鬟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 23 | nét | 髟 | tiêu | biểu nghĩa | tóc dài rũ xuống | 睘 | hoàn | biểu âm | (cho âm) | 鬟 là chữ hình thanh: 髟 (tiêu, tóc dài) biểu nghĩa chỉ liên quan đến tóc; 睘 (hoàn) biểu âm. Nghĩa: búi tóc tròn kiểu cổ đại của phụ nữ Trung Hoa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàn\": bộ 髟 (tóc) + 睘 (hoàn/vòng tròn) — búi tóc 鬟 tròn như vòng hoa, xoắn vào nhau hoàn hảo trên đỉnh đầu thiếu nữ. | Gương Hán-Việt | 鬟 xuất hiện trong 鬟髻 (hoàn kế — búi tóc tròn), 双鬟 (song hoàn — hai búi tóc); ít dùng trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 鬟 giúp đọc văn học cổ tả vẻ đẹp phụ nữ, trang phục và kiểu tóc truyền thống Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi: 鬟 = 髟 (biểu nghĩa: tóc dài) + 睘 (biểu âm), chữ hình thanh. Chỉ kiểu tóc búi tròn truyền thống của phụ nữ Trung Hoa (鬟髻). Tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "uốn tóc, quấn tóc", "Hạng Tần Suất (Jun Da)": "5822.0", "Tần Suất % (Jun Da)": "99.9754516725", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 睘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟睘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "睘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "鬟", "Unihan_Traditional (Chữ Phồn thể)": "鬟", "Pinyin_Xie": "huán", "Âm Hán Việt_Xie": "hoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ kiểu tóc búi của phụ nữ thời xưa hoặc phiếm chỉ người tỳ nữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('崤', '{"9000": "5823.0", "Chữ Trung Quốc": "崤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 11 | nét | 崤 | hào | tượng hình | tên núi Hào Sơn, địa danh lịch sử | 崤 là địa danh chuyên dụng, chỉ núi Hào Sơn (崤山) ở tỉnh Hà Nam, Trung Quốc — một trong những ải hiểm yếu nổi tiếng thời cổ đại. Cấu trúc nội bộ không có dữ liệu phân tích lục thư.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hào\": núi 崤 (Hào Sơn) — ải hiểm yếu thời cổ, ai qua được 崤函 là kiểm soát cả miền Trung Nguyên. | Gương Hán-Việt | \"hào\" — ít dùng trong tiếng Việt hiện đại; xuất hiện trong sử địa Trung Hoa: 崤山 (Hào Sơn) | Mở khoá kiến thức | Biết 崤 mở khoá: 崤函 (Hào Hàm — ải chiến lược), 崤山 (Hào Sơn — tên núi).", "Tự nguyên_Xie": "Wiktionary ghi nhận 崤 là địa danh, dùng để chỉ 崤山 (Hào Sơn), cụm núi hiểm trở ở phía tây Hà Nam. Cùng với 函谷關, tạo thành 崤函 — tuyến phòng thủ chiến lược thời chiến quốc. Không có nguồn phân tích hình thể cụ thể. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: yêm tư 崤嵫)", "Hạng Tần Suất (Jun Da)": "5823.0", "Tần Suất % (Jun Da)": "99.975561231", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 肴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山肴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "崤", "Unihan_Traditional (Chữ Phồn thể)": "崤", "Pinyin_Xie": "xiáo", "Âm Hán Việt_Xie": "hào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ địa danh núi Hào Sơn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('澶', '{"9000": "5824.0", "Chữ Trung Quốc": "澶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 16 | nét | 澶 | thiện | tượng hình | địa danh, tên con sông và đất cổ ở Hà Nam | 澶 là chữ địa danh, cấu trúc nội bộ không có dữ liệu phân tích lục thư từ nguồn anchor. Glyph nguyên Tiểu triện có sẵn nhưng wikitext không ghi rõ phân tích thành phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiện\": 澶 gắn với 澶淵 (Thiện Uyên) — địa danh lịch sử nơi Tống-Liêu ký hoà ước, chấm dứt chiến tranh. | Gương Hán-Việt | \"thiện\" — dùng chủ yếu trong sử địa: 澶淵 (Thiện Uyên), 澶州 (Thiện Châu) | Mở khoá kiến thức | Biết 澶 mở khoá: 澶淵之盟 (Hội minh Thiện Uyên — hiệp ước Tống-Liêu), 澶州 (Thiện Châu).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không ghi lại phân tích hình thể cụ thể cho 澶. Chữ này chủ yếu dùng như địa danh — 澶淵 (Thiện Uyên) là nơi diễn ra Hội minh Thiện Uyên năm 1004 giữa nhà Tống và nhà Liêu. Chưa có nguồn học thuật về nguồn gốc cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Thiền; nước chảy lững lờ", "Hạng Tần Suất (Jun Da)": "5824.0", "Tần Suất % (Jun Da)": "99.9755974059", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 亶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵亶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "澶", "Unihan_Traditional (Chữ Phồn thể)": "澶", "Pinyin_Xie": "chán", "Âm Hán Việt_Xie": "thiền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Dùng làm danh từ chỉ tên sông hoặc tính từ tả dòng nước chảy chậm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('甾', '{"9000": "5825.0", "Chữ Trung Quốc": "甾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 田 | Số nét | 8 | nét | 𠙹 | biểu âm | thành phần phiên âm cổ, nay mất | 田 | điền | biểu nghĩa | ruộng, ô vuông | 甾 là chữ hình thanh cổ: 𠙹 (biểu âm, không còn dùng độc lập) + 田 (Điền, biểu nghĩa: ruộng/ô vuông). Tuy nhiên trong thời hiện đại, chữ được hồi phục làm thuật ngữ sinh hoá cho steroid — phần trên tượng trưng ba nhánh phụ, phần 田 tượng trưng vòng tứ vòng. Chữ tạo muộn hậu kỳ theo nghĩa hóa học.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tai\": 甾 xưa là chữ địa lý cổ; nay sống lại trong khoa học — 甾体 (steroid) với 田 là lõi vòng vòng, nhánh trên là ba nhóm phụ. | Gương Hán-Việt | \"tai\" — ít phổ biến trong Hán-Việt; xuất hiện trong hoá học: 甾体 (tai thể — steroid) | Mở khoá kiến thức | Biết 甾 mở khoá: 甾体 (zāitǐ — steroid), 甾族化合物 (hợp chất steroid), 类固醇 (lèigùchún — corticosteroid).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Lục thư thông | Theo Wiktionary, 甾 là chữ hình thanh: 𠙹 (biểu âm) + 田 (ruộng, biểu nghĩa), được ghi nhận từ thời Tần trong Chiến Quốc. Hình dạng đã biến đổi qua nhiều giai đoạn. Chữ này gần như tuyệt tích trước khi được hồi phục vào thời hiện đại làm phiên dịch cho ''steroid'' (甾体). Theo cách hiểu mới, phần trên của 甾 biểu trưng ba nhánh phụ của steroid, và 田 biểu trưng lõi tứ vòng. Có ảnh giáp cốt văn, kim văn và Lục thư thông. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xtê-rô-ít (Anh: Steroid) (một trong số các hợp chất hữu cơ được sinh ra tự nhiên trong cơ thể, bao gồm hoóc-môn và vi-ta-min nào đó)", "Hạng Tần Suất (Jun Da)": "5825.0", "Tần Suất % (Jun Da)": "99.9756335809", "GavinGrover_Once (Chiết tự trực tiếp)": "巛 + 田", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱巛田", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "田", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巛", "Unihan_Simplified (Chữ Giản thể)": "甾", "Unihan_Traditional (Chữ Phồn thể)": "甾", "Pinyin_Xie": "zāi", "Âm Hán Việt_Xie": "tri", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong hóa học hiện đại để chỉ hợp chất steroid. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('欹', '{"9000": "5826.0", "Chữ Trung Quốc": "欹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 欠 | Số nét | 12 | nét | 欹 | y | tượng hình | thán từ biểu thị ngưỡng mộ; hoặc nghiêng lệch | 欹 có hai cách đọc và dùng: (1) yī — dạng khác của 猗, thán từ biểu cảm; (2) qī — dạng khác của 攲, nghĩa là nghiêng, xiêu. Không có dữ liệu phân tích lục thư từ nguồn anchor; chữ tạo muộn hậu kỳ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"y\": 欹 là tiếng than nhẹ — ồ, ái chà! Hoặc khi đọc qī: vật gì đó nghiêng nghiêng, chực đổ. | Gương Hán-Việt | \"y\" — dùng trong thơ cổ như thán từ: 欹乎 (y hồ, ôi chao) | Mở khoá kiến thức | Biết 欹 mở khoá: 欹斜 (qīxié — nghiêng lệch), 欹器 (qīqì — bình nước đứng thẳng khi rỗng, nghiêng khi đầy).", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary, 欹 có hai cách đọc: (1) yī — dùng như 猗, thán từ biểu thị ngưỡng mộ; (2) qī — dùng như 攲, có nghĩa là nghiêng lệch. Đại triện đã ghi nhận hình dạng này. Không có nguồn phân tích hình thể rõ ràng. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khen ngợi, ca ngợi; xanh tốt; dài; vậy, thế; nương, dựa vào", "Hạng Tần Suất (Jun Da)": "5826.0", "Tần Suất % (Jun Da)": "99.9756697559", "GavinGrover_Once (Chiết tự trực tiếp)": "奇 + 欠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰奇欠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "欠", "Unihan_Simplified (Chữ Giản thể)": "欹", "Unihan_Traditional (Chữ Phồn thể)": "欹", "Pinyin_Xie": "yī", "Âm Hán Việt_Xie": "y", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thán từ | 叹词 | Tính từ | 形容词 | Thường dùng làm động từ chỉ sự nghiêng lệch hoặc thán từ biểu thị cảm xúc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞽', '{"9000": "5827.0", "Chữ Trung Quốc": "瞽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 18 | nét | 鼓 | cổ | biểu âm | trống | 目 | mục | biểu nghĩa | mắt | 瞽 = 鼓 (Cổ, biểu âm: trống) + 目 (Mục, biểu nghĩa: mắt); chữ hình thanh. Bộ 目 chỉ liên quan đến mắt; 鼓 (gǔ) cho âm gần gǔ. Nghĩa gốc: mù mắt, không thấy. Nhạc sĩ mù thường được gọi là 瞽者 trong cổ văn Trung Hoa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cổ\": 瞽 = mắt 目 mà giống trống 鼓 — người mù như trống rỗng không thấy gì; nhưng tiếng trống thì ngân vang. | Gương Hán-Việt | \"cổ\" — ít dùng trong Hán-Việt hiện đại; xuất hiện trong văn cổ: 瞽者 (cổ giả — người mù), 瞽說 (cổ thuyết — lời nói mù quáng) | Mở khoá kiến thức | Biết 瞽 mở khoá: 瞽者 (gǔzhě — người mù), 瞽说 (gǔshuō — lời nói thiếu căn cứ), 聋瞽 (lóng gǔ — điếc và mù).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary không cung cấp phân tích glyph origin chi tiết cho 瞽. Dựa vào cấu trúc: 鼓 (biểu âm, trống) + 目 (biểu nghĩa, mắt) → chữ hình thanh. Nghĩa gốc là người mù. Trong văn hoá Trung Hoa cổ, 瞽者 (người mù) thường là nhạc sĩ hoặc thầy bói — vì người không thấy ánh sáng thường được cho là có giác quan thứ sáu. Tiểu triện và Lục thư thông ghi nhận hình dạng này. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mù mắt", "Hạng Tần Suất (Jun Da)": "5827.0", "Tần Suất % (Jun Da)": "99.9757059308", "GavinGrover_Once (Chiết tự trực tiếp)": "鼓 + 目", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱鼓目", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "目", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼓", "Unihan_Simplified (Chữ Giản thể)": "瞽", "Unihan_Traditional (Chữ Phồn thể)": "瞽", "Pinyin_Xie": "gǔ", "Âm Hán Việt_Xie": "cổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Dùng làm tính từ chỉ trạng thái mù lòa hoặc danh từ chỉ người mù. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钇', '{"9000": "5828.0", "Chữ Trung Quốc": "钇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 6 | nét | 钅 | kim | biểu nghĩa | kim loại | 乙 | ất | biểu âm | chữ thứ hai trong thiên can | 钇 = 钅 (Kim, biểu nghĩa: kim loại) + 乙 (Ất, biểu âm); chữ hình thanh. Cấu trúc điển hình của tên nguyên tố hoá học trong tiếng Trung: bộ 钅 chỉ kim loại, phần còn lại cho âm. 乙 (yǐ) cho âm yǐ (yttrium).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ất\": 钇 = kim loại 钅 + chữ Ất 乙 — nguyên tố kim loại đất hiếm yttrium, đọc âm như 乙 (ất). | Gương Hán-Việt | \"ất\" — dùng trong bảng thiên can; 钇 dùng riêng cho nguyên tố yttrium | Mở khoá kiến thức | Biết 钇 mở khoá: 钇 (Y — yttrium, nguyên tố đất hiếm), tên các nguyên tố kim loại đất hiếm trong tiếng Trung.", "Tự nguyên_Xie": "钇 là chữ hiện đại, được tạo ra để phiên dịch tên nguyên tố yttrium (Y, số nguyên tử 39). Không có nguồn Wiktionary về lịch sử hình thể. Theo mô hình đặt tên nguyên tố trong tiếng Trung: bộ 钅 (kim loại) + 乙 (biểu âm, âm yǐ). Chữ tạo muộn, chưa có nguồn học thuật về cổ hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố ytri, Y", "Hạng Tần Suất (Jun Da)": "5828.0", "Tần Suất % (Jun Da)": "99.9757421058", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + ㇠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅㇠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钇", "Unihan_Traditional (Chữ Phồn thể)": "釔", "Pinyin_Xie": "yǐ", "Âm Hán Việt_Xie": "ất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chuyên ngành hóa học để chỉ nguyên tố kim loại Ytri. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹪', '{"9000": "5829.0", "Chữ Trung Quốc": "鹪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 17 | nét | 焦 | tiêu | biểu âm | cháy khét | 鸟 | điểu | biểu nghĩa | chim | 鹪 = 焦 (Tiêu, biểu âm: cháy khét) + 鸟 (Điểu, biểu nghĩa: chim); chữ hình thanh. Bộ 鸟 chỉ loài chim; 焦 (jiāo) cho âm đọc. Tên loài chim nhỏ — chim wren (chim cúc cu nhỏ, họ Troglodytidae).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": 鹪 = chim 鸟 mang âm 焦 (Tiêu) — chú chim wren nhỏ xíu nhưng hót vang như tiếng lửa. | Gương Hán-Việt | \"tiêu\" — ít phổ biến; 鷦鷯 (tiêu liêu — chim wren) trong thơ cổ | Mở khoá kiến thức | Biết 鹪 mở khoá: 鷦鷯 (jiāoliáo — chim wren), 鷦鷯一枝 (jiāoliáo yī zhī — điển cố: chim nhỏ chỉ cần một cành để ngủ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 鹪 (giản thể của 鷦) chỉ loài chim wren — chim nhỏ họ Troglodytidae. Tiểu triện và Lục thư thông ghi nhận hình dạng này. Cấu trúc hình thanh: 鸟 (chim, biểu nghĩa) + phần cho âm jiāo. Tên phổ biến nhất là 鷦鷯 (jiāoliáo) — chim wren thông thường. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tiêu liêu 鷦鷯,鹪鹩)", "Hạng Tần Suất (Jun Da)": "5829.0", "Tần Suất % (Jun Da)": "99.9757782807", "GavinGrover_Once (Chiết tự trực tiếp)": "焦 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰焦鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "焦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹪", "Unihan_Traditional (Chữ Phồn thể)": "鷦", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường đi kèm với chữ khác tạo thành danh từ chỉ loài chim nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞔', '{"9000": "5830.0", "Chữ Trung Quốc": "鞔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 16 | nét | 革 | cách | biểu nghĩa | da thuộc | 免 | miễn | biểu âm | miễn trừ | 鞔 = 革 (Cách, biểu nghĩa: da thuộc) + 免 (Miễn, biểu âm); chữ hình thanh. Bộ 革 chỉ liên quan đến da thuộc, đồ da; 免 (miǎn) cho âm gần mán/wǎn. Nghĩa: bọc da (mặt trống), phủ da lên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mân\": 鞔 = da 革 + miễn 免 — bọc da lên mặt trống để tiếng trống vang, không miễn được việc bọc da. | Gương Hán-Việt | \"mân\" — ít dùng; 鞔鼓 (mân cổ — bọc da mặt trống) | Mở khoá kiến thức | Biết 鞔 mở khoá: 鞔鼓 (mán gǔ — bọc da mặt trống), các thuật ngữ chế tác nhạc cụ da.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 鞔 là chữ hình thanh: 革 (biểu nghĩa: da thuộc) + 免 (biểu âm). Tiểu triện ghi nhận hình dạng này. Nghĩa gốc liên quan đến việc bọc da lên mặt trống hoặc phủ da lên đồ vật. Chữ ít dùng trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "căng da", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 免", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革免", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "免", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞔", "Unihan_Traditional (Chữ Phồn thể)": "鞔", "Pinyin_Xie": "mán", "Âm Hán Việt_Xie": "man", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Dùng làm động từ chỉ hành động căng da lên mặt trống hoặc làm giày. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缡', '{"9000": "5831.0", "Chữ Trung Quốc": "缡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 糸 | mịch | biểu nghĩa | tơ, sợi | 离 | ly | biểu âm | lìa xa | 缡 = 糸 (Mịch, biểu nghĩa: tơ, sợi) + 离 (Ly, biểu âm); chữ hình thanh. Bộ 糸 chỉ liên quan đến vải, thắt lưng; 离 (lí) cho âm. Nghĩa gốc: dải lụa (thắt lưng lụa của người phụ nữ cổ đại), đặc biệt dùng trong hôn lễ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ly\": 缡 = sợi tơ 糸 mang âm ly — dải lụa buộc quanh eo cô dâu trong hôn lễ, tượng trưng cho sự kết đôi. | Gương Hán-Việt | \"ly\" — ít phổ biến; 結縭 (kết ly — lấy chồng) trong văn ngôn | Mở khoá kiến thức | Biết 缡 mở khoá: 結縭 (jiélí — lấy chồng, kết hôn), 帨縭 (thuật ngữ hôn lễ cổ).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích hình thể chi tiết cho 缡. Dựa trên cấu trúc và ngữ cảnh: 糸 (sợi tơ) + 离 (biểu âm, lí). Nghĩa gốc là thắt lưng lụa của cô dâu — dùng trong 結縭 (kết ly — lấy chồng, nghĩa đen: thắt thắt lưng lụa). Chữ ít dùng độc lập, chủ yếu trong thành ngữ hôn lễ cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây lưng, khăn giắt; cái khăn tân nhân (khăn đỏ phủ kín mặt khi con gái về nhà chồng); buộc; lưới đánh cá", "Hạng Tần Suất (Jun Da)": "5831.0", "Tần Suất % (Jun Da)": "99.9758506307", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 离", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟离", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "离", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缡", "Unihan_Traditional (Chữ Phồn thể)": "縭", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "li", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loại khăn cưới của cô dâu thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铯', '{"9000": "5832.0", "Chữ Trung Quốc": "铯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 钅 | kim | biểu nghĩa | kim loại | 色 | sắc | biểu âm | màu sắc | 铯 = 钅 (Kim, biểu nghĩa: kim loại) + 色 (Sắc, biểu âm); chữ hình thanh. Cấu trúc đặt tên nguyên tố hiện đại: bộ 钅 chỉ kim loại, 色 (sè) cho âm. Là tên tiếng Trung của nguyên tố caesium (Cs, số nguyên tử 55).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sắc\": 铯 = kim loại 钅 + màu 色 — caesium tên từ màu xanh xám (caesius), bộ sắc màu nhắc đúng nguồn gốc tên gọi. | Gương Hán-Việt | \"sắc\" — dùng chủ yếu trong hoá học: 铯 (caesium, Cs) | Mở khoá kiến thức | Biết 铯 mở khoá: tên các nguyên tố kim loại kiềm trong tiếng Trung, 铯原子钟 (đồng hồ nguyên tử caesium).", "Tự nguyên_Xie": "铯 là chữ hiện đại, tạo ra để phiên dịch caesium (Cs, số nguyên tử 55). Không có nguồn Wiktionary về lịch sử hình thể cổ. Theo mô hình đặt tên nguyên tố: 钅 (kim loại) + 色 (biểu âm, âm sè). Caesium được phát hiện năm 1860 bởi Bunsen và Kirchhoff qua phổ màu xanh — tên tiếng Latin caesius nghĩa là xanh xám. Chữ tạo muộn, chưa có nguồn học thuật về cổ hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố cesi, Cs", "Hạng Tần Suất (Jun Da)": "5832.0", "Tần Suất % (Jun Da)": "99.9758868056", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 色", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅色", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "色", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铯", "Unihan_Traditional (Chữ Phồn thể)": "銫", "Pinyin_Xie": "sè", "Âm Hán Việt_Xie": "sắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chuyên ngành hóa học để chỉ nguyên tố kim loại Cesi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲚', '{"9000": "5833.0", "Chữ Trung Quốc": "鲚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 14 | nét | 鱼 | ngư | biểu nghĩa | cá | 齐 | tề | biểu âm | đều nhau, chỉnh tề | 鲚 = 鱼 (Ngư, biểu nghĩa: cá) + 齐 (Tề, biểu âm); chữ hình thanh. Bộ 鱼 chỉ loài cá; 齐 (qí/jì) cho âm. Giản thể của 鱭 — chỉ loài cá đao dao (cá lông gà, Coilia ectenes).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tề\": 鲚 = cá 鱼 mang âm 齐 (Tề) — đàn cá dao dao bơi đều tề, gọn gàng như đội quân chỉnh tề. | Gương Hán-Việt | \"tề\" — ít phổ biến; 鲚鱼 (tề ngư — cá dao dao) trong ẩm thực | Mở khoá kiến thức | Biết 鲚 mở khoá: 刀鲚 (dāo jì — cá dao), 凤尾鱼 (fèngwěi yú — cá lông gà/cá phượng vĩ).", "Tự nguyên_Xie": "Theo Wiktionary, 鲚 là dạng giản thể của 鱭, được tạo bằng cách thay 魚 → 鱼 và 齊 → 齐. Chỉ loài cá 鳀科 (Engraulidae) hay 鲚科 — cá dao dao (凤尾鱼) nổi tiếng ở sông Trường Giang. Không có nguồn Wiktionary về lịch sử hình thể cổ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con cá đao", "Hạng Tần Suất (Jun Da)": "5833.0", "Tần Suất % (Jun Da)": "99.9759229806", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 齐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼齐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "齐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲚", "Unihan_Traditional (Chữ Phồn thể)": "鱭", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "tễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loài cá xương nhỏ ở vùng nước ngọt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘬', '{"9000": "5834.0", "Chữ Trung Quốc": "嘬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 15 | nét | 嘬 | chối | tượng hình | mút, bú; hoặc cắn nuốt | 嘬 có hai cách đọc: (1) chuài — cắn, ăn, nuốt; (2) zuō — mút, bú. Không có dữ liệu phân tích lục thư từ nguồn anchor. Bộ 口 (miệng) ẩn trong 嘬 gợi ý hành động miệng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chối\": 嘬 là động tác miệng dứt khoát — hoặc cắn ngập răng (chuài) hoặc mút chặt (zuō), chối từ không ngừng. | Gương Hán-Việt | \"chối\" — rất ít dùng trong Hán-Việt; 嘬嘴 (zuōzuǐ — chu miệng mút) | Mở khoá kiến thức | Biết 嘬 mở khoá: 嘬嘴 (zuō zuǐ — chu miệng), 嘬炙 (chuài zhì — ăn thịt nướng ngấu nghiến).", "Tự nguyên_Xie": "Theo Wiktionary, 嘬 có hai cách đọc và nghĩa: (1) chuài — cắn, ăn, nuốt mạnh; (2) zuō — mút, bú (như trẻ bú mẹ hoặc mút kẹo). Không có nguồn phân tích hình thể chi tiết. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cắn, khoét", "Hạng Tần Suất (Jun Da)": "5834.0", "Tần Suất % (Jun Da)": "99.9759948137", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 最", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口最", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "最", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嘬", "Unihan_Traditional (Chữ Phồn thể)": "嘬", "Pinyin_Xie": "chuài", "Âm Hán Việt_Xie": "toát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước danh từ chỉ đồ ăn hoặc bộ phận cơ thể để biểu thị hành động mút hoặc bú. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('庹', '{"9000": "5835.0", "Chữ Trung Quốc": "庹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 11 | nét | 庹 | thác | tượng hình | đơn vị đo chiều dài bằng hai tay giang rộng | 庹 là chữ chuyên dụng dùng làm đơn vị đo dân gian. Không có dữ liệu phân tích lục thư từ nguồn anchor. Bộ 广 (mái, rộng) có thể gợi ý không gian rộng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thác\": 庹 — một thác tay bằng hai tay giang rộng, đơn vị đo dân gian xưa, nay còn dùng ở nông thôn Trung Quốc. | Gương Hán-Việt | \"thác\" — rất ít dùng trong Hán-Việt; 庹 dùng riêng trong đo lường dân gian | Mở khoá kiến thức | Biết 庹 mở khoá: đơn vị đo dân gian Trung Quốc, ngữ cảnh văn hoá nông thôn.", "Tự nguyên_Xie": "Wiktionary không cung cấp thông tin nguồn gốc hình thể cho 庹. Đây là đơn vị đo chiều dài dân gian Trung Quốc: một 庹 bằng chiều dài của hai tay một người giang rộng ra (khoảng 1.5–1.67 mét). Chủ yếu dùng trong phương ngữ và đời sống nông thôn. Chữ tạo muộn, chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sải tay; họ Thoả", "Hạng Tần Suất (Jun Da)": "5835.0", "Tần Suất % (Jun Da)": "99.9760304719", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 尺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴尺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "庹", "Unihan_Traditional (Chữ Phồn thể)": "庹", "Pinyin_Xie": "tuǒ", "Âm Hán Việt_Xie": "thoả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm lượng từ để đo chiều dài bằng sải tay hoặc làm động từ chỉ hành động đo. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('渖', '{"9000": "5836.0", "Chữ Trung Quốc": "渖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 水 | thủy | biểu nghĩa | nước | 審 | thẩm | biểu âm | xét xử, thẩm tra | 渖 = 水 (Thủy, biểu nghĩa: nước) + 審 (Thẩm, biểu âm); chữ hình thanh. Bộ 水 chỉ liên quan đến chất lỏng; 審 (shěn) cho âm. Nghĩa gốc: chất lỏng, nước rau/thịt; nay thường dùng làm tên tắt của 瀋陽 (Thẩm Dương).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thẩm\": 渖 = nước 水 + âm thẩm 審 — nước ép thẩm thấu ra từ thức ăn; hoặc tên Thẩm Dương — thành phố lớn vùng Đông Bắc Trung Quốc. | Gương Hán-Việt | \"thẩm\" trong 渖阳 (Thẩm Dương — tên thành phố) | Mở khoá kiến thức | Biết 渖 mở khoá: 渖阳 (Shěnyáng — Thẩm Dương), 墨渖 (mặc thẩm — mực nho).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 渖 (dạng giản thể của 瀋) là chữ hình thanh: 水 (biểu nghĩa: nước) + 審 (biểu âm, shěn). Nghĩa gốc cổ: chất lỏng, nước ép. Ngày nay chủ yếu dùng trong 渖阳 — tên gọi tắt của 瀋陽 (Thẩm Dương), thủ phủ tỉnh Liêu Ninh. Tiểu triện ghi nhận hình dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước ép ra; nước", "Hạng Tần Suất (Jun Da)": "5836.0", "Tần Suất % (Jun Da)": "99.9760661301", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 审", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵审", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "审", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "渖", "Unihan_Traditional (Chữ Phồn thể)": "渖", "Pinyin_Xie": "shěn", "Âm Hán Việt_Xie": "thẩm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong tên riêng như Thẩm Dương hoặc chỉ chất lỏng, nước ép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('湔', '{"9000": "5837.0", "Chữ Trung Quốc": "湔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 氵 | thủy | biểu nghĩa | nước | 前 | tiền | biểu âm | phía trước | 湔 = 氵 (Thủy, biểu nghĩa: nước) + 前 (Tiền, biểu âm); chữ hình thanh. Bộ 氵 chỉ liên quan đến nước; 前 (qián) cho âm gần jiān. Nghĩa: rửa sạch, thanh tẩy; cũng là tên sông 湔江 ở Tứ Xuyên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiên\": 湔 = nước 氵 mang âm 前 (tiền) — dùng nước rửa sạch mọi vết nhơ trước khi bước tiếp. | Gương Hán-Việt | \"tiên\" — ít phổ biến; 湔雪 (tiên tuyết — rửa nhục) trong văn ngôn | Mở khoá kiến thức | Biết 湔 mở khoá: 湔雪 (jiānxuě — rửa nhục), 湔洗 (jiānxǐ — thanh tẩy), 湔江 (Jiān jiāng — sông Tiên).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | Wiktionary ghi nhận 湔 chủ yếu qua nghĩa và hợp thể. Cấu trúc hình thanh: 氵 (nước, biểu nghĩa) + phần cho âm jiān. Nghĩa: rửa sạch, thanh tẩy (dùng trong văn ngôn). Từ 湔雪 nghĩa là rửa nhục. Cũng là tên sông 湔江 ở tỉnh Tứ Xuyên. Giáp cốt văn, Tiểu triện và Lục thư thông đều ghi nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Tiên; gột rửa", "Hạng Tần Suất (Jun Da)": "5837.0", "Tần Suất % (Jun Da)": "99.9761017882", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 前", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵前", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "前", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "湔", "Unihan_Traditional (Chữ Phồn thể)": "湔", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "tiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ trong văn viết để chỉ việc tẩy rửa vết nhơ hoặc oan khuất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('玎', '{"9000": "5838.0", "Chữ Trung Quốc": "玎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 6 | nét | 王 | vương | biểu nghĩa | ngọc (bộ ngọc viết gần giống 王) | 丁 | đinh | biểu âm | đinh, số thứ tư trong thiên can | 玎 = 王/玉 (Vương/Ngọc, biểu nghĩa: ngọc) + 丁 (Đinh, biểu âm); chữ hình thanh. Bộ 王 ở đây thực ra là bộ 玉 (ngọc) viết rút gọn; 丁 (dīng) cho âm. Nghĩa: tiếng lanh canh của ngọc chạm nhau.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đinh\": 玎 = ngọc 玉 + đinh 丁 — tiếng ngọc leng keng như đinh rơi trên đá, lanh canh trong trẻo. | Gương Hán-Việt | \"đinh\" — ít phổ biến; 玲玎 (linh đinh — tiếng ngọc lanh canh) | Mở khoá kiến thức | Biết 玎 mở khoá: 玲玎 (língdīng — tiếng ngọc lanh canh), 玎玲 (dīnglíng — từ tượng thanh ngọc).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 玎 chỉ âm thanh lanh canh, leng keng của hai mảnh ngọc chạm nhẹ vào nhau. Cấu trúc hình thanh: bộ ngọc 玉 (biểu nghĩa) + 丁 (biểu âm, dīng). Tiểu triện ghi nhận hình dạng này. Xuất hiện trong từ ghép 玲玎 (âm thanh ngọc). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đinh đang 玎璫,玎珰)", "Hạng Tần Suất (Jun Da)": "5838.0", "Tần Suất % (Jun Da)": "99.9761374464", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 丁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王丁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "玎", "Unihan_Traditional (Chữ Phồn thể)": "玎", "Pinyin_Xie": "dīng", "Âm Hán Việt_Xie": "đinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Danh từ | 名词 | Thường dùng trong từ ghép tượng thanh để mô tả âm thanh trong trẻo của ngọc hay kim loại va vào nhau. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锜', '{"9000": "5839.0", "Chữ Trung Quốc": "锜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 钅 | kim | biểu nghĩa | kim loại | 奇 | kỳ | biểu âm | kỳ lạ | 锜 = 钅 (Kim, biểu nghĩa: kim loại) + 奇 (Kỳ, biểu âm); chữ hình thanh. Giản thể của 錡. Bộ 钅 chỉ dụng cụ kim loại; 奇 (qí) cho âm. Nghĩa: một loại bút (bút khắc) hoặc đục nhỏ bằng sắt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": 锜 = kim loại 钅 + kỳ 奇 — một chiếc đục kỳ lạ, nhỏ nhắn, dùng để khắc chữ hoặc đục đá. | Gương Hán-Việt | \"kỳ\" — ít phổ biến; 锜 dùng trong mô tả công cụ thủ công cổ đại | Mở khoá kiến thức | Biết 锜 mở khoá: các dụng cụ kim loại cổ đại trong văn ngôn Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 锜 là dạng giản thể của 錡, tạo bằng cách thay 釒 → 钅. Chỉ một loại dụng cụ kim loại: bút khắc hoặc đục nhỏ. Tiểu triện ghi nhận hình dạng 錡. Chữ ít dùng trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái nồi (đáy có ba chân); cái đục", "Hạng Tần Suất (Jun Da)": "5839.0", "Tần Suất % (Jun Da)": "99.9761731046", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 奇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅奇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锜", "Unihan_Traditional (Chữ Phồn thể)": "錡", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ các loại dụng cụ nấu nướng cổ hoặc công cụ đục đẽo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锊', '{"9000": "5840.0", "Chữ Trung Quốc": "锊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 钅 | kim | biểu nghĩa | kim loại | 寽 | biểu âm | thành phần âm cổ | 锊 = 钅 (Kim, biểu nghĩa: kim loại) + 寽 (biểu âm); chữ hình thanh. Bộ 钅 chỉ kim loại hoặc đơn vị cân đo; phần còn lại cho âm lüè. Nghĩa: đơn vị trọng lượng cổ của Trung Quốc (6 兩, khoảng 6 lạng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lược\": 锊 = kim loại 钅 — đơn vị cân kim loại cổ, một lược bằng 6 lạng, dùng để cân vàng bạc. | Gương Hán-Việt | \"lược\" — ít phổ biến; 锊 là đơn vị đo lường trong cổ văn | Mở khoá kiến thức | Biết 锊 mở khoá: đơn vị đo lường cổ đại Trung Hoa, ngữ cảnh lịch sử thương mại.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 锊 là chữ hình thanh với nghĩa là đơn vị trọng lượng cổ — một 锊 bằng khoảng 6 兩 (lạng). Kim văn, Tiểu triện và Lục thư thông đều ghi nhận hình dạng này. Chữ ít dùng trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(đơn vị đo khối lượng, bằng 16 thù)", "Hạng Tần Suất (Jun Da)": "5840.0", "Tần Suất % (Jun Da)": "99.9762087628", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 寽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅寽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锊", "Unihan_Traditional (Chữ Phồn thể)": "鋝", "Pinyin_Xie": "kim", "Âm Hán Việt_Xie": "luyệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Dùng làm lượng từ chỉ trọng lượng trong các tài liệu lịch sử và văn học cổ đại. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舾', '{"9000": "5841.0", "Chữ Trung Quốc": "舾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 12 | nét | 舟 | chu | biểu nghĩa | thuyền | 西 | tây | biểu âm | phía tây | 舾 = 舟 (Chu, biểu nghĩa: thuyền) + 西 (Tây, biểu âm); chữ hình thanh. Bộ 舟 chỉ liên quan đến tàu thuyền; 西 (xī) cho âm. Nghĩa: thiết bị, trang bị trên tàu chiến hoặc tàu biển (Quảng Đông).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tê\": 舾 = thuyền 舟 + hướng tây 西 — thiết bị tàu biển, mọi đồ dùng trên con tàu hướng về phía tây. | Gương Hán-Việt | \"tê\" — rất ít dùng trong Hán-Việt; 舾装 (tê trang — trang bị tàu) | Mở khoá kiến thức | Biết 舾 mở khoá: 舾装 (xīzhuāng — ship outfitting, trang bị tàu), ngành đóng tàu.", "Tự nguyên_Xie": "Wiktionary không cung cấp thông tin nguồn gốc hình thể cho 舾. Là chữ chuyên dùng trong Quảng Đông, chỉ trang thiết bị trên tàu (ship outfitting). Chữ tạo muộn, chưa có nguồn học thuật. Cấu trúc suy luận: 舟 (biểu nghĩa: thuyền) + 西 (biểu âm). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thiết bị trên tàu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 西", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟西", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "西", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "舾", "Unihan_Traditional (Chữ Phồn thể)": "舾", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "tê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường kết hợp với các từ khác để chỉ việc lắp đặt trang thiết bị cho tàu thủy trước khi hạ thủy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籼', '{"9000": "5842.0", "Chữ Trung Quốc": "籼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 9 | nét | 米 | mễ | biểu nghĩa | gạo | 山 | sơn | biểu âm | núi | 籼 = 米 (Mễ, biểu nghĩa: gạo) + 山 (Sơn, biểu âm); chữ hình thanh. Bộ 米 chỉ loại gạo; 山 (shān) cho âm gần xiān. Nghĩa: gạo tẻ hạt dài (non-glutinous long grain rice), phân biệt với gạo nếp 糯.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiên\": 籼 = gạo 米 + sơn 山 — gạo tẻ hạt dài từ vùng đồi núi nhiệt đới phương Nam, tiên (xiān) mang âm. | Gương Hán-Việt | \"tiên\" — ít phổ biến; 籼稻 (tiên đạo — lúa tẻ hạt dài) | Mở khoá kiến thức | Biết 籼 mở khoá: 籼稻 (xiāndào — lúa Indica), 籼米 (xiānmǐ — gạo tẻ hạt dài), phân biệt các loại lúa trong nông học.", "Tự nguyên_Xie": "Wiktionary ghi nhận 籼 là chữ hình thanh chỉ loại gạo tẻ hạt dài. Không có phân tích hình thể cổ chi tiết. Cấu trúc: 米 (gạo) + phần cho âm xiān. Đây là loại gạo Indica (indica rice) — phổ biến ở Nam Á và Nam Trung Hoa. Phân biệt với 粳 (jīng — gạo tẻ hạt tròn) và 糯 (nuò — gạo nếp). Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lúa ba trăng ta (một thứ lúa chín sớm, không có nhựa dính)", "Hạng Tần Suất (Jun Da)": "5842.0", "Tần Suất % (Jun Da)": "99.9762800791", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 山", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米山", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "山", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "籼", "Unihan_Traditional (Chữ Phồn thể)": "籼", "Pinyin_Xie": "xiān", "Âm Hán Việt_Xie": "tiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để phân loại các giống lúa hoặc gạo không có độ dính cao. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阊', '{"9000": "5843.0", "Chữ Trung Quốc": "阊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 11 | nét | 门 | môn | biểu nghĩa | cửa, cổng | 昌 | xương | biểu âm | hưng thịnh, rực sáng | 阊 = 门 (Môn, biểu nghĩa: cửa, cổng) + 昌 (Xương, biểu âm); chữ hình thanh. Bộ 门 chỉ cổng, cửa; 昌 (chāng) cho âm. Nghĩa: cổng trời, cổng thiên đình; cổng chính của cung điện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xương\": 阊 = cổng 门 + xương thịnh 昌 — cổng trời xương vượng, nơi gió thiên đình thổi qua 閶闔. | Gương Hán-Việt | \"xương\" trong 閶闔 (xương hạp — cổng trời thiên đình) | Mở khoá kiến thức | Biết 阊 mở khoá: 阊阖 (chānghé — cổng trời), 阊门 (Chāng mén — cổng thành Tô Châu), 阊阖风 (gió cổng trời trong thơ cổ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 阊 (giản thể của 閶) chủ yếu dùng trong 閶闔 (chānghé) — cổng trời, cổng thiên đình trong thần thoại và văn học cổ Trung Hoa. Tiểu triện ghi nhận hình dạng này. Cũng là tên cổng thành 閶門 (Chāng mén) ở Tô Châu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cửa trời (cửa chính trong cung)", "Hạng Tần Suất (Jun Da)": "5843.0", "Tần Suất % (Jun Da)": "99.9763157373", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 昌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门昌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阊", "Unihan_Traditional (Chữ Phồn thể)": "閶", "Pinyin_Xie": "chāng", "Âm Hán Việt_Xie": "xương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường xuất hiện trong thơ văn cổ làm danh từ chỉ lối vào cung điện hoặc cổng trời. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祕', '{"9000": "5844.0", "Chữ Trung Quốc": "祕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 9 | nét | 示 | thị | biểu nghĩa | bàn thờ, lễ nghi | 必 | tất | biểu âm | nhất định, tất yếu | 祕 = 示 (Thị, biểu nghĩa: bàn thờ/lễ nghi) + 必 (Tất, biểu âm); chữ hình thanh. Bộ 示 chỉ liên quan đến nghi lễ, thần linh; 必 (bì) cho âm gần mì. Nghĩa: nghi lễ bí ẩn, huyền bí; bí mật — những gì chỉ được biết trong tế lễ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\": 祕 = bàn thờ 示 + tất 必 — điều tất yếu giữ kín trên bàn thờ, chỉ thầy tế mới biết — đó là bí mật. | Gương Hán-Việt | \"bí\" trong 祕密 (bí mật), 神祕 (thần bí), 祕書 (bí thư) | Mở khoá kiến thức | Biết 祕 mở khoá: 秘密 (mìmì — bí mật), 神秘 (shénmì — thần bí), 秘书 (mìshū — thư ký, bí thư), 奥秘 (àomì — bí ẩn).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 祕 là chữ hình thanh: 示 (biểu nghĩa: bàn thờ, nghi lễ bí mật) + 必 (biểu âm). Nghĩa gốc: nghi lễ huyền bí, bí truyền. Từ đó mở rộng sang: bí mật, huyền bí, kỳ lạ. 祕 và 秘 là hai dạng viết của cùng một chữ. Tiểu triện và Lục thư thông ghi nhận hình dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bí mật", "Hạng Tần Suất (Jun Da)": "894.0", "Tần Suất % (Jun Da)": "87.2986999164", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 必", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻必", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "必", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "秘", "Unihan_Traditional (Chữ Phồn thể)": "祕", "Pinyin_Xie": "mì", "Âm Hán Việt_Xie": "bi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ đứng trước danh từ để bổ nghĩa cho tính chất kín đáo, không để lộ ra ngoài. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('猊', '{"9000": "5845.0", "Chữ Trung Quốc": "猊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 11 | nét | 犬 | khuyển | biểu nghĩa | chó, thú vật | 兒 | nhi | biểu âm | trẻ em | 猊 = 犬 (Khuyển, biểu nghĩa: chó/thú vật) + 兒 (Nhi, biểu âm); chữ hình thanh. Bộ 犬 chỉ loài thú; 兒 (ér) cho âm gần ní. Nghĩa: dùng trong 狻猊 (suān ní) — con nghê, một trong chín loài con rồng, hình dạng sư tử.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghê\": 猊 là con nghê — thú thần đầu sư tử, con thứ năm của rồng, thường ngồi xổm trên lư hương, nhả khói trầm. | Gương Hán-Việt | \"nghê\" trong 狻猊 (sư tử — con nghê), hình tượng trên lư hương cổ | Mở khoá kiến thức | Biết 猊 mở khoá: 狻猊 (suānní — con nghê, thú thần), 猊座 (nghê tòa — bệ nghê), hình tượng thú thần trong văn hoá Trung Hoa.", "Tự nguyên_Xie": "Theo Wiktionary, 猊 là chữ hình thanh: 犬 (biểu nghĩa: thú vật) + 兒 (biểu âm). Chữ này chủ yếu dùng trong từ ghép 狻猊 (suān ní) — tên một trong chín loài con của rồng, có hình dạng giống sư tử, thường được đúc trên các đồ tế khí, chân hương. Cũng dùng trong 唐猊 (áo giáp đẹp). Không có ảnh etymology images. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một mình", "Hạng Tần Suất (Jun Da)": "5845.0", "Tần Suất % (Jun Da)": "99.9763870536", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 兒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭兒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "猊", "Unihan_Traditional (Chữ Phồn thể)": "猊", "Pinyin_Xie": "ní", "Âm Hán Việt_Xie": "nghê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ loài thú thần thoại hoặc hình tượng sư tử trong nghệ thuật điêu khắc cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('燹', '{"9000": "5846.0", "Chữ Trung Quốc": "燹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 18 | nét | 豩 | biểu nghĩa | đàn lợn (豩 = 两豕) | 火 | hoả | biểu nghĩa | lửa | 燹 là chữ hội ý: 豩 (đàn lợn chạy trốn) + 火 (Hoả, lửa). Đây là hội ý mô tả cảnh đàn lợn bỏ chạy khỏi đám lửa. Kim văn còn thêm tay cầm gậy (攴), ngụ ý lửa được đốt có chủ đích để xua đuổi lợn. Nghĩa: lửa hoang vu, đám cháy lớn (đặc biệt trong chiến tranh).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiển\": 燹 = đàn lợn + lửa 火 — lợn hoảng loạn chạy trốn lửa — hình ảnh loạn lạc chiến tranh, lửa 兵燹 bùng cháy khắp nơi. | Gương Hán-Việt | \"tiển\" trong 兵燹 (binh tiển — lửa chiến tranh) | Mở khoá kiến thức | Biết 燹 mở khoá: 兵燹 (bīngxiǎn — lửa chiến tranh, cảnh tàn phá), 烽燹 (fēngxiǎn — lửa hiệu chiến tranh).", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 燹 là chữ hội ý: 豩 (đàn lợn) + 火 (lửa) — mô tả đàn lợn bỏ chạy tán loạn trước đám lửa. Kim văn còn thêm 攴 (tay cầm gậy), cho thấy lửa được đốt có chủ đích. Đại triện có thêm thành phần gần 爾. Nghĩa chính: lửa chiến tranh, đám cháy hoang dã. Thường gặp trong 兵燹 (bingxiǎn — lửa chiến tranh). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lửa lan ra", "Hạng Tần Suất (Jun Da)": "5846.0", "Tần Suất % (Jun Da)": "99.9764227118", "GavinGrover_Once (Chiết tự trực tiếp)": "豩 + 火", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱豩火", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "燹", "Unihan_Traditional (Chữ Phồn thể)": "燹", "Pinyin_Xie": "xiǎn", "Âm Hán Việt_Xie": "tiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn viết cổ để chỉ tai họa do chiến tranh gây ra. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葑', '{"9000": "5847.0", "Chữ Trung Quốc": "葑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 封 | phong | biểu âm | phong, đóng kín | 葑 = 艹 (Thảo, biểu nghĩa: cỏ/thực vật) + 封 (Phong, biểu âm); chữ hình thanh. Bộ 艹 chỉ loài thực vật; 封 (fēng) cho âm. Nghĩa: củ cải (dạng cổ, nay đã lỗi thời); cũng dùng cho phần gốc héo của cải.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phong\": 葑 = cỏ 艹 + phong 封 — cây củ cải đóng kín rễ trong đất, âm phong gọi tên loài rau cổ trong Kinh Thi. | Gương Hán-Việt | \"phong\" — ít phổ biến; 葑菲 (phong phi — củ cải và rau, trong Kinh Thi) | Mở khoá kiến thức | Biết 葑 mở khoá: 葑菲 (fēngfěi — củ cải và rau cải trong Kinh Thi), điển cố 采葑采菲.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi nhận 葑 là tên cổ của củ cải (蕪菁, turnip). Chữ ít dùng trong tiếng Trung hiện đại. Cấu trúc hình thanh: 艹 (thực vật) + 封 (biểu âm). Tiểu triện và Lục thư thông ghi nhận hình dạng này. Xuất hiện trong Kinh Thi (詩經): 采葑采菲 — hái củ cải hái rau. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rau phong; nấm", "Hạng Tần Suất (Jun Da)": "5847.0", "Tần Suất % (Jun Da)": "99.9764578532", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 封", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹封", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "封", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葑", "Unihan_Traditional (Chữ Phồn thể)": "葑", "Pinyin_Xie": "fēng", "Âm Hán Việt_Xie": "phong, phúng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại rau cải hoặc củ cải thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓼', '{"9000": "5848.0", "Chữ Trung Quốc": "蓼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 翏 | liêu | biểu âm | âm liêu, tiếng gió thổi | 蓼 = 艹 (Thảo, biểu nghĩa: cỏ/thực vật) + 翏 (Liêu, biểu âm); chữ hình thanh. Bộ 艹 chỉ loài thực vật; 翏 (liào/liū) cho âm gần liǎo. Nghĩa: rau liễu/cây rau đắng (smartweed/polygonum) — loài cây cỏ có vị đắng, dùng trong y học cổ và ẩm thực.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêu\": 蓼 = cỏ 艹 + liêu 翏 — cây rau đắng cay liêu xiêu, ví cho thân phận gian khổ trong Kinh Thi. | Gương Hán-Việt | \"liêu\" trong 蓼蓼 (liêu liêu — cao to, cô đơn), 甘蓼 (cam liêu — dùng trong y học) | Mở khoá kiến thức | Biết 蓼 mở khoá: 蓼科 (liǎokē — họ Polygonaceae), 水蓼 (shuǐliǎo — cây rau đắng nước), 蓼蓼者莪 (Kinh Thi — cha mẹ nuôi dưỡng vất vả).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 蓼 là chữ hình thanh: 艸/艹 (biểu nghĩa: cỏ) + 翏 (biểu âm). Kim văn, Tiểu triện và Lục thư thông đều ghi nhận cấu trúc này. Nghĩa: cây rau đắng (Polygonum), loài thực vật có vị đắng cay. Xuất hiện trong Kinh Thi và văn cổ Trung Hoa như biểu tượng của vị đắng, khổ cực. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đa giác", "Hạng Tần Suất (Jun Da)": "5848.0", "Tần Suất % (Jun Da)": "99.9764929946", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 翏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹翏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓼", "Unihan_Traditional (Chữ Phồn thể)": "蓼", "Pinyin_Xie": "liǎo", "Âm Hán Việt_Xie": "liễu, lục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loài cây thân thảo mọc ở nơi ẩm ướt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('幛', '{"9000": "5849.0", "Chữ Trung Quốc": "幛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 14 | nét | 巾 | can | biểu nghĩa | vải, khăn | 章 | chương | biểu âm | chương, đoạn văn | 幛 = 巾 (Can, biểu nghĩa: vải, khăn) + 章 (Chương, biểu âm); chữ hình thanh. Đây là 後起字 (chữ tạo muộn). Bộ 巾 chỉ vải vóc; 章 (zhāng) cho âm. Nghĩa: bức trướng (vải màu dài, thêu chữ, treo trong tang lễ hoặc lễ chúc mừng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trướng\": 幛 = vải 巾 + chương 章 — tấm vải có chương (chữ), treo trong lễ tang hoặc mừng thọ — bức trướng. | Gương Hán-Việt | \"trướng\" trong 幛子 (trướng tử — bức trướng), 挽幛 (vãn trướng — trướng tang lễ) | Mở khoá kiến thức | Biết 幛 mở khoá: 挽幛 (wǎnzhàng — trướng viếng), 贺幛 (hèzhàng — trướng chúc mừng), 幛子 (zhàngzi — bức trướng).", "Tự nguyên_Xie": "Theo Wiktionary, 幛 được coi là 後起字 (chữ tạo muộn): 巾 (biểu nghĩa: vải) + 章 (biểu âm). Nghĩa: bức trướng — dải vải dài thêu chữ hoặc họa tiết, dùng trong đám tang (挽幛) hoặc lễ chúc mừng (贺幛). Không có ảnh etymology images. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bức trướng (viết câu đối hay chữ mừng)", "Hạng Tần Suất (Jun Da)": "5849.0", "Tần Suất % (Jun Da)": "99.976528136", "GavinGrover_Once (Chiết tự trực tiếp)": "巾 + 章", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巾章", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "章", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "幛", "Unihan_Traditional (Chữ Phồn thể)": "幛", "Pinyin_Xie": "zhàng", "Âm Hán Việt_Xie": "trướng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ tấm vải lớn có thêu chữ dùng trong dịp hỷ sự hoặc tang lễ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('岣', '{"9000": "5850.0", "Chữ Trung Quốc": "岣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 8 | nét | 岣 | cẩu | tượng hình | tên núi 岣嶁 ở Hồ Nam — một đỉnh của núi Hành Sơn | 岣 là chữ chuyên dụng, chỉ dùng trong 岣嶁 — tên một đỉnh núi thuộc Hành Sơn (衡山) ở tỉnh Hồ Nam. Không có dữ liệu phân tích lục thư từ nguồn anchor.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cẩu\": 岣 gắn với 岣嶁 — đỉnh núi nơi có bia Cẩu Lâu, tấm bia bí ẩn thời Hạ Vũ trị thủy. | Gương Hán-Việt | \"cẩu\" — rất ít dùng; 岣嶁碑 (Cẩu Lâu bi — bia Cẩu Lâu) | Mở khoá kiến thức | Biết 岣 mở khoá: 岣嶁 (gǒulǒu — tên đỉnh núi), 岣嶁碑 (bia bí ẩn của Hạ Vũ).", "Tự nguyên_Xie": "Wiktionary ghi nhận 岣 chỉ dùng trong địa danh 岣嶁 (gǒulǒu) — một đỉnh của Hành Sơn ở Hồ Nam. Tại đây có 岣嶁碑 (bia Cẩu Lâu) — tấm bia đá bí ẩn được cho là ghi lại công tích trị thủy của vua Vũ. Chưa có nguồn học thuật về cấu tạo hình thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên núi)", "Hạng Tần Suất (Jun Da)": "5850.0", "Tần Suất % (Jun Da)": "99.9765632774", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 句", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山句", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岣", "Unihan_Traditional (Chữ Phồn thể)": "岣", "Pinyin_Xie": "gǒu", "Âm Hán Việt_Xie": "cẩu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng, chủ yếu xuất hiện trong địa danh núi Cẩu Lâu ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('浼', '{"9000": "5851.0", "Chữ Trung Quốc": "浼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 氵 | thủy | biểu nghĩa | nước | 免 | miễn | biểu âm | miễn trừ, thoát khỏi | 浼 = 氵 (Thủy, biểu nghĩa: nước) + 免 (Miễn, biểu âm); chữ hình thanh. Bộ 氵 chỉ liên quan đến chất lỏng/ô nhiễm; 免 (miǎn) cho âm gần měi. Nghĩa: nhờ vả, cầu xin; cũng nghĩa là làm ô nhiễm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mỗi\": 浼 = nước 氵 + miễn 免 — nhờ nước chảy qua để miễn trừ — ý là nhờ vả ai đó giúp thoát khỏi rắc rối. | Gương Hán-Việt | \"mỗi\" — rất ít phổ biến; 央浼 (ương mỗi — nhờ vả) | Mở khoá kiến thức | Biết 浼 mở khoá: 央浼 (yāngměi — nhờ vả, cầu xin), 浼浼 (měiměi — nước chảy tràn).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 浼 là chữ hình thanh: 水 (biểu nghĩa: nước) + 免 (biểu âm). Tiểu triện ghi nhận hình dạng này. Nghĩa: (1) nhờ vả, nhờ người làm hộ việc gì (央浼); (2) làm ô nhiễm, bẩn. Chữ ít dùng trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: miễn miễn 浼浼)", "Hạng Tần Suất (Jun Da)": "5851.0", "Tần Suất % (Jun Da)": "99.9765984187", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 免", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵免", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "免", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "浼", "Unihan_Traditional (Chữ Phồn thể)": "浼", "Pinyin_Xie": "měi", "Âm Hán Việt_Xie": "mỗi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ trong văn ngôn với nghĩa nhờ vả hoặc làm ô uế. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瑷', '{"9000": "5852.0", "Chữ Trung Quốc": "瑷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 14 | nét | 𤣩 | ngọc | biểu nghĩa | ngọc (bộ ngọc rút gọn từ 玉) | 愛 | ái | biểu âm | tình yêu | 瑷 = 𤣩/玉 (Ngọc, biểu nghĩa: ngọc) + 愛 (Ái, biểu âm); chữ hình thanh. Bộ 玉 chỉ ngọc quý; 愛 (ài) cho âm. Nghĩa: ngọc đẹp, ngọc quý. Hiện chủ yếu dùng trong địa danh 瑷珲 (Aigun — Ái Hồn).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ái\": 瑷 = ngọc 玉 + ái 愛 — viên ngọc đáng yêu, ngọc đẹp; nhắc đến 璦琿 (Ái Huy) — địa danh bi kịch của Hiệp ước Aigun. | Gương Hán-Việt | \"ái\" trong 璦琿 (ái huy — Aigun, địa danh lịch sử) | Mở khoá kiến thức | Biết 瑷 mở khoá: 璦琿 (Àihuī — Ái Huy/Aigun), 璦琿條約 (Hiệp ước Aigun 1858 — Nga-Trung).", "Tự nguyên_Xie": "Theo Wiktionary, 瑷 là chữ hình thanh: 玉 (biểu nghĩa: ngọc) + 愛 (biểu âm). Nghĩa: ngọc quý, ngọc đẹp (cổ ngữ, nay hầu như không dùng độc lập). Xuất hiện trong 璦琿 (Àihuī — Ái Huy/Aigun) — địa danh lịch sử trên bờ sông Hắc Long Giang, nơi ký 《璦琿條約》 (Hiệp ước Aigun 1858). Không có ảnh etymology images. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc bích tốt", "Hạng Tần Suất (Jun Da)": "5852.0", "Tần Suất % (Jun Da)": "99.9766687015", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 爱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王爱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "瑷", "Unihan_Traditional (Chữ Phồn thể)": "璦", "Pinyin_Xie": "ài", "Âm Hán Việt_Xie": "ái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại ngọc đẹp hoặc dùng trong địa danh cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('敫', '{"9000": "5853.0", "Chữ Trung Quốc": "敫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 攴 | Số nét | 13 | nét | 白 | bạch | biểu nghĩa | trắng, sáng | 放 | phóng | biểu nghĩa | phóng thích, toả ra | 敫 là chữ hội ý: 白 (Bạch, trắng/sáng) + 放 (Phóng, toả ra); chữ hội ý. Theo Thuyết Văn Giải Tự: 白 (trắng) + 放 (thả ra) → ý nghĩa là toả sáng. Có thể là hình thức nguyên gốc của 皦 (jiǎo, sáng rực).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giảo\": 敫 = trắng 白 + phóng 放 — ánh sáng trắng toả ra bốn phía, rực rỡ giảo chiếu. | Gương Hán-Việt | \"giảo\" — rất ít dùng; 敫 là dạng cổ của 皦 (sáng rực) | Mở khoá kiến thức | Biết 敫 mở khoá: 皦 (jiǎo — sáng rực, hình thức hiện đại), ngữ cảnh thơ cổ mô tả ánh sáng.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 敫 là chữ hội ý theo Thuyết Văn Giải Tự: 白 (trắng) + 放 (toả ra) = toả sáng. Có thể là nguyên dạng của 皦 (jiǎo — sáng rực). Tiểu triện ghi nhận hình dạng này. Nghĩa: chiếu sáng, rực sáng (cổ ngữ). Chữ ít dùng độc lập trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quang cảnh lưu động; họ Kiểu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + ⺙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⺙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "敫", "Unihan_Traditional (Chữ Phồn thể)": "敫", "Pinyin_Xie": "jiǎo", "Âm Hán Việt_Xie": "kiểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ chỉ sự rực rỡ hoặc làm danh từ chỉ họ người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钔', '{"9000": "5854.0", "Chữ Trung Quốc": "钔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 8 | nét | 钅 | kim | biểu nghĩa | kim loại | 门 | môn | biểu âm | cổng, cửa | 钔 = 钅 (Kim, biểu nghĩa: kim loại) + 门 (Môn, biểu âm); chữ hình thanh. Cấu trúc tạo tên nguyên tố hiện đại: 钅 (kim loại) + 门 (mén) cho âm. Là tên tiếng Trung của nguyên tố mendelevium (Md, số nguyên tử 101).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"môn\": 钔 = kim loại 钅 + cổng 门 — mendelevium, nguyên tố nhân tạo đặt theo tên Mendeleev — người mở cánh cửa bảng tuần hoàn. | Gương Hán-Việt | \"môn\" — dùng riêng cho nguyên tố mendelevium trong hoá học | Mở khoá kiến thức | Biết 钔 mở khoá: mendelevium (Md, số 101), các nguyên tố actinide nhân tạo.", "Tự nguyên_Xie": "钔 là chữ hiện đại được tạo ra để phiên dịch mendelevium (Md, số nguyên tử 101), được đặt theo tên nhà khoa học Dmitri Mendeleev. Không có nguồn Wiktionary về lịch sử hình thể. Cấu trúc: 钅 (kim loại) + 门 (biểu âm, mén). Chữ tạo muộn, chưa có nguồn học thuật cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố mendelevi, Md", "Hạng Tần Suất (Jun Da)": "5854.0", "Tần Suất % (Jun Da)": "99.9767389843", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 门", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅门", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "门", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钔", "Unihan_Traditional (Chữ Phồn thể)": "鍆", "Pinyin_Xie": "mén", "Âm Hán Việt_Xie": "môn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong hóa học để chỉ nguyên tố Mendelevi có số hiệu 101. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钫', '{"9000": "5855.0", "Chữ Trung Quốc": "钫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 钅 | kim | biểu nghĩa | kim loại | 方 | phương | biểu âm | phương hướng, vuông | 钫 = 钅 (Kim, biểu nghĩa: kim loại) + 方 (Phương, biểu âm); chữ hình thanh. Cấu trúc tên nguyên tố: 钅 (kim loại) + 方 (fāng) cho âm. Là tên tiếng Trung của nguyên tố francium (Fr, số nguyên tử 87). Tuy nhiên 钫 trong cổ văn cũng chỉ một loại bình rượu vuông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phương\": 钫 = kim loại 钅 + phương 方 — xưa là bình vuông bằng đồng; nay là francium — kim loại kiềm có thể thay thế cho mọi phương. | Gương Hán-Việt | \"phương\" — dùng trong hoá học: 钫 (francium) và trong cổ ngữ: 钫 (bình rượu vuông) | Mở khoá kiến thức | Biết 钫 mở khoá: francium (Fr, số 87), bảng tuần hoàn nhóm kim loại kiềm.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 钫 có hai nghĩa: (1) cổ ngữ — loại bình rượu hình vuông bằng đồng; (2) hiện đại — tên nguyên tố francium (Fr, số 87). Cả hai đều có cấu trúc 钅/金 + 方. Tiểu triện ghi nhận hình dạng cổ (bình rượu). Francium được đặt tên theo nước Pháp (France). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố franxi, Fr", "Hạng Tần Suất (Jun Da)": "5855.0", "Tần Suất % (Jun Da)": "99.9767741257", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 方", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅方", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "方", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钫", "Unihan_Traditional (Chữ Phồn thể)": "鈁", "Pinyin_Xie": "fāng", "Âm Hán Việt_Xie": "phương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ nguyên tố hóa học Franxi hoặc một loại bình đựng rượu thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锼', '{"9000": "5856.0", "Chữ Trung Quốc": "锼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 钅 | kim | biểu nghĩa | kim loại | 叟 | tẩu | biểu âm | ông lão | 锼 = 钅 (Kim, biểu nghĩa: kim loại) + 叟 (Tẩu, biểu âm); chữ hình thanh. Bộ 钅 chỉ dụng cụ kim loại; 叟 (sǒu) cho âm gần sōu. Nghĩa: khắc chạm (trên gỗ hoặc kim loại); phương ngữ Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tẩu\": 锼 = kim loại 钅 + ông lão 叟 — ông thợ già 叟 dùng dao khắc 钅 chạm hoa văn, nghề điêu khắc truyền thống. | Gương Hán-Việt | \"tẩu\" — rất ít dùng; 雕鎪 (điêu tẩu — chạm khắc tinh xảo) | Mở khoá kiến thức | Biết 锼 mở khoá: 雕鎪 (diāosōu — chạm khắc), các thuật ngữ điêu khắc thủ công.", "Tự nguyên_Xie": "Theo Wiktionary, 锼 (giản thể của 鎪) là động từ chỉ việc khắc chạm. Chữ ít dùng trong tiếng Trung phổ thông, chủ yếu xuất hiện trong phương ngữ. Wikitext không cung cấp phân tích hình thể chi tiết. Cấu trúc suy luận: 钅 (kim loại, dụng cụ) + 叟 (biểu âm). Chưa có ảnh etymology images. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trổ (khắc gỗ bằng lưỡi cưa nhỏ); sắt rỉ", "Hạng Tần Suất (Jun Da)": "5856.0", "Tần Suất % (Jun Da)": "99.9768092671", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 叟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅叟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锼", "Unihan_Traditional (Chữ Phồn thể)": "鎪", "Pinyin_Xie": "sōu", "Âm Hán Việt_Xie": "sưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động chạm trổ, khắc rỗng trên gỗ hoặc kim loại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锿', '{"9000": "5857.0", "Chữ Trung Quốc": "锿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 钅 | kim | biểu nghĩa | kim loại | 哀 | ai | biểu âm | đau thương, bi ai | 锿 = 钅 (Kim, biểu nghĩa: kim loại) + 哀 (Ai, biểu âm); chữ hình thanh. Cấu trúc tên nguyên tố hiện đại: 钅 (kim loại) + 哀 (āi) cho âm. Là tên tiếng Trung của nguyên tố einsteinium (Es, số nguyên tử 99).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ai\": 锿 = kim loại 钅 + ai 哀 — einsteinium, nguyên tố tìm thấy trong bi thảm bom nguyên tử, mang âm ai buồn. | Gương Hán-Việt | \"ai\" — dùng riêng cho nguyên tố einsteinium trong hoá học | Mở khoá kiến thức | Biết 锿 mở khoá: einsteinium (Es, số 99), các nguyên tố được đặt theo tên nhà khoa học.", "Tự nguyên_Xie": "锿 là chữ hiện đại, tạo ra để phiên dịch einsteinium (Es, số nguyên tử 99) — được đặt tên theo Albert Einstein. Không có nguồn Wiktionary về lịch sử hình thể. Cấu trúc: 钅 (kim loại) + 哀 (biểu âm, āi). Phát hiện năm 1952 trong mảnh vỡ bom nhiệt hạch thử nghiệm. Chữ tạo muộn, chưa có nguồn học thuật cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố ensteni, Es", "Hạng Tần Suất (Jun Da)": "5857.0", "Tần Suất % (Jun Da)": "99.9768444085", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 哀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅哀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "哀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锿", "Unihan_Traditional (Chữ Phồn thể)": "鎄", "Pinyin_Xie": "āi", "Âm Hán Việt_Xie": "ai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nguyên tố hóa học Einsteinium trong bảng tuần hoàn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('癔', '{"9000": "5858.0", "Chữ Trung Quốc": "癔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 18 | nét | 疒 | nạch | biểu nghĩa | bệnh tật | 意 | ý | biểu âm | ý nghĩ, ý thức | 癔 = 疒 (Nạch, biểu nghĩa: bệnh tật) + 意 (Ý, biểu âm); chữ hình thanh. Bộ 疒 chỉ bệnh tật; 意 (yì) cho âm. Nghĩa: hysteria (chứng cuồng loạn, rối loạn phân ly) — căn bệnh tâm thần mà biểu hiện liên quan đến tâm lý/ý thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ý\": 癔 = bệnh 疒 + ý thức 意 — chứng bệnh mà ý thức bị rối loạn, người bệnh mất kiểm soát hành vi như người mất trí. | Gương Hán-Việt | \"ý\" trong 癔症 (ý chứng — hysteria, rối loạn phân ly) | Mở khoá kiến thức | Biết 癔 mở khoá: 癔症 (yìzhèng — hysteria), 癔病 (yìbìng — bệnh cuồng loạn), tâm lý học lâm sàng.", "Tự nguyên_Xie": "Theo Wiktionary, 癔 là chữ hình thanh: 疒 (biểu nghĩa: bệnh) + 意 (biểu âm). Nghĩa: bệnh hysteria, chứng cuồng loạn tâm lý. Trong tiếng Trung hiện đại, 癔症 (yìzhèng) là thuật ngữ y tế chỉ rối loạn phân ly/hysteria. Chữ tạo muộn, không có ảnh etymology images. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh tâm thần; bệnh thần kinh", "Hạng Tần Suất (Jun Da)": "5858.0", "Tần Suất % (Jun Da)": "99.9768795499", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 意", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒意", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "意", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "癔", "Unihan_Traditional (Chữ Phồn thể)": "癔", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường kết hợp với các từ khác để chỉ bệnh hysteria hoặc chứng tâm thần phân liệt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穸', '{"9000": "5859.0", "Chữ Trung Quốc": "穸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 8 | nét | 穴 | huyệt | biểu nghĩa | hang, hố | 夕 | tịch | biểu âm | buổi tối | 穸 = 穴 (Huyệt, biểu nghĩa: hang/hố) + 夕 (Tịch, biểu âm); chữ hình thanh. Bộ 穴 gợi ý không gian trống dưới lòng đất; 夕 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tịch\": hang mộ (穴) trong đêm tối (夕) — huyệt mộ u tịch. | Gương Hán-Việt | tịch trong \"truân tịch\" (窀穸, chỉ huyệt mộ) | Mở khoá kiến thức | Biết 穸 giúp đọc từ cổ văn 窀穸 (truân tịch) chỉ huyệt mộ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 穴 (huyệt, hang hố) biểu nghĩa — chỉ khoang chứa quan tài trong mộ; 夕 (tịch) biểu âm. Tiểu triện đã có dạng này. Nghĩa gốc: phần lõm trong mộ để đặt quan tài. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: truân tịch 窀穸)", "Hạng Tần Suất (Jun Da)": "5859.0", "Tần Suất % (Jun Da)": "99.9769146912", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 夕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴夕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "穸", "Unihan_Traditional (Chữ Phồn thể)": "穸", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "tịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này hầu như chỉ dùng trong từ ghép truân tịch để chỉ phần mộ hoặc việc chôn cất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褊', '{"9000": "5860.0", "Chữ Trung Quốc": "褊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 14 | nét | 衤 | y | biểu nghĩa | quần áo | 扁 | biển | biểu âm | dẹt, phẳng | 褊 = 衤 (Y, biểu nghĩa: quần áo) + 扁 (Biển, biểu âm); chữ hình thanh. Bộ 衤 chỉ nghĩa liên quan đến y phục — áo chật hẹp; 扁 cho âm đọc biǎn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biển\": áo (衤) dẹt (扁) — mặc áo chật, tâm địa hẹp biển. | Gương Hán-Việt | biển trong \"biển kiến\" (褊見, tầm nhìn hẹp) | Mở khoá kiến thức | Biết 褊 giúp đọc cổ văn chỉ tính cách hẹp hòi như 褊躁 (nóng nảy, tầm thường).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 衤 (y, quần áo) biểu nghĩa; 扁 (biển) biểu âm. Nghĩa gốc: quần áo chật, ôm sát. Từ nghĩa áo chật mở rộng sang: hẹp, nhỏ, tầm thường; tính cách nóng nảy, hẹp hòi. Tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhỏ, hẹp; nóng nảy", "Hạng Tần Suất (Jun Da)": "5860.0", "Tần Suất % (Jun Da)": "99.9769498326", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 扁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤扁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "扁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褊", "Unihan_Traditional (Chữ Phồn thể)": "褊", "Pinyin_Xie": "biǎn", "Âm Hán Việt_Xie": "biển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ bổ nghĩa cho danh từ để chỉ sự nhỏ hẹp của trang phục hoặc lòng dạ con người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚍', '{"9000": "5861.0", "Chữ Trung Quốc": "蚍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 10 | nét | 虫 | trùng | biểu nghĩa | sâu bọ | 比 | tỉ | biểu âm | so sánh | 蚍 = 虫 (Trùng, biểu nghĩa: sâu bọ) + 比 (Tỉ, biểu âm); chữ hình thanh. Bộ 虫 chỉ loài côn trùng; 比 cho âm đọc pí. Tiểu triện và lục thư thông ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỉ\": trùng (虫) so sánh (比) với đại thụ — con kiến nhỏ dám lay cây lớn. | Gương Hán-Việt | tỉ trong \"bì phù\" (蚍蜉, con kiến lớn có cánh) | Mở khoá kiến thức | Biết 蚍 giúp hiểu thành ngữ 蚍蜉撼树 — kiến dời núi, sức nhỏ chống mạnh.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 虫 (trùng, sâu bọ) biểu nghĩa; 比 (tỉ) biểu âm. 蚍 dùng trong 蚍蜉 (bì phù) — con kiến lớn. Thành ngữ: 蚍蜉撼树 (bì phù hàn thụ) — kiến lay cây đại thụ, ví sức yếu mà chống mạnh. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kiến càng", "Hạng Tần Suất (Jun Da)": "5861.0", "Tần Suất % (Jun Da)": "99.976984974", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 比", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫比", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "比", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚍", "Unihan_Traditional (Chữ Phồn thể)": "蚍", "Pinyin_Xie": "pí", "Âm Hán Việt_Xie": "tì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường đi liền với chữ phù tạo thành từ ghép chỉ loài kiến lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篦', '{"9000": "5862.0", "Chữ Trung Quốc": "篦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 16 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 𣬉 | biểu âm | phần biểu âm cổ | 篦 = 竹 (Trúc, biểu nghĩa: tre/trúc) + 𣬉 (biểu âm); chữ hình thanh. Bộ 竹 chỉ vật liệu tre — cái lược bí; phần dưới cho âm đọc bì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\": trúc (竹) cắt thành lược bí để chải tóc cho mịn. | Gương Hán-Việt | bí trong \"bí lược\" (篦梳, lược bí chải tóc) | Mở khoá kiến thức | Biết 篦 giúp đọc văn học cổ miêu tả sinh hoạt hằng ngày với lược chải tóc.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 竹 (trúc, tre) biểu nghĩa; 𣬉 biểu âm. Nghĩa gốc: cái lược bí — dụng cụ chải tóc làm bằng tre, răng dày. Tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái lược bí", "Hạng Tần Suất (Jun Da)": "5862.0", "Tần Suất % (Jun Da)": "99.9770201154", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "篦", "Unihan_Traditional (Chữ Phồn thể)": "篦", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ loại lược răng dày hoặc làm động từ chỉ hành động chải tóc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麇', '{"9000": "5863.0", "Chữ Trung Quốc": "麇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 16 | nét | 麇 | quần | tượng hình | con hươu không sừng | 麇 là chữ tượng hình chỉ con hươu không có sừng. Giáp cốt văn và kim văn đã vẽ hình con hươu. Chữ độc lập, không tách được thành hình thanh/hội ý rõ ràng ở dạng hiện tại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quần\": đàn hươu (麇) tụ lại thành quần thể — quần tụ. | Gương Hán-Việt | quần trong nghĩa tụ tập thành đàn (麇集, quần tập) | Mở khoá kiến thức | Biết 麇 giúp đọc cổ văn miêu tả đàn thú tụ tập hoặc con nai không sừng.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Chữ tượng hình gốc chỉ con hươu không sừng. Giáp cốt văn, kim văn, tiểu triện đều ghi nhận dạng vẽ hình con hươu. Nghĩa gốc: loài hươu không có sừng. Nghĩa mở rộng: tụ tập thành đàn. Đọc jūn chỉ con nai, qún khi nghĩa tụ tập. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tụ tập thành đàn", "Hạng Tần Suất (Jun Da)": "5863.0", "Tần Suất % (Jun Da)": "99.9770552568", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 禾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鹿禾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麇", "Unihan_Traditional (Chữ Phồn thể)": "麇", "Pinyin_Xie": "jūn", "Âm Hán Việt_Xie": "quần, quân, khuân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ một loài hươu nhỏ hoặc làm động từ chỉ sự tụ tập đông đúc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('樘', '{"9000": "5864.0", "Chữ Trung Quốc": "樘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 15 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 唐 | đường | biểu âm | triều Đường, trống rỗng | 樘 = 木 (Mộc, biểu nghĩa: gỗ) + 唐 (Đường, biểu âm); chữ hình thanh. Bộ 木 chỉ vật liệu gỗ — khung cửa; 唐 cho âm đọc táng. Tiểu triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đường\": gỗ (木) làm khung đường đi — khung cửa ra vào. | Gương Hán-Việt | đường trong \"đường cửa\" (樘, bộ khung cửa) | Mở khoá kiến thức | Biết 樘 giúp đọc văn bản kỹ thuật xây dựng cổ và hiện đại khi đếm khung cửa.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 木 (mộc, gỗ) biểu nghĩa; 唐 (đường) biểu âm. Nghĩa chính: khung cửa — cả khung và cánh cửa tính là một đơn vị. Trong kiến trúc 一樘门 (nhất đường môn) chỉ một bộ khung cửa. Tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khung cửa", "Hạng Tần Suất (Jun Da)": "5864.0", "Tần Suất % (Jun Da)": "99.9770903982", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 堂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木堂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "堂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "樘", "Unihan_Traditional (Chữ Phồn thể)": "樘", "Pinyin_Xie": "táng", "Âm Hán Việt_Xie": "đường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ khung cửa hoặc làm lượng từ cho các bộ cửa, ô cửa sổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钯', '{"9000": "5865.0", "Chữ Trung Quốc": "钯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 金 | kim | biểu nghĩa | kim loại | 巴 | ba | biểu âm | mong mỏi, dính vào | 钯 = 金 (Kim, biểu nghĩa: kim loại) + 巴 (Ba, biểu âm); chữ hình thanh. Bộ 金 chỉ kim loại; 巴 cho âm đọc bǎ. Nghĩa 1: cái bồ cào. Nghĩa 2: nguyên tố paladi (Pd).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ba\": kim loại (金) cào đất (巴) — cái bồ cào, hoặc nguyên tố paladi. | Gương Hán-Việt | ba trong \"ba paladi\" — nguyên tố kim loại quý | Mở khoá kiến thức | Biết 钯 giúp đọc từ vựng hóa học (paladi) và nông cụ truyền thống (bồ cào).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 金 (kim, kim loại) biểu nghĩa; 巴 (ba) biểu âm. Nghĩa gốc: cái bồ cào bằng kim loại. Nghĩa hiện đại: nguyên tố paladi (Pd, số 46) — phiên âm từ tiếng Anh. Tiểu triện ghi nhận dạng bồ cào. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bồ cào, cái cào cỏ", "Hạng Tần Suất (Jun Da)": "5865.0", "Tần Suất % (Jun Da)": "99.9771255396", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 巴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅巴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钯", "Unihan_Traditional (Chữ Phồn thể)": "鈀", "Pinyin_Xie": "bǎ", "Âm Hán Việt_Xie": "bả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nông cụ cào cỏ hoặc nguyên tố hóa học Palladium. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禇', '{"9000": "5866.0", "Chữ Trung Quốc": "禇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 12 | nét | 禇 | chử | tượng hình | dạng sai của 褚 | 禇 là dạng viết sai của 褚 (chử). Phần trên bị nhầm từ bộ 衤 (y, quần áo) thành bộ 示 (thị, lễ nghi). Không có cấu trúc hội ý hay hình thanh độc lập.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chử\": dạng viết sai của 褚 — 示 thay vì 衤 ở phần trên, dễ nhầm khi viết nhanh. | Gương Hán-Việt | chử — họ Chử trong tên người (dạng sai của 褚) | Mở khoá kiến thức | Nhận ra 禇 là viết sai của 褚 giúp tránh lỗi khi gặp tên người họ Chử.", "Tự nguyên_Xie": "禇 là chữ viết sai của 褚 — phần trên nhầm từ 衤 thành 示. Chữ chuẩn là 褚 (chử): họ tên người, hoặc túi đựng. Không có Wiktionary anchor; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dạng sai của 褚", "Hạng Tần Suất (Jun Da)": "5866.0", "Tần Suất % (Jun Da)": "99.977160681", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 者", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻者", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "者", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禇", "Unihan_Traditional (Chữ Phồn thể)": "禇", "Pinyin_Xie": "zhě", "Âm Hán Việt_Xie": "trử", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng chỉ họ người hoặc biến thể của chữ chỉ túi đựng áo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铒', '{"9000": "5867.0", "Chữ Trung Quốc": "铒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 金 | kim | biểu nghĩa | kim loại | 耳 | nhĩ | biểu âm | tai | 铒 = 金 (Kim, biểu nghĩa: kim loại) + 耳 (Nhĩ, biểu âm); chữ hình thanh. Bộ 金 chỉ nguyên tố kim loại; 耳 cho âm đọc ěr — phiên âm từ erbium.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhĩ\": kim loại (金) có âm như nhĩ (耳) — nguyên tố erbium (Er, số 68). | Gương Hán-Việt | nhĩ trong \"eribi\" (铒, erbium — nguyên tố đất hiếm) | Mở khoá kiến thức | Biết 铒 giúp đọc bảng tuần hoàn và tài liệu hóa học tiếng Trung (nguyên tố số 68).", "Tự nguyên_Xie": "Chữ hình thanh tạo muộn: 金 (kim, kim loại) biểu nghĩa; 耳 (nhĩ) biểu âm — phiên âm từ erbium (Er). Erbium phát hiện năm 1843 từ quặng Ytterby, Thụy Điển. Chữ tạo muộn để phiên âm tên khoa học; chưa có nguồn học thuật ngoài phiên âm. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố eribi, Er", "Hạng Tần Suất (Jun Da)": "5867.0", "Tần Suất % (Jun Da)": "99.9771958224", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 耳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅耳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铒", "Unihan_Traditional (Chữ Phồn thể)": "鉺", "Pinyin_Xie": "ěr", "Âm Hán Việt_Xie": "nhĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nguyên tố hóa học Erbium trong hóa học hiện đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莩', '{"9000": "5868.0", "Chữ Trung Quốc": "莩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 艸 | tháu | biểu nghĩa | cỏ, thực vật | 孚 | phu | biểu âm | tin tưởng, ấp trứng | 莩 = 艸 (Tháu, biểu nghĩa: thực vật) + 孚 (Phu, biểu âm); chữ hình thanh. Bộ 艸 chỉ loài cây; 孚 cho âm đọc fú. Tiểu triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phù\": cỏ (艸) mỏng như vỏ trứng (孚) — màng mỏng bao bọc hạt mầm. | Gương Hán-Việt | phù trong \"phù giáp\" (莩甲, màng vỏ mầm cây) | Mở khoá kiến thức | Biết 莩 giúp đọc văn học cổ về nông nghiệp và thực vật học truyền thống.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 艸 (tháu, thực vật) biểu nghĩa; 孚 (phu) biểu âm. Nghĩa gốc: màng mỏng bao ngoài hạt giống hoặc mầm cây mới nảy; cũng chỉ lau sậy. Tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màng bao ngoài ở các cây mới nảy mầm", "Hạng Tần Suất (Jun Da)": "5868.0", "Tần Suất % (Jun Da)": "99.9772655884", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 孚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹孚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莩", "Unihan_Traditional (Chữ Phồn thể)": "莩", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phu, biễu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ lớp màng mỏng của thực vật, thường dùng trong văn ngôn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嵯', '{"9000": "5869.0", "Chữ Trung Quốc": "嵯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 12 | nét | 山 | sơn | biểu nghĩa | núi | 差 | sai | biểu âm | sai biệt | 嵯 = 山 (Sơn, biểu nghĩa: núi) + 差 (Sai, biểu âm); chữ hình thanh. Bộ 山 chỉ núi non; 差 cho âm đọc cuó. Dùng trong 嵯峨 chỉ núi sừng sững.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ta\": núi (山) chênh lệch cao thấp (差) — đỉnh núi ta nga sừng sững. | Gương Hán-Việt | ta trong \"ta nga\" (嵯峨, núi hiểm trở, sừng sững) | Mở khoá kiến thức | Biết 嵯 giúp đọc thơ cổ tả cảnh thiên nhiên, đặc biệt từ 嵯峨 mô tả núi cao.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 山 (sơn, núi) biểu nghĩa; 差 (sai) biểu âm. Tiểu triện ghi nhận. Nghĩa: núi cao dốc đứng. Chỉ dùng trong 嵯峨 (ta nga) mô tả cảnh núi non hùng vĩ trong thơ cổ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tha nga 嵯峨)", "Hạng Tần Suất (Jun Da)": "5869.0", "Tần Suất % (Jun Da)": "99.977300213", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 差", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山差", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "差", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "嵯", "Unihan_Traditional (Chữ Phồn thể)": "嵯", "Pinyin_Xie": "cuó", "Âm Hán Việt_Xie": "tha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả dáng núi cao ngất, thường kết hợp thành từ ghép ta nga. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逭', '{"9000": "5870.0", "Chữ Trung Quốc": "逭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 11 | nét | 辶 | xước | biểu nghĩa | đi lại, con đường | 官 | quan | biểu âm | quan lại | 逭 = 辶 (Xước, biểu nghĩa: đi lại) + 官 (Quan, biểu âm); chữ hình thanh. Bộ 辶 gợi ý hành động di chuyển — trốn tránh; 官 cho âm đọc huàn. Tiểu triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quán\": đi (辶) khỏi chức quan (官) — trốn tránh trách nhiệm. | Gương Hán-Việt | quán trong \"bất khả đào quán\" (không thể trốn tránh) | Mở khoá kiến thức | Biết 逭 giúp đọc cổ văn và thành ngữ về trách nhiệm không thể né tránh.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 辶 (xước, đi lại) biểu nghĩa; 官 (quan) biểu âm. Tiểu triện ghi nhận. Nghĩa: trốn tránh, thoát khỏi. Nổi tiếng qua câu cổ văn: tự tác nghiệt, bất khả đào/逭 — tự chuốc hoạ vào thân thì không thể thoát. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trốn tránh", "Hạng Tần Suất (Jun Da)": "5870.0", "Tần Suất % (Jun Da)": "99.9773348376", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 官", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶官", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "官", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逭", "Unihan_Traditional (Chữ Phồn thể)": "逭", "Pinyin_Xie": "huàn", "Âm Hán Việt_Xie": "hoán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành vi né tránh trách nhiệm hoặc tai họa trong văn viết. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遄', '{"9000": "5871.0", "Chữ Trung Quốc": "遄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 12 | nét | 辶 | xước | biểu nghĩa | đi lại, di chuyển | 耑 | đoan | biểu âm | đầu mối, ngay thẳng | 遄 = 辶 (Xước, biểu nghĩa: đi lại) + 耑 (Đoan, biểu âm); chữ hình thanh. Bộ 辶 gợi ý chuyển động; 耑 cho âm đọc chuán. Kim văn, đại triện, tiểu triện đều ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đoán\": đi (辶) ngay lập tức như bắt đầu (耑) — di chuyển mau chóng. | Gương Hán-Việt | đoán trong \"遄行\" (đoán hành — đi mau) | Mở khoá kiến thức | Biết 遄 giúp đọc Kinh Thi và cổ văn mô tả hành động nhanh chóng, tức thì.", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Chữ hình thanh: 辶 (xước, đi lại) biểu nghĩa; 耑 (đoan) biểu âm. Kim văn và đại triện ghi nhận. Nghĩa: nhanh chóng, lập tức. Kinh Thi: nhân nhi vô lễ, hồ bất遄tử — người vô lễ sao không chết ngay. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lo lắng, đi đi lại lại", "Hạng Tần Suất (Jun Da)": "5871.0", "Tần Suất % (Jun Da)": "99.9773694622", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 耑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶耑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "遄", "Unihan_Traditional (Chữ Phồn thể)": "遄", "Pinyin_Xie": "chuán", "Âm Hán Việt_Xie": "thuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Tính từ | 形容词 | Chữ này làm phó từ đứng trước động từ để chỉ hành động diễn ra nhanh chóng. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戗', '{"9000": "5872.0", "Chữ Trung Quốc": "戗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戈 | Số nét | 8 | nét | 仓 | thương | biểu âm | kho | 戈 | qua | biểu nghĩa | giáo mác | 戗 là giản thể của 戧 — cấu trúc suy đoán gồm 仓 (thương) + 戈 (qua, giáo). Không có Wiktionary anchor; chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thương\": cây giáo (戈) cắm vào kho (仓) — chống ngược lại, cản trở. | Gương Hán-Việt | thương trong \"thương phong\" (戗风, ngược gió) | Mở khoá kiến thức | Biết 戗 giúp đọc văn bản xây dựng (chống đỡ) và cổ văn về di chuyển ngược chiều.", "Tự nguyên_Xie": "戗 là giản thể của 戧 (thương). Nghĩa: ngược chiều (ngược gió, ngược nước); chống đỡ, chèn vào. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngược; chống lên, đỡ lên", "Hạng Tần Suất (Jun Da)": "5872.0", "Tần Suất % (Jun Da)": "99.9774040868", "GavinGrover_Once (Chiết tự trực tiếp)": "仓 + 戈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰仓戈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "仓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "戈", "Unihan_Simplified (Chữ Giản thể)": "戗", "Unihan_Traditional (Chữ Phồn thể)": "戧", "Pinyin_Xie": "qiāng", "Âm Hán Việt_Xie": "sang, thương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ hành động dùng vật gì đó để chống đỡ hoặc đi ngược chiều. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睃', '{"9000": "5873.0", "Chữ Trung Quốc": "睃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 12 | nét | 目 | mục | biểu nghĩa | mắt | 差 | sai | biểu âm | sai biệt | 睃 = 目 (Mục, biểu nghĩa: mắt) + phần biểu âm; chữ hình thanh suy đoán. Bộ 目 chỉ hành động liên quan đến mắt — liếc nhìn. Không có anchor Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ta\": mắt (目) liếc đi — liếc nhìn lén lút. | Gương Hán-Việt | ta trong \"liếc nhìn\" — 睃 chỉ hành động nhìn nhanh, lén | Mở khoá kiến thức | Biết 睃 giúp đọc văn học miêu tả cử chỉ mắt tinh tế.", "Tự nguyên_Xie": "Không có Wiktionary anchor cho 睃. Từ cấu trúc: 目 (mục, mắt) biểu nghĩa. Nghĩa: liếc nhìn nhanh, nhìn trộm. Chữ ít phổ biến; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "liếc nhìn", "Hạng Tần Suất (Jun Da)": "5873.0", "Tần Suất % (Jun Da)": "99.9774387114", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 夋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目夋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睃", "Unihan_Traditional (Chữ Phồn thể)": "睃", "Pinyin_Xie": "suō", "Âm Hán Việt_Xie": "tuấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động nhìn nghiêng hoặc liếc mắt về một hướng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鮈', '{"9000": "5874.0", "Chữ Trung Quốc": "鮈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 魚 | ngư | biểu nghĩa | cá | 句 | cú | biểu âm | câu, đoạn văn | 鮈 = 魚 (Ngư, biểu nghĩa: cá) + 句 (Cú, biểu âm); chữ hình thanh. Bộ 魚 chỉ loài cá; 句 cho âm đọc jū. Nghĩa: cá đục (gudgeon).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"câu\": cá (魚) nhỏ như câu chữ (句) — cá đục nhỏ bé. | Gương Hán-Việt | câu trong \"ngư câu\" — loài cá đục nhỏ | Mở khoá kiến thức | Biết 鮈 giúp đọc từ điển sinh học cổ về các loài cá nước ngọt.", "Tự nguyên_Xie": "Chữ hình thanh: 魚 (ngư, cá) biểu nghĩa; 句 (cú) biểu âm. Nghĩa: cá đục (gudgeon) — loài cá nước ngọt nhỏ thuộc họ cá chép. Không có ảnh etymology. Dùng trong từ điển sinh học cổ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá đục", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 句", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚句", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鮈", "Unihan_Traditional (Chữ Phồn thể)": "鮈", "Pinyin_Xie": "jū", "Âm Hán Việt_Xie": "câu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cá nhỏ sống ở vùng nước ngọt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瀣', '{"9000": "5875.0", "Chữ Trung Quốc": "瀣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 19 | nét | 氵 | thuỷ | biểu nghĩa | nước | 解 | giải | biểu âm | giải thích, tháo gỡ | 瀣 = 氵 (Thuỷ, biểu nghĩa: nước) + 解 (Giải, biểu âm); chữ hình thanh. Bộ 氵 chỉ chất lỏng, sương khí; 解 cho âm đọc xiè. Dùng trong 沆瀣.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giải\": nước (氵) tan ra (解) thành sương đêm — hơi ẩm mờ mịt. | Gương Hán-Việt | giải trong \"hàng giải\" (沆瀣) và \"沆瀣一气\" (đồng mưu tiểu nhân) | Mở khoá kiến thức | Biết 瀣 giúp hiểu thành ngữ 沆瀣一气 — bọn tiểu nhân cùng hội cùng thuyền.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 氵 (thuỷ, nước) biểu nghĩa; 解 (giải) biểu âm. Tiểu triện và lục thư thông ghi nhận. Nghĩa: hơi sương đêm, khí ẩm. Dùng trong 沆瀣 (hàng giải). Thành ngữ 沆瀣一气 (hàng giải nhất khí) chỉ bọn tiểu nhân đồng mưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hơi sương", "Hạng Tần Suất (Jun Da)": "5875.0", "Tần Suất % (Jun Da)": "99.9775079606", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 韰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵韰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "韰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "瀣", "Unihan_Traditional (Chữ Phồn thể)": "瀣", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "giới", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ làn sương đêm hoặc khí ẩm, thường dùng trong từ ghép giải cấu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('皴', '{"9000": "5876.0", "Chữ Trung Quốc": "皴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皮 | Số nét | 12 | nét | 皮 | bì | biểu nghĩa | da | 夋 | tuấn | biểu âm | dạng âm phù | 皴 = 皮 (Bì, biểu nghĩa: da) + phần trên (biểu âm); chữ hình thanh. Bộ 皮 chỉ da — da nứt nẻ; phần còn lại cho âm đọc cūn. Tiểu triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuấn\": da (皮) nứt nẻ như đá núi — tuấn pháp trong hội hoạ. | Gương Hán-Việt | tuấn trong \"tuấn pháp\" (皴法, kỹ thuật vẽ kết cấu đá trong tranh thuỷ mặc) | Mở khoá kiến thức | Biết 皴 giúp đọc tài liệu hội hoạ truyền thống về tranh sơn thuỷ.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 皮 (bì, da) biểu nghĩa; phần trên biểu âm. Nghĩa: da nứt nẻ, da khô bong. Mở rộng sang thuật ngữ hội hoạ truyền thống: 皴法 (tuấn pháp) — kỹ thuật vẽ nét thô thể hiện kết cấu đá và núi trong tranh thuỷ mặc. Tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "da nứt nẻ", "Hạng Tần Suất (Jun Da)": "5876.0", "Tần Suất % (Jun Da)": "99.9775425852", "GavinGrover_Once (Chiết tự trực tiếp)": "夋 + 皮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰夋皮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皮", "Unihan_Simplified (Chữ Giản thể)": "皴", "Unihan_Traditional (Chữ Phồn thể)": "皴", "Pinyin_Xie": "cūn", "Âm Hán Việt_Xie": "thuân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hiện tượng da bị khô nẻ do thời tiết lạnh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泮', '{"9000": "5877.0", "Chữ Trung Quốc": "泮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 氵 | thuỷ | biểu nghĩa | nước | 半 | bán | biểu âm | một nửa | 泮 = 氵 (Thuỷ, biểu nghĩa: nước) + 半 (Bán, biểu âm); chữ hình thanh. Bộ 氵 gợi ý nước — tan chảy; 半 cho âm đọc pàn. Tiểu triện và lục thư thông ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bợn\": nước (氵) chỉ một nửa (半) ao bán nguyệt — ao nước trước trường học thời Chu. | Gương Hán-Việt | bợn trong \"bợn cung\" (泮宫, trường học thời Chu) | Mở khoá kiến thức | Biết 泮 giúp đọc cổ văn về giáo dục thời Chu và thơ mô tả băng tan.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 氵 (thuỷ, nước) biểu nghĩa; 半 (bán) biểu âm. Nghĩa gốc: trường học thời Chu (泮宫) — trường có ao nước hình bán nguyệt. Nghĩa thứ hai: tan ra, vỡ ra. Tiểu triện và lục thư thông ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trường học; tan lở", "Hạng Tần Suất (Jun Da)": "5877.0", "Tần Suất % (Jun Da)": "99.9775772098", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 半", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵半", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "半", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泮", "Unihan_Traditional (Chữ Phồn thể)": "泮", "Pinyin_Xie": "pàn", "Âm Hán Việt_Xie": "phán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ sự tan chảy của băng tuyết hoặc danh từ chỉ trường học cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轫', '{"9000": "5878.0", "Chữ Trung Quốc": "轫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 7 | nét | 车 | xa | biểu nghĩa | xe | 刃 | nhẫn | biểu âm | lưỡi dao | 轫 = 车 (Xa, biểu nghĩa: xe) + 刃 (Nhẫn, biểu âm); chữ hình thanh. Bộ 车 chỉ xe cộ; 刃 cho âm đọc rèn. Nghĩa: cái chèn bánh xe.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhẫn\": xe (车) cần lưỡi kê (刃) — cái chêm hãm bánh xe, bắt đầu hành trình khi rút ra. | Gương Hán-Việt | nhẫn trong \"phát nhẫn\" (发轫, khởi hành, bắt đầu) | Mở khoá kiến thức | Biết 轫 giúp hiểu thành ngữ 发轫 (phát nhẫn — khởi động) và 云程发轫.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ hình thanh: 车 (xa, xe) biểu nghĩa; 刃 (nhẫn) biểu âm. Đại triện và tiểu triện ghi nhận. Nghĩa gốc: cái chêm/chèn bánh xe — vật kê dưới bánh để xe không lăn. Mở rộng: bắt đầu hành trình (phát轫 — rút chèn để xe lăn). Thành ngữ 云程发轫 — khởi hành trên con đường mây. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chèn bánh xe để khỏi lăn; ngăn trở", "Hạng Tần Suất (Jun Da)": "5878.0", "Tần Suất % (Jun Da)": "99.9776118344", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 刃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车刃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "轫", "Unihan_Traditional (Chữ Phồn thể)": "軔", "Pinyin_Xie": "rèn", "Âm Hán Việt_Xie": "nhận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ thanh gỗ dùng để chèn giữ cho bánh xe không lăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褰', '{"9000": "5879.0", "Chữ Trung Quốc": "褰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 16 | nét | 衣 | y | biểu nghĩa | quần áo | 寒 | hàn | biểu âm | lạnh | 褰 = phần trên (biểu âm, âm qiān) + 衣 (Y, biểu nghĩa: quần áo) ở dưới; chữ hình thanh. Bộ 衣 chỉ quần áo. Đại triện và tiểu triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiêm\": áo (衣) vén lên — vén xiêm y lội qua suối. | Gương Hán-Việt | khiêm trong \"khiêm thường\" (褰裳, vén váy) | Mở khoá kiến thức | Biết 褰 giúp đọc Kinh Thi và cổ văn miêu tả hình ảnh vén áo qua sông.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ hình thanh: 衣 (y, quần áo) biểu nghĩa; phần trên biểu âm. Đại triện và tiểu triện ghi nhận. Nghĩa gốc: vén áo, vén váy lên khi lội qua suối; quần áo lót. Kinh Thi có hình ảnh người vén áo qua sông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vén áo, vén quần; cái khố; rụt lại", "Hạng Tần Suất (Jun Da)": "5879.0", "Tần Suất % (Jun Da)": "99.9776459422", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "褰", "Unihan_Traditional (Chữ Phồn thể)": "褰", "Pinyin_Xie": "qiān", "Âm Hán Việt_Xie": "khiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động vén vạt áo hoặc quần lên khi đi qua nước. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('炱', '{"9000": "5880.0", "Chữ Trung Quốc": "炱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 9 | nét | 台 | đài | biểu âm | đài, bục | 火 | hoả | biểu nghĩa | lửa | 炱 = 台 (Đài, biểu âm) + 火 (Hoả, biểu nghĩa: lửa) ở dưới; chữ hình thanh. Bộ 火 chỉ lửa — muội khói; 台 cho âm đọc tái. Tiểu triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đài\": lửa (火) để lại bụi đài (台) — muội than, bồ hóng đen kịt. | Gương Hán-Việt | đài trong \"muội đài\" (炱, tro muội lửa) | Mở khoá kiến thức | Biết 炱 giúp đọc văn học cổ miêu tả đống lửa và màu đen xỉn của muội than.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 火 (hoả, lửa) biểu nghĩa; 台 (đài) biểu âm. Nghĩa: muội than, bồ hóng — chất bám đen khi đốt lửa. Tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tro, muội, bồ hóng", "Hạng Tần Suất (Jun Da)": "5880.0", "Tần Suất % (Jun Da)": "99.97768005", "GavinGrover_Once (Chiết tự trực tiếp)": "台 + 火", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱台火", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "台", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "炱", "Unihan_Traditional (Chữ Phồn thể)": "炱", "Pinyin_Xie": "tái", "Âm Hán Việt_Xie": "đài", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ lớp muội đen bám trên các vật dụng do khói lò. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醍', '{"9000": "5881.0", "Chữ Trung Quốc": "醍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 16 | nét | 酉 | dậu | biểu nghĩa | rượu, bình rượu | 是 | thị | biểu âm | là, đúng | 醍 = 酉 (Dậu, biểu nghĩa: rượu/bình rượu) + phần biểu âm; chữ hình thanh. Bộ 酉 chỉ đồ uống, rượu. Tiểu triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đề\": rượu (酉) tinh khiết nhất — đề hồ, tinh tuý như giáo lý Phật. | Gương Hán-Việt | đề trong \"đề hồ\" (醍醐), \"đề hồ quán đỉnh\" (chan tuệ giác) | Mở khoá kiến thức | Biết 醍 giúp hiểu thành ngữ Phật giáo 醍醐灌顶 — tuệ giác khai sáng tâm trí.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 酉 (dậu, rượu) biểu nghĩa; phần còn lại biểu âm. Nghĩa gốc: rượu nhạt màu hồng nhạt. Nghĩa phổ biến nhất: qua từ 醍醐 (đề hồ) — tinh chất bơ sữa thuần khiết, ví với giáo lý Phật giáo tinh tuý. 醍醐灌顶 (đề hồ quán đỉnh) — chan tuệ giác lên đỉnh đầu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đề hồ 醍醐)", "Hạng Tần Suất (Jun Da)": "5881.0", "Tần Suất % (Jun Da)": "99.9777141579", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 是", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉是", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "是", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醍", "Unihan_Traditional (Chữ Phồn thể)": "醍", "Pinyin_Xie": "tí", "Âm Hán Việt_Xie": "đề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong từ ghép đề hồ để chỉ chất béo tinh khiết từ sữa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锱', '{"9000": "5882.0", "Chữ Trung Quốc": "锱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 金 | kim | biểu nghĩa | kim loại, trọng lượng | 甾 | tai | biểu âm | dạng âm phù | 锱 = 金 (Kim, biểu nghĩa: kim loại) + phần biểu âm; chữ hình thanh. Bộ 金 chỉ đơn vị đo lường kim loại. Tiểu triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": kim loại (金) tính từng tư từng chu — 锱铢必较, ki bo tính toán. | Gương Hán-Việt | tư trong \"tư chu\" (锱铢); \"tư chu tất giáo\" (ki bo từng xu nhỏ) | Mở khoá kiến thức | Biết 锱 giúp hiểu thành ngữ 锱铢必较 — tính toán từng xu nhỏ.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 金 (kim, kim loại) biểu nghĩa; phần còn lại biểu âm. Nghĩa: đơn vị trọng lượng cổ đại rất nhỏ — 6 Chu (铢) theo Thuyết Văn. Thành ngữ: 锱铢必较 (tư chu tất giáo) — tính toán từng ly từng tý, keo kiệt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đơn vị trọng lượng thời xưa (có sách nói bằng 6 hoặc 8 lạng, cũng có sách nói 6 thù 銖,铢 là 1 chùy 錘,锤, 2 chùy là tri, như vậy một tri bằng một phần hai lạng Trung Quốc thời xưa)", "Hạng Tần Suất (Jun Da)": "5882.0", "Tần Suất % (Jun Da)": "99.9777482657", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 甾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅甾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锱", "Unihan_Traditional (Chữ Phồn thể)": "錙", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "tri", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ đơn vị đo lường cổ, thường dùng trong từ ghép tư tất để chỉ sự nhỏ nhặt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篁', '{"9000": "5883.0", "Chữ Trung Quốc": "篁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 15 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 皇 | hoàng | biểu âm | hoàng đế, vĩ đại | 篁 = 竹 (Trúc, biểu nghĩa: tre/trúc) + 皇 (Hoàng, biểu âm); chữ hình thanh. Bộ 竹 chỉ cây tre; 皇 cho âm đọc huáng. Tiểu triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàng\": trúc (竹) vĩ đại như hoàng (皇) — rừng trúc bạt ngàn, thanh vắng. | Gương Hán-Việt | hoàng trong \"u hoàng\" (幽篁, rừng trúc u tịch) | Mở khoá kiến thức | Biết 篁 giúp đọc thơ Vương Duy và cổ thi về cảnh rừng trúc thanh tịnh.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 竹 (trúc, tre) biểu nghĩa; 皇 (hoàng) biểu âm. Tiểu triện ghi nhận. Nghĩa: rừng tre, bụi tre. Nổi tiếng trong thơ Vương Duy: 独坐幽篁里 — ngồi một mình giữa rừng trúc vắng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bụi tre, cây tre", "Hạng Tần Suất (Jun Da)": "5883.0", "Tần Suất % (Jun Da)": "99.9777823735", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 皇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮皇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篁", "Unihan_Traditional (Chữ Phồn thể)": "篁", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ khóm tre hoặc rừng tre trúc rậm rạp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葚', '{"9000": "5884.0", "Chữ Trung Quốc": "葚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 艸 | tháu | biểu nghĩa | cỏ, thực vật | 甚 | tham | biểu âm | rất, sâu sắc | 葚 = 艸 (Tháu, biểu nghĩa: thực vật) + 甚 (Tham, biểu âm); chữ hình thanh. Bộ 艸 chỉ loài cây; 甚 cho âm đọc rèn/shèn. Nghĩa: quả dâu tằm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tham\": cỏ (艸) rất (甚) ngọt — quả dâu tằm mọng ngọt tham ăn. | Gương Hán-Việt | tham trong \"tang tham\" (桑葚, quả dâu tằm) | Mở khoá kiến thức | Biết 葚 giúp đọc Kinh Thi mô tả mùa thu hoạch dâu tằm.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ hình thanh: 艸 (tháu, thực vật) biểu nghĩa; 甚 (tham) biểu âm. Đại triện và tiểu triện ghi nhận. Nghĩa: quả dâu tằm (quả của cây 桑). Kinh Thi có hình ảnh hái dâu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quả dâu", "Hạng Tần Suất (Jun Da)": "5884.0", "Tần Suất % (Jun Da)": "99.9778164813", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 甚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹甚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葚", "Unihan_Traditional (Chữ Phồn thể)": "葚", "Pinyin_Xie": "rèn", "Âm Hán Việt_Xie": "thậm, thầm, thấm, nhẫm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ quả của cây dâu tằm, thường dùng trong từ tang thầm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驽', '{"9000": "5885.0", "Chữ Trung Quốc": "驽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 8 | nét | 奴 | nô | biểu âm | nô lệ | 马 | mã | biểu nghĩa | ngựa | 驽 = 奴 (Nô, biểu âm) + 马 (Mã, biểu nghĩa: ngựa); chữ hình thanh. Bộ 马 chỉ ngựa; 奴 cho âm đọc nú. Nghĩa: ngựa kém, ngựa chậm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nô\": ngựa (马) như nô lệ (奴) — ngựa kém cỏi, tài hèn. | Gương Hán-Việt | nô trong \"nô mã\" (驽马, ngựa kém); \"nô độn\" (驽钝, kém cỏi) | Mở khoá kiến thức | Biết 驽 giúp đọc thành ngữ 驽马十驾 và thư phong cổ tự xưng khiêm tốn.", "Tự nguyên_Xie": "Chữ hình thanh: 马 (mã, ngựa) biểu nghĩa; 奴 (nô) biểu âm. Nghĩa: ngựa già, ngựa kém — trái với 骏 (tuấn mã). Câu quen thuộc: 驽马十驾 (nô mã thập giá) — ngựa hèn đi mười ngày chặng, ý nhắc sự kiên trì bù tài hèn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa nhát; (từ xưng hô nhún nhường)", "Hạng Tần Suất (Jun Da)": "5885.0", "Tần Suất % (Jun Da)": "99.9779177712", "GavinGrover_Once (Chiết tự trực tiếp)": "奴 + 马", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱奴马", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "驽", "Unihan_Traditional (Chữ Phồn thể)": "駑", "Pinyin_Xie": "nú", "Âm Hán Việt_Xie": "nô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ để chỉ sự kém cỏi, chậm chạp hoặc làm danh từ chỉ con ngựa yếu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辚', '{"9000": "5886.0", "Chữ Trung Quốc": "辚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 16 | nét | 車 | xa | biểu nghĩa | xe | 粦 | lân | biểu âm | ánh sáng, lân tinh | 辚 = 車 (Xa, biểu nghĩa: xe) + 粦 (Lân, biểu âm); chữ hình thanh. Bộ 車 chỉ xe cộ; 粦 cho âm đọc lín. Nghĩa: tiếng xe lăn ầm ầm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lân\": xe (車) rền như lân tinh (粦) — tiếng bánh xe lăn ầm vang. | Gương Hán-Việt | lân trong \"xa lân lân\" (车辚辚, tiếng xe rền vang) | Mở khoá kiến thức | Biết 辚 giúp đọc Binh xa hành của Đỗ Phủ và cổ thi mô tả đoàn quân hành tiến.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 車 (xa, xe) biểu nghĩa; 粦 (lân) biểu âm. Tiểu triện ghi nhận. Nghĩa: tiếng xe chạy rền. Nổi tiếng qua thơ Đỗ Phủ: 车辚辚，马萧萧 (xa lân lân, mã tiêu tiêu) — Binh xa hành. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bậc cửa; tiếng xe chạy", "Hạng Tần Suất (Jun Da)": "5886.0", "Tần Suất % (Jun Da)": "99.9779513622", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 粦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车粦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "粦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "辚", "Unihan_Traditional (Chữ Phồn thể)": "轔", "Pinyin_Xie": "lín", "Âm Hán Việt_Xie": "lân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Danh từ | 名词 | Chữ này thường dùng làm từ tượng thanh mô tả âm thanh ầm ầm của bánh xe thời cổ. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睥', '{"9000": "5887.0", "Chữ Trung Quốc": "睥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 13 | nét | 目 | mục | biểu nghĩa | mắt | 卑 | ti | biểu âm | thấp hèn | 睥 = 目 (Mục, biểu nghĩa: mắt) + 卑 (Ti, biểu âm); chữ hình thanh. Bộ 目 chỉ hành động liên quan đến mắt — liếc khinh thường; 卑 cho âm đọc pì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ti\": mắt (目) liếc xuống thấp (卑) — nhìn khinh thường người khác. | Gương Hán-Việt | ti trong \"tỉ nghê\" (睥睨, liếc khinh, nhìn thường) | Mở khoá kiến thức | Biết 睥 giúp đọc cổ văn miêu tả thái độ kiêu ngạo, khinh người.", "Tự nguyên_Xie": "Chữ hình thanh: 目 (mục, mắt) biểu nghĩa; 卑 (ti, thấp hèn) biểu âm. Nghĩa 1: nhìn nghiêng, liếc khinh thường (睥睨). Nghĩa 2: thành ngắn trên mặt tường (lỗ châu mai). Tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trong nghiêng, nhìn nghiêng; cái thành ngắn trên tường", "Hạng Tần Suất (Jun Da)": "5887.0", "Tần Suất % (Jun Da)": "99.9779849533", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睥", "Unihan_Traditional (Chữ Phồn thể)": "睥", "Pinyin_Xie": "pì", "Âm Hán Việt_Xie": "bễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện hành động liếc nhìn hoặc nhìn nghiêng với vẻ coi thường. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸺', '{"9000": "5888.0", "Chữ Trung Quốc": "鸺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 11 | nét | 休 | hưu | biểu âm | nghỉ ngơi | 鸟 | điểu | biểu nghĩa | chim | 鸺 = 休 (Hưu, biểu âm) + 鸟 (Điểu, biểu nghĩa: chim); chữ hình thanh. Bộ 鸟 chỉ loài chim; 休 cho âm đọc xiū. Nghĩa: cú mèo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hưu\": chim (鸟) nghỉ ngơi (休) ban ngày, hoạt động đêm — con cú mèo. | Gương Hán-Việt | hưu trong \"hưu lưu\" (鸺鹠, cú mèo châu Á) | Mở khoá kiến thức | Biết 鸺 giúp đọc bách khoa động vật học cổ và thơ cổ mô tả chim cú trong đêm.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 鸟 (điểu, chim) biểu nghĩa; 休 (hưu) biểu âm. Tiểu triện ghi nhận. Nghĩa: cú lợn, cú mèo (Strigidae). Dùng trong 鸺鹠 (hưu lưu) — tên loài cú châu Á. Tiếng cú vang trong đêm được xem là điềm xấu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hưu lưu 鵂鶹,鸺鹠)", "Hạng Tần Suất (Jun Da)": "5888.0", "Tần Suất % (Jun Da)": "99.9780185443", "GavinGrover_Once (Chiết tự trực tiếp)": "休 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰休鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "休", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鸺", "Unihan_Traditional (Chữ Phồn thể)": "鵂", "Pinyin_Xie": "xiū", "Âm Hán Việt_Xie": "hưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim giống cú mèo, thường xuất hiện trong từ ghép hưu lưu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筇', '{"9000": "5889.0", "Chữ Trung Quốc": "筇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 邛 | cùng | biểu âm | tên đất (Tứ Xuyên) | 筇 = 竹 (Trúc, biểu nghĩa: tre/trúc) + 邛 (Cùng, biểu âm); chữ hình thanh. Bộ 竹 chỉ vật liệu tre; 邛 cho âm đọc qióng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cùng\": trúc (竹) từ đất Cùng (邛, Tứ Xuyên) — gậy trúc của ẩn sĩ. | Gương Hán-Việt | cùng trong \"cùng trúc\" (筇竹) và \"cùng trượng\" (筇杖, gậy trúc) | Mở khoá kiến thức | Biết 筇 giúp đọc thơ ẩn sĩ miêu tả gậy chống của người già, nhà tu.", "Tự nguyên_Xie": "Chữ hình thanh: 竹 (trúc, tre) biểu nghĩa; 邛 (cùng, tên đất ở Tứ Xuyên) biểu âm. Nghĩa: loài trúc 筇竹 đặc biệt có đốt dày ở Tứ Xuyên — dùng làm gậy chống. Gậy 筇 là vật tao nhã của ẩn sĩ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một giống trúc)", "Hạng Tần Suất (Jun Da)": "5889.0", "Tần Suất % (Jun Da)": "99.9780521353", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 邛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮邛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "邛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筇", "Unihan_Traditional (Chữ Phồn thể)": "筇", "Pinyin_Xie": "qióng", "Âm Hán Việt_Xie": "cung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại trúc thân cứng dùng làm gậy chống cho người già. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戥', '{"9000": "5890.0", "Chữ Trung Quốc": "戥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戈 | Số nét | 13 | nét | 戥 | để | tượng hình | cái cân tiểu ly | 戥 là chữ tạo muộn, không có phân tích hình thanh hay hội ý rõ ràng. Không có anchor Wiktionary; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"để\": cái cân (戥) nhỏ li ti — cân tiểu ly đo từng li từng tý. | Gương Hán-Việt | để trong \"để xứng\" (戥秤, cân tiểu ly) | Mở khoá kiến thức | Biết 戥 giúp đọc văn bản y học cổ và văn bản buôn bán vàng bạc thời phong kiến.", "Tự nguyên_Xie": "Không có Wiktionary anchor cho 戥. Chữ tạo muộn chỉ cái cân tiểu ly — loại cân nhỏ dùng để cân thuốc, vàng bạc. Chưa thấy trong giáp cốt/kim văn; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái cân tiểu ly", "Hạng Tần Suất (Jun Da)": "5890.0", "Tần Suất % (Jun Da)": "99.9780857264", "GavinGrover_Once (Chiết tự trực tiếp)": "星 + 戈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰星戈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "星", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "戈", "Unihan_Simplified (Chữ Giản thể)": "戥", "Unihan_Traditional (Chữ Phồn thể)": "戥", "Pinyin_Xie": "děng", "Âm Hán Việt_Xie": "đẳng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ loại cân nhỏ hoặc động từ khi cân lượng nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髀', '{"9000": "5891.0", "Chữ Trung Quốc": "髀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 17 | nét | 骨 | cốt | biểu nghĩa | xương | 卑 | ti | biểu âm | thấp hèn | 髀 = 骨 (Cốt, biểu nghĩa: xương) + 卑 (Ti, biểu âm); chữ hình thanh. Bộ 骨 chỉ xương; 卑 cho âm đọc bì. Nghĩa: xương đùi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỉ\": xương (骨) vùng dưới thấp (卑) — xương đùi, bắp vế. | Gương Hán-Việt | tỉ trong \"tỉ nhục\" (髀肉, thịt đùi) — điển cố Lưu Bị | Mở khoá kiến thức | Biết 髀 giúp đọc điển cố 髀肉复生 (Lưu Bị cảm thán tuổi già) và y học cổ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 骨 (cốt, xương) biểu nghĩa; 卑 (ti) biểu âm. Tiểu triện và lục thư thông ghi nhận. Nghĩa: xương đùi. Điển cố nổi tiếng trong Tam Quốc: Lưu Bị khóc vì thấy 髀肉复生 — đùi vế mọc thịt vì lâu không cưỡi ngựa, cảm thán tuổi già. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đùi vế; cây nêu", "Hạng Tần Suất (Jun Da)": "5891.0", "Tần Suất % (Jun Da)": "99.9781193174", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "髀", "Unihan_Traditional (Chữ Phồn thể)": "髀", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn ngôn hoặc y học để chỉ phần đùi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驺', '{"9000": "5892.0", "Chữ Trung Quốc": "驺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 8 | nét | 马 | mã | biểu nghĩa | ngựa | 刍 | sô | biểu âm | cỏ khô, chăn thú | 驺 = 刍 (Sô, biểu âm) + 马 (Mã, biểu nghĩa: ngựa); chữ hình thanh. Bộ 马 chỉ ngựa và công việc liên quan; 刍 cho âm đọc zōu. Đại triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sô\": ngựa (马) của người cắt cỏ (刍) — người gác ngựa, dẹp đường cho kiệu. | Gương Hán-Việt | sô trong \"sô lỵ\" (驺吏); \"thất sô\" (七驺, bảy loại kỵ mã nghi lễ) | Mở khoá kiến thức | Biết 驺 giúp đọc Chu Lễ và cổ văn miêu tả nghi lễ hoàng gia.", "Tự nguyên_Xie": "Đại triện | Chữ hình thanh: 马 (mã, ngựa) biểu nghĩa; 刍 (sô, cắt cỏ) biểu âm. Đại triện ghi nhận. Nghĩa: người dẹp đường / người hầu chạy trước kiệu quan. Dùng trong Chu Lễ — bảy loại kỵ mã nghi lễ hoàng gia (七驺). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dẹp đường cho kiệu quan đi", "Hạng Tần Suất (Jun Da)": "5892.0", "Tần Suất % (Jun Da)": "99.9781529084", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 刍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马刍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "驺", "Unihan_Traditional (Chữ Phồn thể)": "騶", "Pinyin_Xie": "zōu", "Âm Hán Việt_Xie": "sô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ người hầu cưỡi ngựa hoặc động từ dẹp đường. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哙', '{"9000": "5893.0", "Chữ Trung Quốc": "哙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 口 | khẩu | biểu nghĩa | miệng | 会 | hội | biểu âm | gặp gỡ, tụ hội | 哙 là giản thể của 噲 — 口 (Khẩu, biểu nghĩa: miệng) + 会 rút gọn từ 會 (biểu âm). Bộ 口 chỉ hành động miệng — nuốt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoái\": miệng (口) hội tụ (会) thức ăn — nuốt nhanh, tên dũng sĩ Phàn Khoái. | Gương Hán-Việt | khoái trong \"Phàn Khoái\" (樊哙, dũng sĩ thời Hán Sở) | Mở khoá kiến thức | Biết 哙 giúp đọc Sử Ký — câu chuyện Hồng Môn Yến và anh hùng Phàn Khoái.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 哙 là giản thể của 噲, rút gọn phần 會 thành 会. Nghĩa: nuốt vào, cử động cổ họng. Dùng chủ yếu trong tên người: 樊哙 (Phàn Khoái) — dũng sĩ nổi tiếng trong Hán Sở tranh hùng. Đại triện và tiểu triện ghi nhận dạng phồn thể. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nuốt vào", "Hạng Tần Suất (Jun Da)": "5893.0", "Tần Suất % (Jun Da)": "99.9782195737", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 会", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口会", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "会", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哙", "Unihan_Traditional (Chữ Phồn thể)": "噲", "Pinyin_Xie": "kuài", "Âm Hán Việt_Xie": "khoái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ hành động nuốt hoặc làm họ người. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('濞', '{"9000": "5894.0", "Chữ Trung Quốc": "濞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 17 | nét | 氵 | thuỷ | biểu nghĩa | nước | 鼻 | tị | biểu âm | mũi | 濞 = 氵 (Thuỷ, biểu nghĩa: nước) + 鼻 (Tị, biểu âm); chữ hình thanh. Bộ 氵 chỉ nước, chất lỏng; 鼻 cho âm đọc bì/pì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tia\": nước (氵) chảy qua mũi (鼻) — tiếng nước ào ào hoặc nước mũi. | Gương Hán-Việt | tia trong địa danh 怒濞 (Nộ Tia — huyện Vân Nam) | Mở khoá kiến thức | Biết 濞 giúp đọc thơ cổ mô tả sóng nước và địa danh Vân Nam.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 氵 (thuỷ, nước) biểu nghĩa; 鼻 (tị, mũi) biểu âm. Tiểu triện ghi nhận. Nghĩa 1: từ tượng thanh chỉ tiếng nước ào ào (澎濞). Nghĩa 2: nước mũi (tiếng Khách Gia). Nghĩa 3: dùng trong địa danh 怒濞 (huyện ở Vân Nam). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Dạng Tị (tên huyện ở Vân Nam)", "Hạng Tần Suất (Jun Da)": "5894.0", "Tần Suất % (Jun Da)": "99.978252648", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 鼻", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵鼻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鼻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "濞", "Unihan_Traditional (Chữ Phồn thể)": "濞", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ riêng trong địa danh hoặc tính từ mô tả âm thanh nước chảy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逄', '{"9000": "5895.0", "Chữ Trung Quốc": "逄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 9 | nét | 逄 | bàng | tượng hình | họ Bàng — biến thể của 逢 | 逄 là biến dạng (corruption) của 逢, không có cấu trúc hình thanh/hội ý riêng. Hiện dùng chủ yếu làm họ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Bàng\": chữ giống 逢 (bàng, gặp gỡ) nhưng bị biến dạng — họ Bàng mượn dạng biến thể của chữ gặp gỡ. | Gương Hán-Việt | họ Bàng (bàng) — dòng họ trong sử Trung Hoa | Mở khoá kiến thức | Biết 逄 mở khoá nhận diện họ Bàng trong văn bản cổ và sử liệu.", "Tự nguyên_Xie": "Theo Wiktionary, 逄 là dạng biến dạng của 逢 (bàng, nghĩa gặp gỡ). Sau khi hình dạng thay đổi, 逄 được dùng riêng làm họ. Chưa có nguồn học thuật xác nhận niên đại biến dạng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Bàng", "Hạng Tần Suất (Jun Da)": "5895.0", "Tần Suất % (Jun Da)": "99.9782857222", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 夅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶夅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逄", "Unihan_Traditional (Chữ Phồn thể)": "逄", "Pinyin_Xie": "páng", "Âm Hán Việt_Xie": "bàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng chỉ họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桤', '{"9000": "5896.0", "Chữ Trung Quốc": "桤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 桤 | khởi | tượng hình | cây khởi (cây tống quá sủi) | 桤 là chữ chỉ loại cây, cấu trúc nội bộ không có dữ liệu hình thanh/hội ý. Dùng chủ yếu trong tên thực vật. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Khởi\": bộ 木 (cây) — cây khởi mọc ven suối, thân gỗ nhẹ. | Gương Hán-Việt | cây khởi (khởi) — tên loài cây trong y học cổ truyền | Mở khoá kiến thức | Biết 桤 mở khoá nhận diện tên loài cây gỗ trong văn bản thực vật học Hán cổ.", "Tự nguyên_Xie": "Không có dữ liệu Wiktionary về nguồn gốc chữ 桤. Từ bộ 木 (mộc, cây) suy đoán đây là chữ chỉ loại cây. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây khởi", "Hạng Tần Suất (Jun Da)": "5896.0", "Tần Suất % (Jun Da)": "99.9783187965", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 岂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木岂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "岂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桤", "Unihan_Traditional (Chữ Phồn thể)": "榿", "Pinyin_Xie": "qī", "Âm Hán Việt_Xie": "khi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ một loại cây rụng lá thuộc họ Bulô. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('攵', '{"9000": "5897.0", "Chữ Trung Quốc": "攵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 攴 | Số nét | 4 | nét | 攵 | phác | tượng hình | tay cầm que đánh nhẹ — bộ thủ số 66 | 攵 là tượng hình, hình vẽ bàn tay cầm cành cây hay que gõ nhẹ. Là bộ thủ số 66 trong Khang Hi tự điển, xuất hiện trong các chữ liên quan đến hành động (đánh, dạy, thu).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Phác\": hình bàn tay (又) cầm que gõ — bộ thủ của mọi chữ có hành động tay. | Gương Hán-Việt | phác (phác) — xuất hiện trong bộ thủ các chữ 政, 教, 收 | Mở khoá kiến thức | Nhận ra 攵 trong chữ giúp hiểu ngay yếu tố \"hành động có chủ ý\" trong 政 (chính), 教 (giáo), 收 (thu).", "Tự nguyên_Xie": "Không có dữ liệu Wiktionary riêng cho 攵. Đây là dạng viết giản của 攴 (phác), tượng hình bàn tay cầm que. Được dùng làm bộ thủ trong các chữ như 政, 教, 收, 改. Chưa có nguồn học thuật xác nhận thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đánh khẽ", "Hạng Tần Suất (Jun Da)": "5897.0", "Tần Suất % (Jun Da)": "99.9783518707", "GavinGrover_Once (Chiết tự trực tiếp)": "⺙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: me", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⺙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "攵", "Unihan_Traditional (Chữ Phồn thể)": "攵", "Pinyin_Xie": "pū", "Âm Hán Việt_Xie": "truy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chủ yếu dùng làm bộ thủ trong cấu tạo chữ Hán hoặc động từ cổ chỉ việc đánh nhẹ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('炻', '{"9000": "5898.0", "Chữ Trung Quốc": "炻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 9 | nét | 炻 | thạch | tượng hình | đồ sành sứ — lửa + đá | 炻 có bộ 火 (hoả, lửa) bên trái và 石 (thạch, đá) bên phải, kết hợp hội ý: lửa nung đá tạo ra đồ sành. Không có dữ liệu hình thanh chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Thạch\": lửa (火) nung đá (石) → đồ sành sứ — nhớ qua ảnh đồ gốm lửa-đá. | Gương Hán-Việt | thạch (thạch) — liên quan đá và vật liệu nung | Mở khoá kiến thức | Biết 炻 mở khoá nhận diện thuật ngữ vật liệu gốm sứ trong văn bản kỹ thuật Hán ngữ.", "Tự nguyên_Xie": "Không có dữ liệu Wiktionary cho 炻. Từ cấu trúc 火 + 石 suy ra đây là chữ tạo muộn dùng cho khái niệm đồ sành sứ (stoneware) — sản phẩm nung lửa từ đá. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loại đồ sành sứ nhỏ để đựng", "Hạng Tần Suất (Jun Da)": "5898.0", "Tần Suất % (Jun Da)": "99.978384945", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "石", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "炻", "Unihan_Traditional (Chữ Phồn thể)": "炻", "Pinyin_Xie": "shí", "Âm Hán Việt_Xie": "thạch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ hoặc tính từ bổ nghĩa trong từ ghép chỉ chất liệu gốm đá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磙', '{"9000": "5899.0", "Chữ Trung Quốc": "磙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 15 | nét | 磙 | cổn | tượng hình | quả lăn/quả lu nông nghiệp | 磙 có bộ 石 (thạch, đá) là yếu tố nghĩa; phần còn lại (滚 bên phải) gợi âm. Là chữ hình thanh: bộ đá + âm tương tự 滚 (cổn). Chưa có lsCodes xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Cổn\": bộ 石 (đá) + âm cổn — viên đá tròn lăn trên ruộng sau khi gặt. | Gương Hán-Việt | cổn (cổn) — trong \"lăn cổn\" (lăn tròn) | Mở khoá kiến thức | Biết 磙 giúp đọc văn bản nông nghiệp cổ về dụng cụ đồng ruộng.", "Tự nguyên_Xie": "Wiktionary xác nhận 磙 là dụng cụ nông nghiệp dạng lăn (roller), dùng để đập thóc hoặc làm phẳng đất. Đồng nghĩa với 碌碡. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quả lăn, quả lu; lăn", "Hạng Tần Suất (Jun Da)": "5899.0", "Tần Suất % (Jun Da)": "99.9784180192", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 衮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石衮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "衮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磙", "Unihan_Traditional (Chữ Phồn thể)": "磙", "Pinyin_Xie": "gǔn", "Âm Hán Việt_Xie": "cổn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ dụng cụ lăn hoặc động từ chỉ hành động lăn ép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疳', '{"9000": "5900.0", "Chữ Trung Quốc": "疳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 10 | nét | 疳 | cam | tượng hình | bệnh cam (suy dinh dưỡng ở trẻ) | 疳 có bộ 疒 (nạch, bộ bệnh) là yếu tố nghĩa, và 甘 (cam, ngọt) gợi âm. Là chữ hình thanh: bộ bệnh + âm cam. Không có lsCodes xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Cam\": bộ bệnh (疒) + cam (甘) → bệnh cam — trẻ suy dinh dưỡng, bụng to, người mòn. | Gương Hán-Việt | bệnh cam (cam) — trong \"疳积\" (cam tích, suy dinh dưỡng trẻ em) | Mở khoá kiến thức | Biết 疳 mở khoá thuật ngữ y học cổ truyền về bệnh trẻ em như 疳积, 疳疾.", "Tự nguyên_Xie": "Không có dữ liệu Wiktionary chi tiết cho 疳. Từ cấu trúc 疒 (bệnh) + 甘 (cam/ngọt) suy luận: chữ hình thanh chỉ bệnh cam — bệnh suy dinh dưỡng nặng ở trẻ em trong y học cổ truyền. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh cam", "Hạng Tần Suất (Jun Da)": "5900.0", "Tần Suất % (Jun Da)": "99.9784510935", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 甘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒甘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "疳", "Unihan_Traditional (Chữ Phồn thể)": "疳", "Pinyin_Xie": "gān", "Âm Hán Việt_Xie": "cam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong y học cổ truyền để chỉ các chứng bệnh tiêu hóa của trẻ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醭', '{"9000": "5901.0", "Chữ Trung Quốc": "醭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 19 | nét | 酉 | dậu | biểu nghĩa | rượu, lên men | 菐 | biểu âm | 醭 = 酉 (Dậu, biểu nghĩa: rượu/lên men) + 菐 (biểu âm). Chữ hình thanh. Bộ 酉 chỉ rõ liên quan đến rượu hoặc dấm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Bộc\": bộ rượu (酉) + lớp váng trắng — nhớ bình dấm bị mốc trắng phủ mặt. | Gương Hán-Việt | bộc (bộc) — trong \"白醭\" (bạch bộc, mốc trắng trên dấm) | Mở khoá kiến thức | Biết 醭 mở khoá từ 白醭, 醭兒 trong văn bản ẩm thực và y học cổ về bảo quản.", "Tự nguyên_Xie": "Wiktionary: 醭 là chữ hình thanh gồm 酉 (s, biểu nghĩa rượu) và 菐 (p, biểu âm). Nghĩa gốc: lớp mốc trắng mọc trên bề mặt dấm hoặc rượu. Đọc chuẩn là bú (đại lục và Đài Loan), còn có biến âm pú (cũ). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mốc, váng", "Hạng Tần Suất (Jun Da)": "5901.0", "Tần Suất % (Jun Da)": "99.9784841677", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 菐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉菐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "菐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醭", "Unihan_Traditional (Chữ Phồn thể)": "醭", "Pinyin_Xie": "bú", "Âm Hán Việt_Xie": "phốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ lớp màng mốc nổi lên trên bề mặt chất lỏng lên men. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳇', '{"9000": "5902.0", "Chữ Trung Quốc": "鳇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 鳇 | hoàng | tượng hình | cá tầm (cá hoàng) — giản thể của 鰉 | 鳇 là giản thể của 鰉, có bộ 鱼 (ngư, cá) biểu nghĩa và phần 皇 (hoàng) biểu âm. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Hoàng\": bộ cá (鱼) + hoàng (皇) — cá tầm vàng — vua của cá sông Hắc Long Giang. | Gương Hán-Việt | hoàng ngư (hoàng) — cá tầm Amur trong văn bản địa lý và ẩm thực | Mở khoá kiến thức | Biết 鳇 mở khoá tên loài cá tầm quý trong văn bản tự nhiên học và địa lý Trung Hoa.", "Tự nguyên_Xie": "Wiktionary: 鳇 là dạng giản thể của 鰉, thay 魚 bằng 鱼. 鰉 chỉ loài cá tầm lớn (sturgeon) sống ở sông Hắc Long Giang. Thân dài tới 2 trượng, lưng có giáp xương, mũi dài, mỡ vàng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá hoàng (dài tới 2 trượng, lưng có xương bọc như áo giáp, mũi dài, mỡ vàng)", "Hạng Tần Suất (Jun Da)": "5902.0", "Tần Suất % (Jun Da)": "99.978517242", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 皇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼皇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳇", "Unihan_Traditional (Chữ Phồn thể)": "鰉", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loài cá nước ngọt cỡ lớn có vảy cứng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹮', '{"9000": "5903.0", "Chữ Trung Quốc": "鹮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 18 | nét | 鹮 | hoàn | tượng hình | cò quăm (ibis/spoonbill) | 鹮 có bộ 鸟 (điểu, chim) biểu nghĩa và phần còn lại gợi âm. Là chữ hình thanh chỉ loài chim. Không có dữ liệu cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Hoàn\": bộ chim (鸟) + âm hoàn — cò quăm với chiếc mỏ cong vòng đặc trưng. | Gương Hán-Việt | hoàn (hoàn) — trong \"朱鹮\" (chu hoàn, cò quăm Nhật Bản) | Mở khoá kiến thức | Biết 鹮 mở khoá tên các loài chim quý trong danh sách bảo tồn như 朱鹮 (cò quăm đỏ).", "Tự nguyên_Xie": "Không có dữ liệu Wiktionary chi tiết cho 鹮. Từ bộ 鸟 (chim) và âm hoán suy đoán đây là chữ hình thanh chỉ loài cò quăm (ibis) hoặc thìa lông (spoonbill) trong họ Threskiornidae. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cò quăm", "Hạng Tần Suất (Jun Da)": "5903.0", "Tần Suất % (Jun Da)": "99.9785503162", "GavinGrover_Once (Chiết tự trực tiếp)": "睘 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰睘鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "睘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹮", "Unihan_Traditional (Chữ Phồn thể)": "䴉", "Pinyin_Xie": "huán", "Âm Hán Việt_Xie": "hoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các loài chim thuộc họ cò quăm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迓', '{"9000": "5904.0", "Chữ Trung Quốc": "迓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 7 | nét | 辵 | biểu nghĩa | đi, di chuyển | 牙 | nha | biểu âm | 迓 = 辵 (biểu nghĩa: đi/di chuyển) + 牙 (Nha, biểu âm). Chữ hình thanh — bộ di chuyển kết hợp âm nha cho nghĩa đón rước.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Nhạ\": bộ đi (辵) + nha (牙) — chủ động bước ra đón khách, miệng cười như hàm răng 牙. | Gương Hán-Việt | nhạ (nhạ) — trong \"迎迓\" (nghênh nhạ, đón rước) | Mở khoá kiến thức | Biết 迓 mở khoá từ 迎迓 trong thơ ca và văn cổ về nghi lễ đón tiếp.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary: 迓 là chữ hình thanh gồm 辵 (s, biểu nghĩa di chuyển/đi) và 牙 (p, biểu âm). Nghĩa gốc: đi ra đón tiếp khách. Có dạng tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đón rước; đi mời", "Hạng Tần Suất (Jun Da)": "5904.0", "Tần Suất % (Jun Da)": "99.9785833904", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 牙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶牙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "牙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "迓", "Unihan_Traditional (Chữ Phồn thể)": "迓", "Pinyin_Xie": "yà", "Âm Hán Việt_Xie": "nhạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ người để biểu thị sự đón tiếp trang trọng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眇', '{"9000": "5905.0", "Chữ Trung Quốc": "眇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 9 | nét | 眇 | dẻo | tượng hình | chột mắt; nhỏ bé, xa xăm | 眇 có bộ 目 (mục, mắt) biểu nghĩa và 少 (thiểu, ít) gợi âm và ý: mắt thiếu/kém. Nhiều khả năng là hội ý: mắt (目) ít/yếu (少) → chột, nhìn kém. Không có lsCodes xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Dẻo\": bộ mắt (目) + ít (少) — con mắt thiếu đi một bên → chột, nhìn xa thấy nhỏ bé. | Gương Hán-Việt | dẻo (dẻo) — trong \"眇眇\" (dẻo dẻo, xa tít tắp) | Mở khoá kiến thức | Biết 眇 mở khoá từ 眇小 (dẻo tiểu, rất nhỏ), 眇眇 (xa xăm) trong thơ cổ.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 眇 có nhiều nghĩa cổ: chột mắt, nhìn tinh tế, xa xăm, nhỏ bé, cao vời. Đọc thứ hai là biến thể của 妙 (diệu). Không có thông tin cấu trúc hình thanh/hội ý chính thức. Chưa có nguồn học thuật xác nhận thêm. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chột", "Hạng Tần Suất (Jun Da)": "5905.0", "Tần Suất % (Jun Da)": "99.9786164647", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 少", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目少", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "少", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眇", "Unihan_Traditional (Chữ Phồn thể)": "眇", "Pinyin_Xie": "miǎo", "Âm Hán Việt_Xie": "miễu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Làm tính từ bổ nghĩa cho danh từ hoặc làm vị ngữ để tả mắt bị hỏng hoặc sự nhỏ bé. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('楮', '{"9000": "5906.0", "Chữ Trung Quốc": "楮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 楮 | dó | tượng hình | cây dó (Broussonetia papyrifera), dùng làm giấy | 楮 có bộ 木 (mộc, cây) biểu nghĩa; phần còn lại gợi âm. Là chữ hình thanh chỉ loài cây. Không có lsCodes xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Dó\": bộ cây (木) + cây dó — loài cây vỏ xơ làm ra giấy dó truyền thống Việt Nam. | Gương Hán-Việt | cây dó (dó) — trong \"楮先生\" (dó tiên sinh, cách gọi trang trọng cho giấy) | Mở khoá kiến thức | Biết 楮 mở khoá từ 楮纸 (giấy dó), 楮币 (tiền giấy) trong văn bản lịch sử kinh tế.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary: 楮 chỉ cây dó giấy (Broussonetia papyrifera) — loài cây thân gỗ dùng làm giấy truyền thống. Đồng nghĩa với 構/榖. Sau đó mở rộng nghĩa sang giấy nói chung. Có dạng tiểu triện và lục thư thông còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây dó (dùng làm giấy); tiền giấy", "Hạng Tần Suất (Jun Da)": "5906.0", "Tần Suất % (Jun Da)": "99.9786495389", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 者", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木者", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "者", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "楮", "Unihan_Traditional (Chữ Phồn thể)": "楮", "Pinyin_Xie": "chǔ", "Âm Hán Việt_Xie": "chử", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loài cây nguyên liệu làm giấy hoặc hoán dụ chỉ các loại giấy tờ, tiền giấy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砜', '{"9000": "5907.0", "Chữ Trung Quốc": "砜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 9 | nét | 砜 | phong | tượng hình | sulphone — hợp chất hữu cơ chứa S=O | 砜 có bộ 石 (thạch, khoáng chất) biểu nghĩa và 风 (phong) gợi âm. Là chữ hình thanh tạo muộn, dùng trong hoá học. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Phong\": bộ khoáng (石) + phong (风) → hợp chất sulphone trong hoá học hữu cơ. | Gương Hán-Việt | phong (phong) — trong thuật ngữ hoá học 砜类化合物 (hợp chất sulphone) | Mở khoá kiến thức | Biết 砜 mở khoá thuật ngữ hoá học như 亚砜 (sulfoxide), 砜类药物 (thuốc sulphone).", "Tự nguyên_Xie": "Không có dữ liệu Wiktionary cho 砜. Đây là chữ tạo muộn trong hoá học hiện đại, dùng để phiên âm sulfone (SO₂ kẹp giữa hai nhóm hữu cơ). Bộ 石 gợi khoáng/hoá chất, phần 风 biểu âm fēng. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sulphone (hoá học)", "Hạng Tần Suất (Jun Da)": "5907.0", "Tần Suất % (Jun Da)": "99.9786826132", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 风", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石风", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "风", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砜", "Unihan_Traditional (Chữ Phồn thể)": "碸", "Pinyin_Xie": "fēng", "Âm Hán Việt_Xie": "phong", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong thuật ngữ hóa học để chỉ nhóm chức hoặc hợp chất chứa lưu huỳnh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菘', '{"9000": "5908.0", "Chữ Trung Quốc": "菘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菘 | tùng | tượng hình | rau tùng, đồng nghĩa với 白菜 (bắp cải trắng) | 菘 có bộ 艸 (thảo, cỏ/cây) biểu nghĩa và 松 (tùng) gợi âm. Là chữ hình thanh chỉ loại rau. Không có lsCodes xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tùng\": bộ cỏ (艸) + tùng (松) — rau tùng mọc thẳng như thông xanh. | Gương Hán-Việt | tùng (tùng) — trong \"菘菜\" (tùng thái, bắp cải) | Mở khoá kiến thức | Biết 菘 giúp đọc tên rau củ cổ trong y học và ẩm thực cổ điển Trung Hoa.", "Tự nguyên_Xie": "Wiktionary: 菘 là đồng nghĩa với 白菜 (bắp cải trắng/Chinese cabbage). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Bộ 艸 chỉ thực vật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây rau tùng", "Hạng Tần Suất (Jun Da)": "5908.0", "Tần Suất % (Jun Da)": "99.9788138766", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 松", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹松", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "松", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菘", "Unihan_Traditional (Chữ Phồn thể)": "菘", "Pinyin_Xie": "sōng", "Âm Hán Việt_Xie": "tùng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại rau cải trong văn chương cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馇', '{"9000": "5909.0", "Chữ Trung Quốc": "馇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 12 | nét | 馇 | tra | tượng hình | khuấy đun (cám heo, cháo); nấu nhừ | 馇 có bộ 食 (thực, ăn/thức ăn) biểu nghĩa; phần còn lại gợi âm. Là chữ hình thanh chỉ hành động nấu bếp. Không có lsCodes.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tra\": bộ ăn (食) + tra — cảnh khuấy nồi cháo bốc khói trên bếp. | Gương Hán-Việt | tra (tra) — trong ngữ cảnh nấu cám heo hoặc cháo vùng phương ngữ bắc | Mở khoá kiến thức | Biết 馇 giúp đọc văn bản nông thôn phương bắc Trung Quốc về chăn nuôi và nấu nướng.", "Tự nguyên_Xie": "Không có dữ liệu Wiktionary cho 馇. Từ bộ 食 (thức ăn/ăn uống) suy đoán chữ hình thanh chỉ hành động khuấy và đun cám gia súc hoặc cháo. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khuấy; vừa khuấy vừa đun (cám heo, cám chó); hầm; nấu nhừ; nấu; ninh (cháo); tra; như \"tra (nấu; quấy)\"", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 查", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣查", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "查", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "馇", "Unihan_Traditional (Chữ Phồn thể)": "馇", "Pinyin_Xie": "chā", "Âm Hán Việt_Xie": "tra", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ mô tả hành động đun nấu và khuấy đều thức ăn hoặc cám. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('栌', '{"9000": "5910.0", "Chữ Trung Quốc": "栌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 栌 | lô | tượng hình | cây khói (smoke tree) hoặc đấu củng trong kiến trúc cổ | 栌 có bộ 木 (mộc, cây) biểu nghĩa và 卢 (lô) gợi âm. Là chữ hình thanh, giản thể của 櫨. Dùng cho tên cây và thuật ngữ kiến trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Lô\": bộ cây (木) + lô (卢) — cây lô hoặc khối gỗ lô đỡ mái đình. | Gương Hán-Việt | lô (lô) — trong \"黄栌\" (hoàng lô, cây khói vàng) và \"欂栌\" (bác lô, đấu củng) | Mở khoá kiến thức | Biết 栌 mở khoá thuật ngữ thực vật học và kiến trúc cổ: 黄栌 (cây khói), 欂栌 (đấu củng).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary (phồn thể 櫨): 栌 chỉ cây khói (Cotinus coggygria) và đấu củng (dougong) — khối gỗ đỡ trong kiến trúc Trung Hoa cổ. Chữ tạo muộn, có dạng tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hoàng lô 黃櫨,黄栌); (xem: bạc lô 欂櫨,欂栌)", "Hạng Tần Suất (Jun Da)": "5910.0", "Tần Suất % (Jun Da)": "99.9788789915", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 卢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木卢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "栌", "Unihan_Traditional (Chữ Phồn thể)": "櫨", "Pinyin_Xie": "lú", "Âm Hán Việt_Xie": "lô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ trong các từ ghép chỉ tên cây hoặc kết cấu kiến trúc cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醐', '{"9000": "5911.0", "Chữ Trung Quốc": "醐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 16 | nét | 醐 | hồ | tượng hình | tinh túy sữa — dùng trong 醍醐 | 醐 có bộ 酉 (dậu, rượu/lên men) biểu nghĩa và 胡 (hồ) gợi âm. Chỉ dùng trong từ 醍醐 (đề hồ, tinh sữa/bơ tinh khiết trong Phật giáo). Không có lsCodes.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Hồ\": bộ rượu/lên men (酉) + hồ — tinh sữa tinh khiết nhất như rượu lọc hoàn hảo. | Gương Hán-Việt | đề hồ (hồ) — trong \"醍醐灌顶\" (đề hồ quán đỉnh, khai sáng trí tuệ) | Mở khoá kiến thức | Biết 醐 mở khoá thành ngữ 醍醐灌顶 (khai sáng tâm trí) dùng rộng rãi trong tiếng Trung hiện đại.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary: 醐 chỉ xuất hiện trong từ 醍醐 — loại tinh sữa tinh khiết nhất trong Phật giáo Ấn Độ, biểu tượng cho trí tuệ hoàn toàn. Bộ 酉 gợi lên men, phần 胡 biểu âm. Có dạng tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đề hồ 醍醐)", "Hạng Tần Suất (Jun Da)": "5911.0", "Tần Suất % (Jun Da)": "99.978911549", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 胡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉胡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "胡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醐", "Unihan_Traditional (Chữ Phồn thể)": "醐", "Pinyin_Xie": "hú", "Âm Hán Việt_Xie": "hồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong từ ghép đề hồ để chỉ loại thực phẩm bổ dưỡng hoặc ẩn dụ cho Phật pháp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('唢', '{"9000": "5912.0", "Chữ Trung Quốc": "唢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 10 | nét | 唢 | toả | tượng hình | kèn tỏa (唢呐, nhạc cụ thổi) | 唢 có bộ 口 (khẩu, miệng) biểu nghĩa và 索 gợi âm. Là chữ hình thanh tạo muộn, chỉ dùng trong 唢呐 (kèn tỏa). Không có lsCodes.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Toả\": bộ miệng (口) + toả — nhạc cụ thổi miệng, tiếng kèn tỏa vang rộn ràng. | Gương Hán-Việt | toả nột (toả) — trong \"唢呐\" (kèn tỏa nột) | Mở khoá kiến thức | Biết 唢 mở khoá từ 唢呐 — nhạc cụ đặc trưng trong đám cưới và lễ hội truyền thống Trung Hoa.", "Tự nguyên_Xie": "Không có dữ liệu Wiktionary cho 唢. 唢 chỉ xuất hiện trong 唢呐 — nhạc cụ thổi bằng lưỡi gà, có nguồn gốc từ Trung Á, du nhập vào Trung Hoa qua con đường tơ lụa. Bộ 口 gợi nhạc cụ hơi. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: toả nột 嗩吶,唢吶)", "Hạng Tần Suất (Jun Da)": "5912.0", "Tần Suất % (Jun Da)": "99.9789441065", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "唢", "Unihan_Traditional (Chữ Phồn thể)": "嗩", "Pinyin_Xie": "suǒ", "Âm Hán Việt_Xie": "toả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trước chữ nột để tạo thành tên gọi của một loại kèn truyền thống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('獍', '{"9000": "5913.0", "Chữ Trung Quốc": "獍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 14 | nét | 犬 | khuyển | biểu nghĩa | chó, thú vật | 竟 | cánh | biểu âm | 獍 = 犬 (Khuyển, biểu nghĩa: chó/thú) + 竟 (Cánh, biểu âm). Chữ hình thanh chỉ loài thú huyền thoại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Kính\": thú (犬) rốt cuộc (竟) ăn mẹ — con thú bất hiếu nhất trong thần thoại. | Gương Hán-Việt | kính (kính) — trong \"枭獍\" (kiêu kính, những kẻ bất hiếu, tàn nhẫn) | Mở khoá kiến thức | Biết 獍 mở khoá từ 枭獍 trong văn chương ám chỉ người vô ơn, bất hiếu.", "Tự nguyên_Xie": "Wiktionary: 獍 là chữ hình thanh gồm 犬 (s, biểu nghĩa chó/thú) và 竟 (p, biểu âm). Chỉ loài thú huyền thoại trong văn học Trung Hoa cổ: sinh ra đã ăn thịt mẹ. Còn dùng chỉ hổ Mãn Châu. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con kính (một loài vật ăn thịt mẹ sau khi sinh)", "Hạng Tần Suất (Jun Da)": "5913.0", "Tần Suất % (Jun Da)": "99.9789766639", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 竟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭竟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "竟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "獍", "Unihan_Traditional (Chữ Phồn thể)": "獍", "Pinyin_Xie": "jìng", "Âm Hán Việt_Xie": "kính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn cổ để ví với kẻ bất hiếu hoặc tàn ác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('殳', '{"9000": "5914.0", "Chữ Trung Quốc": "殳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 殳 | Số nét | 4 | nét | 又 | hựu | biểu nghĩa | bàn tay | 𠘧 | biểu nghĩa | vật cầm, dụng cụ | 殳 là chữ hội ý hoặc tượng hình: bàn tay (又/Hựu) cầm dụng cụ (𠘧) giống búa — hành động đập. Sau đó mượn âm để chỉ loại kích tre cổ đại. Là bộ thủ số 79.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Thù\": bàn tay (又) cầm cán kích — thù (殳) là loại kích tre của chiến binh cổ đại. | Gương Hán-Việt | thù (thù) — bộ thủ 79, xuất hiện trong 段, 毁, 殴 | Mở khoá kiến thức | Nhận ra 殳 trong chữ giúp hiểu yếu tố \"đập/phá\" trong 毁 (huỷ), 殴 (đánh), 段 (đoạn).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Wiktionary: 殳 ban đầu là tượng hình hoặc hội ý — bàn tay cầm dụng cụ như búa. Gốc: hành động đập. Sau đó mượn âm chỉ loại kích làm bằng tre (halberd), một loại vũ khí cổ. Có dạng giáp cốt văn, kim văn và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "839.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kỷ (015) Hựu (018)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Kỷ (số 015 - cái bàn) ở trên bộ Hựu (số 018 - bàn tay/lại). Hình bàn tay (Hựu) cầm cái thù. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Thù là tên một thứ binh khí thời cổ, cán làm bằng gỗ tre.", "Nghĩa Tiếng Việt_Xie": "thù (binh khí)", "Hạng Tần Suất (Jun Da)": "5914.0", "Tần Suất % (Jun Da)": "99.9790092214", "GavinGrover_Once (Chiết tự trực tiếp)": "几 + 又", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱几又", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "又", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "几", "Unihan_Simplified (Chữ Giản thể)": "殳", "Unihan_Traditional (Chữ Phồn thể)": "殳", "Pinyin_Xie": "shū", "Âm Hán Việt_Xie": "thù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ vũ khí cổ hoặc dùng làm bộ thủ trong cấu tạo chữ Hán. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('仡', '{"9000": "5915.0", "Chữ Trung Quốc": "仡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 5 | nét | 仡 | ngật | tượng hình | dũng mãnh, cường tráng | 仡 có bộ 亻 (nhân, người) biểu nghĩa và 乞 gợi âm. Là chữ hình thanh chỉ phẩm chất con người. Không có lsCodes.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Ngật\": bộ người (亻) + ngật (乞) — người mạnh mẽ, dũng mãnh không cúi đầu. | Gương Hán-Việt | ngật ngật (ngật) — trong \"仡仡\" (ngật ngật, dũng cảm oai phong) | Mở khoá kiến thức | Biết 仡 giúp đọc từ 仡仡 trong thơ ca cổ tả hình tượng chiến binh.", "Tự nguyên_Xie": "Wiktionary chỉ có {{Han etym}} không chi tiết cho 仡. Từ cấu trúc 亻 + 乞 suy đoán là chữ hình thanh chỉ vẻ dũng mãnh. Dùng chủ yếu trong từ láy 仡仡 (ngật ngật, dũng mãnh). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ngật ngật 仡仡)", "Hạng Tần Suất (Jun Da)": "5915.0", "Tần Suất % (Jun Da)": "99.9790417789", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 乞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻乞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "仡", "Unihan_Traditional (Chữ Phồn thể)": "仡", "Pinyin_Xie": "gē", "Âm Hán Việt_Xie": "ngật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ mô tả vẻ dũng mãnh hoặc làm danh từ trong tên gọi dân tộc Ngật Lão. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('刿', '{"9000": "5916.0", "Chữ Trung Quốc": "刿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 8 | nét | 刿 | quế | tượng hình | rạch, cắt gây thương tích | 刿 có bộ 刀 (đao, dao) biểu nghĩa; phần còn lại gợi âm. Là chữ hình thanh chỉ hành động cắt/rạch. Phồn thể là 劌. Không có lsCodes.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Quế\": bộ dao (刀) + quế — lưỡi dao quế sắc bén, rạch vào da thịt. | Gương Hán-Việt | quế (quế) — trong \"劌目\" (quế mục, làm hại mắt), văn học cổ | Mở khoá kiến thức | Biết 刿 giúp đọc văn cổ về thương tích và chiến đấu, như tên nhân vật Tào Quế (曹刿).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ có {{Han etym}} cho phồn thể 劌. Từ cấu trúc 刀 (dao) suy đoán chữ hình thanh chỉ hành động cắt gây thương tích. Có dạng tiểu triện. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "làm hại; rạch, cắt", "Hạng Tần Suất (Jun Da)": "5916.0", "Tần Suất % (Jun Da)": "99.979106377", "GavinGrover_Once (Chiết tự trực tiếp)": "岁 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰岁刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "岁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "刿", "Unihan_Traditional (Chữ Phồn thể)": "劌", "Pinyin_Xie": "guì", "Âm Hán Việt_Xie": "quế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn ngôn để chỉ hành động cắt đứt hoặc gây thương tích. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葜', '{"9000": "5917.0", "Chữ Trung Quốc": "葜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葜 | khiếp | tượng hình | cây bạt kháp (Smilax china), dùng trị phong thấp | 葜 có bộ 艸 (thảo, cỏ/cây) biểu nghĩa. Chỉ dùng trong từ 菝葜 (bạt kháp). Không có lsCodes.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Khiếp\": bộ cỏ (艸) + khiếp — cây khiếp leo gai, rễ dùng trị đau xương. | Gương Hán-Việt | khiếp (khiếp) — trong \"菝葜\" (bạt khiếp, Smilax china) | Mở khoá kiến thức | Biết 葜 mở khoá tên dược liệu 菝葜 trong y học cổ truyền.", "Tự nguyên_Xie": "Wiktionary: 葜 chỉ xuất hiện trong 菝葜 — loài dây leo họ Kim cang (Smilax china), dùng trong đông y trị phong thấp và giải độc. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây bạt kháp (thuốc đông y, trị phong thấp hay giải độc)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 契", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹契", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "契", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葜", "Unihan_Traditional (Chữ Phồn thể)": "葜", "Pinyin_Xie": "qiā", "Âm Hán Việt_Xie": "khiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong y học cổ truyền để chỉ một loại cây làm thuốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薅', '{"9000": "5918.0", "Chữ Trung Quốc": "薅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 薅 | hao | tượng hình | nhổ cỏ; tóm, nắm chặt | 薅 có bộ 艸 (thảo, cỏ) biểu nghĩa và phần dưới liên quan hành động tay. Là chữ hội ý/hình thanh chỉ hành động nhổ cỏ. Không có lsCodes.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Hao\": bộ cỏ (艸) + hao — cúi xuống nhổ từng bụi cỏ hao công sức. | Gương Hán-Việt | hao (hao) — trong \"薅草\" (hao thảo, nhổ cỏ) | Mở khoá kiến thức | Biết 薅 giúp đọc văn bản nông nghiệp và khẩu ngữ hiện đại: 薅羊毛 (tóm/vắt sữa người khác).", "Tự nguyên_Xie": "Tiểu triện | Không có dữ liệu Wiktionary cho 薅. Từ bộ 艸 (cỏ) và cấu trúc suy đoán: nhổ cỏ bằng tay. Trong tiếng Trung hiện đại mở rộng nghĩa sang tóm/nắm. Có dạng tiểu triện. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhổ cỏ; tóm, tóm cổ", "Hạng Tần Suất (Jun Da)": "5918.0", "Tần Suất % (Jun Da)": "99.9791704584", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 媷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹媷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "媷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薅", "Unihan_Traditional (Chữ Phồn thể)": "薅", "Pinyin_Xie": "hāo", "Âm Hán Việt_Xie": "hao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ cỏ hoặc tóc để biểu thị hành động nhổ, giật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('湓', '{"9000": "5919.0", "Chữ Trung Quốc": "湓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 水 | thủy | biểu nghĩa | nước | 盆 | bồn | biểu âm | 湓 = 水/氵 (Thủy, biểu nghĩa: nước) + 盆 (Bồn, biểu âm). Chữ hình thanh — nước tràn như nước trong bồn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Bùn\": nước (水) tràn như bồn (盆) — sông Bùn tràn bờ, gợi cảnh lũ lụt. | Gương Hán-Việt | bùn (bùn) — trong \"湓水\" (sông Bùn, gần Cửu Giang) | Mở khoá kiến thức | Biết 湓 mở khoá địa danh 湓浦 trong bài thơ 琵琶行 của Bạch Cư Dị.", "Tự nguyên_Xie": "Wiktionary: 湓 là chữ hình thanh gồm 水 (s, nước) và 盆 (p, biểu âm). Nghĩa gốc: nước tràn, mưa rào. Cũng là tên sông (湓水) — nhánh sông Trường Giang gần Cửu Giang, nổi tiếng qua bài thơ 琵琶行 của Bạch Cư Dị. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Bồn", "Hạng Tần Suất (Jun Da)": "5919.0", "Tần Suất % (Jun Da)": "99.979202499", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 盆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵盆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "盆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "湓", "Unihan_Traditional (Chữ Phồn thể)": "湓", "Pinyin_Xie": "pén", "Âm Hán Việt_Xie": "bồn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ dòng nước phun trào hoặc làm danh từ riêng chỉ địa danh sông Bồn Giang. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('搴', '{"9000": "5920.0", "Chữ Trung Quốc": "搴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 14 | nét | 搴 | khiên | tượng hình | nhổ lên, kéo ra, đoạt lấy | 搴 có bộ 手/扌 (thủ, tay) biểu nghĩa ở dưới và phần trên gợi âm. Là chữ hình thanh chỉ hành động dùng tay nhổ/kéo. Không có lsCodes.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Khiên\": bộ tay (手) + khiên — tay mạnh kéo nhổ cờ địch khỏi đất. | Gương Hán-Việt | khiên (khiên) — trong \"搴旗\" (khiên kỳ, nhổ cờ địch) | Mở khoá kiến thức | Biết 搴 mở khoá thành ngữ 搴旗斬馘 (chiến thắng vẻ vang) trong văn học cổ.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary: 搴 nghĩa kéo nhổ ra, đoạt lấy, tuyển chọn. Có dạng tiểu triện. Xuất hiện trong thành ngữ 搴旗 (nhổ cờ địch) biểu thị chiến thắng. Không có thông tin cấu trúc chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhổ lên, kéo lên", "Hạng Tần Suất (Jun Da)": "5920.0", "Tần Suất % (Jun Da)": "99.9792345397", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 手", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱手", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "搴", "Unihan_Traditional (Chữ Phồn thể)": "搴", "Pinyin_Xie": "qiān", "Âm Hán Việt_Xie": "khiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết cổ để chỉ hành động nhổ cờ hoặc kéo vật gì đó lên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('尕', '{"9000": "5921.0", "Chữ Trung Quốc": "尕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 小 | Số nét | 5 | nét | 乃 | nãi | biểu nghĩa | vú, sữa mẹ | 小 | tiểu | biểu nghĩa | nhỏ | 尕 là chữ hội ý: 乃 (Nãi, vú/sữa mẹ) + 小 (Tiểu, nhỏ) — đứa trẻ còn bú mẹ = nhỏ bé. Chữ hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không có đọc chuẩn: vú mẹ (乃) + nhỏ (小) — đứa bé còn bú = cái gì rất nhỏ bé. | Gương Hán-Việt | cáp (cáp) — tên địa danh vùng tây bắc Trung Quốc | Mở khoá kiến thức | Biết 尕 giúp đọc địa danh tây bắc Trung Quốc như 尕海 (hồ nhỏ), 尕日根.", "Tự nguyên_Xie": "Wiktionary: 尕 là chữ hội ý gồm 乃 (vú, sữa mẹ) và 小 (nhỏ) — hình ảnh đứa trẻ còn bú mẹ, tức rất nhỏ. Dùng chủ yếu trong tên địa danh vùng Thanh Hải/Cam Túc và trong tiếng Tạng-Hán. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhỏ; bé; nhỏ bé", "Hạng Tần Suất (Jun Da)": "5921.0", "Tần Suất % (Jun Da)": "99.9792665804", "GavinGrover_Once (Chiết tự trực tiếp)": "乃 + 小", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱乃小", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "小", "Unihan_Simplified (Chữ Giản thể)": "尕", "Unihan_Traditional (Chữ Phồn thể)": "尕", "Pinyin_Xie": "gǎ", "Âm Hán Việt_Xie": "ca", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ chỉ sự nhỏ bé hoặc làm danh từ trong phương ngôn để gọi đứa trẻ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磴', '{"9000": "5922.0", "Chữ Trung Quốc": "磴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 17 | nét | 磴 | đặng | tượng hình | bậc đá trên vách núi | 磴 có bộ 石 (thạch, đá) biểu nghĩa và 登 (đặng) gợi âm. Là chữ hình thanh: bậc đá để leo núi. Không có lsCodes.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Đặng\": đá (石) + trèo (登) — những bậc đá giúp leo lên vách núi. | Gương Hán-Việt | đặng (đặng) — trong \"巖磴\" (nham đặng, bậc đá vách núi) | Mở khoá kiến thức | Biết 磴 giúp đọc văn thơ cổ tả phong cảnh núi non như 石磴 (thạch đặng).", "Tự nguyên_Xie": "Wiktionary chỉ có {{Han etym}} không chi tiết. Từ bộ 石 (đá) và âm đặng (登=trèo lên) suy đoán chữ hình thanh chỉ bậc đá trên vách núi hoặc vách đá dùng để leo trèo. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: nham đặng 巖磴)", "Hạng Tần Suất (Jun Da)": "5922.0", "Tần Suất % (Jun Da)": "99.9792986211", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 登", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石登", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "登", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磴", "Unihan_Traditional (Chữ Phồn thể)": "磴", "Pinyin_Xie": "dèng", "Âm Hán Việt_Xie": "đặng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ các bậc thang bằng đá trên núi hoặc lối đi dốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锝', '{"9000": "5923.0", "Chữ Trung Quốc": "锝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 锝 | đắc | tượng hình | nguyên tố technetium (Tc, số 43) | 锝 có bộ 钅/金 (kim, kim loại) biểu nghĩa và 得 (đắc) gợi âm. Là chữ hình thanh tạo muộn dùng trong hoá học hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Đắc\": bộ kim loại (金) + đắc (得) — nguyên tố kim loại \"đắc được\" qua tổng hợp nhân tạo. | Gương Hán-Việt | đắc (đắc) — ký hiệu Tc trong bảng tuần hoàn | Mở khoá kiến thức | Biết 锝 mở khoá tên nguyên tố phóng xạ trong hoá học và y học hạt nhân.", "Tự nguyên_Xie": "Không có dữ liệu Wiktionary cho 锝. Đây là chữ tạo muộn dùng để phiên âm technetium (Tc) — nguyên tố số 43, nguyên tố nhân tạo đầu tiên được tổng hợp (1937). Bộ 金 chỉ kim loại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tốc tecneti, Tc", "Hạng Tần Suất (Jun Da)": "5923.0", "Tần Suất % (Jun Da)": "99.9793306618", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 㝵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅㝵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㝵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锝", "Unihan_Traditional (Chữ Phồn thể)": "鍀", "Pinyin_Xie": "dé", "Âm Hán Việt_Xie": "đắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong hóa học để chỉ nguyên tố kim loại phóng xạ Tecneti. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镅', '{"9000": "5924.0", "Chữ Trung Quốc": "镅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 镅 | mỹ | tượng hình | nguyên tố americium (Am, số 95) | 镅 có bộ 钅/金 (kim, kim loại) biểu nghĩa và 眉 (mi/mỹ) gợi âm. Là chữ hình thanh tạo muộn dùng trong hoá học.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Mỹ\": bộ kim loại (金) + mỹ (眉) — nguyên tố mang tên châu Mỹ. | Gương Hán-Việt | mỹ (mỹ) — ký hiệu Am trong bảng tuần hoàn | Mở khoá kiến thức | Biết 镅 mở khoá tên nguyên tố phóng xạ trong hoá học hạt nhân và nghiên cứu vật lý.", "Tự nguyên_Xie": "Không có dữ liệu Wiktionary cho 镅. Đây là chữ tạo muộn dùng để phiên âm americium (Am) — nguyên tố số 95, đặt tên theo châu Mỹ. Bộ 金 chỉ kim loại phóng xạ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố amerixi, Am", "Hạng Tần Suất (Jun Da)": "5924.0", "Tần Suất % (Jun Da)": "99.9793627024", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 眉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅眉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "眉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镅", "Unihan_Traditional (Chữ Phồn thể)": "鎇", "Pinyin_Xie": "méi", "Âm Hán Việt_Xie": "my", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong hóa học để chỉ nguyên tố kim loại nhân tạo Americi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艚', '{"9000": "5925.0", "Chữ Trung Quốc": "艚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 17 | nét | 舟 | chu | biểu nghĩa | thuyền | 曹 | tào | biểu âm | 艚 = 舟 (Chu, biểu nghĩa: thuyền) + 曹 (Tào, biểu âm). Chữ hình thanh — thuyền chở lương thực thuế.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tàu\": thuyền (舟) + tào (曹) — thuyền tàu chở thóc thuế ngược sông. | Gương Hán-Việt | tàu (tàu) — từ 艚 mà tiếng Việt có \"tàu\" chỉ phương tiện vận tải lớn | Mở khoá kiến thức | Biết 艚 giúp hiểu từ nguyên của từ \"tàu\" trong tiếng Việt — mượn từ tiếng Hán.", "Tự nguyên_Xie": "Wiktionary: 艚 là chữ hình thanh gồm 舟 (s, thuyền) và 曹 (p, biểu âm). Nghĩa gốc: thuyền gỗ chở thóc thuế; mở rộng sang thuyền nhỏ nói chung. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thuyền gỗ chở hàng", "Hạng Tần Suất (Jun Da)": "5925.0", "Tần Suất % (Jun Da)": "99.9793947431", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 曹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟曹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艚", "Unihan_Traditional (Chữ Phồn thể)": "艚", "Pinyin_Xie": "cáo", "Âm Hán Việt_Xie": "tào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các loại thuyền gỗ nhỏ hoặc thuyền chở hàng thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('殄', '{"9000": "5926.0", "Chữ Trung Quốc": "殄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 歹 | Số nét | 9 | nét | 殄 | thiến | tượng hình | tiêu diệt, tuyệt diệt | 殄 có bộ 歹 (đãi, xương tàn, chết chóc) biểu nghĩa. Gốc ban đầu 𠂈 là hình dao/kiếm. Là chữ chỉ hành động tiêu diệt. Không có lsCodes.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Thiến\": bộ chết (歹) + thiến — tiêu diệt đến tận gốc, không còn một mảnh. | Gương Hán-Việt | thiến (thiến) — trong \"暴殄天物\" (bạo thiến thiên vật, phung phí của trời) | Mở khoá kiến thức | Biết 殄 mở khoá thành ngữ 暴殄天物 — phổ biến để phê phán sự lãng phí.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary: Dạng gốc của 殄 là 𠂈 — hình dao hoặc kiếm, nghĩa gốc tiêu diệt. Nổi bật trong thành ngữ 暴殄天物 (phung phí của trời ban). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hết, đứt", "Hạng Tần Suất (Jun Da)": "5926.0", "Tần Suất % (Jun Da)": "99.9794267838", "GavinGrover_Once (Chiết tự trực tiếp)": "歹 + 㐱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰歹㐱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "歹", "Unihan_Simplified (Chữ Giản thể)": "殄", "Unihan_Traditional (Chữ Phồn thể)": "殄", "Pinyin_Xie": "tiǎn", "Âm Hán Việt_Xie": "điển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ trong văn viết với nghĩa tiêu diệt tận gốc hoặc làm hao phí, hủy hoại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('暝', '{"9000": "5927.0", "Chữ Trung Quốc": "暝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 14 | nét | 日 | nhật | biểu nghĩa | mặt trời, ngày | 冥 | minh | biểu âm | 暝 = 日 (Nhật, biểu nghĩa: mặt trời/ngày) + 冥 (Minh, biểu âm). Chữ hình thanh — mặt trời khuất → tối tăm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Minh\": mặt trời (日) bị tối (冥) — ngày tắt xuống là đêm tối mịt. | Gương Hán-Việt | minh (minh) — trong \"暝色\" (minh sắc, màu tối của đêm) | Mở khoá kiến thức | Biết 暝 mở khoá từ 暝色 (bóng tối chiều tà) trong thơ cổ.", "Tự nguyên_Xie": "Wiktionary: 暝 là chữ hình thanh gồm 日 (s, mặt trời) và 冥 (p, biểu âm). Nghĩa gốc: tối tăm (đồng nghĩa 冥). Nghĩa thứ hai phổ biến trong tiếng Min: đêm/buổi tối (夜). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tối tăm", "Hạng Tần Suất (Jun Da)": "5927.0", "Tần Suất % (Jun Da)": "99.9794588245", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 冥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日冥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "暝", "Unihan_Traditional (Chữ Phồn thể)": "暝", "Pinyin_Xie": "míng", "Âm Hán Việt_Xie": "minh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ miêu tả cảnh trời tối hoặc làm danh từ chỉ buổi chập tối. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祢', '{"9000": "5928.0", "Chữ Trung Quốc": "祢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 9 | nét | 祢 | nễ | tượng hình | miếu thờ cha (bài vị cha trong đền thờ) | 祢 có bộ 示 (kỳ, thần/tế lễ) biểu nghĩa và 尔 (nhĩ) gợi âm. Là chữ hình thanh chỉ nơi thờ cúng. Phồn thể là 禰.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Nễ\": bộ thần/tế (示) + nễ (尔) — bàn thờ nhỏ thờ cha trong gian thờ gia đình. | Gương Hán-Việt | nễ (nễ) — trong \"祢庙\" (nễ miếu, miếu thờ cha) | Mở khoá kiến thức | Biết 祢 giúp đọc văn bản lễ nghi gia tộc và sử sách về đền thờ cúng Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary cho 祢 là dạng shinjitai (Nhật) của 禰. Nghĩa: miếu thờ (shrine/mausoleum). Trong tiếng Hán cổ, 祢 chỉ miếu nhỏ thờ cha trong đền thờ gia tộc. Cũng là họ người (Mi/Nể). Có dạng tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "miếu thờ cha", "Hạng Tần Suất (Jun Da)": "5928.0", "Tần Suất % (Jun Da)": "99.9794908651", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 尔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻尔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祢", "Unihan_Traditional (Chữ Phồn thể)": "祢", "Pinyin_Xie": "mí", "Âm Hán Việt_Xie": "nỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong tế lễ cổ đại để chỉ bài vị hoặc miếu thờ người cha đã khuất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豉', '{"9000": "5929.0", "Chữ Trung Quốc": "豉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豆 | Số nét | 11 | nét | 豆 | đậu | biểu nghĩa | đậu, hạt đậu | 支 | chi | biểu âm | 豉 = 豆 (Đậu, biểu nghĩa: đậu/hạt đậu) + 支 (Chi, biểu âm). Chữ hình thanh — đậu lên men.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Xị\": bộ đậu (豆) + chi (支) — đậu tương lên men thành xị đen thơm nồng. | Gương Hán-Việt | đậu xị (xị) — trong \"豆豉\" (đậu xị, tương đậu lên men) | Mở khoá kiến thức | Biết 豉 mở khoá từ 豆豉 (đậu xị) — gia vị quan trọng trong ẩm thực Trung Hoa và Việt Nam.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary: 豉 là chữ hình thanh gồm 豆 (s, đậu) và 支 (p, biểu âm). Dạng chuẩn trong Thuyết Văn là 𢻃 (có 尗 thay vì 豆). Nghĩa: đậu thị — đậu tương lên men, gia vị truyền thống. Có dạng đại triện và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đậu thị", "Hạng Tần Suất (Jun Da)": "5929.0", "Tần Suất % (Jun Da)": "99.9795229058", "GavinGrover_Once (Chiết tự trực tiếp)": "豆 + 支", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豆支", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "支", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豆", "Unihan_Simplified (Chữ Giản thể)": "豉", "Unihan_Traditional (Chữ Phồn thể)": "豉", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ hạt đậu nành đã lên men dùng làm gia vị. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垴', '{"9000": "5930.0", "Chữ Trung Quốc": "垴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 9 | nét | 土 | thổ | biểu nghĩa | đất, địa hình | 𡿺 | biểu âm | 垴 = 土 (Thổ, biểu nghĩa: đất) + 𡿺 (biểu âm, thành phần ít gặp). Chữ hình thanh chỉ đồi đất nhỏ, dùng chủ yếu trong địa danh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Não\": đất (土) nhô lên như đầu (脑) người — gò đất tròn nhỏ như cái đầu. | Gương Hán-Việt | não (não) — trong tên địa danh vùng Sơn Tây, Hà Bắc | Mở khoá kiến thức | Biết 垴 giúp đọc địa danh miền bắc Trung Quốc: 北垴, 南垴, 马垴等.", "Tự nguyên_Xie": "Wiktionary (phồn thể 堖): chữ hình thanh gồm 土 (s, đất) và 𡿺 (p, biểu âm, không có oc). Chỉ gò đất hoặc đồi nhỏ hình đầu người, thường dùng trong tên núi/địa danh. Chữ tạo muộn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "núi nhỏ; đồi nhỏ (thường dùng làm tên núi)", "Hạng Tần Suất (Jun Da)": "5930.0", "Tần Suất % (Jun Da)": "99.9795549465", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "垴", "Unihan_Traditional (Chữ Phồn thể)": "堖", "Pinyin_Xie": "nǎo", "Âm Hán Việt_Xie": "não", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong phương ngôn miền Bắc Trung Quốc để chỉ gò đất hoặc đặt tên địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瓿', '{"9000": "5931.0", "Chữ Trung Quốc": "瓿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 瓦 | Số nét | 12 | nét | 瓿 | bộ | tượng hình | cái vò nhỏ đựng đồ | 瓿 là chữ chỉ loại vò gốm nhỏ. Wiktionary không cung cấp thông tin phân tích bộ phận rõ ràng; chữ tạo muộn, chưa thấy phân tích hội ý hay hình thanh trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bộ\": cái vò nhỏ — hình dáng tròn như bộ (phần, khúc) của đồ gốm cổ. | Gương Hán-Việt | bộ (瓿) — ít dùng độc lập; thường trong 覆瓿 (phủ bộ: dùng vò nhỏ làm vật vô dụng, ý nói tác phẩm kém). | Mở khoá kiến thức | Biết 瓿 (bộ) giúp hiểu thành ngữ 覆醬瓿 (dùng sách làm vật đậy vò tương, tức tác phẩm không giá trị).", "Tự nguyên_Xie": "Tiểu triện | 瓿 chỉ loại bình/vò nhỏ bằng gốm thời cổ đại Trung Quốc. Chữ tạo muộn, chỉ còn thấy hình dạng tiểu triện. Không có phân tích nguồn gốc học thuật rõ ràng từ Wiktionary — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái vò nhỏ", "Hạng Tần Suất (Jun Da)": "5931.0", "Tần Suất % (Jun Da)": "99.9796185111", "GavinGrover_Once (Chiết tự trực tiếp)": "咅 + 瓦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰咅瓦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "瓦", "Unihan_Simplified (Chữ Giản thể)": "瓿", "Unihan_Traditional (Chữ Phồn thể)": "瓿", "Pinyin_Xie": "bù", "Âm Hán Việt_Xie": "bẫu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loại bình, vò nhỏ bằng đất nung hoặc đồng thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('煺', '{"9000": "5932.0", "Chữ Trung Quốc": "煺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 13 | nét | 煺 | thối | tượng hình | nhổ lông gia súc bằng nước sôi | 煺 không có phân tích bộ phận rõ trong nguồn anchor. Chữ tạo muộn, chưa thấy phân tích hình thanh hay hội ý trong giáp cốt hay kim văn — chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thối\": dùng lửa/nước nóng (火) làm thối mềm da để nhổ lông — quy trình làm thịt lợn, gà. | Gương Hán-Việt | thối (煺) — ít dùng trong văn Hán-Việt hiện đại; chủ yếu dùng trong ngữ cảnh chăn nuôi/ẩm thực. | Mở khoá kiến thức | Biết 煺 (thối) giúp hiểu từ chuyên ngành chế biến thực phẩm: 煺毛 (nhổ lông), 煺豬 (cạo lông lợn).", "Tự nguyên_Xie": "煺 chỉ hành động nhổ lông, vặt lông, cạo lông gia súc (thường dùng nước sôi để làm mềm). Không có nguồn Wiktionary về nguồn gốc chữ viết — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhổ lông, vặt lông, cạo lông, làm lông", "Hạng Tần Suất (Jun Da)": "5932.0", "Tần Suất % (Jun Da)": "99.979650035", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 退", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火退", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "退", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "煺", "Unihan_Traditional (Chữ Phồn thể)": "煺", "Pinyin_Xie": "tuì", "Âm Hán Việt_Xie": "thoái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ động vật để biểu thị việc nhúng nước sôi rồi làm sạch lông. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟥', '{"9000": "5933.0", "Chữ Trung Quốc": "蟥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 17 | nét | 蟥 | hoàng | tượng hình | con đỉa, sinh vật sống ở nước | 蟥 là chữ chỉ loài đỉa. Wiktionary chỉ ghi dùng trong 螞蟥 (con đỉa), không phân tích bộ phận cụ thể. Từ cấu tạo có thể thấy: bộ 虫 (trùng) + phần âm 黃 (hoàng) — hình thanh theo nghĩa; chữ tạo muộn không có giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàng\": con đỉa (螞蟥) — con trùng (虫) màu vàng nâu (hoàng) sống dưới nước, hút máu người. | Gương Hán-Việt | hoàng (蟥) trong 螞蟥 (mã hoàng: con đỉa), 石蟥. | Mở khoá kiến thức | Biết 蟥 (hoàng) giúp nhận ra 螞蟥 (con đỉa) — sinh vật quen thuộc ở ruộng nước Việt Nam.", "Tự nguyên_Xie": "Tiểu triện | 蟥 dùng trong 螞蟥 (con đỉa), 馬蟥 (đỉa ngựa/đỉa lớn). Wiktionary không cung cấp phân tích nguồn gốc chi tiết. Có thể là chữ hình thanh: bộ 虫 (sâu bọ, trùng) cho nghĩa + 黃 cho âm đọc. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con đỉa cộ", "Hạng Tần Suất (Jun Da)": "5933.0", "Tần Suất % (Jun Da)": "99.9796815589", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 黄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫黄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "黄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟥", "Unihan_Traditional (Chữ Phồn thể)": "蟥", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các từ ghép để chỉ các loài đỉa hoặc côn trùng hút máu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹀', '{"9000": "5934.0", "Chữ Trung Quốc": "蹀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 16 | nét | 足 | túc | biểu nghĩa | bàn chân | 枼 | điệp | biểu âm | 蹀 = 足 (Túc, biểu nghĩa: chân) + 枼 (Điệp, biểu âm). Chữ hình thanh: 足 cho biết liên quan đến chân/bước đi, 枼 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệp\": bàn chân (足) giẫm điệp (lặp đi lặp lại) từng bước nhỏ — như trong 蹀躞 bước chân lúng túng. | Gương Hán-Việt | điệp (蹀) trong 蹀躞 (điệp tiết: bước đi nhỏ, lúng túng). | Mở khoá kiến thức | Biết 蹀 (điệp) giúp hiểu cụm 蹀躞不下 (không sao ngồi yên được, bồn chồn).", "Tự nguyên_Xie": "蹀 là chữ hình thanh: 足 (chân) biểu nghĩa, 枼 biểu âm. Nghĩa gốc là ''giậm chân, giẫm đạp''. Thường dùng trong 蹀躞 (bước đi ngắn, lúng túng) hay 踥蹀 (bước đi khẽ khàng). Wiktionary xác nhận cấu trúc psc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giẫm, xéo", "Hạng Tần Suất (Jun Da)": "5934.0", "Tần Suất % (Jun Da)": "99.9797130828", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 枼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊枼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "枼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹀", "Unihan_Traditional (Chữ Phồn thể)": "蹀", "Pinyin_Xie": "dié", "Âm Hán Việt_Xie": "điệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn ngôn hoặc dùng trong từ láy để tả dáng đi lững thững. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黼', '{"9000": "5935.0", "Chữ Trung Quốc": "黼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黹 | Số nét | 19 | nét | 黼 | phủ | tượng hình | hoa văn đen trắng trên áo lễ phục | 黼 là chữ chỉ hoa văn đặc biệt trên lễ phục hoàng đế thời cổ — hoa văn hình rìu màu đen trắng. Wiktionary không cung cấp phân tích bộ phận. Chữ tạo muộn, chỉ còn hình dạng tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phủ\": hoa văn áo phủ (áo che) của vua — hình rìu đen trắng trên lễ phục thiên tử. | Gương Hán-Việt | phủ (黼) trong 黼黻 (phủ phất: hoa văn lễ phục hoàng đế), 黼繡 (thêu phủ). | Mở khoá kiến thức | Biết 黼 (phủ) giúp hiểu mỹ thuật cung đình Trung Quốc cổ đại: 黼黻 là hai loại hoa văn trang trí lễ phục hoàng tộc.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | 黼 chỉ loại hoa văn hình rìu đen-trắng thêu trên áo lễ phục của thiên tử thời cổ đại. Thường đi kèm với 黻 (hoa văn hai chữ 弓 lồng nhau). Thấy trong giáp cốt văn, kim văn. Wiktionary không cung cấp phân tích nguồn gốc chữ viết rõ ràng — chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo lễ phục", "Hạng Tần Suất (Jun Da)": "5935.0", "Tần Suất % (Jun Da)": "99.9797761305", "GavinGrover_Once (Chiết tự trực tiếp)": "黹 + 甫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰黹甫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黹", "Unihan_Simplified (Chữ Giản thể)": "黼", "Unihan_Traditional (Chữ Phồn thể)": "黼", "Pinyin_Xie": "fǔ", "Âm Hán Việt_Xie": "phủ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn cổ để chỉ trang phục tế lễ của vua chúa thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氙', '{"9000": "5936.0", "Chữ Trung Quốc": "氙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 气 | Số nét | 7 | nét | 气 | khí | biểu nghĩa | khí, hơi | 山 | sơn | biểu âm | núi (rút gọn từ 仙) | 氙 = 气 (Khí, biểu nghĩa: khí/hơi) + 山 (Sơn, biểu âm rút gọn từ 仙 Tiên). Chữ hình thanh tạo mới để phiên âm nguyên tố xenon: 气 chỉ đây là khí, 山 (từ 仙) cho âm xian.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiên\": khí (气) của các tiên (仙) — xenon là khí quý hiếm, nhẹ như tiên, không phản ứng với ai. | Gương Hán-Việt | tiên (氙) — chỉ dùng trong danh pháp hoá học: 氙气 (khí xenon), 氙灯 (đèn xenon). | Mở khoá kiến thức | Biết 氙 (tiên) giúp nhận ra tên các khí quý trong tiếng Trung: 氦氖氩氪氙氡 (heli, neon, argon, krypton, xenon, radon).", "Tự nguyên_Xie": "氙 là chữ tạo mới trong thế kỷ 20 để phiên âm nguyên tố xenon (Xe, số 54). Cấu trúc hình thanh: 气 (khí) biểu nghĩa + 山 biểu âm, trong đó 山 là rút gọn từ 仙 (tiên). Wiktionary xác nhận thanh phù là 仙 viết tắt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố xenon, khí xenon, Xe", "Hạng Tần Suất (Jun Da)": "5936.0", "Tần Suất % (Jun Da)": "99.9798076544", "GavinGrover_Once (Chiết tự trực tiếp)": "气 + 山", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴气山", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "山", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "气", "Unihan_Simplified (Chữ Giản thể)": "氙", "Unihan_Traditional (Chữ Phồn thể)": "氙", "Pinyin_Xie": "xiān", "Âm Hán Việt_Xie": "tiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng một mình hoặc kết hợp trong các thuật ngữ hóa học, vật lý. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铑', '{"9000": "5937.0", "Chữ Trung Quốc": "铑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 金 | kim | biểu nghĩa | kim loại | 老 | lão | biểu âm | già | 铑 = 金 (Kim, biểu nghĩa: kim loại) + 老 (Lão, biểu âm). Chữ hình thanh tạo mới: 金 chỉ đây là kim loại, 老 cho âm đọc lǎo/lão.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lão\": kim loại (金) quý như bậc lão (老) — rhodium là kim loại quý hiếm nhất, đắt hơn cả vàng bạch kim. | Gương Hán-Việt | lão (铑) — chỉ dùng trong danh pháp hoá học; không có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 铑 (lão) giúp nhận ra cách Trung Quốc phiên âm kim loại quý: 铑 (rhodium), 铂 (bạch kim/platinum), 钯 (palladium).", "Tự nguyên_Xie": "铑 là chữ tạo mới để phiên âm nguyên tố rhodium (Rh, số 45). Cấu trúc hình thanh: 金 (kim loại) biểu nghĩa + 老 biểu âm. Wiktionary xác nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố rôdi, Rh", "Hạng Tần Suất (Jun Da)": "5937.0", "Tần Suất % (Jun Da)": "99.9798391783", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 老", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅老", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "老", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铑", "Unihan_Traditional (Chữ Phồn thể)": "銠", "Pinyin_Xie": "lǎo", "Âm Hán Việt_Xie": "lão", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ nguyên tố hóa học trong bảng tuần hoàn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒡', '{"9000": "5938.0", "Chữ Trung Quốc": "蒡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 艸 | thảo | biểu nghĩa | cỏ, thực vật | 旁 | bàng | biểu âm | bên cạnh | 蒡 = 艸 (Thảo, biểu nghĩa: cỏ, cây) + 旁 (Bàng, biểu âm). Chữ hình thanh: 艸 chỉ đây là thực vật, 旁 cho âm đọc bàng/bảng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bảng\": cây cỏ (艸) bên cạnh (旁) bò (牛) — cây ngưu bảng (牛蒡) mọc cạnh trâu bò ở đồng quê. | Gương Hán-Việt | bảng (蒡) trong 牛蒡 (ngưu bảng: cây burdock, rau củ phổ biến trong ẩm thực Nhật-Hàn). | Mở khoá kiến thức | Biết 蒡 (bảng) giúp nhận ra 牛蒡 — rau củ thảo dược phổ biến trong y học cổ truyền và ẩm thực Đông Á.", "Tự nguyên_Xie": "蒡 là chữ hình thanh: 艸 (thực vật) biểu nghĩa, 旁 biểu âm. Dùng chủ yếu trong 牛蒡 (ngưu bảng — cây ngưu bàng, tên khoa học Arctium lappa), một loại thảo dược và rau củ. Wiktionary xác nhận cấu trúc psc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ngưu bảng 牛蒡)", "Hạng Tần Suất (Jun Da)": "5938.0", "Tần Suất % (Jun Da)": "99.9799332332", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 旁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹旁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒡", "Unihan_Traditional (Chữ Phồn thể)": "蒡", "Pinyin_Xie": "bàng", "Âm Hán Việt_Xie": "bảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ và hầu như chỉ xuất hiện trong từ ghép ngưu bàng để chỉ một loại cây thuốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('杪', '{"9000": "5939.0", "Chữ Trung Quốc": "杪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 8 | nét | 杪 | miểu | tượng hình | ngọn cây, đầu cành nhỏ | 杪 có bộ 木 (mộc: cây) là thành phần nghĩa, phần còn lại biểu âm. Wiktionary không cung cấp phân tích bộ phận cụ thể. Nghĩa là đầu ngọn cây, cành nhỏ — gợi ý phần cực nhỏ của cây.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miểu\": đầu ngọn cây (木) mỏng manh như sợi tóc — miểu (nhỏ tí, cuối cùng); như 月杪 là cuối tháng. | Gương Hán-Việt | miểu (杪) trong 月杪 (nguyệt miểu: cuối tháng), 歲杪 (tuế miểu: cuối năm). | Mở khoá kiến thức | Biết 杪 (miểu) giúp đọc văn ngôn cổ điển: 杪秋 (cuối thu), 月杪 (cuối tháng), 歲杪 (cuối năm).", "Tự nguyên_Xie": "Tiểu triện | 杪 theo Wiktionary là chữ chỉ ngọn cành cây nhỏ, đầu cành. Mở rộng thành: cuối tháng/năm/mùa, và tính từ ''nhỏ nhoi, li ti''. Không có phân tích nguồn gốc chữ viết rõ ràng — chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cánh nhỏ", "Hạng Tần Suất (Jun Da)": "5939.0", "Tần Suất % (Jun Da)": "99.9799642403", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 少", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木少", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "少", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "杪", "Unihan_Traditional (Chữ Phồn thể)": "杪", "Pinyin_Xie": "miǎo", "Âm Hán Việt_Xie": "diểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ phần ngọn của cây cối hoặc phần cuối của một khoảng thời gian. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肜', '{"9000": "5940.0", "Chữ Trung Quốc": "肜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 7 | nét | 肜 | dong | tượng hình | nghi lễ tế tự thời Ân Thương | 肜 là chữ chỉ một nghi thức tế lễ cổ đại (肜祭). Wiktionary không cung cấp phân tích bộ phận. Chữ tạo muộn hoặc ít thấy trong giáp cốt/kim văn với phân tích rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dong\": nghi lễ tế tự (肜祭) — lễ dong (tiếp tục) ngày hôm sau của tế lễ chính, kéo dài sự tôn kính. | Gương Hán-Việt | dong (肜) trong 肜祭 (dong tế: tế ngày hôm sau), 肜日 (dong nhật). | Mở khoá kiến thức | Biết 肜 (dong) giúp đọc giáp cốt văn và thư tịch cổ đại về nghi lễ Ân Thương.", "Tự nguyên_Xie": "肜 chỉ một loại tế lễ cổ đại thời Ân Thương — tế vào ngày hôm sau (肜日) sau ngày lễ chính. Thấy trong 肜夕, 肜日, 肜祭. Wiktionary ghi rfdef (chưa có định nghĩa rõ ràng). Chưa có nguồn học thuật giải thích nguồn gốc chữ viết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tế dung (cách cúng tế thời xưa)", "Hạng Tần Suất (Jun Da)": "5940.0", "Tần Suất % (Jun Da)": "99.9799952474", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 彡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月彡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "肜", "Unihan_Traditional (Chữ Phồn thể)": "肜", "Pinyin_Xie": "róng", "Âm Hán Việt_Xie": "dung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ hoặc động từ trong văn cổ chỉ nghi lễ cúng tế thời nhà Thương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膂', '{"9000": "5941.0", "Chữ Trung Quốc": "膂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 14 | nét | 膂 | lữ | tượng hình | xương sống, cột sống | 膂 là chữ chỉ xương sống (cột sống). Không có phân tích nguồn gốc từ Wiktionary. Chữ tạo muộn, chỉ còn thấy hình dạng tiểu triện và lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lữ\": xương sống (膂力: sức lực cột sống) — người có lữ lực mạnh là người có thể lực cường tráng. | Gương Hán-Việt | lữ (膂) trong 膂力 (lữ lực: sức mạnh thể chất), 脊膂 (tích lữ: cột sống). | Mở khoá kiến thức | Biết 膂 (lữ) giúp đọc văn ngôn về thể lực: 膂力過人 (lữ lực hơn người — sức mạnh phi thường).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 膂 chỉ xương sống (脊膂). Không có phân tích nguồn gốc Wiktionary. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xương sống", "Hạng Tần Suất (Jun Da)": "5941.0", "Tần Suất % (Jun Da)": "99.9800262545", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 月", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "膂", "Unihan_Traditional (Chữ Phồn thể)": "膂", "Pinyin_Xie": "lǚ", "Âm Hán Việt_Xie": "lữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ trong văn viết cổ hoặc kết hợp thành từ ghép như lữ lực để chỉ sức lực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砬', '{"9000": "5942.0", "Chữ Trung Quốc": "砬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 10 | nét | 砬 | lạp | tượng hình | tên địa danh, đá (thường dùng trong tên đất vùng Đông Bắc Trung Quốc) | 砬 có bộ 石 (thạch: đá) là thành phần nghĩa. Wiktionary không cung cấp phân tích bộ phận cụ thể. Chủ yếu dùng trong tên địa danh vùng Đông Bắc Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạp\": đá (石) lạp lạp (thô ráp, gồ ghề) — tên địa danh chỉ vùng địa hình đá lởm chởm ở Đông Bắc Trung Quốc. | Gương Hán-Việt | lạp (砬) ít dùng độc lập; thường trong tên địa danh: 紅石砬, 砬子. | Mở khoá kiến thức | Biết 砬 (lạp) giúp đọc tên địa danh vùng Đông Bắc Trung Quốc và Triều Tiên.", "Tự nguyên_Xie": "砬 chủ yếu dùng trong tên địa danh như 紅石砬 (Hồng Thạch Lạp) ở Hà Bắc, Trung Quốc. Wiktionary ghi rfdef (chưa có định nghĩa rõ ràng). Bộ 石 gợi ý liên quan đến đá/địa hình đá. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Lạp (thường dùng làm tên đất như Hồng Thạch Lạp (红石砬) ở tỉnh Hà Bắc của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "5942.0", "Tần Suất % (Jun Da)": "99.9800572617", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 立", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石立", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "立", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砬", "Unihan_Traditional (Chữ Phồn thể)": "砬", "Pinyin_Xie": "lá", "Âm Hán Việt_Xie": "lạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ trong địa danh hoặc để chỉ các tảng đá lớn nhô ra. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硭', '{"9000": "5943.0", "Chữ Trung Quốc": "硭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 11 | nét | 石 | thạch | biểu nghĩa | đá, khoáng chất | 芒 | mang | biểu âm | 硭 = 石 (Thạch, biểu nghĩa: đá, khoáng chất) + 芒 (Mang, biểu âm). Chữ hình thanh: 石 chỉ đây là chất khoáng, 芒 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mang\": đá (石) có vị mang (cay nóng) — mang tiêu (硭硝) là muối khoáng dùng trong đông y. | Gương Hán-Việt | mang (硭) trong 硭硝 (mang tiêu: natri sulfat, vị thuốc nhuận tràng trong đông y). | Mở khoá kiến thức | Biết 硭 (mang) giúp nhận ra 硭硝 — tên dược liệu đông y quen thuộc trong bài thuốc táo bón, thanh nhiệt.", "Tự nguyên_Xie": "硭 là chữ hình thanh: 石 (khoáng chất) biểu nghĩa, 芒 biểu âm. Dùng chủ yếu trong 硭硝 (mang tiêu — natri sulfat Na₂SO₄, vị thuốc đông y). Wiktionary xác nhận cấu trúc psc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mang tiêu 硭硝)", "Hạng Tần Suất (Jun Da)": "5943.0", "Tần Suất % (Jun Da)": "99.9800882688", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 芒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石芒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "芒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硭", "Unihan_Traditional (Chữ Phồn thể)": "硭", "Pinyin_Xie": "máng", "Âm Hán Việt_Xie": "mang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong thuật ngữ hóa học hoặc đông y như mang tiêu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酽', '{"9000": "5944.0", "Chữ Trung Quốc": "酽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 14 | nét | 酽 | nghiễm | tượng hình | chất lỏng đặc, rượu chua đậm | 酽 là giản thể của 釅. Cấu trúc: bộ 酉 (dậu: bình rượu, lên men) + 严 (nghiêm: biểu âm). Chữ hình thanh chỉ chất lỏng lên men đậm đặc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghiễm\": bình rượu (酉) đặc nghiêm (严) — chất lỏng lên men đặc sánh như giấm đặc hay tương chua. | Gương Hán-Việt | nghiễm (酽) ít dùng độc lập; chỉ chất lỏng đặc trong văn ngôn. | Mở khoá kiến thức | Biết 酽 (nghiễm) giúp đọc văn ngôn miêu tả thức uống/dung dịch đặc: 酽茶 (trà đặc), 酽醋 (giấm đặc).", "Tự nguyên_Xie": "酽 là chữ giản thể của 釅 (nghiễm), theo Wiktionary: ''{{Han simp|釅|f=嚴|t=严}}''. Nghĩa là tương chua, giấm đặc; chất lỏng đặc sánh. Bộ 酉 liên quan đến lên men/rượu giấm. Âm phần từ 嚴/严 (nghiêm). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tương chua, giấm; chất lỏng đặc", "Hạng Tần Suất (Jun Da)": "5944.0", "Tần Suất % (Jun Da)": "99.9801192759", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 严", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉严", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "严", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酽", "Unihan_Traditional (Chữ Phồn thể)": "釅", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "nghiệm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ bổ nghĩa cho các loại đồ uống có độ đậm đặc cao như trà hay rượu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踟', '{"9000": "5945.0", "Chữ Trung Quốc": "踟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 15 | nét | 足 | túc | biểu nghĩa | bàn chân, đi lại | 知 | tri | biểu âm | biết | 踟 = 足 (Túc, biểu nghĩa: chân) + 知 (Tri, biểu âm). Chữ hình thanh: 足 liên quan đến bước đi, 知 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trì\": chân (足) muốn biết (知) nên đi hay không — bước chân trì hoãn, lưỡng lự không tiến. | Gương Hán-Việt | trì (踟) trong 踟躇 (trì trù: do dự, lưỡng lự). | Mở khoá kiến thức | Biết 踟 (trì) giúp hiểu cụm 踟躕不前 (trì trù bất tiền: do dự không tiến).", "Tự nguyên_Xie": "Lục thư thông | 踟 là chữ hình thanh: 足 (chân) biểu nghĩa, 知 biểu âm. Nghĩa là ''đi lui đi tới, lưỡng lự''. Dùng chủ yếu trong 踟躇/踟躕 (trì trù: do dự, lưỡng lự). Wiktionary xác nhận cấu trúc psc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: trì trù 踟躊)", "Hạng Tần Suất (Jun Da)": "5945.0", "Tần Suất % (Jun Da)": "99.980150283", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 知", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊知", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "知", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踟", "Unihan_Traditional (Chữ Phồn thể)": "踟", "Pinyin_Xie": "chí", "Âm Hán Việt_Xie": "trì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ và thường kết hợp với chữ trù tạo thành từ láy trì trù để chỉ sự do dự. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲷', '{"9000": "5946.0", "Chữ Trung Quốc": "鲷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 魚 | ngư | biểu nghĩa | cá | 周 | chu | biểu âm | xung quanh, tuần hoàn | 鲷 = 魚 (Ngư, biểu nghĩa: cá) + 周 (Chu, biểu âm). Chữ hình thanh: 魚 chỉ đây là loài cá, 周 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điêu\": cá (魚) điêu — cá điêu hồng (cá rô phi lai) quen thuộc với người Việt, cũng là cá biển cao cấp trong ẩm thực Nhật. | Gương Hán-Việt | điêu (鲷) trong 真鯛 (chân điêu: cá tai đỏ/red snapper), 黑鯛 (hắc điêu). | Mở khoá kiến thức | Biết 鲷 (điêu) giúp nhận ra các loài cá điêu trong thực đơn Nhật-Trung: 真鯛, 黑鯛, 雀鯛.", "Tự nguyên_Xie": "Tiểu triện | 鲷 là chữ hình thanh: 魚 (cá) biểu nghĩa, 周 biểu âm. Chỉ loài cá điêu (sea bream, họ Sparidae), loài cá biển có thân dẹt màu hồng bạc. Wiktionary xác nhận cấu trúc psc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con cá điêu", "Hạng Tần Suất (Jun Da)": "5946.0", "Tần Suất % (Jun Da)": "99.9801812901", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 周", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼周", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "周", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲷", "Unihan_Traditional (Chữ Phồn thể)": "鯛", "Pinyin_Xie": "diāo", "Âm Hán Việt_Xie": "điêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng độc lập hoặc làm thành phần cấu tạo tên các loài cá tráp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒴', '{"9000": "5947.0", "Chữ Trung Quốc": "蒴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蒴 | sóc | tượng hình | vỏ hạt dạng nang (capsule thực vật học) | 蒴 có bộ 艸 (thảo: cỏ/thực vật) là thành phần nghĩa. Wiktionary không cung cấp phân tích bộ phận cụ thể. Là thuật ngữ thực vật học chỉ loại quả nang (capsule).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sóc\": quả nang (蒴果) — như vỏ sóc gai chứa hạt bên trong, tách ra khi chín. | Gương Hán-Việt | sóc (蒴) trong 蒴果 (sóc quả: quả nang), 孢蒴 (bào sóc: hộp bào tử rêu). | Mở khoá kiến thức | Biết 蒴 (sóc) giúp đọc tài liệu thực vật học: 蒴果 (quả nang) là loại quả của bông vải, mào gà, lanh.", "Tự nguyên_Xie": "蒴 là thuật ngữ thực vật học chỉ loại quả nang (capsule): dạng quả khô, khi chín tách mở để phát tán hạt. Wiktionary xác nhận nghĩa là ''capsule'' trong thực vật học. Không có phân tích nguồn gốc chữ viết chi tiết — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vỏ hạt", "Hạng Tần Suất (Jun Da)": "5947.0", "Tần Suất % (Jun Da)": "99.9802122972", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 朔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹朔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒴", "Unihan_Traditional (Chữ Phồn thể)": "蒴", "Pinyin_Xie": "shuò", "Âm Hán Việt_Xie": "sóc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ trong thực vật học để chỉ loại quả tự nứt khi chín. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藁', '{"9000": "5948.0", "Chữ Trung Quốc": "藁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 17 | nét | 藁 | cảo | tượng hình | rơm rạ, cây khô | 藁 có bộ 艸 (thảo: cỏ/cây) là thành phần nghĩa. Wiktionary ghi là dạng cổ của 稿 (bản thảo/rơm) và 槁 (héo khô). Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cảo\": cỏ (艸) khô cảo (khô héo) — rơm rạ, cây cỏ đã khô. | Gương Hán-Việt | cảo (藁) ít dùng độc lập; biến thể của 稿 (bản thảo), 槁 (khô héo). | Mở khoá kiến thức | Biết 藁 (cảo) giúp nhận dạng biến thể chữ cổ của 稿/槁 trong thư tịch cổ điển.", "Tự nguyên_Xie": "藁 là dạng thay thế cổ của 稿 (rơm, bản thảo) và 槁 (cây khô/héo úa). Wiktionary ghi: ''alt form of 稿 (straw; stalk), alt form of 槁 (withered)''. Cũng dùng trong một số địa danh. Chưa có phân tích nguồn gốc độc lập — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khô; gỗ khô", "Hạng Tần Suất (Jun Da)": "5948.0", "Tần Suất % (Jun Da)": "99.9802427875", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 槀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹槀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "槀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藁", "Unihan_Traditional (Chữ Phồn thể)": "藁", "Pinyin_Xie": "gǎo", "Âm Hán Việt_Xie": "cảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ rơm rạ hoặc làm tính từ chỉ trạng thái khô héo của cây cỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('猡', '{"9000": "5949.0", "Chữ Trung Quốc": "猡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 11 | nét | 猡 | la | tượng hình | con lợn, heo; tên gọi miệt thị một số dân tộc thiểu số Tây Nam Trung Quốc | 猡 có bộ 犭 (khuyển: chó, động vật) là thành phần nghĩa. Không có phân tích nguồn gốc từ Wiktionary. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"la\": con vật (犭) la (gào to) — lợn heo la hét; chữ dùng miệt thị trong lịch sử, nay tránh dùng. | Gương Hán-Việt | la (猡) ít dùng; lưu ý đây là từ mang tính lịch sử tiêu cực. | Mở khoá kiến thức | Biết 猡 (la) giúp nhận ra bối cảnh lịch sử khi đọc tài liệu cổ về dân tộc học Tây Nam Trung Quốc.", "Tự nguyên_Xie": "猡 không có phân tích nguồn gốc từ Wiktionary. Bộ 犭 (khuyển, chỉ động vật) gợi ý đây là tên động vật hoặc tên người theo nghĩa miệt thị. Nghĩa: con lợn/heo; trước đây dùng miệt thị cho dân tộc Lô Lô (Lolo) ở Tây Nam Trung Quốc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lợn, heo", "Hạng Tần Suất (Jun Da)": "5949.0", "Tần Suất % (Jun Da)": "99.9802732778", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 罗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭罗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "罗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "猡", "Unihan_Traditional (Chữ Phồn thể)": "玀", "Pinyin_Xie": "luó", "Âm Hán Việt_Xie": "la", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và thường xuất hiện trong khẩu ngữ hoặc từ ghép để chỉ loài lợn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('旒', '{"9000": "5950.0", "Chữ Trung Quốc": "旒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 方 | Số nét | 13 | nét | 旒 | lưu | tượng hình | dải lụa/tua ngọc treo trên mũ miện hoặc cờ hoàng đế | 旒 có bộ 㫃 (phương: lá cờ) là thành phần nghĩa. Wiktionary không cung cấp phân tích bộ phận chi tiết. Chỉ dải trang trí trên cờ hoặc mũ thiên tử.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưu\": dải lưu (rủ xuống lưu động) trên mũ vua — 冕旒 (miện lưu: mũ miện và dải tua của thiên tử). | Gương Hán-Việt | lưu (旒) trong 冕旒 (miện lưu: mũ vàng hoàng đế), 九旒 (cửu lưu: chín dải cờ). | Mở khoá kiến thức | Biết 旒 (lưu) giúp hiểu nghi lễ cung đình: 冕旒 — mũ thiên tử có dải ngọc che mắt để nhắc vua đừng nhìn điều sai trái.", "Tự nguyên_Xie": "Lục thư thông | 旒 chỉ các dải lụa hay chuỗi ngọc treo lên mũ miện thiên tử (冕旒) hoặc bên dưới cờ hiệu. Wiktionary xác nhận đây là chữ lịch sử. Chỉ còn thấy trong lục thư thông. Chưa có phân tích nguồn gốc chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tua cờ", "Hạng Tần Suất (Jun Da)": "5950.0", "Tần Suất % (Jun Da)": "99.9803037682", "GavinGrover_Once (Chiết tự trực tiếp)": "方 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰方", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "旒", "Unihan_Traditional (Chữ Phồn thể)": "旒", "Pinyin_Xie": "liú", "Âm Hán Việt_Xie": "lưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các dải trang trí rủ xuống trên mũ miện hoặc lá cờ thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硇', '{"9000": "5951.0", "Chữ Trung Quốc": "硇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 11 | nét | 硇 | náo | tượng hình | nao sa (sal ammoniac, NH₄Cl) | 硇 có bộ 石 (thạch: đá/khoáng chất) là thành phần nghĩa. Wiktionary ghi rfe (request for etymology) — chưa có phân tích tại sao là 石 + 囟. Chỉ dùng trong 硇砂 (nao sa).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"náo\": khoáng chất (石) náo loạn — nao sa (硇砂) là muối amoni clorua kích thích mạnh, dùng trong luyện kim và y học. | Gương Hán-Việt | náo (硇) trong 硇砂 (nao sa: ammonium chloride), 硇洲 (Naozhou: tên đảo). | Mở khoá kiến thức | Biết 硇 (náo) giúp nhận ra 硇砂 — dược liệu đông y và chất trợ dung trong luyện kim.", "Tự nguyên_Xie": "硇 dùng trong 硇砂 (nao sa — ammonium chloride NH₄Cl, còn gọi là sal ammoniac). Wiktionary ghi ''{{rfe|zh|why is it 石 + 囟?}}'' — nguồn gốc chưa rõ. Cũng dùng trong địa danh 硇洲 (đảo Naozhou, Quảng Đông). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nao sa (vị thuốc đông y)", "Hạng Tần Suất (Jun Da)": "5951.0", "Tần Suất % (Jun Da)": "99.9803342585", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 囟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石囟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "囟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硇", "Unihan_Traditional (Chữ Phồn thể)": "硇", "Pinyin_Xie": "náo", "Âm Hán Việt_Xie": "nao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và hầu như chỉ dùng trong từ ghép náo sa để chỉ một vị thuốc đông y. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锍', '{"9000": "5952.0", "Chữ Trung Quốc": "锍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 锍 | lưu | tượng hình | xỉ luyện kim (matte); hợp chất sulfonium | 锍 là giản thể của 鋶. Cấu trúc: bộ 钅/金 (kim: kim loại) + phần âm. Chữ thuật ngữ luyện kim chỉ sản phẩm trung gian trong luyện đồng/niken.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưu\": kim loại (金) lưu (lưu lại) dưới dạng xỉ — lưu huỳnh (硫) trong xỉ luyện kim gọi là 锍. | Gương Hán-Việt | lưu (锍) trong 铜锍 (đồng lưu: copper matte), 镍锍 (niken matte). | Mở khoá kiến thức | Biết 锍 (lưu) giúp đọc tài liệu luyện kim: 铜锍 (đồng matte), 镍锍 (niken matte) là sản phẩm trung gian quan trọng.", "Tự nguyên_Xie": "锍 là giản thể của 鋶, theo Wiktionary: ''{{Han simp|鋶|f=釒|t=钅}}''. Chỉ: (1) matte — hỗn hợp sulphide trong luyện kim loại màu (đồng, niken); (2) sulfonium — ion S có ba liên kết hữu cơ. Thuật ngữ kỹ thuật hiện đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sulfonium; mờ; xỉn (kim loại)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 㐬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅㐬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锍", "Unihan_Traditional (Chữ Phồn thể)": "锍", "Pinyin_Xie": "liǔ", "Âm Hán Việt_Xie": "lưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chuyên ngành trong ngành luyện kim hoặc hóa học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞲', '{"9000": "5953.0", "Chữ Trung Quốc": "鞲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 19 | nét | 鞲 | câu | tượng hình | bao da bảo vệ cổ tay/cánh tay khi bắn cung hoặc thả chim săn | 鞲 có bộ 革 (cách: da thuộc) là thành phần nghĩa. Wiktionary xác nhận nghĩa là ''leather arm guard''. Chữ chỉ vật dụng da chuyên dụng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"câu\": da (革) câu (buộc) vào tay — bao da câu tay khi thả chim ưng đi săn, tránh móng vuốt cào. | Gương Hán-Việt | câu (鞲) trong 鞲鞴 (câu bị: bộ bơm/thùng khí — nghĩa mở rộng sang thiết bị cơ học). | Mở khoá kiến thức | Biết 鞲 (câu) giúp hiểu thuật ngữ kỹ thuật: 鞲鞴 (câu bị) là từ cổ chỉ bộ phận piston/bơm trong cơ học.", "Tự nguyên_Xie": "鞲 là chữ chỉ bao da bảo vệ cánh tay khi bắn cung hoặc thả chim ưng đi săn. Wiktionary xác nhận nghĩa là ''leather arm guard''. Bộ 革 (da thuộc) biểu nghĩa. Chưa có phân tích nguồn gốc chi tiết — chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: câu bị 鞲鞴,韝鞴)", "Hạng Tần Suất (Jun Da)": "5953.0", "Tần Suất % (Jun Da)": "99.9803952391", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 冓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革冓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞲", "Unihan_Traditional (Chữ Phồn thể)": "鞲", "Pinyin_Xie": "gōu", "Âm Hán Việt_Xie": "câu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường xuất hiện trong từ ghép chỉ bộ phận máy móc như pít-tông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哿', '{"9000": "5954.0", "Chữ Trung Quốc": "哿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 10 | nét | 哿 | cả | tượng hình | tốt, dễ chịu, chấp thuận được | 哿 có bộ 口 (khẩu: miệng) và 可 (khả: có thể/được). Wiktionary không cung cấp phân tích bộ phận rõ ràng. Nghĩa là ''xuất sắc, chấp nhận được, khen ngợi''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cả\": miệng (口) nói ''được, cả rồi'' — khen ngợi, chấp thuận; như tiếng Việt ''cả'' dùng trong tên các cụ già được kính trọng. | Gương Hán-Việt | cả (哿) ít dùng độc lập trong tiếng Việt hiện đại; thuật ngữ văn học cổ điển. | Mở khoá kiến thức | Biết 哿 (cả) giúp đọc Kinh Thi và thơ văn cổ điển chữ Hán về cung cách khen ngợi.", "Tự nguyên_Xie": "Tiểu triện | 哿 nghĩa là tốt, xuất sắc, chấp nhận được. Thấy trong Kinh Thi: 哿矣富人，哀此惸獨 (người giàu thì qua được; thương thay kẻ cô đơn). Wiktionary không phân tích cấu trúc chữ viết. Chỉ còn thấy trong tiểu triện. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dễ chịu", "Hạng Tần Suất (Jun Da)": "5954.0", "Tần Suất % (Jun Da)": "99.9804257295", "GavinGrover_Once (Chiết tự trực tiếp)": "加 + 可", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱加可", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "可", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "加", "Unihan_Simplified (Chữ Giản thể)": "哿", "Unihan_Traditional (Chữ Phồn thể)": "哿", "Pinyin_Xie": "gě", "Âm Hán Việt_Xie": "cả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ, chủ yếu dùng trong văn ngôn cổ để biểu thị sự ca ngợi hoặc tán thành. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('皤', '{"9000": "5955.0", "Chữ Trung Quốc": "皤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 白 | Số nét | 17 | nét | 皤 | bà | tượng hình | trắng bạc (tóc, râu người già); bụng to phệ | 皤 có bộ 白 (bạch: trắng) là thành phần nghĩa. Wiktionary không cung cấp phân tích cụ thể. Nghĩa liên quan đến màu trắng bạc của người già.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bà\": màu trắng (白) bà (trang nghiêm) — tóc bạc, râu bạc của cụ ông cụ bà; như tiếng Việt ''bà'' chỉ người cao tuổi. | Gương Hán-Việt | bà (皤) trong 皤皤 (bà bà: trắng bạc — mô tả người già), 皤腹 (bà phúc: bụng to phệ). | Mở khoá kiến thức | Biết 皤 (bà) giúp đọc thơ văn cổ điển mô tả hình ảnh bô lão: 皤皤老人 (cụ ông tóc bạc phơ).", "Tự nguyên_Xie": "Tiểu triện | 皤 chỉ màu trắng bạc (tóc trắng, râu bạc của người già) hoặc bụng to phệ. Wiktionary không phân tích cấu trúc chữ viết rõ ràng. Bộ 白 (trắng) là thành phần nghĩa chính. Chỉ còn thấy trong tiểu triện. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màu trắng bạc; bụng to", "Hạng Tần Suất (Jun Da)": "5955.0", "Tần Suất % (Jun Da)": "99.9804562198", "GavinGrover_Once (Chiết tự trực tiếp)": "白 + 番", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰白番", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "番", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "白", "Unihan_Simplified (Chữ Giản thể)": "皤", "Unihan_Traditional (Chữ Phồn thể)": "皤", "Pinyin_Xie": "pó", "Âm Hán Việt_Xie": "bà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ, thường dùng để miêu tả mái tóc bạc trắng của người già hoặc hình dáng bụng phệ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哏', '{"9000": "5956.0", "Chữ Trung Quốc": "哏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 哏 | gắn | tượng hình | hài hước, buồn cười; bật cười, khôi hài | 哏 có bộ 口 (khẩu: miệng) và 艮 (cấn: cứng, dừng lại). Không có phân tích nguồn gốc từ Wiktionary. Nghĩa hiện đại là ''hài hước, buồn cười''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"gắn\": miệng (口) nói gắn gắn — điều hài hước gắn chặt vào người nghe; như người chuyên kể chuyện hề (捧哏, 逗哏). | Gương Hán-Việt | gắn (哏) ít dùng trong Hán-Việt cổ; chủ yếu trong tiếng lóng hiện đại về hài kịch. | Mở khoá kiến thức | Biết 哏 (gắn) giúp hiểu thuật ngữ xiàngsheng: 逗哏 (người kể/gây cười) và 捧哏 (người phụ họa/phối hợp).", "Tự nguyên_Xie": "哏 không có phân tích nguồn gốc từ Wiktionary. Bộ 口 liên quan đến miệng/lời nói, 艮 có thể biểu âm. Nghĩa hiện đại: hài hước, buồn cười (tiếng Bắc Kinh và xiàngsheng 相聲). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hài hước, buồn cười, thú vị", "Hạng Tần Suất (Jun Da)": "5956.0", "Tần Suất % (Jun Da)": "99.9804867101", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 艮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口艮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "艮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哏", "Unihan_Traditional (Chữ Phồn thể)": "哏", "Pinyin_Xie": "gén", "Âm Hán Việt_Xie": "ngận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ tình tiết gây cười trong tấu hài hoặc làm tính từ chỉ sự thú vị. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('殍', '{"9000": "5957.0", "Chữ Trung Quốc": "殍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 歹 | Số nét | 11 | nét | 歹 | đãi | biểu nghĩa | xương tàn, chết chóc | 孚 | phu | biểu âm | 殍 = 歹 (Đãi, biểu nghĩa: xương tàn, chết chóc) + 孚 (Phu, biểu âm). Chữ hình thanh: 歹 chỉ liên quan đến cái chết/tử vong, 孚 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiếu\": xương tàn (歹) của người phiếu lạc (trôi dạt) — xác người chết đói trơ xương bên đường. | Gương Hán-Việt | phiếu (殍) trong 餓殍 (ngạ phiếu: người chết đói, xác chết đói), 殍殣 (phiếu cấn). | Mở khoá kiến thức | Biết 殍 (phiếu) giúp đọc sử ký và văn học về nạn đói: 餓殍遍野 (ngạ phiếu biến dã: xác chết đói la liệt khắp nơi).", "Tự nguyên_Xie": "殍 là chữ hình thanh: 歹 (xương tàn, chỉ cái chết) biểu nghĩa, 孚 biểu âm. Nghĩa: xác người chết đói; chết đói. Wiktionary xác nhận cấu trúc psc. Thường thấy trong 餓殍 (ngạ phiếu: kẻ chết đói, xác chết đói). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chết đói", "Hạng Tần Suất (Jun Da)": "5957.0", "Tần Suất % (Jun Da)": "99.9805172004", "GavinGrover_Once (Chiết tự trực tiếp)": "歹 + 孚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰歹孚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "歹", "Unihan_Simplified (Chữ Giản thể)": "殍", "Unihan_Traditional (Chữ Phồn thể)": "殍", "Pinyin_Xie": "piǎo", "Âm Hán Việt_Xie": "biễu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ việc chết vì đói hoặc làm danh từ chỉ thi thể người chết đói. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('漯', '{"9000": "5958.0", "Chữ Trung Quốc": "漯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 14 | nét | 漯 | tháp | tượng hình | tên sông (Sông Tháp/Luo River, Hà Nam) | 漯 có bộ 水/氵 (thủy: nước) là thành phần nghĩa. Không có phân tích nguồn gốc từ Wiktionary. Chủ yếu dùng làm tên sông và địa danh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tháp\": dòng nước (氵) tháp (đổ xuống) — sông Tháp Hà (漯河) ở Hà Nam chảy qua vùng bình nguyên. | Gương Hán-Việt | tháp (漯) trong 漯河 (Tháp Hà: thành phố ở Hà Nam, tên cũ là Hứa Xương). | Mở khoá kiến thức | Biết 漯 (tháp) giúp nhận ra địa danh 漯河市 — thành phố trung tâm chế biến thực phẩm của Hà Nam, Trung Quốc.", "Tự nguyên_Xie": "Lục thư thông | 漯 chủ yếu dùng trong tên địa danh: 漯河 (Tháp Hà, thành phố ở Hà Nam, Trung Quốc). Bộ 氵 (nước) chỉ liên quan đến sông nước. Không có phân tích nguồn gốc từ Wiktionary — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Tháp", "Hạng Tần Suất (Jun Da)": "5958.0", "Tần Suất % (Jun Da)": "99.9805476907", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 累", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵累", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "累", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "漯", "Unihan_Traditional (Chữ Phồn thể)": "漯", "Pinyin_Xie": "luò", "Âm Hán Việt_Xie": "tháp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng, chủ yếu dùng trong địa danh như tên sông hoặc tên huyện ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谂', '{"9000": "5959.0", "Chữ Trung Quốc": "谂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 10 | nét | 谂 | thẩm | tượng hình | suy nghĩ, xét kỹ, khuyên bảo | 谂 có bộ 言 (ngôn: lời nói) và 念 biểu âm. Là chữ tạo mới theo cách giản thể: bộ 讠(言) + phần âm. Nghĩa là suy nghĩ kỹ lưỡng, khuyên nhủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thẩm\": lời nói (言) thẩm (xem xét kỹ) — thẩm tra, thẩm vấn, xét kỹ trước khi phát ngôn. | Gương Hán-Việt | thẩm (谂) ít dùng độc lập; liên quan đến 諶 (thẩm: thành thật) trong văn cổ. | Mở khoá kiến thức | Biết 谂 (thẩm) giúp đọc văn ngôn cổ về sự suy xét, khuyên nhủ.", "Tự nguyên_Xie": "Tiểu triện | 谂 chỉ hành động suy nghĩ, xét nghĩ, khuyên nhủ. Wiktionary không cung cấp phân tích nguồn gốc đầy đủ. Bộ 言 (lời nói) biểu nghĩa. Chỉ còn thấy trong tiểu triện. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghĩ, xét", "Hạng Tần Suất (Jun Da)": "5959.0", "Tần Suất % (Jun Da)": "99.9806691353", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 念", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠念", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "念", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谂", "Unihan_Traditional (Chữ Phồn thể)": "諗", "Pinyin_Xie": "shěn", "Âm Hán Việt_Xie": "thẩm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ, thường dùng trong văn viết hoặc phương ngôn để chỉ việc suy nghĩ, ghi nhớ hoặc báo cho biết. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跶', '{"9000": "5960.0", "Chữ Trung Quốc": "跶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 13 | nét | 足 | túc | biểu nghĩa | bàn chân | 達 | đạt | biểu âm | đạt đến | 跶 = 足 (Túc, biểu nghĩa: chân) + 達 (Đạt, biểu âm). Chữ hình thanh: 足 liên quan đến bước chân, 達 cho âm đọc. Dùng trong 蹦跶/蹓跶.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đáp\": chân (足) đáp xuống — đáp đất (bước chân), vấp ngã khi chân đáp sai chỗ. | Gương Hán-Việt | đáp (跶) ít dùng độc lập; chủ yếu trong 蹦跶 (bạo đáp: nhảy nhót), 蹓跶 (đi dạo). | Mở khoá kiến thức | Biết 跶 (đáp) giúp hiểu tiếng lóng và khẩu ngữ Bắc Kinh: 蹦跶 (nhảy loạn), 蹓跶 (đi dạo thư thái).", "Tự nguyên_Xie": "跶 là chữ hình thanh: 足 (chân) biểu nghĩa, 達 biểu âm. Nghĩa: vấp ngã, vấp chân; cũng dùng trong 蹦跶 (nhảy nhót, vùng vẫy) và 蹓跶 (đi dạo). Wiktionary xác nhận cấu trúc psc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bính đáp 蹦躂,蹦跶); (xem: lựu đáp 蹓躂,蹓跶)", "Hạng Tần Suất (Jun Da)": "5960.0", "Tần Suất % (Jun Da)": "99.9806991088", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 达", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊达", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "达", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跶", "Unihan_Traditional (Chữ Phồn thể)": "躂", "Pinyin_Xie": "tà", "Âm Hán Việt_Xie": "đáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ, hầu như chỉ dùng trong các từ láy kép để miêu tả động tác đi lại, nhảy nhót. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('橥', '{"9000": "5961.0", "Chữ Trung Quốc": "橥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 15 | nét | 豬 | trư | biểu âm | lợn (biểu âm) | 木 | mộc | biểu nghĩa | gỗ, cây | 橥 = 豬 (Trư, biểu âm: lợn) + 木 (Mộc, biểu nghĩa: gỗ). Chữ hình thanh: 木 chỉ đây là đồ vật bằng gỗ, 豬 cho âm đọc. Nghĩa: cái cọc gỗ nhỏ để buộc gia súc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trư\": cọc gỗ (木) có âm trư — cọc buộc trư (lợn) hoặc súc vật ở sân; mở rộng thành cọc hiệu/biển báo. | Gương Hán-Việt | trư (橥) trong 楬橥/揭橥 (yết trư: trưng bày công khai, đề xuất). | Mở khoá kiến thức | Biết 橥 (trư) giúp hiểu cụm 揭橥 — thành ngữ học thuật có nghĩa ''nêu ra, trưng bày ý kiến công khai''.", "Tự nguyên_Xie": "橥 là chữ hình thanh: 木 (gỗ) biểu nghĩa, 豬 biểu âm. Nghĩa: cọc gỗ nhỏ dùng để buộc gia súc hoặc đánh dấu ranh giới. Wiktionary xác nhận cấu trúc psc. Thấy trong cụm 楬橥 (揭橥: trưng bày, công bố). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cọc buộc gia súc", "Hạng Tần Suất (Jun Da)": "5961.0", "Tần Suất % (Jun Da)": "99.9807290823", "GavinGrover_Once (Chiết tự trực tiếp)": "猪 + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱猪木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "猪", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "橥", "Unihan_Traditional (Chữ Phồn thể)": "櫫", "Pinyin_Xie": "zhū", "Âm Hán Việt_Xie": "trư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, dùng trong văn ngôn để chỉ cái cọc gỗ găm xuống đất hoặc bia dùng trong tập bắn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镬', '{"9000": "5962.0", "Chữ Trung Quốc": "镬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 18 | nét | 金 | kim | biểu nghĩa | kim loại | 蒦 | biểu âm | 镬 = 金 (Kim, biểu nghĩa: kim loại) + 蒦 (biểu âm). Chữ hình thanh: 金 chỉ đây là đồ vật bằng kim loại, 蒦 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoạc\": kim loại (金) đúc thành vạc hoạc (lớn) — cái vạc đồng dùng nấu ăn hoặc dùng trong hình phạt cực hình. | Gương Hán-Việt | hoạc (镬) trong 鑊烹 (hoạc phanh: luộc trong vạc — hình phạt thời cổ), 飯鑊 (phạn hoạc: vạc nấu cơm). | Mở khoá kiến thức | Biết 镬 (hoạc) giúp hiểu lịch sử hình phạt cổ đại: 鑊烹 là một trong 五刑 thời cổ Trung Quốc.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Lục thư thông | 镬 là chữ hình thanh: 金 (kim loại) biểu nghĩa, 蒦 biểu âm. Nghĩa: cái vạc đồng lớn (dùng nấu ăn hoặc làm hình phạt thời cổ — 鑊烹: luộc tội nhân trong vạc). Thấy trong giáp cốt văn, kim văn. Wiktionary xác nhận cấu trúc psc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái vạc, cái chảo", "Hạng Tần Suất (Jun Da)": "5962.0", "Tần Suất % (Jun Da)": "99.9807590559", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 蒦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅蒦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蒦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镬", "Unihan_Traditional (Chữ Phồn thể)": "鑊", "Pinyin_Xie": "huò", "Âm Hán Việt_Xie": "hoạch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ dụng cụ nấu ăn lớn thời cổ, thường xuất hiện trong các từ ghép văn học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸲', '{"9000": "5963.0", "Chữ Trung Quốc": "鸲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 10 | nét | 鸲 | cù | tượng hình | tên chim: sáo myna (鴝鵒), một số loài họ Cơm nguội | 鸲 có bộ 鸟 (điểu: chim) là thành phần nghĩa. Wiktionary không cung cấp phân tích bộ phận rõ ràng. Dùng trong 鴝鵒 (chim sáo/myna) và tên một số loài họ Muscicapidae.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cù\": chim (鸟) cù cù gọi nhau — chim sáo 鴝鵒 biết bắt chước tiếng người, cù (kỳ diệu) như người. | Gương Hán-Việt | cù (鸲) trong 鴝鵒 (cù dục: chim sáo/myna), 鵲鴝 (tước cù: chim cà cưỡng). | Mở khoá kiến thức | Biết 鸲 (cù) giúp nhận tên các loài chim trong sách tự nhiên học Trung Quốc: 鴝鵒 (myna), 鵲鴝 (magpie-robin), 野鴝 (chim cà cưỡng hoang).", "Tự nguyên_Xie": "鸲 dùng trong 鴝鵒 (cù dục — chim sáo/myna, có thể bắt chước tiếng người) và trong tên các loài chim họ Muscicapidae. Wiktionary không cung cấp phân tích nguồn gốc chữ viết. Bộ 鸟 (chim) biểu nghĩa. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: cù dục 鴝鵒,鸜鵒,鸲鹆)", "Hạng Tần Suất (Jun Da)": "5963.0", "Tần Suất % (Jun Da)": "99.9807890294", "GavinGrover_Once (Chiết tự trực tiếp)": "句 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰句鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鸲", "Unihan_Traditional (Chữ Phồn thể)": "鴝", "Pinyin_Xie": "qú", "Âm Hán Việt_Xie": "cù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ trong tên gọi các loài chim như cù dục. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('姝', '{"9000": "5964.0", "Chữ Trung Quốc": "姝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 9 | nét | 女 | nữ | biểu nghĩa | người phụ nữ | 朱 | chu | biểu âm | màu đỏ son | 姝 = 女 (Nữ, biểu nghĩa: phụ nữ) + 朱 (Chu, biểu âm); chữ hình thanh. Bộ Nữ chỉ đối tượng là người phụ nữ, 朱 cho âm đọc gần với shū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thù\": người phụ nữ (女) đẹp như sắc đỏ son (朱) — vẻ đẹp rực rỡ, nổi bật. | Gương Hán-Việt | thù nữ (姝女) — người đẹp | Mở khoá kiến thức | Biết 姝 mở khoá các từ cổ điển chỉ vẻ đẹp phụ nữ trong thơ Đường, Kinh Thi.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 姝 là chữ hình thanh: 女 (nữ) biểu nghĩa chỉ phụ nữ, 朱 (chu) biểu âm. Nghĩa gốc là ''người con gái đẹp'', dùng trong văn chương cổ điển. Kinh Thi có câu: 靜女其姝 — ''người con gái thục nữ kia xinh đẹp thay''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con gái đẹp", "Hạng Tần Suất (Jun Da)": "5964.0", "Tần Suất % (Jun Da)": "99.9808190029", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 朱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女朱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "姝", "Unihan_Traditional (Chữ Phồn thể)": "姝", "Pinyin_Xie": "shū", "Âm Hán Việt_Xie": "xu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm danh từ chỉ mỹ nhân hoặc làm tính từ miêu tả vẻ đẹp thanh tú trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茭', '{"9000": "5965.0", "Chữ Trung Quốc": "茭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艹 | thảo | biểu nghĩa | cỏ, cây | 交 | giao | biểu âm | giao tiếp | 茭 = 艹 (Thảo, biểu nghĩa: cỏ/thực vật) + 交 (Giao, biểu âm); chữ hình thanh. Bộ thảo chỉ đây là loài thực vật, 交 cho âm jiāo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giao\": cây cỏ (艹) mọc đan xen nhau (交) dưới nước — hình ảnh ruộng cỏ lúa chụt chằng chịt. | Gương Hán-Việt | không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 茭 giúp nhận ra tên thực vật cổ điển trong văn bản Trung y và ẩm thực truyền thống.", "Tự nguyên_Xie": "Tiểu triện | 茭 là chữ hình thanh: 艹 (thảo) biểu nghĩa chỉ thực vật, 交 (giao) biểu âm. Chỉ loài cỏ nước như cỏ nến hay lúa chụt (Zizania), dùng làm thức ăn và đan lát. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rau giao; cỏ khô; dây tre", "Hạng Tần Suất (Jun Da)": "5965.0", "Tần Suất % (Jun Da)": "99.9808489765", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 交", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹交", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "交", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茭", "Unihan_Traditional (Chữ Phồn thể)": "茭", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "giao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại thực vật như niêm thảo hoặc nguyên liệu bện dây thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窆', '{"9000": "5966.0", "Chữ Trung Quốc": "窆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 9 | nét | 窆 | biếm | tượng hình | chôn quan tài xuống mộ | 窆 không có cấu trúc hình thanh rõ ràng trong dữ liệu hiện có; chưa có nguồn học thuật phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biếm\": chữ dùng để chỉ lễ hạ quan tài xuống huyệt — một nghi lễ trang nghiêm trong tang lễ truyền thống. | Gương Hán-Việt | không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 窆 giúp đọc hiểu văn bản lịch sử, bi ký và sách tang lễ cổ.", "Tự nguyên_Xie": "窆 mang nghĩa ''đặt quan tài xuống mộ, chôn cất''. Cũng dùng để chỉ ngôi mộ hoặc phiến đá dùng hạ quan tài (窆石). Nguồn Wiktionary không có phân tích hình vị chi tiết; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hạ quan tài xuống huyệt", "Hạng Tần Suất (Jun Da)": "5966.0", "Tần Suất % (Jun Da)": "99.98087895", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 乏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴乏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窆", "Unihan_Traditional (Chữ Phồn thể)": "窆", "Pinyin_Xie": "biǎn", "Âm Hán Việt_Xie": "biếm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ nghi thức mai táng, thường dùng trong văn viết cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髟', '{"9000": "5967.0", "Chữ Trung Quốc": "髟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 10 | nét | 髟 | tiêu | tượng hình | bộ thủ chỉ tóc dài | 髟 là chữ tượng hình: hình người có mái tóc dài buông xuống. Shuowen Jiezi nhầm cho là chữ hội ý, nhưng nguồn gốc thực sự là tượng hình. Đây là bộ thủ (radical) chỉ mọi thứ liên quan đến tóc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": hình ảnh người (人) có mái tóc (髟) dài buông xuống — đây là bộ thủ của tất cả chữ liên quan đến tóc. | Gương Hán-Việt | không có từ Hán-Việt thông dụng riêng; xuất hiện như bộ thủ trong các từ như 鬓发 (鬢 — mái tóc mai) | Mở khoá kiến thức | Nhận ra bộ 髟 trong các chữ như 髻 (búi tóc), 髯 (râu), 鬓 (tóc mai) — đều liên quan đến tóc.", "Tự nguyên_Xie": "Kim văn | Bạch thư | 髟 là chữ tượng hình mô tả người có mái tóc dài. Wiktionary ghi: ''a person with long hair; Shuowen mistakes it for a compound.'' Đây là bộ thủ (214 bộ Khang Hi) chứa các chữ liên quan đến tóc, râu như 髻, 髦, 鬓. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "861.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trường (797) Sam (860)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Trường/Trưởng (số 797 - dài) ở trên bộ Sam (số 860 - lông tóc). Giải thích sự chuyển ý: Đây là chữ Hội ý. Tiêu (Bưu) là mái tóc dài.", "Nghĩa Tiếng Việt_Xie": "tóc dài lượt thượt", "Hạng Tần Suất (Jun Da)": "5967.0", "Tần Suất % (Jun Da)": "99.9809089236", "GavinGrover_Once (Chiết tự trực tiếp)": "镸 + 彡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰镸彡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "镸", "Unihan_Simplified (Chữ Giản thể)": "髟", "Unihan_Traditional (Chữ Phồn thể)": "髟", "Pinyin_Xie": "biāo", "Âm Hán Việt_Xie": "bưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ miêu tả mái tóc dài hoặc làm bộ thủ trong cấu tạo chữ Hán. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畋', '{"9000": "5968.0", "Chữ Trung Quốc": "畋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 田 | Số nét | 9 | nét | 田 | điền | biểu âm | ruộng đồng | 攵 | phác | biểu nghĩa | tay cầm gậy/hành động | 畋 = 田 (Điền, biểu âm) + 攵 (Phác, biểu nghĩa: tay cầm vũ khí/hành động); chữ hình thanh. 攵 gợi hành động đi săn, 田 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điền\": người cầm gậy (攵) đi trên cánh đồng (田) để săn bắt — hình ảnh đi điền liệp (săn bắn trên đồng). | Gương Hán-Việt | điền liệp (畋獵) — săn bắn | Mở khoá kiến thức | Biết 畋 mở khoá các từ cổ điển về săn bắn như 畋猎 (điền liệp), thường gặp trong sử ký và thơ văn cổ.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | 畋 là chữ hình thanh: 攵 biểu nghĩa chỉ hành động (tay cầm gậy), 田 biểu âm. Nghĩa gốc là ''đi săn trên đồng'', sau mở rộng sang nghĩa cày ruộng. Chữ cổ, xuất hiện trong giáp cốt văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cày cấy, trồng trọt; săn bắn", "Hạng Tần Suất (Jun Da)": "5968.0", "Tần Suất % (Jun Da)": "99.9809388971", "GavinGrover_Once (Chiết tự trực tiếp)": "田 + ⺙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰田⺙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "⺙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "田", "Unihan_Simplified (Chữ Giản thể)": "畋", "Unihan_Traditional (Chữ Phồn thể)": "畋", "Pinyin_Xie": "tián", "Âm Hán Việt_Xie": "điền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hoạt động săn bắn hoặc làm ruộng trong văn ngôn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('溏', '{"9000": "5969.0", "Chữ Trung Quốc": "溏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 溏 | đường | tượng hình | nước sệt, nửa đông | 溏 có bộ 氵(thủy) biểu nghĩa chỉ chất lỏng và 唐 biểu âm; chữ hình thanh. Mô tả trạng thái chất lỏng đặc sệt, nửa đông nửa lỏng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đường\": nước (氵) sệt như đường mật đặc (唐/糖) — trạng thái chất lỏng nửa đông nửa lỏng. | Gương Hán-Việt | không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 溏 giúp đọc hiểu thuật ngữ Đông y mô tả tình trạng phân lỏng và chất nhày.", "Tự nguyên_Xie": "溏 là chữ hình thanh với bộ 氵 (thủy) biểu nghĩa và 唐 biểu âm. Nghĩa là ''nửa đông, sệt'' — dùng mô tả phân lỏng (溏便), lòng đỏ trứng chưa chín hẳn (溏心), hay chất lỏng nhớt. Chưa có phân tích chi tiết hơn từ Wiktionary; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái ao; lỏng, chất lỏng", "Hạng Tần Suất (Jun Da)": "5969.0", "Tần Suất % (Jun Da)": "99.9809688706", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 唐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵唐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "唐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "溏", "Unihan_Traditional (Chữ Phồn thể)": "溏", "Pinyin_Xie": "táng", "Âm Hán Việt_Xie": "đường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ bổ nghĩa cho danh từ để chỉ trạng thái lỏng, chưa đông đặc như lòng đỏ trứng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲔', '{"9000": "5970.0", "Chữ Trung Quốc": "鲔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 14 | nét | 鲔 | vỉ | tượng hình | cá tầm Trung Quốc, cá ngừ | 鲔 có bộ 鱼 (ngư) biểu nghĩa chỉ cá và 有 biểu âm; chữ hình thanh. Chỉ loài cá tầm Trung Quốc (nay tuyệt chủng) hoặc cá ngừ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vỉ\": cá (鱼) khổng lồ như cá tầm — một trong những loài cá quý nhất trong lịch sử Trung Quốc. | Gương Hán-Việt | không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 鲔 giúp đọc hiểu văn bản cổ về lễ vật cúng tế và tên các loài cá quý hiếm.", "Tự nguyên_Xie": "Tiểu triện | 鲔 là chữ hình thanh: bộ 鱼 (ngư) biểu nghĩa, 有 biểu âm. Ban đầu chỉ cá tầm Trung Quốc (Psephurus gladius, nay đã tuyệt chủng), sau dùng chỉ cá ngừ. Đây là từ cổ điển xuất hiện trong các văn bản tế lễ. Chưa có phân tích chi tiết hơn từ Wiktionary. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá vĩ; cá tầm (nói trong sách cổ)", "Hạng Tần Suất (Jun Da)": "5970.0", "Tần Suất % (Jun Da)": "99.9809988442", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 有", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼有", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "有", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲔", "Unihan_Traditional (Chữ Phồn thể)": "鮪", "Pinyin_Xie": "wěi", "Âm Hán Việt_Xie": "vị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loài cá lớn, ngày nay thường dùng chỉ cá ngừ đại dương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喹', '{"9000": "5971.0", "Chữ Trung Quốc": "喹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 口 | khẩu | biểu nghĩa | miệng (ký hiệu hóa học) | 圭 | khuê | biểu âm | ngọc khuê | 喹 = 口 (Khẩu, biểu nghĩa: dùng cho ký âm hóa học) + 圭 (Khuê, biểu âm); chữ hình thanh. Đây là chữ tạo muộn dùng để phiên âm tên hóa học — bộ 口 thường thấy trong các chữ phiên âm khoa học hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỳ\": miệng đọc (口) tên chất hóa học khuê (圭) — nhớ ngay đây là ký hiệu phiên âm trong hóa học. | Gương Hán-Việt | không có từ Hán-Việt thông dụng; dùng trong thuật ngữ hóa học | Mở khoá kiến thức | Biết 喹 giúp đọc tên hóa chất như 喹啉 (quinoline), 喹唑啉 (quinazoline) trong tài liệu y dược.", "Tự nguyên_Xie": "喹 là chữ hình thanh tạo muộn (thế kỷ 19-20): 口 biểu nghĩa (dấu hiệu phiên âm), 圭 biểu âm cho âm kuí. Được tạo ra để phiên âm từ hóa học ''quinoline'' (喹啉) trong danh pháp hóa học Trung Quốc. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khuê lâm 喹啉)", "Hạng Tần Suất (Jun Da)": "5971.0", "Tần Suất % (Jun Da)": "99.9810587912", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 奎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口奎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "喹", "Unihan_Traditional (Chữ Phồn thể)": "喹", "Pinyin_Xie": "kuí", "Âm Hán Việt_Xie": "khuê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ liên kết trong các thuật ngữ hóa học phiên âm như quỳ lâm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('吣', '{"9000": "5972.0", "Chữ Trung Quốc": "吣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 吣 | tăm | tượng hình | tiếng chó mèo ói mửa hoặc nói bậy | 吣 không có phân tích hình vị từ Wiktionary. Cấu trúc gồm bộ 口 (khẩu) và 心; chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tăm\": miệng (口) phát ra âm thanh khó chịu từ tâm trạng bực bội — tiếng ói hoặc tiếng nói bậy. | Gương Hán-Việt | không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 吣 giúp nhận ra nghĩa thông tục trong văn học phương ngữ Bắc Kinh.", "Tự nguyên_Xie": "吣 không có nguồn phân tích Wiktionary. Theo cấu trúc: bộ 口 (miệng) kết hợp với 心 (tâm). Nghĩa là tiếng chó mèo kêu trước khi mửa; cũng dùng theo nghĩa tục chỉ nói bậy, nói xằng. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chó mèo mửa (ói); nói bậy bạ, chửi bới", "Hạng Tần Suất (Jun Da)": "5972.0", "Tần Suất % (Jun Da)": "99.9811182215", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "心", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "吣", "Unihan_Traditional (Chữ Phồn thể)": "唚", "Pinyin_Xie": "qìn", "Âm Hán Việt_Xie": "khấm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường dùng làm động từ trong khẩu ngữ để chỉ hành vi nôn mửa của động vật hoặc mắng nhiếc người khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羼', '{"9000": "5973.0", "Chữ Trung Quốc": "羼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 21 | nét | 尸 | thi | biểu nghĩa | mái che, nơi trú ẩn | 羴 | sấn | biểu âm | đàn dê | 羼 = 尸 (Thi, biểu nghĩa: nơi ẩn nấp/trú ẩn) + 羴 (biểu âm: đàn dê). Wiktionary ghi ls=ic nhưng cũng có ls2=psc — đây là trường hợp lai: 尸 cho mái che (một đàn dê trốn lẫn vào nơi khác), 羴 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sấn\": đàn dê (羴) chen nhau vào mái trú ẩn (尸) — hình ảnh của sự trà trộn, pha lẫn. | Gương Hán-Việt | không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 羼 giúp đọc hiểu văn học cổ về sự pha trộn giả mạo, đặc biệt trong ngữ cảnh hàng giả.", "Tự nguyên_Xie": "Tiểu triện | 羼 có cấu trúc kép: vừa hội ý (unas đàn dê chen lấn vào một nơi trú ẩn) vừa hình thanh (羴 cho âm). Nghĩa là ''trộn lẫn, pha vào''. Ví dụ: 羼水 (pha nước vào rượu), 羼入 (trà trộn vào). Tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: sạn tạp 羼雜)", "Hạng Tần Suất (Jun Da)": "5973.0", "Tần Suất % (Jun Da)": "99.9811476783", "GavinGrover_Once (Chiết tự trực tiếp)": "尸 + 羴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴尸羴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "尸", "Unihan_Simplified (Chữ Giản thể)": "羼", "Unihan_Traditional (Chữ Phồn thể)": "羼", "Pinyin_Xie": "chàn", "Âm Hán Việt_Xie": "sạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường kết hợp với các từ khác để chỉ sự pha trộn, lẫn lộn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缧', '{"9000": "5974.0", "Chữ Trung Quốc": "缧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 14 | nét | 缧 | luy | tượng hình | dây trói, xích tù nhân | 缧 có bộ 糸 (mịch) biểu nghĩa chỉ dây, sợi và 畾 biểu âm; chữ hình thanh. Chỉ loại dây thừng dùng để trói tù nhân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"luy\": sợi tơ (糸) quấn chồng lên nhau như núi (畾) — hình ảnh dây thừng trói buộc chắc chắn. | Gương Hán-Việt | không có từ Hán-Việt thông dụng; dùng trong thành ngữ văn học | Mở khoá kiến thức | Biết 缧 giúp hiểu thành ngữ 身陷缧绁 (thân ngồi tù, bị xiềng xích).", "Tự nguyên_Xie": "缧 (cổ thể: 縲) là chữ hình thanh với bộ 糸 (mịch) và 畾 biểu âm. Nghĩa là dây trói, xích tù nhân. Thường gặp trong cụm 縲絏 (luy tiết: xiềng xích, cảnh tù nhân). Wiktionary không có phân tích đầy đủ hơn; chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây đen để trói tội phạm", "Hạng Tần Suất (Jun Da)": "5974.0", "Tần Suất % (Jun Da)": "99.981177135", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 累", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟累", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "累", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缧", "Unihan_Traditional (Chữ Phồn thể)": "縲", "Pinyin_Xie": "léi", "Âm Hán Việt_Xie": "luy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường xuất hiện trong văn ngôn để chỉ dây trói hoặc cảnh tù đày. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窬', '{"9000": "5975.0", "Chữ Trung Quốc": "窬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 14 | nét | 窬 | du | tượng hình | lỗ hổng trên tường, cửa nhỏ | 窬 có bộ 穴 (huyệt) biểu nghĩa chỉ lỗ hổng và 俞 biểu âm; chữ hình thanh. Chỉ lỗ hổng trên tường hoặc cửa nhỏ chui qua.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": lỗ hổng (穴) trên tường mà kẻ trộm (俞) lách qua — nhớ ngay nghĩa đục tường trèo rào. | Gương Hán-Việt | không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 窬 giúp hiểu thành ngữ 穿窬 (xuyên du: đục tường khoét ngạch, chỉ kẻ trộm).", "Tự nguyên_Xie": "Tiểu triện | 窬 là chữ hình thanh với bộ 穴 (lỗ hổng) và 俞 biểu âm. Nghĩa là lỗ hổng đục trên tường để chui qua, hoặc cửa nhỏ thấp buộc phải khom lưng. Wiktionary không cung cấp phân tích chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đào tường, khoét tường; lỗ nhỏ trên cửa", "Hạng Tần Suất (Jun Da)": "5975.0", "Tần Suất % (Jun Da)": "99.9812065918", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 俞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴俞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "俞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窬", "Unihan_Traditional (Chữ Phồn thể)": "窬", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành vi khoét tường hoặc làm danh từ chỉ cái lỗ nhỏ trên tường. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骘', '{"9000": "5976.0", "Chữ Trung Quốc": "骘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 12 | nét | 骘 | trắc | tượng hình | ngựa đực, đánh giá, định luận | 骘 có bộ 馬 (mã) biểu nghĩa và 陟 biểu âm; chữ hình thanh chỉ ngựa đực, sau mở rộng nghĩa sang ''đánh giá, bình định''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trắc\": con ngựa (馬) leo cao (陟) — ẩn dụ phẩm cách cao vươn lên, được người đánh giá tốt. | Gương Hán-Việt | âm trắc (阴骘) — công đức ngầm, phúc báo kín đáo | Mở khoá kiến thức | Biết 骘 giúp hiểu khái niệm 阴骘 (âm trắc) trong đạo đức học Trung Quốc — làm việc tốt không cầu tiếng.", "Tự nguyên_Xie": "骘 (cổ thể: 騭) là chữ hình thanh với bộ 馬 và 陟 biểu âm. Nghĩa gốc là ngựa đực; sau mở rộng sang ''đánh giá, định luận phẩm hạnh''. Thường gặp trong cụm 阴骘 (âm trắc: công đức kín đáo, phúc báo ngầm). Wiktionary không cung cấp phân tích đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "định sẵn; phân biệt; ngựa cái", "Hạng Tần Suất (Jun Da)": "5976.0", "Tần Suất % (Jun Da)": "99.9812360485", "GavinGrover_Once (Chiết tự trực tiếp)": "陟 + 马", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱陟马", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "陟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骘", "Unihan_Traditional (Chữ Phồn thể)": "騭", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "chất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ trong văn ngôn với nghĩa định đoạt hoặc đánh giá, phân biệt tốt xấu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赉', '{"9000": "5977.0", "Chữ Trung Quốc": "赉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 11 | nét | 赉 | lại | tượng hình | ban thưởng, tặng | 赉 có bộ 貝 (bối: tiền, của cải) biểu nghĩa và 来 biểu âm; chữ hình thanh. Chỉ hành động ban thưởng tặng quà của bề trên cho kẻ dưới.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lại\": của cải (貝) được ban tặng đến (来) — vua/thần linh trao thưởng cho người có công. | Gương Hán-Việt | không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 赉 giúp đọc hiểu các văn bản sắc phong, tế lễ và sử ký cổ đại Trung Quốc.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 赉 là chữ hình thanh với bộ 貝 (bối: của cải, tiền) biểu nghĩa và 来 biểu âm. Nghĩa là ban thưởng, tặng của quý. Xuất hiện trong văn bản tế lễ và sử ký. Có dạng đại triện và tiểu triện. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ban cho", "Hạng Tần Suất (Jun Da)": "5977.0", "Tần Suất % (Jun Da)": "99.9812655053", "GavinGrover_Once (Chiết tự trực tiếp)": "来 + 贝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱来贝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "来", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赉", "Unihan_Traditional (Chữ Phồn thể)": "賚", "Pinyin_Xie": "lài", "Âm Hán Việt_Xie": "lãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường dùng trong văn phong cổ kính để chỉ việc vua chúa ban thưởng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镓', '{"9000": "5978.0", "Chữ Trung Quốc": "镓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 镓 | gia | tượng hình | nguyên tố gallium (Ga) | 镓 có bộ 金 (kim) biểu nghĩa chỉ kim loại và 家 biểu âm; chữ hình thanh tạo muộn. Được tạo ra để đặt tên cho nguyên tố gallium trong danh pháp hóa học Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"gia\": kim loại (金) mang tên gia đình (家) — Gallium được đặt tên theo Gallia (nước Pháp), nhớ ngay đây là kim loại quý hiếm. | Gương Hán-Việt | không có từ Hán-Việt; dùng trong hóa học | Mở khoá kiến thức | Biết 镓 giúp đọc tài liệu bán dẫn và điện tử: 镓砷 (GaAs — gallium arsenide) dùng trong chip LED và pin mặt trời.", "Tự nguyên_Xie": "镓 là chữ hình thanh tạo muộn (thế kỷ 19-20): bộ 金 (kim loại) biểu nghĩa, 家 biểu âm cho âm jiā. Đây là chữ chỉ nguyên tố Gallium (Ga, số nguyên tử 31) — một kim loại mềm, có điểm nóng chảy gần nhiệt độ phòng. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố gali, Ga", "Hạng Tần Suất (Jun Da)": "5978.0", "Tần Suất % (Jun Da)": "99.9812949621", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 家", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅家", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "家", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镓", "Unihan_Traditional (Chữ Phồn thể)": "鎵", "Pinyin_Xie": "jiā", "Âm Hán Việt_Xie": "gia", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chuyên ngành hóa học để chỉ nguyên tố kim loại gali. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邳', '{"9000": "5979.0", "Chữ Trung Quốc": "邳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 7 | nét | 邳 | phi | tượng hình | địa danh cổ | 邳 có bộ 邑 (ấp: đô thị, địa danh) biểu nghĩa và 丕 biểu âm; chữ hình thanh chỉ địa danh cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phi\": làng ấp (邑) lớn lao (丕) — địa danh Hạ Bì nổi tiếng trong sử Trung Quốc. | Gương Hán-Việt | không có từ Hán-Việt thông dụng; chỉ dùng trong địa danh | Mở khoá kiến thức | Biết 邳 giúp nhận ra địa danh lịch sử 下邳 (Hạ Bì) — nơi Lã Bố bị bắt, và 邳州 hiện đại ở Giang Tô.", "Tự nguyên_Xie": "Tiểu triện | 邳 là chữ hình thanh với bộ 邑 (ấp) biểu nghĩa và 丕 biểu âm. Chỉ địa danh cổ Hạ邳 (下邳) ở tỉnh Giang Tô ngày nay — nơi nổi tiếng trong lịch sử Trung Quốc qua trận Hạ Bì. Tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "huyện Phi (địa danh, ở tỉnh Giang Tô, Trung Quốc); họ Phi; tính loạn thị", "Hạng Tần Suất (Jun Da)": "5979.0", "Tần Suất % (Jun Da)": "99.981323902", "GavinGrover_Once (Chiết tự trực tiếp)": "丕 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰丕阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邳", "Unihan_Traditional (Chữ Phồn thể)": "邳", "Pinyin_Xie": "pī", "Âm Hán Việt_Xie": "phi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng dùng làm họ người hoặc địa danh như huyện Phi ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('璩', '{"9000": "5980.0", "Chữ Trung Quốc": "璩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 17 | nét | 玉 | ngọc | biểu nghĩa | ngọc | 豦 | cự | biểu âm | (âm) | 璩 = 玉 (Ngọc, biểu nghĩa: ngọc thạch) + 豦 (biểu âm, cho âm qú); chữ hình thanh. Bộ Ngọc chỉ đây là đồ trang sức bằng ngọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cừ\": ngọc (玉) làm vòng khuyên — hình ảnh đồ trang sức ngọc thạch quý giá của người xưa. | Gương Hán-Việt | không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 璩 giúp nhận ra họ người và các từ chỉ đồ trang sức ngọc trong văn học cổ điển.", "Tự nguyên_Xie": "Tiểu triện | 璩 là chữ hình thanh: 玉 (ngọc) biểu nghĩa, 豦 biểu âm cho âm qú. Nghĩa gốc là vòng tay ngọc hoặc hoa tai ngọc hình tròn có khe hở. Đây cũng là họ người (姓璩). Tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái vòng", "Hạng Tần Suất (Jun Da)": "5980.0", "Tần Suất % (Jun Da)": "99.981352842", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 豦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王豦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "璩", "Unihan_Traditional (Chữ Phồn thể)": "璩", "Pinyin_Xie": "qú", "Âm Hán Việt_Xie": "cừ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại vòng ngọc cổ hoặc dùng làm họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸸', '{"9000": "5981.0", "Chữ Trung Quốc": "鸸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 11 | nét | 鸸 | nhi | tượng hình | chim đà điểu emu | 鸸 có bộ 鸟 (điểu: chim) biểu nghĩa và 而 biểu âm; chữ hình thanh tạo muộn. Dùng trong tên chim 鸸鹋 (emu — đà điểu Úc) và 鷾鴯 (một loài chim cổ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhi\": loài chim (鸟) mang bộ lông đơn giản (而) — con emu to lớn không biết bay của châu Úc. | Gương Hán-Việt | không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 鸸 giúp nhận ra tên chim 鸸鹋 (emu) trong văn bản tự nhiên học và sách động vật.", "Tự nguyên_Xie": "鸸 là chữ hình thanh: bộ 鸟 (chim) biểu nghĩa, 而 biểu âm. Xuất hiện chủ yếu trong tên loài chim 鷾鴯 (chim cổ) và 鴯鶓 (emu — đà điểu Úc). Wiktionary không cung cấp phân tích chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ý nhi 鷾鴯); (xem: nhi miêu 鴯鶓,鸸鹋)", "Hạng Tần Suất (Jun Da)": "5981.0", "Tần Suất % (Jun Da)": "99.981381782", "GavinGrover_Once (Chiết tự trực tiếp)": "而 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰而鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鸟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "而", "Unihan_Simplified (Chữ Giản thể)": "鸸", "Unihan_Traditional (Chữ Phồn thể)": "鴯", "Pinyin_Xie": "ér", "Âm Hán Việt_Xie": "nhi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường kết hợp thành từ ghép để chỉ loài chim đà điểu châu Úc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涠', '{"9000": "5982.0", "Chữ Trung Quốc": "涠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 涠 | vi | tượng hình | nước đục, vùng biển | 涠 có bộ 氵(thủy) biểu nghĩa chỉ nước và 韦 biểu âm; chữ hình thanh. Chỉ nước đục hoặc vùng biển. Xuất hiện trong địa danh 涠洲 (đảo Vị Châu ở Vịnh Bắc Bộ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vi\": dòng nước (氵) cuốn vòng quanh (韦) — gợi hình ảnh vùng nước xoáy đục ngầu hoặc đảo biển. | Gương Hán-Việt | không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 涠 giúp nhận ra địa danh 涠洲岛 (đảo Vị Châu) — điểm du lịch nổi tiếng ở Quảng Tây, gần Việt Nam.", "Tự nguyên_Xie": "Tiểu triện | 涠 là chữ hình thanh với bộ 氵(nước) biểu nghĩa và 韦 biểu âm. Nghĩa là nước đục; cũng là thành phần trong địa danh 潿洲 (Vị Châu) — đảo ở Vịnh Bắc Bộ thuộc Quảng Tây. Wiktionary không cung cấp phân tích chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước tù đọng; nước bẩn; nước đục", "Hạng Tần Suất (Jun Da)": "5982.0", "Tần Suất % (Jun Da)": "99.9814107219", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 围", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵围", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "围", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "涠", "Unihan_Traditional (Chữ Phồn thể)": "潿", "Pinyin_Xie": "wéi", "Âm Hán Việt_Xie": "vi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ vũng nước đọng hoặc dùng trong địa danh như đảo Vi Châu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('溲', '{"9000": "5983.0", "Chữ Trung Quốc": "溲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 溲 | sưu | tượng hình | nước tiểu, ngâm rửa | 溲 có bộ 氵(thủy) biểu nghĩa và 叜 biểu âm; chữ hình thanh. Chỉ nước tiểu hoặc hành động ngâm rửa (gạo trước khi nấu).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sưu\": nước (氵) chảy ra như tìm kiếm (叜/搜) — nghĩ đến bài tiết nước tiểu trong y học. | Gương Hán-Việt | không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 溲 giúp đọc thuật ngữ Đông y về bài tiết (溲溺 — tiểu tiện) và chế biến thức ăn cổ (溲面 — nhào bột).", "Tự nguyên_Xie": "溲 là chữ hình thanh với bộ 氵(nước) biểu nghĩa và 叜 biểu âm. Có hai nghĩa: (1) nước tiểu, bài tiết — dùng trong Đông y; (2) ngâm nước, vo gạo. Wiktionary không cung cấp phân tích chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiểu tiện, đi đái", "Hạng Tần Suất (Jun Da)": "5983.0", "Tần Suất % (Jun Da)": "99.9814396619", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 叟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵叟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "溲", "Unihan_Traditional (Chữ Phồn thể)": "溲", "Pinyin_Xie": "sōu", "Âm Hán Việt_Xie": "sưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ việc đi tiểu tiện hoặc hành động nhào trộn bột với nước. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('孥', '{"9000": "5984.0", "Chữ Trung Quốc": "孥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 子 | Số nét | 8 | nét | 孥 | nô | tượng hình | vợ con, con cái | 孥 có bộ 子 (tử: con) biểu nghĩa và 奴 biểu âm; chữ hình thanh. Chỉ vợ và con, hoặc con cái nói chung.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nô\": đứa trẻ (子) phụ thuộc như người hầu (奴) — nghĩa là con cái trong tay cha mẹ. | Gương Hán-Việt | thê nô (妻孥) — vợ con | Mở khoá kiến thức | Biết 孥 giúp hiểu các từ cổ điển về gia đình: 妻孥 (thê nô: vợ con), 孥戮 (tru di gia quyến).", "Tự nguyên_Xie": "孥 là chữ hình thanh với bộ 子 (con) biểu nghĩa và 奴 biểu âm. Nghĩa là con cái, vợ con. Dùng trong văn học cổ điển, ví dụ: 妻孥 (thê nô: vợ con). Wiktionary không cung cấp phân tích chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "164.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nô (163) Tử (58)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nô (số 163) ở trên chữ Tử (số 58) . Hình ảnh người mẹ đưa cánh tay (phần trên) ra bồng lấy đứa con nhỏ (Tử). Giải thích sự chuyển ý: Chữ Nô (nô lệ) chỉ âm, chữ Tử (con) chỉ ý. Ngày xưa con cái (Tử) của tội nhân bị bắt làm nô lệ (Nô), từ đó Noa dùng để chỉ vợ con nói chung. *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Nô và chữ Noa có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Nô và Noa).*", "Nghĩa Tiếng Việt_Xie": "(tiếng gọi chung cả vợ con); đứa ở", "Hạng Tần Suất (Jun Da)": "5984.0", "Tần Suất % (Jun Da)": "99.9814686019", "GavinGrover_Once (Chiết tự trực tiếp)": "奴 + 子", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱奴子", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "子", "Unihan_Simplified (Chữ Giản thể)": "孥", "Unihan_Traditional (Chữ Phồn thể)": "孥", "Pinyin_Xie": "nú", "Âm Hán Việt_Xie": "noa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn ngôn để chỉ chung vợ và con cái của mình. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('敉', '{"9000": "5985.0", "Chữ Trung Quốc": "敉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 攴 | Số nét | 10 | nét | 敉 | mễ | tượng hình | vỗ về, xoa dịu, bình định | 敉 có bộ 攵 (phác: tay cầm gậy/hành động) biểu nghĩa và 米 biểu âm; chữ hình thanh. Chỉ hành động vỗ về, xoa dịu. Dạng kim văn còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mễ\": tay cầm gậy (攵) nhẹ nhàng như gạo (米) — vỗ về, xoa dịu người dân như người mẹ đong gạo cho con. | Gương Hán-Việt | không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 敉 giúp đọc hiểu các văn bản lịch sử và chính trị cổ điển về việc bình định, an dân.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 敉 không có phân tích Wiktionary chi tiết. Cấu trúc: bộ 攵 (hành động) + 米 (mễ, âm). Nghĩa là vỗ về, an ủi, bình định (敉宁: bình định yên ổn). Dạng kim văn, tiểu triện và lục thư thông còn lưu lại. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "yên ổn", "Hạng Tần Suất (Jun Da)": "5985.0", "Tần Suất % (Jun Da)": "99.9814975418", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + ⺙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米⺙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "⺙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "敉", "Unihan_Traditional (Chữ Phồn thể)": "敉", "Pinyin_Xie": "mǐ", "Âm Hán Việt_Xie": "mị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ mang tân ngữ với nghĩa dẹp loạn hoặc làm tính từ chỉ sự thái bình. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筌', '{"9000": "5986.0", "Chữ Trung Quốc": "筌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 12 | nét | 筌 | thuyên | tượng hình | rọ đánh cá bằng tre | 筌 có bộ 竹 (trúc: tre) biểu nghĩa và 全 biểu âm; chữ hình thanh. Chỉ rọ tre đánh cá — dụng cụ đặt dưới nước bẫy cá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuyên\": rọ tre (竹) hoàn chỉnh (全) để bẫy cá — ''được cá thì quên rọ'' (得鱼忘筌). | Gương Hán-Việt | không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 筌 mở khoá thành ngữ triết học 得鱼忘筌 (thuyên — phương tiện đạt mục đích rồi bỏ đi).", "Tự nguyên_Xie": "筌 là chữ hình thanh với bộ 竹 (trúc) biểu nghĩa và 全 biểu âm. Nghĩa là rọ tre đánh cá. Nổi tiếng qua thành ngữ 得鱼忘筌 (đắc ngư vong thuyên: ''được cá quên rọ'' — đạt mục đích quên phương tiện). Wiktionary không cung cấp phân tích đầy đủ hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái nơm cá", "Hạng Tần Suất (Jun Da)": "5986.0", "Tần Suất % (Jun Da)": "99.9815264818", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 全", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮全", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "全", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筌", "Unihan_Traditional (Chữ Phồn thể)": "筌", "Pinyin_Xie": "quán", "Âm Hán Việt_Xie": "thuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ dụng cụ bắt cá bằng tre, xuất hiện nhiều trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹓', '{"9000": "5988.0", "Chữ Trung Quốc": "蹓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 17 | nét | 足 | túc | biểu nghĩa | chân, bước đi | 留 | lưu | biểu âm | ở lại | 蹓 = 足 (Túc, biểu nghĩa: chân, bước đi) + 留 (Lưu, biểu âm); chữ hình thanh. Bộ Túc chỉ hành động bằng chân; 留 cho âm liū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưu\": đôi chân (足) lưu lại (留) để dạo bộ thư thả — nhớ ngay nghĩa đi tản bộ, lướt đi nhẹ nhàng. | Gương Hán-Việt | không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 蹓 giúp nhận ra từ khẩu ngữ 蹓躂 (đi dạo bộ, tản bộ) thường dùng ở miền Bắc Trung Quốc.", "Tự nguyên_Xie": "蹓 là chữ hình thanh: 足 biểu nghĩa chỉ chân/bước đi, 留 biểu âm. Nghĩa là trượt/lướt đi; cũng có nghĩa dạo bộ, đi tản bộ (蹓躂). Thường dùng thay thế cho 溜 (trượt) và 遛 (dắt đi dạo). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lựu đáp 蹓躂,蹓跶)", "Hạng Tần Suất (Jun Da)": "5988.0", "Tần Suất % (Jun Da)": "99.9816706648", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 留", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊留", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "留", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹓", "Unihan_Traditional (Chữ Phồn thể)": "蹓", "Pinyin_Xie": "liū", "Âm Hán Việt_Xie": "lựu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong khẩu ngữ, hay kết hợp thành từ ghép để chỉ việc đi dạo mát. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垓', '{"9000": "5989.0", "Chữ Trung Quốc": "垓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 9 | nét | 垓 | cai | tượng hình | biên giới, ranh giới; số 10^20 | 垓 có bộ 土 (thổ: đất) biểu nghĩa và 亥 biểu âm; chữ hình thanh. Chỉ ranh giới đất đai, hoặc con số thiên văn 10^20. Tiểu triện còn lưu lại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cai\": mảnh đất (土) cuối thiên can (亥) — ranh giới tận cùng của đất đai, nhớ trận Cai Hạ (垓下) lịch sử. | Gương Hán-Việt | Cai Hạ (垓下) — địa danh lịch sử | Mở khoá kiến thức | Biết 垓 giúp đọc lịch sử Trung Quốc: 垓下之战 (trận Cai Hạ) — Hạng Vũ tự sát, Lưu Bang thống nhất Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 垓 là chữ hình thanh với bộ 土 (thổ) biểu nghĩa và 亥 biểu âm. Nghĩa là ranh giới, biên cương; cũng là đơn vị số học cực lớn (10^20). Nổi tiếng qua địa danh 垓下 (Cai Hạ) — nơi Hạng Vũ bị thất bại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một vạn vạn (trăm triệu)", "Hạng Tần Suất (Jun Da)": "5989.0", "Tần Suất % (Jun Da)": "99.981699088", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 亥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土亥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "垓", "Unihan_Traditional (Chữ Phồn thể)": "垓", "Pinyin_Xie": "gāi", "Âm Hán Việt_Xie": "cai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Số từ | 数词 | Thường làm danh từ chỉ ranh giới bờ cõi hoặc làm số từ chỉ một lượng cực kỳ lớn thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苒', '{"9000": "5990.0", "Chữ Trung Quốc": "苒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 苒 | nhiễm | tượng hình | cỏ mọc yếu ớt, thời gian trôi qua | 苒 có bộ 艹 (thảo: cỏ) biểu nghĩa và 冉 biểu âm; chữ hình thanh. Miêu tả cỏ mọc yếu ớt, uốn lượn, gợi hình ảnh thời gian lặng lẽ trôi qua.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhiễm\": cỏ (艹) cứ từ từ lớn lên (冉) — hình ảnh thời gian lặng lẽ trôi như cỏ xanh mọc mãi. | Gương Hán-Việt | không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 苒 giúp đọc thơ cổ dùng hình ảnh cỏ để diễn tả thời gian và sự phù du.", "Tự nguyên_Xie": "苒 là chữ hình thanh với bộ 艹 (thảo) biểu nghĩa và 冉 biểu âm. Nghĩa gốc là cỏ mềm mại, yếu ớt; mở rộng sang nghĩa thời gian dần trôi (苒苒: lặng lẽ). Wiktionary không cung cấp phân tích đầy đủ hơn. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ tốt um", "Hạng Tần Suất (Jun Da)": "5990.0", "Tần Suất % (Jun Da)": "99.9817275112", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 冉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹冉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苒", "Unihan_Traditional (Chữ Phồn thể)": "苒", "Pinyin_Xie": "rǎn", "Âm Hán Việt_Xie": "nhiễm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ trong từ láy để tả cỏ cây tươi tốt hoặc thời gian dần trôi qua. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荸', '{"9000": "5991.0", "Chữ Trung Quốc": "荸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 荸 | mụt | tượng hình | mã thầy (water chestnut) | 荸 không có phân tích hình vị từ Wiktionary. Cấu trúc có bộ 艹 (thảo) và 孛; chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mụt\": loài cây cỏ (艹) mọc dưới nước — nhớ ngay củ mã thầy (荸荠) tròn tròn, ngọt giòn. | Gương Hán-Việt | không có từ Hán-Việt thông dụng; dùng trong tên thực vật | Mở khoá kiến thức | Biết 荸 giúp nhận ra củ mã thầy (荸荠) trong thực đơn ẩm thực Trung Hoa và y học cổ truyền.", "Tự nguyên_Xie": "荸 không có nguồn phân tích từ Wiktionary. Theo cấu trúc: bộ 艹 (thảo: cây cỏ) + 孛. Chủ yếu dùng trong 荸荠 (mã thầy — water chestnut, củ năn). Chữ tạo muộn hoặc ít gặp trong văn bản cổ; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây mã đề", "Hạng Tần Suất (Jun Da)": "5991.0", "Tần Suất % (Jun Da)": "99.9817559344", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 孛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹孛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荸", "Unihan_Traditional (Chữ Phồn thể)": "荸", "Pinyin_Xie": "bí", "Âm Hán Việt_Xie": "bột", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ và hầu như chỉ xuất hiện trong từ ghép để chỉ củ mã thầy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('甓', '{"9000": "5992.0", "Chữ Trung Quốc": "甓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 瓦 | Số nét | 17 | nét | 甓 | bịch | tượng hình | gạch ngói lợp mái | 甓 có bộ 瓦 (ngõa: ngói/gạch) biểu nghĩa và 辟 biểu âm; chữ hình thanh. Chỉ loại gạch ngói dùng lợp mái nhà hoặc lát nền. Tiểu triện còn lưu lại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bịch\": ngói gạch (瓦) chắc chắn như pháp lệnh (辟) — nhớ Đào Khản mỗi sáng vác gạch để rèn tính kỷ luật. | Gương Hán-Việt | không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 甓 giúp hiểu điển tích 陶侃運甓 — câu chuyện nổi tiếng về rèn luyện ý chí bằng lao động chăm chỉ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 甓 là chữ hình thanh với bộ 瓦 (ngói/gạch đất nung) biểu nghĩa và 辟 biểu âm. Nghĩa là gạch ngói, đặc biệt dùng để lợp mái (theo phương ngữ Mân Nam). Cũng trong thành ngữ nổi tiếng 陶侃運甓 (Đào Khản vác gạch) về rèn luyện ý chí. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "viên gạch to", "Hạng Tần Suất (Jun Da)": "5992.0", "Tần Suất % (Jun Da)": "99.9817843576", "GavinGrover_Once (Chiết tự trực tiếp)": "辟 + 瓦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱辟瓦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "瓦", "Unihan_Simplified (Chữ Giản thể)": "甓", "Unihan_Traditional (Chữ Phồn thể)": "甓", "Pinyin_Xie": "pì", "Âm Hán Việt_Xie": "bích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn ngôn để chỉ viên gạch dùng trong xây dựng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锪', '{"9000": "5993.0", "Chữ Trung Quốc": "锪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 锪 | hoắc | tượng hình | dao khoét, dao đột lỗ (kỹ thuật) | 锪 có bộ 金 (kim: kim loại) biểu nghĩa và 活 biểu âm; chữ hình thanh tạo muộn. Chỉ dụng cụ kim loại dùng để khoét lỗ hoặc mở rộng lỗ trong gia công cơ khí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoắc\": công cụ kim loại (金) linh hoạt (活) để khoét — nhớ đây là thuật ngữ cơ khí. | Gương Hán-Việt | không có từ Hán-Việt thông dụng; dùng trong kỹ thuật cơ khí | Mở khoá kiến thức | Biết 锪 giúp đọc tài liệu kỹ thuật cơ khí: 锪孔 (khoét lỗ), 锪钻 (mũi khoét).", "Tự nguyên_Xie": "锪 là chữ hình thanh tạo muộn: bộ 金 (kim loại) biểu nghĩa, 活 biểu âm cho âm huō. Là thuật ngữ kỹ thuật cơ khí chỉ thao tác khoét lỗ (spot facing/counterboring). Không có nguồn phân tích Wiktionary. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gọt; đẽo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 忽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅忽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "忽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锪", "Unihan_Traditional (Chữ Phồn thể)": "锪", "Pinyin_Xie": "huō", "Âm Hán Việt_Xie": "hoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ trong ngành cơ khí để chỉ việc khoan loe hoặc bào rộng miệng lỗ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镄', '{"9000": "5994.0", "Chữ Trung Quốc": "镄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 镄 | phí | tượng hình | nguyên tố Fermium (Fm) | 镄 có bộ 金 (kim: kim loại) biểu nghĩa và 费 biểu âm; chữ hình thanh tạo muộn. Được tạo ra để đặt tên cho nguyên tố Fermium trong danh pháp hóa học Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phí\": kim loại (金) tốn kém (费) để tạo ra trong phòng thí nghiệm — Fermium chỉ tồn tại nhân tạo với lượng cực nhỏ. | Gương Hán-Việt | không có từ Hán-Việt; dùng trong hóa học | Mở khoá kiến thức | Biết 镄 giúp đọc bảng tuần hoàn và tài liệu hóa học hạt nhân tiếng Trung.", "Tự nguyên_Xie": "镄 là chữ hình thanh tạo muộn: bộ 金 (kim loại) biểu nghĩa, 费 biểu âm cho âm fèi. Đây là tên Hán tự của nguyên tố Fermium (Fm, số nguyên tử 100) — nguyên tố phóng xạ tổng hợp, đặt theo tên nhà vật lý Enrico Fermi. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố fermi, Fm", "Hạng Tần Suất (Jun Da)": "5994.0", "Tần Suất % (Jun Da)": "99.9818412039", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 费", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅费", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "费", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镄", "Unihan_Traditional (Chữ Phồn thể)": "鐨", "Pinyin_Xie": "fèi", "Âm Hán Việt_Xie": "phí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chuyên ngành hóa học để chỉ nguyên tố phóng xạ nhân tạo Fermi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脔', '{"9000": "5995.0", "Chữ Trung Quốc": "脔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 䜌 | loan | biểu âm | (âm) | 肉 | nhục | biểu nghĩa | thịt | 脔 = 䜌 (biểu âm) + 肉 (Nhục, biểu nghĩa: thịt); chữ hình thanh. Bộ Nhục chỉ đây là thứ liên quan đến thịt; 䜌 cho âm luán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"loan\": thịt (肉) cắt nhỏ thành từng miếng — nhớ thành ngữ ''nếm một miếng biết cả nồi'' (嘗鼎一臠). | Gương Hán-Việt | không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 脔 giúp hiểu thành ngữ 嘗鼎一臠 và 禁脔 (thứ được độc quyền, không cho kẻ khác).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 脔 là chữ hình thanh: 肉 (nhục: thịt) biểu nghĩa, 䜌 biểu âm. Nghĩa gốc là cắt thịt thành miếng nhỏ; cũng chỉ một miếng thịt nhỏ. Thành ngữ nổi tiếng 嘗鼎一臠 (thử một miếng trong nồi biết được vị cả nồi). Dạng tiểu triện và lục thư thông còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thịt thái từng miếng", "Hạng Tần Suất (Jun Da)": "5995.0", "Tần Suất % (Jun Da)": "99.9818696271", "GavinGrover_Once (Chiết tự trực tiếp)": "亦 + 肉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亦肉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "肉", "Unihan_Simplified (Chữ Giản thể)": "脔", "Unihan_Traditional (Chữ Phồn thể)": "臠", "Pinyin_Xie": "luán", "Âm Hán Việt_Xie": "luyến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ miếng thịt cắt nhỏ hoặc làm động từ chỉ hành động cắt lát thịt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艟', '{"9000": "5996.0", "Chữ Trung Quốc": "艟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 18 | nét | 艟 | đồng | tượng hình | thuyền chiến lớn | 艟 có bộ 舟 (chu: thuyền) biểu nghĩa và 童 biểu âm; chữ hình thanh. Chỉ loại thuyền chiến lớn. Thường dùng trong từ 艨艟 (mông đồng: chiến hạm).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồng\": con thuyền (舟) lớn như đứa trẻ khổng lồ (童) — chiến hạm hùng mạnh trên sông. | Gương Hán-Việt | mông đồng (艨艟) — chiến thuyền | Mở khoá kiến thức | Biết 艟 giúp hiểu từ 艨艟 (mông đồng) — loại chiến hạm gỗ nổi tiếng trong sử Trung Quốc, đặc biệt thời Tam Quốc.", "Tự nguyên_Xie": "艟 là chữ hình thanh với bộ 舟 (thuyền) biểu nghĩa và 童 biểu âm. Chỉ loại thuyền chiến lớn, thường dùng trong từ 艨艟 (mông đồng). Wiktionary không cung cấp phân tích chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mông đồng 艨艟)", "Hạng Tần Suất (Jun Da)": "5996.0", "Tần Suất % (Jun Da)": "99.9818980503", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 童", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟童", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "童", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艟", "Unihan_Traditional (Chữ Phồn thể)": "艟", "Pinyin_Xie": "chōng", "Âm Hán Việt_Xie": "đồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường đi kèm với chữ mông tạo thành từ ghép mông đồng để chỉ thuyền chiến cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眬', '{"9000": "5997.0", "Chữ Trung Quốc": "眬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 10 | nét | 眬 | lung | tượng hình | mắt mờ nhạt, không rõ nét | 眬 là chữ không có nguồn phân tích thành phần rõ ràng. Chữ thuộc bộ 目 (mục, mắt), xuất hiện trong tổ hợp 朦朧/曚曨 với nghĩa mờ ảo, không phân biệt được rõ. Cấu trúc tự hình chưa được xác định chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lung\" (mờ): bộ 目 (mắt) + âm lung — mắt nhìn lung tung, không thấy rõ, như màn sương phủ trước mắt. | Gương Hán-Việt | lung trong \"mông lung\" (朦朧) — cảm giác mờ ảo, không rõ ràng | Mở khoá kiến thức | Biết 眬 giúp đọc hiểu tổ hợp 朦朧 (mông lung) và 曚曨 trong thơ văn cổ điển.", "Tự nguyên_Xie": "眬 xuất hiện chủ yếu trong tổ hợp 朦朧 (mông lung) hoặc 曚曨 với nghĩa mờ nhạt, không rõ ràng. Chưa có nguồn Wiktionary phân tích tự nguyên cụ thể cho chữ này. Chữ thuộc bộ 目 (mắt), gợi liên quan đến thị giác kém rõ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mông lung 朦朧,曚曨,朦胧)", "Hạng Tần Suất (Jun Da)": "5997.0", "Tần Suất % (Jun Da)": "99.9819828031", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 龙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目龙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眬", "Unihan_Traditional (Chữ Phồn thể)": "矓", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "lung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường kết hợp với chữ mông để tạo từ láy mông lung miêu tả trạng thái mắt lim dim buồn ngủ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('彘', '{"9000": "5998.0", "Chữ Trung Quốc": "彘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彐 | Số nét | 12 | nét | 豕 | thỉ | biểu nghĩa | lợn, heo rừng | 矢 | thỉ | biểu âm | mũi tên | 彘 = 豕 (Thỉ, biểu nghĩa: lợn rừng) + 矢 (Thỉ, biểu âm: mũi tên). Theo Wiktionary, đây vừa là chữ hội ý (ic) vừa có yếu tố hình thanh (psc): hình ảnh con lợn rừng bị bắn bằng mũi tên — phân biệt với heo nhà (豕). Chủ thuyết hội ý chiếm ưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trệ\" (lợn sề): 豕 (lợn) bị mũi tên 矢 bắn trúng — lợn rừng hung hãn bị săn, khác với heo nhà hiền lành. | Gương Hán-Việt | trệ trong \"trệ tử\" — từ cổ chỉ con lợn lớn, lợn sề | Mở khoá kiến thức | Biết 彘 giúp phân biệt các chữ chỉ lợn trong Hán văn cổ: 豕 (heo chung), 豚 (heo con), 彘 (lợn rừng/lợn sề).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Theo Wiktionary: 彘 = 豕 (lợn rừng) + 矢 (mũi tên) — hình ảnh con lợn hoang bị bắn bằng tên, phân biệt với heo nhà thuần dưỡng (豕). Chữ xuất hiện từ giáp cốt văn với hình tượng rõ ràng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con lợn sề", "Hạng Tần Suất (Jun Da)": "5998.0", "Tần Suất % (Jun Da)": "99.9820107095", "GavinGrover_Once (Chiết tự trực tiếp)": "彑 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱彑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "彘", "Unihan_Traditional (Chữ Phồn thể)": "彘", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "trệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con lợn trong văn ngôn cổ, thường làm chủ ngữ hoặc tân ngữ trong câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('檠', '{"9000": "5999.0", "Chữ Trung Quốc": "檠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 16 | nét | 檠 | kình | tượng hình | chân đèn, giá đỡ bằng gỗ | 檠 thuộc bộ 木 (mộc, gỗ), là chữ chỉ vật dụng bằng gỗ. Wiktionary cung cấp thông tin định nghĩa nhưng không phân tích thành phần hình thanh hay hội ý rõ ràng cho chữ này. Cấu tạo chính xác chưa được xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kình\" (chân đèn): bộ 木 (gỗ) — cái giá gỗ dùng để giữ cung tên cho thẳng, hoặc đỡ đèn nến sáng trong đêm. | Gương Hán-Việt | kình trong \"đăng kình\" (燈檠) — chân đèn, đế để cây đèn | Mở khoá kiến thức | Biết 檠 giúp đọc hiểu văn cổ về đồ vật nghi lễ: chân đèn (燈檠) và giá nắn cung (檠弓).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary mô tả 檠 (âm qíng/jìng) là đồ vật có hai nghĩa cổ điển: (1) khung/giá giữ cung tên để nắn thẳng; (2) chân đèn, đế nến. Bộ 木 cho thấy chất liệu gỗ. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn có phân tích thành phần rõ ràng. Chưa có nguồn học thuật về tự nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ nắn cung; đế đèn, chân đèn", "Hạng Tần Suất (Jun Da)": "5999.0", "Tần Suất % (Jun Da)": "99.9820386159", "GavinGrover_Once (Chiết tự trực tiếp)": "敬 + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敬木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "檠", "Unihan_Traditional (Chữ Phồn thể)": "檠", "Pinyin_Xie": "qíng", "Âm Hán Việt_Xie": "kềnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cái chân đèn hoặc dụng cụ chỉnh sửa cung tên thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胩', '{"9000": "6000.0", "Chữ Trung Quốc": "胩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 9 | nét | 胩 | các | tượng hình | hợp chất hữu cơ các-bin amin (carbylamine) | 胩 là chữ hiện đại thuộc bộ 肉/月 (nhục, thịt/cơ thể), dùng để phiên âm tên hoá học. Không có phân tích thành phần truyền thống vì đây là chữ tạo gần đây để ghi tên hợp chất carbylamine trong tiếng Trung. Chưa có nguồn học thuật về tự nguyên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"các\" (carbylamine): bộ 月 (hữu cơ/thể xác) + âm kǎ — chữ Hán hiện đại dùng trong hoá học để ghi tên hợp chất carbylamine. | Gương Hán-Việt | các trong thuật ngữ hoá học — ít xuất hiện trong văn học thông thường | Mở khoá kiến thức | Biết 胩 giúp đọc hiểu tên hợp chất hoá học hữu cơ trong văn bản khoa học tiếng Trung.", "Tự nguyên_Xie": "胩 là chữ Hán hiện đại tạo ra để phiên âm hợp chất carbylamine (các-bin amin, R-NC). Bộ 月/肉 (nhục) chỉ liên quan đến hữu cơ, âm kǎ phỏng theo âm ''car'' trong carbylamine. Chữ tạo muộn, không có trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "các-bin a-min", "Hạng Tần Suất (Jun Da)": "6000.0", "Tần Suất % (Jun Da)": "99.9820665223", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 卡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月卡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胩", "Unihan_Traditional (Chữ Phồn thể)": "胩", "Pinyin_Xie": "kǎ", "Âm Hán Việt_Xie": "ca", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chuyên ngành hóa học hữu cơ để chỉ hợp chất carbylamine. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('旄', '{"9000": "6001.0", "Chữ Trung Quốc": "旄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 方 | Số nét | 10 | nét | 㫃 | biểu nghĩa | cờ hiệu | 毛 | mao | biểu âm | lông, lông thú | 旄 = 㫃 (biểu nghĩa: bộ cờ hiệu) + 毛 (Mao, biểu âm: lông). Chữ hình thanh (psc): bộ 㫃 cho nghĩa liên quan đến cờ, 毛 cho âm. Nghĩa gốc là loại cờ cổ đại trang trí bằng lông đuôi bò tót (yak).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mao\" (cờ lông): 㫃 (cờ) + 毛 (lông) — cây cờ được trang trí bằng lông bò tót phất phới trong gió, biểu tượng uy quyền quân sự cổ đại. | Gương Hán-Việt | mao trong \"mao tiết\" (旄節) — cờ tiết của quan lại cổ đại | Mở khoá kiến thức | Biết 旄 giúp đọc hiểu các văn bản cổ về nghi lễ quân sự và triều đình Trung Hoa xưa.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary: 旄 = 㫃 (biểu nghĩa: cờ) + 毛 (biểu âm: lông). Chữ hình thanh chỉ loại cờ cổ đại của Trung Hoa, được trang trí bằng lông đuôi bò tót (耗牛/yak). Cờ mao được dùng trong nghi lễ quân sự và triều đình. Gặp trong kim văn và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cờ mao (cờ có cắm lông đuôi bò tót)", "Hạng Tần Suất (Jun Da)": "6001.0", "Tần Suất % (Jun Da)": "99.9820944287", "GavinGrover_Once (Chiết tự trực tiếp)": "方 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰方", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "旄", "Unihan_Traditional (Chữ Phồn thể)": "旄", "Pinyin_Xie": "máo", "Âm Hán Việt_Xie": "mao, mạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại cờ trang trí bằng lông thú thời cổ, thường làm tân ngữ trong câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
